  </div>

  <!-- End Screen -->
  <div class="screen end-screen" id="endScreen">
    <div class="card">
      <div class="result-icon" id="resultIcon">🏆</div>
      <h2 class="result-title" id="resultTitle">Amazing!</h2>

      <div class="stars-container" id="starsContainer">
        <span class="star">⭐</span>
        <span class="star">⭐</span>
        <span class="star">⭐</span>
      </div>

      <div class="result-stats">
        <div class="result-stat">
          <div class="rs-icon">✅</div>
          <div class="rs-value" id="correctCount">0</div>
          <div class="rs-label">Correct</div>
        </div>
        <div class="result-stat">
          <div class="rs-icon">❌</div>
          <div class="rs-value" id="wrongCount">0</div>
          <div class="rs-label">Wrong</div>
        </div>
        <div class="result-stat">
          <div class="rs-icon">🔥</div>
          <div class="rs-value" id="maxStreak">0</div>
          <div class="rs-label">Best Streak</div>
        </div>
      </div>

      <p class="result-message" id="resultMessage">Great job! Keep practicing!</p>

      <div class="btn-group">
        <button class="btn-primary" onclick="restartGame()">🔄 Play Again</button>
        <button class="btn-secondary" onclick="goToStart()">🏠 Main Menu</button>
      </div>
    </div>
  </div>
</div>

<script>
  // Game State
  let gameState = {
    mode: 'addition',
    difficulty: 'easy',
    score: 0,
    streak: 0,
    maxStreak: 0,
    currentQuestion: 0,
    totalQuestions: 10,
    correctAnswers: 0,
    wrongAnswers: 0,
    currentAnswer: 0,
    answers: [],
    timer: null,
    timeLeft: 100,
    isAnswering: false,
    questionStartTime: 0
  };

  // Difficulty settings
  const difficultySettings = {
    easy: { maxNum: 10, time: 15, label: 'Easy' },
    medium: { maxNum: 20, time: 12, label: 'Medium' },
    hard: { maxNum: 50, time: 10, label: 'Hard' }
  };

  // Encouraging messages
  const correctMessages = [
    "🎉 Awesome!", "🌟 Brilliant!", "🚀 Fantastic!", "💪 Great job!",
    "🎯 Perfect!", "✨ Wonderful!", "🏆 Super!", "🎊 Amazing!",
    "👏 Excellent!", "🌈 Superb!", "💯 Perfect!", "🔥 On fire!"
  ];

  const wrongMessages = [
    "💪 Try again!", "🌟 Almost!", "😊 Keep going!", "🎯 Close!",
    "📚 Learning!", "🌈 Next time!", "💫 Don't give up!", "🎯 So close!"
  ];

  const resultMessages = {
    perfect: "🏆 Perfect Score! You're a math genius!",
    great: "🌟 Amazing work! You're getting really good!",
    good: "👍 Nice job! Keep practicing!",
    okay: "💪 Good effort! Practice makes perfect!",
    tryAgain: "🌈 Don't give up! Keep trying!"
  };

  // Mode selection
  function selectMode(btn) {
    document.querySelectorAll('.mode-btn').forEach(b => b.classList.remove('selected'));
    btn.classList.add('selected');
    gameState.mode = btn.dataset.mode;
  }

  // Difficulty selection
  function selectDifficulty(btn) {
    document.querySelectorAll('.diff-btn').forEach(b => b.classList.remove('selected'));
    btn.classList.add('selected');
    gameState.difficulty = btn.dataset.diff;
  }

  // Start game
  function startGame() {
    gameState.score = 0;
    gameState.streak = 0;
    gameState.maxStreak = 0;
    gameState.currentQuestion = 0;
    gameState.correctAnswers = 0;
    gameState.wrongAnswers = 0;
    gameState.totalQuestions = 10;
    gameState.isAnswering = false;

    showScreen('gameScreen');
    updateStats();
    nextQuestion();
  }

  // Show screen
  function showScreen(screenId) {
    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
    document.getElementById(screenId).classList.add('active');
  }

  // Generate question
  function nextQuestion() {
    if (gameState.currentQuestion >= gameState.totalQuestions) {
      endGame();
      return;
    }

    gameState.currentQuestion++;
    gameState.isAnswering = true;
    gameState.questionStartTime = Date.now();

    const settings = difficultySettings[gameState.difficulty];
    let num1, num2, operator, answer;

    // Determine operator
    if (gameState.mode === 'addition') {
      operator = '+';
    } else if (gameState.mode === 'subtraction') {
      operator = '-';
    } else if (gameState.mode === 'mixed') {
      operator = Math.random() < 0.5 ? '+' : '-';
    } else { // challenge
      operator = Math.random() < 0.5 ? '+' : '-';
    }

    if (operator === '+') {
      num1 = Math.floor(Math.random() * settings.maxNum) + 1;
      num2 = Math.floor(Math.random() * settings.maxNum) + 1;
      answer = num1 + num2;
    } else {
      num1 = Math.floor(Math.random() * settings.maxNum) + 1;
      num2 = Math.floor(Math.random() * num1) + 1; // Ensure positive result
      answer = num1 - num2;
    }

    gameState.currentAnswer = answer;

    // Update UI
    document.getElementById('num1').textContent = num1;
    document.getElementById('num2').textContent = num2;
    document.getElementById('operator').textContent = operator;
    document.getElementById('questionNumber').textContent = `Question ${gameState.currentQuestion} of ${gameState.totalQuestions}`;
    document.getElementById('questionDisplay').textContent = `${gameState.currentQuestion}/${gameState.totalQuestions}`;
    document.getElementById('progressBar').style.width = `${((gameState.currentQuestion - 1) / gameState.totalQuestions) * 100}%`;
    document.getElementById('feedbackMessage').textContent = '';
    document.getElementById('feedbackMessage').className = 'feedback-message';

    // Generate answers
    generateAnswers(answer);

    // Start timer for challenge mode
    if (gameState.mode === 'challenge') {
      startTimer(settings.time);
    } else {
      document.getElementById('timerBar').style.width = '100%';
    }
  }

  // Generate answer options
  function generateAnswers(correct) {
    let answers = [correct];
    while (answers.length < 4) {
      let offset = Math.floor(Math.random() * 10) - 5;
      if (offset === 0) offset = Math.random() < 0.5 ? 1 : -1;
      let wrong = correct + offset;
      if (wrong < 0) wrong = Math.abs(wrong);
      if (!answers.includes(wrong) && wrong !== correct) {
        answers.push(wrong);
      }
    }

    // Shuffle
    answers.sort(() => Math.random() - 0.5);
    gameState.answers = answers;

    const grid = document.getElementById('answersGrid');
    grid.innerHTML = '';
    answers.forEach((ans, index) => {
      const btn = document.createElement('button');
      btn.className = 'answer-btn';
      btn.textContent = ans;
      btn.onclick = () => checkAnswer(index);
      grid.appendChild(btn);
    });
  }

  // Check answer
  function checkAnswer(index) {
    if (!gameState.isAnswering) return;
    gameState.isAnswering = false;

    const selected = gameState.answers[index];
    const isCorrect = selected === gameState.currentAnswer;
    const buttons = document.querySelectorAll('.answer-btn');

    // Highlight correct/wrong
    buttons.forEach((btn, i) => {
      if (gameState.answers[i] === gameState.currentAnswer) {
        btn.classList.add('correct');
      } else if (i === index && !isCorrect) {
        btn.classList.add('wrong');
      }
      btn.style.pointerEvents = 'none';
    });

    const feedback = document.getElementById('feedbackMessage');

    if (isCorrect) {
      gameState.correctAnswers++;
      gameState.streak++;
      if (gameState.streak > gameState.maxStreak) {
        gameState.maxStreak = gameState.streak;
      }

      // Score calculation with streak bonus
      let points = 10;
      if (gameState.streak >= 3) points += 5;
      if (gameState.streak >= 5) points += 10;
      if (gameState.mode === 'challenge') points *= 2;
      gameState.score += points;

      feedback.textContent = correctMessages[Math.floor(Math.random() * correctMessages.length)];
      feedback.className = 'feedback-message correct';

      // Confetti for streaks
      if (gameState.streak >= 3) {
        createConfetti();
      }

      // Level up animation
      if (gameState.streak > 0 && gameState.streak % 5 === 0) {
        showLevelUp(`🔥 ${gameState.streak} Streak!`);
      }
    } else {
      gameState.wrongAnswers++;
      gameState.streak = 0;
      feedback.textContent = `${wrongMessages[Math.floor(Math.random() * wrongMessages.length)]} The answer was ${gameState.currentAnswer}`;
      feedback.className = 'feedback-message wrong';
    }

    updateStats();

    // Next question after delay
    setTimeout(() => {
      nextQuestion();
    }, 1500);
  }

  // Update stats display
  function updateStats() {
    document.getElementById('scoreDisplay').textContent = gameState.score;
    document.getElementById('streakDisplay').textContent = gameState.streak;
  }

  // Timer
  function startTimer(seconds) {
    clearInterval(gameState.timer);
    gameState.timeLeft = 100;
    const timerBar = document.getElementById('timerBar');

    gameState.timer = setInterval(() => {
      gameState.timeLeft -= (100 / (seconds * 10));
      timerBar.style.width = `${gameState.timeLeft}%`;

      if (gameState.timeLeft <= 0) {
        clearInterval(gameState.timer);
        if (gameState.isAnswering) {
          gameState.isAnswering = false;
          gameState.wrongAnswers++;
          gameState.streak = 0;
          updateStats();

          const feedback = document.getElementById('feedbackMessage');
          feedback.textContent = `⏰ Time's up! The answer was ${gameState.currentAnswer}`;
          feedback.className = 'feedback-message wrong';

          const buttons = document.querySelectorAll('.answer-btn');
          buttons.forEach((btn, i) => {
            if (gameState.answers[i] === gameState.currentAnswer) {
              btn.classList.add('correct');
            }
            btn.style.pointerEvents = 'none';
          });

          setTimeout(() => {
            nextQuestion();
          }, 1500);
        }
      }
    }, 100);
  }

  // End game
  function endGame() {
    clearInterval(gameState.timer);
    showScreen('endScreen');

    const percentage = (gameState.correctAnswers / gameState.totalQuestions) * 100;

    document.getElementById('correctCount').textContent = gameState.correctAnswers;
    document.getElementById('wrongCount').textContent = gameState.wrongAnswers;
    document.getElementById('maxStreak').textContent = gameState.maxStreak;

    // Stars
    const stars = document.querySelectorAll('.star');
    stars.forEach(s => s.classList.remove('earned'));

    let starCount = 0;
    if (percentage >= 30) starCount = 1;
    if (percentage >= 60) starCount = 2;
    if (percentage >= 90) starCount = 3;

    setTimeout(() => { stars[0].classList.add('earned'); }, 300);
    setTimeout(() => { if (starCount > 1) stars[1].classList.add('earned'); }, 600);
    setTimeout(() => { if (starCount > 2) stars[2].classList.add('earned'); }, 900);

    // Result icon and message
    let icon, title, message;
    if (percentage === 100) {
      icon = '🏆'; title = 'Perfect!'; message = resultMessages.perfect;
    } else if (percentage >= 80) {
      icon = '🌟'; title = 'Amazing!'; message = resultMessages.great;
    } else if (percentage >= 60) {
      icon = '👍'; title = 'Good Job!'; message = resultMessages.good;
    } else if (percentage >= 40) {
      icon = '💪'; title = 'Nice Effort!'; message = resultMessages.okay;
    } else {
      icon = '🌈'; title = 'Keep Trying!'; message = resultMessages.tryAgain;
    }

    document.getElementById('resultIcon').textContent = icon;
    document.getElementById('resultTitle').textContent = title;
    document.getElementById('resultMessage').textContent = message;

    // Confetti for good results
    if (percentage >= 60) {
      createConfetti();
      setTimeout(createConfetti, 500);
      setTimeout(createConfetti, 1000);
    }
  }

  // Restart game
  function restartGame() {
    startGame();
  }

  // Go to start screen
  function goToStart() {
    showScreen('startScreen');
  }

  // Confetti effect
  function createConfetti() {
    const container = document.getElementById('confettiContainer');
    const colors = ['#6C63FF', '#FF6584', '#00C853', '#FFD600', '#FF9100', '#00B0FF', '#E040FB'];

    for (let i = 0; i < 30; i++) {
      const confetti = document.createElement('div');
      confetti.className = 'confetti';
      confetti.style.left = Math.random() * 100 + '%';
      confetti.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
      confetti.style.width = Math.random() * 10 + 5 + 'px';
      confetti.style.height = Math.random() * 10 + 5 + 'px';
      confetti.style.borderRadius = Math.random() > 0.5 ? '50%' : '0';
      confetti.style.animationDuration = Math.random() * 2 + 2 + 's';
      confetti.style.animationDelay = Math.random() * 0.5 + 's';
      container.appendChild(confetti);

      setTimeout(() => confetti.remove(), 4000);
    }
  }

  // Level up animation
  function showLevelUp(text) {
    const levelUp = document.createElement('div');
    levelUp.className = 'level-up';
    levelUp.textContent = text;
    document.body.appendChild(levelUp);
    setTimeout(() => levelUp.remove(), 1500);
  }

  // Keyboard support
  document.addEventListener('keydown', (e) => {
    if (!gameState.isAnswering) return;

    const keyMap = { '1': 0, '2': 1, '3': 2, '4': 3, 'a': 0, 's': 1, 'd': 2, 'f': 3 };
    const index = keyMap[e.key.toLowerCase()];
    if (index !== undefined) {
      checkAnswer(index);
    }
  });
</script>

</body>
</html>

