  { emoji: '🍌', name: 'banana', points: 1, color: '#ffd700' },
  { emoji: '🥭', name: 'mango', points: 2, color: '#ffaa00' },
  { emoji: '🍍', name: 'pineapple', points: 2, color: '#ffd700' },
  { emoji: '🥥', name: 'coconut', points: 2, color: '#f5f5dc' },
  { emoji: '🍕', name: 'pizza', points: 3, color: '#ff6b35' },
  { emoji: '🍔', name: 'burger', points: 3, color: '#d4a574' },
  { emoji: '🌮', name: 'taco', points: 3, color: '#daa520' },
  { emoji: '🍩', name: 'donut', points: 2, color: '#d4a574' },
  { emoji: '🍰', name: 'cake', points: 3, color: '#ffb6c1' },
  { emoji: '🍪', name: 'cookie', points: 2, color: '#d4a574' },
  { emoji: '🧁', name: 'cupcake', points: 2, color: '#ff69b4' },
  { emoji: '🍣', name: 'sushi', points: 3, color: '#ff6b6b' },
];

// Particles
let particles = [];
let sliceEffects = [];
let floatingTexts = [];

// Background stars
function initStars() {
  bgStars = [];
  for (let i = 0; i < 100; i++) {
    bgStars.push({
      x: Math.random() * W,
      y: Math.random() * H,
      size: Math.random() * 2 + 0.5,
      alpha: Math.random() * 0.5 + 0.1,
      speed: Math.random() * 0.5 + 0.1,
      twinkle: Math.random() * Math.PI * 2
    });
  }
}
initStars();

// Food class
class Food {
  constructor() {
    const type = foodTypes[Math.floor(Math.random() * foodTypes.length)];
    this.emoji = type.emoji;
    this.points = type.points;
    this.color = type.color;
    this.name = type.name;
    this.size = 50 + Math.random() * 20;
    this.x = Math.random() * (W - 200) + 100;
    this.y = H + this.size;
    this.vx = (Math.random() - 0.5) * 4 * difficulty;
    this.vy = -(12 + Math.random() * 6 * difficulty);
    this.gravity = 0.25;
    this.rotation = 0;
    this.rotationSpeed = (Math.random() - 0.5) * 0.1;
    this.sliced = false;
    this.sliceAngle = 0;
    this.opacity = 1;
    this.glow = 0;
    this.alive = true;
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.vy += this.gravity;
    this.rotation += this.rotationSpeed;
    this.glow = Math.max(0, this.glow - 0.02);

    if (this.sliced) {
      this.opacity -= 0.03;
      this.sliceAngle += 0.15;
      if (this.opacity <= 0) this.alive = false;
    }

    if (this.y > H + 100 && !this.sliced && this.vy > 0) {
      this.alive = false;
      if (gameState === 'playing') {
        loseLife();
      }
    }
  }

  draw() {
    ctx.save();
    ctx.globalAlpha = this.opacity;
    ctx.translate(this.x, this.y);
    ctx.rotate(this.rotation);

    // Glow effect
    if (this.glow > 0) {
      ctx.shadowColor = this.color;
      ctx.shadowBlur = 30 * this.glow;
    }

    // Draw food emoji
    ctx.font = `${this.size}px serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(this.emoji, 0, 0);

    ctx.restore();
  }

  slice(direction) {
    if (this.sliced) return;
    this.sliced = true;
    this.glow = 1;

    // Create slice particles
    for (let i = 0; i < 15; i++) {
      particles.push(new Particle(this.x, this.y, this.color));
    }

    // Create juice splash
    for (let i =0; i < 8; i++) {
      particles.push(new JuiceParticle(this.x, this.y, this.color));
    }

    // Slice effect
    sliceEffects.push({
      x: this.x,
      y: this.y,
      angle: direction,
      life: 1,
      color: this.color
    });

    // Score
    combo++;
    if (combo > maxCombo) maxCombo = combo;
    let points = this.points * (combo > 1 ? Math.min(combo, 5) : 1);
    score += points;
    totalSliced++;

    // Floating text
    addFloatingText(this.x, this.y - 30, `+${points}`, this.color);

    if (combo >= 3) {
      showCombo(combo);
    }

    screenShake = 5;
    updateUI();
  }
}

// Particle class
class Particle {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.vx = (Math.random() - 0.5) * 10;
    this.vy = (Math.random() - 0.5) * 10 - 3;
    this.size = Math.random() * 4 + 2;
    this.color = color;
    this.life = 1;
    this.decay = Math.random() * 0.02 + 0.015;
    this.gravity = 0.15;
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.vy += this.gravity;
    this.life -= this.decay;
    this.size *= 0.98;
  }

  draw() {
    ctx.save();
    ctx.globalAlpha = this.life;
    ctx.fillStyle = this.color;
    ctx.shadowColor = this.color;
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

// Juice particle
class JuiceParticle {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.vx = (Math.random() - 0.5) * 6;
    this.vy = (Math.random() - 0.5) * 6 - 2;
    this.size = Math.random() * 6 + 3;
    this.color = color;
    this.life = 1;
    this.decay = Math.random() * 0.01 + 0.008;
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.vy += 0.1;
    this.life -= this.decay;
    this.size *= 0.99;
  }

  draw() {
    ctx.save();
    ctx.globalAlpha = this.life * 0.6;
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

// Floating text
function addFloatingText(x, y, text, color) {
  const el = document.createElement('div');
  el.className = 'float-text';
  el.textContent = text;
  el.style.left = x + 'px';
  el.style.top = y + 'px';
  el.style.color = color || '#ffd700';
  document.getElementById('floating-texts').appendChild(el);
  setTimeout(() => el.remove(), 1000);
}

// Show combo
function showCombo(c) {
  const el = document.getElementById('combo-display');
  el.textContent = `COMBO x${c}`;
  el.className = 'active';
  setTimeout(() => el.className = '', 1000);
}

// Lose life
function loseLife() {
  lives--;
  combo = 0;
  updateUI();

  // Screen flash red
  screenShake = 10;

  const heart = document.getElementById(`h${lives + 1}`);
  if (heart) heart.classList.add('lost');

  if (lives <= 0) {
    gameOver();
  }
}

// Update UI
function updateUI() {
  document.getElementById('score').textContent = score;
}

// Game over
function gameOver() {
  gameState = 'gameover';
  document.getElementById('game-over-screen').style.display = 'flex';
  document.getElementById('final-score').textContent = score;
  document.getElementById('stat-sliced').textContent = totalSliced;
  document.getElementById('stat-combo').textContent = maxCombo;
  document.getElementById('stat-accuracy').textContent = totalSwings > 0 ? Math.round((totalSliced / totalSwings) * 100) + '%' : '0%';
}

// Start game
function startGame() {
  gameState = 'playing';
  score = 0;
  lives = 3;
  combo = 0;
  maxCombo = 0;
  totalSliced = 0;
  totalSwings = 0;
  foodThrown = 0;
  spawnTimer = 0;
  spawnInterval = 90;
  difficulty = 1;
  screenShake = 0;
  foods = [];
  particles = [];
  sliceEffects = [];

  document.getElementById('start-screen').style.display = 'none';
  document.getElementById('game-over-screen').style.display = 'none';

  // Reset hearts
  for (let i = 1; i <= 3; i++) {
    document.getElementById(`h${i}`).classList.remove('lost');
  }

  updateUI();
}

// Spawn food
function spawnFood() {
  const count = Math.floor(Math.random() * 3) + 1;
  for (let i = 0; i < count; i++) {
    foods.push(new Food());
    foodThrown++;
  }
}

// Check collision with blade
function checkSliceCollision() {
  if (bladeTrail.length < 2) return;

  const p1 = bladeTrail[bladeTrail.length - 2];
  const p2 = bladeTrail[bladeTrail.length - 1];

  for (let food of foods) {
    if (food.sliced || !food.alive) continue;

    const dx = food.x - p2.x;
    const dy = food.y - p2.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < food.size / 2 + 10) {
      // Calculate slice direction
      const angle = Math.atan2(dy, dx);
      food.slice(angle);
      totalSwings++;
    }
  }
}

// Draw background
function drawBackground() {
  // Dark gradient background
  const grad = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, Math.max(W, H) * 0.7);
  grad.addColorStop(0, '#1a1a2e');
  grad.addColorStop(0.5, '#16213e');
  grad.addColorStop(1, '#0a0a0f');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // Stars
  const time = Date.now() * 0.001;
  for (let star of bgStars) {
    star.twinkle += 0.02;
    const alpha = star.alpha * (0.5 + 0.5 * Math.sin(star.twinkle));
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // Subtle grid
  ctx.save();
  ctx.globalAlpha = 0.03;
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 1;
  const gridSize = 80;
  for (let x = 0; x < W; x += gridSize) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, H);
    ctx.stroke();
  }
  for (let y = 0; y < H; y += gridSize) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
    ctx.stroke();
  }
  ctx.restore();
}

// Draw blade trail
function drawBlade() {
  if (bladeTrail.length < 2) return;

  ctx.save();
  for (let i = 1; i < bladeTrail.length; i++) {
    const t = i / bladeTrail.length;
    const alpha = t * 0.8;
    const width = t * 4 + 1;

    ctx.beginPath();
    ctx.moveTo(bladeTrail[i - 1].x, bladeTrail[i - 1].y);
    ctx.lineTo(bladeTrail[i].x, bladeTrail[i].y);
    ctx.strokeStyle = `rgba(255, 255, 255, ${alpha})`;
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.shadowColor = '#ff6b6b';
    ctx.shadowBlur = 15;
    ctx.stroke();
  }

  // Glow at tip
  if (bladeTrail.length > 0) {
    const tip = bladeTrail[bladeTrail.length - 1];
    ctx.beginPath();
    ctx.arc(tip.x, tip.y, 8, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 107, 107, 0.8)';
    ctx.shadowColor = '#ff6b6b';
    ctx.shadowBlur = 25;
    ctx.fill();
  }

  ctx.restore();
}

// Draw slice effects
function drawSliceEffects() {
  for (let effect of sliceEffects) {
    ctx.save();
    ctx.globalAlpha = effect.life;
    ctx.translate(effect.x, effect.y);
    ctx.rotate(effect.angle);

    // Slash line
    ctx.beginPath();
    ctx.moveTo(-40, 0);
    ctx.lineTo(40, 0);
    ctx.strokeStyle = effect.color;
    ctx.lineWidth = 3;
    ctx.shadowColor = effect.color;
    ctx.shadowBlur = 20;
    ctx.stroke();

    // Second slash
    ctx.beginPath();
    ctx.moveTo(-30, -5);
    ctx.lineTo(30, -5);
    ctx.strokeStyle = `rgba(255,255,255,0.5)`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.restore();
    effect.life -= 0.05;
  }
  sliceEffects = sliceEffects.filter(e => e.life > 0);
}

// Main game loop
function gameLoop() {
  // Screen shake
  ctx.save();
  if (screenShake > 0) {
    ctx.translate(
      (Math.random() - 0.5) * screenShake,
      (Math.random() - 0.5) * screenShake
    );
    screenShake *= 0.9;
    if (screenShake < 0.5) screenShake = 0;
  }

  drawBackground();

  if (gameState === 'playing') {
    // Spawn food
    spawnTimer++;
    if (spawnTimer >= spawnInterval) {
      spawnFood();
      spawnTimer = 0;
      // Increase difficulty
      if (spawnInterval > 30) spawnInterval -= 0.5;
      difficulty = 1 + (90 - spawnInterval) / 60;
    }

    // Update and draw food
    for (let food of foods) {
      food.update();
      food.draw();
    }
    foods = foods.filter(f => f.alive);

    // Check slice collision
    checkSliceCollision();

    // Update and draw particles
    for (let p of particles) {
      p.update();
      p.draw();
    }
    particles = particles.filter(p => p.life > 0);

    // Draw slice effects
    drawSliceEffects();

    // Draw blade trail
    drawBlade();

    // Clear old trail points
    if (bladeTrail.length > 20) {
      bladeTrail = bladeTrail.slice(-20);
    }
  }

  ctx.restore();
  requestAnimationFrame(gameLoop);
}

// Input handling
canvas.addEventListener('mousedown', (e) => {
  if (gameState !== 'playing') return;
  isSlicing = true;
  totalSwings++;
  mouseX = e.clientX;
  mouseY = e.clientY;
  prevMouseX = mouseX;
  prevMouseY = mouseY;
  bladeTrail = [{ x: mouseX, y: mouseY }];
  document.getElementById('blade-cursor').classList.add('slicing');
});

canvas.addEventListener('mousemove', (e) => {
  mouseX = e.clientX;
  mouseY = e.clientY;
  document.getElementById('blade-cursor').style.left = mouseX + 'px';
  document.getElementById('blade-cursor').style.top = mouseY + 'px';

  if (isSlicing && gameState === 'playing') {
    bladeTrail.push({ x: mouseX, y: mouseY });
    prevMouseX = mouseX;
    prevMouseY = mouseY;
  }
});

canvas.addEventListener('mouseup', () => {
  isSlicing = false;
  bladeTrail = [];
  document.getElementById('blade-cursor').classList.remove('slicing');
});

// Touch support
canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  if (gameState !== 'playing') return;
  isSlicing = true;
  totalSwings++;
  const touch = e.touches[0];
  mouseX = touch.clientX;
  mouseY = touch.clientY;
  prevMouseX = mouseX;
  prevMouseY = mouseY;
  bladeTrail = [{ x: mouseX, y: mouseY }];
  document.getElementById('blade-cursor').classList.add('slicing');
});

canvas.addEventListener('touchmove', (e) => {
  e.preventDefault();
  const touch = e.touches[0];
  mouseX = touch.clientX;
  mouseY = touch.clientY;
  document.getElementById('blade-cursor').style.left = mouseX + 'px';
  document.getElementById('blade-cursor').style.top = mouseY + 'px';

  if (isSlicing && gameState === 'playing') {
    bladeTrail.push({ x: mouseX, y: mouseY });
  }
});

canvas.addEventListener('touchend', (e) => {
  e.preventDefault();
  isSlicing = false;
  bladeTrail = [];
  document.getElementById('blade-cursor').classList.remove('slicing');
});

// Button handlers
document.getElementById('startBtn').addEventListener('click', startGame);
document.getElementById('restartBtn').addEventListener('click', startGame);

// Start game loop
gameLoop();
</script>
</body>
