<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Responsive canvas
function resizeCanvas() {
  canvas.width = Math.min(window.innerWidth, 800);
  canvas.height = Math.min(window.innerHeight, 600);
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

// Game state
let gameRunning = false;
let score = 0;
let health = 3;
let cameraX = 0;
let cameraY = 0;
let particles = [];
let bullets = [];
let enemies = [];
let platforms = [];
let stars = [];
let screenShake = 0;

// Player
const player = {
  x: 100,
  y: 300,
  width: 32,
  height: 40,
  vx: 0,
  vy: 0,
  speed: 5,
  jumpForce: -12,
  onGround: false,
  facing: 1,
  shootCooldown: 0,
  invincible: 0,
  animFrame: 0,
  animTimer: 0
};

// Generate stars background
function generateStars() {
  stars = [];
  for (let i = 0; i < 100; i++) {
    stars.push({
      x: Math.random() * 2000,
      y: Math.random() * 1000,
      size: Math.random() * 2 + 0.5,
      brightness: Math.random()
    });
  }
}

// Generate platforms
function generatePlatforms() {
  platforms = [];
  // Ground
  platforms.push({ x: -200, y: canvas.height - 40, width: 3000, height: 40, type: 'ground' });

  // Floating platforms
  const platformData = [
    { x: 200, y: canvas.height - 120, width: 120 },
    { x: 400, y: canvas.height - 200, width: 100 },
    { x: 550, y: canvas.height - 150, width: 130 },
    { x: 750, y: canvas.height - 250, width: 100 },
    { x: 900, y: canvas.height - 180, width: 150 },
    { x: 1100, y: canvas.height - 300, width: 100 },
