    { x: 1700, y: canvas.height - 250, width: 130 },
    { x: 1900, y: canvas.height - 150, width: 100 },
    { x: 2100, y: canvas.height - 280, width: 120 },
    { x: 2300, y: canvas.height - 200, width: 100 },
    { x: 2500, y: canvas.height - 320, width: 150 },
  ];

  platformData.forEach(p => {
