  });
}

// Generate enemies
function generateEnemies() {
  enemies = [];
  const enemyData = [
    { x: 300, y: canvas.height - 80, type: 'walker' },
    { x: 600, y: canvas.height - 80, type: 'walker' },
    { x: 900, y: canvas.height - 220, type: 'flyer' },
    { x: 1200, y: canvas.height - 80, type: 'walker' },
    { x: 1500, y: canvas.height - 390, type: 'flyer' },
    { x: 1800, y: canvas.height - 80, type: 'walker' },
    { x: 2000, y: canvas.height - 190, type: 'flyer' },
    { x: 2300, y: canvas.height - 80, type: 'walker' },
    { x: 2600, y: canvas.height - 360, type: 'flyer' },
  ];

  enemyData.forEach(e => {
    enemies.push({
      x: e.x,
      y: e.y,
      width: 30,
      height: 30,
      vx: e.type === 'walker' ? 1.5 : 0,
      vy: e.type === 'flyer' ? 0 : 0,
      type: e.type,
      health: e.type === 'walker' ? 2 : 1,
      startX: e.x,
      range: 100,
      animTimer: 0,
      alive: true
    });
  });
}

// Reset game
function resetGame() {
  player.x = 100;
  player.y = 300;
  player.vx = 0;
  player.vy = 0;
  player.onGround = false;
  player.invincible = 0;
  score = 0;
  health = 3;
  cameraX = 0;
  cameraY = 0;
  bullets = [];
  particles = [];
  screenShake = 0;
  generatePlatforms();
  generateEnemies();
  generateStars();
  updateUI();
}

// Update UI
function updateUI() {
  document.getElementById('score-display').textContent = `Score: ${score}`;
  let hearts = '';
  for (let i = 0; i < health; i++) hearts += '❤️';
  document.getElementById('health-display').textContent = hearts;
}

// Particle system
function spawnParticles(x, y, color, count, speed) {
  for (let i = 0; i < count; i++) {
    particles.push({
      x: x,
      y: y,
      vx: (Math.random() - 0.5) * speed,
      vy: (Math.random() - 0.5) * speed,
      life: 1,
      decay: Math.random() * 0.03 + 0.02,
      color: color,
      size: Math.random() * 4 + 2
    });
  }
}

// Shoot bullet
function shoot() {
  if (player.shootCooldown > 0) return;
  player.shootCooldown = 15;

  bullets.push({
    x: player.x + player.width / 2 + player.facing * 20,
    y: player.y + player.height / 2,
    vx: player.facing * 10,
    vy: 0,
    width: 12,
    height: 4,
    life: 60,
    color: '#00ffff'
  });

  spawnParticles(
    player.x + player.width / 2 + player.facing * 20,
    player.y + player.height / 2,
    '#00ffff',
    5,
    3
  );
}

// Jump
function jump() {
  if (player.onGround) {
    player.vy = player.jumpForce;
    player.onGround = false;
    spawnParticles(player.x + player.width / 2, player.y + player.height, '#ffffff', 8, 4);
  }
}

// Input handling
const keys = {};
window.addEventListener('keydown', (e) => {
  keys[e.code] = true;
  if (e.code === 'Space') {
    e.preventDefault();
    jump();
  }
  if (e.code === 'Enter' || e.code === 'ArrowUp') {
    e.preventDefault();
    shoot();
  }
});
window.addEventListener('keyup', (e) => {
  keys[e.code] = false;
});

// Touch controls
const jumpBtn = document.getElementById('jump-btn');
const shootBtn = document.getElementById('shoot-btn');

jumpBtn.addEventListener('touchstart', (e) => {
  e.preventDefault();
