});

// Start button
document.getElementById('start-btn').addEventListener('click', () => {
  document.getElementById('start-screen').style.display = 'none';
  resetGame();
  gameRunning = true;
});

// Restart button
document.getElementById('restart-btn').addEventListener('click', () => {
  document.getElementById('game-over').style.display = 'none';
  resetGame();
  gameRunning = true;
});

// Collision detection
function rectCollision(a, b) {
  return a.x < b.x + b.width &&
         a.x + a.width > b.x &&
         a.y < b.y + b.height &&
         a.y + a.height > b.y;
}

// Update game
function update() {
  if (!gameRunning) return;

  // Player movement
  if (keys['ArrowLeft'] || keys['KeyA']) {
    player.vx = -player.speed;
    player.facing = -1;
  } else if (keys['ArrowRight'] || keys['KeyD']) {
    player.vx = player.speed;
    player.facing = 1;
  } else {
    player.vx *= 0.8;
  }

  // Gravity
  player.vy += 0.6;
  if (player.vy > 15) player.vy = 15;

  // Move player
  player.x += player.vx;
  player.y += player.vy;

  // Platform collision
  player.onGround = false;
  platforms.forEach(platform => {
    if (rectCollision(player, platform)) {
      // Landing on top
      if (player.vy > 0 && player.y + player.height - player.vy <= platform.y + 5) {
        player.y = platform.y - player.height;
        player.vy = 0;
        player.onGround = true;
      }
      // Hitting from below
      else if (player.vy < 0 && player.y - player.vy >= platform.y + platform.height - 5) {
        player.y = platform.y + platform.height;
        player.vy = 0;
      }
      // Side collision
      else if (player.vx > 0) {
        player.x = platform.x - player.width;
      } else if (player.vx < 0) {
        player.x = platform.x + platform.width;
      }
    }
  });

  // Fall death
  if (player.y > canvas.height + 100) {
    health = 0;
    updateUI();
    gameOver();
    return;
  }

  // Shoot cooldown
  if (player.shootCooldown > 0) player.shootCooldown--;

  // Invincibility
  if (player.invincible > 0) player.invincible--;

  // Animation
  player.animTimer++;
  if (player.animTimer > 8) {
    player.animTimer = 0;
    player.animFrame = (player.animFrame + 1) % 4;
  }

  // Update bullets
  bullets.forEach(bullet => {
    bullet.x += bullet.vx;
    bullet.life--;
  });
  bullets = bullets.filter(b => b.life > 0);

  // Update enemies
  enemies.forEach(enemy => {
    if (!enemy.alive) return;

    enemy.animTimer++;

    if (enemy.type === 'walker') {
      enemy.x += enemy.vx;
      if (enemy.x > enemy.startX + enemy.range || enemy.x < enemy.startX - enemy.range) {
        enemy.vx *= -1;
      }
    } else if (enemy.type === 'flyer') {
      enemy.x += Math.sin(enemy.animTimer * 0.03) * 2;
      enemy.y += Math.cos(enemy.animTimer * 0.02) * 1;
    }

    // Bullet-enemy collision
    bullets.forEach(bullet => {
      if (rectCollision(bullet, enemy)) {
        enemy.health--;
        bullet.life = 0;
        spawnParticles(enemy.x + enemy.width / 2, enemy.y + enemy.height / 2, '#ffaa00', 10, 5);

        if (enemy.health <= 0) {
          enemy.alive = false;
          score += enemy.type === 'walker' ? 100 : 150;
          spawnParticles(enemy.x + enemy.width / 2, enemy.y + enemy.height / 2, '#ff4444', 20, 8);
          screenShake = 5;
          updateUI();
        }
      }
    });

    // Player-enemy collision
    if (enemy.alive && player.invincible <= 0 && rectCollision(player, enemy)) {
      health--;
      player.invincible = 60;
      player.vy = -8;
      player.vx = player.x < enemy.x ? -5 : 5;
      screenShake = 10;
      spawnParticles(player.x + player.width / 2, player.y + player.height / 2, '#ff0000', 15, 6);
      updateUI();

      if (health <= 0) {
        gameOver();
        return;
      }
    }
  });

  // Update particles
  particles.forEach(p => {
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.1;
    p.life -= p.decay;
  });
  particles = particles.filter(p => p.life > 0);

  // Camera follow
  const targetCameraX = player.x - canvas.width / 3;
  const targetCameraY = player.y - canvas.height / 2;
  cameraX += (targetCameraX - cameraX) * 0.1;
  cameraY += (targetCameraY - cameraY) * 0.1;

  // Clamp camera
  cameraX = Math.max(0, cameraX);
  cameraY = Math.max(-200, Math.min(200, cameraY));

  // Screen shake
  if (screenShake > 0) screenShake--;
}

// Draw game
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Background gradient
  const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
  gradient.addColorStop(0, '#0a0a2e');
  gradient.addColorStop(0.5, '#1a1a4e');
  gradient.addColorStop(1, '#2a1a3e');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Stars
  stars.forEach(star => {
    const sx = star.x - cameraX * 0.3;
    const sy = star.y - cameraY * 0.3;
    if (sx > -10 && sx < canvas.width + 10 && sy > -10 && sy < canvas.height + 10) {
      const alpha = 0.3 + Math.sin(Date.now() * 0.001 + star.brightness * 10) * 0.3;
      ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
      ctx.beginPath();
      ctx.arc(sx, sy, star.size, 0, Math.PI * 2);
      ctx.fill();
    }
  });

  // Screen shake
  ctx.save();
  if (screenShake > 0) {
    ctx.translate(
      (Math.random() - 0.5) * screenShake * 2,
      (Math.random() - 0.5) * screenShake * 2
    );
  }

  // Camera transform
  ctx.translate(-cameraX, -cameraY);

  // Draw platforms
  platforms.forEach(platform => {
    if (platform.type === 'ground') {
      // Ground
      const groundGrad = ctx.createLinearGradient(platform.x, platform.y, platform.x, platform.y + platform.height);
      groundGrad.addColorStop(0, '#4a7a4a');
      groundGrad.addColorStop(1, '#2a4a2a');
      ctx.fillStyle = groundGrad;
      ctx.fillRect(platform.x, platform.y, platform.width, platform.height);

      // Grass top
      ctx.fillStyle = '#6a9a6a';
      ctx.fillRect(platform.x, platform.y, platform.width, 5);
    } else {
      // Floating platform
      const platGrad = ctx.createLinearGradient(platform.x, platform.y, platform.x, platform.y + platform.height);
      platGrad.addColorStop(0, '#5a5a8a');
      platGrad.addColorStop(1, '#3a3a6a');
      ctx.fillStyle = platGrad;

      // Rounded rectangle
      const r = 5;
      ctx.beginPath();
      ctx.moveTo(platform.x + r, platform.y);
      ctx.lineTo(platform.x + platform.width - r, platform.y);
      ctx.quadraticCurveTo(platform.x + platform.width, platform.y, platform.x + platform.width, platform.y + r);
      ctx.lineTo(platform.x + platform.width, platform.y + platform.height - r);
      ctx.quadraticCurveTo(platform.x + platform.width, platform.y + platform.height, platform.x + platform.width - r, platform.y + platform.height);
      ctx.lineTo(platform.x + r, platform.y + platform.height);
      ctx.quadraticCurveTo(platform.x, platform.y + platform.height, platform.x, platform.y + platform.height - r);
      ctx.lineTo(platform.x, platform.y + r);
      ctx.quadraticCurveTo(platform.x, platform.y, platform.x + r, platform.y);
      ctx.fill();

      // Highlight
      ctx.fillStyle = 'rgba(255,255,255,0.1)';
      ctx.fillRect(platform.x + 2, platform.y + 2, platform.width - 4, 3);
    }
  });

  // Draw bullets
  bullets.forEach(bullet => {
    ctx.fillStyle = bullet.color;
    ctx.shadowColor = bullet.color;
    ctx.shadowBlur = 10;
    ctx.fillRect(bullet.x - bullet.width / 2, bullet.y - bullet.height / 2, bullet.width, bullet.height);
    ctx.shadowBlur = 0;
  });

  // Draw enemies
  enemies.forEach(enemy => {
    if (!enemy.alive) return;

    ctx.save();
    ctx.translate(enemy.x + enemy.width / 2, enemy.y + enemy.height / 2);

    if (enemy.type === 'walker') {
      // Walker enemy - red box with eyes
      ctx.fillStyle = '#ff4444';
      ctx.fillRect(-enemy.width / 2, -enemy.height / 2, enemy.width, enemy.height);

      // Eyes
      ctx.fillStyle = '#fff';
      ctx.fillRect(-8, -8, 6, 6);
      ctx.fillRect(2, -8, 6, 6);
      ctx.fillStyle = '#000';
      ctx.fillRect(-6, -6, 3, 3);
      ctx.fillRect(4, -6, 3, 3);

      // Mouth
      ctx.fillStyle = '#000';
      ctx.fillRect(-5, 5, 10, 3);
    } else {
      // Flyer enemy - purple circle
      ctx.fillStyle = '#aa44ff';
      ctx.beginPath();
      ctx.arc(0, 0, enemy.width / 2, 0, Math.PI * 2);
      ctx.fill();

      // Wings
      const wingFlap = Math.sin(enemy.animTimer * 0.2) * 5;
      ctx.fillStyle = '#cc66ff';
      ctx.fillRect(-enemy.width / 2 - 8, -5 + wingFlap, 10, 10);
      ctx.fillRect(enemy.width / 2 - 2, -5 - wingFlap, 10, 10);

      // Eye
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(0, -3, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#000';
      ctx.beginPath();
      ctx.arc(0, -3, 2, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  });

  // Draw player
  ctx.save();
  ctx.translate(player.x + player.width / 2, player.y + player.height / 2);

  if (player.invincible > 0 && Math.floor(player.invincible / 4) % 2 === 0) {
    ctx.globalAlpha = 0.5;
  }

  // Body
  ctx.fillStyle = '#4488ff';
  ctx.fillRect(-player.width / 2, -player.height / 2, player.width, player.height);

  // Head
  ctx.fillStyle = '#ffcc88';
  ctx.fillRect(-8, -player.height / 2 - 10, 16, 14);

  // Eyes
  ctx.fillStyle = '#fff';
  ctx.fillRect(player.facing * 2 - 3, -player.height / 2 - 6, 6, 5);
  ctx.fillStyle = '#000';
  ctx.fillRect(player.facing * 2 - 1, -player.height / 2 - 5, 3, 3);

  // Gun
  ctx.fillStyle = '#888';
  ctx.fillRect(player.facing * 10, -5, player.facing * 15, 6);
  ctx.fillStyle = '#aaa';
  ctx.fillRect(player.facing * 20, -7, player.facing * 5, 10);

  // Legs animation
  if (!player.onGround) {
    ctx.fillStyle = '#3366cc';
    ctx.fillRect(-8, player.height / 2 - 5, 6, 8);
    ctx.fillRect(2, player.height / 2 - 5, 6, 8);
  } else if (Math.abs(player.vx) > 0.5) {
    const legAnim = Math.sin(player.animTimer * 0.5) * 5;
    ctx.fillStyle = '#3366cc';
    ctx.fillRect(-8, player.height / 2 - 5, 6, 8 + legAnim);
    ctx.fillRect(2, player.height / 2 - 5, 6, 8 - legAnim);
  }

  ctx.restore();

  // Draw particles
  particles.forEach(p => {
    ctx.globalAlpha = p.life;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.globalAlpha = 1;

  ctx.restore();
}

// Game over
function gameOver() {
  gameRunning = false;
  document.getElementById('final-score').textContent = score;
  document.getElementById('game-over').style.display = 'block';
}

// Game loop
function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

// Initialize
generateStars();
gameLoop();
</script>
