            score = 0;
            frameCount = 0;
            difficulty = 1;
            pipeTimer = 0;
            scoreDisplay.textContent = '0';
        }

        function flap() {
            if (gameState === 'start') {
                gameState = 'playing';
                resetGame();
                bird.velocity = bird.jumpStrength;
                bird.flapSpeed = 15;
            } else if (gameState === 'playing') {
                bird.velocity = bird.jumpStrength;
                bird.flapSpeed = 15;
                // Add flap particles
                for (let i = 0; i < 5; i++) {
                    particles.push({
                        x: bird.x,
                        y: bird.y + bird.height / 2,
                        vx: -Math.random() * 3 - 1,
                        vy: Math.random() * 2 - 1,
                        life: 30,
                        maxLife: 30,
                        size: Math.random() * 4 + 2,
                        color: `hsl(${40 + Math.random() * 20}, 100%, ${70 + Math.random() * 20}%)`
                    });
                }
            } else if (gameState === 'gameover') {
                gameState = 'start';
                resetGame();
            }
        }

        // Input handlers
        document.addEventListener('keydown', (e) => {
            if (e.code === 'Space' || e.code === 'ArrowUp') {
                e.preventDefault();
                flap();
            }
            if (e.code === 'Enter') {
                if (gameState === 'gameover') {
                    gameState = 'start';
                    resetGame();
                }
            }
        });

        canvas.addEventListener('click', flap);
        canvas.addEventListener('touchstart', (e) => {
            e.preventDefault();
            flap();
        });

        function drawBackground() {
            // Sky gradient
            const skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
            skyGrad.addColorStop(0, colors.skyTop);
            skyGrad.addColorStop(0.5, '#1e3a5f');
            skyGrad.addColorStop(1, '#2d1b69');
            ctx.fillStyle = skyGrad;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Stars
            stars.forEach(star => {
                star.brightness += 0.02;
                const alpha = 0.3 + Math.sin(star.brightness) * 0.3;
                ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
                ctx.beginPath();
                ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
                ctx.fill();
                star.x -= star.speed;
                if (star.x < -5) star.x = canvas.width + 5;
            });

            // Clouds
            clouds.forEach(cloud => {
                ctx.fillStyle = `rgba(255, 255, 255, ${cloud.opacity})`;
                ctx.beginPath();
                ctx.ellipse(cloud.x, cloud.y, cloud.width / 2, cloud.height / 2, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.beginPath();
                ctx.ellipse(cloud.x - cloud.width * 0.3, cloud.y + 5, cloud.width * 0.3, cloud.height * 0.4, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.beginPath();
                ctx.ellipse(cloud.x + cloud.width * 0.3, cloud.y + 3, cloud.width * 0.35, cloud.height * 0.45, 0, 0, Math.PI * 2);
                ctx.fill();
                cloud.x -= cloud.speed;
                if (cloud.x < -cloud.width) cloud.x = canvas.width + cloud.width;
            });
        }

        function drawGround() {
            const groundY = canvas.height - groundHeight;

            // Ground body
            const groundGrad = ctx.createLinearGradient(0, groundY, 0, canvas.height);
            groundGrad.addColorStop(0, '#4a7c59');
            groundGrad.addColorStop(0.1, '#3d6b4e');
            groundGrad.addColorStop(1, '#2d4a35');
            ctx.fillStyle = groundGrad;
            ctx.fillRect(0, groundY, canvas.width, groundHeight);

            // Ground top line
            ctx.fillStyle = '#5a9c69';
            ctx.fillRect(0, groundY, canvas.width, 3);

            // Ground pattern
            groundOffset = (groundOffset + pipeSpeed) % 40;
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.1)';
            ctx.lineWidth = 1;
            for (let i = -40 + groundOffset; i < canvas.width; i += 40) {
                ctx.beginPath();
                ctx.moveTo(i, groundY + 10);
                ctx.lineTo(i + 20, groundY + groundHeight);
                ctx.stroke();
            }

            // Grass tufts
            ctx.fillStyle = '#6ab04c';
            for (let i = -40 + groundOffset; i < canvas.width; i += 30) {
                ctx.beginPath();
                ctx.moveTo(i, groundY);
                ctx.lineTo(i + 5, groundY - 8);
                ctx.lineTo(i + 10, groundY);
                ctx.fill();
            }
        }

        function drawBird() {
            ctx.save();
            ctx.translate(bird.x + bird.width / 2, bird.y + bird.height / 2);

            // Rotation based on velocity
            bird.rotation = Math.min(Math.max(bird.velocity * 3, -30), 70);
            ctx.rotate(bird.rotation * Math.PI / 180);

            // Trail
            bird.trail.push({ x: bird.x, y: bird.y + bird.height / 2, alpha: 1 });
            if (bird.trail.length > 10) bird.trail.shift();

            // Draw trail
            bird.trail.forEach((t, i) => {
                t.alpha -= 0.1;
                if (t.alpha > 0) {
                    ctx.fillStyle = `rgba(247, 183, 51, ${t.alpha * 0.3})`;
                    ctx.beginPath();
                    ctx.arc(t.x - bird.x + bird.width / 2, t.y - bird.y - bird.height / 2, 3, 0, Math.PI * 2);
                    ctx.fill();
                }
            });

            // Body
            const bodyGrad = ctx.createRadialGradient(0, 0, 5, 0, 0, 20);
            bodyGrad.addColorStop(0, '#fdd835');
            bodyGrad.addColorStop(0.7, colors.birdBody);
            bodyGrad.addColorStop(1, colors.birdDark);
            ctx.fillStyle = bodyGrad;
            ctx.beginPath();
            ctx.ellipse(0, 0, bird.width / 2, bird.height / 2, 0, 0, Math.PI * 2);
            ctx.fill();

            // Body outline
            ctx.strokeStyle = '#e8a825';
            ctx.lineWidth = 1.5;
            ctx.stroke();

            // Wing
            bird.flapFrame += bird.flapSpeed > 0 ? 1 : 0.3;
            if (bird.flapSpeed > 0) bird.flapSpeed--;

            const wingY = Math.sin(bird.flapFrame * 0.3) * 8;
            ctx.fillStyle = colors.birdWing;
            ctx.beginPath();
            ctx.ellipse(-5, wingY, 12, 8, -0.3, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#d4941a';
            ctx.lineWidth = 1;
            ctx.stroke();

            // Eye
            ctx.fillStyle = colors.birdEye;
            ctx.beginPath();
            ctx.arc(10, -5, 6, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#333';
            ctx.lineWidth = 1;
            ctx.stroke();

            // Pupil
            ctx.fillStyle = colors.birdPupil;
            ctx.beginPath();
            ctx.arc(12, -5, 3, 0, Math.PI * 2);
            ctx.fill();

            // Eye shine
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.arc(13, -6, 1.5, 0, Math.PI * 2);
            ctx.fill();

            // Beak
            ctx.fillStyle = colors.birdBeak;
            ctx.beginPath();
            ctx.moveTo(18, -2);
            ctx.lineTo(28, 2);
            ctx.lineTo(18, 6);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#c0392b';
            ctx.lineWidth = 1;
            ctx.stroke();

            // Tail feathers
            ctx.fillStyle = colors.birdDark;
            ctx.beginPath();
            ctx.moveTo(-18, -3);
            ctx.lineTo(-28, -8);
            ctx.lineTo(-25, 0);
            ctx.lineTo(-28, 8);
            ctx.lineTo(-18, 3);
            ctx.closePath();
            ctx.fill();

            ctx.restore();
        }

        function drawPipe(pipe) {
            const topPipeHeight = pipe.y;
            const bottomPipeY = pipe.y + pipeGap;

            // Top pipe
            const topGrad = ctx.createLinearGradient(pipe.x, 0, pipe.x + pipeWidth, 0);
            topGrad.addColorStop(0, colors.pipeDark);
            topGrad.addColorStop(0.3, colors.pipeHighlight);
            topGrad.addColorStop(0.7, colors.pipeBody);
            topGrad.addColorStop(1, colors.pipeDark);

            ctx.fillStyle = topGrad;
            ctx.fillRect(pipe.x, 0, pipeWidth, topPipeHeight);

            // Top pipe cap
            const capWidth = pipeWidth + 10;
            const capHeight = 25;
            const capX = pipe.x - 5;
            const capY = topPipeHeight - capHeight;

            const capGrad = ctx.createLinearGradient(capX, 0, capX + capWidth, 0);
            capGrad.addColorStop(0, colors.pipeDark);
            capGrad.addColorStop(0.3, colors.pipeHighlight);
            capGrad.addColorStop(0.7, colors.pipeBody);
            capGrad.addColorStop(1, colors.pipeDark);

            ctx.fillStyle = capGrad;
            ctx.beginPath();
            ctx.roundRect(capX, capY, capWidth, capHeight, 5);
            ctx.fill();
            ctx.strokeStyle = '#1e8449';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Top pipe border
            ctx.strokeStyle = '#1e8449';
            ctx.lineWidth = 2;
            ctx.strokeRect(pipe.x, 0, pipeWidth, topPipeHeight - capHeight);

            // Bottom pipe
            ctx.fillStyle = topGrad;
            ctx.fillRect(pipe.x, bottomPipeY, pipeWidth, canvas.height - bottomPipeY - groundHeight);

            // Bottom pipe cap
            const bottomCapY = bottomPipeY;
            ctx.fillStyle = capGrad;
            ctx.beginPath();
            ctx.roundRect(capX, bottomCapY, capWidth, capHeight, 5);
            ctx.fill();
            ctx.strokeStyle = '#1e8449';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Bottom pipe border
            ctx.strokeStyle = '#1e8449';
            ctx.lineWidth = 2;
            ctx.strokeRect(pipe.x, bottomPipeY + capHeight, pipeWidth, canvas.height - bottomPipeY - capHeight - groundHeight);

            // Pipe shine effect
            ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
            ctx.fillRect(pipe.x + 5, 0, 8, topPipeHeight - capHeight);
            ctx.fillRect(pipe.x + 5, bottomPipeY + capHeight, 8, canvas.height - bottomPipeY - capHeight - groundHeight);
        }

        function drawParticles() {
            particles.forEach((p, i) => {
                p.x += p.vx;
                p.y += p.vy;
                p.life--;

                const alpha = p.life / p.maxLife;
                ctx.fillStyle = p.color.replace(')', `, ${alpha})`).replace('hsl', 'hsla');
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size * alpha, 0, Math.PI * 2);
                ctx.fill();

                if (p.life <= 0) particles.splice(i, 1);
            });
        }

        function drawScore() {
            if (gameState === 'playing') {
                // Score shadow
                ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
                ctx.font = 'bold 48px Arial';
                ctx.textAlign = 'center';
                ctx.fillText(score, canvas.width / 2 + 3, 63);

                // Score
                ctx.fillStyle = '#fff';
                ctx.strokeStyle = '#333';
                ctx.lineWidth = 3;
                ctx.font = 'bold 48px Arial';
                ctx.textAlign = 'center';
                ctx.strokeText(score, canvas.width / 2, 60);
                ctx.fillText(score, canvas.width / 2, 60);
            }
        }

        function drawStartScreen() {
            // Overlay
            ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Title
            ctx.fillStyle = '#f7b733';
            ctx.strokeStyle = '#333';
            ctx.lineWidth = 4;
            ctx.font = 'bold 52px Arial';
            ctx.textAlign = 'center';
            ctx.strokeText('🐦 Bird Fly', canvas.width / 2, 200);
            ctx.fillText('🐦 Bird Fly', canvas.width / 2, 200);

            // Subtitle
            ctx.fillStyle = '#fff';
            ctx.font = '24px Arial';
            ctx.fillText('Click or Press Space to Start', canvas.width / 2, 300);

            // Animated bird
            const bounceY = Math.sin(frameCount * 0.05) * 15;
            ctx.save();
            ctx.translate(canvas.width / 2, 380 + bounceY);
            ctx.scale(2, 2);
            // Simple bird drawing
            ctx.fillStyle = '#f7b733';
            ctx.beginPath();
            ctx.ellipse(0, 0, 20, 15, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.arc(8, -5, 5, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#333';
            ctx.beginPath();
            ctx.arc(10, -5, 2.5, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#e74c3c';
            ctx.beginPath();
            ctx.moveTo(18, -2);
            ctx.lineTo(28, 2);
            ctx.lineTo(18, 6);
            ctx.closePath();
            ctx.fill();
            ctx.restore();

            // Instructions
            ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
            ctx.font = '18px Arial';
            ctx.fillText('Navigate through the pipes!', canvas.width / 2, 480);
            ctx.fillText('Don\'t hit the pipes or ground!', canvas.width / 2, 510);
        }

        function drawGameOver() {
            // Overlay
            ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Game Over panel
            const panelWidth = 300;
            const panelHeight = 250;
            const panelX = (canvas.width - panelWidth) / 2;
            const panelY = (canvas.height - panelHeight) / 2;

            // Panel background
            ctx.fillStyle = 'rgba(20, 20, 40, 0.9)';
            ctx.beginPath();
            ctx.roundRect(panelX, panelY, panelWidth, panelHeight, 20);
            ctx.fill();
            ctx.strokeStyle = '#f7b733';
            ctx.lineWidth = 3;
            ctx.stroke();

            // Game Over text
            ctx.fillStyle = '#e74c3c';
            ctx.strokeStyle = '#333';
            ctx.lineWidth = 3;
            ctx.font = 'bold 40px Arial';
            ctx.textAlign = 'center';
            ctx.strokeText('Game Over', canvas.width / 2, panelY + 60);
            ctx.fillText('Game Over', canvas.width / 2, panelY + 60);

            // Score
            ctx.fillStyle = '#fff';
            ctx.font = '24px Arial';
            ctx.fillText(`Score: ${score}`, canvas.width / 2, panelY + 110);

            // Best score
            ctx.fillStyle = '#f7b733';
            ctx.font = '22px Arial';
            ctx.fillText(`Best: ${bestScore}`, canvas.width / 2, panelY + 150);

            // New best indicator
            if (score >= bestScore && score > 0) {
                ctx.fillStyle = '#55efc4';
                ctx.font = 'bold 18px Arial';
                ctx.fillText('🎉 New Best! 🎉', canvas.width / 2, panelY + 185);
            }

            // Restart instruction
            ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
            ctx.font = '18px Arial';
            ctx.fillText('Press Enter or Click to Restart', canvas.width / 2, panelY + 225);
        }

        function checkCollision() {
            const birdLeft = bird.x + 5;
            const birdRight = bird.x + bird.width - 5;
            const birdTop = bird.y + 5;
            const birdBottom = bird.y + bird.height - 5;

            // Ground collision
            if (birdBottom >= canvas.height - groundHeight) {
                return true;
            }

            // Ceiling collision
            if (birdTop <= 0) {
                return true;
            }

            // Pipe collision
            for (let pipe of pipes) {
                const pipeLeft = pipe.x;
                const pipeRight = pipe.x + pipeWidth;

                if (birdRight > pipeLeft && birdLeft < pipeRight) {
                    if (birdTop < pipe.y || birdBottom > pipe.y + pipeGap) {
                        return true;
                    }
                }
            }

            return false;
        }

        function update() {
            frameCount++;

            if (gameState === 'playing') {
                // Bird physics
                bird.velocity += bird.gravity;
                bird.y += bird.velocity;

                // Pipe spawning
                pipeTimer++;
                if (pipeTimer >= pipeInterval) {
                    pipeTimer = 0;
                    const minY = 80;
                    const maxY = canvas.height - groundHeight - pipeGap - 80;
                    const pipeY = Math.random() * (maxY - minY) + minY;
                    pipes.push({
                        x: canvas.width,
                        y: pipeY,
                        scored: false
                    });
                }

                // Update pipes
                pipes.forEach((pipe, i) => {
                    pipe.x -= pipeSpeed;

                    // Score counting
                    if (!pipe.scored && pipe.x + pipeWidth < bird.x) {
                        pipe.scored = true;
                        score++;
                        scoreDisplay.textContent = score;

                        // Increase difficulty
                        if (score % 5 === 0) {
                            difficulty += 0.1;
                        }

                        // Score particles
                        for (let j = 0; j < 10; j++) {
                            particles.push({
                                x: bird.x + bird.width,
                                y: bird.y,
                                vx: Math.random() * 4 - 2,
                                vy: Math.random() * 4 - 2,
                                life: 40,
                                maxLife: 40,
                                size: Math.random() * 5 + 2,
                                color: `hsl(${Math.random() * 60 + 30}, 100%, 60%)`
                            });
                        }
                    }

                    // Remove off-screen pipes
                    if (pipe.x + pipeWidth < -10) {
                        pipes.splice(i, 1);
                    }
                });

                // Collision detection
                if (checkCollision()) {
                    gameState = 'gameover';
                    if (score > bestScore) {
                        bestScore = score;
                        localStorage.setItem('birdFlyBest', bestScore);
                        bestDisplay.textContent = bestScore;
                    }

                    // Explosion particles
                    for (let i = 0; i < 30; i++) {
                        particles.push({
                            x: bird.x + bird.width / 2,
                            y: bird.y + bird.height / 2,
                            vx: Math.random() * 8 - 4,
                            vy: Math.random() * 8 - 4,
                            life: 60,
                            maxLife: 60,
                            size: Math.random() * 6 + 2,
                            color: `hsl(${Math.random() * 60 + 10}, 100%, 50%)`
                        });
                    }
                }
            }
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            drawBackground();

            // Draw pipes
            pipes.forEach(pipe => drawPipe(pipe));

            drawGround();
            drawParticles();
            drawBird();
            drawScore();

            if (gameState === 'start') {
                drawStartScreen();
            } else if (gameState === 'gameover') {
                drawGameOver();
            }
        }

        function gameLoop() {
            update();
            draw();
            requestAnimationFrame(gameLoop);
        }

        // Polyfill for roundRect if needed
        if (!ctx.roundRect) {
            CanvasRenderingContext2D.prototype.roundRect = function(x, y, w, h, r) {
                if (typeof r === 'number') r = [r, r, r, r];
                const [tl, tr, br, bl] = r;
                this.moveTo(x + tl, y);
                this.lineTo(x + w - tr, y);
                this.quadraticCurveTo(x + w, y, x + w, y + tr);
                this.lineTo(x + w, y + h - br);
                this.quadraticCurveTo(x + w, y + h, x + w - br, y + h);
                this.lineTo(x + bl, y + h);
                this.quadraticCurveTo(x, y + h, x, y + h - bl);
                this.lineTo(x, y + tl);
                this.quadraticCurveTo(x, y, x + tl, y);
                this.closePath();
                return this;
            };
        }

        // Start the game
        gameLoop();
    </script>
