<script>
// ==================== STOCK DATA ====================
const STOCKS = [
  { symbol: 'AAPL', name: 'Apple Inc.', price: 178.72, volatility: 0.002, sector: 'Technology' },
  { symbol: 'GOOGL', name: 'Alphabet Inc.', price: 141.80, volatility: 0.003, sector: 'Technology' },
  { symbol: 'MSFT', name: 'Microsoft Corp.', price: 378.91, volatility: 0.002, sector: 'Technology' },
  { symbol: 'AMZN', name: 'Amazon.com Inc.', price: 185.07, volatility: 0.003, sector: 'Consumer' },
  { symbol: 'TSLA', name: 'Tesla Inc.', price: 248.42, volatility: 0.005, sector: 'Automotive' },
  { symbol: 'NVDA', name: 'NVIDIA Corp.', price: 875.28, volatility: 0.004, sector: 'Technology' },
  { symbol: 'META', name: 'Meta Platforms', price: 505.75, volatility: 0.003, sector: 'Technology' },
  { symbol: 'JPM', name: 'JPMorgan Chase', price: 198.47, volatility: 0.002, sector: 'Finance' },
  { symbol: 'V', name: 'Visa Inc.', price: 279.32, volatility: 0.002, sector: 'Finance' },
  { symbol: 'JNJ', name: 'Johnson & Johnson', price: 156.74, volatility: 0.001, sector: 'Healthcare' },
  { symbol: 'WMT', name: 'Walmart Inc.', price: 168.53, volatility: 0.001, sector: 'Consumer' },
  { symbol: 'DIS', name: 'Walt Disney Co.', price: 112.84, volatility: 0.003, sector: 'Entertainment' },
];

// ==================== STATE ====================
let state = {
  cash: 100000,
  initialCash: 100000,
  portfolio: {},
  holdings: {},
  trades: [],
  selectedStock: 'AAPL',
  tradeType: 'buy',
  stocks: {},
  chartData: {},
  currentTime: new Date(),
  dayOpen: {},
};

// Initialize stocks
STOCKS.forEach(s => {
  state.stocks[s.symbol] = {
    ...s,
    currentPrice: s.price,
    previousPrice: s.price,
    openPrice: s.price,
    highPrice: s.price,
    lowPrice: s.price,
    volume: Math.floor(Math.random() * 10000000) + 1000000,
    change: 0,
    changePercent: 0,
    history: [],
    sparkline: [],
  };
  state.dayOpen[s.symbol] = s.price;

  // Generate initial chart data
  generateChartData(s.symbol, 100);
});

// ==================== PRICE SIMULATION ====================
function generateChartData(symbol, count) {
  const stock = state.stocks[symbol];
  const data = [];
  let price = stock.openPrice * (0.95 + Math.random() * 0.1);

  for (let i = 0; i < count; i++) {
    const change = (Math.random() - 0.48) * stock.volatility * price;
    price = Math.max(price * 0.5, price + change);
    const volume = Math.floor(Math.random() * 500000) + 50000;
    data.push({
      time: Date.now() - (count - i) * 60000,
      open: price,
      high: price + Math.random() * price * 0.002,
      low: price - Math.random() * price * 0.002,
      close: price + (Math.random() - 0.5) * price * 0.001,
      volume: volume,
    });
    price = data[data.length - 1].close;
  }

  stock.history = data;
  stock.sparkline = data.slice(-20).map(d => d.close);
  stock.currentPrice = data[data.length - 1].close;
  stock.previousPrice = data[data.length - 2]?.close || stock.openPrice;
  stock.change = stock.currentPrice - stock.openPrice;
  stock.changePercent = (stock.change / stock.openPrice) * 100;
  stock.highPrice = Math.max(...data.map(d => d.high));
  stock.lowPrice = Math.min(...data.map(d => d.low));
  stock.volume = data.reduce((sum, d) => sum + d.volume, 0);
}

function updatePrices() {
  Object.keys(state.stocks).forEach(symbol => {
    const stock = state.stocks[symbol];
    stock.previousPrice = stock.currentPrice;

    // Geometric Brownian Motion
    const drift = (Math.random() - 0.48) * stock.volatility;
    const change = stock.currentPrice * drift;
    stock.currentPrice = Math.max(stock.currentPrice * 0.1, stock.currentPrice + change);

    // Update OHLC
    stock.highPrice = Math.max(stock.highPrice, stock.currentPrice);
    stock.lowPrice = Math.min(stock.lowPrice, stock.currentPrice);
    stock.volume += Math.floor(Math.random() * 10000);

    stock.change = stock.currentPrice - state.dayOpen[symbol];
    stock.changePercent = (stock.change / state.dayOpen[symbol]) * 100;

    // Add to history
    const lastCandle = stock.history[stock.history.length - 1];
    if (lastCandle) {
      lastCandle.close = stock.currentPrice;
      lastCandle.high = Math.max(lastCandle.high, stock.currentPrice);
      lastCandle.low = Math.min(lastCandle.low, stock.currentPrice);
      lastCandle.volume += Math.floor(Math.random() * 5000);
    }

    // Sparkline
    stock.sparkline.push(stock.currentPrice);
    if (stock.sparkline.length > 20) stock.sparkline.shift();
  });

  updateUI();
}

// ==================== UI UPDATE ====================
function updateUI() {
  updateWatchlist();
  updateChartHeader();
  updatePortfolio();
  updateHoldings();
  updateSummary();
  updateHeaderStats();
}

function updateWatchlist() {
  const container = document.getElementById('watchlistItems');
  const search = document.getElementById('searchInput').value.toLowerCase();

  const filtered = STOCKS.filter(s =>
    s.symbol.toLowerCase().includes(search) ||
    s.name.toLowerCase().includes(search)
  );

  container.innerHTML = filtered.map(s => {
    const stock = state.stocks[s.symbol];
    const isPositive = stock.change >= 0;
    const isActive = s.symbol === state.selectedStock;

    return `
      <div class="watchlist-item ${isActive ? 'active' : ''} ${stock.currentPrice > stock.previousPrice ? 'flash-green' : stock.currentPrice < stock.previousPrice ? 'flash-red' : ''}"
           onclick="selectStock('${s.symbol}')">
        <span class="wl-symbol">${s.symbol}</span>
        <span class="wl-price">$${stock.currentPrice.toFixed(2)}</span>
        <span class="wl-name">${s.name}</span>
        <span class="wl-change ${isPositive ? 'positive' : 'negative'}">
          ${isPositive ? '▲' : '▼'} ${isPositive ? '+' : ''}${stock.change.toFixed(2)} (${isPositive ? '+' : ''}${stock.changePercent.toFixed(2)}%)
        </span>
        <canvas class="wl-sparkline" id="spark_${s.symbol}" width="240" height="32"></canvas>
      </div>
    `;
  }).join('');

  // Draw sparklines
  filtered.forEach(s => {
    const canvas = document.getElementById(`spark_${s.symbol}`);
    if (canvas) drawSparkline(canvas, state.stocks[s.symbol].sparkline);
  });
}

function drawSparkline(canvas, data) {
  if (!data || data.length < 2) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  ctx.clearRect(0, 0, width, height);

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;

  const isPositive = data[data.length - 1] >= data[0];
  const color = isPositive ? '#10b981' : '#ef4444';

  ctx.beginPath();
  ctx.strokeStyle = color;
  ctx.lineWidth = 1.5;

  data.forEach((price, i) => {
    const x = (i / (data.length - 1)) * width;
    const y = height - ((price - min) / range) * (height - 4) - 2;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });

  ctx.stroke();

  // Fill area
  const lastX = width;
  const lastY = height - ((data[data.length - 1] - min) / range) * (height - 4) - 2;
  ctx.lineTo(lastX, height);
  ctx.lineTo(0, height);
  ctx.closePath();

  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, isPositive ? 'rgba(16, 185, 129, 0.15)' : 'rgba(239, 68, 68, 0.15)');
  gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
  ctx.fillStyle = gradient;
  ctx.fill();
}

function updateChartHeader() {
  const stock = state.stocks[state.selectedStock];
  const isPositive = stock.change >= 0;

  document.getElementById('chartSymbol').textContent = stock.symbol;
  document.getElementById('chartPrice').textContent = `$${stock.currentPrice.toFixed(2)}`;

  const changeEl = document.getElementById('chartChange');
  changeEl.textContent = `${isPositive ? '+' : ''}${stock.change.toFixed(2)} (${isPositive ? '+' : ''}${stock.changePercent.toFixed(2)}%)`;
  changeEl.className = `chart-change ${isPositive ? 'positive' : 'negative'}`;

  document.getElementById('chartOpen').textContent = `$${stock.openPrice.toFixed(2)}`;
  document.getElementById('chartHigh').textContent = `$${stock.highPrice.toFixed(2)}`;
  document.getElementById('chartLow').textContent = `$${stock.lowPrice.toFixed(2)}`;
  document.getElementById('chartVolume').textContent = formatVolume(stock.volume);

  drawMainChart();
}

function drawMainChart() {
  const canvas = document.getElementById('mainChart');
  const ctx = canvas.getContext('2d');
  const rect = canvas.parentElement.getBoundingClientRect();
  canvas.width = rect.width * window.devicePixelRatio;
  canvas.height = rect.height * window.devicePixelRatio;
  canvas.style.width = rect.width + 'px';
  canvas.style.height = rect.height + 'px';
  ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

  const width = rect.width;
  const height = rect.height;
  const stock = state.stocks[state.selectedStock];
  const data = stock.history;

  if (!data || data.length < 2) return;

  ctx.clearRect(0, 0, width, height);

  const padding = { top: 40, right: 80, bottom: 40, left: 10 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;

  const prices = data.flatMap(d => [d.high, d.low]);
  const minPrice = Math.min(...prices) * 0.999;
  const maxPrice = Math.max(...prices) * 1.001;
  const priceRange = maxPrice - minPrice || 1;

  // Grid lines
  ctx.strokeStyle = 'rgba(42, 58, 74, 0.5)';
  ctx.lineWidth = 0.5;
  const gridLines = 6;
  for (let i = 0; i <= gridLines; i++) {
    const y = padding.top + (i / gridLines) * chartHeight;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(width - padding.right, y);
    ctx.stroke();

    // Price labels
    const price = maxPrice - (i / gridLines) * priceRange;
    ctx.fillStyle = '#64748b';
    ctx.font = '11px JetBrains Mono';
    ctx.textAlign = 'left';
    ctx.fillText(`$${price.toFixed(2)}`, width - padding.right + 8, y + 4);
  }

  // Volume bars
  const maxVolume = Math.max(...data.map(d => d.volume));
  const volumeHeight = chartHeight * 0.15;

  data.forEach((d, i) => {
    const x = padding.left + (i / (data.length - 1)) * chartWidth;
    const barWidth = Math.max(1, chartWidth / data.length - 1);
    const volH = (d.volume / maxVolume) * volumeHeight;
    const isPositive = d.close >= d.open;

    ctx.fillStyle = isPositive ? 'rgba(16, 185, 129, 0.2)' : 'rgba(239, 68, 68, 0.2)';
    ctx.fillRect(x - barWidth / 2, height - padding.bottom - volH, barWidth, volH);
  });

  // Candlestick chart
  const candleWidth = Math.max(2, chartWidth / data.length - 2);

  data.forEach((d, i) => {
    const x = padding.left + (i / (data.length - 1)) * chartWidth;
    const isPositive = d.close >= d.open;

    const openY = padding.top + ((maxPrice - d.open) / priceRange) * chartHeight;
    const closeY = padding.top + ((maxPrice - d.close) / priceRange) * chartHeight;
    const highY = padding.top + ((maxPrice - d.high) / priceRange) * chartHeight;
    const lowY = padding.top + ((maxPrice - d.low) / priceRange) * chartHeight;

    // Wick
    ctx.strokeStyle = isPositive ? '#10b981' : '#ef4444';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, highY);
    ctx.lineTo(x, lowY);
    ctx.stroke();

    // Body
    const bodyTop = Math.min(openY, closeY);
    const bodyHeight = Math.max(1, Math.abs(openY - closeY));

    if (isPositive) {
      ctx.fillStyle = '#10b981';
    } else {
      ctx.fillStyle = '#ef4444';
    }
    ctx.fillRect(x - candleWidth / 2, bodyTop, candleWidth, bodyHeight);
  });

  // Current price line
  const currentY = padding.top + ((maxPrice - stock.currentPrice) / priceRange) * chartHeight;
  ctx.strokeStyle = stock.change >= 0 ? '#10b981' : '#ef4444';
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  ctx.moveTo(padding.left, currentY);
  ctx.lineTo(width - padding.right, currentY);
  ctx.stroke();
  ctx.setLineDash([]);

  // Price tag
  ctx.fillStyle = stock.change >= 0 ? '#10b981' : '#ef4444';
  const tagWidth = 70;
  const tagHeight = 22;
  ctx.fillRect(width - padding.right, currentY - tagHeight / 2, tagWidth, tagHeight);
  ctx.fillStyle = 'white';
  ctx.font = 'bold 11px JetBrains Mono';
  ctx.textAlign = 'center';
  ctx.fillText(`$${stock.currentPrice.toFixed(2)}`, width - padding.right + tagWidth / 2, currentY + 4);

  // Moving average line
  if (data.length >= 20) {
    ctx.beginPath();
    ctx.strokeStyle = 'rgba(59, 130, 246, 0.6)';
    ctx.lineWidth = 1.5;

    for (let i = 19; i < data.length; i++) {
      const slice = data.slice(i - 19, i + 1);
      const avg = slice.reduce((sum, d) => sum + d.close, 0) / 20;
      const x = padding.left + (i / (data.length - 1)) * chartWidth;
      const y = padding.top + ((maxPrice - avg) / priceRange) * chartHeight;

      if (i === 19) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

function updatePortfolio() {
  let portfolioValue = state.cash;
  Object.keys(state.holdings).forEach(symbol => {
    const holding = state.holdings[symbol];
    const stock = state.stocks[symbol];
    portfolioValue += holding.quantity * stock.currentPrice;
  });

  const totalChange = portfolioValue - state.initialCash;
  const totalChangePercent = (totalChange / state.initialCash) * 100;
  const isPositive = totalChange >= 0;

  document.getElementById('portfolioTotal').textContent = `$${portfolioValue.toFixed(2)}`;
  const changeEl = document.getElementById('portfolioChange');
  changeEl.textContent = `${isPositive ? '+' : ''}$${totalChange.toFixed(2)} (${isPositive ? '+' : ''}${totalChangePercent.toFixed(2)}%)`;
  changeEl.className = `portfolio-total-change ${isPositive ? 'positive' : 'negative'}`;
}

function updateHoldings() {
  const container = document.getElementById('holdingsList');
  const symbols = Object.keys(state.holdings);

  if (symbols.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-muted);font-size:13px;">No holdings yet. Start trading!</div>';
    return;
  }

  container.innerHTML = symbols.map(symbol => {
    const holding = state.holdings[symbol];
    const stock = state.stocks[symbol];
    const marketValue = holding.quantity * stock.currentPrice;
    const costBasis = holding.quantity * holding.avgPrice;
    const pnl = marketValue - costBasis;
    const pnlPercent = (pnl / costBasis) * 100;
    const isPositive = pnl >= 0;

    const colors = {
      'AAPL': '#555', 'GOOGL': '#4285f4', 'MSFT': '#00a4ef', 'AMZN': '#ff9900',
      'TSLA': '#cc0000', 'NVDA': '#76b900', 'META': '#0668E1', 'JPM': '#1a5276',
      'V': '#1a1f71', 'JNJ': '#d52b1e', 'WMT': '#0071ce', 'DIS': '#113ccf'
    };

    return `
      <div class="holding-item">
        <div class="holding-icon" style="background:${colors[symbol] || '#3b82f6'}">${symbol.slice(0, 2)}</div>
        <div class="holding-info">
          <span class="holding-symbol">${symbol}</span>
          <span class="holding-details">${holding.quantity} shares · Avg $${holding.avgPrice.toFixed(2)}</span>
        </div>
        <div class="holding-pnl">
          <div class="holding-pnl-value" style="color:${isPositive ? 'var(--accent-green)' : 'var(--accent-red)'}">
            ${isPositive ? '+' : ''}$${pnl.toFixed(2)}
          </div>
          <div class="holding-pnl-percent" style="color:${isPositive ? 'var(--accent-green)' : 'var(--accent-red)'}">
            ${isPositive ? '+' : ''}${pnlPercent.toFixed(2)}%
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function updateSummary() {
  const stock = state.stocks[state.selectedStock];
  const qty = parseInt(document.getElementById('qtyInput').value) || 0;
  const total = qty * stock.currentPrice;

  document.getElementById('summaryPrice').textContent = `$${stock.currentPrice.toFixed(2)}`;
  document.getElementById('summaryQty').textContent = qty;
  document.getElementById('summaryTotal').textContent = `$${total.toFixed(2)}`;

  const maxQty = Math.floor(state.cash / stock.currentPrice);
  document.getElementById('maxQty').textContent = `Max: ${maxQty}`;
}

function updateHeaderStats() {
  let portfolioValue = state.cash;
  Object.keys(state.holdings).forEach(symbol => {
    portfolioValue += state.holdings[symbol].quantity * state.stocks[symbol].currentPrice;
  });

  document.getElementById('headerPortfolioValue').textContent = `$${portfolioValue.toFixed(2)}`;
  document.getElementById('headerBuyingPower').textContent = `$${state.cash.toFixed(2)}`;

  const dayPnl = portfolioValue - state.initialCash;
  const isPositive = dayPnl >= 0;
  const pnlEl = document.getElementById('headerDayPnl');
  pnlEl.textContent = `${isPositive ? '+' : ''}$${dayPnl.toFixed(2)}`;
  pnlEl.className = `header-stat-value ${isPositive ? 'positive' : 'negative'}`;
}

// ==================== INTERACTIONS ====================
function selectStock(symbol) {
  state.selectedStock = symbol;
  updateUI();
}

function setTradeType(type) {
  state.tradeType = type;
  document.getElementById('buyBtn').className = `trade-type-btn buy ${type === 'buy' ? 'active' : ''}`;
  document.getElementById('sellBtn').className = `trade-type-btn sell ${type === 'sell' ? 'active' : ''}`;

  const submitBtn = document.getElementById('submitBtn');
  const stock = state.stocks[state.selectedStock];

  if (type === 'buy') {
    submitBtn.className = 'submit-btn buy-btn';
    submitBtn.textContent = `Buy ${stock.symbol}`;
  } else {
    submitBtn.className = 'submit-btn sell-btn';
    submitBtn.textContent = `Sell ${stock.symbol}`;
  }
}

function setQty(qty) {
  document.getElementById('qtyInput').value = qty;
  updateSummary();
}

function submitOrder() {
  const stock = state.stocks[state.selectedStock];
  const qty = parseInt(document.getElementById('qtyInput').value);
  const orderType = document.getElementById('orderType').value;
  const total = qty * stock.currentPrice;

  if (!qty || qty <= 0) {
    showNotification('Error', 'Please enter a valid quantity', 'error');
    return;
  }

  if (state.tradeType === 'buy' && total > state.cash) {
    showNotification('Insufficient Funds', `You need $${total.toFixed(2)} but only have $${state.cash.toFixed(2)}`, 'error');
    return;
  }

  if (state.tradeType === 'sell') {
    const holding = state.holdings[state.selectedStock];
    if (!holding || holding.quantity < qty) {
      showNotification('Insufficient Shares', `You only have ${holding ? holding.quantity : 0} shares of ${state.selectedStock}`, 'error');
      return;
    }
  }

  // Show confirmation modal
  document.getElementById('modalTitle').textContent = `Confirm ${state.tradeType.toUpperCase()} Order`;
  document.getElementById('modalMessage').textContent =
    `Are you sure you want to ${state.tradeType} ${qty} shares of ${stock.symbol} at $${stock.currentPrice.toFixed(2)}? Total: $${total.toFixed(2)}`;
  document.getElementById('confirmModal').classList.add('show');
}

function confirmOrder() {
  const stock = state.stocks[state.selectedStock];
  const qty = parseInt(document.getElementById('qtyInput').value);
  const total = qty * stock.currentPrice;

  if (state.tradeType === 'buy') {
    state.cash -= total;

    if (!state.holdings[state.selectedStock]) {
      state.holdings[state.selectedStock] = { quantity: 0, avgPrice: 0 };
    }

    const holding = state.holdings[state.selectedStock];
    const totalCost = holding.avgPrice * holding.quantity + total;
    holding.quantity += qty;
    holding.avgPrice = totalCost / holding.quantity;

    showNotification('Order Filled', `Bought ${qty} ${stock.symbol} at $${stock.currentPrice.toFixed(2)}`, 'success');
  } else {
    state.cash += total;

    const holding = state.holdings[state.selectedStock];
    holding.quantity -= qty;

    if (holding.quantity === 0) {
      delete state.holdings[state.selectedStock];
    }

    showNotification('Order Filled', `Sold ${qty} ${stock.symbol} at $${stock.currentPrice.toFixed(2)}`, 'success');
  }

  // Add to trade history
  state.trades.unshift({
    type: state.tradeType,
    symbol: stock.symbol,
    quantity: qty,
    price: stock.currentPrice,
    total: total,
    time: new Date(),
  });

  updateTradeHistory();
  closeModal();
  updateUI();
}

function updateTradeHistory() {
  const container = document.getElementById('historyList');
  const recent = state.trades.slice(0, 10);

  if (recent.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-muted);font-size:13px;">No trades yet</div>';
    return;
  }

  container.innerHTML = recent.map(trade => {
    const timeStr = trade.time.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    return `
      <div class="history-item">
        <div class="history-type ${trade.type}">${trade.type === 'buy' ? 'B' : 'S'}</div>
        <div class="history-details">
          <span class="history-symbol">${trade.symbol}</span>
          <span class="history-time">${timeStr} · ${trade.quantity} shares</span>
        </div>
        <div class="history-amount" style="color:${trade.type === 'buy' ? 'var(--accent-green)' : 'var(--accent-red)'}">
          ${trade.type === 'buy' ? '-' : '+'}$${trade.total.toFixed(2)}
        </div>
      </div>
    `;
  }).join('');
}

function showNotification(title, message, type) {
  const notif = document.getElementById('notification');
  const icon = document.getElementById('notifIcon');

  document.getElementById('notifTitle').textContent = title;
  document.getElementById('notifMessage').textContent = message;

  icon.className = `notification-icon ${type}`;
  icon.textContent = type === 'success' ? '✓' : '✕';

  notif.classList.add('show');
  setTimeout(() => notif.classList.remove('show'), 3000);
}

function closeModal() {
  document.getElementById('confirmModal').classList.remove('show');
}

function formatVolume(vol) {
  if (vol >= 1000000) return (vol / 1000000).toFixed(1) + 'M';
  if (vol >= 1000) return (vol / 1000).toFixed(1) + 'K';
  return vol.toString();
}

// ==================== EVENT LISTENERS ====================
document.getElementById('qtyInput').addEventListener('input', updateSummary);

document.getElementById('orderType').addEventListener('change', function() {
  document.getElementById('limitPriceGroup').style.display = this.value === 'limit' ? 'block' : 'none';
});

document.getElementById('searchInput').addEventListener('input', updateWatchlist);

document.querySelectorAll('.tf-btn').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.tf-btn').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
    // Regenerate chart data for different timeframes
    const tf = this.dataset.tf;
    const count = tf === 'D' ? 50 : tf === '1H' ? 80 : tf === '5' ? 100 : 120;
    generateChartData(state.selectedStock, count);
    updateChartHeader();
  });
});

// Update time
function updateTime() {
  const now = new Date();
  document.getElementById('headerTime').textContent = now.toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  });
}

// ==================== INITIALIZATION ====================
function init() {
  updateUI();
  updateTradeHistory();
  updateTime();

  // Price update interval
  setInterval(updatePrices, 2000);

  // Time update
  setInterval(updateTime, 1000);

  // Redraw chart on resize
  window.addEventListener('resize', () => {
    drawMainChart();
  });
}

init();
</script>
