<!-- Status Bar -->
<div class="status-bar">
    <div class="status-indicator">
        <div class="status-dot" id="statusDot"></div>
        <span id="statusText">Ready</span>
    </div>
    <div>
        <span id="fpsCounter">30 FPS</span> | 
        <span id="charCount">0 Characters</span> | 
        <span id="sceneCount">1 Scene</span>
    </div>
</div>

<script>
    // Global State
    let characters = [];
    let props = [];
    let subtitles = [];
    let currentScene = 0;
    let scenes = [{ name: 'Scene 1', bg: 'nature', desc: 'Nature background' }];
    let isPlaying = false;
    let isRecording = false;
    let animationId = null;
    let currentTime = 0;
    let totalTime = 60;
    let selectedColor = '#ff6b6b';
    let subtitleColor = '#fff';
    let mediaRecorder = null;
    let recordedChunks = [];
    let audioContext = null;
    let analyser = null;
    let waveAnimationId = null;
    let speechSynthesis = window.speechSynthesis;
    let voices = [];

    // Canvas Setup
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');

    // Initialize
    function init() {
        generateWaveBars();
        loadVoices();
        drawScene();
        updateStatus('Ready');

        // Load voices
        if (speechSynthesis.onvoiceschanged !== undefined) {
            speechSynthesis.onvoiceschanged = loadVoices;
        }
    }

    function loadVoices() {
        voices = speechSynthesis.getVoices();
        const voiceSelect = document.getElementById('voiceSelect');
        voiceSelect.innerHTML = '';
        voices.forEach((voice, index) => {
            const option = document.createElement('option');
            option.value = index;
            option.textContent = `${voice.name} (${voice.lang})`;
            voiceSelect.appendChild(option);
        });
    }

    function generateWaveBars() {
        const waveContainer = document.getElementById('voiceWave');
        waveContainer.innerHTML = '';
        for (let i = 0; i < 50; i++) {
            const bar = document.createElement('div');
            bar.className = 'wave-bar';
            bar.style.height = '10px';
            waveContainer.appendChild(bar);
        }
    }

    function animateWave() {
        const bars = document.querySelectorAll('.wave-bar');
        bars.forEach(bar => {
            const height = Math.random() * 50 + 10;
            bar.style.height = height + 'px';
        });
        waveAnimationId = requestAnimationFrame(animateWave);
    }

    function stopWaveAnimation() {
        if (waveAnimationId) {
            cancelAnimationFrame(waveAnimationId);
            waveAnimationId = null;
        }
        const bars = document.querySelectorAll('.wave-bar');
        bars.forEach(bar => {
            bar.style.height = '10px';
        });
    }

    // Character Management
    function addCharacter(type) {
        const char = {
            id: Date.now(),
            type: type,
            x: 100 + Math.random() * 400,
            y: 250 + Math.random() * 100,
            size: 1,
            animation: 'idle',
            color: selectedColor,
            name: type.charAt(0).toUpperCase() + type.slice(1),
            frame: 0,
            direction: 1
        };
        characters.push(char);
        updateCharCount();
        drawScene();
        showNotification(`${type.charAt(0).toUpperCase() + type.slice(1)} added to scene!`, 'success');
    }

    function drawCharacter(char) {
        ctx.save();
        ctx.translate(char.x, char.y);
        ctx.scale(char.size * char.direction, char.size);

        const frame = char.frame;
        const anim = char.animation;

        // Body
        ctx.fillStyle = char.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, 30, 40, 0, 0, Math.PI * 2);
        ctx.fill();

        // Head
        ctx.fillStyle = char.color;
        ctx.beginPath();
        ctx.arc(0, -50, 25, 0, Math.PI * 2);
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(-8, -55, 8, 0, Math.PI * 2);
        ctx.arc(8, -55, 8, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(-8, -55, 4, 0, Math.PI * 2);
        ctx.arc(8, -55, 4, 0, Math.PI * 2);
        ctx.fill();

        // Mouth
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 2;
        ctx.beginPath();
        if (anim === 'talk') {
            ctx.ellipse(0, -40, 5, 8, 0, 0, Math.PI * 2);
        } else {
            ctx.arc(0, -42, 8, 0, Math.PI);
        }
        ctx.stroke();

        // Arms
        ctx.strokeStyle = char.color;
        ctx.lineWidth = 8;
        ctx.lineCap = 'round';

        if (anim === 'wave') {
            // Left arm waving
            ctx.beginPath();
            ctx.moveTo(-30, -10);
            ctx.lineTo(-50, -30 + Math.sin(frame * 0.1) * 10);
            ctx.stroke();

            // Right arm
            ctx.beginPath();
            ctx.moveTo(30, -10);
            ctx.lineTo(50, 10);
            ctx.stroke();
        } else if (anim === 'dance') {
            // Dancing arms
            ctx.beginPath();
            ctx.moveTo(-30, -10);
            ctx.lineTo(-50, -30 + Math.sin(frame * 0.15) * 15);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(30, -10);
            ctx.lineTo(50, -30 - Math.sin(frame * 0.15) * 15);
            ctx.stroke();
        } else if (anim === 'walk' || anim === 'run') {
            // Walking arms
            const swing = Math.sin(frame * 0.1) * 20;
            ctx.beginPath();
            ctx.moveTo(-30, -10);
            ctx.lineTo(-40, 20 + swing);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(30, -10);
            ctx.lineTo(40, 20 - swing);
            ctx.stroke();
        } else {
            // Idle arms
            ctx.beginPath();
            ctx.moveTo(-30, -10);
            ctx.lineTo(-45, 20);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(30, -10);
            ctx.lineTo(45, 20);
            ctx.stroke();
        }

        // Legs
        if (anim === 'walk' || anim === 'run') {
            const legSwing = Math.sin(frame * 0.15) * 15;
            ctx.beginPath();
            ctx.moveTo(-15, 35);
            ctx.lineTo(-20 + legSwing, 65);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(15, 35);
            ctx.lineTo(20 - legSwing, 65);
            ctx.stroke();
        } else if (anim === 'jump') {
            // Jumping legs
            ctx.beginPath();
            ctx.moveTo(-15, 35);
            ctx.lineTo(-25, 55);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(15, 35);
            ctx.lineTo(25, 55);
            ctx.stroke();
        } else {
            // Idle legs
            ctx.beginPath();
            ctx.moveTo(-15, 35);
            ctx.lineTo(-20, 65);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(15, 35);
            ctx.lineTo(20, 65);
            ctx.stroke();
        }

        // Type-specific features
        if (char.type === 'robot') {
            // Robot antenna
            ctx.strokeStyle = '#888';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(0, -75);
            ctx.lineTo(0, -90);
            ctx.stroke();

            ctx.fillStyle = '#ff0';
            ctx.beginPath();
            ctx.arc(0, -90, 5, 0, Math.PI * 2);
            ctx.fill();

            // Robot eyes (glowing)
            ctx.fillStyle = '#0ff';
            ctx.beginPath();
            ctx.arc(-8, -55, 5, 0, Math.PI * 2);
            ctx.arc(8, -55, 5, 0, Math.PI * 2);
            ctx.fill();
        } else if (char.type === 'alien') {
            // Alien big eyes
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.ellipse(-10, -55, 10, 12, 0, 0, Math.PI * 2);
            ctx.ellipse(10, -55, 10, 12, 0, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = '#0f0';
            ctx.beginPath();
            ctx.arc(-10, -55, 5, 0, Math.PI * 2);
            ctx.arc(10, -55, 5, 0, Math.PI * 2);
            ctx.fill();
        } else if (char.type === 'dragon') {
            // Dragon wings
            ctx.fillStyle = char.color;
            ctx.beginPath();
            ctx.moveTo(-30, -20);
            ctx.lineTo(-60, -50);
            ctx.lineTo(-40, -10);
            ctx.fill();

            ctx.beginPath();
            ctx.moveTo(30, -20);
            ctx.lineTo(60, -50);
            ctx.lineTo(40, -10);
            ctx.fill();
        } else if (char.type === 'wizard') {
            // Wizard hat
            ctx.fillStyle = '#4a0080';
            ctx.beginPath();
            ctx.moveTo(-20, -70);
            ctx.lineTo(0, -110);
            ctx.lineTo(20, -70);
            ctx.fill();

            ctx.beginPath();
            ctx.ellipse(0, -70, 25, 8, 0, 0, Math.PI * 2);
            ctx.fill();
        } else if (char.type === 'princess') {
            // Crown
            ctx.fillStyle = '#feca57';
            ctx.beginPath();
            ctx.moveTo(-15, -75);
            ctx.lineTo(-10, -85);
            ctx.lineTo(-5, -75);
            ctx.lineTo(0, -85);
            ctx.lineTo(5, -75);
            ctx.lineTo(10, -85);
            ctx.lineTo(15, -75);
            ctx.fill();
        } else if (char.type === 'superhero') {
            // Cape
            ctx.fillStyle = '#ff0000';
            ctx.beginPath();
            ctx.moveTo(-25, -20);
            ctx.lineTo(-35, 40);
            ctx.lineTo(35, 40);
            ctx.lineTo(25, -20);
            ctx.fill();
        }

        ctx.restore();
    }

    function drawProp(prop) {
        ctx.save();
        ctx.translate(prop.x, prop.y);

        switch(prop.type) {
            case 'tree':
                // Trunk
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(-10, 0, 20, 60);
                // Leaves
                ctx.fillStyle = '#228B22';
                ctx.beginPath();
                ctx.arc(0, -20, 35, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = '#32CD32';
                ctx.beginPath();
                ctx.arc(-15, -10, 25, 0, Math.PI * 2);
                ctx.fill();
                ctx.beginPath();
                ctx.arc(15, -10, 25, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'house':
                // Walls
                ctx.fillStyle = '#FFB6C1';
                ctx.fillRect(-40, -30, 80, 60);
                // Roof
                ctx.fillStyle = '#FF6347';
                ctx.beginPath();
                ctx.moveTo(-50, -30);
                ctx.lineTo(0, -70);
                ctx.lineTo(50, -30);
                ctx.fill();
                // Door
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(-10, 0, 20, 30);
                // Window
                ctx.fillStyle = '#87CEEB';
                ctx.fillRect(-30, -15, 15, 15);
                ctx.fillRect(15, -15, 15, 15);
                break;

            case 'cloud':
                ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.beginPath();
                ctx.arc(0, 0, 30, 0, Math.PI * 2);
                ctx.arc(30, -10, 25, 0, Math.PI * 2);
                ctx.arc(-30, -10, 25, 0, Math.PI * 2);
                ctx.arc(15, -20, 20, 0, Math.PI * 2);
                ctx.arc(-15, -20, 20, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'sun':
                ctx.fillStyle = '#FFD700';
                ctx.beginPath();
                ctx.arc(0, 0, 30, 0, Math.PI * 2);
                ctx.fill();
                // Rays
                ctx.strokeStyle = '#FFD700';
                ctx.lineWidth = 3;
                for (let i = 0; i < 12; i++) {
                    const angle = (i * 30) * Math.PI / 180;
                    ctx.beginPath();
                    ctx.moveTo(Math.cos(angle) * 35, Math.sin(angle) * 35);
                    ctx.lineTo(Math.cos(angle) * 50, Math.sin(angle) * 50);
                    ctx.stroke();
                }
                break;

            case 'moon':
                ctx.fillStyle = '#F5F5DC';
                ctx.beginPath();
                ctx.arc(0, 0, 25, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = '#E8E8E8';
                ctx.beginPath();
                ctx.arc(8, -5, 20, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'star':
                ctx.fillStyle = '#FFD700';
                drawStar(0, 0, 5, 20, 10);
                break;

            case 'flower':
                // Stem
                ctx.strokeStyle = '#228B22';
                ctx.lineWidth = 3;
                ctx.beginPath();
                ctx.moveTo(0, 0);
                ctx.lineTo(0, -30);
                ctx.stroke();
                // Petals
                ctx.fillStyle = '#FF69B4';
                for (let i = 0; i < 5; i++) {
                    const angle = (i * 72) * Math.PI / 180;
                    ctx.beginPath();
                    ctx.arc(Math.cos(angle) * 10, -30 + Math.sin(angle) * 10, 8, 0, Math.PI * 2);
                    ctx.fill();
                }
                // Center
                ctx.fillStyle = '#FFD700';
                ctx.beginPath();
                ctx.arc(0, -30, 5, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'car':
                // Body
                ctx.fillStyle = '#ff0000';
                ctx.fillRect(-40, -10, 80, 30);
                // Top
                ctx.fillStyle = '#cc0000';
                ctx.beginPath();
                ctx.moveTo(-20, -10);
                ctx.lineTo(-10, -30);
                ctx.lineTo(20, -30);
                ctx.lineTo(30, -10);
                ctx.fill();
                // Wheels
                ctx.fillStyle = '#333';
                ctx.beginPath();
                ctx.arc(-25, 20, 10, 0, Math.PI * 2);
                ctx.arc(25, 20, 10, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'bird':
                // Body
                ctx.fillStyle = '#4169E1';
                ctx.beginPath();
                ctx.ellipse(0, 0, 15, 10, 0, 0, Math.PI * 2);
                ctx.fill();
                // Wings
                ctx.fillStyle = '#1E90FF';
                const wingFlap = Math.sin(Date.now() * 0.01) * 10;
                ctx.beginPath();
                ctx.moveTo(-10, -5);
                ctx.lineTo(-25, -20 + wingFlap);
                ctx.lineTo(-5, -5);
                ctx.fill();
                ctx.beginPath();
                ctx.moveTo(10, -5);
                ctx.lineTo(25, -20 + wingFlap);
                ctx.lineTo(5, -5);
                ctx.fill();
                // Beak
                ctx.fillStyle = '#FFA500';
                ctx.beginPath();
                ctx.moveTo(15, -2);
                ctx.lineTo(25, 0);
                ctx.lineTo(15, 2);
                ctx.fill();
                break;

            case 'butterfly':
                const wingAngle = Math.sin(Date.now() * 0.005) * 0.3;
                // Left wing
                ctx.fillStyle = '#FF69B4';
                ctx.save();
                ctx.rotate(-wingAngle);
                ctx.beginPath();
                ctx.ellipse(-15, 0, 15, 10, -0.3, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
                // Right wing
                ctx.save();
                ctx.rotate(wingAngle);
                ctx.beginPath();
                ctx.ellipse(15, 0, 15, 10, 0.3, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
                // Body
                ctx.fillStyle = '#333';
                ctx.beginPath();
                ctx.ellipse(0, 0, 3, 10, 0, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'rainbow':
                const colors = ['#ff0000', '#ff7700', '#ffff00', '#00ff00', '#0000ff', '#4b0082', '#9400d3'];
                colors.forEach((color, i) => {
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 5;
                    ctx.beginPath();
                    ctx.arc(0, 50, 60 + i * 8, Math.PI, 0);
                    ctx.stroke();
                });
                break;

            case 'mountain':
                ctx.fillStyle = '#696969';
                ctx.beginPath();
                ctx.moveTo(-60, 0);
                ctx.lineTo(0, -80);
                ctx.lineTo(60, 0);
                ctx.fill();
                // Snow cap
                ctx.fillStyle = '#fff';
                ctx.beginPath();
                ctx.moveTo(-15, -55);
                ctx.lineTo(0, -80);
                ctx.lineTo(15, -55);
                ctx.fill();
                break;

            case 'rock':
                ctx.fillStyle = '#808080';
                ctx.beginPath();
                ctx.moveTo(-20, 0);
                ctx.lineTo(-15, -25);
                ctx.lineTo(5, -30);
                ctx.lineTo(20, -20);
                ctx.lineTo(15, 0);
                ctx.fill();
                break;

            case 'book':
                ctx.fillStyle = '#8B0000';
                ctx.fillRect(-20, -25, 40, 30);
                ctx.fillStyle = '#fff';
                ctx.fillRect(-18, -23, 36, 26);
                ctx.fillStyle = '#333';
                ctx.font = '10px Arial';
                ctx.fillText('Book', -10, -8);
                break;

            case 'sword':
                ctx.fillStyle = '#C0C0C0';
                ctx.fillRect(-3, -40, 6, 40);
                ctx.fillStyle = '#FFD700';
                ctx.fillRect(-10, -5, 20, 5);
                ctx.fillRect(-3, 0, 6, 15);
                ctx.fillStyle = '#8B4513';
                ctx.beginPath();
                ctx.arc(0, 15, 5, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'crown':
                ctx.fillStyle = '#FFD700';
                ctx.beginPath();
                ctx.moveTo(-25, 0);
                ctx.lineTo(-20, -20);
                ctx.lineTo(-10, -10);
                ctx.lineTo(0, -25);
                ctx.lineTo(10, -10);
                ctx.lineTo(20, -20);
                ctx.lineTo(25, 0);
                ctx.fill();
                // Gems
                ctx.fillStyle = '#ff0000';
                ctx.beginPath();
                ctx.arc(0, -5, 3, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = '#0000ff';
                ctx.beginPath();
                ctx.arc(-12, -5, 2, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = '#00ff00';
                ctx.beginPath();
                ctx.arc(12, -5, 2, 0, Math.PI * 2);
                ctx.fill();
                break;
        }

        ctx.restore();
    }

    function drawStar(cx, cy, spikes, outerRadius, innerRadius) {
        let rot = Math.PI / 2 * 3;
        let x = cx;
        let y = cy;
        let step = Math.PI / spikes;

        ctx.beginPath();
        ctx.moveTo(cx, cy - outerRadius);
        for (let i = 0; i < spikes; i++) {
            x = cx + Math.cos(rot) * outerRadius;
            y = cy + Math.sin(rot) * outerRadius;
            ctx.lineTo(x, y);
            rot += step;

            x = cx + Math.cos(rot) * innerRadius;
            y = cy + Math.sin(rot) * innerRadius;
            ctx.lineTo(x, y);
            rot += step;
        }
        ctx.lineTo(cx, cy - outerRadius);
        ctx.closePath();
        ctx.fill();
    }

    function drawBackground(bgType) {
        switch(bgType) {
            case 'nature':
                // Sky
                const skyGrad = ctx.createLinearGradient(0, 0, 0, 300);
                skyGrad.addColorStop(0, '#87CEEB');
                skyGrad.addColorStop(1, '#E0F7FA');
                ctx.fillStyle = skyGrad;
                ctx.fillRect(0, 0, 800, 300);
                // Grass
                const grassGrad = ctx.createLinearGradient(0, 300, 0, 450);
                grassGrad.addColorStop(0, '#98FB98');
                grassGrad.addColorStop(1, '#228B22');
                ctx.fillStyle = grassGrad;
                ctx.fillRect(0, 300, 800, 150);
                // Sun
                ctx.fillStyle = '#FFD700';
                ctx.beginPath();
                ctx.arc(700, 80, 40, 0, Math.PI * 2);
                ctx.fill();
                // Clouds
                ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.beginPath();
                ctx.arc(150, 100, 30, 0, Math.PI * 2);
                ctx.arc(180, 90, 25, 0, Math.PI * 2);
                ctx.arc(120, 90, 25, 0, Math.PI * 2);
                ctx.fill();
                ctx.beginPath();
                ctx.arc(400, 120, 25, 0, Math.PI * 2);
                ctx.arc(430, 110, 20, 0, Math.PI * 2);
                ctx.arc(370, 110, 20, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'night':
                const nightGrad = ctx.createLinearGradient(0, 0, 0, 450);
                nightGrad.addColorStop(0, '#0a0a2e');
                nightGrad.addColorStop(1, '#1a1a3e');
                ctx.fillStyle = nightGrad;
                ctx.fillRect(0, 0, 800, 450);
                // Stars
                ctx.fillStyle = '#fff';
                for (let i = 0; i < 50; i++) {
                    const x = Math.random() * 800;
                    const y = Math.random() * 300;
                    const size = Math.random() * 2 + 1;
                    ctx.beginPath();
                    ctx.arc(x, y, size, 0, Math.PI * 2);
                    ctx.fill();
                }
                // Moon
                ctx.fillStyle = '#F5F5DC';
                ctx.beginPath();
                ctx.arc(650, 80, 35, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = '#0a0a2e';
                ctx.beginPath();
                ctx.arc(665, 75, 30, 0, Math.PI * 2);
                ctx.fill();
                // Ground
                ctx.fillStyle = '#1a3a1a';
                ctx.fillRect(0, 350, 800, 100);
                break;

            case 'sunset':
                const sunsetGrad = ctx.createLinearGradient(0, 0, 0, 450);
                sunsetGrad.addColorStop(0, '#ff6b6b');
                sunsetGrad.addColorStop(0.5, '#feca57');
                sunsetGrad.addColorStop(1, '#ff9ff3');
                ctx.fillStyle = sunsetGrad;
                ctx.fillRect(0, 0, 800, 450);
                // Sun setting
                ctx.fillStyle = '#FF4500';
                ctx.beginPath();
                ctx.arc(400, 250, 50, 0, Math.PI * 2);
                ctx.fill();
                // Water reflection
                ctx.fillStyle = 'rgba(255, 69, 0, 0.3)';
                ctx.fillRect(300, 300, 200, 150);
                break;

            case 'sky':
                const skyGrad2 = ctx.createLinearGradient(0, 0, 0, 450);
                skyGrad2.addColorStop(0, '#74b9ff');
                skyGrad2.addColorStop(1, '#a29bfe');
                ctx.fillStyle = skyGrad2;
                ctx.fillRect(0, 0, 800, 450);
                // Clouds
                ctx.fillStyle = 'rgba(255,255,255,0.6)';
                for (let i = 0; i < 5; i++) {
                    const x = (i * 200 + Date.now() * 0.01) % 900 - 50;
                    ctx.beginPath();
                    ctx.arc(x, 100 + i * 30, 30, 0, Math.PI * 2);
                    ctx.arc(x + 30, 90 + i * 30, 25, 0, Math.PI * 2);
                    ctx.arc(x - 30, 90 + i * 30, 25, 0, Math.PI * 2);
                    ctx.fill();
                }
                break;

            case 'city':
                const cityGrad = ctx.createLinearGradient(0, 0, 0, 450);
                cityGrad.addColorStop(0, '#2d3436');
                cityGrad.addColorStop(1, '#636e72');
                ctx.fillStyle = cityGrad;
                ctx.fillRect(0, 0, 800, 450);
                // Buildings
                const buildingColors = ['#4a4a4a', '#5a5a5a', '#3a3a3a', '#6a6a6a'];
                for (let i = 0; i < 10; i++) {
                    const x = i * 80;
                    const h = 100 + Math.random() * 150;
                    ctx.fillStyle = buildingColors[i % buildingColors.length];
                    ctx.fillRect(x, 450 - h, 70, h);
                    // Windows
                    ctx.fillStyle = '#FFD700';
                    for (let j = 0; j < Math.floor(h / 30); j++) {
                        for (let k = 0; k < 2; k++) {
                            if (Math.random() > 0.3) {
                                ctx.fillRect(x + 10 + k * 30, 450 - h + 15 + j * 30, 15, 20);
                            }
                        }
                    }
                }
                break;

            case 'ocean':
                const oceanGrad = ctx.createLinearGradient(0, 0, 0, 450);
                oceanGrad.addColorStop(0, '#74b9ff');
                oceanGrad.addColorStop(0.5, '#0984e3');
                oceanGrad.addColorStop(1, '#00b894');
                ctx.fillStyle = oceanGrad;
                ctx.fillRect(0, 0, 800, 450);
                // Waves
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 2;
                for (let i = 0; i < 5; i++) {
                    ctx.beginPath();
                    for (let x = 0; x < 800; x += 10) {
                        const y = 200 + i * 50 + Math.sin(x * 0.02 + Date.now() * 0.001 + i) * 10;
                        if (x === 0) ctx.moveTo(x, y);
                        else ctx.lineTo(x, y);
                    }
                    ctx.stroke();
                }
                break;
        }
    }

    function drawScene() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const bgType = scenes[currentScene]?.bg || 'nature';
        drawBackground(bgType);

        // Draw props
        props.forEach(prop => drawProp(prop));

        // Draw characters
        characters.forEach(char => drawCharacter(char));

        // Draw subtitles
        subtitles.forEach(sub => {
            ctx.fillStyle = 'rgba(0,0,0,0.7)';
            ctx.fillRect(100, 380, 600, 40);
            ctx.fillStyle = sub.color || '#fff';
            ctx.font = `${sub.size || 18}px Arial`;
            ctx.textAlign = 'center';
            ctx.fillText(sub.text, 400, 405);
        });
    }

    function animateScene() {
        if (!isPlaying) return;

        currentTime += 0.016;
        if (currentTime > totalTime) {
            currentTime = 0;
        }

        // Update characters animation
        characters.forEach(char => {
            char.frame++;

            if (char.animation === 'walk' || char.animation === 'run') {
                char.x += char.direction * (char.animation === 'run' ? 3 : 1.5);
                if (char.x > 750 || char.x < 50) {
                    char.direction *= -1;
                }
            }

            if (char.animation === 'jump') {
                char.y -= 2;
                if (char.y < 200) {
                    char.animation = 'idle';
                }
            }
        });

        // Update timeline
        const progress = (currentTime / totalTime) * 100;
        document.getElementById('timelineProgress').style.width = progress + '%';
        document.getElementById('timelinePlayhead').style.left = progress + '%';

        drawScene();
        animationId = requestAnimationFrame(animateScene);
    }

    // Animation Controls
    function playAnimation() {
        if (!isPlaying) {
            isPlaying = true;
            animateScene();
            updateStatus('Playing...');
        }
    }

    function pauseAnimation() {
        isPlaying = false;
        if (animationId) {
            cancelAnimationFrame(animationId);
        }
        updateStatus('Paused');
    }

    function stopAnimation() {
        isPlaying = false;
        currentTime = 0;
        if (animationId) {
            cancelAnimationFrame(animationId);
        }
        document.getElementById('timelineProgress').style.width = '0%';
        document.getElementById('timelinePlayhead').style.left = '0%';
        drawScene();
        updateStatus('Stopped');
    }

    // Voice Recording
    function toggleRecording() {
        if (!isRecording) {
            startRecording();
        } else {
            stopRecording();
        }
    }

    async function startRecording() {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            mediaRecorder = new MediaRecorder(stream);
            recordedChunks = [];

            mediaRecorder.ondataavailable = (event) => {
                if (event.data.size > 0) {
                    recordedChunks.push(event.data);
                }
            };

            mediaRecorder.onstop = () => {
                const blob = new Blob(recordedChunks, { type: 'audio/webm' });
                console.log('Recording saved:', blob);
            };

            mediaRecorder.start();
            isRecording = true;
            document.getElementById('recordBtn').textContent = '⏹ Stop Recording';
            document.getElementById('recordBtn').classList.add('btn-recording');
            updateStatus('Recording...');
            animateWave();

            // Setup audio visualization
            audioContext = new (window.AudioContext || window.webkitAudioContext)();
            const source = audioContext.createMediaStreamSource(stream);
            analyser = audioContext.createAnalyser();
            analyser.fftSize = 256;
            source.connect(analyser);

        } catch (err) {
            showNotification('Microphone access denied!', 'error');
            console.error(err);
        }
    }

    function stopRecording() {
        if (mediaRecorder && mediaRecorder.state !== 'inactive') {
            mediaRecorder.stop();
        }
        isRecording = false;
        document.getElementById('recordBtn').textContent = '🎤 Start Recording';
        document.getElementById('recordBtn').classList.remove('btn-recording');
        updateStatus('Recording saved');
        stopWaveAnimation();
    }

    function playRecording() {
        if (recordedChunks.length > 0) {
            const blob = new Blob(recordedChunks, { type: 'audio/webm' });
            const url = URL.createObjectURL(blob);
            const audio = new Audio(url);
            audio.play();
            showNotification('Playing recording...', 'info');
        } else {
            showNotification('No recording found!', 'error');
        }
    }

    function clearRecording() {
        recordedChunks = [];
        if (mediaRecorder) {
            mediaRecorder = null;
        }
        showNotification('Recording cleared', 'info');
    }

    // Text-to-Speech
    function speakText() {
        const text = document.getElementById('ttsText').value;
        if (!text) {
            showNotification('Please enter some text!', 'error');
            return;
        }

        speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(text);

        const voiceIndex = document.getElementById('voiceSelect').value;
        if (voiceIndex !== '') {
            utterance.voice = voices[voiceIndex];
        }

        utterance.rate = 1;
        utterance.pitch = 1;
        utterance.volume = 1;

        speechSynthesis.speak(utterance);
        updateStatus('Speaking...');

        utterance.onend = () => {
            updateStatus('Ready');
        };
    }

    function stopSpeaking() {
        speechSynthesis.cancel();
        updateStatus('Ready');
    }

    // Prop Management
    function addProp(type) {
        const prop = {
            id: Date.now(),
            type: type,
            x: 100 + Math.random() * 500,
            y: 200 + Math.random() * 150
        };
        props.push(prop);
        drawScene();
        showNotification(`${type} added!`, 'success');
    }

    // Subtitle Management
    function addSubtitle() {
        const text = document.getElementById('subtitleText').value;
        if (!text) {
            showNotification('Please enter subtitle text!', 'error');
            return;
        }

        subtitles.push({
            text: text,
            size: document.getElementById('subtitleSize').value,
            color: subtitleColor
        });

        document.getElementById('subtitleText').value = '';
        drawScene();
        showNotification('Subtitle added!', 'success');
    }

    // Scene Management
    function addScene() {
        const name = document.getElementById('sceneName').value || `Scene ${scenes.length + 1}`;
        const desc = document.getElementById('sceneDesc').value || 'Custom scene';
        scenes.push({ name, bg: 'nature', desc });
        currentScene = scenes.length - 1;
        updateSceneList();
        drawScene();
        showNotification(`${name} added!`, 'success');
    }

    function updateSceneList() {
        const list = document.getElementById('sceneList');
        list.innerHTML = '';
        scenes.forEach((scene, index) => {
            const item = document.createElement('div');
            item.className = `scene-item ${index === currentScene ? 'active' : ''}`;
            item.onclick = () => {
                currentScene = index;
                updateSceneList();
                drawScene();
            };
            item.innerHTML = `
                <div class="scene-thumb">🎬</div>
                <div class="scene-info">
                    <div class="name">${scene.name}</div>
                    <div class="desc">${scene.desc}</div>
                </div>
                <div class="scene-actions">
                    <button onclick="event.stopPropagation(); deleteScene(this)">🗑️</button>
                </div>
            `;
            list.appendChild(item);
        });
        document.getElementById('sceneCount').textContent = `${scenes.length} Scene${scenes.length > 1 ? 's' : ''}`;
    }

    function deleteScene(btn) {
        const item = btn.closest('.scene-item');
        const index = Array.from(item.parentElement.children).indexOf(item);
        if (scenes.length > 1) {
            scenes.splice(index, 1);
            if (currentScene >= scenes.length) {
                currentScene = scenes.length - 1;
            }
            updateSceneList();
            drawScene();
            showNotification('Scene deleted!', 'info');
        }
    }

    // UI Helpers
    function switchTab(tabName) {
        document.querySelectorAll('.tab').forEach(tab => tab.classList.remove('active'));
        document.querySelectorAll('.tab-content').forEach(content => content.classList.remove('active'));

        event.target.classList.add('active');
        document.getElementById(`tab-${tabName}`).classList.add('active');
    }

    function selectColor(el, color) {
        document.querySelectorAll('.color-swatch').forEach(s => s.classList.remove('selected'));
        el.classList.add('selected');
        selectedColor = color;
    }

    function selectSubtitleColor(el, color) {
        document.querySelectorAll('.color-swatch').forEach(s => s.classList.remove('selected'));
        el.classList.add('selected');
        subtitleColor = color;
    }

    function selectBg(el, bgType) {
        document.querySelectorAll('.bg-option').forEach(opt => opt.classList.remove('selected'));
        el.classList.add('selected');
        scenes[currentScene].bg = bgType;
        drawScene();
    }

    function selectExportOption(el, option) {
        document.querySelectorAll('.export-option').forEach(opt => opt.classList.remove('selected'));
        el.classList.add('selected');
    }

    function updateCharAnimation() {
        const anim = document.getElementById('charAnimation').value;
        characters.forEach(char => {
            char.animation = anim;
        });
    }

    function updateCharSize() {
        const size = document.getElementById('charSize').value;
        characters.forEach(char => {
            char.size = parseFloat(size);
        });
        drawScene();
    }

    function updateCharCount() {
        document.getElementById('charCount').textContent = `${characters.length} Character${characters.length > 1 ? 's' : ''}`;
    }

    function updateStatus(text) {
        document.getElementById('statusText').textContent = text;
    }

    function showNotification(message, type = 'success') {
        const notif = document.createElement('div');
        notif.className = `notification ${type}`;
        notif.textContent = message;
        document.body.appendChild(notif);

        setTimeout(() => {
            notif.remove();
        }, 3000);
    }

    // Export Modal
    function showExportModal() {
        document.getElementById('exportModal').classList.add('active');
    }

    function closeExportModal() {
        document.getElementById('exportModal').classList.remove('active');
    }

    function exportVideo() {
        closeExportModal();

        const loadingOverlay = document.getElementById('loadingOverlay');
        const loadingText = document.getElementById('loadingText');
        const loadingProgress = document.getElementById('loadingProgress');

        loadingOverlay.classList.add('active');
        loadingText.textContent = 'Rendering Video...';
        loadingProgress.style.width = '0%';

        // Simulate rendering progress
        let progress = 0;
        const renderInterval = setInterval(() => {
            progress += 2;
            loadingProgress.style.width = progress + '%';

            if (progress >= 100) {
                clearInterval(renderInterval);
                loadingText.textContent = 'Video Exported Successfully!';

                // Create video from canvas
                setTimeout(() => {
                    loadingOverlay.classList.remove('active');

                    // Download canvas as image sequence or video
                    const link = document.createElement('a');
                    link.download = 'cartoon-video.webm';

                    // Try to capture canvas as video
                    try {
                        const stream = canvas.captureStream(30);
                        const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
                        const chunks = [];

                        recorder.ondataavailable = (e) => {
                            if (e.data.size > 0) chunks.push(e.data);
                        };

                        recorder.onstop = () => {
                            const blob = new Blob(chunks, { type: 'video/webm' });
                            const url = URL.createObjectURL(blob);
                            link.href = url;
                            link.click();
                            showNotification('Video downloaded successfully! 🎉', 'success');
                        };

                        recorder.start();

                        // Record for a few seconds
                        setTimeout(() => {
                            recorder.stop();
                        }, 3000);
                    } catch (err) {
                        // Fallback: download as image
                        link.href = canvas.toDataURL('image/png');
                        link.download = 'cartoon-scene.png';
                        link.click();
                        showNotification('Scene saved as image! (Video export requires browser support)', 'info');
                    }
                }, 1000);
            }
        }, 100);
    }

    function applySettings() {
        const resolution = document.getElementById('resolution').value;
        const fps = document.getElementById('fps').value;

        const [width, height] = resolution.split('x');
        canvas.width = parseInt(width);
        canvas.height = parseInt(height);

        document.getElementById('fpsCounter').textContent = `${fps} FPS`;
        showNotification('Settings applied! 🎬', 'success');
    }

    function loadBackgroundMusic() {
        const fileInput = document.getElementById('bgMusic');
        if (fileInput.files.length > 0) {
            showNotification('Background music loaded! 🎵', 'success');
        }
    }

    // Timeline interaction
    document.getElementById('timelineTrack').addEventListener('click', (e) => {
        const rect = e.target.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const percentage = x / rect.width;
        currentTime = percentage * totalTime;

        document.getElementById('timelineProgress').style.width = (percentage * 100) + '%';
        document.getElementById('timelinePlayhead').style.left = (percentage * 100) + '%';

        drawScene();
    });

    // Keyboard shortcuts
    document.addEventListener('keydown', (e) => {
        if (e.code === 'Space') {
            e.preventDefault();
            if (isPlaying) {
                pauseAnimation();
            } else {
                playAnimation();
            }
        }
        if (e.code === 'KeyR') {
            toggleRecording();
        }
        if (e.code === 'KeyS') {
            stopAnimation();
        }
    });

    // Initialize
    init();
</script>

