<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #0a0a1a; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; overflow: hidden; color: white; }
canvas { display: block; }
#gameContainer { position: relative; width: 100vw; height: 100vh; }
#menuScreen, #leagueScreen, #teamScreen, #matchScreen, #gameOverScreen {
    position: absolute; top: 0; left: 0; width: 100%; height: 100%;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    z-index: 10;
}
#menuScreen { background: linear-gradient(135deg, #000428, #004e92); }
#leagueScreen { background: linear-gradient(135deg, #0f0c29, #302b63, #24243e); display: none; }
#teamScreen { background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460); display: none; }
#matchScreen { background: transparent; display: none; }
#gameOverScreen { background: rgba(0,0,0,0.9); display: none; }

h1 { font-size: 3em; text-shadow: 0 0 20px rgba(255,255,0,0.5); margin-bottom: 20px; }
h2 { font-size: 2em; margin-bottom: 15px; color: #ffd700; }
h3 { font-size: 1.5em; margin-bottom: 10px; }

.btn {
    padding: 15px 40px; margin: 10px; font-size: 1.2em; border: 2px solid #ffd700;
    background: rgba(255,215,0,0.1); color: #ffd700; cursor: pointer;
    border-radius: 10px; transition: all 0.3s; font-weight: bold;
    text-transform: uppercase; letter-spacing: 2px;
}
.btn:hover { background: #ffd700; color: #000; transform: scale(1.05); }
.btn-small { padding: 8px 20px; font-size: 0.9em; }

.league-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; max-width: 800px; }
.league-card {
    background: rgba(255,255,255,0.1); border: 2px solid rgba(255,255,255,0.2);
    padding: 20px; border-radius: 15px; cursor: pointer; transition: all 0.3s;
    text-align: center;
}
.league-card:hover { border-color: #ffd700; background: rgba(255,215,0,0.2); transform: translateY(-5px); }
.league-card .flag { font-size: 2em; margin-bottom: 10px; }
.league-card .name { font-size: 1em; font-weight: bold; }

.team-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; max-width: 900px; max-height: 60vh; overflow-y: auto; }
.team-card {
    background: rgba(255,255,255,0.05); border: 2px solid rgba(255,255,255,0.1);
    padding: 15px; border-radius: 10px; cursor: pointer; transition: all 0.3s;
    text-align: center;
}
.team-card:hover { border-color: #00ff88; background: rgba(0,255,136,0.1); }
.team-card.selected { border-color: #ffd700; background: rgba(255,215,0,0.2); }
.team-card .crest { font-size: 2em; margin-bottom: 5px; }
.team-card .tname { font-size: 0.85em; font-weight: bold; }
.team-card .rating { font-size: 0.75em; color: #aaa; }

#hud {
    position: absolute; top: 10px; left: 50%; transform: translateX(-50%);
    display: flex; align-items: center; gap: 20px; background: rgba(0,0,0,0.8);
    padding: 10px 30px; border-radius: 30px; border: 1px solid rgba(255,255,255,0.2);
    z-index: 5;
}
.hud-team { display: flex; align-items: center; gap: 10px; font-size: 1.2em; font-weight: bold; }
.hud-score { font-size: 2em; color: #ffd700; font-weight: bold; }
.hud-time { font-size: 1.2em; color: #00ff88; }
.hud-possession { font-size: 0.8em; color: #aaa; }

#minimap {
    position: absolute; bottom: 10px; right: 10px; width: 200px; height: 120px;
    background: rgba(0,100,0,0.8); border: 2px solid rgba(255,255,255,0.3);
    border-radius: 10px; z-index: 5;
}

#commentary {
    position: absolute; bottom: 60px; left: 50%; transform: translateX(-50%);
    background: rgba(0,0,0,0.8); padding: 10px 25px; border-radius: 20px;
    font-size: 1em; z-index: 5; white-space: nowrap;
}

#controls {
    position: absolute; bottom: 10px; left: 10px; background: rgba(0,0,0,0.7);
    padding: 10px; border-radius: 10px; font-size: 0.75em; z-index: 5;
    line-height: 1.6;
}

.goal-animation {
    position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
    font-size: 4em; font-weight: bold; color: #ffd700; text-shadow: 0 0 30px rgba(255,215,0,0.8);
    animation: goalPop 2s ease-out forwards; z-index: 20;
}
@keyframes goalPop {
    0% { transform: translate(-50%, -50%) scale(0); opacity: 0; }
    50% { transform: translate(-50%, -50%) scale(1.5); opacity: 1; }
    100% { transform: translate(-50%, -50%) scale(2); opacity: 0; }
}

.scoreboard {
    position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
    background: rgba(0,0,0,0.9); padding: 30px 50px; border-radius: 20px;
    border: 2px solid #ffd700; text-align: center; z-index: 20;
}
.scoreboard h2 { font-size: 2.5em; margin-bottom: 10px; }
.scoreboard .final-score { font-size: 4em; color: #ffd700; margin: 20px 0; }

.particles { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 15; }
</style>
</head>
<body>
<div id="gameContainer">
    <canvas id="gameCanvas"></canvas>

    <!-- Main Menu -->
    <div id="menuScreen">
        <h1>⚽ PERSIB BANDUNG ⚽</h1>
