    </div>

    <!-- Team Selection -->
    <div id="teamScreen">
        <h2>👥 PILIH TIM</h2>
        <p id="leagueLabel" style="color: #ffd700; margin-bottom: 15px;"></p>
        <div class="team-grid" id="teamGrid"></div>
