        <button class="btn btn-small" onclick="showLeagueScreen()">← KEMBALI</button>
    </div>

    <!-- Match Screen -->
    <div id="matchScreen">
        <div id="hud">
            <div class="hud-team">
                <span id="hudHomeName">PERSIB</span>
                <span id="homeCrest">🔵</span>
            </div>
            <div class="hud-score">
                <span id="homeScore">0</span> - <span id="awayScore">0</span>
            </div>
            <div class="hud-team">
                <span id="awayCrest">🔴</span>
                <span id="awayName">OPPONENT</span>
            </div>
            <div class="hud-time" id="matchTime">00:00</div>
        </div>
        <div id="commentary">Match dimulai! 🏟️</div>
        <div id="controls">
            <strong>CONTROLS:</strong><br>
            ↑↓←→ : Gerak<br>
            SPACE : Tendang/Shoot<br>
            S : Pass<br>
            D : Tackle<br>
            W : Sprint<br>
            ESC : Pause
        </div>
        <canvas id="minimap"></canvas>
    </div>

    <!-- Game Over -->
    <div id="gameOverScreen">
        <div class="scoreboard">
            <h2>🏁 FULL TIME 🏁</h2>
            <div class="final-score">
                <span id="finalHome">0</span> - <span id="finalAway">0</span>
            </div>
            <p id="matchResult" style="font-size: 1.2em; margin-bottom: 20px;"></p>
            <button class="btn" onclick="showMenu()">🏠 MENU UTAMA</button>
            <button class="btn" onclick="restartMatch()">🔄 MAIN LAGI</button>
        </div>
    </div>
</div>

