  <div class="info">
    🟢 Player 1: Tap LEFT/RIGHT buttons<br>
    🔵 Player 2: Tap UP/DOWN buttons<br>
    🏆 First to finish wins!
  </div>
  <button id="start-btn">START RACE</button>
</div>

<div id="finish-screen">
  <h1 id="winner-text">Player 1 Wins!</h1>
  <p id="win-time">Time: 0.0s</p>
  <button id="restart-btn">RACE AGAIN</button>
</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const timerEl = document.getElementById('timer');
const countdownEl = document.getElementById('countdown');
const startScreen = document.getElementById('start-screen');
const finishScreen = document.getElementById('finish-screen');
const winnerText = document.getElementById('winner-text');
const winTime = document.getElementById('win-time');

let W, H;
function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
resize();
window.addEventListener('resize', resize);

// Game state
let gameState = 'menu'; // menu, countdown, racing, finished
let raceTime = 0;
let finishOrder = [];
let terrain = [];
let terrainLength = 8000;
let cameraX = 0;
let particles = [];

// Physics constants
const GRAVITY = 0.4;
const FRICTION = 0.98;
const TERRAIN_SEGMENTS = 400;

// Vehicle class
class Vehicle {
  constructor(x, color, name, controls) {
    this.x = x;
    this.y = 0;
    this.vx = 0;
    this.vy = 0;
    this.angle = 0;
    this.angularVel = 0;
    this.color = color;
    this.name = name;
    this.controls = controls;
    this.wheelRadius = 18;
    this.width = 60;
    this.height = 30;
    this.onGround = false;
    this.finished = false;
    this.finishTime = 0;
    this.fuel = 100;
    this.maxFuel = 100;
    this.enginePower = 0.3;
    this.brakePower = 0.2;
    this.wheelAngle = 0;
    this.suspension = 0;
    this.flipCount = 0;
    this.lastAngle = 0;
    this.trail = [];
  }

  getTerrainY(x) {
    let idx = Math.floor(x / (terrainLength / TERRAIN_SEGMENTS));
    idx = Math.max(0, Math.min(TERRAIN_SEGMENTS - 1, idx));
    let nextIdx = Math.min(idx + 1, TERRAIN_SEGMENTS - 1);
    let t = (x / (terrainLength / TERRAIN_SEGMENTS)) - idx;
    return terrain[idx] * (1 - t) + terrain[nextIdx] * t;
  }

  getTerrainAngle(x) {
    let dy = this.getTerrainY(x + 5) - this.getTerrainY(x - 5);
    return Math.atan2(dy, 10);
  }

  update() {
    if (this.finished) return;

    // Get terrain info
    let terrainY = this.getTerrainY(this.x);
    let terrainAngle = this.getTerrainAngle(this.x);

    // Check if on ground
    let wheelBottom = this.y + this.height / 2 + this.wheelRadius;
    this.onGround = wheelBottom >= terrainY;

    if (this.onGround) {
      // Suspension
      let penetration = wheelBottom - terrainY;
      this.suspension = penetration;

      // Apply terrain normal force
      this.vy -= penetration * 0.3;
      this.y = terrainY - this.height / 2 - this.wheelRadius;
      this.vy = Math.min(this.vy, 0);

      // Align to terrain
      let angleDiff = terrainAngle - this.angle;
      this.angularVel += angleDiff * 0.1;
      this.angularVel *= 0.85;
      this.angle += this.angularVel;

      // Friction
      this.vx *= FRICTION;

      // Wheel rotation
      this.wheelAngle += this.vx * 0.1;

      // Controls
      if (this.controls.left && this.fuel > 0) {
        this.vx -= this.enginePower;
        this.fuel -= 0.15;
      }
      if (this.controls.right && this.fuel > 0) {
        this.vx += this.enginePower;
        this.fuel -= 0.15;
      }
      if (this.controls.up && this.fuel > 0) {
        this.vy -= this.enginePower * 0.5;
        this.fuel -= 0.1;
      }
      if (this.controls.down) {
        this.vx *= 0.95;
      }

      // Check for flips
      if (Math.abs(this.angle - this.lastAngle) > Math.PI * 1.5) {
        this.flipCount++;
      }
      this.lastAngle = this.angle;

      // Trail
      if (Math.abs(this.vx) > 1) {
        this.trail.push({ x: this.x, y: this.y + this.height / 2, alpha: 1 });
      }
    } else {
      // Air control
      if (this.controls.left) this.angularVel -= 0.003;
      if (this.controls.right) this.angularVel += 0.003;
      if (this.controls.up) this.vy -= 0.1;
      this.angularVel *= 0.98;
      this.angle += this.angularVel;

      // Fuel regen in air
      this.fuel = Math.min(this.maxFuel, this.fuel + 0.05);
    }

    // Gravity
    this.vy += GRAVITY;

    // Apply velocity
    this.x += this.vx;
    this.y += this.vy;

    // Clamp position
    if (this.y > H + 200) {
      this.y = -500;
      this.vy = 0;
      this.vx *= 0.5;
    }

    // Fuel depletion
    this.fuel = Math.max(0, this.fuel);

    // Check finish
    if (this.x >= terrainLength && !this.finished) {
      this.finished = true;
      this.finishTime = raceTime;
      finishOrder.push(this);
      if (finishOrder.length >= 2) {
        endRace();
      }
    }

    // Update trail
    for (let i = this.trail.length - 1; i >= 0; i--) {
      this.trail[i].alpha -= 0.02;
      if (this.trail[i].alpha <= 0) this.trail.splice(i, 1);
    }

    // Particles
    if (this.onGround && Math.abs(this.vx) > 3) {
      if (Math.random() < 0.3) {
        particles.push({
          x: this.x - 20,
          y: this.y + this.height / 2,
          vx: -Math.random() * 2 - 1,
          vy: -Math.random() * 3,
          life: 30,
          maxLife: 30,
          color: this.color
        });
      }
    }
  }

  draw() {
    let screenX = this.x - cameraX;
    let screenY = this.y;

    // Draw trail
    for (let t of this.trail) {
      ctx.globalAlpha = t.alpha * 0.3;
      ctx.fillStyle = this.color;
      ctx.beginPath();
      ctx.arc(t.x - cameraX, t.y, 3, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    ctx.save();
    ctx.translate(screenX, screenY);
    ctx.rotate(this.angle);

    // Body
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.roundRect(-this.width / 2, -this.height / 2, this.width, this.height, 8);
    ctx.fill();

    // Cabin
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.beginPath();
    ctx.roundRect(-this.width / 4, -this.height / 2 - 15, this.width / 2, 15, 5);
    ctx.fill();

    // Wheels
    ctx.fillStyle = '#333';
    ctx.beginPath();
    ctx.arc(-this.width / 3, this.height / 2 + this.wheelRadius - 5, this.wheelRadius, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(this.width / 3, this.height / 2 + this.wheelRadius - 5, this.wheelRadius, 0, Math.PI * 2);
    ctx.fill();

    // Wheel rims
    ctx.fillStyle = '#666';
    ctx.beginPath();
    ctx.arc(-this.width / 3, this.height / 2 + this.wheelRadius - 5, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(this.width / 3, this.height / 2 + this.wheelRadius - 5, 8, 0, Math.PI * 2);
    ctx.fill();

    // Wheel spokes
    ctx.strokeStyle = '#888';
    ctx.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      let a = this.wheelAngle + (i * Math.PI / 2);
      ctx.beginPath();
      ctx.moveTo(-this.width / 3, this.height / 2 + this.wheelRadius - 5);
      ctx.lineTo(-this.width / 3 + Math.cos(a) * 12, this.height / 2 + this.wheelRadius - 5 + Math.sin(a) * 12);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(this.width / 3, this.height / 2 + this.wheelRadius - 5);
      ctx.lineTo(this.width / 3 + Math.cos(a) * 12, this.height / 2 + this.wheelRadius - 5 + Math.sin(a) * 12);
      ctx.stroke();
    }

    // Number
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 14px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(this.name === 'P1' ? '1' : '2', 0, 0);

    ctx.restore();

    // Fuel bar
    let barWidth = 40;
    let barHeight = 6;
    let barX = screenX - barWidth / 2;
    let barY = screenY - this.height / 2 - 30;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(barX, barY, barWidth, barHeight);
    let fuelPercent = this.fuel / this.maxFuel;
    let fuelColor = fuelPercent > 0.5 ? '#4CAF50' : fuelPercent > 0.25 ? '#FF9800' : '#f44336';
    ctx.fillStyle = fuelColor;
    ctx.fillRect(barX, barY, barWidth * fuelPercent, barHeight);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.strokeRect(barX, barY, barWidth, barHeight);
  }
}

// Generate terrain
function generateTerrain() {
  terrain = [];
  let y = H * 0.6;
  let segmentWidth = terrainLength / TERRAIN_SEGMENTS;

  for (let i = 0; i <= TERRAIN_SEGMENTS; i++) {
    let x = i * segmentWidth;

    // Combine multiple sine waves for interesting terrain
    let hill1 = Math.sin(x * 0.002) * 80;
    let hill2 = Math.sin(x * 0.005) * 40;
    let hill3 = Math.sin(x * 0.01) * 20;
    let hill4 = Math.sin(x * 0.001) * 120;

    // Add some randomness
    let noise = Math.sin(x * 0.03) * 10 + Math.sin(x * 0.07) * 5;

    y = H * 0.6 + hill1 + hill2 + hill3 + hill4 + noise;

    // Make start flat
    if (i < 20) {
      y = H * 0.6;
    }

    // Make finish flat
    if (i > TERRAIN_SEGMENTS - 20) {
      y = H * 0.5;
    }

    terrain.push(y);
  }
}

// Create vehicles
let player1, player2;

function createVehicles() {
  player1 = new Vehicle(100, '#4CAF50', 'P1', { left: false, right: false, up: false, down: false });
  player2 = new Vehicle(100, '#2196F3', 'P2', { left: false, right: false, up: false, down: false });
  player1.y = player1.getTerrainY(100) - 50;
  player2.y = player2.getTerrainY(100) - 50;
  finishOrder = [];
  raceTime = 0;
  particles = [];
}

// Touch controls
const touches = {};

canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  for (let touch of e.changedTouches) {
    touches[touch.identifier] = { x: touch.clientX, y: touch.clientY };
    handleTouch(touch.clientX, touch.clientY, true);
  }
}, { passive: false });

canvas.addEventListener('touchmove', (e) => {
  e.preventDefault();
  for (let touch of e.changedTouches) {
    touches[touch.identifier] = { x: touch.clientX, y: touch.clientY };
  }
}, { passive: false });

canvas.addEventListener('touchend', (e) => {
  e.preventDefault();
  for (let touch of e.changedTouches) {
    delete touches[touch.identifier];
    handleTouch(touch.clientX, touch.clientY, false);
  }
}, { passive: false });

function handleTouch(x, y, isDown) {
  if (gameState !== 'racing') return;

  // Left half of screen = Player 1 controls
  if (x < W / 2) {
    if (x < W / 4) {
      player1.controls.left = isDown;
    } else {
      player1.controls.right = isDown;
    }
  } else {
    // Right half = Player 2 controls
    if (y < H / 2) {
      player2.controls.up = isDown;
    } else {
      player2.controls.down = isDown;
    }
  }
}

// Draw terrain
function drawTerrain() {
  let segmentWidth = terrainLength / TERRAIN_SEGMENTS;
  let startIdx = Math.max(0, Math.floor(cameraX / segmentWidth) - 2);
  let endIdx = Math.min(TERRAIN_SEGMENTS, Math.ceil((cameraX + W) / segmentWidth) + 2);

  // Sky gradient
  let skyGrad = ctx.createLinearGradient(0, 0, 0, H);
  skyGrad.addColorStop(0, '#87CEEB');
  skyGrad.addColorStop(0.5, '#E0F7FA');
  skyGrad.addColorStop(1, '#B2EBF2');
  ctx.fillStyle = skyGrad;
  ctx.fillRect(0, 0, W, H);

  // Sun
  ctx.fillStyle = '#FFD54F';
  ctx.beginPath();
  ctx.arc(W - 80, 80, 40, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,213,79,0.3)';
  ctx.beginPath();
  ctx.arc(W - 80, 80, 60, 0, Math.PI * 2);
  ctx.fill();

  // Mountains background
  ctx.fillStyle = 'rgba(100,150,100,0.3)';
  ctx.beginPath();
  ctx.moveTo(0, H);
  for (let x = 0; x <= W; x += 50) {
    let mx = x + cameraX * 0.2;
    let my = H * 0.4 + Math.sin(mx * 0.003) * 100 + Math.sin(mx * 0.007) * 50;
    ctx.lineTo(x, my);
  }
  ctx.lineTo(W, H);
  ctx.fill();

  // Terrain
  ctx.beginPath();
  ctx.moveTo(0, H);

  for (let i = startIdx; i <= endIdx; i++) {
    let x = i * segmentWidth - cameraX;
    let y = terrain[i];
    if (i === startIdx) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  }

  ctx.lineTo(W, H);
  ctx.closePath();

  // Terrain gradient
  let terrGrad = ctx.createLinearGradient(0, H * 0.3, 0, H);
  terrGrad.addColorStop(0, '#8BC34A');
  terrGrad.addColorStop(0.3, '#689F38');
  terrGrad.addColorStop(0.7, '#5D4037');
  terrGrad.addColorStop(1, '#3E2723');
  ctx.fillStyle = terrGrad;
  ctx.fill();

  // Terrain outline
  ctx.strokeStyle = '#558B2F';
  ctx.lineWidth = 3;
  ctx.beginPath();
  for (let i = startIdx; i <= endIdx; i++) {
    let x = i * segmentWidth - cameraX;
    let y = terrain[i];
    if (i === startIdx) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  }
  ctx.stroke();

  // Grass on top
  ctx.strokeStyle = '#9CCC65';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let i = startIdx; i <= endIdx; i++) {
    let x = i * segmentWidth - cameraX;
    let y = terrain[i];
    if (i === startIdx) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  }
  ctx.stroke();

  // Finish line
  let finishX = terrainLength - cameraX;
  if (finishX > -50 && finishX < W + 50) {
    // Checkered flag
    let flagHeight = 100;
    let flagWidth = 10;
    for (let row = 0; row < flagHeight / 10; row++) {
      for (let col = 0; col < 2; col++) {
        ctx.fillStyle = (row + col) % 2 === 0 ? '#fff' : '#000';
        ctx.fillRect(finishX + col * flagWidth, H * 0.5 - flagHeight + row * 10, flagWidth, 10);
      }
    }
    // Pole
    ctx.fillStyle = '#888';
    ctx.fillRect(finishX - 2, H * 0.5 - flagHeight - 20, 4, flagHeight + 20);

    // Finish text
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 20px Arial Black';
    ctx.textAlign = 'center';
    ctx.fillText('FINISH', finishX, H * 0.5 - flagHeight - 30);
  }

  // Start line
  let startX = 100 - cameraX;
  if (startX > -50 && startX < W + 50) {
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 3;
    ctx.setLineDash([10, 10]);
    ctx.beginPath();
    ctx.moveTo(startX, terrain[0] - 50);
    ctx.lineTo(startX, H);
    ctx.stroke();
    ctx.setLineDash([]);
  }
}

// Draw particles
function drawParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.1;
    p.life--;

    if (p.life <= 0) {
      particles.splice(i, 1);
      continue;
    }

    ctx.globalAlpha = p.life / p.maxLife;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x - cameraX, p.y, 3, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

// Draw HUD
function drawHUD() {
  // Player 1 info (left side)
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(10, 10, 150, 60);
  ctx.strokeStyle = '#4CAF50';
  ctx.lineWidth = 2;
  ctx.strokeRect(10, 10, 150, 60);

  ctx.fillStyle = '#4CAF50';
  ctx.font = 'bold 16px Arial';
  ctx.textAlign = 'left';
  ctx.fillText('🟢 Player 1', 20, 32);

  ctx.fillStyle = '#fff';
  ctx.font = '12px Arial';
  ctx.fillText(`Dist: ${Math.floor(player1.x / 10)}m`, 20, 50);
  ctx.fillText(`Fuel: ${Math.floor(player1.fuel)}%`, 20, 65);

  // Player 2 info (right side)
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(W - 160, 10, 150, 60);
  ctx.strokeStyle = '#2196F3';
  ctx.lineWidth = 2;
  ctx.strokeRect(W - 160, 10, 150, 60);

  ctx.fillStyle = '#2196F3';
  ctx.font = 'bold 16px Arial';
  ctx.textAlign = 'left';
  ctx.fillText('🔵 Player 2', W - 150, 32);

  ctx.fillStyle = '#fff';
  ctx.font = '12px Arial';
  ctx.fillText(`Dist: ${Math.floor(player2.x / 10)}m`, W - 150, 50);
  ctx.fillText(`Fuel: ${Math.floor(player2.fuel)}%`, W - 150, 65);

  // Progress bars
  let barW = 100;
  let barH = 8;

  // P1 progress
  let p1Progress = Math.min(1, player1.x / terrainLength);
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(10, 80, barW + 20, barH + 10);
  ctx.fillStyle = '#4CAF50';
  ctx.fillRect(20, 85, barW * p1Progress, barH);
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 1;
  ctx.strokeRect(20, 85, barW, barH);

  // P2 progress
  let p2Progress = Math.min(1, player2.x / terrainLength);
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(W - barW - 30, 80, barW + 20, barH + 10);
  ctx.fillStyle = '#2196F3';
  ctx.fillRect(W - barW - 20, 85, barW * p2Progress, barH);
  ctx.strokeStyle = '#fff';
  ctx.strokeRect(W - barW - 20, 85, barW, barH);

  // Controls hint
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.font = '11px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('P1: ← → | P2: ↑ ↓', W / 2, H - 20);

  // Touch zone indicators
  ctx.fillStyle = 'rgba(76,175,80,0.1)';
  ctx.fillRect(0, 0, W / 2, H);
  ctx.fillStyle = 'rgba(33,150,243,0.1)';
  ctx.fillRect(W / 2, 0, W / 2, H);

  // Zone labels
  ctx.fillStyle = 'rgba(76,175,80,0.3)';
  ctx.font = 'bold 14px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('PLAYER 1 CONTROLS', W / 4, H / 2);
  ctx.fillStyle = 'rgba(33,150,243,0.3)';
  ctx.fillText('PLAYER 2 CONTROLS', 3 * W / 4, H / 2);
}

// Draw virtual buttons
function drawButtons() {
  if (gameState !== 'racing') return;

  let btnSize = 60;
  let btnY = H - 100;

  // Player 1 buttons (left side)
  // Left button
  ctx.fillStyle = player1.controls.left ? 'rgba(76,175,80,0.6)' : 'rgba(76,175,80,0.3)';
  ctx.beginPath();
  ctx.roundRect(20, btnY, btnSize, btnSize, 10);
  ctx.fill();
  ctx.strokeStyle = '#4CAF50';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('←', 20 + btnSize / 2, btnY + btnSize / 2);

  // Right button
  ctx.fillStyle = player1.controls.right ? 'rgba(76,175,80,0.6)' : 'rgba(76,175,80,0.3)';
  ctx.beginPath();
  ctx.roundRect(20 + btnSize + 10, btnY, btnSize, btnSize, 10);
  ctx.fill();
  ctx.strokeStyle = '#4CAF50';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = '#fff';
  ctx.fillText('→', 20 + btnSize + 10 + btnSize / 2, btnY + btnSize / 2);

  // Player 2 buttons (right side)
  // Up button
  ctx.fillStyle = player2.controls.up ? 'rgba(33,150,243,0.6)' : 'rgba(33,150,243,0.3)';
  ctx.beginPath();
  ctx.roundRect(W - 20 - btnSize, btnY, btnSize, btnSize, 10);
  ctx.fill();
  ctx.strokeStyle = '#2196F3';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = '#fff';
  ctx.fillText('↑', W - 20 - btnSize + btnSize / 2, btnY + btnSize / 2);

  // Down button
  ctx.fillStyle = player2.controls.down ? 'rgba(33,150,243,0.6)' : 'rgba(33,150,243,0.3)';
  ctx.beginPath();
  ctx.roundRect(W - 20 - btnSize * 2 - 10, btnY, btnSize, btnSize, 10);
  ctx.fill();
  ctx.strokeStyle = '#2196F3';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = '#fff';
  ctx.fillText('↓', W - 20 - btnSize * 2 - 10 + btnSize / 2, btnY + btnSize / 2);
}

// Countdown
function startCountdown() {
  gameState = 'countdown';
  countdownEl.style.display = 'block';
  let count = 3;
  countdownEl.textContent = count;

  let interval = setInterval(() => {
    count--;
    if (count > 0) {
      countdownEl.textContent = count;
    } else if (count === 0) {
      countdownEl.textContent = 'GO!';
      countdownEl.style.color = '#4CAF50';
    } else {
      clearInterval(interval);
      countdownEl.style.display = 'none';
      countdownEl.style.color = '#ff6b35';
      gameState = 'racing';
      timerEl.textContent = '🏁 RACE!';
    }
  }, 1000);
}

// End race
function endRace() {
  gameState = 'finished';
  timerEl.textContent = '🏁 FINISHED!';

  let winner = finishOrder[0];
  winnerText.textContent = winner.name === 'P1' ? '🟢 Player 1 Wins!' : '🔵 Player 2 Wins!';
  winnerText.style.color = winner.color;
  winTime.textContent = `Time: ${winner.finishTime.toFixed(2)}s`;

  setTimeout(() => {
    finishScreen.style.display = 'flex';
  }, 1000);
}

// Main game loop
function gameLoop() {
  if (gameState === 'racing') {
    raceTime += 1 / 60;
    timerEl.textContent = `⏱️ ${raceTime.toFixed(1)}s`;

    player1.update();
    player2.update();

    // Camera follows the leading player
    let leadingX = Math.max(player1.x, player2.x);
    cameraX += (leadingX - W / 3 - cameraX) * 0.1;
    cameraX = Math.max(0, cameraX);
  }

  // Draw
  ctx.clearRect(0, 0, W, H);
  drawTerrain();
  drawParticles();

  if (gameState === 'racing' || gameState === 'finished') {
    player1.draw();
    player2.draw();
    drawHUD();
    drawButtons();
  }

  requestAnimationFrame(gameLoop);
}

// Start button
document.getElementById('start-btn').addEventListener('click', () => {
  startScreen.style.display = 'none';
  generateTerrain();
  createVehicles();
  startCountdown();
});

// Restart button
document.getElementById('restart-btn').addEventListener('click', () => {
  finishScreen.style.display = 'none';
  generateTerrain();
  createVehicles();
  startCountdown();
});

// Polyfill for roundRect
if (!CanvasRenderingContext2D.prototype.roundRect) {
  CanvasRenderingContext2D.prototype.roundRect = function(x, y, w, h, r) {
    if (typeof r === 'number') r = [r, r, r, r];
    this.moveTo(x + r[0], y);
    this.lineTo(x + w - r[1], y);
    this.quadraticCurveTo(x + w, y, x + w, y + r[1]);
    this.lineTo(x + w, y + h - r[2]);
    this.quadraticCurveTo(x + w, y + h, x + w - r[2], y + h);
    this.lineTo(x + r[3], y + h);
    this.quadraticCurveTo(x, y + h, x, y + h - r[3]);
    this.lineTo(x, y + r[0]);
    this.quadraticCurveTo(x, y, x + r[0], y);
    this.closePath();
  };
}

// Start game loop
gameLoop();
</script>
