{ name: 'SMG', damage: 15, fireRate: 60, ammo: 40, maxAmmo: 40, reserve: 160, reloadTime: 1500, spread: 0.04, range: 150, auto: true, type: 'smg' },
{ name: 'SNIPER', damage: 100, fireRate: 1500, ammo: 5, maxAmmo: 5, reserve: 20, reloadTime: 3000, spread: 0.001, range: 500, auto: false, type: 'sniper' },
{ name: 'SHOTGUN', damage: 60, fireRate: 800, ammo: 8, maxAmmo: 8, reserve: 32, reloadTime: 2500, spread: 0.08, range: 50, auto: false, type: 'shotgun', pellets: 8 },
{ name: 'LMG', damage: 20, fireRate: 50, ammo: 100, maxAmmo: 100, reserve: 200, reloadTime: 3500, spread: 0.03, range: 250, auto: true, type: 'lmg' }
],
