// ==================== AUDIO SYSTEM ====================
class AudioSystem {
constructor() {
this.ctx = new (window.AudioContext || window.webkitAudioContext)();
this.masterGain = this.ctx.createGain();
this.masterGain.gain.value = 0.3;
this.masterGain.connect(this.ctx.destination);
}

playGunshot(weaponType) {
const osc = this.ctx.createOscillator();
const gain = this.ctx.createGain();
const noise = this.createNoise();
const noiseGain = this.ctx.createGain();

noise.connect(noiseGain);
noiseGain.connect(this.masterGain);
noiseGain.gain.setValueAtTime(0.8, this.ctx.currentTime);
noiseGain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.15);

osc.connect(gain);
gain.connect(this.masterGain);

if (weaponType === 'sniper') {
osc.frequency.setValueAtTime(150, this.ctx.currentTime);
osc.frequency.exponentialRampToValueAtTime(50, this.ctx.currentTime + 0.3);
gain.gain.setValueAtTime(1, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.3);
} else if (weaponType === 'shotgun') {
osc.frequency.setValueAtTime(100, this.ctx.currentTime);
osc.frequency.exponentialRampToValueAtTime(30, this.ctx.currentTime + 0.2);
gain.gain.setValueAtTime(1, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.2);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.2);
} else if (weaponType === 'rifle') {
osc.frequency.setValueAtTime(200, this.ctx.currentTime);
osc.frequency.exponentialRampToValueAtTime(80, this.ctx.currentTime + 0.1);
gain.gain.setValueAtTime(0.7, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.1);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.1);
} else if (weaponType === 'smg') {
osc.frequency.setValueAtTime(300, this.ctx.currentTime);
osc.frequency.exponentialRampToValueAtTime(100, this.ctx.currentTime + 0.05);
gain.gain.setValueAtTime(0.5, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.05);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.05);
} else {
osc.frequency.setValueAtTime(180, this.ctx.currentTime);
osc.frequency.exponentialRampToValueAtTime(60, this.ctx.currentTime + 0.08);
gain.gain.setValueAtTime(0.6, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.08);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.08);
}
}

playHit() {
const osc = this.ctx.createOscillator();
const gain = this.ctx.createGain();
osc.connect(gain);
gain.connect(this.masterGain);
osc.frequency.setValueAtTime(800, this.ctx.currentTime);
osc.frequency.exponentialRampToValueAtTime(400, this.ctx.currentTime + 0.1);
gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.1);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.1);
}

playReload() {
const osc = this.ctx.createOscillator();
const gain = this.ctx.createGain();
osc.connect(gain);
gain.connect(this.masterGain);
osc.frequency.setValueAtTime(400, this.ctx.currentTime);
osc.frequency.setValueAtTime(600, this.ctx.currentTime + 0.1);
osc.frequency.setValueAtTime(800, this.ctx.currentTime + 0.2);
gain.gain.setValueAtTime(0.2, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.3);
}

playDamage() {
const osc = this.ctx.createOscillator();
const gain = this.ctx.createGain();
osc.connect(gain);
gain.connect(this.masterGain);
osc.frequency.setValueAtTime(200, this.ctx.currentTime);
osc.frequency.exponentialRampToValueAtTime(100, this.ctx.currentTime + 0.2);
gain.gain.setValueAtTime(0.4, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.2);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.2);
}

playFootstep() {
const noise = this.createNoise();
const gain = this.ctx.createGain();
const filter = this.ctx.createBiquadFilter();
filter.type = 'lowpass';
filter.frequency.value = 500;
noise.connect(filter);
filter.connect(gain);
gain.connect(this.masterGain);
gain.gain.setValueAtTime(0.1, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.05);
noise.start(this.ctx.currentTime);
noise.stop(this.ctx.currentTime + 0.05);
}

createNoise() {
const bufferSize = this.ctx.sampleRate * 0.1;
const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
const data = buffer.getChannelData(0);
for (let i = 0; i < bufferSize; i++) {
data[i] = Math.random() * 2 - 1;
}
const source = this.ctx.createBufferSource();
source.buffer = buffer;
return source;
}

playExplosion() {
const osc = this.ctx.createOscillator();
const gain = this.ctx.createGain();
const noise = this.createNoise();
const noiseGain = this.ctx.createGain();
noise.connect(noiseGain);
noiseGain.connect(this.masterGain);
noiseGain.gain.setValueAtTime(1, this.ctx.currentTime);
noiseGain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.5);
osc.connect(gain);
gain.connect(this.masterGain);
osc.frequency.setValueAtTime(80, this.ctx.currentTime);
osc.frequency.exponentialRampToValueAtTime(20, this.ctx.currentTime + 0.5);
gain.gain.setValueAtTime(0.8, this.ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.5);
osc.start(this.ctx.currentTime);
osc.stop(this.ctx.currentTime + 0.5);
}
}

