function createLighting() {
const ambientLight = new THREE.AmbientLight(0x404040, 0.6);
Game.scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0xffffff, 1.2);
sunLight.position.set(100, 100, 50);
sunLight.castShadow = true;
sunLight.shadow.mapSize.width = 2048;
sunLight.shadow.mapSize.height = 2048;
sunLight.shadow.camera.near = 0.5;
sunLight.shadow.camera.far = 500;
sunLight.shadow.camera.left = -200;
sunLight.shadow.camera.right = 200;
sunLight.shadow.camera.top = 200;
sunLight.shadow.camera.bottom = -200;
Game.scene.add(sunLight);

const hemiLight = new THREE.HemisphereLight(0x87CEEB, 0x362907, 0.4);
Game.scene.add(hemiLight);

const pointLight = new THREE.PointLight(0xff4400, 0.5, 100);
pointLight.position.set(0, 20, 0);
Game.scene.add(pointLight);
}

function createGround() {
const groundGeo = new THREE.PlaneGeometry(Game.environment.groundSize, Game.environment.groundSize, 100, 100);
const groundMat = new THREE.MeshStandardMaterial({
color: 0x3d5c3d,
roughness: 0.8,
metalness: 0.1
});

const vertices = groundGeo.attributes.position.array;
for (let i = 0; i < vertices.length; i += 3) {
vertices[i + 2] += Math.sin(vertices[i] * 0.05) * 2 + Math.cos(vertices[i + 1] * 0.05) * 2;
}
groundGeo.computeVertexNormals();

const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
Game.scene.add(ground);

const roadGeo = new THREE.PlaneGeometry(10, Game.environment.groundSize);
const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.9 });
const road1 = new THREE.Mesh(roadGeo, roadMat);
road1.rotation.x = -Math.PI / 2;
road1.position.y = 0.05;
Game.scene.add(road1);

const road2 = road1.clone();
road2.rotation.z = Math.PI / 2;
Game.scene.add(road2);
}

function createBuildings() {
const buildingColors = [0x8B4513, 0x696969, 0x808080, 0xA0522D, 0x708090, 0x556B2F];

for (let i = 0; i < Game.environment.buildingCount; i++) {
const width = 5 + Math.random() * 15;
const height = 5 + Math.random() * 25;
const depth = 5 + Math.random() * 15;

const buildingGeo = new THREE.BoxGeometry(width, height, depth);
const buildingMat = new THREE.MeshStandardMaterial({
color: buildingColors[Math.floor(Math.random() * buildingColors.length)],
roughness: 0.7,
metalness: 0.2
});

const building = new THREE.Mesh(buildingGeo, buildingMat);
building.position.set(
(Math.random() - 0.5) * Game.environment.groundSize * 0.8,
height / 2,
(Math.random() - 0.5) * Game.environment.groundSize * 0.8
);
building.castShadow = true;
building.receiveShadow = true;
Game.scene.add(building);
Game.buildings.push(building);

// Windows
const windowGeo = new THREE.PlaneGeometry(1.5, 2);
const windowMat = new THREE.MeshStandardMaterial({
color: 0x87CEEB,
roughness: 0.1,
metalness: 0.8,
emissive: 0x111111
});

for (let w = 0; w < 3; w++) {
for (let h = 0; h < Math.floor(height / 4); h++) {
const window = new THREE.Mesh(windowGeo, windowMat);
window.position.set(
building.position.x + (w - 1) * 3,
h * 4 + 3,
building.position.z + depth / 2 + 0.1
);
Game.scene.add(window);
}
}

// Roof
const roofGeo = new THREE.ConeGeometry(width * 0.7, 3, 4);
const roofMat = new THREE.MeshStandardMaterial({ color: 0x8B0000, roughness: 0.8 });
const roof = new THREE.Mesh(roofGeo, roofMat);
roof.position.copy(building.position);
roof.position.y = height + 1.5;
roof.rotation.y = Math.PI / 4;
roof.castShadow = true;
Game.scene.add(roof);
}
}

