// ==================== INPUT HANDLING ====================
function onKeyDown(event) {
switch (event.code) {
case 'KeyW': Game.moveForward = true; break;
case 'KeyS': Game.moveBackward = true; break;
case 'KeyA': Game.moveLeft = true; break;
case 'KeyD': Game.moveRight = true; break;
case 'Space':
if (Game.player.onGround) {
Game.player.velocity.y = 0.3;
Game.player.onGround = false;
}
break;
case 'ShiftLeft': Game.sprint = true; break;
case 'ControlLeft': Game.crouch = true; break;
case 'KeyR': reloadWeapon(); break;
case 'Digit1': switchWeapon(0); break;
case 'Digit2': switchWeapon(1); break;
case 'Digit3': switchWeapon(2); break;
case 'Digit4': switchWeapon(3); break;
case 'Digit5': switchWeapon(4); break;
}
}

function onKeyUp(event) {
switch (event.code) {
case 'KeyW': Game.moveForward = false; break;
case 'KeyS': Game.moveBackward = false; break;
case 'KeyA': Game.moveLeft = false; break;
case 'KeyD': Game.moveRight = false; break;
case 'ShiftLeft': Game.sprint = false; break;
case 'ControlLeft': Game.crouch = false; break;
}
}

function onMouseDown(event) {
if (!Game.isPlaying) return;
if (event.button === 0) {
Game.mouseDown = true;
shoot();
} else if (event.button === 2) {
toggleScope();
}
}

function onMouseUp(event) {
if (event.button === 0) Game.mouseDown = false;
if (event.button === 2) toggleScope();
}

function onMouseMove(event) {
if (!Game.pointerLocked || !Game.isPlaying) return;

const sensitivity = Game.scopeActive ? 0.0005 : 0.002;
Game.euler.y -= event.movementX * sensitivity;
Game.euler.x -= event.movementY * sensitivity;
Game.euler.x = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, Game.euler.x));

Game.camera.quaternion.setFromEuler(Game.euler);
}

function toggleScope() {
Game.scopeActive = !Game.scopeActive;
const scopeOverlay = document.getElementById('scope-overlay');
const scopeLines = document.getElementById('scope-lines');

if (Game.scopeActive) {
scopeOverlay.style.display = 'block';
scopeLines.style.display = 'block';
Game.camera.fov = 30;
Game.camera.updateProjectionMatrix();
document.getElementById('crosshair').style.display = 'none';
} else {
scopeOverlay.style.display = 'none';
scopeLines.style.display = 'none';
Game.camera.fov = 75;
Game.camera.updateProjectionMatrix();
document.getElementById('crosshair').style.display = 'block';
}
}

function switchWeapon(index) {
if (index === Game.currentWeapon || Game.isReloading) return;
Game.currentWeapon = index;
updateHUD();

document.querySelectorAll('.weapon-slot').forEach((slot, i) => {
slot.classList.toggle('active', i === index);
});
}

function reloadWeapon() {
if (Game.isReloading) return;
const weapon = Game.weapons[Game.currentWeapon];
if (weapon.ammo === weapon.maxAmmo) return;

Game.isReloading = true;
document.getElementById('reload-bar').style.display = 'block';
document.getElementById('reload-text').style.display = 'block';
audio.playReload();

let progress = 0;
const reloadInterval = setInterval(() => {
progress += 100 / (weapon.reloadTime / 50);
document.getElementById('reload-fill').style.width = progress + '%';

if (progress >= 100) {
clearInterval(reloadInterval);
weapon.ammo = weapon.maxAmmo;
Game.isReloading = false;
document.getElementById('reload-bar').style.display = 'none';
document.getElementById('reload-text').style.display = 'none';
updateHUD();
}
}, 50);
}

function shoot() {
if (!Game.isPlaying || Game.isReloading) return;

const weapon = Game.weapons[Game.currentWeapon];
const now = Date.now();

if (now - Game.lastShot < weapon.fireRate) return;
if (weapon.ammo <= 0) {
reloadWeapon();
return;
}

Game.lastShot = now;
weapon.ammo--;
Game.player.shotsFired++;

audio.playGunshot(weapon.type);

// Muzzle flash
const muzzleFlash = document.getElementById('muzzle-flash');
muzzleFlash.style.display = 'block';
Game.muzzleFlashTime = 50;
setTimeout(() => { muzzleFlash.style.display = 'none'; }, 50);

// Recoil
Game.gunRecoil = 0.1;
Game.euler.x += 0.02;

// Create bullet tracer
createBulletTracer();

// Raycasting for hit detection
const pellets = weapon.pellets || 1;
for (let p = 0; p < pellets; p++) {
const spread = weapon.spread;
const rayOrigin = Game.camera.position.clone();
const rayDirection = new THREE.Vector3(
(Math.random() - 0.5) * spread,
(Math.random() - 0.5) * spread,
-1
).normalize();

Game.raycaster.set(rayOrigin, rayDirection);

const enemyMeshes = [];
Game.enemies.forEach(enemy => {
if (enemy.userData.alive) {
enemy.traverse(child => {
if (child.isMesh) enemyMeshes.push(child);
});
}
});

const intersects = Game.raycaster.intersectObjects(enemyMeshes, false);

if (intersects.length > 0) {
const hitObject = intersects[0].object;
let enemy = hitObject.parent;
while (enemy && !enemy.userData.health) {
enemy = enemy.parent;
}

if (enemy && enemy.userData.alive) {
enemy.userData.health -= weapon.damage;
Game.player.shotsHit++;
audio.playHit();

// Hit marker
showHitMarker();

// Blood effect
createBloodEffect(intersects[0].point);

if (enemy.userData.health <= 0) {
killEnemy(enemy);
}
}
}
}

updateHUD();

// Auto fire
if (weapon.auto && Game.mouseDown) {
setTimeout(() => {
if (Game.mouseDown) shoot();
}, weapon.fireRate);
}
}

function createBulletTracer() {
const tracerGeo = new THREE.CylinderGeometry(0.02, 0.02, 2, 4);
const tracerMat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
const tracer = new THREE.Mesh(tracerGeo, tracerMat);

const direction = new THREE.Vector3(0, 0, -1);
direction.applyQuaternion(Game.camera.quaternion);

tracer.position.copy(Game.camera.position).add(direction.clone().multiplyScalar(2));
tracer.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction);

Game.scene.add(tracer);
Game.bullets.push({ mesh: tracer, velocity: direction.multiplyScalar(3), life: 60 });
}

function createBloodEffect(position) {
for (let i = 0; i < 5; i++) {
const particleGeo = new THREE.SphereGeometry(0.1, 4, 4);
const particleMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
const particle = new THREE.Mesh(particleGeo, particleMat);
particle.position.copy(position);

const velocity = new THREE.Vector3(
(Math.random() - 0.5) * 0.2,
Math.random() * 0.2,
(Math.random() - 0.5) * 0.2
);

Game.scene.add(particle);
Game.particles.push({ mesh: particle, velocity: velocity, life: 30 });
}
}

function showHitMarker() {
const hitMarker = document.getElementById('hit-marker');
hitMarker.style.display = 'block';
setTimeout(() => { hitMarker.style.display = 'none'; }, 100);
}

function killEnemy(enemy) {
enemy.userData.alive = false;
Game.player.kills++;
Game.player.score += 100;

// Death effect
createExplosionEffect(enemy.position);

// Remove enemy
setTimeout(() => {
Game.scene.remove(enemy);
const index = Game.enemies.indexOf(enemy);
if (index > -1) Game.enemies.splice(index, 1);
}, 1000);

// Kill feed
addKillFeedEntry('You', 'Enemy');

updateHUD();
}

function createExplosionEffect(position) {
for (let i = 0; i < 20; i++) {
const particleGeo = new THREE.SphereGeometry(0.2, 4, 4);
const particleMat = new THREE.MeshBasicMaterial({
color: new THREE.Color().setHSL(Math.random() * 0.1, 1, 0.5)
});
const particle = new THREE.Mesh(particleGeo, particleMat);
particle.position.copy(position);

const velocity = new THREE.Vector3(
(Math.random() - 0.5) * 0.5,
Math.random() * 0.5,
(Math.random() - 0.5) * 0.5
);

Game.scene.add(particle);
Game.particles.push({ mesh: particle, velocity: velocity, life: 60 });
}
audio.playExplosion();
}

function addKillFeedEntry(killer, victim) {
const killFeed = document.getElementById('kill-feed');
const entry = document.createElement('div');
entry.className = 'kill-entry';
entry.innerHTML = `${killer} 💀 ${victim}`;
killFeed.appendChild(entry);

setTimeout(() => {
entry.remove();
}, 3000);
}

function updateHUD() {
const weapon = Game.weapons[Game.currentWeapon];
document.getElementById('ammo-current').textContent = weapon.ammo;
document.getElementById('ammo-reserve').textContent = weapon.reserve;
document.getElementById('weapon-name').textContent = weapon.name;
document.getElementById('health-fill').style.width = (Game.player.health / Game.player.maxHealth * 100) + '%';
document.getElementById('health-text').textContent = `❤️ HEALTH: ${Math.max(0, Game.player.health)}`;
document.getElementById('score').textContent = Game.player.score;
document.getElementById('kills').textContent = Game.player.kills;
}

function updateMinimap() {
const canvas = document.getElementById('minimap-canvas');
const ctx = canvas.getContext('2d');
ctx.clearRect(0, 0, 180, 180);

// Background
ctx.fillStyle = 'rgba(0,50,0,0.8)';
ctx.beginPath();
ctx.arc(90, 90, 88, 0, Math.PI * 2);
ctx.fill();

// Player
ctx.fillStyle = '#00ff00';
ctx.beginPath();
ctx.arc(90, 90, 4, 0, Math.PI * 2);
ctx.fill();

// Player direction
ctx.strokeStyle = '#00ff00';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(90, 90);
ctx.lineTo(
90 + Math.sin(Game.euler.y) * 15,
90 - Math.cos(Game.euler.y) * 15
);
ctx.stroke();

// Enemies
Game.enemies.forEach(enemy => {
if (enemy.userData.alive) {
const dx = (enemy.position.x - Game.camera.position.x) * 0.5;
const dz = (enemy.position.z - Game.camera.position.z) * 0.5;
const dist = Math.sqrt(dx * dx + dz * dz);

if (dist < 90) {
ctx.fillStyle = '#ff0000';
ctx.beginPath();
ctx.arc(90 + dx, 90 + dz, 3, 0, Math.PI * 2);
ctx.fill();
}
}
});

// Buildings
Game.buildings.forEach(building => {
const dx = (building.position.x - Game.camera.position.x) * 0.5;
const dz = (building.position.z - Game.camera.position.z) * 0.5;
const dist = Math.sqrt(dx * dx + dz * dz);

if (dist < 90) {
ctx.fillStyle = 'rgba(150,150,150,0.5)';
ctx.fillRect(90 + dx - 3, 90 + dz - 3, 6, 6);
}
});
}

function updateEnemies(delta) {
Game.enemies.forEach(enemy => {
if (!enemy.userData.alive) return;

const distanceToPlayer = enemy.position.distanceTo(Game.camera.position);

// State machine
if (distanceToPlayer < 50) {
enemy.userData.state = 'chase';
} else if (distanceToPlayer < 100) {
enemy.userData.state = 'alert';
} else {
enemy.userData.state = 'patrol';
}

if (enemy.userData.state === 'patrol') {
const direction = enemy.userData.patrolTarget.clone().sub(enemy.position);
direction.y = 0;
direction.normalize();
enemy.position.add(direction.multiplyScalar(enemy.userData.speed * 0.5));

if (enemy.position.distanceTo(enemy.userData.patrolTarget) < 5) {
enemy.userData.patrolTarget.set(
(Math.random() - 0.5) * 100,
0,
(Math.random() - 0.5) * 100
);
}

// Face movement direction
enemy.rotation.y = Math.atan2(direction.x, direction.z);
} else if (enemy.userData.state === 'chase') {
const direction = Game.camera.position.clone().sub(enemy.position);
direction.y = 0;
direction.normalize();
enemy.position.add(direction.multiplyScalar(enemy.userData.speed));
enemy.rotation.y = Math.atan2(direction.x, direction.z);

// Shoot at player
const now = Date.now();
if (now - enemy.userData.lastShot > enemy.userData.fireRate && distanceToPlayer < 80) {
enemy.userData.lastShot = now;
enemyShoot(enemy);
}
} else if (enemy.userData.state === 'alert') {
const direction = Game.camera.position.clone().sub(enemy.position);
direction.y = 0;
direction.normalize();
enemy.position.add(direction.multiplyScalar(enemy.userData.speed * 0.7));
enemy.rotation.y = Math.atan2(direction.x, direction.z);
}

// Animation
const time = Date.now() * 0.005;
if (enemy.userData.state !== 'patrol' || Math.sin(time) > 0) {
enemy.children.forEach((child, index) => {
if (index === 4 || index === 5) { // Legs
child.rotation.x = Math.sin(time + (index === 4 ? 0 : Math.PI)) * 0.5;
}
});
}

// Keep enemy on ground
enemy.position.y = 0;
});
}

function enemyShoot(enemy) {
const direction = Game.camera.position.clone().sub(enemy.position).normalize();
const distance = enemy.position.distanceTo(Game.camera.position);

// Accuracy based on distance
const accuracy = Math.max(0.3, 1 - distance / 200);

if (Math.random() < accuracy * 0.3) {
Game.player.health -= 10;
audio.playDamage();

const damageFlash = document.getElementById('damage-flash');
damageFlash.style.display = 'block';
setTimeout(() => { damageFlash.style.display = 'none'; }, 300);

updateHUD();

if (Game.player.health <= 0) {
gameOver();
}
}
}

function updatePlayer(delta) {
const speed = Game.sprint && Game.player.stamina > 0 ? Game.player.sprintSpeed : Game.player.speed;

if (Game.crouch) {
Game.camera.position.y = 2;
} else {
Game.camera.position.y = 5;
}

const direction = new THREE.Vector3();
const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(Game.camera.quaternion);
const right = new THREE.Vector3(1, 0, 0).applyQuaternion(Game.camera.quaternion);

forward.y = 0;
forward.normalize();
right.y = 0;
right.normalize();

if (Game.moveForward) direction.add(forward);
if (Game.moveBackward) direction.sub(forward);
if (Game.moveLeft) direction.sub(right);
if (Game.moveRight) direction.add(right);

if (direction.length() > 0) {
direction.normalize();
Game.camera.position.add(direction.multiplyScalar(speed));

// Footstep sounds
if (Math.random() < 0.05) audio.playFootstep();
}

// Stamina
if (Game.sprint && (Game.moveForward || Game.moveBackward || Game.moveLeft || Game.moveRight)) {
Game.player.stamina = Math.max(0, Game.player.stamina - 0.5);
} else {
Game.player.stamina = Math.min(100, Game.player.stamina + 0.2);
}

document.getElementById('stamina-fill').style.width = Game.player.stamina + '%';

// Gravity
Game.player.velocity.y -= 0.015;
Game.camera.position.y += Game.player.velocity.y;

if (Game.camera.position.y <= (Game.crouch ? 2 : 5)) {
Game.camera.position.y = Game.crouch ? 2 : 5;
Game.player.velocity.y = 0;
Game.player.onGround = true;
}

// Boundary
const boundary = Game.environment.groundSize * 0.45;
Game.camera.position.x = Math.max(-boundary, Math.min(boundary, Game.camera.position.x));
Game.camera.position.z = Math.max(-boundary, Math.min(boundary, Game.camera.position.z));

// Gun animation
if (Game.gunModel) {
const time = Date.now() * 0.001;
Game.gunModel.position.y = -0.3 + Math.sin(time * 2) * 0.01;
Game.gunModel.position.x = 0.3 + Math.cos(time * 1.5) * 0.005;

// Recoil recovery
if (Game.gunRecoil > 0) {
Game.gunRecoil *= 0.9;
Game.gunModel.rotation.x = -Game.gunRecoil;
} else {
Game.gunModel.rotation.x = 0;
}

// Reload animation
if (Game.isReloading) {
Game.gunModel.rotation.x = Math.sin(Date.now() * 0.005) * 0.5;
}
}
}

function updateBullets() {
for (let i = Game.bullets.length - 1; i >= 0; i--) {
const bullet = Game.bullets[i];
bullet.mesh.position.add(bullet.velocity);
bullet.life--;

if (bullet.life <= 0) {
Game.scene.remove(bullet.mesh);
Game.bullets.splice(i, 1);
}
}
}

function updateParticles() {
for (let i = Game.particles.length - 1; i >= 0; i--) {
const particle = Game.particles[i];
particle.mesh.position.add(particle.velocity);
particle.velocity.y -= 0.01;
particle.life--;

if (particle.life <= 0) {
Game.scene.remove(particle.mesh);
Game.particles.splice(i, 1);
}
}
}

function updatePickups() {
Game.pickups.forEach(pickup => {
if (!pickup.userData.active) return;

pickup.rotation.y += 0.02;
pickup.position.y = 0.5 + Math.sin(Date.now() * 0.003) * 0.2;

const distance = pickup.position.distanceTo(Game.camera.position);
if (distance < 2) {
if (pickup.userData.type === 'health') {
Game.player.health = Math.min(Game.player.maxHealth, Game.player.health + 25);
} else if (pickup.userData.type === 'ammo') {
Game.weapons[Game.currentWeapon].reserve += 30;
} else if (pickup.userData.type === 'armor') {
Game.player.maxHealth += 25;
Game.player.health = Math.min(Game.player.maxHealth, Game.player.health + 25);
}

pickup.userData.active = false;
Game.scene.remove(pickup);
updateHUD();
}
});
}

function updateZoneTimer() {
Game.zoneTimer -= 1 / 60;
if (Game.zoneTimer <= 0) {
Game.zoneTimer = 600;
}

const minutes = Math.floor(Game.zoneTimer / 60);
const seconds = Math.floor(Game.zoneTimer % 60);
document.getElementById('zone-timer').textContent = `⏱️ ${minutes}:${seconds.toString().padStart(2, '0')}`;
}

function gameOver() {
Game.isPlaying = false;
document.exitPointerLock();

document.getElementById('final-kills').textContent = Game.player.kills;
document.getElementById('final-score').textContent = Game.player.score;
const accuracy = Game.player.shotsFired > 0 ?
Math.round(Game.player.shotsHit / Game.player.shotsFired * 100) : 0;
document.getElementById('final-accuracy').textContent = accuracy + '%';

document.getElementById('game-over').style.display = 'flex';
}

function restartGame() {
document.getElementById('game-over').style.display = 'none';

Game.player.health = 100;
Game.player.maxHealth = 100;
Game.player.kills = 0;
Game.player.score = 0;
Game.player.shotsFired = 0;
Game.player.shotsHit = 0;
Game.player.velocity.set(0, 0, 0);
Game.player.onGround = true;

Game.camera.position.set(0, 5, 0);
Game.euler.set(0, 0, 0);
Game.camera.quaternion.setFromEuler(Game.euler);

Game.weapons.forEach(w => {
w.ammo = w.maxAmmo;
w.reserve = w.maxAmmo * 4;
});

Game.currentWeapon = 0;
Game.isReloading = false;
Game.zoneTimer = 600;

// Respawn enemies
Game.enemies.forEach(enemy => {
if (!enemy.userData.alive) {
enemy.userData.alive = true;
enemy.userData.health = 100;
enemy.position.set(
(Math.random() - 0.5) * Game.environment.groundSize * 0.7,
0,
(Math.random() - 0.5) * Game.environment.groundSize * 0.7
);
Game.scene.add(enemy);
}
});

updateHUD();
startGame();
}

function startGame() {
document.getElementById('blocker').style.display = 'none';
Game.isPlaying = true;
Game.pointerLocked = true;
document.body.requestPointerLock();
updateHUD();
}

function onWindowResize() {
Game.camera.aspect = window.innerWidth / window.innerHeight;
Game.camera.updateProjectionMatrix();
Game.renderer.setSize(window.innerWidth, window.innerHeight);
}

function animate() {
requestAnimationFrame(animate);

const delta = Game.clock.getDelta();

if (Game.isPlaying) {
updatePlayer(delta);
updateEnemies(delta);
updateBullets();
updateParticles();
updatePickups();
updateMinimap();
updateZoneTimer();
}

Game.renderer.render(Game.scene, Game.camera);
}

// ==================== START ====================
init();
</script>
</body>
</html>

