// Initialize levels with progress
levels.forEach(l => {
  gameState.levels[l.id] = { stars: 0, completed: false };
});

// Canvas setup
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

function resizeCanvas() {
  const container = document.querySelector('.game-canvas-container');
  canvas.width = Math.min(container.clientWidth - 40, 600);
  canvas.height = Math.min(container.clientHeight - 40, 500);
}

// Wood texture generation
function createWoodTexture(width, height, baseColor, grainColor) {
  const c = document.createElement('canvas');
  c.width = width;
  c.height = height;
  const x = c.getContext('2d');

  // Base color
  x.fillStyle = baseColor;
  x.fillRect(0, 0, width, height);

  // Wood grain
  for (let i = 0; i < 20; i++) {
    x.strokeStyle = grainColor;
    x.lineWidth = Math.random() * 2 + 0.5;
    x.globalAlpha = Math.random() * 0.3 + 0.1;
    x.beginPath();
    let y = Math.random() * height;
    x.moveTo(0, y);
    for (let px = 0; px < width; px += 10) {
      y += (Math.random() - 0.5) * 3;
      x.lineTo(px, y);
    }
    x.stroke();
  }

  // Knots
  if (Math.random() > 0.5) {
    const kx = Math.random() * width;
    const ky = Math.random() * height;
    const kr = Math.random() * 8 + 3;
    x.globalAlpha = 0.2;
    x.fillStyle = grainColor;
    x.beginPath();
    x.ellipse(kx, ky, kr, kr * 0.6, Math.random() * Math.PI, 0, Math.PI * 2);
    x.fill();
  }

  x.globalAlpha = 1;
  return c;
}

// Draw wood piece
function drawWoodPiece(ctx, piece, x, y, scale = 1) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate((piece.rotation || 0) * Math.PI / 180);
  ctx.scale(scale, scale);

  const w = piece.w;
  const h = piece.h;

  // Wood texture
  const woodCanvas = createWoodTexture(w, h, '#8B6914', '#5C3A1E');
  ctx.drawImage(woodCanvas, 0, 0, w, h);

  // Border
  ctx.strokeStyle = '#3d2415';
  ctx.lineWidth = 2;
  ctx.strokeRect(0, 0, w, h);

  // Highlight
  ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
  ctx.fillRect(0, 0, w, 2);
  ctx.fillRect(0, 0, 2, h);

  // Shadow
  ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
  ctx.fillRect(w - 2, 0, 2, h);
  ctx.fillRect(0, h - 2, w, 2);

  ctx.restore();
}

// Draw L-shape piece
function drawLShape(ctx, piece, x, y, scale = 1) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate((piece.rotation || 0) * Math.PI / 180);
  ctx.scale(scale, scale);

  const w = piece.w;
  const h = piece.h;
  const thickness = 30;

  // Wood texture for L-shape
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = w;
  tempCanvas.height = h;
  const tCtx = tempCanvas.getContext('2d');

  // Draw L shape
  tCtx.fillStyle = '#8B6914';
  tCtx.fillRect(0, 0, thickness, h);
  tCtx.fillRect(0, h - thickness, w, thickness);

  // Grain
  for (let i = 0; i < 15; i++) {
    tCtx.strokeStyle = '#5C3A1E';
    tCtx.lineWidth = Math.random() * 1.5 + 0.5;
    tCtx.globalAlpha = Math.random() * 0.3 + 0.1;
    tCtx.beginPath();
    let gy = Math.random() * h;
    tCtx.moveTo(0, gy);
    for (let px = 0; px < w; px += 10) {
      gy += (Math.random() - 0.5) * 2;
      tCtx.lineTo(px, gy);
    }
    tCtx.stroke();
  }
  tCtx.globalAlpha = 1;

  ctx.drawImage(tempCanvas, 0, 0);

  // Border
  ctx.strokeStyle = '#3d2415';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(w, 0);
  ctx.lineTo(w, h - thickness);
  ctx.lineTo(thickness, h - thickness);
  ctx.lineTo(thickness, h);
  ctx.lineTo(0, h);
  ctx.closePath();
  ctx.stroke();

  ctx.restore();
}

// Draw triangle piece
function drawTriangle(ctx, piece, x, y, scale = 1) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate((piece.rotation || 0) * Math.PI / 180);
  ctx.scale(scale, scale);

  const w = piece.w;
  const h = piece.h;

  // Wood texture
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = w;
  tempCanvas.height = h;
  const tCtx = tempCanvas.getContext('2d');

  tCtx.fillStyle = '#8B6914';
  tCtx.beginPath();
  tCtx.moveTo(0, 0);
  tCtx.lineTo(w, 0);
  tCtx.lineTo(0, h);
  tCtx.closePath();
  tCtx.fill();

  // Grain
  for (let i = 0; i < 10; i++) {
    tCtx.strokeStyle = '#5C3A1E';
    tCtx.lineWidth = Math.random() * 1.5 + 0.5;
    tCtx.globalAlpha = Math.random() * 0.3 + 0.1;
    tCtx.beginPath();
    let gy = Math.random() * h;
    tCtx.moveTo(0, gy);
    tCtx.lineTo(w * 0.8, gy + (Math.random() - 0.5) * 10);
    tCtx.stroke();
  }
  tCtx.globalAlpha = 1;

  ctx.drawImage(tempCanvas, 0, 0);

  // Border
  ctx.strokeStyle = '#3d2415';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(w, 0);
  ctx.lineTo(0, h);
  ctx.closePath();
  ctx.stroke();

  ctx.restore();
}

// Draw target area
function drawTarget(ctx, target, offsetX, offsetY) {
  ctx.save();
  ctx.translate(offsetX, offsetY);

  // Dashed border
  ctx.setLineDash([8, 4]);
  ctx.strokeStyle = 'rgba(212, 165, 116, 0.3)';
  ctx.lineWidth = 2;
  ctx.strokeRect(0, 0, target.w, target.h);
  ctx.setLineDash([]);

  // Label
  ctx.fillStyle = 'rgba(212, 165, 116, 0.2)';
  ctx.font = '14px Inter';
  ctx.textAlign = 'center';
  ctx.fillText('Target Area', target.w / 2, target.h / 2);

  ctx.restore();
}

// Draw board background
function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Board background
  const gradient = ctx.createRadialGradient(
    canvas.width / 2, canvas.height / 2, 0,
    canvas.width / 2, canvas.height / 2, canvas.width / 2
  );
  gradient.addColorStop(0, '#3d2415');
  gradient.addColorStop(1, '#1a1209');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Wood grain background
  for (let i = 0; i < 30; i++) {
    ctx.strokeStyle = 'rgba(139, 90, 43, 0.05)';
    ctx.lineWidth = Math.random() * 2 + 1;
    ctx.beginPath();
    let y = Math.random() * canvas.height;
    ctx.moveTo(0, y);
    for (let px = 0; px < canvas.width; px += 20) {
      y += (Math.random() - 0.5) * 2;
      ctx.lineTo(px, y);
    }
    ctx.stroke();
  }

  // Target area
  const level = levels[gameState.currentLevel - 1];
  const targetX = (canvas.width - level.target.w) / 2;
  const targetY = (canvas.height - level.target.h) / 2;
  drawTarget(ctx, level.target, targetX, targetY);

  // Draw placed pieces
  gameState.placedPieces.forEach(piece => {
    if (piece.type === 'lshape') {
      drawLShape(ctx, piece, piece.x, piece.y);
    } else if (piece.type === 'triangle') {
      drawTriangle(ctx, piece, piece.x, piece.y);
    } else {
      drawWoodPiece(ctx, piece, piece.x, piece.y);
    }
  });
}

// Initialize level
function initLevel(levelId) {
  const level = levels[levelId - 1];
  gameState.currentLevel = levelId;
  gameState.moves = 0;
  gameState.timer = 0;
  gameState.placedPieces = [];
  gameState.pieces = level.pieces.map((p, i) => ({
    ...p,
    id: i,
    x: 0,
    y: 0,
    placed: false
  }));

  document.getElementById('currentLevel').textContent = levelId;
  document.getElementById('moveCount').textContent = '0';
  document.getElementById('timer').textContent = '0:00';

  if (gameState.timerInterval) clearInterval(gameState.timerInterval);
  gameState.timerInterval = setInterval(() => {
    gameState.timer++;
    const mins = Math.floor(gameState.timer / 60);
    const secs = gameState.timer % 60;
    document.getElementById('timer').textContent = `${mins}:${secs.toString().padStart(2, '0')}`;
  }, 1000);

  resizeCanvas();
  drawBoard();
  createPieceTray();
}

// Create piece tray
function createPieceTray() {
  const tray = document.getElementById('pieceTray');
  tray.innerHTML = '';

  gameState.pieces.forEach((piece, index) => {
    const div = document.createElement('div');
    div.className = 'tray-piece';
    div.dataset.index = index;

    const pieceCanvas = document.createElement('canvas');
    pieceCanvas.width = 60;
    pieceCanvas.height = 60;
    const pCtx = pieceCanvas.getContext('2d');

    // Draw mini piece
    const scale = Math.min(60 / piece.w, 60 / piece.h) * 0.8;
    const offsetX = (60 - piece.w * scale) / 2;
    const offsetY = (60 - piece.h * scale) / 2;

    pCtx.save();
    pCtx.translate(offsetX, offsetY);
    pCtx.scale(scale, scale);

    if (piece.type === 'lshape') {
      drawLShape(pCtx, piece, 0, 0, 1);
    } else if (piece.type === 'triangle') {
      drawTriangle(pCtx, piece, 0, 0, 1);
    } else {
      drawWoodPiece(pCtx, piece, 0, 0, 1);
    }

    pCtx.restore();
    div.appendChild(pieceCanvas);

    // Drag events
    div.addEventListener('mousedown', (e) => startDrag(e, index));
    div.addEventListener('touchstart', (e) => startDrag(e, index), { passive: false });

    // Double click to rotate
    div.addEventListener('dblclick', () => rotatePiece(index));

    tray.appendChild(div);
  });
}

// Drag and drop
function startDrag(e, index) {
  e.preventDefault();
  const piece = gameState.pieces[index];
  if (piece.placed) return;

  gameState.draggingPiece = index;
  const trayPiece = document.querySelector(`.tray-piece[data-index="${index}"]`);
  trayPiece.classList.add('dragging');

  const rect = trayPiece.getBoundingClientRect();
  const clientX = e.touches ? e.touches[0].clientX : e.clientX;
  const clientY = e.touches ? e.touches[0].clientY : e.clientY;

  gameState.dragOffset = {
    x: clientX - rect.left,
    y: clientY - rect.top
  };

  // Create floating piece
  const floatPiece = document.createElement('div');
  floatPiece.id = 'floatingPiece';
  floatPiece.style.position = 'fixed';
  floatPiece.style.left = (clientX - 40) + 'px';
  floatPiece.style.top = (clientY - 40) + 'px';
  floatPiece.style.zIndex = '1000';
  floatPiece.style.pointerEvents = 'none';

  const floatCanvas = document.createElement('canvas');
  floatCanvas.width = 80;
  floatCanvas.height = 80;
  const fCtx = floatCanvas.getContext('2d');

  const scale = Math.min(80 / piece.w, 80 / piece.h) * 0.9;
  const offsetX = (80 - piece.w * scale) / 2;
  const offsetY = (80 - piece.h * scale) / 2;

  fCtx.save();
  fCtx.translate(offsetX, offsetY);
  fCtx.scale(scale, scale);

  if (piece.type === 'lshape') {
    drawLShape(fCtx, piece, 0, 0, 1);
  } else if (piece.type === 'triangle') {
    drawTriangle(fCtx, piece, 0, 0, 1);
  } else {
    drawWoodPiece(fCtx, piece, 0, 0, 1);
  }

  fCtx.restore();
  floatPiece.appendChild(floatCanvas);
  document.body.appendChild(floatPiece);

  document.addEventListener('mousemove', onDrag);
  document.addEventListener('mouseup', endDrag);
  document.addEventListener('touchmove', onDrag, { passive: false });
  document.addEventListener('touchend', endDrag);
}

function onDrag(e) {
  e.preventDefault();
  const floatPiece = document.getElementById('floatingPiece');
  if (!floatPiece) return;

  const clientX = e.touches ? e.touches[0].clientX : e.clientX;
  const clientY = e.touches ? e.touches[0].clientY : e.clientY;

  floatPiece.style.left = (clientX - 40) + 'px';
  floatPiece.style.top = (clientY - 40) + 'px';
}

function endDrag(e) {
  const floatPiece = document.getElementById('floatingPiece');
  if (floatPiece) floatPiece.remove();

  document.removeEventListener('mousemove', onDrag);
  document.removeEventListener('mouseup', endDrag);
  document.removeEventListener('touchmove', onDrag);
  document.removeEventListener('touchend', endDrag);

  if (gameState.draggingPiece === null) return;

  const piece = gameState.pieces[gameState.draggingPiece];
  const trayPiece = document.querySelector(`.tray-piece[data-index="${gameState.draggingPiece}"]`);
  trayPiece.classList.remove('dragging');

  // Check if dropped on canvas
  const canvasRect = canvas.getBoundingClientRect();
  const clientX = e.touches ? e.touches[0].clientX : e.clientX;
  const clientY = e.touches ? e.touches[0].clientY : e.clientY;

  if (clientX >= canvasRect.left && clientX <= canvasRect.right &&
      clientY >= canvasRect.top && clientY <= canvasRect.bottom) {

    const x = clientX - canvasRect.left - piece.w / 2;
    const y = clientY - canvasRect.top - piece.h / 2;

    // Snap to grid
    const snappedX = Math.round(x / 10) * 10;
    const snappedY = Math.round(y / 10) * 10;

    piece.x = snappedX;
    piece.y = snappedY;
    piece.placed = true;
    gameState.placedPieces.push(piece);
    gameState.moves++;
    document.getElementById('moveCount').textContent = gameState.moves;

    trayPiece.classList.add('placed');

    // Check win condition
    checkWin();
  }

  gameState.draggingPiece = null;
  drawBoard();
}

// Rotate piece
function rotatePiece(index) {
  const piece = gameState.pieces[index];
  if (piece.placed) return;

  piece.rotation = (piece.rotation + 90) % 360;
  createPieceTray();
}

// Check win condition
function checkWin() {
  const level = levels[gameState.currentLevel - 1];
  const target = level.target;

  // Check if all pieces are placed
  if (gameState.placedPieces.length !== gameState.pieces.length) return;

  // Check if pieces form the target shape
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

  gameState.placedPieces.forEach(piece => {
    minX = Math.min(minX, piece.x);
    minY = Math.min(minY, piece.y);
    maxX = Math.max(maxX, piece.x + piece.w);
    maxY = Math.max(maxY, piece.y + piece.h);
  });

  const boundsW = maxX - minX;
  const boundsH = maxY - minY;

  // Allow some tolerance
  if (Math.abs(boundsW - target.w) <= 10 && Math.abs(boundsH - target.h) <= 10) {
    winLevel();
  }
}

// Win level
function winLevel() {
  clearInterval(gameState.timerInterval);

  const level = gameState.levels[gameState.currentLevel];
  const optimalMoves = gameState.pieces.length;
  const stars = gameState.moves <= optimalMoves + 2 ? 3 :
                gameState.moves <= optimalMoves + 5 ? 2 : 1;

  level.stars = Math.max(level.stars, stars);
  level.completed = true;

  if (gameState.currentLevel >= gameState.maxUnlocked) {
    gameState.maxUnlocked = Math.min(gameState.currentLevel + 1, levels.length);
  }

  document.getElementById('winMoves').textContent = gameState.moves;
  document.getElementById('winTime').textContent = document.getElementById('timer').textContent;

  const starsStr = '⭐'.repeat(stars) + '☆'.repeat(3 - stars);
  document.getElementById('winStars').textContent = starsStr;

  setTimeout(() => {
    showScreen('winScreen');
    createParticles();
  }, 500);
}

// Create particles
function createParticles() {
  for (let i = 0; i < 20; i++) {
    const particle = document.createElement('div');
    particle.className = 'particle';
    particle.style.left = (Math.random() * 100) + 'vw';
    particle.style.top = (Math.random() * 100) + 'vh';
    particle.style.width = (Math.random() * 10 + 5) + 'px';
    particle.style.height = particle.style.width;
    particle.style.background = `hsl(${30 + Math.random() * 30}, 70%, ${50 + Math.random() * 30}%)`;
    particle.style.setProperty('--tx', (Math.random() - 0.5) * 200 + 'px');
    particle.style.setProperty('--ty', (Math.random() - 0.5) * 200 + 'px');
    document.body.appendChild(particle);
    setTimeout(() => particle.remove(), 1000);
  }
}

// Screen management
function showScreen(screenId) {
  document.querySelectorAll('.screen').forEach(s => s.classList.add('hidden'));
  document.getElementById(screenId).classList.remove('hidden');
}

function showMainMenu() {
  showScreen('mainMenu');
}

function showLevelSelect() {
  renderLevelGrid();
  showScreen('levelSelect');
}

function showHowToPlay() {
  showScreen('howToPlay');
}

function renderLevelGrid() {
  const grid = document.getElementById('levelGrid');
  grid.innerHTML = '';

  levels.forEach(level => {
    const btn = document.createElement('button');
    btn.className = 'level-btn';

    const levelData = gameState.levels[level.id];
    const locked = level.id > gameState.maxUnlocked;

    if (locked) {
      btn.classList.add('locked');
      btn.innerHTML = '🔒';
    } else {
      btn.innerHTML = `${level.id}<div class="level-stars">${'⭐'.repeat(levelData.stars)}${'☆'.repeat(3 - levelData.stars)}</div>`;
      btn.onclick = () => {
        initLevel(level.id);
        showScreen('gameScreen');
      };
    }

    grid.appendChild(btn);
  });
}

function nextLevel() {
  if (gameState.currentLevel < levels.length) {
    initLevel(gameState.currentLevel + 1);
    showScreen('gameScreen');
  } else {
    showLevelSelect();
  }
}

function resetLevel() {
  initLevel(gameState.currentLevel);
}

// Initialize
window.addEventListener('resize', () => {
  if (!document.getElementById('gameScreen').classList.contains('hidden')) {
    resizeCanvas();
    drawBoard();
  }
});

// Start
showMainMenu();
</script>
