<script>
  let board = ['', '', '', '', '', '', '', '', ''];
  let currentPlayer = 'X';
  let gameActive = true;
  let scores = { X: 0, O: 0, draw: 0 };
  let mode = 'pvp'; // 'pvp' or 'ai'

  const winConditions = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8], // rows
    [0, 3, 6], [1, 4, 7], [2, 5, 8], // columns
    [0, 4, 8], [2, 4, 6]              // diagonals
  ];

  const cells = document.querySelectorAll('.cell');
  const statusDisplay = document.getElementById('status');

  function setMode(newMode) {
    mode = newMode;
    document.querySelectorAll('.mode-btn').forEach(btn => btn.classList.remove('active'));
    event.target.classList.add('active');
    restartGame();
  }

  function handleClick(index) {
    if (board[index] !== '' || !gameActive) return;

    makeMove(index, currentPlayer);

    if (mode === 'ai' && gameActive && currentPlayer === 'O') {
      setTimeout(() => {
        aiMove();
      }, 400);
    }
  }

  function makeMove(index, player) {
    board[index] = player;
    const cell = cells[index];
    cell.textContent = player;
    cell.classList.add('taken', player.toLowerCase());

    const winResult = checkWin();
    if (winResult) {
      gameActive = false;
      scores[player]++;
      updateScores();
      statusDisplay.textContent = `PLAYER ${player} WINS! 🎉`;
      statusDisplay.style.color = player === 'X' ? '#ff00ff' : '#ffff00';
      statusDisplay.style.textShadow = player === 'X'
        ? '0 0 10px #ff00ff, 0 0 20px #ff00ff'
        : '0 0 10px #ffff00, 0 0 20px #ffff00';
      statusDisplay.style.animation = 'none';

      winResult.forEach(idx => {
        cells[idx].classList.add('win');
      });

      return;
    }

    if (board.every(cell => cell !== '')) {
      gameActive = false;
      scores.draw++;
      updateScores();
      statusDisplay.textContent = "IT'S A DRAW! 🤝";
      statusDisplay.style.color = '#00ff00';
      statusDisplay.style.textShadow = '0 0 10px #00ff00, 0 0 20px #00ff00';
      statusDisplay.style.animation = 'none';
      return;
    }

    currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
    statusDisplay.textContent = `PLAYER ${currentPlayer}'S TURN`;
    statusDisplay.style.color = currentPlayer === 'X' ? '#ff00ff' : '#ffff00';
    statusDisplay.style.textShadow = currentPlayer === 'X'
      ? '0 0 10px #ff00ff'
      : '0 0 10px #ffff00';
  }

  function checkWin() {
    for (const condition of winConditions) {
      const [a, b, c] = condition;
      if (board[a] && board[a] === board[b] && board[a] === board[c]) {
        return condition;
      }
    }
    return null;
  }

  function aiMove() {
    if (!gameActive) return;

    // Try to win
    let move = findBestMove('O');
    // Try to block
    if (move === -1) move = findBestMove('X');
    // Take center
    if (move === -1 && board[4] === '') move = 4;
    // Take corners
    if (move === -1) {
      const corners = [0, 2, 6, 8].filter(i => board[i] === '');
      if (corners.length > 0) move = corners[Math.floor(Math.random() * corners.length)];
    }
    // Take any available
    if (move === -1) {
      const available = board.map((cell, i) => cell === '' ? i : null).filter(i => i !== null);
      if (available.length > 0) move = available[Math.floor(Math.random() * available.length)];
    }

    if (move !== -1) {
      makeMove(move, 'O');
    }
  }

  function findBestMove(player) {
    for (const condition of winConditions) {
      const [a, b, c] = condition;
      const cells = [board[a], board[b], board[c]];
      const playerCount = cells.filter(cell => cell === player).length;
      const emptyCount = cells.filter(cell => cell === '').length;
      if (playerCount === 2 && emptyCount === 1) {
        if (board[a] === '') return a;
        if (board[b] === '') return b;
        if (board[c] === '') return c;
      }
    }
    return -1;
  }

  function updateScores() {
    document.getElementById('scoreX').textContent = scores.X;
    document.getElementById('scoreO').textContent = scores.O;
    document.getElementById('scoreDraw').textContent = scores.draw;
  }

  function restartGame() {
    board = ['', '', '', '', '', '', '', '', ''];
    currentPlayer = 'X';
    gameActive = true;
    statusDisplay.textContent = "PLAYER X'S TURN";
    statusDisplay.style.color = '#ff00ff';
    statusDisplay.style.textShadow = '0 0 10px #ff00ff';
    statusDisplay.style.animation = 'pulse 1.5s infinite';

    cells.forEach(cell => {
      cell.textContent = '';
      cell.classList.remove('taken', 'x', 'o', 'win');
    });
  }

  function resetScores() {
    scores = { X: 0, O: 0, draw: 0 };
    updateScores();
    restartGame();
  }

  // Create stars background
  function createStars() {
    const starsContainer = document.getElementById('stars');
    for (let i = 0; i < 50; i++) {
      const star = document.createElement('div');
      star.className = 'star';
      star.style.left = Math.random() * 100 + '%';
      star.style.top = Math.random() * 100 + '%';
      star.style.animationDelay = Math.random() * 3 + 's';
      star.style.animationDuration = (Math.random() * 3 + 2) + 's';
      starsContainer.appendChild(star);
    }
  }

  createStars();

  // Keyboard support
  document.addEventListener('keydown', (e) => {
    if (e.key >= '1' && e.key <= '9') {
      const index = parseInt(e.key) - 1;
      handleClick(index);
    }
    if (e.key === 'r' || e.key === 'R') {
      restartGame();
    }
    if (e.key === 'Escape') {
      resetScores();
    }
  });
</script>

</body>
