// ==================== GAME START ====================
function startGame() {
  GameState.game.state = 'explore';
  GameState.dungeon.floor = 1;
  GameState.dungeon.room = 1;
  GameState.player.gold = 0;
  GameState.player.inventory = { fish: 3, milk: 1, catnip: 2, yarn: 1 };
  GameState.player.buffs = { atk: 0, def: 0 };
  GameState.game.totalKills = 0;
  GameState.game.totalFloors = 1;

  generateDungeon();
  renderDungeon();
  updatePlayerUI();
  updateStatusbar();

