  addLog('Use arrow keys to move. Find enemies to fight!', 'info');

  document.getElementById('statusField2').textContent = 'Exploring';
}

// ==================== DUNGEON GENERATION ====================
function generateDungeon() {
  const width = 10;
  const height = 8;
  GameState.dungeon.map = [];
  GameState.dungeon.revealed = [];
  GameState.dungeon.enemies = [];
  GameState.dungeon.items = [];

  // Initialize with walls
  for (let y = 0; y < height; y++) {
    GameState.dungeon.map[y] = [];
    GameState.dungeon.revealed[y] = [];
    for (let x = 0; x < width; x++) {
      GameState.dungeon.map[y][x] = 'wall';
      GameState.dungeon.revealed[y][x] = false;
    }
  }

  // Generate rooms using simple room placement
  const rooms = [];
  const numRooms = 4 + Math.floor(Math.random() * 3);

  for (let i = 0; i < numRooms; i++) {
    const rw = 2 + Math.floor(Math.random() * 3);
    const rh = 2 + Math.floor(Math.random() * 3);
    const rx = 1 + Math.floor(Math.random() * (width - rw - 2));
    const ry = 1 + Math.floor(Math.random() * (height - rh - 2));

    const room = { x: rx, y: ry, w: rw, h: rh };
    rooms.push(room);

    for (let y = ry; y < ry + rh; y++) {
      for (let x = rx; x < rx + rw; x++) {
        GameState.dungeon.map[y][x] = 'floor';
      }
    }
  }

  // Connect rooms with corridors
  for (let i = 0; i < rooms.length - 1; i++) {
    const r1 = rooms[i];
    const r2 = rooms[i + 1];
    const cx1 = Math.floor(r1.x + r1.w / 2);
    const cy1 = Math.floor(r1.y + r1.h / 2);
    const cx2 = Math.floor(r2.x + r2.w / 2);
    const cy2 = Math.floor(r2.y + r2.h / 2);

    let x = cx1;
    let y = cy1;

    while (x !== cx2) {
      GameState.dungeon.map[y][x] = 'floor';
      x += x < cx2 ? 1 : -1;
    }
    while (y !== cy2) {
      GameState.dungeon.map[y][x] = 'floor';
      y += y < cy2 ? 1 : -1;
    }
  }

  // Place player in first room
  GameState.dungeon.playerPos = { x: rooms[0].x + 1, y: rooms[0].y + 1 };

  // Place exit in last room
  const lastRoom = rooms[rooms.length - 1];
  GameState.dungeon.stairsPos = { x: lastRoom.x + Math.floor(lastRoom.w / 2), y: lastRoom.y + Math.floor(lastRoom.h / 2) };

  // Place enemies in random rooms (not first or last)
  for (let i = 1; i < rooms.length - 1; i++) {
    const room = rooms[i];
    const numEnemies = 1 + Math.floor(Math.random() * 2);
    for (let j = 0; j < numEnemies; j++) {
      const ex = room.x + Math.floor(Math.random() * room.w);
      const ey = room.y + Math.floor(Math.random() * room.h);
      if (GameState.dungeon.map[ey][ex] === 'floor') {
        const enemyTemplate = ENEMY_TEMPLATES[Math.floor(Math.random() * (ENEMY_TEMPLATES.length - 1))]; // Exclude boss
        const floorScale = 1 + (GameState.dungeon.floor - 1) * 0.2;
        GameState.dungeon.enemies.push({
          ...enemyTemplate,
          x: ex,
          y: ey,
          hp: Math.floor(enemyTemplate.hp * floorScale),
          maxHp: Math.floor(enemyTemplate.hp * floorScale),
          atk: Math.floor(enemyTemplate.atk * floorScale),
          def: Math.floor(enemyTemplate.def * floorScale),
          spd: Math.floor(enemyTemplate.spd * floorScale),
          alive: true
        });
      }
    }
  }

  // Place items
  for (let i = 0; i < 2; i++) {
    const room = rooms[Math.floor(Math.random() * rooms.length)];
    const ix = room.x + Math.floor(Math.random() * room.w);
    const iy = room.y + Math.floor(Math.random() * room.h);
    if (GameState.dungeon.map[iy][ix] === 'floor') {
      const itemTypes = ['fish', 'milk', 'catnip', 'yarn'];
      GameState.dungeon.items.push({
        x: ix,
        y: iy,
        type: itemTypes[Math.floor(Math.random() * itemTypes.length)],
        collected: false
      });
    }
  }

  // Reveal around player
  revealAround(GameState.dungeon.playerPos.x, GameState.dungeon.playerPos.y);

  GameState.dungeon.explored = true;
}

function revealAround(px, py) {
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const nx = px + dx;
      const ny = py + dy;
      if (ny >= 0 && ny < 8 && nx >= 0 && nx < 10) {
        GameState.dungeon.revealed[ny][nx] = true;
      }
    }
  }
}

// ==================== DUNGEON RENDERING ====================
function renderDungeon() {
  const grid = document.getElementById('dungeonGrid');
  grid.innerHTML = '';

  for (let y = 0; y < 8; y++) {
    for (let x = 0; x < 10; x++) {
      const cell = document.createElement('div');
      cell.className = 'dungeon-cell';

      if (!GameState.dungeon.revealed[y][x]) {
        cell.style.background = '#000';
        cell.style.visibility = 'hidden';
      } else {
        const tile = GameState.dungeon.map[y][x];
        cell.classList.add(tile);

        // Check for player
        if (x === GameState.dungeon.playerPos.x && y === GameState.dungeon.playerPos.y) {
          cell.classList.add('player');
          cell.textContent = GameState.player.sprite;
        }
        // Check for enemies
        else {
          const enemy = GameState.dungeon.enemies.find(e => e.x === x && e.y === y && e.alive);
          if (enemy) {
            cell.classList.add('enemy');
            cell.textContent = enemy.sprite;
          }
          // Check for stairs
          else if (GameState.dungeon.stairsPos && x === GameState.dungeon.stairsPos.x && y === GameState.dungeon.stairsPos.y) {
            cell.classList.add('stairs');
            cell.textContent = '🚪';
          }
          // Check for items
          else {
            const item = GameState.dungeon.items.find(i => i.x === x && i.y === y && !i.collected);
            if (item) {
              cell.classList.add('item');
              const itemIcons = { fish: '🐟', milk: '🥛', catnip: '🌿', yarn: '🧶' };
              cell.textContent = itemIcons[item.type] || '?';
            }
          }
        }
      }

      grid.appendChild(cell);
    }
  }
}

// ==================== PLAYER MOVEMENT ====================
function movePlayer(dx, dy) {
  if (GameState.game.state !== 'explore') return;

  const newX = GameState.dungeon.playerPos.x + dx;
  const newY = GameState.dungeon.playerPos.y + dy;

  // Bounds check
  if (newX < 0 || newX >= 10 || newY < 0 || newY >= 8) return;

  // Wall check
  if (GameState.dungeon.map[newY][newX] === 'wall') return;

  // Enemy check - initiate combat
  const enemy = GameState.dungeon.enemies.find(e => e.x === newX && e.y === newY && e.alive);
  if (enemy) {
    startCombat(enemy);
    return;
  }

  // Move player
  GameState.dungeon.playerPos.x = newX;
  GameState.dungeon.playerPos.y = newY;

  // Reveal area
  revealAround(newX, newY);

  // Check for items
  const item = GameState.dungeon.items.find(i => i.x === newX && i.y === newY && !i.collected);
  if (item) {
    item.collected = true;
    GameState.player.inventory[item.type] = (GameState.player.inventory[item.type] || 0) + 1;
    addLog(`Found ${item.type}!`, 'heal');
    updateInventoryUI();
  }

  // Check for stairs
  if (GameState.dungeon.stairsPos && newX === GameState.dungeon.stairsPos.x && newY === GameState.dungeon.stairsPos.y) {
    nextFloor();
    return;
  }

  // Check for special rooms
  checkSpecialRoom(newX, newY);

  renderDungeon();
  updateStatusbar();
}

function checkSpecialRoom(x, y) {
  // Simple room type detection based on position
  const roomCenter = findRoomCenter(x, y);
  if (!roomCenter) return;

  // Random chance for special rooms
  const rand = Math.random();
  if (rand < 0.15) {
    startTraining();
  } else if (rand < 0.25) {
    startShop();
  }
}

function findRoomCenter(x, y) {
  // Simple heuristic - find the nearest room center
  let minDist = Infinity;
  let center = null;

  for (let dy = -2; dy <= 2; dy++) {
    for (let dx = -2; dx <= 2; dx++) {
      const nx = x + dx;
      const ny = y + dy;
      if (ny >= 0 && ny < 8 && nx >= 0 && nx < 10) {
        if (GameState.dungeon.map[ny][nx] === 'floor') {
          const dist = Math.abs(dx) + Math.abs(dy);
          if (dist < minDist) {
            minDist = dist;
            center = { x: nx, y: ny };
          }
        }
      }
    }
  }

  return center;
}

function nextFloor() {
  GameState.dungeon.floor++;
  GameState.game.totalFloors = GameState.dungeon.floor;

  addLog(`Descending to Floor ${GameState.dungeon.floor}...`, 'info');
  addLog(`Floor ${GameState.dungeon.floor}: ${FLOOR_NAMES[(GameState.dungeon.floor - 1) % FLOOR_NAMES.length]}`, 'info');

  generateDungeon();
  renderDungeon();
  updatePlayerUI();
  updateStatusbar();

  document.getElementById('floorIndicator').textContent = `🏰 Floor ${GameState.dungeon.floor} - ${FLOOR_NAMES[(GameState.dungeon.floor - 1) % FLOOR_NAMES.length]}`;
  document.getElementById('roomLabel').textContent = `Room ${GameState.dungeon.room}/${GameState.dungeon.totalRooms} - ${ROOM_NAMES[(GameState.dungeon.floor - 1) % ROOM_NAMES.length]}`;

  // Heal partially on new floor
  const healAmount = Math.floor(GameState.player.maxHp * 0.2);
  GameState.player.hp = Math.min(GameState.player.maxHp, GameState.player.hp + healAmount);
  addLog(`Restored ${healAmount} HP at the new floor.`, 'heal');
  updatePlayerUI();
}

// ==================== COMBAT ====================
function startCombat(enemy) {
  GameState.game.state = 'combat';
  GameState.combat.active = true;
  GameState.combat.enemy = { ...enemy };
  GameState.combat.turn = 'player';
  GameState.combat.defending = false;
  GameState.combat.specialReady = true;

  // Show combat panel
  document.getElementById('dungeonPanel').classList.add('hidden');
  document.getElementById('combatPanel').classList.remove('hidden');
  document.getElementById('trainingPanel').classList.add('hidden');
  document.getElementById('shopPanel').classList.add('hidden');

  // Update combat UI
  document.getElementById('combatPlayerName').textContent = GameState.player.name;
  document.getElementById('combatPlayerSprite').textContent = GameState.player.sprite;
  document.getElementById('combatEnemyName').textContent = enemy.name;
  document.getElementById('combatEnemySprite').textContent = enemy.sprite;

  updateCombatUI();

  addLog(`Encountered ${enemy.name}!`, 'combat');
  document.getElementById('statusField2').textContent = 'In Combat';
}

function updateCombatUI() {
  const player = GameState.player;
  const enemy = GameState.combat.enemy;

  // Player HP
  const playerHpPercent = (player.hp / player.maxHp) * 100;
  document.getElementById('combatPlayerHPBar').style.width = playerHpPercent + '%';
  document.getElementById('combatPlayerHPBar').className = 'hp-bar' + (playerHpPercent < 25 ? ' low' : playerHpPercent < 50 ? ' medium' : '');
  document.getElementById('combatPlayerHPText').textContent = `${player.hp}/${player.maxHp}`;

  // Enemy HP
  const enemyHpPercent = (enemy.hp / enemy.maxHp) * 100;
  document.getElementById('combatEnemyHPBar').style.width = enemyHpPercent + '%';
  document.getElementById('combatEnemyHPBar').className = 'hp-bar' + (enemyHpPercent < 25 ? ' low' : enemyHpPercent < 50 ? ' medium' : '');
  document.getElementById('combatEnemyHPText').textContent = `${enemy.hp}/${enemy.maxHp}`;
}

function combatAction(action) {
  if (!GameState.combat.active || GameState.combat.turn !== 'player') return;

  const player = GameState.player;
  const enemy = GameState.combat.enemy;

  GameState.combat.defending = false;

  switch (action) {
    case 'attack':
      const atkDamage = Math.max(1, (player.atk + player.buffs.atk) - enemy.def + Math.floor(Math.random() * 3));
      enemy.hp -= atkDamage;
      addLog(`You attack ${enemy.name} for ${atkDamage} damage!`, 'combat');
      document.getElementById('combatEnemySprite').classList.add('shake');
      setTimeout(() => document.getElementById('combatEnemySprite').classList.remove('shake'), 300);
      break;

    case 'defend':
      GameState.combat.defending = true;
      addLog(`You take a defensive stance!`, 'info');
      break;

    case 'special':
      if (GameState.combat.specialReady) {
        const specialDamage = Math.max(1, (player.atk + player.buffs.atk) * 2 - Math.floor(enemy.def / 2) + Math.floor(Math.random() * 5));
        enemy.hp -= specialDamage;
        addLog(`✨ SPECIAL! You deal ${specialDamage} damage to ${enemy.name}!`, 'combat');
        GameState.combat.specialReady = false;
        document.getElementById('combatEnemySprite').classList.add('shake');
        setTimeout(() => document.getElementById('combatEnemySprite').classList.remove('shake'), 300);
      } else {
        addLog(`Special not ready!`, 'info');
        return;
      }
      break;

    case 'flee':
      if (Math.random() < 0.5 + player.spd * 0.05) {
        addLog(`You fled from ${enemy.name}!`, 'info');
        endCombat(false);
        return;
      } else {
        addLog(`Failed to flee!`, 'combat');
      }
      break;
  }

  // Check if enemy is dead
  if (enemy.hp <= 0) {
    enemy.hp = 0;
    updateCombatUI();
    addLog(`${enemy.name} was defeated!`, 'reward');
    addLog(`Gained ${enemy.xp} XP and ${enemy.gold} gold!`, 'reward');

    player.xp += enemy.xp;
    player.gold += enemy.gold;
    GameState.game.totalKills++;

    // Check level up
    while (player.xp >= player.xpToNext) {
      player.xp -= player.xpToNext;
      player.lvl++;
      player.xpToNext = Math.floor(player.xpToNext * 1.5);
      player.maxHp += 5;
      player.hp = player.maxHp;
      player.atk += 2;
      player.def += 1;
      player.spd += 1;
      addLog(`🎉 LEVEL UP! You are now level ${player.lvl}!`, 'levelup');
    }

    updateCombatUI();
    updatePlayerUI();
    updateInventoryUI();

    setTimeout(() => {
      endCombat(true);
    }, 1000);
    return;
  }

  updateCombatUI();

  // Enemy turn
  GameState.combat.turn = 'enemy';
  disableCombatButtons(true);

  setTimeout(() => {
    enemyTurn();
  }, 800);
}

function enemyTurn() {
  if (!GameState.combat.active) return;

  const player = GameState.player;
  const enemy = GameState.combat.enemy;

  let damage = Math.max(1, enemy.atk - (player.def + player.buffs.def) + Math.floor(Math.random() * 3));

  if (GameState.combat.defending) {
    damage = Math.floor(damage / 2);
    addLog(`Defended! ${enemy.name} attacks for ${damage} damage (reduced).`, 'combat');
  } else {
    addLog(`${enemy.name} attacks you for ${damage} damage!`, 'combat');
  }

  player.hp -= damage;
  document.getElementById('combatPlayerSprite').classList.add('shake');
  setTimeout(() => document.getElementById('combatPlayerSprite').classList.remove('shake'), 300);

  updateCombatUI();
  updatePlayerUI();

  // Check if player is dead
  if (player.hp <= 0) {
    player.hp = 0;
    updateCombatUI();
    updatePlayerUI();
    addLog(`💀 You have been defeated!`, 'combat');
    setTimeout(() => {
      endCombat(false);
      gameOver();
    }, 1500);
    return;
  }

  // Restore special if not used
  if (!GameState.combat.specialReady) {
    GameState.combat.specialReady = true;
  }

  GameState.combat.turn = 'player';
  disableCombatButtons(false);
}

function disableCombatButtons(disabled) {
  document.querySelectorAll('#combatActions button').forEach(btn => {
    btn.disabled = disabled;
  });
}

function endCombat(won) {
  GameState.combat.active = false;
  GameState.game.state = 'explore';

  document.getElementById('combatPanel').classList.add('hidden');
  document.getElementById('dungeonPanel').classList.remove('hidden');

  document.getElementById('statusField2').textContent = 'Exploring';

  if (won) {
    renderDungeon();
  }
}

// ==================== TRAINING ====================
function startTraining() {
  GameState.game.state = 'training';
  GameState.training.active = true;
  GameState.training.position = 0;
  GameState.training.speed = 2 + GameState.dungeon.floor * 0.5;
  GameState.training.target = 50 + Math.random() * 40;

  document.getElementById('dungeonPanel').classList.add('hidden');
  document.getElementById('combatPanel').classList.add('hidden');
  document.getElementById('trainingPanel').classList.remove('hidden');
  document.getElementById('shopPanel').classList.add('hidden');

  document.getElementById('trainingTarget').style.left = GameState.training.target + '%';
  document.getElementById('trainingFill').style.width = '0%';
  document.getElementById('trainingResult').textContent = '';
  document.getElementById('trainingStartBtn').disabled = false;
  document.getElementById('trainingClickBtn').disabled = true;

  addLog('Found a Training Room!', 'info');
  document.getElementById('statusField2').textContent = 'Training';
}

function clickTraining() {
  if (!GameState.training.active) return;

  const pos = GameState.training.position;
  const target = GameState.training.target;
  const diff = Math.abs(pos - target);

  if (diff < 5) {
    GameState.training.success++;
    document.getElementById('trainingResult').textContent = '🎉 Perfect! +3 ATK!';
    document.getElementById('trainingResult').style.color = '#008000';
    GameState.player.atk += 3;
  } else if (diff < 15) {
    GameState.training.success++;
    document.getElementById('trainingResult').textContent = '👍 Good! +1 ATK!';
    document.getElementById('trainingResult').style.color = '#008000';
    GameState.player.atk += 1;
  } else {
    GameState.training.fail++;
    document.getElementById('trainingResult').textContent = '❌ Miss! Try again!';
    document.getElementById('trainingResult').style.color = '#800000';
  }

  document.getElementById('trainingSuccess').textContent = GameState.training.success;
  document.getElementById('trainingFail').textContent = GameState.training.fail;

  GameState.training.active = false;
  cancelAnimationFrame(GameState.training.animationId);

  document.getElementById('trainingStartBtn').disabled = false;
  document.getElementById('trainingClickBtn').disabled = true;

  updatePlayerUI();

  setTimeout(() => {
    backToExplore();
  }, 1500);
}

function startTrainingAnimation() {
  GameState.training.active = true;
  GameState.training.position = 0;
  document.getElementById('trainingStartBtn').disabled = true;
  document.getElementById('trainingClickBtn').disabled = false;

  function animate() {
    GameState.training.position += GameState.training.speed;
    if (GameState.training.position >= 100) {
      GameState.training.position = 0;
    }
    document.getElementById('trainingFill').style.width = GameState.training.position + '%';
    GameState.training.animationId = requestAnimationFrame(animate);
  }
  animate();
}

// Override the start training button
function startTraining() {
  startTrainingAnimation();
}

function backToExplore() {
  GameState.game.state = 'explore';
  document.getElementById('trainingPanel').classList.add('hidden');
  document.getElementById('dungeonPanel').classList.remove('hidden');
  document.getElementById('statusField2').textContent = 'Exploring';
  renderDungeon();
}

// ==================== SHOP ====================
function startShop() {
  GameState.game.state = 'shop';

  document.getElementById('dungeonPanel').classList.add('hidden');
  document.getElementById('combatPanel').classList.add('hidden');
  document.getElementById('trainingPanel').classList.add('hidden');
  document.getElementById('shopPanel').classList.remove('hidden');

  addLog('Found a Cat Supply Shop!', 'info');
  document.getElementById('statusField2').textContent = 'Shopping';
}

function buyItem(type, cost) {
  if (GameState.player.gold < cost) {
    addLog('Not enough gold!', 'combat');
    return;
  }

  GameState.player.gold -= cost;

  switch (type) {
