        </svg>
        <svg class="star-icon" id="star3" viewBox="0 0 40 40">
            <polygon points="20,2 25,15 39,15 28,24 32,38 20,30 8,38 12,24 1,15 15,15" fill="#FFD700" stroke="#FFA500" stroke-width="2"/>
        </svg>
