<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

let W, H;
function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
}
resize();
window.addEventListener('resize', resize);

// Game state
const GRAVITY = 0.4;
const AIR_RESISTANCE = 0.995;
const BOUNCE = 0.3;

let gameState = 'playing'; // playing, won, lost
let starsCollected = 0;
let cutLines = [];
let particles = [];
let trailParticles = [];

// Om Nom
const omNom = {
    x: 0, y: 0,
    radius: 35,
    mouthOpen: 0,
    targetMouthOpen: 0,
    eyeScale: 1,
    expression: 'happy'
};

// Candy
const candy = {
    x: 0, y: 0,
    vx: 0, vy: 0,
    radius: 15,
    attached: true,
    rope: null,
    rotation: 0,
    eaten: false
};

// Ropes
let ropes = [];
let stars = [];
let obstacles = [];
let airZones = [];

function initLevel() {
    gameState = 'playing';
    starsCollected = 0;
    cutLines = [];
    particles = [];
    trailParticles = [];

    document.getElementById('star1').classList.remove('collected');
    document.getElementById('star2').classList.remove('collected');
    document.getElementById('star3').classList.remove('collected');
    document.getElementById('message').classList.remove('show');
    document.getElementById('restart-btn').style.display = 'none';
    document.getElementById('cut-hint').style.display = 'block';

    // Om Nom position (bottom center)
    omNom.x = W / 2;
    omNom.y = H - 120;
    omNom.mouthOpen = 0;
    omNom.targetMouthOpen = 0;

    // Candy starting position
    candy.x = W / 2;
    candy.y = 100;
    candy.vx = 0;
    candy.vy = 0;
    candy.attached = true;
    candy.rotation = 0;
    candy.eaten = false;

    // Create ropes for medium level
    ropes = [];

    // Main rope from top center
    ropes.push({
        x1: W / 2, y1: 0,
        x2: candy.x, y2: candy.y,
        length: 100,
        cut: false,
        color: '#8B4513',
        thickness: 4
    });

    // Secondary rope from left (creates pendulum challenge)
    ropes.push({
        x1: W * 0.2, y1: 0,
        x2: W * 0.2, y2: 150,
        length: 150,
        cut: false,
        color: '#8B4513',
        thickness: 4
    });

    // Third rope from right
    ropes.push({
        x1: W * 0.8, y1: 0,
        x2: W * 0.8, y2: 200,
        length: 200,
        cut: false,
        color: '#8B4513',
        thickness: 4
    });

    // Connect candy to secondary rope temporarily
    ropes[1].connectedCandy = true;
    ropes[1].connectX = W * 0.2;
    ropes[1].connectY = 150;

    // Stars positions
    stars = [
        { x: W * 0.2, y: H * 0.35, collected: false, radius: 18, angle: 0 },
        { x: W * 0.5, y: H * 0.55, collected: false, radius: 18, angle: 0 },
        { x: W * 0.8, y: H * 0.35, collected: false, radius: 18, angle: 0 }
    ];

    // Obstacles - bubbles that push candy up
    airZones = [
        { x: W * 0.35, y: H * 0.45, radius: 50, strength: 0.15 },
        { x: W * 0.65, y: H * 0.45, radius: 50, strength: 0.15 }
    ];

    // Walls/obstacles
    obstacles = [
        // Left wall segment
        { x: W * 0.15, y: H * 0.6, w: 15, h: 100, type: 'wall' },
        // Right wall segment
        { x: W * 0.85, y: H * 0.6, w: 15, h: 100, type: 'wall' },
        // Middle obstacle
        { x: W * 0.45, y: H * 0.5, w: 100, h: 15, type: 'wall' }
    ];
}

// Physics simulation
function updateCandy() {
    if (candy.eaten || gameState !== 'playing') return;

    let attachedRope = null;
    let anchorX = candy.x;
    let anchorY = candy.y;

    // Check which rope candy is attached to
    for (let rope of ropes) {
        if (!rope.cut && rope.connectedCandy) {
            attachedRope = rope;
            anchorX = rope.x1;
            anchorY = rope.y1;
            break;
        }
    }

    if (attachedRope) {
        // Pendulum physics
        let dx = candy.x - anchorX;
        let dy = candy.y - anchorY;
        let dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > attachedRope.length) {
            // Constrain to rope length
            let nx = dx / dist;
            let ny = dy / dist;
            candy.x = anchorX + nx * attachedRope.length;
            candy.y = anchorY + ny * attachedRope.length;

            // Remove velocity component along rope
            let dot = candy.vx * nx + candy.vy * ny;
            if (dot > 0) {
                candy.vx -= dot * nx;
                candy.vy -= dot * ny;
            }
        }

        // Update rope visual
        attachedRope.x2 = candy.x;
        attachedRope.y2 = candy.y;
    } else {
        // Free fall with gravity
        candy.vy += GRAVITY;
        candy.vx *= AIR_RESISTANCE;
        candy.vy *= AIR_RESISTANCE;

        candy.x += candy.vx;
        candy.y += candy.vy;
    }

    // Air zone effects
    for (let zone of airZones) {
        let dx = candy.x - zone.x;
        let dy = candy.y - zone.y;
        let dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < zone.radius) {
            let force = zone.strength * (1 - dist / zone.radius);
            candy.vy -= force;
            candy.vx += (dx / dist) * force * 0.5;
        }
    }

    // Wall collisions
    for (let obs of obstacles) {
        if (candy.x + candy.radius > obs.x && candy.x - candy.radius < obs.x + obs.w &&
            candy.y + candy.radius > obs.y && candy.y - candy.radius < obs.y + obs.h) {

            // Determine collision side
            let overlapLeft = (candy.x + candy.radius) - obs.x;
            let overlapRight = (obs.x + obs.w) - (candy.x - candy.radius);
            let overlapTop = (candy.y + candy.radius) - obs.y;
            let overlapBottom = (obs.y + obs.h) - (candy.y - candy.radius);

            let minOverlap = Math.min(overlapLeft, overlapRight, overlapTop, overlapBottom);

            if (minOverlap === overlapLeft) {
                candy.x = obs.x - candy.radius;
                candy.vx = -candy.vx * BOUNCE;
            } else if (minOverlap === overlapRight) {
                candy.x = obs.x + obs.w + candy.radius;
                candy.vx = -candy.vx * BOUNCE;
            } else if (minOverlap === overlapTop) {
                candy.y = obs.y - candy.radius;
                candy.vy = -candy.vy * BOUNCE;
            } else {
                candy.y = obs.y + obs.h + candy.radius;
                candy.vy = -candy.vy * BOUNCE;
            }
        }
    }

    // Screen bounds
    if (candy.x < candy.radius) {
        candy.x = candy.radius;
        candy.vx = -candy.vx * BOUNCE;
    }
    if (candy.x > W - candy.radius) {
        candy.x = W - candy.radius;
        candy.vx = -candy.vx * BOUNCE;
    }
    if (candy.y < candy.radius) {
        candy.y = candy.radius;
        candy.vy = -candy.vy * BOUNCE;
    }

    // Rotation
    candy.rotation += candy.vx * 0.05;

    // Trail particles
    if (Math.abs(candy.vx) + Math.abs(candy.vy) > 2) {
        trailParticles.push({
            x: candy.x,
            y: candy.y,
            life: 1,
            radius: 3
        });
    }

    // Check star collection
    for (let star of stars) {
        if (!star.collected) {
            let dx = candy.x - star.x;
            let dy = candy.y - star.y;
            let dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < candy.radius + star.radius) {
                star.collected = true;
                starsCollected++;
                starCollectEffect(star.x, star.y);

                let starIdx = stars.indexOf(star);
                document.getElementById('star' + (starIdx + 1)).classList.add('collected');
            }
        }
    }

    // Check if candy reaches Om Nom
    let dx = candy.x - omNom.x;
    let dy = candy.y - omNom.y;
    let dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < omNom.radius + candy.radius) {
        candy.eaten = true;
        omNomMouthOpen();
        setTimeout(() => {
            if (starsCollected >= 3) {
                winLevel();
            } else if (starsCollected >= 1) {
                showMessage('Good! ' + starsCollected + '/3 ⭐\nTap Restart to try for more!', 3000);
            } else {
                showMessage('Not bad! ' + starsCollected + '/3 ⭐\nTap Restart to try for more!', 3000);
            }
            document.getElementById('restart-btn').style.display = 'block';
        }, 1000);
    }

    // Check if candy fell off screen
    if (candy.y > H + 50) {
        loseLevel();
    }
}

function omNomMouthOpen() {
    omNom.targetMouthOpen = 1;
    setTimeout(() => {
        omNom.targetMouthOpen = 0;
    }, 500);
}

function winLevel() {
    gameState = 'won';
    showMessage('🎉 Perfect! 3/3 ⭐\nOm Nom is happy!', 5000);
    document.getElementById('restart-btn').style.display = 'block';
    celebrateEffect();
}

function loseLevel() {
    gameState = 'lost';
    showMessage('😢 Om Nom is hungry!\nTap Restart to try again', 3000);
    document.getElementById('restart-btn').style.display = 'block';
}

function showMessage(text, duration) {
    const msg = document.getElementById('message');
    msg.textContent = text;
    msg.classList.add('show');
    if (duration) {
        setTimeout(() => {
            msg.classList.remove('show');
        }, duration);
    }
}

function starCollectEffect(x, y) {
    for (let i = 0; i < 15; i++) {
        particles.push({
            x: x,
            y: y,
            vx: (Math.random() - 0.5) * 8,
            vy: (Math.random() - 0.5) * 8,
            life: 1,
            color: '#FFD700',
            radius: Math.random() * 4 + 2
        });
    }
}

function celebrateEffect() {
    for (let i = 0; i < 50; i++) {
        particles.push({
            x: W / 2,
            y: H / 2,
            vx: (Math.random() - 0.5) * 15,
            vy: (Math.random() - 0.5) * 15,
            life: 1,
            color: ['#FFD700', '#FF6B6B', '#4ECDC4', '#45B7D1'][Math.floor(Math.random() * 4)],
            radius: Math.random() * 6 + 2
        });
    }
}

// Cutting ropes
let isCutting = false;
let cutPath = [];

function startCut(x, y) {
    if (gameState !== 'playing') return;
    isCutting = true;
    cutPath = [{ x, y }];
    document.getElementById('cut-hint').style.display = 'none';
}

function continueCut(x, y) {
    if (!isCutting) return;
    cutPath.push({ x, y });

    // Check if cutting any rope
    for (let rope of ropes) {
        if (rope.cut) continue;

        if (rope.connectedCandy) {
            // Check distance from cut path to rope segment
            for (let point of cutPath) {
                if (lineIntersectsPoint(rope.x1, rope.y1, rope.x2, rope.y2, point.x, point.y, 15)) {
                    rope.cut = true;
                    rope.connectedCandy = false;
                    cutEffect(rope.x1, rope.y1);
                    cutEffect(rope.x2, rope.y2);
                    break;
                }
            }
        } else {
            for (let point of cutPath) {
                if (lineIntersectsPoint(rope.x1, rope.y1, rope.x2, rope.y2, point.x, point.y, 15)) {
                    rope.cut = true;
                    cutEffect(rope.x1, rope.y1);
                    cutEffect(rope.x2, rope.y2);
                    break;
                }
            }
        }
    }
}

function endCut() {
    isCutting = false;
    cutPath = [];
}

function lineIntersectsPoint(x1, y1, x2, y2, px, py, threshold) {
    let dx = x2 - x1;
    let dy = y2 - y1;
    let len = Math.sqrt(dx * dx + dy * dy);
    if (len === 0) return false;

    let t = ((px - x1) * dx + (py - y1) * dy) / (len * len);
    t = Math.max(0, Math.min(1, t));

    let closestX = x1 + t * dx;
    let closestY = y1 + t * dy;

    let dist = Math.sqrt((px - closestX) ** 2 + (py - closestY) ** 2);
    return dist < threshold;
}

function cutEffect(x, y) {
    for (let i = 0; i < 8; i++) {
        particles.push({
            x: x,
            y: y,
            vx: (Math.random() - 0.5) * 6,
            vy: (Math.random() - 0.5) * 6,
            life: 1,
            color: '#8B4513',
            radius: Math.random() * 3 + 1
        });
    }
}

// Touch events
canvas.addEventListener('touchstart', (e) => {
    e.preventDefault();
    let touch = e.touches[0];
    startCut(touch.clientX, touch.clientY);
});

canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    let touch = e.touches[0];
    continueCut(touch.clientX, touch.clientY);
});

canvas.addEventListener('touchend', (e) => {
    e.preventDefault();
    endCut();
});

// Mouse events for desktop testing
canvas.addEventListener('mousedown', (e) => {
    startCut(e.clientX, e.clientY);
});

canvas.addEventListener('mousemove', (e) => {
    continueCut(e.clientX, e.clientY);
});

canvas.addEventListener('mouseup', (e) => {
    endCut();
});

// Restart button
document.getElementById('restart-btn').addEventListener('click', () => {
    initLevel();
});

// Drawing functions
function drawBackground() {
    // Gradient background
    let grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, '#2d1b69');
    grad.addColorStop(0.5, '#1a1a2e');
    grad.addColorStop(1, '#16213e');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // Stars in background
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    for (let i = 0; i < 50; i++) {
        let x = (i * 137.5) % W;
        let y = (i * 97.3) % H;
        ctx.beginPath();
        ctx.arc(x, y, 1, 0, Math.PI * 2);
        ctx.fill();
    }

    // Ground
    let groundGrad = ctx.createLinearGradient(0, H - 60, 0, H);
    groundGrad.addColorStop(0, '#2d5a27');
    groundGrad.addColorStop(1, '#1a3a15');
    ctx.fillStyle = groundGrad;
    ctx.fillRect(0, H - 60, W, 60);

    // Grass tufts
    ctx.fillStyle = '#3d7a37';
    for (let i = 0; i < W; i += 20) {
        ctx.beginPath();
        ctx.moveTo(i, H - 60);
        ctx.lineTo(i + 5, H - 75);
        ctx.lineTo(i + 10, H - 60);
        ctx.fill();
    }
}

function drawRope(rope) {
    if (rope.cut) return;

    ctx.strokeStyle = rope.color;
    ctx.lineWidth = rope.thickness;
    ctx.lineCap = 'round';

    // Draw rope with slight curve
    ctx.beginPath();
    ctx.moveTo(rope.x1, rope.y1);

    let midX = (rope.x1 + rope.x2) / 2;
    let midY = (rope.y1 + rope.y2) / 2 + 10;
    ctx.quadraticCurveTo(midX, midY, rope.x2, rope.y2);
    ctx.stroke();

    // Rope highlight
    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(rope.x1, rope.y1);
    ctx.quadraticCurveTo(midX, midY, rope.x2, rope.y2);
    ctx.stroke();

    // Anchor point
    ctx.fillStyle = '#666';
    ctx.beginPath();
    ctx.arc(rope.x1, rope.y1, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#888';
    ctx.beginPath();
    ctx.arc(rope.x1, rope.y1, 3, 0, Math.PI * 2);
    ctx.fill();
}

function drawCandy() {
    if (candy.eaten) return;

    ctx.save();
    ctx.translate(candy.x, candy.y);
    ctx.rotate(candy.rotation);

    // Candy body
    let candyGrad = ctx.createRadialGradient(-3, -3, 0, 0, 0, candy.radius);
    candyGrad.addColorStop(0, '#ff6b6b');
    candyGrad.addColorStop(0.5, '#ee5a24');
    candyGrad.addColorStop(1, '#c0392b');
    ctx.fillStyle = candyGrad;
    ctx.beginPath();
    ctx.arc(0, 0, candy.radius, 0, Math.PI * 2);
    ctx.fill();

    // Candy stripes
    ctx.strokeStyle = 'rgba(255,255,255,0.4)';
    ctx.lineWidth = 2;
    for (let i = -2; i <= 2; i++) {
        ctx.beginPath();
        ctx.arc(0, 0, candy.radius * 0.6, i * 0.5, i * 0.5 + 1);
        ctx.stroke();
    }

    // Candy highlight
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.beginPath();
    ctx.arc(-4, -4, 5, 0, Math.PI * 2);
    ctx.fill();

    // Candy wrapper ends
    ctx.fillStyle = '#ffeb3b';
    ctx.beginPath();
    ctx.ellipse(-candy.radius - 3, 0, 6, 4, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(candy.radius + 3, 0, 6, 4, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
}

function drawOmNom() {
    ctx.save();
    ctx.translate(omNom.x, omNom.y);

    // Animate mouth
    omNom.mouthOpen += (omNom.targetMouthOpen - omNom.mouthOpen) * 0.2;

    // Body
    let bodyGrad = ctx.createRadialGradient(-5, -5, 0, 0, 0, omNom.radius);
    bodyGrad.addColorStop(0, '#7bed9f');
    bodyGrad.addColorStop(0.5, '#2ed573');
    bodyGrad.addColorStop(1, '#1e8449');
    ctx.fillStyle = bodyGrad;
    ctx.beginPath();
    ctx.arc(0, 0, omNom.radius, 0, Math.PI * 2);
    ctx.fill();

    // Body outline
    ctx.strokeStyle = '#1e8449';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Eyes
    let eyeY = -8;
    let eyeSpacing = 12;

    // Left eye
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.ellipse(-eyeSpacing, eyeY, 10, 12 * omNom.eyeScale, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Right eye
    ctx.beginPath();
    ctx.ellipse(eyeSpacing, eyeY, 10, 12 * omNom.eyeScale, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // Pupils
    let pupilOffsetX = (candy.x - omNom.x) * 0.02;
    let pupilOffsetY = (candy.y - omNom.y) * 0.02;
    pupilOffsetX = Math.max(-3, Math.min(3, pupilOffsetX));
    pupilOffsetY = Math.max(-3, Math.min(3, pupilOffsetY));

    ctx.fillStyle = '#333';
    ctx.beginPath();
    ctx.arc(-eyeSpacing + pupilOffsetX, eyeY + pupilOffsetY, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(eyeSpacing + pupilOffsetX, eyeY + pupilOffsetY, 5, 0, Math.PI * 2);
    ctx.fill();

    // Eye highlights
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(-eyeSpacing + pupilOffsetX - 2, eyeY + pupilOffsetY - 2, 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(eyeSpacing + pupilOffsetX - 2, eyeY + pupilOffsetY - 2, 2, 0, Math.PI * 2);
    ctx.fill();

    // Mouth
    let mouthOpen = omNom.mouthOpen * 15;
    ctx.fillStyle = '#c0392b';
    ctx.beginPath();
    ctx.ellipse(0, 10 + mouthOpen * 0.3, 12 + mouthOpen * 0.5, 8 + mouthOpen, 0, 0, Math.PI * 2);
    ctx.fill();

    // Teeth
    if (mouthOpen > 5) {
        ctx.fillStyle = '#fff';
        ctx.fillRect(-8, 8, 6, 4);
        ctx.fillRect(2, 8, 6, 4);
    }

    // Feet
    ctx.fillStyle = '#2ed573';
    ctx.beginPath();
    ctx.ellipse(-15, omNom.radius - 5, 10, 6, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(15, omNom.radius - 5, 10, 6, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
}

function drawStars() {
    for (let star of stars) {
        if (star.collected) continue;

        star.angle += 0.02;

        ctx.save();
        ctx.translate(star.x, star.y);
        ctx.rotate(star.angle);

        // Star glow
        ctx.shadowColor = '#FFD700';
        ctx.shadowBlur = 15;

        // Star shape
        ctx.fillStyle = '#FFD700';
        ctx.beginPath();
        for (let i = 0; i < 5; i++) {
            let angle = (i * 4 * Math.PI) / 5 - Math.PI / 2;
            let x = Math.cos(angle) * star.radius;
            let y = Math.sin(angle) * star.radius;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.fill();

        // Star inner
        ctx.fillStyle = '#FFA500';
        ctx.beginPath();
        for (let i = 0; i < 5; i++) {
            let angle = (i * 4 * Math.PI) / 5 - Math.PI / 2;
            let x = Math.cos(angle) * star.radius * 0.5;
            let y = Math.sin(angle) * star.radius * 0.5;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.fill();

        ctx.shadowBlur = 0;
        ctx.restore();
    }
}

function drawObstacles() {
    for (let obs of obstacles) {
        let grad = ctx.createLinearGradient(obs.x, obs.y, obs.x + obs.w, obs.y + obs.h);
        grad.addColorStop(0, '#5a5a5a');
        grad.addColorStop(1, '#3a3a3a');
        ctx.fillStyle = grad;
        ctx.fillRect(obs.x, obs.y, obs.w, obs.h);

        // Highlight
        ctx.fillStyle = 'rgba(255,255,255,0.1)';
        ctx.fillRect(obs.x, obs.y, obs.w, 3);
    }
}

function drawAirZones() {
    for (let zone of airZones) {
        ctx.strokeStyle = 'rgba(100,200,255,0.3)';
        ctx.lineWidth = 2;
        ctx.setLineDash([5, 5]);
        ctx.beginPath();
        ctx.arc(zone.x, zone.y, zone.radius, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);

        // Bubble particles
        ctx.fillStyle = 'rgba(100,200,255,0.1)';
        for (let i = 0; i < 5; i++) {
            let angle = (Date.now() / 1000 + i * 1.2) % (Math.PI * 2);
            let r = zone.radius * 0.5;
            let bx = zone.x + Math.cos(angle) * r;
            let by = zone.y + Math.sin(angle) * r;
            ctx.beginPath();
            ctx.arc(bx, by, 3, 0, Math.PI * 2);
            ctx.fill();
        }
    }
}

function drawCutLines() {
    if (cutPath.length < 2) return;

    ctx.strokeStyle = 'rgba(255,255,255,0.8)';
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(cutPath[0].x, cutPath[0].y);
    for (let i = 1; i < cutPath.length; i++) {
        ctx.lineTo(cutPath[i].x, cutPath[i].y);
    }
    ctx.stroke();
}

function drawParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.1;
        p.life -= 0.02;

        if (p.life <= 0) {
            particles.splice(i, 1);
            continue;
        }

        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.radius * p.life, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.globalAlpha = 1;
}

function drawTrailParticles() {
    for (let i = trailParticles.length - 1; i >= 0; i--) {
        let p = trailParticles[i];
        p.life -= 0.03;

        if (p.life <= 0) {
            trailParticles.splice(i, 1);
            continue;
        }

        ctx.globalAlpha = p.life * 0.5;
        ctx.fillStyle = '#ff6b6b';
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.radius * p.life, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.globalAlpha = 1;
}

// Main game loop
function gameLoop() {
    updateCandy();

    drawBackground();
    drawAirZones();
    drawObstacles();

    for (let rope of ropes) {
        drawRope(rope);
    }

    drawTrailParticles();
    drawStars();
    drawCandy();
    drawOmNom();
    drawCutLines();
    drawParticles();

    requestAnimationFrame(gameLoop);
}

// Initialize and start
initLevel();
gameLoop();
</script>
</body>
