<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const overlay = document.getElementById('overlay');
const startBtn = document.getElementById('startBtn');
const scoreDisplay = document.getElementById('score');
const livesDisplay = document.getElementById('lives');

canvas.width = 900;
canvas.height = 600;

let gameRunning = false;
let gameTime = 0;
let lastTime = 0;
let lives = 3;
let enemies = [];
let particles = [];
let stars = [];
let powerups = [];
let screenShake = 0;
let difficulty = 1;
let invincible = false;
let invincibleTimer = 0;
let speedBoost = false;
let speedBoostTimer = 0;
let trailParticles = [];

const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    width: 40,
    height: 50,
    speed: 5,
    vx: 0,
    vy: 0,
    direction: 1,
    frame: 0,
    frameTimer: 0,
    running: false
};

const keys = {};

document.addEventListener('keydown', (e) => {
    keys[e.key.toLowerCase()] = true;
    keys[e.code] = true;
});

document.addEventListener('keyup', (e) => {
    keys[e.key.toLowerCase()] = false;
    keys[e.code] = false;
});

startBtn.addEventListener('click', startGame);

function startGame() {
    overlay.classList.add('hidden');
    gameRunning = true;
    gameTime = 0;
    lives = 3;
    difficulty = 1;
    enemies = [];
    particles = [];
    stars = [];
    powerups = [];
    trailParticles = [];
    player.x = canvas.width / 2;
    player.y = canvas.height / 2;
    player.vx = 0;
    player.vy = 0;
    invincible = false;
    speedBoost = false;
    updateLives();
    spawnEnemies();
    spawnStars();
    lastTime = performance.now();
    requestAnimationFrame(gameLoop);
}

function updateLives() {
    let hearts = '';
    for (let i = 0; i < lives; i++) hearts += '❤️';
    for (let i = lives; i < 3; i++) hearts += '🖤';
    livesDisplay.textContent = hearts;
}

function spawnEnemies() {
    const count = Math.min(3 + Math.floor(gameTime / 10), 12);
    while (enemies.length < count) {
        const side = Math.floor(Math.random() * 4);
        let x, y;
        switch(side) {
            case 0: x = Math.random() * canvas.width; y = -50; break;
            case 1: x = canvas.width + 50; y = Math.random() * canvas.height; break;
            case 2: x = Math.random() * canvas.width; y = canvas.height + 50; break;
            case 3: x = -50; y = Math.random() * canvas.height; break;
        }
        enemies.push({
            x: x,
            y: y,
            width: 35,
            height: 45,
            speed: 1.5 + Math.random() * 1.5 + difficulty * 0.3,
            frame: 0,
            frameTimer: 0,
            type: Math.random() > 0.7 ? 'fast' : 'normal',
            attackTimer: 0
        });
    }
}

function spawnStars() {
    if (stars.length < 3 + Math.floor(gameTime / 15)) {
        stars.push({
            x: 50 + Math.random() * (canvas.width - 100),
            y: 50 + Math.random() * (canvas.height - 100),
            size: 15,
            frame: 0,
            frameTimer: 0,
            type: Math.random() > 0.5 ? 'life' : 'speed'
        });
    }
}

function createParticles(x, y, color, count, spread) {
    for (let i = 0; i < count; i++) {
        particles.push({
            x: x,
            y: y,
            vx: (Math.random() - 0.5) * spread,
            vy: (Math.random() - 0.5) * spread,
            life: 1,
            decay: 0.02 + Math.random() * 0.03,
            color: color,
            size: 2 + Math.random() * 4
        });
    }
}

function createTrail(x, y) {
    trailParticles.push({
        x: x,
        y: y,
        life: 1,
        decay: 0.05,
        size: 8 + Math.random() * 4
    });
}

function updatePlayer(dt) {
    let dx = 0;
    let dy = 0;

    if (keys['arrowleft'] || keys['a']) dx -= 1;
    if (keys['arrowright'] || keys['d']) dx += 1;
    if (keys['arrowup'] || keys['w']) dy -= 1;
    if (keys['arrowdown'] || keys['s']) dy += 1;

    if (dx !== 0 || dy !== 0) {
        const len = Math.sqrt(dx * dx + dy * dy);
        dx /= len;
        dy /= len;
        player.running = true;
    } else {
        player.running = false;
    }

    const currentSpeed = speedBoost ? player.speed * 1.8 : player.speed;
    player.vx = dx * currentSpeed;
    player.vy = dy * currentSpeed;

    player.x += player.vx;
    player.y += player.vy;

    if (dx !== 0) player.direction = dx > 0 ? 1 : -1;

    player.x = Math.max(player.width / 2, Math.min(canvas.width - player.width / 2, player.x));
    player.y = Math.max(player.height / 2, Math.min(canvas.height - player.height / 2, player.y));

    player.frameTimer += dt;
    if (player.frameTimer > 100) {
        player.frame = (player.frame + 1) % 4;
        player.frameTimer = 0;
    }

    if (player.running && Math.random() > 0.5) {
        createTrail(player.x, player.y + player.height / 2);
    }

    if (invincible) {
        invincibleTimer -= dt;
        if (invincibleTimer <= 0) invincible = false;
    }

    if (speedBoost) {
        speedBoostTimer -= dt;
        if (speedBoostTimer <= 0) speedBoost = false;
    }
}

function updateEnemies(dt) {
    enemies.forEach((enemy, index) => {
        const dx = player.x - enemy.x;
        const dy = player.y - enemy.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > 0) {
            const speed = enemy.type === 'fast' ? enemy.speed * 1.5 : enemy.speed;
            enemy.x += (dx / dist) * speed;
            enemy.y += (dy / dist) * speed;
        }

        enemy.frameTimer += dt;
        if (enemy.frameTimer > 150) {
            enemy.frame = (enemy.frame + 1) % 4;
            enemy.frameTimer = 0;
        }

        if (dist < (player.width + enemy.width) / 2.5) {
            if (!invincible) {
                lives--;
                updateLives();
                screenShake = 15;
                createParticles(player.x, player.y, '#ff0000', 20, 8);
                createParticles(enemy.x, enemy.y, '#8B0000', 15, 6);

                if (lives <= 0) {
                    gameOver();
                    return;
                }

                invincible = true;
                invincibleTimer = 2000;

                const pushDir = Math.atan2(dy, dx);
                player.x += Math.cos(pushDir) * 100;
                player.y += Math.sin(pushDir) * 100;
                player.x = Math.max(player.width / 2, Math.min(canvas.width - player.width / 2, player.x));
                player.y = Math.max(player.height / 2, Math.min(canvas.height - player.height / 2, player.y));
            }
        }
    });

    if (screenShake > 0) screenShake--;
}

function updateStars(dt) {
    stars.forEach((star, index) => {
        star.frameTimer += dt;
        if (star.frameTimer > 200) {
            star.frame = (star.frame + 1) % 3;
            star.frameTimer = 0;
        }

        const dx = player.x - star.x;
        const dy = player.y - star.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < 30) {
            if (star.type === 'life') {
                if (lives < 3) lives++;
                updateLives();
                createParticles(star.x, star.y, '#ff6b6b', 15, 6);
            } else {
                speedBoost = true;
                speedBoostTimer = 5000;
                createParticles(star.x, star.y, '#ffd93d', 15, 6);
            }
            stars.splice(index, 1);
        }
    });
}

function updateParticles(dt) {
    particles = particles.filter(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        p.vy += 0.1;
        return p.life > 0;
    });

    trailParticles = trailParticles.filter(p => {
        p.life -= p.decay;
        return p.life > 0;
    });
}

function drawPlayer() {
    ctx.save();
    ctx.translate(player.x, player.y);

    if (invincible && Math.floor(Date.now() / 100) % 2 === 0) {
        ctx.globalAlpha = 0.5;
    }

    const scale = player.direction;
    ctx.scale(scale, 1);

    // Body
    ctx.fillStyle = '#4ECDC4';
    ctx.beginPath();
    ctx.ellipse(0, 5, 15, 20, 0, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.fillStyle = '#FFE66D';
    ctx.beginPath();
    ctx.arc(0, -18, 14, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#333';
    ctx.beginPath();
    ctx.arc(-5, -20, 3, 0, Math.PI * 2);
    ctx.arc(5, -20, 3, 0, Math.PI * 2);
    ctx.fill();

    // Eye shine
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(-4, -21, 1.5, 0, Math.PI * 2);
    ctx.arc(6, -21, 1.5, 0, Math.PI * 2);
    ctx.fill();

    // Mouth
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, -14, 4, 0, Math.PI);
    ctx.stroke();

    // Hair
    ctx.fillStyle = '#8B4513';
    ctx.beginPath();
    ctx.arc(0, -26, 10, Math.PI, 0);
    ctx.fill();

    // Legs animation
    const legOffset = player.running ? Math.sin(player.frame * Math.PI / 2) * 8 : 0;
    ctx.fillStyle = '#4ECDC4';
    ctx.fillRect(-8, 22, 6, 12 + legOffset);
    ctx.fillRect(2, 22, 6, 12 - legOffset);

    // Shoes
    ctx.fillStyle = '#E74C3C';
    ctx.fillRect(-9, 32 + legOffset, 8, 4);
    ctx.fillRect(1, 32 - legOffset, 8, 4);

    // Arms
    const armOffset = player.running ? Math.sin(player.frame * Math.PI / 2) * 15 : 0;
    ctx.fillStyle = '#FFE66D';
    ctx.save();
    ctx.translate(-14, -5);
    ctx.rotate((-20 + armOffset) * Math.PI / 180);
    ctx.fillRect(-3, 0, 6, 15);
    ctx.restore();

    ctx.save();
    ctx.translate(14, -5);
    ctx.rotate((20 - armOffset) * Math.PI / 180);
    ctx.fillRect(-3, 0, 6, 15);
    ctx.restore();

    // Speed boost effect
    if (speedBoost) {
        ctx.strokeStyle = '#ffd93d';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, 25, 0, Math.PI * 2);
        ctx.stroke();
    }

    ctx.restore();
}

function drawEnemy(enemy) {
    ctx.save();
    ctx.translate(enemy.x, enemy.y);

    const scale = enemy.x < player.x ? 1 : -1;
    ctx.scale(scale, 1);

    // Body - dark menacing figure
    ctx.fillStyle = '#2C3E50';
    ctx.beginPath();
    ctx.ellipse(0, 5, 16, 22, 0, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.fillStyle = '#ECF0F1';
    ctx.beginPath();
    ctx.arc(0, -18, 13, 0, Math.PI * 2);
    ctx.fill();

    // Evil eyes
    ctx.fillStyle = '#E74C3C';
    ctx.beginPath();
    ctx.arc(-5, -20, 3, 0, Math.PI * 2);
    ctx.arc(5, -20, 3, 0, Math.PI * 2);
    ctx.fill();

    // Evil pupils
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(-5, -20, 1.5, 0, Math.PI * 2);
    ctx.arc(5, -20, 1.5, 0, Math.PI * 2);
    ctx.fill();

    // Evil mouth
    ctx.strokeStyle = '#E74C3C';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-6, -12);
    ctx.lineTo(-3, -10);
    ctx.lineTo(0, -12);
    ctx.lineTo(3, -10);
    ctx.lineTo(6, -12);
    ctx.stroke();

    // Hat
    ctx.fillStyle = '#1a1a2e';
    ctx.beginPath();
    ctx.moveTo(-15, -25);
    ctx.lineTo(15, -25);
    ctx.lineTo(10, -35);
    ctx.lineTo(-10, -35);
    ctx.closePath();
    ctx.fill();

    // Knife
    ctx.fillStyle = '#95A5A6';
    ctx.fillRect(12, -5, 3, 20);
    ctx.fillStyle = '#7F8C8D';
    ctx.beginPath();
    ctx.moveTo(10, -5);
    ctx.lineTo(17, -5);
    ctx.lineTo(13.5, -15);
    ctx.closePath();
    ctx.fill();

    // Legs
    const legOffset = Math.sin(enemy.frame * Math.PI / 2) * 6;
    ctx.fillStyle = '#2C3E50';
    ctx.fillRect(-8, 22, 6, 12 + legOffset);
    ctx.fillRect(2, 22, 6, 12 - legOffset);

    // Boots
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(-9, 32 + legOffset, 8, 4);
    ctx.fillRect(1, 32 - legOffset, 8, 4);

    if (enemy.type === 'fast') {
        ctx.strokeStyle = '#E74C3C';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, 22, 0, Math.PI * 2);
        ctx.stroke();
    }

    ctx.restore();
}

function drawStar(star) {
    ctx.save();
    ctx.translate(star.x, star.y);

    const pulse = 1 + Math.sin(Date.now() / 200) * 0.2;
    ctx.scale(pulse, pulse);

    if (star.type === 'life') {
        ctx.fillStyle = '#ff6b6b';
        ctx.font = '24px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('❤️', 0, 0);
    } else {
        ctx.fillStyle = '#ffd93d';
        ctx.font = '24px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('⭐', 0, 0);
    }

    ctx.restore();
}

function drawBackground() {
    // Sky gradient
    const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
    gradient.addColorStop(0, '#1a1a2e');
    gradient.addColorStop(0.5, '#16213e');
    gradient.addColorStop(1, '#0f3460');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Stars in background
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    for (let i = 0; i < 50; i++) {
        const x = (i * 137.5) % canvas.width;
        const y = (i * 97.3) % (canvas.height * 0.6);
        const size = (Math.sin(Date.now() / 1000 + i) + 1) * 1.5;
        ctx.beginPath();
        ctx.arc(x, y, size, 0, Math.PI * 2);
        ctx.fill();
    }

    // Ground
    ctx.fillStyle = '#2d3436';
    ctx.fillRect(0, canvas.height - 60, canvas.width, 60);

    // Ground details
    ctx.fillStyle = '#636e72';
    for (let i = 0; i < canvas.width; i += 40) {
        ctx.fillRect(i, canvas.height - 55, 20, 3);
    }

    // Grass tufts
    ctx.fillStyle = '#00b894';
    for (let i = 0; i < canvas.width; i += 30) {
        ctx.beginPath();
        ctx.moveTo(i, canvas.height - 60);
        ctx.lineTo(i + 5, canvas.height - 75);
        ctx.lineTo(i + 10, canvas.height - 60);
        ctx.fill();
    }
}

function drawParticles() {
    particles.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1;

    trailParticles.forEach(p => {
        ctx.globalAlpha = p.life * 0.3;
        ctx.fillStyle = speedBoost ? '#ffd93d' : '#4ECDC4';
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1;
}

function drawHUD() {
    // Difficulty indicator
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.font = '14px Arial';
    ctx.textAlign = 'right';
    ctx.fillText(`Wave: ${Math.floor(difficulty)}`, canvas.width - 15, 30);

    // Speed boost indicator
    if (speedBoost) {
        ctx.fillStyle = '#ffd93d';
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(`⚡ SPEED BOOST ${Math.ceil(speedBoostTimer / 1000)}s ⚡`, canvas.width / 2, 30);
    }

    // Invincible indicator
    if (invincible) {
        ctx.fillStyle = '#4ECDC4';
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(`🛡️ INVINCIBLE`, canvas.width / 2, 55);
    }
}

function gameOver() {
    gameRunning = false;
    overlay.classList.remove('hidden');
    overlay.innerHTML = `
        <h1>💀 GAME OVER</h1>
        <h2>You were caught!</h2>
        <div id="finalScore">⏱️ Survival Time: ${Math.floor(gameTime)}s</div>
        <p>The murderers got you! Try again to survive longer.</p>
        <button id="restartBtn" onclick="startGame()">TRY AGAIN</button>
        <div class="controls-info">
            <p>Use <span>WASD</span> or <span>Arrow Keys</span> to move</p>
        </div>
    `;
}

function gameLoop(timestamp) {
    if (!gameRunning) return;

    const dt = timestamp - lastTime;
    lastTime = timestamp;

    gameTime += dt / 1000;
    difficulty = 1 + gameTime / 15;

    scoreDisplay.textContent = `⏱️ Time: ${Math.floor(gameTime)}s`;

    // Update
    updatePlayer(dt);
    updateEnemies(dt);
    updateStars(dt);
    updateParticles(dt);

    if (Math.floor(gameTime) % 5 === 0 && Math.floor(gameTime) > 0) {
        spawnEnemies();
    }
    if (Math.floor(gameTime) % 8 === 0 && Math.floor(gameTime) > 0) {
