    if ((keys['ShiftLeft'] || keys['KeyX']) && player.dashCooldown <= 0) {
        player.dashTimer = 10;
        player.dashDir = player.facing;
        player.dashCooldown = 60;
        player.invincible = Math.max(player.invincible, 10);
        playSFX('dash');
    }

    // Attack
    if ((keys['Space'] || keys['KeyZ']) && player.attackCooldown <= 0) {
        player.attacking = true;
        player.attackTimer = 15;
        player.attackCooldown = 20;
        playSFX('attack');
    }

    // Physics
    if (player.dashTimer > 0) {
        player.vx = player.dashDir * 12;
        player.vy = 0;
        player.dashTimer--;
    } else {
        player.vy += player.gravity;
        if (player.vy > 15) player.vy = 15;
    }

    player.x += player.vx;
    player.y += player.vy;

