            if (player.vy > 0 && player.y + player.h - player.vy <= plat.y + 5) {
                player.y = plat.y - player.h;
                player.vy = 0;
                player.onGround = true;
                player.jumping = false;
            }
            // Bottom collision
            else if (player.vy < 0 && player.y - player.vy >= plat.y + plat.h - 5) {
                player.y = plat.y + plat.h;
                player.vy = 0;
            }
            // Side collision
            else if (player.vx > 0 && player.x + player.w - player.vx <= plat.x + 5) {
                player.x = plat.x - player.w;
                player.vx = 0;
            } else if (player.vx < 0 && player.x - player.vx >= plat.x + plat.w - 5) {
                player.x = plat.x + plat.w;
                player.vx = 0;
            }
        }
    }

