    if (player.invincible > 0) player.invincible--;
    if (player.shieldActive > 0) player.shieldActive--;
    if (player.baboucheBoost > 0) player.baboucheBoost--;

    // Animation
    player.animTimer++;
    if (player.animTimer > 8) {
        player.animTimer = 0;
        player.animFrame = (player.animFrame + 1) % 4;
    }

    // Attack hitbox
    if (player.attacking) {
        const attackBox = {
            x: player.facing > 0 ? player.x + player.w : player.x - 24,
            y: player.y + 8, w: 24, h: 32
        };
        // Check enemy hits
        for (const enemy of levels[currentLevel].enemies) {
            if (enemy.alive && rectCollision(attackBox, enemy)) {
                enemy.hp--;
                if (enemy.hp <= 0) {
                    enemy.alive = false;
                    score += 100;
                    playSFX('hit');
                }
            }
        }
        // Check boss hit
        if (levels[currentLevel].boss && levels[currentLevel].boss.alive) {
            const boss = levels[currentLevel].boss;
            if (rectCollision(attackBox, boss)) {
                boss.hp--;
                screenShake = 5;
                playSFX('hit');
                if (boss.hp <= 0) {
                    boss.alive = false;
                    bossDefeated = true;
                    score += 1000;
                    playSFX('boss');
                    setTimeout(() => {
                        levelComplete = true;
                        gameState = 'LEVEL_COMPLETE';
                        playSFX('levelcomplete');
                    }, 1000);
                }
            }
        }
    }

    // Coin collection
    for (const coin of levels[currentLevel].coins) {
        if (!coin.collected && rectCollision(player, coin)) {
            coin.collected = true;
            coins++;
            score += 50;
            playSFX('coin');
        }
    }

    // Power-up collection
    for (const pu of levels[currentLevel].powerups) {
        if (!pu.collected && rectCollision(player, pu)) {
            pu.collected = true;
            playSFX('powerup');
            if (pu.type === 'babouche') {
                player.baboucheBoost = 600; // 10 seconds
            } else if (pu.type === 'tajine') {
                player.shieldActive = 600;
                playSFX('shield');
            }
        }
    }

    // Checkpoint
    if (levels[currentLevel].checkpoint && !levels[currentLevel].checkpoint.activated) {
        if (rectCollision(player, levels[currentLevel].checkpoint)) {
            levels[currentLevel].checkpoint.activated = true;
            checkpointX = levels[currentLevel].checkpoint.x;
            playSFX('powerup');
        }
    }

    // Level end
    if (player.x >= levels[currentLevel].endX && !bossDefeated && levels[currentLevel].boss) {
        // Trigger boss fight
    }
    if (player.x >= levels[currentLevel].endX && bossDefeated) {
        levelComplete = true;
        gameState = 'LEVEL_COMPLETE';
        playSFX('levelcomplete');
    }

    // Enemy collision with player
    for (const enemy of levels[currentLevel].enemies) {
        if (enemy.alive && rectCollision(player, enemy) && player.invincible <= 0) {
            if (player.shieldActive > 0) {
                enemy.alive = false;
                score += 100;
                playSFX('hit');
            } else {
                playerHit();
            }
        }
    }

    // Boss collision
    if (levels[currentLevel].boss && levels[currentLevel].boss.alive) {
        const boss = levels[currentLevel].boss;
        if (rectCollision(player, boss) && player.invincible <= 0) {
            if (player.shieldActive > 0) {
                boss.hp -= 2;
                playSFX('hit');
                if (boss.hp <= 0) {
                    boss.alive = false;
                    bossDefeated = true;
                    score += 1000;
                    playSFX('boss');
                    setTimeout(() => {
                        levelComplete = true;
                        gameState = 'LEVEL_COMPLETE';
                        playSFX('levelcomplete');
                    }, 1000);
                }
            } else {
                playerHit();
            }
        }
    }
}

function playerHit() {
    if (player.invincible > 0) return;
    lives--;
    player.invincible = 90;
    player.vy = -8;
    playSFX('death');
    screenShake = 10;
    if (lives <= 0) {
        playerDeath();
    }
}

function playerDeath() {
    player.dead = true;
    playSFX('death');
    screenShake = 15;
    setTimeout(() => {
        if (lives > 0) {
            resetPlayer();
        } else {
            gameState = 'GAME_OVER';
        }
    }, 1000);
}

function updateEnemies() {
    for (const enemy of levels[currentLevel].enemies) {
        if (!enemy.alive) continue;

        enemy.animTimer++;
        if (enemy.animTimer > 10) {
            enemy.animTimer = 0;
            enemy.animFrame = (enemy.animFrame + 1) % 4;
        }

        if (enemy.type === 'beetle') {
            enemy.x += enemy.vx;
            if (enemy.x <= enemy.patrolStart || enemy.x >= enemy.patrolEnd) {
                enemy.vx *= -1;
            }
        } else if (enemy.type === 'pigeon') {
            enemy.y += Math.sin(Date.now() / 300) * 2;
            enemy.x += enemy.vx;
            if (enemy.x <= enemy.patrolStart || enemy.x >= enemy.patrolEnd) {
                enemy.vx *= -1;
            }
        } else if (enemy.type === 'bandit') {
            enemy.x += enemy.vx;
            if (enemy.x <= enemy.patrolStart || enemy.x >= enemy.patrolEnd) {
                enemy.vx *= -1;
            }
            // Chase player if close
            const dx = player.x - enemy.x;
            if (Math.abs(dx) < 150 && Math.abs(player.y - enemy.y) < 50) {
                enemy.vx = dx > 0 ? 2 : -2;
            }
        }

        // Gravity for ground enemies
        if (enemy.type !== 'pigeon') {
            enemy.vy += 0.5;
            enemy.y += enemy.vy;
            // Platform collision
            for (const plat of levels[currentLevel].platforms) {
                if (rectCollision(enemy, plat) && enemy.vy > 0 && enemy.y + enemy.h - enemy.vy <= plat.y + 5) {
                    enemy.y = plat.y - enemy.h;
                    enemy.vy = 0;
                    enemy.onGround = true;
                }
            }
        }
    }
}

function updateBoss() {
    const boss = levels[currentLevel].boss;
    if (!boss || !boss.alive) return;

    boss.animTimer++;
    if (boss.animTimer > 8) {
        boss.animTimer = 0;
        boss.animFrame = (boss.animFrame + 1) % 4;
    }

    boss.patternTimer++;
    if (boss.patternTimer >= boss.patternDuration) {
        boss.patternTimer = 0;
        boss.attackPattern = (boss.attackPattern + 1) % 3;
    }

    const dx = player.x - boss.x;
    const dy = player.y - boss.y;

    if (boss.type === 'guardian') {
        // Pattern 0: Charge at player
        if (boss.attackPattern === 0) {
            boss.vx = Math.sign(dx) * 3;
            boss.vy = Math.sin(boss.patternTimer / 30) * 2;
        }
        // Pattern 1: Jump and slam
        else if (boss.attackPattern === 1) {
            if (boss.patternTimer < 30) {
                boss.vy = -8;
            } else if (boss.patternTimer < 60) {
                boss.vy += 0.5;
            } else {
                boss.vx = Math.sign(dx) * 2;
            }
        }
        // Pattern 2: Summons minions
        else {
            boss.vx = 0;
            if (boss.patternTimer === 10 && levels[currentLevel].enemies.length < 10) {
                levels[currentLevel].enemies.push({
                    x: boss.x + (Math.random() > 0.5 ? 100 : -100),
                    y: boss.y - 50, w: 32, h: 32,
                    type: 'beetle', vx: Math.sign(dx) * 2, vy: 0,
                    hp: 1, animFrame: 0, animTimer: 0,
                    patrolStart: boss.x, patrolEnd: boss.x + 100,
                    onGround: false, alive: true
                });
            }
        }
    } else if (boss.type === 'sand_wizard') {
        if (boss.attackPattern === 0) {
            boss.vx = Math.sign(dx) * 2;
            boss.vy = Math.sin(boss.patternTimer / 20) * 3;
        } else if (boss.attackPattern === 1) {
            boss.vx = 0;
            if (boss.patternTimer % 20 === 0) {
                // Spawn sand projectile (as enemy)
                levels[currentLevel].enemies.push({
                    x: boss.x, y: boss.y + 20, w: 16, h: 16,
                    type: 'beetle', vx: Math.sign(dx) * 4, vy: 0,
                    hp: 1, animFrame: 0, animTimer: 0,
                    patrolStart: boss.x, patrolEnd: boss.x + 200,
                    onGround: false, alive: true
                });
            }
        } else {
            boss.vx = Math.sign(dx) * 4;
            boss.vy += 0.3;
        }
    } else if (boss.type === 'pharaoh') {
        if (boss.attackPattern === 0) {
            boss.vx = Math.sign(dx) * 2.5;
            boss.vy += 0.4;
        } else if (boss.attackPattern === 1) {
            if (boss.patternTimer < 40) {
                boss.vy = -10;
            } else {
                boss.vy += 0.5;
            }
        } else {
            boss.vx = Math.sign(dx) * 3;
            if (boss.patternTimer % 15 === 0) {
                levels[currentLevel].enemies.push({
                    x: boss.x + (Math.random() > 0.5 ? 80 : -80),
                    y: boss.y, w: 32, h: 32,
                    type: 'bandit', vx: Math.sign(dx) * 2, vy: 0,
                    hp: 2, animFrame: 0, animTimer: 0,
                    patrolStart: boss.x, patrolEnd: boss.x + 150,
                    onGround: false, alive: true
                });
            }
        }
    }

    boss.x += boss.vx;
    boss.y += boss.vy;

    // Boss platform collision
    for (const plat of levels[currentLevel].platforms) {
        if (rectCollision(boss, plat) && boss.vy > 0 && boss.y + boss.h - boss.vy <= plat.y + 5) {
            boss.y = plat.y - boss.h;
            boss.vy = 0;
        }
    }

    // Keep boss in bounds
    if (boss.x < 100) boss.x = 100;
    if (boss.x > levels[currentLevel].width - 200) boss.x = levels[currentLevel].width - 200;
    if (boss.y > H - 100) {
        boss.y = H - 100;
        boss.vy = 0;
    }
}

function updateMovingPlatforms() {
    for (const plat of levels[currentLevel].movingPlatforms) {
        plat.x += plat.speed * plat.dir;
        if (plat.x <= plat.startX || plat.x >= plat.endX) {
            plat.dir *= -1;
        }
    }
}

function updateRugs() {
    for (const rug of levels[currentLevel].rugs) {
        rug.x += rug.speed * rug.dir;
        if (rug.x < 0 || rug.x > levels[currentLevel].width - rug.w) {
            rug.dir *= -1;
        }
    }
}

function updateSandstorms() {
    for (const storm of (levels[currentLevel].sandstorms || [])) {
        storm.timer++;
        if (storm.timer > storm.duration && !storm.active) {
            storm.active = true;
            storm.timer = 0;
        }
        if (storm.active && storm.timer > 120) {
            storm.active = false;
            storm.timer = 0;
        }
    }
}

function updateCamera() {
    const targetX = player.x - W / 3;
    cameraX += (targetX - cameraX) * 0.1;
    if (cameraX < 0) cameraX = 0;
    if (cameraX > levels[currentLevel].width - W) cameraX = levels[currentLevel].width - W;
}

// Drawing functions
function drawVectorCharacter(x, y, w, h, facing, animFrame, isPlayer = false) {
    ctx.save();
    ctx.translate(x + w/2, y + h/2);
    ctx.scale(facing, 1);

    if (isPlayer) {
        // Body - traditional Tunisian dress (modernized)
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(-w/2 + 4, -h/2 + 16, w - 8, h - 20);

        // Belt
        ctx.fillStyle = '#D4AF37';
        ctx.fillRect(-w/2 + 2, -h/2 + 28, w - 4, 6);

        // Head
        ctx.fillStyle = '#D2B48C';
        ctx.beginPath();
        ctx.arc(0, -h/2 + 10, 12, 0, Math.PI * 2);
        ctx.fill();

        // Kufi (traditional hat)
        ctx.fillStyle = '#FFFFFF';
        ctx.beginPath();
        ctx.arc(0, -h/2 + 2, 10, Math.PI, 0);
        ctx.fill();
        ctx.fillStyle = '#D4AF37';
        ctx.fillRect(-10, -h/2 + 2, 20, 4);

        // Eyes
        ctx.fillStyle = '#000';
        ctx.fillRect(2, -h/2 + 8, 3, 3);
        ctx.fillRect(-6, -h/2 + 8, 3, 3);

        // Smile
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, -h/2 + 14, 5, 0.1, Math.PI - 0.1);
        ctx.stroke();

        // Arms
        ctx.fillStyle = '#D2B48C';
        const armOffset = Math.sin(animFrame * Math.PI / 2) * 4;
        ctx.fillRect(-w/2 - 2, -h/2 + 20 + armOffset, 6, 16);
        ctx.fillRect(w/2 - 4, -h/2 + 20 - armOffset, 6, 16);

        // Legs
        ctx.fillStyle = '#4A6741';
        const legOffset = Math.sin(animFrame * Math.PI / 2) * 3;
        ctx.fillRect(-w/2 + 6, h/2 - 12 + legOffset, 8, 12);
        ctx.fillRect(w/2 - 14, h/2 - 12 - legOffset, 8, 12);

        // Babouche shoes
        ctx.fillStyle = '#D4AF37';
        ctx.fillRect(-w/2 + 4, h/2 - 2 + legOffset, 12, 4);
        ctx.fillRect(w/2 - 16, h/2 - 2 - legOffset, 12, 4);

        // Shield effect
        if (player.shieldActive > 0) {
            ctx.strokeStyle = '#00BFFF';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(0, 0, w/2 + 8, 0, Math.PI * 2);
            ctx.stroke();
            ctx.fillStyle = 'rgba(0, 191, 255, 0.1)';
            ctx.fill();
        }

        // Attack effect
        if (player.attacking) {
            ctx.fillStyle = '#FFD700';
            ctx.beginPath();
            ctx.arc(w/2 + 10, 0, 12, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#FFA500';
            ctx.beginPath();
            ctx.arc(w/2 + 10, 0, 8, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    ctx.restore();
}

function drawBeetle(x, y, w, h, animFrame) {
    ctx.save();
    ctx.translate(x + w/2, y + h/2);

    // Body
    ctx.fillStyle = '#2E8B57';
    ctx.beginPath();
    ctx.ellipse(0, 0, w/2, h/2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#1a5c3a';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Shell pattern
    ctx.fillStyle = '#3CB371';
    ctx.beginPath();
    ctx.ellipse(0, -2, w/3, h/3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#FF0000';
    ctx.fillRect(-6, -h/2 + 2, 4, 4);
    ctx.fillRect(2, -h/2 + 2, 4, 4);

    // Legs
    ctx.strokeStyle = '#1a5c3a';
    ctx.lineWidth = 2;
    const legAnim = Math.sin(animFrame * Math.PI / 2) * 3;
    ctx.beginPath();
    ctx.moveTo(-w/2, 0);
    ctx.lineTo(-w/2 - 6, 4 + legAnim);
    ctx.moveTo(w/2, 0);
    ctx.lineTo(w/2 + 6, 4 - legAnim);
    ctx.stroke();

    ctx.restore();
}

function drawPigeon(x, y, w, h, animFrame) {
    ctx.save();
    ctx.translate(x + w/2, y + h/2);

    // Body
    ctx.fillStyle = '#808080';
    ctx.beginPath();
    ctx.ellipse(0, 0, w/2, h/3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Wings
    ctx.fillStyle = '#A9A9A9';
    const wingAnim = Math.sin(animFrame * Math.PI / 2) * 8;
    ctx.beginPath();
    ctx.ellipse(-4, -h/4 + wingAnim, w/3, h/4, -0.3, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(4, -h/4 - wingAnim, w/3, h/4, 0.3, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.fillStyle = '#696969';
    ctx.beginPath();
    ctx.arc(0, -h/3, 8, 0, Math.PI * 2);
    ctx.fill();

    // Eye
    ctx.fillStyle = '#FF0000';
    ctx.beginPath();
    ctx.arc(3, -h/3 - 2, 2, 0, Math.PI * 2);
    ctx.fill();

    // Beak
    ctx.fillStyle = '#FFA500';
    ctx.beginPath();
    ctx.moveTo(8, -h/3);
    ctx.lineTo(14, -h/3 + 2);
    ctx.lineTo(8, -h/3 + 4);
    ctx.fill();

    ctx.restore();
}

function drawBandit(x, y, w, h, animFrame) {
    ctx.save();
    ctx.translate(x + w/2, y + h/2);

    // Body
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(-w/2 + 4, -h/2 + 12, w - 8, h - 16);

    // Head
    ctx.fillStyle = '#D2B48C';
    ctx.beginPath();
    ctx.arc(0, -h/2 + 8, 10, 0, Math.PI * 2);
    ctx.fill();

    // Bandana
    ctx.fillStyle = '#8B0000';
    ctx.beginPath();
    ctx.arc(0, -h/2 + 4, 11, Math.PI, 0);
    ctx.fill();
    ctx.fillRect(-12, -h/2 + 2, 24, 4);

    // Eyes (evil)
    ctx.fillStyle = '#000';
    ctx.fillRect(-5, -h/2 + 6, 3, 3);
    ctx.fillRect(2, -h/2 + 6, 3, 3);

    // Mustache
    ctx.fillStyle = '#000';
    ctx.fillRect(-6, -h/2 + 12, 12, 2);

    // Legs
    ctx.fillStyle = '#654321';
    const legAnim = Math.sin(animFrame * Math.PI / 2) * 3;
    ctx.fillRect(-w/2 + 6, h/2 - 10 + legAnim, 8, 10);
    ctx.fillRect(w/2 - 14, h/2 - 10 - legAnim, 8, 10);

    ctx.restore();
}

function drawBoss(boss) {
    ctx.save();
    ctx.translate(boss.x + boss.w/2, boss.y + boss.h/2);

    if (boss.type === 'guardian') {
        // Guardian body
        ctx.fillStyle = '#8B4513';
        ctx.fillRect(-boss.w/2, -boss.h/2, boss.w, boss.h);

        // Armor
        ctx.fillStyle = '#D4AF37';
        ctx.fillRect(-boss.w/2 + 4, -boss.h/2 + 4, boss.w - 8, 20);
        ctx.fillRect(-boss.w/2 + 4, boss.h/2 - 24, boss.w - 8, 20);

        // Head
        ctx.fillStyle = '#D2B48C';
        ctx.beginPath();
        ctx.arc(0, -boss.h/2 + 20, 16, 0, Math.PI * 2);
        ctx.fill();

        // Crown
        ctx.fillStyle = '#D4AF37';
        ctx.beginPath();
        ctx.moveTo(-16, -boss.h/2 + 8);
        ctx.lineTo(-12, -boss.h/2 - 8);
        ctx.lineTo(-4, -boss.h/2 + 8);
        ctx.lineTo(4, -boss.h/2 - 8);
        ctx.lineTo(12, -boss.h/2 + 8);
        ctx.lineTo(16, -boss.h/2 - 8);
        ctx.lineTo(16, -boss.h/2 + 8);
        ctx.lineTo(-16, -boss.h/2 + 8);
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#FF0000';
        ctx.fillRect(-8, -boss.h/2 + 16, 5, 5);
        ctx.fillRect(3, -boss.h/2 + 16, 5, 5);

        // Weapon
        ctx.fillStyle = '#C0C0C0';
        ctx.fillRect(boss.w/2, -boss.h/2 + 20, 20, 6);
        ctx.fillRect(boss.w/2 + 16, -boss.h/2 + 10, 6, 26);

    } else if (boss.type === 'sand_wizard') {
        // Wizard body
        ctx.fillStyle = '#4B0082';
        ctx.beginPath();
        ctx.moveTo(-boss.w/2, boss.h/2);
        ctx.lineTo(boss.w/2, boss.h/2);
        ctx.lineTo(boss.w/4, -boss.h/2);
        ctx.lineTo(-boss.w/4, -boss.h/2);
        ctx.fill();

        // Hat
        ctx.fillStyle = '#4B0082';
        ctx.beginPath();
        ctx.moveTo(-20, -boss.h/2);
        ctx.lineTo(0, -boss.h/2 - 30);
        ctx.lineTo(20, -boss.h/2);
        ctx.fill();

        // Face
        ctx.fillStyle = '#D2B48C';
        ctx.beginPath();
        ctx.arc(0, -boss.h/2 + 10, 12, 0, Math.PI * 2);
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#FFD700';
        ctx.fillRect(-6, -boss.h/2 + 8, 4, 4);
        ctx.fillRect(2, -boss.h/2 + 8, 4, 4);

        // Beard
        ctx.fillStyle = '#FFFFFF';
        ctx.beginPath();
        ctx.moveTo(-10, -boss.h/2 + 16);
        ctx.lineTo(0, -boss.h/2 + 30);
        ctx.lineTo(10, -boss.h/2 + 16);
        ctx.fill();

        // Staff
        ctx.fillStyle = '#8B4513';
        ctx.fillRect(boss.w/2 + 4, -boss.h/2, 4, boss.h);
        ctx.fillStyle = '#FFD700';
        ctx.beginPath();
        ctx.arc(boss.w/2 + 6, -boss.h/2 - 4, 6, 0, Math.PI * 2);
        ctx.fill();

    } else if (boss.type === 'pharaoh') {
        // Pharaoh body
        ctx.fillStyle = '#D4AF37';
        ctx.fillRect(-boss.w/2, -boss.h/2, boss.w, boss.h);

        // Chest plate
        ctx.fillStyle = '#FFD700';
        ctx.fillRect(-boss.w/2 + 8, -boss.h/2 + 10, boss.w - 16, 30);

        // Head
        ctx.fillStyle = '#D2B48C';
        ctx.beginPath();
        ctx.arc(0, -boss.h/2 + 16, 18, 0, Math.PI * 2);
        ctx.fill();

        // Nemes (royal headdress)
        ctx.fillStyle = '#D4AF37';
        ctx.beginPath();
        ctx.moveTo(-20, -boss.h/2 + 4);
        ctx.lineTo(0, -boss.h/2 - 20);
        ctx.lineTo(20, -boss.h/2 + 4);
        ctx.lineTo(20, -boss.h/2 + 20);
        ctx.lineTo(-20, -boss.h/2 + 20);
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#000';
        ctx.fillRect(-8, -boss.h/2 + 12, 6, 4);
        ctx.fillRect(2, -boss.h/2 + 12, 6, 4);

        // Cobra
        ctx.fillStyle = '#FF0000';
        ctx.beginPath();
        ctx.arc(0, -boss.h/2 + 6, 4, 0, Math.PI * 2);
        ctx.fill();

        // Arms
        ctx.fillStyle = '#D4AF37';
        ctx.fillRect(-boss.w/2 - 10, -boss.h/2 + 30, 10, 30);
        ctx.fillRect(boss.w/2, -boss.h/2 + 30, 10, 30);
    }

    // Health bar
    ctx.fillStyle = '#333';
    ctx.fillRect(-boss.w/2, -boss.h/2 - 16, boss.w, 8);
    ctx.fillStyle = boss.hp > boss.maxHp * 0.3 ? '#00FF00' : '#FF0000';
    ctx.fillRect(-boss.w/2, -boss.h/2 - 16, boss.w * (boss.hp / boss.maxHp), 8);

    ctx.restore();
}

function drawPlatform(plat) {
    ctx.save();
    ctx.translate(plat.x - cameraX, plat.y);

    if (plat.type === 'ground') {
        ctx.fillStyle = '#C2956B';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.fillStyle = '#8B7355';
        ctx.fillRect(0, 0, plat.w, 4);
        // Pattern
        ctx.fillStyle = '#A0826D';
        for (let i = 0; i < plat.w; i += 16) {
            ctx.fillRect(i + 4, 8, 8, 4);
        }
    } else if (plat.type === 'wall') {
        ctx.fillStyle = '#D2B48C';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.strokeStyle = '#8B7355';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, plat.w, plat.h);
    } else if (plat.type === 'arch') {
        ctx.fillStyle = '#D2B48C';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.strokeStyle = '#8B7355';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, plat.w, plat.h);
        // Arch decoration
        ctx.fillStyle = '#D4AF37';
        ctx.fillRect(plat.w/2 - 4, 0, 8, plat.h);
    } else if (plat.type === 'platform') {
        ctx.fillStyle = '#8B4513';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.fillStyle = '#A0522D';
        ctx.fillRect(0, 0, plat.w, 4);
    } else if (plat.type === 'sand') {
        ctx.fillStyle = '#F4A460';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.fillStyle = '#DEB887';
        ctx.fillRect(0, 0, plat.w, 4);
    } else if (plat.type === 'dune') {
        ctx.fillStyle = '#F4A460';
        ctx.beginPath();
        ctx.moveTo(0, plat.h);
        ctx.quadraticCurveTo(plat.w/2, 0, plat.w, plat.h);
        ctx.fill();
    } else if (plat.type === 'ruin' || plat.type === 'ancient') {
        ctx.fillStyle = '#808080';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.strokeStyle = '#606060';
        ctx.lineWidth = 1;
        ctx.strokeRect(0, 0, plat.w, plat.h);
    } else if (plat.type === 'ruin_top' || plat.type === 'ancient_top') {
        ctx.fillStyle = '#909090';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.strokeStyle = '#606060';
        ctx.lineWidth = 1;
        ctx.strokeRect(0, 0, plat.w, plat.h);
    } else if (plat.type === 'wood') {
        ctx.fillStyle = '#8B6914';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.fillStyle = '#A0782C';
        ctx.fillRect(0, 0, plat.w, 3);
    } else if (plat.type === 'grass') {
        ctx.fillStyle = '#4A7C59';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.fillStyle = '#5D8F6E';
        ctx.fillRect(0, 0, plat.w, 6);
        // Grass blades
        ctx.fillStyle = '#6B9E7E';
        for (let i = 0; i < plat.w; i += 8) {
            ctx.fillRect(i, -4, 2, 6);
        }
    } else if (plat.type === 'moving') {
        ctx.fillStyle = '#4169E1';
        ctx.fillRect(0, 0, plat.w, plat.h);
        ctx.fillStyle = '#6495ED';
        ctx.fillRect(0, 0, plat.w, 4);
        ctx.strokeStyle = '#2E4BA0';
        ctx.lineWidth = 1;
        ctx.strokeRect(0, 0, plat.w, plat.h);
    }

    ctx.restore();
}

function drawCoin(coin) {
    if (coin.collected) return;
    ctx.save();
    ctx.translate(coin.x - cameraX + coin.w/2, coin.y + coin.h/2);

    coin.animTimer += 0.05;
    const scale = Math.abs(Math.cos(coin.animTimer));

    ctx.scale(scale, 1);
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(0, 0, coin.w/2, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#DAA520';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Dinar symbol
    ctx.fillStyle = '#B8860B';
    ctx.font = 'bold 10px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('D', 0, 0);

    ctx.restore();
}

function drawPowerup(pu) {
    if (pu.collected) return;
    ctx.save();
    ctx.translate(pu.x - cameraX + pu.w/2, pu.y + pu.h/2);

    pu.animTimer += 0.03;
    const bob = Math.sin(pu.animTimer) * 3;

    ctx.translate(0, bob);

    if (pu.type === 'babouche') {
        // Babouche shoe
        ctx.fillStyle = '#D4AF37';
        ctx.beginPath();
        ctx.moveTo(-12, 4);
        ctx.quadraticCurveTo(-8, -12, 0, -8);
        ctx.quadraticCurveTo(8, -12, 12, 4);
        ctx.quadraticCurveTo(8, 8, 0, 8);
        ctx.quadraticCurveTo(-8, 8, -12, 4);
        ctx.fill();
        ctx.strokeStyle = '#B8860B';
        ctx.lineWidth = 2;
        ctx.stroke();
    } else if (pu.type === 'tajine') {
        // Tajine pot
        ctx.fillStyle = '#CD853F';
        ctx.beginPath();
        ctx.moveTo(-10, 8);
        ctx.lineTo(-10, -2);
        ctx.quadraticCurveTo(0, -14, 10, -2);
        ctx.lineTo(10, 8);
        ctx.fill();
        ctx.strokeStyle = '#8B4513';
        ctx.lineWidth = 2;
        ctx.stroke();
        // Lid
        ctx.fillStyle = '#D4AF37';
        ctx.beginPath();
        ctx.arc(0, -4, 6, Math.PI, 0);
        ctx.fill();
    }

    // Glow
    ctx.strokeStyle = 'rgba(255, 215, 0, 0.5)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, 16, 0, Math.PI * 2);
    ctx.stroke();

    ctx.restore();
}

function drawCheckpoint(cp) {
    if (!cp) return;
    ctx.save();
    ctx.translate(cp.x - cameraX, cp.y);

    // Pole
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(12, 0, 8, cp.h);

    // Flag
    if (cp.activated) {
        ctx.fillStyle = '#00FF00';
        ctx.beginPath();
        ctx.moveTo(20, 4);
        ctx.lineTo(40, 16);
        ctx.lineTo(20, 28);
        ctx.fill();
    } else {
        ctx.fillStyle = '#FF0000';
        ctx.beginPath();
        ctx.moveTo(20, 4);
        ctx.lineTo(40, 16);
        ctx.lineTo(20, 28);
        ctx.fill();
    }

    // Base
    ctx.fillStyle = '#654321';
    ctx.fillRect(8, cp.h - 8, 16, 8);

    ctx.restore();
}

function drawRug(rug) {
    ctx.save();
    ctx.translate(rug.x - cameraX, rug.y);

    // Rug body
    ctx.fillStyle = '#8B0000';
    ctx.fillRect(0, 0, rug.w, rug.h);

    // Pattern
    ctx.fillStyle = '#D4AF37';
    for (let i = 4; i < rug.w; i += 12) {
        ctx.fillRect(i, 2, 6, rug.h - 4);
    }
    ctx.fillStyle = '#FFD700';
    ctx.fillRect(2, 0, 2, rug.h);
    ctx.fillRect(rug.w - 4, 0, 2, rug.h);

    // Fringe
    ctx.fillStyle = '#D4AF37';
    for (let i = 0; i < rug.w; i += 8) {
        ctx.fillRect(i, rug.h, 4, 4);
    }

    ctx.restore();
}

function drawCrate(crate) {
    ctx.save();
    ctx.translate(crate.x - cameraX, crate.y);

    ctx.fillStyle = '#8B6914';
    ctx.fillRect(0, 0, crate.w, crate.h);
    ctx.strokeStyle = '#654321';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, crate.w, crate.h);

    // Cross pattern
    ctx.strokeStyle = '#654321';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(crate.w, crate.h);
    ctx.moveTo(crate.w, 0);
    ctx.lineTo(0, crate.h);
    ctx.stroke();

    ctx.restore();
}

function drawSandstorm(storm) {
    if (!storm.active) return;
    ctx.save();
    ctx.translate(-cameraX, 0);

    ctx.fillStyle = 'rgba(210, 180, 140, 0.3)';
    ctx.fillRect(storm.x, storm.y, storm.w, storm.h);

    // Sand particles
    ctx.fillStyle = 'rgba(210, 180, 140, 0.6)';
    for (let i = 0; i < 20; i++) {
        const px = storm.x + Math.random() * storm.w;
        const py = Math.random() * storm.h;
        ctx.fillRect(px, py, 3, 3);
    }

    ctx.restore();
}

function drawWaterPool(pool) {
    ctx.save();
    ctx.translate(pool.x - cameraX, pool.y);

    ctx.fillStyle = '#4169E1';
    ctx.fillRect(0, 0, pool.w, pool.h);
    ctx.fillStyle = '#6495ED';
    ctx.fillRect(0, 0, pool.w, 8);

    // Water animation
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    for (let i = 0; i < pool.w; i += 16) {
        const wave = Math.sin(Date.now() / 500 + i / 20) * 3;
        ctx.fillRect(i, 4 + wave, 8, 2);
    }

    ctx.restore();
}

function drawBackground() {
    const level = levels[currentLevel];

    // Sky gradient
    const gradient = ctx.createLinearGradient(0, 0, 0, H);
    gradient.addColorStop(0, level.bgColor1);
    gradient.addColorStop(1, level.bgColor2);
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, W, H);

    // Background elements based on level
    if (currentLevel === 0) {
        // Medina background - buildings
        ctx.fillStyle = '#D2B48C';
        for (let i = 0; i < 15; i++) {
            const bx = i * 200 - (cameraX * 0.3) % 200;
            const bh = 100 + Math.sin(i * 2.5) * 50;
            ctx.fillRect(bx, H - 64 - bh, 80, bh);
            // Windows
            ctx.fillStyle = '#8B7355';
            for (let wy = 0; wy < bh - 20; wy += 30) {
                ctx.fillRect(bx + 15, H - 64 - bh + 20 + wy, 12, 16);
                ctx.fillRect(bx + 50, H - 64 - bh + 20 + wy, 12, 16);
            }
            ctx.fillStyle = '#D2B48C';
        }
        // Mosquito minaret
        ctx.fillStyle = '#E8D5B7';
        ctx.fillRect(300 - (cameraX * 0.2) % 400, H - 300, 30, 236);
        ctx.beginPath();
        ctx.moveTo(290, H - 300);
        ctx.lineTo(315, H - 340);
        ctx.lineTo(340, H - 300);
        ctx.fill();
    } else if (currentLevel === 1) {
        // Desert background - dunes
        ctx.fillStyle = '#DEB887';
        for (let i = 0; i < 10; i++) {
            const dx = i * 300 - (cameraX * 0.2) % 300;
            ctx.beginPath();
            ctx.moveTo(dx, H - 64);
            ctx.quadraticCurveTo(dx + 150, H - 200 - Math.sin(i) * 50, dx + 300, H - 64);
            ctx.fill();
        }
        // Cactus
        ctx.fillStyle = '#2E8B57';
        for (let i = 0; i < 5; i++) {
            const cx = 500 + i * 800 - (cameraX * 0.3) % 800;
            ctx.fillRect(cx, H - 150, 8, 86);
            ctx.fillRect(cx - 15, H - 130, 15, 6);
            ctx.fillRect(cx - 15, H - 130, 6, 20);
            ctx.fillRect(cx + 8, H - 110, 15, 6);
            ctx.fillRect(cx + 17, H - 110, 6, 15);
        }
    } else if (currentLevel === 2) {
        // Oasis background - palm trees
        ctx.fillStyle = '#2E8B57';
        for (let i = 0; i < 8; i++) {
            const tx = 200 + i * 700 - (cameraX * 0.25) % 700;
            // Trunk
            ctx.fillStyle = '#8B6914';
            ctx.fillRect(tx, H - 250, 12, 186);
            // Leaves
            ctx.fillStyle = '#228B22';
            for (let a = 0; a < 6; a++) {
                const angle = (a / 6) * Math.PI * 2 + Date.now() / 3000;
                ctx.save();
                ctx.translate(tx + 6, H - 250);
                ctx.rotate(angle);
                ctx.beginPath();
                ctx.ellipse(30, 0, 30, 8, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }
        }
        // Water reflection
        ctx.fillStyle = 'rgba(65, 105, 225, 0.3)';
        ctx.fillRect(0, H - 40, W, 40);
    }

    // Clouds
    ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
    for (let i = 0; i < 5; i++) {
        const cx = (i * 300 + Date.now() / 100) % (W + 200) - 100;
        ctx.beginPath();
        ctx.arc(cx, 80 + i * 30, 30, 0, Math.PI * 2);
        ctx.arc(cx + 25, 75 + i * 30, 25, 0, Math.PI * 2);
        ctx.arc(cx + 50, 80 + i * 30, 30, 0, Math.PI * 2);
        ctx.fill();
    }
}

