function drawMenu() {
    // Background
    const gradient = ctx.createLinearGradient(0, 0, 0, H);
    gradient.addColorStop(0, '#1a0a2e');
    gradient.addColorStop(1, '#2d1b69');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, W, H);

    // Decorative pattern
    ctx.fillStyle = 'rgba(212, 175, 55, 0.1)';
    for (let i = 0; i < 20; i++) {
        for (let j = 0; j < 10; j++) {
            ctx.beginPath();
            ctx.arc(i * 60 + 30, j * 60 + 30, 20, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    // Title
    ctx.fillStyle = '#FFD700';
    ctx.font = 'bold 48px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('🏜️ TUNISI ADVENTURE 🏜️', W/2, 120);

    // Subtitle
    ctx.fillStyle = '#D4AF37';
    ctx.font = '20px Arial';
    ctx.fillText('Un Platform Arcade Tunisino', W/2, 160);

    // Character preview
    drawVectorCharacter(W/2 - 24, 200, 48, 64, 1, 0, true);

    // Start button
    const btnX = W/2 - 100;
    const btnY = 320;
    const btnW = 200;
    const btnH = 50;

    ctx.fillStyle = '#D4AF37';
    ctx.fillRect(btnX, btnY, btnW, btnH);
    ctx.strokeStyle = '#FFD700';
    ctx.lineWidth = 3;
    ctx.strokeRect(btnX, btnY, btnW, btnH);

    ctx.fillStyle = '#1a0a2e';
    ctx.font = 'bold 24px Arial';
    ctx.fillText('🎮 GIOCA', W/2, btnY + 33);

    // Instructions
    ctx.fillStyle = '#FFFFFF';
    ctx.font = '14px Arial';
    ctx.fillText('← → : Muovi  |  ↑ : Salta  |  SPAZIO : Attacca  |  SHIFT : Dash', W/2, 420);
    ctx.fillText('Raccogli monete, sconfiggi nemici, batti il boss!', W/2, 445);

    // Version
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
    ctx.font = '12px Arial';
    ctx.fillText('v1.0 - 3 Livelli di Avventura Tunisina', W/2, 500);

    // Click detection for start
    canvas.onclick = (e) => {
        const rect = canvas.getBoundingClientRect();
        const mx = (e.clientX - rect.left) * (W / rect.width);
        const my = (e.clientY - rect.top) * (H / rect.height);
        if (mx >= btnX && mx <= btnX + btnW && my >= btnY && my <= btnY + btnH) {
            initAudio();
            startLevel(0);
        }
    };
}

function drawLevelComplete() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(0, 0, W, H);

    ctx.fillStyle = '#FFD700';
    ctx.font = 'bold 40px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('🎉 LIVELLO COMPLETATO! 🎉', W/2, 150);

    ctx.fillStyle = '#FFFFFF';
    ctx.font = '24px Arial';
    ctx.fillText('Livello: ' + levels[currentLevel].name, W/2, 220);

    ctx.fillStyle = '#FFD700';
    ctx.font = '20px Arial';
    ctx.fillText('Monete: ' + coins, W/2, 280);
    ctx.fillText('Punteggio: ' + score, W/2, 310);

    // Next level button
    const btnX = W/2 - 100;
    const btnY = 360;
    const btnW = 200;
    const btnH = 50;

    ctx.fillStyle = '#4CAF50';
    ctx.fillRect(btnX, btnY, btnW, btnH);
    ctx.strokeStyle = '#81C784';
    ctx.lineWidth = 3;
    ctx.strokeRect(btnX, btnY, btnW, btnH);

    ctx.fillStyle = '#FFFFFF';
    ctx.font = 'bold 20px Arial';
    ctx.fillText('▶ PROSSIMO LIVELLO', W/2, btnY + 33);

    canvas.onclick = (e) => {
        const rect = canvas.getBoundingClientRect();
        const mx = (e.clientX - rect.left) * (W / rect.width);
        const my = (e.clientY - rect.top) * (H / rect.height);
        if (mx >= btnX && mx <= btnX + btnW && my >= btnY && my <= btnY + btnH) {
            if (currentLevel < 2) {
                startLevel(currentLevel + 1);
            } else {
                gameState = 'MENU';
            }
        }
    };
}

function drawGameOver() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
    ctx.fillRect(0, 0, W, H);

    ctx.fillStyle = '#FF0000';
    ctx.font = 'bold 48px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('💀 GAME OVER 💀', W/2, 200);

    ctx.fillStyle = '#FFFFFF';
    ctx.font = '24px Arial';
    ctx.fillText('Punteggio Finale: ' + score, W/2, 280);
    ctx.fillText('Monete Raccolte: ' + coins, W/2, 320);

    // Restart button
    const btnX = W/2 - 100;
    const btnY = 380;
    const btnW = 200;
    const btnH = 50;

    ctx.fillStyle = '#D4AF37';
    ctx.fillRect(btnX, btnY, btnW, btnH);
    ctx.strokeStyle = '#FFD700';
    ctx.lineWidth = 3;
    ctx.strokeRect(btnX, btnY, btnW, btnH);

    ctx.fillStyle = '#1a0a2e';
    ctx.font = 'bold 20px Arial';
    ctx.fillText('🔄 RIPROVA', W/2, btnY + 33);

    canvas.onclick = (e) => {
        const rect = canvas.getBoundingClientRect();
        const mx = (e.clientX - rect.left) * (W / rect.width);
        const my = (e.clientY - rect.top) * (H / rect.height);
        if (mx >= btnX && mx <= btnX + btnW && my >= btnY && my <= btnY + btnH) {
            score = 0;
            coins = 0;
            lives = 3;
            startLevel(0);
        }
    };
}

function drawBossWarning() {
    if (levels[currentLevel].boss && levels[currentLevel].boss.alive && player.x > levels[currentLevel].boss.x - 400) {
        ctx.fillStyle = 'rgba(255, 0, 0, 0.3)';
        ctx.fillRect(0, 0, W, H);

        ctx.fillStyle = '#FF0000';
        ctx.font = 'bold 32px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('⚠️ BOSS APPRODANDO! ⚠️', W/2, H/2 - 50);
    }
}

// Main game loop
function update() {
    if (gameState === 'PLAYING' || gameState === 'BOSS_FIGHT') {
        updatePlayer();
        updateEnemies();
        updateBoss();
        updateMovingPlatforms();
        updateRugs();
        updateSandstorms();
        updateCamera();

        if (screenShake > 0) screenShake--;
    }
}

function draw() {
    ctx.clearRect(0, 0, W, H);

    if (gameState === 'MENU') {
        drawMenu();
        return;
    }

    if (gameState === 'GAME_OVER') {
        drawGameOver();
        return;
    }

    if (gameState === 'LEVEL_COMPLETE') {
        drawLevelComplete();
        return;
    }

    // Apply screen shake
    ctx.save();
    if (screenShake > 0) {
        ctx.translate(Math.random() * screenShake - screenShake/2, Math.random() * screenShake - screenShake/2);
    }

    // Draw background
    drawBackground();

    const level = levels[currentLevel];

    // Draw water pools
    if (level.waterPools) {
        for (const pool of level.waterPools) {
            drawWaterPool(pool);
        }
    }

    // Draw platforms
    for (const plat of level.platforms) {
        drawPlatform(plat);
    }

    // Draw moving platforms
    for (const plat of level.movingPlatforms) {
        drawPlatform(plat);
    }

    // Draw rugs
    for (const rug of level.rugs) {
        drawRug(rug);
    }

    // Draw crates
    for (const crate of level.crates) {
        drawCrate(crate);
    }

    // Draw sandstorms
    for (const storm of (level.sandstorms || [])) {
        drawSandstorm(storm);
    }

    // Draw checkpoint
    drawCheckpoint(level.checkpoint);

    // Draw coins
    for (const coin of level.coins) {
        drawCoin(coin);
    }

    // Draw power-ups
    for (const pu of level.powerups) {
        drawPowerup(pu);
    }

    // Draw enemies
    for (const enemy of level.enemies) {
        if (!enemy.alive) continue;
        if (enemy.type === 'beetle') {
            drawBeetle(enemy.x - cameraX, enemy.y, enemy.w, enemy.h, enemy.animFrame);
        } else if (enemy.type === 'pigeon') {
            drawPigeon(enemy.x - cameraX, enemy.y, enemy.w, enemy.h, enemy.animFrame);
        } else if (enemy.type === 'bandit') {
            drawBandit(enemy.x - cameraX, enemy.y, enemy.w, enemy.h, enemy.animFrame);
        }
    }

    // Draw boss
    if (level.boss && level.boss.alive) {
        drawBoss(level.boss);
    }

    // Draw player
    if (!player.dead) {
        ctx.save();
        if (player.invincible > 0 && Math.floor(player.invincible / 4) % 2 === 0) {
            ctx.globalAlpha = 0.5;
        }
        drawVectorCharacter(player.x - cameraX, player.y, player.w, player.h, player.facing, player.animFrame, true);
        ctx.restore();
    }

    // Boss warning
    drawBossWarning();

    ctx.restore();

    // Draw UI
    drawUI();
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Start
gameLoop();
</script>
</body>
</html>

