const gamesData = [
{id:'wordle',title:'Word Puzzle',desc:'Guess the 5-letter word in 6 tries!',emoji:'📝',color:'#6C63FF',badge:'popular'},
{id:'sudoku',title:'Sudoku',desc:'Fill the grid with numbers 1-9!',emoji:'🔢',color:'#FF6584',badge:''},
