{id:'rain',title:'Rain Drop Game',desc:'Catch raindrops in your basket!',emoji:'🌧️',color:'#3498DB',badge:''},
{id:'rock',title:'Rock Drop',desc:'Build mountains by dropping rocks!',emoji:'🪨',color:'#2C3E50',badge:'new'},
