{id:'petcoloring',title:'Pet Coloring',desc:'Color adorable pet templates!',emoji:'🐾',color:'#FF9800',badge:''},
{id:'auction',title:'Auction Sim',desc:'Bid on items and win deals!',emoji:'🏷️',color:'#607D8B',badge:''},
{id:'craft',title:'Craft Building',desc:'Build amazing creations block by block!',emoji:'🔨',color:'#4CAF50',badge:'new'}
];

// ==================== NAVIGATION ====================
function toggleNav(){
document.getElementById('mainNav').classList.toggle('active');
}

function showPage(page){
document.querySelectorAll('.page').forEach(p=>p.style.display='none');
document.querySelectorAll('.game-page').forEach(g=>g.classList.remove('active'));
document.getElementById('mainNav').classList.remove('active');

switch(page){
case 'home':document.getElementById('homePage').style.display='block';break;
case 'games':document.getElementById('gamesPage').style.display='block';break;
case 'blog':document.getElementById('blogPage').style.display='block';break;
case 'about':document.getElementById('aboutPage').style.display='block';break;
case 'contact':document.getElementById('contactPage').style.display='block';break;
case 'privacy':document.getElementById('privacyPage').style.display='block';break;
case 'terms':document.getElementById('termsPage').style.display='block';break;
case 'sitemap':document.getElementById('sitemapPage').style.display='block';break;
}
window.scrollTo({top:0,behavior:'smooth'});
}

function openGame(gameId){
document.querySelectorAll('.page').forEach(p=>p.style.display='none');
document.querySelectorAll('.game-page').forEach(g=>g.classList.remove('active'));
document.getElementById(gameId+'Page').classList.add('active');
document.getElementById('mainNav').classList.remove('active');
window.scrollTo({top:0,behavior:'smooth'});

// Initialize games
if(gameId==='wordle')initWordle();
if(gameId==='sudoku')initSudoku();
if(gameId==='tictactoe')initTT();
if(gameId==='math')initMath();
if(gameId==='coloring')initColoring();
if(gameId==='drawing')initDrawing();
if(gameId==='rain')initRain();
if(gameId==='rock')initRock();
if(gameId==='story')initStory();
if(gameId==='petcoloring')initPetColoring();
if(gameId==='auction')initAuction();
if(gameId==='craft')initCraft();
}

// ==================== RENDER GAME CARDS ====================
function renderGameCards(){
const grid=document.getElementById('gamesGrid');
const popularGrid=document.getElementById('popularGrid');
const allGrid=document.getElementById('allGamesGrid');

gamesData.forEach(game=>{
const card=`<div class="game-card animate-in" onclick="openGame('${game.id}')">
<div class="game-thumb" style="background:${game.color}20">${game.emoji}
${game.badge?`<span class="game-badge ${game.badge}">${game.badge.toUpperCase()}</span>`:''}
