let wordleWord='',wordleGuesses=[],wordleCurrent='',wordleUsed=[],wordleGameOver=false;
const wordleWords=['HAPPY','LEARN','GAME','FUNNY','SMART','BRAIN','STUDY','READ','WRITE','PLAY','PUZZLE','COLOR','DRAW','MUSIC','DANCE','NATURE','OCEAN','MOUNTAIN','FOREST','GARDEN','ROCKET','PLANET','STAR','SUNNY','CLOUDY','WINDY','SNOWY','RAINY','BREEZE','FLOWER','TREE','BIRDS','FISH','HORSE','CAMEL','PANDA','TIGER','LION','EAGLE'];

function initWordle(){
wordleWord=wordleWords[Math.floor(Math.random()*wordleWords.length)];
wordleGuesses=[];
wordleCurrent='';
wordleUsed=[];
wordleGameOver=false;
document.getElementById('wordleMessage').textContent='';

const grid=document.getElementById('wordleGrid');
grid.innerHTML='';
for(let i=0;i<6;i++){
const row=document.createElement('div');
row.className='wordle-row';
for(let j=0;j<5;j++){
