function updateColorSwatches(){
document.querySelectorAll('#colorPalette .color-swatch').forEach(s=>{
s.classList.toggle('active',s.style.background===currentColor||rgbToHex(s.style.background)===currentColor);
});
}

function rgbToHex(rgb){
if(rgb.startsWith('#'))return rgb;
const match=rgb.match(/\d+/g);
if(!match)return rgb;
return '#'+match.slice(0,3).map(x=>parseInt(x).toString(16).padStart(2,'0')).join('');
}

function setTool(tool,btn){
currentTool=tool;
document.querySelectorAll('.color-tools button').forEach(b=>b.classList.remove('active'));
if(btn)btn.classList.add('active');
}

function setupCanvas(canvasId,drawFunc){
const canvas=document.getElementById(canvasId);
const ctx=canvas.getContext('2d');
let drawing=false;

canvas.addEventListener('mousedown',(e)=>{drawing=true;drawFunc(e,canvas,ctx);});
canvas.addEventListener('mousemove',(e)=>{if(drawing)drawFunc(e,canvas,ctx);});
canvas.addEventListener('mouseup',()=>drawing=false);
canvas.addEventListener('mouseleave',()=>drawing=false);

canvas.addEventListener('touchstart',(e)=>{e.preventDefault();drawing=true;drawFunc(e.touches[0],canvas,ctx);});
canvas.addEventListener('touchmove',(e)=>{e.preventDefault();if(drawing)drawFunc(e.touches[0],canvas,ctx);});
canvas.addEventListener('touchend',()=>drawing=false);
}

function drawColoring(e,canvas,ctx){
const rect=canvas.getBoundingClientRect();
const x=e.clientX-rect.left;
const y=e.clientY-rect.top;

ctx.beginPath();
ctx.arc(x,y,currentTool==='eraser'?20:5,0,Math.PI*2);
ctx.fillStyle=currentTool==='eraser'?'#FFFFFF':currentColor;
ctx.fill();
}

function clearCanvas(canvasId){
const canvas=document.getElementById(canvasId);
const ctx=canvas.getContext('2d');
ctx.clearRect(0,0,canvas.width,canvas.height);
}

function saveCanvas(canvasId){
