let rainCanvas,rainCtx,rainScore=0,rainLives=3,rainBest=0,rainRunning=false,rainPaused=false;
let raindrops=[],basket={x:200,y:370,width:60,height:20};
let rainAnimId=null;

function initRain(){
rainCanvas=document.getElementById('rainCanvas');
rainCtx=rainCanvas.getContext('2d');
rainScore=0;rainLives=3;rainRunning=false;rainPaused=false;
raindrops=[];
basket.x=200;
document.getElementById('rainScore').textContent='0';
document.getElementById('rainLives').textContent='3';
drawRainFrame();

rainCanvas.addEventListener('mousemove',(e)=>{
const rect=rainCanvas.getBoundingClientRect();
basket.x=e.clientX-rect.left-basket.width/2;
basket.x=Math.max(0,Math.min(rainCanvas.width-basket.width,basket.x));
});

rainCanvas.addEventListener('touchmove',(e)=>{
e.preventDefault();
const rect=rainCanvas.getBoundingClientRect();
basket.x=e.touches[0].clientX-rect.left-basket.width/2;
basket.x=Math.max(0,Math.min(rainCanvas.width-basket.width,basket.x));
});
}

function startRain(){
if(rainRunning)return;
rainRunning=true;rainPaused=false;
raindrops=[];
gameLoop();
}

function pauseRain(){
rainPaused=!rainPaused;
if(!rainPaused)gameLoop();
}

function gameLoop(){
if(!rainRunning||rainPaused)return;
rainCtx.clearRect(0,0,rainCanvas.width,rainCanvas.height);

// Draw sky
rainCtx.fillStyle='#87CEEB';
rainCtx.fillRect(0,0,rainCanvas.width,rainCanvas.height);

// Draw ground
rainCtx.fillStyle='#90EE90';
rainCtx.fillRect(0,rainCanvas.height-30,rainCanvas.width,30);

// Spawn raindrops
if(Math.random()<0.03){
raindrops.push({
x:Math.random()*rainCanvas.width,
y:-10,
speed:2+Math.random()*3,
isRock:Math.random()<0.2,
size:5+Math.random()*5
});
}

// Update and draw raindrops
raindrops.forEach((drop,i)=>{
drop.y+=drop.speed;

rainCtx.beginPath();
rainCtx.arc(drop.x,drop.y,drop.size,0,Math.PI*2);
rainCtx.fillStyle=drop.isRock?'#8B4513':'#3498DB';
rainCtx.fill();

// Check collision with basket
if(drop.y>basket.y&&drop.y<basket.y+basket.height&&drop.x>basket.x&&drop.x<basket.x+basket.width){
if(drop.isRock){
rainLives--;
document.getElementById('rainLives').textContent=rainLives;
if(rainLives<=0){
rainRunning=false;
if(rainScore>rainBest)rainBest=rainScore;
document.getElementById('rainBest').textContent=rainBest;
showModal('💔 Game Over!','Score: '+rainScore);
}
}else{
rainScore+=10;
document.getElementById('rainScore').textContent=rainScore;
}
raindrops.splice(i,1);
}

if(drop.y>rainCanvas.height){
raindrops.splice(i,1);
}
});

// Draw basket
rainCtx.fillStyle='#8B4513';
rainCtx.fillRect(basket.x,basket.y,basket.width,basket.height);
rainCtx.fillStyle='#A0522D';
rainCtx.fillRect(basket.x+5,basket.y-5,basket.width-10,5);

rainAnimId=requestAnimationFrame(gameLoop);
}

function drawRainFrame(){
rainCtx.clearRect(0,0,rainCanvas.width,rainCanvas.height);
rainCtx.fillStyle='#87CEEB';
rainCtx.fillRect(0,0,rainCanvas.width,rainCanvas.height);
rainCtx.fillStyle='#90EE90';
rainCtx.fillRect(0,rainCanvas.height-30,rainCanvas.width,30);
rainCtx.fillStyle='#8B4513';
rainCtx.fillRect(basket.x,basket.y,basket.width,basket.height);
}

// ==================== ROCK DROP GAME ====================
let rockCanvas,rockCtx,rockScore=0,rockTarget=50,rocks=[];

function initRock(){
rockCanvas=document.getElementById('rockCanvas');
rockCtx=rockCanvas.getContext('2d');
rockScore=0;rocks=[];
document.getElementById('rockScore').textContent='0';
document.getElementById('rockTarget').textContent='50';
drawRockFrame();
}

function dropRock(){
const rock={
x:50+Math.random()*(rockCanvas.width-100),
y:0,
size:15+Math.random()*20,
speed:2+Math.random()*2,
rotation:0,
rotSpeed:(Math.random()-0.5)*0.1
};
rocks.push(rock);
animateRock(rock);
}

function animateRock(rock){
if(!rockCanvas)return;
rock.y+=rock.speed;
rock.rotation+=rock.rotSpeed;

rockCtx.clearRect(0,0,rockCanvas.width,rockCanvas.height);

// Draw sky
const gradient=rockCtx.createLinearGradient(0,0,0,rockCanvas.height);
gradient.addColorStop(0,'#87CEEB');
gradient.addColorStop(1,'#90EE90');
rockCtx.fillStyle=gradient;
rockCtx.fillRect(0,0,rockCanvas.width,rockCanvas.height);

// Draw mountains
rockCtx.fillStyle='#2C3E50';
rockCtx.beginPath();
rockCtx.moveTo(0,rockCanvas.height);
rockCtx.lineTo(100,rockCanvas.height-150);
rockCtx.lineTo(200,rockCanvas.height-80);
rockCtx.lineTo(300,rockCanvas.height-200);
rockCtx.lineTo(400,rockCanvas.height-100);
rockCtx.lineTo(500,rockCanvas.height);
rockCtx.fill();

// Draw rocks
rocks.forEach(r=>{
rockCtx.save();
rockCtx.translate(r.x,r.y);
rockCtx.rotate(r.rotation);
rockCtx.fillStyle='#8B7355';
rockCtx.beginPath();
rockCtx.arc(0,0,r.size,0,Math.PI*2);
rockCtx.fill();
rockCtx.strokeStyle='#6B5B45';
rockCtx.lineWidth=2;
rockCtx.stroke();
rockCtx.restore();
});

// Draw basket
rockCtx.fillStyle='#8B4513';
rockCtx.fillRect(rockCanvas.width/2-40,rockCanvas.height-40,80,30);

if(rock.y<rockCanvas.height-50){
requestAnimationFrame(()=>animateRock(rock));
}else{
rockScore+=Math.floor(rock.size);
document.getElementById('rockScore').textContent=rockScore;
if(rockScore>=rockTarget){
showModal('🏆 You Won!','You reached the target of '+rockTarget+' points!');
}
}
}

function resetRock(){
rockScore=0;rocks=[];
document.getElementById('rockScore').textContent='0';
drawRockFrame();
}

function drawRockFrame(){
rockCtx.clearRect(0,0,rockCanvas.width,rockCanvas.height);
const gradient=rockCtx.createLinearGradient(0,0,0,rockCanvas.height);
gradient.addColorStop(0,'#87CEEB');
gradient.addColorStop(1,'#90EE90');
rockCtx.fillStyle=gradient;
rockCtx.fillRect(0,0,rockCanvas.width,rockCanvas.height);
rockCtx.fillStyle='#2C3E50';
rockCtx.beginPath();
rockCtx.moveTo(0,rockCanvas.height);
rockCtx.lineTo(100,rockCanvas.height-150);
rockCtx.lineTo(200,rockCanvas.height-80);
rockCtx.lineTo(300,rockCanvas.height-200);
rockCtx.lineTo(400,rockCanvas.height-100);
rockCtx.lineTo(500,rockCanvas.height);
rockCtx.fill();
rockCtx.fillStyle='#8B4513';
rockCtx.fillRect(rockCanvas.width/2-40,rockCanvas.height-40,80,30);
}

