let auctionBids=0,auctionCurrentBid=50,auctionHistory=[];
const auctionItems=[
{name:'🎁 Vintage Radio',price:50},
{name:'📷 Classic Camera',price:75},
{name:'🎸 Electric Guitar',price:120},
{name:'📚 Rare Book Collection',price:200},
{name:'🎨 Oil Painting',price:150},
{name:'⌚ Luxury Watch',price:300},
{name:'🎮 Gaming Console',price:80},
{name:'👗 Designer Dress',price:250}
];

function initAuction(){
const item=auctionItems[Math.floor(Math.random()*auctionItems.length)];
document.getElementById('auctionItemName').textContent=item.name;
auctionCurrentBid=item.price;
auctionBids=0;
auctionHistory=[];
document.getElementById('auctionPrice').textContent='$'+auctionCurrentBid;
document.getElementById('auctionBids').textContent='Current bids: 0';
document.getElementById('auctionHistory').innerHTML='';
document.getElementById('bidInput').value='';
}

function placeBid(){
const bid=parseInt(document.getElementById('bidInput').value);
if(!bid||bid<=auctionCurrentBid){
showToast('❌ Bid must be higher than $'+auctionCurrentBid);
return;
}
auctionBids++;
auctionHistory.push({bid:bid,user:'You',time:new Date().toLocaleTimeString()});
auctionCurrentBid=bid;
document.getElementById('auctionPrice').textContent='$'+auctionCurrentBid;
document.getElementById('auctionBids').textContent='Current bids: '+auctionBids;
document.getElementById('bidInput').value='';

// Simulate other bidders
if(auctionBids<5){
setTimeout(()=>{
const otherBid=bid+Math.floor(Math.random()*50)+10;
auctionBids++;
auctionHistory.push({bid:otherBid,user:'Bidder '+Math.floor(Math.random()*99),time:new Date().toLocaleTimeString()});
auctionCurrentBid=otherBid;
document.getElementById('auctionPrice').textContent='$'+auctionCurrentBid;
document.getElementById('auctionBids').textContent='Current bids: '+auctionBids;
renderAuctionHistory();
},1000);
}

if(auctionBids>=5){
showModal('🏆 Auction Closed!','You won '+auctionItems.find(a=>a.name===document.getElementById('auctionItemName').textContent).name+' for $'+auctionCurrentBid+'!');
}

renderAuctionHistory();
}

function passBid(){
showToast('⏭️ You passed. Let others bid!');
// Simulate another bid
setTimeout(()=>{
const otherBid=auctionCurrentBid+Math.floor(Math.random()*50)+10;
auctionBids++;
auctionHistory.push({bid:otherBid,user:'Bidder '+Math.floor(Math.random()*99),time:new Date().toLocaleTimeString()});
auctionCurrentBid=otherBid;
document.getElementById('auctionPrice').textContent='$'+auctionCurrentBid;
document.getElementById('auctionBids').textContent='Current bids: '+auctionBids;
renderAuctionHistory();
},1500);
}

function renderAuctionHistory(){
const historyDiv=document.getElementById('auctionHistory');
historyDiv.innerHTML='<h4 style="margin-bottom:10px">📋 Bid History</h4>';
auctionHistory.slice().reverse().forEach(bid=>{
historyDiv.innerHTML+=`<div style="padding:8px 12px;background:#f0f0ff;border-radius:8px;margin-bottom:5px;display:flex;justify-content:space-between">
<span>${bid.user}</span><span style="font-weight:700;color:var(--primary)">$${bid.bid}</span><span style="color:var(--text-light);font-size:0.8rem">${bid.time}</span>
</div>`;
});
}

// ==================== CRAFT BUILDING ====================
let craftTool='block';
const craftColors=['#E74C3C','#FF6584','#FFA502','#FFD700','#00C9A7','#6C63FF','#9B59B6','#3498DB','#2C3E50','#FFFFFF','#8B4513','#4CAF50'];

function initCraft(){
const palette=document.getElementById('craftPalette');
palette.innerHTML='';
craftColors.forEach(color=>{
const swatch=document.createElement('div');
swatch.className='color-swatch';
swatch.style.background=color;
swatch.onclick=()=>{currentColor=color;};
palette.appendChild(swatch);
});
setupCanvas('craftCanvas',drawCraft);
}

function setCraftTool(tool,btn){
craftTool=tool;
document.querySelectorAll('.color-tools button').forEach(b=>b.classList.remove('active'));
if(btn)btn.classList.add('active');
}

function drawCraft(e,canvas,ctx){
const rect=canvas.getBoundingClientRect();
const x=Math.floor((e.clientX-rect.left)/40)*40;
const y=Math.floor((e.clientY-rect.top)/40)*40;

if(craftTool==='erase'){
ctx.clearRect(x,y,40,40);
}else{
ctx.fillStyle=currentColor;
ctx.fillRect(x+1,y+1,38,38);
ctx.strokeStyle='#ddd';
ctx.strokeRect(x,y,40,40);
}
}

// ==================== UTILITIES ====================
function showModal(title,message){
document.getElementById('modalTitle').textContent=title;
document.getElementById('modalMessage').textContent=message;
document.getElementById('gameModal').classList.add('active');
}

function closeModal(){
document.getElementById('gameModal').classList.remove('active');
}

function showToast(message){
const toast=document.getElementById('toast');
toast.textContent=message;
toast.classList.add('show');
setTimeout(()=>toast.classList.remove('show'),3000);
}

function submitContact(){
const name=document.getElementById('contactName').value;
const email=document.getElementById('contactEmail').value;
const message=document.getElementById('contactMessage').value;
if(!name||!email||!message){
showToast('❌ Please fill in all fields!');
return;
}
showModal('📤 Message Sent!','Thank you, '+name+'! We\'ll get back to you soon.');
document.getElementById('contactName').value='';
document.getElementById('contactEmail').value='';
document.getElementById('contactSubject').value='';
document.getElementById('contactMessage').value='';
}

// Close modal on outside click
document.getElementById('gameModal').addEventListener('click',function(e){
if(e.target===this)closeModal();
});

// Initialize
renderGameCards();
</script>
