        onGround: player.onGround,
        jumps: player.jumps
    };

    clones.push({
        x: player.x,
        y: player.y,
        vx: 0,
        vy: 0,
        width: 30,
        height: 40,
        facing: player.facing,
        onGround: false,
        trail: [],
        record: [record],
        alive: true,
        alpha: 0.7,
        color: '#7b2ff7'
    });

    isRecording = false;
}

