    // Move X
    player.x += player.vx;
    checkCollisionX(player);

    // Move Y
    player.y += player.vy;
    player.onGround = false;
    checkCollisionY(player);

    // Wall slide
    if (player.onWall && player.vy > 0) {
        player.vy *= 0.8;
    }

    // Trail
    player.trail.push({ x: player.x, y: player.y, alpha: 1 });
    if (player.trail.length > 10) player.trail.shift();
    player.trail.forEach(t => t.alpha -= 0.1);

    // Step sound
    if (player.onGround && Math.abs(player.vx) > 0) {
        player.stepTimer++;
        if (player.stepTimer > 15) {
            playSound('step');
            player.stepTimer = 0;
        }
    }

