        cloneRecord.push({
            time: Date.now() - recordStartTime,
            x: player.x,
            y: player.y,
            vx: player.vx,
            vy: player.vy,
            facing: player.facing,
            onGround: player.onGround,
            jumps: player.jumps
        });
    }

