        if (!c.collected) {
            let dx = (player.x + player.width / 2) - c.x;
            let dy = (player.y + player.height / 2) - c.y;
            let dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < c.radius + 20) {
                c.collected = true;
                playSound('collect');
                for (let i = 0; i < 10; i++) {
                    particles.push({
                        x: c.x, y: c.y,
                        vx: (Math.random() - 0.5) * 6,
                        vy: (Math.random() - 0.5) * 6,
                        life: 30, maxLife: 30,
                        color: '#ffd700', size: 3
                    });
