@import url('https://fonts.googleapis.com/css2?family=MedievalSharp&family=Noto+Sans+SC:wght@400;700&display=swap');

:root {
  --parchment: #2a1f14;
  --parchment-light: #3d2b1a;
  --parchment-lighter: #5a3d25;
  --gold: #d4a843;
  --gold-bright: #f0c850;
  --red: #c0392b;
  --green: #27ae60;
  --blue: #2980b9;
  --purple: #8e44ad;
  --orange: #e67e22;
  --text: #e8d5b7;
  --text-dim: #a89070;
  --border: #6b4c30;
  --shadow: rgba(0,0,0,0.6);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: #1a120b;
  color: var(--text);
  font-family: 'Noto Sans SC', 'MedievalSharp', serif;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
}

#game-container {
  display: grid;
  grid-template-columns: 280px 1fr 300px;
  grid-template-rows: 60px 1fr 200px;
  height: 100vh;
  gap: 4px;
  background: #0d0a06;
  padding: 4px;
}

/* Header */
#header {
  grid-column: 1 / -1;
  background: linear-gradient(180deg, var(--parchment-light), var(--parchment));
  border: 2px solid var(--border);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  box-shadow: 0 2px 10px var(--shadow);
}

#header h1 {
  font-family: 'MedievalSharp', serif;
  color: var(--gold-bright);
  font-size: 1.4em;
  text-shadow: 0 0 10px rgba(212,168,67,0.5);
  letter-spacing: 2px;
}

#header-info {
  display: flex;
  gap: 20px;
  font-size: 0.85em;
}

.header-stat {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  background: rgba(0,0,0,0.3);
  border-radius: 4px;
  border: 1px solid var(--border);
}

/* Left Panel - Status */
#left-panel {
  background: linear-gradient(180deg, var(--parchment-light), var(--parchment));
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 12px;
  overflow-y: auto;
  box-shadow: 0 2px 10px var(--shadow);
}

#left-panel::-webkit-scrollbar { width: 6px; }
#left-panel::-webkit-scrollbar-track { background: var(--parchment); }
#left-panel::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

.panel-title {
  color: var(--gold);
  font-size: 0.9em;
  font-weight: 700;
  border-bottom: 1px solid var(--border);
  padding-bottom: 6px;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.player-info {
  margin-bottom: 12px;
}

.player-name {
  font-size: 1.1em;
  color: var(--gold-bright);
  font-weight: 700;
  margin-bottom: 4px;
}

.player-class {
  font-size: 0.8em;
  color: var(--text-dim);
  margin-bottom: 8px;
}

.bar-container {
  margin-bottom: 6px;
}

.bar-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.75em;
  margin-bottom: 2px;
}

.bar {
  height: 14px;
  background: rgba(0,0,0,0.4);
  border-radius: 7px;
  overflow: hidden;
  border: 1px solid var(--border);
}

.bar-fill {
  height: 100%;
  border-radius: 7px;
  transition: width 0.5s ease;
  position: relative;
}

.bar-fill.hp { background: linear-gradient(90deg, #c0392b, #e74c3c); }
.bar-fill.mp { background: linear-gradient(90deg, #2980b9, #3498db); }
.bar-fill.xp { background: linear-gradient(90deg, #27ae60, #2ecc71); }
.bar-fill.stamina { background: linear-gradient(90deg, #e67e22, #f39c12); }

.attributes-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  margin-bottom: 12px;
}

.attr-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  background: rgba(0,0,0,0.2);
  border-radius: 4px;
  border: 1px solid rgba(107,76,48,0.5);
  font-size: 0.8em;
}

.attr-icon { font-size: 1.1em; }
.attr-name { color: var(--text-dim); font-size: 0.85em; }
.attr-value { color: var(--gold-bright); font-weight: 700; margin-left: auto; }

.skill-trees {
  margin-bottom: 12px;
}

.skill-tree {
  margin-bottom: 8px;
  padding: 6px;
  background: rgba(0,0,0,0.2);
  border-radius: 4px;
  border: 1px solid rgba(107,76,48,0.5);
}

.skill-tree-name {
  font-size: 0.8em;
  color: var(--gold);
  margin-bottom: 4px;
}

.skill-tree-bar {
  height: 6px;
  background: rgba(0,0,0,0.4);
  border-radius: 3px;
  overflow: hidden;
}

.skill-tree-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s;
}

.skill-tree-fill.fury { background: linear-gradient(90deg, #c0392b, #e74c3c); }
.skill-tree-fill.arcane { background: linear-gradient(90deg, #8e44ad, #9b59b6); }
.skill-tree-fill.nature { background: linear-gradient(90deg, #27ae60, #2ecc71); }

.faction-rep {
  margin-bottom: 8px;
}

.rep-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 6px;
  font-size: 0.75em;
  margin-bottom: 2px;
  background: rgba(0,0,0,0.15);
  border-radius: 3px;
}

.rep-bar {
  flex: 1;
  height: 4px;
  background: rgba(0,0,0,0.3);
  border-radius: 2px;
  overflow: hidden;
}

.rep-fill {
  height: 100%;
  border-radius: 2px;
  transition: width 0.3s;
}

.rep-fill.honor { background: var(--gold); }
.rep-fill.dark { background: var(--purple); }
.rep-fill.nature-rep { background: var(--green); }
.rep-fill.merchant { background: var(--orange); }
.rep-fill.knowledge { background: var(--blue); }

/* Center Panel - Main Display */
#center-panel {
  background: linear-gradient(180deg, var(--parchment), #1e150c);
  border: 2px solid var(--border);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 2px 10px var(--shadow);
}

#map-area {
  flex: 1;
  padding: 12px;
  overflow: hidden;
  position: relative;
}

#ascii-map {
  font-family: 'Courier New', monospace;
  font-size: 12px;
  line-height: 1.2;
  white-space: pre;
  color: var(--text-dim);
  text-align: center;
  padding: 10px;
  background: rgba(0,0,0,0.3);
  border-radius: 6px;
  border: 1px solid var(--border);
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
}

#location-info {
  padding: 12px;
  border-top: 1px solid var(--border);
  background: rgba(0,0,0,0.2);
}

#location-name {
  font-size: 1.2em;
  color: var(--gold-bright);
  font-weight: 700;
  margin-bottom: 4px;
}

#location-desc {
  font-size: 0.85em;
  color: var(--text);
  line-height: 1.6;
  margin-bottom: 8px;
}

#weather-time {
  display: flex;
  gap: 15px;
  font-size: 0.8em;
  color: var(--text-dim);
  margin-bottom: 8px;
}

#action-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 8px 12px;
  border-top: 1px solid var(--border);
  background: rgba(0,0,0,0.15);
}

.action-btn {
  padding: 6px 14px;
  background: linear-gradient(180deg, var(--parchment-lighter), var(--parchment));
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text);
  font-family: inherit;
  font-size: 0.8em;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}

.action-btn:hover {
  background: linear-gradient(180deg, var(--gold), var(--gold-bright));
  color: #1a120b;
  border-color: var(--gold-bright);
  transform: translateY(-1px);
  box-shadow: 0 2px 8px rgba(212,168,67,0.3);
}

.action-btn:active { transform: translateY(0); }
.action-btn.danger { border-color: var(--red); color: var(--red); }
.action-btn.danger:hover { background: var(--red); color: white; }
.action-btn.special { border-color: var(--purple); color: var(--purple); }
.action-btn.special:hover { background: var(--purple); color: white; }

/* Right Panel - Quests & Info */
#right-panel {
  background: linear-gradient(180deg, var(--parchment-light), var(--parchment));
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 12px;
  overflow-y: auto;
  box-shadow: 0 2px 10px var(--shadow);
}

#right-panel::-webkit-scrollbar { width: 6px; }
#right-panel::-webkit-scrollbar-track { background: var(--parchment); }
#right-panel::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

.quest-item {
  padding: 8px;
  margin-bottom: 6px;
  background: rgba(0,0,0,0.2);
  border-radius: 4px;
  border-left: 3px solid var(--gold);
  font-size: 0.8em;
}

.quest-item.main { border-left-color: var(--gold-bright); }
.quest-item.side { border-left-color: var(--blue); }
.quest-item.bounty { border-left-color: var(--red); }
.quest-item.hidden { border-left-color: var(--purple); }

.quest-title {
  font-weight: 700;
  margin-bottom: 2px;
  color: var(--text);
}

.quest-desc {
  color: var(--text-dim);
  font-size: 0.9em;
  line-height: 1.4;
}

.quest-reward {
  color: var(--gold);
  font-size: 0.85em;
  margin-top: 4px;
}

.quest-progress {
  margin-top: 4px;
  font-size: 0.8em;
  color: var(--green);
}

/* Bottom Panel - Command & Log */
#bottom-panel {
  grid-column: 1 / -1;
  background: linear-gradient(180deg, var(--parchment), #1a120b);
  border: 2px solid var(--border);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  box-shadow: 0 2px 10px var(--shadow);
}

#game-log {
  flex: 1;
  padding: 10px 12px;
  overflow-y: auto;
  font-size: 0.85em;
  line-height: 1.6;
  background: rgba(0,0,0,0.3);
  border-bottom: 1px solid var(--border);
}

#game-log::-webkit-scrollbar { width: 6px; }
#game-log::-webkit-scrollbar-track { background: var(--parchment); }
#game-log::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

.log-entry {
  margin-bottom: 4px;
  padding: 2px 0;
  border-bottom: 1px solid rgba(107,76,48,0.2);
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}

.log-entry.combat { color: var(--red); }
.log-entry.item { color: var(--green); }
.log-entry.quest { color: var(--gold); }
.log-entry.system { color: var(--text-dim); }
.log-entry.event { color: var(--purple); }
.log-entry.damage { color: #e74c3c; }
.log-entry.heal { color: #2ecc71; }
.log-entry.info { color: var(--blue); }

#command-area {
  display: flex;
  padding: 8px 12px;
  gap: 8px;
  background: rgba(0,0,0,0.2);
}

#command-input {
  flex: 1;
  padding: 8px 12px;
  background: rgba(0,0,0,0.4);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text);
  font-family: 'Courier New', monospace;
  font-size: 0.9em;
  outline: none;
  transition: border-color 0.2s;
}

#command-input:focus {
  border-color: var(--gold);
  box-shadow: 0 0 8px rgba(212,168,67,0.2);
}

#command-input::placeholder {
  color: var(--text-dim);
  opacity: 0.6;
}

#send-btn {
  padding: 8px 20px;
  background: linear-gradient(180deg, var(--gold), var(--gold-bright));
  border: none;
  border-radius: 4px;
  color: #1a120b;
  font-family: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
}

#send-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 2px 8px rgba(212,168,67,0.4);
}

/* Combat Overlay */
#combat-overlay {
  display: none;
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0,0,0,0.85);
  z-index: 1000;
  justify-content: center;
  align-items: center;
}

#combat-overlay.active { display: flex; }

#combat-container {
  width: 90%;
  max-width: 900px;
  max-height: 90vh;
  background: linear-gradient(180deg, var(--parchment-light), var(--parchment));
  border: 3px solid var(--gold);
  border-radius: 12px;
  padding: 20px;
  overflow-y: auto;
  box-shadow: 0 0 30px rgba(212,168,67,0.3);
}

#combat-header {
  text-align: center;
  margin-bottom: 15px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--border);
}

#combat-header h2 {
  color: var(--red);
  font-size: 1.3em;
  text-shadow: 0 0 10px rgba(192,57,43,0.5);
}

#combat-area {
  display: flex;
  justify-content: space-between;
  margin-bottom: 15px;
  gap: 20px;
}

#player-combat-side {
  flex: 1;
  padding: 15px;
  background: rgba(0,0,0,0.3);
  border-radius: 8px;
  border: 1px solid var(--border);
}

#enemy-combat-side {
  flex: 2;
  padding: 15px;
  background: rgba(0,0,0,0.3);
  border-radius: 8px;
  border: 1px solid var(--border);
}

.combatant {
  margin-bottom: 10px;
  padding: 8px;
  background: rgba(0,0,0,0.2);
  border-radius: 6px;
  border: 1px solid rgba(107,76,48,0.5);
}

.combatant-name {
  font-weight: 700;
  margin-bottom: 4px;
  display: flex;
  justify-content: space-between;
}

.combatant-bars {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.combat-bar {
  height: 8px;
  background: rgba(0,0,0,0.4);
  border-radius: 4px;
  overflow: hidden;
}

.combat-bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.3s;
}

.combat-bar-fill.hp { background: linear-gradient(90deg, #c0392b, #e74c3c); }
.combat-bar-fill.mp { background: linear-gradient(90deg, #2980b9, #3498db); }

.status-effects {
  display: flex;
  gap: 4px;
  margin-top: 4px;
  flex-wrap: wrap;
}

.status-badge {
  padding: 2px 6px;
  background: rgba(0,0,0,0.3);
  border-radius: 3px;
  font-size: 0.7em;
  border: 1px solid var(--border);
}

.status-badge.buff { border-color: var(--green); color: var(--green); }
.status-badge.debuff { border-color: var(--red); color: var(--red); }

#combat-log {
  max-height: 150px;
  overflow-y: auto;
  padding: 10px;
  background: rgba(0,0,0,0.3);
  border-radius: 6px;
  margin-bottom: 15px;
  font-size: 0.85em;
  line-height: 1.5;
}

#combat-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.combat-btn {
  padding: 8px 16px;
  background: linear-gradient(180deg, var(--parchment-lighter), var(--parchment));
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text);
  font-family: inherit;
  font-size: 0.85em;
  cursor: pointer;
  transition: all 0.2s;
  min-width: 80px;
}

.combat-btn:hover {
  background: linear-gradient(180deg, var(--gold), var(--gold-bright));
  color: #1a120b;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(212,168,67,0.3);
}

.combat-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.combat-btn.attack { border-color: var(--red); }
.combat-btn.skill { border-color: var(--purple); }
.combat-btn.defend { border-color: var(--blue); }
.combat-btn.item-btn { border-color: var(--green); }
.combat-btn.flee { border-color: var(--orange); }

/* Inventory Modal */
#inventory-modal {
  display: none;
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0,0,0,0.8);
  z-index: 999;
  justify-content: center;
  align-items: center;
}

#inventory-modal.active { display: flex; }

#inventory-container {
  width: 80%;
  max-width: 700px;
  max-height: 80vh;
  background: linear-gradient(180deg, var(--parchment-light), var(--parchment));
  border: 2px solid var(--gold);
  border-radius: 12px;
  padding: 20px;
  overflow-y: auto;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--border);
}

.modal-header h2 {
  color: var(--gold-bright);
  font-size: 1.2em;
}

.close-btn {
  padding: 4px 12px;
  background: var(--red);
  border: none;
  border-radius: 4px;
  color: white;
  cursor: pointer;
  font-family: inherit;
}

.inventory-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 8px;
  margin-bottom: 15px;
}

.inv-item {
  padding: 10px;
  background: rgba(0,0,0,0.3);
  border-radius: 6px;
  border: 1px solid var(--border);
  text-align: center;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 0.8em;
}

.inv-item:hover {
  border-color: var(--gold);
  transform: translateY(-2px);
  box-shadow: 0 4px 8px var(--shadow);
}

.inv-item.equipped {
  border-color: var(--gold-bright);
  background: rgba(212,168,67,0.1);
}

.inv-item.rarity-common { border-color: #95a5a6; }
.inv-item.rarity-uncommon { border-color: var(--green); }
.inv-item.rarity-rare { border-color: var(--blue); }
.inv-item.rarity-epic { border-color: var(--purple); }
.inv-item.rarity-legendary { border-color: var(--gold-bright); box-shadow: 0 0 10px rgba(240,200,80,0.3); }

.inv-item-icon { font-size: 1.5em; margin-bottom: 4px; }
.inv-item-name { font-weight: 700; margin-bottom: 2px; }
.inv-item-desc { color: var(--text-dim); font-size: 0.85em; }
.inv-item-stats { color: var(--gold); font-size: 0.8em; margin-top: 4px; }

/* Equipment Slots */
.equipment-slots {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 15px;
}

.equip-slot {
  padding: 10px;
  background: rgba(0,0,0,0.3);
  border-radius: 6px;
  border: 1px dashed var(--border);
  text-align: center;
  font-size: 0.8em;
  min-height: 60px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.equip-slot.filled {
  border-style: solid;
  border-color: var(--gold);
}

.equip-slot-label {
  color: var(--text-dim);
  font-size: 0.85em;
  margin-bottom: 4px;
}

/* Shop */
#shop-modal {
  display: none;
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0,0,0,0.8);
  z-index: 999;
  justify-content: center;
  align-items: center;
}

#shop-modal.active { display: flex; }

#shop-container {
  width: 80%;
  max-width: 700px;
  max-height: 80vh;
  background: linear-gradient(180deg, var(--parchment-light), var(--parchment));
  border: 2px solid var(--gold);
