  font-size: 0.8em;
}

.shop-buy-btn:hover { background: #2ecc71; }
.shop-buy-btn:disabled { opacity: 0.5; cursor: not-allowed; }

/* Achievements */
#achievement-popup {
  display: none;
  position: fixed;
  top: 20px;
  right: 20px;
  background: linear-gradient(180deg, var(--parchment-light), var(--parchment));
  border: 2px solid var(--gold-bright);
  border-radius: 8px;
  padding: 15px 20px;
  z-index: 1001;
  box-shadow: 0 0 20px rgba(240,200,80,0.4);
  animation: slideIn 0.5s ease, fadeOut 0.5s ease 3s forwards;
  max-width: 300px;
}

@keyframes slideIn {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

@keyframes fadeOut {
  to { opacity: 0; transform: translateX(100%); }
}

#achievement-popup h3 {
  color: var(--gold-bright);
  margin-bottom: 5px;
  font-size: 0.9em;
}

#achievement-popup p {
  font-size: 0.8em;
  color: var(--text);
}

/* Collection */
.collection-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
  gap: 6px;
  margin-top: 10px;
}

.collection-item {
  padding: 8px;
  background: rgba(0,0,0,0.3);
  border-radius: 4px;
  text-align: center;
  font-size: 0.75em;
  border: 1px solid var(--border);
}

.collection-item.collected {
  border-color: var(--gold);
  background: rgba(212,168,67,0.1);
}

.collection-item.uncollected {
  opacity: 0.4;
}

/* Tooltip */
#tooltip {
  display: none;
  position: fixed;
  background: linear-gradient(180deg, #1a120b, #2a1f14);
  border: 1px solid var(--gold);
  border-radius: 6px;
  padding: 10px 14px;
  z-index: 1002;
  max-width: 250px;
  font-size: 0.8em;
  box-shadow: 0 4px 12px var(--shadow);
  pointer-events: none;
}

#tooltip .tt-name {
  font-weight: 700;
  color: var(--gold-bright);
  margin-bottom: 4px;
}

#tooltip .tt-desc {
  color: var(--text-dim);
  margin-bottom: 4px;
  line-height: 1.4;
}

#tooltip .tt-stats {
  color: var(--green);
  font-size: 0.9em;
}

#tooltip .tt-rarity {
  font-size: 0.85em;
  margin-top: 4px;
}

/* Responsive */
@media (max-width: 1200px) {
  #game-container {
    grid-template-columns: 240px 1fr 260px;
  }
}

@media (max-width: 900px) {
  #game-container {
    grid-template-columns: 1fr;
    grid-template-rows: 50px 1fr 150px;
  }
  #left-panel, #right-panel {
    display: none;
  }
}

/* Animations */
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

.pulse { animation: pulse 2s infinite; }

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}

.shake { animation: shake 0.3s ease; }

/* Tab system for right panel */
.tab-buttons {
  display: flex;
  gap: 4px;
  margin-bottom: 10px;
}

.tab-btn {
  flex: 1;
  padding: 6px;
  background: rgba(0,0,0,0.3);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text-dim);
  font-family: inherit;
  font-size: 0.75em;
  cursor: pointer;
  transition: all 0.2s;
}

.tab-btn.active {
  background: var(--gold);
  color: #1a120b;
  border-color: var(--gold-bright);
}

.tab-content { display: none; }
.tab-content.active { display: block; }

/* Mini map indicator */
.map-indicator {
  position: absolute;
  top: 10px;
