<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Game State
const game = {
money: 100,
day: 1,
hour: 6,
minute: 0,
score: 0,
harvested: 0,
tool: 'plow',
shopOpen: false,
seeds: { wheat: 5, corn: 3, tomato: 0, carrot: 0 },
fertilizer: 0,
tractorSpeed: 2,
tractorUpgradeLevel: 1,
particles: [],
floatingTexts: [],
fields: [],
trees: [],
clouds: [],
sunPosition: { x: 400, y: 50 },
isNight: false,
nightAlpha: 0
};

// Tractor
const tractor = {
x: 400,
y: 300,
width: 40,
height: 50,
direction: 'down',
speed: 2,
animFrame: 0,
animTimer: 0
};

// Initialize fields
function initFields() {
const fieldPositions = [
{ x: 50, y: 80, w: 150, h: 100 },
{ x: 250, y: 80, w: 150, h: 100 },
{ x: 450, y: 80, w: 150, h: 100 },
{ x: 650, y: 80, w: 100, h: 100 },
{ x: 50, y: 250, w: 150, h: 100 },
{ x: 250, y: 250, w: 150, h: 100 },
{ x: 450, y: 250, w: 150, h: 100 },
{ x: 650, y: 250, w: 100, h: 100 },
{ x: 50, y: 420, w: 200, h: 100 },
{ x: 300, y: 420, w: 200, h: 100 },
{ x: 550, y: 420, w: 200, h: 100 }
];

fieldPositions.forEach((pos, i) => {
game.fields.push({
...pos,
id: i,
plowed: false,
plowProgress: 0,
planted: false,
cropType: null,
growth: 0,
watered: false,
waterTimer: 0,
harvested: false,
fertilized: false,
color: '#5a8f3c'
});
});
}

// Initialize trees
function initTrees() {
const treePositions = [
{ x: 100, y: 550 }, { x: 200, y: 560 }, { x: 350, y: 555 },
{ x: 500, y: 560 }, { x: 650, y: 550 }, { x: 750, y: 555 },
{ x: 30, y: 200 }, { x: 770, y: 200 }, { x: 30, y: 400 },
{ x: 770, y: 400 }, { x: 100, y: 350 }, { x: 700, y: 350 }
];
treePositions.forEach(pos => {
game.trees.push({
...pos,
size: 20 + Math.random() * 15,
sway: Math.random() * Math.PI * 2
});
});
}

// Initialize clouds
function initClouds() {
for (let i = 0; i < 5; i++) {
game.clouds.push({
x: Math.random() * 800,
y: 20 + Math.random() * 60,
width: 60 + Math.random() * 40,
speed: 0.2 + Math.random() * 0.3,
opacity: 0.6 + Math.random() * 0.4
});
}
}

// Input handling
const keys = {};
document.addEventListener('keydown', (e) => {
keys[e.key] = true;
if (e.key >= '1' && e.key <= '5') {
selectTool(e.key);
}
if (e.key === ' ') {
e.preventDefault();
useTool();
}
if (e.key === 'e' || e.key === 'E') {
toggleShop();
}
});
document.addEventListener('keyup', (e) => {
keys[e.key] = false;
});

// Tool selection
function selectTool(num) {
const tools = ['plow', 'plant', 'water', 'harvest', 'shop'];
if (num >= 1 && num <= 5) {
game.tool = tools[num - 1];
document.querySelectorAll('.tool-btn').forEach(btn => {
btn.classList.remove('active');
if (btn.dataset.tool === game.tool) btn.classList.add('active');
});
if (game.tool === 'shop') toggleShop();
}
}

document.querySelectorAll('.tool-btn').forEach(btn => {
btn.addEventListener('click', () => {
game.tool = btn.dataset.tool;
document.querySelectorAll('.tool-btn').forEach(b => b.classList.remove('active'));
btn.classList.add('active');
if (game.tool === 'shop') toggleShop();
});
});

function useTool() {
if (game.shopOpen) return;

const field = getFieldAt(tractor.x, tractor.y);
if (!field) return;

switch (game.tool) {
case 'plow':
if (!field.plowed) {
field.plowed = true;
field.plowProgress = 0;
addParticle(tractor.x, tractor.y, '🌾');
addFloatingText(tractor.x, tractor.y - 20, 'Plowed!', '#8B4513');
game.score += 5;
}
break;
case 'plant':
if (field.plowed && !field.planted && game.seeds.wheat > 0) {
field.planted = true;
field.cropType = 'wheat';
field.growth = 0;
game.seeds.wheat--;
addParticle(tractor.x, tractor.y, '🌱');
addFloatingText(tractor.x, tractor.y - 20, 'Planted Wheat!', '#228B22');
game.score += 10;
} else if (field.plowed && !field.planted && game.seeds.corn > 0) {
field.planted = true;
field.cropType = 'corn';
field.growth = 0;
game.seeds.corn--;
addParticle(tractor.x, tractor.y, '🌽');
addFloatingText(tractor.x, tractor.y - 20, 'Planted Corn!', '#FFD700');
game.score += 10;
} else if (field.plowed && !field.planted && game.seeds.tomato > 0) {
field.planted = true;
field.cropType = 'tomato';
field.growth = 0;
game.seeds.tomato--;
addParticle(tractor.x, tractor.y, '🍅');
addFloatingText(tractor.x, tractor.y - 20, 'Planted Tomato!', '#FF6347');
game.score += 10;
} else if (field.plowed && !field.planted && game.seeds.carrot > 0) {
field.planted = true;
field.cropType = 'carrot';
field.growth = 0;
game.seeds.carrot--;
addParticle(tractor.x, tractor.y, '🥕');
addFloatingText(tractor.x, tractor.y - 20, 'Planted Carrot!', '#FF8C00');
game.score += 10;
} else if (field.plowed && !field.planted) {
showMessage('No seeds! Visit the shop.');
}
break;
case 'water':
if (field.planted && !field.watered) {
field.watered = true;
field.waterTimer = 0;
addParticle(tractor.x, tractor.y, '💧');
addFloatingText(tractor.x, tractor.y - 20, 'Watered!', '#4169E1');
game.score += 5;
}
break;
case 'harvest':
if (field.planted && field.growth >= 100 && !field.harvested) {
field.harvested = true;
let earnings = 0;
let cropName = '';
switch (field.cropType) {
case 'wheat': earnings = 15; cropName = 'Wheat'; break;
case 'corn': earnings = 20; cropName = 'Corn'; break;
case 'tomato': earnings = 25; cropName = 'Tomato'; break;
case 'carrot': earnings = 12; cropName = 'Carrot'; break;
}
if (field.fertilized) earnings *= 2;
game.money += earnings;
game.harvested++;
game.score += earnings;
addParticle(tractor.x, tractor.y, '💰');
addFloatingText(tractor.x, tractor.y - 20, `+$${earnings} ${cropName}!`, '#FFD700');
field.planted = false;
field.cropType = null;
field.growth = 0;
field.watered = false;
field.fertilized = false;
} else if (field.planted && field.growth < 100) {
showMessage('Crop not ready yet!');
}
break;
}
updateUI();
}

function getFieldAt(x, y) {
for (let field of game.fields) {
if (x >= field.x && x <= field.x + field.w &&
y >= field.y && y <= field.y + field.h) {
return field;
}
}
return null;
}

function addParticle(x, y, emoji) {
game.particles.push({
x, y, emoji,
life: 60,
vy: -2,
vx: (Math.random() - 0.5) * 2
});
}

function addFloatingText(x, y, text, color) {
game.floatingTexts.push({
x, y, text, color,
life: 90,
vy: -1
});
}

function showMessage(msg) {
const msgEl = document.getElementById('message');
msgEl.textContent = msg;
msgEl.style.display = 'block';
setTimeout(() => { msgEl.style.display = 'none'; }, 2000);
}

function toggleShop() {
game.shopOpen = !game.shopOpen;
document.getElementById('shopPanel').style.display = game.shopOpen ? 'block' : 'none';
}

function buyItem(item) {
switch (item) {
case 'wheat':
if (game.money >= 20) {
game.money -= 20;
game.seeds.wheat += 10;
showMessage('Bought 10 Wheat Seeds!');
} else showMessage('Not enough money!');
break;
case 'corn':
if (game.money >= 25) {
game.money -= 25;
game.seeds.corn += 10;
showMessage('Bought 10 Corn Seeds!');
} else showMessage('Not enough money!');
break;
case 'tomato':
if (game.money >= 30) {
game.money -= 30;
game.seeds.tomato += 10;
showMessage('Bought 10 Tomato Seeds!');
} else showMessage('Not enough money!');
break;
case 'carrot':
if (game.money >= 15) {
game.money -= 15;
game.seeds.carrot += 10;
showMessage('Bought 10 Carrot Seeds!');
} else showMessage('Not enough money!');
break;
case 'fertilizer':
if (game.money >= 40) {
game.money -= 40;
game.fertilizer += 5;
showMessage('Bought 5 Fertilizer!');
} else showMessage('Not enough money!');
break;
case 'tractor_upgrade':
if (game.money >= 200 && game.tractorUpgradeLevel < 3) {
game.money -= 200;
game.tractorUpgradeLevel++;
game.tractorSpeed += 1;
showMessage('Tractor upgraded! Speed increased!');
} else if (game.tractorUpgradeLevel >= 3) {
showMessage('Tractor already max level!');
} else showMessage('Not enough money!');
break;
}
updateUI();
}

function updateUI() {
document.getElementById('money').textContent = game.money;
document.getElementById('day').textContent = game.day;
document.getElementById('time').textContent = `${game.hour}:${game.minute.toString().padStart(2, '0')}`;
document.getElementById('score').textContent = game.score;
document.getElementById('harvested').textContent = game.harvested;

let totalCrops = 0;
game.fields.forEach(f => { if (f.planted) totalCrops++; });
document.getElementById('crops').textContent = totalCrops;
}

// Update game logic
function update() {
// Tractor movement
let dx = 0, dy = 0;
if (keys['ArrowUp'] || keys['w'] || keys['W']) { dy = -tractor.speed; tractor.direction = 'up'; }
if (keys['ArrowDown'] || keys['s'] || keys['S']) { dy = tractor.speed; tractor.direction = 'down'; }
if (keys['ArrowLeft'] || keys['a'] || keys['A']) { dx = -tractor.speed; tractor.direction = 'left'; }
if (keys['ArrowRight'] || keys['d'] || keys['D']) { dx = tractor.speed; tractor.direction = 'right'; }

// Normalize diagonal movement
if (dx !== 0 && dy !== 0) {
dx *= 0.707;
dy *= 0.707;
}

tractor.x += dx;
tractor.y += dy;

// Boundary check
tractor.x = Math.max(20, Math.min(780, tractor.x));
tractor.y = Math.max(20, Math.min(580, tractor.y));

// Animation
if (dx !== 0 || dy !== 0) {
tractor.animTimer++;
if (tractor.animTimer > 5) {
tractor.animFrame = (tractor.animFrame + 1) % 4;
tractor.animTimer = 0;
}
} else {
tractor.animFrame = 0;
}

// Time progression
game.minute += 0.5;
if (game.minute >= 60) {
game.minute = 0;
game.hour++;
if (game.hour >= 24) {
game.hour = 6;
game.day++;
showMessage(`🌅 Day ${game.day} begins!`);
}
}

// Day/night cycle
game.isNight = game.hour < 6 || game.hour >= 20;
if (game.isNight) {
game.nightAlpha = Math.min(0.6, game.nightAlpha + 0.01);
} else {
game.nightAlpha = Math.max(0, game.nightAlpha - 0.01);
}

// Sun position
game.sunPosition.x = 100 + (game.hour - 6) / 18 * 600;
game.sunPosition.y = 50 + Math.sin((game.hour - 6) / 18 * Math.PI) * -30;

// Crop growth
game.fields.forEach(field => {
if (field.planted && !field.harvested) {
let growthRate = 0.05;
if (field.watered) growthRate *= 2;
if (field.fertilized) growthRate *= 1.5;
field.growth = Math.min(100, field.growth + growthRate);

// Water timer
if (field.watered) {
field.waterTimer++;
if (field.waterTimer > 500) {
field.watered = false;
field.waterTimer = 0;
}
}
}

// Plow animation
if (field.plowed && field.plowProgress < 100) {
field.plowProgress = Math.min(100, field.plowProgress + 2);
}
});

// Update particles
game.particles = game.particles.filter(p => {
p.life--;
p.y += p.vy;
p.x += p.vx;
return p.life > 0;
});

// Update floating texts
game.floatingTexts = game.floatingTexts.filter(ft => {
ft.life--;
ft.y += ft.vy;
return ft.life > 0;
});

// Update clouds
game.clouds.forEach(cloud => {
cloud.x += cloud.speed;
if (cloud.x > 850) cloud.x = -cloud.width;
});

// Tree sway
game.trees.forEach(tree => {
tree.sway += 0.02;
});

updateUI();
}

// Render
function render() {
ctx.clearRect(0, 0, 800, 600);

// Sky gradient
const skyGradient = ctx.createLinearGradient(0, 0, 0, 200);
if (game.isNight) {
skyGradient.addColorStop(0, '#0a0a2e');
skyGradient.addColorStop(1, '#1a1a4e');
} else {
skyGradient.addColorStop(0, '#87CEEB');
skyGradient.addColorStop(1, '#B0E0E6');
}
ctx.fillStyle = skyGradient;
ctx.fillRect(0, 0, 800, 200);

// Ground
const groundGradient = ctx.createLinearGradient(0, 200, 0, 600);
groundGradient.addColorStop(0, '#5a8f3c');
groundGradient.addColorStop(1, '#4a7f2c');
ctx.fillStyle = groundGradient;
ctx.fillRect(0, 200, 800, 400);

// Draw clouds
game.clouds.forEach(cloud => {
ctx.fillStyle = `rgba(255, 255, 255, ${cloud.opacity})`;
ctx.beginPath();
ctx.ellipse(cloud.x, cloud.y, cloud.width / 2, 15, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(cloud.x - 20, cloud.y + 5, cloud.width / 3, 12, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(cloud.x + 20, cloud.y + 5, cloud.width / 3, 12, 0, 0, Math.PI * 2);
ctx.fill();
});

// Draw sun/moon
if (game.isNight) {
ctx.fillStyle = '#F5F5DC';
ctx.beginPath();
ctx.arc(700, 80, 30, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#E8E8E8';
ctx.beginPath();
ctx.arc(690, 75, 25, 0, Math.PI * 2);
ctx.fill();
} else {
ctx.fillStyle = '#FFD700';
ctx.beginPath();
ctx.arc(game.sunPosition.x, game.sunPosition.y, 35, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#FFF8DC';
ctx.beginPath();
ctx.arc(game.sunPosition.x, game.sunPosition.y, 25, 0, Math.PI * 2);
ctx.fill();
}

// Draw stars at night
if (game.isNight) {
ctx.fillStyle = 'white';
for (let i = 0; i < 30; i++) {
const sx = (i * 137.5) % 800;
const sy = (i * 73.3) % 150;
ctx.beginPath();
ctx.arc(sx, sy, 1, 0, Math.PI * 2);
ctx.fill();
}
}

// Draw fields
game.fields.forEach(field => {
// Field background
if (field.plowed) {
ctx.fillStyle = '#8B4513';
ctx.fillRect(field.x, field.y, field.w, field.h);

// Plow lines
ctx.strokeStyle = '#6B3410';
ctx.lineWidth = 1;
for (let i = 0; i < field.h; i += 8) {
ctx.beginPath();
ctx.moveTo(field.x, field.y + i);
ctx.lineTo(field.x + field.w, field.y + i);
ctx.stroke();
}
} else {
ctx.fillStyle = '#5a8f3c';
ctx.fillRect(field.x, field.y, field.w, field.h);
}

// Field border
ctx.strokeStyle = '#4a3728';
ctx.lineWidth = 2;
ctx.strokeRect(field.x, field.y, field.w, field.h);

// Draw crops
if (field.planted && field.cropType) {
const cropX = field.x + field.w / 2;
const cropY = field.y + field.h / 2;
const growthPercent = field.growth / 100;

if (field.cropType === 'wheat') {
// Wheat
const stemHeight = 10 + growthPercent * 20;
ctx.strokeStyle = '#228B22';
ctx.lineWidth = 2;
for (let i = -2; i <= 2; i++) {
ctx.beginPath();
ctx.moveTo(cropX + i * 5, cropY + 10);
ctx.lineTo(cropX + i * 5 + Math.sin(game.hour * 0.1) * 2, cropY + 10 - stemHeight);
ctx.stroke();
if (growthPercent > 0.5) {
ctx.fillStyle = '#FFD700';
ctx.beginPath();
ctx.ellipse(cropX + i * 5 + Math.sin(game.hour * 0.1) * 2, cropY + 10 - stemHeight, 2, 4, 0, 0, Math.PI * 2);
ctx.fill();
}
}
} else if (field.cropType === 'corn') {
// Corn
const stemHeight = 15 + growthPercent * 25;
ctx.strokeStyle = '#228B22';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.moveTo(cropX, cropY + 10);
ctx.lineTo(cropX, cropY + 10 - stemHeight);
ctx.stroke();
if (growthPercent > 0.6) {
ctx.fillStyle = '#FFD700';
ctx.beginPath();
ctx.ellipse(cropX + 5, cropY + 10 - stemHeight * 0.6, 4, 8, 0.3, 0, Math.PI * 2);
ctx.fill();
}
// Leaves
ctx.fillStyle = '#32CD32';
ctx.beginPath();
ctx.ellipse(cropX - 8, cropY + 10 - stemHeight * 0.4, 10, 3, -0.5, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(cropX + 8, cropY + 10 - stemHeight * 0.5, 10, 3, 0.5, 0, Math.PI * 2);
ctx.fill();
} else if (field.cropType === 'tomato') {
// Tomato plant
const plantHeight = 10 + growthPercent * 20;
ctx.strokeStyle = '#228B22';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(cropX, cropY + 10);
ctx.lineTo(cropX, cropY + 10 - plantHeight);
ctx.stroke();
// Leaves
ctx.fillStyle = '#32CD32';
for (let i = 0; i < 3; i++) {
ctx.beginPath();
ctx.ellipse(cropX + (i % 2 === 0 ? -8 : 8), cropY + 10 - plantHeight * (0.3 + i * 0.2), 6, 3, (i % 2 === 0 ? -0.5 : 0.5), 0, Math.PI * 2);
ctx.fill();
}
// Tomatoes
if (growthPercent > 0.7) {
ctx.fillStyle = '#FF6347';
for (let i = 0; i < 3; i++) {
ctx.beginPath();
ctx.arc(cropX + (i - 1) * 8, cropY + 10 - plantHeight * 0.5, 3, 0, Math.PI * 2);
ctx.fill();
}
}
} else if (field.cropType === 'carrot') {
// Carrot (greens visible)
const greensHeight = 5 + growthPercent * 15;
ctx.strokeStyle = '#228B22';
ctx.lineWidth = 2;
for (let i = -1; i <= 1; i++) {
ctx.beginPath();
ctx.moveTo(cropX + i * 4, cropY + 10);
ctx.quadraticCurveTo(cropX + i * 8, cropY + 10 - greensHeight / 2, cropX + i * 6, cropY + 10 - greensHeight);
ctx.stroke();
}
// Carrot top (orange part visible when ready)
if (growthPercent > 0.8) {
ctx.fillStyle = '#FF8C00';
ctx.beginPath();
ctx.moveTo(cropX - 3, cropY + 5);
ctx.lineTo(cropX + 3, cropY + 5);
ctx.lineTo(cropX, cropY + 10);
ctx.fill();
}
}

// Growth indicator
if (growthPercent < 1) {
ctx.fillStyle = 'rgba(0,0,0,0.5)';
ctx.fillRect(field.x + 5, field.y + field.h - 8, field.w - 10, 4);
ctx.fillStyle = '#228B22';
ctx.fillRect(field.x + 5, field.y + field.h - 8, (field.w - 10) * growthPercent, 4);
}

// Water indicator
if (field.watered) {
ctx.fillStyle = 'rgba(65, 105, 225, 0.3)';
ctx.fillRect(field.x, field.y, field.w, field.h);
}

// Fertilizer indicator
if (field.fertilized) {
ctx.fillStyle = 'rgba(255, 215, 0, 0.2)';
ctx.fillRect(field.x, field.y, field.w, field.h);
}

// Ready to harvest indicator
if (field.growth >= 100 && !field.harvested) {
ctx.fillStyle = 'rgba(255, 215, 0, 0.3)';
ctx.fillRect(field.x, field.y, field.w, field.h);
ctx.font = '16px Arial';
ctx.fillStyle = '#FFD700';
ctx.textAlign = 'center';
ctx.fillText('✨', cropX, cropY - 15);
}
}
});

// Draw trees
game.trees.forEach(tree => {
// Trunk
ctx.fillStyle = '#8B4513';
ctx.fillRect(tree.x - 3, tree.y - tree.size, 6, tree.size);

// Foliage
ctx.fillStyle = '#228B22';
ctx.beginPath();
ctx.arc(tree.x, tree.y - tree.size - 5, tree.size * 0.6, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#32CD32';
ctx.beginPath();
ctx.arc(tree.x + Math.sin(tree.sway) * 2, tree.y - tree.size - 10, tree.size * 0.5, 0, Math.PI * 2);
ctx.fill();
});

// Draw tractor
drawTractor();

// Draw particles
game.particles.forEach(p => {
ctx.globalAlpha = p.life / 60;
ctx.font = '20px Arial';
ctx.textAlign = 'center';
ctx.fillText(p.emoji, p.x, p.y);
ctx.globalAlpha = 1;
});

// Draw floating texts
game.floatingTexts.forEach(ft => {
ctx.globalAlpha = ft.life / 90;
ctx.font = 'bold 14px Arial';
ctx.textAlign = 'center';
ctx.fillStyle = ft.color;
ctx.strokeStyle = 'black';
ctx.lineWidth = 2;
ctx.strokeText(ft.text, ft.x, ft.y);
ctx.fillText(ft.text, ft.x, ft.y);
ctx.globalAlpha = 1;
});

// Night overlay
if (game.nightAlpha > 0) {
ctx.fillStyle = `rgba(0, 0, 50, ${game.nightAlpha})`;
ctx.fillRect(0, 0, 800, 600);
}

// Path/road
ctx.fillStyle = '#C4A46C';
ctx.fillRect(0, 280, 800, 20);
ctx.fillRect(400, 0, 20, 600);

// Path markings
ctx.strokeStyle = '#8B7355';
ctx.lineWidth = 1;
ctx.setLineDash([10, 10]);
ctx.beginPath();
ctx.moveTo(410, 0);
ctx.lineTo(410, 600);
ctx.stroke();
ctx.setLineDash([]);
}

function drawTractor() {
ctx.save();
ctx.translate(tractor.x, tractor.y);

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.beginPath();
ctx.ellipse(0, 25, 22, 8, 0, 0, Math.PI * 2);
ctx.fill();

// Body
ctx.fillStyle = '#FF0000';
ctx.fillRect(-15, -20, 30, 25);

// Cabin
ctx.fillStyle = '#CC0000';
ctx.fillRect(-12, -30, 24, 15);

// Windows
ctx.fillStyle = '#87CEEB';
ctx.fillRect(-8, -28, 8, 10);
ctx.fillRect(2, -28, 8, 10);

// Roof
ctx.fillStyle = '#FF4444';
ctx.fillRect(-14, -32, 28, 4);

// Exhaust
ctx.fillStyle = '#333';
ctx.fillRect(10, -35, 4, 10);

// Wheels
ctx.fillStyle = '#333';
ctx.beginPath();
ctx.arc(-12, 10, 8, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(12, 10, 8, 0, Math.PI * 2);
ctx.fill();

// Wheel rims
ctx.fillStyle = '#666';
ctx.beginPath();
ctx.arc(-12, 10, 3, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(12, 10, 3, 0, Math.PI * 2);
ctx.fill();

// Front wheels (smaller)
ctx.fillStyle = '#333';
ctx.beginPath();
ctx.arc(-10, -15, 5, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(10, -15, 5, 0, Math.PI * 2);
ctx.fill();

// Tool attachment
if (game.tool === 'plow') {
ctx.fillStyle = '#666';
ctx.fillRect(-5, 15, 10, 15);
ctx.fillStyle = '#888';
ctx.beginPath();
ctx.moveTo(-5, 30);
ctx.lineTo(5, 30);
ctx.lineTo(3, 35);
ctx.lineTo(-3, 35);
ctx.fill();
} else if (game.tool === 'water') {
ctx.fillStyle = '#4169E1';
ctx.fillRect(-8, 15, 16, 10);
ctx.fillStyle = '#87CEEB';
ctx.fillRect(-6, 17, 12, 6);
}

// Direction indicator
ctx.fillStyle = '#FFD700';
ctx.beginPath();
if (tractor.direction === 'up') {
ctx.moveTo(0, -35);
ctx.lineTo(-5, -28);
ctx.lineTo(5, -28);
} else if (tractor.direction === 'down') {
ctx.moveTo(0, 20);
ctx.lineTo(-5, 13);
ctx.lineTo(5, 13);
} else if (tractor.direction === 'left') {
ctx.moveTo(-18, 0);
ctx.lineTo(-11, -5);
ctx.lineTo(-11, 5);
} else {
ctx.moveTo(18, 0);
ctx.lineTo(11, -5);
ctx.lineTo(11, 5);
}
ctx.fill();

ctx.restore();
}

// Game loop
function gameLoop() {
update();
render();
requestAnimationFrame(gameLoop);
}

// Initialize
initFields();
initTrees();
initClouds();
updateUI();
gameLoop();

// Auto-save hint
setInterval(() => {
if (game.harvested > 0 && game.harvested % 5 === 0) {
showMessage(`🎉 Great farming! ${game.harvested} crops harvested!`);
}
}, 10000);
</script>
