    font-weight: 800;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .career-card {
    background: var(--card);
    border-radius: 16px;
    padding: 15px;
    margin-bottom: 10px;
    border-left: 4px solid var(--primary);
  }

  .career-card h4 {
    margin-bottom: 5px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .career-card p {
    font-size: 0.85em;
    color: var(--text-muted);
    margin-bottom: 10px;
  }

  .career-progress {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .career-progress-bar {
    flex: 1;
    height: 6px;
    background: var(--card-light);
    border-radius: 3px;
    overflow: hidden;
  }

  .career-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--primary), var(--secondary));
    border-radius: 3px;
    transition: width 0.5s;
  }

  .career-progress-text {
    font-size: 0.8em;
    color: var(--text-muted);
    font-weight: 700;
    min-width: 40px;
    text-align: right;
  }

  /* Actions Grid */
  .actions-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    margin-bottom: 20px;
  }

  .action-card {
    background: var(--card);
    border-radius: 16px;
    padding: 15px 10px;
    text-align: center;
    cursor: pointer;
    transition: all 0.3s;
    border: 2px solid transparent;
  }

  .action-card:hover {
    border-color: var(--primary);
    transform: translateY(-3px);
  }

  .action-card:active {
    transform: scale(0.95);
  }

  .action-card.disabled {
    opacity: 0.5;
    pointer-events: none;
  }

  .action-icon {
    font-size: 2em;
    margin-bottom: 8px;
    display: block;
  }

  .action-name {
    font-size: 0.85em;
    font-weight: 700;
    margin-bottom: 4px;
  }

  .action-cost {
    font-size: 0.75em;
    color: var(--text-muted);
  }

  /* Bottom Navigation */
  .bottom-nav {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    background: var(--card);
    border-top: 1px solid var(--card-light);
    display: flex;
    justify-content: space-around;
    padding: 10px 0;
    padding-bottom: max(10px, env(safe-area-inset-bottom));
    z-index: 100;
  }

  .nav-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    cursor: pointer;
    padding: 5px 15px;
    border-radius: 12px;
    transition: all 0.3s;
    color: var(--text-muted);
  }

  .nav-item.active {
    color: var(--primary);
    background: rgba(108,92,231,0.1);
  }

  .nav-item:hover {
    color: var(--primary-light);
  }

  .nav-icon {
    font-size: 1.5em;
  }

  .nav-label {
    font-size: 0.7em;
    font-weight: 700;
  }

  /* Modal */
  .modal-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0,0,0,0.7);
    z-index: 200;
    align-items: center;
    justify-content: center;
    padding: 20px;
    animation: fadeIn 0.3s;
  }

  .modal-overlay.active {
    display: flex;
  }

  .modal {
    background: var(--card);
    border-radius: 20px;
    padding: 25px;
    max-width: 400px;
    width: 100%;
    max-height: 80vh;
    overflow-y: auto;
    animation: bounceIn 0.5s;
    position: relative;
  }

  .modal-close {
    position: absolute;
    top: 15px;
    right: 15px;
    background: var(--card-light);
    border: none;
    color: var(--text);
    width: 30px;
    height: 30px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1.2em;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .modal h2 {
    margin-bottom: 15px;
    display: flex;
    align-items: center;
    gap: 10px;
  }

  /* Shop Items */
  .shop-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px;
    background: var(--card-light);
    border-radius: 12px;
    margin-bottom: 10px;
    transition: all 0.3s;
  }

  .shop-item:hover {
    background: rgba(108,92,231,0.1);
  }

  .shop-item-icon {
    font-size: 2em;
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--card);
    border-radius: 12px;
  }

  .shop-item-info {
    flex: 1;
  }

  .shop-item-info h4 {
    font-size: 0.95em;
    margin-bottom: 3px;
  }

  .shop-item-info p {
    font-size: 0.8em;
    color: var(--text-muted);
  }

  .shop-item-price {
    font-weight: 800;
    color: var(--warning);
    font-size: 0.9em;
  }

  /* Relationships */
  .relationship-card {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px;
    background: var(--card-light);
    border-radius: 12px;
    margin-bottom: 10px;
  }

  .relationship-avatar {
    width: 45px;
    height: 45px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5em;
    background: linear-gradient(135deg, var(--primary), var(--accent));
  }

  .relationship-info {
    flex: 1;
  }

  .relationship-info h4 {
    font-size: 0.95em;
    margin-bottom: 3px;
  }

  .relationship-info p {
    font-size: 0.8em;
    color: var(--text-muted);
  }

  .relationship-bar {
    height: 6px;
    background: var(--card);
    border-radius: 3px;
    overflow: hidden;
    margin-top: 5px;
  }

  .relationship-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--accent), var(--primary));
    border-radius: 3px;
    transition: width 0.5s;
  }

  /* Inventory */
  .inventory-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
  }

  .inventory-item {
    background: var(--card-light);
    border-radius: 12px;
    padding: 12px;
    text-align: center;
    cursor: pointer;
    transition: all 0.3s;
  }

  .inventory-item:hover {
    background: rgba(108,92,231,0.2);
    transform: scale(1.05);
  }

  .inventory-item-icon {
    font-size: 1.8em;
    margin-bottom: 5px;
  }

  .inventory-item-count {
    font-size: 0.75em;
    color: var(--text-muted);
    font-weight: 700;
  }

  /* Event Log */
  .event-log {
    max-height: 200px;
    overflow-y: auto;
    padding: 10px;
    background: var(--card-light);
    border-radius: 12px;
    margin-bottom: 15px;
  }

  .event-item {
    padding: 8px 0;
    border-bottom: 1px solid rgba(255,255,255,0.05);
    font-size: 0.85em;
    display: flex;
    align-items: center;
    gap: 8px;
    animation: slideUp 0.3s ease;
  }

  .event-item:last-child {
    border-bottom: none;
  }

  .event-time {
    color: var(--text-muted);
    font-size: 0.75em;
    min-width: 50px;
  }

  /* Notification */
  .notification {
    position: fixed;
    top: 20px;
    left: 50%;
    transform: translateX(-50%) translateY(-100px);
    background: var(--card);
    border: 2px solid var(--primary);
    border-radius: 16px;
    padding: 15px 25px;
    z-index: 300;
    animation: slideDown 0.5s ease forwards;
    display: flex;
    align-items: center;
    gap: 10px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    max-width: 90%;
  }

  @keyframes slideDown {
    to { transform: translateX(-50%) translateY(0); }
  }

  .notification.hide {
    animation: slideUp2 0.5s ease forwards;
  }

  @keyframes slideUp2 {
    to { transform: translateX(-50%) translateY(-100px); }
  }

  /* Tab Content */
  .tab-content {
    display: none;
  }

  .tab-content.active {
    display: block;
    animation: fadeIn 0.3s;
  }

  /* Level Up Animation */
  .level-up-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0,0,0,0.8);
    z-index: 250;
    align-items: center;
    justify-content: center;
    flex-direction: column;
  }

  .level-up-overlay.active {
    display: flex;
  }

  .level-up-text {
    font-size: 3em;
    font-weight: 800;
    background: linear-gradient(135deg, var(--warning), var(--accent));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: pulse 1s infinite;
  }

  .level-up-number {
    font-size: 5em;
    font-weight: 800;
    color: var(--primary-light);
    animation: bounceIn 0.5s;
  }

  /* Responsive */
  @media (max-width: 380px) {
    .actions-grid {
      grid-template-columns: repeat(2, 1fr);
    }
    .stats-container {
      grid-template-columns: 1fr;
    }
    .title-logo {
      font-size: 2.2em;
    }
  }

  /* Particle effects */
  .particle {
    position: fixed;
    pointer-events: none;
    z-index: 300;
    animation: particleFade 1s ease forwards;
  }

  @keyframes particleFade {
    0% { opacity: 1; transform: translateY(0) scale(1); }
    100% { opacity: 0; transform: translateY(-100px) scale(0); }
  }

  .hidden { display: none !important; }

  /* Achievement */
  .achievement {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px;
    background: var(--card-light);
    border-radius: 12px;
    margin-bottom: 10px;
    border-left: 4px solid var(--warning);
  }

  .achievement.locked {
    opacity: 0.5;
    border-left-color: var(--text-muted);
  }

  .achievement-icon {
    font-size: 2em;
  }

  .achievement-info h4 {
    font-size: 0.95em;
    margin-bottom: 3px;
  }

  .achievement-info p {
    font-size: 0.8em;
    color: var(--text-muted);
  }

  /* Sleep screen */
  .sleep-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, #0a0a2e, #1a1a3e);
    z-index: 250;
    align-items: center;
    justify-content: center;
    flex-direction: column;
  }

  .sleep-overlay.active {
    display: flex;
  }

  .sleep-text {
    font-size: 1.5em;
    color: var(--text-muted);
    margin-bottom: 20px;
    animation: float 2s ease-in-out infinite;
  }

  .sleep-z {
    font-size: 3em;
    color: var(--primary-light);
    animation: float 1.5s ease-in-out infinite;
  }

  .sleep-z:nth-child(2) { animation-delay: 0.3s; }
  .sleep-z:nth-child(3) { animation-delay: 0.6s; }
</style>
</head>
<body>

<!-- Title Screen -->
<div id="titleScreen" class="screen active">
  <div class="title-emoji">🌟</div>
  <div class="title-logo">Life RPG</div>
  <div class="title-subtitle">Votre vie, vos choix, votre histoire</div>
  <button class="btn btn-primary" onclick="showScreen('creationScreen')">
    🎮 Commencer l'Aventure
  </button>
  <br><br>
  <button class="btn btn-secondary btn-small" onclick="loadGame()" id="continueBtn" style="display:none">
    📂 Continuer
  </button>
</div>

<!-- Character Creation -->
<div id="creationScreen" class="screen">
  <div class="creation-form">
    <h2 style="text-align:center; margin-bottom:20px;">🎭 Créez votre personnage</h2>

    <div class="form-group">
      <label>👤 Nom de votre personnage</label>
      <input type="text" id="playerName" placeholder="Entrez votre nom..." maxlength="20">
    </div>

    <div class="form-group">
      <label>😊 Choisissez votre avatar</label>
      <div class="avatar-selection" id="avatarSelection">
        <div class="avatar-option selected" data-avatar="😎" onclick="selectAvatar(this)">😎</div>
        <div class="avatar-option" data-avatar="🥳" onclick="selectAvatar(this)">🥳</div>
        <div class="avatar-option" data-avatar="🤩" onclick="selectAvatar(this)">🤩</div>
        <div class="avatar-option" data-avatar="😇" onclick="selectAvatar(this)">😇</div>
        <div class="avatar-option" data-avatar="🦊" onclick="selectAvatar(this)">🦊</div>
        <div class="avatar-option" data-avatar="🐱" onclick="selectAvatar(this)">🐱</div>
        <div class="avatar-option" data-avatar="🦁" onclick="selectAvatar(this)">🦁</div>
        <div class="avatar-option" data-avatar="🐺" onclick="selectAvatar(this)">🐺</div>
      </div>
    </div>

    <div class="form-group">
      <label>⚧ Genre</label>
      <div class="gender-selection">
        <div class="gender-option selected" data-gender="homme" onclick="selectGender(this)">👨</div>
        <div class="gender-option" data-gender="femme" onclick="selectGender(this)">👩</div>
        <div class="gender-option" data-gender="autre" onclick="selectGender(this)">🧑</div>
      </div>
    </div>

    <div class="form-group">
      <label>🎯 Style de vie</label>
      <select id="lifestyle">
        <option value="etudiant">📚 Étudiant (+Exp, -Argent)</option>
        <option value="creatif">🎨 Créatif (+Bonheur, +Énergie)</option>
        <option value="business">💼 Business (+Argent, -Bonheur)</option>
        <option value="sportif">💪 Sportif (+Santé, +Énergie)</option>
      </select>
    </div>

    <button class="btn btn-primary btn-block" onclick="createCharacter()" style="margin-top:10px">
      🚀 Commencer l'aventure
    </button>
  </div>
</div>

<!-- Main Game Screen -->
<div id="gameScreen" class="screen">
  <!-- Top Bar -->
  <div class="top-bar">
    <div class="player-info">
      <div class="player-avatar" id="playerAvatar">😎</div>
      <div class="player-details">
        <h3 id="playerNameDisplay">Joueur</h3>
        <span class="level" id="playerLevel">Niveau 1</span>
      </div>
    </div>
    <div class="top-stats">
      <div class="day-display">📅 Jour <span id="dayCount">1</span></div>
      <div class="top-stat">💰 <span id="moneyDisplay">100</span></div>
    </div>
  </div>

  <!-- Stats -->
  <div class="stats-container">
    <div class="stat-card health">
      <div class="stat-header">
        <span class="stat-label">❤️ Santé</span>
        <span class="stat-value" id="healthValue">100/100</span>
      </div>
      <div class="stat-bar">
        <div class="stat-fill health" id="healthBar" style="width:100%"></div>
      </div>
    </div>
    <div class="stat-card energy">
      <div class="stat-header">
        <span class="stat-label">⚡ Énergie</span>
        <span class="stat-value" id="energyValue">100/100</span>
      </div>
      <div class="stat-bar">
        <div class="stat-fill energy" id="energyBar" style="width:100%"></div>
      </div>
    </div>
    <div class="stat-card happiness">
      <div class="stat-header">
        <span class="stat-label">😊 Bonheur</span>
        <span class="stat-value" id="happinessValue">80/100</span>
      </div>
      <div class="stat-bar">
        <div class="stat-fill happiness" id="happinessBar" style="width:80%"></div>
      </div>
    </div>
    <div class="stat-card exp">
      <div class="stat-header">
        <span class="stat-label">⭐ Expérience</span>
        <span class="stat-value" id="expValue">0/100</span>
      </div>
      <div class="stat-bar">
        <div class="stat-fill exp" id="expBar" style="width:0%"></div>
      </div>
    </div>
  </div>

  <!-- Tab: Actions -->
  <div class="tab-content active" id="tabActions">
    <div class="section">
      <div class="section-header">
        <span class="section-title">🎯 Actions du jour</span>
      </div>
      <div class="actions-grid">
        <div class="action-card" onclick="doAction('work')">
          <span class="action-icon">💼</span>
          <div class="action-name">Travailler</div>
          <div class="action-cost">-20⚡ +💰</div>
        </div>
        <div class="action-card" onclick="doAction('study')">
          <span class="action-icon">📚</span>
          <div class="action-name">Étudier</div>
          <div class="action-cost">-15⚡ +⭐</div>
        </div>
        <div class="action-card" onclick="doAction('exercise')">
          <span class="action-icon">💪</span>
          <div class="action-name">Exercise</div>
          <div class="action-cost">-25⚡ +❤️</div>
        </div>
        <div class="action-card" onclick="doAction('social')">
          <span class="action-icon">🎉</span>
          <div class="action-name">Socialiser</div>
          <div class="action-cost">-15⚡ +😊</div>
        </div>
        <div class="action-card" onclick="doAction('cook')">
          <span class="action-icon">🍳</span>
          <div class="action-name">Cuisiner</div>
          <div class="action-cost">-10⚡ +❤️</div>
        </div>
        <div class="action-card" onclick="doAction('meditate')">
          <span class="action-icon">🧘</span>
          <div class="action-name">Méditer</div>
          <div class="action-cost">-5⚡ +😊+⚡</div>
        </div>
        <div class="action-card" onclick="doAction('read')">
          <span class="action-icon">📖</span>
          <div class="action-name">Lire</div>
          <div class="action-cost">-10⚡ +⭐</div>
        </div>
        <div class="action-card" onclick="doAction('game')">
          <span class="action-icon">🎮</span>
          <div class="action-name">Jouer</div>
          <div class="action-cost">-10⚡ +😊</div>
        </div>
        <div class="action-card" onclick="doAction('sleep')">
          <span class="action-icon">😴</span>
          <div class="action-name">Dormir</div>
          <div class="action-cost">+⚡+❤️</div>
        </div>
      </div>
    </div>

    <!-- Career -->
    <div class="section">
      <div class="section-header">
        <span class="section-title">🏢 Carrière</span>
        <button class="btn btn-small btn-primary" onclick="openModal('careerModal')">Promouvoir</button>
      </div>
      <div class="career-card">
        <h4>💼 <span id="jobTitle">Stagiaire</span></h4>
        <p id="jobDesc">Débutant dans le monde professionnel</p>
        <div class="career-progress">
          <div class="career-progress-bar">
            <div class="career-progress-fill" id="careerProgress" style="width:0%"></div>
          </div>
          <span class="career-progress-text" id="careerProgressText">0%</span>
        </div>
      </div>
    </div>

    <!-- Event Log -->
    <div class="section">
      <div class="section-header">
        <span class="section-title">📜 Journal d'événements</span>
      </div>
      <div class="event-log" id="eventLog">
        <div class="event-item">
          <span class="event-time">Jour 1</span>
          <span>🎉 Bienvenue dans Life RPG ! Commencez votre aventure.</span>
        </div>
      </div>
    </div>
  </div>

  <!-- Tab: Shop -->
  <div class="tab-content" id="tabShop">
    <div class="section">
      <div class="section-header">
        <span class="section-title">🛒 Boutique</span>
      </div>
      <div id="shopItems">
        <!-- Populated by JS -->
      </div>
    </div>
  </div>

  <!-- Tab: Relationships -->
  <div class="tab-content" id="tabRelationships">
    <div class="section">
      <div class="section-header">
        <span class="section-title">💕 Relations</span>
        <button class="btn btn-small btn-primary" onclick="meetNewPerson()">Rencontrer</button>
      </div>
      <div id="relationshipsList">
        <!-- Populated by JS -->
      </div>
    </div>
  </div>

  <!-- Tab: Inventory -->
  <div class="tab-content" id="tabInventory">
    <div class="section">
      <div class="section-header">
        <span class="section-title">🎒 Inventaire</span>
      </div>
      <div class="inventory-grid" id="inventoryGrid">
        <!-- Populated by JS -->
      </div>
    </div>
  </div>

  <!-- Tab: Achievements -->
  <div class="tab-content" id="tabAchievements">
    <div class="section">
      <div class="section-header">
        <span class="section-title">🏆 Succès</span>
      </div>
      <div id="achievementsList">
        <!-- Populated by JS -->
      </div>
    </div>
  </div>

  <!-- Bottom Navigation -->
  <div class="bottom-nav">
    <div class="nav-item active" onclick="switchTab('actions')">
      <span class="nav-icon">🎯</span>
      <span class="nav-label">Actions</span>
    </div>
    <div class="nav-item" onclick="switchTab('shop')">
      <span class="nav-icon">🛒</span>
      <span class="nav-label">Boutique</span>
    </div>
    <div class="nav-item" onclick="switchTab('relationships')">
      <span class="nav-icon">💕</span>
      <span class="nav-label">Relations</span>
    </div>
    <div class="nav-item" onclick="switchTab('inventory')">
      <span class="nav-icon">🎒</span>
      <span class="nav-label">Inventaire</span>
    </div>
    <div class="nav-item" onclick="switchTab('achievements')">
      <span class="nav-icon">🏆</span>
      <span class="nav-label">Succès</span>
    </div>
  </div>
</div>

<!-- Career Modal -->
<div class="modal-overlay" id="careerModal">
  <div class="modal">
    <button class="modal-close" onclick="closeModal('careerModal')">✕</button>
    <h2>🏢 Carrières Disponibles</h2>
    <div id="careerList">
      <!-- Populated by JS -->
    </div>
  </div>
</div>

<!-- Level Up Overlay -->
<div class="level-up-overlay" id="levelUpOverlay">
  <div class="level-up-text">🎉 NIVEAU SUPÉRIEUR !</div>
  <div class="level-up-number" id="levelUpNumber">2</div>
  <button class="btn btn-primary" onclick="closeLevelUp()" style="margin-top:20px">Continuer</button>
</div>

<!-- Sleep Overlay -->
<div class="sleep-overlay" id="sleepOverlay">
  <div class="sleep-text">💤 Bonne nuit...</div>
  <div class="sleep-z">Z</div>
  <div class="sleep-z">z</div>
  <div class="sleep-z">z</div>
</div>

<!-- Notification Container -->
<div id="notificationContainer"></div>

<script>
// ==================== GAME STATE ====================
let gameState = {
  player: {
    name: 'Joueur',
    avatar: '😎',
    gender: 'homme',
    lifestyle: 'etudiant',
    level: 1,
    exp: 0,
    expToNext: 100,
    money: 100,
    health: 100,
    maxHealth: 100,
    energy: 100,
    maxEnergy: 100,
    happiness: 80,
    maxHappiness: 100,
    day: 1,
    actionsToday: 0,
    maxActionsPerDay: 5
  },
  career: {
    title: 'Stagiaire',
    level: 0,
    progress: 0,
    salary: 50
  },
  inventory: {},
  relationships: [],
  achievements: [],
  eventLog: [],
  settings: {
    notifications: true
  }
};

// ==================== DATA ====================
const careers = [
  { title: 'Stagiaire', level: 0, salary: 50, expNeeded: 0, desc: 'Débutant dans le monde professionnel' },
  { title: 'Employé', level: 1, salary: 100, expNeeded: 100, desc: 'Vous avez vos premières expériences' },
  { title: 'Technicien', level: 2, salary: 200, expNeeded: 300, desc: 'Spécialiste dans votre domaine' },
  { title: 'Chef de projet', level: 3, salary: 350, expNeeded: 600, desc: 'Vous dirigez des équipes' },
  { title: 'Manager', level: 4, salary: 500, expNeeded: 1000, desc: 'Responsable de département' },
  { title: 'Directeur', level: 5, salary: 800, expNeeded: 1500, desc: 'Haute direction de l\'entreprise' },
  { title: 'PDG', level: 6, salary: 1500, expNeeded: 2500, desc: 'Le patron en chef !' },
  { title: 'Millionnaire', level: 7, salary: 3000, expNeeded: 5000, desc: 'Liberté financière totale !' }
];

const shopItems = [
  { id: 'pizza', name: '🍕 Pizza', price: 15, effect: { health: 10, happiness: 5 }, desc: 'Repas délicieux' },
  { id: 'coffee', name: '☕ Café', price: 5, effect: { energy: 20 }, desc: 'Boost d\'énergie' },
  { id: 'book', name: '📚 Livre', price: 25, effect: { exp: 15 }, desc: 'Knowledge is power' },
  { id: 'game', name: '🎮 Jeu vidéo', price: 40, effect: { happiness: 20 }, desc: 'Divertissement total' },
  { id: 'gym', name: '💪 Abonnement gym', price: 50, effect: { health: 25, energy: -10 }, desc: 'Santé améliorée' },
  { id: 'medicine', name: '💊 Médicaments', price: 20, effect: { health: 30 }, desc: 'Récupération rapide' },
  { id: 'gift', name: '🎁 Cadeau', price: 30, effect: { happiness: 15 }, desc: 'Pour faire plaisir' },
  { id: 'vacation', name: '🏖️ Vacances', price: 200, effect: { health: 20, energy: 50, happiness: 30 }, desc: 'Repos total' },
  { id: 'phone', name: '📱 Smartphone', price: 500, effect: { happiness: 25, energy: 10 }, desc: 'Toujours connecté' },
  { id: 'car', name: '🚗 Voiture', price: 2000, effect: { happiness: 40 }, desc: 'Liberté de mouvement' }
];

const npcNames = [
  { male: ['Lucas', 'Hugo', 'Thomas', 'Pierre', 'Jean', 'Marc', 'Paul', 'Louis'], female: ['Emma', 'Louise', 'Julie', 'Marie', 'Sophie', 'Léa', 'Chloé', 'Camille'] },
  { male: ['Alex', 'Max', 'Tom', 'Sam', 'Jim', 'Bob', 'Rick', 'Dan'], female: ['Ana', 'Luna', 'Mia', 'Zoe', 'Lily', 'Nina', 'Rosa', 'Iris'] }
];

const achievements = [
  { id: 'first_day', name: '🌅 Premier Jour', desc: 'Commencer votre aventure', icon: '🌅' },
  { id: 'first_job', name: '💼 Premier Travail', desc: 'Effectuer votre première journée de travail', icon: '💼' },
  { id: 'level5', name: '⭐ Niveau 5', desc: 'Atteindre le niveau 5', icon: '⭐' },
  { id: 'level10', name: '🌟 Niveau 10', desc: 'Atteindre le niveau 10', icon: '🌟' },
  { id: 'rich', name: '💰 Riche', desc: 'Avoir 1000 pièces d\'or', icon: '💰' },
  { id: 'super_rich', name: '💎 Super Riche', desc: 'Avoir 5000 pièces d\'or', icon: '💎' },
  { id: 'happy', name: '😊 Bonheur Max', desc: 'Atteindre 100 de bonheur', icon: '😊' },
  { id: 'healthy', name: '❤️ Santé Max', desc: 'Atteindre 100 de santé', icon: '❤️' },
  { id: 'social', name: '🤝 Social', desc: 'Avoir 5 amis', icon: '🤝' },
  { id: 'scholar', name: '🎓 Scholar', desc: 'Atteindre le niveau 20', icon: '🎓' },
  { id: 'collector', name: '🎒 Collectionneur', desc: 'Avoir 10 items dans l\'inventaire', icon: '🎒' },
  { id: 'day30', name: '📅 30 Jours', desc: 'Survivre 30 jours', icon: '📅' }
];

// ==================== INIT ====================
function init() {
  checkSave();
  renderShop();
  renderAchievements();
}

function checkSave() {
  const saved = localStorage.getItem('lifeRPG_save');
  if (saved) {
    document.getElementById('continueBtn').style.display = 'inline-block';
  }
}

function showScreen(screenId) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(screenId).classList.add('active');
}

// ==================== CHARACTER CREATION ====================
let selectedAvatar = '😎';
let selectedGender = 'homme';

function selectAvatar(el) {
  document.querySelectorAll('.avatar-option').forEach(a => a.classList.remove('selected'));
  el.classList.add('selected');
  selectedAvatar = el.dataset.avatar;
}

function selectGender(el) {
  document.querySelectorAll('.gender-option').forEach(g => g.classList.remove('selected'));
  el.classList.add('selected');
  selectedGender = el.dataset.gender;
}

function createCharacter() {
  const name = document.getElementById('playerName').value.trim() || 'Joueur';
  const lifestyle = document.getElementById('lifestyle').value;

  gameState.player.name = name;
  gameState.player.avatar = selectedAvatar;
  gameState.player.gender = selectedGender;
  gameState.player.lifestyle = lifestyle;

  // Lifestyle bonuses
  if (lifestyle === 'etudiant') {
    gameState.player.expToNext = 80;
  } else if (lifestyle === 'creatif') {
    gameState.player.happiness = 90;
  } else if (lifestyle === 'business') {
    gameState.player.money = 200;
  } else if (lifestyle === 'sportif') {
    gameState.player.health = 110;
    gameState.player.maxHealth = 110;
  }

  showScreen('gameScreen');
  updateUI();
  addEvent('🎉', `${name} commence son aventure !`);
  unlockAchievement('first_day');
  saveGame();
}

// ==================== GAME ACTIONS ====================
function doAction(action) {
  const p = gameState.player;

  if (p.actionsToday >= p.maxActionsPerDay) {
    showNotification('⚠️ Plus d\'actions aujourd\'hui ! Dormez pour recommencer.', 'warning');
    return;
  }

  if (p.energy <= 0) {
    showNotification('😴 Vous êtes trop fatigué ! Dormez.', 'warning');
    return;
  }

  let energyCost = 0;
  let expGain = 0;
  let moneyGain = 0;
  let healthGain = 0;
  let happinessGain = 0;
  let eventText = '';

  switch(action) {
    case 'work':
      energyCost = 20;
      moneyGain = gameState.career.salary + Math.floor(Math.random() * 20);
      expGain = 10;
      happinessGain = -5;
      eventText = '💼 Vous avez travaillé dur';
      break;
    case 'study':
      energyCost = 15;
      expGain = 25;
      happinessGain = 5;
      eventText = '📚 Vous avez étudié avec concentration';
      break;
    case 'exercise':
      energyCost = 25;
      healthGain = 15;
      expGain = 5;
      happinessGain = 10;
      eventText = '💪 Session d\'exercice intense';
      break;
    case 'social':
      energyCost = 15;
      happinessGain = 15;
      expGain = 5;
      eventText = '🎉 Soirée entre amis';
      break;
    case 'cook':
      energyCost = 10;
      healthGain = 10;
      happinessGain = 5;
      eventText = '🍳 Repas maison délicieux';
      break;
    case 'meditate':
      energyCost = 5;
      happinessGain = 10;
      energyGain = 10;
      expGain = 5;
      eventText = '🧘 Méditation profonde';
      break;
    case 'read':
      energyCost = 10;
      expGain = 15;
      happinessGain = 5;
      eventText = '📖 Lecture enrichissante';
      break;
    case 'game':
      energyCost = 10;
      happinessGain = 15;
      eventText = '🎮 Session gaming';
      break;
    case 'sleep':
      sleepAction();
      return;
  }

  // Apply effects
  p.energy = Math.max(0, p.energy - energyCost);
  p.exp += expGain;
  p.money += moneyGain;
  p.health = Math.min(p.maxHealth, p.health + healthGain);
  p.happiness = Math.max(0, Math.min(p.maxHappiness, p.happiness + happinessGain));
  p.actionsToday++;

  // Career progress
  gameState.career.progress += expGain;
  checkCareerPromotion();

  // Check level up
  checkLevelUp();

  // Check achievements
  checkAchievements();

  // Log event
  addEvent(eventText, `+${expGain}⭐ ${moneyGain > 0 ? '+' + moneyGain + '💰' : ''} ${healthGain > 0 ? '+' + healthGain + '❤️' : ''} ${happinessGain > 0 ? '+' + happinessGain + '😊' : ''}`);

  updateUI();
  saveGame();

  // Particle effect
  createParticles(action);
}

function sleepAction() {
  const p = gameState.player;

  // Show sleep overlay
  document.getElementById('sleepOverlay').classList.add('active');

  setTimeout(() => {
    document.getElementById('sleepOverlay').classList.remove('active');

    // Restore stats
    p.energy = p.maxEnergy;
    p.health = Math.min(p.maxHealth, p.health + 20);
    p.happiness = Math.min(p.maxHappiness, p.happiness + 10);
    p.actionsToday = 0;
    p.day++;

    // Daily events
    handleDailyEvents();

    addEvent('🌅', `Jour ${p.day} commence !`);
    checkAchievements();
    updateUI();
    saveGame();
    showNotification('🌅 Nouveau jour ! Énergie restaurée.', 'success');
  }, 2000);
}

function handleDailyEvents() {
  const events = [
    { text: '🎁 Cadeau surprise ! +50💰', effect: () => { gameState.player.money += 50; } },
    { text: '🌧️ Mauvais temps, -10😊', effect: () => { gameState.player.happiness = Math.max(0, gameState.player.happiness - 10); } },
    { text: '🍀 Bonne chance ! +20⚡', effect: () => { gameState.player.energy = Math.min(gameState.player.maxEnergy, gameState.player.energy + 20); } },
    { text: '💊 Trouvé des médicaments ! +15❤️', effect: () => { gameState.player.health = Math.min(gameState.player.maxHealth, gameState.player.health + 15); } },
    { text: '📱 Offre d\'emploi ! +10⭐', effect: () => { gameState.player.exp += 10; } },
    { text: '🎉 Fête surprise ! +20😊', effect: () => { gameState.player.happiness = Math.min(gameState.player.maxHappiness, gameState.player.happiness + 20); } }
  ];

  if (Math.random() < 0.3) {
    const event = events[Math.floor(Math.random() * events.length)];
    event.effect();
    addEvent(event.text.split(' ')[0], event.text);
  }
}

// ==================== LEVEL SYSTEM ====================
function checkLevelUp() {
  const p = gameState.player;

  while (p.exp >= p.expToNext) {
    p.exp -= p.expToNext;
    p.level++;
    p.expToNext = Math.floor(p.expToNext * 1.5);
    p.maxEnergy += 5;
    p.maxHealth += 5;
    p.energy = p.maxEnergy;
    p.health = p.maxHealth;

    showLevelUp(p.level);
    addEvent('🎉', `Niveau ${p.level} atteint !`);
  }
}

function showLevelUp(level) {
  document.getElementById('levelUpNumber').textContent = level;
  document.getElementById('levelUpOverlay').classList.add('active');
}

function closeLevelUp() {
  document.getElementById('levelUpOverlay').classList.remove('active');
}

// ==================== CAREER SYSTEM ====================
function checkCareerPromotion() {
  const c = gameState.career;
  const nextCareer = careers[c.level + 1];

  if (nextCareer && c.progress >= nextCareer.expNeeded) {
    c.level++;
    c.title = nextCareer.title;
    c.salary = nextCareer.salary;
    addEvent('🏢', `Promotion ! Vous êtes maintenant ${c.title}`);
    showNotification(`🏢 Promotion ! ${c.title}`, 'success');
  }
}

function openCareerModal() {
  const list = document.getElementById('careerList');
  list.innerHTML = '';

  careers.forEach((career, index) => {
    const isLocked = index > gameState.career.level + 1;
    const isCurrent = index === gameState.career.level;
    const isAvailable = index === gameState.career.level + 1;

    const div = document.createElement('div');
    div.className = 'shop-item';
    div.style.opacity = isLocked ? '0.5' : '1';
    div.innerHTML = `
      <div class="shop-item-icon">${isCurrent ? '💼' : isLocked ? '🔒' : '🏢'}</div>
      <div class="shop-item-info">
        <h4>${career.title} ${isCurrent ? '(Actuel)' : ''}</h4>
        <p>${career.desc} | 💰 ${career.salary}/jour</p>
        ${isAvailable ? `<p style="color:var(--success)">✅ Disponible !</p>` : ''}
        ${isLocked ? `<p style="color:var(--text-muted)">🔒 Nécessité: ${career.expNeeded}⭐</p>` : ''}
      </div>
    `;

    if (isAvailable) {
      div.onclick = () => {
        gameState.career.level = index;
        gameState.career.title = career.title;
        gameState.career.salary = career.salary;
        closeModal('careerModal');
        updateUI();
        addEvent('🏢', `Promotion ! ${career.title}`);
        showNotification(`🏢 Promotion ! ${career.title}`, 'success');
        saveGame();
      };
    }

    list.appendChild(div);
  });
}

// ==================== SHOP ====================
function renderShop() {
  const container = document.getElementById('shopItems');
  container.innerHTML = '';

  shopItems.forEach(item => {
    const div = document.createElement('div');
    div.className = 'shop-item';
    div.innerHTML = `
      <div class="shop-item-icon">${item.name.split(' ')[0]}</div>
      <div class="shop-item-info">
        <h4>${item.name.substring(item.name.indexOf(' ') + 1)}</h4>
        <p>${item.desc}</p>
      </div>
      <div class="shop-item-price">💰 ${item.price}</div>
    `;
    div.onclick = () => buyItem(item);
    container.appendChild(div);
  });
}

function buyItem(item) {
  const p = gameState.player;

  if (p.money < item.price) {
    showNotification('❌ Pas assez d\'argent !', 'warning');
    return;
  }

  p.money -= item.price;

  // Apply effects
  if (item.effect.health) p.health = Math.min(p.maxHealth, p.health + item.effect.health);
  if (item.effect.energy) p.energy = Math.min(p.maxEnergy, p.energy + item.effect.energy);
  if (item.effect.happiness) p.happiness = Math.min(p.maxHappiness, p.happiness + item.effect.happiness);
  if (item.effect.exp) p.exp += item.effect.exp;

  // Add to inventory
  if (!gameState.inventory[item.id]) {
    gameState.inventory[item.id] = { ...item, count: 0 };
  }
  gameState.inventory[item.id].count++;

  addEvent('🛒', `Acheté ${item.name}`);
  updateUI();
  saveGame();
  showNotification(`✅ ${item.name} acheté !`, 'success');
}

// ==================== RELATIONSHIPS ====================
function meetNewPerson() {
  const genders = npcNames;
  const genderIndex = Math.floor(Math.random() * genders.length);
  const isMale = Math.random() > 0.5;
  const names = isMale ? genders[genderIndex].male : genders[genderIndex].female;
  const name = names[Math.floor(Math.random() * names.length)];
  const avatars = ['👨', '👩', '🧑', '👦', '👧', '🧔', '👱‍♀️', '👨‍🦰', '👩‍🦰'];
  const avatar = avatars[Math.floor(Math.random() * avatars.length)];

  const relationship = {
    name: name,
    avatar: avatar,
    affinity: Math.floor(Math.random() * 30) + 10,
    type: isMale ? 'homme' : 'femme'
  };

  gameState.relationships.push(relationship);
  addEvent('💕', `Vous avez rencontré ${name} !`);
  updateUI();
  saveGame();
  showNotification(`💕 Nouveau ami : ${name} !`, 'success');
}

function interactWithNPC(index) {
  const npc = gameState.relationships[index];
  const p = gameState.player;

  if (p.energy < 10) {
    showNotification('😴 Pas assez d\'énergie !', 'warning');
    return;
  }

  p.energy -= 10;
  npc.affinity = Math.min(100, npc.affinity + Math.floor(Math.random() * 15) + 5);
  p.happiness = Math.min(p.maxHappiness, p.happiness + 5);

  addEvent('💬', `Vous avez discuté avec ${npc.name}`);
  updateUI();
  saveGame();
}

function renderRelationships() {
  const container = document.getElementById('relationshipsList');
  container.innerHTML = '';

  if (gameState.relationships.length === 0) {
    container.innerHTML = '<p style="text-align:center;color:var(--text-muted);padding:20px;">Aucune relation pour le moment. Rencontrez des personnes !</p>';
    return;
  }

  gameState.relationships.forEach((npc, index) => {
    const div = document.createElement('div');
    div.className = 'relationship-card';
    div.innerHTML = `
      <div class="relationship-avatar">${npc.avatar}</div>
      <div class="relationship-info">
        <h4>${npc.name}</h4>
        <p>Affinité: ${npc.affinity}%</p>
        <div class="relationship-bar">
          <div class="relationship-fill" style="width:${npc.affinity}%"></div>
        </div>
      </div>
      <button class="btn btn-small btn-primary" onclick="interactWithNPC(${index})">💬</button>
    `;
    container.appendChild(div);
  });
}

// ==================== INVENTORY ====================
function renderInventory() {
  const container = document.getElementById('inventoryGrid');
  container.innerHTML = '';

  const items = Object.values(gameState.inventory);

  if (items.length === 0) {
    container.innerHTML = '<p style="text-align:center;color:var(--text-muted);padding:20px;grid-column:1/-1;">Inventaire vide</p>';
    return;
  }

  items.forEach(item => {
    const div = document.createElement('div');
    div.className = 'inventory-item';
    div.innerHTML = `
      <div class="inventory-item-icon">${item.name.split(' ')[0]}</div>
      <div class="inventory-item-count">x${item.count}</div>
    `;
    container.appendChild(div);
  });
}

// ==================== ACHIEVEMENTS ====================
function renderAchievements() {
  const container = document.getElementById('achievementsList');
  container.innerHTML = '';

  achievements.forEach(ach => {
    const unlocked = gameState.achievements.includes(ach.id);
    const div = document.createElement('div');
    div.className = `achievement ${unlocked ? '' : 'locked'}`;
    div.innerHTML = `
      <div class="achievement-icon">${ach.icon}</div>
      <div class="achievement-info">
        <h4>${ach.name} ${unlocked ? '✅' : '🔒'}</h4>
        <p>${ach.desc}</p>
      </div>
    `;
    container.appendChild(div);
  });
}

function unlockAchievement(id) {
  if (!gameState.achievements.includes(id)) {
    gameState.achievements.push(id);
    const ach = achievements.find(a => a.id === id);
    if (ach) {
      showNotification(`🏆 Succès débloqué : ${ach.name} !`, 'success');
      addEvent('🏆', `Succès : ${ach.name}`);
    }
  }
}

function checkAchievements() {
  const p = gameState.player;

  if (p.level >= 5) unlockAchievement('level5');
  if (p.level >= 10) unlockAchievement('level10');
  if (p.level >= 20) unlockAchievement('scholar');
  if (p.money >= 1000) unlockAchievement('rich');
  if (p.money >= 5000) unlockAchievement('super_rich');
  if (p.happiness >= 100) unlockAchievement('happy');
  if (p.health >= 100) unlockAchievement('healthy');
  if (gameState.relationships.length >= 5) unlockAchievement('social');
  if (p.day >= 30) unlockAchievement('day30');

  // Count total inventory items
  let totalItems = Object.values(gameState.inventory).reduce((sum, item) => sum + item.count, 0);
  if (totalItems >= 10) unlockAchievement('collector');
}

// ==================== UI UPDATE ====================
function updateUI() {
  const p = gameState.player;
  const c = gameState.career;

  // Player info
  document.getElementById('playerAvatar').textContent = p.avatar;
  document.getElementById('playerNameDisplay').textContent = p.name;
  document.getElementById('playerLevel').textContent = `Niveau ${p.level}`;
  document.getElementById('dayCount').textContent = p.day;
  document.getElementById('moneyDisplay').textContent = p.money;

  // Stats
  document.getElementById('healthValue').textContent = `${p.health}/${p.maxHealth}`;
  document.getElementById('healthBar').style.width = `${(p.health / p.maxHealth) * 100}%`;

  document.getElementById('energyValue').textContent = `${p.energy}/${p.maxEnergy}`;
  document.getElementById('energyBar').style.width = `${(p.energy / p.maxEnergy) * 100}%`;

  document.getElementById('happinessValue').textContent = `${p.happiness}/${p.maxHappiness}`;
  document.getElementById('happinessBar').style.width = `${(p.happiness / p.maxHappiness) * 100}%`;

  document.getElementById('expValue').textContent = `${p.exp}/${p.expToNext}`;
  document.getElementById('expBar').style.width = `${(p.exp / p.expToNext) * 100}%`;

  // Career
  document.getElementById('jobTitle').textContent = c.title;
  document.getElementById('jobDesc').textContent = careers[c.level]?.desc || 'Max';

  const nextCareer = careers[c.level + 1];
  if (nextCareer) {
    const progress = Math.min(100, (c.progress / nextCareer.expNeeded) * 100);
    document.getElementById('careerProgress').style.width = `${progress}%`;
    document.getElementById('careerProgressText').textContent = `${Math.floor(progress)}%`;
  } else {
    document.getElementById('careerProgress').style.width = '100%';
    document.getElementById('careerProgressText').textContent = 'MAX';
  }

  // Render dynamic sections
  renderRelationships();
  renderInventory();
  renderAchievements();
}

// ==================== TABS ====================
function switchTab(tabName) {
  document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));

  document.getElementById(`tab${tabName.charAt(0).toUpperCase() + tabName.slice(1)}`).classList.add('active');

  const navItems = document.querySelectorAll('.nav-item');
  const tabMap = { actions: 0, shop: 1, relationships: 2, inventory: 3, achievements: 4 };
  navItems[tabMap[tabName]].classList.add('active');
}

// ==================== MODALS ====================
function openModal(modalId) {
  document.getElementById(modalId).classList.add('active');
  if (modalId === 'careerModal') openCareerModal();
}

function closeModal(modalId) {
  document.getElementById(modalId).classList.remove('active');
}

// ==================== NOTIFICATIONS ====================
