  playSound(1200, 0.3, 'sine', 0.05);
}

// Game State
const GAME_STATES = { MENU: 0, COUNTDOWN: 1, RACING: 2, FINISHED: 3 };
let gameState = GAME_STATES.MENU;
let currentMode = 'circuit';
let selectedCar = 0;
let selectedTrack = 0;
let raceTime = 0;
let lapCount = 3;
let currentLap = 1;
let driftScore = 0;
let isDrifting = false;
let driftTimer = 0;

// Cars
const CARS = [
  { name: 'Thunder', color: '#0ff', speed: 8, accel: 7, grip: 6, durability: 7, handle: 'Balanced' },
  { name: 'Viper', color: '#f0f', speed: 9, accel: 6, grip: 5, durability: 5, handle: 'Fast' },
  { name: 'Tank', color: '#ff0', speed: 5, accel: 8, grip: 9, durability: 10, handle: 'Stable' },
  { name: 'Phantom', color: '#f00', speed: 10, accel: 5, grip: 4, durability: 4, handle: 'Extreme' },
  { name: 'Storm', color: '#0f0', speed: 7, accel: 8, grip: 7, durability: 6, handle: 'Agile' }
];

// Tracks
const TRACKS = [
  { name: 'Neon City', env: 'city', colors: { road: '#222', grass: '#111', line: '#0ff' }, length: 3000, curves: 0.3 },
  { name: 'Desert Highway', env: 'desert', colors: { road: '#8B7355', grass: '#D2B48C', line: '#fff' }, length: 4000, curves: 0.1 },
  { name: 'Mountain Pass', env: 'mountain', colors: { road: '#444', grass: '#2d5a27', line: '#ff0' }, length: 3500, curves: 0.5 },
  { name: 'Cyber Loop', env: 'neon', colors: { road: '#111', grass: '#0a0a2e', line: '#f0f' }, length: 2500, curves: 0.4 }
];

// Road segments
let segments = [];
let trackLength = 0;
let playerX = 0;
let playerZ = 0;
let playerSpeed = 0;
let playerMaxSpeed = 0;
let playerAccel = 0;
let playerGrip = 0;
let playerDurability = 100;
let boost = 100;
let isBoosting = false;
let steering = 0;
let cameraHeight = 1000;
let cameraDepth = 0;
let position = 1;

// AI Cars
let aiCars = [];
const AI_COUNT = 7;

// Input
const keys = {};
window.addEventListener('keydown', e => { keys[e.key] = true; e.preventDefault(); });
window.addEventListener('keyup', e => { keys[e.key] = false; e.preventDefault(); });

// Day/Night cycle
let dayTime = 0;
let isNight = false;

// Weather
let weather = 'clear';
let rainDrops = [];

// Generate road
function generateTrack(trackIndex) {
  segments = [];
  const track = TRACKS[trackIndex];
  const numSegments = track.length;
  trackLength = numSegments * 200;

  for (let i = 0; i < numSegments; i++) {
    const progress = i / numSegments;
    let curve = 0;
    let hill = 0;

    // Generate curves
    if (i > 50 && i < 150) curve = Math.sin(i * 0.05) * track.curves * 3;
    if (i > 200 && i < 350) curve = Math.cos(i * 0.03) * track.curves * 4;
    if (i > 400 && i < 500) curve = Math.sin(i * 0.08) * track.curves * 2;
    if (i > 600 && i < 800) curve = Math.cos(i * 0.04) * track.curves * 5;
    if (i > 900 && i < 1100) curve = Math.sin(i * 0.06) * track.curves * 3;

    // Generate hills
    if (i > 100 && i < 200) hill = Math.sin(i * 0.02) * 30;
    if (i > 300 && i < 400) hill = Math.cos(i * 0.015) * 40;
    if (i > 500 && i < 600) hill = Math.sin(i * 0.025) * 25;

    segments.push({
      index: i,
      p: { world: { x: 0, y: hill, z: i * 200 }, screen: {}, camera: {} },
      curve: curve,
      color: Math.floor(i / 3) % 2 === 0 ? track.colors.road : shadeColor(track.colors.road, 10),
      grassColor: Math.floor(i / 3) % 2 === 0 ? track.colors.grass : shadeColor(track.colors.grass, 10),
      lineColor: track.colors.line,
      hasLine: Math.floor(i / 3) % 2 === 0,
      sprite: null
    });
  }

  // Add sprites (trees, buildings, etc.)
  for (let i = 0; i < numSegments; i += 10 + Math.floor(Math.random() * 20)) {
    const side = Math.random() > 0.5 ? 1 : -1;
    const dist = 3 + Math.random() * 5;
    segments[i].sprite = {
      type: track.env === 'city' ? 'building' : track.env === 'neon' ? 'neon_sign' : track.env === 'desert' ? 'cactus' : 'tree',
      side: side,
      offset: dist
    };
  }
}

function shadeColor(color, percent) {
  let num = parseInt(color.replace('#', ''), 16);
  let r = Math.min(255, (num >> 16) + percent);
  let g = Math.min(255, ((num >> 8) & 0x00FF) + percent);
  let b = Math.min(255, (num & 0x0000FF) + percent);
  return `rgb(${r},${g},${b})`;
}

// Project 3D to 2D
function project(p, cameraX, cameraY, cameraZ, cameraDepth, width, height, roadWidth) {
  p.camera.x = p.world.x - cameraX;
  p.camera.y = p.world.y - cameraY;
  p.camera.z = p.world.z - cameraZ;
  p.screen.scale = cameraDepth / p.camera.z;
  p.screen.x = Math.round(width / 2 + p.screen.scale * p.camera.x * width / 2);
  p.screen.y = Math.round(height / 2 - p.screen.scale * p.camera.y * height / 2);
  p.screen.w = Math.round(p.screen.scale * roadWidth * width / 2);
}

// Render segment
function renderSegment(seg, prevSeg, width, height) {
  const p = seg.p.screen;
  const pp = prevSeg.p.screen;

  if (p.camera.z <= cameraDepth || pp.camera.z <= cameraDepth) return;

  // Draw grass
  ctx.fillStyle = seg.grassColor;
  ctx.fillRect(0, p.y, width, pp.y - p.y);

  // Draw road
  drawPoly(pp.x - pp.w, pp.y, pp.x + pp.w, pp.y, p.x + p.w, p.y, p.x - p.w, p.y, seg.color);

  // Draw lane lines
  if (seg.hasLine) {
    const lineW = p.w / 20;
    drawPoly(pp.x - lineW, pp.y, pp.x + lineW, pp.y, p.x + lineW, p.y, p.x - lineW, p.y, seg.lineColor);
  }

  // Draw road edges
  const edgeW = p.w / 30;
  drawPoly(pp.x - pp.w - edgeW, pp.y, pp.x - pp.w, pp.y, p.x - p.w, p.y, p.x - p.w - edgeW, p.y, '#fff');
  drawPoly(pp.x + pp.w, pp.y, pp.x + pp.w + edgeW, pp.y, p.x + p.w + edgeW, p.y, p.x + p.w, p.y, '#fff');

  // Draw sprites
  if (seg.sprite) {
    drawSprite(seg, width, height);
  }
}

function drawPoly(x1, y1, x2, y2, x3, y3, x4, y4, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.lineTo(x3, y3);
  ctx.lineTo(x4, y4);
  ctx.closePath();
  ctx.fill();
}

function drawSprite(seg, width, height) {
  const p = seg.p.screen;
  const sprite = seg.sprite;
  if (!sprite || p.camera.z <= cameraDepth) return;

  const spriteX = p.x + p.w * sprite.side * sprite.offset;
  const spriteY = p.y;
  const spriteScale = p.scale * 500;

  ctx.save();
  ctx.translate(spriteX, spriteY);

  if (sprite.type === 'building') {
    const bw = spriteScale * 0.5;
    const bh = spriteScale * 2;
    ctx.fillStyle = isNight ? '#1a1a3e' : '#333';
    ctx.fillRect(-bw / 2, -bh, bw, bh);
    // Windows
    ctx.fillStyle = isNight ? '#ff0' : '#888';
    for (let wy = 0; wy < bh - 20; wy += 30) {
      for (let wx = -bw / 2 + 10; wx < bw / 2 - 10; wx += 25) {
        if (isNight && Math.random() > 0.3) {
          ctx.fillRect(wx, -bh + wy + 10, 15, 20);
        }
      }
    }
  } else if (sprite.type === 'tree') {
    const tw = spriteScale * 0.3;
    const th = spriteScale * 1.5;
    ctx.fillStyle = '#4a2800';
    ctx.fillRect(-tw / 6, -th * 0.3, tw / 3, th * 0.3);
    ctx.fillStyle = '#2d5a27';
    ctx.beginPath();
    ctx.moveTo(0, -th);
    ctx.lineTo(-tw / 2, -th * 0.3);
    ctx.lineTo(tw / 2, -th * 0.3);
    ctx.closePath();
    ctx.fill();
  } else if (sprite.type === 'cactus') {
    const cw = spriteScale * 0.15;
    const ch = spriteScale * 0.8;
    ctx.fillStyle = '#2d5a27';
    ctx.fillRect(-cw / 2, -ch, cw, ch);
    ctx.fillRect(-cw, -ch * 0.7, cw * 0.5, cw);
    ctx.fillRect(cw / 2, -ch * 0.5, cw * 0.5, cw);
  } else if (sprite.type === 'neon_sign') {
    const sw = spriteScale * 0.4;
    const sh = spriteScale * 0.6;
    ctx.fillStyle = '#f0f';
    ctx.shadowColor = '#f0f';
    ctx.shadowBlur = 20;
    ctx.fillRect(-sw / 2, -sh, sw, sh);
    ctx.shadowBlur = 0;
  }

  ctx.restore();
}

// Render car
function renderCar(x, y, scale, color, isPlayer = false) {
  const carW = 60 * scale;
  const carH = 30 * scale;

  ctx.save();
  ctx.translate(x, y);

  // Car body
  ctx.fillStyle = color;
  ctx.shadowColor = color;
  ctx.shadowBlur = isPlayer ? 20 : 10;
  ctx.beginPath();
  ctx.moveTo(-carW / 2, 0);
  ctx.lineTo(-carW / 2 + 5 * scale, -carH);
  ctx.lineTo(carW / 2 - 5 * scale, -carH);
  ctx.lineTo(carW / 2, 0);
  ctx.closePath();
  ctx.fill();
  ctx.shadowBlur = 0;

  // Windshield
  ctx.fillStyle = isNight ? '#111' : '#333';
  ctx.beginPath();
  ctx.moveTo(-carW / 4, -carH);
  ctx.lineTo(-carW / 4 + 3 * scale, -carH * 1.3);
  ctx.lineTo(carW / 4 - 3 * scale, -carH * 1.3);
  ctx.lineTo(carW / 4, -carH);
  ctx.closePath();
  ctx.fill();

  // Wheels
  ctx.fillStyle = '#000';
  ctx.fillRect(-carW / 2 - 3 * scale, -5 * scale, 6 * scale, 10 * scale);
  ctx.fillRect(carW / 2 - 3 * scale, -5 * scale, 6 * scale, 10 * scale);

  // Headlights
  if (isNight || isPlayer) {
    ctx.fillStyle = '#ff0';
    ctx.shadowColor = '#ff0';
    ctx.shadowBlur = 10;
    ctx.fillRect(-carW / 3, -3 * scale, 8 * scale, 5 * scale);
    ctx.fillRect(carW / 3 - 8 * scale, -3 * scale, 8 * scale, 5 * scale);
    ctx.shadowBlur = 0;
  }

  // Tail lights
  ctx.fillStyle = '#f00';
  ctx.fillRect(-carW / 2 + 2 * scale, -2 * scale, 5 * scale, 3 * scale);
  ctx.fillRect(carW / 2 - 7 * scale, -2 * scale, 5 * scale, 3 * scale);

  ctx.restore();
}

// Render AI car
function renderAICar(aiCar) {
  const seg = segments[Math.floor(aiCar.z / 200) % segments.length];
  if (!seg) return;

  const p = seg.p.screen;
  if (p.camera.z <= cameraDepth) return;

  const scale = p.scale * 500;
  const x = p.x + p.w * aiCar.offset;
  const y = p.y;

  renderCar(x, y, scale * 0.5, aiCar.color, false);
}

// Update AI
function updateAI(dt) {
  aiCars.forEach(ai => {
    ai.z += ai.speed * dt;
    if (ai.z >= trackLength) {
      ai.z -= trackLength;
      ai.laps++;
    }

    // Simple AI steering
    const segIdx = Math.floor(ai.z / 200) % segments.length;
    const seg = segments[segIdx];
    if (seg) {
      ai.offset += seg.curve * dt * 0.5;
      ai.offset = Math.max(-2, Math.min(2, ai.offset));
    }

    // Speed variation
    ai.speed = ai.baseSpeed + Math.sin(Date.now() * 0.001 + ai.id) * 50;
  });

  // Calculate position
  const playerProgress = playerZ + currentLap * trackLength;
  let pos = 1;
  aiCars.forEach(ai => {
    const aiProgress = ai.z + ai.laps * trackLength;
    if (aiProgress > playerProgress) pos++;
  });
  position = pos;
}

// Update player
function updatePlayer(dt) {
  if (gameState !== GAME_STATES.RACING) return;

  const track = TRACKS[selectedTrack];
  const segIdx = Math.floor(playerZ / 200) % segments.length;
  const seg = segments[segIdx];

  // Acceleration
  if (keys['ArrowUp'] || keys['w']) {
    playerSpeed += playerAccel * dt;
  } else if (keys['ArrowDown'] || keys['s']) {
    playerSpeed -= playerAccel * 2 * dt;
  } else {
    playerSpeed -= playerAccel * 0.5 * dt;
  }

  // Boost
  if ((keys[' '] || keys['Shift']) && boost > 0 && playerSpeed > 0) {
    isBoosting = true;
    boost -= 50 * dt;
    playerSpeed += playerAccel * 3 * dt;
    if (boost <= 0) { boost = 0; isBoosting = false; }
  } else {
    isBoosting = false;
    boost = Math.min(100, boost + 10 * dt);
  }

  // Steering
  if (keys['ArrowLeft'] || keys['a']) {
    steering = -1;
    playerX -= 3 * dt * (playerSpeed / playerMaxSpeed);
  } else if (keys['ArrowRight'] || keys['d']) {
    steering = 1;
    playerX += 3 * dt * (playerSpeed / playerMaxSpeed);
  } else {
    steering = 0;
  }

  // Curve influence
  if (seg) {
    playerX -= seg.curve * dt * (playerSpeed / playerMaxSpeed) * 0.5;
  }

  // Drift mechanics
  if ((keys['ArrowLeft'] || keys['a']) && playerSpeed > playerMaxSpeed * 0.6) {
    isDrifting = true;
    driftTimer += dt;
    driftScore += Math.floor(dt * 100);
    playDriftSound();
    document.getElementById('drift-indicator').style.display = 'block';
  } else if ((keys['ArrowRight'] || keys['d']) && playerSpeed > playerMaxSpeed * 0.6) {
    isDrifting = true;
    driftTimer += dt;
    driftScore += Math.floor(dt * 100);
    playDriftSound();
    document.getElementById('drift-indicator').style.display = 'block';
  } else {
    if (isDrifting && driftTimer > 0.5) {
      driftScore += Math.floor(driftTimer * 200);
    }
    isDrifting = false;
    driftTimer = 0;
    document.getElementById('drift-indicator').style.display = 'none';
  }

  // Grip check
  if (isDrifting) {
    playerX += steering * playerGrip * dt * 0.3;
  }

  // Clamp position
  playerX = Math.max(-3, Math.min(3, playerX));

  // Off-road slowdown
  if (Math.abs(playerX) > 2) {
    playerSpeed -= playerAccel * 2 * dt;
    playerDurability -= dt * 5;
  }

  // Collision with AI
  aiCars.forEach(ai => {
    const dz = Math.abs(ai.z - playerZ);
    const dx = Math.abs(ai.offset - playerX);
    if (dz < 200 && dx < 0.5) {
      playerSpeed -= 200;
      playerDurability -= 10;
      playCollisionSound();
      document.getElementById('damage-overlay').style.opacity = '0.5';
      setTimeout(() => { document.getElementById('damage-overlay').style.opacity = '0'; }, 200);
      if (playerX < ai.offset) {
        playerX -= 0.5;
      } else {
        playerX += 0.5;
      }
    }
  });

  // Clamp speed
  playerSpeed = Math.max(0, Math.min(playerMaxSpeed, playerSpeed));

  // Update position
  playerZ += playerSpeed * dt;
  if (playerZ >= trackLength) {
    playerZ -= trackLength;
    currentLap++;
    if (currentLap > lapCount) {
      finishRace();
    }
  }

  // Day/night cycle
  dayTime += dt * 0.01;
  isNight = Math.sin(dayTime) < 0;

  // Update UI
  document.getElementById('speed-value').textContent = Math.floor(playerSpeed);
  document.getElementById('boost-bar').style.width = boost + '%';
  document.getElementById('gear-value').textContent = Math.min(6, Math.floor(playerSpeed / (playerMaxSpeed / 6)) + 1);
  document.getElementById('pos-value').textContent = position + '/' + (AI_COUNT + 1);
  document.getElementById('lap-value').textContent = Math.min(currentLap, lapCount) + '/' + lapCount;

  const minutes = Math.floor(raceTime / 60);
  const seconds = Math.floor(raceTime % 60);
  const ms = Math.floor((raceTime % 1) * 1000);
  document.getElementById('timer-display').textContent =
    `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}.${String(ms).padStart(3, '0')}`;

  // Engine sound
  if (Math.floor(playerSpeed) % 10 === 0) {
    playEngineSound(playerSpeed);
  }

  // Check elimination mode
  if (currentMode === 'elimination' && playerDurability <= 0) {
    finishRace();
  }
}

// Render minimap
function renderMinimap() {
  minimapCtx.clearRect(0, 0, 150, 150);
  minimapCtx.fillStyle = 'rgba(0,0,0,0.5)';
  minimapCtx.fillRect(0, 0, 150, 150);

  // Draw track outline
  minimapCtx.strokeStyle = '#0ff';
  minimapCtx.lineWidth = 2;
  minimapCtx.beginPath();
  for (let i = 0; i < segments.length; i += 10) {
    const seg = segments[i];
    const x = 75 + (seg.p.world.x / 10) * 20;
    const y = 75 + (Math.sin(i * 0.01) * 30);
    if (i === 0) minimapCtx.moveTo(x, y);
    else minimapCtx.lineTo(x, y);
  }
  minimapCtx.closePath();
  minimapCtx.stroke();

  // Draw player
  const playerSegIdx = Math.floor(playerZ / 200) % segments.length;
  const playerSeg = segments[playerSegIdx];
  if (playerSeg) {
    minimapCtx.fillStyle = '#0ff';
    minimapCtx.beginPath();
    minimapCtx.arc(75 + playerX * 10, 75 + Math.sin(playerSegIdx * 0.01) * 30, 4, 0, Math.PI * 2);
    minimapCtx.fill();
  }

  // Draw AI
  aiCars.forEach(ai => {
    const aiSegIdx = Math.floor(ai.z / 200) % segments.length;
    const aiSeg = segments[aiSegIdx];
    if (aiSeg) {
      minimapCtx.fillStyle = ai.color;
      minimapCtx.beginPath();
      minimapCtx.arc(75 + ai.offset * 10, 75 + Math.sin(aiSegIdx * 0.01) * 30, 3, 0, Math.PI * 2);
      minimapCtx.fill();
    }
  });
}

// Render sky
function renderSky() {
  const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height / 2);
  if (isNight) {
    gradient.addColorStop(0, '#0a0a2e');
    gradient.addColorStop(1, '#1a1a3e');
  } else {
    gradient.addColorStop(0, '#1a3a5c');
    gradient.addColorStop(1, '#4a8ab5');
  }
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height / 2);

  // Stars at night
  if (isNight) {
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
      const x = (Math.sin(i * 123.456) * 0.5 + 0.5) * canvas.width;
      const y = (Math.cos(i * 789.012) * 0.5 + 0.5) * canvas.height / 2;
      const size = Math.sin(Date.now() * 0.001 + i) * 0.5 + 1;
      ctx.beginPath();
      ctx.arc(x, y, size, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // Sun/Moon
  const celestialY = canvas.height / 2 - Math.sin(dayTime) * 100;
  const celestialX = canvas.width / 2 + Math.cos(dayTime) * 200;
  if (isNight) {
    ctx.fillStyle = '#fff';
    ctx.shadowColor = '#fff';
    ctx.shadowBlur = 30;
    ctx.beginPath();
    ctx.arc(celestialX, celestialY, 30, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;
  } else {
    ctx.fillStyle = '#ff0';
    ctx.shadowColor = '#ff0';
    ctx.shadowBlur = 40;
    ctx.beginPath();
    ctx.arc(celestialX, celestialY, 40, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;
  }
}

// Render rain
function renderRain() {
  if (weather !== 'rain') return;
  ctx.strokeStyle = 'rgba(100,150,255,0.3)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 100; i++) {
    const x = (Math.sin(i * 123 + Date.now() * 0.01) * 0.5 + 0.5) * canvas.width;
    const y = (Math.cos(i * 456 + Date.now() * 0.02) * 0.5 + 0.5) * canvas.height;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 2, y + 10);
    ctx.stroke();
  }
}

// Main render
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  renderSky();

  const baseSegment = Math.floor(playerZ / 200) % segments.length;
  const basePercent = (playerZ % 200) / 200;
  const playerSegment = segments[baseSegment];
  const playerY = playerSegment ? playerSegment.p.world.y : 0;

  let maxy = canvas.height;
  let x = 0;
  let dx = 0;

  // Render road segments
  for (let n = 0; n < 200; n++) {
    const segIdx = (baseSegment + n) % segments.length;
    const seg = segments[segIdx];
    if (!seg) continue;

    const looped = (baseSegment + n) >= segments.length;
    const segZ = seg.p.world.z + (looped ? trackLength : 0);

    project(seg.p, playerX * 2000 - x, playerY + cameraHeight, playerZ, cameraDepth, canvas.width, canvas.height, 2000);

    x += dx;
    dx += seg.curve;

    if (seg.p.camera.z <= cameraDepth || seg.p.screen.y >= maxy) continue;

    if (n > 0) {
      const prevIdx = (baseSegment + n - 1) % segments.length;
      const prevSeg = segments[prevIdx];
      if (prevSeg && prevSeg.p.camera.z > cameraDepth) {
        renderSegment(seg, prevSeg, canvas.width, canvas.height);
      }
    }

    maxy = seg.p.screen.y;
  }

  // Render AI cars (back to front)
  for (let n = 199; n > 0; n--) {
    const segIdx = (baseSegment + n) % segments.length;
    const seg = segments[segIdx];
    if (!seg) continue;

    aiCars.forEach(ai => {
      const aiSegIdx = Math.floor(ai.z / 200) % segments.length;
      if (aiSegIdx === segIdx) {
        renderAICar(ai);
      }
    });
  }

  // Render player car
  const playerScreenY = canvas.height - 100;
  const playerScreenX = canvas.width / 2 + playerX * 200;
  renderCar(playerScreenX, playerScreenY, 1.5, CARS[selectedCar].color, true);

  // Speed lines effect
  if (playerSpeed > playerMaxSpeed * 0.7) {
    const intensity = (playerSpeed - playerMaxSpeed * 0.7) / (playerMaxSpeed * 0.3);
    ctx.strokeStyle = `rgba(255,255,255,${intensity * 0.3})`;
    ctx.lineWidth = 2;
    for (let i = 0; i < 20; i++) {
      const x = Math.random() * canvas.width;
      const y = Math.random() * canvas.height;
      const len = 50 + intensity * 100;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + (x - canvas.width / 2) * 0.1, y + len);
      ctx.stroke();
    }
  }

  // Boost effect
  if (isBoosting) {
    ctx.fillStyle = 'rgba(0,255,255,0.1)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Boost flames
    const flameX = playerScreenX;
    const flameY = playerScreenY + 30;
    for (let i = 0; i < 5; i++) {
      ctx.fillStyle = `rgba(0,255,255,${0.5 - i * 0.1})`;
      ctx.beginPath();
      ctx.arc(flameX + (Math.random() - 0.5) * 20, flameY + i * 10, 10 - i * 2, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  renderRain();
  renderMinimap();
}

// Game loop
let lastTime = 0;
function gameLoop(timestamp) {
  const dt = Math.min((timestamp - lastTime) / 1000, 0.05);
  lastTime = timestamp;

  if (gameState === GAME_STATES.RACING) {
    raceTime += dt;
    updatePlayer(dt);
    updateAI(dt);
  }

  render();
  requestAnimationFrame(gameLoop);
}

// Initialize AI
function initAI() {
  aiCars = [];
  for (let i = 0; i < AI_COUNT; i++) {
    aiCars.push({
      id: i,
      z: Math.random() * trackLength,
      speed: 200 + Math.random() * 200,
      baseSpeed: 200 + Math.random() * 200,
      offset: (Math.random() - 0.5) * 2,
      color: CARS[Math.floor(Math.random() * CARS.length)].color,
      laps: 0
    });
  }
}

// Start race
function startRace() {
  initAudio();
  generateTrack(selectedTrack);
  initAI();

  playerX = 0;
  playerZ = 0;
  playerSpeed = 0;
  const car = CARS[selectedCar];
  playerMaxSpeed = car.speed * 50;
  playerAccel = car.accel * 10;
  playerGrip = car.grip * 0.1;
  playerDurability = car.durability * 10;
  boost = 100;
  currentLap = 1;
  raceTime = 0;
  driftScore = 0;
  position = 1;

  document.getElementById('menu-screen').style.display = 'none';
  document.getElementById('game-over').style.display = 'none';
  document.getElementById('hud').style.display = 'flex';
  document.getElementById('position-display').style.display = 'block';
  document.getElementById('lap-display').style.display = 'block';
  document.getElementById('timer-display').style.display = 'block';
  document.getElementById('minimap').style.display = 'block';

  // Countdown
  gameState = GAME_STATES.COUNTDOWN;
  const countdownEl = document.getElementById('countdown');
  countdownEl.style.display = 'block';

  let count = 3;
  countdownEl.textContent = count;
  playSound(440, 0.3, 'sine', 0.1);

  const countInterval = setInterval(() => {
    count--;
    if (count > 0) {
      countdownEl.textContent = count;
      playSound(440, 0.3, 'sine', 0.1);
    } else if (count === 0) {
      countdownEl.textContent = 'GO!';
      countdownEl.style.color = '#0f0';
      playSound(880, 0.5, 'sine', 0.15);
    } else {
      countdownEl.style.display = 'none';
      countdownEl.style.color = '#0ff';
      gameState = GAME_STATES.RACING;
      clearInterval(countInterval);
    }
  }, 1000);
}

// Finish race
function finishRace() {
  gameState = GAME_STATES.FINISHED;
  document.getElementById('hud').style.display = 'none';
  document.getElementById('position-display').style.display = 'none';
  document.getElementById('lap-display').style.display = 'none';
  document.getElementById('timer-display').style.display = 'none';
  document.getElementById('minimap').style.display = 'none';
  document.getElementById('drift-indicator').style.display = 'none';

  const goEl = document.getElementById('game-over');
  goEl.style.display = 'flex';

  const posText = position === 1 ? '1st' : position === 2 ? '2nd' : position === 3 ? '3rd' : `${position}th`;
  document.getElementById('go-title').textContent = currentMode === 'elimination' && playerDurability <= 0 ? 'WRECKED!' : 'RACE COMPLETE';
  document.getElementById('go-position').textContent = `Position: ${posText}`;

  const minutes = Math.floor(raceTime / 60);
  const seconds = Math.floor(raceTime % 60);
  const ms = Math.floor((raceTime % 1) * 1000);
  document.getElementById('go-time').textContent = `Time: ${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}.${String(ms).padStart(3, '0')}`;
  document.getElementById('go-drift').textContent = `Drift Score: ${driftScore}`;

  playSound(880, 0.5, 'sine', 0.1);
  setTimeout(() => playSound(1100, 0.5, 'sine', 0.1), 200);
}

