}
.aircraft-card:hover, .aircraft-card.selected { border-color: #e94560; transform: translateY(-5px); }
.aircraft-card .icon { font-size: 4em; margin-bottom: 10px; }
.aircraft-card .name { color: #fff; font-size: 1.2em; font-weight: bold; }
.aircraft-card .stats { color: #aaa; font-size: 0.9em; margin-top: 8px; }
.aircraft-card .locked { opacity: 0.5; }

/* HUD */
#hud {
  position: fixed; top: 0; left: 0; width: 100%; padding: 15px 20px;
  display: none; z-index: 50; pointer-events: none;
}
#hud.active { display: flex; justify-content: space-between; align-items: flex-start; }
.hud-left, .hud-right, .hud-center { display: flex; flex-direction: column; gap: 5px; }
.hud-center { align-items: center; }
.hud-right { align-items: flex-end; }
.hud-item {
  color: #fff; font-size: 1.1em; text-shadow: 0 2px 4px rgba(0,0,0,0.5);
  background: rgba(0,0,0,0.3); padding: 8px 15px; border-radius: 20px;
  backdrop-filter: blur(5px);
}
.hud-item .label { color: #aaa; font-size: 0.8em; }
.hud-item .value { font-weight: bold; font-size: 1.2em; }

/* Fuel Bar */
#fuelBar {
  width: 200px; height: 8px; background: rgba(255,255,255,0.2);
  border-radius: 4px; overflow: hidden; margin-top: 5px;
}
#fuelFill {
  height: 100%; background: linear-gradient(90deg, #e94560, #ff6b6b);
  border-radius: 4px; transition: width 0.3s;
}

/* Power-up indicators */
.powerup-indicator {
  position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%);
  display: flex; gap: 10px; z-index: 50;
}
.powerup-icon {
  width: 50px; height: 50px; border-radius: 10px;
  background: rgba(0,0,0,0.5); border: 2px solid #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5em; color: #fff;
}

/* Game Over */
#gameOver {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: rgba(0,0,0,0.8); display: none; flex-direction: column;
  align-items: center; justify-content: center; z-index: 200;
}
#gameOver.show { display: flex; }
#gameOver h2 { color: #e94560; font-size: 3em; margin-bottom: 10px; }
#gameOver .final-score { color: #fff; font-size: 2em; margin-bottom: 5px; }
#gameOver .stats { color: #aaa; font-size: 1.1em; margin-bottom: 30px; }

/* Swipe hint */
#swipeHint {
  position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%);
  color: rgba(255,255,255,0.6); font-size: 1em; z-index: 50;
  display: none; text-align: center;
}
#swipeHint.active { display: block; }

/* Speed lines effect */
#speedLines {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  pointer-events: none; z-index: 40; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 50%, rgba(255,255,255,0.1) 100%);
}

/* Combo display */
#combo {
  position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);
  color: #ffd700; font-size: 2em; font-weight: bold; z-index: 55;
  display: none; text-shadow: 0 0 20px #ffd700;
  animation: comboAnim 0.5s ease-out;
}
@keyframes comboAnim {
  0% { transform: translate(-50%, -50%) scale(0.5); opacity: 0; }
  50% { transform: translate(-50%, -50%) scale(1.2); opacity: 1; }
  100% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
}

/* Loading */
#loading {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: #1a1a2e; display: flex; align-items: center; justify-content: center;
  z-index: 300; color: #fff; font-size: 1.5em;
}
#loading.hidden { display: none; }
</style>
</head>
<body>

