  <div class="final-score">Score: <span id="finalScore">0</span></div>
  <div class="stats">
    Distance: <span id="finalDistance">0</span>m |
    Max Speed: <span id="finalSpeed">0</span> mph |
    Fuel Collected: <span id="finalFuel">0</span>
  </div>
