<script>
// ============================================================
// SAVE MANAGER - Persistent storage
// ============================================================
const SaveManager = {
  key: 'templeRunner3D_save',
  defaultData() {
    return {
      totalCoins: 0,
      highScore: 0,
      // Power-up upgrades
      upgrades: {
        magnetDuration: 1,
        magnetCooldown: 1,
        jetDuration: 1,
        jetCooldown: 1,
        hoverboardDuration: 1,
        hoverboardCooldown: 1,
      },
      // Passive upgrades
      passives: {
        coinMultiplier: 0,    // 0 = x1, 1 = x2, 2 = x3
        startingSpeed: 0,     // 0 = normal, 1 = faster start
        extraLife: 0,         // not implemented yet
      },
      // Owned skins
      ownedSkins: ['default'],
      equippedSkin: 'default',
      // Skin prices
      skinPrices: {
        default: 0,
        red: 100,
        blue: 200,
        green: 300,
        gold: 500,
        purple: 750,
        rainbow: 1000,
      },
      // Upgrade costs
      upgradeCosts: {
        magnetDuration: 50,
        magnetCooldown: 50,
        jetDuration: 50,
        jetCooldown: 50,
        hoverboardDuration: 50,
        hoverboardCooldown: 50,
      },
      passiveCosts: {
        coinMultiplier: 200,
        startingSpeed: 150,
      },
    };
  },
  load() {
    try {
      const data = localStorage.getItem(this.key);
      if (data) {
        const parsed = JSON.parse(data);
        const def = this.defaultData();
        // Merge to handle new fields
        return this.deepMerge(def, parsed);
      }
    } catch(e) { console.warn('Save load failed:', e); }
    return this.defaultData();
  },
  save(data) {
    try {
      localStorage.setItem(this.key, JSON.stringify(data));
    } catch(e) { console.warn('Save failed:', e); }
  },
  deepMerge(target, source) {
    const result = { ...target };
    for (const key in source) {
      if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
        result[key] = this.deepMerge(target[key] || {}, source[key]);
      } else {
        result[key] = source[key];
      }
    }
    return result;
  }
};

// ============================================================
// CONFIG - Tunable parameters
// ============================================================
const CONFIG = {
  // Lane settings
  laneWidth: 2.5,
  laneCount: 3,
  // Speed
  baseSpeed: 15,
  maxSpeed: 40,
  speedIncrement: 0.5, // per second
  // Jump
  jumpForce: 12,
  gravity: -30,
  // Slide
  slideDuration: 0.8,
  slideHeight: 0.5,
  // Segment
  segmentLength: 20,
  segmentPoolSize: 20,
  // Obstacles
  obstacleSpawnRate: 0.3, // per segment
  obstacleTypes: ['box', 'barrier', 'low_wall', 'moving'],
  // Coins
  coinSpawnRate: 0.5,
  coinValue: 1,
  // Power-ups
  powerupSpawnRate: 0.05,
  powerupTypes: ['magnet', 'jet', 'hoverboard'],
  // Magnet
  magnetRange: 5,
  magnetDurationBase: 5,
  magnetCooldownBase: 15,
  // Jet
  jetDurationBase: 4,
  jetCooldownBase: 20,
  // Hoverboard
  hoverboardDurationBase: 8,
  hoverboardCooldownBase: 25,
  // Chaser
  chaserSpeed: 14,
  chaserCatchDistance: 30,
  // Colors
  colors: {
    ground: '#2d5a27',
    path: '#8B7355',
    pathBorder: '#6B5335',
    obstacle: '#8B4513',
    coin: '#FFD700',
    player: '#4a90d9',
    chaser: '#e74c3c',
  }
};

// ============================================================
// INPUT MANAGER - Desktop keyboard + Mobile swipe
// ============================================================
const InputManager = {
  keys: {},
  touchStartX: 0,
  touchStartY: 0,
  touchStartTime: 0,
  swipeThreshold: 30,

  init() {
    // Keyboard
    window.addEventListener('keydown', (e) => {
      this.keys[e.code] = true;
      this.handleKey(e.code);
    });
    window.addEventListener('keyup', (e) => {
      this.keys[e.code] = false;
    });

    // Touch
    const canvas = document.getElementById('gameCanvas');
    canvas.addEventListener('touchstart', (e) => {
      e.preventDefault();
      const touch = e.touches[0];
      this.touchStartX = touch.clientX;
      this.touchStartY = touch.clientY;
      this.touchStartTime = Date.now();
    }, { passive: false });

    canvas.addEventListener('touchend', (e) => {
      e.preventDefault();
      const touch = e.changedTouches[0];
      const dx = touch.clientX - this.touchStartX;
      const dy = touch.clientY - this.touchStartY;
      const dt = Date.now() - this.touchStartTime;

      if (dt > 500) return; // Too slow

      const absDx = Math.abs(dx);
      const absDy = Math.abs(dy);

      if (absDx < this.swipeThreshold && absDy < this.swipeThreshold) return;

      if (absDx > absDy) {
        // Horizontal swipe
        if (dx > 0) this.handleKey('ArrowRight');
        else this.handleKey('ArrowLeft');
      } else {
        // Vertical swipe
        if (dy < 0) this.handleKey('ArrowUp');
        else this.handleKey('ArrowDown');
      }
    }, { passive: false });
  },

  handleKey(code) {
    if (!Game.running) return;
    switch(code) {
      case 'ArrowLeft':
      case 'KeyA':
        Game.player.switchLane(-1);
        break;
      case 'ArrowRight':
      case 'KeyD':
        Game.player.switchLane(1);
        break;
      case 'ArrowUp':
      case 'KeyW':
      case 'Space':
        Game.player.jump();
        break;
      case 'ArrowDown':
      case 'KeyS':
        Game.player.slide();
        break;
    }
  },

  isLeft() { return this.keys['ArrowLeft'] || this.keys['KeyA']; },
  isRight() { return this.keys['ArrowRight'] || this.keys['KeyD']; },
  isJump() { return this.keys['ArrowUp'] || this.keys['KeyW'] || this.keys['Space']; },
  isSlide() { return this.keys['ArrowDown'] || this.keys['KeyS']; },
};

// ============================================================
// POOL MANAGER - Object pooling for performance
// ============================================================
class PoolManager {
  constructor(createFn, resetFn, initialSize = 20) {
    this.createFn = createFn;
    this.resetFn = resetFn;
    this.pool = [];
    this.active = [];

    for (let i = 0; i < initialSize; i++) {
      const obj = createFn();
      obj.active = false;
      this.pool.push(obj);
    }
  }

  get() {
    let obj = this.pool.find(o => !o.active);
    if (!obj) {
      obj = this.createFn();
      obj.active = false;
      this.pool.push(obj);
    }
    obj.active = true;
    this.resetFn(obj);
    this.active.push(obj);
    return obj;
  }

  release(obj) {
    obj.active = false;
    const idx = this.active.indexOf(obj);
    if (idx > -1) this.active.splice(idx, 1);
  }

  releaseAll() {
    for (const obj of this.active) {
      obj.active = false;
    }
    this.active = [];
  }

  update(dt) {
    for (let i = this.active.length - 1; i >= 0; i--) {
      const obj = this.active[i];
      if (!obj.update(dt)) {
        this.release(obj);
      }
    }
  }
}

// ============================================================
// SEGMENT - Road segment with obstacles, coins, power-ups
// ============================================================
class Segment {
  constructor() {
    this.z = 0;
    this.obstacles = [];
    this.coins = [];
    this.powerups = [];
    this.active = false;
  }

  init(z) {
    this.z = z;
    this.obstacles = [];
    this.coins = [];
    this.powerups = [];
    this.active = true;
  }

  update(dt) {
    // Move towards player
    this.z -= Game.speed * dt;

    // Remove if behind camera
    if (this.z < -CONFIG.segmentLength * 2) {
      this.active = false;
      return false;
    }
    return true;
  }
}

// ============================================================
// OBSTACLE
// ============================================================
class Obstacle {
  constructor() {
    this.x = 0; // lane (-1, 0, 1)
    this.y = 0;
    this.z = 0;
    this.type = 'box';
    this.width = 1.5;
    this.height = 1.5;
    this.depth = 0.5;
    this.active = false;
    this.moveSpeed = 0;
    this.moveRange = 2;
    this.moveOffset = 0;
  }

  init(x, y, z, type) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.type = type;
    this.active = true;
    this.moveSpeed = 0;
    this.moveOffset = 0;

    switch(type) {
      case 'box':
        this.width = 1.2;
        this.height = 1.2;
        this.depth = 1.2;
        break;
      case 'barrier':
        this.width = 2.2;
        this.height = 1.5;
        this.depth = 0.3;
        break;
      case 'low_wall':
        this.width = 2.2;
        this.height = 0.8;
        this.depth = 0.5;
        break;
      case 'moving':
        this.width = 1.2;
        this.height = 1.5;
        this.depth = 1.2;
        this.moveSpeed = 2 + Math.random() * 2;
        this.moveRange = 1.5;
        break;
    }
  }

  update(dt) {
    this.z -= Game.speed * dt;

    if (this.type === 'moving') {
      this.moveOffset += this.moveSpeed * dt;
      if (this.moveOffset > this.moveRange) {
        this.moveSpeed = -Math.abs(this.moveSpeed);
      }
      if (this.moveOffset < -this.moveRange) {
        this.moveSpeed = Math.abs(this.moveSpeed);
      }
    }

    if (this.z < -5) {
      this.active = false;
      return false;
    }
    return true;
  }

  getScreenPos() {
    const relZ = this.z - Game.player.z;
    if (relZ < -10 || relZ > 100) return null;

    const laneX = this.x * CONFIG.laneWidth + (this.type === 'moving' ? this.moveOffset : 0);
    return { x: laneX, y: this.y, z: relZ };
  }

  checkCollision(player) {
    const relZ = this.z - player.z;
    if (relZ < -1 || relZ > 2) return false;

    const playerLane = player.lane;
    const obsLane = this.x;

    if (Math.abs(playerLane - obsLane) > 0.5) return false;

    // Check height
    if (this.type === 'low_wall' && player.isJumping && player.jumpHeight > this.height) {
      return false;
    }

    if (this.type === 'barrier' && player.isSliding) {
      return false;
    }

    return true;
  }
}

// ============================================================
// COIN
// ============================================================
class Coin {
  constructor() {
    this.x = 0;
    this.y = 0.5;
    this.z = 0;
    this.active = false;
    this.collected = false;
    this.rotation = 0;
  }

  init(x, y, z) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.active = true;
    this.collected = false;
    this.rotation = 0;
  }

  update(dt) {
    this.z -= Game.speed * dt;
    this.rotation += dt * 3;

    if (this.z < -5) {
      this.active = false;
      return false;
    }
    return true;
  }

  checkCollision(player) {
    if (this.collected) return false;
    const relZ = this.z - player.z;
    if (relZ < -1 || relZ > 2) return false;

    const dx = Math.abs(this.x - player.lane) * CONFIG.laneWidth;
    const dy = Math.abs(this.y - (player.y + player.jumpHeight));

    // Magnet effect
    if (Game.activePowerups.magnet && Game.magnetTimer > 0) {
      const dist = Math.sqrt(dx * dx + dy * dy + relZ * relZ);
      if (dist < CONFIG.magnetRange) {
        this.x += (player.lane * CONFIG.laneWidth - this.x) * dt * 5;
        this.y += (player.y + 0.5 - this.y) * dt * 5;
      }
    }

    return dx < 0.8 && dy < 1.5;
  }
}

// ============================================================
// POWERUP
// ============================================================
class PowerUp {
  constructor() {
    this.x = 0;
    this.y = 1;
    this.z = 0;
    this.type = 'magnet';
    this.active = false;
    this.rotation = 0;
  }

  init(x, y, z, type) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.type = type;
    this.active = true;
    this.rotation = 0;
  }

  update(dt) {
    this.z -= Game.speed * dt;
    this.rotation += dt * 2;

    if (this.z < -5) {
      this.active = false;
      return false;
    }
    return true;
  }

  checkCollision(player) {
    const relZ = this.z - player.z;
    if (relZ < -1 || relZ > 2) return false;

    const dx = Math.abs(this.x - player.lane) * CONFIG.laneWidth;
    const dy = Math.abs(this.y - (player.y + player.jumpHeight));

    return dx < 0.8 && dy < 2;
  }
}

// ============================================================
// PLAYER
// ============================================================
class Player {
  constructor() {
    this.lane = 0; // -1, 0, 1
    this.targetLane = 0;
    this.x = 0;
    this.y = 0;
    this.z = 0;
    this.jumpHeight = 0;
    this.jumpVelocity = 0;
    this.isJumping = false;
    this.isSliding = false;
    this.slideTimer = 0;
    this.speed = CONFIG.baseSpeed;
    this.skin = 'default';
    this.invincible = false;
    this.invincibleTimer = 0;
  }

  init() {
    this.lane = 0;
    this.targetLane = 0;
    this.x = 0;
    this.y = 0;
    this.z = 0;
    this.jumpHeight = 0;
    this.jumpVelocity = 0;
    this.isJumping = false;
    this.isSliding = false;
    this.slideTimer = 0;
    this.speed = CONFIG.baseSpeed + CONFIG.startingSpeed * 2;
    this.skin = SaveManager.load().equippedSkin || 'default';
    this.invincible = false;
    this.invincibleTimer = 0;
  }

  switchLane(direction) {
    const newLane = this.targetLane + direction;
    if (newLane >= -1 && newLane <= 1) {
      this.targetLane = newLane;
    }
  }

  jump() {
    if (!this.isJumping && !this.isSliding) {
      this.isJumping = true;
      this.jumpVelocity = CONFIG.jumpForce;
    }
  }

  slide() {
    if (!this.isJumping && !this.isSliding) {
      this.isSliding = true;
      this.slideTimer = CONFIG.slideDuration;
    }
  }

  update(dt) {
    // Lane smoothing
    const targetX = this.targetLane * CONFIG.laneWidth;
    this.x += (targetX - this.x) * dt * 10;

    // Jump physics
    if (this.isJumping) {
      this.jumpVelocity += CONFIG.gravity * dt;
      this.jumpHeight += this.jumpVelocity * dt;

      if (this.jumpHeight <= 0) {
        this.jumpHeight = 0;
        this.jumpVelocity = 0;
        this.isJumping = false;
      }
    }

    // Slide timer
    if (this.isSliding) {
      this.slideTimer -= dt;
      if (this.slideTimer <= 0) {
        this.isSliding = false;
      }
    }

    // Invincibility timer
    if (this.invincible) {
      this.invincibleTimer -= dt;
      if (this.invincibleTimer <= 0) {
        this.invincible = false;
      }
    }

    // Speed increase
    this.speed = Math.min(CONFIG.maxSpeed, this.speed + CONFIG.speedIncrement * dt);
  }

  getHitbox() {
    const height = this.isSliding ? CONFIG.slideHeight : 1.8;
    const y = this.isSliding ? 0.3 : this.jumpHeight;
    return {
      x: this.x,
      y: y,
      z: this.z,
      width: 0.8,
      height: height,
      depth: 0.8
    };
  }
}

// ============================================================
// CHASER - The enemy that follows the player
// ============================================================
class Chaser {
  constructor() {
    this.z = -CONFIG.chaserCatchDistance;
    this.x = 0;
    this.y = 0;
    this.active = false;
    this.speed = CONFIG.chaserSpeed;
    this.catchDistance = CONFIG.chaserCatchDistance;
  }

  init() {
    this.z = -this.catchDistance;
    this.x = 0;
    this.y = 0;
    this.active = true;
  }

  update(dt) {
    // Move towards player
    const dist = Game.player.z - this.z;
    if (dist > 0) {
      this.z += this.speed * dt;
    }

    // Check if caught
    if (dist < 2) {
      Game.gameOver();
    }
  }

  draw(ctx, camera) {
    if (!this.active) return;

    const relZ = this.z - Game.player.z;
    if (relZ < -20 || relZ > 50) return;

    const screenPos = this.project(relZ, 0);
    if (!screenPos) return;

    const size = Math.max(20, 100 / (relZ + 5));

    // Draw chaser (red menacing figure)
    ctx.save();
    ctx.translate(screenPos.x, screenPos.y);

    // Body
    ctx.fillStyle = '#e74c3c';
    ctx.beginPath();
    ctx.ellipse(0, 0, size * 0.4, size * 0.6, 0, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(-size * 0.15, -size * 0.2, size * 0.08, 0, Math.PI * 2);
    ctx.arc(size * 0.15, -size * 0.2, size * 0.08, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(-size * 0.15, -size * 0.2, size * 0.04, 0, Math.PI * 2);
    ctx.arc(size * 0.15, -size * 0.2, size * 0.04, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  project(relZ, laneX) {
    const fov = 500;
    const scale = fov / (fov + relZ * 50);
    const screenX = window.innerWidth / 2 + laneX * CONFIG.laneWidth * scale * 100;
    const screenY = window.innerHeight / 2 + 100 * scale;
    return { x: screenX, y: screenY, scale };
  }
}

// ============================================================
// GAME MANAGER - Main game logic
// ============================================================
const Game = {
  canvas: null,
  ctx: null,
  running: false,
  score: 0,
  coins: 0,
  speed: CONFIG.baseSpeed,
  player: null,
  chaser: null,
  segments: [],
  segmentPool: null,
  obstaclePool: null,
  coinPool: null,
  powerupPool: null,
  activePowerups: {},
  magnetTimer: 0,
  jetTimer: 0,
  hoverboardTimer: 0,
  lastTime: 0,
  spawnTimer: 0,
  segmentZ: 0,
  saveData: null,
  animFrame: null,

  init() {
    this.canvas = document.getElementById('gameCanvas');
    this.ctx = this.canvas.getContext('2d');
    this.resize();
    window.addEventListener('resize', () => this.resize());

    InputManager.init();
    this.saveData = SaveManager.load();

    this.player = new Player();
    this.chaser = new Chaser();

    // Setup pools
    this.segmentPool = new PoolManager(
      () => new Segment(),
      (obj) => { obj.init(0); },
      CONFIG.segmentPoolSize
    );

    this.obstaclePool = new PoolManager(
      () => new Obstacle(),
      (obj) => { obj.active = false; },
      30
    );

    this.coinPool = new PoolManager(
      () => new Coin(),
      (obj) => { obj.active = false; },
      50
    );

    this.powerupPool = new PoolManager(
      () => new PowerUp(),
      (obj) => { obj.active = false; },
      10
    );

    this.showScreen('start-screen');
  },

  resize() {
    this.canvas.width = window.innerWidth;
    this.canvas.height = window.innerHeight;
  },

  showScreen(id) {
    document.querySelectorAll('.screen').forEach(s => s.classList.add('hidden'));
    if (id) document.getElementById(id).classList.remove('hidden');
    document.getElementById('hud').classList.toggle('hidden', id !== null);
  },

  start() {
    this.saveData = SaveManager.load();
    this.player.init();
    this.chaser.init();

    this.score = 0;
    this.coins = 0;
    this.speed = CONFIG.baseSpeed + this.saveData.passives.startingSpeed * 2;
    this.segmentZ = 0;
    this.spawnTimer = 0;
    this.activePowerups = {};
    this.magnetTimer = 0;
    this.jetTimer = 0;
    this.hoverboardTimer = 0;

    // Clear pools
    this.obstaclePool.releaseAll();
    this.coinPool.releaseAll();
    this.powerupPool.releaseAll();
    this.segmentPool.releaseAll();

    // Initial segments
    for (let i = 0; i < 10; i++) {
      const seg = this.segmentPool.get();
      seg.init(this.segmentZ + i * CONFIG.segmentLength);
      this.segments.push(seg);
      this.generateSegmentContent(seg);
    }

    this.running = true;
    this.showScreen(null);
    this.lastTime = performance.now();

    if (this.animFrame) cancelAnimationFrame(this.animFrame);
    this.gameLoop();
  },

  generateSegmentContent(segment) {
    const z = segment.z;

    // Obstacles
    if (Math.random() < CONFIG.obstacleSpawnRate) {
      const lane = Math.floor(Math.random() * 3) - 1;
      const type = CONFIG.obstacleTypes[Math.floor(Math.random() * CONFIG.obstacleTypes.length)];
      const obs = this.obstaclePool.get();
      obs.init(lane, 0, z + CONFIG.segmentLength / 2, type);
      segment.obstacles.push(obs);
    }

    // Multiple obstacles possible
    if (Math.random() < 0.3) {
      const lane = Math.floor(Math.random() * 3) - 1;
      const type = CONFIG.obstacleTypes[Math.floor(Math.random() * CONFIG.obstacleTypes.length)];
      const obs = this.obstaclePool.get();
      obs.init(lane, 0, z + CONFIG.segmentLength * 0.75, type);
      segment.obstacles.push(obs);
    }

    // Coins
    if (Math.random() < CONFIG.coinSpawnRate) {
      const lane = Math.floor(Math.random() * 3) - 1;
      const count = 3 + Math.floor(Math.random() * 5);
      for (let i = 0; i < count; i++) {
        const coin = this.coinPool.get();
        coin.init(lane, 0.5, z + i * 2);
        segment.coins.push(coin);
      }
    }

    // Power-ups
    if (Math.random() < CONFIG.powerupSpawnRate) {
      const lane = Math.floor(Math.random() * 3) - 1;
      const type = CONFIG.powerupTypes[Math.floor(Math.random() * CONFIG.powerupTypes.length)];
      const pu = this.powerupPool.get();
      pu.init(lane, 1, z + CONFIG.segmentLength / 2, type);
      segment.powerups.push(pu);
    }
  },

  gameLoop() {
    if (!this.running) return;

    const now = performance.now();
    const dt = Math.min((now - this.lastTime) / 1000, 0.05);
    this.lastTime = now;

    this.update(dt);
    this.render();

    this.animFrame = requestAnimationFrame(() => this.gameLoop());
  },

  update(dt) {
    // Update player
    this.player.update(dt);

    // Update chaser
    this.chaser.update(dt);

    // Update segments
    for (let i = this.segments.length - 1; i >= 0; i--) {
      const seg = this.segments[i];
      if (!seg.update(dt)) {
        this.segments.splice(i, 1);
        this.segmentPool.release(seg);
      }
    }

    // Spawn new segments
    const frontSegment = this.segments[this.segments.length - 1];
    if (frontSegment && frontSegment.z > this.player.z - CONFIG.segmentLength * 5) {
      this.segmentZ += CONFIG.segmentLength;
      const seg = this.segmentPool.get();
      seg.init(this.segmentZ);
      this.segments.push(seg);
      this.generateSegmentContent(seg);
    }

    // Update obstacles
    for (const seg of this.segments) {
      for (const obs of seg.obstacles) {
        if (!obs.update(dt)) {
          this.obstaclePool.release(obs);
        }
      }
    }

    // Update coins
    for (const seg of this.segments) {
      for (const coin of seg.coins) {
        if (!coin.update(dt)) {
          this.coinPool.release(coin);
        }
      }
    }

    // Update power-ups
    for (const seg of this.segments) {
      for (const pu of seg.powerups) {
        if (!pu.update(dt)) {
          this.powerupPool.release(pu);
        }
      }
    }

    // Collision detection
    this.checkCollisions();

    // Update power-up timers
    if (this.magnetTimer > 0) {
      this.magnetTimer -= dt;
      if (this.magnetTimer <= 0) {
        this.activePowerups.magnet = false;
      }
    }
    if (this.jetTimer > 0) {
      this.jetTimer -= dt;
      if (this.jetTimer <= 0) {
        this.activePowerups.jet = false;
      }
    }
    if (this.hoverboardTimer > 0) {
      this.hoverboardTimer -= dt;
      if (this.hoverboardTimer <= 0) {
        this.activePowerups.hoverboard = false;
      }
    }

    // Update score
    this.score += this.speed * dt * 10;

    // Update HUD
    document.getElementById('hud-score').textContent = Math.floor(this.score);
    document.getElementById('hud-coins').textContent = this.coins;
    this.updatePowerupUI();
  },

  checkCollisions() {
    const playerHB = this.player.getHitbox();

    // Obstacle collisions
    for (const seg of this.segments) {
      for (const obs of seg.obstacles) {
        if (obs.checkCollision(this.player)) {
          if (!this.player.invincible && !this.activePowerups.hoverboard) {
            this.gameOver();
            return;
          } else if (this.activePowerups.hoverboard) {
            // Hoverboard absorbs one hit
            this.activePowerups.hoverboard = false;
            this.hoverboardTimer = 0;
            this.player.invincible = true;
            this.player.invincibleTimer = 1;
            this.obstaclePool.release(obs);
          }
        }
      }
    }

    // Coin collisions
    for (const seg of this.segments) {
      for (const coin of seg.coins) {
        if (coin.checkCollision(this.player)) {
          coin.collected = true;
          this.coinPool.release(coin);
          const multiplier = 1 + this.saveData.passives.coinMultiplier;
          this.coins += CONFIG.coinValue * multiplier;
        }
      }
    }

    // Power-up collisions
    for (const seg of this.segments) {
      for (const pu of seg.powerups) {
        if (pu.checkCollision(this.player)) {
          this.activatePowerup(pu.type);
          this.powerupPool.release(pu);
        }
      }
    }
  },

  activatePowerup(type) {
    const data = this.saveData;
    switch(type) {
      case 'magnet':
        this.activePowerups.magnet = true;
        this.magnetTimer = CONFIG.magnetDurationBase + data.upgrades.magnetDuration * 2;
        break;
      case 'jet':
        this.activePowerups.jet = true;
        this.jetTimer = CONFIG.jetDurationBase + data.upgrades.jetDuration * 2;
        this.player.isJumping = true;
        this.player.jumpVelocity = 15;
        break;
      case 'hoverboard':
        this.activePowerups.hoverboard = true;
        this.hoverboardTimer = CONFIG.hoverboardDurationBase + data.upgrades.hoverboardDuration * 2;
        this.player.invincible = true;
        this.player.invincibleTimer = this.hoverboardTimer;
        break;
    }
  },

  updatePowerupUI() {
    const bar = document.getElementById('powerup-bar');
    bar.innerHTML = '';

    if (this.activePowerups.magnet && this.magnetTimer > 0) {
      bar.innerHTML += this.createPowerupIcon('🧲', this.magnetTimer, CONFIG.magnetDurationBase + this.saveData.upgrades.magnetDuration * 2, '#ff6b6b');
    }
    if (this.activePowerups.jet && this.jetTimer > 0) {
      bar.innerHTML += this.createPowerupIcon('🚀', this.jetTimer, CONFIG.jetDurationBase + this.saveData.upgrades.jetDuration * 2, '#4ecdc4');
    }
    if (this.activePowerups.hoverboard && this.hoverboardTimer > 0) {
      bar.innerHTML += this.createPowerupIcon('🛹', this.hoverboardTimer, CONFIG.hoverboardDurationBase + this.saveData.upgrades.hoverboardDuration * 2, '#a29bfe');
    }
  },

  createPowerupIcon(emoji, time, maxTime, color) {
    const pct = Math.max(0, (time / maxTime) * 100);
    return `<div class="powerup-icon" style="background:${color}33;">
      ${emoji}
      <div class="timer-bar" style="width:${pct}%;background:${color};"></div>
    </div>`;
  },

  render() {
    const ctx = this.ctx;
    const W = this.canvas.width;
    const H = this.canvas.height;

    // Clear
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, W, H);

    // Draw sky gradient
    const skyGrad = ctx.createLinearGradient(0, 0, 0, H * 0.5);
    skyGrad.addColorStop(0, '#0f0c29');
    skyGrad.addColorStop(0.5, '#302b63');
    skyGrad.addColorStop(1, '#24243e');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, W, H * 0.5);

    // Draw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 50; i++) {
      const sx = (i * 137.5 + this.player.z * 0.1) % W;
      const sy = (i * 97.3) % (H * 0.4);
      const size = (i % 3) + 1;
      ctx.globalAlpha = 0.3 + (i % 5) * 0.1;
      ctx.fillRect(sx, sy, size, size);
    }
    ctx.globalAlpha = 1;

    // Draw ground
    const groundGrad = ctx.createLinearGradient(0, H * 0.5, 0, H);
    groundGrad.addColorStop(0, '#2d5a27');
    groundGrad.addColorStop(1, '#1a3a15');
    ctx.fillStyle = groundGrad;
    ctx.fillRect(0, H * 0.5, W, H * 0.5);

    // Draw road segments
    this.drawRoad(ctx, W, H);

    // Draw coins
    this.drawCoins(ctx, W, H);

    // Draw obstacles
    this.drawObstacles(ctx, W, H);

    // Draw power-ups
    this.drawPowerups(ctx, W, H);

    // Draw player
    this.drawPlayer(ctx, W, H);

    // Draw chaser
    this.chaser.draw(ctx, this);

    // Draw speed lines effect
    this.drawSpeedLines(ctx, W, H);
  },

  drawRoad(ctx, W, H) {
    const horizonY = H * 0.5;

    for (const seg of this.segments) {
      const relZ = seg.z - this.player.z;
      if (relZ < -5 || relZ > 100) continue;

      const fov = 500;
      const scale = fov / (fov + relZ * 50);
      const screenY = horizonY + 100 * scale;
      const screenH = CONFIG.segmentLength * scale * 50;

      if (screenY < horizonY || screenY > H) continue;

      // Road
      const roadWidth = CONFIG.laneWidth * 2 * scale * 100;
      const roadX = W / 2 - roadWidth / 2;

      // Ground between lanes
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(roadX, screenY, roadWidth, Math.max(1, screenH));

      // Lane borders
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = Math.max(1, 2 * scale);
      ctx.setLineDash([10 * scale, 10 * scale]);

      for (let l = -1; l <= 1; l++) {
        const laneX = W / 2 + l * CONFIG.laneWidth * scale * 100;
        ctx.beginPath();
        ctx.moveTo(laneX, screenY);
        ctx.lineTo(laneX, screenY + screenH);
        ctx.stroke();
      }

      ctx.setLineDash([]);

      // Road edges
      ctx.strokeStyle = '#ffd700';
      ctx.lineWidth = Math.max(1, 3 * scale);
      ctx.beginPath();
      ctx.moveTo(W / 2 - roadWidth / 2, screenY);
      ctx.lineTo(W / 2 - roadWidth / 2, screenY + screenH);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(W / 2 + roadWidth / 2, screenY);
      ctx.lineTo(W / 2 + roadWidth / 2, screenY + screenH);
      ctx.stroke();
    }
  },

  drawPlayer(ctx, W, H) {
    const relZ = 0; // Player is at z=0 relative to camera
    const fov = 500;
    const scale = fov / (fov + relZ * 50);
    const screenX = W / 2 + this.player.x * scale * 100;
    const screenY = H * 0.5 + 100 * scale - this.player.jumpHeight * scale * 50;

    const size = Math.max(20, 60 * scale);

    ctx.save();
    ctx.translate(screenX, screenY);

    // Skin color
    const skinColors = {
      default: '#4a90d9',
      red: '#e74c3c',
      blue: '#3498db',
      green: '#2ecc71',
      gold: '#f39c12',
      purple: '#9b59b6',
      rainbow: '#ff6b6b',
    };
    const color = skinColors[this.player.skin] || skinColors.default;

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(0, size * 0.8, size * 0.4, size * 0.1, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(-size * 0.3, -size * 0.5, size * 0.6, size * 0.8, 5);
    ctx.fill();

    // Head
    ctx.fillStyle = '#fdbf60';
    ctx.beginPath();
    ctx.arc(0, -size * 0.6, size * 0.25, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(-size * 0.08, -size * 0.65, size * 0.04, 0, Math.PI * 2);
    ctx.arc(size * 0.08, -size * 0.65, size * 0.04, 0, Math.PI * 2);
    ctx.fill();

    // Legs animation
    const legAnim = Math.sin(this.score * 0.01) * size * 0.15;
    ctx.fillStyle = color;
    ctx.fillRect(-size * 0.2, size * 0.3, size * 0.15, size * 0.3 + legAnim);
    ctx.fillRect(size * 0.05, size * 0.3, size * 0.15, size * 0.3 - legAnim);

    // Jet effect
    if (this.activePowerups.jet) {
      ctx.fillStyle = '#ff6b6b';
      ctx.beginPath();
      ctx.moveTo(-size * 0.15, size * 0.5);
      ctx.lineTo(0, size * 0.8 + Math.random() * size * 0.3);
      ctx.lineTo(size * 0.15, size * 0.5);
      ctx.fill();
    }

    // Hoverboard effect
    if (this.activePowerups.hoverboard) {
      ctx.fillStyle = '#a29bfe';
      ctx.beginPath();
      ctx.ellipse(0, size * 0.5, size * 0.5, size * 0.1, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2;
      ctx.stroke();
    }

    // Magnet effect
    if (this.activePowerups.magnet && this.magnetTimer > 0) {
      ctx.strokeStyle = 'rgba(255,107,107,0.5)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, CONFIG.magnetRange * scale * 50, 0, Math.PI * 2);
      ctx.stroke();
    }

    ctx.restore();
  },

  drawObstacles(ctx, W, H) {
    for (const seg of this.segments) {
      for (const obs of seg.obstacles) {
        const relZ = obs.z - this.player.z;
        if (relZ < -5 || relZ > 100) continue;

        const fov = 500;
        const scale = fov / (fov + relZ * 50);
        const screenX = W / 2 + (obs.x * CONFIG.laneWidth + (obs.type === 'moving' ? obs.moveOffset : 0)) * scale * 100;
        const screenY = H * 0.5 + 100 * scale;

        const size = Math.max(10, obs.width * scale * 100);
        const height = obs.height * scale * 100;

        ctx.save();
        ctx.translate(screenX, screenY);

        // Shadow
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.beginPath();
        ctx.ellipse(0, size * 0.3, size * 0.5, size * 0.1, 0, 0, Math.PI * 2);
        ctx.fill();

        // Obstacle body
        switch(obs.type) {
          case 'box':
            ctx.fillStyle = '#8B4513';
            ctx.fillRect(-size * 0.4, -height, size * 0.8, height);
            ctx.strokeStyle = '#654321';
            ctx.lineWidth = 2;
            ctx.strokeRect(-size * 0.4, -height, size * 0.8, height);
            // X mark
            ctx.strokeStyle = '#ffd700';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(-size * 0.2, -height * 0.7);
            ctx.lineTo(size * 0.2, -height * 0.3);
            ctx.moveTo(size * 0.2, -height * 0.7);
            ctx.lineTo(-size * 0.2, -height * 0.3);
            ctx.stroke();
            break;
          case 'barrier':
            ctx.fillStyle = '#e74c3c';
            ctx.fillRect(-size * 0.5, -height * 0.5, size, height * 0.5);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 5]);
            ctx.strokeRect(-size * 0.5, -height * 0.5, size, height * 0.5);
            ctx.setLineDash([]);
            break;
          case 'low_wall':
            ctx.fillStyle = '#666';
            ctx.fillRect(-size * 0.5, -height * 0.5, size, height * 0.5);
            ctx.strokeStyle = '#444';
            ctx.lineWidth = 1;
            ctx.strokeRect(-size * 0.5, -height * 0.5, size, height * 0.5);
            break;
          case 'moving':
            ctx.fillStyle = '#9b59b6';
            ctx.fillRect(-size * 0.4, -height, size * 0.8, height);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.strokeRect(-size * 0.4, -height, size * 0.8, height);
            // Arrow indicators
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(0, -height * 0.8);
            ctx.lineTo(-size * 0.15, -height * 0.6);
            ctx.lineTo(size * 0.15, -height * 0.6);
            ctx.fill();
            break;
        }

        ctx.restore();
      }
    }
  },

  drawCoins(ctx, W, H) {
    for (const seg of this.segments) {
      for (const coin of seg.coins) {
        if (coin.collected) continue;
        const relZ = coin.z - this.player.z;
        if (relZ < -5 || relZ > 100) continue;

        const fov = 500;
        const scale = fov / (fov + relZ * 50);
        const screenX = W / 2 + coin.x * CONFIG.laneWidth * scale * 100;
        const screenY = H * 0.5 + 100 * scale - coin.y * scale * 50;

        const size = Math.max(5, 15 * scale);

        ctx.save();
        ctx.translate(screenX, screenY);
        ctx.rotate(coin.rotation);

        // Coin body
        ctx.fillStyle = '#FFD700';
        ctx.beginPath();
        ctx.arc(0, 0, size, 0, Math.PI * 2);
        ctx.fill();

        // Coin shine
        ctx.fillStyle = '#FFF8DC';
        ctx.beginPath();
        ctx.arc(-size * 0.2, -size * 0.2, size * 0.3, 0, Math.PI * 2);
        ctx.fill();

        // $ symbol
        ctx.fillStyle = '#B8860B';
        ctx.font = `bold ${size}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('$', 0, 0);

        ctx.restore();
      }
    }
  },

  drawPowerups(ctx, W, H) {
    for (const seg of this.segments) {
      for (const pu of seg.powerups) {
        const relZ = pu.z - this.player.z;
        if (relZ < -5 || relZ > 100) continue;

        const fov = 500;
        const scale = fov / (fov + relZ * 50);
        const screenX = W / 2 + pu.x * CONFIG.laneWidth * scale * 100;
        const screenY = H * 0.5 + 100 * scale - pu.y * scale * 50;

        const size = Math.max(10, 25 * scale);

        ctx.save();
        ctx.translate(screenX, screenY);
        ctx.rotate(pu.rotation);

        // Glow
        const glowColors = {
          magnet: 'rgba(255,107,107,0.3)',
          jet: 'rgba(78,205,196,0.3)',
          hoverboard: 'rgba(162,155,254,0.3)',
        };
        ctx.fillStyle = glowColors[pu.type] || 'rgba(255,255,255,0.3)';
        ctx.beginPath();
        ctx.arc(0, 0, size * 1.5, 0, Math.PI * 2);
        ctx.fill();

        // Power-up body
        const colors = {
          magnet: '#ff6b6b',
          jet: '#4ecdc4',
          hoverboard: '#a29bfe',
        };
        ctx.fillStyle = colors[pu.type] || '#fff';
        ctx.beginPath();
        ctx.arc(0, 0, size, 0, Math.PI * 2);
        ctx.fill();

        // Icon
        ctx.fillStyle = '#fff';
        ctx.font = `bold ${size}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        const icons = { magnet: '🧲', jet: '🚀', hoverboard: '🛹' };
        ctx.fillText(icons[pu.type] || '★', 0, 0);

        ctx.restore();
      }
    }
  },

  drawSpeedLines(ctx, W, H) {
    const speed = this.speed / CONFIG.maxSpeed;
    const numLines = Math.floor(speed * 20);

    ctx.strokeStyle = `rgba(255,255,255,${speed * 0.2})`;
    ctx.lineWidth = 1;

    for (let i = 0; i < numLines; i++) {
      const x = Math.random() * W;
      const y = H * 0.5 + Math.random() * H * 0.5;
      const len = 20 + speed * 40;

      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x, y + len);
      ctx.stroke();
    }
  },

  gameOver() {
    this.running = false;

    // Save data
    this.saveData = SaveManager.load();
    this.saveData.totalCoins += this.coins;
    this.saveData.highScore = Math.max(this.saveData.highScore, Math.floor(this.score));
    SaveManager.save(this.saveData);

    // Show game over screen
    document.getElementById('final-score').textContent = Math.floor(this.score);
    document.getElementById('final-coins').textContent = `+${this.coins} 🪙`;
    this.showScreen('gameover-screen');
  },

  openShop() {
    this.showScreen('shop-screen');
    Shop.render();
  },

  toMenu() {
    this.running = false;
    if (this.animFrame) cancelAnimationFrame(this.animFrame);
    this.showScreen('start-screen');
  }
};

