  buyUpgrade(key, cost) {
    const data = SaveManager.load();
    if (data.totalCoins < cost) return;
    if (data.upgrades[key] >= 10) return;

    data.totalCoins -= cost;
    data.upgrades[key]++;
    data.upgradeCosts[key] = Math.floor(data.upgradeCosts[key] * 1.5);
    SaveManager.save(data);
    this.render();
  },

