    if (data.totalCoins < cost) return;
    if (data.passives[key] >= 2) return;

    data.totalCoins -= cost;
    data.passives[key]++;
    data.passiveCosts[key] = Math.floor(data.passiveCosts[key] * 2);
    SaveManager.save(data);
    this.render();
  },

  buyOrEquipSkin(skinId, price) {
    const data = SaveManager.load();

    if (data.ownedSkins.includes(skinId)) {
      // Equip
      data.equippedSkin = skinId;
      SaveManager.save(data);
      this.render();
    } else {
      // Buy
      if (data.totalCoins < price) return;

      data.totalCoins -= price;
      data.ownedSkins.push(skinId);
      data.equippedSkin = skinId;
      SaveManager.save(data);
      this.render();
    }
  }
};

