                if (Math.random() < 0.05 && y > height) world[x][y] = 6; // coal
                if (Math.random() < 0.03 && y > height + 3) world[x][y] = 7; // iron
                if (Math.random() < 0.01 && y > height + 8) world[x][y] = 8; // gold
                if (Math.random() < 0.005 && y > height + 15) world[x][y] = 9; // diamond
            } else {
                world[x][y] = 16; // bedrock
            }
        }

        // Trees
        if (x > 5 && x < WORLD_W - 5 && Math.random() < 0.08 && world[x][height - 5] === 2) {
            let treeHeight = 4 + Math.floor(Math.random() * 4);
            for (let ty = 0; ty < treeHeight; ty++) {
                if (height - 6 - ty >= 0) world[x][height - 6 - ty] = 4;
            }
            // Leaves
            for (let lx = -2; lx <= 2; lx++) {
                for (let ly = -3; ly <= -1; ly++) {
                    let wx = x + lx, wy = height - 6 - treeHeight + ly;
                    if (wx >= 0 && wx < WORLD_W && wy >= 0 && wy < WORLD_H && world[wx][wy] === 0) {
                        if (Math.abs(lx) < 2 || Math.abs(ly) < 2) {
                            world[wx][wy] = 5;
                        }
                    }
                }
            }
        }

        // Caves
        if (Math.random() < 0.02) {
            let cx = x, cy = height + 5 + Math.floor(Math.random() * 10);
            let caveSize = 2 + Math.floor(Math.random() * 3);
            for (let dx = -caveSize; dx <= caveSize; dx++) {
                for (let dy = -caveSize; dy <= caveSize; dy++) {
                    let wx = cx + dx, wy = cy + dy;
                    if (wx >= 0 && wx < WORLD_W && wy >= 0 && wy < WORLD_H) {
                        if (dx * dx + dy * dy < caveSize * caveSize) {
                            world[wx][wy] = 0;
                        }
                    }
                }
            }
        }
    }

    // Find spawn point
    let spawnX = Math.floor(WORLD_W / 2);
    let spawnY = 0;
    for (let y = 0; y < WORLD_H; y++) {
        if (world[spawnX][y] !== 0) {
            spawnY = y - 2;
            break;
        }
    }
    player.x = spawnX * TILE;
    player.y = spawnY * TILE;
}

// Initialize inventory
function initInventory() {
    player.inventory = [];
    player.hotbar = [];
    for (let i = 0; i < 40; i++) player.inventory.push(null);
    for (let i = 0; i < 9; i++) player.hotbar.push(null);

    // Starting items
    addItemToHotbar(20); // Wooden sword
    addItemToHotbar(30); // Wooden pickaxe
    addItemToHotbar(14, 10); // Torches
    addItemToHotbar(1, 20); // Dirt
    addItemToHotbar(40, 3); // Health potions
}

function addItemToHotbar(itemId, count = 1) {
    for (let i = 0; i < 9; i++) {
        if (player.hotbar[i] && player.hotbar[i].id === itemId) {
            player.hotbar[i].count += count;
            return true;
        }
    }
    for (let i = 0; i < 9; i++) {
        if (!player.hotbar[i]) {
            player.hotbar[i] = { id: itemId, count: count };
            return true;
        }
    }
    // Try inventory
    for (let i = 0; i < 40; i++) {
        if (!player.inventory[i]) {
            player.inventory[i] = { id: itemId, count: count };
            return true;
        }
    }
    return false;
}

function removeItemFromHotbar(slot, count = 1) {
    if (player.hotbar[slot]) {
        player.hotbar[slot].count -= count;
        if (player.hotbar[slot].count <= 0) {
            player.hotbar[slot] = null;
        }
        return true;
    }
    return false;
}

function removeItemFromInventory(itemId, count = 1) {
    let remaining = count;
    for (let i = 0; i < player.inventory.length; i++) {
        if (player.inventory[i] && player.inventory[i].id === itemId) {
            let remove = Math.min(player.inventory[i].count, remaining);
            player.inventory[i].count -= remove;
            remaining -= remove;
            if (player.inventory[i].count <= 0) player.inventory[i] = null;
            if (remaining <= 0) return true;
        }
    }
    return remaining <= 0;
}

function countItem(itemId) {
    let total = 0;
    for (let i = 0; i < player.inventory.length; i++) {
        if (player.inventory[i] && player.inventory[i].id === itemId) {
            total += player.inventory[i].count;
        }
    }
    for (let i = 0; i < player.hotbar.length; i++) {
        if (player.hotbar[i] && player.hotbar[i].id === itemId) {
            total += player.hotbar[i].count;
        }
    }
    return total;
}

// Spawn enemies
function spawnEnemies() {
    if (enemies.length < 15) {
        let ex = player.x + (Math.random() - 0.5) * 800;
        let ey = 0;
        let tileX = Math.floor(ex / TILE);
        if (tileX >= 0 && tileX < WORLD_W) {
            for (let y = 0; y < WORLD_H; y++) {
                if (world[tileX][y] !== 0) {
                    ey = (y - 1) * TILE;
                    break;
                }
            }
        }

        let type = Math.random();
        let enemy;
        if (type < 0.4) {
            enemy = { type: 'slime', x: ex, y: ey, w: 16, h: 12, vx: 0, vy: 0, hp: 20 + player.level * 5, maxHp: 20 + player.level * 5, damage: 5 + player.level, xp: 10, animFrame: 0, animTimer: 0, attackCooldown: 0 };
        } else if (type < 0.7) {
            enemy = { type: 'skeleton', x: ex, y: ey, w: 12, h: 24, vx: 0, vy: 0, hp: 40 + player.level * 8, maxHp: 40 + player.level * 8, damage: 10 + player.level * 2, xp: 25, animFrame: 0, animTimer: 0, attackCooldown: 0 };
        } else {
            enemy = { type: 'zombie', x: ex, y: ey, w: 12, h: 24, vx: 0, vy: 0, hp: 30 + player.level * 6, maxHp: 30 + player.level * 6, damage: 8 + player.level, xp: 15, animFrame: 0, animTimer: 0, attackCooldown: 0 };
        }
        enemies.push(enemy);
    }
}

// Particle system
function addParticle(x, y, color, count = 5) {
    for (let i = 0; i < count; i++) {
        particles.push({
            x: x, y: y,
            vx: (Math.random() - 0.5) * 4,
            vy: (Math.random() - 0.5) * 4 - 2,
            life: 30 + Math.random() * 20,
            color: color,
            size: 2 + Math.random() * 2
        });
    }
}

function addDamageNumber(x, y, damage, color = '#fff') {
    particles.push({
        x: x, y: y,
        vx: 0, vy: -2,
        life: 40,
        color: color,
        size: 0,
        text: '-' + damage,
        isText: true
    });
}

// Collision detection
function isSolid(tx, ty) {
    if (tx < 0 || tx >= WORLD_W || ty < 0 || ty >= WORLD_H) return ty >= WORLD_H;
    let block = world[tx][ty];
    return BLOCKS[block] && BLOCKS[block].solid;
}

function getBlock(tx, ty) {
    if (tx < 0 || tx >= WORLD_W || ty < 0 || ty >= WORLD_H) return 16;
    return world[tx][ty];
}

function setBlock(tx, ty, block) {
    if (tx >= 0 && tx < WORLD_W && ty >= 0 && ty < WORLD_H) {
        world[tx][ty] = block;
    }
}

function rectCollision(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

// Update player
function updatePlayer() {
    // Movement
    let moveX = 0;
    if (keys['ArrowLeft'] || keys['KeyA']) { moveX = -1; player.facing = -1; }
    if (keys['ArrowRight'] || keys['KeyD']) { moveX = 1; player.facing = 1; }

    player.vx = moveX * PLAYER_SPEED;

    // Jump
    if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.onGround) {
        player.vy = JUMP_FORCE;
        player.onGround = false;
    }

    // Gravity
    player.vy += GRAVITY;
    if (player.vy > 12) player.vy = 12;

    // Move X
    player.x += player.vx;
    let tileLeft = Math.floor(player.x / TILE);
    let tileRight = Math.floor((player.x + player.w) / TILE);
    let tileTop = Math.floor(player.y / TILE);
    let tileBottom = Math.floor((player.y + player.h) / TILE);

    for (let ty = tileTop; ty <= tileBottom; ty++) {
        if (player.vx > 0 && isSolid(tileRight, ty)) {
            player.x = tileRight * TILE - player.w;
            player.vx = 0;
        } else if (player.vx < 0 && isSolid(tileLeft, ty)) {
            player.x = (tileLeft + 1) * TILE;
            player.vx = 0;
        }
    }

    // Move Y
    player.y += player.vy;
    tileLeft = Math.floor(player.x / TILE);
    tileRight = Math.floor((player.x + player.w) / TILE);
    tileTop = Math.floor(player.y / TILE);
    tileBottom = Math.floor((player.y + player.h) / TILE);

    player.onGround = false;
    for (let tx = tileLeft; tx <= tileRight; tx++) {
        if (player.vy > 0 && isSolid(tx, tileBottom)) {
            player.y = tileBottom * TILE - player.h;
            player.vy = 0;
            player.onGround = true;
        } else if (player.vy < 0 && isSolid(tx, tileTop)) {
            player.y = (tileTop + 1) * TILE;
            player.vy = 0;
        }
    }

    // World bounds
    if (player.x < 0) player.x = 0;
    if (player.x > (WORLD_W - 1) * TILE) player.x = (WORLD_W - 1) * TILE;
    if (player.y > WORLD_H * TILE) {
        player.y = 0;
        player.hp -= 20;
    }

    // Animation
    player.animTimer++;
    if (player.animTimer > 8) {
        player.animTimer = 0;
        player.animFrame = (player.animFrame + 1) % 4;
    }

    // Attack cooldown
    if (player.attackCooldown > 0) player.attackCooldown--;
    if (player.invincible > 0) player.invincible--;

    // Mining
    if (mouse.left) {
        let mx = mouse.x + camera.x;
        let my = mouse.y + camera.y;
        let tx = Math.floor(mx / TILE);
        let ty = Math.floor(my / TILE);

        let dist = Math.sqrt((mx - (player.x + player.w / 2)) ** 2 + (my - (player.y + player.h / 2)) ** 2);
        if (dist < 100 && tx >= 0 && tx < WORLD_W && ty >= 0 && ty < WORLD_H) {
            let block = world[tx][ty];
            if (block !== 0 && block !== 16) {
                let item = ITEMS[block];
                if (item && item.type === 'block') {
                    player.mining = true;
                    player.miningTarget = { x: tx, y: ty };
                    player.miningProgress += 0.05;

                    if (player.miningProgress >= 1) {
                        setBlock(tx, ty, 0);
                        addItemToHotbar(block);
                        addParticle(mx, my, BLOCKS[block].color, 8);
                        player.mining = false;
                        player.miningTarget = null;
                        player.miningProgress = 0;
                    }
                }
            }
        }
    } else {
        player.mining = false;
        player.miningTarget = null;
        player.miningProgress = 0;
    }

    // Attacking
    if (mouse.right && player.attackCooldown <= 0) {
        let heldItem = player.hotbar[player.selectedSlot];
        if (heldItem) {
            let item = ITEMS[heldItem.id];
            if (item && item.type === 'weapon') {
                player.attackCooldown = Math.floor(20 / item.speed);
                let ax = player.x + player.w / 2 + player.facing * 20;
                let ay = player.y + player.h / 2;

                // Check enemy hits
                for (let e of enemies) {
                    let dist = Math.sqrt((ax - (e.x + e.w / 2)) ** 2 + (ay - (e.y + e.h / 2)) ** 2);
                    if (dist < 30) {
                        e.hp -= item.damage;
                        e.vx = player.facing * 5;
                        e.vy = -3;
                        addDamageNumber(e.x, e.y, item.damage);
                        addParticle(e.x + e.w / 2, e.y + e.h / 2, '#ff0', 5);

                        if (e.hp <= 0) {
                            player.xp += e.xp;
                            addParticle(e.x + e.w / 2, e.y + e.h / 2, '#f00', 15);
                            checkLevelUp();
                        }
                    }
                }

                // Swing animation particle
                addParticle(ax, ay, '#ff0', 3);
            } else if (item && item.type === 'tool') {
                player.attackCooldown = Math.floor(15 / item.speed);
                // Tool attack is same as mining but faster
            } else if (item && item.type === 'consumable') {
                if (item.heal) {
                    player.hp = Math.min(player.maxHp, player.hp + item.heal);
                    showMessage('+' + item.heal + ' HP');
                }
                if (item.mana) {
                    player.mana = Math.min(player.maxMana, player.mana + item.mana);
                    showMessage('+' + item.mana + ' MP');
                }
                removeItemFromHotbar(player.selectedSlot);
                player.attackCooldown = 20;
            }
        }
    }

    // Mana regen
    if (player.mana < player.maxMana) {
        player.mana += 0.02;
    }

    // Update UI
    document.getElementById('hpBar').style.width = (player.hp / player.maxHp * 100) + '%';
    document.getElementById('hpText').textContent = Math.floor(player.hp) + '/' + player.maxHp;
    document.getElementById('manaBar').style.width = (player.mana / player.maxMana * 100) + '%';
    document.getElementById('manaText').textContent = Math.floor(player.mana) + '/' + player.maxMana;
    document.getElementById('xpBar').style.width = (player.xp / player.xpNeeded * 100) + '%';
    document.getElementById('xpText').textContent = 'Lv ' + player.level;
}

function checkLevelUp() {
    while (player.xp >= player.xpNeeded) {
        player.xp -= player.xpNeeded;
        player.level++;
        player.xpNeeded = Math.floor(player.xpNeeded * 1.5);
        player.maxHp += 10;
        player.maxMana += 5;
        player.hp = player.maxHp;
        player.mana = player.maxMana;
        showMessage('LEVEL UP! Level ' + player.level);
        addParticle(player.x + player.w / 2, player.y + player.h / 2, '#ff0', 20);
    }
}

function showMessage(text) {
    let msg = document.getElementById('message');
    msg.textContent = text;
    msg.style.opacity = 1;
    messageTimer = 120;
}

// Update enemies
function updateEnemies() {
    for (let i = enemies.length - 1; i >= 0; i--) {
        let e = enemies[i];

        // AI
        let dx = player.x - e.x;
        let dy = player.y - e.y;
        let dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < 300) {
            // Chase player
            if (dx > 10) e.vx = 1.5;
            else if (dx < -10) e.vx = -1.5;
            else e.vx = 0;

            // Jump if blocked
            let tileFront = Math.floor((e.x + (e.vx > 0 ? e.w + 2 : -2)) / TILE);
            let tileBelow = Math.floor((e.y + e.h + 2) / TILE);
            if (isSolid(tileFront, tileBelow - 1) && e.onGround) {
                e.vy = -6;
                e.onGround = false;
            }
        } else {
            e.vx *= 0.9;
        }

        // Gravity
        e.vy += GRAVITY;
        if (e.vy > 10) e.vy = 10;

        // Move X
        e.x += e.vx;
        let tileLeft = Math.floor(e.x / TILE);
        let tileRight = Math.floor((e.x + e.w) / TILE);
        let tileTop = Math.floor(e.y / TILE);
        let tileBottom = Math.floor((e.y + e.h) / TILE);

        for (let ty = tileTop; ty <= tileBottom; ty++) {
            if (e.vx > 0 && isSolid(tileRight, ty)) {
                e.x = tileRight * TILE - e.w;
                e.vx = 0;
            } else if (e.vx < 0 && isSolid(tileLeft, ty)) {
                e.x = (tileLeft + 1) * TILE;
                e.vx = 0;
            }
        }

        // Move Y
        e.y += e.vy;
        tileLeft = Math.floor(e.x / TILE);
        tileRight = Math.floor((e.x + e.w) / TILE);
        tileTop = Math.floor(e.y / TILE);
        tileBottom = Math.floor((e.y + e.h) / TILE);

        e.onGround = false;
        for (let tx = tileLeft; tx <= tileRight; tx++) {
            if (e.vy > 0 && isSolid(tx, tileBottom)) {
                e.y = tileBottom * TILE - e.h;
                e.vy = 0;
                e.onGround = true;
            } else if (e.vy < 0 && isSolid(tx, tileTop)) {
                e.y = (tileTop + 1) * TILE;
                e.vy = 0;
            }
        }

        // Attack player
        if (rectCollision({ x: e.x, y: e.y, w: e.w, h: e.h }, { x: player.x, y: player.y, w: player.w, h: player.h })) {
            if (e.attackCooldown <= 0 && player.invincible <= 0) {
                player.hp -= e.damage;
                player.invincible = 30;
                e.attackCooldown = 60;
                addDamageNumber(player.x, player.y, e.damage, '#f00');
                addParticle(player.x + player.w / 2, player.y + player.h / 2, '#f00', 5);

                if (player.hp <= 0) {
                    showMessage('YOU DIED! Respawning...');
                    setTimeout(() => {
                        player.hp = player.maxHp;
                        player.mana = player.maxMana;
                        let spawnX = Math.floor(WORLD_W / 2);
                        let spawnY = 0;
                        for (let y = 0; y < WORLD_H; y++) {
                            if (world[spawnX][y] !== 0) {
                                spawnY = y - 2;
                                break;
                            }
                        }
                        player.x = spawnX * TILE;
                        player.y = spawnY * TILE;
                    }, 1000);
                }
            }
        }
        if (e.attackCooldown > 0) e.attackCooldown--;

        // Animation
        e.animTimer++;
        if (e.animTimer > 10) {
            e.animTimer = 0;
            e.animFrame = (e.animFrame + 1) % 4;
        }

        // Remove dead enemies
        if (e.hp <= 0) {
            enemies.splice(i, 1);
        }

        // Remove far enemies
        if (Math.abs(e.x - player.x) > 600 || Math.abs(e.y - player.y) > 400) {
            enemies.splice(i, 1);
        }
    }
}

// Update particles
function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life--;
        if (!p.isText) {
            p.vy += 0.1;
        }
        if (p.life <= 0) {
            particles.splice(i, 1);
        }
    }
}

// Update camera
function updateCamera() {
    camera.x = player.x - canvas.width / 2 + player.w / 2;
    camera.y = player.y - canvas.height / 2 + player.h / 2;

    if (camera.x < 0) camera.x = 0;
    if (camera.x > WORLD_W * TILE - canvas.width) camera.x = WORLD_W * TILE - canvas.width;
    if (camera.y < 0) camera.y = 0;
    if (camera.y > WORLD_H * TILE - canvas.height) camera.y = WORLD_H * TILE - canvas.height;
}

// Draw functions
function drawBlock(tx, ty) {
    let block = world[tx][ty];
    if (block === 0) return;

    let x = tx * TILE - camera.x;
    let y = ty * TILE - camera.y;

    if (x < -TILE || x > canvas.width + TILE || y < -TILE || y > canvas.height + TILE) return;

    let blockData = BLOCKS[block];
    if (!blockData || !blockData.color) return;

    ctx.fillStyle = blockData.color;
    ctx.fillRect(x, y, TILE, TILE);

    // Block details
    if (block === 1) { // dirt
        ctx.fillStyle = '#6B3410';
        ctx.fillRect(x + 2, y + 3, 2, 2);
        ctx.fillRect(x + 8, y + 8, 3, 2);
        ctx.fillRect(x + 4, y + 12, 2, 2);
    } else if (block === 2) { // grass
        ctx.fillStyle = '#32CD32';
        ctx.fillRect(x, y, TILE, 3);
        ctx.fillStyle = '#8B4513';
        ctx.fillRect(x + 3, y + 5, 2, 2);
        ctx.fillRect(x + 10, y + 10, 3, 2);
    } else if (block === 3) { // stone
        ctx.fillStyle = '#606060';
        ctx.fillRect(x + 1, y + 1, 6, 6);
        ctx.fillRect(x + 9, y + 8, 5, 5);
        ctx.fillStyle = '#A0A0A0';
        ctx.fillRect(x + 8, y + 2, 4, 4);
    } else if (block === 4) { // wood
        ctx.fillStyle = '#543210';
        ctx.fillRect(x + 3, y, 1, TILE);
        ctx.fillRect(x + 8, y, 1, TILE);
        ctx.fillRect(x + 13, y, 1, TILE);
    } else if (block === 5) { // leaves
        ctx.fillStyle = '#004400';
        ctx.fillRect(x + 2, y + 2, 4, 4);
        ctx.fillRect(x + 8, y + 6, 3, 3);
    } else if (block === 6) { // coal ore
        ctx.fillStyle = '#404040';
        ctx.fillRect(x + 2, y + 2, 4, 4);
        ctx.fillRect(x + 8, y + 8, 5, 5);
        ctx.fillStyle = '#1a1a1a';
        ctx.fillRect(x + 3, y + 3, 2, 2);
        ctx.fillRect(x + 9, y + 9, 3, 3);
    } else if (block === 7) { // iron ore
        ctx.fillStyle = '#404040';
        ctx.fillRect(x + 2, y + 2, 4, 4);
        ctx.fillRect(x + 9, y + 8, 5, 5);
        ctx.fillStyle = '#D4A574';
        ctx.fillRect(x + 3, y + 3, 2, 2);
        ctx.fillRect(x + 10, y + 9, 3, 3);
    } else if (block === 8) { // gold ore
        ctx.fillStyle = '#404040';
        ctx.fillRect(x + 2, y + 2, 4, 4);
        ctx.fillRect(x + 9, y + 8, 5, 5);
        ctx.fillStyle = '#FFD700';
        ctx.fillRect(x + 3, y + 3, 2, 2);
        ctx.fillRect(x + 10, y + 9, 3, 3);
    } else if (block === 9) { // diamond ore
        ctx.fillStyle = '#404040';
        ctx.fillRect(x + 2, y + 2, 4, 4);
        ctx.fillRect(x + 9, y + 8, 5, 5);
        ctx.fillStyle = '#00FFFF';
        ctx.fillRect(x + 3, y + 3, 2, 2);
        ctx.fillRect(x + 10, y + 9, 3, 3);
    } else if (block === 14) { // torch
        ctx.fillStyle = '#8B4513';
        ctx.fillRect(x + 6, y + 4, 4, 10);
        ctx.fillStyle = '#FFA500';
        ctx.fillRect(x + 5, y + 1, 6, 5);
        ctx.fillStyle = '#FFD700';
        ctx.fillRect(x + 6, y + 2, 4, 3);
    } else if (block === 16) { // bedrock
        ctx.fillStyle = '#0a0a0a';
        ctx.fillRect(x + 1, y + 1, 6, 6);
        ctx.fillRect(x + 9, y + 9, 5, 5);
        ctx.fillStyle = '#333';
        ctx.fillRect(x + 8, y + 2, 4, 4);
    }

    // Block border
    ctx.strokeStyle = 'rgba(0,0,0,0.2)';
    ctx.lineWidth = 0.5;
    ctx.strokeRect(x, y, TILE, TILE);
}

function drawPlayer() {
    let x = player.x - camera.x;
    let y = player.y - camera.y;

    // Invincibility flash
    if (player.invincible > 0 && Math.floor(player.invincible / 3) % 2 === 0) return;

    ctx.save();
    if (player.facing < 0) {
        ctx.translate(x + player.w, y);
        ctx.scale(-1, 1);
        x = 0;
        y = 0;
    } else {
        ctx.translate(x, y);
        x = 0;
    }

    // Body
    ctx.fillStyle = '#4488FF';
    ctx.fillRect(x + 2, y + 8, 8, 10);

    // Head
    ctx.fillStyle = '#FFDAB9';
    ctx.fillRect(x + 2, y, 8, 8);

    // Hair
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(x + 2, y, 8, 3);
    ctx.fillRect(x + 1, y + 1, 1, 4);

    // Eyes
    ctx.fillStyle = '#000';
    ctx.fillRect(x + 6, y + 3, 2, 2);

    // Legs
    let legOffset = player.onGround ? Math.sin(player.animFrame * Math.PI / 2) * 2 : 0;
    ctx.fillStyle = '#654321';
    ctx.fillRect(x + 2, y + 18, 3, 6 + legOffset);
    ctx.fillRect(x + 7, y + 18, 3, 6 - legOffset);

    // Arms
    let armOffset = player.attackCooldown > 10 ? -5 : Math.sin(player.animFrame * Math.PI / 2) * 2;
    ctx.fillStyle = '#FFDAB9';
    ctx.fillRect(x + 10, y + 9 + armOffset, 3, 6);
    ctx.fillRect(x - 1, y + 9 - armOffset, 3, 6);

    // Held item
    let heldItem = player.hotbar[player.selectedSlot];
    if (heldItem) {
        let item = ITEMS[heldItem.id];
        if (item) {
            if (item.type === 'weapon') {
                ctx.fillStyle = '#CCC';
                ctx.fillRect(x + 10, y + 6 + armOffset, 2, 12);
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(x + 9, y + 14 + armOffset, 4, 3);
            } else if (item.type === 'tool') {
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(x + 10, y + 4 + armOffset, 2, 14);
                ctx.fillStyle = '#CCC';
                ctx.fillRect(x + 8, y + 2 + armOffset, 6, 4);
            } else if (item.type === 'block') {
                ctx.fillStyle = BLOCKS[item.block] ? BLOCKS[item.block].color : '#888';
                ctx.fillRect(x + 9, y + 8 + armOffset, 4, 4);
            }
        }
    }

    ctx.restore();
}

function drawEnemy(e) {
    let x = e.x - camera.x;
    let y = e.y - camera.y;

    if (x < -50 || x > canvas.width + 50 || y < -50 || y > canvas.height + 50) return;

    ctx.save();

    if (e.type === 'slime') {
        // Slime body
        let squash = 1 + Math.sin(e.animFrame * Math.PI / 2) * 0.1;
        ctx.fillStyle = '#44CC44';
        ctx.fillRect(x + 2, y + 4 * squash, 12, 12 / squash);
        ctx.fillStyle = '#33AA33';
        ctx.fillRect(x + 4, y + 6 * squash, 8, 4 / squash);
        // Eyes
        ctx.fillStyle = '#000';
        ctx.fillRect(x + 4, y + 6 * squash, 2, 2);
        ctx.fillRect(x + 10, y + 6 * squash, 2, 2);
        // Shine
        ctx.fillStyle = '#88FF88';
        ctx.fillRect(x + 5, y + 5 * squash, 2, 2);
    } else if (e.type === 'skeleton') {
        // Body
        ctx.fillStyle = '#DDD';
        ctx.fillRect(x + 2, y + 4, 8, 12);
        // Head
        ctx.fillRect(x + 2, y, 8, 6);
        // Eyes
        ctx.fillStyle = '#F00';
        ctx.fillRect(x + 3, y + 2, 2, 2);
        ctx.fillRect(x + 7, y + 2, 2, 2);
        // Legs
        let legOff = Math.sin(e.animFrame * Math.PI / 2) * 2;
        ctx.fillStyle = '#CCC';
        ctx.fillRect(x + 2, y + 16, 3, 8 + legOff);
        ctx.fillRect(x + 7, y + 16, 3, 8 - legOff);
        // Arms
        ctx.fillRect(x - 1, y + 6, 3, 8);
        ctx.fillRect(x + 10, y + 6, 3, 8);
    } else if (e.type === 'zombie') {
        // Body
        ctx.fillStyle = '#2D5A27';
        ctx.fillRect(x + 2, y + 6, 8, 12);
        // Head
        ctx.fillStyle = '#3A7A33';
        ctx.fillRect(x + 2, y, 8, 8);
        // Eyes
        ctx.fillStyle = '#F00';
        ctx.fillRect(x + 3, y + 3, 2, 2);
        ctx.fillRect(x + 7, y + 3, 2, 2);
        // Mouth
        ctx.fillStyle = '#000';
        ctx.fillRect(x + 4, y + 6, 4, 2);
        // Legs
        let legOff = Math.sin(e.animFrame * Math.PI / 2) * 2;
        ctx.fillStyle = '#444';
        ctx.fillRect(x + 2, y + 18, 3, 6 + legOff);
        ctx.fillRect(x + 7, y + 18, 3, 6 - legOff);
        // Arms
        ctx.fillStyle = '#3A7A33';
        ctx.fillRect(x - 1, y + 8, 3, 8);
        ctx.fillRect(x + 10, y + 8, 3, 8);
    }

    // Health bar
    if (e.hp < e.maxHp) {
        ctx.fillStyle = '#333';
        ctx.fillRect(x, y - 6, 16, 3);
        ctx.fillStyle = '#F00';
        ctx.fillRect(x, y - 6, 16 * (e.hp / e.maxHp), 3);
    }

    ctx.restore();
}

function drawParticles() {
    for (let p of particles) {
        let x = p.x - camera.x;
        let y = p.y - camera.y;

        if (p.isText) {
            ctx.fillStyle = p.color;
            ctx.font = 'bold 14px monospace';
            ctx.textAlign = 'center';
            ctx.fillText(p.text, x, y);
        } else {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life / 50;
            ctx.fillRect(x - p.size / 2, y - p.size / 2, p.size, p.size);
            ctx.globalAlpha = 1;
        }
    }
}

function drawMiningProgress() {
    if (player.mining && player.miningTarget) {
        let tx = player.miningTarget.x;
        let ty = player.miningTarget.y;
        let x = tx * TILE - camera.x;
        let y = ty * TILE - camera.y;

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.strokeRect(x, y, TILE, TILE);

        // Progress bar
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(x, y - 6, TILE, 4);
        ctx.fillStyle = '#FF0';
        ctx.fillRect(x, y - 6, TILE * player.miningProgress, 4);
    }
}

function drawBackground() {
    // Sky gradient based on time of day
    let dayProgress = (dayTime % dayLength) / dayLength;
    let skyColor;

    if (dayProgress < 0.25) {
        // Dawn
        let t = dayProgress / 0.25;
        skyColor = lerpColor('#1a1a3a', '#87CEEB', t);
    } else if (dayProgress < 0.75) {
        // Day
        skyColor = '#87CEEB';
    } else if (dayProgress < 0.85) {
        // Dusk
        let t = (dayProgress - 0.75) / 0.1;
        skyColor = lerpColor('#87CEEB', '#1a1a3a', t);
    } else {
        // Night
        skyColor = '#1a1a3a';
    }

    ctx.fillStyle = skyColor;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Stars at night
    if (dayProgress > 0.8 || dayProgress < 0.15) {
        ctx.fillStyle = '#fff';
        for (let i = 0; i < 50; i++) {
            let sx = (i * 137 + 50) % canvas.width;
            let sy = (i * 97 + 30) % (canvas.height * 0.6);
            let brightness = Math.sin(dayTime * 0.01 + i) * 0.5 + 0.5;
            ctx.globalAlpha = brightness * (dayProgress > 0.8 ? 1 : 0.5);
            ctx.fillRect(sx, sy, 2, 2);
        }
        ctx.globalAlpha = 1;
    }

    // Sun/Moon
    let celestialX = canvas.width * 0.2 + canvas.width * 0.6 * dayProgress;
    let celestialY = canvas.height * 0.1 + Math.sin(dayProgress * Math.PI) * -canvas.height * 0.05;

    if (dayProgress > 0.15 && dayProgress < 0.85) {
        // Sun
        ctx.fillStyle = '#FFD700';
        ctx.beginPath();
        ctx.arc(celestialX, celestialY, 20, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#FFF8DC';
        ctx.beginPath();
        ctx.arc(celestialX, celestialY, 15, 0, Math.PI * 2);
        ctx.fill();
    } else {
        // Moon
        ctx.fillStyle = '#DDD';
        ctx.beginPath();
        ctx.arc(canvas.width - celestialX + 100, celestialY, 15, 0, Math.PI * 2);
        ctx.fill();
    }

    // Clouds
    ctx.fillStyle = 'rgba(255,255,255,0.6)';
    for (let i = 0; i < 5; i++) {
        let cx = (i * 250 + dayTime * 0.2) % (canvas.width + 200) - 100;
        let cy = 50 + i * 30;
        ctx.fillRect(cx, cy, 60, 15);
        ctx.fillRect(cx + 10, cy - 10, 40, 10);
        ctx.fillRect(cx + 20, cy + 15, 30, 10);
    }
}

function lerpColor(a, b, t) {
    let ah = parseInt(a.replace('#', ''), 16);
    let bh = parseInt(b.replace('#', ''), 16);
    let ar = (ah >> 16) & 0xff, ag = (ah >> 8) & 0xff, ab = ah & 0xff;
    let br = (bh >> 16) & 0xff, bg = (bh >> 8) & 0xff, bb = bh & 0xff;
    let rr = Math.round(ar + (br - ar) * t);
    let rg = Math.round(ag + (bg - ag) * t);
    let rb = Math.round(ab + (bb - ab) * t);
    return '#' + ((rr << 16) | (rg << 8) | rb).toString(16).padStart(6, '0');
}

function drawHUD() {
    // Draw hotbar
    let hotbarEl = document.getElementById('hotbar');
    hotbarEl.innerHTML = '';
    for (let i = 0; i < 9; i++) {
        let slot = document.createElement('div');
        slot.className = 'slot' + (i === player.selectedSlot ? ' active' : '');
        if (player.hotbar[i]) {
            let item = ITEMS[player.hotbar[i].id];
            slot.innerHTML = item.name.substring(0, 6) + '<span class="count">' + player.hotbar[i].count + '</span>';
            slot.style.borderColor = item.type === 'weapon' ? '#f44' : item.type === 'tool' ? '#fa0' : '#888';
        }
        slot.onclick = () => { player.selectedSlot = i; };
        hotbarEl.appendChild(slot);
    }
}

function drawBlockHighlight() {
    let mx = mouse.x + camera.x;
    let my = mouse.y + camera.y;
    let tx = Math.floor(mx / TILE);
    let ty = Math.floor(my / TILE);

    let dist = Math.sqrt((mx - (player.x + player.w / 2)) ** 2 + (my - (player.y + player.h / 2)) ** 2);
    if (dist < 100 && tx >= 0 && tx < WORLD_W && ty >= 0 && ty < WORLD_H) {
        let x = tx * TILE - camera.x;
        let y = ty * TILE - camera.y;
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.lineWidth = 2;
        ctx.strokeRect(x, y, TILE, TILE);
    }
}

// Crafting recipes
const RECIPES = [
