// Main game loop
function gameLoop() {
    // Update
    dayTime++;
    updatePlayer();
    updateEnemies();
    updateParticles();
    updateCamera();

    if (messageTimer > 0) {
        messageTimer--;
        if (messageTimer <= 0) {
            document.getElementById('message').style.opacity = 0;
        }
    }

    spawnEnemies();

    // Draw
    drawBackground();

    // Draw blocks
    let startTX = Math.floor(camera.x / TILE);
    let endTX = Math.ceil((camera.x + canvas.width) / TILE);
    let startTY = Math.floor(camera.y / TILE);
    let endTY = Math.ceil((camera.y + canvas.height) / TILE);

    for (let tx = startTX; tx <= endTX; tx++) {
        for (let ty = startTY; ty <= endTY; ty++) {
            drawBlock(tx, ty);
        }
    }

    drawBlockHighlight();
    drawMiningProgress();

    // Draw enemies
    for (let e of enemies) {
        drawEnemy(e);
    }

    drawPlayer();
    drawParticles();

    // Draw HUD
    drawHUD();

    // Day/night overlay
    let dayProgress = (dayTime % dayLength) / dayLength;
    if (dayProgress > 0.8 || dayProgress < 0.15) {
        ctx.fillStyle = 'rgba(0,0,30,0.3)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    // Controls hint
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.font = '10px monospace';
    ctx.fillText('WASD: Move | Click: Mine | Right Click: Attack/Use | E: Inventory | C: Crafting | 1-9: Hotbar', 10, canvas.height - 10);

    requestAnimationFrame(gameLoop);
}

// Initialize
generateWorld();
initInventory();
gameLoop();
