function createTerrain() {
    // Main ground plane
    const groundGeometry = new THREE.PlaneGeometry(2000, 2000, 100, 100);
    const groundMaterial = new THREE.MeshStandardMaterial({
        color: 0x8B7355,
        roughness: 0.9,
        metalness: 0.1,
    });

    // Displace vertices for mountainous terrain
    const vertices = groundGeometry.attributes.position.array;
    for (let i = 0; i < vertices.length; i += 3) {
        const x = vertices[i];
        const z = vertices[i + 1];
        const distance = Math.sqrt(x * x + z * z);
        let height = 0;

        if (distance > 50) {
            height = (Math.sin(x * 0.01) * Math.cos(z * 0.01) * 20 +
                      Math.sin(x * 0.03 + z * 0.02) * 10 +
                      Math.cos(x * 0.005) * Math.sin(z * 0.008) * 30);
            height = Math.max(height, 0);
        }

        vertices[i + 2] = height;
    }
    groundGeometry.computeVertexNormals();

    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -5;
    ground.receiveShadow = true;
    scene.add(ground);

    // Create mountain peaks
    for (let i = 0; i < 15; i++) {
        const mountainGeo = new THREE.ConeGeometry(
            30 + Math.random() * 50,
            40 + Math.random() * 80,
            8 + Math.floor(Math.random() * 5)
        );
        const mountainMat = new THREE.MeshStandardMaterial({
            color: new THREE.Color().setHSL(0.08, 0.3, 0.2 + Math.random() * 0.15),
            roughness: 0.95,
            metalness: 0.05,
            flatShading: true
        });
        const mountain = new THREE.Mesh(mountainGeo, mountainMat);
        const angle = (i / 15) * Math.PI * 2;
        const dist = 200 + Math.random() * 300;
        mountain.position.set(Math.cos(angle) * dist, 10 + Math.random() * 20, Math.sin(angle) * dist);
        mountain.rotation.y = Math.random() * Math.PI;
        mountain.castShadow = true;
        mountain.receiveShadow = true;
        scene.add(mountain);
        mountainMeshes.push(mountain);
    }

    // Rocky details
    for (let i = 0; i < 50; i++) {
        const rockGeo = new THREE.DodecahedronGeometry(1 + Math.random() * 3, 0);
        const rockMat = new THREE.MeshStandardMaterial({
            color: new THREE.Color().setHSL(0.08, 0.2, 0.3 + Math.random() * 0.2),
            roughness: 0.9,
            flatShading: true
        });
        const rock = new THREE.Mesh(rockGeo, rockMat);
        rock.position.set(
            (Math.random() - 0.5) * 200,
            -3 + Math.random() * 5,
            (Math.random() - 0.5) * 200
        );
        rock.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
        rock.castShadow = true;
        scene.add(rock);
    }
}

