function initAudio() {
    audioContext = new (window.AudioContext || window.webkitAudioContext)();

    // Engine rumble - low frequency
    const engine Osc = audioContext.createOscillator();
    const engineGain = audioContext.createGain();
    const engineFilter = audioContext.createBiquadFilter();

    engineOsc.type = 'sawtooth';
    engineOsc.frequency.value = 40;
    engineFilter.type = 'lowpass';
    engineFilter.frequency.value = 200;
    engineGain.gain.value = 0;

    engineOsc.connect(engineFilter);
    engineFilter.connect(engineGain);
    engineGain.connect(audioContext.destination);
    engineOsc.start();
    engineSound = { osc: engineOsc, gain: engineGain, filter: engineFilter };

    // Rumble - deeper bass
    const rumbleOsc = audioContext.createOscillator();
    const rumbleGain = audioContext.createGain();
    const rumbleFilter = audioContext.createBiquadFilter();

    rumbleOsc.type = 'sine';
    rumbleOsc.frequency.value = 25;
    rumbleFilter.type = 'lowpass';
    rumbleFilter.frequency.value = 100;
    rumbleGain.gain.value = 0;

    rumbleOsc.connect(rumbleFilter);
    rumbleFilter.connect(rumbleGain);
    rumbleGain.connect(audioContext.destination);
    rumbleOsc.start();
    rumbleSound = { osc: rumbleOsc, gain: rumbleGain };

    // Wind noise
    const windBufferSize = audioContext.sampleRate * 2;
    const windBuffer = audioContext.createBuffer(1, windBufferSize, audioContext.sampleRate);
    const windData = windBuffer.getChannelData(0);
    for (let i = 0; i < windBufferSize; i++) {
        windData[i] = (Math.random() * 2 - 1) * 0.5;
    }

    const windSource = audioContext.createBufferSource();
    windSource.buffer = windBuffer;
    windSource.loop = true;

    const windFilter = audioContext.createBiquadFilter();
    windFilter.type = 'bandpass';
    windFilter.frequency.value = 500;
    windFilter.Q.value = 0.5;

    const windGain = audioContext.createGain();
    windGain.gain.value = 0;

    windSource.connect(windFilter);
    windFilter.connect(windGain);
    windGain.connect(audioContext.destination);
    windSource.start();
}

function updateAudio(dt) {
    if (!audioContext || !isLaunched) return;

    const speed = missileVelocity / 4400; // Mach 13 ~ 4400 m/s
    const audioIntensity = Math.min(speed, 1);

    // Engine sound increases with speed
    engineSound.gain.gain.setTargetAtTime(audioIntensity * 0.3, audioContext.currentTime, 0.1);
    engineSound.filter.frequency.setTargetAtTime(200 + speed * 800, audioContext.currentTime, 0.1);
    engineSound.osc.frequency.setTargetAtTime(40 + speed * 60, audioContext.currentTime, 0.1);

    // Rumble
    rumbleSound.gain.gain.setTargetAtTime(audioIntensity * 0.2, audioContext.currentTime, 0.1);

    // Wind noise
    const windFilter = audioContext.createBiquadFilter();
    // Wind increases with altitude and speed
}

function spawnSmokeParticle(position) {
    for (let p of particles) {
        if (p.type === 'smoke' && !p.mesh.visible) {
            p.mesh.visible = true;
            p.mesh.position.copy(position);
            p.mesh.position.x += (Math.random() - 0.5) * 3;
            p.mesh.position.z += (Math.random() - 0.5) * 3;
            p.velocity.set(
                (Math.random() - 0.5) * 2,
                -2 - Math.random() * 3,
                (Math.random() - 0.5) * 2
            );
            p.life = 0;
            p.maxLife = 2 + Math.random() * 3;
            p.mesh.scale.set(
                1 + Math.random() * 2,
                1 + Math.random() * 2,
                1 + Math.random() * 2
            );
            p.mesh.material.opacity = 0.4;
            p.mesh.material.color.setHSL(0, 0, 0.4 + Math.random() * 0.2);
            return;
        }
    }
}

function spawnFireParticle(position) {
    for (let p of particles) {
        if (p.type === 'fire' && !p.mesh.visible) {
            p.mesh.visible = true;
            p.mesh.position.copy(position);
            p.mesh.position.x += (Math.random() - 0.5) * 1;
            p.mesh.position.z += (Math.random() - 0.5) * 1;
            p.velocity.set(
                (Math.random() - 0.5) * 5,
                -5 - Math.random() * 10,
                (Math.random() - 0.5) * 5
            );
            p.life = 0;
            p.maxLife = 0.3 + Math.random() * 0.7;
            const colors = [0xff6600, 0xffaa00, 0xffcc00, 0xff3300];
            p.mesh.material.color.setHex(colors[Math.floor(Math.random() * colors.length)]);
            p.mesh.scale.set(0.2 + Math.random() * 0.5, 0.2 + Math.random() * 0.5, 0.2 + Math.random() * 0.5);
            return;
        }
    }
}

function updateParticles(dt) {
    for (let p of particles) {
        if (!p.mesh.visible) continue;

        p.life += dt;
        if (p.life >= p.maxLife) {
            p.mesh.visible = false;
            continue;
        }

        p.mesh.position.add(p.velocity.clone().multiplyScalar(dt));
        p.velocity.y -= dt * 2; // gravity effect on smoke

        const lifeRatio = p.life / p.maxLife;
        p.mesh.material.opacity = (1 - lifeRatio) * (p.type === 'fire' ? 0.8 : 0.3);
        p.mesh.scale.multiplyScalar(1 + dt * 0.5);
    }

    // Update dust particles
    for (let d of dustParticles) {
        if (!d.mesh.visible) continue;

        d.life += dt;
        if (d.life >= d.maxLife) {
            d.mesh.visible = false;
            continue;
        }

        d.mesh.position.add(d.velocity.clone().multiplyScalar(dt));
        d.velocity.y -= dt * 3;
        d.velocity.x *= 0.99;
        d.velocity.z *= 0.99;

        const lifeRatio = d.life / d.maxLife;
        d.mesh.material.opacity = (1 - lifeRatio) * 0.4;
        d.mesh.scale.multiplyScalar(1 + dt * 0.3);
    }
}

function updateMissile(dt) {
    if (!isLaunched) return;

    simulationTime += dt;

    // Physics-based acceleration
    const maxSpeed = 4400; // Mach 13 ~ 4400 m/s
    const acceleration = 50; // m/s^2 initial

    missileVelocity = Math.min(missileVelocity + acceleration * dt, maxSpeed);
    missileAltitude += missileVelocity * dt;

    // Missile position
    missile.position.y = missileAltitude;

    // Slight trajectory adjustments (realistic flight path)
    missile.position.x = Math.sin(simulationTime * 0.1) * 2;
    missile.position.z = Math.cos(simulationTime * 0.15) * 1;

    // Missile rotation - slight wobble
    missile.rotation.z = Math.sin(simulationTime * 2) * 0.02;
    missile.rotation.x = Math.cos(simulationTime * 1.5) * 0.01;

    // Fin vibration
    missile.children.forEach((child, index) => {
        if (index > 10 && index < 15) { // fins
            child.rotation.z += Math.sin(simulationTime * 20 + index) * 0.001;
        }
    });

    // Spawn smoke and fire from nozzle
    if (simulationTime < 30) {
        const nozzlePos = new THREE.Vector3(0, 0, 0);
        missile.localToWorld(nozzlePos);

        for (let i = 0; i < 5; i++) {
            spawnSmokeParticle(nozzlePos);
        }
        for (let i = 0; i < 8; i++) {
            spawnFireParticle(nozzlePos);
        }

        // Explosion light
        explosionLight.intensity = 5 + Math.sin(simulationTime * 10) * 2;
        explosionLight.position.copy(nozzlePos);
        explosionLight.position.y -= 2;
    }

    // Update UI
    document.getElementById('altitude-display').textContent = `ALT: ${Math.floor(missileAltitude)} m`;
    document.getElementById('speed-display').textContent = `SPD: ${Math.floor(missileVelocity)} m/s (${(missileVelocity / 340).toFixed(1)} Mach)`;
    document.getElementById('progress-bar').style.width = `${Math.min(simulationTime / 30 * 100, 100)}%`;
}

function updateCamera(dt) {
    cameraTimer += dt;

    if (!isLaunched) {
        // Pre-launch camera - slow orbit around bunker
        const angle = cameraTimer * 0.1;
        camera.position.set(
            Math.cos(angle) * 25,
            8 + Math.sin(cameraTimer * 0.2) * 3,
            Math.sin(angle) * 25
        );
        camera.lookAt(0, 5, 0);
        document.getElementById('camera-label').textContent = 'CAM: PRE-LAUNCH ORBIT';
        return;
    }

    // Camera mode transitions
    if (cameraTimer < 2) {
        // Low angle close-up as missile emerges
        cameraMode = 0;
        document.getElementById('camera-label').textContent = 'CAM: LOW ANGLE CLOSE-UP';
    } else if (cameraTimer < 5) {
        // Chase camera from behind
        cameraMode = 1;
        document.getElementById('camera-label').textContent = 'CAM: CHASE VIEW';
    } else if (cameraTimer < 8) {
        // FPV from missile
        cameraMode = 2;
        document.getElementById('camera-label').textContent = 'CAM: FPV MISSILE EYE';
    } else if (cameraTimer < 12) {
        // Side profile tracking
        cameraMode = 3;
        document.getElementById('camera-label').textContent = 'CAM: SIDE PROFILE';
    } else if (cameraTimer < 16) {
        // Wide world view
        cameraMode = 4;
        document.getElementById('camera-label').textContent = 'CAM: WORLD VIEW';
    } else if (cameraTimer < 22) {
        // Orbiting camera
        cameraMode = 5;
        document.getElementById('camera-label').textContent = 'CAM: ORBITING';
    } else {
        // Final dramatic shot
        cameraMode = 6;
        document.getElementById('camera-label').textContent = 'CAM: DRAMATIC FINAL';
    }

    const missileWorldPos = new THREE.Vector3();
    missile.getWorldPosition(missileWorldPos);

    switch (cameraMode) {
        case 0: // Low angle close-up
            const lowAngleTime = Math.min(cameraTimer, 2) / 2;
            camera.position.lerpVectors(
                new THREE.Vector3(15, 5, 20),
                new THREE.Vector3(8, missileAltitude + 3, 10),
                lowAngleTime
            );
            camera.lookAt(missileWorldPos.x, missileWorldPos.y - 2, missileWorldPos.z);
            break;

        case 1: // Chase camera
            const chaseOffset = new THREE.Vector3(0, -8, 15);
            chaseOffset.applyQuaternion(missile.quaternion);
            const chasePos = missileWorldPos.clone().add(chaseOffset);
            camera.position.lerp(chasePos, 0.05);
            camera.lookAt(missileWorldPos.x, missileWorldPos.y + 20, missileWorldPos.z);
            break;

        case 2: // FPV
            const fpvOffset = new THREE.Vector3(0, 2, -3);
            fpvOffset.applyQuaternion(missile.quaternion);
            camera.position.copy(missileWorldPos).add(fpvOffset);
            const fpvTarget = missileWorldPos.clone();
            fpvTarget.y += 100;
            camera.lookAt(fpvTarget);
            break;

        case 3: // Side profile
            const sideAngle = cameraTimer * 0.3;
            camera.position.set(
                missileWorldPos.x + Math.cos(sideAngle) * 30,
                missileWorldPos.y + 5,
                missileWorldPos.z + Math.sin(sideAngle) * 30
            );
            camera.lookAt(missileWorldPos);
            break;

        case 4: // World view
            const worldOffset = new THREE.Vector3(0, 100, 50);
            camera.position.lerp(
                missileWorldPos.clone().add(worldOffset),
                0.02
            );
            camera.lookAt(missileWorldPos);
            break;

        case 5: // Orbiting
            const orbitAngle = cameraTimer * 0.5;
            camera.position.set(
                missileWorldPos.x + Math.cos(orbitAngle) * 25,
                missileWorldPos.y + 10,
                missileWorldPos.z + Math.sin(orbitAngle) * 25
            );
            camera.lookAt(missileWorldPos);
            break;

        case 6: // Dramatic final
            const finalAngle = (cameraTimer - 22) * 0.2;
            camera.position.set(
                missileWorldPos.x + Math.cos(finalAngle) * 40,
                missileWorldPos.y - 20,
                missileWorldPos.z + Math.sin(finalAngle) * 40
            );
            camera.lookAt(missileWorldPos);
            break;
    }
}

function updateBunkerDoor(dt) {
    if (bunkerDoor && simulationTime < 1) {
        // Door opens slowly before launch
        const openProgress = Math.min(simulationTime / 1, 1);
        bunkerDoor.position.z = 2.5 + openProgress * 15;
        bunkerDoor.position.y = 8 + openProgress * 5;
    }
}

function updateEnvironment(dt) {
    // Update fog based on altitude
    if (isLaunched) {
        const fogDensity = Math.max(0.0008 - missileAltitude * 0.000001, 0.0001);
        scene.fog.density = fogDensity;

        // Sky color changes with altitude
        const altitudeRatio = Math.min(missileAltitude / 5000, 1);
        const skyColor = new THREE.Color().lerpColors(
            new THREE.Color(0x1a1a2e),
            new THREE.Color(0x000011),
            altitudeRatio
        );
        scene.background = skyColor;
    }
}

function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

function animate() {
    requestAnimationFrame(animate);

    const dt = Math.min(clock.getDelta(), 0.05);

    if (isLaunched) {
        updateMissile(dt);
        updateParticles(dt);
        updateCamera(dt);
        updateEnvironment(dt);
        updateAudio(dt);
    } else {
        updateCamera(dt);
        updateBunkerDoor(dt);
    }

    renderer.render(scene, camera);
}

function startSimulation() {
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('loading').style.display = 'none';

    init();
    initAudio();

    // Start launch sequence after brief delay
    setTimeout(() => {
        isLaunched = true;
        launchTime = performance.now();
    }, 2000);

    animate();
}

// Hide loading screen after init
window.addEventListener('load', () => {
    setTimeout(() => {
        document.getElementById('loading').style.display = 'none';
    }, 1000);
});
</script>
</body>
</html>

