        }
        .btn:hover {
            background: #ffb347;
            transform: scale(1.05);
            box-shadow: 0 0 20px rgba(245, 166, 35, 0.5);
        }
        .controls-info {
            margin-top: 20px;
            color: #aaa;
            font-size: 14px;
            line-height: 1.8;
        }
        .controls-info span {
            background: #333;
            padding: 3px 8px;
            border-radius: 4px;
            color: #f5a623;
            font-weight: bold;
        }
        #gameOverScreen h1 {
            font-size: 42px;
            color: #ff4444;
            margin-bottom: 10px;
        }
        #gameOverScreen .score {
            font-size: 28px;
            color: #f5a623;
            margin-bottom: 20px;
        }
        .hidden {
            display: none !important;
        }
        #mobileControls {
            position: absolute;
            bottom: 10px;
            left: 10px;
            right: 10px;
            display: none;
            justify-content: space-between;
            z-index: 15;
            pointer-events: none;
        }
        .mobile-btn {
            width: 60px;
            height: 60px;
            background: rgba(245, 166, 35, 0.5);
            border: 2px solid #f5a623;
            border-radius: 50%;
            color: white;
            font-size: 24px;
            display: flex;
            justify-content: center;
            align-items: center;
            pointer-events: all;
            user-select: none;
            -webkit-user-select: none;
        }
        .mobile-btn:active {
            background: rgba(245, 166, 35, 0.8);
        }
        .mobile-left {
            display: flex;
            gap: 10px;
        }
        @media (max-width: 850px) {
            #mobileControls {
                display: flex;
            }
        }
    </style>
</head>
<body>
    <div id="gameContainer">
        <canvas id="gameCanvas"></canvas>
        <div id="ui">
            <div class="ui-panel" id="scorePanel">🏗️ Punti: 0</div>
            <div class="ui-panel" id="floorPanel">📐 Piano: 1</div>
            <div class="ui-panel" id="materialsPanel">🧱 Materiali: 0/5</div>
            <div class="ui-panel" id="livesPanel">❤️ Vite: 3</div>
        </div>
        <div id="startScreen">
            <h1>🏗️ COSTRUTTORE EDILE</h1>
            <h2>Costruisci il grattacielo più alto!</h2>
            <button class="btn" onclick="startGame()">🔨 INIZIA A COSTRUIRE</button>
            <div class="controls-info">
                <span>←→</span> o <span>A D</span> per muoversi<br>
                <span>↑</span> o <span>W</span> o <span>SPAZIO</span> per saltare<br>
                Raccogli materiali 🧱🔩🪵 per costruire i piani!<br>
                Evita gli oggetti che cadono ⚠️ e non cadere!
            </div>
        </div>
        <div id="gameOverScreen" class="hidden">
            <h1>💥 SITE ACCIDENT!</h1>
            <div class="score" id="finalScore">Punti: 0</div>
            <div class="score" id="finalFloor">Piano raggiunto: 1</div>
            <button class="btn" onclick="startGame()">🔄 RIPROVA</button>
        </div>
        <div id="mobileControls">
            <div class="mobile-left">
                <div class="mobile-btn" id="btnLeft">←</div>
                <div class="mobile-btn" id="btnRight">→</div>
            </div>
            <div class="mobile-btn" id="btnJump">↑</div>
        </div>
    </div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        // Responsive canvas
        function resizeCanvas() {
            const maxW = 900, maxH = 600;
            const scale = Math.min(window.innerWidth / maxW, window.innerHeight / maxH, 1);
            canvas.width = maxW;
            canvas.height = maxH;
            canvas.style.width = maxW * scale + 'px';
            canvas.style.height = maxH * scale + 'px';
        }
        resizeCanvas();
        window.addEventListener('resize', resizeCanvas);

        // Game state
        let game = {
            running: false,
            score: 0,
            floor: 1,
            lives: 3,
            materials: 0,
            materialsNeeded: 5,
            cameraY: 0,
            targetCameraY: 0,
            time: 0,
            shakeTimer: 0,
            shakeIntensity: 0
        };

        // Player
        let player = {
            x: 400,
            y: 500,
            width: 32,
            height: 48,
            vx: 0,
            vy: 0,
            speed: 5,
            jumpForce: -12,
            onGround: false,
            facing: 1,
            animFrame: 0,
            animTimer: 0,
            invincible: 0,
            hardHatColor: '#f5a623'
        };

        // Platforms (scaffolding and floors)
        let platforms = [];
        let materials = [];
        let fallingObjects = [];
        let particles = [];
        let cranes = [];
        let clouds = [];
        let buildings = [];

        // Input
        let keys = {};
        let mobileLeft = false;
        let mobileRight = false;
        let mobileJump = false;

        // Initialize game
        function initGame() {
            game.score = 0;
            game.floor = 1;
            game.lives = 3;
            game.materials = 0;
            game.materialsNeeded = 5;
            game.cameraY = 0;
            game.targetCameraY = 0;
            game.time = 0;
            game.shakeTimer = 0;

            player.x = 400;
            player.y = 500;
            player.vx = 0;
            player.vy = 0;
            player.onGround = false;
            player.invincible = 0;

            platforms = [];
            materials = [];
            fallingObjects = [];
            particles = [];
            cranes = [];
            clouds = [];
            buildings = [];

            // Generate initial platforms
            generatePlatforms(0, 800);

            // Generate background buildings
            for (let i = 0; i < 15; i++) {
                buildings.push({
                    x: Math.random() * 900,
                    y: 600 + Math.random() * 200,
                    width: 40 + Math.random() * 60,
                    height: 100 + Math.random() * 200,
                    color: `hsl(${200 + Math.random() * 40}, 20%, ${30 + Math.random() * 20}%)`
                });
            }

            // Generate clouds
            for (let i = 0; i < 8; i++) {
                clouds.push({
                    x: Math.random() * 900,
                    y: Math.random() * 300,
                    width: 60 + Math.random() * 80,
                    speed: 0.2 + Math.random() * 0.3
                });
            }

            // Add initial cranes
            addCrane(200, -200);
            addCrane(700, -400);

            updateUI();
        }

        function generatePlatforms(fromY, toY) {
            for (let y = fromY; y > toY; y -= 80 + Math.random() * 40) {
                let numPlatforms = 2 + Math.floor(Math.random() * 3);
                for (let i = 0; i < numPlatforms; i++) {
                    let px = Math.random() * (900 - 120);
                    let pw = 80 + Math.random() * 100;
                    platforms.push({
                        x: px,
                        y: y,
                        width: pw,
                        height: 12,
                        type: Math.random() > 0.7 ? 'scaffold' : 'floor'
                    });

                    // Add materials on some platforms
                    if (Math.random() > 0.5) {
                        let matType = Math.random();
                        let type = matType > 0.66 ? 'brick' : matType > 0.33 ? 'steel' : 'wood';
                        materials.push({
                            x: px + pw / 2 - 10,
                            y: y - 20,
                            width: 20,
                            height: 20,
                            type: type,
                            collected: false,
                            bobTimer: Math.random() * Math.PI * 2
                        });
                    }
                }
            }
        }

        function addCrane(x, y) {
            cranes.push({
                x: x,
                y: y,
                armLength: 150 + Math.random() * 100,
                angle: 0,
                speed: 0.005 + Math.random() * 0.01,
                dropTimer: 60 + Math.random() * 120,
                dropping: false
            });
        }

        // Input handling
        document.addEventListener('keydown', (e) => {
            keys[e.key] = true;
            if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) {
                e.preventDefault();
            }
        });
        document.addEventListener('keyup', (e) => {
            keys[e.key] = false;
        });

        // Mobile controls
        function setupMobileBtn(id, setTrue, setFalse) {
            const btn = document.getElementById(id);
            btn.addEventListener('touchstart', (e) => { e.preventDefault(); setTrue(); });
            btn.addEventListener('touchend', (e) => { e.preventDefault(); setFalse(); });
            btn.addEventListener('mousedown', (e) => { setTrue(); });
            btn.addEventListener('mouseup', (e) => { setFalse(); });
        }

        setupMobileBtn('btnLeft', () => mobileLeft = true, () => mobileLeft = false);
        setupMobileBtn('btnRight', () => mobileRight = true, () => mobileRight = false);
        setupMobileBtn('btnJump', () => mobileJump = true, () => mobileJump = false);

        function startGame() {
            document.getElementById('startScreen').classList.add('hidden');
            document.getElementById('gameOverScreen').classList.add('hidden');
            initGame();
            game.running = true;
            gameLoop();
        }

        function gameOver() {
            game.running = false;
            document.getElementById('finalScore').textContent = `Punti: ${game.score}`;
            document.getElementById('finalFloor').textContent = `Piano raggiunto: ${game.floor}`;
            document.getElementById('gameOverScreen').classList.remove('hidden');
        }

        function updateUI() {
            document.getElementById('scorePanel').textContent = `🏗️ Punti: ${game.score}`;
            document.getElementById('floorPanel').textContent = `📐 Piano: ${game.floor}`;
            document.getElementById('materialsPanel').textContent = `🧱 Materiali: ${game.materials}/${game.materialsNeeded}`;
            document.getElementById('livesPanel').textContent = `❤️ Vite: ${game.lives}`;
        }

        // Update game
        function update() {
            if (!game.running) return;

            game.time++;

            // Player movement
            let moveLeft = keys['ArrowLeft'] || keys['a'] || keys['A'] || mobileLeft;
            let moveRight = keys['ArrowRight'] || keys['d'] || keys['D'] || mobileRight;
            let jump = keys['ArrowUp'] || keys['w'] || keys['W'] || keys[' '] || mobileJump;

            if (moveLeft) {
                player.vx = -player.speed;
                player.facing = -1;
            } else if (moveRight) {
                player.vx = player.speed;
                player.facing = 1;
            } else {
                player.vx *= 0.8;
            }

            if (jump && player.onGround) {
                player.vy = player.jumpForce;
                player.onGround = false;
                // Jump particles
                for (let i = 0; i < 5; i++) {
                    particles.push({
                        x: player.x + player.width / 2,
                        y: player.y + player.height,
                        vx: (Math.random() - 0.5) * 4,
                        vy: Math.random() * 2,
                        life: 20,
                        maxLife: 20,
                        color: '#aaa',
                        size: 3 + Math.random() * 3
                    });
                }
            }

            // Gravity
            player.vy += 0.6;
            player.x += player.vx;
            player.y += player.vy;

            // Animation
            player.animTimer++;
            if (player.animTimer > 8) {
                player.animTimer = 0;
                player.animFrame = (player.animFrame + 1) % 4;
            }

            // Invincibility
            if (player.invincible > 0) player.invincible--;

            // Platform collision
            player.onGround = false;
            for (let p of platforms) {
                if (player.x + player.width > p.x && player.x < p.x + p.width) {
                    if (player.y + player.height > p.y && player.y + player.height < p.y + p.height + 10 && player.vy >= 0) {
                        player.y = p.y - player.height;
                        player.vy = 0;
                        player.onGround = true;
                    }
                }
            }

            // Material collection
            for (let m of materials) {
                if (!m.collected &&
                    player.x + player.width > m.x && player.x < m.x + m.width &&
                    player.y + player.height > m.y && player.y < m.y + m.height) {
                    m.collected = true;
                    game.materials++;
                    game.score += 10;
                    // Collection particles
                    for (let i = 0; i < 8; i++) {
                        particles.push({
                            x: m.x + m.width / 2,
                            y: m.y + m.height / 2,
                            vx: (Math.random() - 0.5) * 6,
                            vy: (Math.random() - 0.5) * 6,
                            life: 30,
                            maxLife: 30,
                            color: m.type === 'brick' ? '#cc3333' : m.type === 'steel' ? '#888' : '#8B4513',
                            size: 3 + Math.random() * 4
                        });
                    }
                    if (game.materials >= game.materialsNeeded) {
                        game.materials = 0;
                        game.floor++;
                        game.score += 50;
                        game.materialsNeeded = 5 + game.floor;
                        // Level up particles
                        for (let i = 0; i < 20; i++) {
                            particles.push({
                                x: player.x + player.width / 2,
                                y: player.y,
                                vx: (Math.random() - 0.5) * 10,
                                vy: -Math.random() * 10,
                                life: 40,
                                maxLife: 40,
                                color: '#f5a623',
                                size: 4 + Math.random() * 6
                            });
                        }
                        // Generate more platforms above
                        let highestY = Math.min(...platforms.map(p => p.y));
                        generatePlatforms(highestY, highestY - 400);
                        // Add more cranes
                        if (game.floor % 2 === 0) {
                            addCrane(Math.random() * 900, highestY - 200);
                        }
                    }
                    updateUI();
                }
                m.bobTimer += 0.05;
            }

            // Falling objects from cranes
            for (let c of cranes) {
                c.angle += c.speed;
                c.dropTimer--;
                if (c.dropTimer <= 0 && !c.dropping) {
                    c.dropping = true;
                    fallingObjects.push({
                        x: c.x + Math.cos(c.angle) * c.armLength,
                        y: c.y + 20,
                        width: 20,
                        height: 20,
                        vy: 2,
                        type: Math.random() > 0.5 ? 'wrench' : 'bolt',
                        rotation: 0
                    });
                    c.dropTimer = 80 + Math.random() * 120;
                }
            }

            // Update falling objects
            for (let i = fallingObjects.length - 1; i >= 0; i--) {
                let fo = fallingObjects[i];
                fo.vy += 0.3;
                fo.y += fo.vy;
                fo.rotation += 0.1;

                // Collision with player
                if (player.invincible <= 0 &&
                    player.x + player.width > fo.x && player.x < fo.x + fo.width &&
                    player.y + player.height > fo.y && player.y < fo.y + fo.height) {
                    player.lives--;
                    player.invincible = 60;
                    game.shakeTimer = 10;
                    game.shakeIntensity = 5;
                    updateUI();
                    if (player.lives <= 0) {
                        gameOver();
                        return;
                    }
                    fallingObjects.splice(i, 1);
                    continue;
                }

                if (fo.y > 1000) {
                    fallingObjects.splice(i, 1);
                }
            }

            // Camera follow
            game.targetCameraY = player.y - 300;
            if (game.targetCameraY < game.cameraY) {
                game.cameraY += (game.targetCameraY - game.cameraY) * 0.1;
            }

            // Screen shake
            if (game.shakeTimer > 0) game.shakeTimer--;

            // Update particles
            for (let i = particles.length - 1; i >= 0; i--) {
                let p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.vy += 0.1;
                p.life--;
                if (p.life <= 0) particles.splice(i, 1);
            }

            // Update clouds
            for (let c of clouds) {
                c.x += c.speed;
                if (c.x > 950) c.x = -c.width;
            }

            // Fall death
            if (player.y > game.cameraY + 700) {
                player.lives--;
                player.invincible = 60;
                updateUI();
                if (player.lives <= 0) {
                    gameOver();
                    return;
                }
                // Respawn on nearest platform
                let nearest = null;
                let minDist = Infinity;
                for (let p of platforms) {
                    let dist = Math.abs(p.y - player.y);
                    if (dist < minDist) {
                        minDist = dist;
                        nearest = p;
                    }
                }
                if (nearest) {
                    player.x = nearest.x + nearest.width / 2;
                    player.y = nearest.y - 60;
                }
                player.vy = 0;
            }

            // Boundaries
            if (player.x < 0) player.x = 0;
            if (player.x + player.width > 900) player.x = 900 - player.width;
        }

        // Draw game
        function draw() {
            ctx.save();

            // Screen shake
            if (game.shakeTimer > 0) {
                ctx.translate(
                    (Math.random() - 0.5) * game.shakeIntensity,
                    (Math.random() - 0.5) * game.shakeIntensity
                );
            }

            // Sky gradient
            let skyGrad = ctx.createLinearGradient(0, 0, 0, 600);
            skyGrad.addColorStop(0, '#87CEEB');
            skyGrad.addColorStop(0.5, '#B0E0E6');
            skyGrad.addColorStop(1, '#E0F7FA');
            ctx.fillStyle = skyGrad;
            ctx.fillRect(0, 0, 900, 600);

            ctx.save();
            ctx.translate(0, -game.cameraY);

            // Background buildings
            for (let b of buildings) {
                ctx.fillStyle = b.color;
                ctx.fillRect(b.x, b.y, b.width, b.height);
                // Windows
                ctx.fillStyle = 'rgba(255, 255, 150, 0.6)';
                for (let wy = b.y + 10; wy < b.y + b.height - 10; wy += 20) {
                    for (let wx = b.x + 5; wx < b.x + b.width - 10; wx += 15) {
                        ctx.fillRect(wx, wy, 8, 12);
                    }
                }
            }

            // Clouds
            for (let c of clouds) {
                ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
                ctx.beginPath();
                ctx.ellipse(c.x + c.width / 2, c.y, c.width / 2, 20, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.beginPath();
                ctx.ellipse(c.x + c.width / 3, c.y - 10, c.width / 3, 15, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.beginPath();
                ctx.ellipse(c.x + c.width * 2 / 3, c.y - 5, c.width / 4, 12, 0, 0, Math.PI * 2);
                ctx.fill();
            }

            // Platforms
            for (let p of platforms) {
                if (p.type === 'scaffold') {
                    // Scaffold platform
                    ctx.fillStyle = '#8B4513';
                    ctx.fillRect(p.x, p.y, p.width, p.height);
                    // Metal poles
                    ctx.fillStyle = '#666';
                    ctx.fillRect(p.x, p.y - 30, 4, 30);
                    ctx.fillRect(p.x + p.width - 4, p.y - 30, 4, 30);
                    // Cross braces
                    ctx.strokeStyle = '#666';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(p.x + 2, p.y);
                    ctx.lineTo(p.x + p.width - 2, p.y - 30);
                    ctx.stroke();
                    ctx.beginPath();
                    ctx.moveTo(p.x + p.width - 2, p.y);
                    ctx.lineTo(p.x + 2, p.y - 30);
                    ctx.stroke();
                } else {
                    // Concrete floor
                    let grad = ctx.createLinearGradient(p.x, p.y, p.x, p.y + p.height);
                    grad.addColorStop(0, '#999');
                    grad.addColorStop(1, '#777');
                    ctx.fillStyle = grad;
                    ctx.fillRect(p.x, p.y, p.width, p.height);
                    // Edge lines
                    ctx.strokeStyle = '#555';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(p.x, p.y, p.width, p.height);
                    // Rebar hints
                    ctx.strokeStyle = '#aaa';
                    ctx.lineWidth = 1;
                    for (let rx = p.x + 10; rx < p.x + p.width - 10; rx += 20) {
                        ctx.beginPath();
                        ctx.moveTo(rx, p.y + 2);
                        ctx.lineTo(rx, p.y + p.height - 2);
                        ctx.stroke();
                    }
                }
            }

            // Cranes
            for (let c of cranes) {
                // Crane tower
                ctx.fillStyle = '#f5a623';
                ctx.fillRect(c.x - 5, c.y - 100, 10, 100);
                // Crane arm
                ctx.save();
                ctx.translate(c.x, c.y - 100);
                ctx.rotate(c.angle);
                ctx.fillStyle = '#f5a623';
                ctx.fillRect(0, -3, c.armLength, 6);
                // Cable
                ctx.strokeStyle = '#333';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(c.armLength - 20, 3);
                ctx.lineTo(c.armLength - 20, 30);
                ctx.stroke();
                // Hook
                ctx.fillStyle = '#666';
                ctx.fillRect(c.armLength - 25, 30, 10, 8);
                ctx.restore();
                // Top
                ctx.fillStyle = '#ff4444';
                ctx.fillRect(c.x - 8, c.y - 108, 16, 8);
            }

            // Materials
            for (let m of materials) {
                if (m.collected) continue;
                let bobY = Math.sin(m.bobTimer) * 3;

                if (m.type === 'brick') {
                    ctx.fillStyle = '#cc3333';
                    ctx.fillRect(m.x, m.y + bobY, m.width, m.height);
                    ctx.fillStyle = '#aa2222';
                    ctx.fillRect(m.x + 2, m.y + bobY + 2, m.width - 4, m.height - 4);
                    // Brick lines
                    ctx.strokeStyle = '#881111';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.moveTo(m.x, m.y + bobY + m.height / 2);
                    ctx.lineTo(m.x + m.width, m.y + bobY + m.height / 2);
                    ctx.stroke();
                } else if (m.type === 'steel') {
                    ctx.fillStyle = '#888';
                    ctx.fillRect(m.x, m.y + bobY, m.width, m.height);
                    ctx.fillStyle = '#aaa';
                    ctx.fillRect(m.x + 2, m.y + bobY + 2, m.width - 4, m.height - 4);
                    // Steel shine
                    ctx.fillStyle = 'rgba(255,255,255,0.3)';
                    ctx.fillRect(m.x + 4, m.y + bobY + 4, 4, 4);
                } else {
                    ctx.fillStyle = '#8B4513';
                    ctx.fillRect(m.x, m.y + bobY, m.width, m.height);
                    ctx.fillStyle = '#A0522D';
                    ctx.fillRect(m.x + 2, m.y + bobY + 2, m.width - 4, m.height - 4);
                    // Wood grain
                    ctx.strokeStyle = '#6B3410';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.moveTo(m.x + 3, m.y + bobY + 5);
                    ctx.lineTo(m.x + m.width - 3, m.y + bobY + 5);
                    ctx.stroke();
                }

                // Glow effect
                ctx.fillStyle = 'rgba(245, 166, 35, 0.2)';
                ctx.beginPath();
                ctx.arc(m.x + m.width / 2, m.y + bobY + m.height / 2, 15, 0, Math.PI * 2);
                ctx.fill();
            }

            // Falling objects
            for (let fo of fallingObjects) {
                ctx.save();
                ctx.translate(fo.x + fo.width / 2, fo.y + fo.height / 2);
                ctx.rotate(fo.rotation);
                if (fo.type === 'wrench') {
                    ctx.fillStyle = '#666';
                    ctx.fillRect(-8, -3, 16, 6);
                    ctx.fillRect(-3, -8, 6, 16);
                } else {
                    ctx.fillStyle = '#aaa';
                    ctx.beginPath();
                    ctx.arc(0, 0, 6, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#888';
                    ctx.beginPath();
                    ctx.arc(0, 0, 3, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.restore();
            }

            // Player
            if (player.invincible <= 0 || Math.floor(game.time / 4) % 2 === 0) {
                let px = player.x;
                let py = player.y;

                // Shadow
                ctx.fillStyle = 'rgba(0,0,0,0.2)';
                ctx.beginPath();
                ctx.ellipse(px + player.width / 2, py + player.height + 2, 15, 4, 0, 0, Math.PI * 2);
                ctx.fill();

                // Legs
                let legOffset = player.onGround ? Math.sin(player.animFrame * Math.PI / 2) * 3 : 0;
                ctx.fillStyle = '#2244aa';
                ctx.fillRect(px + 6, py + 32, 8, 16 + legOffset);
                ctx.fillRect(px + 18, py + 32, 8, 16 - legOffset);

                // Boots
                ctx.fillStyle = '#553300';
                ctx.fillRect(px + 4, py + 44 + legOffset, 12, 6);
                ctx.fillRect(px + 16, py + 44 - legOffset, 12, 6);

                // Body
                ctx.fillStyle = '#ff6600';
                ctx.fillRect(px + 4, py + 16, 24, 20);

                // Safety vest
                ctx.fillStyle = '#ffcc00';
                ctx.fillRect(px + 6, py + 18, 20, 16);
                // Reflective stripes
                ctx.fillStyle = '#fff';
                ctx.fillRect(px + 6, py + 22, 20, 2);
                ctx.fillRect(px + 6, py + 28, 20, 2);

                // Arms
                let armSwing = player.onGround ? Math.sin(player.animFrame * Math.PI / 2) * 5 : 0;
                ctx.fillStyle = '#ff6600';
                ctx.fillRect(px - 2, py + 18 + armSwing, 8, 14);
                ctx.fillRect(px + 26, py + 18 - armSwing, 8, 14);

                // Hands
                ctx.fillStyle = '#ffcc99';
                ctx.fillRect(px - 2, py + 30 + armSwing, 8, 6);
                ctx.fillRect(px + 26, py + 30 - armSwing, 8, 6);

                // Head
                ctx.fillStyle = '#ffcc99';
                ctx.fillRect(px + 8, py + 2, 16, 16);

                // Eyes
                ctx.fillStyle = '#333';
                let eyeX = player.facing > 0 ? 2 : -2;
                ctx.fillRect(px + 12 + eyeX, py + 6, 3, 3);
                ctx.fillRect(px + 18 + eyeX, py + 6, 3, 3);

                // Hard hat
                ctx.fillStyle = player.hardHatColor;
                ctx.fillRect(px + 4, py - 2, 24, 8);
                ctx.fillRect(px + 6, py - 6, 20, 6);
                // Hat brim
                ctx.fillStyle = '#e69500';
                ctx.fillRect(px + 2, py + 4, 28, 4);
                // Hat light
                ctx.fillStyle = '#ffff00';
                ctx.fillRect(px + 14, py - 4, 4, 3);
            }

            // Particles
            for (let p of particles) {
                let alpha = p.life / p.maxLife;
                ctx.fillStyle = p.color;
                ctx.globalAlpha = alpha;
                ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
            }
            ctx.globalAlpha = 1;

            ctx.restore();

            // Foreground construction elements
            // Construction barrier at bottom
            ctx.fillStyle = '#f5a623';
            ctx.fillRect(0, 580, 900, 20);
            ctx.fillStyle = '#000';
            for (let i = 0; i < 900; i += 40) {
                ctx.fillRect(i, 580, 20, 20);
            }

            // Construction sign
            ctx.fillStyle = '#f5a623';
            ctx.fillRect(850, 540, 40, 40);
            ctx.fillStyle = '#000';
            ctx.font = '20px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('⚠', 870, 567);

            ctx.restore();
        }

        function gameLoop() {
            if (!game.running) return;
            update();
            draw();
            requestAnimationFrame(gameLoop);
        }

        // Initial draw
        draw();
    </script>
</body>
</html>

