            --accent-2: #ff6b6b;
            --accent-3: #feca57;
            --accent-4: #48dbfb;
            --accent-5: #ff9ff3;
            --text-primary: #f5f5f5;
            --text-secondary: #a0a0b0;
            --glass: rgba(255, 255, 255, 0.05);
            --glass-border: rgba(255, 255, 255, 0.1);
        }

        body {
            font-family: 'Inter', sans-serif;
            background: var(--bg-primary);
            color: var(--text-primary);
            min-height: 100vh;
            overflow-x: hidden;
            position: relative;
        }

        /* Animated background */
        .bg-animation {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 0;
            overflow: hidden;
            pointer-events: none;
        }

        .bg-animation .orb {
            position: absolute;
            border-radius: 50%;
            filter: blur(80px);
            opacity: 0.3;
            animation: float 20s infinite ease-in-out;
        }

        .orb:nth-child(1) {
            width: 400px;
            height: 400px;
            background: var(--accent-1);
            top: -100px;
            left: -100px;
            animation-delay: 0s;
        }

        .orb:nth-child(2) {
            width: 300px;
            height: 300px;
            background: var(--accent-4);
            top: 50%;
            right: -100px;
            animation-delay: -5s;
        }

        .orb:nth-child(3) {
            width: 350px;
            height: 350px;
            background: var(--accent-5);
            bottom: -100px;
            left: 30%;
            animation-delay: -10s;
        }

        @keyframes float {
            0%, 100% { transform: translate(0, 0) scale(1); }
            25% { transform: translate(50px, -50px) scale(1.1); }
            50% { transform: translate(-30px, 30px) scale(0.9); }
            75% { transform: translate(40px, 20px) scale(1.05); }
        }

        .container {
            position: relative;
            z-index: 1;
            max-width: 700px;
            margin: 0 auto;
            padding: 20px;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }

        /* Screen management */
        .screen {
            display: none;
            width: 100%;
            animation: fadeIn 0.6s ease-out;
        }

        .screen.active {
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(30px); }
            to { opacity: 1; transform: translateY(0); }
        }

        @keyframes slideUp {
            from { opacity: 0; transform: translateY(60px); }
            to { opacity: 1; transform: translateY(0); }
        }

        @keyframes scaleIn {
            from { opacity: 0; transform: scale(0.8); }
            to { opacity: 1; transform: scale(1); }
        }

        @keyframes pulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.05); }
        }

        @keyframes shimmer {
            0% { background-position: -200% center; }
            100% { background-position: 200% center; }
        }

        @keyframes typewriter {
            from { width: 0; }
            to { width: 100%; }
        }

        @keyframes blink {
            50% { border-color: transparent; }
        }

        @keyframes confetti-fall {
            0% { transform: translateY(-100vh) rotate(0deg); opacity: 1; }
            100% { transform: translateY(100vh) rotate(720deg); opacity: 0; }
        }

        @keyframes glow {
            0%, 100% { box-shadow: 0 0 20px rgba(233, 69, 96, 0.3); }
            50% { box-shadow: 0 0 40px rgba(233, 69, 96, 0.6); }
        }

        /* Welcome Screen */
        .welcome-icon {
            font-size: 80px;
            margin-bottom: 20px;
            animation: pulse 2s infinite;
        }

        .welcome-title {
            font-family: 'Playfair Display', serif;
            font-size: 3rem;
            font-weight: 700;
            text-align: center;
            margin-bottom: 10px;
            background: linear-gradient(135deg, var(--accent-1), var(--accent-5), var(--accent-4));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            line-height: 1.2;
        }

        .welcome-subtitle {
            font-size: 1.1rem;
            color: var(--text-secondary);
            text-align: center;
            margin-bottom: 40px;
            max-width: 500px;
            line-height: 1.6;
        }

        .setup-card {
            background: var(--glass);
            backdrop-filter: blur(20px);
            border: 1px solid var(--glass-border);
            border-radius: 24px;
            padding: 40px;
            width: 100%;
            max-width: 500px;
        }

        .setup-card h2 {
            font-family: 'Playfair Display', serif;
            font-size: 1.5rem;
            margin-bottom: 24px;
            text-align: center;
        }

        .form-group {
            margin-bottom: 24px;
        }

        .form-group label {
            display: block;
            font-size: 0.9rem;
            font-weight: 500;
            color: var(--text-secondary);
            margin-bottom: 8px;
        }

        .player-count-selector {
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
            justify-content: center;
        }

        .player-count-btn {
            width: 60px;
            height: 60px;
            border-radius: 16px;
            border: 2px solid var(--glass-border);
            background: var(--glass);
            color: var(--text-primary);
            font-size: 1.3rem;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.3s ease;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .player-count-btn:hover {
            border-color: var(--accent-1);
            background: rgba(233, 69, 96, 0.1);
            transform: translateY(-2px);
        }

        .player-count-btn.selected {
            border-color: var(--accent-1);
            background: rgba(233, 69, 96, 0.2);
            box-shadow: 0 0 20px rgba(233, 69, 96, 0.3);
        }

        .player-names-input {
            display: flex;
            flex-direction: column;
            gap: 12px;
            margin-top: 16px;
        }

        .player-name-input {
            display: flex;
            align-items: center;
            gap: 12px;
            animation: slideUp 0.4s ease-out;
        }

        .player-name-input .player-number {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--accent-1), var(--accent-5));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.85rem;
            font-weight: 700;
            flex-shrink: 0;
        }

        .player-name-input input {
            flex: 1;
            padding: 12px 16px;
            border-radius: 12px;
            border: 2px solid var(--glass-border);
            background: var(--glass);
            color: var(--text-primary);
            font-size: 1rem;
            font-family: 'Inter', sans-serif;
            transition: all 0.3s ease;
            outline: none;
        }

        .player-name-input input:focus {
            border-color: var(--accent-4);
            box-shadow: 0 0 15px rgba(72, 219, 251, 0.2);
        }

        .player-name-input input::placeholder {
            color: var(--text-secondary);
        }

        .btn {
            padding: 16px 32px;
            border-radius: 16px;
            border: none;
            font-size: 1.1rem;
            font-weight: 600;
            font-family: 'Inter', sans-serif;
            cursor: pointer;
            transition: all 0.3s ease;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--accent-1), var(--accent-2));
            color: white;
            box-shadow: 0 4px 15px rgba(233, 69, 96, 0.4);
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 25px rgba(233, 69, 96, 0.5);
        }

        .btn-primary:active {
            transform: translateY(0);
        }

        .btn-secondary {
            background: var(--glass);
            border: 2px solid var(--glass-border);
            color: var(--text-primary);
        }

        .btn-secondary:hover {
            border-color: var(--accent-4);
            background: rgba(72, 219, 251, 0.1);
        }

        .btn-full {
            width: 100%;
        }

        /* Game Screen */
        .game-header {
            width: 100%;
            max-width: 500px;
            margin-bottom: 30px;
            text-align: center;
        }

        .game-header .turn-indicator {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 8px 20px;
            border-radius: 50px;
            background: var(--glass);
            border: 1px solid var(--glass-border);
            font-size: 0.9rem;
            color: var(--text-secondary);
            margin-bottom: 16px;
        }

        .game-header .turn-indicator .dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--accent-3);
            animation: pulse 1.5s infinite;
        }

        .game-header h1 {
            font-family: 'Playfair Display', serif;
            font-size: 2rem;
            margin-bottom: 8px;
        }

        .game-header p {
            color: var(--text-secondary);
            font-size: 0.95rem;
        }

        .game-card {
            background: var(--glass);
            backdrop-filter: blur(20px);
            border: 1px solid var(--glass-border);
            border-radius: 24px;
            padding: 32px;
            width: 100%;
            max-width: 500px;
            margin-bottom: 24px;
        }

        .previous-phrase-container {
            margin-bottom: 24px;
            position: relative;
        }

        .previous-phrase-label {
            font-size: 0.85rem;
            color: var(--text-secondary);
            margin-bottom: 8px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .previous-phrase {
            padding: 16px 20px;
            border-radius: 16px;
            background: rgba(255, 255, 255, 0.03);
            border: 1px dashed var(--glass-border);
            font-family: 'Caveat', cursive;
            font-size: 1.3rem;
            color: var(--text-secondary);
            min-height: 60px;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .previous-phrase.blurred {
            filter: blur(8px);
            user-select: none;
            transition: filter 0.5s ease;
        }

        .previous-phrase.blurred::after {
            content: '🔒 Phrase précédente cachée';
            position: absolute;
            filter: none;
            font-family: 'Inter', sans-serif;
            font-size: 0.9rem;
            color: var(--accent-3);
            font-weight: 500;
        }

        .previous-phrase.revealed {
            filter: none;
            color: var(--text-primary);
        }

        .previous-phrase.revealed::after {
            display: none;
        }

        .phrase-input-container {
            position: relative;
        }

        .phrase-input-container label {
            display: block;
            font-size: 0.85rem;
            color: var(--text-secondary);
            margin-bottom: 8px;
        }

        .phrase-input {
            width: 100%;
            padding: 16px 20px;
            border-radius: 16px;
            border: 2px solid var(--glass-border);
            background: var(--glass);
            color: var(--text-primary);
            font-size: 1.1rem;
            font-family: 'Caveat', cursive;
            line-height: 1.6;
            resize: none;
            outline: none;
            transition: all 0.3s ease;
            min-height: 120px;
        }

        .phrase-input:focus {
            border-color: var(--accent-4);
            box-shadow: 0 0 20px rgba(72, 219, 251, 0.15);
        }

        .phrase-input::placeholder {
            color: var(--text-secondary);
            font-family: 'Inter', sans-serif;
            font-size: 0.95rem;
        }

        .char-count {
            text-align: right;
            font-size: 0.8rem;
            color: var(--text-secondary);
            margin-top: 8px;
        }

        .game-actions {
            display: flex;
            gap: 12px;
            width: 100%;
            max-width: 500px;
        }

        .game-actions .btn {
            flex: 1;
        }

        /* Progress bar */
        .progress-container {
            width: 100%;
            max-width: 500px;
            margin-bottom: 24px;
        }

        .progress-bar {
            height: 6px;
            border-radius: 3px;
            background: var(--glass);
            overflow: hidden;
            margin-bottom: 8px;
        }

        .progress-fill {
            height: 100%;
            border-radius: 3px;
            background: linear-gradient(90deg, var(--accent-1), var(--accent-5), var(--accent-4));
            transition: width 0.5s ease;
            background-size: 200% 100%;
            animation: shimmer 3s infinite linear;
        }

        .progress-text {
            font-size: 0.8rem;
            color: var(--text-secondary);
            text-align: center;
        }

        /* Reveal Screen */
        .reveal-container {
            width: 100%;
            max-width: 600px;
        }

        .reveal-header {
            text-align: center;
            margin-bottom: 40px;
        }

        .reveal-header .icon {
            font-size: 60px;
            margin-bottom: 16px;
            animation: pulse 2s infinite;
        }

        .reveal-header h1 {
            font-family: 'Playfair Display', serif;
            font-size: 2.5rem;
            margin-bottom: 8px;
            background: linear-gradient(135deg, var(--accent-3), var(--accent-1), var(--accent-5));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .reveal-header p {
            color: var(--text-secondary);
            font-size: 1rem;
        }

        .story-card {
            background: var(--glass);
            backdrop-filter: blur(20px);
            border: 1px solid var(--glass-border);
            border-radius: 24px;
            padding: 40px;
            margin-bottom: 30px;
            position: relative;
            overflow: hidden;
        }

        .story-card::before {
            content: '"';
            position: absolute;
            top: -20px;
            left: 20px;
            font-size: 120px;
            font-family: 'Playfair Display', serif;
            color: rgba(233, 69, 96, 0.1);
            line-height: 1;
        }

        .story-phrase {
            font-family: 'Caveat', cursive;
            font-size: 1.4rem;
            line-height: 1.8;
            margin-bottom: 16px;
            padding: 12px 16px;
            border-radius: 12px;
            opacity: 0;
            transform: translateY(20px);
            transition: all 0.6s ease;
            position: relative;
            padding-left: 40px;
        }

        .story-phrase.visible {
            opacity: 1;
            transform: translateY(0);
        }

        .story-phrase::before {
            content: attr(data-author);
            position: absolute;
            left: 12px;
            top: 12px;
            font-family: 'Inter', sans-serif;
            font-size: 0.7rem;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            padding: 4px 10px;
            border-radius: 8px;
            color: white;
        }

        .story-phrase:nth-child(1) { background: rgba(233, 69, 96, 0.1); }
        .story-phrase:nth-child(1)::before { background: var(--accent-1); }
        .story-phrase:nth-child(2) { background: rgba(72, 219, 251, 0.1); }
        .story-phrase:nth-child(2)::before { background: var(--accent-4); }
        .story-phrase:nth-child(3) { background: rgba(255, 159, 243, 0.1); }
        .story-phrase:nth-child(3)::before { background: var(--accent-5); }
        .story-phrase:nth-child(4) { background: rgba(254, 202, 87, 0.1); }
        .story-phrase:nth-child(4)::before { background: var(--accent-3); }
        .story-phrase:nth-child(5) { background: rgba(46, 213, 115, 0.1); }
        .story-phrase:nth-child(5)::before { background: #2ed573; }
        .story-phrase:nth-child(6) { background: rgba(116, 185, 255, 0.1); }
        .story-phrase:nth-child(6)::before { background: #74b9ff; }
        .story-phrase:nth-child(7) { background: rgba(255, 107, 107, 0.1); }
        .story-phrase:nth-child(7)::before { background: var(--accent-2); }
        .story-phrase:nth-child(8) { background: rgba(162, 155, 254, 0.1); }
        .story-phrase:nth-child(8)::before { background: #a29bfe; }

        .story-final {
            font-family: 'Playfair Display', serif;
            font-style: italic;
            font-size: 1.2rem;
            text-align: center;
            color: var(--accent-3);
            margin-top: 24px;
            padding-top: 24px;
            border-top: 1px solid var(--glass-border);
            opacity: 0;
            transition: opacity 1s ease;
        }

        .story-final.visible {
            opacity: 1;
        }

        .reveal-actions {
            display: flex;
            gap: 12px;
            justify-content: center;
            flex-wrap: wrap;
        }

        /* Confetti */
        .confetti-container {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            z-index: 100;
            overflow: hidden;
        }

        .confetti {
            position: absolute;
            width: 10px;
            height: 10px;
            top: -10px;
            animation: confetti-fall linear forwards;
        }

        /* History / Previous phrases display during game */
        .history-container {
            width: 100%;
            max-width: 500px;
            margin-bottom: 24px;
        }

        .history-title {
            font-size: 0.85rem;
            color: var(--text-secondary);
            margin-bottom: 12px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .history-phrase {
            padding: 12px 16px;
            border-radius: 12px;
            margin-bottom: 8px;
            font-size: 0.95rem;
            line-height: 1.5;
            animation: slideUp 0.4s ease-out;
            display: flex;
            align-items: flex-start;
            gap: 12px;
