            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.7rem;
            font-weight: 700;
            flex-shrink: 0;
            color: white;
        }

        .history-phrase .phrase-text {
            flex: 1;
            font-family: 'Caveat', cursive;
            font-size: 1.15rem;
        }

        /* Modal for passing device */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.8);
            backdrop-filter: blur(10px);
            z-index: 50;
            display: none;
            align-items: center;
            justify-content: center;
            padding: 20px;
        }

        .modal-overlay.active {
            display: flex;
        }

        .modal {
            background: var(--bg-secondary);
            border: 1px solid var(--glass-border);
            border-radius: 24px;
            padding: 40px;
            max-width: 450px;
            width: 100%;
            text-align: center;
            animation: scaleIn 0.4s ease-out;
        }

        .modal .icon {
            font-size: 60px;
            margin-bottom: 20px;
        }

        .modal h2 {
            font-family: 'Playfair Display', serif;
            font-size: 1.8rem;
            margin-bottom: 12px;
        }

        .modal p {
            color: var(--text-secondary);
            margin-bottom: 24px;
            line-height: 1.6;
        }

        .modal .player-name-display {
            font-size: 1.3rem;
            font-weight: 700;
            color: var(--accent-4);
            margin-bottom: 24px;
            padding: 12px 24px;
            border-radius: 12px;
            background: rgba(72, 219, 251, 0.1);
            display: inline-block;
        }

        /* Responsive */
        @media (max-width: 600px) {
            .welcome-title {
                font-size: 2.2rem;
            }

            .setup-card, .game-card {
                padding: 24px;
            }

