            display: none !important;
        }

        /* Theme selector */
        .theme-selector {
            display: flex;
            gap: 12px;
            justify-content: center;
            margin-bottom: 24px;
            flex-wrap: wrap;
        }

        .theme-btn {
            padding: 10px 20px;
            border-radius: 12px;
            border: 2px solid var(--glass-border);
