</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const minimapCanvas = document.getElementById('minimapCanvas');
const minimapCtx = minimapCanvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
});

// Game State
let gameState = 'menu'; // menu, playing, gameover
let selectedMap = 'city';
let camera = { x: 0, y: 0 };
let keys = {};
let mouse = { x: 0, y: 0, down: false };
let worldSize = 3000;
let zone = { x: 1500, y: 1500, radius: 1500, targetRadius: 1500, shrinkSpeed: 0.5, phase: 0, timer: 180 };
let players = [];
let bots = [];
let bullets = [];
let pickups = [];
let vehicles = [];
let particles = [];
let buildings = [];
let trees = [];
let explosions = [];
let killFeed = [];
let player = null;
let frameCount = 0;
let lastTime = 0;
let deltaTime = 0;

// Audio Context
let audioCtx = null;
function initAudio() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
}

function playSound(freq, duration, type = 'square', volume = 0.1) {
    if (!audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
    gain.gain.setValueAtTime(volume, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + duration);
}

function playShootSound(weaponType) {
    const sounds = {
        pistol: [800, 0.1, 'square', 0.05],
        shotgun: [200, 0.2, 'sawtooth', 0.1],
        rifle: [600, 0.08, 'square', 0.06],
        sniper: [100, 0.3, 'sawtooth', 0.15],
        smg: [700, 0.05, 'square', 0.04]
    };
    const s = sounds[weaponType] || sounds.pistol;
    playSound(s[0], s[1], s[2], s[3]);
}

function playHitSound() {
    playSound(300, 0.1, 'sine', 0.08);
}

function playExplosionSound() {
    playSound(100, 0.5, 'sawtooth', 0.2);
    playSound(50, 0.8, 'square', 0.15);
}

function playPickupSound() {
    playSound(600, 0.1, 'sine', 0.05);
    playSound(800, 0.1, 'sine', 0.05);
}

// Weapon Definitions
const weapons = {
    pistol: { name: 'Pistol', damage: 15, fireRate: 300, ammo: 12, maxAmmo: 12, reserve: 60, speed: 15, spread: 0.05, reloadTime: 1500, color: '#ffaa00', range: 400 },
    shotgun: { name: 'Shotgun', damage: 10, fireRate: 800, ammo: 6, maxAmmo: 6, reserve: 30, speed: 12, spread: 0.15, reloadTime: 2000, color: '#ff4444', range: 250, pellets: 5 },
    rifle: { name: 'Assault Rifle', damage: 20, fireRate: 100, ammo: 30, maxAmmo: 30, reserve: 120, speed: 20, spread: 0.03, reloadTime: 2500, color: '#44ff44', range: 600 },
    sniper: { name: 'Sniper Rifle', damage: 80, fireRate: 1500, ammo: 5, maxAmmo: 5, reserve: 20, speed: 30, spread: 0.01, reloadTime: 3000, color: '#ff44ff', range: 1000 },
    smg: { name: 'SMG', damage: 12, fireRate: 50, ammo: 25, maxAmmo: 25, reserve: 100, speed: 18, spread: 0.08, reloadTime: 1800, color: '#44aaff', range: 350 }
};

// Map Generation
function generateMap(mapType) {
    buildings = [];
    trees = [];
    pickups = [];
    vehicles = [];

    if (mapType === 'city') {
        // Generate city buildings
        for (let i = 0; i < 80; i++) {
            buildings.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                w: 60 + Math.random() * 120,
                h: 60 + Math.random() * 120,
                color: `hsl(${200 + Math.random() * 40}, 20%, ${20 + Math.random() * 20}%)`,
                type: 'building'
            });
        }
        // Roads
        for (let i = 0; i < 10; i++) {
            buildings.push({
                x: i * 300, y: 0, w: 40, h: worldSize,
                color: '#333', type: 'road'
            });
        }
    } else if (mapType === 'desert') {
        // Desert ruins
        for (let i = 0; i < 40; i++) {
            buildings.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                w: 80 + Math.random() * 100,
                h: 80 + Math.random() * 100,
                color: `hsl(${30 + Math.random() * 20}, 40%, ${40 + Math.random() * 20}%)`,
                type: 'ruin'
            });
        }
        // Cacti
        for (let i = 0; i < 100; i++) {
            trees.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                r: 15,
                type: 'cactus'
            });
        }
    } else if (mapType === 'forest') {
        // Dense forest
        for (let i = 0; i < 200; i++) {
            trees.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                r: 20 + Math.random() * 30,
                type: 'tree'
            });
        }
        // Some clearings with buildings
        for (let i = 0; i < 20; i++) {
            buildings.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                w: 50 + Math.random() * 80,
                h: 50 + Math.random() * 80,
                color: `hsl(${100 + Math.random() * 40}, 30%, ${25 + Math.random() * 15}%)`,
                type: 'hut'
            });
        }
    }

    // Generate pickups
    const weaponKeys = Object.keys(weapons);
    for (let i = 0; i < 150; i++) {
        const type = Math.random();
        if (type < 0.4) {
            // Health pack
            pickups.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                type: 'health',
                amount: 25,
                color: '#00ff00',
                icon: '❤️'
            });
        } else if (type < 0.7) {
            // Ammo
            pickups.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                type: 'ammo',
                amount: 30,
                color: '#ffaa00',
                icon: '🔶'
            });
        } else if (type < 0.85) {
            // Armor
            pickups.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                type: 'armor',
                amount: 50,
                color: '#4488ff',
                icon: '🛡️'
            });
        } else {
            // Weapon
            const wKey = weaponKeys[Math.floor(Math.random() * weaponKeys.length)];
            pickups.push({
                x: Math.random() * worldSize,
                y: Math.random() * worldSize,
                type: 'weapon',
                weapon: wKey,
                color: weapons[wKey].color,
                icon: '🔫'
            });
        }
    }

    // Generate vehicles
    for (let i = 0; i < 15; i++) {
        vehicles.push({
            x: Math.random() * worldSize,
            y: Math.random() * worldSize,
            angle: Math.random() * Math.PI * 2,
            speed: 0,
            maxSpeed: 8,
            health: 200,
            type: 'car',
            color: `hsl(${Math.random() * 360}, 70%, 50%)`,
            occupied: false,
            driver: null
        });
    }
}

// Player Class
class Player {
    constructor(x, y, isBot = false) {
        this.x = x;
        this.y = y;
        this.isBot = isBot;
        this.radius = 15;
        this.speed = 3;
        this.health = 100;
        this.maxHealth = 100;
        this.shield = 0;
        this.maxShield = 100;
        this.armor = 0;
        this.maxArmor = 100;
        this.angle = 0;
        this.weapons = [
            { ...weapons.pistol, currentAmmo: weapons.pistol.ammo, reserveAmmo: weapons.pistol.reserve }
        ];
        this.currentWeapon = 0;
        this.lastShot = 0;
        this reloading = false;
        this.reloadStart = 0;
        this.alive = true;
        this.kills = 0;
        this.inZone = true;
        this.velocity = { x: 0, y: 0 };
        this.name = isBot ? `Bot_${Math.floor(Math.random() * 1000)}` : 'Player';
        this.vehicle = null;
        this.color = isBot ? `hsl(${Math.random() * 360}, 70%, 50%)` : '#ff6b35';
        this.botTarget = null;
        this.botState = 'wander';
        this.botTimer = 0;
        this.botMoveAngle = Math.random() * Math.PI * 2;
    }

    get currentWeaponData() {
        return this.weapons[this.currentWeapon];
    }

    shoot() {
        const now = Date.now();
        const wd = this.currentWeaponData;
        if (!wd || this.reloading) return;
        if (now - this.lastShot < wd.fireRate) return;
        if (wd.currentAmmo <= 0) {
            this.reload();
            return;
        }

        this.lastShot = now;
        wd.currentAmmo--;

        const pellets = wd.pellets || 1;
        for (let i = 0; i < pellets; i++) {
            const spread = (Math.random() - 0.5) * wd.spread * 2;
            const angle = this.angle + spread;
            bullets.push({
                x: this.x + Math.cos(this.angle) * 20,
                y: this.y + Math.sin(this.angle) * 20,
                vx: Math.cos(angle) * wd.speed,
                vy: Math.sin(angle) * wd.speed,
                damage: wd.damage,
                owner: this,
                range: wd.range,
                traveled: 0,
                color: wd.color
            });
        }

        playShootSound(Object.keys(weapons).find(k => weapons[k] === wd) || 'pistol');

        // Muzzle flash
        for (let i = 0; i < 5; i++) {
            particles.push({
                x: this.x + Math.cos(this.angle) * 25,
                y: this.y + Math.sin(this.angle) * 25,
                vx: Math.cos(this.angle + (Math.random() - 0.5) * 0.5) * (3 + Math.random() * 3),
                vy: Math.sin(this.angle + (Math.random() - 0.5) * 0.5) * (3 + Math.random() * 3),
                life: 10,
                maxLife: 10,
                color: wd.color,
                size: 3
            });
        }
    }

    reload() {
        const wd = this.currentWeaponData;
        if (!wd || this.reloading) return;
        if (wd.currentAmmo >= wd.maxAmmo) return;
        if (wd.reserveAmmo <= 0) return;

        this.reloading = true;
        this.reloadStart = Date.now();
        playSound(400, 0.2, 'sine', 0.05);

        setTimeout(() => {
            if (this.reloading && this.alive) {
                const needed = wd.maxAmmo - wd.currentAmmo;
                const available = Math.min(needed, wd.reserveAmmo);
                wd.currentAmmo += available;
                wd.reserveAmmo -= available;
                this.reloading = false;
            }
        }, wd.reloadTime);
    }

    takeDamage(damage, attacker) {
        if (!this.alive) return;

        // Armor absorbs some damage
        if (this.armor > 0) {
            const armorAbsorb = Math.min(this.armor, damage * 0.5);
            this.armor -= armorAbsorb;
            damage -= armorAbsorb;
        }

        // Shield absorbs damage
        if (this.shield > 0) {
            const shieldAbsorb = Math.min(this.shield, damage * 0.7);
            this.shield -= shieldAbsorb;
            damage -= shieldAbsorb;
        }

        this.health -= damage;

        // Blood particles
        for (let i = 0; i < 8; i++) {
            particles.push({
                x: this.x,
                y: this.y,
                vx: (Math.random() - 0.5) * 5,
                vy: (Math.random() - 0.5) * 5,
                life: 30,
                maxLife: 30,
                color: '#ff0000',
                size: 2
            });
        }

        if (this.health <= 0) {
            this.health = 0;
            this.alive = false;
            if (attacker && attacker !== this) {
                attacker.kills++;
                addKillFeed(attacker.name, this.name);
            }
            // Drop loot
            this.weapons.forEach(w => {
                pickups.push({
                    x: this.x + (Math.random() - 0.5) * 30,
                    y: this.y + (Math.random() - 0.5) * 30,
                    type: 'weapon',
                    weapon: Object.keys(weapons).find(k => weapons[k] === w) || 'pistol',
                    color: w.color,
                    icon: '🔫'
                });
            });
            // Death explosion
            for (let i = 0; i < 20; i++) {
                particles.push({
                    x: this.x,
                    y: this.y,
                    vx: (Math.random() - 0.5) * 8,
                    vy: (Math.random() - 0.5) * 8,
                    life: 40,
                    maxLife: 40,
                    color: '#ff6b35',
                    size: 4
                });
            }
            playExplosionSound();
        }
    }

    update() {
        if (!this.alive) return;

        // Zone damage
        const distToZoneCenter = Math.hypot(this.x - zone.x, this.y - zone.y);
        if (distToZoneCenter > zone.radius) {
            this.inZone = false;
            if (frameCount % 60 === 0) {
                this.takeDamage(5, null);
            }
        } else {
            this.inZone = true;
        }

        // Vehicle handling
        if (this.vehicle) {
            this.x = this.vehicle.x;
            this.y = this.vehicle.y;
            this.angle = this.vehicle.angle;
            return;
        }

        // Bot AI
        if (this.isBot) {
            this.updateBot();
        }

        // Movement
        this.x += this.velocity.x;
        this.y += this.velocity.y;

        // World bounds
        this.x = Math.max(this.radius, Math.min(worldSize - this.radius, this.x));
        this.y = Math.max(this.radius, Math.min(worldSize - this.radius, this.y));

        // Building collision
        buildings.forEach(b => {
            if (b.type === 'road') return;
            if (this.x + this.radius > b.x && this.x - this.radius < b.x + b.w &&
                this.y + this.radius > b.y && this.y - this.radius < b.y + b.h) {
                // Push out
                const cx = b.x + b.w / 2;
                const cy = b.y + b.h / 2;
                const dx = this.x - cx;
                const dy = this.y - cy;
                if (Math.abs(dx) / b.w > Math.abs(dy) / b.h) {
                    this.x = dx > 0 ? b.x + b.w + this.radius : b.x - this.radius;
                } else {
                    this.y = dy > 0 ? b.y + b.h + this.radius : b.y - this.radius;
                }
            }
        });

        // Tree collision
        trees.forEach(t => {
            const dist = Math.hypot(this.x - t.x, this.y - t.y);
            if (dist < this.radius + t.r) {
                const angle = Math.atan2(this.y - t.y, this.x - t.x);
                this.x = t.x + Math.cos(angle) * (this.radius + t.r);
                this.y = t.y + Math.sin(angle) * (this.radius + t.r);
            }
        });
    }

    updateBot() {
        this.botTimer++;

        // Find nearest player or bot
        let nearest = null;
        let nearestDist = Infinity;

        [...players, ...bots].forEach(p => {
            if (p === this || !p.alive) return;
            const dist = Math.hypot(p.x - this.x, p.y - this.y);
            if (dist < nearestDist && dist < 500) {
                nearestDist = dist;
                nearest = p;
            }
        });

        // Find nearest pickup
        let nearestPickup = null;
        let nearestPickupDist = Infinity;
        pickups.forEach(p => {
            const dist = Math.hypot(p.x - this.x, p.y - this.y);
            if (dist < nearestPickupDist && dist < 200) {
                nearestPickupDist = dist;
                nearestPickup = p;
            }
        });

        // Zone awareness
        const distToZone = Math.hypot(this.x - zone.x, this.y - zone.y);
        if (distToZone > zone.radius * 0.8) {
            // Move toward zone center
            this.botMoveAngle = Math.atan2(zone.y - this.y, zone.x - this.x);
            this.botState = 'moveToZone';
        } else if (nearest && nearestDist < 400) {
            this.botState = 'combat';
            this.botTarget = nearest;
        } else if (nearestPickup) {
            this.botState = 'collect';
            this.botTarget = nearestPickup;
        } else {
            this.botState = 'wander';
        }

        // Execute state
        switch (this.botState) {
            case 'wander':
                if (this.botTimer % 120 === 0) {
                    this.botMoveAngle = Math.random() * Math.PI * 2;
                }
                this.velocity.x = Math.cos(this.botMoveAngle) * this.speed * 0.5;
                this.velocity.y = Math.sin(this.botMoveAngle) * this.speed * 0.5;
                this.angle = this.botMoveAngle;
                break;

            case 'moveToZone':
                this.velocity.x = Math.cos(this.botMoveAngle) * this.speed;
                this.velocity.y = Math.sin(this.botMoveAngle) * this.speed;
                this.angle = this.botMoveAngle;
                break;

            case 'combat':
                if (this.botTarget && this.botTarget.alive) {
                    const angle = Math.atan2(this.botTarget.y - this.y, this.botTarget.x - this.x);
                    this.angle = angle;
                    const dist = Math.hypot(this.botTarget.x - this.x, this.botTarget.y - this.y);

                    if (dist > 100) {
                        this.velocity.x = Math.cos(angle) * this.speed * 0.7;
                        this.velocity.y = Math.sin(angle) * this.speed * 0.7;
                    } else {
                        this.velocity.x = -Math.cos(angle) * this.speed * 0.3;
                        this.velocity.y = -Math.sin(angle) * this.speed * 0.3;
                    }

                    // Shoot
                    if (dist < 400 && this.botTimer % 10 === 0) {
                        this.shoot();
                    }
                }
                break;

            case 'collect':
                if (this.botTarget) {
                    const angle = Math.atan2(this.botTarget.y - this.y, this.botTarget.x - this.x);
                    this.velocity.x = Math.cos(angle) * this.speed;
                    this.velocity.y = Math.sin(angle) * this.speed;
                    this.angle = angle;

                    if (nearestPickupDist < 30) {
                        // Pick up
                        if (this.botTarget.type === 'health' && this.health < 100) {
                            this.health = Math.min(100, this.health + this.botTarget.amount);
                            removePickup(this.botTarget);
                        } else if (this.botTarget.type === 'armor' && this.armor < 100) {
                            this.armor = Math.min(100, this.armor + this.botTarget.amount);
                            removePickup(this.botTarget);
                        } else if (this.botTarget.type === 'ammo') {
                            this.weapons.forEach(w => w.reserveAmmo += this.botTarget.amount);
                            removePickup(this.botTarget);
                        } else if (this.botTarget.type === 'weapon') {
                            const wKey = this.botTarget.weapon;
                            if (wKey && weapons[wKey]) {
                                const newW = { ...weapons[wKey], currentAmmo: weapons[wKey].ammo, reserveAmmo: weapons[wKey].reserve };
                                if (this.weapons.length < 5) {
                                    this.weapons.push(newW);
                                } else {
                                    this.weapons[this.currentWeapon] = newW;
                                }
                            }
                            removePickup(this.botTarget);
                        }
                    }
                }
                break;
        }
    }
}

function removePickup(pickup) {
    const idx = pickups.indexOf(pickup);
    if (idx > -1) pickups.splice(idx, 1);
}

function addKillFeed(killer, victim) {
    killFeed.unshift({ killer, victim, time: Date.now() });
    if (killFeed.length > 10) killFeed.pop();
    updateKillFeedUI();
}

function updateKillFeedUI() {
    const feed = document.getElementById('killFeed');
    feed.innerHTML = killFeed.map(k =>
        `<div class="kill-entry">${k.killer} ☠️ ${k.victim}</div>`
    ).join('');
}

// Initialize Game
function initGame() {
    generateMap(selectedMap);
    players = [];
    bots = [];
    bullets = [];
    particles = [];
    explosions = [];
    killFeed = [];

    // Create player
    player = new Player(worldSize / 2, worldSize / 2, false);
    players.push(player);

    // Create bots
    for (let i = 0; i < 99; i++) {
        const bot = new Player(
            Math.random() * worldSize,
            Math.random() * worldSize,
            true
        );
        // Give bots random weapons
        const weaponKeys = Object.keys(weapons);
        const randomWeapon = weaponKeys[Math.floor(Math.random() * weaponKeys.length)];
        bot.weapons.push({ ...weapons[randomWeapon], currentAmmo: weapons[randomWeapon].ammo, reserveAmmo: weapons[randomWeapon].reserve });
        bot.currentWeapon = 1;
        bots.push(bot);
    }

    // Reset zone
    zone = {
        x: worldSize / 2,
        y: worldSize / 2,
        radius: worldSize * 0.6,
        targetRadius: worldSize * 0.6,
        shrinkSpeed: 0.3,
        phase: 0,
        timer: 180
    };

    gameState = 'playing';
    document.getElementById('menuScreen').style.display = 'none';
    document.getElementById('hud').style.display = 'block';
    document.getElementById('gameOverScreen').style.display = 'none';
}

// Input Handling
document.addEventListener('keydown', (e) => {
    keys[e.key.toLowerCase()] = true;

    if (gameState !== 'playing') return;

    // Weapon switching
    if (e.key >= '1' && e.key <= '5') {
        const slot = parseInt(e.key) - 1;
        if (slot < player.weapons.length) {
            player.currentWeapon = slot;
            player.reloading = false;
            updateHUD();
        }
    }

    // Reload
    if (e.key.toLowerCase() === 'r') {
        player.reload();
    }

    // Interact
    if (e.key.toLowerCase() === 'e') {
        interact();
    }

    // Vehicle
    if (e.key.toLowerCase() === 'f') {
        toggleVehicle();
    }
});

document.addEventListener('keyup', (e) => {
    keys[e.key.toLowerCase()] = false;
});

canvas.addEventListener('mousemove', (e) => {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
});

canvas.addEventListener('mousedown', (e) => {
    mouse.down = true;
    initAudio();
});

canvas.addEventListener('mouseup', () => {
    mouse.down = false;
});

canvas.addEventListener('contextmenu', (e) => e.preventDefault());

function interact() {
    // Pick up nearby items
    pickups.forEach(p => {
        const dist = Math.hypot(p.x - player.x, p.y - player.y);
        if (dist < 40) {
            if (p.type === 'health' && player.health < 100) {
                player.health = Math.min(100, player.health + p.amount);
                removePickup(p);
                playPickupSound();
            } else if (p.type === 'armor' && player.armor < 100) {
                player.armor = Math.min(100, player.armor + p.amount);
                removePickup(p);
                playPickupSound();
            } else if (p.type === 'ammo') {
                player.weapons.forEach(w => w.reserveAmmo += p.amount);
                removePickup(p);
                playPickupSound();
            } else if (p.type === 'weapon') {
                const wKey = p.weapon;
                if (wKey && weapons[wKey]) {
                    const newW = { ...weapons[wKey], currentAmmo: weapons[wKey].ammo, reserveAmmo: weapons[wKey].reserve };
                    if (player.weapons.length < 5) {
                        player.weapons.push(newW);
                    } else {
                        player.weapons[player.currentWeapon] = newW;
                    }
                    playPickupSound();
                }
                removePickup(p);
            }
        }
    });
}

function toggleVehicle() {
    if (player.vehicle) {
        // Exit vehicle
        player.vehicle.occupied = false;
        player.vehicle.driver = null;
        player.vehicle = null;
        player.x += Math.cos(player.angle + Math.PI / 2) * 30;
        player.y += Math.sin(player.angle + Math.PI / 2) * 30;
    } else {
        // Find nearest vehicle
        let nearestVehicle = null;
        let nearestDist = Infinity;
        vehicles.forEach(v => {
            const dist = Math.hypot(v.x - player.x, v.y - player.y);
            if (dist < nearestDist && dist < 60) {
                nearestDist = dist;
                nearestVehicle = v;
            }
        });

        if (nearestVehicle) {
            player.vehicle = nearestVehicle;
            nearestVehicle.occupied = true;
            nearestVehicle.driver = player;
            playPickupSound();
        }
    }
}

// Update HUD
function updateHUD() {
    if (!player) return;

    document.getElementById('healthFill').style.width = `${player.health}%`;
    document.getElementById('shieldFill').style.width = `${player.shield}%`;
    document.getElementById('armorFill').style.width = `${player.armor}%`;

    const wd = player.currentWeaponData;
    if (wd) {
        document.getElementById('weaponName').textContent = wd.name + (player.reloading ? ' (RELOADING)' : '');
        document.getElementById('ammoInfo').textContent = `${wd.currentAmmo} / ${wd.reserveAmmo}`;
    }

    const aliveCount = players.filter(p => p.alive).length + bots.filter(b => b.alive).length;
    document.getElementById('aliveCount').textContent = `👥 Alive: ${aliveCount}`;

    const minutes = Math.floor(zone.timer / 60);
    const seconds = Math.floor(zone.timer % 60);
    document.getElementById('zoneTimer').textContent = `ZONE IN: ${minutes}:${seconds.toString().padStart(2, '0')}`;

    // Update inventory slots
    document.querySelectorAll('.inv-slot').forEach((slot, i) => {
        slot.classList.toggle('active', i === player.currentWeapon);
        if (player.weapons[i]) {
            slot.childNodes[1].textContent = '🔫';
        }
    });
}

// Main Game Loop
function gameLoop(timestamp) {
    deltaTime = timestamp - lastTime;
    lastTime = timestamp;
    frameCount++;

    if (gameState === 'playing') {
        update();
        render();
        renderMinimap();
        updateHUD();
    }

    requestAnimationFrame(gameLoop);
}

function update() {
    // Player input
    if (player && player.alive && !player.vehicle) {
        player.velocity.x = 0;
        player.velocity.y = 0;

        if (keys['w'] || keys['arrowup']) player.velocity.y = -player.speed;
        if (keys['s'] || keys['arrowdown']) player.velocity.y = player.speed;
        if (keys['a'] || keys['arrowleft']) player.velocity.x = -player.speed;
        if (keys['d'] || keys['arrowright']) player.velocity.x = player.speed;

        // Normalize diagonal movement
        if (player.velocity.x !== 0 && player.velocity.y !== 0) {
            player.velocity.x *= 0.707;
            player.velocity.y *= 0.707;
        }

        // Aim
        const worldMouseX = mouse.x + camera.x;
        const worldMouseY = mouse.y + camera.y;
        player.angle = Math.atan2(worldMouseY - player.y, worldMouseX - player.x);

        // Shoot
        if (mouse.down) {
            player.shoot();
        }
    }

    // Vehicle update
    if (player && player.vehicle) {
        const v = player.vehicle;
        if (keys['w'] || keys['arrowup']) {
            v.speed = Math.min(v.speed + 0.2, v.maxSpeed);
        } else if (keys['s'] || keys['arrowdown']) {
            v.speed = Math.max(v.speed - 0.2, -v.maxSpeed / 2);
        } else {
            v.speed *= 0.95;
        }

        if (keys['a'] || keys['arrowleft']) v.angle -= 0.03;
        if (keys['d'] || keys['arrowright']) v.angle += 0.03;

        v.x += Math.cos(v.angle) * v.speed;
        v.y += Math.sin(v.angle) * v.speed;

        v.x = Math.max(30, Math.min(worldSize - 30, v.x));
        v.y = Math.max(30, Math.min(worldSize - 30, v.y));

        player.x = v.x;
        player.y = v.y;
    }

    // Update player
    if (player) player.update();

    // Update bots
    bots.forEach(bot => bot.update());

    // Update bullets
    bullets.forEach((bullet, i) => {
        bullet.x += bullet.vx;
        bullet.y += bullet.vy;
        bullet.traveled += Math.hypot(bullet.vx, bullet.vy);

        // Range check
        if (bullet.traveled > bullet.range) {
            bullets.splice(i, 1);
            return;
        }

        // Building collision
        let hitBuilding = false;
        buildings.forEach(b => {
            if (b.type === 'road') return;
            if (bullet.x > b.x && bullet.x < b.x + b.w &&
                bullet.y > b.y && bullet.y < b.y + b.h) {
                hitBuilding = true;
                // Spark particles
                for (let j = 0; j < 3; j++) {
                    particles.push({
                        x: bullet.x, y: bullet.y,
                        vx: (Math.random() - 0.5) * 4,
                        vy: (Math.random() - 0.5) * 4,
                        life: 15, maxLife: 15,
                        color: '#ffff00', size: 2
                    });
                }
            }
        });

        if (hitBuilding) {
            bullets.splice(i, 1);
            return;
        }

        // Hit players/bots
        const allTargets = [...players, ...bots];
        for (let j = allTargets.length - 1; j >= 0; j--) {
            const target = allTargets[j];
            if (!target.alive || target === bullet.owner) continue;

            const dist = Math.hypot(bullet.x - target.x, bullet.y - target.y);
            if (dist < target.radius + 5) {
                target.takeDamage(bullet.damage, bullet.owner);
                bullets.splice(i, 1);
                playHitSound();
                break;
            }
        }
    });

    // Update particles
    particles.forEach((p, i) => {
        p.x += p.vx;
        p.y += p.vy;
        p.life--;
        p.vx *= 0.95;
        p.vy *= 0.95;
        if (p.life <= 0) particles.splice(i, 1);
    });

    // Zone shrinking
    zone.timer -= deltaTime / 1000;
    if (zone.timer <= 0) {
        zone.phase++;
        zone.targetRadius = Math.max(100, zone.radius * 0.6);
        zone.timer = 120 - zone.phase * 10;
        if (zone.timer < 30) zone.timer = 30;
    }

    if (zone.radius > zone.targetRadius) {
        zone.radius -= zone.shrinkSpeed;
    }

    // Check game over
    const alivePlayers = players.filter(p => p.alive).length;
    const aliveBots = bots.filter(b => b.alive).length;

    if (!player.alive) {
        gameState = 'gameover';
        document.getElementById('gameOverScreen').style.display = 'flex';
        document.getElementById('gameOverTitle').textContent = 'ELIMINATED';
        document.getElementById('gameOverStats').textContent = `Kills: ${player.kills}`;
        document.getElementById('gameOverRank').textContent = `Rank: #${alivePlayers + aliveBots}`;
        document.getElementById('hud').style.display = 'none';
    } else if (aliveBots === 0 && alivePlayers <= 1) {
        gameState = 'gameover';
        document.getElementById('gameOverScreen').style.display = 'flex';
        document.getElementById('gameOverTitle').textContent = '🏆 WINNER WINNER!';
        document.getElementById('gameOverStats').textContent = `Kills: ${player.kills}`;
        document.getElementById('gameOverRank').textContent = `Rank: #1`;
        document.getElementById('hud').style.display = 'none';
    }

    // Camera follow player
    if (player) {
        camera.x = player.x - canvas.width / 2;
        camera.y = player.y - canvas.height / 2;
    }

    // Clamp camera
    camera.x = Math.max(0, Math.min(worldSize - canvas.width, camera.x));
    camera.y = Math.max(0, Math.min(worldSize - canvas.height, camera.y));
}

function render() {
    // Clear
    ctx.fillStyle = getMapBackgroundColor();
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    // Draw ground grid
    drawGround();

    // Draw buildings
    buildings.forEach(b => {
        if (b.type === 'road') {
            ctx.fillStyle = '#444';
            ctx.fillRect(b.x, b.y, b.w, b.h);
            // Road lines
            ctx.strokeStyle = '#666';
            ctx.setLineDash([20, 20]);
            ctx.lineWidth = 2;
            if (b.w < b.h) {
                ctx.beginPath();
                ctx.moveTo(b.x + b.w / 2, b.y);
                ctx.lineTo(b.x + b.w / 2, b.y + b.h);
                ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(b.x, b.y + b.h / 2);
                ctx.lineTo(b.x + b.w, b.y + b.h / 2);
                ctx.stroke();
            }
            ctx.setLineDash([]);
        } else {
            // Building shadow
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.fillRect(b.x + 10, b.y + 10, b.w, b.h);

            // Building
            ctx.fillStyle = b.color;
            ctx.fillRect(b.x, b.y, b.w, b.h);

            // Building border
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 2;
            ctx.strokeRect(b.x, b.y, b.w, b.h);

            // Windows
            if (b.type === 'building') {
                ctx.fillStyle = 'rgba(255,255,150,0.3)';
                for (let wx = b.x + 10; wx < b.x + b.w - 10; wx += 20) {
                    for (let wy = b.y + 10; wy < b.y + b.h - 10; wy += 20) {
                        ctx.fillRect(wx, wy, 8, 8);
                    }
                }
            }
        }
    });

    // Draw trees
    trees.forEach(t => {
        // Tree shadow
        ctx.fillStyle = 'rgba(0,0,0,0.2)';
        ctx.beginPath();
        ctx.ellipse(t.x + 5, t.y + 5, t.r, t.r * 0.7, 0, 0, Math.PI * 2);
        ctx.fill();

        if (t.type === 'tree') {
            // Tree trunk
            ctx.fillStyle = '#8B4513';
            ctx.fillRect(t.x - 3, t.y - 3, 6, 6);

            // Tree canopy
            ctx.fillStyle = '#228B22';
            ctx.beginPath();
            ctx.arc(t.x, t.y, t.r, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = '#32CD32';
            ctx.beginPath();
            ctx.arc(t.x - 3, t.y - 3, t.r * 0.7, 0, Math.PI * 2);
            ctx.fill();
        } else if (t.type === 'cactus') {
            ctx.fillStyle = '#228B22';
            ctx.fillRect(t.x - 5, t.y - 20, 10, 40);
            ctx.fillRect(t.x - 15, t.y - 10, 10, 5);
            ctx.fillRect(t.x - 15, t.y - 15, 5, 15);
            ctx.fillRect(t.x + 5, t.y - 5, 10, 5);
            ctx.fillRect(t.x + 10, t.y - 10, 5, 15);
        }
    });

    // Draw pickups
    pickups.forEach(p => {
        const pulse = Math.sin(frameCount * 0.05) * 3;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, 10 + pulse, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#fff';
        ctx.font = '16px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(p.icon, p.x, p.y);

        // Glow
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 10;
        ctx.beginPath();
        ctx.arc(p.x, p.y, 10 + pulse, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;
    });

    // Draw vehicles
    vehicles.forEach(v => {
        ctx.save();
        ctx.translate(v.x, v.y);
        ctx.rotate(v.angle);

        // Vehicle shadow
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fillRect(-20 + 3, -10 + 3, 40, 20);

        // Vehicle body
        ctx.fillStyle = v.color;
        ctx.fillRect(-20, -10, 40, 20);

        // Vehicle details
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fillRect(-15, -8, 10, 16); // windshield
        ctx.fillRect(10, -8, 8, 16); // rear

        // Wheels
        ctx.fillStyle = '#333';
        ctx.fillRect(-18, -12, 8, 4);
        ctx.fillRect(-18, 8, 8, 4);
        ctx.fillRect(10, -12, 8, 4);
        ctx.fillRect(10, 8, 8, 4);

        ctx.restore();
    });

    // Draw bullets
    bullets.forEach(b => {
        ctx.fillStyle = b.color;
        ctx.shadowColor = b.color;
        ctx.shadowBlur = 5;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;

        // Bullet trail
        ctx.strokeStyle = b.color;
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        ctx.beginPath();
        ctx.moveTo(b.x, b.y);
        ctx.lineTo(b.x - b.vx * 3, b.y - b.vy * 3);
        ctx.stroke();
        ctx.globalAlpha = 1;
    });

    // Draw players/bots
    [...players, ...bots].forEach(p => {
        if (!p.alive) return;

        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.angle);

        // Shadow
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.beginPath();
        ctx.ellipse(3, 3, p.radius, p.radius * 0.7, 0, 0, Math.PI * 2);
        ctx.fill();

        // Body
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(0, 0, p.radius, 0, Math.PI * 2);
        ctx.fill();

        // Body outline
        ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Gun
        ctx.fillStyle = '#333';
        ctx.fillRect(10, -3, 15, 6);

        // Head
        ctx.fillStyle = p === player ? '#ff6b35' : '#fff';
        ctx.beginPath();
        ctx.arc(0, 0, 8, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();

        // Health bar
        if (p !== player) {
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(p.x - 20, p.y - 25, 40, 4);
            ctx.fillStyle = p.health > 50 ? '#00ff00' : p.health > 25 ? '#ffaa00' : '#ff0000';
            ctx.fillRect(p.x - 20, p.y - 25, 40 * (p.health / 100), 4);
        }

        // Name
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(p.name, p.x, p.y - 30);
    });

    // Draw particles
    particles.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (p.life / p.maxLife), 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1;

    // Draw zone
    ctx.strokeStyle = '#ff4444';
    ctx.lineWidth = 3;
    ctx.setLineDash([10, 10]);
    ctx.beginPath();
    ctx.arc(zone.x, zone.y, zone.radius, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // Zone damage area
    ctx.fillStyle = 'rgba(255,0,0,0.1)';
    ctx.beginPath();
    ctx.rect(camera.x, camera.y, canvas.width, canvas.height);
    ctx.arc(zone.x, zone.y, zone.radius, 0, Math.PI * 2, true);
    ctx.fill();

    ctx.restore();

    // Draw crosshair
    drawCrosshair();
}

function getMapBackgroundColor() {
    switch (selectedMap) {
        case 'city': return '#2a2a2a';
        case 'desert': return '#c2a661';
        case 'forest': return '#2d5a1e';
        default: return '#2a2a2a';
    }
}

function drawGround() {
    const gridSize = 100;
    const startX = Math.floor(camera.x / gridSize) * gridSize;
    const startY = Math.floor(camera.y / gridSize) * gridSize;

    ctx.strokeStyle = 'rgba(255,255,255,0.05)';
    ctx.lineWidth = 1;

    for (let x = startX; x < camera.x + canvas.width + gridSize; x += gridSize) {
        ctx.beginPath();
        ctx.moveTo(x, camera.y);
        ctx.lineTo(x, camera.y + canvas.height);
        ctx.stroke();
    }

    for (let y = startY; y < camera.y + canvas.height + gridSize; y += gridSize) {
        ctx.beginPath();
        ctx.moveTo(camera.x, y);
        ctx.lineTo(camera.x + canvas.width, y);
        ctx.stroke();
    }
}

function drawCrosshair() {
    const cx = mouse.x;
    const cy = mouse.y;

    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;

    // Top
    ctx.beginPath();
    ctx.moveTo(cx, cy - 15);
    ctx.lineTo(cx, cy - 5);
    ctx.stroke();

    // Bottom
    ctx.beginPath();
    ctx.moveTo(cx, cy + 5);
    ctx.lineTo(cx, cy + 15);
    ctx.stroke();

    // Left
    ctx.beginPath();
    ctx.moveTo(cx - 15, cy);
    ctx.lineTo(cx - 5, cy);
    ctx.stroke();

    // Right
    ctx.beginPath();
    ctx.moveTo(cx + 5, cy);
    ctx.lineTo(cx + 15, cy);
    ctx.stroke();

    // Center dot
    ctx.fillStyle = '#ff6b35';
    ctx.beginPath();
    ctx.arc(cx, cy, 2, 0, Math.PI * 2);
    ctx.fill();
}

function renderMinimap() {
    minimapCtx.fillStyle = 'rgba(0,0,0,0.8)';
    minimapCtx.fillRect(0, 0, 200, 200);

    const scale = 200 / worldSize;

    // Draw zone
    minimapCtx.strokeStyle = '#ff4444';
    minimapCtx.lineWidth = 2;
    minimapCtx.beginPath();
    minimapCtx.arc(zone.x * scale, zone.y * scale, zone.radius * scale, 0, Math.PI * 2);
    minimapCtx.stroke();

    // Draw buildings
    minimapCtx.fillStyle = 'rgba(255,255,255,0.3)';
    buildings.forEach(b => {
        if (b.type === 'road') return;
        minimapCtx.fillRect(b.x * scale, b.y * scale, Math.max(2, b.w * scale), Math.max(2, b.h * scale));
    });

    // Draw bots
    bots.forEach(b => {
        if (!b.alive) return;
        minimapCtx.fillStyle = '#ff4444';
        minimapCtx.beginPath();
        minimapCtx.arc(b.x * scale, b.y * scale, 2, 0, Math.PI * 2);
        minimapCtx.fill();
    });

    // Draw player
    if (player && player.alive) {
        minimapCtx.fillStyle = '#00ff00';
        minimapCtx.beginPath();
        minimapCtx.arc(player.x * scale, player.y * scale, 3, 0, Math.PI * 2);
        minimapCtx.fill();

        // Player direction
        minimapCtx.strokeStyle = '#00ff00';
        minimapCtx.lineWidth = 1;
        minimapCtx.beginPath();
        minimapCtx.moveTo(player.x * scale, player.y * scale);
        minimapCtx.lineTo(
            player.x * scale + Math.cos(player.angle) * 10,
            player.y * scale + Math.sin(player.angle) * 10
        );
        minimapCtx.stroke();
    }

    // Viewport rectangle
    minimapCtx.strokeStyle = 'rgba(255,255,255,0.5)';
    minimapCtx.lineWidth = 1;
    minimapCtx.strokeRect(
        camera.x * scale,
        camera.y * scale,
        canvas.width * scale,
        canvas.height * scale
    );
}

