}

#start-screen h1 {
    font-size: 64px;
    color: #fff;
    text-shadow: 0 0 30px rgba(0, 150, 255, 0.8), 0 0 60px rgba(0, 100, 255, 0.4);
    margin-bottom: 20px;
    letter-spacing: 4px;
}

#start-screen p, #game-over-screen p {
    color: rgba(255, 255, 255, 0.7);
    font-size: 18px;
    margin-bottom: 30px;
}

.btn {
    padding: 15px 50px;
    font-size: 22px;
    font-weight: bold;
    color: #fff;
    background: linear-gradient(135deg, #0066ff, #00ccff);
