    text-shadow: 0 0 30px rgba(255, 0, 64, 0.8);
    margin-bottom: 10px;
}

#final-score {
    font-size: 32px;
    color: #fff;
    margin-bottom: 30px;
}

#wave-display {
    position: absolute;
    top: 50px;
    left: 20px;
    color: rgba(255, 255, 255, 0.6);
    font-size: 16px;
    z-index: 11;
}

#combo-display {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: #ffcc00;
    font-size: 36px;
    font-weight: bold;
    text-shadow: 0 0 20px rgba(255, 200, 0, 0.8);
    z-index: 11;
    opacity: 0;
    transition: opacity 0.3s;
}

