</style>
</head>
<body>

<canvas id="gameCanvas"></canvas>

<div id="ui-overlay">
    <div id="score-display">Score: 0</div>
    <div id="wave-display">Wave: 1</div>
    <div id="health-text">HP</div>
    <div id="health-bar-container">
        <div id="health-bar"></div>
    </div>
    <div id="combo-display"></div>
    <div id="powerup-display"></div>
</div>

<div id="start-screen">
    <h1>COSMIC DEFENDER</h1>
    <p>Defend the galaxy from alien invaders!</p>
    <p style="font-size:14px; margin-bottom:20px;">WASD / Arrow Keys to move &nbsp;|&nbsp; Mouse to aim &nbsp;|&nbsp; Click to shoot</p>
    <button class="btn" id="start-btn">START GAME</button>
</div>

<div id="game-over-screen" style="display:none;">
    <h2>GAME OVER</h2>
    <div id="final-score">Score: 0</div>
    <p id="final-wave">Wave: 1</p>
    <button class="btn" id="restart-btn">PLAY AGAIN</button>
</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
});

// Audio context for sound effects
const AudioContext = window.AudioContext || window.webkitAudioContext;
const audioCtx = new AudioContext();

function playSound(freq, type, duration, volume = 0.1) {
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
    gain.gain.setValueAtTime(volume, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + duration);
}

function playShootSound() {
    playSound(800, 'square', 0.1, 0.05);
}

function playExplosionSound() {
    playSound(100, 'sawtooth', 0.3, 0.1);
    playSound(50, 'square', 0.4, 0.08);
}

function playPowerupSound() {
    playSound(600, 'sine', 0.1, 0.1);
    setTimeout(() => playSound(800, 'sine', 0.1, 0.1), 100);
    setTimeout(() => playSound(1000, 'sine', 0.2, 0.1), 200);
}

function playHitSound() {
    playSound(200, 'triangle', 0.15, 0.08);
}

// Game state
let gameRunning = false;
let score = 0;
let wave = 1;
let combo = 0;
let comboTimer = 0;
let lastTime = 0;
let enemySpawnTimer = 0;
let enemySpawnRate = 2000;
let particles = [];
let bullets = [];
let enemies = [];
let powerups = [];
let stars = [];
let player = null;
let mouse = { x: canvas.width / 2, y: canvas.height / 2 };
let keys = {};
let screenShake = 0;

// Initialize stars
function initStars() {
    stars = [];
    for (let i = 0; i < 200; i++) {
        stars.push({
            x: Math.random() * canvas.width,
            y: Math.random() * canvas.height,
            size: Math.random() * 2 + 0.5,
            speed: Math.random() * 0.5 + 0.1,
            brightness: Math.random()
        });
    }
}

// Player class
class Player {
    constructor() {
        this.x = canvas.width / 2;
        this.y = canvas.height / 2;
        this.radius = 20;
        this.speed = 5;
        this.health = 100;
        this.maxHealth = 100;
        this.shootCooldown = 0;
        this.shootRate = 150;
        this.bulletDamage = 25;
        this.trail = [];
        this.powerup = null;
        this.powerupTimer = 0;
        this.invincible = false;
        this.invincibleTimer = 0;
    }

    update(dt) {
        // Movement
        let dx = 0;
        let dy = 0;
        if (keys['ArrowUp'] || keys['w'] || keys['W']) dy -= 1;
        if (keys['ArrowDown'] || keys['s'] || keys['S']) dy += 1;
        if (keys['ArrowLeft'] || keys['a'] || keys['A']) dx -= 1;
        if (keys['ArrowRight'] || keys['d'] || keys['D']) dx += 1;

        if (dx !== 0 && dy !== 0) {
            dx *= 0.707;
            dy *= 0.707;
        }

        this.x += dx * this.speed;
        this.y += dy * this.speed;

        // Boundary check
        this.x = Math.max(this.radius, Math.min(canvas.width - this.radius, this.x));
        this.y = Math.max(this.radius, Math.min(canvas.height - this.radius, this.y));

        // Trail
        this.trail.push({ x: this.x, y: this.y, alpha: 1 });
        if (this.trail.length > 10) this.trail.shift();
        this.trail.forEach(t => t.alpha -= 0.1);

        // Shooting
        if (this.shootCooldown > 0) this.shootCooldown -= dt;
        if (keys[' '] || keys['mouse']) {
            this.shoot();
        }

        // Powerup timer
        if (this.powerupTimer > 0) {
            this.powerupTimer -= dt;
            if (this.powerupTimer <= 0) {
                this.powerup = null;
                document.getElementById('powerup-display').textContent = '';
            }
        }

        // Invincibility timer
        if (this.invincibleTimer > 0) {
            this.invincibleTimer -= dt;
            if (this.invincibleTimer <= 0) {
                this.invincible = false;
            }
        }
    }

    shoot() {
        if (this.shootCooldown > 0) return;

        const angle = Math.atan2(mouse.y - this.y, mouse.x - this.x);
        const bulletSpeed = 12;

        if (this.powerup === 'triple') {
            for (let i = -1; i <= 1; i++) {
                const spreadAngle = angle + i * 0.15;
                bullets.push({
                    x: this.x,
                    y: this.y,
                    vx: Math.cos(spreadAngle) * bulletSpeed,
                    vy: Math.sin(spreadAngle) * bulletSpeed,
                    radius: 4,
                    damage: this.bulletDamage,
                    color: '#00ffcc',
                    life: 100
                });
            }
        } else if (this.powerup === 'rapid') {
            bullets.push({
                x: this.x,
                y: this.y,
                vx: Math.cos(angle) * bulletSpeed * 1.5,
                vy: Math.sin(angle) * bulletSpeed * 1.5,
                radius: 3,
                damage: this.bulletDamage * 0.7,
                color: '#ffcc00',
                life: 80
            });
            this.shootCooldown = 50;
        } else {
            bullets.push({
                x: this.x,
                y: this.y,
                vx: Math.cos(angle) * bulletSpeed,
                vy: Math.sin(angle) * bulletSpeed,
                radius: 4,
                damage: this.bulletDamage,
                color: '#00ccff',
                life: 100
            });
            this.shootCooldown = this.shootRate;
        }

        playShootSound();
    }

    takeDamage(damage) {
        if (this.invincible) return;
        this.health -= damage;
        this.invincible = true;
        this.invincibleTimer = 1000;
        screenShake = 10;
        playHitSound();

        if (this.health <= 0) {
            this.health = 0;
            gameOver();
        }

        updateHealthBar();
    }

    draw() {
        // Trail
        this.trail.forEach((t, i) => {
            if (t.alpha > 0) {
                ctx.beginPath();
                ctx.arc(t.x, t.y, this.radius * 0.5 * t.alpha, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(0, 150, 255, ${t.alpha * 0.3})`;
                ctx.fill();
            }
        });

        // Invincibility flash
        if (this.invincible && Math.floor(Date.now() / 100) % 2 === 0) return;

        // Ship body
        ctx.save();
        ctx.translate(this.x, this.y);

        const angle = Math.atan2(mouse.y - this.y, mouse.x - this.x);
        ctx.rotate(angle);

        // Main body
        ctx.beginPath();
        ctx.moveTo(25, 0);
        ctx.lineTo(-15, -15);
        ctx.lineTo(-10, 0);
        ctx.lineTo(-15, 15);
        ctx.closePath();

        const gradient = ctx.createLinearGradient(-15, 0, 25, 0);
        gradient.addColorStop(0, '#0044aa');
        gradient.addColorStop(1, '#00aaff');
        ctx.fillStyle = gradient;
        ctx.fill();
        ctx.strokeStyle = '#00ccff';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Cockpit
        ctx.beginPath();
        ctx.arc(5, 0, 5, 0, Math.PI * 2);
        ctx.fillStyle = '#00ffcc';
        ctx.fill();

        // Engine glow
        ctx.beginPath();
        ctx.arc(-12, 0, 8, 0, Math.PI * 2);
        const engineGradient = ctx.createRadialGradient(-12, 0, 0, -12, 0, 8);
        engineGradient.addColorStop(0, 'rgba(0, 150, 255, 0.8)');
        engineGradient.addColorStop(1, 'rgba(0, 150, 255, 0)');
        ctx.fillStyle = engineGradient;
        ctx.fill();

        ctx.restore();

        // Powerup indicator
        if (this.powerup) {
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.radius + 10, 0, Math.PI * 2);
            ctx.strokeStyle = this.powerup === 'triple' ? '#00ffcc' : '#ffcc00';
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 5]);
            ctx.stroke();
            ctx.setLineDash([]);
        }
    }
}

// Enemy class
class Enemy {
    constructor(type = 'basic') {
        this.type = type;
        this.radius = 15;
        this.speed = 2;
        this.health = 50;
        this.maxHealth = 50;
        this.scoreValue = 100;
        this.shootCooldown = 0;
        this.angle = 0;
        this.spawnTime = Date.now();

        // Spawn from edges
        const side = Math.floor(Math.random() * 4);
        switch (side) {
            case 0: this.x = Math.random() * canvas.width; this.y = -30; break;
            case 1: this.x = canvas.width + 30; this.y = Math.random() * canvas.height; break;
            case 2: this.x = Math.random() * canvas.width; this.y = canvas.height + 30; break;
            case 3: this.x = -30; this.y = Math.random() * canvas.height; break;
        }

        switch (type) {
            case 'basic':
                this.radius = 15;
                this.speed = 2 + wave * 0.2;
                this.health = 50 + wave * 10;
                this.maxHealth = this.health;
                this.scoreValue = 100;
                this.color = '#ff4444';
                break;
            case 'fast':
                this.radius = 12;
                this.speed = 4 + wave * 0.3;
                this.health = 30 + wave * 5;
                this.maxHealth = this.health;
                this.scoreValue = 150;
                this.color = '#ffaa00';
                break;
            case 'tank':
                this.radius = 25;
                this.speed = 1 + wave * 0.1;
                this.health = 150 + wave * 20;
                this.maxHealth = this.health;
                this.scoreValue = 300;
                this.color = '#aa44ff';
                break;
            case 'shooter':
                this.radius = 18;
                this.speed = 1.5 + wave * 0.15;
                this.health = 80 + wave * 15;
                this.maxHealth = this.health;
                this.scoreValue = 200;
                this.color = '#ff44aa';
                this.shootCooldown = 2000;
                break;
        }
    }

    update(dt) {
        // Move towards player
        const angle = Math.atan2(player.y - this.y, player.x - this.x);
        this.x += Math.cos(angle) * this.speed;
        this.y += Math.sin(angle) * this.speed;

        this.angle = angle;

        // Shooter enemies fire bullets
        if (this.type === 'shooter') {
            this.shootCooldown -= dt;
            if (this.shootCooldown <= 0) {
                this.shootCooldown = 2000;
                const bulletAngle = Math.atan2(player.y - this.y, player.x - this.x);
                enemies.push({
                    x: this.x,
                    y: this.y,
                    vx: Math.cos(bulletAngle) * 4,
                    vy: Math.sin(bulletAngle) * 4,
                    radius: 5,
                    damage: 10,
                    color: '#ff44aa',
                    life: 200,
                    isEnemyBullet: true
                });
            }
        }

        // Collision with player
        const dist = Math.hypot(this.x - player.x, this.y - player.y);
        if (dist < this.radius + player.radius) {
            player.takeDamage(20);
            this.health = 0;
            createExplosion(this.x, this.y, this.color, 10);
        }
    }

    draw() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);

        // Enemy body
        ctx.beginPath();
        if (this.type === 'basic') {
            ctx.moveTo(this.radius, 0);
            ctx.lineTo(-this.radius * 0.7, -this.radius * 0.7);
            ctx.lineTo(-this.radius * 0.4, 0);
            ctx.lineTo(-this.radius * 0.7, this.radius * 0.7);
        } else if (this.type === 'fast') {
            ctx.moveTo(this.radius, 0);
            ctx.lineTo(-this.radius, -this.radius * 0.5);
            ctx.lineTo(-this.radius * 0.5, 0);
            ctx.lineTo(-this.radius, this.radius * 0.5);
        } else if (this.type === 'tank') {
            ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
        } else if (this.type === 'shooter') {
            ctx.moveTo(this.radius, 0);
            ctx.lineTo(0, -this.radius);
            ctx.lineTo(-this.radius, 0);
            ctx.lineTo(0, this.radius);
        }
        ctx.closePath();

        const gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, this.radius);
        gradient.addColorStop(0, this.color);
        gradient.addColorStop(1, 'rgba(0,0,0,0.5)');
        ctx.fillStyle = gradient;
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.restore();

        // Health bar
        if (this.health < this.maxHealth) {
            const barWidth = this.radius * 2;
            const barHeight = 4;
            const barX = this.x - barWidth / 2;
            const barY = this.y - this.radius - 10;

            ctx.fillStyle = 'rgba(255,0,0,0.5)';
            ctx.fillRect(barX, barY, barWidth, barHeight);
            ctx.fillStyle = '#00ff00';
            ctx.fillRect(barX, barY, barWidth * (this.health / this.maxHealth), barHeight);
        }
    }

    takeDamage(damage) {
        this.health -= damage;
        if (this.health <= 0) {
            score += this.scoreValue * (1 + combo * 0.1);
            combo++;
            comboTimer = 3000;
            createExplosion(this.x, this.y, this.color, 15);
            playExplosionSound();
            screenShake = 5;

            // Chance to drop powerup
            if (Math.random() < 0.15) {
                powerups.push({
                    x: this.x,
                    y: this.y,
                    type: ['triple', 'rapid', 'health'][Math.floor(Math.random() * 3)],
                    radius: 15,
                    life: 10000,
                    angle: 0
                });
            }

            return true; // died
        }
        return false;
    }
}

// Particle system
function createExplosion(x, y, color, count) {
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 5 + 2;
        particles.push({
            x: x,
            y: y,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            radius: Math.random() * 3 + 1,
            color: color,
            alpha: 1,
            life: 1000
        });
    }
}

function createSparkle(x, y) {
    for (let i = 0; i < 5; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 3 + 1;
        particles.push({
            x: x,
            y: y,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            radius: Math.random() * 2 + 0.5,
            color: '#ffffff',
            alpha: 1,
            life: 500
        });
    }
}

// Update functions
function updateParticles(dt) {
    particles = particles.filter(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.life -= dt;
        p.alpha = p.life / 1000;
        p.vx *= 0.98;
        p.vy *= 0.98;
        return p.life > 0;
    });
}

function updateBullets(dt) {
    bullets = bullets.filter(b => {
        b.x += b.vx;
        b.y += b.vy;
        b.life -= dt;

        // Check collision with enemies
        for (let i = enemies.length - 1; i >= 0; i--) {
            const enemy = enemies[i];
            const dist = Math.hypot(b.x - enemy.x, b.y - enemy.y);
            if (dist < b.radius + enemy.radius) {
                const died = enemy.takeDamage(b.damage);
                if (died) {
                    enemies.splice(i, 1);
                }
                createSparkle(b.x, b.y);
                return false;
            }
        }

        return b.x > -50 && b.x < canvas.width + 50 && b.y > -50 && b.y < canvas.height + 50 && b.life > 0;
    });
}

function updateEnemies(dt) {
    enemies = enemies.filter(e => {
        if (e.isEnemyBullet) {
            e.x += e.vx;
            e.y += e.vy;
            e.life -= dt;

            // Check collision with player
            const dist = Math.hypot(e.x - player.x, e.y - player.y);
            if (dist < e.radius + player.radius) {
                player.takeDamage(e.damage);
                return false;
            }

            return e.life > 0 && e.x > -50 && e.x < canvas.width + 50 && e.y > -50 && e.y < canvas.height + 50;
        }

        e.update(dt);
        return e.health > 0;
    });
}

function updatePowerups(dt) {
    powerups = powerups.filter(p => {
        p.life -= dt;
        p.angle += 0.02;

        const dist = Math.hypot(p.x - player.x, p.y - player.y);
        if (dist < p.radius + player.radius) {
            applyPowerup(p.type);
            playPowerupSound();
            createSparkle(p.x, p.y);
            return false;
        }

        return p.life > 0;
    });
}

function applyPowerup(type) {
    player.powerup = type;
    player.powerupTimer = 10000;

    switch (type) {
        case 'triple':
            document.getElementById('powerup-display').textContent = '⚡ TRIPLE SHOT ⚡';
            break;
        case 'rapid':
            document.getElementById('powerup-display').textContent = '🔥 RAPID FIRE 🔥';
            break;
        case 'health':
            player.health = Math.min(player.maxHealth, player.health + 30);
            updateHealthBar();
            document.getElementById('powerup-display').textContent = '❤️ HEALTH +30 ❤️';
            break;
    }
}

function updateStars() {
    stars.forEach(star => {
        star.y += star.speed;
        if (star.y > canvas.height) {
            star.y = 0;
            star.x = Math.random() * canvas.width;
        }
        star.brightness = 0.5 + Math.sin(Date.now() * 0.001 + star.x) * 0.5;
    });
}

function updateCombo(dt) {
    if (comboTimer > 0) {
        comboTimer -= dt;
        if (comboTimer <= 0) {
            combo = 0;
        }
    }

    const comboDisplay = document.getElementById('combo-display');
    if (combo > 1) {
        comboDisplay.textContent = `x${combo} COMBO!`;
        comboDisplay.style.opacity = '1';
    } else {
        comboDisplay.style.opacity = '0';
    }
}

function updateHealthBar() {
    const healthBar = document.getElementById('health-bar');
    healthBar.style.width = `${(player.health / player.maxHealth) * 100}%`;
}

function spawnEnemies(dt) {
    enemySpawnTimer -= dt;
    if (enemySpawnTimer <= 0) {
        enemySpawnTimer = enemySpawnRate;

        const types = ['basic', 'basic', 'basic', 'fast', 'fast', 'tank', 'shooter'];
        const availableTypes = types.slice(0, Math.min(3 + Math.floor(wave / 2), types.length));
        const type = availableTypes[Math.floor(Math.random() * availableTypes.length)];

        enemies.push(new Enemy(type));
    }

    // Increase wave difficulty
    if (score > wave * 1000) {
        wave++;
        enemySpawnRate = Math.max(500, 2000 - wave * 100);
        document.getElementById('wave-display').textContent = `Wave: ${wave}`;

        // Wave announcement
        const comboDisplay = document.getElementById('combo-display');
        comboDisplay.textContent = `🌊 WAVE ${wave} 🌊`;
        comboDisplay.style.opacity = '1';
        setTimeout(() => {
            if (combo <= 1) comboDisplay.style.opacity = '0';
        }, 2000);
    }
}

function drawStars() {
    stars.forEach(star => {
        ctx.beginPath();
        ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255, 255, 255, ${star.brightness * 0.8})`;
        ctx.fill();
    });
}

function drawParticles() {
    particles.forEach(p => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.alpha;
        ctx.fill();
        ctx.globalAlpha = 1;
    });
}

function drawBullets() {
    bullets.forEach(b => {
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
        ctx.fillStyle = b.color;
        ctx.fill();

        // Glow effect
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.radius * 2, 0, Math.PI * 2);
        const gradient = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, b.radius * 2);
        gradient.addColorStop(0, b.color);
        gradient.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = gradient;
        ctx.fill();
    });
}

function drawPowerups() {
    powerups.forEach(p => {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.angle);

        // Outer glow
        ctx.beginPath();
        ctx.arc(0, 0, p.radius + 5, 0, Math.PI * 2);
        const glowGradient = ctx.createRadialGradient(0, 0, 0, 0, 0, p.radius + 5);
        glowGradient.addColorStop(0, 'rgba(255, 255, 0, 0.3)');
        glowGradient.addColorStop(1, 'rgba(255, 255, 0, 0)');
        ctx.fillStyle = glowGradient;
        ctx.fill();

        // Powerup icon
        ctx.beginPath();
        ctx.arc(0, 0, p.radius, 0, Math.PI * 2);
        ctx.fillStyle = p.type === 'triple' ? '#00ffcc' : p.type === 'rapid' ? '#ffcc00' : '#ff4444';
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Icon text
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(p.type === 'triple' ? '3' : p.type === 'rapid' ? 'R' : '♥', 0, 0);

        ctx.restore();
    });
}

function drawCrosshair() {
    ctx.beginPath();
    ctx.arc(mouse.x, mouse.y, 15, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(mouse.x - 20, mouse.y);
    ctx.lineTo(mouse.x - 10, mouse.y);
    ctx.moveTo(mouse.x + 10, mouse.y);
    ctx.lineTo(mouse.x + 20, mouse.y);
    ctx.moveTo(mouse.x, mouse.y - 20);
    ctx.lineTo(mouse.x, mouse.y - 10);
    ctx.moveTo(mouse.x, mouse.y + 10);
    ctx.lineTo(mouse.x, mouse.y + 20);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(mouse.x, mouse.y, 2, 0, Math.PI * 2);
    ctx.fillStyle = '#ff0000';
    ctx.fill();
}

function gameLoop(timestamp) {
    if (!gameRunning) return;

    const dt = timestamp - lastTime;
    lastTime = timestamp;

    // Clear canvas
    ctx.fillStyle = '#000011';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Screen shake
    if (screenShake > 0) {
        ctx.save();
        ctx.translate(
            (Math.random() - 0.5) * screenShake,
            (Math.random() - 0.5) * screenShake
        );
        screenShake *= 0.9;
        if (screenShake < 0.5) screenShake = 0;
    }

    // Update
    updateStars();
    player.update(dt);
    updateBullets(dt);
    updateEnemies(dt);
    updateParticles(dt);
    updatePowerups(dt);
    spawnEnemies(dt);
    updateCombo(dt);

    // Draw
    drawStars();
    drawPowerups();
    drawBullets();
    enemies.forEach(e => e.draw());
    player.draw();
    drawParticles();

    if (screenShake > 0) {
        ctx.restore();
    }

    drawCrosshair();

    // Update score display
    document.getElementById('score-display').textContent = `Score: ${Math.floor(score)}`;

    requestAnimationFrame(gameLoop);
}

function startGame() {
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('game-over-screen').style.display = 'none';

    player = new Player();
    score = 0;
    wave = 1;
    combo = 0;
    comboTimer = 0;
    enemies = [];
    bullets = [];
    particles = [];
    powerups = [];
    enemySpawnTimer = 0;
    enemySpawnRate = 2000;
    screenShake = 0;

    initStars();
    updateHealthBar();
    document.getElementById('wave-display').textContent = 'Wave: 1';
    document.getElementById('powerup-display').textContent = '';

    gameRunning = true;
    lastTime = performance.now();
    requestAnimationFrame(gameLoop);
}

function gameOver() {
    gameRunning = false;
    document.getElementById('game-over-screen').style.display = 'flex';
    document.getElementById('final-score').textContent = `Score: ${Math.floor(score)}`;
    document.getElementById('final-wave').textContent = `Wave: ${wave}`;
}

// Event listeners
document.getElementById('start-btn').addEventListener('click', () => {
    audioCtx.resume();
    startGame();
});

document.getElementById('restart-btn').addEventListener('click', () => {
    startGame();
});

canvas.addEventListener('mousemove', (e) => {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
});

canvas.addEventListener('mousedown', (e) => {
    keys['mouse'] = true;
});

canvas.addEventListener('mouseup', (e) => {
    keys['mouse'] = false;
});

canvas.addEventListener('contextmenu', (e) => e.preventDefault());

window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
    if (e.key === ' ') e.preventDefault();
});

window.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

// Initialize stars for start screen
initStars();

function animateStartScreen() {
    if (gameRunning) return;

    ctx.fillStyle = '#000011';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    updateStars();
    drawStars();
    requestAnimationFrame(animateStartScreen);
}

animateStartScreen();
</script>
