  { id: 'dog', name: 'Brainrot Dog', emoji: '🐕', buff: 'steal', value: 0.1, desc: '+10% Steal Chance' },
  { id: 'cat', name: 'Mystic Cat', emoji: '🐱', buff: 'speed', value: 0.15, desc: '+15% Speed' },
  { id: 'dragon', name: 'Baby Dragon', emoji: '🐉', buff: 'defense', value: 0.2, desc: '+20% Defense' },
  { id: 'fox', name: 'Shadow Fox', emoji: '🦊', buff: 'carry', value: 3, desc: '+3 Carry Capacity' },
  { id: 'owl', name: 'Wisdom Owl', emoji: '🦉', buff: 'aura', value: 0.25, desc: '+25% Aura Multiplier' },
  { id: 'wolf', name: 'Alpha Wolf', emoji: '🐺', buff: 'race', value: 0.2, desc: '+20% Racing Speed' },
  { id: 'eagle', name: 'Golden Eagle', emoji: '🦅', buff: 'spawn', value: 0.3, desc: '+30% Brainrot Spawn' },
  { id: 'bear', name: 'Iron Bear', emoji: '🐻', buff: 'armor', value: 0.3, desc: '+30% Damage Reduction' },
  { id: 'rabbit', name: 'Speed Rabbit', emoji: '🐰', buff: 'boost', value: 0.4, desc: '+40% Boost Duration' }
];

function startGame() {
  document.getElementById('main-menu').style.display = 'none';
  game.running = true;
  initAIPlayers();
  spawnBrainrotItems(20);
  game.vehicles = [...vehicleTypes];
  updateUI();
  gameLoop();
}

function spawnBrainrotItems(count) {
  for (let i = 0; i < count; i++) {
    const type = brainrotTypes[Math.floor(Math.random() * Math.min(brainrotTypes.length, 2 + game.baseLevel))];
    brainrotItems.push({
      x: 1800 + Math.random() * 400,
      y: 1800 + Math.random() * 400,
      type: type,
      size: 15,
      pulse: Math.random() * Math.PI * 2,
      collected: false
    });
  }
}

function clickAura() {
  const amount = Math.floor(game.clickPower * game.auraMultiplier);
  game.aura += amount;
  game.clickPower = Math.min(game.clickPower + 0.1, 10);
  addParticle(player.x, player.y - 30, `+${amount} 💰`, '#ffd700');
  updateUI();
}

function addParticle(x, y, text, color) {
  game.particles.push({
    x, y, text, color,
    life: 60,
    vy: -2,
    vx: (Math.random() - 0.5) * 2
  });
}

function showNotification(text) {
  const notif = document.getElementById('notification');
  notif.textContent = text;
  notif.classList.add('show');
  setTimeout(() => notif.classList.remove('show'), 3000);
}

function openShop() {
  document.getElementById('shop-panel').classList.add('open');
  renderShopItems('vehicles');
}

function closeShop() {
  document.getElementById('shop-panel').classList.remove('open');
}

function openBasePanel() {
  document.getElementById('base-panel').classList.add('open');
  renderBaseUpgrades();
}

function closeBasePanel() {
  document.getElementById('base-panel').classList.remove('open');
}

function openPetPanel() {
  document.getElementById('pet-panel').style.display = 'block';
  renderPetGrid();
}

function closePetPanel() {
  document.getElementById('pet-panel').style.display = 'none';
}

function switchTab(tab) {
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  event.target.classList.add('active');
  if (tab === 'vehicles') renderShopItems('vehicles');
  else if (tab === 'custom') renderShopItems('custom');
  else if (tab === 'parts') renderShopItems('parts');
}

function renderShopItems(tab) {
  const container = document.getElementById('shop-items');
  container.innerHTML = '';

  if (tab === 'vehicles') {
    vehicleTypes.forEach(v => {
      const owned = game.vehicles.find(ov => ov.id === v.id && ov.owned);
      const item = document.createElement('div');
      item.className = 'shop-item';
      item.innerHTML = `
        <div class="item-info">
          <div class="item-name">${v.emoji} ${v.name}</div>
          <div class="item-desc">Speed: ${v.speed} | Capacity: ${v.capacity}</div>
        </div>
        <div style="text-align:right;">
          <div class="item-cost">${v.cost} 💰</div>
          <button class="buy-btn" ${owned ? 'disabled' : ''} onclick="buyVehicle('${v.id}')">
            ${owned ? 'Owned' : 'Buy'}
          </button>
        </div>
      `;
      container.appendChild(item);
    });
  } else if (tab === 'custom') {
    customColors.forEach(color => {
      const item = document.createElement('div');
      item.className = 'shop-item';
      item.innerHTML = `
        <div class="item-info">
          <div class="item-name" style="display:flex;align-items:center;gap:8px;">
            <div style="width:20px;height:20px;border-radius:50%;background:${color};border:2px solid #fff;"></div>
            Custom Color
          </div>
          <div class="item-desc">Change vehicle color</div>
        </div>
        <button class="buy-btn" onclick="applyColor('${color}')">Apply</button>
      `;
      container.appendChild(item);
    });
  } else if (tab === 'parts') {
    partTypes.forEach(p => {
      const item = document.createElement('div');
      item.className = 'shop-item';
      item.innerHTML = `
        <div class="item-info">
          <div class="item-name">⚙️ ${p.name}</div>
          <div class="item-desc">${p.desc}</div>
        </div>
        <div style="text-align:right;">
          <div class="item-cost">${p.cost} 💰</div>
          <button class="buy-btn" onclick="buyPart('${p.id}')">Buy</button>
        </div>
      `;
      container.appendChild(item);
    });
  }
}

function buyVehicle(id) {
  const vehicle = vehicleTypes.find(v => v.id === id);
  if (!vehicle || game.aura < vehicle.cost) {
    showNotification('Not enough Aura!');
    return;
  }
  game.aura -= vehicle.cost;
  const ownedVehicle = { ...vehicle, owned: true, color: vehicle.color, parts: [] };
  game.vehicles.push(ownedVehicle);
  showNotification(`Bought ${vehicle.name}!`);
  updateUI();
  renderShopItems('vehicles');
}

function applyColor(color) {
  if (game.currentVehicle) {
    game.currentVehicle.color = color;
    showNotification(`Color applied!`);
  } else {
    showNotification('Enter a vehicle first!');
  }
}

function buyPart(id) {
  const part = partTypes.find(p => p.id === id);
  if (!part || game.aura < part.cost) {
    showNotification('Not enough Aura!');
    return;
  }
  game.aura -= part.cost;
  if (game.currentVehicle) {
    game.currentVehicle.parts.push({ ...part });
    applyPartEffects(game.currentVehicle, part);
    showNotification(`Installed ${part.name}!`);
  } else {
    showNotification('Enter a vehicle first!');
  }
  updateUI();
}

function applyPartEffects(vehicle, part) {
  if (part.effect === 'speed') vehicle.speed += part.value;
  if (part.effect === 'defense') game.baseDefense += part.value;
  if (part.effect === 'capacity') vehicle.capacity += part.value;
  if (part.effect === 'boost') game.boostEnergy += part.value * 10;
}

function renderBaseUpgrades() {
  const container = document.getElementById('base-upgrades');
  container.innerHTML = '';
  baseUpgrades.forEach(upgrade => {
    const maxed = upgrade.level >= upgrade.maxLevel;
    const item = document.createElement('div');
    item.className = 'shop-item';
    item.innerHTML = `
      <div class="item-info">
        <div class="item-name">🏠 ${upgrade.name} (Lv.${upgrade.level})</div>
        <div class="item-desc">${upgrade.desc}</div>
      </div>
      <div style="text-align:right;">
        <div class="item-cost">${upgrade.cost} 💰</div>
        <button class="buy-btn" ${maxed || game.aura < upgrade.cost ? 'disabled' : ''} onclick="upgradeBase('${upgrade.id}')">
          ${maxed ? 'MAX' : 'Upgrade'}
        </button>
      </div>
    `;
    container.appendChild(item);
  });
}

function upgradeBase(id) {
  const upgrade = baseUpgrades.find(u => u.id === id);
  if (!upgrade || upgrade.level >= upgrade.maxLevel || game.aura < upgrade.cost) {
    showNotification('Cannot upgrade!');
    return;
  }
  game.aura -= upgrade.cost;
  upgrade.level++;
  game.baseLevel++;

  if (upgrade.effect === 'defense') game.baseDefense += upgrade.value;
  if (upgrade.effect === 'capacity') player.maxCarry += upgrade.value;
  if (upgrade.effect === 'spawnRate') game.brainrotRate += upgrade.value;

  showNotification(`Upgraded ${upgrade.name} to Lv.${upgrade.level}!`);
  updateUI();
  renderBaseUpgrades();
}

function renderPetGrid() {
  const container = document.getElementById('pet-grid');
  container.innerHTML = '';
  petTypes.forEach(pet => {
    const owned = game.pets.find(p => p.id === pet.id);
    const card = document.createElement('div');
    card.className = 'pet-card';
    card.innerHTML = `
      <div class="pet-emoji">${pet.emoji}</div>
      <div class="pet-name">${pet.name}</div>
      <div class="pet-buff">${pet.desc}</div>
      ${owned ? '<div style="color:#00ff88;font-size:10px;margin-top:4px;">✓ Owned</div>' : ''}
    `;
    container.appendChild(card);
  });
}

function hatchPet() {
  if (game.aura < 500) {
    showNotification('Not enough Aura!');
    return;
  }
  game.aura -= 500;
  const pet = petTypes[Math.floor(Math.random() * petTypes.length)];
  if (game.pets.find(p => p.id === pet.id)) {
    showNotification('Already have this pet!');
    return;
  }
  game.pets.push({ ...pet });
  applyPetBuff(pet);
  showNotification(`Hatched ${pet.name}! ${pet.desc}`);
  updateUI();
  renderPetGrid();
}

function applyPetBuff(pet) {
  if (pet.buff === 'steal') game.stealCooldown = Math.max(0, game.stealCooldown - pet.value);
  if (pet.buff === 'speed') player.speed += pet.value * 2;
  if (pet.buff === 'defense') game.baseDefense += pet.value * 5;
  if (pet.buff === 'carry') player.maxCarry += pet.value;
  if (pet.buff === 'aura') game.auraMultiplier += pet.value;
  if (pet.buff === 'race') game.boostEnergy += pet.value * 20;
  if (pet.buff === 'spawn') game.brainrotRate += pet.value;
}

function updateUI() {
  document.getElementById('aura-display').textContent = Math.floor(game.aura);
  document.getElementById('brainrot-display').textContent = game.brainrotItems;
  document.getElementById('base-display').textContent = `Lv.${game.baseLevel}`;
  document.getElementById('pet-display').textContent = game.pets.length;
  document.getElementById('vehicle-display').textContent = game.currentVehicle ? game.currentVehicle.name : 'None';
}

function handleInput() {
  game.keys = game.keys || {};
  // Movement
  let dx = 0, dy = 0;
  if (game.keys['w'] || game.keys['arrowup']) dy = -1;
  if (game.keys['s'] || game.keys['arrowdown']) dy = 1;
  if (game.keys['a'] || game.keys['arrowleft']) dx = -1;
  if (game.keys['d'] || game.keys['arrowright']) dx = 1;

  if (dx !== 0 || dy !== 0) {
    const len = Math.sqrt(dx * dx + dy * dy);
    dx /= len; dy /= len;

    let speed = player.speed;
    if (game.inVehicle && game.currentVehicle) {
      speed = game.currentVehicle.speed;
    }
    if (game.boosting && game.boostEnergy > 0) {
      speed *= 2;
      game.boostEnergy -= 0.5;
    }

    // Penalty for carrying items
    if (player.carrying > 0) {
      speed *= 0.7;
    }

    // Pet speed buff
    const speedPet = game.pets.find(p => p.buff === 'speed');
    if (speedPet) speed *= (1 + speedPet.value);

    player.vx = dx * speed;
    player.vy = dy * speed;
    player.angle = Math.atan2(dy, dx);
  } else {
    player.vx *= 0.8;
    player.vy *= 0.8;
  }

  player.x += player.vx;
  player.y += player.vy;

  // World bounds
  player.x = Math.max(50, Math.min(game.worldSize - 50, player.x));
  player.y = Math.max(50, Math.min(game.worldSize - 50, player.y));

  // Boost
  if (game.keys[' '] && game.boostEnergy > 0) {
    game.boosting = true;
  } else {
    game.boosting = false;
    game.boostEnergy = Math.min(game.boostEnergy + 0.2, 100);
  }

  // Pick up items
  if (game.keys['e']) {
    game.keys['e'] = false;
    pickUpItem();
  }

  // Enter/exit vehicle
  if (game.keys['f']) {
    game.keys['f'] = false;
    toggleVehicle();
  }
}

function pickUpItem() {
  if (player.carrying >= player.maxCarry) {
    showNotification('Carry capacity full!');
    return;
  }

  for (let i = brainrotItems.length - 1; i >= 0; i--) {
    const item = brainrotItems[i];
    const dist = Math.hypot(item.x - player.x, item.y - player.y);
    if (dist < 40) {
      player.carrying++;
      brainrotItems.splice(i, 1);
      addParticle(player.x, player.y - 20, `+1 ${item.type.emoji}`, item.type.color);
      showNotification(`Picked up ${item.type.name}!`);
      updateUI();
      return;
    }
  }
}

function toggleVehicle() {
  if (game.inVehicle) {
    // Exit vehicle
    game.inVehicle = false;
    player.x = game.currentVehicle.x + 40;
    player.y = game.currentVehicle.y;
    game.currentVehicle = null;
    document.getElementById('vehicle-indicator').style.display = 'none';
    showNotification('Exited vehicle');
  } else {
    // Enter nearest vehicle
    let nearest = null;
    let nearestDist = 100;
    game.vehicles.forEach(v => {
      if (v.owned) {
        const dist = Math.hypot(v.x - player.x, v.y - player.y);
        if (dist < nearestDist) {
          nearest = v;
          nearestDist = dist;
        }
      }
    });

    if (nearest) {
      game.inVehicle = true;
      game.currentVehicle = nearest;
      player.x = nearest.x;
      player.y = nearest.y;
      document.getElementById('vehicle-indicator').style.display = 'block';
      showNotification(`Entered ${nearest.name}!`);
    } else {
      showNotification('No vehicles nearby!');
    }
  }
}

function updateAI() {
  game.aiPlayers.forEach(ai => {
    // AI behavior
    if (ai.state === 'collect') {
      // Find nearest brainrot item
      let nearestItem = null;
      let nearestDist = Infinity;
      brainrotItems.forEach(item => {
        const dist = Math.hypot(item.x - ai.x, item.y - ai.y);
        if (dist < nearestDist) {
          nearestDist = dist;
          nearestItem = item;
        }
      });

      if (nearestItem && nearestDist < 500) {
        ai.targetX = nearestItem.x;
        ai.targetY = nearestItem.y;
      } else {
        // Return to base zone
        ai.targetX = 2000;
        ai.targetY = 2000;
      }

      // Move towards target
      const dx = ai.targetX - ai.x;
      const dy = ai.targetY - ai.y;
      const dist = Math.hypot(dx, dy);
      if (dist > 10) {
        ai.x += (dx / dist) * ai.speed;
        ai.y += (dy / dist) * ai.speed;
        ai.angle = Math.atan2(dy, dx);
      }

      // Pick up item
      if (nearestItem && nearestDist < 30) {
        if (ai.carrying < ai.maxCarry) {
          ai.carrying++;
          const idx = brainrotItems.indexOf(nearestItem);
          if (idx > -1) brainrotItems.splice(idx, 1);
        }
      }

      // Steal from player
      if (ai.carrying > 0) {
        const distToPlayer = Math.hypot(ai.x - player.x, ai.y - player.y);
        if (distToPlayer < 50 && player.carrying > 0 && ai.stealCooldown <= 0) {
          const stolen = Math.min(1, player.carrying);
          player.carrying -= stolen;
          ai.carrying += stolen;
          ai.stealCooldown = 120;
          game.stolenItems += stolen;
          addParticle(player.x, player.y - 30, `-${stolen} 🧠`, '#ff0000');
          showNotification(`${ai.name} stole ${stolen} brainrot items!`);
        }
      }

      // Change state if carrying enough
      if (ai.carrying >= ai.maxCarry * 0.8) {
        ai.state = 'return';
      }
    } else if (ai.state === 'return') {
      ai.targetX = 2000;
      ai.targetY = 2000;

      const dx = ai.targetX - ai.x;
      const dy = ai.targetY - ai.y;
      const dist = Math.hypot(dx, dy);

      if (dist > 50) {
        ai.x += (dx / dist) * ai.speed;
        ai.y += (dy / dist) * ai.speed;
      } else {
        // Deposit items
        game.aura += ai.carrying * 10;
        addParticle(ai.x, ai.y - 30, `+${ai.carrying * 10} 💰`, '#ffd700');
        ai.carrying = 0;
        ai.state = 'collect';
      }
    }

    if (ai.stealCooldown > 0) ai.stealCooldown--;

    // Keep in bounds
    ai.x = Math.max(50, Math.min(game.worldSize - 50, ai.x));
    ai.y = Math.max(50, Math.min(game.worldSize - 50, ai.y));
  });
}

function updateBrainrotSpawning() {
  game.brainrotSpawnTimer++;
  const spawnRate = Math.max(30, 120 - game.brainrotRate * 10);

  if (game.brainrotSpawnTimer >= spawnRate && brainrotItems.length < 50) {
    game.brainrotSpawnTimer = 0;
    spawnBrainrotItems(1);
  }
}

function updateParticles() {
  for (let i = game.particles.length - 1; i >= 0; i--) {
    const p = game.particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.life--;
    if (p.life <= 0) {
      game.particles.splice(i, 1);
    }
  }
}

function updateCamera() {
  game.camera.x = player.x - canvas.width / 2;
  game.camera.y = player.y - canvas.height / 2;
}

function drawWorld() {
  // Background
  ctx.fillStyle = '#1a1a2e';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.save();
  ctx.translate(-game.camera.x, -game.camera.y);

  // Grid
  ctx.strokeStyle = 'rgba(255,255,255,0.05)';
  ctx.lineWidth = 1;
  const gridSize = 100;
  const startX = Math.floor(game.camera.x / gridSize) * gridSize;
  const startY = Math.floor(game.camera.y / gridSize) * gridSize;

  for (let x = startX; x < game.camera.x + canvas.width + gridSize; x += gridSize) {
    ctx.beginPath();
    ctx.moveTo(x, game.camera.y);
    ctx.lineTo(x, game.camera.y + canvas.height);
    ctx.stroke();
  }
  for (let y = startY; y < game.camera.y + canvas.height + gridSize; y += gridSize) {
    ctx.beginPath();
    ctx.moveTo(game.camera.x, y);
    ctx.lineTo(game.camera.x + canvas.width, y);
    ctx.stroke();
  }

  // World border
  ctx.strokeStyle = '#ff6b35';
  ctx.lineWidth = 3;
  ctx.strokeRect(0, 0, game.worldSize, game.worldSize);

  // Central zone (Brainrot collection zone)
  const zoneX = 2000, zoneY = 2000, zoneSize = 300;
  const gradient = ctx.createRadialGradient(zoneX, zoneY, 0, zoneX, zoneY, zoneSize);
  gradient.addColorStop(0, 'rgba(255,107,53,0.3)');
  gradient.addColorStop(1, 'rgba(255,107,53,0)');
  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(zoneX, zoneY, zoneSize, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = 'rgba(255,107,53,0.5)';
  ctx.lineWidth = 2;
  ctx.setLineDash([10, 5]);
  ctx.beginPath();
  ctx.arc(zoneX, zoneY, zoneSize, 0, Math.PI * 2);
  ctx.stroke();
  ctx.setLineDash([]);

  // Zone label
  ctx.fillStyle = '#ff6b35';
  ctx.font = 'bold 16px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('🧠 BRAINROT ZONE', zoneX, zoneY - zoneSize - 10);

  // Base
  const baseX = 1800, baseY = 1800;
  ctx.fillStyle = 'rgba(0,255,136,0.2)';
  ctx.fillRect(baseX - 50, baseY - 50, 100, 100);
  ctx.strokeStyle = '#00ff88';
  ctx.lineWidth = 2;
  ctx.strokeRect(baseX - 50, baseY - 50, 100, 100);
  ctx.fillStyle = '#00ff88';
  ctx.font = 'bold 14px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(`🏠 BASE Lv.${game.baseLevel}`, baseX, baseY + 5);

  // Draw brainrot items
  brainrotItems.forEach(item => {
    item.pulse += 0.05;
    const pulseSize = item.size + Math.sin(item.pulse) * 3;

    // Glow
    ctx.fillStyle = item.type.color + '33';
    ctx.beginPath();
    ctx.arc(item.x, item.y, pulseSize + 10, 0, Math.PI * 2);
    ctx.fill();

    // Item
    ctx.font = `${pulseSize * 2}px Arial`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(item.type.emoji, item.x, item.y);

    // Value label
    ctx.fillStyle = '#fff';
    ctx.font = '10px Arial';
    ctx.fillText(`${item.type.value}💰`, item.x, item.y + pulseSize + 10);
  });

  // Draw AI players
  game.aiPlayers.forEach(ai => {
    // Body
    ctx.fillStyle = ai.color;
    ctx.beginPath();
    ctx.arc(ai.x, ai.y, ai.size, 0, Math.PI * 2);
    ctx.fill();

    // Outline
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Name
    ctx.fillStyle = '#fff';
    ctx.font = '11px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(ai.name, ai.x, ai.y - ai.size - 10);

    // Carrying indicator
    if (ai.carrying > 0) {
      ctx.fillStyle = '#ff6b35';
      ctx.font = '12px Arial';
      ctx.fillText(`🧠${ai.carrying}`, ai.x, ai.y + ai.size + 15);
    }

    // Direction indicator
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(
      ai.x + Math.cos(ai.angle) * ai.size,
      ai.y + Math.sin(ai.angle) * ai.size,
      4, 0, Math.PI * 2
    );
    ctx.fill();
  });

  // Draw player
  if (!game.inVehicle) {
    // Player body
    ctx.fillStyle = player.color;
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
    ctx.fill();

    // Player outline
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 3;
    ctx.stroke();

    // Direction indicator
    ctx.fillStyle = '#ffd700';
    ctx.beginPath();
    ctx.arc(
      player.x + Math.cos(player.angle) * player.size,
      player.y + Math.sin(player.angle) * player.size,
      5, 0, Math.PI * 2
    );
    ctx.fill();

    // Carrying indicator
    if (player.carrying > 0) {
      ctx.fillStyle = '#ff6b35';
      ctx.font = 'bold 14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(`🧠${player.carrying}/${player.maxCarry}`, player.x, player.y + player.size + 20);

      // Vulnerability warning
      if (player.carrying > 0) {
        ctx.fillStyle = 'rgba(255,0,0,0.3)';
        ctx.beginPath();
        ctx.arc(player.x, player.y, player.size + 15, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Name
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('YOU', player.x, player.y - player.size - 10);
  } else {
    // Draw vehicle
    const v = game.currentVehicle;
    ctx.save();
    ctx.translate(v.x, v.y);

    // Vehicle body
    ctx.fillStyle = v.color;
    ctx.fillRect(-25, -15, 50, 30);

    // Vehicle outline
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.strokeRect(-25, -15, 50, 30);

    // Wheels
    ctx.fillStyle = '#333';
    ctx.fillRect(-20, -18, 10, 6);
    ctx.fillRect(-20, 12, 10, 6);
    ctx.fillRect(10, -18, 10, 6);
    ctx.fillRect(10, 12, 10, 6);

    // Windshield
    ctx.fillStyle = 'rgba(100,200,255,0.5)';
    ctx.fillRect(10, -12, 12, 24);

    // Speed lines when moving
    if (Math.abs(player.vx) > 1 || Math.abs(player.vy) > 1) {
      ctx.strokeStyle = 'rgba(255,255,255,0.3)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(-30 - i * 10, -10 + i * 10);
        ctx.lineTo(-40 - i * 10, -10 + i * 10);
        ctx.stroke();
      }
    }

    ctx.restore();

    // Vehicle name
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(`${v.emoji} ${v.name}`, v.x, v.y - 25);

    // Capacity
    ctx.fillStyle = '#ffd700';
    ctx.font = '11px Arial';
    ctx.fillText(`🧠${player.carrying}/${v.capacity}`, v.x, v.y + 30);
  }

  // Draw particles
  game.particles.forEach(p => {
    ctx.globalAlpha = p.life / 60;
    ctx.fillStyle = p.color;
    ctx.font = 'bold 14px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(p.text, p.x, p.y);
    ctx.globalAlpha = 1;
  });

  ctx.restore();
}

function drawMinimap() {
  minimapCtx.fillStyle = 'rgba(0,0,0,0.8)';
  minimapCtx.fillRect(0, 0, 180, 180);

  const scale = 180 / game.worldSize;

  // Central zone
  minimapCtx.fillStyle = 'rgba(255,107,53,0.3)';
  minimapCtx.beginPath();
  minimapCtx.arc(2000 * scale, 2000 * scale, 300 * scale, 0, Math.PI * 2);
  minimapCtx.fill();

  // Base
  minimapCtx.fillStyle = 'rgba(0,255,136,0.5)';
  minimapCtx.fillRect(1800 * scale - 5, 1800 * scale - 5, 10, 10);

  // Brainrot items
  brainrotItems.forEach(item => {
    minimapCtx.fillStyle = item.type.color;
    minimapCtx.fillRect(item.x * scale - 1, item.y * scale - 1, 2, 2);
  });

  // AI players
  game.aiPlayers.forEach(ai => {
    minimapCtx.fillStyle = ai.color;
    minimapCtx.beginPath();
    minimapCtx.arc(ai.x * scale, ai.y * scale, 3, 0, Math.PI * 2);
    minimapCtx.fill();
  });

  // Player
  minimapCtx.fillStyle = '#ff6b35';
  minimapCtx.beginPath();
  minimapCtx.arc(player.x * scale, player.y * scale, 4, 0, Math.PI * 2);
  minimapCtx.fill();

  // Camera view
  minimapCtx.strokeStyle = 'rgba(255,255,255,0.5)';
  minimapCtx.lineWidth = 1;
  minimapCtx.strokeRect(
    game.camera.x * scale,
    game.camera.y * scale,
    canvas.width * scale,
    canvas.height * scale
  );

  // Border
  minimapCtx.strokeStyle = '#ff6b35';
  minimapCtx.lineWidth = 2;
  minimapCtx.strokeRect(0, 0, 180, 180);
}

function drawHUD() {
  // Boost bar
  const barWidth = 200;
  const barHeight = 10;
  const barX = canvas.width / 2 - barWidth / 2;
  const barY = canvas.height - 40;

  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(barX, barY, barWidth, barHeight);

  const boostPercent = game.boostEnergy / 100;
  const boostColor = game.boosting ? '#ff0000' : '#00ff88';
  ctx.fillStyle = boostColor;
  ctx.fillRect(barX, barY, barWidth * boostPercent, barHeight);

  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 1;
  ctx.strokeRect(barX, barY, barWidth, barHeight);

  ctx.fillStyle = '#fff';
  ctx.font = '11px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('BOOST', canvas.width / 2, barY - 5);

  // Carry capacity bar
  if (player.carrying > 0) {
    const capWidth = 150;
    const capX = canvas.width / 2 - capWidth / 2;
    const capY = canvas.height - 60;

    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(capX, capY, capWidth, 8);

    const capPercent = player.carrying / player.maxCarry;
    ctx.fillStyle = '#ff6b35';
    ctx.fillRect(capX, capY, capWidth * capPercent, 8);

    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.strokeRect(capX, capY, capWidth, 8);

    ctx.fillStyle = '#fff';
    ctx.font = '10px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(`CARRYING: ${player.carrying}/${player.maxCarry}`, canvas.width / 2, capY - 3);
  }

  // Aura multiplier display
  ctx.fillStyle = '#ffd700';
  ctx.font = 'bold 14px Arial';
  ctx.textAlign = 'left';
  ctx.fillText(`Aura Multiplier: x${game.auraMultiplier.toFixed(1)}`, 20, canvas.height - 20);
}

function gameLoop() {
  if (!game.running) return;

  game.time++;

  handleInput();
  updateAI();
  updateBrainrotSpawning();
  updateParticles();
  updateCamera();

  // Passive income from carried items
  if (player.carrying > 0) {
    if (game.time % 60 === 0) {
      const income = Math.floor(player.carrying * game.brainrotRate * game.auraMultiplier);
      game.aura += income;
      game.brainrotItems += player.carrying;
      addParticle(player.x, player.y - 50, `+${income} 💰`, '#ffd700');
    }
  }

  // Base passive aura generation
  const generator = baseUpgrades.find(u => u.id === 'generator');
  if (generator && generator.level > 0 && game.time % 60 === 0) {
    const income = generator.level * generator.value;
    game.aura += income;
  }

  // Defense auto-repair
  const turret = baseUpgrades.find(u => u.id === 'turret');
  if (turret && turret.level > 0 && game.time % 120 === 0) {
    game.baseDefense += turret.level * turret.value;
  }

  drawWorld();
  drawMinimap();
  drawHUD();
  updateUI();

  requestAnimationFrame(gameLoop);
}

// Input handlers
window.addEventListener('keydown', (e) => {
  game.keys[e.key.toLowerCase()] = true;
  if (e.key === ' ') e.preventDefault();
});

window.addEventListener('keyup', (e) => {
  game.keys[e.key.toLowerCase()] = false;
});

window.addEventListener('mousemove', (e) => {
  game.mouse.x = e.clientX;
  game.mouse.y = e.clientY;
});

// Prevent context menu
window.addEventListener('contextmenu', (e) => e.preventDefault());

// Initial UI setup
updateUI();
</script>
