<script>
// ============================================================
// BATTLE ROYALE GAME - WEB EDITION
// ============================================================

const CONFIG = {
WORLD_SIZE: 800,
PLAYER_HEIGHT: 1.8,
CROUCH_HEIGHT: 1.0,
PRONE_HEIGHT: 0.5,
SPEED_WALK: 5,
SPEED_SPRINT: 10,
SPEED_CROUCH: 3,
SPEED_PRONE: 1.5,
JUMP_FORCE: 8,
GRAVITY: 20,
MOUSE_SENSITIVITY: 0.002,
MAX_HEALTH: 100,
MAX_ARMOR: 100,
MAX_STAMINA: 100,
STAMINA_REGEN: 15,
STAMINA_SPRINT_COST: 25,
ZONE_PHASES: 9,
ZONE_DAMAGE: [0.4, 0.8, 1.5, 3, 5, 8, 12, 16, 20],
