RECOIL: [0.02, 0.015, 0.05, 0.03, 0.01],
DAMAGE: [25, 15, 50, 40, 12],
AMMO_CAP: [30, 25, 5, 8, 12],
RESERVE_AMMO: [90, 75, 10, 20, 36],
WEAPON_NAMES: ['Assault Rifle', 'SMG', 'Sniper Rifle', 'Shotgun', 'Pistol'],
WEAPON_COLORS: [0x444444, 0x333333, 0x222222, 0x555555, 0x666666],
BIOMES: ['urban', 'forest', 'desert', 'coastal', 'mountains']
};

// Game State
let game = {
active: false,
paused: false,
time: 0,
deltaTime: 0,
lastTime: 0,
kills: 0,
damageDealt: 0,
aliveCount: 50,
zonePhase: 0,
zoneTimer: 0,
zoneCenter: { x: 0, z: 0 },
zoneRadius: 400,
zoneTargetRadius: 400,
weather: 'clear',
weatherTimer: 0,
messages: [],
lootItems: [],
bots: [],
vehicles: [],
buildings: [],
trees: [],
rocks: [],
particles: [],
bullets: [],
explosions: []
};

// Player State
let player = {
health: 100,
armor: 0,
stamina: 100,
position: new THREE.Vector3(0, 10, 0),
velocity: new THREE.Vector3(0, 0, 0),
rotation: new THREE.Euler(0, 0, 0, 'YXZ'),
pitch: 0,
yaw: 0,
height: CONFIG.PLAYER_HEIGHT,
isSprinting: false,
isCrouching: false,
isProne: false,
isJumping: false,
isReloading: false,
reloadTime: 0,
reloadDuration: 2,
isInVehicle: false,
currentVehicle: null,
weapons: [
{ name: CONFIG.WEAPON_NAMES[0], ammo: 30, reserve: CONFIG.RESERVE_AMMO[0], damage: CONFIG.DAMAGE[0], fireRate: CONFIG.FIRE_RATE[0], recoil: CONFIG.RECOIL[0], type: 'ar' },
{ name: CONFIG.WEAPON_NAMES[1], ammo: 25, reserve: CONFIG.RESERVE_AMMO[1], damage: CONFIG.DAMAGE[1], fireRate: CONFIG.FIRE_RATE[1], recoil: CONFIG.RECOIL[1], type: 'smg' },
{ name: CONFIG.WEAPON_NAMES[2], ammo: 5, reserve: CONFIG.RESERVE_AMMO[2], damage: CONFIG.DAMAGE[2], fireRate: CONFIG.FIRE_RATE[2], recoil: CONFIG.RECOIL[2], type: 'sniper' },
{ name: CONFIG.WEAPON_NAMES[3], ammo: 8, reserve: CONFIG.RESERVE_AMMO[3], damage: CONFIG.DAMAGE[3], fireRate: CONFIG.FIRE_RATE[3], recoil: CONFIG.RECOIL[3], type: 'shotgun' },
{ name: CONFIG.WEAPON_NAMES[4], ammo: 12, reserve: CONFIG.RESERVE_AMMO[4], damage: CONFIG.DAMAGE[4], fireRate: CONFIG.FIRE_RATE[4], recoil: CONFIG.RECOIL[4], type: 'pistol' }
],
currentWeapon: 0,
isScoped: false,
scopeZoom: 1,
lastShot: 0,
isShooting: false,
bleedTimer: 0,
isDBNO: false,
fov: 70
};

// Input State
let input = {
keys: {},
mouseX: 0,
mouseY: 0,
mouseDown: false,
scrollDelta: 0
};

// Three.js Setup
let scene, camera, renderer, clock;
let minimapCanvas, minimapCtx;
let terrainMesh, terrainGeometry;
let rainSystem, fogSystem;
let sunLight, ambientLight;
let weaponMesh, weaponGroup;
let muzzleFlash;

function init() {
// Scene
scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.FogExp2(0x87CEEB, 0.002);

// Camera
camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 2000);
camera.position.set(0, 10, 0);

// Renderer
renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
document.body.appendChild(renderer.domElement);

// Clock
clock = new THREE.Clock();

// Lighting
ambientLight = new THREE.AmbientLight(0x404040, 0.5);
scene.add(ambientLight);

sunLight = new THREE.DirectionalLight(0xffffff, 1.0);
sunLight.position.set(100, 200, 100);
sunLight.castShadow = true;
sunLight.shadow.mapSize.width = 2048;
sunLight.shadow.mapSize.height = 2048;
sunLight.shadow.camera.near = 0.5;
sunLight.shadow.camera.far = 500;
sunLight.shadow.camera.left = -200;
sunLight.shadow.camera.right = 200;
sunLight.shadow.camera.top = 200;
sunLight.shadow.camera.bottom = -200;
scene.add(sunLight);

// Hemisphere light
const hemiLight = new THREE.HemisphereLight(0x87CEEB, 0x362907, 0.3);
scene.add(hemiLight);

// Minimap
minimapCanvas = document.getElementById('minimap-canvas');
minimapCtx = minimapCanvas.getContext('2d');

// Generate World
generateTerrain();
generateBuildings();
generateTrees();
generateRocks();
generateLoot();
generateVehicles();
generateBots();
generateWeather();

// Weapon Model
createWeaponModel();

// Event Listeners
setupEventListeners();

// Start Game Loop
animate();
}

function generateTerrain() {
// Create terrain with different biomes
const size = CONFIG.WORLD_SIZE;
const segments = 200;
terrainGeometry = new THREE.PlaneGeometry(size, size, segments, segments);
terrainGeometry.rotateX(-Math.PI / 2);

const vertices = terrainGeometry.attributes.position.array;
const colors = new Float32Array(vertices.length);

for (let i = 0; i < vertices.length; i += 3) {
const x = vertices[i];
const z = vertices[i + 2];

// Multi-octave noise for terrain
let height = 0;
height += Math.sin(x * 0.01) * Math.cos(z * 0.01) * 10;
height += Math.sin(x * 0.03 + 1) * Math.cos(z * 0.02 + 2) * 5;
height += Math.sin(x * 0.07 + 3) * Math.cos(z * 0.05 + 4) * 2;
height += Math.sin(x * 0.15 + 5) * Math.cos(z * 0.1 + 6) * 1;

// Create mountains in corners
const distFromCenter = Math.sqrt(x * x + z * z);
if (distFromCenter > 200) {
height += (distFromCenter - 200) * 0.1;
}

// Flatten center area for spawn
if (distFromCenter < 50) {
height *= distFromCenter / 50;
}

vertices[i + 1] = height;

// Biome coloring
let biome = getBiome(x, z);
let color = getBiomeColor(biome);

colors[i] = color.r;
colors[i + 1] = color.g;
colors[i + 2] = color.b;
}

terrainGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
terrainGeometry.computeVertexNormals();

const terrainMaterial = new THREE.MeshStandardMaterial({
vertexColors: true,
roughness: 0.8,
metalness: 0.2
});

terrainMesh = new THREE.Mesh(terrainGeometry, terrainMaterial);
terrainMesh.receiveShadow = true;
scene.add(terrainMesh);

// Water plane
const waterGeometry = new THREE.PlaneGeometry(size, size);
waterGeometry.rotateX(-Math.PI / 2);
const waterMaterial = new THREE.MeshStandardMaterial({
color: 0x006994,
transparent: true,
opacity: 0.6,
roughness: 0.1,
metalness: 0.8
});
const water = new THREE.Mesh(waterGeometry, waterMaterial);
water.position.y = -2;
water.receiveShadow = true;
scene.add(water);
}

function getBiome(x, z) {
const dist = Math.sqrt(x * x + z * z);
if (dist < 100) return 'urban';
if (dist < 200) return 'forest';
if (dist < 300) return 'desert';
if (dist < 400) return 'coastal';
return 'mountains';
}

function getBiomeColor(biome) {
switch (biome) {
case 'urban': return { r: 0.4, g: 0.4, b: 0.4 };
case 'forest': return { r: 0.2, g: 0.5, b: 0.15 };
case 'desert': return { r: 0.8, g: 0.7, b: 0.4 };
case 'coastal': return { r: 0.6, g: 0.7, b: 0.3 };
case 'mountains': return { r: 0.5, g: 0.5, b: 0.5 };
default: return { r: 0.3, g: 0.5, b: 0.2 };
}
}

function getTerrainHeight(x, z) {
let height = 0;
height += Math.sin(x * 0.01) * Math.cos(z * 0.01) * 10;
height += Math.sin(x * 0.03 + 1) * Math.cos(z * 0.02 + 2) * 5;
height += Math.sin(x * 0.07 + 3) * Math.cos(z * 0.05 + 4) * 2;
height += Math.sin(x * 0.15 + 5) * Math.cos(z * 0.1 + 6) * 1;

const distFromCenter = Math.sqrt(x * x + z * z);
if (distFromCenter > 200) {
height += (distFromCenter - 200) * 0.1;
}
if (distFromCenter < 50) {
height *= distFromCenter / 50;
}

return height;
}

function generateBuildings() {
const buildingMaterials = [
new THREE.MeshStandardMaterial({ color: 0x888888, roughness: 0.7 }),
new THREE.MeshStandardMaterial({ color: 0x666666, roughness: 0.7 }),
new THREE.MeshStandardMaterial({ color: 0x999999, roughness: 0.7 }),
new THREE.MeshStandardMaterial({ color: 0x777777, roughness: 0.7 })
];

for (let i = 0; i < CONFIG.BUILDING_COUNT; i++) {
const x = (Math.random() - 0.5) * CONFIG.WORLD_SIZE * 0.8;
