function setupEventListeners() {
// Keyboard
document.addEventListener('keydown', (e) => {
input.keys[e.code] = true;

if (e.code === 'KeyR' && game.active) {
reloadWeapon();
}
if (e.code === 'KeyQ' && game.active) {
switchWeapon();
}
if (e.code === 'KeyE' && game.active) {
interactWithLoot();
}
if (e.code === 'KeyF' && game.active) {
interactWithVehicle();
}
if (e.code >= 'Digit1' && e.code <= 'Digit5') {
const slot = parseInt(e.code.replace('Digit', '')) - 1;
if (slot < player.weapons.length) {
player.currentWeapon = slot;
updateWeaponUI();
}
}
if (e.code === 'Space' && game.active && !player.isJumping) {
player.isJumping = true;
player.velocity.y = CONFIG.JUMP_FORCE;
}
if (e.code === 'KeyC' && game.active) {
player.isCrouching = !player.isCrouching;
player.isProne = false;
updatePlayerHeight();
}
if (e.code === 'ControlLeft' && game.active) {
player.isProne = !player.isProne;
player.isCrouching = false;
updatePlayerHeight();
}
if (e.code === 'Escape' && game.active) {
togglePause();
}
});

document.addEventListener('keyup', (e) => {
input.keys[e.code] = false;
});

// Mouse
document.addEventListener('mousemove', (e) => {
if (!game.active || game.paused) return;

player.yaw -= e.movementX * CONFIG.MOUSE_SENSITIVITY;
player.pitch -= e.movementY * CONFIG.MOUSE_SENSITIVITY;
player.pitch = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, player.pitch));
});

document.addEventListener('mousedown', (e) => {
if (!game.active || game.paused) return;
if (e.button === 0) {
input.mouseDown = true;
player.isShooting = true;
}
if (e.button === 2) {
toggleScope();
}
});

document.addEventListener('mouseup', (e) => {
if (e.button === 0) {
input.mouseDown = false;
player.isShooting = false;
}
if (e.button === 2) {
toggleScope();
}
});

document.addEventListener('contextmenu', (e) => e.preventDefault());

document.addEventListener('wheel', (e) => {
if (!game.active) return;
if (player.isScoped) {
player.scopeZoom = Math.max(1, Math.min(15, player.scopeZoom + e.deltaY * 0.01));
}
});

// Window resize
window.addEventListener('resize', () => {
camera.aspect = window.innerWidth / window.innerHeight;
camera.updateProjectionMatrix();
renderer.setSize(window.innerWidth, window.innerHeight);
});
}

function updatePlayerHeight() {
if (player.isProne) {
player.height = CONFIG.PRONE_HEIGHT;
} else if (player.isCrouching) {
player.height = CONFIG.CROUCH_HEIGHT;
} else {
player.height = CONFIG.PLAYER_HEIGHT;
}
}

function toggleScope() {
player.isScoped = !player.isScoped;
const scopeOverlay = document.getElementById('scope-overlay');
if (player.isScoped) {
scopeOverlay.style.display = 'block';
camera.fov = 40;
} else {
scopeOverlay.style.display = 'none';
camera.fov = 70;
}
camera.updateProjectionMatrix();
}

function switchWeapon() {
player.currentWeapon = (player.currentWeapon + 1) % player.weapons.length;
updateWeaponUI();
}

function updateWeaponUI() {
const weapon = player.weapons[player.currentWeapon];
document.getElementById('weapon-name').textContent = weapon.name;
document.getElementById('ammo-display').innerHTML = `${weapon.ammo} <span class="ammo-reserve">/ ${weapon.reserve}</span>`;

// Update slot highlighting
document.querySelectorAll('#inventory .slot').forEach((slot, index) => {
slot.classList.toggle('active', index === player.currentWeapon);
});
}

function reloadWeapon() {
const weapon = player.weapons[player.currentWeapon];
if (weapon.ammo >= CONFIG.AMMO_CAP[player.currentWeapon] || weapon.reserve <= 0) return;

player.isReloading = true;
player.reloadTime = 0;
player.reloadDuration = 2;

document.getElementById('reload-indicator').style.display = 'block';
document.getElementById('reload-fill').style.width = '0%';
}

function finishReload() {
const weapon = player.weapons[player.currentWeapon];
const needed = CONFIG.AMMO_CAP[player.currentWeapon] - weapon.ammo;
const available = Math.min(needed, weapon.reserve);
weapon.ammo += available;
weapon.reserve -= available;

player.isReloading = false;
document.getElementById('reload-indicator').style.display = 'none';
updateWeaponUI();
}

function interactWithLoot() {
const playerPos = player.position;

for (let loot of game.lootItems) {
if (loot.picked) continue;
const dist = playerPos.distanceTo(loot.position);
if (dist < 3) {
applyLoot(loot);
loot.picked = true;
scene.remove(loot.mesh);
addMessage(`Picked up: ${loot.name}`);
break;
}
}
}

function applyLoot(loot) {
switch (loot.type) {
case 'health':
player.health = Math.min(CONFIG.MAX_HEALTH, player.health + loot.amount);
break;
case 'armor':
player.armor = Math.min(CONFIG.MAX_ARMOR, player.armor + loot.amount);
break;
case 'ammo':
player.weapons[player.currentWeapon].reserve += loot.amount;
break;
case 'stamina':
player.stamina = CONFIG.MAX_STAMINA;
break;
}
updateHealthUI();
updateWeaponUI();
}

function interactWithVehicle() {
const playerPos = player.position;

for (let vehicle of game.vehicles) {
const dist = playerPos.distanceTo(vehicle.position);
if (dist < 5 && !vehicle.occupied) {
enterVehicle(vehicle);
break;
}
}
}

function enterVehicle(vehicle) {
player.isInVehicle = true;
player.currentVehicle = vehicle;
vehicle.occupied = true;
player.position.copy(vehicle.position);
player.position.y += 2;

document.getElementById('vehicle-hud').style.display = 'block';
addMessage(`Entered ${vehicle.type}`);
}

function exitVehicle() {
if (!player.isInVehicle) return;

const vehicle = player.currentVehicle;
vehicle.occupied = false;
player.isInVehicle = false;
player.currentVehicle = null;

player.position.x = vehicle.position.x + 3;
player.position.z = vehicle.position.z;
player.position.y = getTerrainHeight(player.position.x, player.position.z) + player.height;

document.getElementById('vehicle-hud').style.display = 'none';
addMessage('Exited vehicle');
}

function shoot() {
const weapon = player.weapons[player.currentWeapon];
const now = performance.now() / 1000;

if (now - player.lastShot < weapon.fireRate) return;
if (player.isReloading) return;
if (weapon.ammo <= 0) {
reloadWeapon();
return;
}

player.lastShot = now;
weapon.ammo--;

// Recoil
player.pitch += weapon.recoil * (0.5 + Math.random() * 0.5);
player.yaw += (Math.random() - 0.5) * weapon.recoil * 0.5;

// Muzzle flash
muzzleFlash.visible = true;
setTimeout(() => { muzzleFlash.visible = false; }, 50);

// Raycasting for hit detection
const raycaster = new THREE.Raycaster();
raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);

// Check bot hits
let hit = false;
for (let bot of game.bots) {
if (!bot.alive) continue;

const botPos = bot.position.clone();
botPos.y += 0.9;

const direction = raycaster.ray.direction.clone();
const origin = camera.position.clone();

// Simple distance-based hit detection
const toBot = botPos.clone().sub(origin);
const projection = toBot.dot(direction);

if (projection > 0) {
const closestPoint = origin.clone().add(direction.clone().multiplyScalar(projection));
const distance = closestPoint.distanceTo(botPos);

if (distance < 1.5 && projection < 200) {
// Hit!
let damage = weapon.damage;
const headDist = bot.head.position.clone().sub(origin).distanceTo(camera.position);

// Headshot detection
if (headDist < 2) {
damage *= 2.5;
addMessage(`Headshot! ${bot.name} eliminated`);
} else {
addMessage(`Hit ${bot.name}`);
}

bot.health -= damage;
game.damageDealt += damage;

// Hit marker
showHitMarker();

// Blood effect
createBloodEffect(bot.position.clone());

if (bot.health <= 0) {
bot.alive = false;
game.kills++;
game.aliveCount--;
document.getElementById('kill-count-num').textContent = game.kills;
document.getElementById('alive-num').textContent = game.aliveCount;
addMessage(`${bot.name} eliminated!`);

// Drop loot
dropLoot(bot.position.clone());

// Remove bot mesh
scene.remove(bot.mesh);
scene.remove(bot.head);
scene.remove(bot.weapon);
}

hit = true;
break;
}
}
}

if (!hit) {
// Create bullet trail
createBulletTrail(camera.position.clone(), raycaster.ray.direction.clone());
}

updateWeaponUI();

// Auto reload
if (weapon.ammo <= 0 && weapon.reserve > 0) {
reloadWeapon();
}
}

function showHitMarker() {
const hitMarker = document.getElementById('hit-marker');
hitMarker.style.display = 'block';
setTimeout(() => { hitMarker.style.display = 'none'; }, 150);
}

function createBloodEffect(position) {
const bloodGeometry = new THREE.SphereGeometry(0.1, 4, 4);
const bloodMaterial = new THREE.MeshBasicMaterial({ color: 0xff0000 });

for (let i = 0; i < 5; i++) {
const blood = new THREE.Mesh(bloodGeometry, bloodMaterial);
blood.position.copy(position);
blood.position.x += (Math.random() - 0.5) * 0.5;
blood.position.y += (Math.random() - 0.5) * 0.5;
blood.position.z += (Math.random() - 0.5) * 0.5;
scene.add(blood);

game.particles.push({
mesh: blood,
velocity: new THREE.Vector3(
(Math.random() - 0.5) * 2,
Math.random() * 2,
(Math.random() - 0.5) * 2
),
life: 1.0
});
}
}

function createBulletTrail(origin, direction) {
const trailGeometry = new THREE.BufferGeometry();
const points = [
origin.clone(),
origin.clone().add(direction.clone().multiplyScalar(50))
];
trailGeometry.setFromPoints(points);

const trailMaterial = new THREE.LineBasicMaterial({
color: 0xffff00,
transparent: true,
opacity: 0.5
});

const trail = new THREE.Line(trailGeometry, trailMaterial);
scene.add(trail);

game.particles.push({
mesh: trail,
life: 0.1
});
}

function dropLoot(position) {
const lootTypes = [
{ name: 'Health Kit', type: 'health', color: 0x00ff00 },
{ name: 'Armor Vest', type: 'armor', color: 0x4488ff },
{ name: 'Ammo Box', type: 'ammo', color: 0xffaa00 }
];

const lootType = lootTypes[Math.floor(Math.random() * lootTypes.length)];
const geometry = new THREE.BoxGeometry(0.5, 0.5, 0.5);
const material = new THREE.MeshStandardMaterial({
color: lootType.color,
emissive: lootType.color,
emissiveIntensity: 0.3
});
const mesh = new THREE.Mesh(geometry, material);
mesh.position.copy(position);
mesh.position.y += 0.5;
scene.add(mesh);

game.lootItems.push({
mesh: mesh,
position: position.clone(),
type: lootType.type,
name: lootType.name,
icon: '📦',
color: lootType.color,
picked: false
});
}

function updateBots(dt) {
for (let bot of game.bots) {
if (!bot.alive) continue;

const distToPlayer = bot.position.distanceTo(player.position);

// State machine
switch (bot.state) {
case 'patrol':
if (distToPlayer < bot.visionRange && player.health > 0) {
bot.state = 'chase';
} else {
// Move towards patrol target
const dir = bot.patrolTarget.clone().sub(bot.position);
dir.y = 0;
if (dir.length() > 2) {
dir.normalize();
bot.position.x += dir.x * bot.speed * dt;
bot.position.z += dir.z * bot.speed * dt;
bot.position.y = getTerrainHeight(bot.position.x, bot.position.z);
} else {
// Pick new patrol target
bot.patrolTarget.set(
bot.position.x + (Math.random() - 0.5) * 100,
bot.position.y,
bot.position.z + (Math.random() - 0.5) * 100
);
}
}
break;

case 'chase':
if (distToPlayer > bot.visionRange * 1.5 || player.health <= 0) {
bot.state = 'patrol';
} else {
// Move towards player
const dir = player.position.clone().sub(bot.position);
dir.y = 0;
dir.normalize();
bot.position.x += dir.x * bot.speed * 1.5 * dt;
bot.position.z += dir.z * bot.speed * 1.5 * dt;
bot.position.y = getTerrainHeight(bot.position.x, bot.position.z);

// Shoot at player
if (distToPlayer < 50) {
botShoot(bot, dt);
}
}
break;

case 'shoot':
if (distToPlayer > 30) {
bot.state = 'chase';
} else {
botShoot(bot, dt);
}
break;
}

// Update bot mesh position
bot.mesh.position.copy(bot.position);
bot.mesh.position.y += 0.9;
bot.head.position.copy(bot.position);
bot.head.position.y += 1.9;
bot.weapon.position.copy(bot.position);
bot.weapon.position.y += 1.2;

// Bot health bar (simple text sprite would be better but keeping it simple)
}
}

function botShoot(bot, dt) {
const now = performance.now() / 1000;
if (now - bot.lastShot < bot.fireRate) return;

bot.lastShot = now;

const distToPlayer = bot.position.distanceTo(player.position);
if (distToPlayer > 50) return;

// Accuracy check
if (Math.random() > bot.accuracy) return;

// Deal damage to player
let damage = bot.damage;
player.health -= damage;
game.damageDealt += damage;

// Damage overlay
const overlay = document.getElementById('damage-overlay');
overlay.classList.add('hit');
setTimeout(() => { overlay.classList.remove('hit'); }, 200);

updateHealthUI();

if (player.health <= 0) {
playerDeath();
}
}

function playerDeath() {
game.active = false;
document.exitPointerLock();

document.getElementById('final-kills').textContent = game.kills;
document.getElementById('final-placement').textContent = `#${game.aliveCount}`;
document.getElementById('final-damage').textContent = Math.floor(game.damageDealt);
document.getElementById('death-screen').style.display = 'flex';
document.getElementById('hud').style.display = 'none';
}

function updateZone(dt) {
game.zoneTimer -= dt;

if (game.zoneTimer <= 0) {
game.zonePhase++;
if (game.zonePhase >= CONFIG.ZONE_PHASES) {
// Final zone - keep shrinking
game.zoneTargetRadius = Math.max(10, game.zoneTargetRadius - 5);
} else {
game.zoneTimer = CONFIG.ZONE_DURATIONS[game.zonePhase];
game.zoneTargetRadius = CONFIG.WORLD_SIZE * 0.5 * (1 - game.zonePhase / CONFIG.ZONE_PHASES);
addMessage(`Zone phase ${game.zonePhase + 1} started!`);
}
}

// Shrink zone
if (game.zoneRadius > game.zoneTargetRadius) {
game.zoneRadius -= CONFIG.ZONE_SHRINK_RATE[game.zonePhase] * dt;
}

// Check if player is in zone
const distFromCenter = Math.sqrt(
player.position.x * player.position.x +
player.position.z * player.position.z
);

if (distFromCenter > game.zoneRadius) {
const damage = CONFIG.ZONE_DAMAGE[game.zonePhase] * dt;
player.health -= damage;
updateHealthUI();

if (player.health <= 0) {
playerDeath();
}
}

// Update zone timer display
const minutes = Math.floor(game.zoneTimer / 60);
const seconds = Math.floor(game.zoneTimer % 60);
document.getElementById('zone-time').textContent =
`${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
document.getElementById('zone-phase').textContent =
`PHASE ${game.zonePhase + 1} / ${CONFIG.ZONE_PHASES}`;
}

function updateWeather(dt) {
game.weatherTimer -= dt;

if (game.weatherTimer <= 0) {
const weathers = ['clear', 'rain', 'fog', 'storm'];
game.weather = weathers[Math.floor(Math.random() * weathers.length)];
game.weatherTimer = 30 + Math.random() * 60;

switch (game.weather) {
case 'clear':
scene.fog.density = 0.002;
scene.background = new THREE.Color(0x87CEEB);
rainSystem.visible = false;
break;
case 'rain':
scene.fog.density = 0.005;
scene.background = new THREE.Color(0x666688);
rainSystem.visible = true;
break;
case 'fog':
scene.fog.density = 0.01;
scene.background = new THREE.Color(0x888888);
rainSystem.visible = false;
break;
case 'storm':
scene.fog.density = 0.015;
scene.background = new THREE.Color(0x444466);
rainSystem.visible = true;
break;
}
}

// Update rain particles
if (rainSystem.visible) {
const positions = rainSystem.geometry.attributes.position.array;
for (let i = 0; i < positions.length; i += 3) {
positions[i + 1] -= 50 * dt;
if (positions[i + 1] < 0) {
positions[i + 1] = 100;
}
}
rainSystem.geometry.attributes.position.needsUpdate = true;
}
}

function updateVehicles(dt) {
if (!player.isInVehicle || !player.currentVehicle) return;

const vehicle = player.currentVehicle;

// Vehicle movement
if (input.keys['KeyW']) {
const speed = vehicle.speed * dt;
vehicle.position.x += Math.sin(vehicle.rotation) * speed;
vehicle.position.z += Math.cos(vehicle.rotation) * speed;
}
if (input.keys['KeyS']) {
const speed = vehicle.speed * dt * 0.5;
vehicle.position.x -= Math.sin(vehicle.rotation) * speed;
vehicle.position.z -= Math.cos(vehicle.rotation) * speed;
}
if (input.keys['KeyA']) {
vehicle.rotation += 2 * dt;
}
if (input.keys['KeyD']) {
vehicle.rotation -= 2 * dt;
}

// Fuel consumption
vehicle.fuel -= dt * 0.5;
if (vehicle.fuel <= 0) {
vehicle.fuel = 0;
addMessage('Vehicle out of fuel!');
}

// Update vehicle position
vehicle.mesh.position.copy(vehicle.position);
vehicle.mesh.rotation.y = vehicle.rotation;

// Update player position
player.position.copy(vehicle.position);
player.position.y = getTerrainHeight(player.position.x, player.position.z) + 2;

// Update HUD
const speedKmh = Math.floor(vehicle.speed * (input.keys['KeyW'] || input.keys['KeyS'] ? 1 : 0));
document.getElementById('vehicle-speed').textContent = `${speedKmh} km/h`;
document.getElementById('vehicle-fuel').style.width = `${vehicle.fuel}%`;
document.getElementById('vehicle-fuel-text').textContent = `Fuel: ${Math.floor(vehicle.fuel)}%`;

// Exit vehicle
if (input.keys['KeyF'] && !input._fPressed) {
input._fPressed = true;
exitVehicle();
}
}

function updatePlayer(dt) {
if (player.isInVehicle) return;

// Movement
let speed = CONFIG.SPEED_WALK;
if (input.keys['ShiftLeft']) {
if (player.stamina > 0) {
speed = CONFIG.SPEED_SPRINT;
player.stamina -= CONFIG.STAMINA_SPRINT_COST * dt;
player.isSprinting = true;
} else {
player.isSprinting = false;
}
} else {
player.isSprinting = false;
player.stamina = Math.min(CONFIG.MAX_STAMINA, player.stamina + CONFIG.STAMINA_REGEN * dt);
}

if (player.isCrouching) speed = CONFIG.SPEED_CROUCH;
if (player.isProne) speed = CONFIG.SPEED_PRONE;

// Calculate movement direction
const forward = new THREE.Vector3(0, 0, -1);
forward.applyEuler(new THREE.Euler(0, player.yaw, 0));
const right = new THREE.Vector3(1, 0, 0);
right.applyEuler(new THREE.Euler(0, player.yaw, 0));

let moveX = 0;
let moveZ = 0;

if (input.keys['KeyW']) {
moveX += forward.x;
moveZ += forward.z;
}
if (input.keys['KeyS']) {
moveX -= forward.x;
moveZ -= forward.z;
}
if (input.keys['KeyA']) {
moveX -= right.x;
moveZ -= right.z;
}
if (input.keys['KeyD']) {
moveX += right.x;
moveZ += right.z;
}

// Normalize movement
if (moveX !== 0 || moveZ !== 0) {
const len = Math.sqrt(moveX * moveX + moveZ * moveZ);
moveX /= len;
moveZ /= len;
}

// Apply movement
player.position.x += moveX * speed * dt;
player.position.z += moveZ * speed * dt;

// Gravity
if (player.isJumping) {
player.velocity.y -= CONFIG.GRAVITY * dt;
}

player.position.y += player.velocity.y * dt;

// Terrain collision
const terrainHeight = getTerrainHeight(player.position.x, player.position.z);
if (player.position.y < terrainHeight + player.height) {
player.position.y = terrainHeight + player.height;
player.velocity.y = 0;
player.isJumping = false;
}

// World bounds
const halfWorld = CONFIG.WORLD_SIZE / 2;
player.position.x = Math.max(-halfWorld, Math.min(halfWorld, player.position.x));
player.position.z = Math.max(-halfWorld, Math.min(halfWorld, player.position.z));

// Update camera
camera.position.copy(player.position);
camera.rotation.copy(player.rotation);
camera.rotation.y = player.yaw;
camera.rotation.x = player.pitch;

// Update weapon position
if (weaponGroup) {
const bobAmount = player.isSprinting ? 0.05 : 0.02;
const bobSpeed = player.isSprinting ? 10 : 5;
const time = game.time;

weaponGroup.position.x = 0.3 + Math.sin(time * bobSpeed) * bobAmount * (moveX !== 0 || moveZ !== 0 ? 1 : 0);
weaponGroup.position.y = -0.3 + Math.cos(time * bobSpeed * 2) * bobAmount * 0.5 * (moveX !== 0 || moveZ !== 0 ? 1 : 0);

// Reload animation
if (player.isReloading) {
weaponGroup.rotation.x = -Math.sin(player.reloadTime / player.reloadDuration * Math.PI) * 0.5;
}
}

// Shooting
if (player.isShooting && !player.isReloading) {
shoot();
}

// Reload timer
if (player.isReloading) {
player.reloadTime += dt;
const progress = player.reloadTime / player.reloadDuration;
document.getElementById('reload-fill').style.width = `${progress * 100}%`;

if (player.reloadTime >= player.reloadDuration) {
finishReload();
}
}

// Update stamina UI
document.getElementById('stamina-fill').style.width = `${player.stamina}%`;
}

function updateHealthUI() {
document.getElementById('health-fill').style.width = `${player.health}%`;
document.getElementById('health-text').textContent = `HP: ${Math.floor(player.health)}`;
document.getElementById('armor-fill').style.width = `${player.armor}%`;
document.getElementById('armor-text').textContent = `ARMOR: ${Math.floor(player.armor)}`;
}

function updateMinimap() {
minimapCtx.fillStyle = '#1a1a2e';
minimapCtx.fillRect(0, 0, 200, 200);

const scale = 200 / CONFIG.WORLD_SIZE;
const centerX = 100;
const centerY = 100;

// Draw zone circle
minimapCtx.strokeStyle = '#ff4444';
minimapCtx.lineWidth = 2;
minimapCtx.beginPath();
minimapCtx.arc(centerX, centerY, game.zoneRadius * scale, 0, Math.PI * 2);
minimapCtx.stroke();

// Draw buildings
minimapCtx.fillStyle = '#666';
for (let building of game.buildings) {
const x = centerX + building.position.x * scale;
const y = centerY + building.position.z * scale;
minimapCtx.fillRect(x - 2, y - 2, 4, 4);
}

// Draw bots
minimapCtx.fillStyle = '#ff0000';
for (let bot of game.bots) {
if (!bot.alive) continue;
const x = centerX + bot.position.x * scale;
const y = centerY + bot.position.z * scale;
minimapCtx.beginPath();
minimapCtx.arc(x, y, 2, 0, Math.PI * 2);
minimapCtx.fill();
}

// Draw player
minimapCtx.fillStyle = '#00ff00';
const playerX = centerX + player.position.x * scale;
const playerY = centerY + player.position.z * scale;
minimapCtx.beginPath();
minimapCtx.arc(playerX, playerY, 3, 0, Math.PI * 2);
minimapCtx.fill();

// Player direction
minimapCtx.strokeStyle = '#00ff00';
minimapCtx.lineWidth = 1;
minimapCtx.beginPath();
minimapCtx.moveTo(playerX, playerY);
minimapCtx.lineTo(
playerX - Math.sin(player.yaw) * 10,
playerY - Math.cos(player.yaw) * 10
);
minimapCtx.stroke();

// Draw loot
minimapCtx.fillStyle = '#ffaa00';
for (let loot of game.lootItems) {
if (loot.picked) continue;
const x = centerX + loot.position.x * scale;
const y = centerY + loot.position.z * scale;
minimapCtx.fillRect(x - 1, y - 1, 2, 2);
}

// Draw vehicles
minimapCtx.fillStyle = '#8888ff';
for (let vehicle of game.vehicles) {
const x = centerX + vehicle.position.x * scale;
const y = centerY + vehicle.position.z * scale;
minimapCtx.fillRect(x - 3, y - 2, 6, 4);
}
}

function updateParticles(dt) {
for (let i = game.particles.length - 1; i >= 0; i--) {
const particle = game.particles[i];
particle.life -= dt;

if (particle.life <= 0) {
scene.remove(particle.mesh);
game.particles.splice(i, 1);
continue;
}

if (particle.velocity) {
particle.mesh.position.add(particle.velocity.clone().multiplyScalar(dt));
particle.velocity.y -= 9.8 * dt;
}

particle.mesh.material.opacity = particle.life;
}
}

function addMessage(text) {
const log = document.getElementById('message-log');
const msg = document.createElement('div');
msg.className = 'msg';
msg.textContent = text;
log.appendChild(msg);

setTimeout(() => { msg.classList.add('fade'); }, 3000);
setTimeout(() => { msg.remove(); }, 3500);

// Keep only last 5 messages
while (log.children.length > 5) {
log.removeChild(log.firstChild);
}
}

function togglePause() {
game.paused = !game.paused;
if (game.paused) {
document.exitPointerLock();
} else {
renderer.domElement.requestPointerLock();
}
}

function startGame() {
document.getElementById('menu-overlay').style.display = 'none';
document.getElementById('blocker').style.display = 'none';
document.getElementById('hud').style.display = 'block';

game.active = true;
game.time = 0;
game.zoneTimer = CONFIG.ZONE_DURATIONS[0];
game.zoneRadius = CONFIG.WORLD_SIZE * 0.5;

renderer.domElement.requestPointerLock();
addMessage('Game started! Good luck!');
addMessage('Zone will shrink in 60 seconds');
}

function showControls() {
alert('Controls:\n\nWASD - Move\nSHIFT - Sprint\nC - Crouch\nCTRL - Prone\nMouse - Aim\nLeft Click - Shoot\nR - Reload\nQ - Switch Weapon\nE - Interact with Loot\nF - Enter/Exit Vehicle\n1-5 - Select Weapon Slot\nSPACE - Jump\nESC - Pause');
}

function animate() {
requestAnimationFrame(animate);

const dt = Math.min(clock.getDelta(), 0.1);
game.time += dt;

if (game.active && !game.paused) {
updatePlayer(dt);
updateBots(dt);
updateZone(dt);
updateWeather(dt);
updateVehicles(dt);
updateParticles(dt);
updateMinimap();
}

renderer.render(scene, camera);
}

// Initialize
init();
</script>
