<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const minimapCanvas = document.getElementById('minimap');
const minimapCtx = minimapCanvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
minimapCanvas.width = 200;
minimapCanvas.height = 200;

window.addEventListener('resize', () => {
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
});

// Game State
const GAME_STATE = { MENU: 0, COUNTDOWN: 1, RACING: 2, FINISHED: 3 };
let gameState = GAME_STATE.MENU;
let selectedTrack = 0;
let raceTime = 0;
let countdownValue = 3;
let countdownTimer = 0;

// Tracks
const tracks = [
{
name: "NEON CITY",
color: "#ff006e",
groundColor: "#1a1a2e",
roadColor: "#333355",
borderColor: "#ff006e",
length: 8000,
width: 200,
segments: []
},
{
name: "DESERT STORM",
color: "#ff8c00",
groundColor: "#2a1a0a",
roadColor: "#4a3a2a",
borderColor: "#ff8c00",
length: 9000,
width: 220,
segments: []
},
{
name: "ICE RACE",
color: "#00bfff",
groundColor: "#0a1a2a",
roadColor: "#2a3a4a",
borderColor: "#00bfff",
length: 7500,
width: 190,
segments: []
},
{
name: "VOLCANO",
color: "#ff4500",
groundColor: "#1a0a0a",
roadColor: "#3a2a2a",
borderColor: "#ff4500",
length: 8500,
width: 210,
segments: []
},
{
name: "FOREST",
color: "#00ff00",
groundColor: "#0a1a0a",
roadColor: "#2a3a2a",
borderColor: "#00ff00",
length: 7000,
width: 180,
segments: []
},
{
name: "SPACE",
color: "#8a2be2",
groundColor: "#0a0a1a",
roadColor: "#1a1a3a",
borderColor: "#8a2be2",
length: 10000,
width: 230,
segments: []
}
];

// Generate track segments
function generateTrack(track) {
track.segments = [];
const numSegments = 200;
const angleStep = (Math.PI * 2) / numSegments;

for (let i = 0; i < numSegments; i++) {
const angle = i * angleStep;
const radius = 1500 + Math.sin(angle * 3) * 500 + Math.cos(angle * 5) * 300;
const x = Math.cos(angle) * radius;
const y = Math.sin(angle) * radius;
track.segments.push({ x, y, angle, index: i });
}
}

tracks.forEach(t => generateTrack(t));

// Kart class
class Kart {
constructor(color, name, isPlayer = false) {
this.color = color;
this.name = name;
this.isPlayer = isPlayer;
this.x = 0;
this.y = 0;
this.angle = 0;
this.speed = 0;
this.maxSpeed = 8 + Math.random() * 2;
this.acceleration = 0.15;
this.deceleration = 0.05;
this.turnSpeed = 0.04;
this.lap = 0;
this.segmentIndex = 0;
this.totalDistance = 0;
this.finishTime = 0;
this.powerups = [null, null, null];
this.activePowerup = null;
this.nitro = 100;
this.nitroActive = false;
this.hit = false;
this.hitTimer = 0;
this.trail = [];
this.width = 30;
this.height = 50;
}

reset(track, startOffset) {
const seg = track.segments[startOffset % track.segments.length];
this.x = seg.x;
this.y = seg.y;
this.angle = seg.angle + Math.PI / 2;
this.speed = 0;
this.lap = 0;
this.segmentIndex = startOffset;
this.totalDistance = 0;
this.finishTime = 0;
this.nitro = 100;
this.nitroActive = false;
this.hit = false;
this.hitTimer = 0;
this.trail = [];
this.powerups = [null, null, null];
this.activePowerup = null;
}

update(track, keys, otherKarts) {
if (this.hit) {
this.hitTimer--;
if (this.hitTimer <= 0) this.hit = false;
this.speed *= 0.95;
}

if (this.isPlayer) {
// Player controls
if (keys['ArrowUp'] || keys['w']) {
this.speed = Math.min(this.speed + this.acceleration, this.maxSpeed * (this.nitroActive ? 1.5 : 1));
}
if (keys['ArrowDown'] || keys['s']) {
this.speed = Math.max(this.speed - this.acceleration * 1.5, -this.maxSpeed * 0.3);
}
if (keys['ArrowLeft'] || keys['a']) {
this.angle -= this.turnSpeed * (this.speed / this.maxSpeed);
}
if (keys['ArrowRight'] || keys['d']) {
this.angle += this.turnSpeed * (this.speed / this.maxSpeed);
}

// Nitro
if ((keys[' '] || keys['Shift']) && this.nitro > 0 && this.speed > 2) {
this.nitroActive = true;
this.nitro = Math.max(0, this.nitro - 0.5);
} else {
this.nitroActive = false;
this.nitro = Math.min(100, this.nitro + 0.1);
}

// Use powerup
if (keys['1'] && this.powerups[0]) {
this.usePowerup(0);
keys['1'] = false;
}
if (keys['2'] && this.powerups[1]) {
this.usePowerup(1);
keys['2'] = false;
}
if (keys['3'] && this.powerups[2]) {
this.usePowerup(2);
keys['3'] = false;
}
} else {
// AI behavior
this.updateAI(track, otherKarts);
}

// Apply movement
this.x += Math.cos(this.angle) * this.speed;
this.y += Math.sin(this.angle) * this.speed;
this.totalDistance += Math.abs(this.speed);

// Trail
if (Math.abs(this.speed) > 2) {
this.trail.push({ x: this.x, y: this.y, alpha: 1 });
if (this.trail.length > 20) this.trail.shift();
}
this.trail.forEach(t => t.alpha -= 0.05);
this.trail = this.trail.filter(t => t.alpha > 0);

// Check segment progress
this.checkSegment(track);

// Check powerup collection
this.checkPowerups(track);

// Check collisions with other karts
if (!this.hit) {
otherKarts.forEach(other => {
if (other !== this) {
const dx = this.x - other.x;
const dy = this.y - other.y;
const dist = Math.sqrt(dx * dx + dy * dy);
if (dist < 40) {
this.speed *= 0.8;
other.speed *= 0.8;
if (this.isPlayer) {
this.hit = true;
this.hitTimer = 30;
}
}
}
});
}
}

updateAI(track, otherKarts) {
// Find next segment to target
const targetSeg = track.segments[(this.segmentIndex + 10) % track.segments.length];
const dx = targetSeg.x - this.x;
const dy = targetSeg.y - this.y;
const targetAngle = Math.atan2(dy, dx);

let angleDiff = targetAngle - this.angle;
while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

this.angle += angleDiff * 0.05;

// Speed control
const distToTarget = Math.sqrt(dx * dx + dy * dy);
if (distToTarget > 200) {
this.speed = Math.min(this.speed + this.acceleration, this.maxSpeed * 0.9);
} else if (Math.abs(angleDiff) > 0.5) {
this.speed = Math.max(this.speed - this.acceleration, this.maxSpeed * 0.3);
} else {
this.speed = Math.min(this.speed + this.acceleration * 0.5, this.maxSpeed * 0.85);
}

// Avoid other karts
otherKarts.forEach(other => {
if (other !== this) {
const dx2 = this.x - other.x;
const dy2 = this.y - other.y;
const dist2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);
if (dist2 < 60) {
this.angle += 0.05;
this.speed *= 0.95;
}
}
});
}

checkSegment(track) {
let minDist = Infinity;
let closestSeg = 0;

track.segments.forEach((seg, i) => {
const dx = this.x - seg.x;
const dy = this.y - seg.y;
const dist = dx * dx + dy * dy;
if (dist < minDist) {
minDist = dist;
closestSeg = i;
}
});

const prevIndex = this.segmentIndex;
this.segmentIndex = closestSeg;

// Check lap completion
if (prevIndex > track.segments.length * 0.9 && closestSeg < track.segments.length * 0.1) {
this.lap++;
if (this.lap >= 3 && this.finishTime === 0) {
this.finishTime = raceTime;
}
}
}

checkPowerups(track) {
track.powerups.forEach((pu, i) => {
if (pu && !pu.collected) {
const dx = this.x - pu.x;
const dy = this.y - pu.y;
const dist = Math.sqrt(dx * dx + dy * dy);
if (dist < 30) {
pu.collected = true;
this.addPowerup(pu.type);
}
}
});
}

addPowerup(type) {
for (let i = 0; i < 3; i++) {
if (!this.powerups[i]) {
this.powerups[i] = type;
return;
}
}
}

usePowerup(slot) {
const type = this.powerups[slot];
if (!type) return;

this.powerups[slot] = null;

switch (type) {
case 'red':
// Speed boost
this.speed = Math.min(this.speed + 5, this.maxSpeed * 1.5);
break;
case 'blue':
// Shield
this.hit = false;
this.hitTimer = 120;
break;
case 'yellow':
// Nitro boost
this.nitro = 100;
this.nitroActive = true;
setTimeout(() => { this.nitroActive = false; }, 3000);
break;
case 'green':
// Slow opponents
break;
case 'purple':
// Teleport forward
const nextSeg = track.segments[(this.segmentIndex + 20) % track.segments.length];
this.x = nextSeg.x;
this.y = nextSeg.y;
break;
}
}

draw(ctx) {
// Draw trail
this.trail.forEach(t => {
ctx.beginPath();
ctx.arc(t.x, t.y, 3, 0, Math.PI * 2);
ctx.fillStyle = `rgba(${this.color === '#ff006e' ? '255,0,110' : this.color === '#3a86ff' ? '58,134,255' : this.color === '#ff8c00' ? '255,140,0' : this.color === '#00ff00' ? '0,255,0' : '255,255,0'}, ${t.alpha * 0.3})`;
ctx.fill();
});

ctx.save();
ctx.translate(this.x, this.y);
ctx.rotate(this.angle);

// Kart body
ctx.fillStyle = this.color;
ctx.shadowColor = this.color;
ctx.shadowBlur = 15;
ctx.beginPath();
ctx.moveTo(0, -this.height / 2);
ctx.lineTo(-this.width / 2, this.height / 2);
ctx.lineTo(this.width / 2, this.height / 2);
ctx.closePath();
ctx.fill();

// Kart details
ctx.fillStyle = '#fff';
ctx.beginPath();
ctx.arc(0, -5, 5, 0, Math.PI * 2);
ctx.fill();

// Wheels
ctx.fillStyle = '#333';
ctx.fillRect(-this.width / 2 - 5, -this.height / 4, 8, 15);
ctx.fillRect(this.width / 2 - 3, -this.height / 4, 8, 15);
ctx.fillRect(-this.width / 2 - 5, this.height / 4 - 5, 8, 15);
ctx.fillRect(this.width / 2 - 3, this.height / 4 - 5, 8, 15);

// Nitro flame
if (this.nitroActive) {
ctx.fillStyle = '#0ff';
ctx.shadowColor = '#0ff';
ctx.shadowBlur = 20;
ctx.beginPath();
ctx.moveTo(-8, this.height / 2);
ctx.lineTo(0, this.height / 2 + 20 + Math.random() * 10);
ctx.lineTo(8, this.height / 2);
ctx.fill();
}

// Hit effect
if (this.hit) {
ctx.strokeStyle = '#ff0';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.arc(0, 0, 25, 0, Math.PI * 2);
ctx.stroke();
}

ctx.restore();

// Name tag
ctx.fillStyle = '#fff';
ctx.font = '12px Arial';
ctx.textAlign = 'center';
ctx.fillText(this.name, this.x, this.y - 35);
}
}

// Powerup on track
class PowerupItem {
constructor(x, y, type) {
this.x = x;
this.y = y;
this.type = type;
this.collected = false;
this.bobTimer = Math.random() * Math.PI * 2;
}

draw(ctx) {
if (this.collected) return;

this.bobTimer += 0.05;
const bob = Math.sin(this.bobTimer) * 5;

ctx.save();
ctx.translate(this.x, this.y + bob);

// Glow
ctx.shadowColor = this.getTypeColor();
ctx.shadowBlur = 20;

// Box
ctx.fillStyle = this.getTypeColor();
ctx.beginPath();
ctx.arc(0, 0, 15, 0, Math.PI * 2);
ctx.fill();

// Icon
ctx.fillStyle = '#fff';
ctx.font = '16px Arial';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillText(this.getTypeIcon(), 0, 0);

ctx.restore();
}

getTypeColor() {
switch (this.type) {
case 'red': return '#ff0000';
case 'blue': return '#0066ff';
case 'yellow': return '#ffff00';
case 'green': return '#00ff00';
case 'purple': return '#8800ff';
default: return '#ff0000';
}
}

getTypeIcon() {
switch (this.type) {
case 'red': return '⚡';
case 'blue': return '🛡️';
case 'yellow': return '🔥';
case 'green': return '🐌';
case 'purple': return '✨';
default: return '⚡';
}
}
}

// Game variables
let player;
let aiKarts = [];
let trackPowerups = [];
let keys = {};
let camera = { x: 0, y: 0 };
let particles = [];

const kartColors = ['#ff006e', '#3a86ff', '#ff8c00', '#00ff00', '#8a2be2', '#ff4500', '#00bfff', '#ffff00'];
const kartNames = ['PLAYER', 'VELOCITY', 'TURBO', 'BLAZE', 'SHADOW', 'NOVA', 'STORM', 'FLASH'];

function initRace() {
const track = tracks[selectedTrack];

// Create player
player = new Kart(kartColors[0], 'PLAYER', true);
player.reset(track, 0);

// Create AI karts
aiKarts = [];
for (let i = 1; i < 8; i++) {
const kart = new Kart(kartColors[i], kartNames[i], false);
kart.reset(track, i * 5);
kart.maxSpeed = 7 + Math.random() * 3;
aiKarts.push(kart);
}

// Create powerups on track
trackPowerups = [];
for (let i = 0; i < 30; i++) {
const segIndex = Math.floor(Math.random() * track.segments.length);
const seg = track.segments[segIndex];
const types = ['red', 'blue', 'yellow', 'green', 'purple'];
const type = types[Math.floor(Math.random() * types.length)];
trackPowerups.push(new PowerupItem(seg.x + (Math.random() - 0.5) * 100, seg.y + (Math.random() - 0.5) * 100, type));
}

// Reset state
raceTime = 0;
particles = [];
gameState = GAME_STATE.COUNTDOWN;
countdownValue = 3;
countdownTimer = 0;

document.getElementById('menu').style.display = 'none';
document.getElementById('track-select').style.display = 'none';
document.getElementById('results').style.display = 'none';
}

function showTrackSelect() {
document.getElementById('menu').style.display = 'none';
document.getElementById('track-select').style.display = 'flex';

const grid = document.getElementById('trackGrid');
grid.innerHTML = '';

tracks.forEach((track, i) => {
const card = document.createElement('div');
card.className = 'track-card' + (i === selectedTrack ? ' selected' : '');
card.style.background = `linear-gradient(135deg, ${track.color}33, ${track.color}11)`;
card.style.borderColor = track.color;
card.innerHTML = `<div style="font-size:30px;margin-bottom:5px;">🏁</div>${track.name}`;
card.onclick = () => {
selectedTrack = i;
document.querySelectorAll('.track-card').forEach(c => c.classList.remove('selected'));
card.classList.add('selected');
};
grid.appendChild(card);
});
}

function showControls() {
alert('CONTROLS:\n\n↑/W - Accelerate\n↓/S - Brake\n←/A - Turn Left\n→/D - Turn Right\nSPACE/SHIFT - Nitro\n1/2/3 - Use Powerup\n\nESC - Pause');
}

function backToMenu() {
gameState = GAME_STATE.MENU;
document.getElementById('menu').style.display = 'flex';
document.getElementById('track-select').style.display = 'none';
document.getElementById('results').style.display = 'none';
}

function restartRace() {
document.getElementById('results').style.display = 'none';
initRace();
}

function startRace() {
initRace();
}

// Input handling
document.addEventListener('keydown', (e) => {
keys[e.key] = true;
if (e.key === 'Escape') {
if (gameState === GAME_STATE.RACING) {
gameState = GAME_STATE.MENU;
document.getElementById('menu').style.display = 'flex';
}
}
});

document.addEventListener('keyup', (e) => {
keys[e.key] = false;
});

// Particle system
function createParticle(x, y, color, count = 5) {
for (let i = 0; i < count; i++) {
particles.push({
x, y,
vx: (Math.random() - 0.5) * 10,
vy: (Math.random() - 0.5) * 10,
life: 1,
color,
size: Math.random() * 5 + 2
});
}
}

function updateParticles() {
particles.forEach(p => {
p.x += p.vx;
p.y += p.vy;
p.life -= 0.02;
p.size *= 0.98;
});
particles = particles.filter(p => p.life > 0);
}

function drawParticles(ctx) {
particles.forEach(p => {
ctx.beginPath();
ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
ctx.fillStyle = p.color + Math.floor(p.life * 255).toString(16).padStart(2, '0');
ctx.fill();
});
}

// Drawing functions
function drawTrack(ctx, track) {
// Ground
ctx.fillStyle = track.groundColor;
ctx.fillRect(-5000, -5000, 10000, 10000);

// Draw road
ctx.strokeStyle = track.roadColor;
ctx.lineWidth = track.width;
ctx.lineCap = 'round';
ctx.lineJoin = 'round';

ctx.beginPath();
track.segments.forEach((seg, i) => {
if (i === 0) {
ctx.moveTo(seg.x, seg.y);
} else {
ctx.lineTo(seg.x, seg.y);
}
});
ctx.closePath();
ctx.stroke();

// Road borders
ctx.strokeStyle = track.borderColor;
ctx.lineWidth = track.width + 10;
ctx.globalAlpha = 0.3;
ctx.beginPath();
track.segments.forEach((seg, i) => {
if (i === 0) {
ctx.moveTo(seg.x, seg.y);
} else {
ctx.lineTo(seg.x, seg.y);
}
});
ctx.closePath();
ctx.stroke();
ctx.globalAlpha = 1;

// Center line
ctx.strokeStyle = '#fff';
ctx.lineWidth = 2;
ctx.setLineDash([20, 20]);
ctx.beginPath();
track.segments.forEach((seg, i) => {
if (i === 0) {
ctx.moveTo(seg.x, seg.y);
} else {
ctx.lineTo(seg.x, seg.y);
}
});
ctx.closePath();
ctx.stroke();
ctx.setLineDash([]);

// Start/finish line
const startSeg = track.segments[0];
const nextSeg = track.segments[1];
const startAngle = Math.atan2(nextSeg.y - startSeg.y, nextSeg.x - startSeg.x) + Math.PI / 2;

ctx.save();
ctx.translate(startSeg.x, startSeg.y);
ctx.rotate(startAngle);

// Checkered pattern
const checkSize = 10;
for (let row = 0; row < 4; row++) {
for (let col = 0; col < Math.floor(track.width / checkSize); col++) {
ctx.fillStyle = (row + col) % 2 === 0 ? '#fff' : '#000';
ctx.fillRect(-track.width / 2 + col * checkSize, -20 + row * checkSize, checkSize, checkSize);
}
}

ctx.restore();
}

function drawMinimap(track) {
minimapCtx.fillStyle = '#000';
minimapCtx.fillRect(0, 0, 200, 200);

const scale = 0.015;
const offsetX = 100;
const offsetY = 100;

// Draw track
minimapCtx.strokeStyle = track.borderColor;
minimapCtx.lineWidth = 3;
minimapCtx.beginPath();
track.segments.forEach((seg, i) => {
const x = seg.x * scale + offsetX;
const y = seg.y * scale + offsetY;
if (i === 0) minimapCtx.moveTo(x, y);
else minimapCtx.lineTo(x, y);
});
minimapCtx.closePath();
minimapCtx.stroke();

// Draw karts
aiKarts.forEach(kart => {
minimapCtx.fillStyle = kart.color;
minimapCtx.beginPath();
minimapCtx.arc(kart.x * scale + offsetX, kart.y * scale + offsetY, 3, 0, Math.PI * 2);
minimapCtx.fill();
});

// Draw player
minimapCtx.fillStyle = '#fff';
minimapCtx.beginPath();
minimapCtx.arc(player.x * scale + offsetX, player.y * scale + offsetY, 4, 0, Math.PI * 2);
minimapCtx.fill();
minimapCtx.strokeStyle = '#ff0';
minimapCtx.lineWidth = 2;
minimapCtx.stroke();
}

function updateHUD() {
// Position calculation
const allKarts = [player, ...aiKarts];
allKarts.sort((a, b) => {
if (b.lap !== a.lap) return b.lap - a.lap;
return b.totalDistance - a.totalDistance;
});

const playerPos = allKarts.indexOf(player) + 1;
document.getElementById('position').textContent = `${playerPos}/8`;

// Lap
document.getElementById('lap').textContent = `${Math.min(player.lap + 1, 3)}/3`;

// Time
const minutes = Math.floor(raceTime / 60);
const seconds = Math.floor(raceTime % 60);
document.getElementById('time').textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

// Speed
document.getElementById('speed').textContent = `${Math.floor(Math.abs(player.speed) * 30)} km/h`;

// Nitro
document.getElementById('nitro-fill').style.width = `${player.nitro}%`;

// Powerup slots
for (let i = 0; i < 3; i++) {
const slot = document.getElementById(`slot${i}`);
if (player.powerups[i]) {
slot.classList.add('active');
const icons = { red: '⚡', blue: '🛡️', yellow: '🔥', green: '🐌', purple: '✨' };
slot.textContent = icons[player.powerups[i]] || '?';
} else {
slot.classList.remove('active');
slot.textContent = '';
}
}
}

function updateCamera() {
camera.x = player.x - canvas.width / 2;
camera.y = player.y - canvas.height / 2;
}

function drawBackground(ctx, track) {
// Grid pattern
ctx.strokeStyle = track.borderColor + '22';
ctx.lineWidth = 1;
const gridSize = 100;
const startX = -camera.x % gridSize;
const startY = -camera.y % gridSize;

for (let x = startX; x < canvas.width; x += gridSize) {
ctx.beginPath();
ctx.moveTo(x, 0);
ctx.lineTo(x, canvas.height);
ctx.stroke();
}
for (let y = startY; y < canvas.height; y += gridSize) {
ctx.beginPath();
ctx.moveTo(0, y);
ctx.lineTo(canvas.width, y);
ctx.stroke();
}
}

function drawSpeedLines(ctx) {
if (Math.abs(player.speed) > 6) {
const opacity = (Math.abs(player.speed) - 6) / 4;
ctx.strokeStyle = `rgba(255,255,255,${opacity * 0.3})`;
ctx.lineWidth = 2;

for (let i = 0; i < 10; i++) {
const x = Math.random() * canvas.width;
const y = Math.random() * canvas.height;
const length = 50 + Math.random() * 100;

ctx.beginPath();
ctx.moveTo(x, y);
ctx.lineTo(x - Math.cos(player.angle) * length, y - Math.sin(player.angle) * length);
ctx.stroke();
}
}
}

// Main game loop
function gameLoop() {
requestAnimationFrame(gameLoop);

const track = tracks[selectedTrack];

if (gameState === GAME_STATE.COUNTDOWN) {
countdownTimer++;
if (countdownTimer % 60 === 0) {
countdownValue--;
if (countdownValue <= 0) {
gameState = GAME_STATE.RACING;
document.getElementById('countdown').style.display = 'none';
}
}

const countdownEl = document.getElementById('countdown');
countdownEl.style.display = 'block';
countdownEl.textContent = countdownValue > 0 ? countdownValue : 'GO!';
countdownEl.style.color = countdownValue > 0 ? '#fff' : '#0f0';

// Still draw the scene
ctx.fillStyle = track.groundColor;
ctx.fillRect(0, 0, canvas.width, canvas.height);

ctx.save();
ctx.translate(-camera.x, -camera.y);
drawTrack(ctx, track);
trackPowerups.forEach(pu => pu.draw(ctx));
aiKarts.forEach(kart => kart.draw(ctx));
player.draw(ctx);
ctx.restore();

drawMinimap(track);
updateCamera();
}

if (gameState === GAME_STATE.RACING) {
raceTime += 1 / 60;

// Update all karts
aiKarts.forEach(kart => kart.update(track, keys, [player, ...aiKarts]));
player.update(track, keys, aiKarts);

// Update particles
updateParticles();

// Check if race is over
if (player.finishTime > 0 && gameState === GAME_STATE.RACING) {
gameState = GAME_STATE.FINISHED;
showResults();
}

// Update camera
updateCamera();

// Draw everything
ctx.fillStyle = track.groundColor;
ctx.fillRect(0, 0, canvas.width, canvas.height);

drawBackground(ctx, track);

ctx.save();
ctx.translate(-camera.x, -camera.y);

drawTrack(ctx, track);
trackPowerups.forEach(pu => pu.draw(ctx));
aiKarts.forEach(kart => kart.draw(ctx));
player.draw(ctx);
drawParticles(ctx);

ctx.restore();

drawSpeedLines(ctx);
drawMinimap(track);
updateHUD();
}

if (gameState === GAME_STATE.FINISHED) {
updateHUD();
}
}

function showResults() {
const allKarts = [player, ...aiKarts];
allKarts.sort((a, b) => {
if (b.lap !== a.lap) return b.lap - a.lap;
if (b.finishTime !== a.finishTime) return b.finishTime - a.finishTime;
return b.totalDistance - a.totalDistance;
});

const playerPos = allKarts.indexOf(player) + 1;
const posText = ['1st', '2nd', '3rd', '4th', '5th', '6th', '7th', '8th'][playerPos - 1];

document.getElementById('finalPos').textContent = posText;
document.getElementById('finalPos').style.color = playerPos === 1 ? '#ff0' : '#fff';

const minutes = Math.floor(raceTime / 60);
const seconds = Math.floor(raceTime % 60);
document.getElementById('finalTime').textContent = `Time: ${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
document.getElementById('finalLaps').textContent = `Laps: ${Math.min(player.lap + 1, 3)}/3`;

document.getElementById('results').style.display = 'flex';
}

// Start the game loop
gameLoop();
</script>
</body>
</html>

