for (let i = 0; i < 15; i++) {
decorations.push({
x: i * 450 + Math.random() * 200,
y: canvas.height - 40,
type: 'hill',
size: 80 + Math.random() * 60
});
}
}

function resetPlayer() {
player.x = 100;
player.y = 400;
player.vx = 0;
player.vy = 0;
player.onGround = false;
player.dead = false;
player.deathTimer = 0;
player.winning = false;
player.winTimer = 0;
player.invincible = 0;
player.big = false;
cameraX = 0;
}

function startGame() {
initAudio();
document.getElementById('startScreen').style.display = 'none';
document.getElementById('gameOverScreen').style.display = 'none';
document.getElementById('winScreen').style.display = 'none';
score = 0;
coins = 0;
lives = 3;
generateLevel();
resetPlayer();
gameRunning = true;
updateUI();
}

function updateUI() {
document.getElementById('coinCount').textContent = coins;
document.getElementById('lives').textContent = lives;
document.getElementById('score').textContent = score;
}

function addParticle(x, y, color, count = 5) {
for (let i = 0; i < count; i++) {
particles.push({
x, y,
vx: (Math.random() - 0.5) * 8,
vy: (Math.random() - 0.5) * 8 - 3,
life: 30 + Math.random() * 20,
maxLife: 50,
color,
size: 2 + Math.random() * 4
});
}
}

function addFloatingText(x, y, text, color = '#fff') {
floatingTexts.push({ x, y, text, color, life: 60, vy: -2 });
}

function checkCollision(a, b) {
return a.x < b.x + b.width && a.x + a.width > b.x &&
a.y < b.y + b.height && a.y + a.height > b.y;
}

function update() {
if (!gameRunning) return;
time++;
dayTime = (Math.sin(time * 0.001) + 1) * 0.5;

if (player.dead) {
player.deathTimer++;
player.vy += 0.3;
player.y += player.vy;
if (player.deathTimer > 120) {
lives--;
updateUI();
if (lives <= 0) {
gameRunning = false;
document.getElementById('finalScore').textContent = score;
document.getElementById('gameOverScreen').style.display = 'flex';
} else {
resetPlayer();
}
}
return;
}

if (player.winning) {
player.winTimer++;
if (player.winTimer < 60) {
player.y += 2;
} else if (player.winTimer < 120) {
player.vx = 3;
player.x += player.vx;
player.facing = 1;
} else {
gameRunning = false;
playWinSound();
document.getElementById('winScore').textContent = score;
document.getElementById('winScreen').style.display = 'flex';
}
return;
}

// Input
let moveSpeed = keys['ShiftLeft'] || keys['ShiftRight'] ? player.runSpeed : player.speed;
if (keys['ArrowLeft'] || keys['KeyA']) {
player.vx = -moveSpeed;
player.facing = -1;
} else if (keys['ArrowRight'] || keys['KeyD']) {
player.vx = moveSpeed;
player.facing = 1;
} else {
player.vx *= 0.8;
if (Math.abs(player.vx) < 0.1) player.vx = 0;
}

if ((keys['Space'] || keys['ArrowUp'] || keys['KeyW']) && player.onGround) {
player.vy = player.jumpForce;
player.onGround = false;
playJumpSound();
}

// Gravity
player.vy += player.gravity;
if (player.vy > 15) player.vy = 15;

// Move X
player.x += player.vx;

// Collision X
for (let p of platforms) {
if (checkCollision(player, p)) {
if (player.vx > 0) {
player.x = p.x - player.width;
} else if (player.vx < 0) {
player.x = p.x + p.width;
}
player.vx = 0;
}
}

// Move Y
player.y += player.vy;
player.onGround = false;

// Collision Y
for (let p of platforms) {
if (checkCollision(player, p)) {
if (player.vy > 0) {
player.y = p.y - player.height;
player.vy = 0;
player.onGround = true;
} else if (player.vy < 0) {
player.y = p.y + p.height;
player.vy = 0;
// Hit question block
if (p.type === 'question') {
p.type = 'brick_used';
score += 100;
coins++;
playCoinSound();
addParticle(p.x + p.width/2, p.y, '#ffd700', 8);
addFloatingText(p.x + p.width/2, p.y - 20, '+100', '#ffd700');
updateUI();
}
}
}
}

// Pipe collision
for (let pipe of pipes) {
if (checkCollision(player, pipe)) {
if (player.vx > 0) player.x = pipe.x - player.width;
else if (player.vx < 0) player.x = pipe.x + pipe.width;
}
}

// World bounds
if (player.x < 0) player.x = 0;
if (player.x > levelWidth - player.width) player.x = levelWidth - player.width;

// Fall death
if (player.y > canvas.height + 100) {
player.dead = true;
player.vy = -10;
playDeathSound();
}

// Animation
if (Math.abs(player.vx) > 0.5) {
player.animTimer += Math.abs(player.vx) * 0.1;
if (player.animTimer > 1) {
player.animFrame = (player.animFrame + 1) % 4;
player.animTimer = 0;
}
} else {
player.animFrame = 0;
}

// Invincibility
if (player.invincible > 0) player.invincible--;

// Coins
for (let c of coinItems) {
if (!c.collected && checkCollision(player, c)) {
c.collected = true;
coins++;
score += 50;
playCoinSound();
addParticle(c.x + 10, c.y + 10, '#ffd700', 6);
addFloatingText(c.x, c.y - 10, '+50', '#ffd700');
updateUI();
}
c.animTimer += 0.05;
}

// Enemies
for (let e of enemies) {
if (!e.alive) {
if (e.squishTimer > 0) e.squishTimer--;
continue;
}

// Only update if near camera
if (Math.abs(e.x - cameraX) > canvas.width + 100) continue;

e.animTimer += 0.1;
if (e.animTimer > 1) {
e.animFrame = (e.animFrame + 1) % 2;
e.animTimer = 0;
}

if (e.shell) {
e.x += e.shellSpeed;
// Shell collision with other enemies
for (let other of enemies) {
if (other !== e && other.alive && checkCollision(e, other)) {
other.alive = false;
score += 200;
addParticle(other.x + 16, other.y + 16, '#ff0000', 8);
addFloatingText(other.x, other.y - 10, '+200', '#ff0000');
updateUI();
playStompSound();
}
}
} else {
e.x += e.vx;
}

// Enemy platform collision
for (let p of platforms) {
if (checkCollision(e, p)) {
if (e.vx > 0 && e.x + e.width > p.x && e.x < p.x) {
e.vx = -e.vx;
e.x = p.x - e.width;
} else if (e.vx < 0 && e.x < p.x + p.width && e.x + e.width > p.x + p.width) {
e.vx = -e.vx;
e.x = p.x + p.width;
}
}
}

// Enemy fall
if (e.y > canvas.height + 100) {
e.alive = false;
}

// Player collision with enemy
if (e.alive && player.invincible <= 0 && checkCollision(player, e)) {
if (player.vy > 0 && player.y + player.height - e.y < 20) {
// Stomp
if (e.type === 'koopa' && !e.shell) {
e.shell = true;
e.height = 24;
e.y += 8;
e.vx = 0;
e.shellSpeed = 0;
score += 100;
addFloatingText(e.x, e.y - 10, '+100', '#fff');
} else {
e.alive = false;
e.squishTimer = 30;
}
player.vy = -8;
playStompSound();
score += 100;
addParticle(e.x + 16, e.y + 16, '#ff0000', 6);
addFloatingText(e.x, e.y - 20, '+100', '#fff');
updateUI();
} else if (e.shell && e.shellSpeed === 0) {
e.shellSpeed = player.x < e.x ? 6 : -6;
playStompSound();
} else if (e.shell && e.shellSpeed !== 0) {
// Shell hits player
player.dead = true;
player.vy = -10;
playDeathSound();
} else {
player.dead = true;
player.vy = -10;
playDeathSound();
}
}
}

// Flag pole
if (flagPole && !player.winning && checkCollision(player, { x: flagPole.x - 10, y: flagPole.y, width: flagPole.width + 20, height: flagPole.height })) {
player.winning = true;
player.winTimer = 0;
player.vx = 0;
player.vy = 0;
score += 1000;
addFloatingText(flagPole.x, flagPole.y, '+1000', '#ffd700');
updateUI();
}

// Camera
let targetCameraX = player.x - canvas.width / 3;
cameraX += (targetCameraX - cameraX) * 0.1;
if (cameraX < 0) cameraX = 0;
if (cameraX > levelWidth - canvas.width) cameraX = levelWidth - canvas.width;

// Particles
particles = particles.filter(p => {
p.x += p.vx;
p.y += p.vy;
p.vy += 0.2;
p.life--;
return p.life > 0;
});

// Floating texts
floatingTexts = floatingTexts.filter(ft => {
ft.y += ft.vy;
ft.life--;
return ft.life > 0;
});
}

function drawMario(x, y) {
const p = player;
if (p.invincible > 0 && Math.floor(p.invincible / 3) % 2 === 0) return;

ctx.save();
ctx.translate(x + p.width/2, y + p.height/2);
ctx.scale(p.facing, 1);
ctx.translate(-p.width/2, -p.height/2);

const w = p.width;
const h = p.height;

// Hat
ctx.fillStyle = '#e74c3c';
ctx.fillRect(2, 0, w - 4, 12);
ctx.fillRect(0, 4, w, 8);

// Face
ctx.fillStyle = '#fdbcb4';
ctx.fillRect(4, 12, w - 8, 14);

// Eyes
ctx.fillStyle = '#000';
ctx.fillRect(w - 12, 14, 4, 4);

// Mustache
ctx.fillStyle = '#8b4513';
ctx.fillRect(w - 14, 20, 10, 3);

// Body
ctx.fillStyle = '#e74c3c';
ctx.fillRect(2, 26, w - 4, 12);

// Overalls
ctx.fillStyle = '#3498db';
ctx.fillRect(4, 32, w - 8, 12);

// Legs
if (!p.onGround) {
// Jumping pose
ctx.fillStyle = '#3498db';
ctx.fillRect(2, 40, 10, 8);
ctx.fillRect(w - 12, 36, 10, 8);
ctx.fillStyle = '#8b4513';
ctx.fillRect(0, 44, 10, 4);
ctx.fillRect(w - 10, 40, 10, 4);
} else if (Math.abs(p.vx) > 0.5) {
// Walking animation
const legOffset = Math.sin(p.animTimer * 3) * 4;
ctx.fillStyle = '#3498db';
ctx.fillRect(4 + legOffset, 40, 10, 8);
ctx.fillRect(w - 14 - legOffset, 40, 10, 8);
ctx.fillStyle = '#8b4513';
ctx.fillRect(2 + legOffset, 46, 12, 4);
ctx.fillRect(w - 16 - legOffset, 46, 12, 4);
} else {
// Standing
ctx.fillStyle = '#3498db';
ctx.fillRect(4, 40, 10, 8);
ctx.fillRect(w - 14, 40, 10, 8);
ctx.fillStyle = '#8b4513';
ctx.fillRect(2, 46, 12, 4);
ctx.fillRect(w - 14, 46, 12, 4);
}

ctx.restore();
}

function drawGoomba(e) {
const x = e.x - cameraX;
const y = e.y;

if (!e.alive && e.squishTimer > 0) {
// Squished
ctx.fillStyle = '#8b4513';
ctx.fillRect(x, y + 24, 32, 8);
return;
}
if (!e.alive) return;

ctx.save();
ctx.translate(x + 16, y + 16);

// Body
ctx.fillStyle = '#8b4513';
ctx.beginPath();
ctx.arc(0, 0, 16, 0, Math.PI * 2);
ctx.fill();

// Face
ctx.fillStyle = '#fdbcb4';
ctx.fillRect(-8, -4, 16, 10);

// Eyes
ctx.fillStyle = '#000';
ctx.fillRect(-6, -2, 4, 5);
ctx.fillRect(2, -2, 4, 5);

// Angry eyebrows
ctx.fillStyle = '#000';
ctx.fillRect(-7, -5, 5, 2);
ctx.fillRect(2, -5, 5, 2);

// Feet
const footOffset = Math.sin(e.animTimer * 3) * 3;
ctx.fillStyle = '#000';
ctx.fillRect(-12 + footOffset, 12, 8, 6);
ctx.fillRect(4 - footOffset, 12, 8, 6);

ctx.restore();
}

function drawKoopa(e) {
const x = e.x - cameraX;
const y = e.y;

if (!e.alive) return;

ctx.save();
ctx.translate(x + 16, y + (e.shell ? 12 : 16));

if (e.shell) {
// Shell
ctx.fillStyle = '#2ecc71';
ctx.beginPath();
ctx.arc(0, 0, 14, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#f1c40f';
ctx.beginPath();
ctx.arc(0, 0, 8, 0, Math.PI * 2);
ctx.fill();
} else {
// Body
ctx.fillStyle = '#2ecc71';
ctx.beginPath();
ctx.arc(0, -4, 14, 0, Math.PI * 2);
ctx.fill();

// Head
ctx.fillStyle = '#f1c40f';
ctx.beginPath();
ctx.arc(0, -16, 10, 0, Math.PI * 2);
ctx.fill();

// Eyes
ctx.fillStyle = '#000';
ctx.fillRect(-4, -18, 3, 4);
ctx.fillRect(2, -18, 3, 4);

// Shell
ctx.fillStyle = '#2ecc71';
ctx.beginPath();
ctx.arc(0, 4, 12, 0, Math.PI);
ctx.fill();

// Feet
const footOffset = Math.sin(e.animTimer * 3) * 3;
ctx.fillStyle = '#f1c40f';
ctx.fillRect(-10 + footOffset, 10, 8, 6);
ctx.fillRect(2 - footOffset, 10, 8, 6);
}

ctx.restore();
}

function draw() {
// Sky gradient
const skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
skyGrad.addColorStop(0, `hsl(${200 + dayTime * 20}, 70%, ${60 + dayTime * 20}%)`);
skyGrad.addColorStop(0.5, `hsl(${190 + dayTime * 30}, 60%, ${70 + dayTime * 15}%)`);
skyGrad.addColorStop(1, `hsl(${180 + dayTime * 20}, 50%, ${80 + dayTime * 10}%)`);
ctx.fillStyle = skyGrad;
ctx.fillRect(0, 0, canvas.width, canvas.height);

// Sun/Moon
const sunX = canvas.width * 0.8 - cameraX * 0.02;
const sunY = 80 + Math.sin(time * 0.005) * 30;
ctx.fillStyle = '#ffd700';
ctx.beginPath();
ctx.arc(sunX, sunY, 40, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = 'rgba(255, 215, 0, 0.2)';
ctx.beginPath();
ctx.arc(sunX, sunY, 60, 0, Math.PI * 2);
ctx.fill();

// Clouds (parallax)
ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
decorations.filter(d => d.type === 'cloud').forEach(c => {
const cx = c.x - cameraX * 0.3;
const cy = c.y;
ctx.beginPath();
ctx.arc(cx, cy, c.size, 0, Math.PI * 2);
ctx.arc(cx + c.size * 0.8, cy - c.size * 0.2, c.size * 0.7, 0, Math.PI * 2);
ctx.arc(cx + c.size * 1.4, cy, c.size * 0.8, 0, Math.PI * 2);
ctx.arc(cx + c.size * 0.5, cy + c.size * 0.2, c.size * 0.6, 0, Math.PI * 2);
ctx.fill();
});

// Hills (parallax)
ctx.fillStyle = '#27ae60';
decorations.filter(d => d.type === 'hill').forEach(h => {
const hx = h.x - cameraX * 0.5;
const hy = h.y;
ctx.beginPath();
ctx.arc(hx, hy, h.size, Math.PI, 0);
ctx.fill();
ctx.fillStyle = '#2ecc71';
ctx.beginPath();
ctx.arc(hx, hy, h.size * 0.7, Math.PI, 0);
ctx.fill();
ctx.fillStyle = '#27ae60';
});

// Bushes
decorations.filter(d => d.type === 'bush').forEach(b => {
const bx = b.x - cameraX * 0.7;
const by = b.y;
ctx.fillStyle = '#27ae60';
ctx.beginPath();
ctx.arc(bx, by, b.size * 0.5, 0, Math.PI * 2);
ctx.arc(bx + b.size * 0.6, by - b.size * 0.1, b.size * 0.4, 0, Math.PI * 2);
ctx.arc(bx + b.size * 1.2, by, b.size * 0.45, 0, Math.PI * 2);
ctx.fill();
});

// Platforms
platforms.forEach(p => {
const px = p.x - cameraX;
if (px > canvas.width + 50 || px + p.width < -50) return;

if (p.type === 'ground') {
// Ground block
ctx.fillStyle = '#8b4513';
ctx.fillRect(px, p.y, p.width, p.height);
ctx.fillStyle = '#27ae60';
ctx.fillRect(px, p.y, p.width, 8);
ctx.fillStyle = '#2ecc71';
ctx.fillRect(px, p.y, p.width, 4);
// Texture
ctx.fillStyle = '#a0522d';
for (let i = 0; i < p.width; i += 20) {
ctx.fillRect(px + i, p.y + 12, 2, p.height - 12);
}
} else if (p.type === 'brick') {
ctx.fillStyle = '#c0392b';
ctx.fillRect(px, p.y, p.width, p.height);
ctx.fillStyle = '#e74c3c';
ctx.fillRect(px + 2, p.y + 2, p.width - 4, p.height - 4);
ctx.fillStyle = '#a93226';
ctx.fillRect(px, p.y + p.height - 4, p.width, 4);
// Brick lines
ctx.fillStyle = '#922b21';
for (let i = 0; i < p.width; i += 20) {
ctx.fillRect(px + i, p.y, 2, p.height);
}
for (let j = 0; j < p.height; j += 16) {
ctx.fillRect(px, p.y + j, p.width, 2);
}
} else if (p.type === 'question') {
ctx.fillStyle = '#f39c12';
ctx.fillRect(px, p.y, p.width, p.height);
ctx.fillStyle = '#f1c40f';
ctx.fillRect(px + 2, p.y + 2, p.width - 4, p.height - 4);
ctx.fillStyle = '#e67e22';
ctx.fillRect(px, p.y + p.height - 4, p.width, 4);
// Question mark
ctx.fillStyle = '#fff';
ctx.font = 'bold 20px Arial';
ctx.textAlign = 'center';
ctx.fillText('?', px + p.width/2, p.y + p.height/2 + 7);
} else if (p.type === 'brick_used') {
ctx.fillStyle = '#7f8c8d';
ctx.fillRect(px, p.y, p.width, p.height);
ctx.fillStyle = '#95a5a6';
ctx.fillRect(px + 2, p.y + 2, p.width - 4, p.height - 4);
} else if (p.type === 'pipe') {
// Pipe body
ctx.fillStyle = '#27ae60';
ctx.fillRect(px + 4, p.y + 20, p.width - 8, p.height - 20);
ctx.fillStyle = '#2ecc71';
ctx.fillRect(px + 6, p.y + 20, p.width - 12, p.height - 20);
// Pipe top
ctx.fillStyle = '#27ae60';
ctx.fillRect(px, p.y, p.width, 24);
ctx.fillStyle = '#2ecc71';
ctx.fillRect(px + 2, p.y + 2, p.width - 4, 20);
ctx.fillStyle = '#1e8449';
ctx.fillRect(px, p.y + 20, p.width, 4);
}
});

// Coins
coinItems.forEach(c => {
if (c.collected) return;
const cx = c.x - cameraX;
if (cx > canvas.width + 50 || cx < -50) return;

const bounce = Math.sin(c.animTimer) * 3;
ctx.fillStyle = '#ffd700';
ctx.beginPath();
ctx.arc(cx + 10, c.y + 10 + bounce, 10, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#f39c12';
ctx.beginPath();
ctx.arc(cx + 10, c.y + 10 + bounce, 7, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#ffd700';
ctx.font = 'bold 12px Arial';
ctx.textAlign = 'center';
ctx.fillText('$', cx + 10, c.y + 14 + bounce);
});

// Pipes (visual only, platforms handled above)
pipes.forEach(p => {
const px = p.x - cameraX;
if (px > canvas.width + 50 || px < -50) return;
// Already drawn as platforms
});

// Enemies
enemies.forEach(e => {
const ex = e.x - cameraX;
if (ex > canvas.width + 50 || ex < -50) return;
if (e.type === 'goomba') drawGoomba(e);
else if (e.type === 'koopa') drawKoopa(e);
});

// Flag pole
if (flagPole) {
const fx = flagPole.x - cameraX;
ctx.fillStyle = '#7f8c8d';
ctx.fillRect(fx, flagPole.y, flagPole.width, flagPole.height);
ctx.fillStyle = '#95a5a6';
ctx.fillRect(fx + 2, flagPole.y, flagPole.width - 4, flagPole.height);
// Flag
const flagWave = Math.sin(time * 0.05) * 5;
ctx.fillStyle = '#e74c3c';
ctx.beginPath();
ctx.moveTo(fx + flagPole.width, flagPole.y + 10);
ctx.lineTo(fx + flagPole.width + 40 + flagWave, flagPole.y + 25);
ctx.lineTo(fx + flagPole.width, flagPole.y + 40);
ctx.fill();
// Ball on top
ctx.fillStyle = '#f1c40f';
ctx.beginPath();
ctx.arc(fx + flagPole.width/2, flagPole.y, 8, 0, Math.PI * 2);
ctx.fill();
}

// Player
if (!player.dead || player.deathTimer < 120) {
drawMario(player.x - cameraX, player.y);
}

// Particles
particles.forEach(p => {
const alpha = p.life / p.maxLife;
ctx.fillStyle = p.color;
ctx.globalAlpha = alpha;
ctx.fillRect(p.x - cameraX, p.y, p.size, p.size);
});
ctx.globalAlpha = 1;

// Floating texts
floatingTexts.forEach(ft => {
const alpha = ft.life / 60;
ctx.globalAlpha = alpha;
ctx.fillStyle = ft.color;
ctx.font = 'bold 16px Arial';
ctx.textAlign = 'center';
ctx.fillText(ft.text, ft.x - cameraX, ft.y);
});
ctx.globalAlpha = 1;

// Death animation
if (player.dead) {
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.fillRect(0, 0, canvas.width, canvas.height);
}
}

function gameLoop() {
update();
draw();
requestAnimationFrame(gameLoop);
}

generateLevel();
gameLoop();
</script>
