text-shadow: 0 0 10px #ff0;
opacity: 0;
transition: opacity 0.3s;
}
#ability-btn {
position: absolute;
bottom: 70px;
right: 20px;
width: 60px; height: 60px;
border-radius: 50%;
background: radial-gradient(circle, #0ff, #00f);
border: 3px solid #fff;
color: #fff;
font-size: 12px;
font-weight: bold;
cursor: pointer;
pointer-events: all;
display: none;
align-items: center;
justify-content: center;
text-shadow: 0 0 5px #fff;
box-shadow: 0 0 15px #0ff;
}
</style>
</head>
<body>
<canvas id="gameCanvas"></canvas>
<div id="ui-overlay">
<div id="score-display">SCORE: 0</div>
<div id="distance-display">DIST: 0m</div>
<div id="power-label">⚡ POWER METER</div>
<div id="power-meter-container">
<div id="power-meter"></div>
</div>
<div id="transform-indicator">🔥 SHIFT FORM ACTIVATED! 🔥</div>
<div id="boss-name">👹 AMY THE DESTROYER</div>
<div id="boss-health-container">
<div id="boss-health"></div>
</div>
<div id="combo-display">COMBO x1</div>
<button id="ability-btn">BLAST</button>
</div>

<div id="menu-screen">
<h1>SHADOW SHIFT</h1>
<h2>⚡ Infinite Run ⚡</h2>
<button id="start-btn">START RUN</button>
<div id="controls-info">
🎮 Swipe Left/Right → Change Lane<br>
⬆️ Swipe Up → Jump | ⬇️ Swipe Down → Slide<br>
👆 Tap → Attack (after shift) | 👆👆 Hold → Charge Attack
</div>
</div>

<div id="game-over-screen">
<h1>GAME OVER</h1>
<div id="final-score">SCORE: 0</div>
<button id="restart-btn">RUN AGAIN</button>
</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Responsive canvas
function resizeCanvas() {
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

// Game State
const STATE = {
MENU: 0,
RUNNING: 1,
TRANSFORMING: 2,
COMBAT: 3,
BOSS: 4,
GAME_OVER: 5
};

let gameState = STATE.MENU;
let score = 0;
let distance = 0;
let speed = 5;
let maxSpeed = 12;
let powerMeter = 0;
let maxPower = 100;
let isTransformed = false;
let transformTimer = 0;
let transformDuration = 15000;
let combo = 0;
let comboTimer = 0;
let bossHealth = 100;
let bossMaxHealth = 100;
let bossPhase = 1;
let bossActive = false;
let bossTimer = 0;
let particles = [];
let enemies = [];
let obstacles = [];
let powerups = [];
let projectiles = [];
let bossProjectiles = [];
let laneWidth = 0;
let lanePositions = [];
let player = null;
let groundY = 0;
let frameCount = 0;
let shakeAmount = 0;
let slowMotion = false;
let slowMotionTimer = 0;
let invincible = false;
let invincibleTimer = 0;
let bgOffset = 0;
let buildings = [];
let stars = [];
let transformFlash = 0;
let lastTime = 0;
let deltaTime = 0;

// Player class
class Player {
constructor() {
this.lane = 1; // 0, 1, 2
this.x = canvas.width / 2;
this.y = groundY;
this.width = 40;
this.height = 60;
this.vy = 0;
this.isJumping = false;
this.isSliding = false;
this.slideTimer = 0;
this.isAttacking = false;
this.attackTimer = 0;
this.attackCooldown = 0;
this.chargeAttack = 0;
this.isCharging = false;
this.color = '#0ff';
this.trail = [];
this.laneTarget = this.x;
this.jumpPower = -15;
this.gravity = 0.8;
this.groundY = groundY;
this.invulnerable = 0;
this.dashCooldown = 0;
this.isDashing = false;
this.dashTimer = 0;
}

update() {
// Smooth lane movement
this.laneTarget = lanePositions[this.lane];
this.x += (this.laneTarget - this.x) * 0.15;

// Jump physics
if (this.isJumping) {
this.vy += this.gravity;
this.y += this.vy;
if (this.y >= this.groundY) {
this.y = this.groundY;
this.isJumping = false;
this.vy = 0;
}
}

// Slide
if (this.isSliding) {
this.slideTimer--;
if (this.slideTimer <= 0) {
this.isSliding = false;
this.height = 60;
}
}

// Attack
if (this.isAttacking) {
this.attackTimer--;
if (this.attackTimer <= 0) {
this.isAttacking = false;
}
}

// Charge attack
if (this.isCharging) {
this.chargeAttack = Math.min(this.chargeAttack + 2, 100);
}

// Cooldowns
if (this.attackCooldown > 0) this.attackCooldown--;
if (this.invulnerable > 0) this.invulnerable--;
if (this.dashCooldown > 0) this.dashCooldown--;

// Dash
if (this.isDashing) {
this.dashTimer--;
this.x += (this.laneTarget - this.x) * 0.5;
if (this.dashTimer <= 0) {
this.isDashing = false;
}
}

// Trail
this.trail.push({ x: this.x, y: this.y, alpha: 1 });
if (this.trail.length > 10) this.trail.shift();
this.trail.forEach(t => t.alpha -= 0.1);
}

draw() {
// Draw trail
this.trail.forEach(t => {
if (t.alpha > 0) {
ctx.globalAlpha = t.alpha * 0.3;
ctx.fillStyle = isTransformed ? '#f0f' : '#0ff';
ctx.fillRect(t.x - this.width/2, t.y - this.height, this.width, this.height);
}
});
ctx.globalAlpha = 1;

// Draw player
ctx.save();
if (this.invulnerable > 0 && Math.floor(this.invulnerable / 3) % 2 === 0) {
ctx.globalAlpha = 0.5;
}

const x = this.x - this.width / 2;
const y = this.y - this.height;

// Body
if (isTransformed) {
// Transformed form - energy warrior
const gradient = ctx.createLinearGradient(x, y, x + this.width, y + this.height);
gradient.addColorStop(0, '#f0f');
gradient.addColorStop(0.5, '#ff0');
gradient.addColorStop(1, '#f00');
ctx.fillStyle = gradient;
ctx.shadowColor = '#f0f';
ctx.shadowBlur = 20;
} else {
ctx.fillStyle = this.color;
ctx.shadowColor = '#0ff';
ctx.shadowBlur = 15;
}

// Main body
ctx.fillRect(x, y, this.width, this.height);

// Head
ctx.fillRect(x + 5, y - 15, this.width - 10, 15);

// Eyes
ctx.fillStyle = '#fff';
ctx.fillRect(x + 10, y - 10, 6, 6);
ctx.fillRect(x + 24, y - 10, 6, 6);

// Arms
if (this.isAttacking) {
// Attack animation
ctx.fillStyle = isTransformed ? '#ff0' : '#0ff';
ctx.fillRect(x + this.width, y + 10, 30, 10);
ctx.fillRect(x - 30, y + 10, 30, 10);
} else {
ctx.fillRect(x - 10, y + 15, 10, 25);
ctx.fillRect(x + this.width, y + 15, 10, 25);
}

// Legs
if (this.isSliding) {
ctx.fillRect(x, y + this.height - 10, this.width, 10);
} else {
ctx.fillRect(x + 5, y + this.height, 12, 20);
ctx.fillRect(x + 23, y + this.height, 12, 20);
}

// Transformation effects
if (isTransformed) {
// Energy aura
ctx.strokeStyle = '#f0f';
ctx.lineWidth = 2;
ctx.shadowBlur = 30;
ctx.beginPath();
ctx.arc(this.x, this.y - this.height/2, 40 + Math.sin(frameCount * 0.1) * 5, 0, Math.PI * 2);
ctx.stroke();

// Charge attack indicator
if (this.isCharging && this.chargeAttack > 0) {
ctx.strokeStyle = '#ff0';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.arc(this.x, this.y - this.height/2, 50 + this.chargeAttack * 0.3, 0, Math.PI * 2 * (this.chargeAttack / 100));
ctx.stroke();
}
}

ctx.restore();
}

jump() {
if (!this.isJumping && !this.isSliding) {
this.isJumping = true;
this.vy = this.jumpPower;
}
}

slide() {
if (!this.isJumping && !this.isSliding) {
this.isSliding = true;
this.slideTimer = 40;
this.height = 30;
}
}

attack() {
if (this.attackCooldown <= 0 && isTransformed) {
this.isAttacking = true;
this.attackTimer = 15;
this.attackCooldown = 20;

// Create attack projectile
projectiles.push({
x: this.x + this.width/2,
y: this.y - this.height/2,
vx: 15,
vy: 0,
radius: 8,
damage: 20,
color: '#ff0',
life: 60
});

// Hit check
enemies.forEach(enemy => {
const dx = enemy.x - this.x;
const dy = enemy.y - this.y;
const dist = Math.sqrt(dx*dx + dy*dy);
if (dist < 100) {
enemy.health -= 20;
addParticles(enemy.x, enemy.y, '#ff0', 10);
shakeAmount = 5;
}
});
}
}

chargeAttack() {
if (this.isCharging && this.chargeAttack >= 100 && isTransformed) {
this.isCharging = false;
this.isAttacking = true;
this.attackTimer = 30;

// Massive attack
for (let i = -2; i <= 2; i++) {
projectiles.push({
x: this.x + this.width/2,
y: this.y - this.height/2,
vx: 12,
vy: i * 3,
radius: 12,
damage: 50,
color: '#f0f',
life: 80
});
}

addParticles(this.x, this.y - this.height/2, '#f0f', 30);
shakeAmount = 15;
this.chargeAttack = 0;
}
}

dash() {
if (this.dashCooldown <= 0 && isTransformed) {
this.isDashing = true;
this.dashTimer = 10;
this.dashCooldown = 60;
this.invulnerable = 15;
shakeAmount = 8;
}
}
}

// Enemy class
class Enemy {
constructor(type = 'basic') {
this.type = type;
this.lane = Math.floor(Math.random() * 3);
this.x = lanePositions[this.lane];
this.y = groundY - 50;
this.width = 40;
this.height = 50;
this.speed = speed + (type === 'fast' ? 3 : type === 'armored' ? -1 : 0);
this.health = type === 'armored' ? 60 : type === 'flying' ? 30 : 40;
this.maxHealth = this.health;
this.color = type === 'basic' ? '#f00' : type === 'armored' ? '#888' : '#f80';
this.attackTimer = 0;
this.attackCooldown = 60 + Math.random() * 60;
this.isFlying = type === 'flying';
this.flyHeight = 0;
this.flySpeed = 2;
this.points = type === 'armored' ? 30 : type === 'flying' ? 25 : 10;
this.hitFlash = 0;
}

update() {
this.x = lanePositions[this.lane];
this.y = groundY - 50;

if (this.isFlying) {
this.flyHeight += this.flySpeed;
if (this.flyHeight > 80 || this.flyHeight < 0) this.flySpeed *= -1;
this.y -= this.flyHeight;
}

// Move towards player
this.y -= this.speed * 0.5;

// Attack
this.attackTimer++;
if (this.attackTimer >= this.attackCooldown) {
this.attackTimer = 0;
this.attack();
}

if (this.hitFlash > 0) this.hitFlash--;
}

attack() {
bossProjectiles.push({
x: this.x,
y: this.y - this.height/2,
vx: (player.x - this.x) * 0.05,
vy: -5,
radius: 6,
color: '#f00',
life: 120
});
}

draw() {
ctx.save();
if (this.hitFlash > 0) {
ctx.fillStyle = '#fff';
} else {
ctx.fillStyle = this.color;
}

ctx.shadowColor = this.color;
ctx.shadowBlur = 15;

// Body
ctx.fillRect(this.x - this.width/2, this.y - this.height, this.width, this.height);

// Eyes
ctx.fillStyle = '#fff';
ctx.fillRect(this.x - 10, this.y - this.height + 10, 8, 8);
ctx.fillRect(this.x + 2, this.y - this.height + 10, 8, 8);

// Health bar
const healthPercent = this.health / this.maxHealth;
ctx.fillStyle = '#333';
ctx.fillRect(this.x - 20, this.y - this.height - 10, 40, 5);
ctx.fillStyle = healthPercent > 0.5 ? '#0f0' : healthPercent > 0.25 ? '#ff0' : '#f00';
ctx.fillRect(this.x - 20, this.y - this.height - 10, 40 * healthPercent, 5);

ctx.restore();
}
}

// Boss class
class Boss {
constructor() {
this.x = canvas.width / 2;
this.y = groundY - 120;
this.width = 100;
this.height = 120;
this.health = 500;
this.maxHealth = 500;
this.phase = 1;
this.attackTimer = 0;
this.attackCooldown = 90;
this.moveTimer = 0;
this.targetX = this.x;
this.color = '#f00';
this.hitFlash = 0;
this.summonTimer = 0;
this.rageMode = false;
this.projectilePattern = 0;
}

update() {
this.moveTimer++;
this.attackTimer++;

// Move towards player lane
if (this.moveTimer % 60 === 0) {
this.targetX = lanePositions[Math.floor(Math.random() * 3)];
}
this.x += (this.targetX - this.x) * 0.05;

// Attack
const cooldown = this.rageMode ? 40 : 90;
if (this.attackTimer >= cooldown) {
this.attackTimer = 0;
this.attack();
}

// Summon minions
this.summonTimer++;
if (this.summonTimer >= 180 && this.phase < 3) {
this.summonTimer = 0;
this.summonMinion();
}

// Rage mode
if (this.health < this.maxHealth * 0.3 && !this.rageMode) {
this.rageMode = true;
this.phase = 3;
shakeAmount = 20;
}

if (this.hitFlash > 0) this.hitFlash--;
}

attack() {
if (this.phase === 1) {
// Single projectile
bossProjectiles.push({
x: this.x,
y: this.y,
vx: (player.x - this.x) * 0.03,
vy: -8,
radius: 10,
color: '#f00',
life: 150
});
} else if (this.phase === 2) {
// Spread shot
for (let i = -2; i <= 2; i++) {
bossProjectiles.push({
x: this.x,
y: this.y,
vx: i * 3,
vy: -6,
radius: 8,
color: '#ff0',
life: 120
});
}
} else {
// Rage mode - rapid fire
for (let i = -3; i <= 3; i++) {
bossProjectiles.push({
x: this.x,
y: this.y,
vx: i * 2,
vy: -5 - Math.random() * 3,
radius: 6,
color: '#f00',
life: 100
});
}
}
}

summonMinion() {
const enemy = new Enemy('basic');
enemy.x = this.x + (Math.random() - 0.5) * 200;
enemies.push(enemy);
}

draw() {
ctx.save();

if (this.hitFlash > 0) {
ctx.fillStyle = '#fff';
} else {
const gradient = ctx.createLinearGradient(this.x - this.width/2, this.y - this.height, this.x + this.width/2, this.y);
gradient.addColorStop(0, this.rageMode ? '#f00' : '#800');
gradient.addColorStop(1, this.rageMode ? '#ff0' : '#f00');
ctx.fillStyle = gradient;
}

ctx.shadowColor = this.rageMode ? '#f00' : '#f00';
ctx.shadowBlur = 30;

// Body
ctx.fillRect(this.x - this.width/2, this.y - this.height, this.width, this.height);

// Head
ctx.fillRect(this.x - 30, this.y - this.height - 30, 60, 30);

// Eyes
ctx.fillStyle = this.rageMode ? '#ff0' : '#f00';
ctx.fillRect(this.x - 20, this.y - this.height - 20, 15, 15);
ctx.fillRect(this.x + 5, this.y - this.height - 20, 15, 15);

// Horns
ctx.fillStyle = '#fff';
ctx.fillRect(this.x - 35, this.y - this.height - 50, 10, 25);
ctx.fillRect(this.x + 25, this.y - this.height - 50, 10, 25);

// Health bar
const healthPercent = this.health / this.maxHealth;
ctx.fillStyle = '#333';
ctx.fillRect(this.x - 60, this.y - this.height - 60, 120, 10);
ctx.fillStyle = healthPercent > 0.5 ? '#0f0' : healthPercent > 0.25 ? '#ff0' : '#f00';
ctx.fillRect(this.x - 60, this.y - this.height - 60, 120 * healthPercent, 10);

ctx.restore();
}
}

// Obstacle class
class Obstacle {
constructor() {
this.lane = Math.floor(Math.random() * 3);
this.x = lanePositions[this.lane];
this.y = -100;
this.width = 50;
this.height = 50;
this.type = Math.random() > 0.5 ? 'barrier' : 'car';
this.color = this.type === 'barrier' ? '#f80' : '#0f0';
this.speed = speed;
}

update() {
this.y += this.speed;
}

draw() {
ctx.save();
ctx.fillStyle = this.color;
ctx.shadowColor = this.color;
ctx.shadowBlur = 10;

if (this.type === 'barrier') {
// Barrier
ctx.fillRect(this.x - this.width/2, this.y - this.height, this.width, this.height);
ctx.fillStyle = '#ff0';
ctx.fillRect(this.x - this.width/2 + 5, this.y - this.height + 5, this.width - 10, this.height - 10);
} else {
// Car
ctx.fillRect(this.x - this.width/2, this.y - this.height, this.width, this.height);
ctx.fillStyle = '#fff';
ctx.fillRect(this.x - this.width/2 + 5, this.y - this.height + 5, 15, 10);
ctx.fillRect(this.x + this.width/2 - 20, this.y - this.height + 5, 15, 10);
}

ctx.restore();
}
}

// Power-up class
class PowerUp {
constructor(type) {
this.lane = Math.floor(Math.random() * 3);
this.x = lanePositions[this.lane];
this.y = -50;
this.type = type; // 'energy', 'shield', 'timeslow'
this.radius = 15;
this.speed = speed;
this.color = type === 'energy' ? '#0ff' : type === 'shield' ? '#0f0' : '#ff0';
this.bobOffset = 0;
}

update() {
this.y += this.speed;
this.bobOffset += 0.1;
}

draw() {
ctx.save();
ctx.fillStyle = this.color;
ctx.shadowColor = this.color;
ctx.shadowBlur = 20;

const bobY = this.y + Math.sin(this.bobOffset) * 5;

ctx.beginPath();
ctx.arc(this.x, bobY, this.radius, 0, Math.PI * 2);
ctx.fill();

ctx.fillStyle = '#fff';
ctx.font = '16px Arial';
ctx.textAlign = 'center';
const icon = this.type === 'energy' ? '⚡' : this.type === 'shield' ? '🛡️' : '⏳';
ctx.fillText(icon, this.x, bobY + 5);

ctx.restore();
}
}

// Particle class
class Particle {
constructor(x, y, color, speed = 5) {
this.x = x;
this.y = y;
this.color = color;
this.vx = (Math.random() - 0.5) * speed * 2;
this.vy = (Math.random() - 0.5) * speed * 2;
this.life = 30 + Math.random() * 30;
this.maxLife = this.life;
this.size = 2 + Math.random() * 4;
}

update() {
this.x += this.vx;
this.y += this.vy;
this.life--;
this.size *= 0.98;
}

draw() {
ctx.save();
ctx.globalAlpha = this.life / this.maxLife;
ctx.fillStyle = this.color;
ctx.shadowColor = this.color;
ctx.shadowBlur = 10;
ctx.fillRect(this.x - this.size/2, this.y - this.size/2, this.size, this.size);
ctx.restore();
}
}

function addParticles(x, y, color, count) {
for (let i = 0; i < count; i++) {
particles.push(new Particle(x, y, color));
}
}

// Initialize game
function initGame() {
laneWidth = canvas.width / 3;
lanePositions = [
laneWidth * 0.5,
laneWidth * 1.5,
laneWidth * 2.5
];
groundY = canvas.height - 100;

player = new Player();
player.groundY = groundY;
player.y = groundY;

enemies = [];
obstacles = [];
powerups = [];
projectiles = [];
bossProjectiles = [];
particles = [];

score = 0;
distance = 0;
speed = 5;
powerMeter = 0;
isTransformed = false;
transformTimer = 0;
combo = 0;
comboTimer = 0;
bossHealth = 500;
bossMaxHealth = 500;
bossPhase = 1;
bossActive = false;
bossTimer = 0;
shakeAmount = 0;
slowMotion = false;
slowMotionTimer = 0;
invincible = false;
invincibleTimer = 0;
transformFlash = 0;

// Generate buildings
buildings = [];
for (let i = 0; i < 20; i++) {
buildings.push({
x: Math.random() * canvas.width,
width: 30 + Math.random() * 80,
height: 100 + Math.random() * 300,
color: `hsl(${Math.random() * 60 + 240}, 50%, 20%)`,
windows: Math.floor(Math.random() * 5) + 2
});
}

// Generate stars
stars = [];
for (let i = 0; i < 100; i++) {
stars.push({
x: Math.random() * canvas.width,
y: Math.random() * canvas.height * 0.5,
size: Math.random() * 2,
twinkle: Math.random() * Math.PI * 2
});
}

document.getElementById('menu-screen').style.display = 'none';
document.getElementById('game-over-screen').style.display = 'none';
document.getElementById('boss-health-container').style.display = 'none';
document.getElementById('boss-name').style.display = 'none';
document.getElementById('ability-btn').style.display = 'none';
document.getElementById('transform-indicator').style.opacity = '0';

gameState = STATE.RUNNING;
}

// Spawn enemies
function spawnEnemy() {
if (!isTransformed) return;
if (Math.random() < 0.02 + distance * 0.00001) {
const types = ['basic', 'basic', 'basic', 'fast', 'armored', 'flying'];
const type = types[Math.floor(Math.random() * types.length)];
enemies.push(new Enemy(type));
}
}

// Spawn obstacles
function spawnObstacle() {
if (Math.random() < 0.015 + distance * 0.00001) {
obstacles.push(new Obstacle());
}
}

// Spawn power-ups
function spawnPowerUp() {
if (Math.random() < 0.005) {
const types = ['energy', 'shield', 'timeslow'];
const type = types[Math.floor(Math.random() * types.length)];
powerups.push(new PowerUp(type));
}
}

// Check collisions
function checkCollisions() {
// Player vs obstacles
obstacles.forEach((obs, index) => {
if (Math.abs(player.x - obs.x) < (player.width + obs.width) / 2 &&
Math.abs(player.y - obs.y) < (player.height + obs.height) / 2) {
if (player.invulnerable <= 0) {
if (invincible) {
obs.y = -200;
addParticles(obs.x, obs.y, '#0f0', 15);
score += 50;
} else {
gameOver();
}
}
}
});

// Player vs enemies
enemies.forEach((enemy, index) => {
if (Math.abs(player.x - enemy.x) < (player.width + enemy.width) / 2 &&
Math.abs(player.y - enemy.y) < (player.height + enemy.height) / 2) {
if (player.invulnerable <= 0) {
if (invincible) {
enemy.health -= 50;
addParticles(enemy.x, enemy.y, '#0f0', 15);
} else {
gameOver();
}
}
}

// Check if enemy is destroyed
if (enemy.health <= 0) {
score += enemy.points * (1 + combo * 0.1);
combo++;
comboTimer = 120;
powerMeter = Math.min(powerMeter + 10, maxPower);
addParticles(enemy.x, enemy.y, enemy.color, 20);
shakeAmount = 8;
enemies.splice(index, 1);
}
});

// Projectiles vs enemies
projectiles.forEach((proj, pIndex) => {
enemies.forEach((enemy, eIndex) => {
const dx = proj.x - enemy.x;
const dy = proj.y - enemy.y;
const dist = Math.sqrt(dx*dx + dy*dy);
if (dist < proj.radius + enemy.width/2) {
enemy.health -= proj.damage;
enemy.hitFlash = 5;
addParticles(proj.x, proj.y, proj.color, 8);
projectiles.splice(pIndex, 1);
shakeAmount = 3;
}
});
});

// Projectiles vs boss
if (bossActive) {
projectiles.forEach((proj, pIndex) => {
const dx = proj.x - boss.x;
const dy = proj.y - boss.y;
const dist = Math.sqrt(dx*dx + dy*dy);
if (dist < proj.radius + boss.width/2) {
boss.health -= proj.damage;
boss.hitFlash = 5;
addParticles(proj.x, proj.y, proj.color, 8);
projectiles.splice(pIndex, 1);
shakeAmount = 5;

if (boss.health <= 0) {
defeatBoss();
}
}
});
}

// Boss projectiles vs player
bossProjectiles.forEach((proj, index) => {
const dx = proj.x - player.x;
const dy = proj.y - player.y;
const dist = Math.sqrt(dx*dx + dy*dy);
if (dist < proj.radius + player.width/2 && player.invulnerable <= 0) {
if (invincible) {
addParticles(proj.x, proj.y, '#0f0', 10);
bossProjectiles.splice(index, 1);
} else {
gameOver();
}
}
});

// Player vs power-ups
powerups.forEach((pu, index) => {
const dx = pu.x - player.x;
const dy = pu.y - player.y;
const dist = Math.sqrt(dx*dx + dy*dy);
if (dist < pu.radius + player.width/2) {
applyPowerUp(pu.type);
powerups.splice(index, 1);
addParticles(pu.x, pu.y, pu.color, 15);
}
});
}

function applyPowerUp(type) {
switch(type) {
case 'energy':
powerMeter = Math.min(powerMeter + 30, maxPower);
score += 100;
break;
case 'shield':
invincible = true;
invincibleTimer = 300;
break;
case 'timeslow':
slowMotion = true;
slowMotionTimer = 180;
break;
}
}

function defeatBoss() {
bossActive = false;
score += 5000;
addParticles(boss.x, boss.y, '#ff0', 50);
shakeAmount = 30;
transformFlash = 60;

// Reset for continued running
bossHealth = 500;
bossMaxHealth = 500;
bossPhase = 1;
bossTimer = 0;

document.getElementById('boss-health-container').style.display = 'none';
document.getElementById('boss-name').style.display = 'none';
}

function gameOver() {
gameState = STATE.GAME_OVER;
document.getElementById('final-score').textContent = `SCORE: ${Math.floor(score)} | DIST: ${Math.floor(distance)}m`;
document.getElementById('game-over-screen').style.display = 'flex';
}

// Update game
function update() {
if (gameState !== STATE.RUNNING && gameState !== STATE.COMBAT && gameState !== STATE.BOSS) return;

deltaTime = lastTime ? (performance.now() - lastTime) / 16.67 : 1;
lastTime = performance.now();

if (slowMotion) {
slowMotionTimer--;
if (slowMotionTimer <= 0) slowMotion = false;
deltaTime *= 0.5;
}

if (invincible) {
invincibleTimer--;
if (invincibleTimer <= 0) invincible = false;
}

if (transformFlash > 0) transformFlash--;

frameCount++;
distance += speed * 0.1 * deltaTime;
score += speed * 0.01 * deltaTime;

// Increase speed over time
speed = Math.min(maxSpeed, 5 + distance * 0.001);

// Update player
if (player) {
player.update();
}

// Update particles
particles = particles.filter(p => {
p.update();
return p.life > 0;
});

// Update obstacles
obstacles = obstacles.filter(obs => {
obs.update();
return obs.y < canvas.height + 100;
});

// Update enemies
enemies = enemies.filter(enemy => {
enemy.update();
return enemy.y < canvas.height + 100 && enemy.health > 0;
});

// Update power-ups
powerups = powerups.filter(pu => {
pu.update();
return pu.y < canvas.height + 50;
});

// Update projectiles
projectiles = projectiles.filter(proj => {
proj.x += proj.vx * deltaTime;
proj.y += proj.vy * deltaTime;
proj.life--;
return proj.life > 0 && proj.y > -50 && proj.y < canvas.height + 50;
});

// Update boss projectiles
bossProjectiles = bossProjectiles.filter(proj => {
proj.x += proj.vx * deltaTime;
proj.y += proj.vy * deltaTime;
proj.life--;
return proj.life > 0;
});

// Spawn systems
spawnEnemy();
spawnObstacle();
spawnPowerUp();

// Collision detection
checkCollisions();

// Combo timer
if (comboTimer > 0) {
comboTimer--;
if (comboTimer <= 0) combo = 0;
}

// Transform logic
if (!isTransformed && distance > 500) {
isTransformed = true;
transformTimer = transformDuration;
gameState = STATE.TRANSFORMING;
transformFlash = 60;
document.getElementById('transform-indicator').style.opacity = '1';
setTimeout(() => {
document.getElementById('transform-indicator').style.opacity = '0';
gameState = STATE.COMBAT;
}, 2000);
}

// Transform timer
if (isTransformed) {
transformTimer -= 16.67 * deltaTime;
if (transformTimer <= 0) {
isTransformed = false;
transformTimer = 0;
gameState = STATE.RUNNING;
}
}

// Boss fight
if (distance > 2000 && !bossActive && !bossActive) {
bossActive = true;
gameState = STATE.BOSS;
document.getElementById('boss-health-container').style.display = 'block';
document.getElementById('boss-name').style.display = 'block';
document.getElementById('ability-btn').style.display = 'flex';
}

if (bossActive) {
bossTimer += deltaTime;
if (player) player.update();

// Update boss
if (!window.bossInstance) {
window.bossInstance = new Boss();
}
window.bossInstance.update();

// Update boss health UI
const healthPercent = (bossHealth / bossMaxHealth) * 100;
document.getElementById('boss-health').style.width = healthPercent + '%';
}

// Background scroll
bgOffset += speed * 0.5 * deltaTime;

// Update UI
document.getElementById('score-display').textContent = `SCORE: ${Math.floor(score)}`;
document.getElementById('distance-display').textContent = `DIST: ${Math.floor(distance)}m`;
document.getElementById('power-meter').style.width = (powerMeter / maxPower * 100) + '%';

if (combo > 1) {
document.getElementById('combo-display').textContent = `COMBO x${combo}`;
document.getElementById('combo-display').style.opacity = '1';
} else {
document.getElementById('combo-display').style.opacity = '0';
}
}

// Draw game
function draw() {
ctx.clearRect(0, 0, canvas.width, canvas.height);

// Screen shake
ctx.save();
if (shakeAmount > 0) {
ctx.translate(
(Math.random() - 0.5) * shakeAmount,
(Math.random() - 0.5) * shakeAmount
);
shakeAmount *= 0.9;
if (shakeAmount < 0.5) shakeAmount = 0;
}

// Background
drawBackground();

// Ground
drawGround();

// Buildings
drawBuildings();

// Obstacles
obstacles.forEach(obs => obs.draw());

// Power-ups
powerups.forEach(pu => pu.draw());

// Enemies
enemies.forEach(enemy => enemy.draw());

// Boss
if (bossActive && window.bossInstance) {
window.bossInstance.draw();
}

// Projectiles
projectiles.forEach(proj => {
ctx.save();
ctx.fillStyle = proj.color;
ctx.shadowColor = proj.color;
ctx.shadowBlur = 15;
ctx.beginPath();
ctx.arc(proj.x, proj.y, proj.radius, 0, Math.PI * 2);
ctx.fill();
ctx.restore();
});

// Boss projectiles
bossProjectiles.forEach(proj => {
ctx.save();
ctx.fillStyle = proj.color;
ctx.shadowColor = proj.color;
ctx.shadowBlur = 15;
ctx.beginPath();
ctx.arc(proj.x, proj.y, proj.radius, 0, Math.PI * 2);
ctx.fill();
ctx.restore();
});

// Player
if (player) {
player.draw();
}

// Particles
particles.forEach(p => p.draw());

// Transform flash
if (transformFlash > 0) {
ctx.save();
ctx.globalAlpha = transformFlash / 60 * 0.3;
ctx.fillStyle = '#fff';
ctx.fillRect(0, 0, canvas.width, canvas.height);
ctx.restore();
}

// Slow motion overlay
if (slowMotion) {
ctx.save();
ctx.globalAlpha = 0.1;
ctx.fillStyle = '#00f';
ctx.fillRect(0, 0, canvas.width, canvas.height);
ctx.restore();
}

ctx.restore();
}

function drawBackground() {
// Sky gradient
const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
gradient.addColorStop(0, '#0a0015');
gradient.addColorStop(0.5, '#1a0a2e');
gradient.addColorStop(1, '#0a0a1a');
ctx.fillStyle = gradient;
ctx.fillRect(0, 0, canvas.width, canvas.height);

// Stars
stars.forEach(star => {
star.twinkle += 0.05;
const alpha = 0.5 + Math.sin(star.twinkle) * 0.5;
ctx.save();
ctx.globalAlpha = alpha;
ctx.fillStyle = '#fff';
ctx.fillRect(star.x, star.y, star.size, star.size);
ctx.restore();
});
}

function drawGround() {
// Ground
const groundGradient = ctx.createLinearGradient(0, groundY, 0, canvas.height);
groundGradient.addColorStop(0, '#1a1a2e');
groundGradient.addColorStop(1, '#0a0a1a');
ctx.fillStyle = groundGradient;
ctx.fillRect(0, groundY, canvas.width, canvas.height - groundY);

// Lane lines
ctx.strokeStyle = 'rgba(0, 255, 255, 0.3)';
ctx.lineWidth = 2;
ctx.setLineDash([20, 20]);
ctx.lineDashOffset = -bgOffset;

for (let i = 1; i < 3; i++) {
const x = laneWidth * i;
ctx.beginPath();
ctx.moveTo(x, groundY);
ctx.lineTo(x, canvas.height);
ctx.stroke();
}

ctx.setLineDash([]);

// Ground glow
ctx.save();
ctx.globalAlpha = 0.1;
const glowGradient = ctx.createLinearGradient(0, groundY, 0, groundY + 50);
glowGradient.addColorStop(0, isTransformed ? '#f0f' : '#0ff');
glowGradient.addColorStop(1, 'transparent');
ctx.fillStyle = glowGradient;
ctx.fillRect(0, groundY, canvas.width, 50);
ctx.restore();
}

function drawBuildings() {
buildings.forEach(b => {
const x = ((b.x - bgOffset * 0.3) % (canvas.width + 200)) - 100;
ctx.fillStyle = b.color;
ctx.fillRect(x, groundY - b.height, b.width, b.height);

// Windows
ctx.fillStyle = 'rgba(255, 255, 100, 0.5)';
for (let w = 0; w < b.windows; w++) {
for (let h = 0; h < 3; h++) {
if (Math.random() > 0.3) {
ctx.fillRect(
x + 5 + w * (b.width / b.windows),
groundY - b.height + 10 + h * 30,
b.width / b.windows - 10,
20
);
}
}
}
});
}

// Game loop
function gameLoop() {
update();
draw();
requestAnimationFrame(gameLoop);
}

// Input handling
let touchStartX = 0;
let touchStartY = 0;
let touchStartTime = 0;
let isTouching = false;

canvas.addEventListener('touchstart', (e) => {
e.preventDefault();
const touch = e.touches[0];
touchStartX = touch.clientX;
touchStartY = touch.clientY;
touchStartTime = performance.now();
isTouching = true;
});

canvas.addEventListener('touchmove', (e) => {
e.preventDefault();
});

canvas.addEventListener('touchend', (e) => {
e.preventDefault();
if (!isTouching) return;
isTouching = false;

const touch = e.changedTouches[0];
const dx = touch.clientX - touchStartX;
const dy = touch.clientY - touchStartY;
const dt = performance.now() - touchStartTime;

const minSwipe = 30;

if (Math.abs(dx) > Math.abs(dy)) {
// Horizontal swipe
if (Math.abs(dx) > minSwipe) {
if (dx > 0 && player.lane < 2) {
player.lane++;
} else if (dx < 0 && player.lane > 0) {
player.lane--;
}
}
} else {
// Vertical swipe
if (Math.abs(dy) > minSwipe) {
if (dy < 0) {
player.jump();
} else {
player.slide();
}
}
}

// Tap to attack
if (Math.abs(dx) < 10 && Math.abs(dy) < 10 && dt < 200) {
if (isTransformed) {
player.attack();
}
}
});

// Keyboard controls
document.addEventListener('keydown', (e) => {
if (gameState === STATE.MENU) {
initGame();
return;
}

if (gameState === STATE.GAME_OVER) {
initGame();
return;
}

switch(e.key) {
case 'ArrowLeft':
case 'a':
if (player && player.lane > 0) player.lane--;
break;
case 'ArrowRight':
case 'd':
if (player && player.lane < 2) player.lane++;
break;
case 'ArrowUp':
case 'w':
case ' ':
if (player) player.jump();
break;
case 'ArrowDown':
case 's':
if (player) player.slide();
break;
case 'j':
case 'z':
if (player && isTransformed) player.attack();
break;
case 'k':
case 'x':
if (player && isTransformed) {
player.isCharging = true;
}
break;
case 'l':
case 'c':
if (player && isTransformed) player.dash();
break;
}
});

document.addEventListener('keyup', (e) => {
if (e.key === 'k' || e.key === 'x') {
if (player) {
player.isCharging = false;
player.chargeAttack();
}
}
});

// Ability button
document.getElementById('ability-btn').addEventListener('click', () => {
if (player && isTransformed) {
player.dash();
}
});

// Start button
document.getElementById('start-btn').addEventListener('click', () => {
initGame();
});

// Restart button
document.getElementById('restart-btn').addEventListener('click', () => {
initGame();
});

// Start game loop
gameLoop();
</script>
</body>
</html>

