        // Initialize data
        function initData() {
            if (!localStorage.getItem(DB_KEY)) {
                localStorage.setItem(DB_KEY, JSON.stringify(sampleProducts));
            }
            if (!localStorage.getItem(PAYMENTS_KEY)) {
                localStorage.setItem(PAYMENTS_KEY, JSON.stringify([]));
            }
        }

        function getProducts() {
            return JSON.parse(localStorage.getItem(DB_KEY) || '[]');
        }

        function saveProducts(products) {
            localStorage.setItem(DB_KEY, JSON.stringify(products));
        }

        function getPayments() {
            return JSON.parse(localStorage.getItem(PAYMENTS_KEY) || '[]');
        }

        function savePayments(payments) {
            localStorage.setItem(PAYMENTS_KEY, JSON.stringify(payments));
        }

        function generateId() {
            return Date.now().toString(36) + Math.random().toString(36).substr(2);
        }

        // ==================== PAGE NAVIGATION ====================
        function showPage(page) {
            // Hide all pages
            document.querySelectorAll('.page').forEach(p => p.style.display = 'none');
            document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));

            // Show selected page
            switch(page) {
                case 'home':
                    document.getElementById('homePage').style.display = 'block';
                    document.querySelectorAll('.nav-btn')[0].classList.add('active');
                    renderProducts();
                    break;
                case 'post':
                    document.getElementById('postPage').style.display = 'block';
                    document.querySelectorAll('.nav-btn')[1].classList.add('active');
                    break;
                case 'myproducts':
                    document.getElementById('myProductsPage').style.display = 'block';
                    document.querySelectorAll('.nav-btn')[2].classList.add('active');
                    renderMyProducts();
                    break;
                case 'admin':
                    document.getElementById('adminPage').style.display = 'block';
                    document.querySelectorAll('.nav-btn')[3].classList.add('active');
                    checkAdminSession();
                    break;
            }

            window.scrollTo(0, 0);
        }

        // ==================== PRODUCT RENDERING ====================
        let currentCategory = 'all';

        function renderProducts() {
            const products = getProducts().filter(p => p.status === 'approved');
            const searchTerm = document.getElementById('searchInput').value.toLowerCase();
            const grid = document.getElementById('productGrid');
            const emptyState = document.getElementById('emptyState');

            let filtered = products;

            if (currentCategory !== 'all') {
                filtered = filtered.filter(p => p.category === currentCategory);
            }

            if (searchTerm) {
                filtered = filtered.filter(p =>
                    p.name.toLowerCase().includes(searchTerm) ||
                    p.seller.toLowerCase().includes(searchTerm)
                );
            }

            if (filtered.length === 0) {
                grid.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            grid.innerHTML = filtered.map(product => {
                const stockClass = product.stock > 10 ? 'in-stock' : product.stock > 0 ? 'low-stock' : 'out-of-stock';
                const stockText = product.stock > 10 ? 'In Stock' : product.stock > 0 ? `Only ${product.stock} left` : 'Out of Stock';

                return `
                    <div class="product-card fade-in">
                        <div class="product-image">
                            <img src="${product.image}" alt="${product.name}" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22400%22 height=%22300%22><rect fill=%22%23e0e0e0%22 width=%22400%22 height=%22300%22/><text x=%2250%25%22 y=%2250%25%22 dominant-baseline=%22middle%22 text-anchor=%22middle%22 font-size=%2240%22>📦</text></svg>'">
                            <span class="stock-badge ${stockClass}">${stockText}</span>
                        </div>
                        <div class="product-info">
                            <div class="product-name">${product.name}</div>
                            <div class="product-price">₹${product.price} <span>₹${product.originalPrice || product.price * 2}</span></div>
                            <div class="product-stock">
                                <span class="stock-dot"></span>
                                ${product.stock} items available
                            </div>
                            <button class="view-details-btn" onclick="viewProduct('${product.id}')">
                                🔓 View Full Details
                            </button>
                        </div>
                    </div>
                `;
            }).join('');
        }

        function filterProducts() {
            renderProducts();
        }

        function filterByCategory(category) {
            currentCategory = category;
            document.querySelectorAll('.category-chip').forEach(chip => chip.classList.remove('active'));
            event.target.classList.add('active');
            renderProducts();
        }

        // ==================== PRODUCT DETAIL & PAYMENT ====================
        function viewProduct(productId) {
            const products = getProducts();
            const product = products.find(p => p.id === productId);
            if (!product) return;

            const payments = getPayments();
            const hasPaid = payments.some(p => p.productId === productId);

            const modal = document.getElementById('productModal');
            const body = document.getElementById('productModalBody');

            body.innerHTML = `
                <div class="payment-modal">
                    <div class="product-preview">
                        <img src="${product.image}" alt="${product.name}" class="preview-image" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%2280%22 height=%2280%22><rect fill=%22%23e0e0e0%22 width=%2280%22 height=%2280%22/><text x=%2250%25%22 y=%2250%25%22 dominant-baseline=%22middle%22 text-anchor=%22middle%22 font-size=%2220%22>📦</text></svg>'">
                        <div class="preview-info">
                            <h4>${product.name}</h4>
                            <div class="price">₹${product.price}</div>
                        </div>
                    </div>

                    <div class="payment-amount">
                        <span>Pay only</span> ₹1 <span>to unlock</span>
                    </div>

                    <div class="qr-container">
                        <div class="qr-code">
                            <canvas id="qrCanvas" width="180" height="180"></canvas>
                        </div>
                        <p class="qr-label">Scan QR Code to pay ₹1</p>
                    </div>

                    <button class="pay-btn" onclick="processPayment('${product.id}')">
                        ✅ I Have Paid ₹1
                    </button>

                    <div class="locked-details" id="lockedDetails">
                        <div class="locked-content">
                            <div class="detail-row">
                                <span class="detail-label">👤 Seller</span>
                                <span class="detail-value">${product.seller}</span>
                            </div>
                            <div class="detail-row">
                                <span class="detail-label">📞 Phone</span>
                                <span class="detail-value">${product.phone}</span>
                            </div>
                            <div class="detail-row">
                                <span class="detail-label">📍 Address</span>
                                <span class="detail-value">${product.address}</span>
                            </div>
                            <div class="detail-row">
                                <span class="detail-label">📦 Stock</span>
                                <span class="detail-value">${product.stock} items</span>
                            </div>
                        </div>
                    </div>

                    ${hasPaid ? `
                        <div class="unlocked-details" id="unlockedDetails">
                            <div class="detail-row">
                                <span class="detail-label">👤 Seller</span>
                                <span class="detail-value">${product.seller}</span>
                            </div>
                            <div class="detail-row">
                                <span class="detail-label">📞 Phone</span>
                                <span class="detail-value">${product.phone}</span>
                            </div>
                            <div class="detail-row">
                                <span class="detail-label">📍 Address</span>
                                <span class="detail-value">${product.address}</span>
                            </div>
                            <div class="detail-row">
                                <span class="detail-label">📦 Stock</span>
                                <span class="detail-value">${product.stock} items</span>
                            </div>
                            <a href="tel:${product.phone}" class="contact-btn call-btn">📞 Call Seller</a>
                            <a href="https://wa.me/${product.phone}?text=Hi! I'm interested in ${product.name}" class="contact-btn message-btn" target="_blank">💬 WhatsApp</a>
                        </div>
                    ` : ''}
                </div>
            `;

            modal.classList.add('active');

            // Generate QR code
            generateQRCode(product.id);
        }

        function generateQRCode(productId) {
            const canvas = document.getElementById('qrCanvas');
            if (!canvas) return;

            const ctx = canvas.getContext('2d');
            const size = 180;
            const cellSize = 6;
            const cells = Math.floor(size / cellSize);

            // Clear canvas
            ctx.fillStyle = 'white';
            ctx.fillRect(0, 0, size, size);

            // Generate pseudo-random QR pattern based on product ID
            ctx.fillStyle = '#000';
            let seed = 0;
            for (let i = 0; i < productId.length; i++) {
                seed += productId.charCodeAt(i);
            }

            function pseudoRandom() {
                seed = (seed * 16807 + 0) % 2147483647;
                return seed / 2147483647;
            }

            // Draw QR-like pattern
            for (let row = 0; row < cells; row++) {
                for (let col = 0; col < cells; col++) {
                    // Skip corner positions for finder patterns
                    if ((row < 7 && col < 7) || (row < 7 && col > cells - 8) || (row > cells - 8 && col < 7)) {
                        continue;
                    }

                    if (pseudoRandom() > 0.5) {
                        ctx.fillRect(col * cellSize, row * cellSize, cellSize, cellSize);
                    }
                }
            }

            // Draw finder patterns
            drawFinderPattern(ctx, 0, 0, cellSize);
            drawFinderPattern(ctx, (cells - 7) * cellSize, 0, cellSize);
            drawFinderPattern(ctx, 0, (cells - 7) * cellSize, cellSize);

            // Draw center logo
            ctx.fillStyle = 'white';
            ctx.fillRect(size/2 - 15, size/2 - 15, 30, 30);
            ctx.fillStyle = '#6C63FF';
            ctx.font = '16px Arial';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('₹', size/2, size/2);
        }

        function drawFinderPattern(ctx, x, y, cellSize) {
            ctx.fillStyle = '#000';
            // Outer box
            for (let i = 0; i < 7; i++) {
                for (let j = 0; j < 7; j++) {
                    if (i === 0 || i === 6 || j === 0 || j === 6 || (i >= 2 && i <= 4 && j >= 2 && j <= 4)) {
                        ctx.fillRect(x + j * cellSize, y + i * cellSize, cellSize, cellSize);
                    }
                }
            }
        }

        function processPayment(productId) {
            const btn = event.target;
            btn.disabled = true;
            btn.innerHTML = '⏳ Processing...';

            setTimeout(() => {
                // Save payment
                const payments = getPayments();
                payments.push({
                    id: generateId(),
                    productId: productId,
                    amount: 1,
                    date: new Date().toISOString(),
                    status: 'completed'
                });
                savePayments(payments);

                // Update UI
                btn.innerHTML = '✅ Payment Successful!';
                btn.style.background = 'var(--accent)';

                setTimeout(() => {
                    viewProduct(productId); // Refresh modal
                    showToast('✅ Payment successful! Details unlocked.', 'success');
                }, 500);
            }, 1500);
        }

        function closeModal() {
            document.getElementById('productModal').classList.remove('active');
        }

        // ==================== POST PRODUCT ====================
        function previewImage(event) {
            const file = event.target.files[0];
            if (file) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    const preview = document.getElementById('imagePreview');
                    preview.src = e.target.result;
                    preview.style.display = 'block';
                };
                reader.readAsDataURL(file);
            }
        }

        function submitProduct(event) {
            event.preventDefault();

            const imagePreview = document.getElementById('imagePreview');
            const image = imagePreview.style.display !== 'none' ? imagePreview.src : '';

            const product = {
                id: generateId(),
                name: document.getElementById('productName').value,
                image: image || 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22400%22 height=%22300%22><rect fill=%22%23e0e0e0%22 width=%22400%22 height=%22300%22/><text x=%2250%25%22 y=%2250%25%22 dominant-baseline=%22middle%22 text-anchor=%22middle%22 font-size=%2240%22>📦</text></svg>',
                price: parseInt(document.getElementById('productPrice').value),
                originalPrice: parseInt(document.getElementById('productPrice').value) * 2,
                stock: parseInt(document.getElementById('productStock').value),
                category: document.getElementById('productCategory').value,
                phone: document.getElementById('productPhone').value,
                address: document.getElementById('productAddress').value,
                seller: 'You',
                status: 'pending',
                createdAt: new Date().toISOString()
            };

            const products = getProducts();
            products.push(product);
            saveProducts(products);

            // Reset form
            document.getElementById('postProductForm').reset();
            imagePreview.style.display = 'none';

            showToast('✅ Product posted successfully! Awaiting approval.', 'success');
            showPage('home');
        }

        // ==================== MY PRODUCTS ====================
        function renderMyProducts() {
            const products = getProducts().filter(p => p.seller === 'You');
            const grid = document.getElementById('myProductsGrid');
            const emptyState = document.getElementById('myProductsEmpty');

            if (products.length === 0) {
                grid.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            grid.innerHTML = products.map(product => {
                const statusClass = product.status === 'approved' ? 'status-approved' :
                                   product.status === 'pending' ? 'status-pending' : 'status-rejected';
                const statusText = product.status === 'approved' ? '✅ Approved' :
                                  product.status === 'pending' ? '⏳ Pending' : '❌ Rejected';

                return `
                    <div class="my-product-card">
                        <div class="product-image">
                            <img src="${product.image}" alt="${product.name}" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22400%22 height=%22300%22><rect fill=%22%23e0e0e0%22 width=%22400%22 height=%22300%22/><text x=%2250%25%22 y=%2250%25%22 dominant-baseline=%22middle%22 text-anchor=%22middle%22 font-size=%2240%22>📦</text></svg>'">
                        </div>
                        <div class="product-info">
                            <div class="product-name">${product.name}</div>
                            <div class="product-price">₹${product.price}</div>
                            <span class="status-badge ${statusClass}">${statusText}</span>
                        </div>
                        <div class="my-product-actions">
                            <button class="edit-my-btn" onclick="editProduct('${product.id}')">✏️ Edit</button>
                            <button class="delete-my-btn" onclick="deleteProduct('${product.id}')">🗑️ Delete</button>
                        </div>
                    </div>
                `;
            }).join('');
        }

        function editProduct(productId) {
            const products = getProducts();
            const product = products.find(p => p.id === productId);
            if (!product) return;

            document.getElementById('editProductId').value = product.id;
            document.getElementById('editProductName').value = product.name;
            document.getElementById('editProductPrice').value = product.price;
            document.getElementById('editProductStock').value = product.stock;
            document.getElementById('editProductPhone').value = product.phone;
            document.getElementById('editProductAddress').value = product.address;

            document.getElementById('editModal').classList.add('active');
        }

        function closeEditModal() {
            document.getElementById('editModal').classList.remove('active');
        }

        function saveEditProduct(event) {
            event.preventDefault();

            const productId = document.getElementById('editProductId').value;
            const products = getProducts();
            const index = products.findIndex(p => p.id === productId);

            if (index !== -1) {
                products[index].name = document.getElementById('editProductName').value;
                products[index].price = parseInt(document.getElementById('editProductPrice').value);
                products[index].stock = parseInt(document.getElementById('editProductStock').value);
                products[index].phone = document.getElementById('editProductPhone').value;
                products[index].address = document.getElementById('editProductAddress').value;

                saveProducts(products);
                closeEditModal();
                renderMyProducts();
                showToast('✅ Product updated successfully!', 'success');
            }
        }

        let pendingDeleteId = null;

        function deleteProduct(productId) {
            pendingDeleteId = productId;
            document.getElementById('confirmTitle').textContent = 'Delete Product?';
            document.getElementById('confirmMessage').textContent = 'This action cannot be undone.';
            document.getElementById('confirmDialog').classList.add('active');
        }

        function confirmAction() {
            if (pendingDeleteId) {
                let products = getProducts();
                products = products.filter(p => p.id !== pendingDeleteId);
                saveProducts(products);
                pendingDeleteId = null;
                closeConfirm();
                renderMyProducts();
                showToast('🗑️ Product deleted successfully!', 'success');
            }
        }

        function closeConfirm() {
            document.getElementById('confirmDialog').classList.remove('active');
            pendingDeleteId = null;
        }

        // ==================== ADMIN PANEL ====================
        function checkAdminSession() {
            const isAdmin = sessionStorage.getItem('adminLoggedIn');
            if (isAdmin === 'true') {
                document.getElementById('adminLogin').style.display = 'none';
                document.getElementById('adminDashboard').style.display = 'block';
                loadAdminDashboard();
            } else {
                document.getElementById('adminLogin').style.display = 'block';
                document.getElementById('adminDashboard').style.display = 'none';
            }
        }

        function adminLogin() {
            const username = document.getElementById('adminUsername').value;
            const password = document.getElementById('adminPassword').value;

            if (username === ADMIN_CREDENTIALS.username && password === ADMIN_CREDENTIALS.password) {
                sessionStorage.setItem('adminLoggedIn', 'true');
                document.getElementById('adminLogin').style.display = 'none';
                document.getElementById('adminDashboard').style.display = 'block';
                loadAdminDashboard();
                showToast('✅ Admin login successful!', 'success');
            } else {
                showToast('❌ Invalid credentials!', 'error');
            }
        }

        function logoutAdmin() {
            sessionStorage.removeItem('adminLoggedIn');
            document.getElementById('adminLogin').style.display = 'block';
            document.getElementById('adminDashboard').style.display = 'none';
            document.getElementById('adminUsername').value = '';
            document.getElementById('adminPassword').value = '';
            showToast('👋 Logged out successfully!', 'success');
        }

        function loadAdminDashboard() {
            const products = getProducts();
            const payments = getPayments();

            // Update stats
            document.getElementById('totalProducts').textContent = products.length;
            document.getElementById('totalPayments').textContent = payments.length;
            document.getElementById('totalRevenue').textContent = `₹${payments.length}`;
            document.getElementById('pendingProducts').textContent = products.filter(p => p.status === 'pending').length;

            // Load products table
            loadAdminProducts();
            loadAdminPayments();
            loadAdminUsers();
        }

        function loadAdminProducts() {
            const products = getProducts();
            const tbody = document.getElementById('adminProductsTable');

            tbody.innerHTML = products.map(product => {
                const statusClass = product.status === 'approved' ? 'status-approved' :
                                   product.status === 'pending' ? 'status-pending' : 'status-rejected';
                const statusText = product.status === 'approved' ? '✅ Approved' :
                                  product.status === 'pending' ? '⏳ Pending' : '❌ Rejected';

                return `
                    <tr>
                        <td><img src="${product.image}" alt="${product.name}" style="width: 50px; height: 50px; object-fit: cover; border-radius: 8px;" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%2250%22 height=%2250%22><rect fill=%22%23e0e0e0%22 width=%2250%22 height=%2250%22/><text x=%2250%25%22 y=%2250%25%22 dominant-baseline=%22middle%22 text-anchor=%22middle%22 font-size=%2215%22>📦</text></svg>'"></td>
                        <td>${product.name}</td>
                        <td>₹${product.price}</td>
                        <td>${product.stock}</td>
                        <td>${product.seller}</td>
                        <td><span class="status-badge ${statusClass}">${statusText}</span></td>
                        <td>
                            <button class="action-btn approve-btn" onclick="approveProduct('${product.id}')">✅</button>
                            <button class="action-btn reject-btn" onclick="rejectProduct('${product.id}')">❌</button>
                            <button class="action-btn delete-btn" onclick="adminDeleteProduct('${product.id}')">🗑️</button>
                            <button class="action-btn edit-btn" onclick="adminEditProduct('${product.id}')">✏️</button>
                        </td>
                    </tr>
                `;
            }).join('');
        }

        function loadAdminPayments() {
            const payments = getPayments();
            const products = getProducts();
            const container = document.getElementById('adminPaymentsList');

            if (payments.length === 0) {
                container.innerHTML = '<div class="empty-state"><div class="empty-icon">💰</div><h3>No Payments Yet</h3></div>';
                return;
            }

            container.innerHTML = payments.map(payment => {
                const product = products.find(p => p.id === payment.productId);
                const productName = product ? product.name : 'Unknown Product';
                const initials = payment.productId.substring(0, 2).toUpperCase();

                return `
                    <div class="payment-item">
                        <div class="payment-info">
                            <div class="payment-avatar">${initials}</div>
                            <div class="payment-details">
                                <h4>${productName}</h4>
                                <p>${new Date(payment.date).toLocaleDateString('en-IN')}</p>
                            </div>
                        </div>
                        <div class="payment-amount-badge">₹${payment.amount}</div>
                    </div>
                `;
            }).join('');
        }

        function loadAdminUsers() {
            const products = getProducts();
            const payments = getPayments();
            const tbody = document.getElementById('adminUsersTable');

            // Get unique sellers
            const sellers = [...new Set(products.map(p => p.seller))];

            tbody.innerHTML = sellers.map(seller => {
                const sellerProducts = products.filter(p => p.seller === seller);
                const sellerPayments = payments.filter(p => {
                    const product = products.find(pr => pr.id === p.productId);
                    return product && product.seller === seller;
                });

                return `
                    <tr>
                        <td><strong>${seller}</strong></td>
                        <td>${sellerProducts[0]?.phone || 'N/A'}</td>
                        <td>${sellerProducts[0]?.address || 'N/A'}</td>
                        <td>${sellerProducts.length}</td>
                        <td>₹${sellerPayments.length}</td>
                    </tr>
                `;
            }).join('');
        }

        function switchAdminTab(tab) {
            document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
            document.querySelectorAll('.tab-content').forEach(content => content.classList.remove('active'));

            event.target.classList.add('active');
            document.getElementById(tab + 'Tab').classList.add('active');
        }

        function approveProduct(productId) {
            const products = getProducts();
            const product = products.find(p => p.id === productId);
            if (product) {
                product.status = 'approved';
                saveProducts(products);
                loadAdminDashboard();
                showToast('✅ Product approved!', 'success');
            }
        }

        function rejectProduct(productId) {
            const products = getProducts();
            const product = products.find(p => p.id === productId);
            if (product) {
                product.status = 'rejected';
                saveProducts(products);
                loadAdminDashboard();
                showToast('❌ Product rejected!', 'error');
            }
        }

        function adminDeleteProduct(productId) {
            pendingDeleteId = productId;
            document.getElementById('confirmTitle').textContent = 'Delete Product?';
            document.getElementById('confirmMessage').textContent = 'This product will be permanently deleted.';
            document.getElementById('confirmDialog').classList.add('active');
        }

        function adminEditProduct(productId) {
            editProduct(productId);
        }

        // Override confirmAction for admin
        const originalConfirmAction = confirmAction;
        confirmAction = function() {
            if (pendingDeleteId) {
                let products = getProducts();
                products = products.filter(p => p.id !== pendingDeleteId);
                saveProducts(products);
                pendingDeleteId = null;
                closeConfirm();
                loadAdminDashboard();
                showToast('🗑️ Product deleted!', 'success');
            }
        };

        // ==================== TOAST NOTIFICATION ====================
        function showToast(message, type = 'success') {
            const toast = document.getElementById('toast');
            toast.textContent = message;
            toast.className = `toast ${type} show`;

            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
        }

        // ==================== INITIALIZATION ====================
        document.addEventListener('DOMContentLoaded', function() {
            initData();
            renderProducts();

            // Close modals on overlay click
            document.querySelectorAll('.modal-overlay').forEach(overlay => {
                overlay.addEventListener('click', function(e) {
                    if (e.target === this) {
                        this.classList.remove('active');
                    }
                });
            });

            // Enter key for admin login
            document.getElementById('adminPassword').addEventListener('keypress', function(e) {
                if (e.key === 'Enter') {
                    adminLogin();
                }
            });
        });

        // Service Worker for offline support (future ready)
        if ('serviceWorker' in navigator) {
            // Placeholder for service worker registration
            // navigator.serviceWorker.register('/sw.js');
        }
    </script>
