      <span class="value" id="timeDisplay">60</span>
    </div>
    <div class="stat-box">
      <span class="icon">🧆</span>
      <span>مُقدّم</span>
      <span class="value" id="servedDisplay">0</span>
    </div>
    <div class="stat-box">
      <span class="icon">🔥</span>
      <span>كومبو</span>
      <span class="value" id="comboDisplayHeader">x1</span>
    </div>
  </div>

  <!-- Level Progress -->
  <div id="levelProgress" style="display:none;">
    <div id="levelProgressFill"></div>
  </div>

  <!-- Day Indicator -->
  <div id="dayIndicator" style="display:none;">☀️</div>

  <!-- Customer Queue -->
  <div id="customerQueue" style="display:none;"></div>

  <!-- Combo Display -->
  <div id="comboDisplay"></div>

  <!-- Main Area -->
  <div id="mainArea" style="display:none;">
    <!-- Cooking Station -->
    <div id="cookingStation">
      <h3>🍳 محطة القلي</h3>
      <div id="fryer" onclick="toggleFryer()">
        <div id="oil">
          <div class="oil-bubble" style="left:20%; bottom:10%; animation-delay:0s;"></div>
          <div class="oil-bubble" style="left:50%; bottom:5%; animation-delay:0.3s;"></div>
          <div class="oil-bubble" style="left:70%; bottom:15%; animation-delay:0.6s;"></div>
          <div class="oil-bubble" style="left:35%; bottom:8%; animation-delay:0.9s;"></div>
        </div>
        <div id="falafelPatty"></div>
      </div>
      <div id="temperatureBar">
        <div id="temperatureFill"></div>
      </div>
      <div id="tempLabel">الحرارة: 150°C</div>
      <button class="cook-btn" id="cookBtn" onclick="startFrying()">🔥 اقلي الفلافل!</button>
      <button class="cook-btn secondary" id="removeBtn" onclick="removeFalafel()" style="display:none; background: linear-gradient(180deg, #ff4444 0%, #cc0000 100%);">🗑️ أزل الفلافل</button>
      <div id="cookedCount" style="text-align:center; margin-top:10px; color:#aaa; font-size:12px;">
        فلافل جاهزة: <span id="cookedFalafelCount">0</span>/3
      </div>
    </div>

    <!-- Assembly Station -->
    <div id="assemblyStation">
      <h3>🥪 محطة التجهيز</h3>
      <div id="sandwichArea">
        <div class="sandwich-layer layer-bread-top" id="layerBreadTop"></div>
        <div class="sandwich-layer layer-pickle" id="layerPickle"></div>
        <div class="sandwich-layer layer-salad" id="layerSalad"></div>
        <div class="sandwich-layer layer-tahini" id="layerTahini"></div>
        <div class="sandwich-layer layer-falafel" id="layerFalafel"></div>
        <div class="sandwich-layer layer-bread-bottom" id="layerBreadBottom"></div>
      </div>
      <div id="ingredients">
        <button class="ingredient-btn" onclick="addIngredient('bread')">
          <span class="emoji">🍞</span>
          خبز
        </button>
        <button class="ingredient-btn" onclick="addIngredient('falafel')">
          <span class="emoji">🧆</span>
          فلافل
        </button>
        <button class="ingredient-btn" onclick="addIngredient('tahini')">
          <span class="emoji">🥄</span>
          طحينة
        </button>
        <button class="ingredient-btn" onclick="addIngredient('salad')">
          <span class="emoji">🥬</span>
          سلطة
        </button>
        <button class="ingredient-btn" onclick="addIngredient('pickle')">
          <span class="emoji">🥒</span>
          مخلل
        </button>
        <button class="ingredient-btn" onclick="addIngredient('spice')">
          <span class="emoji">🌶️</span>
          توابل
        </button>
      </div>
      <button id="serveBtn" onclick="serveSandwich()" disabled>🍽️ قدّم الساندوتش!</button>
      <button class="cook-btn secondary" onclick="clearSandwich()" style="margin-top:10px; background: linear-gradient(180deg, #666 0%, #444 100%); color:#fff;">🔄 إعادة</button>
    </div>
  </div>

  <!-- Fly Section -->
  <div id="flySection"></div>

  <!-- Upgrade Panel -->
  <div id="upgradePanel">
    <h2>🏪 الترقيات</h2>
    <div id="upgradeList"></div>
    <button class="close-btn" onclick="closeUpgrades()">إغلاق ❌</button>
  </div>

  <!-- Spice Panel -->
  <div id="spicePanel">
    <h2>🌶️ سر الخلطة</h2>
    <p style="color:#aaa; margin-bottom:15px;">اختر التوابل السرية لزيادة الأرباح!</p>
    <div>
      <button class="spice-btn" onclick="selectSpice('cumin')">🫘 كمون</button>
      <button class="spice-btn" onclick="selectSpice('coriander')">🌿 كزبرة</button>
      <button class="spice-btn" onclick="selectSpice('garlic')">🧄 ثوم</button>
      <button class="spice-btn" onclick="selectSpice('chili')">🌶️ فلفل حار</button>
    </div>
    <button class="cook-btn" onclick="applySpice()" style="margin-top:15px;">✅ تطبيق الخلطة</button>
    <button class="close-btn" onclick="closeSpice()">إلغاء ❌</button>
  </div>

  <!-- Level Up Overlay -->
  <div id="levelUpOverlay">
    <div class="content">
      <h2>🎉 مستوى جديد!</h2>
      <p id="levelUpText">وصلت للمستوى 2!</p>
      <button class="start-btn" onclick="closeLevelUp()">استمر! 🚀</button>
    </div>
  </div>

  <!-- Bottom Bar -->
  <div id="bottomBar" style="display:none;">
    <button class="bottom-btn" onclick="openUpgrades()">🏪 ترقيات</button>
    <button class="bottom-btn" onclick="openSpice()">🌶️ سر الخلطة</button>
    <button class="bottom-btn secondary" onclick="pauseGame()">⏸️ إيقاف</button>
  </div>
</div>

<script>
// Game State
const gameState = {
  money: 0,
  level: 1,
  time: 60,
  served: 0,
  combo: 0,
  maxCombo: 0,
  isPlaying: false,
  isPaused: false,
  isFrying: false,
  fryTime: 0,
  temperature: 150,
  cookedFalafel: 0,
  maxCookedFalafel: 3,
  currentSandwich: {
    bread: false,
    falafel: false,
    tahini: false,
    salad: false,
    pickle: false,
    spice: false
  },
  customers: [],
  maxCustomers: 3,
  customerSpawnRate: 5000,
  lastSpawn: 0,
  upgrades: {
    betterOil: false,
    extraBread: false,
    fasterCook: false,
    moreCustomers: false,
    autoTahini: false,
    spiceMaster: false
  },
  selectedSpice: null,
  spiceMultiplier: 1,
  totalServed: 0,
  flies: [],
  flyTimer: null,
  gameTimer: null,
  spawnTimer: null,
  comboTimer: null
};

// Customer Names & Faces
const customerNames = ['أحمد', 'محمد', 'فاطمة', 'علي', 'سارة', 'خالد', 'نور', 'يوسف', 'مريم', 'عمر'];
const customerFaces = ['😄', '😊', '😋', '🤤', '😎', '🥳', '😃', '😁', '🤩', '😺'];
const customerOrders = [
  'فلافل عادي',
  'فلافل بطحينة',
  'فلافل بسلطة',
  'فلافل بمخلل',
  'فلافل كامل',
  'فلافل بالتوابل',
  'فلافل خاص'
];

// Upgrades Data
const upgradesData = [
  { id: 'betterOil', name: '🛢️ زيت أفضل', desc: 'الفلافل بتقلي أسرع بـ 20%', cost: 50, effect: () => { gameState.upgrades.betterOil = true; }},
  { id: 'extraBread', name: '🍞 خبز إضافي', desc: 'ابدأ بالخبز تلقائياً', cost: 30, effect: () => { gameState.upgrades.extraBread = true; }},
  { id: 'fasterCook', name: '🔥 نار أقوى', desc: 'القلي أسرع بـ 30%', cost: 80, effect: () => { gameState.upgrades.fasterCook = true; }},
  { id: 'moreCustomers', name: '👥 زبائن أكثر', desc: 'زد عدد الزبائن في الطابور', cost: 100, effect: () => { gameState.upgrades.moreCustomers = true; }},
  { id: 'autoTahini', name: '🥄 طحينة تلقائية', desc: 'الطحينة بتضاف تلقائياً', cost: 60, effect: () => { gameState.upgrades.autoTahini = true; }},
  { id: 'spiceMaster', name: '🌶️ мастер التوابل', desc: 'ضرب التوابل x2', cost: 120, effect: () => { gameState.upgrades.spiceMaster = true; }}
];

// Initialize Game
function startGame() {
  document.getElementById('startScreen').style.display = 'none';
  document.getElementById('header').style.display = 'flex';
  document.getElementById('levelProgress').style.display = 'block';
  document.getElementById('dayIndicator').style.display = 'block';
  document.getElementById('customerQueue').style.display = 'flex';
  document.getElementById('mainArea').style.display = 'flex';
  document.getElementById('bottomBar').style.display = 'flex';

  gameState.isPlaying = true;
  gameState.time = 60;
  gameState.money = 0;
  gameState.level = 1;
  gameState.served = 0;
  gameState.combo = 0;
  gameState.cookedFalafel = 0;
  gameState.customers = [];

  updateDisplay();
  startGameTimer();
  startCustomerSpawn();
  startFlyTimer();

  showNotification('🎮 اهلاً بيك في ملك الفلافل!');
}

function showTutorial() {
  alert('📖 طريقة اللعب:\n\n1. 🍳 اقلي الفلافل بالضغط على زر "قلي الفلافل"\n2. 🌡️راقب الحرارة - مش حرانة ولا باردة!\n3. 🥪 جهز الساندوتش بالمكونات المطلوبة\n4. 🍽️ قدّم للزبون قبل ما يمل\n5. 💰 اجمع الفلوس واشترِ ترقيات\n6. 🪰 اضرب الذباب إذا ظهر!\n\n💡 نصيحة: كل ما تخدم أسرع، كومبو أكبر، فلوس أكثر!');
}

// Game Timer
function startGameTimer() {
  if (gameState.gameTimer) clearInterval(gameState.gameTimer);
  gameState.gameTimer = setInterval(() => {
    if (!gameState.isPlaying || gameState.isPaused) return;

    gameState.time--;
    updateDisplay();

    if (gameState.time <= 0) {
      endLevel();
    }
  }, 1000);
}

// Customer Spawning
function startCustomerSpawn() {
  if (gameState.spawnTimer) clearInterval(gameState.spawnTimer);
  gameState.spawnTimer = setInterval(() => {
    if (!gameState.isPlaying || gameState.isPaused) return;
    if (gameState.customers.length < gameState.maxCustomers) {
      spawnCustomer();
    }
  }, gameState.customerSpawnRate);
}

function spawnCustomer() {
  const name = customerNames[Math.floor(Math.random() * customerNames.length)];
  const face = customerFaces[Math.floor(Math.random() * customerFaces.length)];
  const order = customerOrders[Math.floor(Math.random() * Math.min(gameState.level + 1, customerOrders.length))];
  const patience = 15 + Math.random() * 15;

  const customer = {
    id: Date.now() + Math.random(),
    name,
    face,
    order,
    patience,
    maxPatience: patience,
    state: 'waiting'
  };

  gameState.customers.push(customer);
  renderCustomers();
}

function renderCustomers() {
  const queue = document.getElementById('customerQueue');
  queue.innerHTML = '';

  gameState.customers.forEach(customer => {
    const patiencePercent = (customer.patience / customer.maxPatience) * 100;
    const isImpatient = patiencePercent < 30;

    const div = document.createElement('div');
    div.className = `customer ${isImpatient ? 'impatient' : ''}`;
    div.innerHTML = `
      <div class="customer-face">${customer.face}</div>
      <div class="customer-order">${customer.order}</div>
      <div class="customer-patience">
        <div class="customer-patience-bar" style="width:${patiencePercent}%"></div>
      </div>
      <div class="customer-timer">${Math.ceil(customer.patience)}ث</div>
    `;
    queue.appendChild(div);
  });
}

// Customer Patience Timer
setInterval(() => {
  if (!gameState.isPlaying || gameState.isPaused) return;

  gameState.customers = gameState.customers.filter(customer => {
    customer.patience -= 0.5;

    if (customer.patience <= 0) {
      showNotification(`😡 ${customer.name} غاضب! راح بدون ساندوتش`);
      gameState.combo = 0;
      updateDisplay();
      return false;
    }
    return true;
  });

  renderCustomers();
}, 500);

// Frying Mechanic
function toggleFryer() {
  if (!gameState.isFrying) return;

  const patty = document.getElementById('falafelPatty');
  const oil = document.getElementById('oil');

  if (gameState.fryTime > 3 && gameState.fryTime < 8) {
    // Perfect!
    patty.className = 'done';
    oil.className = '';
    gameState.cookedFalafel++;
    document.getElementById('cookedFalafelCount').textContent = gameState.cookedFalafel;
    showFloatingText('🧆 مثالي!', window.innerWidth / 2, window.innerHeight / 2);
    stopFrying();
  } else if (gameState.fryTime >= 8) {
    // Burnt!
    patty.className = 'burnt';
    oil.className = 'burning';
    showNotification('🔥 الفلافل احترقت!');
    stopFrying();
  } else {
    // Undercooked
    patty.className = 'cooking';
    showNotification('⚠️ الفلافل لسه نيئة!');
    stopFrying();
  }
}

function startFrying() {
  if (gameState.isFrying || gameState.cookedFalafel >= gameState.maxCookedFalafel) return;

  gameState.isFrying = true;
  gameState.fryTime = 0;

  const patty = document.getElementById('falafelPatty');
  const oil = document.getElementById('oil');
  const tempFill = document.getElementById('temperatureFill');
  const tempLabel = document.getElementById('tempLabel');
  const cookBtn = document.getElementById('cookBtn');
  const removeBtn = document.getElementById('removeBtn');

  patty.className = 'cooking';
  oil.className = 'hot';
  cookBtn.style.display = 'none';
  removeBtn.style.display = 'block';

  let fryInterval = setInterval(() => {
    if (!gameState.isFrying) {
      clearInterval(fryInterval);
      return;
    }

    gameState.fryTime += 0.1;

    // Temperature simulation
    gameState.temperature = 150 + Math.sin(gameState.fryTime * 0.5) * 30;
    const tempPercent = Math.min(100, (gameState.temperature / 250) * 100);
    tempFill.style.width = tempPercent + '%';
    tempLabel.textContent = `الحرارة: ${Math.round(gameState.temperature)}°C`;

    if (gameState.temperature > 220) {
      oil.className = 'burning';
      tempFill.style.background = '#ff4444';
    } else if (gameState.temperature > 180) {
      oil.className = 'hot';
      tempFill.style.background = 'linear-gradient(90deg, #44ff44, #ffaa00, #ff4444)';
    } else {
      oil.className = '';
      tempFill.style.background = 'linear-gradient(90deg, #44ff44, #ffaa00)';
    }

    // Auto-remove if too long
    if (gameState.fryTime > 10) {
      clearInterval(fryInterval);
      stopFrying();
      patty.className = 'burnt';
      showNotification('🔥 الفلافل احترقت!');
    }
  }, 100);

  // Store interval for cleanup
  gameState.fryInterval = fryInterval;
}

function stopFrying() {
  gameState.isFrying = false;
  if (gameState.fryInterval) clearInterval(gameState.fryInterval);

  const cookBtn = document.getElementById('cookBtn');
  const removeBtn = document.getElementById('removeBtn');
  const patty = document.getElementById('falafelPatty');
  const oil = document.getElementById('oil');

  cookBtn.style.display = 'block';
  removeBtn.style.display = 'none';

  if (patty.className !== 'done' && patty.className !== 'burnt') {
    patty.className = '';
  }
  oil.className = '';

  document.getElementById('tempLabel').textContent = 'الحرارة: 150°C';
  document.getElementById('temperatureFill').style.width = '50%';
}

function removeFalafel() {
  stopFrying();
  const patty = document.getElementById('falafelPatty');
  patty.className = '';
  showNotification('🗑️ تم إزالة الفلافل');
}

// Sandwich Assembly
function addIngredient(ingredient) {
  if (!gameState.isPlaying || gameState.isPaused) return;

  if (gameState.currentSandwich[ingredient]) {
    showNotification('⚠️ ده موجود بالفعل!');
    return;
  }

  // Check requirements
  if (ingredient === 'falafel' && gameState.cookedFalafel <= 0) {
    showNotification('🧆 محتاج تقلي فلافل الأول!');
    return;
  }

  gameState.currentSandwich[ingredient] = true;

  // Update visual
  const layerMap = {
    'bread': 'layerBreadBottom',
    'falafel': 'layerFalafel',
    'tahini': 'layerTahini',
    'salad': 'layerSalad',
    'pickle': 'layerPickle',
    'spice': 'layerPickle'
  };

  if (layerMap[ingredient]) {
    const layer = document.getElementById(layerMap[ingredient]);
    layer.classList.add('visible');
  }

  // Mark button as used
  event.target.closest('.ingredient-btn').classList.add('used');

  // Auto bread
  if (ingredient === 'bread' || gameState.upgrades.extraBread) {
    document.getElementById('layerBreadTop').classList.add('visible');
    gameState.currentSandwich.bread = true;
  }

  // Check if sandwich is complete
  checkSandwichComplete();
}

function checkSandwichComplete() {
  const s = gameState.currentSandwich;
  const isComplete = s.bread && s.falafel && (s.tahini || s.salad || s.pickle);

  document.getElementById('serveBtn').disabled = !isComplete;
}

function clearSandwich() {
  gameState.currentSandwich = {
    bread: false,
    falafel: false,
    tahini: false,
    salad: false,
    pickle: false,
    spice: false
  };

  // Reset visual layers
  document.querySelectorAll('.sandwich-layer').forEach(l => l.classList.remove('visible'));

  // Reset buttons
  document.querySelectorAll('.ingredient-btn').forEach(b => b.classList.remove('used'));

  document.getElementById('serveBtn').disabled = true;

  // Return falafel
  gameState.cookedFalafel = Math.min(gameState.cookedFalafel + 1, gameState.maxCookedFalafel);
  document.getElementById('cookedFalafelCount').textContent = gameState.cookedFalafel;
}

function serveSandwich() {
  if (!gameState.isPlaying || gameState.isPaused) return;

  const isComplete = Object.values(gameState.currentSandwich).every(v => v);
  if (!isComplete) return;

  // Find matching customer
  const customer = gameState.customers[0];
  if (!customer) {
    showNotification('⚠️ مفيش زبائن!');
    return;
  }

  // Calculate earnings
  let earnings = 10 * gameState.level;

  // Combo bonus
  if (gameState.combo > 0) {
    earnings *= (1 + gameState.combo * 0.1);
  }

  // Spice bonus
  earnings *= gameState.spiceMultiplier;

  // Patience bonus
  const patiencePercent = customer.patience / customer.maxPatience;
  if (patiencePercent > 0.7) {
    earnings *= 1.5;
    showNotification('⚡ بونص السرعة!');
  }

  earnings = Math.round(earnings);
  gameState.money += earnings;
  gameState.served++;
  gameState.totalServed++;
  gameState.combo++;

  if (gameState.combo > gameState.maxCombo) {
    gameState.maxCombo = gameState.combo;
  }

  // Remove customer
  gameState.customers.shift();
  renderCustomers();

  // Clear sandwich
  clearSandwich();

  // Show floating text
  showFloatingText(`+${earnings}💰`, window.innerWidth / 2, window.innerHeight / 2);

  // Update display
  updateDisplay();

  // Check level up
  if (gameState.served >= gameState.level * 5) {
    levelUp();
  }

  showNotification(`✅ قدّمت لـ ${customer.name}! +${earnings}💰`);
}

// Level Up
function levelUp() {
  gameState.level++;
  gameState.time += 30;
  gameState.maxCustomers = Math.min(6, 3 + Math.floor(gameState.level / 2));
  gameState.customerSpawnRate = Math.max(2000, 5000 - gameState.level * 300);

  document.getElementById('levelUpText').textContent = `وصلت للمستوى ${gameState.level}! الوقت زائد 30 ثانية`;
  document.getElementById('levelUpOverlay').style.display = 'flex';

  // Restart spawn with new rate
  startCustomerSpawn();

  updateDisplay();
}

function closeLevelUp() {
  document.getElementById('levelUpOverlay').style.display = 'none';
}

// End Level
function endLevel() {
  gameState.isPlaying = false;
  clearInterval(gameState.gameTimer);
  clearInterval(gameState.spawnTimer);
  clearInterval(gameState.flyTimer);

  showNotification(`🏁 انتهى الوقت! قدّمت ${gameState.served} ساندوتش`);

  setTimeout(() => {
    if (confirm(`🏁 انتهى الوقت!\n\nقدّمت: ${gameState.served} ساندوتش\nالفلوس: ${gameState.money}💰\nأعلى كومبو: x${gameState.maxCombo}\n\nتعيد من جديد؟`)) {
      startGame();
    }
  }, 1000);
}

// Fly Swatting
function startFlyTimer() {
  if (gameState.flyTimer) clearInterval(gameState.flyTimer);
  gameState.flyTimer = setInterval(() => {
    if (!gameState.isPlaying || gameState.isPaused) return;
    if (Math.random() < 0.3) {
      spawnFly();
    }
  }, 8000);
}

function spawnFly() {
  const flySection = document.getElementById('flySection');
  flySection.style.display = 'block';

  const fly = document.createElement('div');
  fly.className = 'fly';
  fly.textContent = '🪰';
  fly.style.left = Math.random() * (window.innerWidth - 50) + 'px';
  fly.style.top = Math.random() * (window.innerHeight - 50) + 'px';

  fly.onclick = function() {
    fly.classList.add('fly-swatted');
    setTimeout(() => fly.remove(), 300);
    gameState.money += 5;
    updateDisplay();
    showFloatingText('+5💰', parseFloat(fly.style.left), parseFloat(fly.style.top));

    // Check if all flies are swatted
    setTimeout(() => {
      if (document.querySelectorAll('.fly').length === 0) {
        flySection.style.display = 'none';
      }
    }, 300);
  };

  flySection.appendChild(fly);

  // Auto-remove fly after 5 seconds
  setTimeout(() => {
    if (fly.parentNode) {
      fly.remove();
      if (document.querySelectorAll('.fly').length === 0) {
        flySection.style.display = 'none';
      }
    }
  }, 5000);
}

// Upgrades
function openUpgrades() {
  const panel = document.getElementById('upgradePanel');
  const list = document.getElementById('upgradeList');
  list.innerHTML = '';

  upgradesData.forEach(upgrade => {
    const div = document.createElement('div');
    div.className = `upgrade-item ${gameState.upgrades[upgrade.id] ? 'owned' : ''}`;
    div.innerHTML = `
      <div class="upgrade-info">
        <h4>${upgrade.name}</h4>
        <p>${upgrade.desc}</p>
      </div>
      <button class="upgrade-btn" onclick="buyUpgrade('${upgrade.id}')" ${gameState.upgrades[upgrade.id] || gameState.money < upgrade.cost ? 'disabled' : ''}>
        ${gameState.upgrades[upgrade.id] ? '✅ تم' : upgrade.cost + '💰'}
      </button>
    `;
    list.appendChild(div);
  });

  panel.style.display = 'block';
}

function closeUpgrades() {
  document.getElementById('upgradePanel').style.display = 'none';
}

function buyUpgrade(id) {
  const upgrade = upgradesData.find(u => u.id === id);
  if (!upgrade || gameState.money < upgrade.cost || gameState.upgrades[id]) return;

  gameState.money -= upgrade.cost;
  gameState.upgrades[id] = true;
  upgrade.effect();

  updateDisplay();
  openUpgrades(); // Refresh

  showNotification(`🎉 اشتريت: ${upgrade.name}!`);
}

// Spice Mix
function openSpice() {
  document.getElementById('spicePanel').style.display = 'block';
}

function closeSpice() {
  document.getElementById('spicePanel').style.display = 'none';
  gameState.selectedSpice = null;
  document.querySelectorAll('.spice-btn').forEach(b => b.classList.remove('selected'));
}

function selectSpice(spice) {
  gameState.selectedSpice = spice;
  document.querySelectorAll('.spice-btn').forEach(b => b.classList.remove('selected'));
  event.target.classList.add('selected');
}

function applySpice() {
  if (!gameState.selectedSpice) {
    showNotification('⚠️ اختر تابة الأول!');
    return;
  }

  const spiceMultipliers = {
    'cumin': 1.2,
    'coriander': 1.3,
    'garlic': 1.5,
    'chili': 2.0
  };

  gameState.spiceMultiplier = spiceMultipliers[gameState.selectedSpice];
  if (gameState.upgrades.spiceMaster) {
    gameState.spiceMultiplier *= 2;
  }

  showNotification(`🌶️ تم تطبيق تابة ${gameState.selectedSpice}! ضرب x${gameState.spiceMultiplier.toFixed(1)}`);
  closeSpice();
}

// Pause
function pauseGame() {
  gameState.isPaused = !gameState.isPaused;
  showNotification(gameState.isPaused ? '⏸️ اللعبة متوقفة' : '▶️ استمر!');
}

// Display Updates
function updateDisplay() {
  document.getElementById('moneyDisplay').textContent = gameState.money;
  document.getElementById('levelDisplay').textContent = gameState.level;
  document.getElementById('timeDisplay').textContent = gameState.time;
  document.getElementById('servedDisplay').textContent = gameState.served;
  document.getElementById('comboDisplayHeader').textContent = `x${gameState.combo}`;

  // Level progress
  const progress = (gameState.served % (gameState.level * 5)) / (gameState.level * 5) * 100;
  document.getElementById('levelProgressFill').style.width = progress + '%';

  // Day indicator
  const hour = Math.floor(gameState.time / 60);
  document.getElementById('dayIndicator').textContent = hour % 2 === 0 ? '☀️' : '🌙';
}

// Floating Text
function showFloatingText(text, x, y) {
  const div = document.createElement('div');
  div.className = 'floating-text';
  div.textContent = text;
  div.style.left = x + 'px';
  div.style.top = y + 'px';
  document.getElementById('gameContainer').appendChild(div);

  setTimeout(() => div.remove(), 1000);
}

// Notification
function showNotification(text) {
  const div = document.createElement('div');
  div.className = 'notification';
  div.textContent = text;
  document.getElementById('gameContainer').appendChild(div);

  setTimeout(() => div.remove(), 2000);
}

// Keyboard shortcuts
document.addEventListener('keydown', (e) => {
  if (!gameState.isPlaying) return;

  switch(e.key) {
    case ' ':
      e.preventDefault();
      if (!gameState.isFrying) {
        startFrying();
      } else {
        toggleFryer();
      }
      break;
    case 'r':
    case 'R':
      clearSandwich();
      break;
    case 's':
    case 'S':
      serveSandwich();
      break;
    case 'Escape':
      pauseGame();
      break;
  }
});

// Prevent context menu
document.addEventListener('contextmenu', e => e.preventDefault());
</script>
