<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const minimapCanvas = document.getElementById('minimap');
const minimapCtx = minimapCanvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
minimapCanvas.width = 180;
minimapCanvas.height = 180;

const WORLD_SIZE = 3000;
const TILE_SIZE = 50;

// Game state
let gameRunning = false;
let gameTime = 0;
let zonePhase = 0;
let zoneTimer = 30;
let zoneCenter = { x: WORLD_SIZE / 2, y: WORLD_SIZE / 2 };
let zoneRadius = WORLD_SIZE * 0.45;
let zoneTargetRadius = WORLD_SIZE * 0.45;
let zoneShrinking = false;

// Weapons database
const WEAPONS = {
    pistol: { name: 'Pistol', damage: 15, fireRate: 400, range: 400, ammo: Infinity, maxAmmo: Infinity, spread: 0.05, speed: 15, color: '#ffeb3b', auto: false },
    shotgun: { name: 'Shotgun', damage: 10, fireRate: 800, range: 250, ammo: 30, maxAmmo: 30, spread: 0.15, speed: 12, color: '#ff9800', auto: false, pellets: 6 },
    rifle: { name: 'Rifle', damage: 25, fireRate: 150, range: 600, ammo: 90, maxAmmo: 90, spread: 0.03, speed: 20, color: '#4caf50', auto: true },
    sniper: { name: 'Sniper', damage: 80, fireRate: 1200, range: 1000, ammo: 20, maxAmmo: 20, spread: 0.01, speed: 25, color: '#f44336', auto: false },
    smg: { name: 'SMG', damage: 12, fireRate: 100, range: 350, ammo: 120, maxAmmo: 120, spread: 0.08, speed: 18, color: '#9c27b0', auto: true }
};

// Items
const ITEM_TYPES = ['health', 'armor', 'ammo_pistol', 'ammo_shotgun', 'ammo_rifle', 'ammo_sniper', 'ammo_smg'];

// Game objects
let players = [];
let bots = [];
let bullets = [];
let items = [];
let particles = [];
let buildings = [];
let killFeed = [];

// Input
const keys = {};
let mouseX = 0, mouseY = 0;
let mouseDown = false;

class Player {
    constructor(x, y, id, isBot = false) {
        this.x = x;
        this.y = y;
        this.id = id;
        this.isBot = isBot;
        this.radius = 18;
        this.speed = 3.5;
        this.hp = 100;
        this.maxHp = 100;
        this.armor = 0;
        this.maxArmor = 100;
        this.angle = 0;
        this.weapons = [{ ...WEAPONS.pistol, ammo: Infinity }];
        this.currentWeapon = 0;
        this.lastShot = 0;
        this.kills = 0;
        this.alive = true;
        this.reloadTime = 0;
        this.isReloading = false;
        this.color = id === 1 ? '#4fc3f7' : id === 2 ? '#ff7043' : '#888';
        this.name = isBot ? `Bot ${id}` : `Player ${id}`;
        this.vx = 0;
        this.vy = 0;
        this.pickupRange = 50;
    }

    get weapon() {
        return this.weapons[this.currentWeapon];
    }

    shoot(targetX, targetY) {
        const now = Date.now();
        const w = this.weapon;
        if (now - this.lastShot < w.fireRate) return;
        if (this.isReloading) return;
        if (w.ammo <= 0 && w.ammo !== Infinity) {
            this.reload();
            return;
        }

        this.lastShot = now;
        if (w.ammo !== Infinity) w.ammo--;

        const pellets = w.pellets || 1;
        for (let i = 0; i < pellets; i++) {
            const spread = (Math.random() - 0.5) * w.spread * 2;
            const angle = this.angle + spread;
            bullets.push({
                x: this.x + Math.cos(this.angle) * 25,
                y: this.y + Math.sin(this.angle) * 25,
                vx: Math.cos(angle) * w.speed,
                vy: Math.sin(angle) * w.speed,
                damage: w.damage,
                range: w.range,
                traveled: 0,
                owner: this.id,
                color: w.color
            });
        }

        // Muzzle flash
        for (let i = 0; i < 5; i++) {
            particles.push({
                x: this.x + Math.cos(this.angle) * 25,
                y: this.y + Math.sin(this.angle) * 25,
                vx: Math.cos(this.angle + (Math.random() - 0.5) * 0.5) * (3 + Math.random() * 3),
                vy: Math.sin(this.angle + (Math.random() - 0.5) * 0.5) * (3 + Math.random() * 3),
                life: 10,
                maxLife: 10,
                color: w.color,
                size: 3
            });
        }
    }

    reload() {
        const w = this.weapon;
        if (w.ammo === Infinity || w.ammo === w.maxAmmo) return;
        this.isReloading = true;
        this.reloadTime = Date.now();
        setTimeout(() => {
            if (this.alive) {
                w.ammo = w.maxAmmo;
                this.isReloading = false;
            }
        }, 2000);
    }

    takeDamage(damage, attackerId) {
        if (!this.alive) return;
        let actualDamage = damage;
        if (this.armor > 0) {
            const armorAbsorb = Math.min(this.armor, damage * 0.6);
            this.armor -= armorAbsorb;
            actualDamage = damage * 0.4;
        }
        this.hp -= actualDamage;
        if (this.hp <= 0) {
            this.hp = 0;
            this.alive = false;
            if (attackerId) {
                const attacker = players.find(p => p.id === attackerId) || bots.find(b => b.id === attackerId);
                if (attacker) attacker.kills++;
                addKillFeed(this.name, attacker ? attacker.name : 'Zone');
            }
            // Drop items
            for (let i = 0; i < 3; i++) {
                items.push({
                    x: this.x + (Math.random() - 0.5) * 40,
                    y: this.y + (Math.random() - 0.5) * 40,
                    type: ITEM_TYPES[Math.floor(Math.random() * ITEM_TYPES.length)],
                    radius: 10
                });
            }
        }
    }

    update() {
        if (!this.alive) return;

        // Zone damage
        const distToZone = Math.hypot(this.x - zoneCenter.x, this.y - zoneCenter.y);
        if (distToZone > zoneRadius) {
            this.takeDamage(0.5, 0);
        }

        // Bot AI
        if (this.isBot) {
            this.botAI();
        }
    }

    botAI() {
        // Find nearest target
        let nearestTarget = null;
        let nearestDist = Infinity;

        // Check players
        for (const p of players) {
            if (!p.alive || p.id === this.id) continue;
            const dist = Math.hypot(p.x - this.x, p.y - this.y);
            if (dist < nearestDist && dist < 500) {
                nearestDist = dist;
                nearestTarget = p;
            }
        }

        // Check other bots
        for (const b of bots) {
            if (!b.alive || b.id === this.id) continue;
            const dist = Math.hypot(b.x - this.x, b.y - this.y);
            if (dist < nearestDist && dist < 400) {
                nearestDist = dist;
                nearestTarget = b;
            }
        }

        if (nearestTarget) {
            this.angle = Math.atan2(nearestTarget.y - this.y, nearestTarget.x - this.x);
            if (nearestDist < 300) {
                this.shoot(nearestTarget.x, nearestTarget.y);
            }
            // Move towards target but keep some distance
            if (nearestDist > 150) {
                this.x += Math.cos(this.angle) * this.speed * 0.7;
                this.y += Math.sin(this.angle) * this.speed * 0.7;
            } else if (nearestDist < 100) {
                this.x -= Math.cos(this.angle) * this.speed * 0.5;
                this.y -= Math.sin(this.angle) * this.speed * 0.5;
            }
        }

        // Move towards zone if outside
        const distToZone = Math.hypot(this.x - zoneCenter.x, this.y - zoneCenter.y);
        if (distToZone > zoneRadius * 0.8) {
            const angleToZone = Math.atan2(zoneCenter.y - this.y, zoneCenter.x - this.x);
            this.x += Math.cos(angleToZone) * this.speed * 0.5;
            this.y += Math.sin(angleToZone) * this.speed * 0.5;
        }

        // Pick up items
        for (let i = items.length - 1; i >= 0; i--) {
            const item = items[i];
            const dist = Math.hypot(item.x - this.x, item.y - this.y);
            if (dist < this.pickupRange) {
                this.pickupItem(item);
                items.splice(i, 1);
            }
        }

        // Keep in bounds
        this.x = Math.max(this.radius, Math.min(WORLD_SIZE - this.radius, this.x));
        this.y = Math.max(this.radius, Math.min(WORLD_SIZE - this.radius, this.y));
    }

    pickupItem(item) {
        switch (item.type) {
            case 'health':
                this.hp = Math.min(this.maxHp, this.hp + 30);
                break;
            case 'armor':
                this.armor = Math.min(this.maxArmor, this.armor + 50);
                break;
            default:
                const ammoMap = {
                    'ammo_pistol': { weapon: 'pistol', ammo: 30 },
                    'ammo_shotgun': { weapon: 'shotgun', ammo: 10 },
                    'ammo_rifle': { weapon: 'rifle', ammo: 30 },
                    'ammo_sniper': { weapon: 'sniper', ammo: 5 },
                    'ammo_smg': { weapon: 'smg', ammo: 30 }
                };
                const ammo = ammoMap[item.type];
                if (ammo) {
                    const w = this.weapons.find(w => w.name.toLowerCase() === ammo.weapon);
                    if (w) w.ammo = Math.min(w.maxAmmo, w.ammo + ammo.ammo);
                }
        }
    }

    draw() {
        if (!this.alive) return;

        // Shadow
        ctx.beginPath();
        ctx.ellipse(this.x, this.y + 5, this.radius, this.radius * 0.6, 0, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fill();

        // Body
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Gun
        const gunLen = 25;
        ctx.beginPath();
        ctx.moveTo(this.x + Math.cos(this.angle) * 10, this.y + Math.sin(this.angle) * 10);
        ctx.lineTo(this.x + Math.cos(this.angle) * gunLen, this.y + Math.sin(this.angle) * gunLen);
        ctx.strokeStyle = '#333';
        ctx.lineWidth = 4;
        ctx.stroke();
        ctx.strokeStyle = '#666';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Name
        ctx.fillStyle = '#fff';
        ctx.font = '12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(this.name, this.x, this.y - 25);

        // HP bar
        const barWidth = 40;
        const barHeight = 4;
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
