            }

            // Weapon switch
            if (keys['1']) p.currentWeapon = 0;
            if (keys['2'] && p.weapons.length > 1) p.currentWeapon = 1;
            if (keys['3'] && p.weapons.length > 2) p.currentWeapon = 2;
            if (keys['4'] && p.weapons.length > 3) p.currentWeapon = 3;

        } else if (p.id === 2) {
            // Player 2 controls
            let dx = 0, dy = 0;
            if (keys['ArrowUp']) dy -= 1;
            if (keys['ArrowDown']) dy += 1;
            if (keys['ArrowLeft']) dx -= 1;
            if (keys['ArrowRight']) dx += 1;

            if (dx !== 0 || dy !== 0) {
                const len = Math.hypot(dx, dy);
                dx /= len; dy /= len;
                p.x += dx * p.speed;
                p.y += dy * p.speed;
            }

            // Aim with Q,E,T,G keys (8 directions)
            let aimDx = 0, aimDy = 0;
            if (keys['q'] || keys['Q']) { aimDx -= 1; aimDy -= 1; }
            if (keys['e'] && !keys['E']) { aimDx += 1; aimDy -= 1; }
            if (keys['t'] || keys['T']) { aimDx -= 1; aimDy += 1; }
            if (keys['g'] || keys['G']) { aimDx += 1; aimDy += 1; }
            if (aimDx === 0 && aimDy === 0) {
                // Default aim towards nearest enemy
                let nearest = null, nearDist = Infinity;
                for (const b of bots) {
                    if (!b.alive) continue;
                    const d = Math.hypot(b.x - p.x, b.y - p.y);
                    if (d < nearDist) { nearDist = d; nearest = b; }
                }
                if (nearest) {
                    p.angle = Math.atan2(nearest.y - p.y, nearest.x - p.x);
                }
            } else {
                p.angle = Math.atan2(aimDy, aimDx);
            }

            // Shoot with Num 0
            if (keys['NumPad0'] || keys['0']) {
                if (p.weapon.auto) {
                    p.shoot(p.x + Math.cos(p.angle) * 1000, p.y + Math.sin(p.angle) * 1000);
                } else if (Date.now() - p.lastShot > 200) {
                    p.shoot(p.x + Math.cos(p.angle) * 1000, p.y + Math.sin(p.angle) * 1000);
                }
            }

            // Reload with Num .
            if (keys['NumPadDecimal'] || keys['Period']) p.reload();

            // Pickup with Num ,
            if (keys['NumPadComma'] || keys['Comma']) {
                for (let i = items.length - 1; i >= 0; i--) {
                    const item = items[i];
                    const dist = Math.hypot(item.x - p.x, item.y - p.y);
                    if (dist < p.pickupRange) {
                        if (item.type.startsWith('weapon_')) {
                            const wName = item.type.replace('weapon_', '');
                            if (!p.weapons.find(w => w.name === WEAPONS[wName].name)) {
                                p.weapons.push({ ...item.weapon });
                            }
                        } else {
