            if (keys['6'] && p.weapons.length > 2) p.currentWeapon = 2;
            if (keys['7'] && p.weapons.length > 3) p.currentWeapon = 3;
        }

        // Keep in bounds
        p.x = Math.max(p.radius, Math.min(WORLD_SIZE - p.radius, p.x));
        p.y = Math.max(p.radius, Math.min(WORLD_SIZE - p.radius, p.y));

        // Building collision
        for (const b of buildings) {
            if (p.x + p.radius > b.x && p.x - p.radius < b.x + b.w &&
                p.y + p.radius > b.y && p.y - p.radius < b.y + b.h) {
                // Push out
                const overlapX = Math.min(p.x + p.radius - b.x, b.x + b.w - (p.x - p.radius));
                const overlapY = Math.min(p.y + p.radius - b.y, b.y + b.h - (p.y - p.radius));
                if (overlapX < overlapY) {
                    p.x += p.x < b.x + b.w / 2 ? -overlapX : overlapX;
                } else {
                    p.y += p.y < b.y + b.h / 2 ? -overlapY : overlapY;
                }
            }
        }

        p.update();
    }

    // Update bots
    for (const b of bots) {
        b.update();
    }

    // Update bullets
    for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.x += b.vx;
        b.y += b.vy;
        b.traveled += Math.hypot(b.vx, b.vy);

        if (b.traveled > b.range) {
            bullets.splice(i, 1);
            continue;
        }

        // Check building collision
        let hitBuilding = false;
        for (const building of buildings) {
            if (b.x > building.x && b.x < building.x + building.w &&
                b.y > building.y && b.y < building.y + building.h) {
                hitBuilding = true;
                break;
            }
        }
        if (hitBuilding) {
            bullets.splice(i, 1);
            continue;
        }

        // Check player/bot collision
        let hit = false;
        const allEntities = [...players, ...bots];
        for (const entity of allEntities) {
            if (!entity.alive || entity.id === b.owner) continue;
            const dist = Math.hypot(b.x - entity.x, b.y - entity.y);
            if (dist < entity.radius) {
                entity.takeDamage(b.damage, b.owner);
                hit = true;
                // Hit particles
                for (let j = 0; j < 8; j++) {
                    particles.push({
                        x: b.x, y: b.y,
                        vx: (Math.random() - 0.5) * 5,
                        vy: (Math.random() - 0.5) * 5,
                        life: 20, maxLife: 20,
                        color: '#f44336', size: 3
                    });
                }
                break;
            }
        }
        if (hit) bullets.splice(i, 1);
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life--;
        p.vx *= 0.95;
        p.vy *= 0.95;
        if (p.life <= 0) particles.splice(i, 1);
    }

    // Update UI
    updateUI();

    // Check win condition
    const alivePlayers = players.filter(p => p.alive).length;
    const aliveBots = bots.filter(b => b.alive).length;
    if (alivePlayers === 0 || (aliveBots === 0 && alivePlayers <= 1)) {
        gameRunning = false;
        const gameOver = document.getElementById('game-over');
        gameOver.style.display = 'flex';
        if (alivePlayers > 0) {
            document.getElementById('winner-text').innerHTML = `🎉 Player ${players.find(p => p.alive)?.id || 0} WINS! 🎉`;
            document.getElementById('winner-text').style.color = '#ffeb3b';
        } else {
            document.getElementById('winner-text').innerHTML = '💀 All Players Eliminated! 💀';
            document.getElementById('winner-text').style.color = '#f44336';
        }
    }
}

