function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Camera
    const camera = {
        x: canvas.width / 2 - (players[0]?.x || 0),
        y: canvas.height / 2 - (players[0]?.y || 0)
    };

    ctx.save();
    ctx.translate(camera.x, camera.y);

    // Draw ground
    ctx.fillStyle = '#2d5a27';
    ctx.fillRect(0, 0, WORLD_SIZE, WORLD_SIZE);

    // Grid
    ctx.strokeStyle = 'rgba(255,255,255,0.05)';
    ctx.lineWidth = 1;
    for (let x = 0; x < WORLD_SIZE; x += TILE_SIZE) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, WORLD_SIZE);
        ctx.stroke();
    }
    for (let y = 0; y < WORLD_SIZE; y += TILE_SIZE) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(WORLD_SIZE, y);
        ctx.stroke();
    }

    // Draw buildings
    for (const b of buildings) {
        ctx.fillStyle = b.color;
        ctx.fillRect(b.x, b.y, b.w, b.h);
        ctx.strokeStyle = 'rgba(0,0,0,0.3)';
        ctx.lineWidth = 2;
        ctx.strokeRect(b.x, b.y, b.w, b.h);

        // Roof detail
        ctx.fillStyle = 'rgba(0,0,0,0.2)';
        ctx.fillRect(b.x + 5, b.y + 5, b.w - 10, b.h - 10);
    }

    // Draw zone
    ctx.beginPath();
    ctx.arc(zoneCenter.x, zoneCenter.y, zoneRadius, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(33, 150, 243, 0.8)';
    ctx.lineWidth = 3;
    ctx.stroke();

    // Zone damage area (outside circle)
    ctx.beginPath();
    ctx.rect(0, 0, WORLD_SIZE, WORLD_SIZE);
    ctx.arc(zoneCenter.x, zoneCenter.y, zoneRadius, 0, Math.PI * 2, true);
    ctx.fillStyle = 'rgba(33, 150, 243, 0.15)';
    ctx.fill();

    // Draw items
    const time = Date.now() / 1000;
    for (const item of items) {
        const bob = Math.sin(time * 3 + item.bobOffset) * 3;
        ctx.beginPath();
        ctx.arc(item.x, item.y + bob, item.radius, 0, Math.PI * 2);

        if (item.type.startsWith('weapon_')) {
            const wName = item.type.replace('weapon_', '');
            ctx.fillStyle = WEAPONS[wName].color;
        } else {
            switch (item.type) {
                case 'health': ctx.fillStyle = '#4caf50'; break;
                case 'armor': ctx.fillStyle = '#2196f3'; break;
                default: ctx.fillStyle = '#ff9800'; break;
            }
        }
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.stroke();

        // Item label
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        let label = '';
        if (item.type.startsWith('weapon_')) label = item.type.replace('weapon_', '').toUpperCase();
        else if (item.type === 'health') label = '❤️';
        else if (item.type === 'armor') label = '🛡️';
        else label = '📦';
        ctx.fillText(label, item.x, item.y + bob - 15);
    }

    // Draw bullets
    for (const b of bullets) {
        ctx.beginPath();
        ctx.arc(b.x, b.y, 3, 0, Math.PI * 2);
        ctx.fillStyle = b.color;
        ctx.fill();

        // Trail
        ctx.beginPath();
        ctx.moveTo(b.x, b.y);
        ctx.lineTo(b.x - b.vx * 2, b.y - b.vy * 2);
        ctx.strokeStyle = b.color + '80';
        ctx.lineWidth = 2;
        ctx.stroke();
    }

    // Draw particles
    for (const p of particles) {
        const alpha = p.life / p.maxLife;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * alpha, 0, Math.PI * 2);
        ctx.fillStyle = p.color + Math.floor(alpha * 255).toString(16).padStart(2, '0');
        ctx.fill();
    }

    // Draw bots
    for (const b of bots) {
        b.draw();
    }

    // Draw players
    for (const p of players) {
        p.draw();
    }

    // Draw reload indicator
    for (const p of players) {
        if (p.alive && p.isReloading) {
            const elapsed = Date.now() - p.reloadTime;
            const progress = Math.min(elapsed / 2000, 1);
            ctx.beginPath();
            ctx.arc(p.x, p.y - 35, 8, -Math.PI / 2, -Math.PI / 2 + progress * Math.PI * 2);
            ctx.strokeStyle = '#ffeb3b';
            ctx.lineWidth = 2;
            ctx.stroke();
        }
    }

    ctx.restore();

    // Draw minimap
    drawMinimap();
}

function drawMinimap() {
    minimapCtx.clearRect(0, 0, 180, 180);
    minimapCtx.fillStyle = 'rgba(0,0,0,0.8)';
    minimapCtx.fillRect(0, 0, 180, 180);

    const scale = 180 / WORLD_SIZE;

    // Zone on minimap
    minimapCtx.beginPath();
    minimapCtx.arc(zoneCenter.x * scale, zoneCenter.y * scale, zoneRadius * scale, 0, Math.PI * 2);
    minimapCtx.strokeStyle = 'rgba(33, 150, 243, 0.8)';
    minimapCtx.lineWidth = 1;
    minimapCtx.stroke();

    // Buildings on minimap
    minimapCtx.fillStyle = 'rgba(255,255,255,0.2)';
    for (const b of buildings) {
        minimapCtx.fillRect(b.x * scale, b.y * scale, b.w * scale, b.h * scale);
    }

    // Players on minimap
    for (const p of players) {
        if (!p.alive) continue;
        minimapCtx.beginPath();
        minimapCtx.arc(p.x * scale, p.y * scale, 3, 0, Math.PI * 2);
        minimapCtx.fillStyle = p.color;
        minimapCtx.fill();
    }

    // Bots on minimap
    for (const b of bots) {
        if (!b.alive) continue;
        minimapCtx.beginPath();
        minimapCtx.arc(b.x * scale, b.y * scale, 2, 0, Math.PI * 2);
        minimapCtx.fillStyle = '#f44336';
        minimapCtx.fill();
    }

    // Border
    minimapCtx.strokeStyle = 'rgba(255,255,255,0.3)';
    minimapCtx.lineWidth = 1;
    minimapCtx.strokeRect(0, 0, 180, 180);
}

function gameLoop() {
    update();
