}

// Main body
ctx.fillStyle = bodyGradient;
ctx.beginPath();
ctx.moveTo(-w / 2 + 5, -h / 2);
ctx.lineTo(w / 2 - 5, -h / 2);
ctx.lineTo(w / 2, -h / 4);
ctx.lineTo(w / 2, h / 4);
ctx.lineTo(w / 2 - 5, h / 2);
ctx.lineTo(-w / 2 + 5, h / 2);
ctx.lineTo(-w / 2, h / 4);
ctx.lineTo(-w / 2, -h / 4);
ctx.closePath();
ctx.fill();

// Roof
const roofGradient = ctx.createLinearGradient(0, -h / 4, 0, h / 4);
roofGradient.addColorStop(0, isPlayer ? '#0a0a1e' : '#222');
roofGradient.addColorStop(1, isPlayer ? '#1a1a3e' : '#333');
ctx.fillStyle = roofGradient;
ctx.beginPath();
ctx.moveTo(-w / 3, -h / 4);
ctx.lineTo(w / 3, -h / 4);
ctx.lineTo(w / 3 - 5, h / 6);
ctx.lineTo(-w / 3 + 5, h / 6);
ctx.closePath();
ctx.fill();

// Windshield
ctx.fillStyle = 'rgba(100, 150, 255, 0.3)';
ctx.beginPath();
ctx.moveTo(-w / 3 + 3, -h / 4 + 5);
ctx.lineTo(w / 3 - 3, -h / 4 + 5);
ctx.lineTo(w / 3 - 8, -h / 6);
ctx.lineTo(-w / 3 + 8, -h / 6);
ctx.closePath();
ctx.fill();

// Rear window
ctx.fillStyle = 'rgba(100, 150, 255, 0.2)';
ctx.beginPath();
ctx.moveTo(-w / 3 + 5, h / 6);
ctx.lineTo(w / 3 - 5, h / 6);
ctx.lineTo(w / 3 - 3, h / 4 - 5);
ctx.lineTo(-w / 3 + 3, h / 4 - 5);
ctx.closePath();
ctx.fill();

// Headlights (front)
if (isPlayer) {
ctx.shadowColor = '#ffffff';
ctx.shadowBlur = 20;
ctx.fillStyle = '#ffffff';
ctx.beginPath();
ctx.ellipse(-w / 3, -h / 2 + 5, 8, 4, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(w / 3, -h / 2 + 5, 8, 4, 0, 0, Math.PI * 2);
ctx.fill();
ctx.shadowBlur = 0;

// Headlight beams
ctx.fillStyle = 'rgba(255, 255, 200, 0.1)';
ctx.beginPath();
ctx.moveTo(-w / 3 - 10, -h / 2);
ctx.lineTo(-w / 3 + 10, -h / 2);
ctx.lineTo(-w / 3 + 30, -h / 2 - 100);
ctx.lineTo(-w / 3 - 30, -h / 2 - 100);
ctx.closePath();
ctx.fill();
ctx.beginPath();
ctx.moveTo(w / 3 - 10, -h / 2);
ctx.lineTo(w / 3 + 10, -h / 2);
ctx.lineTo(w / 3 + 30, -h / 2 - 100);
ctx.lineTo(w / 3 - 30, -h / 2 - 100);
ctx.closePath();
ctx.fill();
}

// Taillights (rear)
ctx.shadowColor = '#ff0000';
ctx.shadowBlur = 15;
ctx.fillStyle = '#ff0000';
ctx.beginPath();
ctx.ellipse(-w / 3, h / 2 - 5, 8, 3, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(w / 3, h / 2 - 5, 8, 3, 0, 0, Math.PI * 2);
ctx.fill();
ctx.shadowBlur = 0;

// BMW kidney grille
if (isPlayer) {
ctx.fillStyle = '#000';
ctx.fillRect(-8, -h / 2 + 10, 6, 12);
ctx.fillRect(2, -h / 2 + 10, 6, 12);
ctx.strokeStyle = '#ccc';
ctx.lineWidth = 1;
ctx.strokeRect(-8, -h / 2 + 10, 6, 12);
ctx.strokeRect(2, -h / 2 + 10, 6, 12);
}

// Side skirts
ctx.fillStyle = '#111';
ctx.fillRect(-w / 2 - 2, -h / 4, 4, h / 2);
ctx.fillRect(w / 2 - 2, -h / 4, 4, h / 2);

// Wheels
const wheelPositions = [
[-w / 2 - 3, -h / 3],
[w / 2 - 1, -h / 3],
[-w / 2 - 3, h / 3],
[w / 2 - 1, h / 3]
];

wheelPositions.forEach(([wx, wy]) => {
ctx.fillStyle = '#111';
ctx.beginPath();
ctx.arc(wx, wy, 8, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#333';
ctx.beginPath();
ctx.arc(wx, wy, 5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#666';
ctx.beginPath();
ctx.arc(wx, wy, 2, 0, Math.PI * 2);
ctx.fill();
});

// M stripe
if (isPlayer) {
ctx.fillStyle = '#0066ff';
ctx.fillRect(-w / 2 + 5, h / 2 - 15, 15, 3);
ctx.fillStyle = '#ff0000';
ctx.fillRect(-w / 2 + 5, h / 2 - 10, 15, 3);
ctx.fillStyle = '#ff6600';
ctx.fillRect(-w / 2 + 5, h / 2 - 5, 15, 3);
}

// Nitro flame
if (nitroActive && isPlayer) {
ctx.shadowColor = '#ff6600';
ctx.shadowBlur = 30;
const flameHeight = 20 + Math.random() * 30;
const flameGradient = ctx.createLinearGradient(0, h / 2, 0, h / 2 + flameHeight);
flameGradient.addColorStop(0, '#ffcc00');
flameGradient.addColorStop(0.5, '#ff6600');
flameGradient.addColorStop(1, 'rgba(255, 0, 0, 0)');
ctx.fillStyle = flameGradient;
ctx.beginPath();
ctx.moveTo(-10, h / 2);
ctx.lineTo(10, h / 2);
ctx.lineTo(5 + Math.random() * 5, h / 2 + flameHeight);
ctx.lineTo(-5 - Math.random() * 5, h / 2 + flameHeight);
ctx.closePath();
ctx.fill();
ctx.shadowBlur = 0;
}

ctx.restore();
}

function drawRain() {
ctx.strokeStyle = 'rgba(150, 180, 255, 0.3)';
ctx.lineWidth = 1;
rainDrops.forEach(drop => {
ctx.beginPath();
ctx.moveTo(drop.x, drop.y);
ctx.lineTo(drop.x - 2, drop.y + drop.length);
ctx.stroke();
drop.y += drop.speed;
drop.x -= 1;
if (drop.y > canvas.height) {
drop.y = -drop.length;
drop.x = Math.random() * canvas.width;
}
});
}

function drawParticles() {
particles.forEach(p => {
ctx.globalAlpha = p.life;
ctx.fillStyle = p.color;
ctx.beginPath();
ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
ctx.fill();
});
ctx.globalAlpha = 1;
}

function drawMinimap() {
minimapCtx.fillStyle = 'rgba(0, 0, 0, 0.8)';
minimapCtx.fillRect(0, 0, 150, 200);

// Road
minimapCtx.fillStyle = '#333';
minimapCtx.fillRect(50, 0, 50, 200);

// Player
minimapCtx.fillStyle = '#00ff00';
minimapCtx.fillRect(70, 150, 10, 15);

// Enemies
enemies.forEach(e => {
minimapCtx.fillStyle = '#ff0000';
minimapCtx.fillRect(65 + e.lane * 15, 100 + (e.y / canvas.height) * 100, 8, 12);
});

// Border
minimapCtx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
minimapCtx.lineWidth = 1;
minimapCtx.strokeRect(0, 0, 150, 200);
}

function update() {
if (!gameRunning) return;

// Acceleration
if (keys['ArrowUp'] || keys['w']) {
speed += 0.5;
} else if (keys['ArrowDown'] || keys['s']) {
speed -= 0.8;
} else {
speed -= 0.1;
}

// Nitro
if (keys[' '] && nitro > 0) {
nitroActive = true;
nitro -= 0.5;
speed += 1;
if (nitro <= 0) {
nitro = 0;
nitroActive = false;
}
} else {
nitroActive = false;
if (nitro < 100) nitro += 0.1;
}

// Speed limits
speed = Math.max(0, Math.min(speed, maxSpeed + (nitroActive ? 100 : 0)));

// Steering
if (keys['ArrowLeft'] || keys['a']) {
player.x -= 5;
player.tilt = -0.1;
} else if (keys['ArrowRight'] || keys['d']) {
player.x += 5;
player.tilt = 0.1;
} else {
player.tilt *= 0.9;
}

// Road boundaries
const roadLeft = canvas.width / 2 - 170;
const roadRight = canvas.width / 2 + 170;
player.x = Math.max(roadLeft + 30, Math.min(roadRight - 30, player.x));

// Score
score += Math.floor(speed * 0.1);

// Spawn enemies
if (Math.random() < 0.02 * difficulty) {
spawnEnemy();
}

// Update enemies
enemies.forEach((enemy, index) => {
enemy.y += enemy.speed + speed * 0.3;

// Collision detection
const dx = player.x - enemy.x;
const dy = player.y - enemy.y;
const dist = Math.sqrt(dx * dx + dy * dy);

if (dist < 40) {
gameRunning = false;
createParticle(player.x, player.y, 'explosion');
document.getElementById('final-score').textContent = score;
document.getElementById('game-over').style.display = 'block';
}

// Remove off-screen enemies
if (enemy.y > canvas.height + 100) {
enemies.splice(index, 1);
score += 50;
}
});

// Update particles
particles.forEach((p, index) => {
p.x += p.vx;
p.y += p.vy;
p.life -= p.decay;
if (p.life <= 0) {
particles.splice(index, 1);
}
});

// Exhaust particles
if (speed > 50 && Math.random() > 0.5) {
createParticle(
player.x + (Math.random() - 0.5) * 10,
player.y + 45,
'exhaust'
);
}

// Increase difficulty
difficulty = 1 + score / 5000;

// Update UI
document.getElementById('score').textContent = `SCORE: ${score}`;
document.getElementById('speed-text').textContent = Math.floor(speed);
document.getElementById('nitro-fill').style.width = `${nitro}%`;
}

function draw() {
ctx.clearRect(0, 0, canvas.width, canvas.height);

drawSky();
drawBuildings();
drawRoad();
drawRain();

// Draw enemies
enemies.forEach(enemy => {
drawBMW_M4(enemy.x, enemy.y, enemy.width, enemy.height, 0, 0, false);
});

// Draw player
drawBMW_M4(player.x, player.y, player.width, player.height, player.tilt, 0, true);

// Draw particles
drawParticles();

// Speed lines effect
if (speed > 200) {
const alpha = (speed - 200) / 200;
ctx.strokeStyle = `rgba(255, 255, 255, ${alpha * 0.3})`;
ctx.lineWidth = 1;
for (let i = 0; i < 10; i++) {
const x = Math.random() * canvas.width;
const y = Math.random() * canvas.height;
ctx.beginPath();
ctx.moveTo(x, y);
ctx.lineTo(x, y + 50 + speed * 0.5);
ctx.stroke();
}
}

// Vignette
const vignetteGradient = ctx.createRadialGradient(
canvas.width / 2, canvas.height / 2, canvas.height * 0.3,
canvas.width / 2, canvas.height / 2, canvas.height * 0.8
);
vignetteGradient.addColorStop(0, 'rgba(0,0,0,0)');
vignetteGradient.addColorStop(1, 'rgba(0,0,0,0.5)');
ctx.fillStyle = vignetteGradient;
ctx.fillRect(0, 0, canvas.width, canvas.height);

drawMinimap();
}

function gameLoop() {
if (!gameRunning) return;
update();
draw();
requestAnimationFrame(gameLoop);
}

// Initial draw
draw();
</script>
</body>
</html>

