        const canvas = document.getElementById('dartboard');
        const ctx = canvas.getContext('2d');
        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        const radius = 230;

        // Dartboard segment definitions (standard dartboard order)
        const segmentOrder = [20, 1, 18, 4, 13, 6, 10, 15, 2, 17, 3, 19, 7, 16, 8, 11, 14, 9, 12, 5];
        const segmentAngle = (2 * Math.PI) / 20;

        // Ring radii
        const outerDoubleRadius = radius;
        const innerDoubleRadius = radius * 0.95;
        const outerSingleRadius = radius * 0.95;
        const innerSingleRadius = radius * 0.35;
        const outerTripleRadius = radius * 0.55;
        const innerTripleRadius = radius * 0.49;
        const outerBullRadius = 16;
        const innerBullRadius = 6;

        let darts = [];
        let totalScore = 0;
        let currentRound = 1;
        let dartsInRound = 0;
        let maxDartsPerRound = 3;
        let maxRounds = 10;
        let highestScore = 0;
        let bullseyeCount = 0;
        let leaderboard = [];
        let gameActive = true;

        function drawDartboard() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw background circle
            ctx.beginPath();
            ctx.arc(centerX, centerY, radius + 10, 0, 2 * Math.PI);
            ctx.fillStyle = '#1a0a0a';
            ctx.fill();

            // Draw segments
            for (let i = 0; i < 20; i++) {
                const startAngle = i * segmentAngle - Math.PI / 2 - segmentAngle / 2;
                const endAngle = startAngle + segmentAngle;
                const value = segmentOrder[i];

                // Double ring (outer)
                ctx.beginPath();
                ctx.arc(centerX, centerY, outerDoubleRadius, startAngle, endAngle);
                ctx.arc(centerX, centerY, innerDoubleRadius, endAngle, startAngle, true);
                ctx.closePath();
                ctx.fillStyle = i % 2 === 0 ? '#8b0000' : '#f5e6d3';
                ctx.fill();
                ctx.strokeStyle = '#333';
                ctx.lineWidth = 1;
                ctx.stroke();

                // Single ring (outer)
                ctx.beginPath();
                ctx.arc(centerX, centerY, outerSingleRadius, startAngle, endAngle);
                ctx.arc(centerX, centerY, outerTripleRadius, endAngle, startAngle, true);
                ctx.closePath();
                ctx.fillStyle = i % 2 === 0 ? '#8b0000' : '#f5e6d3';
                ctx.fill();
                ctx.strokeStyle = '#333';
                ctx.lineWidth = 1;
                ctx.stroke();

                // Triple ring
                ctx.beginPath();
                ctx.arc(centerX, centerY, outerTripleRadius, startAngle, endAngle);
                ctx.arc(centerX, centerY, innerTripleRadius, endAngle, startAngle, true);
                ctx.closePath();
                ctx.fillStyle = i % 2 === 0 ? '#8b0000' : '#f5e6d3';
                ctx.fill();
                ctx.strokeStyle = '#333';
                ctx.lineWidth = 1;
                ctx.stroke();

                // Single ring (inner)
                ctx.beginPath();
                ctx.arc(centerX, centerY, innerTripleRadius, startAngle, endAngle);
                ctx.arc(centerX, centerY, innerSingleRadius, endAngle, startAngle, true);
                ctx.closePath();
                ctx.fillStyle = i % 2 === 0 ? '#8b0000' : '#f5e6d3';
                ctx.fill();
                ctx.strokeStyle = '#333';
                ctx.lineWidth = 1;
                ctx.stroke();

                // Draw segment numbers
                const numberRadius = radius * 1.08;
                const midAngle = startAngle + segmentAngle / 2;
                const numX = centerX + Math.cos(midAngle) * numberRadius;
                const numY = centerY + Math.sin(midAngle) * numberRadius;

                ctx.beginPath();
                ctx.arc(numX, numY, 15, 0, 2 * Math.PI);
                ctx.fillStyle = '#1a0a0a';
                ctx.fill();

                ctx.fillStyle = '#e8c4a0';
                ctx.font = 'bold 16px Georgia';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(value, numX, numY);
            }

            // Draw bullseye
            // Outer bull (25)
            ctx.beginPath();
            ctx.arc(centerX, centerY, outerBullRadius, 0, 2 * Math.PI);
            ctx.fillStyle = '#228b22';
            ctx.fill();
            ctx.strokeStyle = '#333';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Inner bull (50)
            ctx.beginPath();
            ctx.arc(centerX, centerY, innerBullRadius, 0, 2 * Math.PI);
            ctx.fillStyle = '#8b0000';
            ctx.fill();
            ctx.strokeStyle = '#333';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Draw wire lines
            ctx.strokeStyle = '#888';
            ctx.lineWidth = 0.5;
            for (let i = 0; i < 20; i++) {
                const angle = i * segmentAngle - Math.PI / 2 - segmentAngle / 2;
                ctx.beginPath();
                ctx.moveTo(centerX + Math.cos(angle) * innerSingleRadius, centerY + Math.sin(angle) * innerSingleRadius);
                ctx.lineTo(centerX + Math.cos(angle) * outerDoubleRadius, centerY + Math.sin(angle) * outerDoubleRadius);
                ctx.stroke();
            }

            // Draw circles
            [outerDoubleRadius, innerDoubleRadius, outerTripleRadius, innerTripleRadius, innerSingleRadius, outerBullRadius].forEach(r => {
                ctx.beginPath();
                ctx.arc(centerX, centerY, r, 0, 2 * Math.PI);
                ctx.strokeStyle = '#888';
                ctx.lineWidth = 1;
                ctx.stroke();
            });

            // Draw existing darts
            darts.forEach(dart => {
                drawDart(dart.x, dart.y, dart.score, dart.multiplier, dart.segment);
            });
        }

        function drawDart(x, y, score, multiplier, segment) {
            // Dart shadow
            ctx.beginPath();
            ctx.arc(x + 2, y + 2, 8, 0, 2 * Math.PI);
            ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
            ctx.fill();

            // Dart outer ring
            ctx.beginPath();
            ctx.arc(x, y, 8, 0, 2 * Math.PI);
            ctx.fillStyle = '#ffd700';
            ctx.fill();
            ctx.strokeStyle = '#b8860b';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Dart inner
            ctx.beginPath();
            ctx.arc(x, y, 4, 0, 2 * Math.PI);
            ctx.fillStyle = '#8b0000';
            ctx.fill();

            // Dart point
            ctx.beginPath();
            ctx.moveTo(x, y - 8);
            ctx.lineTo(x - 3, y - 15);
            ctx.lineTo(x + 3, y - 15);
            ctx.closePath();
            ctx.fillStyle = '#c0c0c0';
            ctx.fill();

            // Score label
            if (score > 0) {
                ctx.fillStyle = '#fff';
                ctx.font = 'bold 10px Georgia';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                const label = multiplier > 1 ? `${score}${multiplier}x` : score;
                ctx.fillText(label, x, y);
            }
        }

        function getSegmentInfo(x, y) {
            const dx = x - centerX;
            const dy = y - centerY;
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance > radius) {
                return { score: 0, multiplier: 0, segment: -1, ring: 'miss' };
            }

            // Calculate angle
            let angle = Math.atan2(dy, dx) + Math.PI / 2;
            if (angle < 0) angle += 2 * Math.PI;
            angle = angle % (2 * Math.PI);

            const segmentIndex = Math.floor(angle / segmentAngle);
            const segment = segmentOrder[segmentIndex % 20];

            // Determine ring
            let multiplier = 1;
            let ring = 'single';

            if (distance <= innerBullRadius) {
                return { score: 50, multiplier: 1, segment: segment, ring: 'bullseye' };
            } else if (distance <= outerBullRadius) {
                return { score: 25, multiplier: 1, segment: segment, ring: 'outer_bull' };
            } else if (distance <= innerDoubleRadius) {
                multiplier = 1;
                ring = 'single';
            } else if (distance <= innerTripleRadius) {
                multiplier = 3;
                ring = 'triple';
            } else if (distance <= outerTripleRadius) {
                multiplier = 1;
                ring = 'single';
            } else if (distance <= innerSingleRadius) {
                multiplier = 1;
                ring = 'single';
            } else if (distance <= outerDoubleRadius) {
                multiplier = 2;
                ring = 'double';
            }

            return { score: segment, multiplier: multiplier, segment: segment, ring: ring };
        }

        function throwDart() {
            if (!gameActive) return;
            if (dartsInRound >= maxDartsPerRound) {
                showMessage("Runde beendet! Nächste Runde startet...");
                setTimeout(() => {
                    currentRound++;
                    dartsInRound = 0;
                    if (currentRound > maxRounds) {
                        endGame();
                        return;
                    }
                    document.getElementById('currentRound').textContent = currentRound;
                    showMessage(`Runde ${currentRound} - Wirf deine 3 Darts!`);
                }, 1500);
                return;
            }

            // Add some randomness to make it more realistic
            const randomOffsetX = (Math.random() - 0.5) * 20;
            const randomOffsetY = (Math.random() - 0.5) * 20;

            // Random target position (biased towards center for realism)
            const angle = Math.random() * 2 * Math.PI;
            const dist = Math.random() * radius * 0.9;
            const targetX = centerX + Math.cos(angle) * dist + randomOffsetX;
            const targetY = centerY + Math.sin(angle) * dist + randomOffsetY;

            // Clamp to canvas
            const x = Math.max(10, Math.min(canvas.width - 10, targetX));
            const y = Math.max(10, Math.min(canvas.height - 10, targetY));

            const info = getSegmentInfo(x, y);
            const score = info.score * info.multiplier;

            darts.push({ x, y, score, multiplier: info.multiplier, segment: info.segment, ring: info.ring });
            dartsInRound++;

            totalScore += score;
            if (score > highestScore) highestScore = score;
            if (info.ring === 'bullseye') bullseyeCount++;

            // Update UI
            document.getElementById('totalScore').textContent = totalScore;
            document.getElementById('dartsThrown').textContent = darts.length;
            document.getElementById('highestScore').textContent = highestScore;
            document.getElementById('bullseyeCount').textContent = bullseyeCount;
            document.getElementById('average').textContent = darts.length > 0 ? Math.round(totalScore / darts.length) : 0;

            // Add to history
            addHistory(currentRound, score);

            // Show message
            let ringName = '';
            switch (info.ring) {
                case 'bullseye': ringName = '🎯 BULLSEYE!'; break;
                case 'outer_bull': ringName = '🔵 Outer Bull'; break;
                case 'triple': ringName = '🔥 TRIPLE!'; break;
                case 'double': ringName = '⭐ DOUBLE!'; break;
                case 'miss': ringName = '❌ Verpasst!'; break;
                default: ringName = '';
            }

            if (score > 0) {
                showMessage(`${ringName} +${score} Punkte!`);
                showScorePopup(x, y, `+${score}`);
            } else {
                showMessage('❌ Verpasst das Dartboard!');
            }

            // Redraw
            drawDartboard();

            // Check if round is complete
            if (dartsInRound >= maxDartsPerRound) {
                setTimeout(() => {
                    currentRound++;
                    dartsInRound = 0;
                    if (currentRound > maxRounds) {
                        endGame();
                        return;
                    }
                    document.getElementById('currentRound').textContent = currentRound;
                    showMessage(`Runde ${currentRound} - Wirf deine 3 Darts!`);
                }, 1500);
            }
        }

        function showScorePopup(x, y, text) {
            const popup = document.createElement('div');
            popup.className = 'score-popup';
            popup.textContent = text;
            popup.style.left = x + 'px';
            popup.style.top = y + 'px';
            document.querySelector('.dartboard-container').appendChild(popup);
            setTimeout(() => popup.remove(), 1500);
        }

        function addHistory(round, score) {
            const history = document.getElementById('history');
            const item = document.createElement('div');
            item.className = 'history-item';
            item.innerHTML = `
                <span class="history-round">Runde ${round}</span>
                <span class="history-score">+${score}</span>
                <span class="history-total">Gesamt: ${totalScore}</span>
            `;
            history.insertBefore(item, history.firstChild);
        }

        function showMessage(text) {
            document.getElementById('message').textContent = text;
        }

        function resetGame() {
            darts = [];
            totalScore = 0;
            currentRound = 1;
            dartsInRound = 0;
            highestScore = 0;
            bullseyeCount = 0;
            gameActive = true;

            document.getElementById('totalScore').textContent = '0';
            document.getElementById('currentRound').textContent = '1';
            document.getElementById('dartsThrown').textContent = '0';
            document.getElementById('average').textContent = '0';
            document.getElementById('highestScore').textContent = '0';
            document.getElementById('bullseyeCount').textContent = '0';
            document.getElementById('history').innerHTML = '<div class="history-item" style="color: #666; justify-content: center;">Noch keine Würfe</div>';
            showMessage('Neues Spiel! Wirf deine Darts!');

            drawDartboard();
        }

        function clearDarts() {
            darts = [];
            drawDartboard();
            showMessage('Darts entfernt!');
        }

        function endGame() {
            gameActive = false;
            showMessage(`🏆 Spiel beendet! Endscore: ${totalScore} Punkte!`);

            // Add to leaderboard
            leaderboard.push(totalScore);
            leaderboard.sort((a, b) => b - a);
            leaderboard = leaderboard.slice(0, 3);

            updateLeaderboard();
        }

        function updateLeaderboard() {
            const lb = document.getElementById('leaderboard');
            lb.innerHTML = '';
            for (let i = 0; i < 3; i++) {
                const item = document.createElement('div');
                item.className = 'leaderboard-item';
                item.innerHTML = `
                    <span class="lb-name">Platz ${i + 1}</span>
                    <span class="lb-score">${leaderboard[i] !== undefined ? leaderboard[i] : '-'}</span>
                `;
                lb.appendChild(item);
            }
        }

        // Canvas click handler
        canvas.addEventListener('click', function (e) {
            const rect = canvas.getBoundingClientRect();
            const scaleX = canvas.width / rect.width;
            const scaleY = canvas.height / rect.height;
            const x = (e.clientX - rect.left) * scaleX;
            const y = (e.clientY - rect.top) * scaleY;

            // Check if click is within dartboard
            const dx = x - centerX;
            const dy = y - centerY;
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance <= radius) {
                throwDart();
            } else {
                showMessage('❌ Du hast außerhalb des Dartboards geklickt!');
            }
        });

        // Keyboard handler
        document.addEventListener('keydown', function (e) {
            if (e.code === 'Space' || e.code === 'Enter') {
                e.preventDefault();
                throwDart();
            }
        });

        // Initialize
        drawDartboard();
        showMessage('Willkommen beim Wein Dart Game! 🍷');
    </script>
</body>
</html>

The user wants a puzzle game that uses a photo from the gallery (device photo library). I'll create a sliding puzzle game where the user can upload a photo from their device, and then the photo gets sliced into a grid that they need to rearrange by sliding tiles into the correct position.

Let me design a complete, polished puzzle game with:
1. Photo upload functionality (from gallery/device)
2. Grid-based sliding puzzle mechanics
3. Visual feedback and animations
4. Move counter and timer
5. Difficulty levels (3x3, 4x4, 5x5)
6. Win detection
7. Nice UI/UX with CSS styling

I'll use CSS background-image to display parts of the uploaded photo on each tile, and implement the classic sliding puzzle mechanics.
