<script>
const photoInput = document.getElementById('photoInput');
const uploadSection = document.getElementById('uploadSection');
const gameContainer = document.getElementById('gameContainer');
const tilesContainer = document.getElementById('tilesContainer');
const moveCountEl = document.getElementById('moveCount');
const timerEl = document.getElementById('timer');
const gridSizeEl = document.getElementById('gridSize');
const previewImage = document.getElementById('previewImage');
const winOverlay = document.getElementById('winOverlay');
const winMoves = document.getElementById('winMoves');
const winTime = document.getElementById('winTime');
const shuffleBtn = document.getElementById('shuffleBtn');
const resetBtn = document.getElementById('resetBtn');
const changePhotoBtn = document.getElementById('changePhotoBtn');
const playAgainBtn = document.getElementById('playAgainBtn');
const difficultyBtns = document.querySelectorAll('.difficulty-btn');

let gridSize = 3;
let tiles = [];
let emptyIndex = 0;
let moves = 0;
let timer = null;
let seconds = 0;
let gameStarted = false;
let photoSrc = '';
let boardSize = 400;

// Handle photo upload
photoInput.addEventListener('change', function(e) {
  const file = e.target.files[0];
  if (file) {
    const reader = new FileReader();
    reader.onload = function(event) {
      photoSrc = event.target.result;
      previewImage.src = photoSrc;
      uploadSection.style.display = 'none';
      gameContainer.classList.add('visible');
      initGame();
    };
    reader.readAsDataURL(file);
  }
});

// Difficulty selection
difficultyBtns.forEach(btn => {
  btn.addEventListener('click', function() {
    difficultyBtns.forEach(b => b.classList.remove('active'));
    this.classList.add('active');
    gridSize = parseInt(this.dataset.size);
    if (photoSrc) {
      initGame();
    }
  });
});

// Shuffle button
shuffleBtn.addEventListener('click', shuffle Puzzle);

// Reset button
resetBtn.addEventListener('click', resetGame);

// Change photo button
changePhotoBtn.addEventListener('click', function() {
  gameContainer.classList.remove('visible');
  uploadSection.style.display = 'flex';
  photoInput.value = '';
  photoSrc = '';
  previewImage.src = '';
  stopTimer();
  moves = 0;
  seconds = 0;
  moveCountEl.textContent = '0';
  timerEl.textContent = '00:00';
});

// Play again button
playAgainBtn.addEventListener('click', function() {
  winOverlay.classList.remove('visible');
  shufflePuzzle();
});

function initGame() {
  stopTimer();
  moves = 0;
  seconds = 0;
  gameStarted = false;
  moveCountEl.textContent = '0';
  timerEl.textContent = '00:00';
  gridSizeEl.textContent = `${gridSize}×${gridSize}`;

  // Adjust board size for mobile
  if (window.innerWidth <= 500) {
    boardSize = 320;
  } else {
    boardSize = 400;
  }

  tilesContainer.style.width = boardSize + 'px';
  tilesContainer.style.height = boardSize + 'px';

  createTiles();
  shufflePuzzle();
}

function createTiles() {
  tilesContainer.innerHTML = '';
  tiles = [];
  const totalTiles = gridSize * gridSize;
  const tileSize = boardSize / gridSize;

  for (let i = 0; i < totalTiles; i++) {
    const tile = document.createElement('div');
    tile.className = 'tile';
    tile.style.width = tileSize + 'px';
    tile.style.height = tileSize + 'px';

    const row = Math.floor(i / gridSize);
    const col = i % gridSize;

    // Calculate background position
    const bgX = (col / (gridSize - 1)) * 100;
    const bgY = (row / (gridSize - 1)) * 100;

    tile.style.backgroundImage = `url(${photoSrc})`;
    tile.style.backgroundSize = `${boardSize}px ${boardSize}px`;
    tile.style.backgroundPosition = `${bgX}% ${bgY}%`;
    tile.style.left = (col * tileSize) + 'px';
    tile.style.top = (row * tileSize) + 'px';
    tile.dataset.index = i;
    tile.dataset.correctIndex = i;

    // Add number overlay for harder difficulties
    if (gridSize >= 4) {
      tile.textContent = i + 1;
      tile.style.fontSize = (tileSize / 5) + 'px';
    }

    tile.addEventListener('click', () => handleTileClick(i));
    tilesContainer.appendChild(tile);
    tiles.push(tile);
  }

  // Set empty tile (last tile)
  emptyIndex = totalTiles - 1;
  tiles[emptyIndex].classList.add('empty');
  tiles[emptyIndex].textContent = '';
}

function handleTileClick(originalIndex) {
  if (!gameStarted) {
    gameStarted = true;
    startTimer();
  }

  // Find current position of the clicked tile
  const currentPos = tiles.findIndex(t => parseInt(t.dataset.correctIndex) === originalIndex);

  if (currentPos === -1) return;

  // Check if adjacent to empty tile
  if (isAdjacent(currentPos, emptyIndex)) {
    swapTiles(currentPos, emptyIndex);
    moves++;
    moveCountEl.textContent = moves;

    // Check win
    if (checkWin()) {
      setTimeout(() => showWin(), 300);
    }
  }
}

function isAdjacent(pos1, pos2) {
  const row1 = Math.floor(pos1 / gridSize);
  const col1 = pos1 % gridSize;
  const row2 = Math.floor(pos2 / gridSize);
  const col2 = pos2 % gridSize;

  return (Math.abs(row1 - row2) + Math.abs(col1 - col2)) === 1;
}

function swapTiles(pos1, pos2) {
  const tile1 = tiles[pos1];
  const tile2 = tiles[pos2];

  const tileSize = boardSize / gridSize;

  // Swap positions
  const tempRow1 = Math.floor(pos1 / gridSize);
  const tempCol1 = pos1 % gridSize;
  const tempRow2 = Math.floor(pos2 / gridSize);
  const tempCol2 = pos2 % gridSize;

  tile1.style.left = (tempCol2 * tileSize) + 'px';
  tile1.style.top = (tempRow2 * tileSize) + 'px';
  tile2.style.left = (tempCol1 * tileSize) + 'px';
  tile2.style.top = (tempRow1 * tileSize) + 'px';

  // Swap in array
  tiles[pos1] = tile2;
  tiles[pos2] = tile1;

  // Update empty index
  if (pos1 === emptyIndex) {
    emptyIndex = pos2;
  } else if (pos2 === emptyIndex) {
    emptyIndex = pos1;
  }

  // Update classes
  tile1.classList.toggle('empty');
  tile2.classList.toggle('empty');

  // Add moving animation
  tile1.classList.add('moving');
  tile2.classList.add('moving');
  setTimeout(() => {
    tile1.classList.remove('moving');
    tile2.classList.remove('moving');
  }, 200);

  // Check if tiles are in correct position
  updateCorrectIndicators();
}

function updateCorrectIndicators() {
  tiles.forEach((tile, index) => {
    if (!tile.classList.contains('empty')) {
      if (parseInt(tile.dataset.correctIndex) === index) {
        tile.classList.add('correct');
      } else {
        tile.classList.remove('correct');
      }
    }
  });
}

function shufflePuzzle() {
  // Reset to solved state first
  createTiles();

  // Perform random valid moves to shuffle
  const totalMoves = gridSize * gridSize * 20;
  let lastPos = -1;

  for (let i = 0; i < totalMoves; i++) {
    const adjacentPositions = getAdjacentPositions(emptyIndex);
    // Avoid undoing the last move
    const filtered = adjacentPositions.filter(pos => pos !== lastPos);
    const randomPos = filtered[Math.floor(Math.random() * filtered.length)];

    lastPos = emptyIndex;
    swapTiles(randomPos, emptyIndex);
  }

  moves = 0;
  moveCountEl.textContent = '0';
  stopTimer();
  seconds = 0;
  timerEl.textContent = '00:00';
  gameStarted = false;

  updateCorrectIndicators();
}

function getAdjacentPositions(pos) {
  const row = Math.floor(pos / gridSize);
  const col = pos % gridSize;
  const adjacent = [];

  if (row > 0) adjacent.push(pos - gridSize); // up
  if (row < gridSize - 1) adjacent.push(pos + gridSize); // down
  if (col > 0) adjacent.push(pos - 1); // left
  if (col < gridSize - 1) adjacent.push(pos + 1); // right

  return adjacent;
}

function checkWin() {
  for (let i = 0; i < tiles.length; i++) {
    if (parseInt(tiles[i].dataset.correctIndex) !== i) {
      return false;
    }
  }
  return true;
}

function showWin() {
  stopTimer();
  winMoves.textContent = moves;
  winTime.textContent = formatTime(seconds);
  winOverlay.classList.add('visible');
  createConfetti();
}

function createConfetti() {
  const colors = ['#f093fb', '#f5576c', '#667eea', '#4facfe', '#00f2fe', '#43e97b', '#fa709a', '#fee140'];

  for (let i = 0; i < 50; i++) {
    const confetti = document.createElement('div');
    confetti.className = 'confetti';
    confetti.style.left = Math.random() * 100 + 'vw';
    confetti.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
    confetti.style.animationDuration = (Math.random() * 2 + 2) + 's';
    confetti.style.animationDelay = Math.random() * 2 + 's';
    confetti.style.width = (Math.random() * 8 + 5) + 'px';
    confetti.style.height = (Math.random() * 8 + 5) + 'px';
    document.body.appendChild(confetti);

    setTimeout(() => confetti.remove(), 4000);
  }
}

function startTimer() {
  stopTimer();
  timer = setInterval(() => {
    seconds++;
    timerEl.textContent = formatTime(seconds);
  }, 1000);
}

function stopTimer() {
  if (timer) {
    clearInterval(timer);
    timer = null;
  }
}

function formatTime(sec) {
  const minutes = Math.floor(sec / 60);
  const remainingSeconds = sec % 60;
  return `${String(minutes).padStart(2, '0')}:${String(remainingSeconds).padStart(2, '0')}`;
}

function resetGame() {
  stopTimer();
  moves = 0;
  seconds = 0;
  gameStarted = false;
  moveCountEl.textContent = '0';
  timerEl.textContent = '00:00';
  createTiles();
  updateCorrectIndicators();
}

// Handle window resize
window.addEventListener('resize', () => {
  if (photoSrc && gameContainer.classList.contains('visible')) {
    if (window.innerWidth <= 500) {
      boardSize = 320;
    } else {
      boardSize = 400;
    }
    tilesContainer.style.width = boardSize + 'px';
    tilesContainer.style.height = boardSize + 'px';

    const tileSize = boardSize / gridSize;
    tiles.forEach((tile, index) => {
      tile.style.width = tileSize + 'px';
      tile.style.height = tileSize + 'px';
      tile.style.backgroundSize = `${boardSize}px ${boardSize}px`;

      const row = Math.floor(index / gridSize);
      const col = index % gridSize;
      tile.style.left = (col * tileSize) + 'px';
      tile.style.top = (row * tileSize) + 'px';
    });
  }
});
</script>

