  }

  .no-moves-overlay h2 {
    color: #fff;
    font-size: 1.8rem;
    margin-bottom: 10px;
  }

  .no-moves-overlay p {
    color: rgba(255,255,255,0.7);
    margin-bottom: 20px;
  }

  .hint-highlight {
    animation: hintPulse 0.5s ease infinite;
  }

  @keyframes hintPulse {
    0%, 100% { box-shadow: 0 0 0 3px #ffe259, 0 0 15px rgba(255,226,89,0.5); }
    50% { box-shadow: 0 0 0 5px #ffe259, 0 0 25px rgba(255,226,89,0.8); }
  }

  @media (max-width: 400px) {
    .board {
      gap: 2px;
