    }
  }

  .bg-candy {
    position: fixed;
    width: 60px;
    height: 60px;
    border-radius: 50%;
    opacity: 0.05;
    pointer-events: none;
    animation: floatCandy 20s ease-in-out infinite;
  }

  @keyframes floatCandy {
    0%, 100% { transform: translateY(0) rotate(0deg); }
    25% { transform: translateY(-30px) rotate(90deg); }
    50% { transform: translateY(0) rotate(180deg); }
    75% { transform: translateY(30px) rotate(270deg); }
  }
</style>
</head>
<body>

<div class="bg-candy" style="top:10%;left:5%;background:#e74c3c;animation-delay:0s;"></div>
<div class="bg-candy" style="top:60%;left:85%;background:#f39c12;animation-delay:-5s;"></div>
<div class="bg-candy" style="top:30%;left:70%;background:#27ae60;animation-delay:-10s;"></div>
<div class="bg-candy" style="top:80%;left:20%;background:#2980b9;animation-delay:-15s;"></div>

<div class="game-container">
  <div class="header">
    <div class="title">🍬 Candy Crush</div>
    <div class="score-board">
      <div class="score-item">
        <div class="score-label">Score</div>
        <div class="score-value" id="score">0</div>
      </div>
      <div class="score-item">
        <div class="score-label">Moves</div>
        <div class="score-value" id="moves">30</div>
      </div>
    </div>
  </div>

  <div class="board-wrapper">
    <div class="board" id="board"></div>
  </div>

  <div class="moves-display">
    Match 3 or more candies to score! <span id="combo-display"></span>
  </div>

  <button class="btn btn-primary" onclick="resetGame()">🔄 New Game</button>
</div>

<div class="particles-container" id="particles"></div>

<script>
const ROWS = 8;
const COLS = 8;
const CANDY_TYPES = 6;
const INITIAL_MOVES = 30;

let board = [];
let selectedCell = null;
let score = 0;
let moves = INITIAL_MOVES;
let isProcessing = false;
let combo = 0;

const boardEl = document.getElementById('board');
const scoreEl = document.getElementById('score');
const movesEl = document.getElementById('moves');
const particlesEl = document.getElementById('particles');
const comboDisplayEl = document.getElementById('combo-display');

function init() {
  board = [];
  for (let r = 0; r < ROWS; r++) {
    board[r] = [];
    for (let c = 0; c < COLS; c++) {
      let type;
      do {
        type = Math.floor(Math.random() * CANDY_TYPES);
      } while (
        (c >= 2 && board[r][c-1] === type && board[r][c-2] === type) ||
        (r >= 2 && board[r-1][c] === type && board[r-2][c] === type)
      );
      board[r][c] = type;
    }
  }
  score = 0;
  moves = INITIAL_MOVES;
  combo = 0;
  selectedCell = null;
  isProcessing = false;
  updateUI();
  renderBoard();
}

function renderBoard() {
  boardEl.innerHTML = '';
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.dataset.row = r;
      cell.dataset.col = c;

      if (board[r][c] !== -1) {
        const candy = document.createElement('div');
        candy.className = `candy candy-${board[r][c]}`;
        cell.appendChild(candy);
      }

      cell.addEventListener('click', () => handleCellClick(r, c));
      cell.addEventListener('touchstart', (e) => {
        e.preventDefault();
        handleCellClick(r, c);
      }, { passive: false });

      boardEl.appendChild(cell);
    }
  }
}

function getCellEl(r, c) {
  return boardEl.children[r * COLS + c];
}

function handleCellClick(r, c) {
  if (isProcessing) return;
  if (moves <= 0) return;

  if (!selectedCell) {
    selectedCell = { r, c };
    getCellEl(r, c).classList.add('selected');
  } else {
    const prev = selectedCell;
    getCellEl(prev.r, prev.c).classList.remove('selected');

    const dr = Math.abs(prev.r - r);
    const dc = Math.abs(prev.c - c);

    if ((dr === 1 && dc === 0) || (dr === 0 && dc === 1)) {
      trySwap(prev.r, prev.c, r, c);
    } else {
      selectedCell = { r, c };
      getCellEl(r, c).classList.add('selected');
      return;
    }
    selectedCell = null;
  }
}

async function trySwap(r1, c1, r2, c2) {
  isProcessing = true;

  // Swap in data
  [board[r1][c1], board[r2][c2]] = [board[r2][c2], board[r1][c1]];

  // Animate swap
  await animateSwap(r1, c1, r2, c2);

  // Check for matches
  const matches = findMatches();
  if (matches.length > 0) {
    moves--;
    updateUI();
    combo = 0;
    await processMatches();
  } else {
    // Swap back
    [board[r1][c1], board[r2][c2]] = [board[r2][c2], board[r1][c1]];
    await animateSwap(r1, c1, r2, c2);
  }

  // Check if any moves available
  if (!hasAvailableMoves() && moves > 0) {
    await shuffleBoard();
  }

  if (moves <= 0) {
    setTimeout(() => {
      alert(`Game Over! Final Score: ${score}`);
    }, 500);
  }

  isProcessing = false;
}

function animateSwap(r1, c1, r2, c2) {
  return new Promise(resolve => {
    const cell1 = getCellEl(r1, c1);
    const cell2 = getCellEl(r2, c2);

    const rect1 = cell1.getBoundingClientRect();
    const rect2 = cell2.getBoundingClientRect();

    const dx = rect2.left - rect1.left;
    const dy = rect2.top - rect1.top;

    cell1.style.transition = 'transform 0.25s ease-in-out';
    cell2.style.transition = 'transform 0.25s ease-in-out';
    cell1.style.zIndex = '10';
    cell2.style.zIndex = '10';

    cell1.style.transform = `translate(${dx}px, ${dy}px)`;
    cell2.style.transform = `translate(${-dx}px, ${-dy}px)`;

    setTimeout(() => {
      cell1.style.transition = '';
      cell2.style.transition = '';
      cell1.style.zIndex = '';
      cell2.style.zIndex = '';
      cell1.style.transform = '';
      cell2.style.transform = '';
      renderBoard();
      resolve();
    }, 260);
  });
}

function findMatches() {
  const matches = [];

  // Horizontal
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS - 2; c++) {
      if (board[r][c] !== -1 && board[r][c] === board[r][c+1] && board[r][c] === board[r][c+2]) {
        let matchLen = 3;
        while (c + matchLen < COLS && board[r][c + matchLen] === board[r][c]) {
          matchLen++;
        }
        for (let i = 0; i < matchLen; i++) {
          matches.push({ r, c: c + i });
        }
        c += matchLen - 1;
      }
    }
  }

  // Vertical
  for (let c = 0; c < COLS; c++) {
    for (let r = 0; r < ROWS - 2; r++) {
      if (board[r][c] !== -1 && board[r][c] === board[r+1][c] && board[r][c] === board[r+2][c]) {
        let matchLen = 3;
        while (r + matchLen < ROWS && board[r + matchLen][c] === board[r][c]) {
          matchLen++;
        }
        for (let i = 0; i < matchLen; i++) {
          matches.push({ r: r + i, c });
        }
        r += matchLen - 1;
      }
    }
  }

  // Deduplicate
  const unique = [];
  const seen = new Set();
  for (const m of matches) {
    const key = `${m.r},${m.c}`;
    if (!seen.has(key)) {
      seen.add(key);
      unique.push(m);
    }
  }

  return unique;
}

async function processMatches() {
  let matches = findMatches();

  while (matches.length > 0) {
    combo++;
    const matchScore = matches.length * 10 * combo;
    score += matchScore;
    updateUI();

    if (combo > 1) {
      showCombo(combo);
    }

    // Show score popup at center of matches
    showScorePopup(matches, matchScore);

    // Animate matched candies
    for (const m of matches) {
      const cell = getCellEl(m.r, m.c);
      cell.classList.add('matched');
      spawnParticles(m.r, m.c, board[m.r][m.c]);
    }

    await delay(400);

    // Remove matched candies
    for (const m of matches) {
      board[m.r][m.c] = -1;
    }

    // Apply gravity
    await applyGravity();

    // Fill empty spaces
    await fillEmpty();

    matches = findMatches();
  }
}

async function applyGravity() {
  let moved = false;

  for (let c = 0; c < COLS; c++) {
    let emptyRow = ROWS - 1;
    for (let r = ROWS - 1; r >= 0; r--) {
      if (board[r][c] !== -1) {
        if (r !== emptyRow) {
          board[emptyRow][c] = board[r][c];
          board[r][c] = -1;
          moved = true;
        }
        emptyRow--;
      }
    }
  }

  if (moved) {
    renderBoard();
    await delay(300);
  }
}

async function fillEmpty() {
  let filled = false;

  for (let c = 0; c < COLS; c++) {
    for (let r = 0; r < ROWS; r++) {
      if (board[r][c] === -1) {
        board[r][c] = Math.floor(Math.random() * CANDY_TYPES);
        filled = true;
        const cell = getCellEl(r, c);
        cell.classList.add('falling');
        const candy = document.createElement('div');
        candy.className = `candy candy-${board[r][c]}`;
        cell.appendChild(candy);
      }
    }
  }

  if (filled) {
    await delay(350);
    renderBoard();
  }
}

function hasAvailableMoves() {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      // Try swap right
      if (c < COLS - 1) {
        [board[r][c], board[r][c+1]] = [board[r][c+1], board[r][c]];
        if (findMatches().length > 0) {
          [board[r][c], board[r][c+1]] = [board[r][c+1], board[r][c]];
          return true;
        }
        [board[r][c], board[r][c+1]] = [board[r][c+1], board[r][c]];
      }
      // Try swap down
      if (r < ROWS - 1) {
        [board[r][c], board[r+1][c]] = [board[r+1][c], board[r][c]];
        if (findMatches().length > 0) {
          [board[r][c], board[r+1][c]] = [board[r+1][c], board[r][c]];
          return true;
        }
        [board[r][c], board[r+1][c]] = [board[r+1][c], board[r][c]];
      }
    }
  }
  return false;
}

async function shuffleBoard() {
  // Simple shuffle: reset board
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      board[r][c] = Math.floor(Math.random() * CANDY_TYPES);
    }
  }

  // Remove initial matches
  let matches = findMatches();
  while (matches.length > 0) {
    for (const m of matches) {
      board[m.r][m.c] = Math.floor(Math.random() * CANDY_TYPES);
    }
    matches = findMatches();
  }

  renderBoard();
  showComboText('Shuffled!');
}

function showParticles(r, c, type) {
  const cell = getCellEl(r, c);
  const rect = cell.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;

  const colors = ['#e74c3c', '#f39c12', '#27ae60', '#2980b9', '#8e44ad', '#e84393'];
  const color = colors[type] || '#fff';

  for (let i = 0; i < 8; i++) {
    const particle = document.createElement('div');
    particle.className = 'particle';
    particle.style.left = cx + 'px';
    particle.style.top = cy + 'px';
    particle.style.background = color;
    particle.style.setProperty('--tx', (Math.random() - 0.5) * 100 + 'px');
    particle.style.setProperty('--ty', (Math.random() - 0.5) * 100 + 'px');
    particle.style.width = (4 + Math.random() * 6) + 'px';
    particle.style.height = particle.style.width;
    particlesEl.appendChild(particle);

    setTimeout(() => particle.remove(), 800);
  }
}

function spawnParticles(r, c, type) {
  showParticles(r, c, type);
}

function showScorePopup(matches, points) {
  if (matches.length === 0) return;

  const avgR = matches.reduce((s, m) => s + m.r, 0) / matches.length;
  const avgC = matches.reduce((s, m) => s + m.c, 0) / matches.length;

  const cell = getCellEl(Math.round(avgR), Math.round(avgC));
  const rect = cell.getBoundingClientRect();
  const boardRect = boardEl.getBoundingClientRect();

  const popup = document.createElement('div');
  popup.className = 'score-popup';
  popup.textContent = `+${points}`;
  popup.style.left = (rect.left - boardRect.left + rect.width / 2) + 'px';
  popup.style.top = (rect.top - boardRect.top) + 'px';
  boardEl.appendChild(popup);

  setTimeout(() => popup.remove(), 1000);
}

function showCombo(comboCount) {
  const text = document.createElement('div');
  text.className = 'combo-text';
  text.textContent = `${comboCount}x Combo!`;
  boardEl.appendChild(text);
  setTimeout(() => text.remove(), 1000);
}

function showComboText(text) {
  const el = document.createElement('div');
  el.className = 'combo-text';
  el.textContent = text;
  boardEl.appendChild(el);
  setTimeout(() => el.remove(), 1000);
}

function updateUI() {
  scoreEl.textContent = score;
  movesEl.textContent = moves;
  comboDisplayEl.textContent = combo > 1 ? `🔥 ${combo}x Combo` : '';
}

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function resetGame() {
  init();
}

// Initialize game
init();
</script>
