<button class="btn" onclick="initGame()">🔄 New Game</button>

<script>
  const gridSize = 4;
  const totalTiles = gridSize * gridSize;
  let tiles = [];
  let moves = 0;
  let timerInterval = null;
  let seconds = 0;
  let gameStarted = false;

  function initGame() {
    moves = 0;
    seconds = 0;
    gameStarted = false;
    document.getElementById('moves').textContent = '0';
    document.getElementById('timer').textContent = '0:00';
    document.getElementById('winOverlay').classList.remove('show');
    clearInterval(timerInterval);

    // Create solved array then shuffle
    tiles = Array.from({ length: totalTiles }, (_, i) => i);
    tiles[totalTiles - 1] = 0; // 0 represents empty

    // Shuffle by making random valid moves
    let emptyIdx = totalTiles - 1;
    for (let i = 0; i < 200; i++) {
      const neighbors = getNeighbors(emptyIdx);
      const randomNeighbor = neighbors[Math.floor(Math.random() * neighbors.length)];
      [tiles[emptyIdx], tiles[randomNeighbor]] = [tiles[randomNeighbor], tiles[emptyIdx]];
      emptyIdx = randomNeighbor;
    }

    renderGrid();
  }

  function getNeighbors(idx) {
    const row = Math.floor(idx / gridSize);
    const col = idx % gridSize;
    const neighbors = [];
    if (row > 0) neighbors.push(idx - gridSize);
    if (row < gridSize - 1) neighbors.push(idx + gridSize);
    if (col > 0) neighbors.push(idx - 1);
    if (col < gridSize - 1) neighbors.push(idx + 1);
    return neighbors;
  }

  function renderGrid() {
    const grid = document.getElementById('grid');
    grid.innerHTML = '';

    tiles.forEach((val, idx) => {
      const tile = document.createElement('div');
      tile.className = 'tile' + (val === 0 ? ' empty' : '');
      tile.draggable = val !== 0;
      tile.dataset.index = idx;

      if (val !== 0) {
        tile.textContent = val;
        tile.classList.add('correct');

        // Check if tile is in correct position
        if (val !== idx + 1) {
          tile.classList.remove('correct');
        }

        tile.addEventListener('dragstart', handleDragStart);
        tile.addEventListener('dragend', handleDragEnd);
        tile.addEventListener('dragover', handleDragOver);
        tile.addEventListener('drop', handleDrop);
        tile.addEventListener('dragenter', handleDragEnter);
        tile.addEventListener('dragleave', handleDragLeave);

        // Touch support
        tile.addEventListener('touchstart', handleTouchStart, { passive: false });
        tile.addEventListener('touchmove', handleTouchMove, { passive: false });
        tile.addEventListener('touchend', handleTouchEnd, { passive: false });
      }

      grid.appendChild(tile);
    });
  }

  let draggedIndex = null;

  function handleDragStart(e) {
    draggedIndex = parseInt(this.dataset.index);
    this.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', draggedIndex);

    if (!gameStarted) {
      gameStarted = true;
      startTimer();
    }
  }

  function handleDragEnd(e) {
    this.classList.remove('dragging');
    document.querySelectorAll('.tile').forEach(t => t.classList.remove('drag-over'));
  }

  function handleDragOver(e) {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  }

  function handleDragEnter(e) {
    e.preventDefault();
    if (!this.classList.contains('empty')) {
      this.classList.add('drag-over');
    }
  }

  function handleDragLeave(e) {
    this.classList.remove('drag-over');
  }

  function handleDrop(e) {
    e.preventDefault();
    this.classList.remove('drag-over');

    const targetIndex = parseInt(this.dataset.index);
    if (targetIndex !== undefined && draggedIndex !== null) {
      swapTiles(draggedIndex, targetIndex);
    }
  }

  // Touch support
  let touchStartIndex = null;
  let touchClone = null;

  function handleTouchStart(e) {
    e.preventDefault();
    touchStartIndex = parseInt(this.dataset.index);
    this.classList.add('dragging');

    if (!gameStarted) {
      gameStarted = true;
      startTimer();
    }

    // Create a clone for visual feedback
    touchClone = this.cloneNode(true);
    touchClone.style.position = 'fixed';
    touchClone.style.zIndex = '1000';
    touchClone.style.pointerEvents = 'none';
    touchClone.style.opacity = '0.8';
    touchClone.style.transform = 'scale(1.1)';
    document.body.appendChild(touchClone);

    const touch = e.touches[0];
    touchClone.style.left = (touch.clientX - 30) + 'px';
    touchClone.style.top = (touch.clientY - 30) + 'px';
  }

  function handleTouchMove(e) {
    e.preventDefault();
    if (!touchClone) return;

    const touch = e.touches[0];
    touchClone.style.left = (touch.clientX - 30) + 'px';
    touchClone.style.top = (touch.clientY - 30) + 'px';

    // Highlight target
    document.querySelectorAll('.tile').forEach(t => t.classList.remove('drag-over'));
    const element = document.elementFromPoint(touch.clientX, touch.clientY);
    if (element && element.classList.contains('tile') && !element.classList.contains('empty')) {
      element.classList.add('drag-over');
    }
  }

  function handleTouchEnd(e) {
    e.preventDefault();
    if (touchClone) {
      touchClone.remove();
      touchClone = null;
    }

    document.querySelectorAll('.tile').forEach(t => {
      t.classList.remove('dragging');
      t.classList.remove('drag-over');
    });

    if (touchStartIndex === null) return;

    const touch = e.changedTouches[0];
    const element = document.elementFromPoint(touch.clientX, touch.clientY);

    if (element && element.classList.contains('tile')) {
      const targetIndex = parseInt(element.dataset.index);
      if (!isNaN(targetIndex) && targetIndex !== touchStartIndex) {
        swapTiles(touchStartIndex, targetIndex);
      }
    }

    touchStartIndex = null;
  }

  function swapTiles(idx1, idx2) {
    // Check if adjacent
    const row1 = Math.floor(idx1 / gridSize);
    const col1 = idx1 % gridSize;
    const row2 = Math.floor(idx2 / gridSize);
    const col2 = idx2 % gridSize;

    const isAdjacent = (Math.abs(row1 - row2) + Math.abs(col1 - col2)) === 1;

    if (isAdjacent) {
      [tiles[idx1], tiles[idx2]] = [tiles[idx2], tiles[idx1]];
      moves++;
      document.getElementById('moves').textContent = moves;
      renderGrid();
      checkWin();
    }
  }

  function checkWin() {
    for (let i = 0; i < totalTiles - 1; i++) {
      if (tiles[i] !== i + 1) return;
    }
    // Win!
    clearInterval(timerInterval);
    setTimeout(() => {
      document.getElementById('winStats').textContent =
        `Completed in ${moves} moves and ${formatTime(seconds)}`;
      document.getElementById('winOverlay').classList.add('show');
      launchConfetti();
    }, 300);
  }

  function startTimer() {
    timerInterval = setInterval(() => {
      seconds++;
      document.getElementById('timer').textContent = formatTime(seconds);
    }, 1000);
  }

  function formatTime(s) {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  }

  function launchConfetti() {
    const colors = ['#ffd700', '#ff6b6b', '#4ecdc4', '#45b7d1', '#96ceb4', '#ff9ff3', '#54a0ff'];
    for (let i = 0; i < 80; i++) {
      setTimeout(() => {
        const confetti = document.createElement('div');
        confetti.className = 'confetti';
        confetti.style.left = Math.random() * 100 + 'vw';
        confetti.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
        confetti.style.width = Math.random() * 10 + 5 + 'px';
        confetti.style.height = Math.random() * 10 + 5 + 'px';
        confetti.style.animationDuration = Math.random() * 2 + 2 + 's';
        confetti.style.animationDelay = '0s';
        document.body.appendChild(confetti);
        setTimeout(() => confetti.remove(), 4000);
      }, i * 30);
    }
  }

  // Initialize
  initGame();
</script>

