<script>
  const tracks = [
    { title: "Neon Overdrive", artist: "CyberBeat", album: "Digital Realm", duration: "3:45", emoji: "🏎️" },
    { title: "Boss Battle Anthem", artist: "Pixel Storm", album: "Final Stage", duration: "4:12", emoji: "⚔️" },
    { title: "Cyberpunk City", artist: "Neon Waves", album: "Future Noir", duration: "3:58", emoji: "🌃" },
    { title: "Pixel Warriors", artist: "8Bit Army", album: "Retro Legends", duration: "3:22", emoji: "👾" },
    { title: "Dark Dungeon", artist: "Shadow Synth", album: "Deep Quest", duration: "5:01", emoji: "🏰" },
    { title: "Rocket Boost", artist: "Turbo Bass", album: "Speed Run", duration: "3:33", emoji: "🚀" },
    { title: "Epic Victory", artist: "Glory Sound", album: "Champion", duration: "4:28", emoji: "🏆" },
    { title: "Stealth Mode", artist: "Shadow Ops", album: "Hidden Path", duration: "3:15", emoji: "🥷" },
    { title: "Laser Grid", artist: "Synth Commander", album: "Matrix", duration: "4:45", emoji: "🔫" },
    { title: "Dragon's Lair", artist: "Fantasy Beat", album: "Mythic World", duration: "5:20", emoji: "🐉" },
    { title: "Neon Nights", artist: "Retro Wave", album: "Synthwave", duration: "3:50", emoji: "🌙" },
    { title: "Game Over", artist: "Final Boss", album: "Last Stand", duration: "4:05", emoji: "💀" }
  ];

  let currentTrack = -1;
  let isPlaying = false;
  let isShuffle = false;
  let isRepeat = false;
  let playCount = 0;
  let progress = 0;
  let progressInterval = null;
  let currentDuration = 0;

  function init() {
    createParticles();
    createVisualizer();
    renderPlaylist();
    setupEventListeners();
    setTimeout(() => {
      document.getElementById('modalOverlay').classList.add('active');
    }, 500);
  }

  function createParticles() {
    const container = document.getElementById('particles');
    for (let i = 0; i < 30; i++) {
      const particle = document.createElement('div');
      particle.className = 'particle';
      particle.style.left = Math.random() * 100 + '%';
      particle.style.animationDuration = (Math.random() * 10 + 5) + 's';
      particle.style.animationDelay = Math.random() * 10 + 's';
      particle.style.width = (Math.random() * 3 + 1) + 'px';
      particle.style.height = particle.style.width;
      container.appendChild(particle);
    }
  }

  function createVisualizer() {
    const container = document.getElementById('visualizer');
    for (let i = 0; i < 50; i++) {
      const bar = document.createElement('div');
      bar.className = 'visualizer-bar';
      bar.style.height = '4px';
      container.appendChild(bar);
    }
  }

  function updateVisualizer() {
    const bars = document.querySelectorAll('.visualizer-bar');
    bars.forEach((bar, i) => {
      if (isPlaying) {
        const height = Math.random() * 80 + 10;
        bar.style.height = height + 'px';
      } else {
        bar.style.height = '4px';
      }
    });
  }

  function renderPlaylist() {
    const playlist = document.getElementById('playlist');
    playlist.innerHTML = '';
    tracks.forEach((track, index) => {
      const trackEl = document.createElement('div');
      trackEl.className = 'track' + (index === currentTrack ? ' active' : '');
      trackEl.innerHTML = `
        <div class="track-number">
          <span class="track-number-text">${String(index + 1).padStart(2, '0')}</span>
          <div class="track-wave">
            <div class="wave-bar"></div>
            <div class="wave-bar"></div>
            <div class="wave-bar"></div>
            <div class="wave-bar"></div>
          </div>
        </div>
        <div class="track-art">${track.emoji}</div>
        <div class="track-info">
          <div class="track-title">${track.title}</div>
          <div class="track-artist">${track.artist}</div>
        </div>
        <div class="track-duration">${track.duration}</div>
        <div class="track-actions">
          <button class="track-action-btn" onclick="event.stopPropagation(); toggleLike(this)" title="Like">♡</button>
        </div>
      `;
      trackEl.addEventListener('click', () => playTrack(index));
      playlist.appendChild(trackEl);
    });
  }

  function playTrack(index) {
    if (index === currentTrack && isPlaying) {
      pauseTrack();
      return;
    }

    currentTrack = index;
    const track = tracks[index];
    currentDuration = parseDuration(track.duration);
    progress = 0;

    document.getElementById('npTitle').textContent = track.title;
    document.getElementById('npArtist').textContent = track.artist;
    document.getElementById('npAlbum').textContent = track.album;
    document.getElementById('albumArt').textContent = track.emoji;
    document.getElementById('totalTime').textContent = track.duration;
    document.getElementById('currentTrackNum').textContent = index + 1;

    document.getElementById('albumArt').classList.add('playing');

    isPlaying = true;
    document.getElementById('playBtn').textContent = '⏸';
    playCount++;
    document.getElementById('playCount').textContent = playCount;

    renderPlaylist();
    startProgress();
  }

  function pauseTrack() {
    isPlaying = false;
    document.getElementById('playBtn').textContent = '▶';
    document.getElementById('albumArt').classList.remove('playing');
    clearInterval(progressInterval);
  }

  function togglePlay() {
    if (currentTrack === -1) {
      playTrack(0);
    } else if (isPlaying) {
      pauseTrack();
    } else {
      isPlaying = true;
      document.getElementById('playBtn').textContent = '⏸';
      document.getElementById('albumArt').classList.add('playing');
      startProgress();
    }
  }

  function startProgress() {
    clearInterval(progressInterval);
    progressInterval = setInterval(() => {
      if (progress < currentDuration) {
        progress += 0.1;
        updateProgress();
        updateVisualizer();
      } else {
        if (isRepeat) {
          progress = 0;
        } else {
          nextTrack();
        }
      }
    }, 100);
  }

  function updateProgress() {
    const percent = (progress / currentDuration) * 100;
    document.getElementById('progressFill').style.width = percent + '%';
    document.getElementById('currentTime').textContent = formatTime(progress);
  }

  function formatTime(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return mins + ':' + String(secs).padStart(2, '0');
  }

  function parseDuration(duration) {
    const parts = duration.split(':');
    return parseInt(parts[0]) * 60 + parseInt(parts[1]);
  }

  function nextTrack() {
    if (isShuffle) {
      let next;
      do {
        next = Math.floor(Math.random() * tracks.length);
      } while (next === currentTrack && tracks.length > 1);
      playTrack(next);
    } else {
      playTrack((currentTrack + 1) % tracks.length);
    }
  }

  function prevTrack() {
    if (progress > 3) {
      progress = 0;
      updateProgress();
    } else {
      playTrack((currentTrack - 1 + tracks.length) % tracks.length);
    }
  }

  function toggleLike(btn) {
    btn.classList.toggle('liked');
    btn.textContent = btn.classList.contains('liked') ? '♥' : '♡';
  }

  function setupEventListeners() {
    document.getElementById('playBtn').addEventListener('click', togglePlay);
    document.getElementById('nextBtn').addEventListener('click', nextTrack);
    document.getElementById('prevBtn').addEventListener('click', prevTrack);

    document.getElementById('shuffleBtn').addEventListener('click', function() {
      isShuffle = !isShuffle;
      this.classList.toggle('active', isShuffle);
    });

    document.getElementById('repeatBtn').addEventListener('click', function() {
      isRepeat = !isRepeat;
      this.classList.toggle('active', isRepeat);
    });

    document.getElementById('progressBar').addEventListener('click', function(e) {
      const rect = this.getBoundingClientRect();
      const percent = (e.clientX - rect.left) / rect.width;
      progress = percent * currentDuration;
      updateProgress();
    });

    document.getElementById('volumeSlider').addEventListener('input', function() {
      // Visual feedback only in this demo
    });

    setInterval(updateVisualizer, 150);
  }

  function closeModal() {
    document.getElementById('modalOverlay').classList.remove('active');
  }

  document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
      e.preventDefault();
      togglePlay();
    } else if (e.code === 'ArrowRight') {
      nextTrack();
    } else if (e.code === 'ArrowLeft') {
      prevTrack();
    }
  });

  init();
</script>

</body>
