<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Responsive canvas
function resizeCanvas() {
    canvas.width = Math.min(window.innerWidth, 480);
    canvas.height = Math.min(window.innerHeight, 800);
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

// Game state
let gameState = 'start'; // start, playing, gameover
let score = 0;
let coins = 0;
let distance = 0;
let speed = 5;
let maxSpeed = 15;
let speedIncrement = 0.002;

// Lane positions (3 lanes)
const LANE_COUNT = 3;
let laneWidth;
let lanePositions = [];

function updateLanePositions() {
    laneWidth = canvas.width / LANE_COUNT;
    lanePositions = [];
    for (let i = 0; i < LANE_COUNT; i++) {
        lanePositions.push(laneWidth * i + laneWidth / 2);
    }
}
updateLanePositions();

// Player
const player = {
    lane: 1, // 0, 1, 2
    x: 0,
    y: 0,
    targetX: 0,
    width: 40,
    height: 60,
    jumping: false,
    sliding: false,
    jumpVelocity: 0,
    jumpHeight: 0,
    slideTimer: 0,
    animFrame: 0,
    animTimer: 0,
    color: '#FF6B35',
    invincible: false,
    invincibleTimer: 0
};

// Objects array
let obstacles = [];
let coinItems = [];
let particles = [];
let trackLines = [];
let buildings = [];

// Initialize track lines
function initTrackLines() {
    trackLines = [];
    for (let i = 0; i < 20; i++) {
        trackLines.push({ z: i * 80 });
    }
}
initTrackLines();

// Initialize buildings
function initBuildings() {
    buildings = [];
    for (let i = 0; i < 10; i++) {
        buildings.push({
            z: i * 200,
            side: Math.random() > 0.5 ? 1 : -1,
            width: 40 + Math.random() * 60,
            height: 80 + Math.random() * 120,
            color: `hsl(${Math.random() * 60 + 200}, 30%, ${20 + Math.random() * 20}%)`
        });
    }
}
initBuildings();

// Spawn obstacle
function spawnObstacle() {
    const lane = Math.floor(Math.random() * LANE_COUNT);
    const types = ['train', 'barrier', 'low_barrier'];
    const type = types[Math.floor(Math.random() * types.length)];

    obstacles.push({
        lane: lane,
        z: 2000,
        type: type,
        width: type === 'train' ? 50 : 40,
        height: type === 'train' ? 120 : (type === 'low_barrier' ? 30 : 60),
        color: type === 'train' ? `hsl(${Math.random() * 360}, 60%, 40%)` : '#888',
        passed: false
    });
}

// Spawn coin
function spawnCoin() {
    const lane = Math.floor(Math.random() * LANE_COUNT);
    const count = 3 + Math.floor(Math.random() * 5);
    for (let i = 0; i < count; i++) {
        coinItems.push({
            lane: lane,
            z: 2000 + i * 60,
            collected: false,
            bobOffset: Math.random() * Math.PI * 2,
            radius: 12
        });
    }
}

// Particle system
function spawnParticles(x, y, color, count) {
    for (let i = 0; i < count; i++) {
        particles.push({
            x: x,
            y: y,
            vx: (Math.random() - 0.5) * 10,
            vy: (Math.random() - 0.5) * 10 - 5,
            life: 1,
            color: color,
            size: 2 + Math.random() * 4
        });
    }
}

// Perspective projection
function project(x, y, z) {
    const cameraHeight = 150;
    const cameraZ = 0;
    const fov = 300;
    const relZ = z - cameraZ;

    if (relZ <= 0) return null;

    const scale = fov / relZ;
    const screenX = canvas.width / 2 + (x - canvas.width / 2) * scale;
    const screenY = canvas.height * 0.6 - (y - cameraHeight) * scale;

    return { x: screenX, y: screenY, scale: scale };
}

// Draw perspective track
function drawTrack() {
    const horizonY = canvas.height * 0.35;
    const bottomY = canvas.height;

    // Sky gradient
    const skyGrad = ctx.createLinearGradient(0, 0, 0, horizonY);
    skyGrad.addColorStop(0, '#1a1a2e');
    skyGrad.addColorStop(0.5, '#16213e');
    skyGrad.addColorStop(1, '#0f3460');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, canvas.width, horizonY);

    // Stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 50; i++) {
        const sx = (i * 137.5 + distance * 0.01) % canvas.width;
        const sy = (i * 97.3) % horizonY;
        const size = (Math.sin(Date.now() * 0.001 + i) + 1) * 1.5;
        ctx.globalAlpha = 0.3 + Math.sin(Date.now() * 0.002 + i) * 0.3;
        ctx.fillRect(sx, sy, size, size);
    }
    ctx.globalAlpha = 1;

    // Ground
    const groundGrad = ctx.createLinearGradient(0, horizonY, 0, canvas.height);
    groundGrad.addColorStop(0, '#2d3436');
    groundGrad.addColorStop(1, '#636e72');
    ctx.fillStyle = groundGrad;
    ctx.fillRect(0, horizonY, canvas.width, canvas.height - horizonY);

    // Track rails
    const trackLeft = canvas.width * 0.15;
    const trackRight = canvas.width * 0.85;

    // Draw track surface with perspective
    ctx.beginPath();
    ctx.moveTo(canvas.width / 2 - 5, horizonY);
    ctx.lineTo(canvas.width / 2 + 5, horizonY);
    ctx.lineTo(trackRight, bottomY);
    ctx.lineTo(trackLeft, bottomY);
    ctx.closePath();
    ctx.fillStyle = '#555';
    ctx.fill();

    // Lane dividers
    for (let i = 1; i < LANE_COUNT; i++) {
        const xRatio = i / LANE_COUNT;
        const topX = canvas.width / 2 + (canvas.width * 0.5 * (xRatio - 0.5)) * 0.1;
        const bottomX = trackLeft + (trackRight - trackLeft) * xRatio;

        ctx.beginPath();
        ctx.moveTo(topX, horizonY);
        ctx.lineTo(bottomX, bottomY);
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.setLineDash([20, 20]);
        ctx.lineDashOffset = -distance * 2;
        ctx.stroke();
        ctx.setLineDash([]);
    }

    // Track ties (sleepers)
    for (let i = 0; i < trackLines.length; i++) {
        const z = trackLines[i].z;
        const relZ = z - (distance % 80);
        if (relZ <= 0 || relZ > 2000) continue;

        const proj = project(canvas.width / 2, 0, relZ);
        if (!proj) continue;

        const tieWidth = (trackRight - trackLeft) * proj.scale * 0.5;
        const tieX = canvas.width / 2;
        const tieY = proj.y;

        ctx.fillStyle = '#444';
        ctx.fillRect(tieX - tieWidth, tieY - 2, tieWidth * 2, 4);
    }

    // Buildings on sides
    buildings.forEach(b => {
        const relZ = b.z - (distance % 2000);
        if (relZ <= 0 || relZ > 2000) return;

        const sideX = b.side === 1 ? trackRight + 20 : trackLeft - 20 - b.width;
        const proj = project(sideX + b.width / 2, b.height / 2, relZ);
        if (!proj) return;

        const bw = b.width * proj.scale * 0.5;
        const bh = b.height * proj.scale * 0.5;
        const bx = proj.x - bw / 2;
        const by = proj.y - bh;

        ctx.fillStyle = b.color;
        ctx.fillRect(bx, by, bw, bh);

        // Windows
        ctx.fillStyle = '#FFD700';
        ctx.globalAlpha = 0.6;
        for (let wy = 0; wy < bh - 10; wy += 15) {
            for (let wx = 5; wx < bw - 5; wx += 12) {
                if (Math.random() > 0.3) {
                    ctx.fillRect(bx + wx, by + wy + 5, 6, 8);
                }
            }
        }
        ctx.globalAlpha = 1;
    });
}

// Draw player
function drawPlayer() {
    const laneX = lanePositions[player.lane];
    const targetX = laneX;

    // Smooth lane transition
    player.x += (targetX - player.x) * 0.2;

    const baseY = canvas.height * 0.75;
    const jumpOffset = player.jumpHeight;
    const slideOffset = player.sliding ? 20 : 0;

    const px = player.x;
    const py = baseY - jumpOffset - slideOffset;

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(px, baseY + 10, 20, 8, 0, 0, Math.PI * 2);
    ctx.fill();

    // Player body
    const bodyHeight = player.sliding ? 25 : 60;
    const bodyWidth = 35;

    // Invincibility flash
    if (player.invincible && Math.floor(Date.now() / 100) % 2 === 0) {
        ctx.globalAlpha = 0.5;
    }

    // Body
    ctx.fillStyle = player.color;
    ctx.fillRect(px - bodyWidth / 2, py - bodyHeight, bodyWidth, bodyHeight);

    // Head
    const headY = py - bodyHeight - 15;
    ctx.fillStyle = '#FFDAB9';
    ctx.beginPath();
    ctx.arc(px, headY, 12, 0, Math.PI * 2);
    ctx.fill();

    // Hat
    ctx.fillStyle = '#FF4500';
    ctx.fillRect(px - 14, headY - 12, 28, 8);
    ctx.fillRect(px - 10, headY - 18, 20, 8);

    // Eyes
    ctx.fillStyle = '#000';
    ctx.fillRect(px - 6, headY - 3, 4, 4);
    ctx.fillRect(px + 2, headY - 3, 4, 4);

    // Legs animation
    if (!player.sliding && !player.jumping) {
        player.animTimer += 0.15;
        const legSwing = Math.sin(player.animTimer) * 15;

        ctx.fillStyle = '#2d3436';
        ctx.fillRect(px - 12, py - 5, 8, 20 + legSwing);
        ctx.fillRect(px + 4, py - 5, 8, 20 - legSwing);

        // Shoes
        ctx.fillStyle = '#e74c3c';
        ctx.fillRect(px - 14, py + 15 + legSwing, 12, 6);
        ctx.fillRect(px + 2, py + 15 - legSwing, 12, 6);
    }

    // Arms
    ctx.fillStyle = '#FFDAB9';
    const armSwing = Math.sin(player.animTimer) * 10;
    ctx.fillRect(px - 20, py - bodyHeight + 10 + armSwing, 8, 25);
    ctx.fillRect(px + 12, py - bodyHeight + 10 - armSwing, 8, 25);

    ctx.globalAlpha = 1;
}

// Draw obstacles
function drawObstacles() {
    obstacles.forEach(obs => {
        const laneX = lanePositions[obs.lane];
        const proj = project(laneX, 0, obs.z - distance);
        if (!proj) return;

        const w = obs.width * proj.scale * 0.5;
        const h = obs.height * proj.scale * 0.5;
        const x = proj.x - w / 2;
        const y = proj.y - h;

        if (obs.type === 'train') {
            // Train body
            ctx.fillStyle = obs.color;
            ctx.fillRect(x, y, w, h);

            // Train details
            ctx.fillStyle = '#333';
            ctx.fillRect(x + 5, y + 10, w - 10, h * 0.3);

            // Windows
            ctx.fillStyle = '#87CEEB';
            for (let wy = y + 15; wy < y + h - 20; wy += 25) {
                ctx.fillRect(x + 8, wy, w - 16, 15);
            }

            // Stripe
            ctx.fillStyle = '#FFD700';
            ctx.fillRect(x, y + h * 0.6, w, 5);

        } else if (obs.type === 'barrier') {
            // Barrier
            ctx.fillStyle = '#e74c3c';
            ctx.fillRect(x, y, w, h);

            // Stripes
            ctx.fillStyle = '#fff';
            for (let sy = y; sy < y + h; sy += 10) {
                ctx.fillRect(x, sy, w, 5);
            }

            // Posts
            ctx.fillStyle = '#888';
            ctx.fillRect(x - 3, y, 6, h);
            ctx.fillRect(x + w - 3, y, 6, h);

        } else if (obs.type === 'low_barrier') {
            // Low barrier (can jump over)
            ctx.fillStyle = '#f39c12';
            ctx.fillRect(x, y + h * 0.5, w, h * 0.5);

            // Warning stripes
            ctx.fillStyle = '#000';
            for (let sx = x; sx < x + w; sx += 15) {
                ctx.fillRect(sx, y + h * 0.5, 8, h * 0.5);
            }
        }
    });
}

// Draw coins
function drawCoins() {
    coinItems.forEach(coin => {
        if (coin.collected) return;

        const laneX = lanePositions[coin.lane];
        const proj = project(laneX, 20, coin.z - distance);
        if (!proj) return;

        const r = coin.radius * proj.scale * 0.5;
        const bob = Math.sin(Date.now() * 0.005 + coin.bobOffset) * 5;

        // Coin glow
        ctx.fillStyle = 'rgba(255, 215, 0, 0.3)';
        ctx.beginPath();
        ctx.arc(proj.x, proj.y + bob, r * 1.5, 0, Math.PI * 2);
        ctx.fill();

        // Coin body
        ctx.fillStyle = '#FFD700';
        ctx.beginPath();
        ctx.arc(proj.x, proj.y + bob, r, 0, Math.PI * 2);
        ctx.fill();

        // Coin inner
        ctx.fillStyle = '#FFA500';
        ctx.beginPath();
        ctx.arc(proj.x, proj.y + bob, r * 0.7, 0, Math.PI * 2);
        ctx.fill();

        // $ symbol
        ctx.fillStyle = '#FFD700';
        ctx.font = `bold ${r}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('$', proj.x, proj.y + bob + 1);
    });
}

// Draw particles
function drawParticles() {
    particles.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
    });
    ctx.globalAlpha = 1;
}

// Update game
function update() {
    if (gameState !== 'playing') return;

    // Increase speed
    speed = Math.min(maxSpeed, speed + speedIncrement);
    distance += speed;
    score = Math.floor(distance / 10);

    // Update UI
    document.getElementById('score-display').textContent = `Score: ${score}`;
    document.getElementById('coin-display').textContent = `🪙 ${coins}`;

    // Player jump
    if (player.jumping) {
        player.jumpHeight += player.jumpVelocity;
        player.jumpVelocity -= 0.8;
        if (player.jumpHeight <= 0) {
            player.jumpHeight = 0;
            player.jumping = false;
            player.jumpVelocity = 0;
        }
    }

    // Player slide
    if (player.sliding) {
        player.slideTimer--;
        if (player.slideTimer <= 0) {
            player.sliding = false;
        }
    }

    // Invincibility timer
    if (player.invincible) {
        player.invincibleTimer--;
        if (player.invincibleTimer <= 0) {
            player.invincible = false;
        }
    }

    // Spawn obstacles
    if (Math.random() < 0.02 + speed * 0.001) {
        spawnObstacle();
    }

    // Spawn coins
    if (Math.random() < 0.015) {
        spawnCoin();
    }

    // Update obstacles
    obstacles.forEach(obs => {
        obs.z -= speed;

        // Collision detection
        if (!obs.passed && obs.z - distance < 100 && obs.z - distance > -50) {
            if (obs.lane === player.lane) {
                if (obs.type === 'low_barrier') {
                    if (!player.jumping || player.jumpHeight < 40) {
                        if (!player.invincible) {
                            gameOver();
                        }
                    }
                } else {
                    if (!player.sliding || obs.type !== 'low_barrier') {
                        if (!player.invincible) {
                            gameOver();
                        }
                    }
                }
            }
        }

        if (obs.z - distance < -100) {
            obs.passed = true;
        }
    });

    // Remove old obstacles
    obstacles = obstacles.filter(obs => obs.z - distance > -200);

    // Update coins
    coinItems.forEach(coin => {
        coin.z -= speed;

        // Collection detection
        if (!coin.collected && coin.z - distance < 80 && coin.z - distance > -20) {
            const coinLane = coin.lane;
            if (coinLane === player.lane) {
                if (!player.jumping || player.jumpHeight < 60) {
                    coin.collected = true;
                    coins++;
                    spawnParticles(player.x, canvas.height * 0.75 - 30, '#FFD700', 8);
                }
            }
        }
    });

    // Remove old coins
    coinItems = coinItems.filter(coin => coin.z - distance > -200 && !coin.collected);

    // Update particles
    particles.forEach(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.3;
        p.life -= 0.02;
    });
    particles = particles.filter(p => p.life > 0);

    // Update track lines
    trackLines.forEach(line => {
        line.z -= speed;
        if (line.z < 0) line.z += 20 * 80;
    });

    // Update buildings
    buildings.forEach(b => {
        b.z -= speed;
        if (b.z < 0) b.z += 10 * 200;
    });
}

// Game over
function gameOver() {
    gameState = 'gameover';
    document.getElementById('final-score').textContent = `Score: ${score}`;
    document.getElementById('final-coins').textContent = `Coins: ${coins}`;
    document.getElementById('game-over-screen').style.display = 'flex';
    spawnParticles(player.x, canvas.height * 0.75, '#FF4444', 20);
}

// Start game
function startGame() {
    gameState = 'playing';
    score = 0;
    coins = 0;
    distance = 0;
    speed = 5;
    player.lane = 1;
    player.x = lanePositions[1];
    player.jumping = false;
    player.sliding = false;
    player.jumpHeight = 0;
    player.jumpVelocity = 0;
    player.invincible = false;
    obstacles = [];
    coinItems = [];
    particles = [];
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('game-over-screen').style.display = 'none';
}

// Input handling
let touchStartX = 0;
let touchStartY = 0;

document.addEventListener('keydown', (e) => {
    if (gameState !== 'playing') return;

    switch(e.key) {
        case 'ArrowLeft':
        case 'a':
        case 'A':
            if (player.lane > 0) player.lane--;
            break;
        case 'ArrowRight':
        case 'd':
        case 'D':
            if (player.lane < LANE_COUNT - 1) player.lane++;
            break;
        case 'ArrowUp':
        case 'w':
        case 'W':
        case ' ':
            if (!player.jumping) {
                player.jumping = true;
                player.jumpVelocity = 15;
            }
            break;
        case 'ArrowDown':
        case 's':
        case 'S':
            if (!player.sliding) {
                player.sliding = true;
                player.slideTimer = 30;
            }
            break;
    }
});

// Touch handling
canvas.addEventListener('touchstart', (e) => {
    e.preventDefault();
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
});

canvas.addEventListener('touchend', (e) => {
    e.preventDefault();
    if (gameState !== 'playing') return;

    const touchEndX = e.changedTouches[0].clientX;
    const touchEndY = e.changedTouches[0].clientY;

    const dx = touchEndX - touchStartX;
    const dy = touchEndY - touchStartY;

    const absDx = Math.abs(dx);
    const absDy = Math.abs(dy);

    if (absDx < 10 && absDy < 10) return; // Too small

    if (absDx > absDy) {
        // Horizontal swipe
        if (dx > 0 && player.lane < LANE_COUNT - 1) {
            player.lane++;
        } else if (dx < 0 && player.lane > 0) {
            player.lane--;
        }
    } else {
        // Vertical swipe
        if (dy < 0 && !player.jumping) {
            player.jumping = true;
            player.jumpVelocity = 15;
        } else if (dy > 0 && !player.sliding) {
            player.sliding = true;
            player.slideTimer = 30;
        }
    }
});

// Button handlers
document.getElementById('startBtn').addEventListener('click', startGame);
document.getElementById('restartBtn').addEventListener('click', startGame);

// Game loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    drawTrack();

    if (gameState === 'playing' || gameState === 'gameover') {
        drawObstacles();
        drawCoins();
        drawPlayer();
        drawParticles();
    }

    update();
    requestAnimationFrame(gameLoop);
}

// Initialize player position
player.x = lanePositions[1];

// Start game loop
gameLoop();
</script>
</body>
</html>

