  margin-top: 30px; text-align: center; color: #888;
  font-size: 13px; line-height: 1.8;
}

#start-screen .controls-info kbd {
  background: rgba(255,255,255,0.1); padding: 2px 8px;
  border-radius: 4px; border: 1px solid rgba(255,255,255,0.2);
  color: #ccc;
}

#message-popup {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  background: rgba(0,0,0,0.9); border: 2px solid #ffaa00;
  border-radius: 12px; padding: 20px 30px; color: #fff;
  text-align: center; display: none; z-index: 50;
  pointer-events: auto;
}

#message-popup h2 { color: #ffaa00; margin-bottom: 10px; }
#message-popup p { color: #ccc; margin-bottom: 15px; }

#message-popup .msg-btn {
  padding: 8px 24px; background: #ffaa00; border: none;
  border-radius: 6px; color: #000; font-weight: bold;
  cursor: pointer; font-size: 14px;
}

#fuel-warning {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  color: #ff4444; font-size: 24px; font-weight: bold;
  text-shadow: 0 0 20px rgba(255,0,0,0.5);
  display: none; animation: pulse 1s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

#engine-noise {
  position: absolute; bottom: 180px; right: 20px;
  color: #ff6600; font-size: 11px; font-family: monospace;
}
</style>
</head>
<body>

<div id="start-screen">
  <h1>🌴 TRUK SAWIT SUMATRA 🌴</h1>
  <h2>Simulator Pengangkut Tandan Buah Sawit</h2>
