      <div class="hud-row">
        <span class="hud-label">📦 Beban</span>
        <div class="bar-container"><div class="bar-fill bar-load" id="load-bar" style="width:0%"></div></div>
        <span class="hud-value" id="load-value">0 ton</span>
      </div>
      <div class="hud-row">
        <span class="hud-label">🛞 Traksi</span>
        <div class="bar-container"><div class="bar-fill bar-traction" id="traction-bar" style="width:100%"></div></div>
        <span class="hud-value" id="traction-value">100%</span>
      </div>
    </div>
  </div>

  <div id="weather-indicator">
    <span id="weather-icon">☀️</span>
    <span id="weather-text">Cerah</span>
    <span style="margin-left:10px;color:#aaa;">|</span>
    <span id="time-display">06:00</span>
  </div>

  <div id="mission-panel">
    <h3>📋 Misi Aktif</h3>
    <div id="mission-status">
      <div>📍 Asal: Kebun Sawit Sektor A</div>
      <div>🏭 Tujuan: Pabrik Kelapa Sawit</div>
      <div>📏 Jarak: <span id="distance-to-factory">0</span> m</div>
      <div>💰 Reward: <span id="mission-reward">Rp 5.000.000</span></div>
    </div>
  </div>

  <div id="upgrade-panel">
    <h3>🔧 Upgrade Truk</h3>
    <div id="money-display" style="color:#ffaa00;margin-bottom:8px;">💰 Rp 10.000.000</div>
    <button class="upgrade-btn" onclick="upgradeEngine()">
      ⚙️ Mesin <span class="cost" id="engine-cost">Rp 3.000.000</span>
    </button>
    <button class="upgrade-btn" onclick="upgradeSuspension()">
      🔩 Suspensi <span class="cost" id="suspension-cost">Rp 2.000.000</span>
    </button>
    <button class="upgrade-btn" onclick="upgradeTires()">
      🛞 Ban <span class="cost" id="tires-cost">Rp 1.500.000</span>
    </button>
    <button class="upgrade-btn" onclick="upgradeFuelTank()">
      ⛽ Tangki BBM <span class="cost" id="fueltank-cost">Rp 2.500.000</span>
    </button>
    <button class="upgrade-btn" onclick="closeUpgrade()">
      ✖ Tutup
    </button>
  </div>

  <div id="speedometer">
    <div id="speed-value">0</div>
    <div id="speed-unit">km/h</div>
  </div>

  <div id="gear-display">
    <div id="gear-label">Gear</div>
    <div id="gear-value">N</div>
  </div>

  <div id="minimap">
    <canvas id="minimap-canvas" width="150" height="150"></canvas>
  </div>

  <div id="controls-help">
    W/S: Gas/Rem &nbsp; A/D: Belok &nbsp; Q/E: Gear &nbsp; C: Kamera &nbsp; U: Upgrade &nbsp; Space: Rem Tangan &nbsp; F: Isi BBM
  </div>

  <div id="fuel-warning">⚠️ BAHAN BAKAR HABIS!</div>

  <div id="message-popup">
    <h2 id="msg-title">Misi Selesai!</h2>
    <p id="msg-text">Anda berhasil mengantarkan muatan sawit ke pabrik.</p>
    <button class="msg-btn" onclick="closeMessage()">Lanjut</button>
  </div>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// ==================== GAME STATE ====================
const GameState = {
  running: false,
  speed: 0,
  maxSpeed: 60,
  acceleration: 0.3,
  braking: 0.5,
  friction: 0.1,
  gear: 0, // -1: R, 0: N, 1-5: gears
  gears: [0, 15, 30, 45, 55, 60], // max speed per gear
  steering: 0,
  steeringSpeed: 0.03,
  fuel: 100,
  maxFuel: 100,
  fuelConsumption: 0.02,
  load: 0,
  maxLoad: 20, // tons
  traction: 1.0,
  money: 10000000,
  engineLevel: 1,
  suspensionLevel: 1,
  tiresLevel: 1,
  fuelTankLevel: 1,
  weather: 'clear', // clear, rain, fog, storm
  weatherTimer: 0,
  timeOfDay: 6, // hours
  cameraMode: 0, // 0: third person, 1: cabin, 2: top
  truckPosition: new THREE.Vector3(0, 0, 0),
  truckRotation: 0,
  missionActive: true,
  factoryPosition: new THREE.Vector3(200, 0, -300),
  plantationPosition: new THREE.Vector3(0, 0, 0),
  distanceToFactory: 360,
  engineCost: 3000000,
  suspensionCost: 2000000,
  tiresCost: 1500000,
  fuelTankCost: 2500000,
  keys: {},
  handbrake: false,
  onRoad: true,
  mudEffect: 0,
  slopeAngle: 0,
  bridgeActive: false,
  particles: [],
  rainDrops: [],
  trees: [],
  roadSegments: [],
  mudPatches: [],
  hills: [],
  bridges: [],
  factory: null,
  plantation: null,
  truck: null,
  truckMesh: null,
  cargo: null,
  terrain: null,
  sky: null,
  fog: null,
  sun: null,
  moon: null,
  rainSystem: null,
  minimapCtx: null,
  engineSound: null,
  lastTime: 0,
  deltaTime: 0,
  totalDistance: 0,
  missionsCompleted: 0,
  oilSpills: [],
  barriers: [],
  signposts: [],
  streetLights: []
};

// ==================== THREE.JS SETUP ====================
let scene, camera, renderer, clock;

function initThreeJS() {
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x87CEEB);
  scene.fog = new THREE.FogExp2(0x87CEEB, 0.002);

  camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 2000);
  camera.position.set(0, 5, 10);

  renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  document.body.insertBefore(renderer.domElement, document.getElementById('ui-overlay'));

  clock = new THREE.Clock();

  // Lighting
  const ambientLight = new THREE.AmbientLight(0x404060, 0.6);
  scene.add(ambientLight);

  const sunLight = new THREE.DirectionalLight(0xffeedd, 1.2);
  sunLight.position.set(100, 100, 50);
  sunLight.castShadow = true;
  sunLight.shadow.mapSize.width = 2048;
  sunLight.shadow.mapSize.height = 2048;
  sunLight.shadow.camera.near = 0.5;
  sunLight.shadow.camera.far = 500;
  sunLight.shadow.camera.left = -100;
  sunLight.shadow.camera.right = 100;
  sunLight.shadow.camera.top = 100;
  sunLight.shadow.camera.bottom = -100;
  scene.add(sunLight);
  GameState.sun = sunLight;

  const hemiLight = new THREE.HemisphereLight(0x87CEEB, 0x3a5f0b, 0.4);
  scene.add(hemiLight);

  // Minimap
  const minimapCanvas = document.getElementById('minimap-canvas');
  GameState.minimapCtx = minimapCanvas.getContext('2d');

  window.addEventListener('resize', onWindowResize);
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}

// ==================== TERRAIN GENERATION ====================
function generateTerrain() {
  // Ground plane
  const groundGeometry = new THREE.PlaneGeometry(2000, 2000, 100, 100);
  const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x3a5f0b,
    roughness: 0.9,
    metalness: 0.1
  });

  // Add terrain variation
  const vertices = groundGeometry.attributes.position.array;
  for (let i = 0; i < vertices.length; i += 3) {
    const x = vertices[i];
    const z = vertices[i + 2];
    let y = 0;

    // Create hills
    y += Math.sin(x * 0.01) * Math.cos(z * 0.01) * 5;
    y += Math.sin(x * 0.03 + z * 0.02) * 2;

    // Create steep hills near certain areas
    const distToFactory = Math.sqrt((x - 200) ** 2 + (z + 300) ** 2);
    if (distToFactory < 100) {
      y += (100 - distToFactory) * 0.1;
    }

    vertices[i + 1] = y;
  }

  groundGeometry.computeVertexNormals();
  const ground = new THREE.Mesh(groundGeometry, groundMaterial);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);
  GameState.terrain = ground;

  // Road network
  generateRoads();

  // Palm trees
  generatePalmTrees();

  // Bridges
  generateBridges();

  // Mud patches
  generateMudPatches();

  // Factory
  generateFactory();

  // Plantation
  generatePlantation();

  // Barriers
  generateBarriers();

  // Signposts
  generateSignposts();

  // Street lights
  generateStreetLights();
}

function generateRoads() {
  const roadMaterial = new THREE.MeshStandardMaterial({
    color: 0x333333,
    roughness: 0.8,
    metalness: 0.1
  });

  const roadWidth = 8;
  const roadLength = 600;

  // Main road from plantation to factory
  const mainRoadGeo = new THREE.PlaneGeometry(roadWidth, roadLength);
  const mainRoad = new THREE.Mesh(mainRoadGeo, roadMaterial);
  mainRoad.rotation.x = -Math.PI / 2;
  mainRoad.rotation.z = Math.atan2(-300, 200);
  mainRoad.position.set(100, 0.05, -150);
  mainRoad.receiveShadow = true;
  scene.add(mainRoad);

  // Road markings
  const markingMaterial = new THREE.MeshStandardMaterial({ color: 0xffff00 });
  for (let i = -290; i < 290; i += 10) {
    const markingGeo = new THREE.PlaneGeometry(0.3, 3);
    const marking = new THREE.Mesh(markingGeo, markingMaterial);
    marking.rotation.x = -Math.PI / 2;
    marking.rotation.z = Math.atan2(-300, 200);
    marking.position.set(100 + i * 0.28, 0.06, -150 + i * 0.42);
    scene.add(marking);
  }

  // Side roads
  for (let i = 0; i < 5; i++) {
    const sideRoadGeo = new THREE.PlaneGeometry(4, 100);
    const sideRoad = new THREE.Mesh(sideRoadGeo, roadMaterial);
    sideRoad.rotation.x = -Math.PI / 2;
    sideRoad.rotation.z = Math.PI / 2;
    sideRoad.position.set(-200 + i * 100, 0.05, -100 + Math.random() * 200);
    sideRoad.receiveShadow = true;
    scene.add(sideRoad);
  }

  // Mud sections on road
  const mudMaterial = new THREE.MeshStandardMaterial({
    color: 0x5c4033,
    roughness: 1.0,
    metalness: 0.0
  });

  for (let i = 0; i < 8; i++) {
    const mudGeo = new THREE.PlaneGeometry(6 + Math.random() * 4, 10 + Math.random() * 20);
    const mud = new THREE.Mesh(mudGeo, mudMaterial);
    mud.rotation.x = -Math.PI / 2;
    mud.rotation.z = Math.atan2(-300, 200) + (Math.random() - 0.5) * 0.3;
    mud.position.set(
      100 + (Math.random() - 0.5) * 200,
      0.03,
      -150 + (Math.random() - 0.5) * 400
    );
    mud.receiveShadow = true;
    scene.add(mud);
    GameState.mudPatches.push({
      position: mud.position.clone(),
      radius: 5 + Math.random() * 5,
      effect: 0.3 + Math.random() * 0.4
    });
  }
}

function generatePalmTrees() {
  const trunkMaterial = new THREE.MeshStandardMaterial({
    color: 0x8B4513,
    roughness: 0.9
  });

  const leafMaterial = new THREE.MeshStandardMaterial({
    color: 0x228B22,
    roughness: 0.8,
    side: THREE.DoubleSide
  });

  for (let i = 0; i < 200; i++) {
    const x = (Math.random() - 0.5) * 800;
    const z = (Math.random() - 0.5) * 800;

    // Don't place trees on road
    const distToMainRoad = Math.abs((x - 100) * 0.42 + (z + 150) * 0.28);
    if (distToMainRoad < 6) continue;

    const treeGroup = new THREE.Group();

    // Trunk
    const trunkHeight = 8 + Math.random() * 6;
    const trunkGeo = new THREE.CylinderGeometry(0.3, 0.5, trunkHeight, 8);
    const trunk = new THREE.Mesh(trunkGeo, trunkMaterial);
    trunk.position.y = trunkHeight / 2;
    trunk.castShadow = true;
    treeGroup.add(trunk);

    // Leaves
    for (let j = 0; j < 7; j++) {
      const leafGeo = new THREE.PlaneGeometry(3, 0.8);
      const leaf = new THREE.Mesh(leafGeo, leafMaterial);
      leaf.position.y = trunkHeight;
      leaf.rotation.y = (j / 7) * Math.PI * 2;
      leaf.rotation.z = 0.3 + Math.random() * 0.3;
      leaf.castShadow = true;
      treeGroup.add(leaf);
    }

    // Coconuts/palm fruits
    for (let j = 0; j < 3; j++) {
      const fruitGeo = new THREE.SphereGeometry(0.3, 8, 8);
      const fruitMat = new THREE.MeshStandardMaterial({ color: 0x8B4513 });
      const fruit = new THREE.Mesh(fruitGeo, fruitMat);
      fruit.position.y = trunkHeight - 0.5;
      fruit.position.x = Math.random() * 0.5 - 0.25;
      fruit.position.z = Math.random() * 0.5 - 0.25;
      treeGroup.add(fruit);
    }

    treeGroup.position.set(x, 0, z);
    scene.add(treeGroup);
    GameState.trees.push({ position: new THREE.Vector3(x, 0, z), radius: 1 });
  }
}

function generateBridges() {
  const bridgeMaterial = new THREE.MeshStandardMaterial({
    color: 0x8B7355,
    roughness: 0.8
  });

  const metalMaterial = new THREE.MeshStandardMaterial({
    color: 0x666666,
    roughness: 0.5,
    metalness: 0.8
  });

  // Bridge 1
  const bridge1 = new THREE.Group();
  const bridgeDeck = new THREE.Mesh(
    new THREE.BoxGeometry(6, 0.3, 20),
    bridgeMaterial
  );
  bridgeDeck.position.y = 2;
  bridgeDeck.castShadow = true;
  bridge1.add(bridgeDeck);

  // Railings
  for (let side = -1; side <= 1; side += 2) {
    const railing = new THREE.Mesh(
      new THREE.BoxGeometry(0.2, 1.5, 20),
      metalMaterial
    );
    railing.position.set(side * 2.8, 2.75, 0);
    railing.castShadow = true;
    bridge1.add(railing);
  }

  // Support pillars
  for (let i = -1; i <= 1; i++) {
    const pillar = new THREE.Mesh(
      new THREE.CylinderGeometry(0.5, 0.7, 4, 8),
      bridgeMaterial
    );
    pillar.position.set(0, 0, i * 8);
    pillar.castShadow = true;
    bridge1.add(pillar);
  }

  bridge1.position.set(50, 0, -100);
  bridge1.rotation.y = Math.atan2(-300, 200) * 0.3;
  scene.add(bridge1);
  GameState.bridges.push({ position: bridge1.position.clone(), width: 6, length: 20 });

  // Bridge 2
  const bridge2 = bridge1.clone();
  bridge2.position.set(-100, 0, 50);
  bridge2.rotation.y = Math.PI / 4;
  scene.add(bridge2);
  GameState.bridges.push({ position: bridge2.position.clone(), width: 6, length: 20 });
}

function generateMudPatches() {
  // Already generated with roads
}

function generateFactory() {
  const factoryGroup = new THREE.Group();

  // Main building
  const buildingGeo = new THREE.BoxGeometry(30, 15, 20);
  const buildingMat = new THREE.MeshStandardMaterial({
    color: 0x666666,
    roughness: 0.7
  });
  const building = new THREE.Mesh(buildingGeo, buildingMat);
  building.position.y = 7.5;
  building.castShadow = true;
  factoryGroup.add(building);

  // Storage tanks
  for (let i = 0; i < 4; i++) {
    const tankGeo = new THREE.CylinderGeometry(3, 3, 8, 16);
    const tankMat = new THREE.MeshStandardMaterial({
      color: 0x444444,
      metalness: 0.6,
      roughness: 0.3
    });
    const tank = new THREE.Mesh(tankGeo, tankMat);
    tank.position.set(-10 + i * 7, 4, 15);
    tank.castShadow = true;
    factoryGroup.add(tank);
  }

  // Chimney
  const chimneyGeo = new THREE.CylinderGeometry(1, 1.5, 20, 8);
  const chimneyMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
  const chimney = new THREE.Mesh(chimneyGeo, chimneyMat);
  chimney.position.set(10, 25, -5);
  chimney.castShadow = true;
  factoryGroup.add(chimney);

  // Sign
  const signGeo = new THREE.BoxGeometry(8, 2, 0.5);
  const signMat = new THREE.MeshStandardMaterial({ color: 0xffaa00 });
  const sign = new THREE.Mesh(signGeo, signMat);
  sign.position.set(0, 12, 10.5);
  factoryGroup.add(sign);

  factoryGroup.position.copy(GameState.factoryPosition);
  scene.add(factoryGroup);
  GameState.factory = factoryGroup;
}

function generatePlantation() {
  const plantationGroup = new THREE.Group();

  // Loading platform
  const platformGeo = new THREE.BoxGeometry(15, 1, 10);
  const platformMat = new THREE.MeshStandardMaterial({
    color: 0x8B7355,
    roughness: 0.9
  });
  const platform = new THREE.Mesh(platformGeo, platformMat);
  platform.position.y = 0.5;
  platform.castShadow = true;
  plantationGroup.add(platform);

  // Storage piles (palm fruits)
  for (let i = 0; i < 5; i++) {
    const pileGeo = new THREE.SphereGeometry(2 + Math.random(), 8, 8);
    const pileMat = new THREE.MeshStandardMaterial({
      color: 0xcc4400,
      roughness: 0.8
    });
    const pile = new THREE.Mesh(pileGeo, pileMat);
    pile.position.set(-5 + i * 3, 2, -3);
    pile.scale.y = 0.5;
    pile.castShadow = true;
    plantationGroup.add(pile);
  }

  // Small building
  const smallBuildingGeo = new THREE.BoxGeometry(8, 5, 6);
  const smallBuildingMat = new THREE.MeshStandardMaterial({ color: 0x996633 });
  const smallBuilding = new THREE.Mesh(smallBuildingGeo, smallBuildingMat);
  smallBuilding.position.set(10, 2.5, 5);
  smallBuilding.castShadow = true;
  plantationGroup.add(smallBuilding);

  plantationGroup.position.copy(GameState.plantationPosition);
  scene.add(plantationGroup);
  GameState.plantation = plantationGroup;
}

function generateBarriers() {
  const barrierMaterial = new THREE.MeshStandardMaterial({
    color: 0xff6600,
    roughness: 0.7
  });

  for (let i = 0; i < 10; i++) {
    const barrierGeo = new THREE.BoxGeometry(2, 1, 0.5);
    const barrier = new THREE.Mesh(barrierGeo, barrierMaterial);
    barrier.position.set(
      (Math.random() - 0.5) * 400,
      0.5,
      (Math.random() - 0.5) * 400
    );
    barrier.castShadow = true;
    scene.add(barrier);
    GameState.barriers.push({ position: barrier.position.clone(), radius: 1.5 });
  }
}

function generateSignposts() {
  const postMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513 });
  const signMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff });

  for (let i = 0; i < 15; i++) {
    const postGroup = new THREE.Group();

    const post = new THREE.Mesh(
      new THREE.CylinderGeometry(0.1, 0.1, 3, 6),
      postMaterial
    );
    post.position.y = 1.5;
    postGroup.add(post);

    const sign = new THREE.Mesh(
      new THREE.BoxGeometry(2, 1, 0.1),
      signMaterial
    );
    sign.position.y = 3;
    postGroup.add(sign);

    postGroup.position.set(
      (Math.random() - 0.5) * 500,
      0,
      (Math.random() - 0.5) * 500
    );
    scene.add(postGroup);
    GameState.signposts.push(postGroup);
  }
}

function generateStreetLights() {
  const poleMaterial = new THREE.MeshStandardMaterial({ color: 0x444444 });
  const lightMaterial = new THREE.MeshStandardMaterial({
    color: 0xffffcc,
    emissive: 0xffffcc,
    emissiveIntensity: 0.5
  });

  for (let i = 0; i < 20; i++) {
    const lightGroup = new THREE.Group();

    const pole = new THREE.Mesh(
      new THREE.CylinderGeometry(0.1, 0.15, 6, 6),
      poleMaterial
    );
    pole.position.y = 3;
    lightGroup.add(pole);

    const light = new THREE.Mesh(
      new THREE.SphereGeometry(0.3, 8, 8),
      lightMaterial
    );
    light.position.y = 6.2;
    lightGroup.add(light);

    const pointLight = new THREE.PointLight(0xffffcc, 0.5, 20);
    pointLight.position.y = 6;
    lightGroup.add(pointLight);

    lightGroup.position.set(
      100 + (Math.random() - 0.5) * 300,
      0,
      -150 + (Math.random() - 0.5) * 300
    );
    scene.add(lightGroup);
    GameState.streetLights.push(lightGroup);
  }
}

// ==================== TRUCK GENERATION ====================
function generateTruck() {
  const truckGroup = new THREE.Group();

  // Chassis
  const chassisGeo = new THREE.BoxGeometry(2.5, 0.5, 12);
  const chassisMat = new THREE.MeshStandardMaterial({
    color: 0x222222,
    roughness: 0.6,
    metalness: 0.8
  });
  const chassis = new THREE.Mesh(chassisGeo, chassisMat);
  chassis.position.y = 0.8;
  chassis.castShadow = true;
  truckGroup.add(chassis);

  // Cab
  const cabGeo = new THREE.BoxGeometry(2.5, 2.5, 3);
  const cabMat = new THREE.MeshStandardMaterial({
    color: 0xcc3300,
    roughness: 0.4,
    metalness: 0.6
  });
  const cab = new THREE.Mesh(cabGeo, cabMat);
  cab.position.set(0, 2.3, 4.5);
  cab.castShadow = true;
  truckGroup.add(cab);

  // Windshield
  const windshieldGeo = new THREE.PlaneGeometry(2.2, 1.5);
  const windshieldMat = new THREE.MeshStandardMaterial({
    color: 0x88ccff,
    transparent: true,
    opacity: 0.6,
    roughness: 0.1,
    metalness: 0.9
  });
  const windshield = new THREE.Mesh(windshieldGeo, windshieldMat);
  windshield.position.set(0, 2.5, 6.01);
  truckGroup.add(windshield);

  // Side windows
  for (let side = -1; side <= 1; side += 2) {
    const sideWindowGeo = new THREE.PlaneGeometry(1.5, 1.2);
    const sideWindow = new THREE.Mesh(sideWindowGeo, windshieldMat);
    sideWindow.position.set(side * 1.26, 2.5, 4.5);
    sideWindow.rotation.y = side * Math.PI / 2;
    truckGroup.add(sideWindow);
  }

  // Engine hood
  const hoodGeo = new THREE.BoxGeometry(2.3, 0.8, 2);
  const hood = new THREE.Mesh(hoodGeo, cabMat);
  hood.position.set(0, 2.2, 7);
  hood.castShadow = true;
  truckGroup.add(hood);

  // Cargo bed
  const cargoBedGeo = new THREE.BoxGeometry(2.8, 1.5, 8);
  const cargoBedMat = new THREE.MeshStandardMaterial({
    color: 0x444444,
    roughness: 0.7,
    metalness: 0.5
  });
  const cargoBed = new THREE.Mesh(cargoBedGeo, cargoBedMat);
  cargoBed.position.set(0, 1.8, -1.5);
  cargoBed.castShadow = true;
  truckGroup.add(cargoBed);

  // Cargo (palm fruits)
  const cargoGroup = new THREE.Group();
  for (let i = 0; i < 20; i++) {
    const fruitGeo = new THREE.SphereGeometry(0.4 + Math.random() * 0.3, 8, 8);
    const fruitMat = new THREE.MeshStandardMaterial({
      color: 0xcc4400,
      roughness: 0.8
    });
    const fruit = new THREE.Mesh(fruitGeo, fruitMat);
    fruit.position.set(
      (Math.random() - 0.5) * 2,
      0.3 + Math.random() * 0.5,
      (Math.random() - 0.5) * 6
    );
    fruit.castShadow = true;
    cargoGroup.add(fruit);
  }
  cargoGroup.position.set(0, 2.5, -1.5);
  truckGroup.add(cargoGroup);
  GameState.cargo = cargoGroup;

  // Wheels
  const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 16);
  const wheelMat = new THREE.MeshStandardMaterial({
    color: 0x111111,
    roughness: 0.9
  });
  const wheelPositions = [
    { x: -1.3, y: 0.6, z: 4 },
    { x: 1.3, y: 0.6, z: 4 },
    { x: -1.3, y: 0.6, z: -2 },
    { x: 1.3, y: 0.6, z: -2 },
    { x: -1.3, y: 0.6, z: -4 },
    { x: 1.3, y: 0.6, z: -4 }
  ];

  GameState.wheels = [];
  wheelPositions.forEach(pos => {
    const wheel = new THREE.Mesh(wheelGeo, wheelMat);
    wheel.rotation.z = Math.PI / 2;
    wheel.position.set(pos.x, pos.y, pos.z);
    wheel.castShadow = true;
    truckGroup.add(wheel);
    GameState.wheels.push(wheel);
  });

  // Headlights
  const headlightGeo = new THREE.SphereGeometry(0.2, 8, 8);
  const headlightMat = new THREE.MeshStandardMaterial({
    color: 0xffffcc,
    emissive: 0xffffcc,
    emissiveIntensity: 0.8
  });
  for (let side = -1; side <= 1; side += 2) {
    const headlight = new THREE.Mesh(headlightGeo, headlightMat);
    headlight.position.set(side * 0.8, 1.5, 6.1);
    truckGroup.add(headlight);
  }

  // Tail lights
  const tailLightMat = new THREE.MeshStandardMaterial({
    color: 0xff0000,
    emissive: 0xff0000,
    emissiveIntensity: 0.5
  });
  for (let side = -1; side <= 1; side += 2) {
    const tailLight = new THREE.Mesh(headlightGeo, tailLightMat);
    tailLight.position.set(side * 0.8, 1.5, -5.6);
    truckGroup.add(tailLight);
  }

  // Exhaust
  const exhaustGeo = new THREE.CylinderGeometry(0.15, 0.2, 1.5, 8);
  const exhaustMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
  const exhaust = new THREE.Mesh(exhaustGeo, exhaustMat);
  exhaust.position.set(1.2, 3, 6.5);
  truckGroup.add(exhaust);

  truckGroup.position.copy(GameState.truckPosition);
  scene.add(truckGroup);
  GameState.truck = truckGroup;
  GameState.truckMesh = truckGroup;
}

// ==================== WEATHER SYSTEM ====================
function initWeather() {
  // Rain system
  const rainGeometry = new THREE.BufferGeometry();
  const rainCount = 10000;
  const rainPositions = new Float32Array(rainCount * 3);
  const rainVelocities = new Float32Array(rainCount);

  for (let i = 0; i < rainCount; i++) {
    rainPositions[i * 3] = (Math.random() - 0.5) * 400;
    rainPositions[i * 3 + 1] = Math.random() * 100;
    rainPositions[i * 3 + 2] = (Math.random() - 0.5) * 400;
    rainVelocities[i] = 0.5 + Math.random() * 0.5;
  }

  rainGeometry.setAttribute('position', new THREE.BufferAttribute(rainPositions, 3));
  GameState.rainVelocities = rainVelocities;

  const rainMaterial = new THREE.PointsMaterial({
    color: 0xaaaaaa,
    size: 0.3,
    transparent: true,
    opacity: 0.6
  });

  GameState.rainSystem = new THREE.Points(rainGeometry, rainMaterial);
  GameState.rainSystem.visible = false;
  scene.add(GameState.rainSystem);
}

function updateWeather(deltaTime) {
  GameState.weatherTimer += deltaTime;

  // Change weather every 30-60 seconds
  if (GameState.weatherTimer > 30 + Math.random() * 30) {
    GameState.weatherTimer = 0;
    const weathers = ['clear', 'rain', 'fog', 'storm'];
    GameState.weather = weathers[Math.floor(Math.random() * weathers.length)];
    updateWeatherVisuals();
  }

  // Update time of day
  GameState.timeOfDay += deltaTime * 0.1;
  if (GameState.timeOfDay >= 24) GameState.timeOfDay -= 24;

  updateWeatherUI();
}

function updateWeatherVisuals() {
  const rainSystem = GameState.rainSystem;

  switch (GameState.weather) {
    case 'clear':
      rainSystem.visible = false;
      scene.fog.color.setHex(0x87CEEB);
      scene.background.setHex(0x87CEEB);
      scene.fog.density = 0.002;
      GameState.traction = 1.0;
      GameState.fuelConsumption = 0.02;
      break;

    case 'rain':
      rainSystem.visible = true;
      scene.fog.color.setHex(0x666688);
      scene.background.setHex(0x666688);
      scene.fog.density = 0.005;
      GameState.traction = 0.7;
      GameState.fuelConsumption = 0.03;
      break;

    case 'fog':
      rainSystem.visible = false;
      scene.fog.color.setHex(0xaaaaaa);
      scene.background.setHex(0xaaaaaa);
      scene.fog.density = 0.015;
      GameState.traction = 0.85;
      GameState.fuelConsumption = 0.025;
      break;

    case 'storm':
      rainSystem.visible = true;
      rainSystem.material.opacity = 0.8;
      scene.fog.color.setHex(0x444455);
      scene.background.setHex(0x444455);
      scene.fog.density = 0.02;
      GameState.traction = 0.5;
      GameState.fuelConsumption = 0.04;
      break;
  }

  // Adjust lighting based on weather
  if (GameState.sun) {
    switch (GameState.weather) {
      case 'clear':
        GameState.sun.intensity = 1.2;
        break;
      case 'rain':
        GameState.sun.intensity = 0.6;
        break;
      case 'fog':
        GameState.sun.intensity = 0.4;
        break;
      case 'storm':
        GameState.sun.intensity = 0.3;
        break;
    }
  }
}

function updateWeatherUI() {
  const weatherIcon = document.getElementById('weather-icon');
  const weatherText = document.getElementById('weather-text');

  switch (GameState.weather) {
    case 'clear':
      weatherIcon.textContent = '☀️';
      weatherText.textContent = 'Cerah';
      break;
    case 'rain':
      weatherIcon.textContent = '🌧️';
      weatherText.textContent = 'Hujan';
      break;
    case 'fog':
      weatherIcon.textContent = '🌫️';
      weatherText.textContent = 'Berkabut';
      break;
    case 'storm':
      weatherIcon.textContent = '⛈️';
      weatherText.textContent = 'Badai';
      break;
  }

  const hours = Math.floor(GameState.timeOfDay);
  const minutes = Math.floor((GameState.timeOfDay - hours) * 60);
  document.getElementById('time-display').textContent =
    `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
}

function updateRain(deltaTime) {
  if (!GameState.rainSystem || !GameState.rainSystem.visible) return;

  const positions = GameState.rainSystem.geometry.attributes.position.array;
  const velocities = GameState.rainVelocities;

  for (let i = 0; i < positions.length / 3; i++) {
    positions[i * 3 + 1] -= velocities[i] * 2 * deltaTime * 60;

    if (positions[i * 3 + 1] < 0) {
      positions[i * 3 + 1] = 100;
      positions[i * 3] = GameState.truckPosition.x + (Math.random() - 0.5) * 200;
      positions[i * 3 + 2] = GameState.truckPosition.z + (Math.random() - 0.5) * 200;
    }
  }

  GameState.rainSystem.geometry.attributes.position.needsUpdate = true;
}

// ==================== PHYSICS & MOVEMENT ====================
function updateTruck(deltaTime) {
  if (!GameState.running) return;

  const truck = GameState.truck;
  if (!truck) return;

  // Input handling
  const accelInput = GameState.keys['KeyW'] || GameState.keys['ArrowUp'] ? 1 : 0;
  const brakeInput = GameState.keys['KeyS'] || GameState.keys['ArrowDown'] ? 1 : 0;
  const leftInput = GameState.keys['KeyA'] || GameState.keys['ArrowLeft'] ? 1 : 0;
  const rightInput = GameState.keys['KeyD'] || GameState.keys['ArrowRight'] ? 1 : 0;

  GameState.handbrake = GameState.keys['Space'] || false;

  // Gear shifting
  if (GameState.keys['KeyQ']) {
    if (GameState.gear > -1) GameState.gear--;
    GameState.keys['KeyQ'] = false;
  }
  if (GameState.keys['KeyE']) {
    if (GameState.gear < 5) GameState.gear++;
    GameState.keys['KeyE'] = false;
  }

  // Ensure gear is valid
  if (GameState.gear < -1) GameState.gear = -1;
  if (GameState.gear > 5) GameState.gear = 5;

  // Calculate target speed based on gear
  const gearSpeeds = [-15, 0, 15, 30, 45, 55, 60];
  const targetSpeed = gearSpeeds[GameState.gear + 1] || 0;

  // Acceleration
  if (accelInput > 0) {
    if (GameState.gear === 0) {
      // Neutral - can't accelerate
    } else if (GameState.gear === -1) {
      // Reverse
      GameState.speed = Math.max(GameState.speed - GameState.acceleration * 0.5 * deltaTime * 60, -15);
    } else {
      GameState.speed = Math.min(
        GameState.speed + GameState.acceleration * GameState.engineLevel * deltaTime * 60,
        targetSpeed
      );
    }
  }

  // Braking
  if (brakeInput > 0) {
    GameState.speed = Math.max(GameState.speed - GameState.braking * deltaTime * 60, -5);
  }

  // Handbrake
  if (GameState.handbrake) {
    GameState.speed = Math.max(GameState.speed - 0.8 * deltaTime * 60, 0);
  }

  // Friction
  if (accelInput === 0 && brakeInput === 0 && !GameState.handbrake) {
    GameState.speed = Math.max(GameState.speed - GameState.friction * deltaTime * 60, 0);
  }

  // Apply slope effect
  GameState.speed -= GameState.slopeAngle * 0.1 * deltaTime * 60;

  // Apply traction effect
  GameState.speed *= (0.99 + GameState.traction * 0.001);

  // Fuel consumption
  if (accelInput > 0 && GameState.gear !== 0) {
    GameState.fuel -= GameState.fuelConsumption * deltaTime * 60 * (1 + GameState.load / GameState.maxLoad * 0.5);
    if (GameState.fuel <= 0) {
      GameState.fuel = 0;
      GameState.speed = Math.max(GameState.speed - 0.5 * deltaTime * 60, 0);
      document.getElementById('fuel-warning').style.display = 'block';
    } else {
      document.getElementById('fuel-warning').style.display = 'none';
    }
  }

  // Steering
  if (Math.abs(GameState.speed) > 0.1) {
    const steerAmount = GameState.steeringSpeed * (GameState.speed / GameState.maxSpeed) * 60 * deltaTime;
    if (leftInput) {
      GameState.truckRotation += steerAmount;
      GameState.steering = Math.min(GameState.steering + 0.1, 1);
    } else if (rightInput) {
      GameState.truckRotation -= steerAmount;
      GameState.steering = Math.max(GameState.steering - 0.1, -1);
    } else {
      GameState.steering *= 0.9;
    }
  }

  // Move truck
  const moveX = Math.sin(GameState.truckRotation) * GameState.speed * deltaTime * 60 * 0.1;
  const moveZ = Math.cos(GameState.truckRotation) * GameState.speed * deltaTime * 60 * 0.1;

  GameState.truckPosition.x += moveX;
  GameState.truckPosition.z += moveZ;

  // Check mud effects
  let inMud = false;
  GameState.mudPatches.forEach(patch => {
    const dist = GameState.truckPosition.distanceTo(patch.position);
    if (dist < patch.radius) {
      inMud = true;
      GameState.speed *= (1 - patch.effect * 0.01 * deltaTime * 60);
      GameState.mudEffect = Math.min(GameState.mudEffect + 0.05, 1);
    }
  });

  if (!inMud) {
    GameState.mudEffect = Math.max(GameState.mudEffect - 0.02, 0);
  }

  // Check bridge effects
  let onBridge = false;
  GameState.bridges.forEach(bridge => {
    const dist = GameState.truckPosition.distanceTo(bridge.position);
    if (dist < 15) {
      onBridge = true;
      // Narrow bridge - limit speed
      if (Math.abs(GameState.speed) > 20) {
        GameState.speed *= 0.98;
      }
    }
  });

  // Check barriers
  GameState.barriers.forEach(barrier => {
    const dist = GameState.truckPosition.distanceTo(barrier.position);
    if (dist < barrier.radius) {
      GameState.speed *= 0.5;
      // Push truck back
      GameState.truckPosition.x -= Math.sin(GameState.truckRotation) * 0.5;
      GameState.truckPosition.z -= Math.cos(GameState.truckRotation) * 0.5;
    }
  });

  // Update truck position
  truck.position.copy(GameState.truckPosition);
  truck.rotation.y = GameState.truckRotation;

  // Rotate wheels
  if (GameState.wheels) {
    GameState.wheels.forEach(wheel => {
      wheel.rotation.x += GameState.speed * deltaTime * 2;
    });
  }

  // Update cargo sway
  if (GameState.cargo) {
    GameState.cargo.position.x = Math.sin(GameState.truckRotation * 2) * 0.1 * Math.abs(GameState.speed) / 60;
    GameState.cargo.position.z = Math.cos(GameState.truckRotation) * 0.05 * Math.abs(GameState.speed) / 60;
  }

  // Calculate distance to factory
  const distToFactory = GameState.truckPosition.distanceTo(GameState.factoryPosition);
  GameState.distanceToFactory = distToFactory;
  document.getElementById('distance-to-factory').textContent = Math.round(distToFactory);

  // Check mission completion
  if (distToFactory < 15 && GameState.load > 0) {
    completeMission();
  }

  // Update total distance
  GameState.totalDistance += Math.abs(GameState.speed) * deltaTime * 0.1;

  // Update UI
  updateHUD();
}

function updateHUD() {
  // Speed
  document.getElementById('speed-value').textContent = Math.round(Math.abs(GameState.speed));

  // Gear
  const gearLabels = ['R', 'N', '1', '2', '3', '4', '5'];
  document.getElementById('gear-value').textContent = gearLabels[GameState.gear + 1] || 'N';

  // Fuel
  const fuelPercent = (GameState.fuel / GameState.maxFuel) * 100;
  document.getElementById('fuel-bar').style.width = fuelPercent + '%';
  document.getElementById('fuel-value').textContent = Math.round(fuelPercent) + '%';

  // Load
  const loadPercent = (GameState.load / GameState.maxLoad) * 100;
  document.getElementById('load-bar').style.width = loadPercent + '%';
  document.getElementById('load-value').textContent = GameState.load.toFixed(1) + ' ton';

  // Traction
  const tractionPercent = GameState.traction * 100;
  document.getElementById('traction-bar').style.width = tractionPercent + '%';
  document.getElementById('traction-value').textContent = Math.round(tractionPercent) + '%';

  // Money
  document.getElementById('money-display').textContent = '💰 Rp ' + GameState.money.toLocaleString('id-ID');

  // Upgrade costs
  document.getElementById('engine-cost').textContent = 'Rp ' + GameState.engineCost.toLocaleString('id-ID');
  document.getElementById('suspension-cost').textContent = 'Rp ' + GameState.suspensionCost.toLocaleString('id-ID');
  document.getElementById('tires-cost').textContent = 'Rp ' + GameState.tiresCost.toLocaleString('id-ID');
  document.getElementById('fueltank-cost').textContent = 'Rp ' + GameState.fuelTankCost.toLocaleString('id-ID');

  // Disable upgrade buttons if not enough money
  document.querySelectorAll('.upgrade-btn').forEach(btn => {
    const costText = btn.querySelector('.cost');
    if (costText) {
      const cost = parseInt(costText.textContent.replace(/[^0-9]/g, ''));
      btn.disabled = GameState.money < cost;
    }
  });
}

// ==================== CAMERA SYSTEM ====================
function updateCamera(deltaTime) {
  const truck = GameState.truck;
  if (!truck) return;

  switch (GameState.cameraMode) {
    case 0: // Third person
      const camDist = 12;
      const camHeight = 6;
      const targetX = truck.position.x - Math.sin(GameState.truckRotation) * camDist;
      const targetZ = truck.position.z - Math.cos(GameState.truckRotation) * camDist;
      camera.position.lerp(new THREE.Vector3(targetX, truck.position.y + camHeight, targetZ), 0.05);
      camera.lookAt(truck.position.x, truck.position.y + 2, truck.position.z);
      break;

    case 1: // Cabin view
      const cabinX = truck.position.x + Math.sin(GameState.truckRotation) * 3;
      const cabinZ = truck.position.z + Math.cos(GameState.truckRotation) * 3;
      camera.position.lerp(new THREE.Vector3(cabinX, truck.position.y + 3, cabinZ), 0.1);
      camera.lookAt(
        truck.position.x + Math.sin(GameState.truckRotation) * 20,
        truck.position.y + 2,
        truck.position.z + Math.cos(GameState.truckRotation) * 20
      );
      break;

    case 2: // Top down
      camera.position.lerp(new THREE.Vector3(
        truck.position.x,
        truck.position.y + 50,
        truck.position.z
      ), 0.05);
      camera.lookAt(truck.position);
      break;
  }
}

// ==================== MINIMAP ====================
function updateMinimap() {
  const ctx = GameState.minimapCtx;
  if (!ctx) return;

  ctx.clearRect(0, 0, 150, 150);

  // Background
  ctx.fillStyle = '#2a4a2a';
  ctx.fillRect(0, 0, 150, 150);

  // Scale factor
  const scale = 0.15;
  const centerX = 75;
  const centerY = 75;

  // Draw road
  ctx.strokeStyle = '#555';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(centerX + (0 - GameState.truckPosition.x) * scale, centerY + (0 - GameState.truckPosition.z) * scale);
  ctx.lineTo(centerX + (GameState.factoryPosition.x - GameState.truckPosition.x) * scale,
             centerY + (GameState.factoryPosition.z - GameState.truckPosition.z) * scale);
  ctx.stroke();

  // Draw factory
  ctx.fillStyle = '#ff4444';
  ctx.fillRect(
    centerX + (GameState.factoryPosition.x - GameState.truckPosition.x) * scale - 3,
    centerY + (GameState.factoryPosition.z - GameState.truckPosition.z) * scale - 3,
    6, 6
  );

  // Draw plantation
  ctx.fillStyle = '#44ff44';
  ctx.fillRect(
    centerX + (GameState.plantationPosition.x - GameState.truckPosition.x) * scale - 3,
    centerY + (GameState.plantationPosition.z - GameState.truckPosition.z) * scale - 3,
    6, 6
  );

  // Draw truck
  ctx.fillStyle = '#ffaa00';
  ctx.beginPath();
  ctx.arc(centerX, centerY, 4, 0, Math.PI * 2);
  ctx.fill();

  // Draw truck direction
  ctx.strokeStyle = '#ffaa00';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(centerX, centerY);
  ctx.lineTo(
    centerX + Math.sin(GameState.truckRotation) * 10,
    centerY + Math.cos(GameState.truckRotation) * 10
  );
  ctx.stroke();

  // Draw trees
  ctx.fillStyle = '#1a3a1a';
  GameState.trees.forEach(tree => {
    const dx = tree.position.x - GameState.truckPosition.x;
    const dz = tree.position.z - GameState.truckPosition.z;
    if (Math.abs(dx) < 100 && Math.abs(dz) < 100) {
      ctx.fillRect(
        centerX + dx * scale - 1,
        centerY + dz * scale - 1,
        2, 2
      );
    }
  });
}

// ==================== MISSION SYSTEM ====================
function completeMission() {
  if (!GameState.missionActive) return;

  GameState.missionActive = false;
  GameState.missionsCompleted++;

  const reward = 5000000 + Math.round(GameState.totalDistance * 100);
  GameState.money += reward;

  showMessage(
    '🎉 Misi Selesai!',
    `Anda berhasil mengantarkan ${GameState.load.toFixed(1)} ton tandan buah sawit ke pabrik!\n\nReward: Rp ${reward.toLocaleString('id-ID')}\nJarak tempuh: ${GameState.totalDistance.toFixed(0)} m\nMisi selesai: ${GameState.missionsCompleted}`
  );

  // Reset for next mission
  setTimeout(() => {
    resetMission();
  }, 3000);
}

function resetMission() {
  GameState.missionActive = true;
  GameState.load = 10 + Math.random() * 10;
  GameState.fuel = Math.min(GameState.fuel + 30, GameState.maxFuel);
  GameState.totalDistance = 0;
  GameState.truckPosition.set(0, 0, 0);
  GameState.truckRotation = 0;
  GameState.speed = 0;
  GameState.gear = 0;

  // Randomize factory position
  GameState.factoryPosition.set(
    150 + Math.random() * 200,
    0,
    -200 - Math.random() * 300
  );

  closeMessage();
}

function showMessage(title, text) {
  document.getElementById('msg-title').textContent = title;
  document.getElementById('msg-text').textContent = text;
  document.getElementById('message-popup').style.display = 'block';
}

function closeMessage() {
  document.getElementById('message-popup').style.display = 'none';
}

// ==================== UPGRADE SYSTEM ====================
function upgradeEngine() {
  if (GameState.money >= GameState.engineCost) {
    GameState.money -= GameState.engineCost;
    GameState.engineLevel++;
    GameState.maxSpeed += 10;
    GameState.acceleration += 0.05;
    GameState.engineCost = Math.round(GameState.engineCost * 1.5);
    updateHUD();
    showMessage('⚙️ Mesin Upgraded!', `Mesin level ${GameState.engineLevel}\nKecepatan maksimum: ${GameState.maxSpeed} km/h\nAkselerasi meningkat!`);
  }
}

function upgradeSuspension() {
  if (GameState.money >= GameState.suspensionCost) {
    GameState.money -= GameState.suspensionCost;
    GameState.suspensionLevel++;
    GameState.traction += 0.1;
    GameState.suspensionCost = Math.round(GameState.suspensionCost * 1.5);
    updateHUD();
    showMessage('🔩 Suspensi Upgraded!', `Suspensi level ${GameState.suspensionLevel}\nTraksi meningkat!\nKontrol lebih baik di jalan berlumpur.`);
  }
}

function upgradeTires() {
  if (GameState.money >= GameState.tiresCost) {
    GameState.money -= GameState.tiresCost;
    GameState.tiresLevel++;
    GameState.traction += 0.15;
    GameState.tiresCost = Math.round(GameState.tiresCost * 1.5);
    updateHUD();
    showMessage('🛞 Ban Upgraded!', `Ban level ${GameState.tiresLevel}\nTraksi meningkat signifikan!\nLebih baik di hujan dan lumpur.`);
  }
}

function upgradeFuelTank() {
  if (GameState.money >= GameState.fuelTankCost) {
    GameState.money -= GameState.fuelTankCost;
    GameState.fuelTankLevel++;
    GameState.maxFuel += 20;
    GameState.fuel = GameState.maxFuel;
    GameState.fuelTankCost = Math.round(GameState.fuelTankCost * 1.5);
    updateHUD();
    showMessage('⛽ Tangki BBM Upgraded!', `Tangki level ${GameState.fuelTankLevel}\nKapasitas BBM: ${GameState.maxFuel} liter\nBBM terisi penuh!`);
  }
}

function closeUpgrade() {
  document.getElementById('upgrade-panel').style.display = 'none';
}

function toggleUpgrade() {
  const panel = document.getElementById('upgrade-panel');
  panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
}

// ==================== FUEL REFILL ====================
function refuel() {
  if (GameState.fuel < GameState.maxFuel) {
    const refuelAmount = 30;
    GameState.fuel = Math.min(GameState.fuel + refuelAmount, GameState.maxFuel);
    GameState.money -= 50000;
    updateHUD();
  }
}

// ==================== INPUT HANDLING ====================
function initInput() {
  document.addEventListener('keydown', (e) => {
    GameState.keys[e.code] = true;

    if (e.code === 'KeyC') {
      GameState.cameraMode = (GameState.cameraMode + 1) % 3;
    }

    if (e.code === 'KeyU') {
      toggleUpgrade();
    }

    if (e.code === 'KeyF') {
      refuel();
    }
  });

  document.addEventListener('keyup', (e) => {
    GameState.keys[e.code] = false;
  });
}

// ==================== GAME LOOP ====================
function gameLoop() {
  requestAnimationFrame(gameLoop);

  const deltaTime = Math.min(clock.getDelta(), 0.05);

  if (GameState.running) {
    updateTruck(deltaTime);
    updateCamera(deltaTime);
    updateWeather(deltaTime);
    updateRain(deltaTime);
    updateMinimap();
  }

  renderer.render(scene, camera);
}

// ==================== START GAME ====================
function startGame() {
  document.getElementById('start-screen').style.display = 'none';
  GameState.running = true;

  initThreeJS();
  generateTerrain();
  generateTruck();
  initWeather();
  initInput();

  // Set initial load
  GameState.load = 15;

  gameLoop();
}

// Auto-start if Three.js loads
window.addEventListener('load', () => {
  // Show start screen
});
</script>
</body>
