<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// Game State
const gameState = {
running: false,
health: 100,
maxHealth: 100,
ammo: 30,
maxAmmo: 30,
reserveAmmo: 120,
score: 0,
kills: 0,
deaths: 0,
wave: 1,
isReloading: false,
isSprinting: false,
isJumping: false,
jumpVelocity: 0,
playerHeight: 1.7,
speed: 0.15,
sprintSpeed: 0.25,
mouseSensitivity: 0.002,
invincible: false
};

// Three.js Setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.Fog(0x87CEEB, 50, 200);

const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, gameState.playerHeight, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// Audio Context
const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

function playSound(type) {
const osc = audioCtx.createOscillator();
const gain = audioCtx.createGain();
osc.connect(gain);
gain.connect(audioCtx.destination);

switch(type) {
case 'shoot':
osc.frequency.setValueAtTime(150, audioCtx.currentTime);
osc.frequency.exponentialRampToValueAtTime(50, audioCtx.currentTime + 0.1);
gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);
osc.start(audioCtx.currentTime);
osc.stop(audioCtx.currentTime + 0.1);
break;
case 'hit':
osc.frequency.setValueAtTime(800, audioCtx.currentTime);
osc.frequency.exponentialRampToValueAtTime(200, audioCtx.currentTime + 0.15);
gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.15);
osc.start(audioCtx.currentTime);
osc.stop(audioCtx.currentTime + 0.15);
break;
case 'kill':
osc.frequency.setValueAtTime(600, audioCtx.currentTime);
osc.frequency.exponentialRampToValueAtTime(1200, audioCtx.currentTime + 0.2);
gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.2);
osc.start(audioCtx.currentTime);
osc.stop(audioCtx.currentTime + 0.2);
break;
case 'reload':
osc.frequency.setValueAtTime(400, audioCtx.currentTime);
osc.frequency.setValueAtTime(600, audioCtx.currentTime + 0.1);
osc.frequency.setValueAtTime(800, audioCtx.currentTime + 0.2);
gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);
osc.start(audioCtx.currentTime);
osc.stop(audioCtx.currentTime + 0.3);
break;
case 'damage':
osc.frequency.setValueAtTime(100, audioCtx.currentTime);
osc.frequency.exponentialRampToValueAtTime(50, audioCtx.currentTime + 0.2);
gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.2);
osc.start(audioCtx.currentTime);
osc.stop(audioCtx.currentTime + 0.2);
break;
case 'headshot':
osc.frequency.setValueAtTime(1000, audioCtx.currentTime);
osc.frequency.exponentialRampToValueAtTime(2000, audioCtx.currentTime + 0.1);
gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.15);
osc.start(audioCtx.currentTime);
osc.stop(audioCtx.currentTime + 0.15);
break;
}
}

// Lighting
const ambientLight = new THREE.AmbientLight(0x404040, 0.6);
scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0xffffff, 0.8);
sunLight.position.set(50, 100, 50);
sunLight.castShadow = true;
sunLight.shadow.mapSize.width = 2048;
sunLight.shadow.mapSize.height = 2048;
sunLight.shadow.camera.near = 0.5;
sunLight.shadow.camera.far = 500;
sunLight.shadow.camera.left = -100;
sunLight.shadow.camera.right = 100;
sunLight.shadow.camera.top = 100;
sunLight.shadow.camera.bottom = -100;
scene.add(sunLight);

const hemiLight = new THREE.HemisphereLight(0x87CEEB, 0x362907, 0.4);
scene.add(hemiLight);

// Materials
const groundMat = new THREE.MeshStandardMaterial({ color: 0x3d5c3d, roughness: 0.8 });
const wallMat = new THREE.MeshStandardMaterial({ color: 0x8B7355, roughness: 0.7 });
const concreteMat = new THREE.MeshStandardMaterial({ color: 0x808080, roughness: 0.6 });
const metalMat = new THREE.MeshStandardMaterial({ color: 0x4a4a4a, roughness: 0.3, metalness: 0.8 });
const woodMat = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.9 });
const enemyMat = new THREE.MeshStandardMaterial({ color: 0x8B0000, roughness: 0.5 });
const enemyHeadMat = new THREE.MeshStandardMaterial({ color: 0xFFDBAC, roughness: 0.5 });
const windowMat = new THREE.MeshStandardMaterial({ color: 0x1a1a2e, roughness: 0.1, metalness: 0.5 });

// Map Generation
const mapObjects = [];
const enemySpawnPoints = [];
const waypoints = [];

function createBox(x, y, z, w, h, d, material, castShadow = true) {
const geo = new THREE.BoxGeometry(w, h, d);
const mesh = new THREE.Mesh(geo, material);
mesh.position.set(x, y + h/2, z);
mesh.castShadow = castShadow;
mesh.receiveShadow = true;
scene.add(mesh);
mapObjects.push(mesh);
return mesh;
}

// Ground
const groundGeo = new THREE.PlaneGeometry(300, 300);
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Road
createBox(0, 0, 0, 10, 0.1, 300, new THREE.MeshStandardMaterial({ color: 0x333333 }));
createBox(0, 0, 0, 0.2, 0.15, 300, new THREE.MeshStandardMaterial({ color: 0xffff00 }));

// Buildings
function createBuilding(x, z, w, h, d, floors) {
const buildingGroup = new THREE.Group();

// Main structure
const mainGeo = new THREE.BoxGeometry(w, h, d);
const mainMesh = new THREE.Mesh(mainGeo, concreteMat);
mainMesh.position.set(x, h/2, z);
mainMesh.castShadow = true;
mainMesh.receiveShadow = true;
scene.add(mainMesh);
mapObjects.push(mainMesh);

// Windows
const windowSize = 1.5;
const windowSpacing = 4;
for (let floor = 0; floor < floors; floor++) {
for (let wx = -w/2 + 2; wx < w/2 - 1; wx += windowSpacing) {
for (let side = 0; side < 4; side++) {
const winGeo = new THREE.PlaneGeometry(windowSize, windowSize);
const winMesh = new THREE.Mesh(winGeo, windowMat);

if (side === 0) { winMesh.position.set(x + wx, floor * 3 + 2, z + d/2 + 0.01); }
else if (side === 1) { winMesh.position.set(x + wx, floor * 3 + 2, z - d/2 - 0.01); winMesh.rotation.y = Math.PI; }
else if (side === 2) { winMesh.position.set(x + w/2 + 0.01, floor * 3 + 2, z + wx); winMesh.rotation.y = Math.PI/2; }
else { winMesh.position.set(x - w/2 - 0.01, floor * 3 + 2, z + wx); winMesh.rotation.y = -Math.PI/2; }

scene.add(winMesh);
}
}
}

// Roof
const roofGeo = new THREE.BoxGeometry(w + 1, 0.5, d + 1);
const roofMesh = new THREE.Mesh(roofGeo, metalMat);
roofMesh.position.set(x, h + 0.25, z);
roofMesh.castShadow = true;
scene.add(roofMesh);
mapObjects.push(roofMesh);

// Spawn point on roof
enemySpawnPoints.push(new THREE.Vector3(x, h + 0.5, z));

return buildingGroup;
}

// Create buildings
createBuilding(-40, -40, 20, 15, 20, 5);
createBuilding(40, -40, 25, 12, 18, 4);
createBuilding(-40, 40, 18, 18, 22, 6);
createBuilding(40, 40, 22, 10, 20, 3);
createBuilding(0, -80, 30, 8, 15, 3);
createBuilding(0, 80, 20, 14, 25, 4);
createBuilding(-80, 0, 15, 10, 30, 3);
createBuilding(80, 0, 18, 12, 20, 4);
createBuilding(-60, -70, 12, 8, 12, 2);
createBuilding(60, -70, 14, 10, 14, 3);
createBuilding(-60, 70, 16, 9, 16, 3);
createBuilding(60, 70, 12, 11, 12, 3);

// Walls and barriers
for (let i = 0; i < 20; i++) {
const x = (Math.random() - 0.5) * 200;
const z = (Math.random() - 0.5) * 200;
const w = Math.random() * 8 + 2;
const h = Math.random() * 3 + 1;
const d = Math.random() * 2 + 0.5;
createBox(x, 0, z, w, h, d, wallMat);
}

// Crates
for (let i = 0; i < 30; i++) {
const x = (Math.random() - 0.5) * 180;
const z = (Math.random() - 0.5) * 180;
const size = Math.random() * 2 + 1;
createBox(x, 0, z, size, size, size, woodMat);
}

// Sandbags
for (let i = 0; i < 15; i++) {
const x = (Math.random() - 0.5) * 160;
const z = (Math.random() - 0.5) * 160;
createBox(x, 0.5, z, 4, 1, 1.5, new THREE.MeshStandardMaterial({ color: 0xC2B280 }));
}

// Trees
function createTree(x, z) {
const trunkGeo = new THREE.CylinderGeometry(0.3, 0.5, 4, 8);
const trunkMat = new THREE.MeshStandardMaterial({ color: 0x4a3728 });
const trunk = new THREE.Mesh(trunkGeo, trunkMat);
trunk.position.set(x, 2, z);
trunk.castShadow = true;
scene.add(trunk);
mapObjects.push(trunk);

const leavesGeo = new THREE.SphereGeometry(3, 8, 8);
const leavesMat = new THREE.MeshStandardMaterial({ color: 0x2d5a27 });
const leaves = new THREE.Mesh(leavesGeo, leavesMat);
leaves.position.set(x, 5, z);
leaves.castShadow = true;
scene.add(leaves);
mapObjects.push(leaves);
}

for (let i = 0; i < 40; i++) {
const x = (Math.random() - 0.5) * 250;
const z = (Math.random() - 0.5) * 250;
if (Math.abs(x) > 15 || Math.abs(z) > 15) {
createTree(x, z);
}
}

// Waypoints for AI
for (let i = 0; i < 20; i++) {
waypoints.push(new THREE.Vector3(
(Math.random() - 0.5) * 200,
0,
(Math.random() - 0.5) * 200
));
}

// Enemies
const enemies = [];
const enemyBullets = [];

class Enemy {
constructor(x, y, z) {
this.health = 100;
this.maxHealth = 100;
this.speed = 0.05 + Math.random() * 0.03;
this.damage = 10 + Math.random() * 10;
this.shootCooldown = 0;
this.shootRate = 60 + Math.random() * 60;
this.state = 'patrol'; // patrol, chase, attack
this.targetWaypoint = waypoints[Math.floor(Math.random() * waypoints.length)];
this.alertRange = 40;
this.attackRange = 30;
this.lastSeenPlayer = null;
this.isDead = false;
this.deathTimer = 0;
this.regenTimer = 0;

// Body
this.group = new THREE.Group();

// Torso
const torsoGeo = new THREE.BoxGeometry(1, 1.5, 0.6);
this.torso = new THREE.Mesh(torsoGeo, enemyMat);
this.torso.position.y = 1.5;
this.torso.castShadow = true;
this.group.add(this.torso);

// Head
const headGeo = new THREE.SphereGeometry(0.35, 8, 8);
this.head = new THREE.Mesh(headGeo, enemyHeadMat);
this.head.position.y = 2.5;
this.head.castShadow = true;
this.group.add(this.head);

// Helmet
const helmetGeo = new THREE.SphereGeometry(0.4, 8, 4, 0, Math.PI * 2, 0, Math.PI/2);
const helmetMat = new THREE.MeshStandardMaterial({ color: 0x2d4a2d });
this.helmet = new THREE.Mesh(helmetGeo, helmetMat);
this.helmet.position.y = 2.55;
this.group.add(this.helmet);

// Arms
const armGeo = new THREE.BoxGeometry(0.3, 1.2, 0.3);
this.leftArm = new THREE.Mesh(armGeo, enemyMat);
this.leftArm.position.set(-0.7, 1.5, 0);
this.group.add(this.leftArm);

this.rightArm = new THREE.Mesh(armGeo, enemyMat);
this.rightArm.position.set(0.7, 1.5, 0);
this.group.add(this.rightArm);

// Legs
const legGeo = new THREE.BoxGeometry(0.35, 1.2, 0.35);
this.leftLeg = new THREE.Mesh(legGeo, new THREE.MeshStandardMaterial({ color: 0x3d3d3d }));
this.leftLeg.position.set(-0.3, 0.6, 0);
this.group.add(this.leftLeg);

this.rightLeg = new THREE.Mesh(legGeo, new THREE.MeshStandardMaterial({ color: 0x3d3d3d }));
this.rightLeg.position.set(0.3, 0.6, 0);
this.group.add(this.rightLeg);

// Weapon
const gunGeo = new THREE.BoxGeometry(0.15, 0.15, 1.2);
const gunMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a });
this.gun = new THREE.Mesh(gunGeo, gunMat);
this.gun.position.set(0.7, 1.5, 0.5);
this.group.add(this.gun);

this.group.position.set(x, y, z);
scene.add(this.group);

this.velocity = new THREE.Vector3();
this.animationTime = Math.random() * Math.PI * 2;
}

update(playerPos) {
if (this.isDead) {
this.deathTimer++;
if (this.deathTimer < 60) {
this.group.rotation.x = Math.min(this.deathTimer * 0.05, Math.PI / 2);
this.group.position.y -= 0.01;
} else if (this.deathTimer < 300) {
this.group.visible = false;
} else {
this.respawn();
}
return;
}

this.animationTime += 0.05;

const distToPlayer = this.group.position.distanceTo(playerPos);

// State machine
if (distToPlayer < this.alertRange) {
this.state = 'chase';
this.lastSeenPlayer = playerPos.clone();
}

if (distToPlayer < this.attackRange && this.lastSeenPlayer) {
this.state = 'attack';
}

if (distToPlayer > this.alertRange * 1.5) {
this.state = 'patrol';
}

// Movement
let moveDir = new THREE.Vector3();

switch(this.state) {
case 'patrol':
if (this.group.position.distanceTo(this.targetWaypoint) < 5) {
this.targetWaypoint = waypoints[Math.floor(Math.random() * waypoints.length)];
}
moveDir.copy(this.targetWaypoint).sub(this.group.position).normalize();
break;

case 'chase':
if (this.lastSeenPlayer) {
moveDir.copy(this.lastSeenPlayer).sub(this.group.position).normalize();
}
break;

case 'attack':
if (this.lastSeenPlayer) {
const dir = this.lastSeenPlayer.clone().sub(this.group.position);
const dist = dir.length();
if (dist > 15) {
moveDir.copy(dir).normalize();
} else if (dist < 10) {
moveDir.copy(dir).normalize().multiplyScalar(-1);
}
// Aim at player
this.group.lookAt(playerPos.x, this.group.position.y, playerPos.z);
}
break;
}

// Apply movement
if (moveDir.length() > 0) {
moveDir.normalize().multiplyScalar(this.speed);
this.group.position.x += moveDir.x;
this.group.position.z += moveDir.z;

// Animation
this.leftLeg.position.y = 0.6 + Math.sin(this.animationTime) * 0.2;
this.rightLeg.position.y = 0.6 + Math.sin(this.animationTime + Math.PI) * 0.2;
this.leftArm.position.y = 1.5 + Math.sin(this.animationTime + Math.PI) * 0.15;
this.rightArm.position.y = 1.5 + Math.sin(this.animationTime) * 0.15;
}

// Shooting
this.shootCooldown++;
if (this.state === 'attack' && this.shootCooldown >= this.shootRate && distToPlayer < this.attackRange) {
this.shootCooldown = 0;
this.shoot(playerPos);
}

// Keep on ground
this.group.position.y = 0;

// Boundary check
this.group.position.x = Math.max(-140, Math.min(140, this.group.position.x));
this.group.position.z = Math.max(-140, Math.min(140, this.group.position.z));
}

shoot(playerPos) {
const dir = playerPos.clone().sub(this.group.position).normalize();
dir.y = 0;

// Add inaccuracy
dir.x += (Math.random() - 0.5) * 0.1;
dir.z += (Math.random() - 0.5) * 0.1;
dir.normalize();

const bulletGeo = new THREE.SphereGeometry(0.1, 4, 4);
const bulletMat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
const bullet = new THREE.Mesh(bulletGeo, bulletMat);
bullet.position.copy(this.group.position);
bullet.position.y = 1.5;
scene.add(bullet);

enemyBullets.push({
mesh: bullet,
direction: dir,
speed: 0.8,
life: 100,
damage: this.damage
});

playSound('shoot');
}

takeDamage(amount, isHeadshot = false) {
if (this.isDead) return;

const actualDamage = isHeadshot ? amount * 2.5 : amount;
this.health -= actualDamage;

if (isHeadshot) {
playSound('headshot');
showHeadshotIndicator();
} else {
playSound('hit');
}

if (this.health <= 0) {
this.die();
}
}

die() {
this.isDead = true;
this.deathTimer = 0;
gameState.kills++;
gameState.score += 100;
updateHUD();
addKillFeed('You', 'Enemy');
playSound('kill');

// Drop ammo
createAmmoDrop(this.group.position.clone());
}

respawn() {
this.isDead = false;
this.deathTimer = 0;
this.health = this.maxHealth;
this.group.visible = true;
this.group.rotation.x = 0;
this.group.position.set(
(Math.random() - 0.5) * 200,
0,
(Math.random() - 0.5) * 200
);
this.state = 'patrol';
this.targetWaypoint = waypoints[Math.floor(Math.random() * waypoints.length)];
}
}

// Ammo drops
const ammoDrops = [];

function createAmmoDrop(position) {
const geo = new THREE.BoxGeometry(0.5, 0.5, 0.5);
const mat = new THREE.MeshStandardMaterial({ color: 0xffaa00 });
const mesh = new THREE.Mesh(geo, mat);
mesh.position.copy(position);
mesh.position.y = 0.5;
scene.add(mesh);
ammoDrops.push({ mesh, amount: 30 });
}

// Player controls
const keys = {};
let mouseX = 0, mouseY = 0;
let pitch = 0, yaw = 0;

document.addEventListener('keydown', (e) => {
keys[e.code] = true;
if (e.code === 'KeyR' && !gameState.isReloading) {
reload();
}
if (e.code === 'ShiftLeft') {
gameState.isSprinting = true;
}
if (e.code === 'Space' && !gameState.isJumping) {
gameState.isJumping = true;
gameState.jumpVelocity = 0.3;
}
});

document.addEventListener('keyup', (e) => {
keys[e.code] = false;
if (e.code === 'ShiftLeft') {
gameState.isSprinting = false;
}
});

document.addEventListener('mousemove', (e) => {
if (gameState.running) {
yaw -= e.movementX * gameState.mouseSensitivity;
pitch -= e.movementY * gameState.mouseSensitivity;
pitch = Math.max(-Math.PI/2 + 0.1, Math.min(Math.PI/2 - 0.1, pitch));
}
});

document.addEventListener('mousedown', (e) => {
if (e.button === 0 && gameState.running) {
shoot();
}
});

// Shooting
let lastShot = 0;
const fireRate = 100; // ms between shots

function shoot() {
const now = Date.now();
if (now - lastShot < fireRate || gameState.isReloading || gameState.ammo <= 0) {
if (gameState.ammo <= 0 && !gameState.isReloading) {
reload();
}
return;
}

lastShot = now;
gameState.ammo--;
updateHUD();
playSound('shoot');

// Raycasting
const raycaster = new THREE.Raycaster();
raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);

// Add recoil
pitch += 0.02;

// Check enemy hits
let hitEnemy = false;
for (const enemy of enemies) {
if (enemy.isDead) continue;

const enemyPos = enemy.group.position.clone();
enemyPos.y += 1.5;

const toEnemy = enemyPos.clone().sub(camera.position).normalize();
const dot = raycaster.ray.direction.dot(toEnemy);

if (dot > 0.95) {
const dist = camera.position.distanceTo(enemyPos);
if (dist < 100) {
// Check if hit head
const headPos = enemy.group.position.clone();
headPos.y += 2.5;
const toHead = headPos.clone().sub(camera.position).normalize();
const headDot = raycaster.ray.direction.dot(toHead);

if (headDot > 0.9) {
enemy.takeDamage(35, true);
} else {
enemy.takeDamage(25, false);
}
hitEnemy = true;
break;
}
}
}

// Muzzle flash
createMuzzleFlash();

// Auto reload
if (gameState.ammo <= 0) {
reload();
}
}

function createMuzzleFlash() {
const flashGeo = new THREE.SphereGeometry(0.1, 4, 4);
const flashMat = new THREE.MeshBasicMaterial({ color: 0xffff00 });
const flash = new THREE.Mesh(flashGeo, flashMat);
flash.position.copy(camera.position);
flash.position.y -= 0.1;

const dir = new THREE.Vector3(0, 0, -1);
dir.applyQuaternion(camera.quaternion);
flash.position.add(dir.multiplyScalar(1));
scene.add(flash);

setTimeout(() => scene.remove(flash), 50);
}

function reload() {
if (gameState.isReloading || gameState.ammo === gameState.maxAmmo || gameState.reserveAmmo <= 0) return;

gameState.isReloading = true;
playSound('reload');

document.getElementById('reload-bar').style.display = 'block';
document.getElementById('reload-text').style.display = 'block';

let reloadProgress = 0;
const reloadTime = 2000;
const startTime = Date.now();

const reloadInterval = setInterval(() => {
reloadProgress = Date.now() - startTime;
const percent = Math.min(reloadProgress / reloadTime * 100, 100);
document.getElementById('reload-fill').style.width = percent + '%';

if (reloadProgress >= reloadTime) {
clearInterval(reloadInterval);
const needed = gameState.maxAmmo - gameState.ammo;
const available = Math.min(needed, gameState.reserveAmmo);
gameState.ammo += available;
gameState.reserveAmmo -= available;
gameState.isReloading = false;
document.getElementById('reload-bar').style.display = 'none';
document.getElementById('reload-text').style.display = 'none';
updateHUD();
}
}, 50);
}

function showHeadshotIndicator() {
const indicator = document.getElementById('headshot-indicator');
indicator.style.display = 'block';
indicator.style.animation = 'none';
indicator.offsetHeight; // Trigger reflow
indicator.style.animation = 'headshotAnim 0.5s forwards';
setTimeout(() => { indicator.style.display = 'none'; }, 500);
gameState.score += 50;
}

function addKillFeed(killer, victim) {
const feed = document.getElementById('kill-feed');
const entry = document.createElement('div');
entry.className = 'kill-entry';
entry.textContent = `${killer} eliminated ${victim}`;
feed.appendChild(entry);
setTimeout(() => entry.remove(), 3000);
}

function updateHUD() {
document.getElementById('health-fill').style.width = (gameState.health / gameState.maxHealth * 100) + '%';
document.getElementById('ammo-current').textContent = gameState.ammo;
document.getElementById('ammo-reserve').textContent = gameState.reserveAmmo;
document.getElementById('kill-count').textContent = gameState.kills;
document.getElementById('death-count').textContent = gameState.deaths;
document.getElementById('score').textContent = gameState.score;
}

function takeDamage(amount) {
if (gameState.invincible) return;
gameState.health -= amount;
gameState.invincible = true;
setTimeout(() => { gameState.invincible = false; }, 500);

document.getElementById('damage-overlay').style.opacity = '1';
setTimeout(() => {
document.getElementById('damage-overlay').style.opacity = '0';
}, 200);

playSound('damage');

if (gameState.health <= 0) {
gameOver();
}
updateHUD();
}

function gameOver() {
gameState.running = false;
gameState.deaths++;
document.exitPointerLock();
document.getElementById('game-over').style.display = 'flex';
document.getElementById('final-kills').textContent = gameState.kills;
document.getElementById('final-score').textContent = gameState.score;
document.getElementById('final-wave').textContent = gameState.wave;
}

// Minimap
const minimapCanvas = document.getElementById('minimap-canvas');
const minimapCtx = minimapCanvas.getContext('2d');

function updateMinimap() {
minimapCtx.clearRect(0, 0, 200, 200);

// Background
minimapCtx.fillStyle = 'rgba(0,50,0,0.5)';
minimapCtx.fillRect(0, 0, 200, 200);

// Scale
const scale = 0.6;
const centerX = 100;
const centerY = 100;

// Draw buildings
minimapCtx.fillStyle = 'rgba(100,100,100,0.8)';
mapObjects.forEach(obj => {
if (obj.geometry && obj.geometry.parameters) {
const w = obj.geometry.parameters.width || 0;
const d = obj.geometry.parameters.depth || 0;
const x = (obj.position.x - camera.position.x) * scale + centerX;
const z = (obj.position.z - camera.position.z) * scale + centerY;
if (x > -20 && x < 220 && z > -20 && z < 220) {
minimapCtx.fillRect(x - w*scale/2, z - d*scale/2, w*scale, d*scale);
}
}
});

// Draw enemies
enemies.forEach(enemy => {
if (!enemy.isDead) {
const x = (enemy.group.position.x - camera.position.x) * scale + centerX;
const z = (enemy.group.position.z - camera.position.z) * scale + centerY;
if (x > 0 && x < 200 && z > 0 && z < 200) {
minimapCtx.fillStyle = '#ff0000';
minimapCtx.beginPath();
minimapCtx.arc(x, z, 3, 0, Math.PI * 2);
minimapCtx.fill();
}
}
});

// Draw player
minimapCtx.fillStyle = '#00ff00';
minimapCtx.beginPath();
minimapCtx.arc(centerX, centerY, 4, 0, Math.PI * 2);
minimapCtx.fill();

// Player direction
const dirX = Math.sin(yaw) * 10;
const dirZ = -Math.cos(yaw) * 10;
minimapCtx.strokeStyle = '#00ff00';
minimapCtx.lineWidth = 2;
minimapCtx.beginPath();
minimapCtx.moveTo(centerX, centerY);
minimapCtx.lineTo(centerX + dirX, centerY + dirZ);
minimapCtx.stroke();

// Border
minimapCtx.strokeStyle = 'rgba(255,255,255,0.3)';
minimapCtx.lineWidth = 2;
minimapCtx.beginPath();
minimapCtx.arc(100, 100, 98, 0, Math.PI * 2);
minimapCtx.stroke();
}

// Wave system
function spawnWave() {
const enemyCount = 5 + gameState.wave * 3;
for (let i = 0; i < enemyCount; i++) {
const x = (Math.random() - 0.5) * 200;
const z = (Math.random() - 0.5) * 200;
if (Math.abs(x) > 20 || Math.abs(z) > 20) {
enemies.push(new Enemy(x, 0, z));
}
}

const waveDisplay = document.getElementById('wave-display');
document.getElementById('wave-num').textContent = gameState.wave;
waveDisplay.style.display = 'block';
setTimeout(() => { waveDisplay.style.display = 'none'; }, 2000);
}

// Initial wave
spawnWave();

// Game loop
function animate() {
requestAnimationFrame(animate);

if (!gameState.running) {
renderer.render(scene, camera);
return;
}

// Player movement
const speed = gameState.isSprinting ? gameState.sprintSpeed : gameState.speed;
const moveDir = new THREE.Vector3();

if (keys['KeyW']) moveDir.z -= 1;
if (keys['KeyS']) moveDir.z += 1;
if (keys['KeyA']) moveDir.x -= 1;
if (keys['KeyD']) moveDir.x += 1;

if (moveDir.length() > 0) {
moveDir.normalize().multiplyScalar(speed);

// Apply yaw rotation
const sinYaw = Math.sin(yaw);
const cosYaw = Math.cos(yaw);
const newX = moveDir.x * cosYaw - moveDir.z * sinYaw;
const newZ = moveDir.x * sinYaw + moveDir.z * cosYaw;

camera.position.x += newX;
camera.position.z += newZ;
}

// Jump
if (gameState.isJumping) {
gameState.jumpVelocity -= 0.015;
camera.position.y += gameState.jumpVelocity;
if (camera.position.y <= gameState.playerHeight) {
camera.position.y = gameState.playerHeight;
gameState.isJumping = false;
gameState.jumpVelocity = 0;
}
}

// Boundary
camera.position.x = Math.max(-145, Math.min(145, camera.position.x));
camera.position.z = Math.max(-145, Math.min(145, camera.position.z));

// Camera rotation
camera.rotation.order = 'YXZ';
camera.rotation.y = yaw;
camera.rotation.x = pitch;

// Update enemies
enemies.forEach(enemy => enemy.update(camera.position));

// Update enemy bullets
for (let i = enemyBullets.length - 1; i >= 0; i--) {
const bullet = enemyBullets[i];
bullet.mesh.position.add(bullet.direction.clone().multiplyScalar(bullet.speed));
bullet.life--;

// Check if hits player
const distToPlayer = bullet.mesh.position.distanceTo(camera.position);
if (distToPlayer < 1) {
takeDamage(bullet.damage);
scene.remove(bullet.mesh);
enemyBullets.splice(i, 1);
continue;
}

// Check if hits map objects
let hitMap = false;
for (const obj of mapObjects) {
const box = new THREE.Box3().setFromObject(obj);
if (box.containsPoint(bullet.mesh.position)) {
hitMap = true;
break;
}
}

if (hitMap || bullet.life <= 0) {
scene.remove(bullet.mesh);
enemyBullets.splice(i, 1);
}
}

// Check ammo drops
for (let i = ammoDrops.length - 1; i >= 0; i--) {
const drop = ammoDrops[i];
const dist = camera.position.distanceTo(drop.mesh.position);
if (dist < 3) {
gameState.reserveAmmo += drop.amount;
updateHUD();
scene.remove(drop.mesh);
ammoDrops.splice(i, 1);
}
}

// Wave progression
if (enemies.filter(e => !e.isDead).length === 0) {
gameState.wave++;
spawnWave();
}

// Update minimap
updateMinimap();

// Render
renderer.render(scene, camera);
}

// Start game
document.getElementById('startBtn').addEventListener('click', () => {
document.getElementById('blocker').style.display = 'none';
renderer.domElement.requestPointerLock();
gameState.running = true;
audioCtx.resume();
});

document.addEventListener('pointerlockchange', () => {
if (document.pointerLockElement === renderer.domElement) {
gameState.running = true;
} else {
gameState.running = false;
}
});

window.addEventListener('resize', () => {
camera.aspect = window.innerWidth / window.innerHeight;
camera.updateProjectionMatrix();
renderer.setSize(window.innerWidth, window.innerHeight);
});

animate();
</script>
