    border-color: transparent;
  }

  .mode-btn:hover {
    background: rgba(255, 255, 255, 0.15);
    color: #fff;
  }

  .mode-btn.active:hover {
    background: linear-gradient(135deg, #667eea, #764ba2);
  }

  .display {
    background: rgba(0, 0, 0, 0.3);
