    <button class="btn btn-function" onclick="inputFunction('asin(')">sin⁻¹</button>
    <button class="btn btn-function" onclick="inputFunction('acos(')">cos⁻¹</button>

    <button class="btn btn-function" onclick="inputFunction('atan(')">tan⁻¹</button>
    <button class="btn btn-function" onclick="inputFunction('log(')">log</button>
    <button class="btn btn-function" onclick="inputFunction('ln(')">ln</button>
