    <button class="btn btn-function" onclick="inputFunction('cbrt(')">∛</button>

    <button class="btn btn-function" onclick="inputText('π')">π</button>
    <button class="btn btn-function" onclick="inputText('e')">e</button>
    <button class="btn btn-function" onclick="inputFunction('fact(')">n!</button>
    <button class="btn btn-function" onclick="inputText('^2')">x²</button>
    <button class="btn btn-function" onclick="inputText('^3')">x³</button>

    <button class="btn btn-function" onclick="inputText('^')">xʸ</button>
    <button class="btn btn-function" onclick="inputText('10^')">10ˣ</button>
    <button class="btn btn-function" onclick="inputText('e^')">eˣ</button>
    <button class="btn btn-function" onclick="inputText('1/')">1/x</button>
    <button class="btn btn-function" onclick="inputText('%')">%</button>

    <!-- Logical / Bitwise -->
    <div class="section-label">Logical / Bitwise</div>
    <button class="btn btn-logical" onclick="inputText('&amp;')">AND</button>
    <button class="btn btn-logical" onclick="inputText('|')">OR</button>
    <button class="btn btn-logical" onclick="inputText('^')">XOR</button>
    <button class="btn btn-logical" onclick="inputText('~')">NOT</button>
    <button class="btn btn-logical" onclick="inputText('<<')">SHL</button>

    <button class="btn btn-logical" onclick="inputText('>>')">SHR</button>
    <button class="btn btn-logical" onclick="inputText('0b')">BIN</button>
    <button class="btn btn-logical" onclick="inputText('0x')">HEX</button>
    <button class="btn btn-logical" onclick="inputText('0o')">OCT</button>
    <button class="btn btn-logical" onclick="toggleBaseMode()">BASE</button>

    <!-- Basic Operations -->
    <div class="section-label">Basic</div>
    <button class="btn btn-clear" onclick="clearAll()">AC</button>
    <button class="btn btn-clear" onclick="clearEntry()">CE</button>
    <button class="btn btn-operator" onclick="inputText('(')">(</button>
    <button class="btn btn-operator" onclick="inputText(')')">)</button>
    <button class="btn btn-operator" onclick="inputText('÷')">÷</button>

    <button class="btn btn-number" onclick="inputText('7')">7</button>
    <button class="btn btn-number" onclick="inputText('8')">8</button>
    <button class="btn btn-number" onclick="inputText('9')">9</button>
    <button class="btn btn-operator" onclick="inputText('×')">×</button>
    <button class="btn btn-operator" onclick="inputText('−')">−</button>

    <button class="btn btn-number" onclick="inputText('4')">4</button>
    <button class="btn btn-number" onclick="inputText('5')">5</button>
    <button class="btn btn-number" onclick="inputText('6')">6</button>
    <button class="btn btn-operator" onclick="inputText('+')">+</button>
    <button class="btn btn-operator" onclick="backspace()">⌫</button>

    <button class="btn btn-number" onclick="inputText('1')">1</button>
    <button class="btn btn-number" onclick="inputText('2')">2</button>
    <button class="btn btn-number" onclick="inputText('3')">3</button>
    <button class="btn btn-number" onclick="inputText('.')">.</button>
    <button class="btn btn-equals" onclick="calculate()">=</button>

    <button class="btn btn-number btn-span-2" onclick="inputText('0')">0</button>
    <button class="btn btn-number" onclick="inputText('00')">00</button>
    <button class="btn btn-number" onclick="inputText('000')">000</button>
    <button class="btn btn-number" onclick="toggleSign()">±</button>
