<script>
  let expression = '';
  let currentResult = '0';
  let angleMode = 'deg';
  let memory = 0;
  let hasMemory = false;
  let history = [];
  let lastResult = null;

  const expressionEl = document.getElementById('expression');
  const resultEl = document.getElementById('result');
  const baseDisplayEl = document.getElementById('baseDisplay');
  const memIndicator = document.getElementById('memIndicator');
  const historyPanel = document.getElementById('historyPanel');
  const historyContent = document.getElementById('historyContent');

  function updateDisplay() {
    expressionEl.textContent = expression;
    resultEl.textContent = currentResult;
    resultEl.classList.remove('error');
  }

  function inputText(text) {
    if (lastResult !== null && !expression) {
      expression = '';
      lastResult = null;
    }
    expression += text;
    updateDisplay();
    try {
      let preview = evaluateExpression(expression);
      if (preview !== null && !isNaN(preview) && isFinite(preview)) {
        currentResult = formatNumber(preview);
        resultEl.textContent = currentResult;
      }
    } catch (e) {
      // Don't update preview on error
    }
  }

  function inputFunction(func) {
    if (lastResult !== null && !expression) {
      expression = '';
      lastResult = null;
    }
    expression += func;
    updateDisplay();
  }

  function backspace() {
    if (expression.length > 0) {
      // Check if last characters form a function name
      const funcPatterns = ['sin(', 'cos(', 'tan(', 'asin(', 'acos(', 'atan(', 'log(', 'ln(', 'sqrt(', 'cbrt(', 'fact('];
      let removed = false;
      for (let pattern of funcPatterns) {
        if (expression.endsWith(pattern)) {
          expression = expression.slice(0, -pattern.length);
          removed = true;
          break;
        }
      }
      if (!removed) {
        expression = expression.slice(0, -1);
      }
      updateDisplay();
      try {
        let preview = evaluateExpression(expression);
        if (preview !== null && !isNaN(preview) && isFinite(preview)) {
          currentResult = formatNumber(preview);
          resultEl.textContent = currentResult;
        }
      } catch (e) {
        // Don't update preview on error
      }
    }
  }

  function clearAll() {
    expression = '';
    currentResult = '0';
    lastResult = null;
    updateDisplay();
    baseDisplayEl.textContent = '';
  }

  function clearEntry() {
    expression = '';
    currentResult = '0';
    updateDisplay();
  }

  function toggleSign() {
    if (expression) {
      if (expression.startsWith('-')) {
        expression = expression.slice(1);
      } else {
        expression = '-' + expression;
      }
      updateDisplay();
      try {
        let preview = evaluateExpression(expression);
        if (preview !== null && !isNaN(preview) && isFinite(preview)) {
          currentResult = formatNumber(preview);
          resultEl.textContent = currentResult;
        }
      } catch (e) { }
    }
  }

  function setAngleMode(mode) {
    angleMode = mode;
    document.getElementById('degBtn').classList.toggle('active', mode === 'deg');
    document.getElementById('radBtn').classList.toggle('active', mode === 'rad');
  }

  function toggleBaseMode() {
    // Toggle between decimal and show binary representation
    if (currentResult !== '0' && currentResult !== 'Error') {
      let num = parseFloat(currentResult);
      if (!isNaN(num)) {
        baseDisplayEl.textContent = `BIN: ${Math.floor(num).toString(2)} | HEX: ${Math.floor(num).toString(16).toUpperCase()} | OCT: ${Math.floor(num).toString(8)}`;
      }
    }
  }

  function toggleHistory() {
    historyPanel.classList.toggle('open');
  }

  function addHistory(expr, result) {
    history.unshift({ expression: expr, result: result });
    if (history.length > 50) history.pop();
    renderHistory();
  }

  function renderHistory() {
    historyContent.innerHTML = history.map((item, i) => `
      <div class="history-item" onclick="loadHistory(${i})">
        <div class="hist-expr">${item.expression}</div>
        <div class="hist-result">${item.result}</div>
      </div>
    `).join('');
  }

  function loadHistory(index) {
    expression = history[index].expression;
    currentResult = history[index].result;
    lastResult = parseFloat(history[index].result);
    updateDisplay();
    historyPanel.classList.remove('open');
  }

  // Memory functions
  function memoryClear() {
    memory = 0;
    hasMemory = false;
    memIndicator.classList.remove('active');
  }

  function memoryRecall() {
    if (hasMemory) {
      expression += memory.toString();
      updateDisplay();
    }
  }

  function memoryAdd() {
    let val = parseFloat(currentResult) || 0;
    memory += val;
    hasMemory = true;
    memIndicator.classList.add('active');
  }

  function memorySubtract() {
    let val = parseFloat(currentResult) || 0;
    memory -= val;
    hasMemory = true;
    memIndicator.classList.add('active');
  }

  function memoryStore() {
    memory = parseFloat(currentResult) || 0;
    hasMemory = true;
    memIndicator.classList.add('active');
  }

  // Core evaluation
  function evaluateExpression(expr) {
    if (!expr.trim()) return null;

    let evalExpr = expr;

    // Replace display symbols with JS operators
    evalExpr = evalExpr.replace(/×/g, '*');
    evalExpr = evalExpr.replace(/÷/g, '/');
    evalExpr = evalExpr.replace(/−/g, '-');
    evalExpr = evalExpr.replace(/π/g, Math.PI.toString());
    evalExpr = evalExpr.replace(/e(?![x^])/g, Math.E.toString());

    // Handle percentage
    evalExpr = evalExpr.replace(/(\d+\.?\d*)%/g, '($1/100)');

    // Handle power operator
    evalExpr = evalExpr.replace(/\^/g, '**');

    // Handle factorial
    evalExpr = evalExpr.replace(/fact\(([^)]+)\)/g, 'factorial($1)');

    // Handle square root
    evalExpr = evalExpr.replace(/sqrt\(([^)]+)\)/g, 'Math.sqrt($1)');

    // Handle cube root
    evalExpr = evalExpr.replace(/cbrt\(([^)]+)\)/g, 'Math.cbrt($1)');

    // Handle logarithms
    evalExpr = evalExpr.replace(/log\(([^)]+)\)/g, 'Math.log10($1)');
    evalExpr = evalExpr.replace(/ln\(([^)]+)\)/g, 'Math.log($1)');

    // Handle trigonometric functions with angle mode
    if (angleMode === 'deg') {
      evalExpr = evalExpr.replace(/sin\(([^)]+)\)/g, 'Math.sin($1 * Math.PI / 180)');
      evalExpr = evalExpr.replace(/cos\(([^)]+)\)/g, 'Math.cos($1 * Math.PI / 180)');
      evalExpr = evalExpr.replace(/tan\(([^)]+)\)/g, 'Math.tan($1 * Math.PI / 180)');
      evalExpr = evalExpr.replace(/asin\(([^)]+)\)/g, '(Math.asin($1) * 180 / Math.PI)');
      evalExpr = evalExpr.replace(/acos\(([^)]+)\)/g, '(Math.acos($1) * 180 / Math.PI)');
      evalExpr = evalExpr.replace(/atan\(([^)]+)\)/g, '(Math.atan($1) * 180 / Math.PI)');
    } else {
      evalExpr = evalExpr.replace(/sin\(([^)]+)\)/g, 'Math.sin($1)');
      evalExpr = evalExpr.replace(/cos\(([^)]+)\)/g, 'Math.cos($1)');
      evalExpr = evalExpr.replace(/tan\(([^)]+)\)/g, 'Math.tan($1)');
      evalExpr = evalExpr.replace(/asin\(([^)]+)\)/g, 'Math.asin($1)');
      evalExpr = evalExpr.replace(/acos\(([^)]+)\)/g, 'Math.acos($1)');
      evalExpr = evalExpr.replace(/atan\(([^)]+)\)/g, 'Math.atan($1)');
    }

    // Handle 10^x and e^x
    evalExpr = evalExpr.replace(/10\*\*/g, 'Math.pow(10,');
    evalExpr = evalExpr.replace(/e\*\*/g, 'Math.exp(');

    // Handle bitwise operations (convert to integers)
    evalExpr = evalExpr.replace(/~/g, '~');
    evalExpr = evalExpr.replace(/&amp;/g, '&');

    // Handle binary, hex, octal prefixes
    evalExpr = evalExpr.replace(/0b([01]+)/gi, 'parseInt($1, 2)');
    evalExpr = evalExpr.replace(/0x([0-9a-f]+)/gi, 'parseInt($1, 16)');
    evalExpr = evalExpr.replace(/0o([0-7]+)/gi, 'parseInt($1, 8)');

    // Factorial function
    function factorial(n) {
      n = Math.floor(n);
      if (n < 0) return NaN;
      if (n === 0 || n === 1) return 1;
      if (n > 170) return Infinity;
      let result = 1;
      for (let i = 2; i <= n; i++) result *= i;
      return result;
    }

    // Safe evaluation
    try {
      // Check for balanced parentheses
      let openCount = (evalExpr.match(/\(/g) || []).length;
      let closeCount = (evalExpr.match(/\)/g) || []).length;
      if (openCount !== closeCount) {
        // Auto-close parentheses
        evalExpr += ')'.repeat(openCount - closeCount);
      }

      let result = Function('factorial', '"use strict"; return (' + evalExpr + ')')(factorial);
      return result;
    } catch (e) {
      return null;
    }
  }

  function formatNumber(num) {
    if (isNaN(num)) return 'Error';
    if (!isFinite(num)) return num > 0 ? 'Infinity' : '-Infinity';

    // Handle very large or very small numbers
    if (Math.abs(num) > 1e15 || (Math.abs(num) < 1e-10 && num !== 0)) {
      return num.toExponential(8);
    }

    // Round to avoid floating point issues
    let rounded = parseFloat(num.toPrecision(12));
    let str = rounded.toString();

    // Add commas for readability
    let parts = str.split('.');
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return parts.join('.');
  }

  function calculate() {
    if (!expression) return;

    try {
      let result = evaluateExpression(expression);

      if (result === null || isNaN(result)) {
        currentResult = 'Error';
        resultEl.classList.add('error');
      } else {
        currentResult = formatNumber(result);
        resultEl.textContent = currentResult;
        lastResult = result;
        addHistory(expression, currentResult);
      }
    } catch (e) {
      currentResult = 'Error';
      resultEl.classList.add('error');
    }

    expression = '';
  }

  // Keyboard support
  document.addEventListener('keydown', function (e) {
    e.preventDefault();

    const key = e.key;

    if (key >= '0' && key <= '9') {
      inputText(key);
    } else if (key === '.') {
      inputText('.');
    } else if (key === '+') {
      inputText('+');
    } else if (key === '-') {
      inputText('−');
    } else if (key === '*') {
      inputText('×');
    } else if (key === '/') {
      inputText('÷');
    } else if (key === '(') {
      inputText('(');
    } else if (key === ')') {
      inputText(')');
    } else if (key === '^') {
      inputText('^');
    } else if (key === 'Enter' || key === '=') {
      calculate();
    } else if (key === 'Backspace') {
      backspace();
    } else if (key === 'Escape' || key === 'c' || key === 'C') {
      clearAll();
    } else if (key === 'p') {
      inputText('π');
    } else if (key === 's') {
      inputFunction('sin(');
    } else if (key === 'o') {
      inputFunction('cos(');
    } else if (key === 't') {
      inputFunction('tan(');
    } else if (key === 'l') {
      inputFunction('log(');
    } else if (key === 'n') {
      inputFunction('ln(');
    } else if (key === 'r') {
      inputFunction('sqrt(');
    } else if (key === 'f') {
      inputFunction('fact(');
    }
  });

  // Initialize
  updateDisplay();
</script>

</body>
