function generateBuildings() {
  const buildingColors = ['#555', '#666', '#777', '#888', '#556', '#665', '#566', '#445'];
  const buildingTypes = ['commercial', 'residential', 'industrial', 'apartment'];

  for (let district of world.districts) {
    for (let x = district.x + 100; x < district.x + district.w - 100; x += 120) {
      for (let y = district.y + 100; y < district.y + district.h - 100; y += 120) {
        // Check if on road
        let onRoad = false;
        for (let road of world.roads) {
          if (x + 60 > road.x && x < road.x + road.w && y + 60 > road.y && y < road.y + road.h) {
            onRoad = true;
            break;
          }
        }
        if (onRoad) continue;

        // Random building
        if (Math.random() < 0.7) {
          const w = 60 + Math.random() * 80;
          const h = 60 + Math.random() * 80;
          const height = 20 + Math.random() * 60;
