  { x: 6000, y: 5000, angle: 0, type: 'truck', speed: 0, maxSpeed: 8, acceleration: 0.15, handling: 0.02, color: '#448844', health: 150, driver: null },
  { x: 3800, y: 5000, angle: Math.PI, type: 'bike', speed: 0, maxSpeed: 15, acceleration: 0.4, handling: 0.06, color: '#00FFFF', health: 50, driver: null },
