// ==================== TRAFFIC ====================
function spawnTraffic() {
  if (world.traffic.length >= 30) return;
  const road = world.roads[Math.floor(Math.random() * world.roads.length)];
  if (road.type === 'highway') return;

  const type = Math.random();
  let vehicle;
  if (type < 0.5) {
    vehicle = { x: road.x + 30, y: road.y + 30, angle: Math.random() * Math.PI * 2, type: 'traffic_sedan', speed: 2 + Math.random() * 3, maxSpeed: 5, acceleration: 0.1, handling: 0.03, color: `hsl(${Math.random()*360},60%,50%)`, health: 100, driver: 'ai' };
  } else if (type < 0.8) {
    vehicle = { x: road.x + 30, y: road.y + 30, angle: Math.random() * Math.PI * 2, type: 'traffic_truck', speed: 1.5 + Math.random() * 2, maxSpeed: 4, acceleration: 0.05, handling: 0.02, color: `hsl(${Math.random()*360},40%,40%)`, health: 150, driver: 'ai' };
