// ==================== COLLISION DETECTION ====================
function checkCollision(x, y, radius) {
  for (let building of world.buildings) {
    if (x + radius > building.x && x - radius < building.x + building.w &&
        y + radius > building.y && y - radius < building.y + building.h) {
      return building;
    }
  }
  return null;
}

function checkRoadCollision(x, y, radius) {
  for (let road of world.roads) {
    if (x + radius > road.x && x - radius < road.x + road.w &&
        y + radius > road.y && y - radius < road.y + road.h) {
      return road;
    }
  }
  return null;
}

function pointInRect(px, py, rx, ry, rw, rh) {
  return px > rx && px < rx + rw && py > ry && py < ry + rh;
}

function distance(x1, y1, x2, y2) {
  return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
}

// ==================== GAME LOGIC ====================
function updatePlayer(dt) {
  if (player.health <= 0) return;

  if (player.inVehicle) {
    updateVehicleDriving(dt);
  } else {
    updatePlayerMovement(dt);
  }

  // Update wanted level
  if (player.wantedLevel > 0) {
    player.wantedTimer -= dt;
    if (player.wantedTimer <= 0) {
      player.wantedLevel = Math.max(0, player.wantedLevel - 1);
      player.wantedTimer = 30000; // 30 seconds per star decay
      showNotification(`Wanted level: ${player.wantedLevel} stars`);
    }
  }

  // Update weapon firing
  if (mouse.down && !player.inVehicle) {
    fireWeapon();
  }

  // Animation
  player.animTimer += dt;
  if (player.animTimer > 200) {
    player.animFrame = (player.animFrame + 1) % 4;
    player.animTimer = 0;
  }
}

function updatePlayerMovement(dt) {
  let moveX = 0, moveY = 0;
  const speed = keys['shift'] ? player.sprintSpeed : player.maxSpeed;

  if (keys['w'] || keys['arrowup']) moveY = -1;
  if (keys['s'] || keys['arrowdown']) moveY = 1;
  if (keys['a'] || keys['arrowleft']) moveX = -1;
  if (keys['d'] || keys['arrowright']) moveX = 1;

  // Normalize diagonal movement
  if (moveX !== 0 && moveY !== 0) {
    moveX *= 0.707;
    moveY *= 0.707;
  }

  player.isSprinting = keys['shift'];

  // Calculate angle towards mouse
  const screenX = player.x - GAME.camera.x;
  const screenY = player.y - GAME.camera.y;
  player.angle = Math.atan2(mouse.y - screenY, mouse.x - screenX);

  // Apply movement
  player.vx = moveX * speed;
  player.vy = moveY * speed;

  // Check collision with buildings
  const newX = player.x + player.vx;
  const newY = player.y + player.vy;

  if (!checkCollision(newX, player.y, 15)) {
    player.x = newX;
  }
  if (!checkCollision(player.x, newY, 15)) {
    player.y = newY;
  }

  // World bounds
  player.x = Math.max(50, Math.min(GAME.worldSize.width - 50, player.x));
  player.y = Math.max(50, Math.min(GAME.worldSize.height - 50, player.y));

  // Speed for display
  player.speed = Math.sqrt(player.vx ** 2 + player.vy ** 2);
}

function updateVehicleDriving(dt) {
  const vehicle = player.inVehicle;
  if (!vehicle) return;

  const accel = keys['w'] || keys['arrowup'] ? vehicle.acceleration : 0;
  const brake = keys['s'] || keys['arrowdown'] ? -vehicle.acceleration * 0.5 : 0;
  const steer = keys['a'] || keys['arrowleft'] ? -vehicle.handling : keys['d'] || keys['arrowright'] ? vehicle.handling : 0;

  vehicle.speed += accel + brake;
  vehicle.speed = Math.max(-vehicle.maxSpeed * 0.3, Math.min(vehicle.maxSpeed, vehicle.speed));

  // Friction
  vehicle.speed *= 0.98;

  if (Math.abs(vehicle.speed) > 0.5) {
    vehicle.angle += steer * vehicle.speed * 0.02;
  }

  vehicle.x += Math.cos(vehicle.angle) * vehicle.speed;
  vehicle.y += Math.sin(vehicle.angle) * vehicle.speed;

  // Collision with buildings
  if (checkCollision(vehicle.x, vehicle.y, 30)) {
    vehicle.speed *= -0.5;
    vehicle.x -= Math.cos(vehicle.angle) * vehicle.speed * 2;
    vehicle.y -= Math.sin(vehicle.angle) * vehicle.speed * 2;
    vehicle.health -= Math.abs(vehicle.speed) * 2;
    GAME.shakeAmount = 5;
    GAME.shakeDuration = 200;
  }

  // World bounds
  vehicle.x = Math.max(50, Math.min(GAME.worldSize.width - 50, vehicle.x));
  vehicle.y = Math.max(50, Math.min(GAME.worldSize.height - 50, vehicle.y));

  // Update player position to vehicle
  player.x = vehicle.x;
  player.y = vehicle.y;
  player.angle = vehicle.angle;

  // Damage vehicle
  if (vehicle.health <= 0) {
    exitVehicle();
    player.health -= 20;
    showNotification("Vehicle destroyed!");
    createExplosion(vehicle.x, vehicle.y);
  }
}

function fireWeapon() {
  const weapon = player.weapons[player.currentWeapon];
  const now = Date.now();
  if (now - weapon.lastFire < weapon.fireRate) return;
  if (weapon.ammo <= 0 && weapon.type === 'gun') return;

  weapon.lastFire = now;
  if (weapon.type === 'gun') weapon.ammo--;

  if (weapon.type === 'melee') {
    // Melee attack
    const meleeRange = weapon.range;
    const meleeX = player.x + Math.cos(player.angle) * meleeRange;
    const meleeY = player.y + Math.sin(player.angle) * meleeRange;

    // Check hit pedestrians
    for (let ped of world.pedestrians) {
      if (distance(meleeX, meleeY, ped.x, ped.y) < 30) {
        ped.health -= weapon.damage;
        createBloodSplats(ped.x, ped.y);
        if (ped.health <= 0) {
          player.money += 50;
          increaseWantedLevel(1);
        }
      }
    }
    // Check hit traffic
    for (let traffic of world.traffic) {
      if (distance(meleeX, meleeY, traffic.x, traffic.y) < 30) {
        traffic.health -= weapon.damage;
      }
    }
  } else {
    // Gun fire
    const pellets = weapon.pellets || 1;
    for (let i = 0; i < pellets; i++) {
      const spread = (Math.random() - 0.5) * 0.1;
      const bulletAngle = player.angle + spread;
      GAME.bullets.push({
        x: player.x + Math.cos(player.angle) * 20,
        y: player.y + Math.sin(player.angle) * 20,
        vx: Math.cos(bulletAngle) * 20,
        vy: Math.sin(bulletAngle) * 20,
        damage: weapon.damage,
        range: weapon.range,
        traveled: 0,
        owner: 'player'
      });
    }
    // Muzzle flash
    createMuzzleFlash(player.x + Math.cos(player.angle) * 25, player.y + Math.sin(player.angle) * 25);
    // Sound effect visual
    GAME.shakeAmount = 2;
    GAME.shakeDuration = 100;
  }
}

function reloadWeapon() {
  const weapon = player.weapons[player.currentWeapon];
  if (weapon.type === 'melee' || weapon.ammo === weapon.maxAmmo) return;
  weapon.ammo = weapon.maxAmmo;
  showNotification("Weapon reloaded!");
}

function handleVehicleInteraction() {
  if (player.inVehicle) {
    exitVehicle();
  } else {
    // Find nearest vehicle
    let nearest = null;
    let nearestDist = 80;
    for (let vehicle of vehicles) {
      const dist = distance(player.x, player.y, vehicle.x, vehicle.y);
      if (dist < nearestDist) {
        nearestDist = dist;
        nearest = vehicle;
      }
    }
    if (nearest) {
      enterVehicle(nearest);
    }
  }
}

function enterVehicle(vehicle) {
  player.inVehicle = vehicle;
  vehicle.driver = 'player';
  showNotification(`Entered ${vehicle.type}`);
}

function exitVehicle() {
  if (!player.inVehicle) return;
  player.inVehicle.driver = null;
  player.x = player.inVehicle.x + 40;
  player.y = player.inVehicle.y;
  player.inVehicle = null;
  showNotification("Exited vehicle");
}

function handleInteraction() {
  // Check mission NPCs
  for (let npc of world.missionNPCs) {
    if (distance(player.x, player.y, npc.x, npc.y) < 60) {
      acceptMission(npc.mission);
      showNotification(npc.dialogue);
      return;
    }
  }
}

function acceptMission(mission) {
  GAME.activeMission = mission;
  GAME.missionStep = 0;
  document.getElementById('mission-title').textContent = mission.title;
  document.getElementById('mission-desc').textContent = mission.description;
  showNotification(`Mission Accepted: ${mission.title}`);
}

function increaseWantedLevel(amount) {
  player.wantedLevel = Math.min(5, player.wantedLevel + amount);
  player.wantedTimer = 60000;
  showNotification(`Wanted Level: ${player.wantedLevel} stars!`);
}

function updateTraffic(dt) {
  for (let i = world.traffic.length - 1; i >= 0; i--) {
    const traffic = world.traffic[i];
    traffic.x += Math.cos(traffic.angle) * traffic.speed;
    traffic.y += Math.sin(traffic.angle) * traffic.speed;

    // Check if on road, if not turn
    if (!checkRoadCollision(traffic.x, traffic.y, 20)) {
      traffic.angle += Math.PI / 2;
      traffic.x += Math.cos(traffic.angle) * traffic.speed * 2;
      traffic.y += Math.sin(traffic.angle) * traffic.speed * 2;
    }

    // Remove if too far
    if (distance(traffic.x, traffic.y, player.x, player.y) > 3000) {
      world.traffic.splice(i, 1);
    }
  }
}

function updatePedestrians(dt) {
  for (let i = world.pedestrians.length - 1; i >= 0; i--) {
    const ped = world.pedestrians[i];

    if (ped.state === 'walking') {
      ped.changeTimer -= dt;
      if (ped.changeTimer <= 0) {
        ped.angle = Math.random() * Math.PI * 2;
        ped.changeTimer = 2000 + Math.random() * 3000;
      }
      ped.x += Math.cos(ped.angle) * ped.speed;
      ped.y += Math.sin(ped.angle) * ped.speed;

      // Avoid buildings
      if (checkCollision(ped.x, ped.y, 10)) {
        ped.angle += Math.PI;
        ped.x += Math.cos(ped.angle) * ped.speed * 2;
        ped.y += Math.sin(ped.angle) * ped.speed * 2;
      }
    } else if (ped.state === 'fleeing') {
      // Run away from player
      const angleToPlayer = Math.atan2(player.y - ped.y, player.x - ped.x);
      ped.x -= Math.cos(angleToPlayer) * ped.speed * 2;
      ped.y -= Math.sin(angleToPlayer) * ped.speed * 2;
      ped.changeTimer -= dt;
      if (ped.changeTimer <= 0) {
        ped.state = 'walking';
        ped.changeTimer = 5000;
      }
    }

    // Remove if too far
    if (distance(ped.x, ped.y, player.x, player.y) > 2500) {
      world.pedestrians.splice(i, 1);
    }
  }
}

function updatePolice(dt) {
  for (let i = world.police.length - 1; i >= 0; i--) {
    const cop = world.police[i];
    const distToPlayer = distance(cop.x, cop.y, player.x, player.y);

    if (player.wantedLevel > 0 && distToPlayer < 1500) {
      cop.state = 'chase';
      // Chase player
      const angleToPlayer = Math.atan2(player.y - cop.y, player.x - cop.x);
      cop.targetX = player.x;
      cop.targetY = player.y;

      cop.vehicle.speed += cop.vehicle.acceleration;
      cop.vehicle.speed = Math.min(cop.vehicle.maxSpeed, cop.vehicle.speed);
      cop.vehicle.angle += (angleToPlayer - cop.vehicle.angle) * 0.05;

      cop.vehicle.x += Math.cos(cop.vehicle.angle) * cop.vehicle.speed;
      cop.vehicle.y += Math.sin(cop.vehicle.angle) * cop.vehicle.speed;

      cop.x = cop.vehicle.x;
      cop.y = cop.vehicle.y;

      // Shoot at player
      if (distToPlayer < 400 && Math.random() < 0.02) {
        GAME.bullets.push({
          x: cop.vehicle.x,
          y: cop.vehicle.y,
          vx: Math.cos(angleToPlayer) * 15,
          vy: Math.sin(angleToPlayer) * 15,
          damage: 10,
          range: 400,
          traveled: 0,
          owner: 'police'
        });
      }
    } else {
      cop.state = 'patrol';
      // Patrol randomly
      cop.changeTimer = (cop.changeTimer || 0) - dt;
      if (cop.changeTimer <= 0) {
        cop.vehicle.angle = Math.random() * Math.PI * 2;
        cop.changeTimer = 3000 + Math.random() * 5000;
      }
      cop.vehicle.speed = 3;
      cop.vehicle.x += Math.cos(cop.vehicle.angle) * cop.vehicle.speed;
      cop.vehicle.y += Math.sin(cop.vehicle.angle) * cop.vehicle.speed;
      cop.x = cop.vehicle.x;
      cop.y = cop.vehicle.y;
    }

    // Remove if too far
    if (distToPlayer > 3000) {
      world.police.splice(i, 1);
    }
  }
}

function updateBullets(dt) {
  for (let i = GAME.bullets.length - 1; i >= 0; i--) {
    const bullet = GAME.bullets[i];
    bullet.x += bullet.vx;
    bullet.y += bullet.vy;
    bullet.traveled += Math.sqrt(bullet.vx ** 2 + bullet.vy ** 2);

    if (bullet.traveled > bullet.range) {
      GAME.bullets.splice(i, 1);
      continue;
    }

    // Check building collision
    if (checkCollision(bullet.x, bullet.y, 2)) {
      GAME.bullets.splice(i, 1);
      createSparks(bullet.x, bullet.y);
      continue;
    }

    // Check hit player
    if (bullet.owner === 'police' && distance(bullet.x, bullet.y, player.x, player.y) < 20) {
      player.health -= bullet.damage;
      GAME.bullets.splice(i, 1);
      createBloodSplats(player.x, player.y);
      GAME.shakeAmount = 3;
      GAME.shakeDuration = 150;
      if (player.health <= 0) {
        playerDeath();
      }
      continue;
    }

    // Check hit pedestrians
    if (bullet.owner === 'player') {
      for (let ped of world.pedestrians) {
        if (distance(bullet.x, bullet.y, ped.x, ped.y) < 15) {
          ped.health -= bullet.damage;
          createBloodSplats(ped.x, ped.y);
          GAME.bullets.splice(i, 1);
          if (ped.health <= 0) {
            player.money += 50;
            increaseWantedLevel(1);
          }
          break;
        }
      }
    }

    // Check hit traffic
    if (bullet.owner === 'player') {
      for (let traffic of world.traffic) {
        if (distance(bullet.x, bullet.y, traffic.x, traffic.y) < 25) {
          traffic.health -= bullet.damage;
          GAME.bullets.splice(i, 1);
          createSparks(traffic.x, traffic.y);
          break;
        }
      }
    }
  }
}

function updateParticles(dt) {
  for (let i = GAME.particles.length - 1; i >= 0; i--) {
    const p = GAME.particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.life -= dt;
    p.vy += 0.1; // gravity
    if (p.life <= 0) {
      GAME.particles.splice(i, 1);
    }
  }

  for (let i = GAME.explosions.length - 1; i >= 0; i--) {
    const exp = GAME.explosions[i];
    exp.radius += 2;
    exp.life -= dt;
    if (exp.life <= 0) {
      GAME.explosions.splice(i, 1);
    }
  }
}

function createBloodSplats(x, y) {
  for (let i = 0; i < 5; i++) {
    GAME.bloodSplats.push({
      x: x + (Math.random() - 0.5) * 20,
      y: y + (Math.random() - 0.5) * 20,
      size: 2 + Math.random() * 4,
      alpha: 0.8
    });
  }
}

function createMuzzleFlash(x, y) {
  for (let i = 0; i < 3; i++) {
    GAME.particles.push({
      x: x, y: y,
      vx: (Math.random() - 0.5) * 5,
      vy: (Math.random() - 0.5) * 5,
      life: 100,
      maxLife: 100,
      color: '#FFA500',
      size: 3
    });
  }
}

function createSparks(x, y) {
  for (let i = 0; i < 8; i++) {
    GAME.particles.push({
      x: x, y: y,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 8,
      life: 300,
      maxLife: 300,
      color: '#FFD700',
      size: 2
    });
  }
}

function createExplosion(x, y) {
  GAME.explosions.push({ x: x, y: y, radius: 10, life: 500 });
  GAME.shakeAmount = 10;
  GAME.shakeDuration = 500;
  // Damage nearby
  for (let ped of world.pedestrians) {
    if (distance(x, y, ped.x, ped.y) < 100) {
      ped.health -= 50;
    }
  }
}

function updateWeather(dt) {
  GAME.weatherTimer -= dt;
  if (GAME.weatherTimer <= 0) {
    const weathers = ['clear', 'clear', 'clear', 'rain', 'fog'];
    GAME.weather = weathers[Math.floor(Math.random() * weathers.length)];
    GAME.weatherDuration = 10000 + Math.random() * 30000;
    GAME.weatherTimer = GAME.weatherDuration;
  }

  const weatherEl = document.getElementById('weather-indicator');
  if (GAME.weather === 'clear') weatherEl.textContent = '☀️ Clear';
  else if (GAME.weather === 'rain') weatherEl.textContent = '🌧️ Rain';
  else if (GAME.weather === 'fog') weatherEl.textContent = '🌫️ Fog';
}

function updateTime(dt) {
  GAME.time += GAME.daySpeed;
  if (GAME.time >= 1440) GAME.time -= 1440;

  const hours = Math.floor(GAME.time / 60);
  const minutes = Math.floor(GAME.time % 60);
  const ampm = hours >= 12 ? 'PM' : 'AM';
  const displayHours = hours % 12 || 12;
  document.getElementById('time-display').textContent = `${displayHours}:${minutes.toString().padStart(2, '0')} ${ampm}`;
}

function updateCamera() {
  const targetX = player.x - canvas.width / 2;
  const targetY = player.y - canvas.height / 2;

  GAME.camera.x += (targetX - GAME.camera.x) * 0.1;
  GAME.camera.y += (targetY - GAME.camera.y) * 0.1;

  // Screen shake
  if (GAME.shakeDuration > 0) {
    GAME.shakeDuration -= 16;
    GAME.camera.x += (Math.random() - 0.5) * GAME.shakeAmount;
    GAME.camera.y += (Math.random() - 0.5) * GAME.shakeAmount;
  }
}

function updateMission() {
  if (!GAME.activeMission) return;

  const mission = GAME.activeMission;

  if (mission.type === 'combat') {
    // Check if target enemies are eliminated
    // Simplified: just track time and random completion
    if (mission.completed < mission.target) {
      mission.completed = Math.min(mission.target, mission.completed + 0.001);
      if (mission.completed >= mission.target) {
        completeMission();
      }
    }
  } else if (mission.type === 'race') {
    // Check if player reaches checkpoints
    if (!mission.completed) {
      mission.completed = true;
      completeMission();
    }
  } else if (mission.type === 'delivery') {
    if (!mission.completed) {
      if (distance(player.x, player.y, mission.targetX, mission.targetY) < 100) {
        mission.completed = true;
        completeMission();
      }
    }
  } else if (mission.type === 'heist') {
    if (!mission.completed) {
      mission.completed = true;
      completeMission();
    }
  }
}

function completeMission() {
  const mission = GAME.activeMission;
  player.money += mission.reward;
  showNotification(`Mission Complete! +$${mission.reward}`);
  GAME.activeMission = null;
  document.getElementById('mission-title').textContent = 'No Active Mission';
  document.getElementById('mission-desc').textContent = 'Explore the city and find missions!';
}

function playerDeath() {
  GAME.state = 'dead';
  document.getElementById('death-screen').style.display = 'flex';
}

function respawnPlayer() {
  player.health = player.maxHealth;
  player.armor = 0;
  player.x = 4000;
  player.y = 4000;
  player.wantedLevel = 0;
  player.money = Math.max(0, player.money - 500);
  GAME.state = 'playing';
  document.getElementById('death-screen').style.display = 'none';
  showNotification("Respawned! -$500");
}

function showNotification(text) {
  const notif = document.getElementById('notification');
  notif.textContent = text;
  notif.style.opacity = 1;
  setTimeout(() => { notif.style.opacity = 0; }, 3000);
}

function updateUI() {
  document.getElementById('health-bar').style.width = `${(player.health / player.maxHealth) * 100}%`;
  document.getElementById('armor-bar').style.width = `${(player.armor / 100) * 100}%`;
  document.getElementById('money').textContent = `$${player.money.toLocaleString()}`;

  // Wanted stars
  const stars = document.querySelectorAll('#wanted-stars .star');
  stars.forEach((star, i) => {
    star.className = i < player.wantedLevel ? 'star active' : 'star';
  });

  // Speed display
  if (player.inVehicle) {
    document.getElementById('speed-display').textContent = `${Math.abs(Math.round(player.inVehicle.speed * 10))} km/h`;
  } else {
    document.getElementById('speed-display').textContent = '';
  }

  // Weapon display
  const weapon = player.weapons[player.currentWeapon];
  document.getElementById('weapon-display').textContent = `${weapon.type === 'melee' ? '👊' : '🔫'} ${weapon.name} ${weapon.ammo !== Infinity ? `(${weapon.ammo}/${weapon.maxAmmo})` : ''}`;

  // Interaction prompt
  const prompt = document.getElementById('interaction-prompt');
  let showPrompt = false;
  for (let vehicle of vehicles) {
    if (distance(player.x, player.y, vehicle.x, vehicle.y) < 80 && !player.inVehicle) {
      prompt.textContent = `Press E to enter ${vehicle.type}`;
      prompt.style.display = 'block';
      showPrompt = true;
      break;
    }
  }
  for (let npc of world.missionNPCs) {
    if (distance(player.x, player.y, npc.x, npc.y) < 60) {
      prompt.textContent = 'Press F to interact';
      prompt.style.display = 'block';
      showPrompt = true;
      break;
    }
  }
  if (!showPrompt) {
    prompt.style.display = 'none';
  }
}

// ==================== RENDERING ====================
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.save();
  ctx.translate(-GAME.camera.x, -GAME.camera.y);

  // Draw ground
  drawGround();

  // Draw water
  drawWater();

  // Draw roads
  drawRoads();

  // Draw parks
  drawParks();

  // Draw buildings
  drawBuildings();

  // Draw street lights
  drawStreetLights();

  // Draw pickups
  drawPickups();

  // Draw traffic
  drawTraffic();

  // Draw vehicles
  drawVehicles();

  // Draw pedestrians
  drawPedestrians();

  // Draw police
  drawPolice();

  // Draw mission NPCs
  drawMissionNPCs();

  // Draw player
  if (!player.inVehicle) {
    drawPlayer();
  }

  // Draw bullets
  drawBullets();

  // Draw particles
  drawParticles();

  // Draw explosions
  drawExplosions();

  // Draw blood splats
  drawBloodSplats();

  ctx.restore();

  // Draw weather effects
  drawWeather();

  // Draw day/night overlay
  drawDayNightOverlay();

  // Draw minimap
  drawMinimap();

  // Update UI
  updateUI();
}

function drawGround() {
  // Base ground color
  ctx.fillStyle = '#3a5a3a';
  ctx.fillRect(GAME.camera.x, GAME.camera.y, canvas.width, canvas.height);

  // Grid pattern for ground
  ctx.strokeStyle = 'rgba(255,255,255,0.05)';
  ctx.lineWidth = 1;
  const gridSize = 100;
  const startX = Math.floor(GAME.camera.x / gridSize) * gridSize;
  const startY = Math.floor(GAME.camera.y / gridSize) * gridSize;

  for (let x = startX; x < GAME.camera.x + canvas.width + gridSize; x += gridSize) {
    ctx.beginPath();
    ctx.moveTo(x, GAME.camera.y);
    ctx.lineTo(x, GAME.camera.y + canvas.height);
    ctx.stroke();
  }
  for (let y = startY; y < GAME.camera.y + canvas.height + gridSize; y += gridSize) {
    ctx.beginPath();
    ctx.moveTo(GAME.camera.x, y);
    ctx.lineTo(GAME.camera.x + canvas.width, y);
    ctx.stroke();
  }
}

function drawWater() {
  for (let water of world.water) {
    // Only draw if visible
    if (water.x + water.w < GAME.camera.x || water.x > GAME.camera.x + canvas.width ||
        water.y + water.h < GAME.camera.y || water.y > GAME.camera.y + canvas.height) continue;

    const time = Date.now() / 1000;
    ctx.fillStyle = GAME.weather === 'rain' ? '#1a3a5a' : '#2266aa';
    ctx.fillRect(water.x, water.y, water.w, water.h);

    // Wave effect
    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
    ctx.lineWidth = 2;
    for (let y = water.y; y < water.y + water.h; y += 20) {
      ctx.beginPath();
      for (let x = water.x; x < water.x + water.w; x += 5) {
        const waveY = y + Math.sin((x + time * 50) / 30) * 3;
        if (x === water.x) ctx.moveTo(x, waveY);
        else ctx.lineTo(x, waveY);
      }
      ctx.stroke();
    }
  }
}

function drawRoads() {
  for (let road of world.roads) {
    if (road.x + road.w < GAME.camera.x || road.x > GAME.camera.x + canvas.width ||
        road.y + road.h < GAME.camera.y || road.y > GAME.camera.y + canvas.height) continue;

    // Road surface
    ctx.fillStyle = road.type === 'highway' ? '#555' : '#444';
    ctx.fillRect(road.x, road.y, road.w, road.h);

    // Road lines
    ctx.strokeStyle = '#FFD700';
    ctx.lineWidth = 2;
    ctx.setLineDash([20, 20]);

    if (road.type === 'horizontal') {
      ctx.beginPath();
      ctx.moveTo(road.x, road.y + road.h / 2);
      ctx.lineTo(road.x + road.w, road.y + road.h / 2);
      ctx.stroke();
    } else {
      ctx.beginPath();
      ctx.moveTo(road.x + road.w / 2, road.y);
      ctx.lineTo(road.x + road.w / 2, road.y + road.h);
      ctx.stroke();
    }
    ctx.setLineDash([]);

    // Road edges
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    if (road.type === 'horizontal') {
      ctx.beginPath();
      ctx.moveTo(road.x, road.y);
      ctx.lineTo(road.x + road.w, road.y);
      ctx.moveTo(road.x, road.y + road.h);
      ctx.lineTo(road.x + road.w, road.y + road.h);
      ctx.stroke();
    } else {
      ctx.beginPath();
      ctx.moveTo(road.x, road.y);
      ctx.lineTo(road.x, road.y + road.h);
      ctx.moveTo(road.x + road.w, road.y);
      ctx.lineTo(road.x + road.w, road.y + road.h);
      ctx.stroke();
    }
  }
}

function drawParks() {
  for (let park of world.parks) {
    if (park.x + park.w < GAME.camera.x || park.x > GAME.camera.x + canvas.width ||
        park.y + park.h < GAME.camera.y || park.y > GAME.camera.y + canvas.height) continue;

    // Grass
    ctx.fillStyle = '#2d8a2d';
    ctx.fillRect(park.x, park.y, park.w, park.h);

    // Trees
    for (let tree of park.trees) {
      // Tree shadow
      ctx.fillStyle = 'rgba(0,0,0,0.2)';
      ctx.beginPath();
      ctx.ellipse(tree.x + 5, tree.y + 5, tree.size, tree.size * 0.6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Tree trunk
      ctx.fillStyle = '#8B4513';
      ctx.fillRect(tree.x - 3, tree.y - 5, 6, 15);

      // Tree canopy
      ctx.fillStyle = '#228B22';
      ctx.beginPath();
      ctx.arc(tree.x, tree.y - 10, tree.size, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#32CD32';
      ctx.beginPath();
      ctx.arc(tree.x - 3, tree.y - 13, tree.size * 0.7, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function drawBuildings() {
  for (let building of world.buildings) {
    if (building.x + building.w < GAME.camera.x || building.x > GAME.camera.x + canvas.width ||
        building.y + building.h < GAME.camera.y || building.y > GAME.camera.y + canvas.height) continue;

    // Building shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fillRect(building.x + 5, building.y + 5, building.w, building.h);

    // Building body
    ctx.fillStyle = building.color;
    ctx.fillRect(building.x, building.y, building.w, building.h);

    // Building border
    ctx.strokeStyle = 'rgba(0,0,0,0.3)';
    ctx.lineWidth = 1;
    ctx.strokeRect(building.x, building.y, building.w, building.h);

    // Windows
    if (building.windows) {
      const windowSize = 8;
      const windowGap = 15;
      for (let wx = building.x + 10; wx < building.x + building.w - 10; wx += windowGap) {
        for (let wy = building.y + 10; wy < building.y + building.h - 10; wy += windowGap) {
          // Window glow based on time of day
          const isNight = GAME.time > 1200 || GAME.time < 360;
          ctx.fillStyle = isNight ? '#FFD700' : '#88CCFF';
          ctx.globalAlpha = isNight ? 0.8 : 0.5;
          ctx.fillRect(wx, wy, windowSize, windowSize);
          ctx.globalAlpha = 1;
        }
      }
    }

    // Building top (3D effect)
    ctx.fillStyle = 'rgba(255,255,255,0.1)';
    ctx.fillRect(building.x, building.y, building.w, 3);
    ctx.fillRect(building.x, building.y, 3, building.h);
  }
}

function drawStreetLights() {
  const isNight = GAME.time > 1200 || GAME.time < 360;
  for (let light of world.streetLights) {
    if (light.x < GAME.camera.x - 50 || light.x > GAME.camera.x + canvas.width + 50 ||
        light.y < GAME.camera.y - 50 || light.y > GAME.camera.y + canvas.height + 50) continue;

    // Pole
    ctx.fillStyle = '#555';
    ctx.fillRect(light.x - 2, light.y - 20, 4, 20);

    // Light
    if (isNight) {
      ctx.fillStyle = '#FFD700';
      ctx.beginPath();
      ctx.arc(light.x, light.y - 22, 4, 0, Math.PI * 2);
      ctx.fill();

      // Light glow
      const gradient = ctx.createRadialGradient(light.x, light.y - 22, 0, light.x, light.y - 22, 60);
      gradient.addColorStop(0, 'rgba(255,215,0,0.3)');
      gradient.addColorStop(1, 'rgba(255,215,0,0)');
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(light.x, light.y - 22, 60, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function drawVehicles() {
  for (let vehicle of vehicles) {
    if (vehicle.x < GAME.camera.x - 100 || vehicle.x > GAME.camera.x + canvas.width + 100 ||
        vehicle.y < GAME.camera.y - 100 || vehicle.y > GAME.camera.y + canvas.height + 100) continue;

    ctx.save();
    ctx.translate(vehicle.x, vehicle.y);
    ctx.rotate(vehicle.angle);

    // Vehicle shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fillRect(-20, -10, 45, 22);

    // Vehicle body
    ctx.fillStyle = vehicle.color;
    ctx.fillRect(-20, -10, 40, 20);

    // Vehicle roof
    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.fillRect(-10, -8, 20, 16);

    // Windshield
    ctx.fillStyle = '#88CCFF';
    ctx.fillRect(10, -7, 8, 14);

    // Headlights
    ctx.fillStyle = '#FFD700';
    ctx.fillRect(18, -8, 3, 4);
    ctx.fillRect(18, 4, 3, 4);

    // Taillights
    ctx.fillStyle = '#FF0000';
    ctx.fillRect(-20, -8, 3, 4);
    ctx.fillRect(-20, 4, 3, 4);

    // Health bar
    if (vehicle.health < 100) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(-20, -15, 40, 4);
      ctx.fillStyle = vehicle.health > 50 ? '#4CAF50' : '#FF4444';
      ctx.fillRect(-20, -15, 40 * (vehicle.health / 100), 4);
    }

    ctx.restore();
  }
}

function drawTraffic() {
  for (let traffic of world.traffic) {
    if (traffic.x < GAME.camera.x - 100 || traffic.x > GAME.camera.x + canvas.width + 100 ||
        traffic.y < GAME.camera.y - 100 || traffic.y > GAME.camera.y + canvas.height + 100) continue;

    ctx.save();
    ctx.translate(traffic.x, traffic.y);
    ctx.rotate(traffic.angle);

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.fillRect(-15, -8, 35, 18);

    // Body
    ctx.fillStyle = traffic.color;
    ctx.fillRect(-15, -8, 30, 16);

    // Windshield
    ctx.fillStyle = '#88CCFF';
    ctx.fillRect(8, -6, 6, 12);

    ctx.restore();
  }
}

function drawPedestrians() {
  for (let ped of world.pedestrians) {
    if (ped.x < GAME.camera.x - 50 || ped.x > GAME.camera.x + canvas.width + 50 ||
        ped.y < GAME.camera.y - 50 || ped.y > GAME.camera.y + canvas.height + 50) continue;

    ctx.save();
    ctx.translate(ped.x, ped.y);

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(0, 5, 8, 4, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = ped.color;
    ctx.beginPath();
    ctx.arc(0, 0, 8, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.fillStyle = '#FFDAB9';
    ctx.beginPath();
    ctx.arc(0, -5, 5, 0, Math.PI * 2);
    ctx.fill();

    // Direction indicator
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(ped.angle) * 12, Math.sin(ped.angle) * 12);
    ctx.stroke();

    ctx.restore();
  }
}

function drawPolice() {
  for (let cop of world.police) {
    if (cop.x < GAME.camera.x - 100 || cop.x > GAME.camera.x + canvas.width + 100 ||
        cop.y < GAME.camera.y - 100 || cop.y > GAME.camera.y + canvas.height + 100) continue;

    // Police vehicle
    ctx.save();
    ctx.translate(cop.vehicle.x, cop.vehicle.y);
    ctx.rotate(cop.vehicle.angle);

    // Body
    ctx.fillStyle = '#0000AA';
    ctx.fillRect(-20, -10, 40, 20);

    // Police markings
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(-15, -10, 30, 3);
    ctx.fillRect(-15, 7, 30, 3);

    // Siren
    const sirenColor = Math.floor(Date.now() / 200) % 2 === 0 ? '#FF0000' : '#0000FF';
    ctx.fillStyle = sirenColor;
    ctx.beginPath();
    ctx.arc(0, -5, 4, 0, Math.PI * 2);
    ctx.fill();

    // Siren glow
    const gradient = ctx.createRadialGradient(0, -5, 0, 0, -5, 30);
    gradient.addColorStop(0, sirenColor + '80');
    gradient.addColorStop(1, sirenColor + '00');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(0, -5, 30, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }
}

function drawMissionNPCs() {
  for (let npc of world.missionNPCs) {
    if (npc.x < GAME.camera.x - 100 || npc.x > GAME.camera.x + canvas.width + 100 ||
        npc.y < GAME.camera.y - 100 || npc.y > GAME.camera.y + canvas.height + 100) continue;

    ctx.save();
    ctx.translate(npc.x, npc.y);

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(0, 5, 10, 5, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = npc.color;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.fillStyle = '#FFDAB9';
    ctx.beginPath();
    ctx.arc(0, -8, 7, 0, Math.PI * 2);
    ctx.fill();

    // Mission indicator
    ctx.fillStyle = '#FFD700';
    ctx.font = 'bold 16px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('!', 0, -20);

    // Name
    ctx.fillStyle = '#fff';
    ctx.font = '12px Arial';
    ctx.fillText('MISSION', 0, 25);

    ctx.restore();
  }
}

function drawPlayer() {
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(player.angle);

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(0, 5, 10, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body
  ctx.fillStyle = '#4488FF';
  ctx.beginPath();
  ctx.arc(0, 0, 10, 0, Math.PI * 2);
  ctx.fill();

  // Head
  ctx.fillStyle = '#FFDAB9';
  ctx.beginPath();
  ctx.arc(0, -6, 6, 0, Math.PI * 2);
  ctx.fill();

  // Arms
  ctx.strokeStyle = '#FFDAB9';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(5, 0);
  ctx.lineTo(15, -5);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(5, 0);
  ctx.lineTo(15, 5);
  ctx.stroke();

  // Weapon
  if (player.currentWeapon > 0) {
    ctx.fillStyle = '#333';
    ctx.fillRect(12, -2, 12, 4);
  }

  // Sprint effect
  if (player.isSprinting) {
    ctx.strokeStyle = 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(-15 - i * 5, -8 + i * 8);
      ctx.lineTo(-25 - i * 5, -8 + i * 8);
      ctx.stroke();
    }
  }

  ctx.restore();
}

function drawBullets() {
  for (let bullet of GAME.bullets) {
    ctx.fillStyle = bullet.owner === 'player' ? '#FFD700' : '#FF4444';
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 3, 0, Math.PI * 2);
    ctx.fill();

    // Trail
    ctx.strokeStyle = bullet.owner === 'player' ? 'rgba(255,215,0,0.5)' : 'rgba(255,68,68,0.5)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(bullet.x, bullet.y);
    ctx.lineTo(bullet.x - bullet.vx * 2, bullet.y - bullet.vy * 2);
    ctx.stroke();
  }
}

function drawParticles() {
  for (let p of GAME.particles) {
    const alpha = p.life / p.maxLife;
    ctx.fillStyle = p.color;
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawExplosions() {
  for (let exp of GAME.explosions) {
    const alpha = exp.life / 500;
    ctx.strokeStyle = `rgba(255,100,0,${alpha})`;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(exp.x, exp.y, exp.radius, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = `rgba(255,200,0,${alpha * 0.3})`;
    ctx.beginPath();
    ctx.arc(exp.x, exp.y, exp.radius, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawBloodSplats() {
  for (let splat of GAME.bloodSplats) {
    ctx.fillStyle = `rgba(139,0,0,${splat.alpha})`;
    ctx.beginPath();
    ctx.arc(splat.x, splat.y, splat.size, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawWeather() {
  if (GAME.weather === 'rain') {
    ctx.strokeStyle = 'rgba(150,150,200,0.3)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 100; i++) {
      const x = GAME.camera.x + Math.random() * canvas.width;
      const y = GAME.camera.y + Math.random() * canvas.height;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x - 2, y + 10);
      ctx.stroke();
    }
  } else if (GAME.weather === 'fog') {
    ctx.fillStyle = 'rgba(200,200,200,0.3)';
    ctx.fillRect(GAME.camera.x, GAME.camera.y, canvas.width, canvas.height);
  }
}

function drawDayNightOverlay() {
  const isNight = GAME.time > 1200 || GAME.time < 360;
  const isDawn = (GAME.time > 360 && GAME.time < 480) || (GAME.time > 1080 && GAME.time < 1200);

  if (isNight) {
    ctx.fillStyle = 'rgba(0,0,30,0.4)';
    ctx.fillRect(GAME.camera.x, GAME.camera.y, canvas.width, canvas.height);
  } else if (isDawn) {
    const alpha = GAME.time < 480 ? (GAME.time - 360) / 120 * 0.2 : (1200 - GAME.time) / 120 * 0.2;
    ctx.fillStyle = `rgba(255,150,50,${alpha})`;
    ctx.fillRect(GAME.camera.x, GAME.camera.y, canvas.width, canvas.height);
  }
}

function drawMinimap() {
  minimapCtx.clearRect(0, 0, 200, 200);

  // Background
  minimapCtx.fillStyle = '#2a4a2a';
  minimapCtx.fillRect(0, 0, 200, 200);

  const scale = 200 / GAME.worldSize.width;

  // Draw roads
  minimapCtx.fillStyle = '#555';
  for (let road of world.roads) {
    minimapCtx.fillRect(road.x * scale, road.y * scale, road.w * scale, road.h * scale);
  }

  // Draw buildings
  minimapCtx.fillStyle = '#777';
  for (let building of world.buildings) {
    minimapCtx.fillRect(building.x * scale, building.y * scale, building.w * scale, building.h * scale);
  }

  // Draw water
  minimapCtx.fillStyle = '#2266aa';
  for (let water of world.water) {
    minimapCtx.fillRect(water.x * scale, water.y * scale, water.w * scale, water.h * scale);
  }

  // Draw parks
  minimapCtx.fillStyle = '#2d8a2d';
  for (let park of world.parks) {
    minimapCtx.fillRect(park.x * scale, park.y * scale, park.w * scale, park.h * scale);
  }

  // Draw mission NPCs
  for (let npc of world.missionNPCs) {
    minimapCtx.fillStyle = '#FFD700';
    minimapCtx.beginPath();
    minimapCtx.arc(npc.x * scale, npc.y * scale, 4, 0, Math.PI * 2);
    minimapCtx.fill();
  }

  // Draw player
  minimapCtx.fillStyle = '#4488FF';
  minimapCtx.beginPath();
  minimapCtx.arc(player.x * scale, player.y * scale, 4, 0, Math.PI * 2);
  minimapCtx.fill();

  // Player direction
  minimapCtx.strokeStyle = '#4488FF';
  minimapCtx.lineWidth = 2;
  minimapCtx.beginPath();
  minimapCtx.moveTo(player.x * scale, player.y * scale);
  minimapCtx.lineTo(player.x * scale + Math.cos(player.angle) * 10, player.y * scale + Math.sin(player.angle) * 10);
  minimapCtx.stroke();

  // Draw police
  minimapCtx.fillStyle = '#0000FF';
  for (let cop of world.police) {
    minimapCtx.beginPath();
    minimapCtx.arc(cop.x * scale, cop.y * scale, 3, 0, Math.PI * 2);
    minimapCtx.fill();
  }

  // Draw traffic
  minimapCtx.fillStyle = '#888';
  for (let traffic of world.traffic) {
    minimapCtx.fillRect(traffic.x * scale - 1, traffic.y * scale - 1, 3, 3);
  }

  // Viewport rectangle
  minimapCtx.strokeStyle = '#fff';
  minimapCtx.lineWidth = 1;
  minimapCtx.strokeRect(
    GAME.camera.x * scale,
    GAME.camera.y * scale,
    canvas.width * scale,
    canvas.height * scale
  );

  // Circular mask
  minimapCtx.globalCompositeOperation = 'destination-in';
  minimapCtx.beginPath();
  minimapCtx.arc(100, 100, 100, 0, Math.PI * 2);
  minimapCtx.fill();
  minimapCtx.globalCompositeOperation = 'source-over';
}

// ==================== GAME LOOP ====================
let lastTime = 0;

function gameLoop(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;

  if (GAME.state === 'playing') {
    updatePlayer(dt);
    updateTraffic(dt);
    updatePedestrians(dt);
    updatePolice(dt);
    updateBullets(dt);
    updateParticles(dt);
    updateWeather(dt);
    updateTime(dt);
    updateCamera();
    updateMission();

    // Spawn traffic
    GAME.trafficSpawnTimer -= dt;
    if (GAME.trafficSpawnTimer <= 0) {
      spawnTraffic();
      GAME.trafficSpawnTimer = 2000 + Math.random() * 3000;
    }

    // Spawn pedestrians
    GAME.npcSpawnTimer -= dt;
    if (GAME.npcSpawnTimer <= 0) {
      spawnPedestrian();
      GAME.npcSpawnTimer = 3000 + Math.random() * 5000;
    }

    // Spawn police when wanted
    if (player.wantedLevel > 0) {
      GAME.policeSpawnTimer -= dt;
      if (GAME.policeSpawnTimer <= 0) {
        spawnPolice();
        GAME.policeSpawnTimer = 10000 / player.wantedLevel;
      }
    }

    // Respawn pickups
    for (let pickup of world.pickups) {
      if (!pickup.active) {
        pickup.respawnTimer -= dt;
        if (pickup.respawnTimer <= 0) {
          pickup.active = true;
        }
      } else {
        // Check if player picks up
        if (distance(player.x, player.y, pickup.x, pickup.y) < 30) {
          if (pickup.type === 'health') {
            player.health = Math.min(player.maxHealth, player.health + pickup.amount);
          } else if (pickup.type === 'armor') {
            player.armor = Math.min(100, player.armor + pickup.amount);
          } else if (pickup.type === 'money') {
            player.money += pickup.amount;
          } else if (pickup.type === 'weapon') {
            player.weapons[pickup.weaponIndex].ammo = player.weapons[pickup.weaponIndex].maxAmmo;
          }
          pickup.active = false;
          pickup.respawnTimer = 60000;
          showNotification(`Picked up ${pickup.type}!`);
        }
      }
    }
  }

  render();
  requestAnimationFrame(gameLoop);
}

// ==================== GAME START ====================
function startGame() {
  document.getElementById('menu-overlay').style.display = 'none';
  GAME.state = 'playing';
  generateWorld();
  requestAnimationFrame(gameLoop);
}

