    margin: 0;
    padding: 0;
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
  }

  html, body {
    height: 100%;
    overflow: hidden;
  }

  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    overflow: hidden;
    position: relative;
  }

  body::before {
    content: '';
    position: fixed;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(ellipse at 30% 20%, rgba(0,212,255,0.05) 0%, transparent 50%),
                radial-gradient(ellipse at 70% 80%, rgba(255,51,102,0.05) 0%, transparent 50%),
                radial-gradient(ellipse at 50% 50%, rgba(139,92,246,0.03) 0%, transparent 70%);
    animation: bgFloat 20s ease-in-out infinite;
    z-index: 0;
    pointer-events: none;
  }

  @keyframes bgFloat {
    0%, 100% { transform: translate(0, 0) rotate(0deg); }
    33% { transform: translate(2%, -2%) rotate(1deg); }
    66% { transform: translate(-1%, 1%) rotate(-1deg); }
  }

  .app-container {
    position: relative;
    z-index: 1;
    height: 100vh;
    height: 100dvh;
    display: flex;
    flex-direction: column;
    max-width: 480px;
    margin: 0 auto;
    overflow: hidden;
  }

  /* Header */
  .app-header {
    padding: 16px 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: rgba(10,10,15,0.8);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--glass-border);
    flex-shrink: 0;
    z-index: 100;
  }

  .app-logo {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .app-logo-icon {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, var(--neon-blue), var(--neon-purple));
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    box-shadow: var(--shadow-blue);
    animation: logoPulse 3s ease-in-out infinite;
  }

  @keyframes logoPulse {
    0%, 100% { box-shadow: 0 0 20px rgba(0,212,255,0.3); }
    50% { box-shadow: 0 0 30px rgba(0,212,255,0.5); }
  }

  .app-logo-text {
    font-family: 'Orbitron', sans-serif;
    font-size: 20px;
    font-weight: 800;
    background: linear-gradient(135deg, var(--neon-blue), var(--neon-purple));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: 1px;
  }

  .header-actions {
    display: flex;
    gap: 8px;
  }

  .header-btn {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    color: var(--text-secondary);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: 16px;
  }

  .header-btn:hover {
    background: rgba(255,255,255,0.1);
    color: var(--neon-blue);
    border-color: var(--neon-blue);
  }

  /* Pages */
  .pages-container {
    flex: 1;
    position: relative;
    overflow: hidden;
  }

  .page {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 20px;
    padding-bottom: 100px;
    opacity: 0;
    transform: translateX(30px);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    pointer-events: none;
    scrollbar-width: none;
  }

  .page::-webkit-scrollbar {
    display: none;
  }

  .page.active {
    opacity: 1;
    transform: translateX(0);
    pointer-events: all;
  }

  .page.exit-left {
    opacity: 0;
    transform: translateX(-30px);
  }

  /* Bottom Navigation */
  .bottom-nav {
    position: fixed;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 100%;
    max-width: 480px;
    background: rgba(10,10,15,0.95);
    backdrop-filter: blur(30px);
    -webkit-backdrop-filter: blur(30px);
    border-top: 1px solid var(--glass-border);
    display: flex;
    justify-content: space-around;
    padding: 8px 0;
    padding-bottom: max(8px, env(safe-area-inset-bottom));
    z-index: 100;
  }

  .nav-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    padding: 8px 16px;
    border-radius: 12px;
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    min-width: 64px;
  }

  .nav-item::before {
    content: '';
    position: absolute;
    top: -8px;
    left: 50%;
    transform: translateX(-50%) scaleX(0);
    width: 24px;
    height: 3px;
    background: var(--neon-blue);
    border-radius: 0 0 3px 3px;
    transition: transform 0.3s ease;
  }

  .nav-item.active::before {
    transform: translateX(-50%) scaleX(1);
  }

  .nav-item.active {
    background: rgba(0,212,255,0.1);
  }

  .nav-icon {
    font-size: 22px;
    transition: all 0.3s ease;
  }

  .nav-label {
    font-size: 10px;
    font-weight: 600;
    color: var(--text-muted);
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .nav-item.active .nav-label {
    color: var(--neon-blue);
  }

  .nav-item.active .nav-icon {
    color: var(--neon-blue);
  }

  /* Home Page - Rock Chat */
  .rock-header {
    text-align: center;
    margin-bottom: 24px;
  }

  .rock-avatar-container {
    position: relative;
    width: 100px;
    height: 100px;
    margin: 0 auto 16px;
  }

  .rock-avatar {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--neon-blue), var(--neon-purple));
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 48px;
    position: relative;
    z-index: 2;
    box-shadow: 0 0 40px rgba(0,212,255,0.4);
    animation: avatarFloat 4s ease-in-out infinite;
  }

  @keyframes avatarFloat {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-8px); }
  }

  .rock-avatar-ring {
    position: absolute;
    top: -5px;
    left: -5px;
    right: -5px;
    bottom: -5px;
    border-radius: 50%;
    border: 2px solid var(--neon-blue);
    opacity: 0.3;
    animation: ringPulse 2s ease-in-out infinite;
  }

  .rock-avatar-ring:nth-child(2) {
    top: -10px;
    left: -10px;
    right: -10px;
    bottom: -10px;
    animation-delay: 0.5s;
    border-color: var(--neon-purple);
  }

  @keyframes ringPulse {
    0%, 100% { transform: scale(1); opacity: 0.3; }
    50% { transform: scale(1.05); opacity: 0.1; }
  }

  .rock-status {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 12px;
    background: rgba(16,185,129,0.1);
    border: 1px solid rgba(16,185,129,0.3);
    border-radius: 20px;
    font-size: 12px;
    color: var(--neon-green);
    margin-bottom: 12px;
  }

  .status-dot {
    width: 6px;
    height: 6px;
    background: var(--neon-green);
    border-radius: 50%;
    animation: statusBlink 2s ease-in-out infinite;
  }

  @keyframes statusBlink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
  }

  .rock-title {
    font-family: 'Orbitron', sans-serif;
    font-size: 24px;
    font-weight: 800;
    margin-bottom: 4px;
    background: linear-gradient(135deg, #fff, var(--neon-blue));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .rock-subtitle {
    font-size: 14px;
    color: var(--text-secondary);
  }

  /* Daily Tip */
  .daily-tip {
    background: linear-gradient(135deg, rgba(139,92,246,0.1), rgba(0,212,255,0.1));
    border: 1px solid rgba(139,92,246,0.2);
    border-radius: 16px;
    padding: 16px;
    margin-bottom: 20px;
    position: relative;
    overflow: hidden;
  }

  .daily-tip::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: linear-gradient(90deg, var(--neon-purple), var(--neon-blue), var(--neon-purple));
    animation: tipGradient 3s linear infinite;
    background-size: 200% 100%;
  }

  @keyframes tipGradient {
    0% { background-position: 0% 0%; }
    100% { background-position: 200% 0%; }
  }

  .daily-tip-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--neon-purple);
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .daily-tip-text {
    font-size: 14px;
    line-height: 1.6;
    color: var(--text-secondary);
  }

  /* Chat Container */
  .chat-container {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    overflow: hidden;
    margin-bottom: 20px;
    min-height: 300px;
    max-height: 450px;
    display: flex;
    flex-direction: column;
  }

  .chat-messages {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    scrollbar-width: thin;
    scrollbar-color: rgba(255,255,255,0.1) transparent;
  }

  .chat-messages::-webkit-scrollbar {
    width: 4px;
  }

  .chat-messages::-webkit-scrollbar-track {
    background: transparent;
  }

  .chat-messages::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.1);
    border-radius: 2px;
  }

  .message {
    display: flex;
    gap: 10px;
    max-width: 85%;
    animation: messageSlide 0.3s ease-out;
  }

  @keyframes messageSlide {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
  }

  .message.user {
    align-self: flex-end;
    flex-direction: row-reverse;
  }

  .message-avatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    flex-shrink: 0;
  }

  .message.rock .message-avatar {
    background: linear-gradient(135deg, var(--neon-blue), var(--neon-purple));
    box-shadow: 0 0 15px rgba(0,212,255,0.3);
  }

  .message.user .message-avatar {
    background: linear-gradient(135deg, var(--neon-red), var(--neon-orange));
    box-shadow: 0 0 15px rgba(255,51,102,0.3);
  }

  .message-bubble {
    padding: 12px 16px;
    border-radius: 16px;
    font-size: 14px;
    line-height: 1.5;
    position: relative;
  }

  .message.rock .message-bubble {
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--glass-border);
    border-top-left-radius: 4px;
    color: var(--text-primary);
  }

  .message.user .message-bubble {
    background: linear-gradient(135deg, rgba(0,212,255,0.2), rgba(139,92,246,0.2));
    border: 1px solid rgba(0,212,255,0.3);
    border-top-right-radius: 4px;
    color: var(--text-primary);
  }

  .message-time {
    font-size: 10px;
    color: var(--text-muted);
    margin-top: 4px;
    display: block;
  }

  .typing-indicator {
    display: flex;
    gap: 4px;
    padding: 12px 16px;
    align-items: center;
  }

  .typing-dot {
    width: 8px;
    height: 8px;
    background: var(--neon-blue);
    border-radius: 50%;
    animation: typingBounce 1.4s ease-in-out infinite;
  }

  .typing-dot:nth-child(2) { animation-delay: 0.2s; }
  .typing-dot:nth-child(3) { animation-delay: 0.4s; }

  @keyframes typingBounce {
    0%, 60%, 100% { transform: translateY(0); opacity: 0.3; }
    30% { transform: translateY(-8px); opacity: 1; }
  }

  /* Chat Input */
  .chat-input-container {
    padding: 12px 16px;
    border-top: 1px solid var(--glass-border);
    display: flex;
    gap: 8px;
    align-items: center;
    background: rgba(0,0,0,0.2);
  }

  .chat-input {
    flex: 1;
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 10px 16px;
    color: var(--text-primary);
    font-size: 14px;
    font-family: 'Inter', sans-serif;
    outline: none;
    transition: all 0.3s ease;
  }

  .chat-input:focus {
    border-color: var(--neon-blue);
    box-shadow: 0 0 20px rgba(0,212,255,0.1);
  }

  .chat-input::placeholder {
    color: var(--text-muted);
  }

  .chat-send-btn {
    width: 40px;
    height: 40px;
    border-radius: 12px;
    background: linear-gradient(135deg, var(--neon-blue), var(--neon-purple));
    border: none;
    color: white;
    font-size: 18px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    box-shadow: 0 0 20px rgba(0,212,255,0.3);
  }

  .chat-send-btn:hover {
    transform: scale(1.05);
    box-shadow: 0 0 30px rgba(0,212,255,0.5);
  }

  .chat-send-btn:active {
    transform: scale(0.95);
  }

  .chat-voice-btn {
    width: 40px;
    height: 40px;
    border-radius: 12px;
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--glass-border);
    color: var(--text-secondary);
    font-size: 16px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
  }

  .chat-voice-btn:hover {
    background: rgba(255,51,102,0.1);
    border-color: var(--neon-red);
    color: var(--neon-red);
  }

  /* Quick Actions */
  .quick-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 20px;
  }

  .quick-action-btn {
    padding: 8px 14px;
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    color: var(--text-secondary);
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .quick-action-btn:hover {
    background: rgba(0,212,255,0.1);
    border-color: var(--neon-blue);
    color: var(--neon-blue);
    transform: translateY(-2px);
  }

  /* CTA Button */
  .cta-container {
    margin-top: 20px;
  }

  .cta-button {
    width: 100%;
    padding: 16px;
    background: linear-gradient(135deg, var(--neon-blue), var(--neon-purple));
    border: none;
    border-radius: 16px;
    color: white;
    font-size: 16px;
    font-weight: 700;
    font-family: 'Inter', sans-serif;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    transition: all 0.3s ease;
    box-shadow: 0 0 30px rgba(0,212,255,0.3);
    position: relative;
    overflow: hidden;
  }

  .cta-button::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
    transition: left 0.5s ease;
  }

  .cta-button:hover::before {
    left: 100%;
  }

  .cta-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 0 40px rgba(0,212,255,0.5);
  }

  .cta-button:active {
    transform: translateY(0);
  }

  /* Calorie Tracker Page */
  .page-title {
    font-family: 'Orbitron', sans-serif;
    font-size: 22px;
    font-weight: 800;
    margin-bottom: 8px;
    background: linear-gradient(135deg, #fff, var(--neon-blue));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .page-subtitle {
    font-size: 14px;
    color: var(--text-secondary);
    margin-bottom: 24px;
  }

  /* Food Upload */
  .food-upload-area {
    background: var(--bg-card);
    border: 2px dashed var(--glass-border);
    border-radius: 20px;
    padding: 32px 20px;
    text-align: center;
    margin-bottom: 20px;
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
  }

  .food-upload-area:hover {
    border-color: var(--neon-blue);
    background: rgba(0,212,255,0.05);
  }

  .food-upload-area.dragover {
    border-color: var(--neon-blue);
    background: rgba(0,212,255,0.1);
    transform: scale(1.02);
  }

  .upload-icon {
    font-size: 48px;
    margin-bottom: 12px;
    display: block;
  }

  .upload-text {
    font-size: 16px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 4px;
  }

  .upload-subtext {
    font-size: 12px;
    color: var(--text-muted);
  }

  .upload-preview {
    width: 100%;
    max-height: 200px;
    object-fit: cover;
    border-radius: 12px;
    margin-top: 12px;
    display: none;
  }

  .analyze-btn {
    width: 100%;
    padding: 14px;
    background: linear-gradient(135deg, var(--neon-red), var(--neon-orange));
    border: none;
    border-radius: 14px;
    color: white;
    font-size: 15px;
    font-weight: 700;
    font-family: 'Inter', sans-serif;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 0 25px rgba(255,51,102,0.3);
    margin-top: 16px;
    display: none;
  }

  .analyze-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 0 35px rgba(255,51,102,0.5);
  }

  /* Food Result */
  .food-result {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    padding: 20px;
    margin-bottom: 20px;
    display: none;
    animation: resultSlide 0.4s ease-out;
  }

  @keyframes resultSlide {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
  }

  .food-result-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
  }

  .food-result-icon {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    background: linear-gradient(135deg, var(--neon-green), var(--neon-blue));
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
  }

  .food-result-name {
    font-size: 18px;
    font-weight: 700;
  }

  .food-result-confidence {
    font-size: 12px;
    color: var(--neon-green);
  }

  .nutrition-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }

  .nutrition-item {
    background: rgba(255,255,255,0.03);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 12px;
    text-align: center;
  }

  .nutrition-value {
    font-size: 20px;
    font-weight: 800;
    font-family: 'Orbitron', sans-serif;
    margin-bottom: 4px;
  }

  .nutrition-value.calories { color: var(--neon-orange); }
  .nutrition-value.protein { color: var(--neon-blue); }
  .nutrition-value.carbs { color: var(--neon-purple); }
  .nutrition-value.fat { color: var(--neon-red); }

  .nutrition-label {
    font-size: 11px;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  /* Daily Log */
  .daily-log {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    padding: 20px;
    margin-bottom: 20px;
  }

  .log-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 16px;
  }

  .log-title {
    font-size: 16px;
    font-weight: 700;
  }

  .log-total {
    font-family: 'Orbitron', sans-serif;
    font-size: 14px;
    color: var(--neon-orange);
  }

  .log-entry {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 0;
    border-bottom: 1px solid var(--glass-border);
  }

  .log-entry:last-child {
    border-bottom: none;
  }

  .log-entry-info {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .log-entry-emoji {
    font-size: 24px;
  }

  .log-entry-name {
    font-size: 14px;
    font-weight: 600;
  }

  .log-entry-time {
    font-size: 11px;
    color: var(--text-muted);
  }

  .log-entry-cal {
    font-family: 'Orbitron', sans-serif;
    font-size: 14px;
    color: var(--neon-orange);
    font-weight: 700;
  }

  /* Progress Bar */
  .progress-container {
    margin-top: 16px;
  }

  .progress-header {
    display: flex;
    justify-content: space-between;
    margin-bottom: 8px;
    font-size: 12px;
    color: var(--text-muted);
  }

  .progress-bar {
    width: 100%;
    height: 8px;
    background: rgba(255,255,255,0.05);
    border-radius: 4px;
    overflow: hidden;
  }

  .progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--neon-green), var(--neon-blue));
    border-radius: 4px;
    transition: width 0.5s ease;
    position: relative;
  }

  .progress-fill::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
    animation: progressShine 2s ease-in-out infinite;
  }

  @keyframes progressShine {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(100%); }
  }

  /* Wellness Page */
  .wellness-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin-bottom: 24px;
  }

  .wellness-card {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    padding: 20px;
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
  }

  .wellness-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, transparent, rgba(255,255,255,0.02));
    pointer-events: none;
  }

  .wellness-card:hover {
    transform: translateY(-4px);
    border-color: var(--neon-blue);
    box-shadow: 0 10px 30px rgba(0,0,0,0.3);
  }

  .wellness-card-icon {
    font-size: 32px;
    margin-bottom: 12px;
    display: block;
  }

  .wellness-card-title {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 4px;
  }

  .wellness-card-desc {
    font-size: 11px;
    color: var(--text-muted);
  }

  /* BMI Calculator */
  .bmi-calculator {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    padding: 24px;
    margin-bottom: 20px;
    display: none;
  }

  .bmi-calculator.active {
    display: block;
    animation: resultSlide 0.4s ease-out;
  }

  .bmi-title {
    font-size: 18px;
    font-weight: 700;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .input-group {
    margin-bottom: 16px;
  }

  .input-label {
    font-size: 12px;
    font-weight: 600;
    color: var(--text-secondary);
    margin-bottom: 6px;
    display: block;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .input-field {
    width: 100%;
    padding: 12px 16px;
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    color: var(--text-primary);
    font-size: 16px;
    font-family: 'Inter', sans-serif;
    outline: none;
    transition: all 0.3s ease;
  }

  .input-field:focus {
    border-color: var(--neon-blue);
    box-shadow: 0 0 20px rgba(0,212,255,0.1);
  }

  .input-field::placeholder {
    color: var(--text-muted);
  }

  .bmi-result {
    text-align: center;
    padding: 20px;
    background: rgba(255,255,255,0.03);
    border-radius: 16px;
    margin-top: 16px;
    display: none;
  }

  .bmi-result.active {
    display: block;
    animation: resultSlide 0.4s ease-out;
  }

  .bmi-value {
    font-family: 'Orbitron', sans-serif;
    font-size: 42px;
    font-weight: 900;
    margin-bottom: 8px;
  }

  .bmi-category {
    font-size: 16px;
    font-weight: 600;
    margin-bottom: 4px;
  }

  .bmi-info {
    font-size: 12px;
    color: var(--text-muted);
  }

  .bmi-scale {
    display: flex;
    height: 6px;
    border-radius: 3px;
    overflow: hidden;
    margin-top: 16px;
    gap: 2px;
  }

  .bmi-scale-segment {
    flex: 1;
    border-radius: 3px;
  }

  .bmi-scale-segment.underweight { background: var(--neon-blue); }
  .bmi-scale-segment.normal { background: var(--neon-green); }
  .bmi-scale-segment.overweight { background: var(--neon-orange); }
  .bmi-scale-segment.obese { background: var(--neon-red); }

  .bmi-indicator {
    width: 12px;
    height: 12px;
    background: white;
    border-radius: 50%;
    position: relative;
    margin-top: -8px;
    margin-left: calc(var(--bmi-pos) * 1% - 6px);
    box-shadow: 0 0 10px rgba(255,255,255,0.5);
    transition: margin-left 0.5s ease;
  }

  /* Daily Tips Section */
  .tips-section {
    margin-bottom: 20px;
  }

  .tips-section-title {
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .tip-card {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    padding: 16px;
    margin-bottom: 10px;
    display: flex;
    gap: 12px;
    align-items: flex-start;
    transition: all 0.3s ease;
  }

  .tip-card:hover {
    border-color: var(--neon-purple);
    transform: translateX(4px);
  }

  .tip-icon {
    font-size: 28px;
    flex-shrink: 0;
  }

  .tip-content {
    flex: 1;
  }

  .tip-title {
    font-size: 14px;
    font-weight: 600;
    margin-bottom: 4px;
  }

  .tip-text {
    font-size: 12px;
    color: var(--text-muted);
    line-height: 1.5;
  }

  /* Water Tracker */
  .water-tracker {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    padding: 24px;
    margin-bottom: 20px;
    text-align: center;
  }

  .water-title {
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
  }

  .water-glasses {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-bottom: 16px;
    flex-wrap: wrap;
  }

  .water-glass {
    width: 40px;
    height: 50px;
    border: 2px solid var(--glass-border);
    border-radius: 8px 8px 12px 12px;
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
    display: flex;
    align-items: flex-end;
  }

  .water-glass.filled {
    border-color: var(--neon-blue);
  }

  .water-glass.filled::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 100%;
    background: linear-gradient(180deg, rgba(0,212,255,0.3), var(--neon-blue));
    animation: waterFill 0.3s ease-out;
  }

  @keyframes waterFill {
    from { height: 0; }
    to { height: 100%; }
  }

  .water-glass:hover {
    transform: scale(1.1);
    border-color: var(--neon-blue);
  }

  .water-count {
    font-family: 'Orbitron', sans-serif;
    font-size: 24px;
    font-weight: 800;
    color: var(--neon-blue);
    margin-bottom: 4px;
  }

  .water-goal {
    font-size: 12px;
    color: var(--text-muted);
  }

  /* Modal */
  .modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0,0,0,0.7);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    z-index: 200;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 20px;
  }

  .modal-overlay.active {
    display: flex;
    animation: modalFadeIn 0.3s ease-out;
  }

  @keyframes modalFadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
  }

  .modal-content {
    background: var(--bg-secondary);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    padding: 24px;
    max-width: 400px;
    width: 100%;
    max-height: 80vh;
    overflow-y: auto;
    animation: modalSlideIn 0.3s ease-out;
  }

  @keyframes modalSlideIn {
    from { transform: translateY(20px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
  }

  .modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
  }

  .modal-title {
    font-size: 18px;
    font-weight: 700;
  }

  .modal-close {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--glass-border);
    color: var(--text-secondary);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: 16px;
  }

  .modal-close:hover {
    background: rgba(255,51,102,0.1);
    border-color: var(--neon-red);
    color: var(--neon-red);
  }

  /* Loading Spinner */
  .spinner {
    width: 24px;
    height: 24px;
    border: 3px solid rgba(255,255,255,0.1);
    border-top-color: var(--neon-blue);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin: 0 auto;
  }

  @keyframes spin {
    to { transform: rotate(360deg); }
  }

  /* Responsive */
  @media (max-width: 480px) {
    .app-container {
      max-width: 100%;
    }
    .bottom-nav {
      max-width: 100%;
    }
  }

  /* Scrollbar for pages */
  .page::-webkit-scrollbar {
    width: 0;
  }

  /* Animations */
  .fade-in {
    animation: fadeIn 0.5s ease-out;
  }

  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
  }

  .glow-text {
    text-shadow: 0 0 10px currentColor;
  }

  /* Stats Row */
  .stats-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    margin-bottom: 20px;
  }

  .stat-card {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: 14px;
    padding: 14px;
    text-align: center;
  }

  .stat-value {
    font-family: 'Orbitron', sans-serif;
    font-size: 20px;
    font-weight: 800;
    margin-bottom: 4px;
  }

  .stat-label {
    font-size: 10px;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  /* Workout suggestion */
  .workout-suggestion {
    background: linear-gradient(135deg, rgba(255,51,102,0.1), rgba(139,92,246,0.1));
    border: 1px solid rgba(255,51,102,0.2);
    border-radius: 16px;
    padding: 16px;
    margin-bottom: 20px;
  }

  .workout-suggestion-title {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .workout-suggestion-text {
    font-size: 13px;
    color: var(--text-secondary);
    line-height: 1.5;
  }

  /* Notification badge */
  .notification-badge {
    position: absolute;
    top: -2px;
    right: -2px;
    width: 8px;
    height: 8px;
    background: var(--neon-red);
    border-radius: 50%;
    animation: badgePulse 2s ease-in-out infinite;
  }

  @keyframes badgePulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.3); }
  }
</style>
</head>
<body>

<div class="app-container">
  <!-- Header -->
  <header class="app-header">
    <div class="app-logo">
      <div class="app-logo-icon">💪</div>
      <span class="app-logo-text">FitFlux</span>
    </div>
    <div class="header-actions">
      <div class="header-btn" onclick="showNotifications()">🔔</div>
      <div class="header-btn" onclick="showSettings()">⚙️</div>
    </div>
  </header>

  <!-- Pages Container -->
  <div class="pages-container">
    <!-- Home Page - Rock AI Coach -->
    <div class="page active" id="page-home">
      <div class="rock-header">
        <div class="rock-avatar-container">
          <div class="rock-avatar">🤖</div>
          <div class="rock-avatar-ring"></div>
          <div class="rock-avatar-ring"></div>
        </div>
        <div class="rock-status">
          <span class="status-dot"></span>
          Online — Ready to help
        </div>
        <h1 class="rock-title">Rock</h1>
        <p class="rock-subtitle">Your AI Fitness Coach</p>
      </div>

      <!-- Daily Tip -->
      <div class="daily-tip">
        <div class="daily-tip-label">
          ✨ Today's Tip
        </div>
        <p class="daily-tip-text" id="dailyTip">Stay consistent! Small daily improvements lead to stunning results over time. Remember: progress, not perfection.</p>
      </div>

      <!-- Quick Actions -->
      <div class="quick-actions">
        <button class="quick-action-btn" onclick="sendQuickMessage('Create a workout plan for me')">🏋️ Workout Plan</button>
        <button class="quick-action-btn" onclick="sendQuickMessage('Give me a nutrition tip')">🥗 Nutrition Tip</button>
        <button class="quick-action-btn" onclick="sendQuickMessage('How do I lose weight?')">🔥 Weight Loss</button>
        <button class="quick-action-btn" onclick="sendQuickMessage('Suggest a stretching routine')">🧘 Stretching</button>
      </div>

      <!-- Chat Container -->
      <div class="chat-container">
        <div class="chat-messages" id="chatMessages">
          <div class="message rock">
            <div class="message-avatar">🤖</div>
            <div>
              <div class="message-bubble">
                Hey there! I'm <strong>Rock</strong>, your AI fitness coach. 💪 I can help you with workout plans, nutrition advice, weight loss strategies, and much more. What would you like to work on today?
              </div>
              <span class="message-time">Just now</span>
            </div>
          </div>
        </div>
        <div class="chat-input-container">
          <button class="chat-voice-btn" onclick="toggleVoiceInput()" id="voiceBtn">🎤</button>
          <input type="text" class="chat-input" id="chatInput" placeholder="Ask Rock anything about fitness..." onkeypress="handleChatKeypress(event)">
          <button class="chat-send-btn" onclick="sendMessage()">➤</button>
        </div>
      </div>

      <!-- CTA -->
      <div class="cta-container">
        <button class="cta-button" onclick="navigateTo('calorie')">
          🔥 Go to Calorie Tracker
        </button>
      </div>
    </div>

    <!-- Calorie Tracker Page -->
    <div class="page" id="page-calorie">
      <h1 class="page-title">Smart Calorie Tracker</h1>
      <p class="page-subtitle">Upload a food photo or type to track your calories</p>

      <!-- Stats -->
      <div class="stats-row">
        <div class="stat-card">
          <div class="stat-value" style="color: var(--neon-orange);" id="totalCalories">0</div>
          <div class="stat-label">Calories</div>
        </div>
        <div class="stat-card">
          <div class="stat-value" style="color: var(--neon-blue);" id="totalProtein">0g</div>
          <div class="stat-label">Protein</div>
        </div>
        <div class="stat-card">
          <div class="stat-value" style="color: var(--neon-purple);" id="totalMeals">0</div>
          <div class="stat-label">Meals</div>
        </div>
      </div>

      <!-- Food Upload -->
      <div class="food-upload-area" id="foodUploadArea" onclick="document.getElementById('foodInput').click()">
        <span class="upload-icon">📸</span>
        <div class="upload-text">Upload Food Photo</div>
        <div class="upload-subtext">Tap to take a photo or choose from gallery</div>
        <img class="upload-preview" id="uploadPreview" alt="Preview">
        <input type="file" id="foodInput" accept="image/*" style="display:none" onchange="handleFileUpload(event)">
      </div>

      <button class="analyze-btn" id="analyzeBtn" onclick="analyzeFood()">🔍 Analyze Food</button>

      <!-- Manual Entry -->
      <div style="margin-top: 16px;">
        <div class="input-group">
          <label class="input-label">Or type food name manually</label>
          <div style="display: flex; gap: 8px;">
            <input type="text" class="input-field" id="manualFoodInput" placeholder="e.g., Grilled Chicken Salad" style="flex:1;">
            <button class="chat-send-btn" onclick="addManualFood()" style="width: auto; padding: 0 20px;">Add</button>
          </div>
        </div>
      </div>

      <!-- Food Result -->
      <div class="food-result" id="foodResult">
        <div class="food-result-header">
          <div class="food-result-icon">🍽️</div>
          <div>
            <div class="food-result-name" id="foodResultName">—</div>
            <div class="food-result-confidence" id="foodResultConfidence">Confidence: —</div>
          </div>
        </div>
        <div class="nutrition-grid">
          <div class="nutrition-item">
            <div class="nutrition-value calories" id="resultCalories">0</div>
            <div class="nutrition-label">Calories</div>
          </div>
          <div class="nutrition-item">
            <div class="nutrition-value protein" id="resultProtein">0g</div>
            <div class="nutrition-label">Protein</div>
          </div>
          <div class="nutrition-item">
            <div class="nutrition-value carbs" id="resultCarbs">0g</div>
            <div class="nutrition-label">Carbs</div>
          </div>
          <div class="nutrition-item">
            <div class="nutrition-value fat" id="resultFat">0g</div>
            <div class="nutrition-label">Fat</div>
          </div>
        </div>
      </div>

      <!-- Daily Log -->
      <div class="daily-log">
        <div class="log-header">
          <span class="log-title">📋 Today's Log</span>
          <span class="log-total" id="logTotal">0 cal</span>
        </div>
        <div id="logEntries">
          <div style="text-align: center; padding: 20px; color: var(--text-muted); font-size: 14px;">
            No meals logged yet. Start tracking!
          </div>
        </div>
        <div class="progress-container">
          <div class="progress-header">
            <span>Daily Goal</span>
            <span id="progressPercent">0%</span>
          </div>
          <div class="progress-bar">
            <div class="progress-fill" id="progressFill" style="width: 0%"></div>
          </div>
        </div>
      </div>
    </div>

    <!-- Wellness Page -->
    <div class="page" id="page-wellness">
      <h1 class="page-title">Wellness Tools</h1>
      <p class="page-subtitle">Track your health metrics and get daily insights</p>

      <!-- Wellness Grid -->
      <div class="wellness-grid">
        <div class="wellness-card" onclick="toggleBMICalculator()">
          <span class="wellness-card-icon">⚖️</span>
          <div class="wellness-card-title">BMI Calculator</div>
          <div class="wellness-card-desc">Check your body mass index</div>
        </div>
        <div class="wellness-card" onclick="toggleWaterTracker()">
          <span class="wellness-card-icon">💧</span>
          <div class="wellness-card-title">Water Tracker</div>
          <div class="wellness-card-desc">Stay hydrated daily</div>
        </div>
        <div class="wellness-card" onclick="showSleepTracker()">
          <span class="wellness-card-icon">😴</span>
          <div class="wellness-card-title">Sleep Tracker</div>
          <div class="wellness-card-desc">Monitor your sleep quality</div>
        </div>
        <div class="wellness-card" onclick="showStepCounter()">
          <span class="wellness-card-icon">👟</span>
          <div class="wellness-card-title">Step Counter</div>
          <div class="wellness-card-desc">Track your daily steps</div>
        </div>
      </div>

      <!-- BMI Calculator -->
      <div class="bmi-calculator" id="bmiCalculator">
        <div class="bmi-title">⚖️ BMI Calculator</div>
        <div class="input-group">
          <label class="input-label">Height (cm)</label>
          <input type="number" class="input-field" id="bmiHeight" placeholder="e.g., 175">
        </div>
        <div class="input-group">
          <label class="input-label">Weight (kg)</label>
          <input type="number" class="input-field" id="bmiWeight" placeholder="e.g., 70">
        </div>
        <button class="cta-button" onclick="calculateBMI()" style="margin-top: 8px;">
          Calculate BMI
        </button>
        <div class="bmi-result" id="bmiResult">
          <div class="bmi-value" id="bmiValue">0</div>
          <div class="bmi-category" id="bmiCategory">—</div>
          <div class="bmi-info" id="bmiInfo">Enter your height and weight to calculate</div>
          <div class="bmi-scale">
            <div class="bmi-scale-segment underweight"></div>
            <div class="bmi-scale-segment normal"></div>
            <div class="bmi-scale-segment overweight"></div>
            <div class="bmi-scale-segment obese"></div>
          </div>
          <div class="bmi-indicator" id="bmiIndicator" style="--bmi-pos: 0;"></div>
        </div>
      </div>

      <!-- Water Tracker -->
      <div class="water-tracker" id="waterTracker" style="display: none;">
        <div class="water-title">💧 Water Tracker</div>
        <div class="water-glasses" id="waterGlasses">
          <div class="water-glass" onclick="toggleWaterGlass(0)"></div>
          <div class="water-glass" onclick="toggleWaterGlass(1)"></div>
          <div class="water-glass" onclick="toggleWaterGlass(2)"></div>
          <div class="water-glass" onclick="toggleWaterGlass(3)"></div>
          <div class="water-glass" onclick="toggleWaterGlass(4)"></div>
          <div class="water-glass" onclick="toggleWaterGlass(5)"></div>
          <div class="water-glass" onclick="toggleWaterGlass(6)"></div>
          <div class="water-glass" onclick="toggleWaterGlass(7)"></div>
        </div>
        <div class="water-count" id="waterCount">0/8</div>
        <div class="water-goal">Goal: 8 glasses (2 liters)</div>
      </div>

      <!-- Daily Tips -->
      <div class="tips-section">
        <div class="tips-section-title">💡 Daily Wellness Tips</div>
        <div class="tip-card">
          <span class="tip-icon">🏃</span>
          <div class="tip-content">
            <div class="tip-title">Stay Active</div>
            <div class="tip-text">Aim for at least 30 minutes of moderate exercise daily. Even a brisk walk counts!</div>
          </div>
        </div>
        <div class="tip-card">
          <span class="tip-icon">🥦</span>
          <div class="tip-content">
            <div class="tip-title">Eat Colorful</div>
            <div class="tip-text">Include fruits and vegetables of different colors in your meals for maximum nutrients.</div>
          </div>
        </div>
        <div class="tip-card">
          <span class="tip-icon">😴</span>
          <div class="tip-content">
            <div class="tip-title">Sleep Well</div>
            <div class="tip-text">Get 7-9 hours of quality sleep. Your body recovers and grows during sleep.</div>
          </div>
