            <h3 style="color: #00d4ff; margin: 20px 0 10px;">2. ScreenCaptureService.kt - Screen Capture & Encoding</h3>
            <div class="code-block">
                <button class="copy-btn" onclick="copyCode(this)">📋 Copy</button>
                <pre><span class="keyword">class</span> <span class="type">ScreenCaptureService</span> : <span class="type">Service</span>() {

    <span class="keyword">private</span> <span class="keyword">var</span> mediaCodec: <span class="type">MediaCodec</span>? = <span class="keyword">null</span>
    <span class="keyword">private</span> <span class="keyword">var</span> virtualDisplay: <span class="type">VirtualDisplay</span>? = <span class="keyword">null</span>
    <span class="keyword">private</span> <span class="keyword">var</span> outputSurface: <span class="type">Surface</span>? = <span class="keyword">null</span>
    <span class="keyword">private</span> <span class="keyword">var</span> isRunning = <span class="keyword">false</span>

    <span class="comment">// Hardware encoding configuration</span>
    <span class="keyword">private</span> <span class="keyword">companion</span> <span class="keyword">object</span> {
        <span class="keyword">const val</span> BIT_RATE = <span class="number">8000000</span>       <span class="comment">// 8 Mbps</span>
        <span class="keyword">const val</span> FRAME_RATE = <span class="number">60</span>         <span class="comment">// 60 FPS</span>
        <span class="keyword">const val</span> I_FRAME_INTERVAL = <span class="number">10</span>   <span class="comment">// I-frame every 10s</span>
        <span class="keyword">const val</span> COLOR_FORMAT = 
            <span class="type">MediaCodecInfo</span>.<span class="type">CodecCapabilities</span>.<span class="type">COLOR_FormatSurface</span>
        <span class="keyword">const val</span> MIME_TYPE = <span class="string">"video/avc"</span>   <span class="comment">// H.264</span>
    }

    <span class="keyword">fun</span> <span class="type">startCapture</span>(
        <span class="type">mediaProjection</span>: <span class="type">MediaProjection</span>,
        <span class="type">width</span>: <span class="type">Int</span> = <span class="number">1920</span>,
        <span class="type">height</span>: <span class="type">Int</span> = <span class="number">1080</span>,
        <span class="type">dpi</span>: <span class="type">Int</span> = <span class="number">420</span>
    ) {
        <span class="type">initializeEncoder</span>(width, height)

        virtualDisplay = mediaProjection.<span class="type">createVirtualDisplay</span>(
            <span class="string">"ScreenMirror"</span>,
            width, height, dpi,
            <span class="type">DisplayManager</span>.<span class="type">VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR</span>,
            outputSurface,
            <span class="keyword">null</span>, <span class="keyword">null</span>
        )

        isRunning = <span class="keyword">true</span>
        <span class="type">startEncodingLoop</span>()
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">initializeEncoder</span>(width: <span class="type">Int</span>, height: <span class="type">Int</span>) {
        mediaCodec = <span class="type">MediaCodec</span>.<span class="type">createEncoderByType</span>(MIME_TYPE)
        <span class="keyword">val</span> format = <span class="type">MediaFormat</span>.<span class="type">createVideoFormat</span>(MIME_TYPE, width, height).<span class="keyword">apply</span> {
            <span class="type">setInteger</span>(<span class="type">MediaFormat</span>.KEY_COLOR_FORMAT, COLOR_FORMAT)
            <span class="type">setInteger</span>(<span class="type">MediaFormat</span>.KEY_BIT_RATE, BIT_RATE)
            <span class="type">setInteger</span>(<span class="type">MediaFormat</span>.KEY_FRAME_RATE, FRAME_RATE)
            <span class="type">setInteger</span>(<span class="type">MediaFormat</span>.KEY_I_FRAME_INTERVAL, I_FRAME_INTERVAL)
            <span class="type">setInteger</span>(<span class="type">MediaFormat</span>.KEY_BITRATE_MODE, 
                <span class="type">MediaCodecInfo</span>.<span class="type">EncoderCapabilities</span>.BITRATE_MODE_CBR)
        }

        mediaCodec?.<span class="type">configure</span>(format, <span class="keyword">null</span>, <span class="keyword">null</span>, 
            <span class="type">MediaCodec</span>.CONFIGURE_FLAG_ENCODE)

        outputSurface = mediaCodec?.<span class="type">createInputSurface</span>()
        mediaCodec?.<span class="type">start</span>()
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">startEncodingLoop</span>() {
        <span class="keyword">thread</span>(name = <span class="string">"EncodingThread"</span>) {
            <span class="keyword">val</span> codec = mediaCodec ?: <span class="keyword">return</span>@thread
            <span class="keyword">val</span> timeoutUs = <span class="number">10000</span>L

            <span class="keyword">while</span> (isRunning) {
                <span class="keyword">val</span> inputBufIndex = codec.<span class="type">dequeueInputBuffer</span>(timeoutUs)
                <span class="keyword">if</span> (inputBufIndex >= <span class="number">0</span>) {
                    <span class="comment">// Buffer is ready, virtualDisplay fills it</span>
                    codec.<span class="type">queueInputBuffer</span>(
                        inputBufIndex, <span class="number">0</span>, <span class="number">0</span>, 
                        <span class="type">System</span>.<span class="type">currentTimeMillis</span>() * <span class="number">1000</span>, <span class="number">0</span>
                    )
                }

                <span class="keyword">val</span> outputBufIndex = codec.<span class="type">dequeueOutputBuffer</span>(
                    <span class="type">bufferInfo</span>, timeoutUs
                )

                <span class="keyword">when</span> (outputBufIndex) {
                    <span class="type">MediaCodec</span>.INFO_OUTPUT_FORMAT_CHANGED -> {
                        <span class="type">handleFormatChanged</span>(codec.<span class="type">outputFormat</span>)
                    }
                    <span class="type">MediaCodec</span>.INFO_TRY_AGAIN_LATER -> {
                        <span class="comment">// No output available</span>
                    }
                    <span class="keyword">else</span> -> {
                        <span class="type">sendEncodedFrame</span>(codec, outputBufIndex)
                        codec.<span class="type">releaseOutputBuffer</span>(outputBufIndex, <span class="keyword">false</span>)
                    }
                }
            }
        }
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">sendEncodedFrame</span>(
        <span class="type">codec</span>: <span class="type">MediaCodec</span>, 
        <span class="type">index</span>: <span class="type">Int</span>
    ) {
        <span class="keyword">val</span> buffer = codec.<span class="type">getOutputBuffer</span>(index) ?: <span class="keyword">return</span>
        <span class="keyword">val</span> info = <span class="type">bufferInfo</span>

        <span class="comment">// Send via TCP socket</span>
        clientSocket?.<span class="type">outputStream</span>.<span class="type">write</span>(<span class="keyword">byteArrayOf</span>(
            <span class="number">0xAA</span>.<span class="type">toByte</span>(), <span class="number">0x55</span>.<span class="type">toByte</span>() <span class="comment">// Frame header</span>
        ))
        clientSocket?.<span class="type">outputStream</span>.<span class="type">write</span>(
            info.size.<span class="type">toByteArray</span>()
        )
        clientSocket?.<span class="type">outputStream</span>.<span class="type">write</span>(buffer)
        clientSocket?.<span class="type">outputStream</span>.<span class="type">flush</span>()
    }</pre>
