            <h3 style="color: #00d4ff; margin: 20px 0 10px;">3. InputRelayService.kt - Reverse Control (Accessibility)</h3>
            <div class="code-block">
                <button class="copy-btn" onclick="copyCode(this)">📋 Copy</button>
                <pre><span class="annotation">@AccessibilityService</span>
<span class="keyword">class</span> <span class="type">InputRelayService</span> : <span class="type">AccessibilityService</span>() {

    <span class="keyword">private</span> <span class="keyword">var</span> clientSocket: <span class="type">Socket</span>? = <span class="keyword">null</span>

    <span class="comment">// Input event types mapping</span>
    <span class="keyword">enum class</span> <span class="type">InputType</span> {
        TOUCH, SWIPE, KEY_EVENT, SCROLL, NAVIGATION
    }

    <span class="keyword">override</span> <span class="keyword">fun</span> <span class="type">onAccessibilityEvent</span>(event: <span class="type">AccessibilityEvent</span>?) {
        <span class="comment">// Forward accessibility events to TV if needed</span>
    }

    <span class="keyword">override</span> <span class="keyword">fun</span> <span class="type">onInterrupt</span>() {
        <span class="comment">// Handle interruption</span>
    }

    <span class="comment">// Handle incoming input commands from TV</span>
    <span class="keyword">fun</span> <span class="type">handleInputCommand</span>(<span class="type">command</span>: <span class="type">ByteArray</span>) {
        <span class="keyword">val</span> reader = <span class="type">DataInputStream</span>(
            <span class="type">ByteArrayInputStream</span>(command)
        )

        <span class="keyword">try</span> {
            <span class="keyword">val</span> type = reader.<span class="type">readInt</span>()
            <span class="keyword">val</span> x = reader.<span class="type">readInt</span>()
            <span class="keyword">val</span> y = reader.<span class="type">readInt</span>()
            <span class="keyword">val</span> action = reader.<span class="type">readInt</span>()

            <span class="keyword">when</span> (type) {
                <span class="type">InputType</span>.TOUCH.<span class="type">ordinal</span> -> {
                    <span class="type">performTouchInput</span>(x, y, action)
                }
                <span class="type">InputType</span>.KEY_EVENT.<span class="type">ordinal</span> -> {
                    <span class="type">performKeyEvent</span>(x, action)
                }
                <span class="type">InputType</span>.SWIPE.<span class="type">ordinal</span> -> {
                    <span class="type">performSwipe</span>(x, y, reader.<span class="type">readInt</span>())
                }
            }
        } <span class="keyword">catch</span> (e: <span class="type">IOException</span>) {
            <span class="type">Log</span>.<span class="type">e</span>(<span class="string">"InputRelay"</span>, <span class="string">"Error processing input"</span>, e)
        }
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">performTouchInput</span>(
        <span class="type">x</span>: <span class="type">Int</span>, <span class="type">y</span>: <span class="type">Int</span>, <span class="type">action</span>: <span class="type">Int</span>
    ) {
        <span class="keyword">val</span> movementEvent = <span class="type">MotionEvent</span>.<span class="type">obtain</span>(
            <span class="type">System</span>.<span class="type">uptimeMillis</span>(),
            <span class="type">System</span>.<span class="type">uptimeMillis</span>(),
            action, <span class="type">x</span>.<span class="type">toFloat</span>(), <span class="type">y</span>.<span class="type">toFloat</span>(), <span class="number">0</span>
        )

        <span class="comment">// Dispatch to current focused window</span>
        <span class="keyword">val</span> window = <span class="type">getCurrentWindow</span>()
        window?.<span class="type">decorView</span>?.<span class="type">dispatchTouchEvent</span>(movementEvent)

        movementEvent.<span class="type">recycle</span>()
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">performKeyEvent</span>(
        <span class="type">keyCode</span>: <span class="type">Int</span>, <span class="type">action</span>: <span class="type">Int</span>
    ) {
        <span class="keyword">val</span> keyEvent = <span class="type">KeyEvent</span>.<span class="type">obtain</span>(
            <span class="type">System</span>.<span class="type">uptimeMillis</span>(),
            <span class="type">System</span>.<span class="type">uptimeMillis</span>(),
            action, keyCode, <span class="number">0</span>,
            <span class="type">KeyEvent</span>.<span class="type">META_OFF</span>
        )

        <span class="keyword">val</span> window = <span class="type">getCurrentWindow</span>()
        window?.<span class="type">decorView</span>?.<span class="type">dispatchKeyEvent</span>(keyEvent)

        keyEvent.<span class="type">recycle</span>()
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">performSwipe</span>(
        <span class="type">startX</span>: <span class="type">Int</span>, <span class="type">startY</span>: <span class="type">Int</span>, <span class="type">endX</span>: <span class="type">Int</span>
    ) {
        <span class="keyword">val</span> endY = <span class="type">startY</span>
        <span class="keyword">val</span> duration = <span class="number">300</span>L

        <span class="keyword">val</span> downEvent = <span class="type">MotionEvent</span>.<span class="type">obtain</span>(
            <span class="type">System</span>.<span class="type">uptimeMillis</span>(), 
            <span class="type">System</span>.<span class="type">uptimeMillis</span>(),
            <span class="type">MotionEvent</span>.<span class="type">ACTION_DOWN</span>,
            <span class="type">startX</span>.<span class="type">toFloat</span>(), <span class="type">startY</span>.<span class="type">toFloat</span>(), <span class="number">0</span>
        )

        <span class="keyword">val</span> upEvent = <span class="type">MotionEvent</span>.<span class="type">obtain</span>(
            <span class="type">System</span>.<span class="type">uptimeMillis</span>() + duration,
            <span class="type">System</span>.<span class="type">uptimeMillis</span>() + duration,
            <span class="type">MotionEvent</span>.<span class="type">ACTION_UP</span>,
            <span class="type">endX</span>.<span class="type">toFloat</span>(), <span class="type">endY</span>.<span class="type">toFloat</span>(), <span class="number">0</span>
        )

        <span class="type">getCurrentWindow</span>()?.<span class="type">decorView</span>?.<span class="type">dispatchTouchEvent</span>(downEvent)
        <span class="type">getCurrentWindow</span>()?.<span class="type">decorView</span>?.<span class="type">dispatchTouchEvent</span>(upEvent)

        downEvent.<span class="type">recycle</span>()
        upEvent.<span class="type">recycle</span>()
    }</pre>
