            <h3 style="color: #00d4ff; margin: 20px 0 10px;">4. ScreenOffManager.kt - Screen Off While Streaming</h3>
            <div class="code-block">
                <button class="copy-btn" onclick="copyCode(this)">📋 Copy</button>
                <pre><span class="keyword">class</span> <span class="type">ScreenOffManager</span> <span class="keyword">private</span>(<span class="keyword">val</span> context: <span class="type">Context</span>) {

    <span class="keyword">private</span> <span class="keyword">var</span> powerManager: <span class="type">PowerManager</span>? = <span class="keyword">null</span>
    <span class="keyword">private</span> <span class="keyword">var</span> wakeLock: <span class="type">PowerManager</span>.<span class="type">WakeLock</span>? = <span class="keyword">null</span>
    <span class="keyword">private</span> <span class="keyword">var</span> windowManager: <span class="type">WindowManager</span>? = <span class="keyword">null</span>
    <span class="keyword">private</span> <span class="keyword">var</span> isScreenOff = <span class="keyword">false</span>

    <span class="keyword">fun</span> <span class="type">initialize</span>() {
        powerManager = context.<span class="type">getSystemService</span>(
            <span class="type">Context</span>.POWER_SERVICE
        ) <span class="keyword">as</span> <span class="type">PowerManager</span>

        windowManager = context.<span class="type">getSystemService</span>(
            <span class="type">Context</span>.WINDOW_SERVICE
        ) <span class="keyword">as</span> <span class="type">WindowManager</span>
    }

    <span class="keyword">fun</span> <span class="type">turnScreenOff</span>() {
        <span class="comment">// Keep CPU running but turn off display</span>
        wakeLock = powerManager?.<span class="type">newWakeLock</span>(
            <span class="type">PowerManager</span>.<span class="type">PARTIAL_WAKE_LOCK</span>,
            <span class="string">"ScreenMirror::WakeLock"</span>
        ).<span class="type">apply</span> {
            <span class="type">acquire</span>(<span class="number">30</span> * <span class="number">60</span> * <span class="number">1000</span>L) <span class="comment">// 30 min timeout</span>
        }

        <span class="comment">// Hide status bar and navigation bar</span>
        <span class="keyword">val</span> activity = context <span class="keyword">as</span> <span class="type">Activity</span>
        activity.<span class="type">window</span>.<span class="type">addFlags</span>(
            <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">FLAG_KEEP_SCREEN_ON</span> or
            <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">FLAG_FULLSCREEN</span> or
            <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">FLAG_LAYOUT_NO_LIMITS</span>
        )

        <span class="comment">// Create a transparent overlay to prevent screen from turning on</span>
        <span class="keyword">val</span> params = <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>().<span class="keyword">apply</span> {
            width = <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">MATCH_PARENT</span>
            height = <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">MATCH_PARENT</span>
            type = <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">TYPE_APPLICATION_OVERLAY</span>
            flags = <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">FLAG_NOT_TOUCHABLE</span> or
                    <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">FLAG_LAYOUT_IN_SCREEN</span>
            format = <span class="type">PixelFormat</span>.<span class="type">TRANSLUCENT</span>
        }

        <span class="keyword">val</span> overlayView = <span class="type">View</span>(context).<span class="keyword">apply</span> {
            <span class="type">alpha</span> = <span class="number">0.01f</span> <span class="comment">// Nearly invisible</span>
            <span class="type">background</span> = <span class="type">Color</span>.<span class="type">TRANSPARENT</span>.<span class="type">getDrawable</span>()
        }

        windowManager?.<span class="type">addView</span>(overlayView, params)
        isScreenOff = <span class="keyword">true</span>
    }

    <span class="keyword">fun</span> <span class="type">turnScreenOn</span>() {
        wakeLock?.<span class="type">release</span>()
        isScreenOff = <span class="keyword">false</span>

        <span class="keyword">val</span> activity = context <span class="keyword">as</span> <span class="type">Activity</span>
        activity.<span class="type">window</span>.<span class="type">clearFlags</span>(
            <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">FLAG_KEEP_SCREEN_ON</span> or
            <span class="type">WindowManager</span>.<span class="type">LayoutParams</span>.<span class="type">FLAG_FULLSCREEN</span>
        )
    }

    <span class="keyword">fun</span> <span class="type">isScreenOff</span>(): <span class="type">Boolean</span> = isScreenOff
}</pre>
