    <span class="keyword">fun</span> <span class="type">connectToMobile</span>(<span class="type">view</span>: <span class="type">View</span>) {
        <span class="keyword">thread</span>(name = <span class="string">"ConnectThread"</span>) {
            <span class="keyword">try</span> {
                <span class="comment">// Connect to mobile's hotspot IP</span>
                tcpSocket = <span class="type">Socket</span>(<span class="string">"192.168.43.1"</span>, <span class="number">8080</span>)
                udpSocket = <span class="type">DatagramSocket</span>()

                <span class="type">updateStatus</span>(<span class="string">"Connected to Mobile"</span>)
                isConnected = <span class="keyword">true</span>

                <span class="type">startVideoDecoder</span>()
                <span class="type">startInputRelay</span>()

            } <span class="keyword">catch</span> (e: <span class="type">IOException</span>) {
                <span class="type">updateStatus</span>(<span class="string">"Connection failed: </span>${e.message}<span class="string">"</span>)
            }
        }
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">initializeDecoder</span>() {
        <span class="keyword">val</span> format = <span class="type">MediaFormat</span>.<span class="type">createVideoFormat</span>(
            <span class="string">"video/avc"</span>, <span class="number">1920</span>, <span class="number">1080</span>
        ).<span class="keyword">apply</span> {
            <span class="type">setInteger</span>(<span class="type">MediaFormat</span>.KEY_COLOR_FORMAT,
                <span class="type">MediaCodecInfo</span>.<span class="type">CodecCapabilities</span>.<span class="type">COLOR_FormatSurface</span>)
        }

        mediaCodec = <span class="type">MediaCodec</span>.<span class="type">createDecoderByType</span>(<span class="string">"video/avc"</span>)
        mediaCodec.<span class="type">configure</span>(format, surface, <span class="keyword">null</span>, <span class="number">0</span>)
        mediaCodec.<span class="type">start</span>()
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">startVideoDecoder</span>() {
        <span class="keyword">thread</span>(name = <span class="string">"DecoderThread"</span>) {
            <span class="keyword">val</span> inputStream = tcpSocket.<span class="type">inputStream</span>
            <span class="keyword">val</span> buffer = <span class="type">ByteArray</span>(<span class="number">8192</span>)
            <span class="keyword">val</span> codec = mediaCodec

            <span class="keyword">while</span> (isConnected) {
                <span class="keyword">val</span> bytesRead = inputStream.<span class="type">read</span>(buffer)
                <span class="keyword">if</span> (bytesRead > <span class="number">0</span>) {
                    <span class="type">decodeFrame</span>(buffer, bytesRead)
                }
            }
        }
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">decodeFrame</span>(
        <span class="type">data</span>: <span class="type">ByteArray</span>, <span class="type">length</span>: <span class="type">Int</span>
    ) {
        <span class="keyword">val</span> codec = mediaCodec
        <span class="keyword">val</span> inputBufIndex = codec.<span class="type">dequeueInputBuffer</span>(<span class="number">10000</span>L)

        <span class="keyword">if</span> (inputBufIndex >= <span class="number">0</span>) {
            <span class="keyword">val</span> inputBuffer = codec.<span class="type">getInputBuffer</span>(inputBufIndex)
            inputBuffer?.<span class="type">put</span>(data, <span class="number">0</span>, length)

            codec.<span class="type">queueInputBuffer</span>(
                inputBufIndex, <span class="number">0</span>, length,
                <span class="type">System</span>.<span class="type">currentTimeMillis</span>() * <span class="number">1000</span>, <span class="number">0</span>
            )
        }

        <span class="keyword">val</span> outputBufIndex = codec.<span class="type">dequeueOutputBuffer</span>(
            <span class="type">bufferInfo</span>, <span class="number">10000</span>L
        )

        <span class="keyword">if</span> (outputBufIndex >= <span class="number">0</span>) {
            codec.<span class="type">releaseOutputBuffer</span>(outputBufIndex, <span class="keyword">true</span>)
        }
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">setupInputListeners</span>() {
        <span class="comment">// Handle TV remote input</span>
        <span class="type">findViewById</span>&lt;<span class="type">View</span>&gt;(R.id.<span class="type">surfaceView</span>)
            .<span class="type">setOnKeyListener</span> { <span class="type">v</span>, <span class="type">keyCode</span>, <span class="type">event</span> ->
                <span class="keyword">if</span> (event.<span class="type">action</span> == <span class="type">MotionEvent</span>.<span class="type">ACTION_DOWN</span>) {
                    <span class="type">sendInputToMobile</span>(
                        <span class="type">InputType</span>.KEY_EVENT, 
                        keyCode, <span class="number">0</span>, 
                        <span class="type">event</span>.<span class="type">action</span>
                    )
                    <span class="keyword">true</span>
                } <span class="keyword">else</span> {
                    <span class="keyword">false</span>
                }
            }

        <span class="comment">// Handle touch/mouse input</span>
        <span class="type">findViewById</span>&lt;<span class="type">View</span>&gt;(R.id.<span class="type">surfaceView</span>)
            .<span class="type">setOnTouchListener</span> { <span class="type">v</span>, <span class="type">event</span> ->
                <span class="type">sendInputToMobile</span>(
                    <span class="type">InputType</span>.TOUCH,
                    event.<span class="type">x</span>.<span class="type">toInt</span>(),
                    event.<span class="type">y</span>.<span class="type">toInt</span>(),
                    event.<span class="type">action</span>
                )
                <span class="keyword">true</span>
            }
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">sendInputToMobile</span>(
        <span class="type">type</span>: <span class="type">InputType</span>,
        <span class="type">x</span>: <span class="type">Int</span>,
        <span class="type">y</span>: <span class="type">Int</span>,
        <span class="type">action</span>: <span class="type">Int</span>
    ) {
        <span class="keyword">val</span> outputStream = tcpSocket.<span class="type">outputStream</span>
        <span class="keyword">val</span> data = <span class="type">ByteArray</span>(<span class="number">16</span>).<span class="keyword">apply</span> {
            <span class="type">putInt</span>(<span class="number">0</span>, type.<span class="type">ordinal</span>)
            <span class="type">putInt</span>(<span class="number">4</span>, x)
            <span class="type">putInt</span>(<span class="number">8</span>, y)
            <span class="type">putInt</span>(<span class="number">12</span>, action)
        }
        outputStream.<span class="type">write</span>(data)
        outputStream.<span class="type">flush</span>()
    }
}</pre>
