                <pre><span class="keyword">class</span> <span class="type">InputSender</span> <span class="keyword">private</span>(<span class="keyword">val</span> socket: <span class="type">Socket</span>) {

    <span class="keyword">enum class</span> <span class="type">InputType</span> {
