    <span class="keyword">fun</span> <span class="type">sendKeyEvent</span>(
        <span class="type">keyCode</span>: <span class="type">Int</span>, <span class="type">action</span>: <span class="type">Int</span>
    ) {
        <span class="keyword">val</span> data = <span class="type">ByteArray</span>(<span class="number">16</span>).<span class="keyword">apply</span> {
            <span class="type">putInt</span>(<span class="number">0</span>, <span class="type">InputType</span>.KEY_EVENT.<span class="type">ordinal</span>)
            <span class="type">putInt</span>(<span class="number">4</span>, keyCode)
            <span class="type">putInt</span>(<span class="number">8</span>, action)
        }
        <span class="type">send</span>(data)
    }

    <span class="keyword">fun</span> <span class="type">sendSwipeEvent</span>(
        <span class="type">startX</span>: <span class="type">Float</span>, <span class="type">startY</span>: <span class="type">Float</span>,
        <span class="type">endX</span>: <span class="type">Float</span>, <span class="type">endY</span>: <span class="type">Float</span>
    ) {
        <span class="keyword">val</span> data = <span class="type">ByteArray</span>(<span class="number">24</span>).<span class="keyword">apply</span> {
            <span class="type">putInt</span>(<span class="number">0</span>, <span class="type">InputType</span>.SWIPE.<span class="type">ordinal</span>)
            <span class="type">putInt</span>(<span class="number">4</span>, startX.<span class="type">toInt</span>())
            <span class="type">putInt</span>(<span class="number">8</span>, startY.<span class="type">toInt</span>())
            <span class="type">putInt</span>(<span class="number">12</span>, endX.<span class="type">toInt</span>())
            <span class="type">putInt</span>(<span class="number">16</span>, endY.<span class="type">toInt</span>())
        }
        <span class="type">send</span>(data)
    }

    <span class="keyword">private</span> <span class="keyword">fun</span> <span class="type">send</span>(<span class="type">data</span>: <span class="type">ByteArray</span>) {
        <span class="keyword">try</span> {
