            <h3 style="color: #00d4ff; margin: 20px 0 10px;">Protocol Specification</h3>
            <div class="code-block">
                <button class="copy-btn" onclick="copyCode(this)">📋 Copy</button>
                <pre><span class="comment">/*
 * ============================================
 * SCREEN MIRRORING PROTOCOL SPECIFICATION
 * ============================================
 * 
 * Transport: TCP (video) + UDP (input/controls)
 * Video Codec: H.264 (AVC) / H.265 (HEVC)
 * Frame Rate: 30-60 FPS
 * Resolution: Up to 1920x1080
 * Bitrate: 4-16 Mbps (adaptive)
 * Latency Target: &lt; 50ms
 */</span>

<span class="comment">// === TCP Protocol (Video Stream) ===</span>

<span class="comment">// Frame Header Structure (16 bytes)</span>
<span class="keyword">struct</span> <span class="type">FrameHeader</span> {
    <span class="type">uint32</span>  magic;        <span class="comment">// 0xAA55AA55</span>
    <span class="type">uint32</span>  frameNumber;  <span class="comment">// Sequential frame counter</span>
    <span class="type">uint32</span>  dataSize;     <span class="comment">// Size of payload in bytes</span>
    <span class="type">uint32</span>  timestamp;    <span class="comment">// Unix timestamp in microseconds</span>
}

<span class="comment">// Video Frame Payload</span>
<span class="keyword">struct</span> <span class="type">VideoFrame</span> {
    <span class="type">FrameHeader</span> header;
    <span class="type">byte[]</span>      payload;  <span class="comment">// Encoded H.264 NAL units</span>
}

<span class="comment">// === UDP Protocol (Input Commands) ===</span>

<span class="comment">// Input Command Structure (32 bytes)</span>
<span class="keyword">struct</span> <span class="type">InputCommand</span> {
    <span class="type">uint8</span>   type;         <span class="comment">// 0=TOUCH, 1=KEY, 2=SWIPE, 3=SCROLL</span>
    <span class="type">uint8</span>   action;       <span class="comment">// DOWN, UP, MOVE</span>
    <span class="type">int16</span>   x;            <span class="comment">// X coordinate</span>
    <span class="type">int16</span>   y;            <span class="comment">// Y coordinate</span>
    <span class="type">uint32</span>  keyCode;      <span class="comment">// For KEY events</span>
    <span class="type">uint32</span>  timestamp;    <span class="comment">// Timestamp in microseconds</span>
    <span class="type">uint16</span>  padding;      <span class="comment">// Alignment padding</span>
}

<span class="comment">// === Control Messages (TCP) ===</span>

<span class="keyword">enum</span> <span class="type">ControlMessage</span> : <span class="type">uint8</span> {
    CONNECT_REQUEST = <span class="number">0x01</span>,
    CONNECT_RESPONSE = <span class="number">0x02</span>,
    DISCONNECT = <span class="number">0x03</span>,
    SCREEN_OFF = <span class="number">0x04</span>,
    SCREEN_ON = <span class="number">0x05</span>,
    HEARTBEAT = <span class="number">0x06</span>,
    QUALITY_CHANGE = <span class="number">0x07</span>,
    DEVICE_INFO = <span class="number">0x08</span>,
}

<span class="comment">// === Connection Handshake ===</span>

<span class="comment">// 1. Mobile starts TCP server on port 8080</span>
<span class="comment">// 2. TV connects to Mobile's IP:8080</span>
<span class="comment">// 3. TV sends CONNECT_REQUEST with device info</span>
<span class="comment">// 4. Mobile responds with CONNECT_RESPONSE + capabilities</span>
<span class="comment">// 5. Video stream begins</span>

<span class="comment">// === Heartbeat (every 5 seconds) ===</span>
<span class="keyword">struct</span> <span class="type">Heartbeat</span> {
    <span class="type">uint8</span>   type = HEARTBEAT;
    <span class="type">uint32</span>  mobileCpu;    <span class="comment">// Mobile CPU usage %</span>
    <span class="type">uint32</span>  tvCpu;        <span class="comment">// TV CPU usage %</span>
    <span class="type">uint32</span>  latency;      <span class="comment">// Round-trip latency in ms</span>
    <span class="type">uint32</span>  bitrate;      <span class="comment">// Current bitrate in kbps</span>
}

<span class="comment">// === Quality Adaptation ===</span>
<span class="comment">// If latency &gt; 100ms for 3+ seconds:</span>
<span class="comment">//   → Reduce bitrate by 25%</span>
<span class="comment">//   → Reduce frame rate to 30 FPS</span>
<span class="comment">// If latency &lt; 30ms for 5+ seconds:</span>
<span class="comment">//   → Increase bitrate by 25%</span>
<span class="comment">//   → Increase frame rate to 60 FPS</span></pre>
            </div>

