    <script>
        // Tab switching
        function switchTab(tabId) {
            document.querySelectorAll('.tab-content').forEach(tab => {
                tab.classList.remove('active');
            });
            document.querySelectorAll('.tab').forEach(tab => {
                tab.classList.remove('active');
            });
            document.getElementById(tabId).classList.add('active');
            event.target.classList.add('active');
        }

        // Copy code function
        function copyCode(btn) {
            const codeBlock = btn.parentElement;
            const pre = codeBlock.querySelector('pre');
            const text = pre.textContent;
            navigator.clipboard.writeText(text).then(() => {
                btn.textContent = '✅ Copied!';
                setTimeout(() => {
                    btn.textContent = '📋 Copy';
                }, 2000);
            });
        }

        // Simulation state
        let simulationState = {
            mobileServerRunning: false,
            tvConnected: false,
            screenOff: false,
            mobileCpu: 0,
            tvCpu: 0,
            latency: 0,
            bitrate: 0,
            fps: 0,
            animationInterval: null
        };

        function addLog(message, type = 'info') {
            const logPanel = document.getElementById('logPanel');
            const timestamp = new Date().toLocaleTimeString('en-US', { hour12: false });
            const entry = document.createElement('div');
            entry.className = 'log-entry';
            entry.innerHTML = `<span class="timestamp">[${timestamp}]</span> <span class="${type}">${message}</span>`;
            logPanel.appendChild(entry);
            logPanel.scrollTop = logPanel.scrollHeight;
        }

        function startMobileServer() {
            simulationState.mobileServerRunning = true;
            document.getElementById('mobileStartBtn').disabled = true;
            document.getElementById('mobileStopBtn').disabled = false;
            document.getElementById('screenOffBtn').disabled = false;

            const mobileScreen = document.getElementById('mobileScreen');
            mobileScreen.classList.add('streaming');
            document.getElementById('mobileScreenContent').innerHTML = '📱 Mobile Screen<br><small>Streaming to TV...</small>';

            document.getElementById('mobileStatusDot').classList.add('connected');
            document.getElementById('mobileStatusText').textContent = 'Server Running';

            simulationState.mobileCpu = 92;
            updateCpuDisplay('mobile', 92);

            addLog('Mobile server started on port 8080', 'success');
            addLog('MediaProjection API initialized', 'info');
            addLog('H.264 hardware encoder activated', 'info');
            addLog('Waiting for TV connection...', 'warning');
        }

        function stopMobileServer() {
            simulationState.mobileServerRunning = false;
            document.getElementById('mobileStartBtn').disabled = false;
            document.getElementById('mobileStopBtn').disabled = true;
            document.getElementById('screenOffBtn').disabled = true;

            const mobileScreen = document.getElementById('mobileScreen');
            mobileScreen.classList.remove('streaming');
            document.getElementById('mobileScreenContent').innerHTML = '📱 Mobile Screen<br><small>Server stopped</small>';

            document.getElementById('mobileStatusDot').classList.remove('connected');
            document.getElementById('mobileStatusText').textContent = 'Disconnected';

            simulationState.mobileCpu = 0;
            updateCpuDisplay('mobile', 0);

