    <span class="keyword">private const string</span> <span class="property">SAVE_DIR</span> = <span class="string">"Saves"</span>;
    <span class="keyword">private const string</span> <span class="property">BACKUP_DIR</span> = <span class="string">"Saves/Backups"</span>;
    <span class="keyword">private const string</span> <span class="property">VERSION</span> = <span class="string">"1.0.0"</span>;

    <span class="keyword">private</span> <span class="type">SaveFormat</span> _format = <span class="type">SaveFormat</span>.JSON;
    <span class="keyword">private</span> <span class="type">bool</span> _encrypt = <span class="keyword">false</span>;
    <span class="keyword">private</span> <span class="type">string</span> _encryptionKey = <span class="string">"your-32-character-encryption-key-here!!"</span>;

    <span class="keyword">private</span> <span class="type">Dictionary</span>&lt;<span class="type">string</span>, <span class="type">SaveData</span>&gt; _cache = <span class="keyword">new</span>();

    <span class="keyword">void</span> <span class="method">Awake</span>()
    {
