        {
            Destroy(gameObject);
            <span class="keyword">return</span>;
        }
        Instance = <span class="keyword">this</span>;
        DontDestroyOnLoad(gameObject);
        Directory.CreateDirectory(Path.Combine(Application.persistentDataPath, SAVE_DIR));
        Directory.CreateDirectory(Path.Combine(Application.persistentDataPath, BACKUP_DIR));
    }

    <span class="keyword">public</span> <span class="type">string</span> <span class="method">GetSavePath</span>(<span class="type">SaveSlot</span> slot = <span class="type">SaveSlot</span>.Slot1, <span class="type">string</span> customName = <span class="keyword">null</span>)
    {
        <span class="type">string</span> fileName = customName ?? slot.ToString().ToLower();
        <span class="type">string</span> extension = _format == <span class="type">SaveFormat</span>.JSON ? <span class="string">".json"</span> : <span class="string">".bin"</span>;
        <span class="keyword">return</span> Path.Combine(Application.persistentDataPath, SAVE_DIR, fileName + extension);
    }

    <span class="keyword">public</span> <span class="type">Task</span>&lt;<span class="type">bool</span>&gt; <span class="method">SaveAsync</span>(<span class="type">SaveData</span> data, <span class="type">SaveSlot</span> slot = <span class="type">SaveSlot</span>.Slot1, <span class="type">string</span> customName = <span class="keyword">null</span>)
    {
        <span class="keyword">return</span> Task.Run(() =&gt;
        {
