                }

                <span class="keyword">if</span> (_encrypt)
                {
                    content = <span class="method">Encrypt</span>(content);
                }

                File.WriteAllText(path, content);
                _cache[customName ?? slot.ToString()] = data;
                <span class="method">CreateBackup</span>(path);
                <span class="keyword">return true</span>;
            }
            <span class="keyword">catch</span> (Exception e)
            {
                Debug.LogError(<span class="string">$"[SaveManager] Save failed: {e.Message}"</span>);
                <span class="keyword">return false</span>;
            }
        });
    }

    <span class="keyword">public</span> <span class="type">Task</span>&lt;<span class="type">SaveData</span>&gt; <span class="method">LoadAsync</span>(<span class="type">SaveSlot</span> slot = <span class="type">SaveSlot</span>.Slot1, <span class="type">string</span> customName = <span class="keyword">null</span>)
    {
        <span class="keyword">return</span> Task.Run(() =&gt;
        {
            <span class="keyword">try</span>
            {
                <span class="type">string</span> path = <span class="method">GetSavePath</span>(slot, customName);
                <span class="keyword">if</span> (!File.Exists(path)) <span class="keyword">return null</span>;

                <span class="type">string</span> content = File.ReadAllText(path);

                <span class="keyword">if</span> (_encrypt)
                {
                    content = <span class="method">Decrypt</span>(content);
                }

                <span class="type">SaveData</span> data;
                <span class="keyword">if</span> (_format == <span class="type">SaveFormat</span>.JSON)
                {
