    }

    <span class="keyword">public</span> <span class="type">Task</span>&lt;<span class="type">bool</span>&gt; <span class="method">DeleteAsync</span>(<span class="type">SaveSlot</span> slot = <span class="type">SaveSlot</span>.Slot1, <span class="type">string</span> customName = <span class="keyword">null</span>)
    {
        <span class="keyword">return</span> Task.Run(() =&gt;
        {
            <span class="type">string</span> path = <span class="method">GetSavePath</span>(slot, customName);
            <span class="keyword">if</span> (File.Exists(path))
