            <span class="keyword">if</span> (!Directory.Exists(savePath)) <span class="keyword">return new</span> <span class="type">List</span>&lt;<span class="type">string</span>&gt;();
            <span class="keyword">return new</span> <span class="type">List</span>&lt;<span class="type">string</span>&gt;(Directory.GetFiles(savePath));
