    <span class="keyword">private string</span> <span class="method">Encrypt</span>(<span class="type">string</span> text)
    {
        <span class="keyword">using</span> (<span class="keyword">var</span> aes = System.Security.Cryptography.AES.Create())
        {
            aes.Key = System.Text.Encoding.UTF8.GetBytes(_encryptionKey.PadRight(<span class="number">32</span>).Substring(<span class="number">0</span>, <span class="number">32</span>));
            aes.IV = System.Text.Encoding.UTF8.GetBytes(_encryptionKey.PadRight(<span class="number">16</span>).Substring(<span class="number">0</span>, <span class="number">16</span>));
            <span class="keyword">var</span> encryptor = aes.CreateEncryptor();
            <span class="keyword">var</span> encrypted = encryptor.TransformFinalBlock(
                System.Text.Encoding.UTF8.GetBytes(text), <span class="number">0</span>, text.Length);
            <span class="keyword">return</span> Convert.ToBase64String(encrypted);
