    }

    <span class="keyword">private string</span> <span class="method">Decrypt</span>(<span class="type">string</span> ciphertext)
    {
        <span class="keyword">using</span> (<span class="keyword">var</span> aes = System.Security.Cryptography.AES.Create())
        {
