            aes.IV = System.Text.Encoding.UTF8.GetBytes(_encryptionKey.PadRight(<span class="number">16</span>).Substring(<span class="number">0</span>, <span class="number">16</span>));
            <span class="keyword">var</span> decryptor = aes.CreateDecryptor();
            <span class="keyword">var</span> encryptedBytes = Convert.FromBase64String(ciphertext);
            <span class="keyword">var</span> decrypted = decryptor.TransformFinalBlock(encryptedBytes, <span class="number">0</span>, encryptedBytes.Length);
            <span class="keyword">return</span> System.Text.Encoding.UTF8.GetString(decrypted);
        }
    }

    <span class="keyword">private byte</span>[] <span class="method">SerializeBinary</span>(<span class="type">object</span> obj)
    {
        <span class="keyword">using</span> (<span class="keyword">var</span> ms = <span class="keyword">new</span> MemoryStream())
