    <span class="keyword">private object</span> <span class="method">DeserializeBinary</span>(<span class="type">byte</span>[] data)
    {
        <span class="keyword">using</span> (<span class="keyword">var</span> ms = <span class="keyword">new</span> MemoryStream(data))
