        <pre><span class="keyword">using</span> System;
<span class="keyword">using</span> System.Collections.Generic;
<span class="keyword">using</span> UnityEngine;
<span class="keyword">using</span> Newtonsoft.Json;

<span class="keyword">public static class</span> <span class="type">SaveSystem</span>
{
    <span class="keyword">private static string</span> <span class="property">SavePath</span> =&gt;
        Path.Combine(Application.persistentDataPath, <span class="string">"save.json"</span>);

    <span class="keyword">public static void</span> <span class="method">Save</span>&lt;<span class="type">T</span>&gt;(<span class="type">T</span> data, <span class="type">string</span> filename = <span class="string">"save"</span>)
    {
        <span class="type">string</span> json = JsonConvert.SerializeObject(data, Formatting.Indented);
        File.WriteAllText(Path.Combine(Application.persistentDataPath, $"<span class="string">{filename}.json"</span>), json);
        Debug.Log(<span class="string">$"[SaveSystem] Saved: {filename}"</span>);
    }

    <span class="keyword">public static</span> <span class="type">T</span> <span class="method">Load</span>&lt;<span class="type">T</span>&gt;(<span class="type">string</span> filename = <span class="string">"save"</span>)
    {
        <span class="type">string</span> path = Path.Combine(Application.persistentDataPath, $"<span class="string">{filename}.json"</span>);
        <span class="keyword">if</span> (!File.Exists(path)) <span class="keyword">return</span> <span class="keyword">default</span>;
        <span class="type">string</span> json = File.ReadAllText(path);
        <span class="keyword">return</span> JsonConvert.DeserializeObject&lt;<span class="type">T</span>&gt;(json);
    }

    <span class="keyword">public static bool</span> <span class="method">Exists</span>(<span class="type">string</span> filename = <span class="string">"save"</span>)
    {
        <span class="keyword">return</span> File.Exists(Path.Combine(Application.persistentDataPath, $"<span class="string">{filename}.json"</span>));
    }

    <span class="keyword">public static void</span> <span class="method">Delete</span>(<span class="type">string</span> filename = <span class="string">"save"</span>)
    {
        <span class="type">string</span> path = Path.Combine(Application.persistentDataPath, $"<span class="string">{filename}.json"</span>);
        <span class="keyword">if</span> (File.Exists(path)) File.Delete(path);
    }

    <span class="keyword">public static</span> <span class="type">List</span>&lt;<span class="type">string</span>&gt; <span class="method">GetAllFilenames</span>()
    {
        <span class="keyword">var</span> dir = Application.persistentDataPath;
        <span class="keyword">var</span> files = Directory.GetFiles(dir, <span class="string">"*.json"</span>);
        <span class="keyword">var</span> names = <span class="keyword">new</span> <span class="type">List</span>&lt;<span class="type">string</span>&gt;();
        <span class="keyword">foreach</span> (<span class="keyword">var</span> f <span class="keyword">in</span> files)
        {
            names.Add(Path.GetFileNameWithoutExtension(f));
        }
        <span class="keyword">return</span> names;
    }
}</pre>
