<span class="comment">// ===== Vector2 Converter =====</span>
<span class="keyword">public class</span> <span class="type">Vector2Converter</span> : <span class="type">JsonConverter</span>&lt;<span class="type">Vector2</span>&gt;
{
    <span class="keyword">public override void</span> <span class="method">WriteJson</span>(<span class="type">JsonWriter</span> writer, <span class="type">Vector2</span> value, <span class="type">JsonSerializer</span> serializer)
    {
        writer.WriteStartObject();
        writer.WritePropertyName(<span class="string">"x"</span>);
        writer.WriteValue(value.x);
        writer.WritePropertyName(<span class="string">"y"</span>);
        writer.WriteValue(value.y);
        writer.WriteEndObject();
    }

    <span class="keyword">public override</span> <span class="type">Vector2</span> <span class="method">ReadJson</span>(<span class="type">JsonReader</span> reader, <span class="type">Type</span> objectType, <span class="type">Vector2</span> existingValue,
        <span class="type">bool</span> hasExistingValue, <span class="type">JsonSerializer</span> serializer)
    {
        <span class="keyword">var</span> obj = <span class="type">JObject</span>.Load(reader);
        <span class="keyword">return new</span> <span class="type">Vector2</span>((<span class="type">float</span>)obj[<span class="string">"x"</span>], (<span class="type">float</span>)obj[<span class="string">"y"</span>]);
    }
}

