        writer.WritePropertyName(<span class="string">"z"</span>); writer.WriteValue(value.z);
        writer.WriteEndObject();
    }

    <span class="keyword">public override</span> <span class="type">Vector3</span> <span class="method">ReadJson</span>(<span class="type">JsonReader</span> reader, <span class="type">Type</span> objectType, <span class="type">Vector3</span> existingValue,
