    <span class="keyword">public string</span> playerName;
    <span class="keyword">public bool</span> isPremium;
    <span class="keyword">public bool</span> notificationsEnabled;

    <span class="comment">// ===== Unity Math Types =====</span>
    <span class="keyword">public</span> <span class="type">Vector2</span> cameraOffset;
    <span class="keyword">public</span> <span class="type">Vector3</span> playerPosition;
    <span class="keyword">public</span> <span class="type">Vector3</span> playerRotation; <span class="comment">// stored as Euler angles</span>
    <span class="keyword">public</span> <span class="type">Quaternion</span> playerQuaternion;
