    <span class="keyword">public</span> <span class="type">Color</span> mainColor;
    <span class="keyword">public</span> <span class="type">Color32</span> uiColor;
    <span class="keyword">public</span> <span class="type">Rect</span> windowRect;

    <span class="comment">// ===== Enums =====</span>
    <span class="keyword">public</span> <span class="type">PlayerClass</span> playerClass;
    <span class="keyword">public</span> <span class="type">Difficulty</span> difficulty;

    <span class="comment">// ===== Collections =====</span>
    <span class="keyword">public</span> <span class="type">PlayerStats</span> stats;
    <span class="keyword">public</span> <span class="type">List</span>&lt;<span class="type">InventoryItem</span>&gt; inventory;
    <span class="keyword">public</span> <span class="type">string</span>[] unlockedLevels;
    <span class="keyword">public</span> <span class="type">int</span>[] achievements;
    <span class="keyword">public</span> <span class="type">Dictionary</span>&lt;<span class="type">string</span>, <span class="type">int</span>&gt; statsDictionary;
    <span class="keyword">public</span> <span class="type">Dictionary</span>&lt;<span class="type">string</span>, <span class="type">Vector3</span>&gt; checkpointPositions;

    <span class="comment">// ===== Special Types =====</span>
    <span class="keyword">public</span> <span class="type">DateTime</span> firstPlayed;
    <span class="keyword">public</span> <span class="type">DateTime</span> lastPlayed;
    <span class="keyword">public int</span> totalPlayTime; <span class="comment">// in seconds</span>

    <span class="keyword">public</span> <span class="type">PlayerSaveData</span>()
    {
        playerId = <span class="number">0</span>;
        highScore = <span class="number">0</span>;
        version = <span class="number">1</span>;
        volume = <span class="number">0.8f</span>;
        precisionValue = <span class="number">3.14159265</span>;
        playerName = <span class="string">"Player"</span>;
        isPremium = <span class="keyword">false</span>;
        notificationsEnabled = <span class="keyword">true</span>;

        cameraOffset = <span class="type">Vector2</span>.zero;
        playerPosition = <span class="type">Vector3</span>.zero;
        playerRotation = <span class="type">Vector3</span>.zero;
        playerQuaternion = <span class="type">Quaternion</span>.identity;
        customVector = <span class="type">Vector4</span>.zero;
        mainColor = <span class="type">Color</span>.white;
        uiColor = <span class="type">Color32</span>.white;
        windowRect = <span class="keyword">new</span> <span class="type">Rect</span>(<span class="number">0</span>, <span class="number">0</span>, <span class="number">800</span>, <span class="number">600</span>);

        playerClass = <span class="type">PlayerClass</span>.Warrior;
        difficulty = <span class="type">Difficulty</span>.Normal;

        stats = <span class="keyword">new</span> <span class="type">PlayerStats</span>();
        inventory = <span class="keyword">new</span> <span class="type">List</span>&lt;<span class="type">InventoryItem</span>&gt;();
        unlockedLevels = <span class="keyword">new</span> <span class="type">string</span>[] { <span class="string">"level1"</span> };
        achievements = <span class="keyword">new int</span>[] { <span class="number">0</span> };
        statsDictionary = <span class="keyword">new</span> <span class="type">Dictionary</span>&lt;<span class="type">string</span>, <span class="type">int</span>&gt;();
        checkpointPositions = <span class="keyword">new</span> <span class="type">Dictionary</span>&lt;<span class="type">string</span>, <span class="type">Vector3</span>&gt;();

        firstPlayed = DateTime.UtcNow;
        lastPlayed = DateTime.UtcNow;
        totalPlayTime = <span class="number">0</span>;
    }

    <span class="comment">// ===== Helper Methods =====</span>
    <span class="keyword">public void</span> <span class="method">AddToInventory</span>(<span class="type">string</span> itemId, <span class="type">string</span> itemName, <span class="type">int</span> quantity = <span class="number">1</span>)
    {
        <span class="keyword">var</span> existing = inventory.Find(i =&gt; i.itemId == itemId);
        <span class="keyword">if</span> (existing != <span class="keyword">null</span>)
        {
            existing.quantity += quantity;
        }
        <span class="keyword">else</span>
        {
            inventory.Add(<span class="keyword">new</span> <span class="type">InventoryItem</span>(itemId, itemName, quantity));
        }
    }

    <span class="keyword">public void</span> <span class="method">AddExperience</span>(<span class="type">float</span> amount)
    {
        stats.experience += amount;
        <span class="keyword">while</span> (stats.experience >= stats.level * <span class="number">100</span>)
        {
            stats.experience -= stats.level * <span class="number">100</span>;
            stats.level++;
            stats.maxHealth += <span class="number">10</span>;
            stats.health = stats.maxHealth;
            stats.maxMana += <span class="number">5</span>;
            stats.mana = stats.maxMana;
        }
    }
