<span class="keyword">using</span> System.IO;

<span class="attribute">[Serializable]</span>
<span class="keyword">public class</span> <span class="type">BinarySaveManager</span>
{
    <span class="keyword">public static void</span> <span class="method">Save</span>&lt;<span class="type">T</span>&gt;(<span class="type">T</span> data, <span class="type">string</span> path)
    {
        <span class="keyword">using</span> (<span class="keyword">var</span> ms = <span class="keyword">new</span> MemoryStream())
        {
            <span class="keyword">var</span> formatter = <span class="keyword">new</span> BinaryFormatter();
            formatter.Serialize(ms, data);
            File.WriteAllBytes(path, ms.ToArray());
        }
    }

    <span class="keyword">public static</span> <span class="type">T</span> <span class="method">Load</span>&lt;<span class="type">T</span>&gt;(<span class="type">string</span> path)
    {
        <span class="keyword">if</span> (!File.Exists(path)) <span class="keyword">return default</span>;
        <span class="keyword">using</span> (<span class="keyword">var</span> ms = <span class="keyword">new</span> MemoryStream(File.ReadAllBytes(path)))
        {
            <span class="keyword">var</span> formatter = <span class="keyword">new</span> BinaryFormatter();
            <span class="keyword">return</span> (<span class="type">T</span>)formatter.Deserialize(ms);
        }
    }
