                <pre><span class="keyword">using</span> UnityEngine;
<span class="keyword">using</span> Newtonsoft.Json;

<span class="keyword">public static class</span> <span class="type">ComponentSaver</span>
{
    <span class="keyword">public static</span> <span class="type">Dictionary</span>&lt;<span class="type">string</span>, <span class="type">object</span>&gt; <span class="method">SaveComponent</span>&lt;<span class="type">T</span>&gt;(<span class="type">T</span> component) <span class="keyword">where</span> <span class="type">T</span> : <span class="type">Component</span>
    {
        <span class="keyword">var</span> data = <span class="keyword">new</span> <span class="type">Dictionary</span>&lt;<span class="type">string</span>, <span class="type">object</span>&gt;();
        <span class="keyword">var</span> type = component.GetType();

        <span class="keyword">foreach</span> (<span class="keyword">var</span> prop <span class="keyword">in</span> type.GetProperties())
        {
            <span class="keyword">if</span> (prop.CanRead &amp;&amp; prop.CanWrite)
            {
                <span class="keyword">var</span> value = prop.GetValue(component);
                data[prop.Name] = value;
            }
        }

        <span class="keyword">return</span> data;
    }

    <span class="keyword">public static void</span> <span class="method">LoadComponent</span>&lt;<span class="type">T</span>&gt;(<span class="type">T</span> component, <span class="type">Dictionary</span>&lt;<span class="type">string</span>, <span class="type">object</span>&gt; data) <span class="keyword">where</span> <span class="type">T</span> : <span class="type">Component</span>
    {
        <span class="keyword">var</span> type = component.GetType();

        <span class="keyword">foreach</span> (<span class="keyword">var</span> kvp <span class="keyword">in</span> data)
        {
            <span class="keyword">var</span> prop = type.GetProperty(kvp.Key);
            <span class="keyword">if</span> (prop != <span class="keyword">null</span> &amp;&amp; prop.CanWrite)
            {
                <span class="keyword">try</span>
                {
                    prop.SetValue(component, kvp.Value);
                }
                <span class="keyword">catch</span>
                {
                    Debug.LogWarning(<span class="string">$"[ComponentSaver] Failed to set {kvp.Key}"</span>);
                }
            }
        }
    }
}</pre>
