<script>
  // Tab switching
  function switchTab(tabName) {
    document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    document.getElementById('panel-' + tabName).classList.add('active');
    event.target.closest('.tab').classList.add('active');
  }

  // Accordion
  function toggleAccordion(header) {
    const item = header.parentElement;
    item.classList.toggle('open');
  }

  // Copy code
  function copyCode(btn) {
    const codeBlock = btn.closest('.code-block');
    const pre = codeBlock.querySelector('pre');
    const text = pre.textContent;

    navigator.clipboard.writeText(text).then(() => {
      btn.classList.add('copied');
      btn.innerHTML = '✅ Copied!';
      showToast('Code copied to clipboard!');
      setTimeout(() => {
        btn.classList.remove('copied');
        btn.innerHTML = '📋 Copy';
      }, 2000);
    });
  }

  // Toast
  function showToast(message) {
    const toast = document.getElementById('toast');
    document.getElementById('toast-message').textContent = message;
    toast.classList.add('show');
    setTimeout(() => toast.classList.remove('show'), 3000);
  }

  // Scroll to top button
  window.addEventListener('scroll', () => {
    const btn = document.getElementById('scroll-top');
    if (window.scrollY > 300) {
      btn.classList.add('visible');
    } else {
      btn.classList.remove('visible');
    }
  });

  // Interactive Demo
  let demoSaveData = null;

  function updateDemo() {
    const healthVal = document.getElementById('demo-health').value;
    const manaVal = document.getElementById('demo-mana').value;
    const speedVal = document.getElementById('demo-speed').value;
    const volumeVal = (document.getElementById('demo-volume').value / 100).toFixed(2);

    document.getElementById('demo-health-val').textContent = healthVal;
    document.getElementById('demo-mana-val').textContent = manaVal;
    document.getElementById('demo-speed-val').textContent = speedVal;
    document.getElementById('demo-volume-val').textContent = volumeVal;

    const data = {
      playerName: document.getElementById('demo-name').value,
      level: parseInt(document.getElementById('demo-level').value),
      health: parseInt(healthVal),
      mana: parseInt(manaVal),
      attack: parseInt(document.getElementById('demo-attack').value),
      defense: parseInt(document.getElementById('demo-defense').value),
      speed: parseInt(speedVal),
      volume: parseFloat(volumeVal),
      position: {
        x: parseFloat(document.getElementById('demo-x').value),
        y: parseFloat(document.getElementById('demo-y').value),
        z: parseFloat(document.getElementById('demo-z').value)
      },
      isPremium: document.getElementById('demo-premium').value === 'true',
      timestamp: new Date().toISOString()
    };

    document.getElementById('json-preview').textContent = JSON.stringify(data, null, 2);
  }

  function addLog(type, message) {
    const log = document.getElementById('save-log');
    const time = new Date().toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const entry = document.createElement('div');
    entry.className = 'log-entry';
    entry.innerHTML = `
      <span class="log-time">[${time}]</span>
      <span class="log-type ${type}">${type.toUpperCase()}</span>
      <span class="log-message">${message}</span>
    `;
    log.insertBefore(entry, log.firstChild);
  }

  function demoSave() {
    const data = {
      playerName: document.getElementById('demo-name').value,
      level: parseInt(document.getElementById('demo-level').value),
      health: parseInt(document.getElementById('demo-health').value),
      mana: parseInt(document.getElementById('demo-mana').value),
      attack: parseInt(document.getElementById('demo-attack').value),
      defense: parseInt(document.getElementById('demo-defense').value),
      speed: parseInt(document.getElementById('demo-speed').value),
      volume: parseFloat(document.getElementById('demo-volume').value / 100).toFixed(2),
      position: {
        x: parseFloat(document.getElementById('demo-x').value),
        y: parseFloat(document.getElementById('demo-y').value),
        z: parseFloat(document.getElementById('demo-z').value)
      },
      isPremium: document.getElementById('demo-premium').value === 'true',
      timestamp: new Date().toISOString()
    };

    demoSaveData = data;
    localStorage.setItem('unitySaveDemo', JSON.stringify(data));
    addLog('save', `Saved: ${data.playerName} (Level ${data.level}, HP ${data.health})`);
    showToast('Game saved successfully!');
  }

  function demoLoad() {
    const saved = localStorage.getItem('unitySaveDemo');
    if (saved) {
      demoSaveData = JSON.parse(saved);
      document.getElementById('demo-name').value = demoSaveData.playerName || '';
      document.getElementById('demo-level').value = demoSaveData.level || 1;
      document.getElementById('demo-health').value = demoSaveData.health || 100;
      document.getElementById('demo-mana').value = demoSaveData.mana || 50;
      document.getElementById('demo-attack').value = demoSaveData.attack || 10;
      document.getElementById('demo-defense').value = demoSaveData.defense || 5;
      document.getElementById('demo-speed').value = demoSaveData.speed || 5;
      document.getElementById('demo-volume').value = (demoSaveData.volume || 0.8) * 100;
      document.getElementById('demo-x').value = demoSaveData.position?.x || 0;
      document.getElementById('demo-y').value = demoSaveData.position?.y || 0;
      document.getElementById('demo-z').value = demoSaveData.position?.z || 0;
      document.getElementById('demo-premium').value = demoSaveData.isPremium?.toString() || 'false';
      updateDemo();
      addLog('load', `Loaded: ${demoSaveData.playerName} (Level ${demoSaveData.level})`);
      showToast('Game loaded successfully!');
    } else {
      addLog('info', 'No save data found. Save first!');
      showToast('No save data found!');
    }
  }

  function demoDelete() {
    localStorage.removeItem('unitySaveDemo');
    demoSaveData = null;
    addLog('delete', 'Save data deleted.');
    showToast('Save data deleted!');
  }

  function demoReset() {
    document.getElementById('demo-name').value = 'Hero';
    document.getElementById('demo-level').value = 1;
    document.getElementById('demo-health').value = 100;
    document.getElementById('demo-mana').value = 50;
    document.getElementById('demo-attack').value = 10;
    document.getElementById('demo-defense').value = 5;
    document.getElementById('demo-speed').value = 5;
    document.getElementById('demo-volume').value = 80;
    document.getElementById('demo-x').value = 0;
    document.getElementById('demo-y').value = 0;
    document.getElementById('demo-z').value = 0;
    document.getElementById('demo-premium').value = 'false';
    updateDemo();
    addLog('info', 'Demo reset to defaults.');
    showToast('Demo reset!');
  }

  // Initialize demo
  updateDemo();
</script>
</body>
</html>

