    align-items: center;
    gap: 10px;
  }

  #player-hp-bar {
    width: 200px;
    height: 14px;
    background: #1a1a2a;
    border: 1px solid #3a3a4a;
    border-radius: 7px;
    overflow: hidden;
  }

  #player-hp-fill {
    height: 100%;
    background: linear-gradient(90deg, #3a8b3a, #6bff6b);
    transition: width 0.5s;
    border-radius: 7px;
  }

  #energy-display {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 5px 15px;
    background: rgba(20, 20, 30, 0.8);
    border: 1px solid #c9a84c;
    border-radius: 5px;
  }

  .energy-orb {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: radial-gradient(circle, #ffd700, #c9a84c);
    box-shadow: 0 0 10px rgba(255, 215, 0, 0.5);
    display: inline-block;
  }

  .energy-orb.used {
    background: radial-gradient(circle, #3a3a4a, #2a2a3a);
    box-shadow: none;
  }

  #hand-container {
    display: flex;
    justify-content: center;
    gap: 10px;
    flex-wrap: wrap;
    max-width: 900px;
    padding: 0 10px;
  }

  .card {
    width: 130px;
    height: 180px;
    background: linear-gradient(180deg, #1a1a2e 0%, #0a0a1a 100%);
    border: 2px solid #3a3a4a;
    border-radius: 10px;
    padding: 8px;
    cursor: pointer;
    transition: all 0.3s;
    position: relative;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  .card:hover {
    transform: translateY(-20px);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), 0 0 15px rgba(201, 168, 76, 0.2);
    border-color: #c9a84c;
    z-index: 20;
  }

  .card.playable {
    border-color: #c9a84c;
  }

  .card.unplayable {
    opacity: 0.5;
    cursor: not-allowed;
  }

  .card.unplayable:hover {
    transform: translateY(-5px);
  }

  .card-cost {
    position: absolute;
    top: 5px;
    left: 5px;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: radial-gradient(circle, #ffd700, #c9a84c);
    color: #0a0a0f;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 900;
    font-size: 0.9em;
    z-index: 2;
  }

  .card-type {
    position: absolute;
    top: 5px;
    right: 5px;
    font-size: 0.7em;
    padding: 2px 6px;
    border-radius: 3px;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .card-type.attack {
    background: rgba(139, 58, 58, 0.5);
    color: #ff6b6b;
  }

  .card-type.skill {
    background: rgba(58, 58, 139, 0.5);
    color: #6b6bff;
  }

  .card-type.power {
    background: rgba(58, 139, 58, 0.5);
    color: #6bff6b;
  }

  .card-type.curse {
    background: rgba(139, 58, 139, 0.5);
    color: #ff6bff;
  }

  .card-icon {
    font-size: 2em;
    text-align: center;
    margin-top: 25px;
    margin-bottom: 5px;
  }

  .card-name {
    font-size: 0.75em;
    font-weight: 700;
    color: #c9a84c;
    text-align: center;
    margin-bottom: 5px;
    line-height: 1.2;
  }

  .card-desc {
    font-size: 0.65em;
    color: #8b8b9b;
    text-align: center;
    line-height: 1.3;
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0 3px;
  }

  .card-image {
    width: 100%;
    height: 50px;
    margin-top: 5px;
    border-radius: 5px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5em;
  }

  /* Draft Screen */
  #draft-screen {
    background: radial-gradient(ellipse at center, #1a1a2e 0%, #0a0a0f 70%);
  }

  #draft-container {
    text-align: center;
    max-width: 900px;
    width: 90%;
  }

  #draft-container h2 {
    font-size: 2em;
    color: #c9a84c;
    margin-bottom: 10px;
    text-shadow: 0 0 20px rgba(201, 168, 76, 0.3);
  }

  #draft-container .draft-desc {
    color: #6b5b4a;
    margin-bottom: 30px;
    font-size: 0.9em;
  }

  #draft-cards {
    display: flex;
    justify-content: center;
    gap: 20px;
    flex-wrap: wrap;
    margin-bottom: 30px;
  }

  #draft-cards .card {
    width: 160px;
    height: 220px;
  }

  #draft-cards .card:hover {
    transform: translateY(-15px) scale(1.05);
  }

  #draft-info {
    font-size: 0.9em;
    color: #6b5b4a;
    margin-bottom: 20px;
  }

  /* Game Over / Victory */
  #gameover-screen, #victory-screen {
    background: radial-gradient(ellipse at center, #1a1a2e 0%, #0a0a0f 70%);
  }

  #gameover-screen h1 {
    font-size: 3em;
    color: #ff4444;
    text-shadow: 0 0 30px rgba(255, 68, 68, 0.5);
    margin-bottom: 15px;
  }

  #victory-screen h1 {
    font-size: 3em;
    color: #ffd700;
    text-shadow: 0 0 30px rgba(255, 215, 0, 0.5);
    margin-bottom: 15px;
  }

  .final-stats {
    margin: 20px 0;
    padding: 20px;
    background: rgba(20, 20, 30, 0.8);
    border: 1px solid #3a3a4a;
    border-radius: 10px;
    text-align: center;
  }

  .final-stats p {
    margin: 8px 0;
    font-size: 1em;
  }

  /* Damage popup */
  .damage-popup {
    position: absolute;
    font-size: 2em;
    font-weight: 900;
    pointer-events: none;
    animation: damageFloat 1s ease-out forwards;
    z-index: 100;
  }

  .damage-popup.player-dmg {
    color: #ff4444;
    text-shadow: 0 0 10px rgba(255, 68, 68, 0.5);
  }

  .damage-popup.enemy-dmg {
    color: #ff6b6b;
    text-shadow: 0 0 10px rgba(255, 107, 107, 0.5);
  }

  .damage-popup.block {
    color: #6b9bff;
    text-shadow: 0 0 10px rgba(107, 155, 255, 0.5);
  }

  .damage-popup.heal {
    color: #6bff6b;
    text-shadow: 0 0 10px rgba(107, 255, 107, 0.5);
  }

  @keyframes damageFloat {
    0% { opacity: 1; transform: translateY(0) scale(1); }
    100% { opacity: 0; transform: translateY(-60px) scale(1.5); }
  }

  /* Card play animation */
  .card.playing {
    animation: cardPlay 0.3s ease-out;
  }

  @keyframes cardPlay {
    0% { transform: scale(1); }
    50% { transform: scale(1.1) translateY(-30px); }
    100% { transform: scale(0) translateY(-50px); opacity: 0; }
  }

  /* Enemy hit animation */
  .enemy-hit {
    animation: enemyHit 0.3s ease-out;
  }

  @keyframes enemyHit {
    0% { transform: translateX(0); }
    25% { transform: translateX(-10px); }
    50% { transform: translateX(10px); }
    75% { transform: translateX(-5px); }
    100% { transform: translateX(0); }
  }

  /* Player hit animation */
  .player-hit {
    animation: playerHit 0.3s ease-out;
  }

  @keyframes playerHit {
    0% { transform: translateX(0); }
    25% { transform: translateX(-5px); }
    50% { transform: translateX(5px); }
    75% { transform: translateX(-3px); }
    100% { transform: translateX(0); }
  }

  /* Deck view */
  #deck-view {
    position: absolute;
    top: 10px;
    right: 10px;
    display: flex;
    gap: 5px;
  }

  .deck-counter {
    padding: 5px 10px;
    background: rgba(20, 20, 30, 0.8);
    border: 1px solid #3a3a4a;
    border-radius: 5px;
    font-size: 0.8em;
    color: #8b8b9b;
  }

  .deck-counter span {
    color: #c9a84c;
    font-weight: 700;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: #0a0a0f;
  }

  ::-webkit-scrollbar-thumb {
    background: #3a3a4a;
    border-radius: 4px;
  }

  /* Event screen */
  #event-screen {
    background: radial-gradient(ellipse at center, #1a1a2e 0%, #0a0a0f 70%);
  }

  #event-container {
    max-width: 600px;
    text-align: center;
    padding: 40px;
    background: rgba(20, 20, 30, 0.9);
    border: 1px solid #3a3a4a;
    border-radius: 15px;
  }

  #event-container h2 {
    font-size: 1.8em;
    color: #c9a84c;
    margin-bottom: 15px;
  }

  #event-container p {
    color: #8b8b9b;
    margin-bottom: 25px;
    line-height: 1.6;
    font-size: 0.95em;
  }

  #event-choices {
    display: flex;
    flex-direction: column;
    gap: 10px;
    align-items: center;
  }

  /* Rest screen */
  #rest-screen {
    background: radial-gradient(ellipse at center, #1a1a2e 0%, #0a0a0f 70%);
  }

  #rest-container {
    max-width: 500px;
    text-align: center;
    padding: 40px;
    background: rgba(20, 20, 30, 0.9);
    border: 1px solid #3a8b3a;
    border-radius: 15px;
  }

  #rest-container h2 {
    font-size: 1.8em;
    color: #6bff6b;
    margin-bottom: 15px;
  }

  #rest-container p {
    color: #8b8b9b;
    margin-bottom: 25px;
  }

  /* Shop screen */
  #shop-screen {
    background: radial-gradient(ellipse at center, #1a1a2e 0%, #0a0a0f 70%);
  }

  #shop-container {
    max-width: 800px;
    text-align: center;
    width: 90%;
  }

  #shop-container h2 {
    font-size: 1.8em;
    color: #ffd700;
    margin-bottom: 10px;
  }

  #shop-gold {
    font-size: 1.2em;
    color: #ffd700;
    margin-bottom: 20px;
  }

  #shop-cards {
    display: flex;
    justify-content: center;
    gap: 15px;
    flex-wrap: wrap;
    margin-bottom: 20px;
  }

  #shop-cards .card {
    width: 140px;
    height: 190px;
  }

  .shop-price {
    position: absolute;
    bottom: 5px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 0.75em;
    color: #ffd700;
    font-weight: 700;
  }

  /* Notification */
  #notification {
    position: fixed;
    top: 20px;
    left: 50%;
    transform: translateX(-50%);
    padding: 10px 30px;
    background: rgba(20, 20, 30, 0.95);
    border: 1px solid #c9a84c;
    border-radius: 5px;
    color: #c9a84c;
    font-size: 0.9em;
    z-index: 1000;
    opacity: 0;
    transition: opacity 0.3s;
    pointer-events: none;
  }

  #notification.show {
    opacity: 1;
  }

  /* Tooltip */
  .tooltip {
    position: absolute;
    background: rgba(10, 10, 15, 0.95);
    border: 1px solid #c9a84c;
    border-radius: 8px;
    padding: 10px 15px;
    max-width: 250px;
    z-index: 100;
    pointer-events: none;
    display: none;
  }

  .tooltip .tooltip-title {
    color: #c9a84c;
    font-weight: 700;
    margin-bottom: 5px;
  }

  .tooltip .tooltip-desc {
    color: #8b8b9b;
    font-size: 0.85em;
    line-height: 1.4;
  }

  /* Level up animation */
  .level-up {
    animation: levelUp 0.5s ease-out;
  }

  @keyframes levelUp {
    0% { transform: scale(1); }
    50% { transform: scale(1.2); }
    100% { transform: scale(1); }
  }

  /* Card back */
  .card-back {
    width: 130px;
    height: 180px;
    background: linear-gradient(135deg, #1a1a2e 0%, #0a0a1a 100%);
    border: 2px solid #3a3a4a;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2em;
    color: #3a3a4a;
  }

  /* Parchment texture overlay */
  .parchment {
    position: relative;
  }

  .parchment::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: url("data:image/svg+xml,%3Csvg width='100' height='100' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.03'/%3E%3C/svg%3E");
    pointer-events: none;
    border-radius: inherit;
  }
</style>
</head>
<body>
<div id="game-container">
  <canvas id="bg-canvas"></canvas>

  <!-- Title Screen -->
  <div id="title-screen" class="screen active">
    <h1>⚔ Shadows of the Abyss ⚔</h1>
    <p class="subtitle">A Roguelike Deck Builder</p>
    <button class="btn" onclick="startGame()">Enter the Abyss</button>
    <button class="btn small" onclick="showHelp()">How to Play</button>
  </div>

  <!-- Map Screen -->
  <div id="map-screen" class="screen">
    <div id="map-header">
      <div class="player-stats">
        <div class="stat-badge">
          <span class="icon">❤️</span>
          <span class="value" id="map-hp">100/100</span>
        </div>
        <div class="hp-bar">
          <div class="hp-bar-fill" id="map-hp-bar" style="width: 100%"></div>
        </div>
        <div class="stat-badge">
          <span class="icon">🏆</span>
          <span class="value" id="map-floor">Floor 1</span>
        </div>
        <div class="stat-badge">
          <span class="icon">💀</span>
          <span class="value" id="map-kills">0</span>
        </div>
      </div>
      <button class="btn small" onclick="viewDeck()">View Deck</button>
    </div>
    <div id="map-container"></div>
  </div>

  <!-- Combat Screen -->
  <div id="combat-screen" class="screen">
    <div id="combat-area">
      <div id="enemy-area">
        <div id="enemy-sprite">👹</div>
        <div id="enemy-info">
          <div id="enemy-name">Dark Knight</div>
          <div id="enemy-hp-bar">
            <div id="enemy-hp-fill" style="width: 100%"></div>
          </div>
          <div id="enemy-stats">
            <span>⚔️ <span id="enemy-atk">10</span></span>
            <span id="enemy-block">🛡️ 0</span>
          </div>
          <div id="enemy-intent">Intent: Attack 10</div>
        </div>
      </div>

      <div id="combat-middle">
        <div id="turn-indicator">YOUR TURN</div>
        <button id="end-turn-btn" onclick="endTurn()">End Turn</button>
      </div>

      <div id="player-area">
        <div id="player-stats-bar">
          <div id="player-hp-info">
            <span>❤️</span>
            <span id="player-hp-text">100/100</span>
            <div id="player-hp-bar">
              <div id="player-hp-fill" style="width: 100%"></div>
            </div>
          </div>
          <div id="energy-display">
            <span>⚡</span>
            <span id="energy-text">3/3</span>
            <div id="energy-orbs"></div>
          </div>
          <div id="player-block-info">
            <span>🛡️</span>
            <span id="player-block-text">0</span>
          </div>
        </div>
        <div id="hand-container"></div>
      </div>
    </div>
  </div>

  <!-- Draft Screen -->
  <div id="draft-screen" class="screen">
    <div id="draft-container">
      <h2>⚔ Choose a Reward ⚔</h2>
      <p class="draft-desc">Select a card to add to your deck</p>
      <div id="draft-cards"></div>
      <div id="draft-info">Choose wisely, warrior.</div>
    </div>
  </div>

  <!-- Event Screen -->
  <div id="event-screen" class="screen">
    <div id="event-container">
      <h2 id="event-title">Mysterious Shrine</h2>
      <p id="event-desc">You discover an ancient shrine in the depths. A spectral figure offers you a choice.</p>
      <div id="event-choices"></div>
    </div>
  </div>

  <!-- Rest Screen -->
  <div id="rest-screen" class="screen">
    <div id="rest-container">
      <h2>🕯️ Resting Place 🕯️</h2>
      <p>You find a safe haven in the abyss. Rest and recover your strength.</p>
      <button class="btn" onclick="restAndContinue()">Rest (Heal 20 HP)</button>
      <button class="btn small" onclick="restAndContinue()">Continue</button>
    </div>
  </div>

  <!-- Shop Screen -->
  <div id="shop-screen" class="screen">
    <div id="shop-container">
      <h2>🏪 Abyssal Shop</h2>
      <div id="shop-gold">💰 Gold: <span id="shop-gold-value">0</span></div>
      <div id="shop-cards"></div>
      <button class="btn" onclick="leaveShop()">Leave Shop</button>
    </div>
  </div>

  <!-- Game Over Screen -->
  <div id="gameover-screen" class="screen">
    <h1>💀 You Have Fallen 💀</h1>
    <div class="final-stats">
      <p>Floor Reached: <span id="go-floor">1</span></p>
      <p>Enemies Defeated: <span id="go-kills">0</span></p>
      <p>Cards in Deck: <span id="go-deck">0</span></p>
    </div>
    <button class="btn" onclick="startGame()">Try Again</button>
  </div>

  <!-- Victory Screen -->
  <div id="victory-screen" class="screen">
    <h1>👑 Victory! 👑</h1>
    <p style="color: #c9a84c; margin-bottom: 20px;">You have conquered the Abyss!</p>
    <div class="final-stats">
      <p>Floor Reached: <span id="vic-floor">10</span></p>
      <p>Enemies Defeated: <span id="vic-kills">0</span></p>
      <p>Final HP: <span id="vic-hp">0</span></p>
      <p>Cards in Deck: <span id="vic-deck">0</span></p>
    </div>
    <button class="btn" onclick="startGame()">Play Again</button>
  </div>
</div>

<div id="notification"></div>

<script>
// ==================== GAME STATE ====================
const GameState = {
  player: {
    maxHp: 100,
    hp: 100,
    block: 0,
    energy: 3,
    maxEnergy: 3,
    gold: 0,
