// ==================== CARD DATABASE ====================
const CARD_DB = [
  // Attack Cards
  { id: 'strike', name: 'Strike', cost: 1, type: 'attack', icon: '⚔️', desc: 'Deal 8 damage', target: 'enemy', damage: 8, rarity: 'common' },
