  { id: 'ice_lance', name: 'Ice Lance', cost: 2, type: 'attack', icon: '❄️', desc: 'Deal 12 damage. Apply 3 Freeze', target: 'enemy', damage: 12, freeze: 3, rarity: 'uncommon' },
  { id: 'dark_bolt', name: 'Dark Bolt', cost: 2, type: 'attack', icon: '🌑', desc: 'Deal 14 damage. Draw 2 cards', target: 'enemy', damage: 14, draw: 2, rarity: 'uncommon' },

  // Skill Cards
  { id: 'defend', name: 'Defend', cost: 1, type: 'skill', icon: '🛡️', desc: 'Gain 5 Block', target: 'self', block: 5, rarity: 'common' },
  { id: 'wall_of_stone', name: 'Wall of Stone', cost: 2, type: 'skill', icon: '🧱', desc: 'Gain 12 Block', target: 'self', block: 12, rarity: 'common' },
  { id: 'meditate', name: 'Meditate', cost: 0, type: 'skill', icon: '🧘', desc: 'Draw 2 cards. Gain 1 energy', target: 'self', draw: 2, energyGain: 1, rarity: 'uncommon' },
  { id: 'iron_wave', name: 'Iron Wave', cost: 1, type: 'skill', icon: '🌊', desc: 'Gain 4 Block. Draw 1 card', target: 'self', block: 4, draw: 1, rarity: 'common' },
