// ==================== MAP GENERATION ====================
function generateMap() {
  const nodes = [];
  const floors = 10;
  const nodeTypes = ['combat', 'combat', 'combat', 'rest', 'event', 'shop'];

  for (let floor = 0; floor < floors; floor++) {
    const nodesPerFloor = floor === floors - 1 ? 1 : 2 + Math.floor(Math.random() * 2);
    const isBossFloor = floor === floors - 1;

    for (let i = 0; i < nodesPerFloor; i++) {
      let type;
      if (isBossFloor && i === 0) {
        type = 'boss';
      } else {
        type = nodeTypes[Math.floor(Math.random() * nodeTypes.length)];
      }

      nodes.push({
        id: `node_${floor}_${i}`,
        floor: floor + 1,
        index: i,
        type: type,
        x: 10 + (floor * 80),
        y: 100 + (i * 120) + (Math.random() * 40 - 20),
        completed: false,
        locked: floor > 0,
        enemy: null,
        event: null
      });
    }
  }

  // Connect nodes
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    if (node.floor > 1) {
      const prevFloorNodes = nodes.filter(n => n.floor === node.floor - 1);
      if (prevFloorNodes.length > 0) {
        const prevNode = prevFloorNodes[Math.floor(Math.random() * prevFloorNodes.length)];
        node.connections = [prevNode.id];
        prevNode.children = prevNode.children || [];
        prevNode.children.push(node.id);
      }
    }
    if (i < nodes.length - 1 && nodes[i + 1].floor === node.floor) {
      node.children = node.children || [];
      node.children.push(nodes[i + 1].id);
    }
  }

  // Set first node as current
  nodes[0].locked = false;
  nodes[0].completed = false;

  return nodes;
}

function renderMap() {
  const container = document.getElementById('map-container');
  container.innerHTML = '';

  // Draw connections
  GameState.mapNodes.forEach(node => {
    if (node.children) {
      node.children.forEach(childId => {
        const child = GameState.mapNodes.find(n => n.id === childId);
        if (child) {
          const line = document.createElement('div');
          line.className = 'map-connection' + (node.completed ? ' active' : '');
          const dx = child.x - node.x;
          const dy = child.y - node.y;
          const length = Math.sqrt(dx * dx + dy * dy);
          const angle = Math.atan2(dy, dx) * 180 / Math.PI;
          line.style.width = length + 'px';
          line.style.left = (node.x + 30) + 'px';
          line.style.top = (node.y + 30) + 'px';
          line.style.transform = `rotate(${angle}deg)`;
          container.appendChild(line);
        }
      });
    }
  });

  // Draw nodes
  GameState.mapNodes.forEach(node => {
    const el = document.createElement('div');
    el.className = `map-node ${node.type}`;
    if (node.completed) el.classList.add('completed');
    if (node.locked) el.classList.add('locked');
    if (!node.completed && !node.locked) el.classList.add('current');

    const icons = { combat: '⚔️', rest: '🕯️', event: '❓', boss: '👿', shop: '🏪' };
    el.innerHTML = icons[node.type] || '⚔️';
    el.style.left = node.x + 'px';
    el.style.top = node.y + 'px';

    if (!node.completed && !node.locked) {
      el.onclick = () => enterNode(node);
    }

    container.appendChild(el);
  });

  // Update header
  document.getElementById('map-hp').textContent = `${GameState.player.hp}/${GameState.player.maxHp}`;
  document.getElementById('map-hp-bar').style.width = `${(GameState.player.hp / GameState.player.maxHp) * 100}%`;
  document.getElementById('map-floor').textContent = `Floor ${GameState.player.floor}`;
  document.getElementById('map-kills').textContent = GameState.player.kills;
}

function enterNode(node) {
  GameState.currentNode = node;

  switch (node.type) {
    case 'combat':
    case 'boss':
      startCombat(node);
      break;
    case 'rest':
      showRestScreen();
      break;
    case 'event':
      showEvent(node);
      break;
    case 'shop':
      showShop(node);
      break;
  }
}

// ==================== COMBAT SYSTEM ====================
function startCombat(node) {
  const floorMultiplier = 1 + (node.floor - 1) * 0.15;
  let enemyTemplate;

  if (node.type === 'boss') {
    enemyTemplate = ENEMY_DB.find(e => e.id === 'boss_abyss');
  } else {
    const availableEnemies = ENEMY_DB.filter(e => e.id !== 'boss_abyss' && e.id !== 'slime' || node.floor > 3);
    enemyTemplate = availableEnemies[Math.floor(Math.random() * availableEnemies.length)];
  }

  GameState.enemy = {
    ...enemyTemplate,
    hp: Math.floor(enemyTemplate.hp * floorMultiplier),
    maxHp: Math.floor(enemyTemplate.hp * floorMultiplier),
    atk: Math.floor(enemyTemplate.atk * floorMultiplier),
    def: Math.floor(enemyTemplate.def * floorMultiplier),
    block: 0,
    weak: 0,
    burn: 0,
    freeze: 0
  };

  GameState.player.block = 0;
  GameState.player.energy = GameState.player.maxEnergy;
  GameState.player.hand = [];
  GameState.player.discard = [];
  GameState.player.drawPile = shuffle([...GameState.player.deck]);
  GameState.combatActive = true;
  GameState.turn = 1;

  showScreen('combat-screen');
  renderCombat();
  drawHand();
}

function renderCombat() {
  const enemy = GameState.enemy;
  if (!enemy) return;

  document.getElementById('enemy-sprite').textContent = enemy.icon;
  document.getElementById('enemy-name').textContent = enemy.name;
  document.getElementById('enemy-hp-fill').style.width = `${(enemy.hp / enemy.maxHp) * 100}%`;
  document.getElementById('enemy-atk').textContent = enemy.atk;
  document.getElementById('enemy-block').textContent = `🛡️ ${enemy.block}`;

  // Enemy intent
  const intentTypes = ['Attack', 'Defend', 'Buff', 'Weak'];
  const intent = enemy.intent || 'Attack';
  document.getElementById('enemy-intent').textContent = `Intent: ${intent} ${enemy.atk}`;

  // Player stats
  document.getElementById('player-hp-text').textContent = `${GameState.player.hp}/${GameState.player.maxHp}`;
  document.getElementById('player-hp-fill').style.width = `${(GameState.player.hp / GameState.player.maxHp) * 100}%`;
  document.getElementById('player-block-text').textContent = GameState.player.block;
  document.getElementById('energy-text').textContent = `${GameState.player.energy}/${GameState.player.maxEnergy}`;

  // Energy orbs
  const orbsContainer = document.getElementById('energy-orbs');
  orbsContainer.innerHTML = '';
  for (let i = 0; i < GameState.player.maxEnergy; i++) {
    const orb = document.createElement('div');
    orb.className = 'energy-orb' + (i >= GameState.player.energy ? ' used' : '');
    orbsContainer.appendChild(orb);
  }

  // Hand
  renderHand();
}

function renderHand() {
  const container = document.getElementById('hand-container');
  container.innerHTML = '';

  GameState.player.hand.forEach((card, index) => {
    const el = document.createElement('div');
    el.className = 'card';
    if (card.cost <= GameState.player.energy) {
      el.classList.add('playable');
    } else {
      el.classList.add('unplayable');
    }

    el.innerHTML = `
      <div class="card-cost">${card.cost}</div>
      <div class="card-type ${card.type}">${card.type}</div>
      <div class="card-icon">${card.icon}</div>
      <div class="card-name">${card.name}</div>
      <div class="card-desc">${card.desc}</div>
    `;

    if (card.cost <= GameState.player.energy) {
      el.onclick = () => playCard(index);
    }

    container.appendChild(el);
  });
}

function drawHand() {
  const handSize = 5;
  GameState.player.hand = [];

  for (let i = 0; i < handSize; i++) {
    if (GameState.player.drawPile.length === 0) {
      if (GameState.player.discard.length === 0) break;
      GameState.player.drawPile = shuffle([...GameState.player.discard]);
      GameState.player.discard = [];
    }

    if (GameState.player.drawPile.length > 0) {
      GameState.player.hand.push(GameState.player.drawPile.pop());
    }
  }

  renderCombat();
}

function playCard(index) {
  if (!GameState.combatActive) return;

  const card = GameState.player.hand[index];
  if (card.cost > GameState.player.energy) {
    showNotification('Not enough energy!');
    return;
  }

  GameState.player.energy -= card.cost;
  GameState.player.hand.splice(index, 1);
  GameState.player.discard.push(card);

  // Apply card effects
  applyCardEffect(card);

  // Check if enemy is dead
  if (GameState.enemy && GameState.enemy.hp <= 0) {
    enemyDefeated();
    return;
  }

  renderCombat();
}

function applyCardEffect(card) {
  const enemy = GameState.enemy;
  if (!enemy) return;

  let damage = card.damage || 0;

  // Apply weak to player attacks
  if (card.type === 'attack' && GameState.player.weak > 0) {
    damage = Math.floor(damage * 0.5);
    GameState.player.weak--;
  }

  // Apply damage to enemy
  if (damage > 0) {
    const actualDamage = Math.max(1, damage - enemy.def);
    enemy.hp -= actualDamage;
    showDamagePopup(actualDamage, 'enemy-dmg');
    document.getElementById('enemy-sprite').classList.add('enemy-hit');
    setTimeout(() => document.getElementById('enemy-sprite').classList.remove('enemy-hit'), 300);
  }

  // Apply block
  if (card.block) {
    GameState.player.block += card.block;
    showDamagePopup(card.block, 'block');
  }

  // Apply heal
  if (card.heal) {
    GameState.player.hp = Math.min(GameState.player.maxHp, GameState.player.hp + card.heal);
    showDamagePopup(card.heal, 'heal');
  }

  // Apply draw
  if (card.draw) {
    for (let i = 0; i < card.draw; i++) {
      if (GameState.player.drawPile.length === 0) {
        if (GameState.player.discard.length > 0) {
          GameState.player.drawPile = shuffle([...GameState.player.discard]);
          GameState.player.discard = [];
        } else break;
      }
      if (GameState.player.drawPile.length > 0) {
        GameState.player.hand.push(GameState.player.drawPile.pop());
      }
    }
  }

  // Apply energy gain
  if (card.energyGain) {
    GameState.player.energy += card.energyGain;
  }

  // Apply weak to enemy
  if (card.weak) {
    enemy.weak = (enemy.weak || 0) + card.weak;
  }

  // Apply burn
  if (card.burn) {
    enemy.burn = (enemy.burn || 0) + card.burn;
  }

  // Apply freeze
  if (card.freeze) {
    enemy.freeze = (enemy.freeze || 0) + card.freeze;
  }

  // Apply strength
  if (card.strength) {
    GameState.player.strength = (GameState.player.strength || 0) + card.strength;
    GameState.player.strengthTurns = card.strengthTurns;
  }

  // Apply powers
  if (card.power) {
    GameState.player.powers = GameState.player.powers || {};
    GameState.player.powers[card.power] = (GameState.player.powers[card.power] || 0) + 1;
  }

  // Apply curses
  if (card.curse) {
    GameState.player.curses = GameState.player.curses || {};
    GameState.player.curses[card.curse] = (GameState.player.curses[card.curse] || 0) + 1;
  }
}

function endTurn() {
  if (!GameState.combatActive) return;

  // Process enemy turn
  processEnemyTurn();

  // Start new player turn
  GameState.turn++;
  GameState.player.energy = GameState.player.maxEnergy;
  GameState.player.block = 0;

  // Process start-of-turn effects
  processStartOfTurn();

  // Draw new hand
  drawHand();
  renderCombat();
}

function processEnemyTurn() {
  const enemy = GameState.enemy;
  if (!enemy) return;

  // Process burn damage
  if (enemy.burn > 0) {
    const burnDamage = enemy.burn;
    enemy.hp -= burnDamage;
    showDamagePopup(burnDamage, 'enemy-dmg');
    enemy.burn = 0;
  }

  // Process enemy attack
  let enemyAtk = enemy.atk;
  if (enemy.weak > 0) {
    enemyAtk = Math.floor(enemyAtk * 0.5);
    enemy.weak--;
  }

  // Player block
  let damage = Math.max(1, enemyAtk - GameState.player.block);
  GameState.player.block = Math.max(0, GameState.player.block - enemyAtk);
  GameState.player.hp -= damage;

  showDamagePopup(damage, 'player-dmg');
  document.getElementById('player-area').classList.add('player-hit');
  setTimeout(() => document.getElementById('player-area').classList.remove('player-hit'), 300);

  // Process thorns
  if (GameState.player.powers && GameState.player.powers.thorns) {
    const thornsDamage = 3 * GameState.player.powers.thorns;
    enemy.hp -= thornsDamage;
    showDamagePopup(thornsDamage, 'enemy-dmg');
  }

  // Check player death
  if (GameState.player.hp <= 0) {
    GameState.player.hp = 0;
    gameOver();
    return;
  }

  // Check enemy death
  if (enemy.hp <= 0) {
    enemyDefeated();
    return;
  }

  renderCombat();
}

function processStartOfTurn() {
  // Process powers
  if (GameState.player.powers) {
    if (GameState.player.powers.fortify) {
      GameState.player.block += 3 * GameState.player.powers.fortify;
    }
    if (GameState.player.powers.warding) {
      if (GameState.player.drawPile.length === 0) {
        if (GameState.player.discard.length > 0) {
          GameState.player.drawPile = shuffle([...GameState.player.discard]);
          GameState.player.discard = [];
        }
      }
      if (GameState.player.drawPile.length > 0) {
        GameState.player.hand.push(GameState.player.drawPile.pop());
      }
    }
    if (GameState.player.powers.alchemy) {
      GameState.player.energy += GameState.player.powers.alchemy;
    }
  }

  // Process curses
  if (GameState.player.curses) {
    if (GameState.player.curses.blight) {
      GameState.player.hp -= 2 * GameState.player.curses.blight;
      showDamagePopup(2 * GameState.player.curses.blight, 'player-dmg');
    }
    if (GameState.player.curses.pain) {
      GameState.player.weak += 2 * GameState.player.curses.pain;
    }
  }

  // Process strength decay
  if (GameState.player.strengthTurns) {
    GameState.player.strengthTurns--;
    if (GameState.player.strengthTurns <= 0) {
      GameState.player.strength = 0;
    }
  }
}

function enemyDefeated() {
  GameState.combatActive = false;
  GameState.player.kills++;
  GameState.currentNode.completed = true;

  // Gold reward
  const goldReward = 10 + Math.floor(Math.random() * 15);
  GameState.player.gold += goldReward;

  showNotification(`Victory! +${goldReward} gold`);

  // Show draft after a delay
  setTimeout(() => {
    showDraftScreen();
  }, 1000);
}

function showDamagePopup(value, type) {
  const popup = document.createElement('div');
  popup.className = `damage-popup ${type}`;
  popup.textContent = type === 'block' ? `+${value}` : type === 'heal' ? `+${value}` : `-${value}`;

  if (type.includes('enemy')) {
    popup.style.left = '50%';
    popup.style.top = '30%';
  } else {
    popup.style.left = '50%';
    popup.style.top = '70%';
  }

  document.getElementById('combat-area').appendChild(popup);
  setTimeout(() => popup.remove(), 1000);
}

// ==================== DRAFT SYSTEM ====================
function showDraftScreen() {
  // Generate 3 random cards
  GameState.draftCards = [];
  const availableCards = CARD_DB.filter(c => c.rarity !== 'curse');
  const shuffled = shuffle([...availableCards]);

  for (let i = 0; i < 3; i++) {
    GameState.draftCards.push(shuffled[i]);
  }

  renderDraft();
  showScreen('draft-screen');
}

function renderDraft() {
  const container = document.getElementById('draft-cards');
  container.innerHTML = '';

  GameState.draftCards.forEach((card, index) => {
    const el = document.createElement('div');
    el.className = 'card';
    el.innerHTML = `
      <div class="card-cost">${card.cost}</div>
      <div class="card-type ${card.type}">${card.type}</div>
      <div class="card-icon">${card.icon}</div>
      <div class="card-name">${card.name}</div>
      <div class="card-desc">${card.desc}</div>
    `;
    el.onclick = () => selectDraftCard(index);
    container.appendChild(el);
  });
}

function selectDraftCard(index) {
  const card = GameState.draftCards[index];
  GameState.player.deck.push({ ...card });
  showNotification(`Added ${card.name} to deck!`);

  // Move to next node
  advanceMap();
}

