function showShop(node) {
  const shopCards = [];
  const availableCards = CARD_DB.filter(c => c.rarity !== 'curse');
  const shuffled = shuffle([...availableCards]);

  for (let i = 0; i < 4; i++) {
    shopCards.push({ ...shuffled[i], price: 50 + Math.floor(Math.random() * 50) });
  }

  GameState.shopCards = shopCards;
  document.getElementById('shop-gold-value').textContent = GameState.player.gold;

  const container = document.getElementById('shop-cards');
  container.innerHTML = '';

  shopCards.forEach((card, index) => {
    const el = document.createElement('div');
    el.className = 'card';
    el.innerHTML = `
