      <div class="card-type ${card.type}">${card.type}</div>
      <div class="card-icon">${card.icon}</div>
      <div class="card-name">${card.name}</div>
      <div class="card-desc">${card.desc}</div>
      <div class="shop-price">💰 ${card.price}</div>
    `;
    el.onclick = () => buyCard(index);
    container.appendChild(el);
  });

  showScreen('shop-screen');
}

function buyCard(index) {
  const card = GameState.shopCards[index];
  if (GameState.player.gold >= card.price) {
    GameState.player.gold -= card.price;
    GameState.player.deck.push({ ...card });
    document.getElementById('shop-gold-value').textContent = GameState.player.gold;
    showNotification(`Bought ${card.name}!`);

    // Remove from shop
    GameState.shopCards.splice(index, 1);
    showShop(GameState.currentNode);
  } else {
    showNotification('Not enough gold!');
  }
}

function leaveShop() {
  GameState.currentNode.completed = true;
  advanceMap();
}

// ==================== MAP ADVANCEMENT ====================
function advanceMap() {
  // Find next available node
  const currentFloor = GameState.currentNode.floor;
  const nextNodes = GameState.mapNodes.filter(n =>
    n.floor === currentFloor + 1 && !n.completed && !n.locked
  );

  if (nextNodes.length > 0) {
    // Unlock next floor nodes
    GameState.mapNodes.forEach(n => {
      if (n.floor === currentFloor + 1) {
        n.locked = false;
      }
    });
  }

  // Check if all nodes on current floor are completed
  const currentFloorNodes = GameState.mapNodes.filter(n => n.floor === currentFloor);
  const allCompleted = currentFloorNodes.every(n => n.completed);

  if (allCompleted || currentFloor >= 10) {
    // Check victory
    if (currentFloor >= 10) {
      victory();
      return;
    }
  }

  renderMap();
  showScreen('map-screen');
}

