                player.onGround = false;
                player.doubleJump = false;
                addParticles(player.x + player.width / 2, player.y + player.height, '#fff', 5, 3);
            } else if ((keys['Space'] || keys['ArrowUp'] || keys['KeyW']) && !player.doubleJump && player.hasDoubleJump && !player.onGround) {
                player.vy = player.jumpForce * 0.8;
                player.doubleJump = true;
                addParticles(player.x + player.width / 2, player.y + player.height, '#4ecca3', 8, 4);
            }

            // Gravity
            player.vy += 0.6;
            if (player.vy > 15) player.vy = 15;

            // Move player
            player.x += player.vx;
            player.y += player.vy;

            // Animation
            player.animTimer++;
            if (Math.abs(player.vx) > 0.5) {
                if (player.animTimer % 8 === 0) {
                    player.animFrame = (player.animFrame + 1) % 4;
                }
            } else {
                player.animFrame = 0;
            }

            // Invincibility timer
            if (player.invincible > 0) player.invincible--;

            // Platform collision
            player.onGround = false;
            if (currentLevelData) {
                for (let platform of currentLevelData.platforms) {
                    if (player.x + player.width > platform.x &&
                        player.x < platform.x + platform.w &&
                        player.y + player.height > platform.y &&
                        player.y + player.height < platform.y + platform.h + 10 &&
                        player.vy >= 0) {
                        player.y = platform.y - player.height;
                        player.vy = 0;
                        player.onGround = true;
                        player.doubleJump = false;
                    }
                }

                // Coin collection
                for (let coin of currentLevelData.coins) {
                    if (!coin.collected) {
                        const dx = (player.x + player.width / 2) - coin.x;
                        const dy = (player.y + player.height / 2) - coin.y;
                        const dist = Math.sqrt(dx * dx + dy * dy);
                        if (dist < 25) {
                            coin.collected = true;
                            score += 10;
                            addParticles(coin.x, coin.y, '#ffd700', 10, 5);
                            updateUI();
                        }
                    }
                }

                // Enemy collision
                for (let enemy of currentLevelData.enemies) {
                    enemy.x += enemy.vx;
                    if (enemy.x <= enemy.patrolStart || enemy.x + enemy.w >= enemy.patrolEnd) {
                        enemy.vx *= -1;
                    }

                    if (player.invincible <= 0 &&
                        player.x + player.width > enemy.x &&
                        player.x < enemy.x + enemy.w &&
                        player.y + player.height > enemy.y &&
                        player.y < enemy.y + enemy.h) {

                        // Check if stomping
                        if (player.vy > 0 && player.y + player.height < enemy.y + enemy.h / 2 + 10) {
                            // Stomp enemy
                            player.vy = -8;
                            score += 25;
                            addParticles(enemy.x + enemy.w / 2, enemy.y + enemy.h / 2, '#e94560', 15, 6);
                            enemy.x = -1000; // Remove enemy
                            updateUI();
                        } else {
                            // Hit by enemy
                            lives--;
                            player.invincible = 60;
                            screenShake = 10;
                            addParticles(player.x + player.width / 2, player.y + player.height / 2, '#e94560', 20, 8);
                            updateUI();

                            if (lives <= 0) {
                                gameOver();
                                return;
                            }
                        }
                    }
                }

                // Flag collision (level complete)
                const flag = currentLevelData.flag;
                if (player.x + player.width > flag.x && player.x < flag.x + 30 &&
                    player.y + player.height > flag.y && player.y < flag.y + 60) {
                    score += 100;
                    updateUI();
                    addParticles(flag.x + 15, flag.y + 30, '#4ecca3', 30, 8);
                    loadLevel(currentLevel);
                    return;
                }

                // Fall death
                if (player.y > 600) {
                    lives--;
                    updateUI();
                    if (lives <= 0) {
                        gameOver();
                        return;
                    }
                    player.x = currentLevelData.spawn.x;
                    player.y = currentLevelData.spawn.y;
                    player.vx = 0;
                    player.vy = 0;
                    screenShake = 10;
                }
            }

            // Camera
            const targetCameraX = player.x - 300;
            cameraX += (targetCameraX - cameraX) * 0.1;
            if (cameraX < 0) cameraX = 0;

            // Particles
            for (let i = particles.length - 1; i >= 0; i--) {
                let p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.vy += 0.1;
                p.life -= p.decay;
                if (p.life <= 0) {
                    particles.splice(i, 1);
                }
            }

            // Screen shake
            if (screenShake > 0) screenShake--;
        }

        function drawPlayer() {
            const x = player.x - cameraX;
            const y = player.y;

            // Invincibility flash
            if (player.invincible > 0 && Math.floor(player.invincible / 4) % 2 === 0) return;

            ctx.save();
            ctx.translate(x + player.width / 2, y + player.height / 2);
            ctx.scale(player.facing, 1);

            // Body
            ctx.fillStyle = '#2196F3';
            ctx.fillRect(-12, -8, 24, 20);

            // Head
            ctx.fillStyle = '#FFCC80';
            ctx.fillRect(-8, -20, 16, 14);

            // Hair
            ctx.fillStyle = '#4E342E';
            ctx.fillRect(-9, -22, 18, 6);
            ctx.fillRect(-9, -22, 4, 10);

            // Eyes
            ctx.fillStyle = '#000';
            ctx.fillRect(2, -16, 3, 3);

            // Mouth
            ctx.fillStyle = '#000';
            ctx.fillRect(2, -10, 4, 2);

            // Legs
            ctx.fillStyle = '#1565C0';
            if (player.onGround && Math.abs(player.vx) > 0.5) {
                const legOffset = Math.sin(player.animFrame * Math.PI / 2) * 4;
                ctx.fillRect(-8, 12, 6, 8 + legOffset);
                ctx.fillRect(2, 12, 6, 8 - legOffset);
            } else {
                ctx.fillRect(-8, 12, 6, 8);
                ctx.fillRect(2, 12, 6, 8);
            }

            // Shoes
            ctx.fillStyle = '#333';
            ctx.fillRect(-9, 18 + (player.onGround && Math.abs(player.vx) > 0.5 ? Math.sin(player.animFrame * Math.PI / 2) * 4 : 0), 8, 4);
            ctx.fillRect(1, 18 + (player.onGround && Math.abs(player.vx) > 0.5 ? -Math.sin(player.animFrame * Math.PI / 2) * 4 : 0), 8, 4);

            // Arms
            ctx.fillStyle = '#FFCC80';
            const armSwing = Math.sin(player.animFrame * Math.PI / 2) * 5;
            ctx.fillRect(-16, -4 + armSwing, 4, 12);
            ctx.fillRect(12, -4 - armSwing, 4, 12);

            ctx.restore();
        }

        function draw() {
            // Clear
            ctx.fillStyle = '#16213e';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Background stars
            ctx.fillStyle = '#fff';
            for (let i = 0; i < 50; i++) {
                const sx = ((i * 137 + 50) % 900) - (cameraX * 0.1 % 900);
                const sy = (i * 97 + 30) % 400;
                const size = (i % 3) + 1;
                ctx.globalAlpha = 0.3 + (Math.sin(Date.now() / 1000 + i) * 0.3);
                ctx.fillRect(sx < 0 ? sx + 900 : sx, sy, size, size);
            }
            ctx.globalAlpha = 1;

            // Background mountains
            ctx.fillStyle = '#0f3460';
            for (let i = 0; i < 8; i++) {
                const mx = i * 200 - (cameraX * 0.2 % 200);
                ctx.beginPath();
                ctx.moveTo(mx, 500);
                ctx.lineTo(mx + 100, 250 + Math.sin(i) * 50);
                ctx.lineTo(mx + 200, 500);
                ctx.fill();
            }

            ctx.save();

            // Screen shake
            if (screenShake > 0) {
                ctx.translate(
                    (Math.random() - 0.5) * screenShake,
                    (Math.random() - 0.5) * screenShake
                );
            }

            if (currentLevelData) {
                // Draw platforms
                for (let platform of currentLevelData.platforms) {
                    const px = platform.x - cameraX;
                    if (px + platform.w < -50 || px > canvas.width + 50) continue;

                    if (platform.type === 'ground') {
                        // Ground platform
                        ctx.fillStyle = '#4ecca3';
                        ctx.fillRect(px, platform.y, platform.w, platform.h);
                        ctx.fillStyle = '#3ba887';
                        ctx.fillRect(px, platform.y, platform.w, 5);
                        // Grass detail
                        ctx.fillStyle = '#2d8f6e';
                        for (let g = 0; g < platform.w; g += 10) {
                            ctx.fillRect(px + g, platform.y - 3, 3, 6);
                        }
                    } else {
                        // Floating platform
                        ctx.fillStyle = '#e94560';
                        ctx.fillRect(px, platform.y, platform.w, platform.h);
                        ctx.fillStyle = '#ff6b81';
                        ctx.fillRect(px, platform.y, platform.w, 4);
                        ctx.fillStyle = '#c73650';
                        ctx.fillRect(px, platform.y + platform.h - 3, platform.w, 3);
                    }
                }

                // Draw coins
                for (let coin of currentLevelData.coins) {
                    if (coin.collected) continue;
                    const cx = coin.x - cameraX;
                    if (cx < -50 || cx > canvas.width + 50) continue;

                    const bob = Math.sin(Date.now() / 300 + coin.x) * 3;
                    const cy = coin.y + bob;

                    // Coin glow
                    ctx.fillStyle = 'rgba(255, 215, 0, 0.3)';
                    ctx.beginPath();
                    ctx.arc(cx, cy, 15, 0, Math.PI * 2);
                    ctx.fill();

                    // Coin
                    ctx.fillStyle = '#ffd700';
                    ctx.beginPath();
                    ctx.arc(cx, cy, 8, 0, Math.PI * 2);
                    ctx.fill();

                    ctx.fillStyle = '#ffed4a';
                    ctx.beginPath();
                    ctx.arc(cx - 2, cy - 2, 4, 0, Math.PI * 2);
                    ctx.fill();

                    // Star on coin
                    ctx.fillStyle = '#fff';
                    ctx.font = '10px Arial';
                    ctx.textAlign = 'center';
                    ctx.fillText('★', cx, cy + 3);
                }

                // Draw enemies
                for (let enemy of currentLevelData.enemies) {
                    if (enemy.x < -500) continue;
                    const ex = enemy.x - cameraX;
                    if (ex < -50 || ex > canvas.width + 50) continue;

                    // Enemy body
                    ctx.fillStyle = '#e94560';
                    ctx.fillRect(ex, enemy.y, enemy.w, enemy.h);

                    // Enemy eyes
                    ctx.fillStyle = '#fff';
                    ctx.fillRect(ex + 5, enemy.y + 5, 6, 6);
                    ctx.fillRect(ex + 18, enemy.y + 5, 6, 6);
                    ctx.fillStyle = '#000';
                    const eyeDir = enemy.vx > 0 ? 2 : 0;
                    ctx.fillRect(ex + 6 + eyeDir, enemy.y + 7, 3, 3);
                    ctx.fillRect(ex + 19 + eyeDir, enemy.y + 7, 3, 3);

                    // Enemy mouth
                    ctx.fillStyle = '#000';
                    ctx.fillRect(ex + 8, enemy.y + 18, 14, 3);

                    // Enemy spikes
                    ctx.fillStyle = '#c73650';
                    for (let s = 0; s < 3; s++) {
                        ctx.beginPath();
                        ctx.moveTo(ex + s * 10, enemy.y);
                        ctx.lineTo(ex + s * 10 + 5, enemy.y - 6);
                        ctx.lineTo(ex + s * 10 + 10, enemy.y);
                        ctx.fill();
                    }
                }

                // Draw flag
                const flag = currentLevelData.flag;
                const fx = flag.x - cameraX;

                // Flag pole
                ctx.fillStyle = '#aaa';
                ctx.fillRect(fx + 10, flag.y - 40, 4, 100);

                // Flag
                const flagWave = Math.sin(Date.now() / 200) * 3;
                ctx.fillStyle = '#4ecca3';
                ctx.beginPath();
                ctx.moveTo(fx + 14, flag.y - 40);
                ctx.lineTo(fx + 50 + flagWave, flag.y - 30);
                ctx.lineTo(fx + 14, flag.y - 15);
                ctx.fill();

                // Flag star
                ctx.fillStyle = '#fff';
                ctx.font = '12px Arial';
                ctx.textAlign = 'center';
                ctx.fillText('★', fx + 30 + flagWave / 2, flag.y - 25);

                // Draw player
                drawPlayer();

                // Draw particles
                for (let p of particles) {
                    ctx.globalAlpha = p.life;
                    ctx.fillStyle = p.color;
                    ctx.fillRect(p.x - cameraX - p.size / 2, p.y - p.size / 2, p.size, p.size);
                }
                ctx.globalAlpha = 1;
            }

            ctx.restore();
        }

        function gameLoop() {
            update();
            draw();
            if (gameRunning) {
                requestAnimationFrame(gameLoop);
            }
        }

        // Initial draw
        draw();
    </script>
</body>
