// Input
const keys = {};
let mouse = { x: 0, y: 0, down: false };

document.addEventListener('keydown', (e) => {
keys[e.key.toLowerCase()] = true;
if (e.key === 'e' || e.key === 'E') interact();
if (e.key === 'i' || e.key === 'I') toggleInventory();
if (e.key === 'm' || e.key === 'M') toggleMap();
if (e.key === 'Enter' && GAME.currentDialogue) advanceDialogue();
if (e.key === 'Escape') {
if (GAME.state === 'playing') {
GAME.state = 'menu';
document.getElementById('menu').style.display = 'flex';
}
}
});

document.addEventListener('keyup', (e) => {
keys[e.key.toLowerCase()] = false;
});

canvas.addEventListener('mousemove', (e) => {
mouse.x = e.clientX;
mouse.y = e.clientY;
});

canvas.addEventListener('mousedown', (e) => {
mouse.down = true;
shoot();
});

canvas.addEventListener('mouseup', () => {
mouse.down = false;
});

canvas.addEventListener('contextmenu', (e) => e.preventDefault());

// Shooting
function shoot() {
if (!GAME.player || GAME.player.ammo <= 0) return;

const player = GAME.player;
const worldMouseX = mouse.x + GAME.camera.x;
const worldMouseY = mouse.y + GAME.camera.y;
const angle = Math.atan2(worldMouseY - player.y, worldMouseX - player.x);

GAME.bullets.push({
x: player.x + Math.cos(angle) * 20,
y: player.y + Math.sin(angle) * 20,
vx: Math.cos(angle) * 12,
vy: Math.sin(angle) * 12,
damage: player.damage,
owner: 'player',
life: 60,
color: '#ffff00'
});

player.ammo--;
GAME.shakes.push({ x: 0, y: 0, intensity: 3, life: 5 });

// Muzzle flash particles
for (let i = 0; i < 5; i++) {
GAME.particles.push({
x: player.x + Math.cos(angle) * 20,
y: player.y + Math.sin(angle) * 20,
vx: Math.cos(angle + (Math.random() - 0.5) * 0.5) * (3 + Math.random() * 3),
vy: Math.sin(angle + (Math.random() - 0.5) * 0.5) * (3 + Math.random() * 3),
life: 10 + Math.random() * 10,
maxLife: 20,
color: '#ffff00',
size: 2 + Math.random() * 3
});
}

updateHUD();
}

// Auto-fire when holding mouse
setInterval(() => {
if (mouse.down && GAME.state === 'playing' && GAME.player) {
shoot();
}
}, 200);

// Interaction
function interact() {
if (!GAME.player) return;

const player = GAME.player;

// Check interactables
for (let inter of GAME.interactables) {
const dist = Math.hypot(player.x - inter.x, player.y - inter.y);
if (dist < inter.distance) {
if (inter.type === 'npc') {
const npc = GAME.npcs.find(n => n.x === inter.x && n.y === inter.y);
if (npc) {
startDialogue(npc.name, npc.dialogue[Math.floor(Math.random() * npc.dialogue.length)]);
}
} else if (inter.type === 'hotel') {
player.health = Math.min(player.health + 50, player.maxHealth);
showNotification('Healed at Hotel! +50 HP');
updateHUD();
} else if (inter.type === 'shop') {
if (GAME.money >= 100) {
GAME.money -= 100;
GAME.player.ammo = Math.min(GAME.player.ammo + 30, GAME.player.maxAmmo);
showNotification('Bought Ammo! - $100');
updateHUD();
} else {
showNotification('Not enough money!');
}
} else if (inter.type === 'mission_board') {
acceptNextMission();
}
}
}

// Check NPCs
for (let npc of GAME.npcs) {
const dist = Math.hypot(player.x - npc.x, player.y - npc.y);
if (dist < 50 && npc.type === 'enemy') {
// Attack NPC
npc.health -= player.damage;
GAME.shakes.push({ x: 0, y: 0, intensity: 5, life: 8 });
if (npc.health <= 0) {
GAME.kills++;
GAME.money += 50;
showNotification('Enemy defeated! +$50');
updateMissionProgress('kill');
// Respawn
setTimeout(() => {
npc.x = Math.random() * GAME.worldWidth;
npc.y = Math.random() * GAME.worldHeight;
npc.health = npc.maxHealth;
}, 5000);
}
updateHUD();
}
}
}

function acceptNextMission() {
const available = GAME.missions.find(m => !m.active && !m.completed);
if (available) {
available.active = true;
GAME.activeMission = available;
document.getElementById('mission-panel').style.display = 'block';
document.getElementById('missionTitle').textContent = available.title;
document.getElementById('missionDesc').textContent = available.description + ' (Reward: $' + available.reward + ')';
showNotification('Mission Accepted: ' + available.title);
} else {
showNotification('No available missions!');
}
}

function updateMissionProgress(type) {
if (!GAME.activeMission) return;
if (type === 'kill') {
GAME.activeMission.current++;
if (GAME.activeMission.current >= GAME.activeMission.target) {
GAME.activeMission.completed = true;
GAME.money += GAME.activeMission.reward;
showNotification('Mission Complete! +$' + GAME.activeMission.reward);
GAME.activeMission = null;
document.getElementById('mission-panel').style.display = 'none';
updateHUD();
}
}
}

