function useItem(index) {
const item = GAME.inventory[index];
if (!item) return;
if (item.type === 'health') {
GAME.player.health = Math.min(GAME.player.health + 30, GAME.player.maxHealth);
showNotification('Used Medkit! +30 HP');
} else if (item.type === 'ammo') {
GAME.player.ammo = Math.min(GAME.player.ammo + 20, GAME.player.maxAmmo);
showNotification('Used Ammo Pack! +20 Ammo');
} else if (item.type === 'money') {
GAME.money += item.amount;
showNotification('Used Money Bag! +$' + item.amount);
}
GAME.inventory.splice(index, 1);
updateHUD();
updateInventoryDisplay();
}

// HUD
function updateHUD() {
if (!GAME.player) return;
const healthPercent = (GAME.player.health / GAME.player.maxHealth) * 100;
