document.getElementById('ammoBar').style.width = ammoPercent + '%';
document.getElementById('moneyDisplay').textContent = GAME.money;
document.getElementById('killCount').textContent = GAME.kills;
document.getElementById('dayDisplay').textContent = GAME.dayNumber;

// Location
