for (let [key, district] of Object.entries(DISTRICTS)) {
if (GAME.player.x > district.x && GAME.player.x < district.x + district.w &&
GAME.player.y > district.y && GAME.player.y < district.y + district.h) {
currentDistrict = district.name;
break;
}
}
document.getElementById('locationDisplay').textContent = currentDistrict;
}

