// Update
function update() {
if (GAME.state !== 'playing' || !GAME.player) return;

const player = GAME.player;

// Movement
let dx = 0, dy = 0;
if (keys['w'] || keys['arrowup']) dy = -1;
if (keys['s'] || keys['arrowdown']) dy = 1;
if (keys['a'] || keys['arrowleft']) dx = -1;
if (keys['d'] || keys['arrowright']) dx = 1;

if (dx !== 0 || dy !== 0) {
const len = Math.hypot(dx, dy);
dx /= len;
dy /= len;
const newX = player.x + dx * player.speed;
const newY = player.y + dy * player.speed;

// Collision with buildings
let collides = false;
for (let building of GAME.buildings) {
if (newX > building.x - player.size && newX < building.x + building.w + player.size &&
newY > building.y - player.size && newY < building.y + building.h + player.size) {
collides = true;
break;
}
}

if (!collides) {
player.x = Math.max(player.size, Math.min(GAME.worldWidth - player.size, newX));
player.y = Math.max(player.size, Math.min(GAME.worldHeight - player.size, newY));
}
}

// Aim angle
const worldMouseX = mouse.x + GAME.camera.x;
const worldMouseY = mouse.y + GAME.camera.y;
player.angle = Math.atan2(worldMouseY - player.y, worldMouseX - player.x);

// Camera
GAME.camera.x = player.x - canvas.width / 2;
GAME.camera.y = player.y - canvas.height / 2;

// Day/night cycle
GAME.dayTime += 0.5;
if (GAME.dayTime >= GAME.dayLength) {
GAME.dayTime = 0;
GAME.dayNumber++;
showNotification('Day ' + GAME.dayNumber + ' begins...');
}

const dayProgress = GAME.dayTime / GAME.dayLength;
if (dayProgress < 0.25) GAME.timeOfDay = 'morning';
else if (dayProgress < 0.5) GAME.timeOfDay = 'afternoon';
else if (dayProgress < 0.75) GAME.timeOfDay = 'evening';
else GAME.timeOfDay = 'night';

// Update bullets
for (let i = GAME.bullets.length - 1; i >= 0; i--) {
const bullet = GAME.bullets[i];
bullet.x += bullet.vx;
bullet.y += bullet.vy;
bullet.life--;

if (bullet.life <= 0 || bullet.x < 0 || bullet.x > GAME.worldWidth ||
bullet.y < 0 || bullet.y > GAME.worldHeight) {
GAME.bullets.splice(i, 1);
continue;
}

// Hit buildings
let hitBuilding = false;
for (let building of GAME.buildings) {
if (bullet.x > building.x && bullet.x < building.x + building.w &&
bullet.y > building.y && bullet.y < building.y + building.h) {
hitBuilding = true;
// Spawn impact particles
for (let j = 0; j < 3; j++) {
GAME.particles.push({
x: bullet.x, y: bullet.y,
vx: (Math.random() - 0.5) * 4,
vy: (Math.random() - 0.5) * 4,
life: 10, maxLife: 10,
color: '#ffaa00', size: 2
});
}
break;
}
}
if (hitBuilding) {
GAME.bullets.splice(i, 1);
continue;
}

// Hit enemies
if (bullet.owner === 'player') {
for (let enemy of GAME.enemies) {
const dist = Math.hypot(bullet.x - enemy.x, bullet.y - enemy.y);
if (dist < enemy.size) {
enemy.health -= bullet.damage;
GAME.shakes.push({ x: 0, y: 0, intensity: 2, life: 3 });
GAME.bullets.splice(i, 1);

// Blood particles
for (let j = 0; j < 5; j++) {
GAME.particles.push({
x: enemy.x, y: enemy.y,
vx: (Math.random() - 0.5) * 6,
vy: (Math.random() - 0.5) * 6,
life: 20, maxLife: 20,
color: '#ff0000', size: 3
});
}

if (enemy.health <= 0) {
GAME.kills++;
GAME.money += 30;
showNotification('Enemy eliminated! +$30');
updateMissionProgress('kill');
// Respawn
setTimeout(() => {
enemy.x = Math.random() * GAME.worldWidth;
enemy.y = Math.random() * GAME.worldHeight;
enemy.health = enemy.maxHealth;
}, 8000);
}
updateHUD();
break;
}
}

// Hit NPC enemies
for (let npc of GAME.npcs) {
if (npc.type === 'enemy') {
const dist = Math.hypot(bullet.x - npc.x, bullet.y - npc.y);
if (dist < npc.size) {
npc.health -= bullet.damage;
GAME.bullets.splice(i, 1);
if (npc.health <= 0) {
GAME.kills++;
GAME.money += 50;
updateMissionProgress('kill');
}
break;
}
}
}
}

// Enemy bullets hitting player
if (bullet.owner === 'enemy') {
const dist = Math.hypot(bullet.x - player.x, bullet.y - player.y);
if (dist < player.size && player.invincible <= 0) {
player.health -= bullet.damage;
player.invincible = 30;
GAME.shakes.push({ x: 0, y: 0, intensity: 5, life: 10 });
GAME.bullets.splice(i, 1);
updateHUD();
if (player.health <= 0) {
showNotification('You died! Resawning...');
player.health = player.maxHealth;
player.x = 2000;
player.y = 2000;
player.ammo = player.maxAmmo;
GAME.money = Math.max(0, GAME.money - 100);
updateHUD();
}
}
}
}

// Update enemies
for (let enemy of GAME.enemies) {
const distToPlayer = Math.hypot(enemy.x - player.x, enemy.y - player.y);

if (enemy.aggressive && distToPlayer < 300) {
enemy.state = 'chase';
}

if (enemy.state === 'chase') {
const angle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
enemy.x += Math.cos(angle) * enemy.speed;
enemy.y += Math.sin(angle) * enemy.speed;

// Shoot at player
enemy.shootTimer--;
if (enemy.shootTimer <= 0 && distToPlayer < 200) {
GAME.bullets.push({
x: enemy.x + Math.cos(angle) * 15,
y: enemy.y + Math.sin(angle) * 15,
vx: Math.cos(angle) * 8,
vy: Math.sin(angle) * 8,
damage: enemy.damage,
owner: 'enemy',
life: 40,
color: '#ff4444'
});
enemy.shootTimer = 60 + Math.random() * 60;
}
} else {
// Patrol
const distToPatrol = Math.hypot(enemy.x - enemy.patrolX, enemy.y - enemy.patrolY);
if (distToPatrol < 10) {
enemy.patrolX = Math.random() * GAME.worldWidth;
enemy.patrolY = Math.random() * GAME.worldHeight;
}
const angle = Math.atan2(enemy.patrolY - enemy.y, enemy.patrolX - enemy.x);
enemy.x += Math.cos(angle) * enemy.speed * 0.5;
enemy.y += Math.sin(angle) * enemy.speed * 0.5;
}

// Keep in bounds
enemy.x = Math.max(0, Math.min(GAME.worldWidth, enemy.x));
enemy.y = Math.max(0, Math.min(GAME.worldHeight, enemy.y));
}

// Update NPCs
for (let npc of GAME.npcs) {
if (npc.type === 'enemy') {
const distToPlayer = Math.hypot(npc.x - player.x, npc.y - player.y);
if (distToPlayer < 200) {
const angle = Math.atan2(player.y - npc.y, player.x - npc.x);
npc.x += Math.cos(angle) * npc.speed * 0.5;
npc.y += Math.sin(angle) * npc.speed * 0.5;

// Shoot
if (Math.random() < 0.02) {
GAME.bullets.push({
x: npc.x + Math.cos(angle) * 15,
y: npc.y + Math.sin(angle) * 15,
vx: Math.cos(angle) * 7,
vy: Math.sin(angle) * 7,
damage: 10,
owner: 'enemy',
life: 30,
color: '#ff4444'
});
}
}
}
}

// Update particles
for (let i = GAME.particles.length - 1; i >= 0; i--) {
const p = GAME.particles[i];
p.x += p.vx;
p.y += p.vy;
p.life--;
p.vx *= 0.95;
p.vy *= 0.95;
if (p.life <= 0) {
GAME.particles.splice(i, 1);
}
}

// Update screen shakes
for (let i = GAME.shakes.length - 1; i >= 0; i--) {
const s = GAME.shakes[i];
s.life--;
s.intensity *= 0.9;
if (s.life <= 0) {
GAME.shakes.splice(i, 1);
}
}

// Player invincibility
if (player.invincible > 0) player.invincible--;

// Combo timer
if (player.comboTimer > 0) {
player.comboTimer--;
if (player.comboTimer <= 0) player.combo = 0;
}

updateHUD();
}

// Render
function render() {
ctx.clearRect(0, 0, canvas.width, canvas.height);

if (GAME.state !== 'playing' || !GAME.player) return;

const player = GAME.player;

// Screen shake
let shakeX = 0, shakeY = 0;
for (let s of GAME.shakes) {
shakeX += (Math.random() - 0.5) * s.intensity;
shakeY += (Math.random() - 0.5) * s.intensity;
}

ctx.save();
ctx.translate(-GAME.camera.x + shakeX, -GAME.camera.y + shakeY);

// Draw ground
drawGround();

// Draw districts
drawDistricts();

// Draw buildings
drawBuildings();

// Draw vehicles
drawVehicles();

// Draw interactables
drawInteractables();

// Draw NPCs
drawNPCs();

// Draw enemies
drawEnemies();

// Draw player
drawPlayer();

// Draw bullets
drawBullets();

// Draw particles
drawParticles();

ctx.restore();

// Draw minimap
drawMinimap();

// Draw day/night overlay
drawDayNightOverlay();
}

function drawGround() {
// Base ground
ctx.fillStyle = '#2a2a2a';
ctx.fillRect(0, 0, GAME.worldWidth, GAME.worldHeight);

// Grid pattern
ctx.strokeStyle = '#333333';
ctx.lineWidth = 1;
for (let x = 0; x < GAME.worldWidth; x += 100) {
ctx.beginPath();
ctx.moveTo(x, 0);
ctx.lineTo(x, GAME.worldHeight);
ctx.stroke();
}
for (let y = 0; y < GAME.worldHeight; y += 100) {
ctx.beginPath();
ctx.moveTo(0, y);
ctx.lineTo(GAME.worldWidth, y);
ctx.stroke();
}

// Roads
ctx.fillStyle = '#444444';
// Main horizontal road
ctx.fillRect(0, 1500, GAME.worldWidth, 200);
// Main vertical road
ctx.fillRect(1500, 0, 200, GAME.worldHeight);
// Other roads
ctx.fillRect(0, 1000, GAME.worldWidth, 100);
ctx.fillRect(0, 2000, GAME.worldWidth, 100);
ctx.fillRect(1000, 0, 100, GAME.worldHeight);
ctx.fillRect(2000, 0, 100, GAME.worldHeight);
ctx.fillRect(3000, 0, 100, GAME.worldHeight);

// Road markings
ctx.strokeStyle = '#666666';
ctx.lineWidth = 2;
ctx.setLineDash([20, 20]);
ctx.beginPath();
ctx.moveTo(0, 1600);
ctx.lineTo(GAME.worldWidth, 1600);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(1600, 0);
ctx.lineTo(1600, GAME.worldHeight);
ctx.stroke();
ctx.setLineDash([]);

// Beach area
ctx.fillStyle = '#c2a645';
ctx.fillRect(2800, 2800, 1200, 600);

// Water
ctx.fillStyle = '#1a3a5c';
ctx.fillRect(0, 3400, GAME.worldWidth, 600);
ctx.fillRect(3600, 0, 400, GAME.worldHeight);
}

function drawDistricts() {
for (let [key, district] of Object.entries(DISTRICTS)) {
ctx.fillStyle = district.color + '22';
ctx.fillRect(district.x, district.y, district.w, district.h);

// District label
ctx.fillStyle = district.color + '88';
ctx.font = '12px Courier New';
ctx.textAlign = 'center';
ctx.fillText(district.name, district.x + district.w / 2, district.y + district.h / 2);
}
}

function drawBuildings() {
for (let building of GAME.buildings) {
// Building shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.fillRect(building.x + 5, building.y + 5, building.w, building.h);

// Building body
ctx.fillStyle = building.color;
ctx.fillRect(building.x, building.y, building.w, building.h);

// Building border
ctx.strokeStyle = '#000';
ctx.lineWidth = 2;
ctx.strokeRect(building.x, building.y, building.w, building.h);

// Building details
if (building.type === 'hotel') {
ctx.fillStyle = '#ffaa00';
ctx.font = '10px Courier New';
ctx.textAlign = 'center';
ctx.fillText('HOTEL', building.x + building.w / 2, building.y + building.h / 2);
} else if (building.type === 'warehouse') {
ctx.fillStyle = '#888';
ctx.font = '10px Courier New';
ctx.textAlign = 'center';
ctx.fillText('WAREHOUSE', building.x + building.w / 2, building.y + building.h / 2);
} else if (building.type === 'stall') {
ctx.fillStyle = '#ff6600';
ctx.font = '8px Courier New';
ctx.textAlign = 'center';
ctx.fillText('STALL', building.x + building.w / 2, building.y + building.h / 2);
} else if (building.type === 'beach_shack') {
ctx.fillStyle = '#ffcc00';
ctx.font = '8px Courier New';
ctx.textAlign = 'center';
ctx.fillText('SHACK', building.x + building.w / 2, building.y + building.h / 2);
}

// Windows
ctx.fillStyle = '#ffff88';
for (let wx = building.x + 10; wx < building.x + building.w - 10; wx += 20) {
for (let wy = building.y + 10; wy < building.y + building.h - 10; wy += 20) {
if (Math.random() > 0.3) {
ctx.fillRect(wx, wy, 8, 8);
}
}
}
}
}

function drawVehicles() {
for (let vehicle of GAME.vehicles) {
ctx.fillStyle = vehicle.color;
ctx.fillRect(vehicle.x - 20, vehicle.y - 10, 40, 20);
ctx.strokeStyle = '#000';
ctx.lineWidth = 2;
ctx.strokeRect(vehicle.x - 20, vehicle.y - 10, 40, 20);

// Wheels
ctx.fillStyle = '#222';
ctx.fillRect(vehicle.x - 18, vehicle.y - 12, 8, 4);
ctx.fillRect(vehicle.x + 10, vehicle.y - 12, 8, 4);
ctx.fillRect(vehicle.x - 18, vehicle.y + 8, 8, 4);
ctx.fillRect(vehicle.x + 10, vehicle.y + 8, 8, 4);

// Vehicle type label
ctx.fillStyle = '#fff';
ctx.font = '8px Courier New';
ctx.textAlign = 'center';
ctx.fillText(vehicle.type.toUpperCase(), vehicle.x, vehicle.y + 3);
}
}

function drawInteractables() {
for (let inter of GAME.interactables) {
const dist = Math.hypot(GAME.player.x - inter.x, GAME.player.y - inter.y);
const highlight = dist < inter.distance;

ctx.fillStyle = highlight ? '#ffaa00' : '#666666';
ctx.beginPath();
ctx.arc(inter.x, inter.y, 10, 0, Math.PI * 2);
ctx.fill();

ctx.strokeStyle = highlight ? '#ffaa00' : '#888';
ctx.lineWidth = 2;
ctx.stroke();

ctx.fillStyle = '#fff';
ctx.font = '10px Courier New';
ctx.textAlign = 'center';
ctx.fillText(inter.name, inter.x, inter.y - 15);

if (highlight) {
ctx.fillStyle = '#ffaa00';
ctx.font = '12px Courier New';
ctx.fillText('[E] Interact', inter.x, inter.y + 25);
}
}
}

function drawNPCs() {
for (let npc of GAME.npcs) {
// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.beginPath();
ctx.ellipse(npc.x + 3, npc.y + 3, npc.size, npc.size * 0.6, 0, 0, Math.PI * 2);
ctx.fill();

// Body
ctx.fillStyle = npc.color;
ctx.beginPath();
ctx.arc(npc.x, npc.y, npc.size, 0, Math.PI * 2);
ctx.fill();

// Border
ctx.strokeStyle = '#000';
ctx.lineWidth = 2;
ctx.stroke();

// Name
ctx.fillStyle = '#fff';
ctx.font = '11px Courier New';
ctx.textAlign = 'center';
ctx.fillText(npc.name, npc.x, npc.y - npc.size - 8);

// Type indicator
if (npc.type === 'enemy') {
ctx.fillStyle = '#ff0000';
ctx.font = '16px Courier New';
ctx.fillText('!', npc.x, npc.y - npc.size - 20);
} else if (npc.type === 'ally') {
ctx.fillStyle = '#00ff00';
ctx.font = '16px Courier New';
ctx.fillText('★', npc.x, npc.y - npc.size - 20);
}

// Health bar
if (npc.health < npc.maxHealth) {
ctx.fillStyle = '#333';
ctx.fillRect(npc.x - 15, npc.y + npc.size + 5, 30, 4);
ctx.fillStyle = '#ff0000';
ctx.fillRect(npc.x - 15, npc.y + npc.size + 5, 30 * (npc.health / npc.maxHealth), 4);
}
}
}

function drawEnemies() {
for (let enemy of GAME.enemies) {
// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.beginPath();
ctx.ellipse(enemy.x + 2, enemy.y + 2, enemy.size, enemy.size * 0.6, 0, 0, Math.PI * 2);
ctx.fill();

// Body
ctx.fillStyle = enemy.color;
ctx.beginPath();
ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
ctx.fill();

// Border
ctx.strokeStyle = '#000';
ctx.lineWidth = 2;
ctx.stroke();

// Health bar
ctx.fillStyle = '#333';
ctx.fillRect(enemy.x - 15, enemy.y - enemy.size - 10, 30, 4);
ctx.fillStyle = '#ff0000';
ctx.fillRect(enemy.x - 15, enemy.y - enemy.size - 10, 30 * (enemy.health / enemy.maxHealth), 4);

// State indicator
if (enemy.state === 'chase') {
ctx.fillStyle = '#ff0000';
ctx.font = '14px Courier New';
ctx.textAlign = 'center';
ctx.fillText('!', enemy.x, enemy.y - enemy.size - 15);
}
}
}

function drawPlayer() {
const player = GAME.player;

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.beginPath();
ctx.ellipse(player.x + 3, player.y + 3, player.size, player.size * 0.6, 0, 0, Math.PI * 2);
ctx.fill();

// Body
ctx.fillStyle = player.color;
ctx.beginPath();
ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
ctx.fill();

// Border
ctx.strokeStyle = '#000';
ctx.lineWidth = 2;
ctx.stroke();

// Direction indicator (gun)
const gunX = player.x + Math.cos(player.angle) * 25;
const gunY = player.y + Math.sin(player.angle) * 25;
ctx.strokeStyle = '#fff';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.moveTo(player.x, player.y);
ctx.lineTo(gunX, gunY);
ctx.stroke();

// Gun tip
ctx.fillStyle = '#ffff00';
ctx.beginPath();
ctx.arc(gunX, gunY, 3, 0, Math.PI * 2);
ctx.fill();

// Name
ctx.fillStyle = '#fff';
ctx.font = '12px Courier New';
ctx.textAlign = 'center';
ctx.fillText(player.name, player.x, player.y - player.size - 10);

// Weapon
ctx.fillStyle = '#aaa';
ctx.font = '10px Courier New';
ctx.fillText(player.weapon, player.x, player.y - player.size - 22);

// Invincibility flash
if (player.invincible > 0 && Math.floor(player.invincible / 3) % 2 === 0) {
ctx.fillStyle = 'rgba(255,255,255,0.3)';
ctx.beginPath();
ctx.arc(player.x, player.y, player.size + 5, 0, Math.PI * 2);
ctx.fill();
}
}

function drawBullets() {
for (let bullet of GAME.bullets) {
ctx.fillStyle = bullet.color;
ctx.beginPath();
ctx.arc(bullet.x, bullet.y, 3, 0, Math.PI * 2);
ctx.fill();

// Trail
ctx.strokeStyle = bullet.color + '88';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(bullet.x, bullet.y);
ctx.lineTo(bullet.x - bullet.vx * 2, bullet.y - bullet.vy * 2);
ctx.stroke();
}
}

function drawParticles() {
for (let p of GAME.particles) {
const alpha = p.life / p.maxLife;
ctx.fillStyle = p.color + Math.floor(alpha * 255).toString(16).padStart(2, '0');
ctx.beginPath();
ctx.arc(p.x, p.y, p.size * alpha, 0, Math.PI * 2);
ctx.fill();
}
}

function drawMinimap() {
minimapCtx.fillStyle = '#111';
minimapCtx.fillRect(0, 0, 180, 180);

const scale = 180 / GAME.worldWidth;

// Draw districts
for (let [key, district] of Object.entries(DISTRICTS)) {
minimapCtx.fillStyle = district.color + '44';
minimapCtx.fillRect(district.x * scale, district.y * scale, district.w * scale, district.h * scale);
}

// Draw buildings
minimapCtx.fillStyle = '#555';
for (let building of GAME.buildings) {
minimapCtx.fillRect(building.x * scale, building.y * scale, Math.max(2, building.w * scale), Math.max(2, building.h * scale));
}

// Draw NPCs
for (let npc of GAME.npcs) {
minimapCtx.fillStyle = npc.type === 'enemy' ? '#ff0000' : npc.type === 'ally' ? '#00ff00' : '#ffff00';
minimapCtx.beginPath();
minimapCtx.arc(npc.x * scale, npc.y * scale, 2, 0, Math.PI * 2);
minimapCtx.fill();
}

// Draw enemies
minimapCtx.fillStyle = '#ff4444';
for (let enemy of GAME.enemies) {
minimapCtx.beginPath();
minimapCtx.arc(enemy.x * scale, enemy.y * scale, 2, 0, Math.PI * 2);
minimapCtx.fill();
}

// Draw player
if (GAME.player) {
minimapCtx.fillStyle = '#00ffff';
minimapCtx.beginPath();
minimapCtx.arc(GAME.player.x * scale, GAME.player.y * scale, 4, 0, Math.PI * 2);
minimapCtx.fill();

// Player direction
const gunX = GAME.player.x + Math.cos(GAME.player.angle) * 10;
const gunY = GAME.player.y + Math.sin(GAME.player.angle) * 10;
minimapCtx.strokeStyle = '#00ffff';
minimapCtx.lineWidth = 1;
minimapCtx.beginPath();
minimapCtx.moveTo(GAME.player.x * scale, GAME.player.y * scale);
minimapCtx.lineTo(gunX * scale, gunY * scale);
minimapCtx.stroke();
}

// Camera view rectangle
minimapCtx.strokeStyle = '#ffffff44';
minimapCtx.lineWidth = 1;
minimapCtx.strokeRect(
GAME.camera.x * scale,
GAME.camera.y * scale,
canvas.width * scale,
canvas.height * scale
);

// Border
minimapCtx.strokeStyle = '#ffaa00';
minimapCtx.lineWidth = 2;
minimapCtx.strokeRect(0, 0, 180, 180);
}

function drawDayNightOverlay() {
const dayProgress = GAME.dayTime / GAME.dayLength;
let alpha = 0;

if (dayProgress > 0.75) {
alpha = (dayProgress - 0.75) * 0.6;
} else if (dayProgress < 0.15) {
alpha = (0.15 - dayProgress) * 0.6;
}

if (alpha > 0) {
ctx.fillStyle = `rgba(0, 0, 30, ${alpha})`;
ctx.fillRect(0, 0, canvas.width, canvas.height);

// Stars at night
if (alpha > 0.3) {
ctx.fillStyle = '#ffffff';
for (let i = 0; i < 50; i++) {
const sx = (Math.sin(i * 123.456 + GAME.dayTime * 0.01) * 0.5 + 0.5) * canvas.width;
const sy = (Math.cos(i * 789.012 + GAME.dayTime * 0.005) * 0.5 + 0.5) * canvas.height * 0.5;
ctx.beginPath();
ctx.arc(sx, sy, 1, 0, Math.PI * 2);
ctx.fill();
}
}
}
}

// Game Loop
function gameLoop() {
update();
render();
requestAnimationFrame(gameLoop);
}

// Start
gameLoop();
</script>
