  margin-bottom: 30px;
  text-shadow: 0 0 15px #ffaa00;
}
.charGrid {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  justify-content: center;
  max-width: 900px;
}
.charCard {
  width: 200px;
  padding: 20px;
  background: linear-gradient(180deg, #2a2a4a, #1a1a2a);
  border: 2px solid #4444ff;
  border-radius: 10px;
  text-align: center;
  cursor: pointer;
  transition: all 0.3s;
}
.charCard:hover {
  border-color: #ff4444;
  transform: scale(1.05);
  box-shadow: 0 0 20px rgba(255,68,68,0.5);
}
.charCard .charIcon {
  width: 80px;
  height: 80px;
  margin: 0 auto 15px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2em;
}
.charCard h3 { color: #ffaa00; margin-bottom: 10px; }
.charCard .stats { font-size: 0.85em; color: #aaa; }
.charCard .stats div { margin: 3px 0; }
.statBar {
  width: 100%;
  height: 6px;
  background: #333;
  border-radius: 3px;
  overflow: hidden;
  margin-top: 2px;
}
.statBarFill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s;
}

/* Village Hub */
#villageHub {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: linear-gradient(180deg, #87CEEB 0%, #98D8C8 40%, #228B22 40%, #1a6b1a 100%);
  display: none;
  z-index: 80;
}
#villageHub .hubTop {
  position: absolute;
  top: 10px; left: 10px;
  background: rgba(0,0,0,0.7);
  padding: 10px 20px;
  border-radius: 10px;
  border: 1px solid #ffaa00;
}
#villageHub .hubTop .playerInfo {
  font-size: 1.1em;
  color: #ffaa00;
}
#villageHub .hubTop .playerInfo span { color: #fff; }
.hubNPCs {
  position: absolute;
  bottom: 100px;
  width: 100%;
  display: flex;
  justify-content: center;
  gap: 40px;
}
.npc {
  text-align: center;
  cursor: pointer;
  transition: transform 0.3s;
}
.npc:hover { transform: scale(1.1); }
.npcIcon {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  margin: 0 auto 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5em;
  border: 2px solid #fff;
}
.npcName {
  font-size: 0.8em;
  color: #fff;
  text-shadow: 1px 1px 2px #000;
  background: rgba(0,0,0,0.5);
  padding: 2px 8px;
  border-radius: 10px;
}

/* Battle Screen */
#battleScreen {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  display: none;
  z-index: 70;
}
#battleCanvas {
  width: 100%;
  height: 100%;
}
.battleHUD {
  position: absolute;
  top: 10px;
  left: 10px;
  right: 10px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  pointer-events: none;
}
.hudBar {
  background: rgba(0,0,0,0.8);
  padding: 10px 15px;
  border-radius: 10px;
  border: 1px solid #555;
  min-width: 200px;
}
.hudBar .name {
  font-size: 1em;
  font-weight: bold;
  margin-bottom: 5px;
}
.hudBar .barContainer {
  width: 100%;
  height: 20px;
  background: #333;
  border-radius: 10px;
  overflow: hidden;
  margin: 3px 0;
  position: relative;
}
.hudBar .barFill {
  height: 100%;
  transition: width 0.3s;
  border-radius: 10px;
}
.hudBar .barText {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 0.75em;
  font-weight: bold;
  text-shadow: 1px 1px 2px #000;
}
.hpFill { background: linear-gradient(90deg, #ff0000, #ff4444); }
.chakraFill { background: linear-gradient(90deg, #0066ff, #4488ff); }
.expFill { background: linear-gradient(90deg, #ffaa00, #ffcc44); }
.enemyHPFill { background: linear-gradient(90deg, #aa0000, #ff0000); }

.battleActions {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 10px;
  pointer-events: auto;
}
.actionBtn {
  padding: 12px 25px;
  font-size: 1em;
  font-weight: bold;
  border: 2px solid;
  background: rgba(0,0,0,0.8);
  color: #fff;
  cursor: pointer;
  border-radius: 8px;
  transition: all 0.2s;
  text-transform: uppercase;
}
.actionBtn:hover { transform: scale(1.1); }
.actionBtn.attack { border-color: #ff4444; color: #ff4444; }
.actionBtn.attack:hover { background: #ff4444; color: #fff; }
.actionBtn.special { border-color: #4488ff; color: #4488ff; }
.actionBtn.special:hover { background: #4488ff; color: #fff; }
.actionBtn.ultimate { border-color: #ffaa00; color: #ffaa00; }
.actionBtn.ultimate:hover { background: #ffaa00; color: #000; }
.actionBtn.heal { border-color: #44ff44; color: #44ff44; }
.actionBtn.heal:hover { background: #44ff44; color: #000; }
.actionBtn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
  transform: none !important;
}

/* Damage Numbers */
.damageNumber {
  position: absolute;
  font-size: 1.5em;
  font-weight: bold;
  pointer-events: none;
  animation: damageFloat 1s ease-out forwards;
  z-index: 200;
  text-shadow: 2px 2px 4px #000;
}
@keyframes damageFloat {
  0% { opacity: 1; transform: translateY(0) scale(1); }
  100% { opacity: 0; transform: translateY(-80px) scale(1.5); }
}

/* Shop */
#shopScreen {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0,0,0,0.9);
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 95;
}
#shopScreen h2 {
  font-size: 2em;
  color: #ffaa00;
  margin-bottom: 20px;
}
.shopGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 15px;
  max-width: 800px;
  margin-bottom: 20px;
}
.shopItem {
  background: linear-gradient(180deg, #2a2a4a, #1a1a2a);
  border: 2px solid #555;
  border-radius: 10px;
  padding: 15px;
  text-align: center;
  cursor: pointer;
  transition: all 0.3s;
}
.shopItem:hover {
  border-color: #ffaa00;
  transform: scale(1.05);
}
.shopItem .itemIcon { font-size: 2em; margin-bottom: 5px; }
.shopItem .itemName { color: #ffaa00; font-weight: bold; margin-bottom: 5px; }
.shopItem .itemDesc { font-size: 0.8em; color: #aaa; margin-bottom: 5px; }
.shopItem .itemPrice { color: #44ff44; font-weight: bold; }

/* Inventory */
#inventoryScreen {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0,0,0,0.9);
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 95;
}
#inventoryScreen h2 {
  font-size: 2em;
  color: #ffaa00;
  margin-bottom: 20px;
}
.invGrid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  max-width: 600px;
  margin-bottom: 20px;
}
.invSlot {
  width: 80px;
  height: 80px;
  background: linear-gradient(180deg, #2a2a4a, #1a1a2a);
  border: 2px solid #555;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s;
}
.invSlot:hover { border-color: #ffaa00; }
.invSlot .itemIcon { font-size: 1.5em; }
.invSlot .itemCount { font-size: 0.7em; color: #aaa; }

/* Level Up */
#levelUpScreen {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0,0,0,0.8);
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 110;
}
#levelUpScreen h2 {
  font-size: 3em;
  color: #ffaa00;
  text-shadow: 0 0 30px #ffaa00;
  animation: levelUpPulse 0.5s ease-in-out 3;
}
@keyframes levelUpPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.2); }
}

/* Notification */
.notification {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(0,0,0,0.9);
  border: 2px solid #ffaa00;
  padding: 20px 40px;
  border-radius: 10px;
  font-size: 1.5em;
  color: #ffaa00;
  z-index: 200;
  animation: notifFade 2s ease-out forwards;
  text-align: center;
}
@keyframes notifFade {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.5); }
  20% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  80% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -60%) scale(0.8); }
}

/* Scrollbar */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: #1a1a2a; }
::-webkit-scrollbar-thumb { background: #ff4444; border-radius: 4px; }

/* Responsive */
@media (max-width: 768px) {
  #titleScreen h1 { font-size: 2.5em; }
  .charGrid { gap: 10px; }
  .charCard { width: 150px; padding: 15px; }
  .battleActions { flex-wrap: wrap; justify-content: center; }
  .actionBtn { padding: 8px 15px; font-size: 0.8em; }
  .shopGrid { grid-template-columns: repeat(2, 1fr); }
  .invGrid { grid-template-columns: repeat(4, 1fr); }
}
</style>
</head>
