}

function startBattle() {
  showBattle();
}

function openShop() {
  hideAllScreens();
  document.getElementById('shopScreen').style.display = 'flex';
  document.getElementById('shopGold').textContent = GameState.player.gold;
  renderShop();
}

function closeShop() {
  showVillage();
}

function renderShop() {
  const grid = document.getElementById('shopGrid');
  grid.innerHTML = '';
  SHOP_ITEMS.forEach(item => {
    const div = document.createElement('div');
    div.className = 'shopItem';
    div.innerHTML = `
      <div class="itemIcon">${item.icon}</div>
      <div class="itemName">${item.name}</div>
      <div class="itemDesc">${item.desc}</div>
      <div class="itemPrice">💰 ${item.price}</div>
    `;
    div.onclick = () => buyItem(item);
    grid.appendChild(div);
  });
}

function buyItem(item) {
  if (GameState.player.gold >= item.price) {
    GameState.player.gold -= item.price;
    document.getElementById('shopGold').textContent = GameState.player.gold;

    switch(item.effect) {
      case 'hp':
        addInventoryItem(item);
        break;
      case 'chakra':
        addInventoryItem(item);
        break;
      case 'attack':
        GameState.player.attack += item.value;
        showNotification(`+${item.value} Attack!`);
        break;
      case 'defense':
        GameState.player.defense += item.value;
        showNotification(`+${item.value} Defense!`);
        break;
      case 'speed':
        GameState.player.speed += item.value;
        showNotification(`+${item.value} Speed!`);
        break;
      case 'revive':
        addInventoryItem(item);
        break;
      case 'exp':
        GameState.player.exp += item.value;
        checkLevelUp();
        showNotification(`+${item.value} EXP!`);
        break;
    }
    playSound('coin');
  } else {
    showNotification('Gold tidak cukup!');
  }
}

function addInventoryItem(item) {
  const existing = GameState.player.inventory.find(i => i.id === item.id);
  if (existing) {
    existing.count++;
  } else {
    GameState.player.inventory.push({ ...item, count: 1 });
  }
}

function openInventory() {
  hideAllScreens();
  document.getElementById('inventoryScreen').style.display = 'flex';
  renderInventory();
}

function closeInventory() {
  showVillage();
}

function renderInventory() {
  const grid = document.getElementById('invGrid');
  grid.innerHTML = '';
  const inv = GameState.player.inventory;

  for (let i = 0; i < 20; i++) {
    const slot = document.createElement('div');
    slot.className = 'invSlot';
    if (inv[i]) {
      slot.innerHTML = `
        <div class="itemIcon">${inv[i].icon}</div>
        <div class="itemCount">x${inv[i].count}</div>
      `;
      slot.onclick = () => useInventoryItem(i);
    } else {
      slot.innerHTML = '<div style="color:#333;font-size:1.5em;">-</div>';
    }
    grid.appendChild(slot);
  }
}

function useInventoryItem(index) {
  const item = GameState.player.inventory[index];
  if (!item) return;

  switch(item.effect) {
    case 'hp':
      GameState.player.hp = Math.min(GameState.player.maxHp, GameState.player.hp + item.value);
      showNotification(`+${item.value} HP restored!`);
      playSound('heal');
      break;
    case 'chakra':
      GameState.player.chakra = Math.min(GameState.player.maxChakra, GameState.player.chakra + item.value);
      showNotification(`+${item.value} Chakra restored!`);
      playSound('heal');
      break;
    case 'revive':
      showNotification('Revive Token used!');
      break;
  }

  item.count--;
  if (item.count <= 0) {
    GameState.player.inventory.splice(index, 1);
  }
  renderInventory();
  updateHubUI();
}

function trainStats() {
  if (GameState.player.gold >= 30) {
    GameState.player.gold -= 30;
    GameState.player.attack += 2;
    GameState.player.defense += 2;
    GameState.player.speed += 2;
    showNotification('Stats trained! +2 ATK, DEF, SPD');
    playSound('coin');
    updateHubUI();
  } else {
    showNotification('Gold tidak cukup! (Butuh 30 gold)');
  }
}

function restAtInn() {
  if (GameState.player.gold >= 10) {
    GameState.player.gold -= 10;
    GameState.player.hp = GameState.player.maxHp;
    GameState.player.chakra = GameState.player.maxChakra;
    showNotification('Fully restored! HP & Chakra full.');
    playSound('heal');
    updateHubUI();
  } else {
    showNotification('Gold tidak cukup! (Butuh 10 gold)');
  }
}

// ==================== BATTLE SYSTEM ====================
function startBattle() {
  GameState.battleActive = true;
  GameState.wave = GameState.player.wave;
  GameState.particles = [];
  GameState.projectiles = [];

  // Generate enemy based on wave
  const enemyIndex = Math.min(Math.floor((GameState.wave - 1) / 2), ENEMIES.length - 1);
  const enemyTemplate = ENEMIES[enemyIndex];
  const waveMultiplier = 1 + (GameState.wave - 1) * 0.15;

  GameState.currentEnemy = {
    name: enemyTemplate.name,
    icon: enemyTemplate.icon,
    hp: Math.floor(enemyTemplate.hp * waveMultiplier),
    maxHp: Math.floor(enemyTemplate.hp * waveMultiplier),
    attack: Math.floor(enemyTemplate.attack * waveMultiplier),
    defense: Math.floor(enemyTemplate.defense * waveMultiplier),
    exp: Math.floor(enemyTemplate.exp * waveMultiplier),
    gold: Math.floor(enemyTemplate.gold * waveMultiplier),
    color: enemyTemplate.color,
    x: 0,
    y: 0,
    animFrame: 0,
    animTimer: 0,
    state: 'idle',
    stateTimer: 0,
    hitTimer: 0
  };

  GameState.player.x = 200;
  GameState.player.y = 0;
  GameState.player.vy = 0;
  GameState.player.onGround = true;
  GameState.player.facing = 1;
  GameState.player.attackCooldown = 0;
  GameState.player.specialCooldown = 0;
  GameState.player.ultimateCooldown = 0;
  GameState.player.healCooldown = 0;
  GameState.player.isAttacking = false;
  GameState.player.attackTimer = 0;

  updateBattleUI();
  document.getElementById('waveNumber').textContent = GameState.wave;

  // Start battle loop
  if (!GameState.battleLoop) {
    GameState.battleLoop = requestAnimationFrame(battleLoop);
  }
}

function updateBattleUI() {
  const p = GameState.player;
  const e = GameState.currentEnemy;

  document.getElementById('battlePlayerName').textContent = p.name;
  document.getElementById('battleEnemyName').textContent = e.name;

  document.getElementById('playerHPBar').style.width = (p.hp / p.maxHp * 100) + '%';
  document.getElementById('playerHPText').textContent = `${Math.floor(p.hp)}/${p.maxHp}`;

  document.getElementById('playerChakraBar').style.width = (p.chakra / p.maxChakra * 100) + '%';
  document.getElementById('playerChakraText').textContent = `${Math.floor(p.chakra)}/${p.maxChakra}`;

  document.getElementById('playerEXPBar').style.width = (p.exp / p.expToNext * 100) + '%';
  document.getElementById('playerEXPText').textContent = `${Math.floor(p.exp)}/${p.expToNext}`;

  document.getElementById('enemyHPBar').style.width = (e.hp / e.maxHp * 100) + '%';
  document.getElementById('enemyHPText').textContent = `${Math.floor(e.hp)}/${e.maxHp}`;
}

function battleLoop(timestamp) {
  if (!GameState.battleActive) return;

  const canvas = document.getElementById('battleCanvas');
  const ctx = canvas.getContext('2d');
  canvas.width = canvas.clientWidth;
  canvas.height = canvas.clientHeight;

  const W = canvas.width;
  const H = canvas.height;
  const groundY = H - 100;

  // Update player position
  if (GameState.keys['a'] || GameState.keys['arrowleft']) {
    GameState.player.x -= 5;
    GameState.player.facing = -1;
  }
  if (GameState.keys['d'] || GameState.keys['arrowright']) {
    GameState.player.x += 5;
    GameState.player.facing = 1;
  }
  if ((GameState.keys['w'] || GameState.keys['arrowup']) && GameState.player.onGround) {
    GameState.player.vy = -15;
    GameState.player.onGround = false;
  }

  // Gravity
  GameState.player.vy += 0.8;
  GameState.player.y += GameState.player.vy;

  if (GameState.player.y >= groundY) {
    GameState.player.y = groundY;
    GameState.player.vy = 0;
    GameState.player.onGround = true;
  }

  // Clamp player position
  GameState.player.x = Math.max(50, Math.min(W - 50, GameState.player.x));

  // Update cooldowns
  if (GameState.player.attackCooldown > 0) GameState.player.attackCooldown--;
  if (GameState.player.specialCooldown > 0) GameState.player.specialCooldown--;
  if (GameState.player.ultimateCooldown > 0) GameState.player.ultimateCooldown--;
  if (GameState.player.healCooldown > 0) GameState.player.healCooldown--;
  if (GameState.player.attackTimer > 0) GameState.player.attackTimer--;
  else GameState.player.isAttacking = false;

  // Enemy AI
  updateEnemyAI(timestamp);

  // Update particles
  updateParticles();

  // Update projectiles
  updateProjectiles();

  // Screen shake
  if (GameState.screenShake > 0) {
    GameState.screenShake *= 0.9;
    if (GameState.screenShake < 0.5) GameState.screenShake = 0;
  }

  // Draw
  ctx.save();
  if (GameState.screenShake > 0) {
    ctx.translate(
      (Math.random() - 0.5) * GameState.screenShake,
      (Math.random() - 0.5) * GameState.screenShake
    );
  }

  // Background
  drawBackground(ctx, W, H);

  // Ground
  ctx.fillStyle = '#2a5a2a';
  ctx.fillRect(0, groundY, W, H - groundY);
  ctx.fillStyle = '#3a7a3a';
  ctx.fillRect(0, groundY, W, 5);

  // Draw enemies
  drawEnemy(ctx);

  // Draw player
  drawPlayer(ctx);

  // Draw projectiles
  drawProjectiles(ctx);

  // Draw particles
  drawParticles(ctx);

  ctx.restore();

  updateBattleUI();

  // Check win/lose
  if (GameState.currentEnemy.hp <= 0) {
    battleWin();
    return;
  }
  if (GameState.player.hp <= 0) {
    battleLose();
    return;
  }

  GameState.battleLoop = requestAnimationFrame(battleLoop);
}

function drawBackground(ctx, W, H) {
  // Sky gradient
  const skyGrad = ctx.createLinearGradient(0, 0, 0, H);
  skyGrad.addColorStop(0, '#1a0a2e');
  skyGrad.addColorStop(0.5, '#2a1a4e');
  skyGrad.addColorStop(1, '#1a3a1a');
  ctx.fillStyle = skyGrad;
  ctx.fillRect(0, 0, W, H);

  // Stars
  ctx.fillStyle = '#fff';
  for (let i = 0; i < 50; i++) {
    const x = (i * 137.5) % W;
    const y = (i * 97.3) % (H * 0.5);
    const size = (i % 3) + 1;
    ctx.globalAlpha = 0.3 + (Math.sin(Date.now() * 0.001 + i) * 0.3);
    ctx.fillRect(x, y, size, size);
  }
  ctx.globalAlpha = 1;

  // Mountains
  ctx.fillStyle = '#1a2a1a';
  ctx.beginPath();
  ctx.moveTo(0, H - 150);
  for (let i = 0; i <= W; i += 50) {
    ctx.lineTo(i, H - 150 - Math.sin(i * 0.01) * 50 - Math.cos(i * 0.02) * 30);
  }
  ctx.lineTo(W, H);
  ctx.lineTo(0, H);
  ctx.fill();

  // Trees
  for (let i = 0; i < 8; i++) {
    const x = i * (W / 7) + 30;
    const treeH = 60 + (i % 3) * 20;
    ctx.fillStyle = '#1a4a1a';
    ctx.beginPath();
    ctx.moveTo(x, H - 100);
    ctx.lineTo(x - 15, H - 100);
    ctx.lineTo(x, H - 100 - treeH);
    ctx.lineTo(x + 15, H - 100);
    ctx.fill();
    ctx.fillStyle = '#3a2a1a';
    ctx.fillRect(x - 3, H - 100, 6, 20);
  }
}

function drawPlayer(ctx) {
  const p = GameState.player;
  const char = CHARACTERS[p.character];
  const x = p.x;
  const y = p.y;

  ctx.save();
  ctx.translate(x, y);
  ctx.scale(p.facing, 1);

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(0, 0, 20, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body
  const bodyColor = char.color;
  ctx.fillStyle = '#2a2a2a';
  ctx.fillRect(-15, -60, 30, 40);

  // Head
  ctx.fillStyle = '#ffcc99';
  ctx.beginPath();
  ctx.arc(0, -70, 15, 0, Math.PI * 2);
  ctx.fill();

  // Headband
  ctx.fillStyle = '#333';
  ctx.fillRect(-16, -80, 32, 8);
  ctx.fillStyle = '#aaa';
  ctx.fillRect(-8, -79, 16, 6);

  // Eyes
  ctx.fillStyle = '#fff';
  ctx.fillRect(-8, -72, 6, 4);
  ctx.fillRect(2, -72, 6, 4);
  ctx.fillStyle = '#000';
  ctx.fillRect(-6, -71, 3, 3);
  ctx.fillRect(4, -71, 3, 3);

  // Legs
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(-12, -20, 10, 20);
  ctx.fillRect(2, -20, 10, 20);

  // Arms
  if (p.isAttacking) {
    // Attack animation
    ctx.fillStyle = '#ffcc99';
    ctx.fillRect(15, -55, 25, 8);
    // Sword/weapon effect
    ctx.fillStyle = bodyColor;
    ctx.globalAlpha = 0.7;
    ctx.fillRect(35, -60, 30, 18);
    ctx.globalAlpha = 1;
  } else {
    ctx.fillStyle = '#ffcc99';
    ctx.fillRect(-20, -55, 8, 25);
    ctx.fillRect(12, -55, 8, 25);
  }

  // Character icon
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(char.icon, 0, -90);

  // Chakra aura
  if (p.chakra > 0) {
    ctx.strokeStyle = char.color;
    ctx.globalAlpha = 0.3 + Math.sin(Date.now() * 0.005) * 0.2;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, -40, 35 + Math.sin(Date.now() * 0.003) * 5, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  ctx.restore();
}

function drawEnemy(ctx) {
  const e = GameState.currentEnemy;
  const canvas = document.getElementById('battleCanvas');
  const W = canvas.width;
  const x = W - 200;
  const groundY = canvas.height - 100;
  const y = groundY;

  ctx.save();
  ctx.translate(x, y);

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(0, 0, 25, 6, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body
  ctx.fillStyle = '#3a3a3a';
  ctx.fillRect(-20, -70, 40, 50);

  // Head
  ctx.fillStyle = '#ffcc99';
  ctx.beginPath();
  ctx.arc(0, -80, 18, 0, Math.PI * 2);
  ctx.fill();

  // Eyes (angry)
  ctx.fillStyle = '#ff0000';
  ctx.fillRect(-10, -85, 8, 5);
  ctx.fillRect(2, -85, 8, 5);
  ctx.fillStyle = '#000';
  ctx.fillRect(-8, -84, 4, 3);
  ctx.fillRect(4, -84, 4, 3);

  // Mouth
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-8, -70);
  ctx.lineTo(8, -70);
  ctx.stroke();

  // Legs
  ctx.fillStyle = '#2a2a2a';
  ctx.fillRect(-15, -20, 12, 20);
  ctx.fillRect(3, -20, 12, 20);

  // Arms
  ctx.fillStyle = '#ffcc99';
  ctx.fillRect(-28, -65, 10, 30);
  ctx.fillRect(18, -65, 10, 30);

  // Enemy icon
  ctx.font = '25px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(e.icon, 0, -100);

  // Hit flash
  if (e.hitTimer > 0) {
    ctx.globalAlpha = e.hitTimer / 10;
    ctx.fillStyle = '#fff';
    ctx.fillRect(-25, -85, 50, 75);
    ctx.globalAlpha = 1;
    e.hitTimer--;
  }

  ctx.restore();
}

function updateEnemyAI(timestamp) {
  const e = GameState.currentEnemy;
  const p = GameState.player;
  const canvas = document.getElementById('battleCanvas');
  const W = canvas.width;

  e.stateTimer++;

  // Simple AI: move towards player and attack
  const dx = p.x - (W - 200);
  const dist = Math.abs(dx);

  if (dist > 100) {
    // Move towards player
    if (dx > 0) {
      e.x = (W - 200) + 2;
    } else {
      e.x = (W - 200) - 2;
    }
  } else if (dist < 80 && e.stateTimer > 60) {
    // Attack player
    if (e.stateTimer % 60 === 0) {
      enemyAttack();
    }
  }

  // Random special attack
  if (Math.random() < 0.005 && e.stateTimer > 120) {
    enemySpecial();
  }
}

function enemyAttack() {
  const e = GameState.currentEnemy;
  const p = GameState.player;

  const damage = Math.max(1, e.attack - p.defense / 2);
  p.hp -= damage;
  e.hitTimer = 10;
  GameState.screenShake = 5;
  playSound('hit');

  // Show damage number
  showDamageNumber(p.x, p.y - 80, Math.floor(damage), '#ff4444');

  // Spawn hit particles
  for (let i = 0; i < 5; i++) {
    GameState.particles.push({
      x: p.x,
      y: p.y - 40,
      vx: (Math.random() - 0.5) * 10,
      vy: (Math.random() - 0.5) * 10,
      life: 30,
      maxLife: 30,
      color: '#ff4444',
      size: 3 + Math.random() * 3
    });
  }
}

function enemySpecial() {
  const e = GameState.currentEnemy;
  const p = GameState.player;
  const canvas = document.getElementById('battleCanvas');
  const W = canvas.width;

  const damage = Math.max(1, e.attack * 1.5 - p.defense / 3);
  p.hp -= damage;
  GameState.screenShake = 10;
  playSound('special');

  // Create projectile
  GameState.projectiles.push({
    x: W - 200,
    y: p.y - 50,
    vx: -8,
    vy: 0,
    damage: Math.floor(damage),
    color: e.color,
    type: 'enemy_special',
    life: 100,
    size: 15
  });

  showDamageNumber(p.x, p.y - 80, Math.floor(damage), '#ff8844');
}

function playerAttack() {
  if (!GameState.battleActive || GameState.player.attackCooldown > 0) return;

  const p = GameState.player;
  const e = GameState.currentEnemy;

  p.isAttacking = true;
  p.attackTimer = 15;
  p.attackCooldown = 20;

  const damage = Math.max(1, p.attack - e.defense / 2);
  e.hp -= damage;
  e.hitTimer = 10;
  GameState.screenShake = 3;
  playSound('attack');

  showDamageNumber(GameState.currentEnemy ? (document.getElementById('battleCanvas').width - 200) : 0, 
                    document.getElementById('battleCanvas').height - 150, 
                    Math.floor(damage), '#ff4444');

  // Spawn attack particles
  for (let i = 0; i < 8; i++) {
    GameState.particles.push({
      x: p.x + p.facing * 30,
      y: p.y - 40,
      vx: p.facing * (5 + Math.random() * 5),
      vy: (Math.random() - 0.5) * 5,
      life: 20,
      maxLife: 20,
      color: CHARACTERS[p.character].color,
      size: 2 + Math.random() * 3
    });
  }
}

function playerSpecial() {
  if (!GameState.battleActive || GameState.player.specialCooldown > 0 || GameState.player.chakra < 30) return;

  const p = GameState.player;
  const e = GameState.currentEnemy;

  p.chakra -= 30;
  p.specialCooldown = 60;
  p.isAttacking = true;
  p.attackTimer = 25;

  const damage = Math.max(1, p.attack * 2 - e.defense / 3);
  e.hp -= damage;
  e.hitTimer = 15;
  GameState.screenShake = 8;
  playSound('special');

  // Create special projectile
  GameState.projectiles.push({
    x: p.x + p.facing * 20,
    y: p.y - 50,
    vx: p.facing * 10,
    vy: 0,
    damage: Math.floor(damage),
    color: CHARACTERS[p.character].color,
    type: 'player_special',
    life: 60,
    size: 20
  });

  showDamageNumber(GameState.currentEnemy ? (document.getElementById('battleCanvas').width - 200) : 0, 
                    document.getElementById('battleCanvas').height - 150, 
                    Math.floor(damage), '#4488ff');

  // Spawn special particles
  for (let i = 0; i < 15; i++) {
    GameState.particles.push({
      x: p.x + p.facing * 30,
      y: p.y - 40,
      vx: p.facing * (8 + Math.random() * 8),
      vy: (Math.random() - 0.5) * 8,
      life: 30,
      maxLife: 30,
      color: CHARACTERS[p.character].color,
      size: 3 + Math.random() * 5
    });
  }
}

function playerUltimate() {
  if (!GameState.battleActive || GameState.player.ultimateCooldown > 0 || GameState.player.chakra < 60) return;

  const p = GameState.player;
  const e = GameState.currentEnemy;

  p.chakra -= 60;
  p.ultimateCooldown = 120;
  p.isAttacking = true;
  p.attackTimer = 40;

  const damage = Math.max(1, p.attack * 3 - e.defense / 4);
  e.hp -= damage;
  e.hitTimer = 20;
  GameState.screenShake = 15;
  playSound('ultimate');

  // Create ultimate projectile
  GameState.projectiles.push({
    x: p.x + p.facing * 20,
    y: p.y - 50,
    vx: p.facing * 12,
    vy: 0,
    damage: Math.floor(damage),
    color: '#ffaa00',
    type: 'player_ultimate',
    life: 80,
    size: 30
  });

  showDamageNumber(GameState.currentEnemy ? (document.getElementById('battleCanvas').width - 200) : 0, 
                    document.getElementById('battleCanvas').height - 150, 
                    Math.floor(damage), '#ffaa00');

  // Spawn ultimate particles
  for (let i = 0; i < 30; i++) {
    GameState.particles.push({
      x: p.x + p.facing * 30,
      y: p.y - 40,
      vx: p.facing * (10 + Math.random() * 15),
      vy: (Math.random() - 0.5) * 15,
      life: 40,
      maxLife: 40,
      color: ['#ff4444', '#ffaa00', '#ff0000', '#ffffff'][Math.floor(Math.random() * 4)],
      size: 4 + Math.random() * 6
    });
  }
}

function playerHeal() {
  if (!GameState.battleActive || GameState.player.healCooldown > 0 || GameState.player.chakra < 20) return;

  const p = GameState.player;
  p.chakra -= 20;
  p.healCooldown = 90;

  const healAmount = Math.floor(p.maxHp * 0.3);
  p.hp = Math.min(p.maxHp, p.hp + healAmount);
  playSound('heal');

  showDamageNumber(p.x, p.y - 80, healAmount, '#44ff44');

  // Spawn heal particles
  for (let i = 0; i < 10; i++) {
    GameState.particles.push({
      x: p.x,
      y: p.y - 40,
      vx: (Math.random() - 0.5) * 5,
      vy: -3 - Math.random() * 5,
      life: 40,
      maxLife: 40,
      color: '#44ff44',
      size: 3 + Math.random() * 4
    });
  }
}

function fleeBattle() {
  if (!GameState.battleActive) return;
  GameState.battleActive = false;
  if (GameState.battleLoop) cancelAnimationFrame(GameState.battleLoop);
  showVillage();
  showNotification('Kamu lari dari pertempuran!');
}

function battleWin() {
  GameState.battleActive = false;
  if (GameState.battleLoop) cancelAnimationFrame(GameState.battleLoop);

  const e = GameState.currentEnemy;
  const p = GameState.player;

  p.exp += e.exp;
  p.gold += e.gold;
  playSound('coin');

  showNotification(`🎉 Victory! +${e.exp} EXP, +${e.gold} Gold`);

  // Check level up
  checkLevelUp();

  // Next wave
  GameState.player.wave++;
  if (GameState.player.wave > GameState.player.maxWave) {
    GameState.player.wave = 1;
    GameState.player.maxWave = Math.min(20, GameState.player.maxWave + 1);
  }

  // Update rank
  updateRank();

  setTimeout(() => {
    showVillage();
  }, 2000);
}

function battleLose() {
  GameState.battleActive = false;
  if (GameState.battleLoop) cancelAnimationFrame(GameState.battleLoop);

  playSound('death');
  showNotification('💀 Defeated! Try again!');

  setTimeout(() => {
    GameState.player.hp = GameState.player.maxHp;
    GameState.player.chakra = GameState.player.maxChakra;
    showVillage();
  }, 2000);
}

function checkLevelUp() {
  const p = GameState.player;
  while (p.exp >= p.expToNext) {
    p.exp -= p.expToNext;
    p.level++;
    p.expToNext = Math.floor(p.expToNext * 1.5);

    // Stat increases
    p.maxHp += 10;
    p.hp = p.maxHp;
    p.maxChakra += 5;
    p.chakra = p.maxChakra;
    p.attack += 3;
    p.defense += 2;
    p.speed += 2;

    playSound('levelup');
    document.getElementById('newLevel').textContent = p.level;
    document.getElementById('levelUpScreen').style.display = 'flex';
  }
}

function closeLevelUp() {
  document.getElementById('levelUpScreen').style.display = 'none';
}

function updateRank() {
  const p = GameState.player;
  if (p.level >= 50) p.rank = 'Kage';
  else if (p.level >= 40) p.rank = 'Jonin';
  else if (p.level >= 30) p.rank = 'Chunin';
  else if (p.level >= 20) p.rank = 'Jonin';
  else if (p.level >= 10) p.rank = 'Chunin';
  else p.rank = 'Genin';
}

// ==================== PARTICLES & PROJECTILES ====================
function updateParticles() {
  for (let i = GameState.particles.length - 1; i >= 0; i--) {
    const p = GameState.particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.2;
    p.life--;
    if (p.life <= 0) {
      GameState.particles.splice(i, 1);
    }
  }
}

function updateProjectiles() {
  for (let i = GameState.projectiles.length - 1; i >= 0; i--) {
    const proj = GameState.projectiles[i];
    proj.x += proj.vx;
    proj.y += proj.vy;
    proj.life--;

    // Check collision with player
    if (proj.type === 'enemy_special') {
      const p = GameState.player;
      if (Math.abs(proj.x - p.x) < 30 && Math.abs(proj.y - (p.y - 40)) < 30) {
        p.hp -= proj.damage;
        GameState.screenShake = 5;
        playSound('hit');
        showDamageNumber(p.x, p.y - 80, proj.damage, '#ff4444');
        GameState.projectiles.splice(i, 1);
        continue;
      }
    }

    // Check collision with enemy
    if (proj.type === 'player_special' || proj.type === 'player_ultimate') {
      const e = GameState.currentEnemy;
      const canvas = document.getElementById('battleCanvas');
      const ex = canvas.width - 200;
      if (Math.abs(proj.x - ex) < 40 && Math.abs(proj.y - (canvas.height - 140)) < 40) {
        e.hp -= proj.damage;
        e.hitTimer = 15;
        GameState.screenShake = 10;
        playSound('hit');
        showDamageNumber(ex, canvas.height - 180, proj.damage, '#ffaa00');
        GameState.projectiles.splice(i, 1);
        continue;
      }
    }

    if (proj.life <= 0 || proj.x < -50 || proj.x > document.getElementById('battleCanvas').width + 50) {
      GameState.projectiles.splice(i, 1);
    }
  }
}

function drawProjectiles(ctx) {
  GameState.projectiles.forEach(proj => {
    ctx.save();
    ctx.globalAlpha = 0.8;

    if (proj.type === 'player_special') {
      // Fireball
      const grad = ctx.createRadialGradient(proj.x, proj.y, 0, proj.x, proj.y, proj.size);
      grad.addColorStop(0, '#fff');
      grad.addColorStop(0.3, proj.color);
      grad.addColorStop(1, 'transparent');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(proj.x, proj.y, proj.size, 0, Math.PI * 2);
      ctx.fill();
    } else if (proj.type === 'player_ultimate') {
      // Ultimate blast
      const grad = ctx.createRadialGradient(proj.x, proj.y, 0, proj.x, proj.y, proj.size);
      grad.addColorStop(0, '#fff');
      grad.addColorStop(0.2, '#ffaa00');
      grad.addColorStop(0.5, '#ff4400');
      grad.addColorStop(1, 'transparent');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(proj.x, proj.y, proj.size, 0, Math.PI * 2);
      ctx.fill();

      // Ring effect
      ctx.strokeStyle = '#ffaa00';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(proj.x, proj.y, proj.size + 5, 0, Math.PI * 2);
      ctx.stroke();
    } else if (proj.type === 'enemy_special') {
      // Enemy projectile
      ctx.fillStyle = proj.color;
      ctx.beginPath();
      ctx.arc(proj.x, proj.y, proj.size, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(proj.x, proj.y, proj.size * 0.5, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  });
}

function drawParticles(ctx) {
  GameState.particles.forEach(p => {
    ctx.save();
    ctx.globalAlpha = p.life / p.maxLife;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  });
}

// ==================== UI HELPERS ====================
function showDamageNumber(x, y, amount, color) {
  const canvas = document.getElementById('battleCanvas');
  const div = document.createElement('div');
  div.className = 'damageNumber';
  div.style.left = x + 'px';
  div.style.top = y + 'px';
  div.style.color = color;
  div.textContent = amount > 0 ? `-${amount}` : `+${Math.abs(amount)}`;
  document.getElementById('gameContainer').appendChild(div);
  setTimeout(() => div.remove(), 1000);
}

function showNotification(text) {
  const div = document.createElement('div');
  div.className = 'notification';
  div.textContent = text;
  document.getElementById('gameContainer').appendChild(div);
  setTimeout(() => div.remove(), 2000);
}

// ==================== INPUT HANDLING ====================
document.addEventListener('keydown', (e) => {
  GameState.keys[e.key.toLowerCase()] = true;

  if (GameState.screen === 'battle') {
    if (e.key.toLowerCase() === 'j') playerAttack();
    if (e.key.toLowerCase() === 'k') playerSpecial();
    if (e.key.toLowerCase() === 'l') playerUltimate();
    if (e.key.toLowerCase() === 'h') playerHeal();
  }
});

document.addEventListener('keyup', (e) => {
  GameState.keys[e.key.toLowerCase()] = false;
});

// Touch controls for mobile
document.addEventListener('touchstart', (e) => {
  const touch = e.touches[0];
  const x = touch.clientX;
  const y = touch.clientY;
  const W = window.innerWidth;
  const H = window.innerHeight;

  if (GameState.screen === 'battle') {
    // Left side = move left
    if (x < W / 3) {
      GameState.keys['a'] = true;
    }
    // Right side = move right
    if (x > W * 2 / 3) {
      GameState.keys['d'] = true;
    }
    // Top center = jump
    if (y < H / 3 && x > W / 3 && x < W * 2 / 3) {
      GameState.keys['w'] = true;
    }
  }
});

document.addEventListener('touchend', (e) => {
  GameState.keys['a'] = false;
  GameState.keys['d'] = false;
  GameState.keys['w'] = false;
});

// ==================== MAIN CANVAS (for title screen background) ====================
const mainCanvas = document.getElementById('gameCanvas');
const mainCtx = mainCanvas.getContext('2d');

function resizeCanvas() {
  mainCanvas.width = window.innerWidth;
  mainCanvas.height = window.innerHeight;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function drawTitleBackground() {
  if (GameState.screen !== 'title') {
    requestAnimationFrame(drawTitleBackground);
    return;
  }

  const W = mainCanvas.width;
  const H = mainCanvas.height;

  mainCtx.fillStyle = '#0a0a0a';
  mainCtx.fillRect(0, 0, W, H);

  // Animated particles
  const time = Date.now() * 0.001;
  for (let i = 0; i < 30; i++) {
    const x = (Math.sin(time + i * 0.5) * 0.5 + 0.5) * W;
    const y = (Math.cos(time * 0.7 + i * 0.3) * 0.5 + 0.5) * H;
    const size = 2 + Math.sin(time + i) * 2;
    mainCtx.fillStyle = `rgba(255, ${68 + i * 5}, ${68 + i * 3}, ${0.3 + Math.sin(time + i) * 0.2})`;
    mainCtx.beginPath();
    mainCtx.arc(x, y, size, 0, Math.PI * 2);
    mainCtx.fill();
  }

  requestAnimationFrame(drawTitleBackground);
}

drawTitleBackground();

// ==================== INIT ====================
showTitle();
</script>
