function lightenColor(hex, amount) {
  const num = parseInt(hex.replace('#', ''), 16);
  const r = Math.min(255, (num >> 16) + amount);
  const g = Math.min(255, ((num >> 8) & 0x00FF) + amount);
  const b = Math.min(255, (num & 0x0000FF) + amount);
  return `rgb(${r},${g},${b})`;
}

// Spawn management
let spawnTimer = 0;
let coinSpawnTimer = 0;
let powerupSpawnTimer = 0;
let trainSpawnTimer = 0;
let bgSpawnTimer = 0;

function spawnManagement() {
  spawnTimer++;
  coinSpawnTimer++;
  powerupSpawnTimer++;
  trainSpawnTimer++;
  bgSpawnTimer++;

  // Spawn obstacles
  if (spawnTimer > 60 - Math.min(gameSpeed * 2, 30)) {
    spawnObstacle();
    spawnTimer = 0;
  }

  // Spawn coins
  if (coinSpawnTimer > 40) {
    spawnCoin();
    coinSpawnTimer = 0;
  }

  // Spawn powerups
  if (powerupSpawnTimer > 300) {
    spawnPowerup();
    powerupSpawnTimer = 0;
  }

  // Spawn trains
  if (trainSpawnTimer > 200) {
    spawnTrain();
    trainSpawnTimer = 0;
  }

  // Spawn background elements
  if (bgSpawnTimer > 30) {
    spawnBgElement();
    bgSpawnTimer = 0;
  }
}

// Main game loop
function gameLoop() {
  frameCount++;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  switch(gameState) {
    case STATE.MENU:
      drawMenu();
      break;

    case STATE.PLAYING:
      spawnManagement();
      updatePlayer();
      updateObstacles();
      updateCoins();
      updatePowerups();
      updateTrains();
      updateBgElements();
      updateParticles();

      drawBackground();
      drawBgElements();
      drawTrains();
      drawObstacles();
      drawCoins();
      drawPowerups();
      drawPlayer();
      drawParticles();
      drawUI();
      break;

    case STATE.PAUSED:
      drawBackground();
      drawBgElements();
      drawTrains();
      drawObstacles();
      drawCoins();
      drawPowerups();
      drawPlayer();
      drawParticles();
      drawUI();
      drawPaused();
      break;

    case STATE.GAMEOVER:
      drawBackground();
      drawBgElements();
      drawTrains();
      drawObstacles();
      drawCoins();
      drawPowerups();
      drawPlayer();
      drawParticles();
      drawGameOver();
      break;
  }

  // Pause toggle
  if (gameState === STATE.PLAYING && keys['Escape'] || keys['p']) {
    gameState = STATE.PAUSED;
    keys['Escape'] = false;
    keys['p'] = false;
  }

  requestAnimationFrame(gameLoop);
}

// Polyfill for roundRect if needed
if (!CanvasRenderingContext2D.prototype.roundRect) {
  CanvasRenderingContext2D.prototype.roundRect = function(x, y, w, h, r) {
    if (typeof r === 'number') r = [r, r, r, r];
    const [tl, tr, br, bl] = r;
    this.moveTo(x + tl, y);
    this.lineTo(x + w - tr, y);
    this.quadraticCurveTo(x + w, y, x + w, y + tr);
    this.lineTo(x + w, y + h - br);
    this.quadraticCurveTo(x + w, y + h, x + w - br, y + h);
    this.lineTo(x + bl, y + h);
    this.quadraticCurveTo(x, y + h, x, y + h - bl);
    this.lineTo(x, y + tl);
    this.quadraticCurveTo(x, y, x + tl, y);
    this.closePath();
    return this;
  };
}

// Start the game
gameLoop();
</script>
</body>
</html>

