        <span class="icon">🥕</span>
        <span id="carrotCount">0</span>
      </div>
      <div class="stat-item">
        <span class="icon">💰</span>
        <span id="coinCount">0</span>
      </div>
    </div>
  </div>

  <!-- Stats Panel -->
  <div class="stats-panel">
    <div class="stat">
      <div class="stat-value" id="totalRabbits">0</div>
      <div>총 토끼</div>
    </div>
    <div class="stat">
      <div class="stat-value" id="coinsPerSec">0</div>
      <div>초당 수익</div>
    </div>
    <div class="stat">
      <div class="stat-value" id="totalMerges">0</div>
      <div>합계 횟수</div>
    </div>
  </div>

  <!-- Click Area -->
  <div class="click-area" id="clickArea" onclick="handleClick(event)">
    <span class="carrot-icon">🥕</span>
    <div class="click-text">클릭하여 당근 수집!</div>
    <div class="click-power">클릭당 +<span id="clickPower">1</span> 🥕</div>
  </div>

  <!-- Farm Area -->
  <div class="farm-area">
    <div class="farm-grid" id="farmGrid"></div>
  </div>

  <!-- Merge Area -->
  <div class="merge-area">
    <h3>🔮 토끼 합치기</h3>
    <div class="merge-grid" id="mergeGrid"></div>
    <div class="merge-info" id="mergeInfo">같은 레벨의 토끼 2마리를 선택하세요!</div>
    <button class="breed-btn" id="breedBtn" onclick="breedRabbit()">🐰 새 토끼 태우기 (💰 <span id="breedCost">50</span>)</button>
  </div>

  <!-- Shop -->
  <div class="shop">
    <div class="shop-tabs">
      <button class="shop-tab active" onclick="switchTab('upgrades')">⬆️ 업그레이드</button>
      <button class="shop-tab" onclick="switchTab('plots')">🏡 Plot</button>
      <button class="shop-tab" onclick="switchTab('items')">🛒 아이템</button>
    </div>

    <div class="tab-content active" id="tab-upgrades">
      <div class="shop-items" id="upgradeItems"></div>
    </div>

    <div class="tab-content" id="tab-plots">
      <div class="shop-items" id="plotItems"></div>
    </div>

    <div class="tab-content" id="tab-items">
      <div class="shop-items" id="itemItems"></div>
    </div>
  </div>
</div>

<script>
// Game State
let game = {
  coins: 0,
  carrots: 0,
  clickPower: 1,
  coinsPerSec: 0,
  totalMerges: 0,
  farmSlots: 8,
  maxFarmSlots: 8,
  rabbits: [],
  mergeSlots: 6,
  upgrades: {
    clickPower: { level: 1, cost: 20, maxLevel: 20, effect: 1 },
    autoCollect: { level: 0, cost: 50, maxLevel: 10, effect: 0 },
    breedSpeed: { level: 0, cost: 100, maxLevel: 5, effect: 0 },
    mergeBonus: { level: 0, cost: 200, maxLevel: 10, effect: 0 },
    farmExpand: { level: 0, cost: 300, maxLevel: 5, effect: 0 }
  },
  lastSave: Date.now()
};

// Rabbit types by level
const rabbitTypes = [
  { emoji: '🐰', name: '작은 토끼', coinsPerSec: 0.1 },
  { emoji: '🐇', name: '어린 토끼', coinsPerSec: 0.3 },
  { emoji: '🐰', name: '성장한 토끼', coinsPerSec: 0.8 },
  { emoji: '🐇', name: '큰 토끼', coinsPerSec: 2 },
  { emoji: '🐰', name: '영리한 토끼', coinsPerSec: 5 },
  { emoji: '🐇', name: '황금 토끼', coinsPerSec: 12 },
  { emoji: '🐰', name: '마법 토끼', coinsPerSec: 30 },
  { emoji: '🐇', name: '전설의 토끼', coinsPerSec: 80 },
  { emoji: '🐰', name: '신화의 토끼', coinsPerSec: 200 },
  { emoji: '🐇', name: '우주의 토끼', coinsPerSec: 500 }
];

let selectedMergeSlot = null;
let currentTab = 'upgrades';

// Initialize
function init() {
  loadGame();
  renderFarm();
  renderMergeGrid();
  renderShop();
  updateUI();
  startGameLoop();
  startAutoSave();
}

// Render Farm Grid
function renderFarm() {
  const grid = document.getElementById('farmGrid');
  grid.innerHTML = '';
  grid.style.gridTemplateColumns = `repeat(${Math.min(game.farmSlots, 4)}, 1fr)`;

  for (let i = 0; i < game.farmSlots; i++) {
    const slot = document.createElement('div');
    slot.className = 'farm-slot' + (game.rabbits[i] ? ' occupied' : '');
    slot.onclick = () => handleFarmClick(i);

    if (game.rabbits[i]) {
      const rabbit = game.rabbits[i];
      const type = rabbitTypes[Math.min(rabbit.level - 1, rabbitTypes.length - 1)];
      slot.innerHTML = `
        <div class="rabbit level-${rabbit.level}">${type.emoji}</div>
        <div class="rabbit-level">Lv.${rabbit.level}</div>
        <div class="rabbit-coins">+${type.coinsPerSec}/초</div>
        <div class="auto-indicator"></div>
      `;
    } else {
      slot.innerHTML = `<span class="slot-empty-text">빈 슬롯</span>`;
    }

    grid.appendChild(slot);
  }
}

// Render Merge Grid
function renderMergeGrid() {
  const grid = document.getElementById('mergeGrid');
  grid.innerHTML = '';

  for (let i = 0; i < game.mergeSlots; i++) {
    const slot = document.createElement('div');
    slot.className = 'merge-slot' + (selectedMergeSlot === i ? ' selected' : '');
    slot.onclick = () => handleMergeClick(i);

    if (game.rabbits[i + game.farmSlots]) {
      const rabbit = game.rabbits[i + game.farmSlots];
      const type = rabbitTypes[Math.min(rabbit.level - 1, rabbitTypes.length - 1)];
      slot.innerHTML = `
        <div class="rabbit">${type.emoji}</div>
        <div class="rabbit-level">Lv.${rabbit.level}</div>
      `;
    } else {
      slot.innerHTML = `<span class="slot-empty-text">합치기 공간</span>`;
    }

    grid.appendChild(slot);
  }
}

// Handle Farm Click
function handleFarmClick(index) {
  if (game.rabbits[index]) {
    // Collect coins from this rabbit
    const rabbit = game.rabbits[index];
    const type = rabbitTypes[Math.min(rabbit.level - 1, rabbitTypes.length - 1)];
    const coins = type.coinsPerSec * 5; // 5 seconds worth
    game.coins += coins;
    showFloatingNumber(`+${coins.toFixed(1)}💰`, event);
    updateUI();
  }
}

// Handle Click
function handleClick(event) {
  game.carrots += game.clickPower;
  game.coins += game.clickPower;
  showFloatingNumber(`+${game.clickPower}🥕`, event);
  updateUI();
}

// Handle Merge Click
function handleMergeClick(index) {
  if (!game.rabbits[index + game.farmSlots]) return;

  if (selectedMergeSlot === null) {
    selectedMergeSlot = index;
    renderMergeGrid();
    document.getElementById('mergeInfo').textContent = `Lv.${game.rabbits[index + game.farmSlots].level} 토끼 선택됨! 다른 같은 레벨 토끼를 선택하세요.`;
  } else if (selectedMergeSlot === index) {
    selectedMergeSlot = null;
    renderMergeGrid();
    document.getElementById('mergeInfo').textContent = '같은 레벨의 토끼 2마리를 선택하세요!';
  } else {
    const rabbit1 = game.rabbits[selectedMergeSlot + game.farmSlots];
    const rabbit2 = game.rabbits[index + game.farmSlots];

    if (rabbit1.level === rabbit2.level && rabbit1.level < 10) {
      // Merge!
      const newLevel = rabbit1.level + 1;
      const bonus = 1 + (game.upgrades.mergeBonus.level * 0.1);

      // Remove both rabbits
      game.rabbits[selectedMergeSlot + game.farmSlots] = null;
      game.rabbits[index + game.farmSlots] = null;

      // Add new rabbit
      game.rabbits[selectedMergeSlot + game.farmSlots] = {
        level: newLevel,
        born: Date.now()
      };

      game.totalMerges++;
      game.coins += newLevel * 10 * bonus;

      showNotification(`🎉 Lv.${newLevel} 토끼 탄생! (+${newLevel * 10 * bonus}💰)`);
      selectedMergeSlot = null;

      renderFarm();
      renderMergeGrid();
      updateUI();
    } else if (rabbit1.level !== rabbit2.level) {
      showNotification('❌ 같은 레벨의 토끼만 합칠 수 있습니다!');
      selectedMergeSlot = null;
      renderMergeGrid();
    } else {
      showNotification('❌ 이미 최고 레벨입니다!');
      selectedMergeSlot = null;
      renderMergeGrid();
    }
  }
}

// Breed Rabbit
function breedRabbit() {
  const cost = Math.floor(50 * Math.pow(1.5, game.rabbits.length));
  if (game.coins < cost) {
    showNotification('❌ 코인이 부족합니다!');
    return;
  }

  if (game.rabbits.length >= game.farmSlots + game.mergeSlots) {
    showNotification('❌ 슬롯이 부족합니다!');
    return;
  }

  game.coins -= cost;
  game.rabbits.push({
    level: 1,
    born: Date.now()
  });

  showNotification('🐰 새 토끼가 태어났습니다!');
  renderFarm();
  renderMergeGrid();
  updateUI();
}

// Render Shop
function renderShop() {
  // Upgrades
  const upgradeItems = document.getElementById('upgradeItems');
  upgradeItems.innerHTML = '';

  const upgradeNames = {
    clickPower: { icon: '👆', name: '클릭력 UP', desc: '클릭당 +1' },
    autoCollect: { icon: '⚡', name: '자동수집', desc: '초당 +0.5💰' },
    breedSpeed: { icon: '🐣', name: '번식속도', desc: '태우기 비용 감소' },
    mergeBonus: { icon: '✨', name: '합치보너스', desc: '합치기 보너스 +10%' },
    farmExpand: { icon: '🏗️', name: '농장확장', desc: '슬롯 +2' }
  };

  for (const [key, upgrade] of Object.entries(game.upgrades)) {
    const info = upgradeNames[key];
    const canAfford = game.coins >= upgrade.cost;
    const maxed = upgrade.level >= upgrade.maxLevel;

    const item = document.createElement('div');
    item.className = 'shop-item' + (!canAfford && !maxed ? ' cant-afford' : '');
    item.innerHTML = `
      <span class="item-icon">${info.icon}</span>
      <div class="item-name">${info.name} (Lv.${upgrade.level})</div>
      <div class="item-cost">${maxed ? 'MAX' : '💰 ' + upgrade.cost}</div>
      <div class="item-desc">${info.desc}</div>
    `;

    if (!maxed) {
      item.onclick = () => buyUpgrade(key);
    }

    upgradeItems.appendChild(item);
  }

  // Plots
  const plotItems = document.getElementById('plotItems');
  plotItems.innerHTML = '';

  const plotCost = Math.floor(100 * Math.pow(2, game.maxFarmSlots - 8));
  const canAffordPlot = game.coins >= plotCost;

  const plotItem = document.createElement('div');
  plotItem.className = 'shop-item' + (!canAffordPlot ? ' cant-afford' : '');
  plotItem.innerHTML = `
    <span class="item-icon">🏡</span>
    <div class="item-name">농장 확장</div>
    <div class="item-cost">💰 ${plotCost}</div>
    <div class="item-desc">슬롯 +4 (현재: ${game.maxFarmSlots})</div>
  `;

  if (canAffordPlot) {
    plotItem.onclick = () => buyPlot();
  }

  plotItems.appendChild(plotItem);

  // Items
  const itemItems = document.getElementById('itemItems');
  itemItems.innerHTML = '';

  const items = [
    { icon: '🥕', name: '당근 묶음', desc: '+10 🥕', cost: 30, action: () => { game.carrots += 10; } },
    { icon: '💰', name: '금화 주머니', desc: '+50 💰', cost: 100, action: () => { game.coins += 50; } },
    { icon: '🌟', name: '행운의 네잎클로버', desc: '클릭력 +1', cost: 200, action: () => { game.clickPower += 1; } },
    { icon: '🎁', name: '행운의 상자', desc: '랜덤 보너스', cost: 500, action: () => {
      const rand = Math.random();
      if (rand < 0.3) { game.coins += 200; showNotification('🎁 200💰 획득!'); }
      else if (rand < 0.6) { game.carrots += 50; showNotification('🎁 50🥕 획득!'); }
      else { game.clickPower += 3; showNotification('🎁 클릭력 +3!'); }
    }}
  ];

  items.forEach(item => {
    const canAfford = game.coins >= item.cost;
    const el = document.createElement('div');
    el.className = 'shop-item' + (!canAfford ? ' cant-afford' : '');
    el.innerHTML = `
      <span class="item-icon">${item.icon}</span>
      <div class="item-name">${item.name}</div>
      <div class="item-cost">💰 ${item.cost}</div>
      <div class="item-desc">${item.desc}</div>
    `;
    if (canAfford) {
      el.onclick = () => {
        game.coins -= item.cost;
        item.action();
        updateUI();
      };
    }
    itemItems.appendChild(el);
  });
}

// Buy Upgrade
function buyUpgrade(key) {
  const upgrade = game.upgrades[key];
  if (game.coins < upgrade.cost || upgrade.level >= upgrade.maxLevel) return;

  game.coins -= upgrade.cost;
  upgrade.level++;
  upgrade.cost = Math.floor(upgrade.cost * 1.8);

  // Apply effects
  switch(key) {
    case 'clickPower':
      game.clickPower += 1;
      break;
    case 'autoCollect':
      game.coinsPerSec += 0.5;
      break;
    case 'mergeBonus':
      break;
    case 'farmExpand':
      game.farmSlots += 2;
      game.maxFarmSlots += 2;
      break;
  }

  showNotification(`⬆️ ${key} 업그레이드! (Lv.${upgrade.level})`);
  renderFarm();
  renderShop();
  updateUI();
}

// Buy Plot
function buyPlot() {
  const cost = Math.floor(100 * Math.pow(2, game.maxFarmSlots - 8));
  if (game.coins < cost) return;

  game.coins -= cost;
  game.maxFarmSlots += 4;
  game.farmSlots += 4;

  showNotification('🏡 농장이 확장되었습니다!');
  renderFarm();
  renderShop();
  updateUI();
}

// Update UI
function updateUI() {
  document.getElementById('carrotCount').textContent = Math.floor(game.carrots);
  document.getElementById('coinCount').textContent = Math.floor(game.coins);
  document.getElementById('clickPower').textContent = game.clickPower;
  document.getElementById('totalRabbits').textContent = game.rabbits.length;
  document.getElementById('totalMerges').textContent = game.totalMerges;

  // Calculate coins per second
  let cps = game.coinsPerSec;
  game.rabbits.forEach(rabbit => {
    const type = rabbitTypes[Math.min(rabbit.level - 1, rabbitTypes.length - 1)];
    cps += type.coinsPerSec;
  });
  game.coinsPerSec = cps;
  document.getElementById('coinsPerSec').textContent = cps.toFixed(1);

  // Breed cost
  const breedCost = Math.floor(50 * Math.pow(1.5, game.rabbits.length));
  document.getElementById('breedCost').textContent = breedCost;

  renderShop();
}

// Show Floating Number
function showFloatingNumber(text, event) {
  const el = document.createElement('div');
  el.className = 'float-number';
  el.textContent = text;
  el.style.left = event.clientX + 'px';
  el.style.top = event.clientY + 'px';
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 1000);
}

// Show Notification
function showNotification(text) {
  const el = document.createElement('div');
  el.className = 'notification';
  el.textContent = text;
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 2000);
}

// Switch Tab
function switchTab(tab) {
  currentTab = tab;
  document.querySelectorAll('.shop-tab').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));

  event.target.classList.add('active');
  document.getElementById('tab-' + tab).classList.add('active');
}

// Game Loop
function startGameLoop() {
  setInterval(() => {
    // Auto collect from rabbits
    game.rabbits.forEach(rabbit => {
      const type = rabbitTypes[Math.min(rabbit.level - 1, rabbitTypes.length - 1)];
      game.coins += type.coinsPerSec;
    });

    // Auto collect upgrade
    if (game.upgrades.autoCollect.level > 0) {
      game.coins += game.upgrades.autoCollect.level * 0.5;
    }

    updateUI();
  }, 1000);
}

// Auto Save
function startAutoSave() {
  setInterval(() => {
    saveGame();
  }, 30000);
}

// Save Game
function saveGame() {
  const saveData = {
    coins: game.coins,
    carrots: game.carrots,
    clickPower: game.clickPower,
    coinsPerSec: game.coinsPerSec,
    totalMerges: game.totalMerges,
    farmSlots: game.farmSlots,
    maxFarmSlots: game.maxFarmSlots,
    rabbits: game.rabbits,
    upgrades: game.upgrades,
    lastSave: Date.now()
  };
  localStorage.setItem('rabbitFarmSave', JSON.stringify(saveData));
}

// Load Game
function loadGame() {
  const saveData = localStorage.getItem('rabbitFarmSave');
  if (saveData) {
    try {
      const data = JSON.parse(saveData);
      game.coins = data.coins || 0;
      game.carrots = data.carrots || 0;
      game.clickPower = data.clickPower || 1;
      game.coinsPerSec = data.coinsPerSec || 0;
      game.totalMerges = data.totalMerges || 0;
      game.farmSlots = data.farmSlots || 8;
      game.maxFarmSlots = data.maxFarmSlots || 8;
      game.rabbits = data.rabbits || [];
      game.upgrades = data.upgrades || game.upgrades;
    } catch(e) {
      console.log('Load failed');
    }
  }
}

// Start game
init();
</script>

</body>
