            flex-direction: column;
            align-items: center;
            justify-content: center;
            font-size: 0.7em;
            cursor: pointer;
            transition: all 0.3s;
            position: relative;
            border: 2px solid transparent;
            min-height: 60px;
        }

        .cell:hover {
            transform: scale(1.1);
            z-index: 10;
            box-shadow: 0 0 15px rgba(255,255,255,0.2);
        }

        .cell.city { background: linear-gradient(135deg, #2c3e50, #34495e); border-color: #7f8c8d; }
        .cell.forest { background: linear-gradient(135deg, #1a472a, #2d5a3f); border-color: #27ae60; }
        .cell.desert { background: linear-gradient(135deg, #8B7355, #A0896C); border-color: #d4a76a; }
        .cell.water { background: linear-gradient(135deg, #1a3a5c, #2c5f8a); border-color: #3498db; }
        .cell.ruins { background: linear-gradient(135deg, #4a3728, #6b5344); border-color: #8b7355; }
        .cell.base { background: linear-gradient(135deg, #1a472a, #2d8a4f); border-color: #00ff88; }
        .cell.danger { background: linear-gradient(135deg, #4a1a1a, #8a2d2d); border-color: #e94560; }

        .cell .cell-icon {
            font-size: 1.5em;
            margin-bottom: 2px;
        }

        .cell .cell-label {
            font-size: 0.6em;
            opacity: 0.8;
            text-align: center;
        }

        .cell .players-on-cell {
            position: absolute;
            bottom: 2px;
            right: 2px;
            display: flex;
            gap: 2px;
        }

        .cell .player-dot {
            width: 14px;
            height: 14px;
            border-radius: 50%;
            border: 2px solid white;
            font-size: 0.5em;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .cell.highlight {
            animation: pulse 1s infinite;
            border-color: #00ff88 !important;
        }

        @keyframes pulse {
            0%, 100% { box-shadow: 0 0 5px rgba(0,255,136,0.5); }
            50% { box-shadow: 0 0 20px rgba(0,255,136,0.8); }
        }

        /* Right Panel */
        .right-panel {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .panel-section {
            background: #16213e;
            border-radius: 10px;
            padding: 15px;
            border: 2px solid #0f3460;
        }

        .panel-section h3 {
            font-family: 'Press Start 2P', cursive;
            font-size: 0.6em;
            color: #e94560;
            margin-bottom: 10px;
            text-align: center;
        }

        /* Dice */
        .dice-container {
            text-align: center;
        }

        .dice {
            width: 80px;
            height: 80px;
            background: linear-gradient(135deg, #fff, #e0e0e0);
            border-radius: 15px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-size: 2em;
            font-weight: bold;
            color: #1a1a2e;
            cursor: pointer;
            transition: all 0.3s;
            box-shadow: 0 5px 15px rgba(0,0,0,0.3);
            margin: 10px;
            user-select: none;
        }

        .dice:hover {
            transform: scale(1.1);
            box-shadow: 0 8px 25px rgba(0,0,0,0.4);
        }

        .dice.rolling {
            animation: roll 0.5s ease-in-out;
        }

        @keyframes roll {
            0% { transform: rotate(0deg) scale(1); }
            25% { transform: rotate(90deg) scale(0.8); }
            50% { transform: rotate(180deg) scale(1.1); }
            75% { transform: rotate(270deg) scale(0.9); }
            100% { transform: rotate(360deg) scale(1); }
        }

        .btn {
            background: linear-gradient(135deg, #e94560, #c0392b);
            color: white;
            border: none;
            padding: 10px 20px;
            border-radius: 8px;
            cursor: pointer;
            font-family: 'Roboto', sans-serif;
            font-weight: bold;
            font-size: 0.9em;
            transition: all 0.3s;
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(233,69,96,0.4);
        }

        .btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
            transform: none;
        }

        .btn-green {
            background: linear-gradient(135deg, #27ae60, #2ecc71);
        }

        .btn-green:hover {
            box-shadow: 0 5px 15px rgba(46,204,113,0.4);
        }

        .btn-blue {
            background: linear-gradient(135deg, #2980b9, #3498db);
        }

        .btn-blue:hover {
            box-shadow: 0 5px 15px rgba(52,152,219,0.4);
        }

        .btn-small {
            padding: 5px 10px;
            font-size: 0.8em;
        }

        /* Event Log */
        .event-log {
            max-height: 300px;
            overflow-y: auto;
            font-size: 0.8em;
        }

        .event-log::-webkit-scrollbar {
            width: 6px;
        }

        .event-log::-webkit-scrollbar-track {
            background: #0f3460;
            border-radius: 3px;
        }

        .event-log::-webkit-scrollbar-thumb {
            background: #e94560;
            border-radius: 3px;
        }

        .log-entry {
            padding: 8px;
            margin-bottom: 5px;
            border-radius: 5px;
            background: #0f3460;
            border-left: 3px solid #e94560;
            animation: slideIn 0.3s ease-out;
        }

        .log-entry.event { border-left-color: #f39c12; }
        .log-entry.danger { border-left-color: #e94560; }
        .log-entry.good { border-left-color: #27ae60; }
        .log-entry.info { border-left-color: #3498db; }

        @keyframes slideIn {
            from { opacity: 0; transform: translateX(-20px); }
            to { opacity: 1; transform: translateX(0); }
        }

        /* Modal */
        .modal-overlay {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.7);
            z-index: 1000;
            align-items: center;
            justify-content: center;
        }

        .modal-overlay.active {
            display: flex;
        }

        .modal {
            background: #16213e;
            border-radius: 15px;
            padding: 30px;
            max-width: 500px;
            width: 90%;
            border: 2px solid #e94560;
            text-align: center;
            animation: modalIn 0.3s ease-out;
        }

        @keyframes modalIn {
            from { transform: scale(0.8); opacity: 0; }
            to { transform: scale(1); opacity: 1; }
        }

        .modal h2 {
            font-family: 'Press Start 2P', cursive;
            font-size: 1em;
            color: #e94560;
            margin-bottom: 15px;
        }

        .modal p {
            margin-bottom: 20px;
            line-height: 1.6;
        }

        .modal .choices {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .modal .choice-btn {
            background: #0f3460;
            color: white;
            border: 2px solid #3498db;
            padding: 12px;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.3s;
            font-size: 0.9em;
        }

        .modal .choice-btn:hover {
            background: #3498db;
            transform: translateX(5px);
        }

        /* Turn Indicator */
        .turn-indicator {
            text-align: center;
            padding: 10px;
            background: #0f3460;
            border-radius: 8px;
            margin-bottom: 15px;
        }

        .turn-indicator .turn-number {
            font-family: 'Press Start 2P', cursive;
            font-size: 0.8em;
            color: #00ff88;
        }

        .turn-indicator .current-player {
            font-size: 1em;
            margin-top: 5px;
            color: #e94560;
            font-weight: bold;
        }

        /* Inventory */
        .inventory {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 8px;
        }

        .inv-item {
            background: #0f3460;
            padding: 8px;
            border-radius: 6px;
            text-align: center;
            font-size: 0.8em;
        }

        .inv-item .inv-icon {
            font-size: 1.5em;
            display: block;
            margin-bottom: 3px;
        }

        .inv-item .inv-count {
            font-weight: bold;
            color: #00ff88;
        }

        /* Setup Screen */
        .setup-screen {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 80vh;
            text-align: center;
        }

        .setup-screen h1 {
            font-family: 'Press Start 2P', cursive;
            font-size: 2.5em;
            color: #e94560;
            margin-bottom: 20px;
            text-shadow: 3px 3px 6px rgba(0,0,0,0.5);
        }

        .setup-screen .subtitle {
            color: #a0a0a0;
            margin-bottom: 40px;
            font-size: 1.1em;
        }

        .player-setup {
            background: #16213e;
            border-radius: 15px;
            padding: 30px;
            max-width: 600px;
            width: 90%;
            border: 2px solid #0f3460;
        }

        .player-setup h2 {
            font-family: 'Press Start 2P', cursive;
            font-size: 0.8em;
            color: #e94560;
            margin-bottom: 20px;
        }

        .setup-input {
            display: flex;
            align-items: center;
            gap: 10px;
            margin-bottom: 15px;
        }

        .setup-input input {
            flex: 1;
            padding: 10px;
            border-radius: 8px;
            border: 2px solid #0f3460;
            background: #0f3460;
            color: white;
            font-size: 1em;
        }

        .setup-input input:focus {
            outline: none;
            border-color: #e94560;
        }

        .avatar-select {
            display: flex;
            gap: 10px;
            justify-content: center;
            margin: 20px 0;
        }

        .avatar-option {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.5em;
            cursor: pointer;
            border: 3px solid transparent;
            transition: all 0.3s;
            background: #0f3460;
        }

        .avatar-option:hover {
            transform: scale(1.1);
        }

        .avatar-option.selected {
            border-color: #e94560;
            box-shadow: 0 0 15px rgba(233,69,96,0.5);
        }

        .game-over-screen {
            display: none;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 80vh;
            text-align: center;
        }

        .game-over-screen h1 {
            font-family: 'Press Start 2P', cursive;
            font-size: 2em;
            color: #e94560;
            margin-bottom: 20px;
        }

        .winner-display {
            font-size: 1.5em;
            color: #00ff88;
            margin-bottom: 30px;
        }

        /* Responsive */
        @media (max-width: 1200px) {
            .main-layout {
                grid-template-columns: 1fr;
            }
            .board {
                max-width: 500px;
            }
        }

        @media (max-width: 600px) {
            .board {
                max-width: 350px;
                gap: 2px;
            }
            .cell {
                min-height: 40px;
                font-size: 0.5em;
            }
            .cell .cell-icon {
                font-size: 1.2em;
            }
            header h1 {
                font-size: 1.2em;
            }
        }

        .tooltip {
            position: absolute;
            bottom: 100%;
            left: 50%;
            transform: translateX(-50%);
            background: #1a1a2e;
            color: white;
            padding: 5px 10px;
            border-radius: 5px;
            font-size: 0.7em;
            white-space: nowrap;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.3s;
            z-index: 100;
        }

        .cell:hover .tooltip {
            opacity: 1;
        }

        .action-buttons {
            display: flex;
            gap: 10px;
            justify-content: center;
            flex-wrap: wrap;
            margin-top: 10px;
        }

        .round-info {
            display: flex;
            justify-content: space-around;
            margin-top: 10px;
            font-size: 0.8em;
        }

        .round-info div {
            text-align: center;
        }

        .round-info .label {
            color: #a0a0a0;
            font-size: 0.8em;
        }

        .round-info .value {
            color: #00ff88;
            font-weight: bold;
            font-size: 1.2em;
        }

        .notification {
            position: fixed;
            top: 20px;
            right: 20px;
            background: #16213e;
            border: 2px solid #e94560;
            border-radius: 10px;
            padding: 15px 20px;
            z-index: 2000;
            animation: notifIn 0.3s ease-out, notifOut 0.3s ease-in 2.7s;
            max-width: 300px;
        }

        @keyframes notifIn {
            from { transform: translateX(100%); opacity: 0; }
            to { transform: translateX(0); opacity: 1; }
        }

        @keyframes notifOut {
            from { opacity: 1; }
            to { opacity: 0; }
        }

        .notification .notif-title {
            font-weight: bold;
            color: #e94560;
            margin-bottom: 5px;
        }

        .notification .notif-text {
            font-size: 0.85em;
            color: #a0a0a0;
        }
    </style>
</head>
<body>

<!-- Setup Screen -->
<div id="setupScreen" class="setup-screen">
    <h1>🧟 LE SURVIVANT</h1>
    <p class="subtitle">Un jeu de plateau de survie post-apocalyptique</p>
    <div class="player-setup">
        <h2>👥 Configuration des Joueurs</h2>
        <div id="setupPlayers">
            <div class="setup-input">
                <input type="text" id="player1Name" placeholder="Nom du Joueur 1" value="Survivant 1">
                <div class="avatar-select" data-player="0">
                    <div class="avatar-option selected" data-avatar="🧑">🧑</div>
                    <div class="avatar-option" data-avatar="👩">👩</div>
                    <div class="avatar-option" data-avatar="🧔">🧔</div>
                    <div class="avatar-option" data-avatar="👨‍🦳">👨‍🦳</div>
                </div>
            </div>
            <div class="setup-input">
                <input type="text" id="player2Name" placeholder="Nom du Joueur 2" value="Survivant 2">
                <div class="avatar-select" data-player="1">
                    <div class="avatar-option" data-avatar="🧑">🧑</div>
                    <div class="avatar-option selected" data-avatar="👩">👩</div>
                    <div class="avatar-option" data-avatar="🧔">🧔</div>
                    <div class="avatar-option" data-avatar="👨‍🦳">👨‍🦳</div>
                </div>
            </div>
        </div>
        <div style="margin-top: 20px;">
            <button class="btn btn-green" onclick="addPlayerField()">➕ Ajouter un joueur</button>
        </div>
        <div style="margin-top: 20px;">
            <button class="btn" onclick="startGame()">🎮 Commencer la Partie</button>
        </div>
    </div>
</div>

<!-- Game Screen -->
<div id="gameScreen" style="display:none;">
    <div class="game-container">
        <header>
            <h1>🧟 LE SURVIVANT</h1>
            <p>Survivez le plus longtemps possible dans un monde post-apocalyptique</p>
        </header>

        <div class="main-layout">
            <!-- Left Panel - Players -->
            <div class="player-panel">
                <h2>👥 JOUEURS</h2>
                <div id="playerCards"></div>
            </div>

            <!-- Center - Board -->
            <div class="board-container">
                <div class="turn-indicator">
                    <div class="turn-number">TOUR <span id="turnNumber">1</span></div>
                    <div class="current-player" id="currentPlayerName">Tour de Survivant 1</div>
                </div>
                <div class="board" id="board"></div>
                <div class="action-buttons">
                    <button class="btn" id="rollBtn" onclick="rollDice()">🎲 Lancer le Dé</button>
                    <button class="btn btn-green" id="moveBtn" onclick="movePlayer()" disabled>🚶 Bouger</button>
                    <button class="btn btn-blue" id="actionBtn" onclick="playerAction()" disabled>⚡ Action</button>
                    <button class="btn" id="endTurnBtn" onclick="endTurn()" disabled>⏭️ Fin du Tour</button>
                </div>
                <div class="round-info">
                    <div>
                        <div class="label">Jours restants</div>
                        <div class="value" id="daysLeft">30</div>
                    </div>
                    <div>
                        <div class="label">Événements</div>
                        <div class="value" id="eventCount">0</div>
                    </div>
                    <div>
                        <div class="label">Survivants</div>
                        <div class="value" id="survivorsCount">0</div>
                    </div>
                </div>
            </div>

            <!-- Right Panel -->
            <div class="right-panel">
                <div class="panel-section dice-container">
                    <h3>🎲 DÉ</h3>
                    <div class="dice" id="dice" onclick="rollDice()">?</div>
                    <p style="font-size:0.8em; color:#a0a0a0; margin-top:10px;">Cliquez ou utilisez le bouton pour lancer</p>
                </div>

                <div class="panel-section">
                    <h3>🎒 INVENTAIRE</h3>
                    <div class="inventory" id="inventory"></div>
                </div>

                <div class="panel-section">
                    <h3>📜 JOURNAL</h3>
                    <div class="event-log" id="eventLog"></div>
                </div>

                <div class="panel-section">
                    <h3>📊 LÉGENDE</h3>
                    <div style="font-size:0.8em; display:grid; grid-template-columns:1fr 1fr; gap:5px;">
                        <div>🏙️ Ville</div>
                        <div>🌲 Forêt</div>
                        <div>🏜️ Désert</div>
                        <div>🌊 Eau</div>
                        <div>🏚️ Ruines</div>
                        <div>🏠 Base</div>
                        <div>💀 Danger</div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

<!-- Game Over Screen -->
<div id="gameOverScreen" class="game-over-screen">
    <h1>💀 PARTIE TERMINÉE</h1>
    <div class="winner-display" id="winnerDisplay"></div>
    <p id="gameOverStats" style="margin-bottom:30px; color:#a0a0a0;"></p>
    <button class="btn btn-green" onclick="location.reload()">🔄 Nouvelle Partie</button>
</div>

<!-- Event Modal -->
<div class="modal-overlay" id="eventModal">
    <div class="modal">
        <h2 id="modalTitle">🎲 Événement</h2>
        <p id="modalText">Un événement surprend les survivants...</p>
        <div class="choices" id="modalChoices"></div>
    </div>
</div>

<script>
// ==================== GAME STATE ====================
const GAME_STATE = {
    players: [],
    currentPlayerIndex: 0,
    turn: 1,
    daysLeft: 30,
    totalEvents: 0,
    board: [],
    diceValue: 0,
    phase: 'roll', // roll, move, action, end
    gameOver: false,
    selectedAvatar: ['🧑', '👩']
};

// ==================== BOARD DEFINITION ====================
const BOARD_TYPES = {
    BASE: 'base',
    CITY: 'city',
    FOREST: 'forest',
    DESERT: 'desert',
    WATER: 'water',
    RUINS: 'ruins',
    DANGER: 'danger'
};

const BOARD_ICONS = {
    base: '🏠',
    city: '🏙️',
    forest: '🌲',
    desert: '🏜️',
    water: '🌊',
    ruins: '🏚️',
    danger: '💀'
};

const BOARD_LABELS = {
    base: 'Base',
    city: 'Ville',
    forest: 'Forêt',
    desert: 'Désert',
    water: 'Eau',
    ruins: 'Ruines',
    danger: 'Danger'
};

// 10x10 board layout
const BOARD_LAYOUT = [
    ['base', 'city', 'forest', 'ruins', 'danger', 'danger', 'city', 'forest', 'city', 'base'],
    ['city', 'forest', 'desert', 'water', 'city', 'ruins', 'forest', 'desert', 'forest', 'city'],
    ['forest', 'desert', 'city', 'forest', 'danger', 'city', 'desert', 'water', 'desert', 'forest'],
    ['ruins', 'city', 'forest', 'danger', 'city', 'forest', 'city', 'forest', 'city', 'ruins'],
    ['danger', 'ruins', 'city', 'forest', 'water', 'forest', 'city', 'ruins', 'danger', 'danger'],
    ['danger', 'city', 'forest', 'water', 'city', 'water', 'forest', 'city', 'city', 'city'],
    ['city', 'forest', 'ruins', 'city', 'forest', 'city', 'ruins', 'forest', 'ruins', 'forest'],
    ['forest', 'city', 'desert', 'forest', 'city', 'forest', 'desert', 'city', 'forest', 'city'],
    ['city', 'ruins', 'water', 'city', 'ruins', 'city', 'water', 'ruins', 'city', 'ruins'],
    ['base', 'city', 'forest', 'city', 'city', 'city', 'forest', 'city', 'city', 'base']
];

// ==================== EVENTS ====================
const EVENTS = [
    {
        title: "🧟 Attaque de zombies!",
        text: "Un groupe de zombies attaque votre position!",
        choices: [
            { text: "🗡️ Combattre (risqué)", effect: (p) => { const dmg = Math.random() > 0.5 ? 10 : 0; p.health -= dmg; return dmg > 0 ? `Vous prenez ${dmg} dégâts!` : "Vous avez vaincu les zombies!"; }},
            { text: "🏃 Fuir", effect: (p) => { p.health -= 5; return "Vous fuyez mais perdez 5 PV."; }},
            { text: "🛡️ Se cacher", effect: (p) => { return "Vous restez caché et survivez."; }}
        ]
    },
    {
        title: "📦 Caisse de fournitures!",
        text: "Vous trouvez une caisse abandonnée!",
        choices: [
            { text: "🍖 Prendre de la nourriture", effect: (p) => { p.food += 3; return "+3 Nourriture!"; }},
            { text: "💧 Prendre de l'eau", effect: (p) => { p.water += 3; return "+3 Eau!"; }},
            { text: "💊 Prendre des médicaments", effect: (p) => { p.medicine += 2; return "+2 Médicaments!"; }}
        ]
    },
    {
        title: "🌪️ Tempête!",
        text: "Une tempête violente se déclenche!",
        choices: [
            { text: "🏠 Chercher abri", effect: (p) => { p.health -= 5; return "Abri précaire, -5 PV."; }},
            { text: "🌳 Se cacher sous un arbre", effect: (p) => { const dmg = Math.random() > 0.6 ? 15 : 0; p.health -= dmg; return dmg > 0 ? `Un arbre tombe sur vous! -${dmg} PV` : "Vous vous en sortez indemne!"; }},
            { text: "🏃 Courir vers l'abri", effect: (p) => { const dmg = Math.random() > 0.4 ? 10 : 0; p.health -= dmg; return dmg > 0 ? `Blessé pendant la course! -${dmg} PV` : "Vous atteignez l'abri sain et sauf!"; }}
        ]
    },
    {
        title: "🏚️ Ruines explorées!",
