// ==================== INITIALIZATION ====================
function addPlayerField() {
    const container = document.getElementById('setupPlayers');
    const count = container.children.length + 1;
    if (count > 4) {
        showNotification("⚠️ Maximum 4 joueurs!", "Impossible d'ajouter plus de joueurs.");
        return;
    }

    const avatars = ['🧑', '👩', '🧔', '👨‍🦳', '👩‍🦰', '🧑‍🦲', '👨‍🦱', '🧑‍🦳'];
    const avatar = avatars[count % avatars.length];

    const div = document.createElement('div');
    div.className = 'setup-input';
    div.innerHTML = `
        <input type="text" id="player${count}Name" placeholder="Nom du Joueur ${count}" value="Survivant ${count}">
        <div class="avatar-select" data-player="${count-1}">
            ${avatars.map(a => `<div class="avatar-option ${a === avatar ? 'selected' : ''}" data-avatar="${a}">${a}</div>`).join('')}
        </div>
    `;
    container.appendChild(div);

    // Add click handlers for new avatar options
    div.querySelectorAll('.avatar-option').forEach(opt => {
        opt.addEventListener('click', function() {
            div.querySelectorAll('.avatar-option').forEach(o => o.classList.remove('selected'));
            this.classList.add('selected');
        });
    });
}

// Setup avatar selection
document.querySelectorAll('.avatar-option').forEach(opt => {
    opt.addEventListener('click', function() {
        const parent = this.closest('.avatar-select');
        parent.querySelectorAll('.avatar-option').forEach(o => o.classList.remove('selected'));
        this.classList.add('selected');
    });
});

function startGame() {
    const setupInputs = document.querySelectorAll('#setupPlayers .setup-input');
    GAME_STATE.players = [];

    setupInputs.forEach((input, index) => {
        const name = input.querySelector('input').value || `Survivant ${index + 1}`;
        const avatar = input.querySelector('.avatar-option.selected')?.dataset.avatar || '🧑';
        GAME_STATE.players.push({
            name: name,
            avatar: avatar,
            health: 100,
            maxHealth: 100,
            food: 5,
            water: 5,
            medicine: 2,
            position: { row: index < 2 ? 0 : 9, col: index < 2 ? index * 3 : 9 - index * 3 },
            alive: true,
            color: ['#e94560', '#3498db', '#27ae60', '#f39c12'][index % 4]
        });
    });

    if (GAME_STATE.players.length === 0) {
        showNotification("⚠️ Erreur!", "Ajoutez au moins un joueur.");
        return;
    }

    document.getElementById('setupScreen').style.display = 'none';
    document.getElementById('gameScreen').style.display = 'block';

    initBoard();
    renderBoard();
    renderPlayers();
    updateUI();
    addLog("🎮 La partie commence! Survivez le plus longtemps possible!", "info");
    addLog(`📅 Jour 1 - ${GAME_STATE.players[0].name} commence.`, "info");
}

// ==================== BOARD ====================
function initBoard() {
    GAME_STATE.board = [];
    for (let row = 0; row < 10; row++) {
        GAME_STATE.board[row] = [];
        for (let col = 0; col < 10; col++) {
            GAME_STATE.board[row][col] = {
                type: BOARD_LAYOUT[row][col],
                resources: generateResources(BOARD_LAYOUT[row][col])
            };
        }
    }
}

function generateResources(type) {
    const resources = { food: 0, water: 0, medicine: 0 };
    switch(type) {
        case 'city':
            resources.food = Math.floor(Math.random() * 3) + 1;
            resources.water = Math.floor(Math.random() * 2);
            break;
        case 'forest':
            resources.food = Math.floor(Math.random() * 4) + 1;
            resources.water = Math.floor(Math.random() * 2);
            break;
        case 'desert':
            resources.water = Math.floor(Math.random() * 2);
            break;
        case 'water':
            resources.water = Math.floor(Math.random() * 5) + 2;
            break;
        case 'ruins':
            resources.medicine = Math.floor(Math.random() * 3);
            resources.food = Math.floor(Math.random() * 2);
            break;
        case 'base':
            resources.food = 3;
            resources.water = 3;
            resources.medicine = 2;
            break;
        case 'danger':
            // No resources, just danger
            break;
    }
    return resources;
}

function renderBoard() {
    const boardEl = document.getElementById('board');
    boardEl.innerHTML = '';

    for (let row = 0; row < 10; row++) {
        for (let col = 0; col < 10; col++) {
            const cell = document.createElement('div');
            cell.className = `cell ${GAME_STATE.board[row][col].type}`;
            cell.dataset.row = row;
            cell.dataset.col = col;

            const type = GAME_STATE.board[row][col].type;
            cell.innerHTML = `
                <div class="cell-icon">${BOARD_ICONS[type]}</div>
                <div class="cell-label">${BOARD_LABELS[type]}</div>
                <div class="players-on-cell" id="players-${row}-${col}"></div>
            `;

            cell.addEventListener('click', () => cellClicked(row, col));
            boardEl.appendChild(cell);
        }
    }

    updatePlayerPositions();
}

function updatePlayerPositions() {
    // Clear all player dots
    document.querySelectorAll('.players-on-cell').forEach(el => el.innerHTML = '');

    // Add player dots to their cells
    GAME_STATE.players.forEach((player, index) => {
        if (player.alive) {
            const cell = document.getElementById(`players-${player.position.row}-${player.position.col}`);
            if (cell) {
                const dot = document.createElement('div');
                dot.className = 'player-dot';
                dot.style.background = player.color;
                dot.textContent = player.avatar;
                dot.title = player.name;
                cell.appendChild(dot);
            }
        }
    });
}

function cellClicked(row, col) {
    if (GAME_STATE.phase !== 'move') return;

    const player = GAME_STATE.players[GAME_STATE.currentPlayerIndex];
    const currentRow = player.position.row;
    const currentCol = player.position.col;

    const rowDiff = Math.abs(row - currentRow);
    const colDiff = Math.abs(col - currentCol);

    // Check if adjacent (including diagonals)
    if (rowDiff <= 1 && colDiff <= 1 && (rowDiff + colDiff > 0)) {
        if (GAME_STATE.diceValue >= rowDiff + colDiff) {
            player.position = { row, col };
            GAME_STATE.phase = 'action';
            updatePlayerPositions();
            updateUI();
            handleCellArrival(row, col);
        }
    }
}

function handleCellArrival(row, col) {
    const cell = GAME_STATE.board[row][col];
    const player = GAME_STATE.players[GAME_STATE.currentPlayerIndex];

    // Collect resources
    if (cell.resources.food > 0) {
        player.food += cell.resources.food;
        addLog(`🍖 +${cell.resources.food} nourriture trouvée!`, "good");
        cell.resources.food = 0;
    }
    if (cell.resources.water > 0) {
        player.water += cell.resources.water;
        addLog(`💧 +${cell.resources.water} eau trouvée!`, "good");
        cell.resources.water = 0;
    }
    if (cell.resources.medicine > 0) {
        player.medicine += cell.resources.medicine;
        addLog(`💊 +${cell.resources.medicine} médicaments trouvés!`, "good");
        cell.resources.medicine = 0;
    }

    // Danger cell event
    if (cell.type === 'danger') {
        if (Math.random() > 0.5) {
            triggerRandomEvent();
        } else {
            addLog("💀 Zone dangereuse mais vous avez échappé au péril!", "danger");
        }
    }

    // Forest event
    if (cell.type === 'forest' && Math.random() > 0.7) {
        triggerRandomEvent();
    }

    // Desert event
    if (cell.type === 'desert') {
        player.water -= 1;
        addLog("🏜️ La chaleur vous déshydrate! -1 eau", "danger");
    }

    updateUI();
}

// ==================== DICE ====================
function rollDice() {
    if (GAME_STATE.phase !== 'roll' || GAME_STATE.gameOver) return;

    const diceEl = document.getElementById('dice');
    diceEl.classList.add('rolling');

    let rolls = 0;
    const interval = setInterval(() => {
        diceEl.textContent = Math.floor(Math.random() * 6) + 1;
        rolls++;
        if (rolls >= 10) {
            clearInterval(interval);
            GAME_STATE.diceValue = Math.floor(Math.random() * 6) + 1;
            diceEl.textContent = GAME_STATE.diceValue;
            diceEl.classList.remove('rolling');
            GAME_STATE.phase = 'move';
            addLog(`🎲 ${GAME_STATE.players[GAME_STATE.currentPlayerIndex].name} lance un ${GAME_STATE.diceValue}`, "info");
            updateUI();
        }
    }, 50);
}

// ==================== MOVEMENT ====================
function movePlayer() {
    if (GAME_STATE.phase !== 'move') return;
    // Movement is handled by clicking on adjacent cells
    showNotification("📍 Déplacement", "Cliquez sur une case adjacente pour vous déplacer!");
}

function playerAction() {
    if (GAME_STATE.phase !== 'action') return;

    const player = GAME_STATE.players[GAME_STATE.currentPlayerIndex];
    const cell = GAME_STATE.board[player.position.row][player.position.col];

    // Use medicine to heal
    if (player.medicine > 0 && player.health < 100) {
        player.health = Math.min(100, player.health + 15);
        player.medicine--;
        addLog(`💊 ${player.name} utilise un médicament! +15 PV`, "good");
    }

    // Eat food
    if (player.food > 0) {
        player.food--;
        player.health = Math.min(100, player.health + 5);
        addLog(`🍖 ${player.name} mange! +5 PV`, "good");
    }

    // Drink water
    if (player.water > 0) {
        player.water--;
        player.health = Math.min(100, player.health + 3);
        addLog(`💧 ${player.name} boit! +3 PV`, "good");
    }

    GAME_STATE.phase = 'end';
    updateUI();
}

// ==================== TURN MANAGEMENT ====================
function endTurn() {
    if (GAME_STATE.phase !== 'end') return;

    const player = GAME_STATE.players[GAME_STATE.currentPlayerIndex];

    // Daily resource consumption
    player.food -= 1;
    player.water -= 1;
    addLog(`📉 ${player.name} consomme 1 nourriture et 1 eau`, "info");

    // Check survival
    if (player.food < 0 || player.water < 0) {
        player.health -= 10;
        addLog(`💀 ${player.name} meurt de faim/de soif! -10 PV`, "danger");
        player.food = Math.max(0, player.food);
        player.water = Math.max(0, player.water);
    }

    if (player.health <= 0) {
        player.alive = false;
        addLog(`💀 ${player.name} est décédé!`, "danger");
        showNotification("💀 Décès!", `${player.name} ne survit pas.`);
    }

    // Check game over
    const alivePlayers = GAME_STATE.players.filter(p => p.alive);
    if (alivePlayers.length === 0) {
        endGame();
        return;
    }

    if (alivePlayers.length === 1 && GAME_STATE.turn > 3) {
        endGame();
        return;
    }

    // Next player
    GAME_STATE.currentPlayerIndex = (GAME_STATE.currentPlayerIndex + 1) % GAME_STATE.players.length;

    // Check if we completed a full round
    if (GAME_STATE.currentPlayerIndex === 0) {
        GAME_STATE.turn++;
        GAME_STATE.daysLeft--;
        addLog(`📅 Jour ${GAME_STATE.turn} commence!`, "info");

        if (GAME_STATE.daysLeft <= 0) {
            endGame();
            return;
        }

        // Random event at start of new day
        if (Math.random() > 0.5) {
            triggerRandomEvent();
        }
    }

    // Reset phase for new player
    GAME_STATE.phase = 'roll';
    GAME_STATE.diceValue = 0;
    document.getElementById('dice').textContent = '?';

    updateUI();
}

// ==================== EVENTS ====================
function triggerRandomEvent() {
    const event = EVENTS[Math.floor(Math.random() * EVENTS.length)];
    GAME_STATE.totalEvents++;

    document.getElementById('modalTitle').textContent = event.title;
    document.getElementById('modalText').textContent = event.text;

    const choicesEl = document.getElementById('modalChoices');
    choicesEl.innerHTML = '';

    event.choices.forEach(choice => {
        const btn = document.createElement('button');
        btn.className = 'choice-btn';
        btn.textContent = choice.text;
        btn.addEventListener('click', () => {
            const player = GAME_STATE.players[GAME_STATE.currentPlayerIndex];
            const result = choice.effect(player);
            addLog(`${event.title} ${result}`, "event");
            document.getElementById('eventModal').classList.remove('active');
            updateUI();

            if (player.health <= 0) {
                player.alive = false;
                addLog(`💀 ${player.name} est décédé!`, "danger");
            }
        });
        choicesEl.appendChild(btn);
    });

    document.getElementById('eventModal').classList.add('active');
}

// ==================== UI UPDATES ====================
function updateUI() {
    // Turn info
    document.getElementById('turnNumber').textContent = GAME_STATE.turn;
    document.getElementById('currentPlayerName').textContent = `Tour de ${GAME_STATE.players[GAME_STATE.currentPlayerIndex].name}`;
    document.getElementById('daysLeft').textContent = GAME_STATE.daysLeft;
    document.getElementById('eventCount').textContent = GAME_STATE.totalEvents;
    document.getElementById('survivorsCount').textContent = GAME_STATE.players.filter(p => p.alive).length;

    // Buttons
    document.getElementById('rollBtn').disabled = GAME_STATE.phase !== 'roll';
    document.getElementById('moveBtn').disabled = GAME_STATE.phase !== 'move';
    document.getElementById('actionBtn').disabled = GAME_STATE.phase !== 'action';
    document.getElementById('endTurnBtn').disabled = GAME_STATE.phase !== 'end';

    // Player cards
    renderPlayers();

    // Inventory
    renderInventory();
}

function renderPlayers() {
    const container = document.getElementById('playerCards');
    container.innerHTML = '';

    GAME_STATE.players.forEach((player, index) => {
        const card = document.createElement('div');
        card.className = `player-card ${index === GAME_STATE.currentPlayerIndex ? 'active' : ''} ${!player.alive ? 'dead' : ''}`;
        if (!player.alive) {
            card.style.opacity = '0.5';
            card.style.borderLeftColor = '#666';
        }

        card.innerHTML = `
            <div class="name">
                <span class="avatar" style="background:${player.color}">${player.avatar}</span>
                ${player.name} ${!player.alive ? '💀' : ''}
            </div>
            <div class="stats">
                <div class="stat">
                    <span class="stat-icon">❤️</span>
                    <span>${player.health}/100</span>
                </div>
                <div class="stat-bar"><div class="stat-fill health-fill" style="width:${player.health}%"></div></div>
                <div class="stat">
                    <span class="stat-icon">🍖</span>
                    <span>${player.food}</span>
                </div>
                <div class="stat">
                    <span class="stat-icon">💧</span>
                    <span>${player.water}</span>
                </div>
                <div class="stat">
                    <span class="stat-icon">💊</span>
                    <span>${player.medicine}</span>
                </div>
            </div>
        `;

        container.appendChild(card);
    });
}

function renderInventory() {
    const container = document.getElementById('inventory');
    const player = GAME_STATE.players[GAME_STATE.currentPlayerIndex];

    container.innerHTML = `
        <div class="inv-item">
            <span class="inv-icon">🍖</span>
            <span class="inv-count">${player.food}</span>
            <div>Nourriture</div>
        </div>
        <div class="inv-item">
            <span class="inv-icon">💧</span>
            <span class="inv-count">${player.water}</span>
            <div>Eau</div>
        </div>
        <div class="inv-item">
            <span class="inv-icon">💊</span>
            <span class="inv-count">${player.medicine}</span>
            <div>Médicaments</div>
        </div>
        <div class="inv-item">
            <span class="inv-icon">❤️</span>
            <span class="inv-count">${player.health}</span>
            <div>PV</div>
        </div>
    `;
}

function addLog(message, type = 'info') {
    const log = document.getElementById('eventLog');
    const entry = document.createElement('div');
    entry.className = `log-entry ${type}`;
    entry.textContent = message;
    log.insertBefore(entry, log.firstChild);

    // Keep only last 50 entries
    while (log.children.length > 50) {
        log.removeChild(log.lastChild);
    }
}

function showNotification(title, text) {
    const notif = document.createElement('div');
    notif.className = 'notification';
    notif.innerHTML = `
        <div class="notif-title">${title}</div>
        <div class="notif-text">${text}</div>
    `;
    document.body.appendChild(notif);
    setTimeout(() => notif.remove(), 3000);
}

// ==================== GAME OVER ====================
function endGame() {
    GAME_STATE.gameOver = true;
    document.getElementById('gameScreen').style.display = 'none';
    document.getElementById('gameOverScreen').style.display = 'flex';

    const alivePlayers = GAME_STATE.players.filter(p => p.alive);
    const winnerDisplay = document.getElementById('winnerDisplay');
    const statsDisplay = document.getElementById('gameOverStats');

    if (alivePlayers.length === 1) {
        winnerDisplay.textContent = `🏆 ${alivePlayers[0].name} est le dernier survivant!`;
    } else if (alivePlayers.length === 0) {
        winnerDisplay.textContent = "💀 Tous les survivants sont morts!";
    } else {
        winnerDisplay.textContent = `🏆 ${alivePlayers.length} survivants ont réussi à tenir bon!`;
        alivePlayers.forEach(p => {
            winnerDisplay.textContent += ` ${p.avatar}${p.name}`;
        });
    }

    statsDisplay.textContent = `Partie terminée en ${GAME_STATE.turn} tours. ${GAME_STATE.totalEvents} événements ont eu lieu.`;
}

// ==================== KEYBOARD CONTROLS ====================
document.addEventListener('keydown', (e) => {
    if (GAME_STATE.gameOver) return;

    switch(e.key) {
        case ' ':
        case 'Enter':
            e.preventDefault();
            if (GAME_STATE.phase === 'roll') rollDice();
            break;
        case 'm':
        case 'M':
            if (GAME_STATE.phase === 'move') movePlayer();
            break;
        case 'a':
        case 'A':
            if (GAME_STATE.phase === 'action') playerAction();
            break;
        case 'e':
        case 'E':
            if (GAME_STATE.phase === 'end') endTurn();
            break;
    }
});
