<title>Lansana Games</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Rajdhani:wght@400;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: #0a0a1a;
    color: #fff;
    font-family: 'Rajdhani', sans-serif;
    overflow: hidden;
    height: 100vh;
    width: 100vw;
  }

  #particles-canvas {
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    z-index: 0;
    pointer-events: none;
  }

  .screen {
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    z-index: 1;
    transition: opacity 0.5s, transform 0.5s;
  }

  .screen.hidden {
    opacity: 0;
    pointer-events: none;
    transform: scale(0.95);
  }

  /* MAIN MENU */
  #main-menu {
    background: radial-gradient(ellipse at center, rgba(20,20,60,0.8) 0%, rgba(10,10,26,0.95) 70%);
  }

  .logo-container {
    text-align: center;
    margin-bottom: 40px;
    animation: float 3s ease-in-out infinite;
  }

  @keyframes float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-15px); }
  }

  .logo-title {
    font-family: 'Orbitron', sans-serif;
    font-size: 4rem;
    font-weight: 900;
    background: linear-gradient(135deg, #00f5ff, #7b2ff7, #ff2d95);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    text-shadow: none;
    filter: drop-shadow(0 0 30px rgba(123,47,247,0.5));
    letter-spacing: 4px;
  }

  .logo-subtitle {
    font-family: 'Orbitron', sans-serif;
    font-size: 1.2rem;
    color: #7b2ff7;
    letter-spacing: 8px;
    margin-top: 10px;
    text-transform: uppercase;
  }

  .logo-icon {
    font-size: 5rem;
    margin-bottom: 20px;
    display: block;
    animation: pulse 2s ease-in-out infinite;
  }

  @keyframes pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.1); }
  }

  .menu-buttons {
    display: flex;
    flex-direction: column;
    gap: 15px;
    width: 320px;
  }

  .menu-btn {
    font-family: 'Orbitron', sans-serif;
    font-size: 1.1rem;
    padding: 15px 30px;
    border: 2px solid rgba(123,47,247,0.5);
    background: rgba(123,47,247,0.1);
    color: #fff;
    cursor: pointer;
    border-radius: 8px;
    transition: all 0.3s;
    text-transform: uppercase;
    letter-spacing: 2px;
    position: relative;
    overflow: hidden;
  }

  .menu-btn::before {
    content: '';
    position: absolute;
    top: 0; left: -100%;
    width: 100%; height: 100%;
    background: linear-gradient(90deg, transparent, rgba(123,47,247,0.3), transparent);
    transition: left 0.5s;
  }

  .menu-btn:hover::before {
    left: 100%;
  }

  .menu-btn:hover {
    border-color: #7b2ff7;
    background: rgba(123,47,247,0.3);
    transform: translateX(10px);
    box-shadow: 0 0 20px rgba(123,47,247,0.3);
  }

  .menu-btn.play {
    background: linear-gradient(135deg, #7b2ff7, #ff2d95);
    border: none;
    font-size: 1.3rem;
    padding: 18px 30px;
  }

  .menu-btn.play:hover {
    background: linear-gradient(135deg, #ff2d95, #7b2ff7);
    transform: translateX(10px) scale(1.05);
  }

  /* GAME SELECT */
  #game-select {
    background: radial-gradient(ellipse at center, rgba(20,20,60,0.8) 0%, rgba(10,10,26,0.95) 70%);
  }

  .select-title {
    font-family: 'Orbitron', sans-serif;
    font-size: 2rem;
    margin-bottom: 30px;
    color: #00f5ff;
  }

  .games-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    max-width: 600px;
    width: 90%;
  }

  .game-card {
    background: rgba(255,255,255,0.05);
    border: 2px solid rgba(123,47,247,0.3);
    border-radius: 15px;
    padding: 25px;
    text-align: center;
    cursor: pointer;
    transition: all 0.3s;
    position: relative;
    overflow: hidden;
  }

  .game-card:hover {
    border-color: #00f5ff;
    transform: translateY(-5px);
    box-shadow: 0 10px 30px rgba(0,245,255,0.2);
  }

  .game-card-icon {
    font-size: 3rem;
    margin-bottom: 10px;
    display: block;
  }

  .game-card-title {
    font-family: 'Orbitron', sans-serif;
    font-size: 1rem;
    margin-bottom: 5px;
    color: #fff;
  }

  .game-card-desc {
    font-size: 0.85rem;
    color: rgba(255,255,255,0.6);
  }

  .back-btn {
    position: absolute;
    top: 20px;
    left: 20px;
    font-family: 'Orbitron', sans-serif;
    font-size: 0.9rem;
    padding: 10px 20px;
    border: 2px solid rgba(255,255,255,0.3);
    background: rgba(255,255,255,0.1);
    color: #fff;
    cursor: pointer;
    border-radius: 8px;
    transition: all 0.3s;
    z-index: 10;
  }

  .back-btn:hover {
    border-color: #ff2d95;
    background: rgba(255,45,149,0.2);
  }

  /* GAME AREA */
  #game-area {
    background: #0a0a1a;
  }

  .game-header {
    position: absolute;
    top: 0; left: 0;
    width: 100%;
    padding: 15px 30px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(0,0,0,0.5);
    z-index: 10;
    border-bottom: 1px solid rgba(123,47,247,0.3);
  }

  .game-score {
    font-family: 'Orbitron', sans-serif;
    font-size: 1.2rem;
    color: #00f5ff;
  }

  .game-title-display {
    font-family: 'Orbitron', sans-serif;
    font-size: 1.1rem;
    color: #ff2d95;
  }

  .game-canvas-container {
    position: absolute;
    top: 60px;
    left: 0;
    width: 100%;
    height: calc(100% - 60px);
    display: flex;
    align-items: center;
    justify-content: center;
  }

  canvas#game-canvas {
    border: 2px solid rgba(123,47,247,0.5);
    border-radius: 10px;
    background: rgba(0,0,0,0.5);
  }

  /* MEMORY GAME */
  #memory-game {
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    padding-top: 60px;
  }

  .memory-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
    max-width: 500px;
    width: 90%;
  }

  .memory-card {
    aspect-ratio: 1;
    background: rgba(123,47,247,0.2);
    border: 2px solid rgba(123,47,247,0.4);
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    cursor: pointer;
    transition: all 0.3s;
    user-select: none;
  }

  .memory-card:hover {
    border-color: #00f5ff;
    transform: scale(1.05);
  }

  .memory-card.flipped {
    background: rgba(0,245,255,0.2);
    border-color: #00f5ff;
    transform: rotateY(180deg);
  }

  .memory-card.matched {
    background: rgba(0,255,100,0.2);
    border-color: #00ff64;
    animation: matchPulse 0.5s;
  }

  @keyframes matchPulse {
    0% { transform: scale(1); }
    50% { transform: scale(1.2); }
    100% { transform: scale(1); }
  }

  /* CLICK GAME */
  #click-game {
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    padding-top: 60px;
  }

  .click-target {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: radial-gradient(circle, #ff2d95, #7b2ff7);
    cursor: pointer;
    position: absolute;
    transition: transform 0.1s;
    box-shadow: 0 0 20px rgba(255,45,149,0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
  }

  .click-target:hover {
    transform: scale(1.1);
  }

  .click-target:active {
    transform: scale(0.9);
  }

  .click-info {
    font-family: 'Orbitron', sans-serif;
    font-size: 1.5rem;
    margin-bottom: 20px;
    color: #00f5ff;
  }

  /* SNAKE GAME */
  #snake-game {
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    padding-top: 60px;
  }

  .snake-canvas {
    border: 2px solid rgba(123,47,247,0.5);
    border-radius: 10px;
    background: rgba(0,0,0,0.5);
  }

  /* SHOOTER GAME */
  #shooter-game {
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    padding-top: 60px;
  }

  .shooter-canvas {
    border: 2px solid rgba(123,47,247,0.5);
    border-radius: 10px;
    background: rgba(0,0,0,0.5);
  }

  /* GAME OVER */
  #game-over {
    background: rgba(10,10,26,0.95);
  }

  .game-over-title {
    font-family: 'Orbitron', sans-serif;
    font-size: 3rem;
    color: #ff2d95;
    margin-bottom: 20px;
    animation: float 2s ease-in-out infinite;
  }

  .game-over-score {
    font-family: 'Orbitron', sans-serif;
    font-size: 1.5rem;
    color: #00f5ff;
    margin-bottom: 30px;
  }

  .game-over-buttons {
    display: flex;
    gap: 15px;
  }

  /* RESPONSIVE */
  @media (max-width: 768px) {
    .logo-title { font-size: 2.5rem; }
    .games-grid { grid-template-columns: 1fr; }
    .memory-grid { grid-template-columns: repeat(4, 1fr); gap: 8px; }
    .memory-card { font-size: 1.5rem; }
  }

  /* SCROLLBAR */
  ::-webkit-scrollbar { width: 8px; }
  ::-webkit-scrollbar-track { background: #0a0a1a; }
  ::-webkit-scrollbar-thumb { background: #7b2ff7; border-radius: 4px; }

  .instructions {
    font-size: 0.9rem;
    color: rgba(255,255,255,0.5);
    margin-top: 15px;
    text-align: center;
  }

  .timer-display {
    font-family: 'Orbitron', sans-serif;
    font-size: 1rem;
    color: #ff2d95;
  }

  /* Mobile controls */
  .mobile-controls {
    display: none;
    position: absolute;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 20;
  }

  .mobile-btn {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: rgba(123,47,247,0.3);
    border: 2px solid rgba(123,47,247,0.5);
    color: #fff;
    font-size: 1.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    user-select: none;
    -webkit-user-select: none;
    touch-action: manipulation;
  }

  .mobile-btn:active {
    background: rgba(123,47,247,0.6);
  }

  @media (max-width: 768px) {
    .mobile-controls { display: flex; gap: 10px; }
  }

  .controls-row {
    display: flex;
    justify-content: center;
    gap: 10px;
  }
</style>
</head>
<body>

<canvas id="particles-canvas"></canvas>

<!-- MAIN MENU -->
<div id="main-menu" class="screen">
  <div class="logo-container">
    <span class="logo-icon">🎮</span>
    <div class="logo-title">LANSANA</div>
    <div class="logo-subtitle">G A M E S</div>
  </div>
  <div class="menu-buttons">
    <button class="menu-btn play" onclick="showScreen('game-select')">▶ JOGAR</button>
    <button class="menu-btn" onclick="showScreen('game-select')">🎯 SELECIONAR JOGO</button>
    <button class="menu-btn" onclick="showAbout()">ℹ️ SOBRE</button>
  </div>
  <div class="instructions">Escolha um jogo e divirta-se!</div>
</div>

<!-- GAME SELECT -->
<div id="game-select" class="screen hidden">
  <button class="back-btn" onclick="showScreen('main-menu')">← VOLTA</button>
  <div class="select-title">SELECIONE O JOGO</div>
  <div class="games-grid">
    <div class="game-card" onclick="startGame('snake')">
      <span class="game-card-icon">🐍</span>
      <div class="game-card-title">SNAKE</div>
      <div class="game-card-desc">Clássico jogo da cobrinha</div>
    </div>
    <div class="game-card" onclick="startGame('memory')">
      <span class="game-card-icon">🧠</span>
      <div class="game-card-title">MEMORY</div>
      <div class="game-card-desc">Encontre os pares</div>
    </div>
    <div class="game-card" onclick="startGame('clicker')">
      <span class="game-card-icon">🎯</span>
      <div class="game-card-title">CLICK FAST</div>
      <div class="game-card-desc">Clique rápido nos alvos</div>
    </div>
    <div class="game-card" onclick="startGame('shooter')">
      <span class="game-card-icon">🚀</span>
      <div class="game-card-title">SPACE SHOOTER</div>
      <div class="game-card-desc">Destrua os inimigos</div>
    </div>
  </div>
</div>

<!-- GAME AREA -->
<div id="game-area" class="screen hidden">
  <div class="game-header">
    <button class="back-btn" onclick="backToMenu()">← MENU</button>
    <div class="game-title-display" id="game-title-display">JOGO</div>
    <div class="game-score" id="game-score">Score: 0</div>
  </div>

  <!-- Snake Game -->
  <div id="snake-game">
    <canvas id="snake-canvas" class="snake-canvas" width="400" height="400"></canvas>
    <div class="instructions">Use as setas ou WASD para mover</div>
    <div class="mobile-controls">
      <div class="controls-row">
        <div class="mobile-btn" ontouchstart="snakeDir('up')" onclick="snakeDir('up')">↑</div>
      </div>
      <div class="controls-row">
        <div class="mobile-btn" ontouchstart="snakeDir('left')" onclick="snakeDir('left')">←</div>
        <div class="mobile-btn" ontouchstart="snakeDir('down')" onclick="snakeDir('down')">↓</div>
        <div class="mobile-btn" ontouchstart="snakeDir('right')" onclick="snakeDir('right')">→</div>
      </div>
    </div>
  </div>

  <!-- Memory Game -->
  <div id="memory-game">
    <div class="click-info" id="memory-info">Pares encontrados: 0/8</div>
    <div class="memory-grid" id="memory-grid"></div>
  </div>

  <!-- Clicker Game -->
  <div id="click-game">
    <div class="click-info" id="click-info">Score: 0 | Tempo: 30s</div>
    <div id="click-area" style="position:relative; width:400px; height:400px; max-width:90vw; max-height:60vh; border:2px solid rgba(123,47,247,0.3); border-radius:10px; background:rgba(0,0,0,0.3);"></div>
  </div>

  <!-- Shooter Game -->
  <div id="shooter-game">
    <canvas id="shooter-canvas" class="shooter-canvas" width="400" height="500"></canvas>
    <div class="instructions">Use ← → ou A/D para mover, ESPAÇO para atirar</div>
    <div class="mobile-controls">
      <div class="controls-row">
        <div class="mobile-btn" ontouchstart="shooterMove('left')" onclick="shooterMove('left')">←</div>
        <div class="mobile-btn" ontouchstart="shooterShoot()" onclick="shooterShoot()">🔥</div>
        <div class="mobile-btn" ontouchstart="shooterMove('right')" onclick="shooterMove('right')">→</div>
      </div>
    </div>
  </div>
</div>

<!-- GAME OVER -->
<div id="game-over" class="screen hidden">
  <div class="game-over-title">GAME OVER</div>
  <div class="game-over-score" id="final-score">Score: 0</div>
  <div class="game-over-buttons">
    <button class="menu-btn play" onclick="restartGame()">🔄 JOGAR NOVAMENTE</button>
    <button class="menu-btn" onclick="backToMenu()">🏠 MENU</button>
  </div>
</div>

<script>
// ============ PARTICLES BACKGROUND ============
const particlesCanvas = document.getElementById('particles-canvas');
const pCtx = particlesCanvas.getContext('2d');
let particles = [];

function resizeParticles() {
  particlesCanvas.width = window.innerWidth;
  particlesCanvas.height = window.innerHeight;
}
resizeParticles();
window.addEventListener('resize', resizeParticles);

class Particle {
  constructor() {
    this.reset();
  }
  reset() {
    this.x = Math.random() * particlesCanvas.width;
    this.y = Math.random() * particlesCanvas.height;
    this.size = Math.random() * 2 + 0.5;
    this.speedX = (Math.random() - 0.5) * 0.5;
    this.speedY = (Math.random() - 0.5) * 0.5;
    this.opacity = Math.random() * 0.5 + 0.1;
    this.color = ['#7b2ff7', '#00f5ff', '#ff2d95'][Math.floor(Math.random() * 3)];
  }
  update() {
    this.x += this.speedX;
    this.y += this.speedY;
    if (this.x < 0 || this.x > particlesCanvas.width || this.y < 0 || this.y > particlesCanvas.height) {
      this.reset();
    }
  }
  draw() {
    pCtx.beginPath();
    pCtx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    pCtx.fillStyle = this.color;
    pCtx.globalAlpha = this.opacity;
    pCtx.fill();
    pCtx.globalAlpha = 1;
  }
}

for (let i = 0; i < 100; i++) {
  particles.push(new Particle());
}

function animateParticles() {
  pCtx.clearRect(0, 0, particlesCanvas.width, particlesCanvas.height);
  particles.forEach(p => {
    p.update();
    p.draw();
  });
  requestAnimationFrame(animateParticles);
}
animateParticles();

// ============ SCREEN MANAGEMENT ============
let currentGame = null;
let gameInterval = null;
let gameActive = false;

function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.add('hidden'));
  document.getElementById(id).classList.remove('hidden');
}

function showAbout() {
  alert('🎮 Lansana Games\n\nUma coleção de jogos clássicos desenvolvida com HTML5, CSS e JavaScript.\n\nDivirt-se jogando!');
}

function backToMenu() {
  gameActive = false;
  if (gameInterval) clearInterval(gameInterval);
  showScreen('main-menu');
}

function startGame(game) {
  currentGame = game;
  gameActive = true;
  showScreen('game-area');

  // Hide all game containers
  document.getElementById('snake-game').style.display = 'none';
  document.getElementById('memory-game').style.display = 'none';
  document.getElementById('click-game').style.display = 'none';
  document.getElementById('shooter-game').style.display = 'none';

  switch(game) {
    case 'snake':
      document.getElementById('snake-game').style.display = 'flex';
      document.getElementById('game-title-display').textContent = '🐍 SNAKE';
      initSnake();
      break;
    case 'memory':
      document.getElementById('memory-game').style.display = 'flex';
      document.getElementById('game-title-display').textContent = '🧠 MEMORY';
      initMemory();
      break;
    case 'clicker':
      document.getElementById('click-game').style.display = 'flex';
      document.getElementById('game-title-display').textContent = '🎯 CLICK FAST';
      initClicker();
      break;
    case 'shooter':
      document.getElementById('shooter-game').style.display = 'flex';
      document.getElementById('game-title-display').textContent = '🚀 SPACE SHOOTER';
      initShooter();
      break;
  }
}

function restartGame() {
  startGame(currentGame);
}

function showGameOver(score) {
  gameActive = false;
  if (gameInterval) clearInterval(gameInterval);
  document.getElementById('final-score').textContent = `Score: ${score}`;
  showScreen('game-over');
}

function updateScore(score) {
  document.getElementById('game-score').textContent = `Score: ${score}`;
}

// ============ SNAKE GAME ============
let snake, snakeFood, snakeDirection, snakeScore, snakeSpeed;
const snakeGrid = 20;

function initSnake() {
  const canvas = document.getElementById('snake-canvas');
  const ctx = canvas.getContext('2d');
  snake = [{x: 10, y: 10}];
  snakeDirection = {x: 1, y: 0};
  snakeScore = 0;
  snakeSpeed = 150;
  updateScore(0);
  placeSnakeFood();

  if (gameInterval) clearInterval(gameInterval);
  gameInterval = setInterval(() => {
    if (!gameActive) return;
    updateSnake(ctx, canvas);
    drawSnake(ctx, canvas);
  }, snakeSpeed);
}

function placeSnakeFood() {
  const canvas = document.getElementById('snake-canvas');
  snakeFood = {
    x: Math.floor(Math.random() * (canvas.width / snakeGrid)),
    y: Math.floor(Math.random() * (canvas.height / snakeGrid))
  };
}

function updateSnake(ctx, canvas) {
  const head = {x: snake[0].x + snakeDirection.x, y: snake[0].y + snakeDirection.y};

  // Wall collision
  if (head.x < 0 || head.x >= canvas.width / snakeGrid || head.y < 0 || head.y >= canvas.height / snakeGrid) {
    showGameOver(snakeScore);
    return;
  }

  // Self collision
  for (let s of snake) {
    if (s.x === head.x && s.y === head.y) {
      showGameOver(snakeScore);
      return;
    }
  }

  snake.unshift(head);

  if (head.x === snakeFood.x && head.y === snakeFood.y) {
    snakeScore += 10;
    updateScore(snakeScore);
    placeSnakeFood();
  } else {
    snake.pop();
  }
}

function drawSnake(ctx, canvas) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw grid
  ctx.strokeStyle = 'rgba(123,47,247,0.1)';
  ctx.lineWidth = 0.5;
  for (let x = 0; x < canvas.width; x += snakeGrid) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, canvas.height);
    ctx.stroke();
  }
  for (let y = 0; y < canvas.height; y += snakeGrid) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(canvas.width, y);
    ctx.stroke();
  }

  // Draw food
  ctx.fillStyle = '#ff2d95';
  ctx.shadowColor = '#ff2d95';
  ctx.shadowBlur = 10;
  ctx.beginPath();
  ctx.arc(snakeFood.x * snakeGrid + snakeGrid/2, snakeFood.y * snakeGrid + snakeGrid/2, snakeGrid/2 - 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.shadowBlur = 0;

  // Draw snake
  snake.forEach((s, i) => {
    const gradient = ctx.createRadialGradient(
      s.x * snakeGrid + snakeGrid/2, s.y * snakeGrid + snakeGrid/2, 0,
      s.x * snakeGrid + snakeGrid/2, s.y * snakeGrid + snakeGrid/2, snakeGrid/2
    );
    if (i === 0) {
      gradient.addColorStop(0, '#00f5ff');
      gradient.addColorStop(1, '#7b2ff7');
    } else {
      gradient.addColorStop(0, '#7b2ff7');
      gradient.addColorStop(1, '#4a1a9e');
    }
    ctx.fillStyle = gradient;
    ctx.shadowColor = i === 0 ? '#00f5ff' : '#7b2ff7';
    ctx.shadowBlur = 5;
    ctx.fillRect(s.x * snakeGrid + 1, s.y * snakeGrid + 1, snakeGrid - 2, snakeGrid - 2);
  });
  ctx.shadowBlur = 0;
}

function snakeDir(dir) {
  switch(dir) {
    case 'up': if (snakeDirection.y !== 1) snakeDirection = {x: 0, y: -1}; break;
    case 'down': if (snakeDirection.y !== -1) snakeDirection = {x: 0, y: 1}; break;
    case 'left': if (snakeDirection.x !== 1) snakeDirection = {x: -1, y: 0}; break;
    case 'right': if (snakeDirection.x !== -1) snakeDirection = {x: 1, y: 0}; break;
  }
}

document.addEventListener('keydown', (e) => {
  if (currentGame === 'snake' && gameActive) {
    switch(e.key) {
      case 'ArrowUp': case 'w': case 'W': snakeDir('up'); e.preventDefault(); break;
      case 'ArrowDown': case 's': case 'S': snakeDir('down'); e.preventDefault(); break;
      case 'ArrowLeft': case 'a': case 'A': snakeDir('left'); e.preventDefault(); break;
      case 'ArrowRight': case 'd': case 'D': snakeDir('right'); e.preventDefault(); break;
    }
  }
});

// ============ MEMORY GAME ============
let memoryCards, memoryFlipped, memoryMatched, memoryLocked;

function initMemory() {
  const emojis = ['🎮', '🎯', '🎲', '🎪', '🎨', '🎭', '🎵', '🎸'];
  memoryCards = [...emojis, ...emojis].sort(() => Math.random() - 0.5);
  memoryFlipped = [];
  memoryMatched = new Set();
  memoryLocked = false;
  updateScore(0);
  document.getElementById('memory-info').textContent = 'Pares encontrados: 0/8';

  const grid = document.getElementById('memory-grid');
  grid.innerHTML = '';
  memoryCards.forEach((emoji, i) => {
    const card = document.createElement('div');
    card.className = 'memory-card';
    card.dataset.index = i;
    card.dataset.emoji = emoji;
    card.textContent = '?';
    card.onclick = () => flipMemoryCard(card);
    grid.appendChild(card);
  });
}

function flipMemoryCard(card) {
  if (memoryLocked || memoryFlipped.length >= 2) return;
  if (memoryFlipped.find(c => c.dataset.index === card.dataset.index)) return;
  if (memoryMatched.has(card.dataset.index)) return;

  card.classList.add('flipped');
  card.textContent = card.dataset.emoji;
  memoryFlipped.push(card);

  if (memoryFlipped.length === 2) {
    memoryLocked = true;
    const [c1, c2] = memoryFlipped;
    if (c1.dataset.emoji === c2.dataset.emoji) {
      memoryMatched.add(c1.dataset.index);
      memoryMatched.add(c2.dataset.index);
      c1.classList.add('matched');
      c2.classList.add('matched');
      memoryFlipped = [];
      memoryLocked = false;
      updateScore(memoryMatched.size / 2);
      document.getElementById('memory-info').textContent = `Pares encontrados: ${memoryMatched.size / 2}/8`;

      if (memoryMatched.size === memoryCards.length) {
        setTimeout(() => showGameOver(memoryMatched.size / 2), 500);
      }
    } else {
      setTimeout(() => {
        c1.classList.remove('flipped');
        c2.classList.remove('flipped');
        c1.textContent = '?';
        c2.textContent = '?';
        memoryFlipped = [];
        memoryLocked = false;
      }, 800);
    }
  }
}

