// ============ SPACE SHOOTER ============
let shooterPlayer, shooterBullets, shooterEnemies, shooterScore, shooterKeys;

function initShooter() {
  const canvas = document.getElementById('shooter-canvas');
  const ctx = canvas.getContext('2d');
  shooterPlayer = { x: 180, y: 440, width: 40, height: 40 };
  shooterBullets = [];
  shooterEnemies = [];
  shooterScore = 0;
  shooterKeys = {};
  updateScore(0);

  if (gameInterval) clearInterval(gameInterval);
  gameInterval = setInterval(() => {
    if (!gameActive) return;
    updateShooter(ctx, canvas);
    drawShooter(ctx, canvas);
  }, 16);

  // Spawn enemies
  if (window.shooterSpawnInterval) clearInterval(window.shooterSpawnInterval);
  window.shooterSpawnInterval = setInterval(() => {
    if (!gameActive) return;
    const canvas = document.getElementById('shooter-canvas');
    shooterEnemies.push({
      x: Math.random() * (canvas.width - 40),
      y: -40,
      width: 35,
      height: 35,
      speed: 2 + Math.random() * 2
    });
  }, 1000);
}

function updateShooter(ctx, canvas) {
  // Move player
  if (shooterKeys['ArrowLeft'] || shooterKeys['a']) shooterPlayer.x -= 5;
  if (shooterKeys['ArrowRight'] || shooterKeys['d']) shooterPlayer.x += 5;
  shooterPlayer.x = Math.max(0, Math.min(canvas.width - shooterPlayer.width, shooterPlayer.x));

  // Update bullets
  shooterBullets = shooterBullets.filter(b => {
    b.y -= 8;
    return b.y > -10;
  });

  // Update enemies
  shooterEnemies = shooterEnemies.filter(e => {
    e.y += e.speed;
    return e.y < canvas.height + 40;
  });

  // Check bullet-enemy collisions
  shooterBullets.forEach((b, bi) => {
    shooterEnemies.forEach((e, ei) => {
      if (b.x < e.x + e.width && b.x + b.width > e.x && b.y < e.y + e.height && b.y + b.height > e.y) {
        shooterBullets.splice(bi, 1);
        shooterEnemies.splice(ei, 1);
        shooterScore += 15;
        updateScore(shooterScore);
      }
    });
  });

  // Check player-enemy collisions
  shooterEnemies.forEach(e => {
    if (shooterPlayer.x < e.x + e.width && shooterPlayer.x + shooterPlayer.width > e.x &&
        shooterPlayer.y < e.y + e.height && shooterPlayer.y + shooterPlayer.height > e.y) {
      showGameOver(shooterScore);
    }
  });
}

function drawShooter(ctx, canvas) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw stars
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  for (let i = 0; i < 50; i++) {
    const x = (i * 73 + Date.now() * 0.01) % canvas.width;
    const y = (i * 137 + Date.now() * 0.05) % canvas.height;
    ctx.fillRect(x, y, 1, 1);
  }

  // Draw player
  ctx.fillStyle = '#00f5ff';
  ctx.shadowColor = '#00f5ff';
  ctx.shadowBlur = 15;
  ctx.beginPath();
  ctx.moveTo(shooterPlayer.x + shooterPlayer.width/2, shooterPlayer.y);
  ctx.lineTo(shooterPlayer.x, shooterPlayer.y + shooterPlayer.height);
  ctx.lineTo(shooterPlayer.x + shooterPlayer.width, shooterPlayer.y + shooterPlayer.height);
  ctx.closePath();
  ctx.fill();
  ctx.shadowBlur = 0;

  // Draw bullets
  ctx.fillStyle = '#ff2d95';
  ctx.shadowColor = '#ff2d95';
  ctx.shadowBlur = 10;
  shooterBullets.forEach(b => {
    ctx.fillRect(b.x, b.y, b.width, b.height);
  });
  ctx.shadowBlur = 0;

  // Draw enemies
  shooterEnemies.forEach(e => {
    ctx.fillStyle = '#ff2d95';
    ctx.shadowColor = '#ff2d95';
    ctx.shadowBlur = 10;
    ctx.fillRect(e.x, e.y, e.width, e.height);
    // Enemy eyes
    ctx.fillStyle = '#fff';
    ctx.fillRect(e.x + 8, e.y + 10, 6, 6);
    ctx.fillRect(e.x + e.width - 14, e.y + 10, 6, 6);
    ctx.shadowBlur = 0;
  });
}

function shooterMove(dir) {
  shooterKeys[dir === 'left' ? 'ArrowLeft' : 'ArrowRight'] = true;
}

function shooterShoot() {
  if (!gameActive) return;
  const canvas = document.getElementById('shooter-canvas');
  shooterBullets.push({
    x: shooterPlayer.x + shooterPlayer.width/2 - 2,
    y: shooterPlayer.y,
    width: 4,
    height: 10
  });
}

document.addEventListener('keydown', (e) => {
  if (currentGame === 'shooter' && gameActive) {
    shooterKeys[e.key] = true;
    if (e.key === ' ') {
      shooterShoot();
      e.preventDefault();
    }
  }
});

document.addEventListener('keyup', (e) => {
  if (currentGame === 'shooter') {
    shooterKeys[e.key] = false;
  }
});

// ============ TOUCH SUPPORT FOR SNAKE ============
let touchStartX = 0, touchStartY = 0;

document.addEventListener('touchstart', (e) => {
  touchStartX = e.touches[0].clientX;
  touchStartY = e.touches[0].clientY;
});

document.addEventListener('touchend', (e) => {
  if (currentGame !== 'snake' || !gameActive) return;
  const dx = e.changedTouches[0].clientX - touchStartX;
  const dy = e.changedTouches[0].clientY - touchStartY;

  if (Math.abs(dx) > Math.abs(dy)) {
    snakeDir(dx > 0 ? 'right' : 'left');
  } else {
    snakeDir(dy > 0 ? 'down' : 'up');
  }
});

// Prevent scrolling on mobile
document.addEventListener('touchmove', (e) => {
  if (gameActive) e.preventDefault();
}, { passive: false });
