</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const minimapCanvas = document.getElementById('minimap');
const minimapCtx = minimapCanvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
minimapCanvas.width = 150;
minimapCanvas.height = 150;

window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
});

// Game State
let gameRunning = false;
let score = 0;
let selectedPower = 'heat';
let camera = { x: 0, y: 100, z: 0, rotX: 0, rotY: 0 };
let keys = {};
let mouse = { x: 0, y: 0, down: false };
let time = 0;

// Superman
let superman = {
    x: 0, y: 50, z: 0,
    vx: 0, vy: 0, vz: 0,
    health: 100, maxHealth: 100,
    energy: 100, maxEnergy: 100,
    kryptonite: 0, maxKryptonite: 100,
    speed: 1.5,
    isFlying: false,
    isSuperSpeed: false,
    isDashing: false,
    dashCooldown: 0,
    attackCooldown: 0,
    invincible: 0,
    width: 2, height: 4,
    angle: 0,
    animFrame: 0,
    animTimer: 0
};

// Buildings
let buildings = [];
let enemies = [];
let projectiles = [];
let particles = [];
let collectibles = [];
let explosions = [];

// Generate city
function generateCity() {
    buildings = [];
    for (let i = 0; i < 200; i++) {
        let x = (Math.random() - 0.5) * 4000;
        let z = (Math.random() - 0.5) * 4000;
        let w = 20 + Math.random() * 60;
        let h = 30 + Math.random() * 200;
        let d = 20 + Math.random() * 60;
        buildings.push({
            x, y: 0, z, w, h, d,
            color: `hsl(${200 + Math.random() * 40}, ${10 + Math.random() * 20}%, ${20 + Math.random() * 30}%)`,
            windows: Math.random() > 0.3,
            windowColor: Math.random() > 0.5 ? '#ffcc44' : '#88ccff'
        });
    }
}

// Generate enemies
function spawnEnemies() {
    enemies = [];
    for (let i = 0; i < 30; i++) {
        spawnEnemy();
    }
}

function spawnEnemy() {
    let angle = Math.random() * Math.PI * 2;
    let dist = 200 + Math.random() * 800;
    let type = Math.random();
    let enemy = {
        x: superman.x + Math.cos(angle) * dist,
        y: 0,
        z: superman.z + Math.sin(angle) * dist,
        vx: 0, vy: 0, vz: 0,
        health: 30 + Math.random() * 70,
        maxHealth: 100,
        type: type < 0.4 ? 'robot' : type < 0.7 ? 'alien' : 'kryptonite',
        speed: 0.3 + Math.random() * 0.5,
        attackRange: type < 0.7 ? 50 : 150,
        attackDamage: 5 + Math.random() * 15,
        attackCooldown: 0,
        angle: 0,
        animFrame: 0,
        animTimer: 0,
        size: type === 'kryptonite' ? 3 : 2,
        color: type === 'robot' ? '#888' : type === 'alien' ? '#44aa44' : '#44ff44',
        alive: true,
        hitFlash: 0
    };
    enemies.push(enemy);
}

// Generate collectibles
function spawnCollectibles() {
    collectibles = [];
    for (let i = 0; i < 20; i++) {
        collectibles.push({
            x: (Math.random() - 0.5) * 3000,
            y: 10 + Math.random() * 50,
            z: (Math.random() - 0.5) * 3000,
            type: Math.random() > 0.5 ? 'health' : 'energy',
            amount: 20 + Math.random() * 30,
            collected: false,
            bobTimer: Math.random() * Math.PI * 2
        });
    }
}

// 3D Projection
function project(x, y, z) {
    let dx = x - camera.x;
    let dy = y - camera.y;
    let dz = z - camera.z;

    let cosY = Math.cos(-camera.rotY);
    let sinY = Math.sin(-camera.rotY);
    let cosX = Math.cos(-camera.rotX);
    let sinX = Math.sin(-camera.rotX);

    let rx = dx * cosY - dz * sinY;
    let rz = dx * sinY + dz * cosY;
    let ry = dy;

    let ry2 = ry * cosX - rz * sinX;
    let rz2 = ry * sinX + rz * cosX;

    if (rz2 <= 0) return null;

    let fov = 800;
    let sx = canvas.width / 2 + (rx * fov) / rz2;
    let sy = canvas.height / 2 - (ry2 * fov) / rz2;

    return { x: sx, y: sy, z: rz2, scale: fov / rz2 };
}

// Draw 3D cube
function drawCube(x, y, z, w, h, d, color, alpha = 1) {
    let vertices = [
        {x: x - w/2, y: y, z: z - d/2},
        {x: x + w/2, y: y, z: z - d/2},
        {x: x + w/2, y: y, z: z + d/2},
        {x: x - w/2, y: y, z: z + d/2},
        {x: x - w/2, y: y + h, z: z - d/2},
        {x: x + w/2, y: y + h, z: z - d/2},
        {x: x + w/2, y: y + h, z: z + d/2},
        {x: x - w/2, y: y + h, z: z + d/2}
    ];

    let projected = vertices.map(v => project(v.x, v.y, v.z));
    if (projected.some(p => p === null)) return;

    let faces = [
        { indices: [0, 1, 2, 3], normal: {x: 0, y: 0, z: -1} },
        { indices: [5, 4, 7, 6], normal: {x: 0, y: 0, z: 1} },
        { indices: [4, 0, 3, 7], normal: {x: -1, y: 0, z: 0} },
        { indices: [1, 5, 6, 2], normal: {x: 1, y: 0, z: 0} },
        { indices: [3, 2, 6, 7], normal: {x: 0, y: -1, z: 0} },
        { indices: [4, 5, 1, 0], normal: {x: 0, y: 1, z: 0} }
    ];

    let lightDir = { x: 0.5, y: -1, z: 0.3 };
    let lightLen = Math.sqrt(lightDir.x**2 + lightDir.y**2 + lightDir.z**2);
    lightDir.x /= lightLen; lightDir.y /= lightLen; lightDir.z /= lightLen;

    faces.forEach(face => {
        let pts = face.indices.map(i => projected[i]);
        let avgZ = pts.reduce((s, p) => s + p.z, 0) / 4;

        let nx = face.normal.x;
        let ny = face.normal.y;
        let nz = face.normal.z;

        let dot = nx * lightDir.x + ny * lightDir.y + nz * lightDir.z;
        let brightness = Math.max(0.3, Math.min(1, 0.5 + dot * 0.5));

        ctx.beginPath();
        ctx.moveTo(pts[0].x, pts[0].y);
        for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
        ctx.closePath();

        let r = parseInt(color.slice(1,3), 16);
        let g = parseInt(color.slice(3,5), 16);
        let b = parseInt(color.slice(5,7), 16);

        ctx.fillStyle = `rgba(${Math.floor(r*brightness)},${Math.floor(g*brightness)},${Math.floor(b*brightness)},${alpha})`;
        ctx.fill();
        ctx.strokeStyle = `rgba(255,255,255,${alpha * 0.1})`;
        ctx.lineWidth = 0.5;
        ctx.stroke();
    });
}

// Draw Superman
function drawSuperman() {
    let p = project(superman.x, superman.y + superman.height/2, superman.z);
    if (!p) return;

    let scale = p.scale;
    let size = 30 * scale;

    ctx.save();
    ctx.translate(p.x, p.y);

    // Shadow
    let shadowP = project(superman.x, 0, superman.z);
    if (shadowP) {
        ctx.beginPath();
        ctx.ellipse(shadowP.x - p.x, shadowP.y - p.y, size * 0.8, size * 0.3, 0, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fill();
    }

    // Body
    ctx.fillStyle = '#0066cc';
    ctx.fillRect(-size * 0.3, -size * 0.5, size * 0.6, size * 0.8);

    // Suit detail
    ctx.fillStyle = '#004499';
    ctx.fillRect(-size * 0.3, -size * 0.5, size * 0.6, size * 0.15);

    // Cape
    ctx.fillStyle = '#cc0000';
    let capeWave = Math.sin(time * 5) * size * 0.2;
    ctx.beginPath();
    ctx.moveTo(-size * 0.3, -size * 0.4);
    ctx.quadraticCurveTo(-size * 0.5 + capeWave, size * 0.2, -size * 0.4 + capeWave, size * 0.6);
    ctx.lineTo(size * 0.4 - capeWave, size * 0.6);
    ctx.quadraticCurveTo(size * 0.5 + capeWave, size * 0.2, size * 0.3, -size * 0.4);
    ctx.fill();

    // Head
    ctx.fillStyle = '#ffcc88';
    ctx.beginPath();
    ctx.arc(0, -size * 0.65, size * 0.25, 0, Math.PI * 2);
    ctx.fill();

    // Hair
    ctx.fillStyle = '#221100';
    ctx.beginPath();
    ctx.arc(0, -size * 0.7, size * 0.27, Math.PI, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.ellipse(-size * 0.08, -size * 0.67, size * 0.06, size * 0.04, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(size * 0.08, -size * 0.67, size * 0.06, size * 0.04, 0, 0, Math.PI * 2);
    ctx.fill();

    // S shield
    ctx.fillStyle = '#ffcc00';
    ctx.beginPath();
    ctx.moveTo(0, -size * 0.45);
    ctx.lineTo(-size * 0.15, -size * 0.35);
    ctx.lineTo(-size * 0.15, -size * 0.2);
    ctx.lineTo(0, -size * 0.25);
    ctx.lineTo(size * 0.15, -size * 0.2);
    ctx.lineTo(size * 0.15, -size * 0.35);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#cc0000';
    ctx.font = `bold ${size * 0.15}px Arial`;
    ctx.textAlign = 'center';
    ctx.fillText('S', 0, -size * 0.3);

    // Arms
    let armAngle = Math.sin(time * 8) * 0.3;
    ctx.fillStyle = '#0066cc';
    ctx.save();
    ctx.translate(-size * 0.35, -size * 0.35);
    ctx.rotate(-0.5 + armAngle);
    ctx.fillRect(-size * 0.08, 0, size * 0.16, size * 0.5);
    ctx.restore();

    ctx.save();
    ctx.translate(size * 0.35, -size * 0.35);
    ctx.rotate(0.5 - armAngle);
    ctx.fillRect(-size * 0.08, 0, size * 0.16, size * 0.5);
    ctx.restore();

    // Legs
    ctx.fillStyle = '#0066cc';
    ctx.fillRect(-size * 0.25, size * 0.3, size * 0.15, size * 0.4);
    ctx.fillRect(size * 0.1, size * 0.3, size * 0.15, size * 0.4);

    // Boots
    ctx.fillStyle = '#cc0000';
    ctx.fillRect(-size * 0.28, size * 0.65, size * 0.2, size * 0.15);
    ctx.fillRect(size * 0.08, size * 0.65, size * 0.2, size * 0.15);

    // Invincibility effect
    if (superman.invincible > 0) {
        ctx.beginPath();
        ctx.arc(0, 0, size * 1.5, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(255,255,0,${superman.invincible / 60})`;
        ctx.lineWidth = 3;
        ctx.stroke();
    }

    ctx.restore();
}

// Draw enemy
function drawEnemy(enemy) {
    if (!enemy.alive) return;
    let p = project(enemy.x, enemy.y + enemy.size, enemy.z);
    if (!p) return;

    let scale = p.scale;
    let size = enemy.size * 25 * scale;

    ctx.save();
    ctx.translate(p.x, p.y);

    // Shadow
    let shadowP = project(enemy.x, 0, enemy.z);
    if (shadowP) {
        ctx.beginPath();
        ctx.ellipse(shadowP.x - p.x, shadowP.y - p.y, size * 0.6, size * 0.2, 0, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fill();
    }

    // Body
    let bodyColor = enemy.hitFlash > 0 ? '#fff' : enemy.color;
    ctx.fillStyle = bodyColor;

    if (enemy.type === 'robot') {
        // Robot body
        ctx.fillRect(-size * 0.4, -size * 0.5, size * 0.8, size * 0.8);
        // Head
        ctx.fillStyle = '#666';
        ctx.fillRect(-size * 0.3, -size * 0.8, size * 0.6, size * 0.3);
        // Eyes
        ctx.fillStyle = '#ff0000';
        ctx.beginPath();
        ctx.arc(-size * 0.1, -size * 0.7, size * 0.05, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(size * 0.1, -size * 0.7, size * 0.05, 0, Math.PI * 2);
        ctx.fill();
        // Arms
        ctx.fillStyle = '#888';
        ctx.fillRect(-size * 0.6, -size * 0.3, size * 0.2, size * 0.6);
        ctx.fillRect(size * 0.4, -size * 0.3, size * 0.2, size * 0.6);
    } else if (enemy.type === 'alien') {
        // Alien body
        ctx.beginPath();
        ctx.ellipse(0, 0, size * 0.4, size * 0.6, 0, 0, Math.PI * 2);
        ctx.fill();
        // Head
        ctx.fillStyle = '#338833';
        ctx.beginPath();
        ctx.ellipse(0, -size * 0.7, size * 0.3, size * 0.25, 0, 0, Math.PI * 2);
        ctx.fill();
        // Eyes
        ctx.fillStyle = '#ffff00';
        ctx.beginPath();
        ctx.arc(-size * 0.1, -size * 0.75, size * 0.08, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(size * 0.1, -size * 0.75, size * 0.08, 0, Math.PI * 2);
        ctx.fill();
    } else {
        // Kryptonite enemy
        ctx.fillStyle = '#44ff44';
        ctx.beginPath();
        ctx.moveTo(0, -size * 0.8);
        ctx.lineTo(size * 0.5, 0);
        ctx.lineTo(0, size * 0.8);
        ctx.lineTo(-size * 0.5, 0);
        ctx.closePath();
        ctx.fill();
        // Glow
        ctx.beginPath();
        ctx.arc(0, 0, size * 0.6, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(68,255,68,0.5)';
        ctx.lineWidth = 2;
        ctx.stroke();
    }

    // Health bar
    let healthPercent = enemy.health / enemy.maxHealth;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(-size * 0.5, -size * 1.2, size, size * 0.1);
    ctx.fillStyle = healthPercent > 0.5 ? '#00ff00' : healthPercent > 0.25 ? '#ffaa00' : '#ff0000';
    ctx.fillRect(-size * 0.5, -size * 1.2, size * healthPercent, size * 0.1);

    ctx.restore();
}

// Draw projectile
function drawProjectile(proj) {
    let p = project(proj.x, proj.y, proj.z);
    if (!p) return;

    let size = proj.size * p.scale;

    ctx.save();
    ctx.translate(p.x, p.y);

    if (proj.type === 'heat') {
        // Heat vision beam
        let gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, size * 2);
        gradient.addColorStop(0, 'rgba(255,255,255,0.9)');
        gradient.addColorStop(0.3, 'rgba(255,100,0,0.8)');
        gradient.addColorStop(1, 'rgba(255,0,0,0)');
        ctx.beginPath();
        ctx.arc(0, 0, size * 2, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();
    } else if (proj.type === 'freeze') {
        // Freeze breath
        let gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, size * 2);
        gradient.addColorStop(0, 'rgba(200,230,255,0.9)');
        gradient.addColorStop(0.5, 'rgba(100,180,255,0.6)');
        gradient.addColorStop(1, 'rgba(50,100,255,0)');
        ctx.beginPath();
        ctx.arc(0, 0, size * 2, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();
    } else if (proj.type === 'shockwave') {
        ctx.beginPath();
        ctx.arc(0, 0, size, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
        ctx.lineWidth = 3;
        ctx.stroke();
    }

    ctx.restore();
}

// Draw particle
function drawParticle(part) {
    let p = project(part.x, part.y, part.z);
    if (!p) return;

    let size = part.size * p.scale;
    ctx.beginPath();
    ctx.arc(p.x, p.y, Math.max(1, size), 0, Math.PI * 2);
    ctx.fillStyle = part.color.replace('ALPHA', part.alpha.toFixed(2));
    ctx.fill();
}

// Draw collectible
function drawCollectible(col) {
    if (col.collected) return;
    let p = project(col.x, col.y + Math.sin(col.bobTimer) * 5, col.z);
    if (!p) return;

    let size = 15 * p.scale;

    ctx.save();
    ctx.translate(p.x, p.y);

    if (col.type === 'health') {
        ctx.fillStyle = '#ff0000';
        ctx.beginPath();
        ctx.arc(0, 0, size, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#fff';
        ctx.font = `bold ${size}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('+', 0, 0);
    } else {
        ctx.fillStyle = '#0088ff';
        ctx.beginPath();
        ctx.arc(0, 0, size, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#fff';
        ctx.font = `bold ${size}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('E', 0, 0);
    }

    // Glow
    ctx.beginPath();
    ctx.arc(0, 0, size * 1.5, 0, Math.PI * 2);
    ctx.strokeStyle = col.type === 'health' ? 'rgba(255,0,0,0.3)' : 'rgba(0,136,255,0.3)';
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.restore();
}

// Draw sky
function drawSky() {
    let gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
    gradient.addColorStop(0, '#001133');
    gradient.addColorStop(0.3, '#003366');
    gradient.addColorStop(0.6, '#006699');
    gradient.addColorStop(1, '#0099cc');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Stars
    for (let i = 0; i < 100; i++) {
        let sx = (Math.sin(i * 123.456) * 0.5 + 0.5) * canvas.width;
        let sy = (Math.cos(i * 789.012) * 0.5 + 0.5) * canvas.height * 0.5;
        let brightness = 0.3 + Math.sin(time * 2 + i) * 0.3;
        ctx.fillStyle = `rgba(255,255,255,${brightness})`;
        ctx.beginPath();
        ctx.arc(sx, sy, 1 + Math.random(), 0, Math.PI * 2);
        ctx.fill();
    }

    // Moon
    let moonP = project(500, 300, -1000);
    if (moonP) {
        ctx.beginPath();
        ctx.arc(moonP.x, moonP.y, 40 * moonP.scale, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffcc';
        ctx.fill();
        ctx.beginPath();
        ctx.arc(moonP.x + 10 * moonP.scale, moonP.y - 5 * moonP.scale, 35 * moonP.scale, 0, Math.PI * 2);
        ctx.fillStyle = '#001133';
        ctx.fill();
    }
}

// Draw ground
function drawGround() {
    let gridSize = 200;
    let range = 2000;

    ctx.strokeStyle = 'rgba(100,100,100,0.3)';
    ctx.lineWidth = 1;

    for (let x = -range; x <= range; x += gridSize) {
        let p1 = project(x + camera.x, 0, -range + camera.z);
        let p2 = project(x + camera.x, 0, range + camera.z);
        if (p1 && p2) {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();
        }
    }

    for (let z = -range; z <= range; z += gridSize) {
        let p1 = project(-range + camera.x, 0, z + camera.z);
        let p2 = project(range + camera.x, 0, z + camera.z);
        if (p1 && p2) {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();
        }
    }

    // Ground fill
    let gradient = ctx.createLinearGradient(0, canvas.height * 0.5, 0, canvas.height);
    gradient.addColorStop(0, 'rgba(50,50,50,0)');
    gradient.addColorStop(1, 'rgba(50,50,50,0.5)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, canvas.height * 0.5, canvas.width, canvas.height * 0.5);
}

// Draw clouds
function drawClouds() {
    for (let i = 0; i < 20; i++) {
        let cx = (Math.sin(i * 3.7 + time * 0.1) * 0.5 + 0.5) * 4000 - 2000;
        let cz = (Math.cos(i * 2.3 + time * 0.05) * 0.5 + 0.5) * 4000 - 2000;
        let cy = 200 + Math.sin(i * 1.5) * 50;

        let p = project(cx + camera.x * 0.1, cy, cz + camera.z * 0.1);
        if (!p) continue;

        let size = 100 * p.scale;
        ctx.beginPath();
        ctx.arc(p.x, p.y, size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255,255,255,${0.1 + Math.sin(time + i) * 0.05})`;
        ctx.fill();
    }
}

// Update game
function update() {
    if (!gameRunning) return;

    time += 0.016;

    // Superman movement
    let speed = superman.isSuperSpeed ? superman.speed * 3 : superman.speed;
    let moveX = 0, moveZ = 0;

    if (keys['w'] || keys['arrowup']) moveZ -= 1;
    if (keys['s'] || keys['arrowdown']) moveZ += 1;
    if (keys['a'] || keys['arrowleft']) moveX -= 1;
    if (keys['d'] || keys['arrowright']) moveX += 1;

    let moveAngle = camera.rotY;
    superman.vx += (Math.sin(moveAngle) * moveZ + Math.cos(moveAngle) * moveX) * speed * 0.1;
    superman.vz += (Math.cos(moveAngle) * moveZ - Math.sin(moveAngle) * moveX) * speed * 0.1;

    // Friction
    superman.vx *= 0.92;
    superman.vz *= 0.92;

    // Flying
    if (keys[' '] && superman.isFlying) {
        superman.vy += 0.5;
        if (superman.vy > 5) superman.vy = 5;
    } else if (superman.isFlying) {
        superman.vy *= 0.95;
        if (superman.vy < -0.5) superman.vy = -0.5;
    } else {
        superman.vy -= 0.3; // Gravity
        if (superman.y <= 0) {
            superman.y = 0;
            superman.vy = 0;
            superman.isFlying = false;
        }
    }

    superman.x += superman.vx;
    superman.y += superman.vy;
    superman.z += superman.vz;

    // Keep in bounds
    superman.x = Math.max(-2000, Math.min(2000, superman.x));
    superman.z = Math.max(-2000, Math.min(2000, superman.z));

    // Camera follows Superman
    camera.x = superman.x;
    camera.y = superman.y + 50;
    camera.z = superman.z;

    // Mouse look
    camera.rotY += mouse.dx * 0.002;
    camera.rotX += mouse.dy * 0.002;
    camera.rotX = Math.max(-0.5, Math.min(0.5, camera.rotX));
    mouse.dx = 0;
    mouse.dy = 0;

    // Super speed
    superman.isSuperSpeed = keys['shift'];
    if (superman.isSuperSpeed) {
        document.getElementById('speed-lines').style.opacity = '1';
    } else {
        document.getElementById('speed-lines').style.opacity = '0';
    }

    // Dash
    if (keys['q'] && superman.dashCooldown <= 0) {
        superman.isDashing = true;
        superman.dashCooldown = 60;
        superman.invincible = 30;
        let dashSpeed = 20;
        superman.vx += Math.sin(camera.rotY) * dashSpeed;
        superman.vz += Math.cos(camera.rotY) * dashSpeed;
        superman.vy += 5;
        // Dash particles
        for (let i = 0; i < 20; i++) {
            particles.push({
                x: superman.x, y: superman.y + 2, z: superman.z,
                vx: (Math.random() - 0.5) * 5,
                vy: (Math.random() - 0.5) * 5,
                vz: (Math.random() - 0.5) * 5,
                size: 3 + Math.random() * 5,
                color: 'rgba(255,200,0,ALPHA)',
                alpha: 1,
                life: 30
            });
        }
    }
    if (superman.dashCooldown > 0) superman.dashCooldown--;
    if (superman.invincible > 0) superman.invincible--;

    // Attack
    if (superman.attackCooldown > 0) superman.attackCooldown--;
    if (mouse.down && superman.attackCooldown <= 0) {
        attack();
        superman.attackCooldown = selectedPower === 'heat' ? 5 : selectedPower === 'freeze' ? 10 : 20;
    }

    // Energy regeneration
    if (superman.energy < superman.maxEnergy) {
        superman.energy += 0.1;
    }

    // Update enemies
    enemies.forEach(enemy => {
        if (!enemy.alive) return;

        let dx = superman.x - enemy.x;
        let dz = superman.z - enemy.z;
        let dist = Math.sqrt(dx * dx + dz * dz);

        enemy.angle = Math.atan2(dx, dz);

        if (dist > enemy.attackRange) {
            enemy.vx += (dx / dist) * enemy.speed * 0.1;
            enemy.vz += (dz / dist) * enemy.speed * 0.1;
        }

        enemy.vx *= 0.95;
        enemy.vz *= 0.95;
        enemy.x += enemy.vx;
        enemy.z += enemy.vz;

        // Attack Superman
        if (dist < enemy.attackRange && enemy.attackCooldown <= 0) {
            if (superman.invincible <= 0) {
                superman.health -= enemy.attackDamage;
                superman.invincible = 30;
                document.getElementById('damage-overlay').style.opacity = '1';
                setTimeout(() => {
                    document.getElementById('damage-overlay').style.opacity = '0';
                }, 200);
            }
            enemy.attackCooldown = 60;
        }
        if (enemy.attackCooldown > 0) enemy.attackCooldown--;

        if (enemy.hitFlash > 0) enemy.hitFlash--;

        // Check death
        if (enemy.health <= 0) {
            enemy.alive = false;
            score += enemy.type === 'kryptonite' ? 200 : enemy.type === 'alien' ? 150 : 100;

            // Death explosion
            for (let i = 0; i < 30; i++) {
                particles.push({
                    x: enemy.x, y: enemy.y + enemy.size, z: enemy.z,
                    vx: (Math.random() - 0.5) * 10,
                    vy: (Math.random() - 0.5) * 10,
                    vz: (Math.random() - 0.5) * 10,
                    size: 2 + Math.random() * 4,
                    color: enemy.type === 'kryptonite' ? 'rgba(68,255,68,ALPHA)' :
                           enemy.type === 'alien' ? 'rgba(68,170,68,ALPHA)' : 'rgba(136,136,136,ALPHA)',
                    alpha: 1,
                    life: 40
                });
            }

            // Respawn after delay
            setTimeout(() => spawnEnemy(), 5000);
        }
    });

    // Update projectiles
    projectiles.forEach((proj, i) => {
        proj.x += proj.vx;
        proj.y += proj.vy;
        proj.z += proj.vz;
        proj.life--;

        if (proj.life <= 0) {
            projectiles.splice(i, 1);
            return;
        }

        // Check collision with enemies
        enemies.forEach(enemy => {
            if (!enemy.alive) return;
            let dx = proj.x - enemy.x;
            let dy = proj.y - (enemy.y + enemy.size);
            let dz = proj.z - enemy.z;
            let dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

            if (dist < enemy.size * 2) {
                let damage = proj.type === 'heat' ? 20 : proj.type === 'freeze' ? 15 : 30;
                enemy.health -= damage;
                enemy.hitFlash = 10;

                if (proj.type === 'freeze') {
                    enemy.vx *= 0.5;
                    enemy.vz *= 0.5;
                }

                // Hit particles
                for (let j = 0; j < 10; j++) {
                    particles.push({
                        x: enemy.x, y: enemy.y + enemy.size, z: enemy.z,
                        vx: (Math.random() - 0.5) * 5,
                        vy: (Math.random() - 0.5) * 5,
                        vz: (Math.random() - 0.5) * 5,
                        size: 2 + Math.random() * 3,
                        color: proj.type === 'heat' ? 'rgba(255,100,0,ALPHA)' :
                               proj.type === 'freeze' ? 'rgba(100,200,255,ALPHA)' : 'rgba(255,255,255,ALPHA)',
                        alpha: 1,
                        life: 20
                    });
                }

                projectiles.splice(i, 1);
            }
        });
    });

    // Update particles
    particles.forEach((part, i) => {
        part.x += part.vx;
        part.y += part.vy;
        part.z += part.vz;
        part.vy += 0.1; // gravity
        part.life--;
        part.alpha = part.life / 40;

        if (part.life <= 0) {
            particles.splice(i, 1);
        }
    });

    // Update collectibles
    collectibles.forEach(col => {
        if (col.collected) return;
        col.bobTimer += 0.05;

        let dx = superman.x - col.x;
        let dy = superman.y - col.y;
        let dz = superman.z - col.z;
        let dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

        if (dist < 20) {
            col.collected = true;
            if (col.type === 'health') {
                superman.health = Math.min(superman.maxHealth, superman.health + col.amount);
                showMessage('+Health!', '#ff0000');
            } else {
                superman.energy = Math.min(superman.maxEnergy, superman.energy + col.amount);
                showMessage('+Energy!', '#0088ff');
            }
            score += 50;
        }
    });

    // Update UI
    document.getElementById('health-bar').style.width = (superman.health / superman.maxHealth * 100) + '%';
    document.getElementById('energy-bar').style.width = (superman.energy / superman.maxEnergy * 100) + '%';
    document.getElementById('score').textContent = 'SCORE: ' + score;

    // Check game over
    if (superman.health <= 0) {
        gameOver();
    }

    // Update minimap
    updateMinimap();
}

function attack() {
    if (selectedPower === 'heat') {
        // Heat vision
        projectiles.push({
            x: superman.x,
            y: superman.y + 3,
            z: superman.z,
            vx: Math.sin(camera.rotY) * 15,
            vy: 0,
            vz: Math.cos(camera.rotY) * 15,
            type: 'heat',
            size: 5,
            life: 60
        });
        // Heat vision particles
        for (let i = 0; i < 5; i++) {
            particles.push({
                x: superman.x + Math.sin(camera.rotY) * 2,
                y: superman.y + 3,
                z: superman.z + Math.cos(camera.rotY) * 2,
                vx: Math.sin(camera.rotY) * 3 + (Math.random() - 0.5) * 2,
                vy: (Math.random() - 0.5) * 2,
                vz: Math.cos(camera.rotY) * 3 + (Math.random() - 0.5) * 2,
                size: 2 + Math.random() * 3,
                color: 'rgba(255,100,0,ALPHA)',
                alpha: 1,
                life: 15
            });
        }
    } else if (selectedPower === 'freeze') {
        // Freeze breath
        for (let i = 0; i < 3; i++) {
            projectiles.push({
                x: superman.x + (Math.random() - 0.5) * 2,
                y: superman.y + 3 + (Math.random() - 0.5) * 2,
                z: superman.z + (Math.random() - 0.5) * 2,
                vx: Math.sin(camera.rotY) * 10 + (Math.random() - 0.5) * 2,
                vy: (Math.random() - 0.5) * 2,
                vz: Math.cos(camera.rotY) * 10 + (Math.random() - 0.5) * 2,
                type: 'freeze',
                size: 8,
                life: 40
            });
        }
    } else if (selectedPower === 'strength') {
        // Super punch shockwave
        projectiles.push({
            x: superman.x + Math.sin(camera.rotY) * 5,
            y: superman.y + 2,
            z: superman.z + Math.cos(camera.rotY) * 5,
            vx: Math.sin(camera.rotY) * 8,
            vy: 0,
            vz: Math.cos(camera.rotY) * 8,
            type: 'shockwave',
            size: 15,
            life: 30
        });
    }
}

function selectPower(power) {
    selectedPower = power;
    document.querySelectorAll('.power-slot').forEach(slot => {
        slot.classList.toggle('active', slot.dataset.power === power);
    });
}

function showMessage(text, color) {
    let msg = document.getElementById('message');
    msg.textContent = text;
    msg.style.color = color;
    msg.style.opacity = '1';
    setTimeout(() => { msg.style.opacity = '0'; }, 1500);
}

function updateMinimap() {
    minimapCtx.fillStyle = 'rgba(0,0,0,0.8)';
    minimapCtx.fillRect(0, 0, 150, 150);

    let scale = 0.05;
    let cx = 75;
    let cy = 75;

    // Draw buildings
    minimapCtx.fillStyle = '#444';
    buildings.forEach(b => {
        let bx = cx + (b.x - superman.x) * scale;
        let bz = cy + (b.z - superman.z) * scale;
        if (bx > 0 && bx < 150 && bz > 0 && bz < 150) {
            minimapCtx.fillRect(bx - 2, bz - 2, 4, 4);
        }
    });

    // Draw enemies
    enemies.forEach(e => {
        if (!e.alive) return;
        let ex = cx + (e.x - superman.x) * scale;
        let ez = cy + (e.z - superman.z) * scale;
        if (ex > 0 && ex < 150 && ez > 0 && ez < 150) {
            minimapCtx.fillStyle = e.type === 'kryptonite' ? '#44ff44' : '#ff0000';
            minimapCtx.beginPath();
            minimapCtx.arc(ex, ez, 3, 0, Math.PI * 2);
            minimapCtx.fill();
        }
    });

    // Draw collectibles
    collectibles.forEach(c => {
        if (c.collected) return;
        let cx2 = cx + (c.x - superman.x) * scale;
        let cz = cy + (c.z - superman.z) * scale;
        if (cx2 > 0 && cx2 < 150 && cz > 0 && cz < 150) {
            minimapCtx.fillStyle = c.type === 'health' ? '#ff0000' : '#0088ff';
            minimapCtx.beginPath();
            minimapCtx.arc(cx2, cz, 2, 0, Math.PI * 2);
            minimapCtx.fill();
        }
    });

    // Draw Superman
    minimapCtx.fillStyle = '#0066ff';
    minimapCtx.beginPath();
    minimapCtx.arc(cx, cy, 4, 0, Math.PI * 2);
    minimapCtx.fill();

    // Direction indicator
    minimapCtx.strokeStyle = '#0066ff';
    minimapCtx.lineWidth = 2;
    minimapCtx.beginPath();
    minimapCtx.moveTo(cx, cy);
    minimapCtx.lineTo(cx + Math.sin(camera.rotY) * 10, cy + Math.cos(camera.rotY) * 10);
    minimapCtx.stroke();
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    drawSky();
    drawClouds();
    drawGround();

    // Sort buildings by distance
    let sortedBuildings = buildings.map(b => {
        let dx = b.x - camera.x;
        let dz = b.z - camera.z;
        return { ...b, dist: dx * dx + dz * dz };
    }).sort((a, b) => b.dist - a.dist);

    // Draw buildings
    sortedBuildings.forEach(b => {
        drawCube(b.x, b.y, b.z, b.w, b.h, b.d, b.color);

        // Draw windows
        if (b.windows) {
            let windowSize = 3;
            let windowGap = 8;
            for (let wy = 5; wy < b.h - 5; wy += windowGap) {
                for (let wx = -b.w/2 + 5; wx < b.w/2 - 5; wx += windowGap) {
                    let p1 = project(b.x + wx, b.y + wy, b.z - b.d/2 - 0.1);
                    let p2 = project(b.x + wx, b.y + wy, b.z + b.d/2 + 0.1);
                    if (p1 && p2) {
                        ctx.fillStyle = Math.random() > 0.3 ? b.windowColor : 'rgba(0,0,0,0.5)';
                        ctx.globalAlpha = 0.6;
                        ctx.fillRect(p1.x - windowSize/2, p1.y - windowSize/2, windowSize, windowSize);
                        ctx.globalAlpha = 1;
                    }
                }
            }
        }
    });

    // Draw collectibles
    collectibles.forEach(c => drawCollectible(c));

    // Draw enemies
    let sortedEnemies = enemies.map(e => {
        let dx = e.x - camera.x;
        let dz = e.z - camera.z;
        return { ...e, dist: dx * dx + dz * dz };
    }).sort((a, b) => b.dist - a.dist);

    sortedEnemies.forEach(e => drawEnemy(e));

    // Draw projectiles
    projectiles.forEach(p => drawProjectile(p));

    // Draw particles
    particles.forEach(p => drawParticle(p));

    // Draw Superman
    drawSuperman();

    // Speed effect
    if (superman.isSuperSpeed) {
        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
        ctx.lineWidth = 1;
        for (let i = 0; i < 20; i++) {
            let angle = Math.random() * Math.PI * 2;
            let dist = Math.random() * 500;
            let sx = canvas.width / 2 + Math.cos(angle) * dist;
            let sy = canvas.height / 2 + Math.sin(angle) * dist;
            ctx.beginPath();
            ctx.moveTo(sx, sy);
            ctx.lineTo(sx + Math.cos(angle) * 100, sy + Math.sin(angle) * 100);
            ctx.stroke();
        }
    }
}

function gameLoop() {
    update();
    render();
    requestAnimationFrame(gameLoop);
}

function startGame() {
    document.getElementById('title-screen').style.display = 'none';
    gameRunning = true;
    generateCity();
    spawnEnemies();
    spawnCollectibles();
    gameLoop();
}

function gameOver() {
    gameRunning = false;
    document.getElementById('game-over').style.display = 'flex';
    document.getElementById('final-score').textContent = 'Score: ' + score;
}

function restartGame() {
    superman = {
        x: 0, y: 50, z: 0,
        vx: 0, vy: 0, vz: 0,
        health: 100, maxHealth: 100,
        energy: 100, maxEnergy: 100,
