        }
        #start-screen, #game-over-screen {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            z-index: 100;
            background: radial-gradient(ellipse at center, rgba(0, 20, 60, 0.9) 0%, rgba(0, 0, 0, 0.95) 100%);
        }
        #game-over-screen {
            display: none;
        }
        .game-title {
            font-size: 72px;
            font-weight: 900;
            background: linear-gradient(135deg, #00d4ff, #7b2fff, #ff006e);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            text-shadow: none;
            margin-bottom: 10px;
            letter-spacing: 4px;
            animation: titlePulse 3s ease-in-out infinite;
        }
        @keyframes titlePulse {
            0%, 100% { transform: scale(1); filter: brightness(1); }
            50% { transform: scale(1.05); filter: brightness(1.2); }
        }
        .game-subtitle {
            font-size: 18px;
            color: rgba(0, 200, 255, 0.6);
            letter-spacing: 8px;
            text-transform: uppercase;
            margin-bottom: 50px;
        }
        .owner-credit {
            font-size: 16px;
            color: rgba(255, 200, 50, 0.8);
            letter-spacing: 3px;
            margin-bottom: 40px;
            text-transform: uppercase;
        }
        .owner-credit span {
            color: #ffd700;
            font-weight: bold;
            font-size: 20px;
        }
        .btn {
            pointer-events: all;
            padding: 18px 60px;
            font-size: 20px;
            font-weight: bold;
            letter-spacing: 3px;
            text-transform: uppercase;
            border: 2px solid #00d4ff;
            background: rgba(0, 100, 200, 0.2);
            color: #00d4ff;
            border-radius: 50px;
            cursor: pointer;
            transition: all 0.3s ease;
            margin: 10px;
        }
        .btn:hover {
            background: rgba(0, 150, 255, 0.4);
            box-shadow: 0 0 30px rgba(0, 150, 255, 0.5);
            transform: scale(1.05);
        }
        .controls-info {
            margin-top: 40px;
            color: rgba(255, 255, 255, 0.4);
            font-size: 14px;
            text-align: center;
            line-height: 2;
        }
        .controls-info kbd {
            background: rgba(255, 255, 255, 0.1);
            padding: 4px 12px;
            border-radius: 5px;
            border: 1px solid rgba(255, 255, 255, 0.2);
            color: rgba(255, 255, 255, 0.7);
        }
        #final-score {
            font-size: 48px;
            color: #ffd700;
            font-weight: bold;
            margin: 20px 0;
        }
        #final-wave {
            font-size: 24px;
            color: #00d4ff;
            margin-bottom: 30px;
        }
        .particle-container {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            z-index: 5;
        }
        #minimap {
            position: fixed;
            bottom: 20px;
            right: 20px;
            width: 150px;
            height: 150px;
            border: 1px solid rgba(0, 150, 255, 0.3);
            border-radius: 50%;
            background: rgba(0, 10, 30, 0.7);
            z-index: 20;
            pointer-events: none;
        }
        .wave-announcement {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            font-size: 48px;
            font-weight: 900;
            color: #ffd700;
            text-shadow: 0 0 20px rgba(255, 200, 0, 0.5);
            z-index: 50;
            pointer-events: none;
            opacity: 0;
            transition: opacity 0.5s ease;
        }
        .wave-announcement.show {
            opacity: 1;
            animation: waveAnnounce 2s ease-out forwards;
        }
        @keyframes waveAnnounce {
            0% { transform: translate(-50%, -50%) scale(0.5); opacity: 0; }
            20% { transform: translate(-50%, -50%) scale(1.2); opacity: 1; }
            80% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
            100% { transform: translate(-50%, -50%) scale(1); opacity: 0; }
        }
    </style>
</head>
<body>
    <div id="hud">
        <div class="hud-panel">
            <div class="hud-label">Score</div>
            <div class="hud-value" id="score-display">0</div>
        </div>
        <div class="hud-panel" style="text-align: center;">
            <div class="hud-label">Wave</div>
            <div class="hud-value" id="wave-display">1</div>
        </div>
        <div class="hud-panel" style="text-align: right;">
            <div class="hud-label">Health</div>
            <div class="hud-value" id="health-display">100</div>
            <div id="health-bar-container">
                <div id="health-bar"></div>
            </div>
        </div>
    </div>

    <div id="start-screen">
        <div class="game-title">COSMIC DEFENDER</div>
        <div class="game-subtitle">Protect the Galaxy</div>
        <div class="owner-credit">Game Owner: <span>Noor Alam</span></div>
        <button class="btn" id="start-btn">Start Mission</button>
        <div class="controls-info">
            <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> or <kbd>↑</kbd> <kbd>←</kbd> <kbd>↓</kbd> <kbd>→</kbd> to move<br>
            <kbd>SPACE</kbd> to shoot &nbsp;|&nbsp; <kbd>SHIFT</kbd> for boost
        </div>
    </div>

    <div id="game-over-screen">
        <div class="game-title" style="font-size: 48px;">MISSION FAILED</div>
        <div id="final-score">0</div>
        <div id="final-wave">Wave 1</div>
        <div class="owner-credit">Game Owner: <span>Noor Alam</span></div>
        <button class="btn" id="restart-btn">Try Again</button>
    </div>

    <div class="wave-announcement" id="wave-announcement"></div>

    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
    <script>
        // Game State
        const gameState = {
            running: false,
            score: 0,
            health: 100,
            wave: 1,
            enemiesKilled: 0,
            enemiesPerWave: 5,
            playerSpeed: 0.3,
            boostSpeed: 0.6,
            isBoosting: false,
            bullets: [],
            enemies: [],
            particles: [],
            stars: [],
            powerUps: [],
            lastShot: 0,
            shotCooldown: 150,
            enemySpawnTimer: 0,
            enemySpawnInterval: 120,
            difficultyMultiplier: 1
        };

        // Three.js Setup
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x334466, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(10, 20, 10);
        directionalLight.castShadow = true;
        scene.add(directionalLight);

        const pointLight1 = new THREE.PointLight(0x00d4ff, 2, 50);
        pointLight1.position.set(-10, 5, 0);
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0xff006e, 2, 50);
        pointLight2.position.set(10, -5, 0);
        scene.add(pointLight2);

        // Star Field
        function createStarField() {
            const starGeometry = new THREE.BufferGeometry();
            const starCount = 5000;
            const positions = new Float32Array(starCount * 3);
            const colors = new Float32Array(starCount * 3);
            const sizes = new Float32Array(starCount);

            for (let i = 0; i < starCount; i++) {
                positions[i * 3] = (Math.random() - 0.5) * 200;
                positions[i * 3 + 1] = (Math.random() - 0.5) * 200;
                positions[i * 3 + 2] = (Math.random() - 0.5) * 200;

                const color = new THREE.Color();
                color.setHSL(Math.random() * 0.2 + 0.5, 0.8, Math.random() * 0.5 + 0.5);
                colors[i * 3] = color.r;
                colors[i * 3 + 1] = color.g;
                colors[i * 3 + 2] = color.b;

                sizes[i] = Math.random() * 2 + 0.5;
            }

            starGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
            starGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
            starGeometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

            const starMaterial = new THREE.PointsMaterial({
                size: 0.5,
                vertexColors: true,
                transparent: true,
                opacity: 0.8,
                sizeAttenuation: true
            });

            const starField = new THREE.Points(starGeometry, starMaterial);
            scene.add(starField);
            return starField;
        }

        const starField = createStarField();

        // Player Ship
        function createPlayerShip() {
            const group = new THREE.Group();

            // Main body
            const bodyGeometry = new THREE.ConeGeometry(0.5, 2, 8);
            const bodyMaterial = new THREE.MeshPhongMaterial({
                color: 0x00d4ff,
                emissive: 0x004466,
                shininess: 100,
                flatShading: true
            });
            const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
            body.rotation.x = Math.PI / 2;
            body.castShadow = true;
            group.add(body);

            // Wings
            const wingGeometry = new THREE.BoxGeometry(2.5, 0.1, 0.8);
            const wingMaterial = new THREE.MeshPhongMaterial({
                color: 0x0088cc,
                emissive: 0x003344,
                shininess: 80
            });
            const wings = new THREE.Mesh(wingGeometry, wingMaterial);
            wings.position.z = 0.3;
            wings.castShadow = true;
            group.add(wings);

            // Wing tips
            const tipGeometry = new THREE.ConeGeometry(0.15, 0.5, 4);
            const tipMaterial = new THREE.MeshPhongMaterial({
                color: 0xff006e,
                emissive: 0x660033
            });

            const leftTip = new THREE.Mesh(tipGeometry, tipMaterial);
            leftTip.position.set(-1.2, 0, 0.5);
            leftTip.rotation.z = Math.PI / 2;
            group.add(leftTip);

            const rightTip = new THREE.Mesh(tipGeometry, tipMaterial);
            rightTip.position.set(1.2, 0, 0.5);
            rightTip.rotation.z = -Math.PI / 2;
            group.add(rightTip);

            // Engine glow
            const engineGeometry = new THREE.SphereGeometry(0.3, 8, 8);
            const engineMaterial = new THREE.MeshBasicMaterial({
                color: 0x00d4ff,
                transparent: true,
                opacity: 0.8
            });
            const engine = new THREE.Mesh(engineGeometry, engineMaterial);
            engine.position.z = 1;
            group.add(engine);

            // Engine light
            const engineLight = new THREE.PointLight(0x00d4ff, 1, 5);
            engineLight.position.z = 1;
            group.add(engineLight);

            group.position.set(0, 0, 0);
            return group;
        }

        const playerShip = createPlayerShip();
        scene.add(playerShip);

        // Enemy Ship Creator
        function createEnemyShip(type = 'basic') {
            const group = new THREE.Group();
            let color, emissive, size;

            switch(type) {
                case 'basic':
                    color = 0xff006e;
                    emissive = 0x660033;
                    size = 1;
                    break;
                case 'fast':
                    color = 0xff6600;
                    emissive = 0x663300;
                    size = 0.8;
                    break;
                case 'tank':
                    color = 0x9900ff;
                    emissive = 0x440066;
                    size = 1.3;
                    break;
                default:
                    color = 0xff006e;
                    emissive = 0x660033;
                    size = 1;
            }

            // Body
            const bodyGeometry = new THREE.DodecahedronGeometry(size, 0);
            const bodyMaterial = new THREE.MeshPhongMaterial({
                color: color,
                emissive: emissive,
                shininess: 60,
                flatShading: true
            });
            const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
            body.castShadow = true;
            group.add(body);

            // Rotating ring
            const ringGeometry = new THREE.TorusGeometry(size * 1.2, 0.1, 8, 16);
            const ringMaterial = new THREE.MeshBasicMaterial({
                color: color,
                transparent: true,
                opacity: 0.5
            });
            const ring = new THREE.Mesh(ringGeometry, ringMaterial);
            group.add(ring);

            // Enemy light
            const enemyLight = new THREE.PointLight(color, 0.5, 5);
            group.add(enemyLight);

            return group;
        }

        // Bullet Creator
        function createBullet(position, direction) {
            const geometry = new THREE.CylinderGeometry(0.05, 0.05, 0.5, 8);
            const material = new THREE.MeshBasicMaterial({
                color: 0x00ff88,
                transparent: true,
                opacity: 0.9
            });
            const bullet = new THREE.Mesh(geometry, material);
            bullet.position.copy(position);
            bullet.rotation.x = Math.PI / 2;

            const light = new THREE.PointLight(0x00ff88, 0.5, 3);
            bullet.add(light);

            return bullet;
        }

        // Explosion Particle System
        function createExplosion(position, color = 0xff6600, count = 20) {
            for (let i = 0; i < count; i++) {
                const geometry = new THREE.SphereGeometry(0.1, 4, 4);
                const material = new THREE.MeshBasicMaterial({
                    color: color,
                    transparent: true,
                    opacity: 1
                });
                const particle = new THREE.Mesh(geometry, material);
                particle.position.copy(position);

                const velocity = new THREE.Vector3(
                    (Math.random() - 0.5) * 0.5,
                    (Math.random() - 0.5) * 0.5,
                    (Math.random() - 0.5) * 0.5
                );

                scene.add(particle);
                gameState.particles.push({
                    mesh: particle,
                    velocity: velocity,
                    life: 1,
                    decay: 0.02 + Math.random() * 0.03
                });
            }
        }

        // Power-up Creator
        function createPowerUp(position, type) {
            const geometry = new THREE.OctahedronGeometry(0.3, 0);
            const colors = { health: 0x00ff88, speed: 0x00d4ff, shield: 0xffd700 };
            const material = new THREE.MeshPhongMaterial({
                color: colors[type] || 0x00ff88,
                emissive: colors[type] || 0x00ff88,
                emissiveIntensity: 0.5,
                transparent: true,
                opacity: 0.8
            });
            const powerUp = new THREE.Mesh(geometry, material);
            powerUp.position.copy(position);

            const light = new THREE.PointLight(colors[type] || 0x00ff88, 1, 5);
            powerUp.add(light);

            scene.add(powerUp);
            return { mesh: powerUp, type: type, time: 0 };
        }

        // Input Handling
        const keys = {};
        document.addEventListener('keydown', (e) => {
            keys[e.code] = true;
            if (e.code === 'Space') e.preventDefault();
        });
        document.addEventListener('keyup', (e) => {
            keys[e.code] = false;
        });

        // Mouse/Touch control for mobile
        let mouseX = 0, mouseY = 0;
        document.addEventListener('mousemove', (e) => {
            mouseX = (e.clientX / window.innerWidth) * 2 - 1;
            mouseY = -(e.clientY / window.innerHeight) * 2 + 1;
        });

        // Collision Detection
        function checkCollision(obj1, obj2, distance = 1.5) {
            const dist = obj1.position.distanceTo(obj2.position);
            return dist < distance;
        }

        // Spawn Enemy
        function spawnEnemy() {
            const types = ['basic', 'basic', 'basic', 'fast', 'tank'];
            const type = types[Math.floor(Math.random() * types.length)];
            const enemy = createEnemyShip(type);

            const angle = Math.random() * Math.PI * 2;
            const radius = 30 + Math.random() * 20;
            enemy.position.set(
                Math.cos(angle) * radius,
                Math.sin(angle) * radius,
                -20 - Math.random() * 30
            );

            const speed = type === 'fast' ? 0.15 : type === 'tank' ? 0.05 : 0.08;
            scene.add(enemy);
            gameState.enemies.push({
                mesh: enemy,
                type: type,
                speed: speed * gameState.difficultyMultiplier,
                health: type === 'tank' ? 3 : 1,
                rotationSpeed: (Math.random() - 0.5) * 0.05
            });
        }

        // Shoot Bullet
        function shoot() {
            const now = Date.now();
            if (now - gameState.lastShot < gameState.shotCooldown) return;
            gameState.lastShot = now;

            const bullet = createBullet(
                playerShip.position.clone().add(new THREE.Vector3(0, 0, -1.5)),
                new THREE.Vector3(0, 0, -1)
            );
            scene.add(bullet);
            gameState.bullets.push({
                mesh: bullet,
                velocity: new THREE.Vector3(0, 0, -1),
                life: 100
            });

            // Muzzle flash
            createExplosion(
                playerShip.position.clone().add(new THREE.Vector3(0, 0, -1.5)),
                0x00ff88,
                5
            );
        }

        // Update HUD
        function updateHUD() {
            document.getElementById('score-display').textContent = gameState.score;
            document.getElementById('wave-display').textContent = gameState.wave;
            document.getElementById('health-display').textContent = Math.max(0, Math.round(gameState.health));
            document.getElementById('health-bar').style.width = Math.max(0, gameState.health) + '%';
        }

        // Wave Announcement
        function announceWave(wave) {
            const el = document.getElementById('wave-announcement');
            el.textContent = `WAVE ${wave}`;
            el.classList.remove('show');
            void el.offsetWidth;
            el.classList.add('show');
        }

        // Game Over
        function gameOver() {
            gameState.running = false;
            document.getElementById('game-over-screen').style.display = 'flex';
            document.getElementById('final-score').textContent = gameState.score;
            document.getElementById('final-wave').textContent = `Wave ${gameState.wave}`;
        }

        // Reset Game
        function resetGame() {
            gameState.score = 0;
            gameState.health = 100;
            gameState.wave = 1;
            gameState.enemiesKilled = 0;
            gameState.enemiesPerWave = 5;
            gameState.difficultyMultiplier = 1;
            gameState.bullets = [];
            gameState.enemies = [];
            gameState.particles = [];
            gameState.powerUps = [];
            gameState.enemySpawnTimer = 0;

            playerShip.position.set(0, 0, 0);

            // Remove all enemies and bullets from scene
            gameState.enemies.forEach(e => scene.remove(e.mesh));
            gameState.bullets.forEach(b => scene.remove(b.mesh));
            gameState.particles.forEach(p => scene.remove(p.mesh));
            gameState.powerUps.forEach(p => scene.remove(p.mesh));

            updateHUD();
            announceWave(1);
        }

        // Start Game
        function startGame() {
            document.getElementById('start-screen').style.display = 'none';
            document.getElementById('game-over-screen').style.display = 'none';
            resetGame();
            gameState.running = true;
        }

        // Event Listeners
        document.getElementById('start-btn').addEventListener('click', startGame);
        document.getElementById('restart-btn').addEventListener('click', startGame);

        // Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Main Game Loop
        function animate() {
            requestAnimationFrame(animate);

            if (!gameState.running) {
                // Rotate star field slowly when not playing
                starField.rotation.y += 0.0005;
                renderer.render(scene, camera);
                return;
            }

            // Player Movement
            const speed = keys['ShiftLeft'] || keys['ShiftRight'] ? gameState.boostSpeed : gameState.playerSpeed;
            let moveX = 0, moveY = 0;

            if (keys['KeyA'] || keys['ArrowLeft']) moveX = -1;
            if (keys['KeyD'] || keys['ArrowRight']) moveX = 1;
            if (keys['KeyW'] || keys['ArrowUp']) moveY = 1;
            if (keys['KeyS'] || keys['ArrowDown']) moveY = -1;

            playerShip.position.x += moveX * speed;
            playerShip.position.y += moveY * speed;

            // Clamp player position
            playerShip.position.x = Math.max(-15, Math.min(15, playerShip.position.x));
            playerShip.position.y = Math.max(-10, Math.min(10, playerShip.position.y));

            // Tilt ship based on movement
            playerShip.rotation.z = -moveX * 0.3;
            playerShip.rotation.x = moveY * 0.2;

            // Shooting
            if (keys['Space']) {
                shoot();
            }

            // Update Bullets
            for (let i = gameState.bullets.length - 1; i >= 0; i--) {
                const bullet = gameState.bullets[i];
                bullet.mesh.position.add(bullet.velocity.clone().multiplyScalar(1.5));
                bullet.life--;

                if (bullet.life <= 0 || bullet.mesh.position.z < -50) {
                    scene.remove(bullet.mesh);
                    gameState.bullets.splice(i, 1);
                }
            }

            // Spawn Enemies
            gameState.enemySpawnTimer++;
            if (gameState.enemySpawnTimer >= gameState.enemySpawnInterval) {
                gameState.enemySpawnTimer = 0;
                spawnEnemy();
            }

            // Update Enemies
            for (let i = gameState.enemies.length - 1; i >= 0; i--) {
                const enemy = gameState.enemies[i];
                const dir = playerShip.position.clone().sub(enemy.mesh.position).normalize();
                enemy.mesh.position.add(dir.multiplyScalar(enemy.speed));
                enemy.mesh.rotation.y += enemy.rotationSpeed;
                enemy.mesh.rotation.x += enemy.rotationSpeed * 0.5;

                // Check collision with player
                if (checkCollision(enemy.mesh, playerShip, 1.5)) {
                    gameState.health -= 20;
                    createExplosion(enemy.mesh.position, 0xff006e, 15);
                    scene.remove(enemy.mesh);
                    gameState.enemies.splice(i, 1);
                    updateHUD();

                    if (gameState.health <= 0) {
                        createExplosion(playerShip.position, 0x00d4ff, 50);
                        gameOver();
                    }
                    continue;
                }

                // Check collision with bullets
                for (let j = gameState.bullets.length - 1; j >= 0; j--) {
                    if (checkCollision(enemy.mesh, gameState.bullets[j].mesh, 1.2)) {
                        enemy.health--;
                        createExplosion(gameState.bullets[j].mesh.position, 0x00ff88, 8);
                        scene.remove(gameState.bullets[j].mesh);
                        gameState.bullets.splice(j, 1);

                        if (enemy.health <= 0) {
                            createExplosion(enemy.mesh.position, 0xff6600, 25);
                            scene.remove(enemy.mesh);
                            gameState.enemies.splice(i, 1);
                            gameState.score += enemy.type === 'tank' ? 30 : enemy.type === 'fast' ? 20 : 10;
                            gameState.enemiesKilled++;
                            updateHUD();

                            // Chance to drop power-up
                            if (Math.random() < 0.15) {
                                const types = ['health', 'speed', 'shield'];
                                const type = types[Math.floor(Math.random() * types.length)];
                                gameState.powerUps.push(createPowerUp(enemy.mesh.position.clone(), type));
                            }

                            // Check wave completion
                            if (gameState.enemiesKilled >= gameState.enemiesPerWave) {
                                gameState.wave++;
                                gameState.enemiesKilled = 0;
                                gameState.enemiesPerWave = Math.floor(5 + gameState.wave * 2);
                                gameState.difficultyMultiplier += 0.15;
                                gameState.enemySpawnInterval = Math.max(30, 120 - gameState.wave * 5);
                                announceWave(gameState.wave);
                                updateHUD();
                            }
                        }
                        break;
                    }
                }

                // Remove enemies that are too far
                if (enemy.mesh.position.distanceTo(playerShip.position) > 60) {
                    scene.remove(enemy.mesh);
                    gameState.enemies.splice(i, 1);
                }
            }

            // Update Particles
            for (let i = gameState.particles.length - 1; i >= 0; i--) {
                const particle = gameState.particles[i];
                particle.mesh.position.add(particle.velocity);
                particle.life -= particle.decay;
                particle.mesh.material.opacity = particle.life;
                particle.mesh.scale.setScalar(particle.life);

                if (particle.life <= 0) {
                    scene.remove(particle.mesh);
                    gameState.particles.splice(i, 1);
                }
            }

            // Update Power-ups
            for (let i = gameState.powerUps.length - 1; i >= 0; i--) {
                const powerUp = gameState.powerUps[i];
                powerUp.time += 0.05;
                powerUp.mesh.rotation.y += 0.05;
                powerUp.mesh.rotation.x += 0.03;
                powerUp.mesh.position.y += Math.sin(powerUp.time) * 0.02;

                if (checkCollision(powerUp.mesh, playerShip, 1.5)) {
                    switch(powerUp.type) {
                        case 'health':
                            gameState.health = Math.min(100, gameState.health + 30);
                            break;
                        case 'speed':
                            gameState.playerSpeed = 0.5;
                            setTimeout(() => { gameState.playerSpeed = 0.3; }, 5000);
                            break;
                        case 'shield':
                            gameState.health = Math.min(100, gameState.health + 50);
                            break;
                    }
                    createExplosion(powerUp.mesh.position, 0x00ff88, 10);
                    scene.remove(powerUp.mesh);
                    gameState.powerUps.splice(i, 1);
                    updateHUD();
                    continue;
                }

                // Remove old power-ups
                powerUp.time += 0.016;
                if (powerUp.time > 10) {
                    scene.remove(powerUp.mesh);
                    gameState.powerUps.splice(i, 1);
                }
            }

            // Rotate star field
            starField.rotation.y += 0.0002;
            starField.rotation.x += 0.0001;

            // Camera follow
            camera.position.lerp(new THREE.Vector3(
                playerShip.position.x * 0.3,
                playerShip.position.y * 0.3 + 5,
                playerShip.position.z + 10
            ), 0.05);
            camera.lookAt(playerShip.position);

            // Animate lights
            pointLight1.position.x = Math.sin(Date.now() * 0.001) * 10;
            pointLight1.position.z = Math.cos(Date.now() * 0.001) * 10;
            pointLight2.position.x = Math.cos(Date.now() * 0.001) * 10;
            pointLight2.position.z = Math.sin(Date.now() * 0.001) * 10;

            renderer.render(scene, camera);
        }

        // Start the animation loop
        animate();
    </script>
