    <canvas id="handCanvas"></canvas>

    <div id="gestureIndicator">
        <h3>🖐️ Gesture</h3>
        <div id="gestureName">Waiting...</div>
        <div id="gestureDescription">Show your hand to the camera</div>
    </div>

    <div id="gameOver">
        <h2>GAME OVER</h2>
        <div id="finalScore">Score: 0</div>
        <button id="restartBtn" onclick="restartGame()">PLAY AGAIN</button>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/hands.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/@mediapipe/camera_utils@0.3.1675466862/camera_utils.js"></script>
    <script>
        // Game constants
        const COLS = 10;
        const ROWS = 20;
        const BLOCK_SIZE = 35;
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const handCanvas = document.getElementById('handCanvas');
        const handCtx = handCanvas.getContext('2d');

        // Game state
        let board = [];
        let score = 0;
        let level = 1;
        let lines = 0;
        let gameOver = false;
        let gameStarted = false;
        let dropCounter = 0;
        let dropInterval = 1000;
        let lastTime = 0;
        let animationId = null;

        // Piece definitions
        const PIECES = [
            { shape: [[1,1,1,1]], color: '#00f0f0' }, // I
            { shape: [[1,1],[1,1]], color: '#f0f000' }, // O
            { shape: [[0,1,0],[1,1,1]], color: '#a000f0' }, // T
            { shape: [[1,0,0],[1,1,1]], color: '#0000f0' }, // L
            { shape: [[0,0,1],[1,1,1]], color: '#f0a000' }, // J
            { shape: [[0,1,1],[1,1,0]], color: '#00f000' }, // S
            { shape: [[1,1,0],[0,1,1]], color: '#f00000' }  // Z
        ];

        let currentPiece = null;
        let pieceX = 0;
        let pieceY = 0;

        // Gesture state
        let handPosition = { x: 0.5, y: 0.5 };
        let isHandDetected = false;
        let handOpenness = 0;
        let prevOpenness = 0;
        let opennessChange = 0;
        let lastGestureTime = 0;
        let gestureCooldown = false;

        // Initialize board
        function initBoard() {
            board = [];
            for (let y = 0; y < ROWS; y++) {
                board[y] = [];
                for (let x = 0; x < COLS; x++) {
                    board[y][x] = null;
                }
            }
        }

        // Create new piece
        function createPiece() {
            const piece = PIECES[Math.floor(Math.random() * PIECES.length)];
            return {
                shape: piece.shape.map(row => [...row]),
                color: piece.color,
                x: Math.floor(COLS / 2) - Math.floor(piece.shape[0].length / 2),
                y: 0
            };
        }

        // Rotate piece
        function rotatePiece(piece) {
            const rotated = piece.shape[0].map((_, i) =>
                piece.shape.map(row => row[i]).reverse()
            );
            return rotated;
        }

        // Check collision
        function collides(piece, offsetX = 0, offsetY = 0, newShape = null) {
            const shape = newShape || piece.shape;
            for (let y = 0; y < shape.length; y++) {
                for (let x = 0; x < shape[y].length; x++) {
                    if (shape[y][x]) {
                        const newX = piece.x + x + offsetX;
                        const newY = piece.y + y + offsetY;
                        if (newX < 0 || newX >= COLS || newY >= ROWS) return true;
                        if (newY >= 0 && board[newY][newX]) return true;
                    }
                }
            }
            return false;
        }

        // Lock piece
        function lockPiece() {
            for (let y = 0; y < currentPiece.shape.length; y++) {
                for (let x = 0; x < currentPiece.shape[y].length; x++) {
                    if (currentPiece.shape[y][x]) {
                        const boardY = pieceY + y;
                        const boardX = pieceX + x;
                        if (boardY < 0) {
                            gameOver = true;
                            return;
                        }
                        board[boardY][boardX] = currentPiece.color;
                    }
                }
            }
            clearLines();
            currentPiece = createPiece();
            pieceX = currentPiece.x;
            pieceY = currentPiece.y;
            if (collides(currentPiece)) {
                gameOver = true;
            }
        }

        // Clear lines
        function clearLines() {
            let linesCleared = 0;
            for (let y = ROWS - 1; y >= 0; y--) {
                if (board[y].every(cell => cell !== null)) {
                    board.splice(y, 1);
                    const newRow = [];
                    for (let x = 0; x < COLS; x++) newRow.push(null);
                    board.unshift(newRow);
                    linesCleared++;
                    y++;
                }
            }
            if (linesCleared > 0) {
                lines += linesCleared;
                score += linesCleared * 100 * level;
                if (linesCleared === 4) score += 400 * level; // Tetris bonus
                level = Math.floor(lines / 10) + 1;
                dropInterval = Math.max(100, 1000 - (level - 1) * 80);
                updateUI();
            }
        }

        // Update UI
        function updateUI() {
            document.getElementById('score').textContent = score;
            document.getElementById('level').textContent = `Level ${level}`;
            document.getElementById('lines').textContent = `Lines: ${lines}`;
        }

        // Draw block
        function drawBlock(x, y, color, size = BLOCK_SIZE) {
            const px = x * size;
            const py = y * size;

            // Main block
            ctx.fillStyle = color;
            ctx.fillRect(px + 1, py + 1, size - 2, size - 2);

            // Highlight
            ctx.fillStyle = 'rgba(255,255,255,0.3)';
            ctx.fillRect(px + 1, py + 1, size - 2, 3);
            ctx.fillRect(px + 1, py + 1, 3, size - 2);

            // Shadow
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.fillRect(px + size - 3, py + 1, 2, size - 2);
            ctx.fillRect(px + 1, py + size - 3, size - 2, 2);
        }

        // Draw board
        function draw() {
            // Clear
            ctx.fillStyle = '#1a1a3e';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Grid
            ctx.strokeStyle = 'rgba(74, 144, 217, 0.1)';
            ctx.lineWidth = 1;
            for (let x = 0; x <= COLS; x++) {
                ctx.beginPath();
                ctx.moveTo(x * BLOCK_SIZE, 0);
                ctx.lineTo(x * BLOCK_SIZE, canvas.height);
                ctx.stroke();
            }
            for (let y = 0; y <= ROWS; y++) {
                ctx.beginPath();
                ctx.moveTo(0, y * BLOCK_SIZE);
                ctx.lineTo(canvas.width, y * BLOCK_SIZE);
                ctx.stroke();
            }

            // Draw locked blocks
            for (let y = 0; y < ROWS; y++) {
                for (let x = 0; x < COLS; x++) {
                    if (board[y][x]) {
                        drawBlock(x, y, board[y][x]);
                    }
                }
            }

            // Draw ghost piece
            if (currentPiece) {
                let ghostY = pieceY;
                while (!collides(currentPiece, 0, ghostY - pieceY + 1)) {
                    ghostY++;
                }
                ctx.globalAlpha = 0.2;
                for (let y = 0; y < currentPiece.shape.length; y++) {
                    for (let x = 0; x < currentPiece.shape[y].length; x++) {
                        if (currentPiece.shape[y][x]) {
                            drawBlock(pieceX + x, ghostY + y, currentPiece.color);
                        }
                    }
                }
                ctx.globalAlpha = 1;

                // Draw current piece
                for (let y = 0; y < currentPiece.shape.length; y++) {
                    for (let x = 0; x < currentPiece.shape[y].length; x++) {
                        if (currentPiece.shape[y][x]) {
                            drawBlock(pieceX + x, pieceY + y, currentPiece.color);
                        }
                    }
                }
            }
        }

        // Game loop
        function gameLoop(time = 0) {
            if (gameOver) {
                document.getElementById('finalScore').textContent = `Score: ${score}`;
                document.getElementById('gameOver').style.display = 'flex';
                return;
            }

            const deltaTime = time - lastTime;
            lastTime = time;
            dropCounter += deltaTime;

            if (dropCounter > dropInterval) {
                if (!collides(currentPiece, 0, 1)) {
                    pieceY++;
                } else {
                    lockPiece();
                }
                dropCounter = 0;
            }

            draw();
            animationId = requestAnimationFrame(gameLoop);
        }

        // Move piece
        function movePiece(dx, dy) {
            if (!collides(currentPiece, dx, dy)) {
                pieceX += dx;
                pieceY += dy;
                return true;
            }
            return false;
        }

        // Rotate piece
        function rotatePieceHandler() {
            if (gestureCooldown) return;
            const rotated = rotatePiece(currentPiece);
            if (!collides(currentPiece, 0, 0, rotated)) {
                currentPiece.shape = rotated;
            } else if (!collides(currentPiece, -1, 0, rotated)) {
                currentPiece.shape = rotated;
                pieceX -= 1;
            } else if (!collides(currentPiece, 1, 0, rotated)) {
                currentPiece.shape = rotated;
                pieceX += 1;
            }
            gestureCooldown = true;
            setTimeout(() => gestureCooldown = false, 150);
        }

        // Hard drop
