                    [0,5],[5,6],[6,7],[7,8],
                    [0,9],[9,10],[10,11],[11,12],
                    [0,13],[13,14],[14,15],[15,16],
                    [0,17],[17,18],[18,19],[19,20],
                    [5,9],[9,13],[13,17]
                ];

                connections.forEach(([i, j]) => {
                    const x1 = landmarks[i].x * 220;
                    const y1 = landmarks[i].y * 165;
                    const x2 = landmarks[j].x * 220;
                    const y2 = landmarks[j].y * 165;
                    handCtx.beginPath();
                    handCtx.moveTo(x1, y1);
                    handCtx.lineTo(x2, y2);
                    handCtx.stroke();
                });

                landmarks.forEach((landmark, i) => {
                    const x = landmark.x * 220;
                    const y = landmark.y * 165;
                    handCtx.beginPath();
                    handCtx.arc(x, y, 4, 0, Math.PI * 2);
                    handCtx.fill();
