            // Open hand detection
            if (openness > 0.3) {
                gestureName.textContent = '🖐️ Open Hand';
                gestureName.style.color = '#00ff00';
                gestureDesc.textContent = 'Move hand to control';
            }

            // Quick open/close for rotation
            if (change > 0.15 && Date.now() - lastGestureTime > 200) {
                gestureName.textContent = '🔄 Rotate!';
                gestureName.style.color = '#ffaa00';
                gestureDesc.textContent = 'Piece rotated!';
                rotatePieceHandler();
                lastGestureTime = Date.now();
                return;
            }

            // Movement based on hand position
            if (handPosition.x < 0.3) {
