                    <p style="color: #ff4444; font-size: 24px;">Camera access denied!</p>
                    <p style="color: #888; margin-top: 10px;">Please allow camera access and refresh.</p>
                    <button onclick="location.reload()" style="margin-top: 20px; padding: 10px 30px; font-size: 18px; background: #4a90d9; border: none; border-radius: 25px; color: white; cursor: pointer;">Retry</button>
                `;
            }
        }

        // Start game
