/* Animations */
.card-enter { animation: cardEnter 0.3s ease-out; }
@keyframes cardEnter { from { transform: translateY(50px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

.shake { animation: shake 0.5s; }
@keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px); } 75% { transform: translateX(5px); } }

.glow { animation: glow 1s infinite alternate; }
@keyframes glow { from { box-shadow: 0 0 5px #ffd700; } to { box-shadow: 0 0 20px #ffd700; } }

/* Rank badges */
.rank-badge {
  display: inline-block; padding: 3px 8px; border-radius: 12px;
  font-size: 0.7em; font-weight: 700;
}
.rank-bronze { background: #cd7f32; color: #fff; }
.rank-silver { background: #c0c0c0; color: #000; }
.rank-gold { background: #ffd700; color: #000; }
.rank-special { background: linear-gradient(135deg, #ff00ff, #8800ff); color: #fff; }

/* Energy popup */
.energy-popup {
  position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);
  background: rgba(0,0,0,0.95); padding: 30px; border-radius: 16px;
  border: 2px solid #ffd700; text-align: center; z-index: 200;
  display: none;
}
.energy-popup.active { display: block; }
.energy-popup h3 { color: #ffd700; margin-bottom: 10px; }
.energy-popup p { color: #8899aa; margin-bottom: 20px; font-size: 0.9em; }
</style>
</head>
