            --bg-card: #12121a;
            --accent: #6c5ce7;
            --accent-light: #a29bfe;
            --accent-glow: rgba(108, 92, 231, 0.3);
            --text-primary: #ffffff;
            --text-secondary: #8888aa;
            --success: #00b894;
            --warning: #fdcb6e;
            --danger: #e17055;
        }

        body {
            font-family: 'Inter', sans-serif;
            background: var(--bg-dark);
            color: var(--text-primary);
            overflow-x: hidden;
            min-height: 100vh;
        }

        /* Particle Background */
        #particles-canvas {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 0;
            pointer-events: none;
        }

        /* Navigation */
        .nav {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            z-index: 100;
            padding: 20px 40px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            backdrop-filter: blur(20px);
            background: rgba(10, 10, 15, 0.8);
            border-bottom: 1px solid rgba(108, 92, 231, 0.1);
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 900;
            background: linear-gradient(135deg, var(--accent), var(--accent-light));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            letter-spacing: -1px;
        }

        .nav-links {
            display: flex;
            gap: 30px;
            list-style: none;
        }

        .nav-links a {
            color: var(--text-secondary);
            text-decoration: none;
            font-size: 0.9rem;
            font-weight: 400;
            transition: color 0.3s;
        }

        .nav-links a:hover {
            color: var(--text-primary);
        }

        /* Hero Section */
        .hero {
            position: relative;
            z-index: 1;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            padding: 120px 20px 80px;
        }

        .hero-badge {
            display: inline-block;
            padding: 8px 20px;
            border: 1px solid var(--accent);
            border-radius: 50px;
            font-size: 0.8rem;
            color: var(--accent-light);
            margin-bottom: 30px;
            animation: fadeInUp 0.8s ease-out;
            background: rgba(108, 92, 231, 0.1);
        }

        .hero h1 {
            font-size: clamp(2.5rem, 6vw, 5rem);
            font-weight: 900;
            line-height: 1.1;
            margin-bottom: 20px;
            animation: fadeInUp 0.8s ease-out 0.2s both;
            max-width: 800px;
        }

        .hero h1 .highlight {
            background: linear-gradient(135deg, var(--accent), var(--accent-light), var(--success));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .hero p {
            font-size: 1.2rem;
            color: var(--text-secondary);
            max-width: 600px;
            line-height: 1.6;
            margin-bottom: 40px;
            animation: fadeInUp 0.8s ease-out 0.4s both;
        }

        .cta-button {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 16px 40px;
            background: linear-gradient(135deg, var(--accent), #8b7cf7);
            color: white;
            text-decoration: none;
            border-radius: 50px;
            font-size: 1rem;
            font-weight: 600;
            border: none;
            cursor: pointer;
            transition: all 0.3s;
            animation: fadeInUp 0.8s ease-out 0.6s both;
            box-shadow: 0 4px 30px var(--accent-glow);
        }

        .cta-button:hover {
            transform: translateY(-3px);
            box-shadow: 0 8px 40px rgba(108, 92, 231, 0.5);
        }

        .cta-button svg {
            width: 20px;
            height: 20px;
            transition: transform 0.3s;
        }

        .cta-button:hover svg {
            transform: translateX(5px);
        }

        /* Scroll Indicator */
        .scroll-indicator {
            position: absolute;
            bottom: 40px;
            left: 50%;
            transform: translateX(-50%);
            animation: bounce 2s infinite;
        }

        .scroll-indicator .mouse {
            width: 26px;
            height: 40px;
            border: 2px solid var(--text-secondary);
            border-radius: 13px;
            position: relative;
        }

        .scroll-indicator .mouse::before {
            content: '';
            position: absolute;
            top: 8px;
            left: 50%;
            transform: translateX(-50%);
            width: 4px;
            height: 8px;
            background: var(--accent-light);
            border-radius: 2px;
            animation: scrollWheel 2s infinite;
        }

        /* Sections */
        .section {
            position: relative;
            z-index: 1;
            padding: 100px 20px;
            max-width: 1200px;
            margin: 0 auto;
        }

        .section-header {
            text-align: center;
            margin-bottom: 60px;
        }

        .section-header h2 {
            font-size: clamp(2rem, 4vw, 3rem);
            font-weight: 800;
            margin-bottom: 15px;
        }

        .section-header p {
            color: var(--text-secondary);
            font-size: 1.1rem;
            max-width: 600px;
            margin: 0 auto;
        }

        /* Problem Cards */
        .problem-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
            margin-bottom: 80px;
        }

        .problem-card {
            background: var(--bg-card);
            border: 1px solid rgba(255, 255, 255, 0.05);
            border-radius: 20px;
            padding: 40px;
            transition: all 0.4s;
            position: relative;
            overflow: hidden;
            cursor: pointer;
        }

        .problem-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent), var(--accent-light));
            transform: scaleX(0);
            transition: transform 0.4s;
        }

        .problem-card:hover::before {
            transform: scaleX(1);
        }

        .problem-card:hover {
            transform: translateY(-5px);
            border-color: rgba(108, 92, 231, 0.3);
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
        }

        .problem-card .icon {
            width: 60px;
            height: 60px;
            border-radius: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
            font-size: 1.5rem;
        }

        .problem-card .icon.tension {
            background: rgba(225, 112, 85, 0.15);
            color: var(--danger);
        }

        .problem-card .icon.energy {
            background: rgba(253, 203, 110, 0.15);
            color: var(--warning);
        }

        .problem-card .icon.recovery {
            background: rgba(0, 184, 148, 0.15);
            color: var(--success);
        }

        .problem-card h3 {
            font-size: 1.3rem;
            font-weight: 700;
            margin-bottom: 10px;
        }

        .problem-card p {
            color: var(--text-secondary);
            line-height: 1.6;
            font-size: 0.95rem;
        }

        /* Body Tension Interactive */
        .tension-section {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
            margin-bottom: 80px;
        }

        .tension-visual {
            position: relative;
            height: 500px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .body-svg {
            width: 200px;
            height: 400px;
            position: relative;
        }

        .body-outline {
            fill: none;
            stroke: var(--accent);
            stroke-width: 2;
            opacity: 0.6;
        }

        .tension-zone {
            position: absolute;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(225, 112, 85, 0.4), transparent);
            animation: pulse 2s infinite;
            cursor: pointer;
            transition: all 0.3s;
        }

        .tension-zone:hover {
            background: radial-gradient(circle, rgba(225, 112, 85, 0.7), transparent);
            transform: scale(1.2);
        }

        .tension-zone.neck {
            width: 60px;
            height: 60px;
            top: 20px;
            left: 50%;
            transform: translateX(-50%);
        }

        .tension-zone.shoulders {
            width: 80px;
            height: 40px;
            top: 80px;
            left: 50%;
            transform: translateX(-50%);
        }

        .tension-zone.back {
            width: 70px;
            height: 100px;
            top: 130px;
            left: 50%;
            transform: translateX(-50%);
        }

        .tension-zone.hips {
            width: 70px;
            height: 50px;
            top: 240px;
            left: 50%;
            transform: translateX(-50%);
        }

        .tension-info h3 {
            font-size: 2rem;
            font-weight: 800;
            margin-bottom: 20px;
        }

        .tension-info p {
            color: var(--text-secondary);
            line-height: 1.8;
            margin-bottom: 20px;
            font-size: 1.05rem;
        }

        .stat-bar {
            margin-bottom: 20px;
        }

        .stat-bar .label {
            display: flex;
            justify-content: space-between;
            margin-bottom: 8px;
            font-size: 0.9rem;
        }

        .stat-bar .label span:last-child {
            color: var(--accent-light);
            font-weight: 600;
        }

        .stat-bar .bar {
            height: 8px;
            background: rgba(255, 255, 255, 0.05);
            border-radius: 4px;
            overflow: hidden;
        }

        .stat-bar .bar .fill {
            height: 100%;
            border-radius: 4px;
            transition: width 1.5s ease-out;
            width: 0;
        }

        .stat-bar .fill.danger {
            background: linear-gradient(90deg, var(--danger), #e74c3c);
        }

        .stat-bar .fill.warning {
            background: linear-gradient(90deg, var(--warning), #f39c12);
        }

        .stat-bar .fill.success {
            background: linear-gradient(90deg, var(--success), #2ecc71);
        }

        /* Energy Meter */
        .energy-section {
            background: var(--bg-card);
            border: 1px solid rgba(255, 255, 255, 0.05);
            border-radius: 24px;
            padding: 60px;
            margin-bottom: 80px;
            text-align: center;
        }

        .energy-meter {
            position: relative;
            width: 250px;
            height: 250px;
            margin: 40px auto;
        }

        .energy-meter svg {
            transform: rotate(-90deg);
        }

        .energy-meter .bg-circle {
            fill: none;
            stroke: rgba(255, 255, 255, 0.05);
            stroke-width: 12;
        }

        .energy-meter .progress-circle {
            fill: none;
            stroke: url(#energyGradient);
            stroke-width: 12;
            stroke-linecap: round;
            stroke-dasharray: 691;
            stroke-dashoffset: 691;
            transition: stroke-dashoffset 2s ease-out;
        }

        .energy-meter .center-text {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            text-align: center;
        }

        .energy-meter .center-text .value {
            font-size: 3rem;
            font-weight: 900;
            background: linear-gradient(135deg, var(--accent), var(--accent-light));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .energy-meter .center-text .label {
            font-size: 0.8rem;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 2px;
        }

        .energy-stats {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 30px;
            margin-top: 40px;
        }

        .energy-stat {
            padding: 20px;
            background: rgba(255, 255, 255, 0.02);
            border-radius: 16px;
            border: 1px solid rgba(255, 255, 255, 0.05);
        }

        .energy-stat .value {
            font-size: 1.8rem;
            font-weight: 800;
            margin-bottom: 5px;
        }

        .energy-stat .label {
            font-size: 0.85rem;
            color: var(--text-secondary);
        }

        /* Recovery Steps */
        .recovery-steps {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 30px;
            margin-bottom: 80px;
        }

        .step-card {
            background: var(--bg-card);
            border: 1px solid rgba(255, 255, 255, 0.05);
            border-radius: 20px;
            padding: 35px;
            text-align: center;
            transition: all 0.4s;
            position: relative;
        }

        .step-card:hover {
            transform: translateY(-5px);
            border-color: rgba(108, 92, 231, 0.3);
        }

        .step-number {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--accent), var(--accent-light));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.2rem;
            font-weight: 800;
            margin: 0 auto 20px;
        }

        .step-card h3 {
            font-size: 1.2rem;
            font-weight: 700;
            margin-bottom: 10px;
        }

        .step-card p {
            color: var(--text-secondary);
            font-size: 0.9rem;
            line-height: 1.6;
        }

        /* Testimonial */
        .testimonial-section {
            background: linear-gradient(135deg, rgba(108, 92, 231, 0.1), rgba(0, 184, 148, 0.05));
            border: 1px solid rgba(108, 92, 231, 0.2);
            border-radius: 24px;
            padding: 60px;
            text-align: center;
            margin-bottom: 80px;
            position: relative;
            overflow: hidden;
        }

        .testimonial-section::before {
            content: '"';
            position: absolute;
            top: -20px;
            left: 30px;
            font-size: 150px;
            color: rgba(108, 92, 231, 0.1);
            font-family: Georgia, serif;
            line-height: 1;
        }

        .testimonial-section blockquote {
            font-size: 1.5rem;
            font-weight: 300;
            line-height: 1.6;
            max-width: 700px;
            margin: 0 auto 30px;
            font-style: italic;
        }

        .testimonial-section .author {
            color: var(--accent-light);
            font-weight: 600;
        }

        /* CTA Section */
        .cta-section {
            text-align: center;
            padding: 100px 20px;
            position: relative;
            z-index: 1;
        }

        .cta-section h2 {
            font-size: clamp(2rem, 5vw, 3.5rem);
            font-weight: 900;
            margin-bottom: 20px;
        }

        .cta-section p {
            color: var(--text-secondary);
            font-size: 1.2rem;
            margin-bottom: 40px;
            max-width: 500px;
            margin-left: auto;
            margin-right: auto;
        }

        .cta-section .tagline {
            display: flex;
            justify-content: center;
            gap: 20px;
            margin-top: 40px;
            flex-wrap: wrap;
        }

        .cta-section .tagline span {
            padding: 10px 25px;
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 50px;
            font-size: 0.9rem;
            color: var(--text-secondary);
        }

        /* Footer */
        .footer {
            position: relative;
            z-index: 1;
            padding: 40px 20px;
            text-align: center;
            border-top: 1px solid rgba(255, 255, 255, 0.05);
        }

        .footer p {
            color: var(--text-secondary);
            font-size: 0.85rem;
        }

        /* Animations */
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(30px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes bounce {
            0%, 20%, 50%, 80%, 100% {
                transform: translateX(-50%) translateY(0);
            }
            40% {
                transform: translateX(-50%) translateY(-10px);
            }
            60% {
                transform: translateX(-50%) translateY(-5px);
            }
        }

        @keyframes scrollWheel {
            0% {
                opacity: 1;
                transform: translateX(-50%) translateY(0);
            }
            100% {
                opacity: 0;
                transform: translateX(-50%) translateY(12px);
            }
        }

        @keyframes pulse {
            0%, 100% {
                opacity: 0.5;
                transform: translateX(-50%) scale(1);
            }
            50% {
                opacity: 0.8;
                transform: translateX(-50%) scale(1.1);
            }
        }

        @keyframes float {
            0%, 100% {
                transform: translateY(0);
            }
            50% {
                transform: translateY(-20px);
            }
        }

        /* Scroll Reveal */
        .reveal {
            opacity: 0;
            transform: translateY(40px);
            transition: all 0.8s ease-out;
        }

        .reveal.active {
            opacity: 1;
            transform: translateY(0);
        }

        /* Responsive */
        @media (max-width: 768px) {
            .nav {
                padding: 15px 20px;
            }

            .nav-links {
                display: none;
            }

            .tension-section {
                grid-template-columns: 1fr;
                gap: 40px;
            }

            .tension-visual {
                height: 350px;
            }

            .energy-stats {
                grid-template-columns: 1fr;
            }

            .energy-section {
                padding: 40px 20px;
            }

            .testimonial-section {
                padding: 40px 20px;
            }

            .problem-grid {
                grid-template-columns: 1fr;
            }
        }

        /* Interactive Slider */
        .slider-container {
            margin: 40px 0;
            padding: 30px;
            background: rgba(255, 255, 255, 0.02);
            border-radius: 16px;
            border: 1px solid rgba(255, 255, 255, 0.05);
        }

        .slider-container label {
            display: block;
            margin-bottom: 15px;
            font-weight: 600;
        }

        .slider-container input[type="range"] {
            width: 100%;
            height: 6px;
            -webkit-appearance: none;
            appearance: none;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 3px;
            outline: none;
        }

        .slider-container input[type="range"]::-webkit-slider-thumb {
            -webkit-appearance: none;
            appearance: none;
            width: 22px;
            height: 22px;
            border-radius: 50%;
            background: var(--accent);
            cursor: pointer;
            box-shadow: 0 0 15px var(--accent-glow);
        }

        .slider-value {
            text-align: center;
            margin-top: 10px;
            font-size: 1.5rem;
            font-weight: 800;
            color: var(--accent-light);
        }

        /* Glow effect */
        .glow {
            position: absolute;
            width: 300px;
            height: 300px;
            border-radius: 50%;
            background: radial-gradient(circle, var(--accent-glow), transparent);
            filter: blur(60px);
            pointer-events: none;
        }

        .glow-1 {
            top: 20%;
            left: -100px;
        }

        .glow-2 {
            bottom: 20%;
            right: -100px;
            background: radial-gradient(circle, rgba(0, 184, 148, 0.2), transparent);
        }
    </style>
</head>
<body>

    <canvas id="particles-canvas"></canvas>

    <!-- Navigation -->
    <nav class="nav">
        <div class="logo">RECOVER+</div>
        <ul class="nav-links">
            <li><a href="#problema">O Problema</a></li>
            <li><a href="#tensao">Tensão</a></li>
            <li><a href="#energia">Energia</a></li>
            <li><a href="#recuperacao">Recuperação</a></li>
            <li><a href="#contato">Contato</a></li>
        </ul>
    </nav>

    <!-- Hero Section -->
    <section class="hero">
        <div class="glow glow-1"></div>
        <div class="glow glow-2"></div>
        <div class="hero-badge">🔬 Ciência da Recuperação</div>
        <h1>Você não está cansado <span class="highlight">à toa.</span></h1>
        <p>Seu corpo vive em tensão. Isso consome energia que deveria ir pra emagrecer. A recuperação correta muda tudo.</p>
        <a href="#contato" class="cta-button">
            Comece agora
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <line x1="5" y1="12" x2="19" y2="12"></line>
                <polyline points="12 5 19 12 12 19"></polyline>
            </svg>
        </a>
        <div class="scroll-indicator">
            <div class="mouse"></div>
        </div>
    </section>

    <!-- Problem Section -->
    <section class="section" id="problema">
        <div class="section-header reveal">
            <h2>O ciclo invisível</h2>
            <p>Entenda por que você sente cansaço constante e não consegue emagrecer</p>
        </div>

        <div class="problem-grid">
            <div class="problem-card reveal">
                <div class="icon tension">⚡</div>
                <h3>Tensão Constante</h3>
                <p>Seu corpo vive em estado de alerta. Músculos contraídos, nervos tensos — tudo isso gera um desgaste silencioso que você nem percebe.</p>
            </div>
            <div class="problem-card reveal">
                <div class="icon energy">🔥</div>
                <h3>Energia Desperdiçada</h3>
                <p>A cada dia, sua energia é drenada pela tensão muscular. Energia que poderia ser usada para metabolizar gordura vai para sustentar o estresse.</p>
            </div>
            <div class="problem-card reveal">
                <div class="icon recovery">💪</div>
                <h3>Recuperação Falha</h3>
                <p>Sem recuperação adequada, seu corpo entra em modo de conservação. O metabolismo desacelera e o emagrecimento fica impossível.</p>
            </div>
        </div>
    </section>

    <!-- Tension Section -->
    <section class="section" id="tensao">
        <div class="tension-section">
            <div class="tension-visual reveal">
                <svg class="body-svg" viewBox="0 0 200 400">
                    <!-- Head -->
                    <ellipse cx="100" cy="40" rx="30" ry="35" class="body-outline"/>
                    <!-- Neck -->
                    <line x1="100" y1="75" x2="100" y2="100" class="body-outline"/>
                    <!-- Shoulders -->
                    <path d="M 60 100 Q 100 90 140 100" class="body-outline"/>
                    <!-- Torso -->
                    <path d="M 60 100 L 55 200 Q 100 210 145 200 L 140 100" class="body-outline"/>
                    <!-- Arms -->
                    <path d="M 60 100 L 30 180 L 25 250" class="body-outline"/>
                    <path d="M 140 100 L 170 180 L 175 250" class="body-outline"/>
                    <!-- Hips -->
                    <path d="M 55 200 Q 100 220 145 200" class="body-outline"/>
                    <!-- Legs -->
                    <path d="M 70 210 L 65 320 L 60 380" class="body-outline"/>
                    <path d="M 130 210 L 135 320 L 140 380" class="body-outline"/>
                </svg>

                <div class="tension-zone neck" title="Pescoço"></div>
                <div class="tension-zone shoulders" title="Ombros"></div>
                <div class="tension-zone back" title="Costas"></div>
                <div class="tension-zone hips" title="Quadril"></div>
            </div>

            <div class="tension-info reveal">
                <h3>Seu corpo vive em <span style="color: var(--danger)">tensão.</span></h3>
                <p>Cada zona de tensão representa energia sendo desperdiçada. Quando seu corpo está constantemente contraído, ele não consegue entrar em modo de recuperação e queima de gordura.</p>

                <div class="stat-bar">
                    <div class="label">
                        <span>Tensão no Pescoço</span>
