    <script>
        // Particle System
        const canvas = document.getElementById('particles-canvas');
        const ctx = canvas.getContext('2d');
        let particles = [];
        let mouse = { x: null, y: null };

        function resizeCanvas() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }

        resizeCanvas();
        window.addEventListener('resize', resizeCanvas);

        class Particle {
            constructor() {
                this.x = Math.random() * canvas.width;
                this.y = Math.random() * canvas.height;
                this.size = Math.random() * 2 + 0.5;
                this.speedX = (Math.random() - 0.5) * 0.5;
                this.speedY = (Math.random() - 0.5) * 0.5;
                this.opacity = Math.random() * 0.5 + 0.1;
            }

            update() {
                this.x += this.speedX;
                this.y += this.speedY;

                if (this.x > canvas.width) this.x = 0;
                if (this.x < 0) this.x = canvas.width;
                if (this.y > canvas.height) this.y = 0;
                if (this.y < 0) this.y = canvas.height;

                // Mouse interaction
                if (mouse.x !== null) {
                    const dx = mouse.x - this.x;
                    const dy = mouse.y - this.y;
                    const distance = Math.sqrt(dx * dx + dy * dy);
                    if (distance < 150) {
                        this.x -= dx * 0.01;
                        this.y -= dy * 0.01;
                    }
                }
            }

            draw() {
                ctx.fillStyle = `rgba(108, 92, 231, ${this.opacity})`;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        function initParticles() {
            particles = [];
            const count = Math.min(80, Math.floor(canvas.width * canvas.height / 15000));
            for (let i = 0; i < count; i++) {
                particles.push(new Particle());
            }
        }

        function connectParticles() {
            for (let i = 0; i < particles.length; i++) {
                for (let j = i + 1; j < particles.length; j++) {
                    const dx = particles[i].x - particles[j].x;
                    const dy = particles[i].y - particles[j].y;
                    const distance = Math.sqrt(dx * dx + dy * dy);

                    if (distance < 150) {
                        const opacity = (1 - distance / 150) * 0.15;
                        ctx.strokeStyle = `rgba(108, 92, 231, ${opacity})`;
                        ctx.lineWidth = 0.5;
                        ctx.beginPath();
                        ctx.moveTo(particles[i].x, particles[i].y);
                        ctx.lineTo(particles[j].x, particles[j].y);
                        ctx.stroke();
                    }
                }
            }
        }

        function animateParticles() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            particles.forEach(p => {
                p.update();
                p.draw();
            });
            connectParticles();
            requestAnimationFrame(animateParticles);
        }

        initParticles();
        animateParticles();

        window.addEventListener('mousemove', (e) => {
            mouse.x = e.clientX;
            mouse.y = e.clientY;
        });

        window.addEventListener('mouseleave', () => {
            mouse.x = null;
            mouse.y = null;
        });

        // Scroll Reveal
        const revealElements = document.querySelectorAll('.reveal');

        const revealObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('active');
                }
            });
        }, {
            threshold: 0.1,
            rootMargin: '0px 0px -50px 0px'
        });

        revealElements.forEach(el => revealObserver.observe(el));

        // Stat Bars Animation
        const statBars = document.querySelectorAll('.stat-bar .fill');

        const barObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const width = entry.target.getAttribute('data-width');
                    entry.target.style.width = width + '%';
                }
            });
        }, { threshold: 0.5 });

        statBars.forEach(bar => barObserver.observe(bar));

        // Energy Meter Animation
        const energyCircle = document.getElementById('energyCircle');
        const energyValue = document.getElementById('energyValue');
        let energyAnimated = false;

        const energyObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting && !energyAnimated) {
                    energyAnimated = true;
                    const circumference = 2 * Math.PI * 110;
                    const targetOffset = circumference * (1 - 0.55); // 55% remaining = 45% lost

                    energyCircle.style.strokeDashoffset = targetOffset;

                    // Animate number
                    let current = 0;
                    const target = 45;
                    const duration = 2000;
                    const step = target / (duration / 16);

                    const counter = setInterval(() => {
                        current += step;
                        if (current >= target) {
                            current = target;
                            clearInterval(counter);
                        }
                        energyValue.textContent = Math.round(current) + '%';
                    }, 16);
                }
            });
        }, { threshold: 0.5 });

        energyObserver.observe(energyCircle);

        // Tension Slider
        const tensionSlider = document.getElementById('tensionSlider');
        const sliderValue = document.getElementById('sliderValue');

        tensionSlider.addEventListener('input', (e) => {
            const value = e.target.value;
            sliderValue.textContent = value + '% de tensão';

            // Update color based on value
            if (value < 30) {
                sliderValue.style.color = 'var(--success)';
            } else if (value < 70) {
                sliderValue.style.color = 'var(--warning)';
            } else {
                sliderValue.style.color = 'var(--danger)';
            }
        });

        // Smooth Scroll
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    target.scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });
                }
            });
        });

        // Tension Zone Click Interaction
        document.querySelectorAll('.tension-zone').forEach(zone => {
            zone.addEventListener('click', function() {
                this.style.animation = 'none';
                this.offsetHeight; // Trigger reflow
                this.style.animation = 'pulse 0.5s ease-out 3';

                // Show tooltip
                const title = this.getAttribute('title');
                showTooltip(title, this);
            });
        });

        function showTooltip(text, element) {
            const tooltip = document.createElement('div');
            tooltip.textContent = text + ': Tensão alta';
            tooltip.style.cssText = `
                position: absolute;
                background: rgba(108, 92, 231, 0.9);
                color: white;
                padding: 8px 16px;
                border-radius: 8px;
                font-size: 0.85rem;
                font-weight: 600;
                pointer-events: none;
                z-index: 1000;
                white-space: nowrap;
                animation: fadeInUp 0.3s ease-out;
            `;

            const rect = element.getBoundingClientRect();
            tooltip.style.left = rect.left + rect.width / 2 - tooltip.offsetWidth / 2 + 'px';
            tooltip.style.top = rect.top - 40 + 'px';

            document.body.appendChild(tooltip);

            setTimeout(() => {
                tooltip.style.opacity = '0';
                tooltip.style.transition = 'opacity 0.3s';
                setTimeout(() => tooltip.remove(), 300);
            }, 2000);
        }

        // Parallax effect on scroll
        window.addEventListener('scroll', () => {
            const scrolled = window.pageYOffset;
            const parallaxElements = document.querySelectorAll('.glow');
            parallaxElements.forEach((el, index) => {
                const speed = index === 0 ? 0.3 : 0.2;
                el.style.transform = `translateY(${scrolled * speed}px)`;
            });
        });

        // Counter animation for energy stats
        function animateCounters() {
            const counters = document.querySelectorAll('.energy-stat .value');
            counters.forEach(counter => {
                const target = parseInt(counter.textContent);
                if (isNaN(target)) return;

                let current = 0;
                const duration = 1500;
                const step = target / (duration / 16);

                const counterInterval = setInterval(() => {
                    current += step;
                    if (current >= target) {
                        current = target;
                        clearInterval(counterInterval);
                    }
                    counter.textContent = Math.round(current) + '%';
                }, 16);
            });
        }

        // Trigger counter animation when energy section is visible
        const energySection = document.querySelector('.energy-section');
        const counterObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    setTimeout(animateCounters, 500);
                }
            });
        }, { threshold: 0.3 });

        counterObserver.observe(energySection);

        // Add hover effect to problem cards
        document.querySelectorAll('.problem-card').forEach(card => {
            card.addEventListener('mouseenter', function() {
                this.style.transform = 'translateY(-8px) scale(1.02)';
            });
            card.addEventListener('mouseleave', function() {
                this.style.transform = 'translateY(0) scale(1)';
            });
        });

        console.log('🚀 Recover+ - Recuperação Correcta');
        console.log('Simples. Diferente. Funciona.');
    </script>
</body>
