        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x0a0a2e, 0.015);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 10);

        // Particle System
        const particleCanvas = document.getElementById('particle-canvas');
        const pCtx = particleCanvas.getContext('2d');
        particleCanvas.width = window.innerWidth;
        particleCanvas.height = window.innerHeight;
        const particles = [];

        class Particle {
            constructor(x, y, color, size, velocity) {
                this.x = x;
                this.y = y;
                this.color = color;
                this.size = size;
                this.velocity = velocity;
                this.life = 1;
                this.decay = 0.02 + Math.random() * 0.03;
            }
            update() {
                this.x += this.velocity.x;
                this.y += this.velocity.y;
                this.velocity.y += 0.1;
                this.life -= this.decay;
                this.size *= 0.98;
            }
            draw() {
                pCtx.save();
                pCtx.globalAlpha = this.life;
                pCtx.fillStyle = this.color;
                pCtx.beginPath();
                pCtx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                pCtx.fill();
                pCtx.restore();
            }
        }

        function spawnParticles(x, y, count, color, sizeRange, velocityRange) {
            for (let i = 0; i < count; i++) {
                particles.push(new Particle(
                    x, y, color,
                    sizeRange[0] + Math.random() * (sizeRange[1] - sizeRange[0]),
                    {
                        x: (Math.random() - 0.5) * velocityRange[0],
                        y: (Math.random() - 0.5) * velocityRange[1]
                    }
                ));
            }
        }

        function updateParticles() {
            pCtx.clearRect(0, 0, particleCanvas.width, particleCanvas.height);
            for (let i = particles.length - 1; i >= 0; i--) {
                particles[i].update();
                particles[i].draw();
                if (particles[i].life <= 0) {
                    particles.splice(i, 1);
                }
            }
        }

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(50, 100, 50);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 2048;
        directionalLight.shadow.mapSize.height = 2048;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 500;
        directionalLight.shadow.camera.left = -100;
        directionalLight.shadow.camera.right = 100;
        directionalLight.shadow.camera.top = 100;
        directionalLight.shadow.camera.bottom = -100;
        scene.add(directionalLight);

        const pointLight1 = new THREE.PointLight(0x4facfe, 2, 50);
        pointLight1.position.set(-20, 10, -20);
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0xf093fb, 2, 50);
        pointLight2.position.set(20, 10, 20);
        scene.add(pointLight2);

        // Player
        const player = {
            mesh: null,
            velocity: new THREE.Vector3(0, 0, 0),
            onGround: false,
            height: 1.8,
            radius: 0.5
        };

        function createPlayer() {
            const group = new THREE.Group();

            // Body
            const bodyGeo = new THREE.CapsuleGeometry(0.4, 1, 8, 16);
            const bodyMat = new THREE.MeshStandardMaterial({
                color: 0x4facfe,
                metalness: 0.3,
                roughness: 0.4,
                emissive: 0x1a1a3e,
                emissiveIntensity: 0.2
            });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 0.9;
            body.castShadow = true;
            group.add(body);

            // Head
            const headGeo = new THREE.SphereGeometry(0.35, 16, 16);
            const headMat = new THREE.MeshStandardMaterial({
                color: 0xffffff,
                metalness: 0.1,
                roughness: 0.5
            });
            const head = new THREE.Mesh(headGeo, headMat);
            head.position.y = 1.8;
            head.castShadow = true;
            group.add(head);

            // Eyes
            const eyeGeo = new THREE.SphereGeometry(0.08, 8, 8);
            const eyeMat = new THREE.MeshStandardMaterial({
                color: 0x000000,
                emissive: 0x4facfe,
                emissiveIntensity: 0.5
            });
            const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
            leftEye.position.set(-0.12, 1.85, 0.3);
            group.add(leftEye);
            const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
            rightEye.position.set(0.12, 1.85, 0.3);
            group.add(rightEye);

            // Glow effect
            const glowGeo = new THREE.SphereGeometry(0.6, 16, 16);
            const glowMat = new THREE.MeshBasicMaterial({
                color: 0x4facfe,
                transparent: true,
                opacity: 0.1
            });
            const glow = new THREE.Mesh(glowGeo, glowMat);
            glow.position.y = 0.9;
            group.add(glow);

            player.mesh = group;
            scene.add(group);
        }

        // Platforms
        const platforms = [];
        const collectibles = [];
        const hazards = [];

        function createPlatform(x, y, z, width, depth, color, type = 'normal') {
            const geometry = new THREE.BoxGeometry(width, 1, depth);
            const material = new THREE.MeshStandardMaterial({
                color: color,
                metalness: 0.5,
                roughness: 0.3,
                emissive: color,
                emissiveIntensity: 0.1
            });
            const platform = new THREE.Mesh(geometry, material);
            platform.position.set(x, y, z);
            platform.castShadow = true;
            platform.receiveShadow = true;
            platform.userData = { type, width, depth, height: 1 };
            scene.add(platform);
            platforms.push(platform);
            return platform;
        }

        function createCollectible(x, y, z) {
            const group = new THREE.Group();

            const geo = new THREE.OctahedronGeometry(0.3, 0);
            const mat = new THREE.MeshStandardMaterial({
                color: 0xffd700,
                metalness: 0.8,
                roughness: 0.2,
                emissive: 0xffd700,
                emissiveIntensity: 0.5
            });
            const mesh = new THREE.Mesh(geo, mat);
            mesh.castShadow = true;
            group.add(mesh);

            const glowGeo = new THREE.SphereGeometry(0.5, 16, 16);
            const glowMat = new THREE.MeshBasicMaterial({
                color: 0xffd700,
                transparent: true,
                opacity: 0.2
            });
            const glow = new THREE.Mesh(glowGeo, glowMat);
            group.add(glow);

            group.position.set(x, y, z);
            group.userData = { collected: false, type: 'coin' };
            scene.add(group);
            collectibles.push(group);
            return group;
        }

        function createHazard(x, y, z, width, depth) {
            const geometry = new THREE.BoxGeometry(width, 0.5, depth);
            const material = new THREE.MeshStandardMaterial({
                color: 0xff0000,
                emissive: 0xff0000,
                emissiveIntensity: 0.5,
                transparent: true,
                opacity: 0.7
            });
            const hazard = new THREE.Mesh(geometry, material);
            hazard.position.set(x, y, z);
            scene.add(hazard);
            hazards.push(hazard);
            return hazard;
        }

        function createLevel(level) {
            // Clear existing
            platforms.forEach(p => scene.remove(p));
            collectibles.forEach(c => scene.remove(c));
            hazards.forEach(h => scene.remove(h));
            platforms.length = 0;
            collectibles.length = 0;
            hazards.length = 0;

            // Ground platform
            createPlatform(0, -1, 0, 20, 20, 0x2a2a4a);

            if (level === 1) {
                // Level 1 - Basic platforms
                createPlatform(0, 1, -8, 6, 6, 0x3a3a6a);
                createPlatform(8, 2, -5, 4, 4, 0x4a4a8a);
                createPlatform(-8, 3, -3, 4, 4, 0x4a4a8a);
                createPlatform(0, 4, -15, 8, 4, 0x5a5a9a);
                createPlatform(12, 5, -10, 4, 4, 0x5a5a9a);
                createPlatform(-12, 6, -8, 4, 4, 0x5a5a9a);
                createPlatform(0, 7, -25, 10, 6, 0x6a6aaa);

                // Collectibles
                createCollectible(0, 2.5, -8);
                createCollectible(8, 3.5, -5);
                createCollectible(-8, 4.5, -3);
                createCollectible(0, 5.5, -15);
                createCollectible(12, 6.5, -10);
                createCollectible(-12, 7.5, -8);
                createCollectible(0, 8.5, -25);
                createCollectible(5, 0, -5);
                createCollectible(-5, 0, 5);

                // Hazards
                createHazard(3, -0.5, 3, 4, 2);
                createHazard(-3, -0.5, -3, 4, 2);

            } else if (level === 2) {
                // Level 2 - More challenging
                createPlatform(0, 1, -5, 5, 5, 0x3a3a6a);
                createPlatform(7, 2, -10, 3, 3, 0x4a4a8a);
                createPlatform(-7, 3, -12, 3, 3, 0x4a4a8a);
                createPlatform(14, 4, -8, 3, 3, 0x5a5a9a);
                createPlatform(-14, 5, -6, 3, 3, 0x5a5a9a);
                createPlatform(0, 6, -20, 6, 4, 0x6a6aaa);
                createPlatform(10, 8, -18, 3, 3, 0x7a7aba);
                createPlatform(-10, 9, -16, 3, 3, 0x7a7aba);
                createPlatform(0, 11, -30, 8, 6, 0x8a8aca);

                createCollectible(7, 3.5, -10);
                createCollectible(-7, 4.5, -12);
                createCollectible(14, 5.5, -8);
                createCollectible(-14, 6.5, -6);
                createCollectible(0, 7.5, -20);
                createCollectible(10, 9.5, -18);
                createCollectible(-10, 10.5, -16);
                createCollectible(0, 12.5, -30);
                createCollectible(5, 0, -10);
                createCollectible(-5, 0, -15);

                createHazard(5, -0.5, -5, 3, 2);
                createHazard(-5, -0.5, -10, 3, 2);
                createHazard(0, -0.5, -20, 6, 2);

            } else {
                // Level 3 - Ultimate challenge
                createPlatform(0, 1, -5, 4, 4, 0x3a3a6a);
                createPlatform(6, 2, -12, 2.5, 2.5, 0x4a4a8a);
                createPlatform(-6, 3, -15, 2.5, 2.5, 0x4a4a8a);
                createPlatform(12, 5, -10, 2.5, 2.5, 0x5a5a9a);
                createPlatform(-12, 6, -8, 2.5, 2.5, 0x5a5a9a);
                createPlatform(0, 8, -22, 4, 3, 0x6a6aaa);
                createPlatform(8, 10, -20, 2.5, 2.5, 0x7a7aba);
                createPlatform(-8, 12, -18, 2.5, 2.5, 0x7a7aba);
                createPlatform(0, 14, -35, 6, 4, 0x8a8aca);
                createPlatform(15, 16, -30, 2.5, 2.5, 0x9a9ada);
                createPlatform(-15, 18, -28, 2.5, 2.5, 0x9a9ada);
                createPlatform(0, 20, -45, 10, 6, 0xaaaaea);

                createCollectible(6, 3.5, -12);
                createCollectible(-6, 4.5, -15);
                createCollectible(12, 6.5, -10);
                createCollectible(-12, 7.5, -8);
                createCollectible(0, 9.5, -22);
                createCollectible(8, 11.5, -20);
                createCollectible(-8, 13.5, -18);
                createCollectible(0, 15.5, -35);
                createCollectible(15, 17.5, -30);
                createCollectible(-15, 19.5, -28);
                createCollectible(0, 21.5, -45);

                createHazard(4, -0.5, -8, 2, 2);
                createHazard(-4, -0.5, -12, 2, 2);
                createHazard(0, -0.5, -22, 4, 2);
                createHazard(6, -0.5, -30, 3, 2);
            }

            // Add decorative elements
            addDecorations(level);
        }

        function addDecorations(level) {
            // Floating orbs
            for (let i = 0; i < 10 + level * 5; i++) {
                const geo = new THREE.SphereGeometry(0.2 + Math.random() * 0.3, 8, 8);
                const mat = new THREE.MeshBasicMaterial({
                    color: new THREE.Color().setHSL(Math.random() * 0.3 + 0.5, 0.8, 0.6),
                    transparent: true,
                    opacity: 0.6
                });
                const orb = new THREE.Mesh(geo, mat);
                orb.position.set(
                    (Math.random() - 0.5) * 40,
                    5 + Math.random() * 15,
                    (Math.random() - 0.5) * 50 - 10
                );
                orb.userData = {
                    originalY: orb.position.y,
                    phase: Math.random() * Math.PI * 2,
                    speed: 0.5 + Math.random() * 1
                };
                scene.add(orb);
                platforms.push(orb); // Reuse for animation
            }

            // Background stars
            const starsGeo = new THREE.BufferGeometry();
            const starsPositions = [];
            for (let i = 0; i < 1000; i++) {
                starsPositions.push(
                    (Math.random() - 0.5) * 200,
                    Math.random() * 100 + 10,
                    (Math.random() - 0.5) * 200
                );
            }
            starsGeo.setAttribute('position', new THREE.Float32BufferAttribute(starsPositions, 3));
            const starsMat = new THREE.PointsMaterial({
                color: 0xffffff,
                size: 0.5,
                transparent: true,
                opacity: 0.8
            });
            const stars = new THREE.Points(starsGeo, starsMat);
            scene.add(stars);
        }

        // Input Handling
        const keys = {};
        let mouseX = 0, mouseY = 0;
        let cameraAngle = 0;
        let isPointerLocked = false;

        document.addEventListener('keydown', (e) => {
            keys[e.code] = true;
        });

        document.addEventListener('keyup', (e) => {
            keys[e.code] = false;
        });

        document.addEventListener('mousemove', (e) => {
            if (isPointerLocked) {
                cameraAngle -= e.movementX * 0.002;
                gameState.cameraPitch = Math.max(-0.5, Math.min(1.0, gameState.cameraPitch - e.movementY * 0.002));
            }
        });

        canvas.addEventListener('click', () => {
            if (gameState.running) {
                canvas.requestPointerLock();
            }
        });

        document.addEventListener('pointerlockchange', () => {
            isPointerLocked = document.pointerLockElement === canvas;
        });

        // Collision Detection
        function checkCollision(playerPos, platform) {
            const px = playerPos.x;
            const py = playerPos.y;
            const pz = playerPos.z;
            const pd = platform.userData;

            if (!pd.width || !pd.depth) return false;

            const halfW = pd.width / 2 + player.radius;
            const halfD = pd.depth / 2 + player.radius;
            const halfH = pd.height / 2;

            return (
                px > platform.position.x - halfW &&
                px < platform.position.x + halfW &&
                pz > platform.position.z - halfD &&
                pz < platform.position.z + halfD &&
                py > platform.position.y - halfH &&
                py < platform.position.y + halfH + player.height
            );
        }

        function checkCollectibleCollision(playerPos) {
            for (let i = collectibles.length - 1; i >= 0; i--) {
                const c = collectibles[i];
                if (c.userData.collected) continue;
                const dist = playerPos.distanceTo(c.position);
                if (dist < 1.5) {
                    c.userData.collected = true;
                    scene.remove(c);
                    collectibles.splice(i, 1);
                    gameState.score += 100;
                    updateHUD();
                    spawnParticles(
                        window.innerWidth / 2,
                        window.innerHeight / 2,
                        20,
                        '#ffd700',
                        [2, 6],
                        [5, 10]
                    );
                    showNotification('+100');
                    return true;
                }
            }
            return false;
        }

        function checkHazardCollision(playerPos) {
            for (const h of hazards) {
                const hx = h.position.x;
                const hz = h.position.z;
                const hw = h.geometry.parameters.width / 2 + player.radius;
                const hd = h.geometry.parameters.depth / 2 + player.radius;

                if (
                    playerPos.x > hx - hw &&
                    playerPos.x < hx + hw &&
                    playerPos.z > hz - hd &&
                    playerPos.z < hz + hd &&
                    playerPos.y < h.position.y + 1
                ) {
                    return true;
                }
            }
            return false;
        }

        // HUD Update
        function updateHUD() {
            document.getElementById('score').textContent = gameState.score;
            document.getElementById('level').textContent = gameState.level;
            let hearts = '';
            for (let i = 0; i < gameState.lives; i++) hearts += '❤️';
            document.getElementById('lives').textContent = hearts || '💀';
            document.getElementById('health-fill').style.width = gameState.health + '%';
        }

        function showNotification(text) {
            const notif = document.getElementById('notification');
            notif.textContent = text;
            notif.classList.add('show');
            setTimeout(() => notif.classList.remove('show'), 1500);
        }

        // Game Logic
        function updatePlayer() {
            if (!player.mesh) return;

            const speed = gameState.playerSpeed * (keys['ShiftLeft'] || keys['ShiftRight'] ? gameState.sprintMultiplier : 1);
            const forward = new THREE.Vector3(-Math.sin(cameraAngle), 0, -Math.cos(cameraAngle));
            const right = new THREE.Vector3(Math.cos(cameraAngle), 0, -Math.sin(cameraAngle));

            const moveDir = new THREE.Vector3(0, 0, 0);
            if (keys['KeyW'] || keys['ArrowUp']) moveDir.add(forward);
            if (keys['KeyS'] || keys['ArrowDown']) moveDir.sub(forward);
            if (keys['KeyA'] || keys['ArrowLeft']) moveDir.sub(right);
            if (keys['KeyD'] || keys['ArrowRight']) moveDir.add(right);

            if (moveDir.length() > 0) {
                moveDir.normalize().multiplyScalar(speed);
                player.velocity.x = moveDir.x;
                player.velocity.z = moveDir.z;

                // Rotate player mesh to face movement direction
                const targetAngle = Math.atan2(moveDir.x, moveDir.z);
                player.mesh.rotation.y = targetAngle;
            } else {
                player.velocity.x *= 0.8;
                player.velocity.z *= 0.8;
            }

            // Jump
            if ((keys['Space']) && player.onGround) {
                player.velocity.y = gameState.jumpForce;
                player.onGround = false;
                spawnParticles(
                    window.innerWidth / 2 + (Math.random() - 0.5) * 50,
                    window.innerHeight / 2 + 50,
                    10,
                    '#4facfe',
                    [1, 3],
                    [2, 5]
                );
            }

            // Gravity
            player.velocity.y -= gameState.gravity;

            // Apply velocity
            player.mesh.position.add(player.velocity);

            // Platform collision
            player.onGround = false;
            for (const platform of platforms) {
                if (platform.userData.type === 'orb') continue;

                const px = player.mesh.position.x;
                const py = player.mesh.position.y;
                const pz = player.mesh.position.z;
                const pd = platform.userData;

                if (!pd.width || !pd.depth) continue;

                const halfW = pd.width / 2 + player.radius;
                const halfD = pd.depth / 2 + player.radius;
                const topY = platform.position.y + pd.height / 2;

                if (
                    px > platform.position.x - halfW &&
                    px < platform.position.x + halfW &&
                    pz > platform.position.z - halfD &&
                    pz < platform.position.z + halfD
                ) {
                    // Landing on top
                    if (py > topY - 0.5 && py < topY + 1 && player.velocity.y <= 0) {
                        player.mesh.position.y = topY + player.height / 2;
                        player.velocity.y = 0;
                        player.onGround = true;
                    }
                    // Hitting bottom
                    else if (py < topY && py > topY - pd.height - 1 && player.velocity.y > 0) {
                        player.velocity.y = 0;
                        player.mesh.position.y = topY - pd.height - player.height / 2;
                    }
                }
            }

            // Collectible collision
            checkCollectibleCollision(player.mesh.position);

            // Hazard collision
            if (checkHazardCollision(player.mesh.position)) {
                gameState.health -= 1;
                updateHUD();
                if (gameState.health <= 0) {
                    gameState.lives--;
                    gameState.health = 100;
                    updateHUD();
                    if (gameState.lives <= 0) {
                        gameOver();
                        return;
                    }
                    // Respawn
                    player.mesh.position.set(0, 5, 0);
                    player.velocity.set(0, 0, 0);
                    showNotification('💀 Lost a life!');
                }
                spawnParticles(
                    window.innerWidth / 2,
                    window.innerHeight / 2,
                    15,
                    '#ff0000',
                    [2, 5],
                    [3, 8]
                );
            }

            // Fall detection
            if (player.mesh.position.y < -10) {
                gameState.lives--;
                gameState.health = 100;
                updateHUD();
                if (gameState.lives <= 0) {
                    gameOver();
                    return;
                }
                player.mesh.position.set(0, 5, 0);
                player.velocity.set(0, 0, 0);
                showNotification('💀 Fell!');
            }

            // Check level completion
            if (player.mesh.position.z < -30 && player.mesh.position.y > 15) {
                gameState.level++;
                gameState.score += 500;
                updateHUD();
                showNotification('🎉 Level Complete! +500');
                createLevel(gameState.level);
                player.mesh.position.set(0, 5, 0);
                player.velocity.set(0, 0, 0);
            }

            // Animate player
            player.mesh.children[0].material.emissiveIntensity = 0.2 + Math.sin(Date.now() * 0.005) * 0.1;
        }

        function updateCamera() {
            const targetX = player.mesh.position.x + Math.sin(cameraAngle) * gameState.cameraDistance;
            const targetZ = player.mesh.position.z + Math.cos(cameraAngle) * gameState.cameraDistance;
            const targetY = player.mesh.position.y + gameState.cameraHeight + gameState.cameraPitch * 5;

            camera.position.x += (targetX - camera.position.x) * 0.1;
            camera.position.y += (targetY - camera.position.y) * 0.1;
            camera.position.z += (targetZ - camera.position.z) * 0.1;

            camera.lookAt(player.mesh.position.x, player.mesh.position.y + 1, player.mesh.position.z);
        }

        function updateCollectibles() {
            const time = Date.now() * 0.001;
            collectibles.forEach((c, i) => {
                if (!c.userData.collected) {
                    c.position.y = c.position.y + Math.sin(time + i) * 0.002;
                    c.rotation.y += 0.02;
                    c.rotation.x += 0.01;
                }
            });
        }

        function updateOrbs() {
            const time = Date.now() * 0.001;
            platforms.forEach(p => {
                if (p.userData.type === 'orb' && p.userData.phase !== undefined) {
                    p.position.y = p.userData.originalY + Math.sin(time * p.userData.speed + p.userData.phase) * 2;
                }
            });
        }

        function gameOver() {
            gameState.running = false;
            document.exitPointerLock();
            document.getElementById('menu').classList.remove('hidden');
            document.querySelector('#menu h1').textContent = 'GAME OVER';
            document.querySelector('#menu .subtitle').textContent = `Final Score: ${gameState.score}`;
            document.getElementById('startBtn').textContent = 'Play Again';
        }

        function startGame() {
            gameState.running = true;
            gameState.score = 0;
            gameState.lives = 3;
            gameState.level = 1;
            gameState.health = 100;
            updateHUD();
            createPlayer();
            createLevel(1);
            player.mesh.position.set(0, 5, 0);
            player.velocity.set(0, 0, 0);
            document.getElementById('menu').classList.add('hidden');
            canvas.requestPointerLock();
        }

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            if (gameState.running) {
                updatePlayer();
                updateCamera();
                updateCollectibles();
                updateOrbs();
            }

            updateParticles();
            renderer.render(scene, camera);
        }

        // Event Listeners
        document.getElementById('startBtn').addEventListener('click', startGame);
        document.getElementById('controlsBtn').addEventListener('click', () => {
            showNotification('WASD: Move | SPACE: Jump | SHIFT: Sprint | MOUSE: Look');
        });

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            particleCanvas.width = window.innerWidth;
            particleCanvas.height = window.innerHeight;
        });

        // Initialize
        createPlayer();
        createLevel(1);
        animate();
    </script>
</body>
</html>

