</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

canvas.width = 1200;
canvas.height = 700;

// Game state
let gameRunning = false;
let score = 0;
let lives = 3;
let level = 1;
let camera = { x: 0, y: 0 };
let particles = [];
let floatingTexts = [];
let screenShake = 0;

// Input
const keys = {};
window.addEventListener('keydown', e => {
    keys[e.code] = true;
    if (['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)) {
        e.preventDefault();
    }
});
window.addEventListener('keyup', e => keys[e.code] = false);

// Player
const player = {
    x: 100, y: 400,
    vx: 0, vy: 0,
    width: 32, height: 40,
    onGround: false,
    jumping: false,
    facing: 1,
    animFrame: 0,
    animTimer: 0,
    invincible: 0,
    trail: [],
    doubleJump: false,
    canDoubleJump: true
};

// Platform types
const PLATFORM_TYPES = {
    normal: { color: '#4a9c5d', topColor: '#6bcf7f', height: 20 },
    stone: { color: '#7a7a7a', topColor: '#9a9a9a', height: 20 },
    ice: { color: '#87ceeb', topColor: '#b0e0ff', height: 20 },
    moving: { color: '#ff8c42', topColor: '#ffaa66', height: 20 },
    spring: { color: '#ff6b9d', topColor: '#ff8eb5', height: 20 }
};

// Level generation
let platforms = [];
let gems = [];
let enemies = [];
let decorations = [];
let clouds = [];
let stars = [];

function generateLevel() {
    platforms = [];
    gems = [];
    enemies = [];
    decorations = [];
    clouds = [];
    stars = [];

    // Ground
    for (let x = 0; x < 5000; x += 200) {
        if (Math.random() > 0.15 || x < 400) {
            platforms.push({
                x: x, y: 620,
                width: 200, height: 80,
                type: 'normal',
                moving: false
            });
        }
    }

    // Platforms
    const platformCount = 60 + level * 10;
    for (let i = 0; i < platformCount; i++) {
        const x = 300 + Math.random() * 4500;
        const y = 200 + Math.random() * 350;
        const width = 80 + Math.random() * 120;
        const type = Math.random() < 0.1 ? 'spring' :
                     Math.random() < 0.15 ? 'ice' :
                     Math.random() < 0.2 ? 'stone' : 'normal';

        const moving = Math.random() < 0.15;
        platforms.push({
            x, y, width, height: 20,
            type,
            moving,
            moveSpeed: moving ? (1 + Math.random() * 2) * (Math.random() < 0.5 ? 1 : -1) : 0,
            moveRange: moving ? 60 + Math.random() * 80 : 0,
            origX: x,
            origY: y
        });
    }

    // Gems
    const gemCount = 40 + level * 5;
    for (let i = 0; i < gemCount; i++) {
        gems.push({
            x: 200 + Math.random() * 4800,
            y: 150 + Math.random() * 400,
            size: 12 + Math.random() * 8,
            collected: false,
            bobOffset: Math.random() * Math.PI * 2,
            type: Math.random() < 0.1 ? 'gold' : 'diamond',
            rotation: 0
        });
    }

    // Enemies
    const enemyCount = 15 + level * 5;
    for (let i = 0; i < enemyCount; i++) {
        const type = Math.random() < 0.5 ? 'walker' : 'flyer';
        enemies.push({
            x: 400 + Math.random() * 4500,
            y: type === 'walker' ? 580 : 200 + Math.random() * 300,
            width: 30, height: 30,
            type,
            vx: type === 'walker' ? (1 + Math.random() * 2) * (Math.random() < 0.5 ? 1 : -1) : 0,
            vy: 0,
            origX: 0,
            origY: 0,
            range: 100 + Math.random() * 150,
            animFrame: 0,
            animTimer: 0,
            alive: true,
            flyAngle: Math.random() * Math.PI * 2
        });
        enemies[enemies.length - 1].origX = enemies[enemies.length - 1].x;
        enemies[enemies.length - 1].origY = enemies[enemies.length - 1].y;
    }

    // Clouds
    for (let i = 0; i < 30; i++) {
        clouds.push({
            x: Math.random() * 5000,
            y: 50 + Math.random() * 200,
            width: 100 + Math.random() * 200,
            height: 40 + Math.random() * 60,
            speed: 0.2 + Math.random() * 0.5,
            opacity: 0.3 + Math.random() * 0.4
        });
    }

    // Stars
    for (let i = 0; i < 100; i++) {
        stars.push({
            x: Math.random() * 5000,
            y: Math.random() * 300,
            size: 1 + Math.random() * 2,
            twinkle: Math.random() * Math.PI * 2,
            speed: 0.5 + Math.random() * 2
        });
    }

    // Decorations (trees, bushes)
    for (let i = 0; i < 50; i++) {
        decorations.push({
            x: Math.random() * 5000,
            y: 600,
            type: Math.random() < 0.5 ? 'tree' : 'bush',
            size: 0.5 + Math.random() * 1
        });
    }
}

function resetPlayer() {
    player.x = 100;
    player.y = 400;
    player.vx = 0;
    player.vy = 0;
    player.onGround = false;
    player.invincible = 0;
    player.trail = [];
    player.canDoubleJump = true;
}

function startGame() {
    document.getElementById('startScreen').classList.add('hidden');
    document.getElementById('gameOverScreen').classList.add('hidden');
    score = 0;
    lives = 3;
    level = 1;
    generateLevel();
    resetPlayer();
    gameRunning = true;
    updateUI();
}

function updateUI() {
    document.getElementById('score').textContent = score;
    document.getElementById('lives').textContent = lives;
    document.getElementById('level').textContent = level;
}

function spawnParticles(x, y, color, count, speed, life) {
    for (let i = 0; i < count; i++) {
        particles.push({
            x, y,
            vx: (Math.random() - 0.5) * speed,
            vy: (Math.random() - 0.5) * speed - 2,
            life: life || 30 + Math.random() * 20,
            maxLife: life || 30 + Math.random() * 20,
            color,
            size: 2 + Math.random() * 4
        });
    }
}

function spawnFloatingText(x, y, text, color) {
    floatingTexts.push({
        x, y, text, color,
        life: 60,
        vy: -2
    });
}

function update() {
    if (!gameRunning) return;

    // Player movement
    const speed = 5;
    const jumpForce = -12;
    const gravity = 0.6;
    const friction = 0.85;

    if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vx -= 1;
        player.facing = -1;
    }
    if (keys['ArrowRight'] || keys['KeyD']) {
        player.vx += 1;
        player.facing = 1;
    }

    if ((keys['Space'] || keys['ArrowUp'] || keys['KeyW']) && player.onGround) {
        player.vy = jumpForce;
        player.onGround = false;
        player.jumping = true;
        player.canDoubleJump = true;
        spawnParticles(player.x + player.width/2, player.y + player.height, '#fff', 8, 3, 20);
    } else if ((keys['Space'] || keys['ArrowUp'] || keys['KeyW']) && player.canDoubleJump && !player.onGround && player.vy > -5) {
        player.vy = jumpForce * 0.8;
        player.canDoubleJump = false;
        player.jumping = true;
        spawnParticles(player.x + player.width/2, player.y + player.height, '#aaf', 12, 4, 25);
    }

    player.vx *= friction;
    player.vy += gravity;

    if (Math.abs(player.vx) > speed) player.vx = speed * Math.sign(player.vx);
    if (player.vy > 15) player.vy = 15;

    player.x += player.vx;
    player.y += player.vy;

    // Trail
    if (Math.abs(player.vx) > 1 || Math.abs(player.vy) > 1) {
        player.trail.push({ x: player.x + player.width/2, y: player.y + player.height/2, life: 10 });
    }
    player.trail = player.trail.filter(t => {
        t.life--;
        return t.life > 0;
    });

    // Platform collision
    player.onGround = false;
    for (const platform of platforms) {
        // Moving platforms
        if (platform.moving) {
            platform.x = platform.origX + Math.sin(Date.now() * 0.001 * platform.moveSpeed) * platform.moveRange;
        }

        if (player.x + player.width > platform.x &&
            player.x < platform.x + platform.width &&
            player.y + player.height > platform.y &&
            player.y + player.height < platform.y + platform.height + 10 &&
            player.vy >= 0) {
            player.y = platform.y - player.height;
            player.vy = 0;
            player.onGround = true;
            player.jumping = false;
            player.canDoubleJump = true;

            if (platform.type === 'spring') {
                player.vy = -18;
                player.onGround = false;
                spawnParticles(player.x + player.width/2, player.y + player.height, '#ff6b9d', 15, 5, 30);
            }
        }
    }

    // Gem collection
    for (const gem of gems) {
        if (gem.collected) continue;
        gem.rotation += 0.05;
        const bobY = gem.y + Math.sin(Date.now() * 0.003 + gem.bobOffset) * 5;

        const dx = (player.x + player.width/2) - gem.x;
        const dy = (player.y + player.height/2) - bobY;
        const dist = Math.sqrt(dx*dx + dy*dy);

        if (dist < gem.size + 20) {
            gem.collected = true;
            const points = gem.type === 'gold' ? 50 : 100;
            score += points;
            spawnParticles(gem.x, bobY, gem.type === 'gold' ? '#ffd700' : '#00ffff', 20, 6, 40);
            spawnFloatingText(gem.x, bobY - 20, `+${points}`, gem.type === 'gold' ? '#ffd700' : '#00ffff');
            updateUI();
        }
    }

    // Enemy collision
    for (const enemy of enemies) {
        if (!enemy.alive) continue;

        if (enemy.type === 'flyer') {
            enemy.flyAngle += 0.02;
            enemy.x = enemy.origX + Math.cos(enemy.flyAngle) * enemy.range;
            enemy.y = enemy.origY + Math.sin(enemy.flyAngle * 0.5) * 50;
        } else {
            enemy.x += enemy.vx;
            if (Math.abs(enemy.x - enemy.origX) > enemy.range) {
                enemy.vx *= -1;
            }
        }

        enemy.animTimer++;
        if (enemy.animTimer > 10) {
            enemy.animTimer = 0;
            enemy.animFrame = (enemy.animFrame + 1) % 4;
        }

        // Check collision with player
        if (player.invincible <= 0) {
            if (player.x + player.width > enemy.x - enemy.width/2 &&
                player.x < enemy.x + enemy.width/2 &&
                player.y + player.height > enemy.y - enemy.height/2 &&
                player.y < enemy.y + enemy.height/2) {

                // Stomp from above
                if (player.vy > 0 && player.y + player.height < enemy.y + enemy.height/2) {
                    enemy.alive = false;
                    player.vy = -8;
                    score += 200;
                    spawnParticles(enemy.x, enemy.y, '#ff6b6b', 25, 8, 40);
                    spawnFloatingText(enemy.x, enemy.y - 30, '+200', '#ff6b6b');
                    screenShake = 5;
                    updateUI();
                } else {
                    // Take damage
                    lives--;
                    player.invincible = 90;
                    player.vy = -8;
                    player.vx = -5 * player.facing;
                    screenShake = 10;
                    spawnParticles(player.x + player.width/2, player.y + player.height/2, '#ff0000', 20, 6, 30);
                    updateUI();

                    if (lives <= 0) {
                        gameOver();
                        return;
                    }
                }
            }
        }
    }

    if (player.invincible > 0) player.invincible--;

    // Fall death
    if (player.y > 750) {
        lives--;
        updateUI();
        if (lives <= 0) {
            gameOver();
            return;
        }
        resetPlayer();
    }

    // Camera
    const targetX = player.x - canvas.width / 3;
    const targetY = player.y - canvas.height / 2;
    camera.x += (targetX - camera.x) * 0.1;
    camera.y += (targetY - camera.y) * 0.1;
    camera.x = Math.max(0, camera.x);
    camera.y = Math.max(-100, Math.min(200, camera.y));

    // Screen shake
    if (screenShake > 0) screenShake--;

    // Update particles
    particles = particles.filter(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.1;
        p.life--;
        return p.life > 0;
    });

    // Update floating texts
    floatingTexts = floatingTexts.filter(ft => {
        ft.y += ft.vy;
        ft.life--;
        return ft.life > 0;
    });

    // Update clouds
    for (const cloud of clouds) {
        cloud.x += cloud.speed;
        if (cloud.x > 5200) cloud.x = -cloud.width;
    }
}

function gameOver() {
    gameRunning = false;
    document.getElementById('finalScore').textContent = score;
    document.getElementById('gameOverScreen').classList.remove('hidden');
}

function drawBackground() {
    // Sky gradient
    const skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
    skyGrad.addColorStop(0, '#0a0a2e');
    skyGrad.addColorStop(0.3, '#1a1a4e');
    skyGrad.addColorStop(0.6, '#2d1b69');
    skyGrad.addColorStop(1, '#4a2c8a');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Stars
    for (const star of stars) {
        const sx = star.x - camera.x * 0.1;
        const sy = star.y;
        const twinkle = Math.sin(Date.now() * 0.001 * star.speed + star.twinkle) * 0.5 + 0.5;
        ctx.fillStyle = `rgba(255, 255, 255, ${twinkle * 0.8})`;
        ctx.beginPath();
        ctx.arc(sx, sy, star.size, 0, Math.PI * 2);
        ctx.fill();
    }

    // Moon
    const moonX = canvas.width - 150 - camera.x * 0.05;
    const moonY = 100;
    ctx.fillStyle = '#fffde7';
    ctx.shadowColor = '#fffde7';
    ctx.shadowBlur = 40;
    ctx.beginPath();
    ctx.arc(moonX, moonY, 40, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Moon craters
    ctx.fillStyle = 'rgba(200, 200, 180, 0.3)';
    ctx.beginPath();
    ctx.arc(moonX - 10, moonY - 5, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(moonX + 15, moonY + 10, 6, 0, Math.PI * 2);
    ctx.fill();

    // Distant mountains (parallax layer 1)
    ctx.fillStyle = '#1a1a3e';
    ctx.beginPath();
    ctx.moveTo(0, canvas.height);
    for (let x = 0; x <= canvas.width + 100; x += 50) {
        const worldX = x + camera.x * 0.1;
        const height = Math.sin(worldX * 0.003) * 100 + Math.sin(worldX * 0.007) * 50 + 200;
        ctx.lineTo(x, canvas.height - height);
    }
    ctx.lineTo(canvas.width, canvas.height);
    ctx.fill();

    // Closer mountains (parallax layer 2)
    ctx.fillStyle = '#2a2a5e';
    ctx.beginPath();
    ctx.moveTo(0, canvas.height);
    for (let x = 0; x <= canvas.width + 100; x += 30) {
        const worldX = x + camera.x * 0.2;
        const height = Math.sin(worldX * 0.005) * 80 + Math.sin(worldX * 0.01) * 40 + 150;
        ctx.lineTo(x, canvas.height - height);
    }
    ctx.lineTo(canvas.width, canvas.height);
    ctx.fill();

    // Clouds
    for (const cloud of clouds) {
        const cx = cloud.x - camera.x * 0.3;
        if (cx > -cloud.width && cx < canvas.width + cloud.width) {
            ctx.fillStyle = `rgba(255, 255, 255, ${cloud.opacity * 0.3})`;
            ctx.beginPath();
            ctx.ellipse(cx, cloud.y, cloud.width/2, cloud.height/2, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.beginPath();
            ctx.ellipse(cx - cloud.width*0.3, cloud.y + 10, cloud.width*0.3, cloud.height*0.4, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.beginPath();
            ctx.ellipse(cx + cloud.width*0.3, cloud.y + 5, cloud.width*0.35, cloud.height*0.45, 0, 0, Math.PI * 2);
            ctx.fill();
        }
    }
}

function drawPlatform(platform) {
    const x = platform.x - camera.x;
    const y = platform.y - camera.y;

    if (x + platform.width < -50 || x > canvas.width + 50) return;

    const type = PLATFORM_TYPES[platform.type] || PLATFORM_TYPES.normal;

    // Platform shadow
    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.fillRect(x + 3, y + 3, platform.width, platform.height);

    // Main platform body
    const grad = ctx.createLinearGradient(x, y, x, y + platform.height);
    grad.addColorStop(0, type.topColor);
    grad.addColorStop(1, type.color);
    ctx.fillStyle = grad;
    ctx.fillRect(x, y, platform.width, platform.height);

    // Top highlight
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.fillRect(x, y, platform.width, 3);

    // Grass on top for normal platforms
    if (platform.type === 'normal') {
        ctx.fillStyle = '#7ddf6b';
        for (let gx = x; gx < x + platform.width; gx += 8) {
            const gh = 3 + Math.sin(gx * 0.5) * 2;
            ctx.fillRect(gx, y - gh, 3, gh);
        }
    }

    // Ice sparkle
    if (platform.type === 'ice') {
        ctx.fillStyle = 'rgba(255,255,255,0.5)';
        for (let i = 0; i < 3; i++) {
            const sx = x + Math.random() * platform.width;
            const sy = y + Math.random() * platform.height;
            ctx.fillRect(sx, sy, 2, 2);
        }
    }

    // Moving platform indicator
    if (platform.moving) {
        ctx.fillStyle = 'rgba(255,255,255,0.2)';
        ctx.fillRect(x + 5, y + 5, platform.width - 10, 3);
    }
}

function drawPlayer() {
    if (player.invincible > 0 && Math.floor(player.invincible / 5) % 2 === 0) return;

    const x = player.x - camera.x;
    const y = player.y - camera.y;

    // Trail
    for (const trail of player.trail) {
        const alpha = trail.life / 10;
        ctx.fillStyle = `rgba(100, 150, 255, ${alpha * 0.3})`;
        ctx.beginPath();
        ctx.arc(trail.x - camera.x, trail.y - camera.y, 5 * alpha, 0, Math.PI * 2);
        ctx.fill();
    }

    ctx.save();
    ctx.translate(x + player.width/2, y + player.height/2);
    ctx.scale(player.facing, 1);

    // Body
    const bodyGrad = ctx.createLinearGradient(-12, -15, 12, 15);
    bodyGrad.addColorStop(0, '#667eea');
    bodyGrad.addColorStop(1, '#764ba2');
    ctx.fillStyle = bodyGrad;

    // Body shape
    ctx.beginPath();
    ctx.roundRect(-12, -15, 24, 30, 8);
    ctx.fill();

    // Head
    ctx.fillStyle = '#ffd5a0';
    ctx.beginPath();
    ctx.arc(0, -18, 10, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#333';
    ctx.beginPath();
    ctx.arc(3, -20, 2, 0, Math.PI * 2);
    ctx.fill();

    // Eye shine
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(4, -21, 1, 0, Math.PI * 2);
    ctx.fill();

    // Hair
    ctx.fillStyle = '#4a3728';
    ctx.beginPath();
    ctx.arc(0, -22, 10, Math.PI, Math.PI * 2);
    ctx.fill();

    // Legs animation
    const legAnim = player.onGround ? Math.sin(Date.now() * 0.01) * (Math.abs(player.vx) > 0.5 ? 5 : 0) : 3;
    ctx.fillStyle = '#5a4a3a';
    ctx.fillRect(-8, 12, 6, 8 + legAnim);
    ctx.fillRect(2, 12, 6, 8 - legAnim);

    // Shoes
    ctx.fillStyle = '#8b4513';
    ctx.fillRect(-9, 18 + legAnim, 8, 4);
    ctx.fillRect(1, 18 - legAnim, 8, 4);

    // Cape
    ctx.fillStyle = 'rgba(102, 126, 234, 0.6)';
    ctx.beginPath();
    ctx.moveTo(-10, -10);
    ctx.lineTo(-15 + Math.sin(Date.now() * 0.005) * 3, 15);
    ctx.lineTo(-5, 10);
    ctx.fill();

    ctx.restore();
}

function drawGem(gem) {
    if (gem.collected) return;
    const x = gem.x - camera.x;
    const y = gem.y - camera.y + Math.sin(Date.now() * 0.003 + gem.bobOffset) * 5;

    if (x < -50 || x > canvas.width + 50) return;

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(gem.rotation);

    // Glow
    const glowColor = gem.type === 'gold' ? 'rgba(255, 215, 0, 0.3)' : 'rgba(0, 255, 255, 0.3)';
    ctx.fillStyle = glowColor;
    ctx.beginPath();
    ctx.arc(0, 0, gem.size + 5, 0, Math.PI * 2);
    ctx.fill();

    // Gem shape
    const color = gem.type === 'gold' ? '#ffd700' : '#00ffff';
    const lightColor = gem.type === 'gold' ? '#fff8dc' : '#e0ffff';
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(0, -gem.size);
    ctx.lineTo(gem.size * 0.7, 0);
    ctx.lineTo(0, gem.size);
    ctx.lineTo(-gem.size * 0.7, 0);
    ctx.closePath();
    ctx.fill();

    // Highlight
    ctx.fillStyle = lightColor;
    ctx.beginPath();
    ctx.moveTo(0, -gem.size * 0.5);
    ctx.lineTo(gem.size * 0.3, 0);
    ctx.lineTo(0, gem.size * 0.3);
    ctx.lineTo(-gem.size * 0.3, 0);
    ctx.closePath();
    ctx.fill();

    ctx.restore();
}

function drawEnemy(enemy) {
    if (!enemy.alive) return;
    const x = enemy.x - camera.x;
    const y = enemy.y - camera.y;

    if (x < -50 || x > canvas.width + 50) return;

    ctx.save();
    ctx.translate(x, y);

    if (enemy.type === 'walker') {
        // Body
        ctx.fillStyle = '#ff6b6b';
        ctx.beginPath();
        ctx.roundRect(-15, -15, 30, 30, 5);
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(-5, -5, 5, 0, Math.PI * 2);
        ctx.arc(5, -5, 5, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#333';
        ctx.beginPath();
        ctx.arc(-5 + enemy.vx * 0.5, -5, 2, 0, Math.PI * 2);
        ctx.arc(5 + enemy.vx * 0.5, -5, 2, 0, Math.PI * 2);
        ctx.fill();

        // Mouth
        ctx.fillStyle = '#333';
        ctx.beginPath();
        ctx.arc(0, 5, 4, 0, Math.PI);
        ctx.fill();

        // Legs
        const legAnim = Math.sin(Date.now() * 0.01) * 3;
        ctx.fillStyle = '#cc5555';
        ctx.fillRect(-10, 13, 6, 8 + legAnim);
        ctx.fillRect(4, 13, 6, 8 - legAnim);
    } else {
        // Flyer
        ctx.fillStyle = '#9b59b6';
        ctx.beginPath();
        ctx.arc(0, 0, 15, 0, Math.PI * 2);
        ctx.fill();

        // Wings
        const wingFlap = Math.sin(Date.now() * 0.02) * 10;
        ctx.fillStyle = 'rgba(155, 89, 182, 0.6)';
        ctx.beginPath();
        ctx.ellipse(-18, -5 + wingFlap, 12, 6, -0.3, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.ellipse(18, -5 - wingFlap, 12, 6, 0.3, 0, Math.PI * 2);
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(-5, -3, 4, 0, Math.PI * 2);
        ctx.arc(5, -3, 4, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#ff0000';
        ctx.beginPath();
        ctx.arc(-5, -3, 2, 0, Math.PI * 2);
        ctx.arc(5, -3, 2, 0, Math.PI * 2);
        ctx.fill();
    }

    ctx.restore();
}

function drawParticles() {
    for (const p of particles) {
        const alpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.arc(p.x - camera.x, p.y - camera.y, p.size * alpha, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.globalAlpha = 1;
}

function drawFloatingTexts() {
    for (const ft of floatingTexts) {
        const alpha = ft.life / 60;
        ctx.fillStyle = ft.color;
        ctx.globalAlpha = alpha;
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(ft.text, ft.x - camera.x, ft.y - camera.y);
    }
    ctx.globalAlpha = 1;
}

function drawDecorations() {
    for (const dec of decorations) {
        const x = dec.x - camera.x * 0.5;
        const y = dec.y - camera.y;

        if (x < -100 || x > canvas.width + 100) continue;

        if (dec.type === 'tree') {
            // Tree trunk
            ctx.fillStyle = '#5a3a1a';
            ctx.fillRect(x - 5 * dec.size, y - 40 * dec.size, 10 * dec.size, 40 * dec.size);

            // Tree top
            ctx.fillStyle = '#2d5a1e';
            ctx.beginPath();
            ctx.arc(x, y - 50 * dec.size, 25 * dec.size, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = '#3a7a2a';
            ctx.beginPath();
            ctx.arc(x - 10 * dec.size, y - 45 * dec.size, 18 * dec.size, 0, Math.PI * 2);
            ctx.fill();

            ctx.beginPath();
            ctx.arc(x + 10 * dec.size, y - 45 * dec.size, 18 * dec.size, 0, Math.PI * 2);
            ctx.fill();
        } else {
            // Bush
            ctx.fillStyle = '#2d5a1e';
            ctx.beginPath();
            ctx.arc(x, y - 10 * dec.size, 15 * dec.size, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = '#3a7a2a';
            ctx.beginPath();
            ctx.arc(x - 8 * dec.size, y - 8 * dec.size, 10 * dec.size, 0, Math.PI * 2);
            ctx.fill();

            ctx.beginPath();
            ctx.arc(x + 8 * dec.size, y - 8 * dec.size, 10 * dec.size, 0, Math.PI * 2);
            ctx.fill();
        }
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Screen shake
    ctx.save();
    if (screenShake > 0) {
        ctx.translate(
            (Math.random() - 0.5) * screenShake * 2,
            (Math.random() - 0.5) * screenShake * 2
        );
    }

    drawBackground();
    drawDecorations();

    // Platforms
    for (const platform of platforms) {
        drawPlatform(platform);
    }

    // Gems
    for (const gem of gems) {
        drawGem(gem);
    }

    // Enemies
    for (const enemy of enemies) {
        drawEnemy(enemy);
    }

    // Player
    drawPlayer();

    // Particles
    drawParticles();

    // Floating texts
    drawFloatingTexts();

    ctx.restore();
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Initialize
generateLevel();
gameLoop();
</script>
</body>
</html>

