      }
      if (row < GRID_SIZE) {
        createWaypoint(x, zEnd - 1, 'south', false).lane = 'left';
      }
      if (row === 0) {
        createWaypoint(x, zStart, 'south', true, { type: 'intersection', roadCount: 4 }).lane = 'left';
      }
      if (row === GRID_SIZE) {
        createWaypoint(x, zEnd, 'south', true, { type: 'intersection', roadCount: 4 }).lane = 'left';
      }
    }
  }

  // Connect waypoints
  connectWaypoints();
}

function connectWaypoints() {
  const directionMap = {
    'north': { x: 0, z: -1 },
    'south': { x: 0, z: 1 },
    'east': { x: 1, z: 0 },
    'west': { x: -1, z: 0 }
  };

  for (const wp of waypoints) {
    const dir = directionMap[wp.direction];
    const searchDist = STREET_WIDTH / 2 + BLOCK_SIZE + 1;

    // Find next waypoint in direction
    for (const other of waypoints) {
      if (other === wp) continue;

      const dx = other.position.x - wp.position.x;
      const dz = other.position.z - wp.position.z;
      const dist = Math.sqrt(dx * dx + dz * dz);

      // Check if other is in the direction of wp's direction
      const dot = dx * dir.x + dz * dir.z;

      if (dot > 0 && dist < searchDist && dist > 1) {
        // Check if there's a clear path (no building in between)
        wp.targets.push(other);
      }
    }

    // For intersections, add all connected waypoints
    if (wp.isIntersection) {
      const connectedDirs = new Set();

      // Determine which roads connect to this intersection
      const x = wp.position.x;
      const z = wp.position.z;

      // Check horizontal connections
      const hasHorizontal = waypoints.some(w => 
        Math.abs(w.position.z - z) < 0.5 && w.position.x !== x && !w.isIntersection
      );
      // Check vertical connections
      const hasVertical = waypoints.some(w => 
        Math.abs(w.position.x - x) < 0.5 && w.position.z !== z && !w.isIntersection
      );

      if (hasHorizontal) {
        // Add east and west targets
        wp.targets.push(...waypoints.filter(w => 
          Math.abs(w.position.z - z) < 0.5 && 
          w.position.x !== x && 
          !w.isIntersection &&
          (w.direction === 'east' || w.direction === 'west')
        ));
      }
      if (hasVertical) {
        // Add north and south targets
        wp.targets.push(...waypoints.filter(w => 
          Math.abs(w.position.x - x) < 0.5 && 
          w.position.z !== z && 
          !w.isIntersection &&
          (w.direction === 'north' || w.direction === 'south')
        ));
      }
    }

    // Remove duplicate targets
    wp.targets = [...new Set(wp.targets)];
  }
}

