  // Headlights
  const lightGeo = new THREE.SphereGeometry(0.2, 8, 8);
  const lightMat = new THREE.MeshStandardMaterial({ color: 0xffffcc, emissive: 0xffffcc, emissiveIntensity: 0.5 });
  const headlight1 = new THREE.Mesh(lightGeo, lightMat);
  headlight1.position.set(-0.6, 0.8, 2);
  carGroup.add(headlight1);
  const headlight2 = new THREE.Mesh(lightGeo, lightMat);
  headlight2.position.set(0.6, 0.8, 2);
  carGroup.add(headlight2);

  // Tail lights
