  const tail1 = new THREE.Mesh(lightGeo, tailMat);
  tail1.position.set(-0.6, 0.8, -2);
  carGroup.add(tail1);
  const tail2 = new THREE.Mesh(lightGeo, tailMat);
  tail2.position.set(0.6, 0.8, -2);
  carGroup.add(tail2);

  // Find a starting waypoint
  const startWP = waypoint || waypoints[Math.floor(Math.random() * waypoints.length)];

  const car = {
    group: carGroup,
    currentWaypoint: startWP,
    targetWaypoint: startWP.targets.length > 0 ? startWP.targets[0] : startWP,
    speed: 3 + Math.random() * 2,
    progress: 0,
    direction: startWP.direction
  };

  carGroup.position.copy(startWP.position);

  // Orient car based on direction
  const rotationMap = {
    'north': Math.PI,
    'south': 0,
    'east': -Math.PI / 2,
    'west': Math.PI / 2
  };
  carGroup.rotation.y = rotationMap[startWP.direction] || 0;

  scene.add(carGroup);
  cars.push(car);
}

