// ============ CAMERA CONTROLS ============
let cameraAngleX = 0;
let cameraAngleY = 0.3;
let cameraDistance = 8;
let isPointerLocked = false;

const mouse = { x: 0, y: 0 };
const keys = { w: false, a: false, s: false, d: false, shift: false, space: false };

renderer.domElement.addEventListener('click', () => {
  renderer.domElement.requestPointerLock();
});

document.addEventListener('pointerlockchange', () => {
  isPointerLocked = document.pointerLockElement === renderer.domElement;
});

document.addEventListener('mousemove', (e) => {
  if (isPointerLocked) {
    cameraAngleX -= e.movementX * 0.002;
    cameraAngleY -= e.movementY * 0.002;
    cameraAngleY = Math.max(-Math.PI / 2.5, Math.min(Math.PI / 2.5, cameraAngleY));
  }
});

document.addEventListener('keydown', (e) => {
  switch(e.key.toLowerCase()) {
    case 'w': keys.w = true; break;
    case 'a': keys.a = true; break;
    case 's': keys.s = true; break;
    case 'd': keys.d = true; break;
    case 'shift': keys.shift = true; break;
    case 'space': keys.space = true; break;
  }
});

document.addEventListener('keyup', (e) => {
  switch(e.key.toLowerCase()) {
    case 'w': keys.w = false; break;
    case 'a': keys.a = false; break;
    case 's': keys.s = false; break;
    case 'd': keys.d = false; break;
    case 'shift': keys.shift = false; break;
    case 'space': keys.space = false; break;
  }
});

// ============ PLAYER PHYSICS ============
const playerVelocity = new THREE.Vector3();
const playerOnGround = true;
let playerVerticalVelocity = 0;
const gravity = -20;
const jumpForce = 8;
const moveSpeed = 8;
const sprintMultiplier = 1.8;

function updatePlayer(delta) {
  const speed = moveSpeed * (keys.shift ? sprintMultiplier : 1);

  // Calculate movement direction based on camera orientation
  const forward = new THREE.Vector3(-Math.sin(cameraAngleX), 0, -Math.cos(cameraAngleX));
  const right = new THREE.Vector3(Math.cos(cameraAngleX), 0, -Math.sin(cameraAngleX));

  const moveDir = new THREE.Vector3();

  if (keys.w) moveDir.add(forward);
  if (keys.s) moveDir.sub(forward);
  if (keys.a) moveDir.sub(right);
  if (d) moveDir.add(right);
  if (keys.d) moveDir.add(right);

  if (moveDir.length() > 0) {
    moveDir.normalize();
    playerVelocity.x = moveDir.x * speed;
    playerVelocity.z = moveDir.z * speed;
  } else {
    playerVelocity.x *= 0.85;
    playerVelocity.z *= 0.85;
  }

  // Jump
  if (keys.space && playerOnGround) {
    playerVerticalVelocity = jumpForce;
  }

  // Apply gravity
  playerVerticalVelocity += gravity * delta;

  // Update position
  player.position.x += playerVelocity.x * delta;
  player.position.z += playerVelocity.z * delta;
  player.position.y += playerVerticalVelocity * delta;

  // Ground collision
  if (player.position.y <= 1) {
    player.position.y = 1;
    playerVerticalVelocity = 0;
  }

  // Keep player in bounds
  const bound = HALF_TOTAL - 2;
  player.position.x = Math.max(-bound, Math.min(bound, player.position.x));
  player.position.z = Math.max(-bound, Math.min(bound, player.position.z));

  // Rotate player to face movement direction
  if (moveDir.length() > 0.1) {
    const targetRotation = Math.atan2(moveDir.x, moveDir.z);
    player.rotation.y = targetRotation;
  }
}

// ============ CAMERA UPDATE ============
function updateCamera() {
  // Camera position relative to player
  const camX = player.position.x + cameraDistance * Math.sin(cameraAngleX) * Math.cos(cameraAngleY);
  const camY = player.position.y + 3 + cameraDistance * Math.sin(cameraAngleY);
  const camZ = player.position.z + cameraDistance * Math.cos(cameraAngleX) * Math.cos(cameraAngleY);

  camera.position.set(camX, camY, camZ);
  camera.lookAt(player.position.x, player.position.y + 1, player.position.z);
}

// ============ CAR AI UPDATE ============
function updateCars(delta) {
  for (const car of cars) {
    const currentPos = car.group.position;
    const targetPos = car.targetWaypoint.position;

    const direction = new THREE.Vector3().subVectors(targetPos, currentPos);
    const dist = direction.length();

    if (dist < 0.5) {
      // Reached waypoint, pick next
      if (car.targetWaypoint.targets.length > 0) {
        car.targetWaypoint = car.targetWaypoint.targets[Math.floor(Math.random() * car.targetWaypoint.targets.length)];
        car.direction = car.targetWaypoint.direction;
      } else {
        // Reverse if no targets
        car.targetWaypoint = car.currentWaypoint;
      }
    } else {
      // Move towards target
      direction.normalize();
      const moveSpeed = car.speed * delta;
      car.group.position.add(direction.multiplyScalar(moveSpeed));

      // Rotate car to face direction
      const rotationMap = {
        'north': Math.PI,
        'south': 0,
        'east': -Math.PI / 2,
        'west': Math.PI / 2
      };
      car.group.rotation.y = rotationMap[car.direction] || 0;
    }
  }
}

// ============ GAME LOOP ============
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const delta = Math.min(clock.getDelta(), 0.05);

  updatePlayer(delta);
  updateCamera();
  updateCars(delta);

  renderer.render(scene, camera);
}

// ============ WINDOW RESIZE ============
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start
animate();
