function addAchievement(name, icon) {
  if (gameState.achievements.includes(name)) return;
  gameState.achievements.push(name);

  const list = document.getElementById('achievements-list');
  if (list.querySelector('span')) list.innerHTML = '';

  const badge = document.createElement('span');
  badge.className = 'achievement';
  badge.innerHTML = `${icon} ${name}`;
  list.appendChild(badge);

  showNotification(`Achievement: ${name}`, 'success');
}

function updatePhaseIndicator(phase) {
  document.querySelectorAll('.phase-dot').forEach((dot, i) => {
    dot.classList.remove('active', 'completed');
    if (i < phase) dot.classList.add('completed');
    if (i === phase) dot.classList.add('active');
  });
}

