function renderChallenge() {
  const area = document.getElementById('challenge-area');
  area.innerHTML = '';

  let challenge;
  if (gameState.currentPhase === 0) {
    challenge = mindsetChallenges[gameState.currentChallenge];
  } else if (gameState.currentPhase === 1) {
    challenge = reconChallenges[gameState.currentChallenge];
  } else if (gameState.currentPhase === 2) {
    challenge = exploitChallenges[gameState.currentChallenge];
  } else {
    challenge = rootChallenges[gameState.currentChallenge];
  }

  if (!challenge) {
    area.innerHTML = '<div style="text-align:center; padding: 40px; color: var(--green);">🎉 All challenges completed! You are a master hacker!</div>';
    return;
  }

  const title = document.createElement('div');
  title.className = 'challenge-title';
  title.innerHTML = `⚡ ${challenge.title}`;
  area.appendChild(title);

  const desc = document.createElement('div');
  desc.className = 'challenge-description';
  desc.textContent = challenge.description;
  area.appendChild(desc);

  // Render based on challenge type
  if (challenge.type === 'portScan') {
    renderPortScan(challenge, area);
  } else if (challenge.type === 'vulnSelect') {
    renderVulnSelect(challenge, area);
  } else if (challenge.type === 'codeChallenge') {
    renderCodeChallenge(challenge, area);
  } else if (challenge.type === 'finalChallenge') {
    renderFinalChallenge(challenge, area);
  } else {
    renderQuizChallenge(challenge, area);
  }
}

function renderQuizChallenge(challenge, container) {
  const quiz = document.createElement('div');
