function handleQuizAnswer(challenge, isCorrect, btn, options) {
  if (btn.disabled) return;

  // Disable all buttons
  options.forEach((_, i) => {
    const b = btn.parentElement.children[i];
    b.disabled = true;
    if (challenge.options[i].correct) {
      b.style.borderColor = 'var(--green)';
      b.style.background = 'rgba(0, 255, 65, 0.1)';
    }
  });

  if (isCorrect) {
    btn.style.borderColor = 'var(--green)';
    btn.style.background = 'rgba(0, 255, 65, 0.15)';
    updateScore(challenge.points);
    gameState.skills[challenge.skill] = Math.min(100, gameState.skills[challenge.skill] + 25);
    updateSkills();
    showNotification(`+${challenge.points} points! Correct!`, 'success');
    addAchievement('Quick Thinker', '🧠');
  } else {
    btn.style.borderColor = 'var(--red)';
    btn.style.background = 'rgba(255, 0, 64, 0.1)';
    showNotification('Incorrect! Review the explanation.', 'error');
  }

  // Show explanation
  const expl = document.createElement('div');
  expl.style.marginTop = '15px';
  expl.style.padding = '15px';
  expl.style.background = 'rgba(0, 0, 0, 0.3)';
  expl.style.borderRadius = '8px';
  expl.style.borderLeft = '3px solid var(--cyan)';
  expl.style.color = '#aaa';
  expl.style.fontSize = '0.85em';
  expl.style.lineHeight = '1.6';
  expl.innerHTML = `<strong style="color: var(--cyan);">💡 Explanation:</strong> ${challenge.explanation}`;
  btn.parentElement.appendChild(expl);

  // Next button
  const nextBtn = document.createElement('button');
  nextBtn.className = 'btn btn-primary';
  nextBtn.style.marginTop = '15px';
  nextBtn.textContent = 'Next Challenge →';
  nextBtn.onclick = () => nextChallenge();
  btn.parentElement.appendChild(nextBtn);
}

function renderPortScan(challenge, container) {
  const grid = document.createElement('div');
  grid.className = 'port-grid';

  challenge.ports.forEach(port => {
    const cell = document.createElement('div');
    cell.className = 'port-cell';
    cell.innerHTML = `<div class="port-number">${port}</div><div class="port-status">???</div>`;
    cell.onclick = () => scanPort(cell, port, challenge);
    grid.appendChild(cell);
  });

  container.appendChild(grid);

  const info = document.createElement('div');
  info.style.marginTop = '10px';
  info.style.color = '#888';
  info.style.fontSize = '0.8em';
  info.textContent = `🔍 Click ports to scan. Find all open ports to proceed. (${challenge.openPorts.length} open)`;
  container.appendChild(info);
}

function scanPort(cell, port, challenge) {
  if (cell.classList.contains('scanned')) return;

  cell.classList.add('scanned');
  gameState.scannedPorts.add(port);

  if (challenge.openPorts.includes(port)) {
    cell.classList.add('open');
    cell.querySelector('.port-status').textContent = 'OPEN';
    gameState.openPorts.add(port);
    showNotification(`Port ${port} is OPEN!`, 'success');
  } else {
    cell.classList.add('closed');
    cell.querySelector('.port-status').textContent = 'CLOSED';
  }

  // Check if all open ports found
  if (gameState.openPorts.size === challenge.openPorts.length) {
    updateScore(challenge.points);
    gameState.skills[challenge.skill] = Math.min(100, gameState.skills[challenge.skill] + 25);
    updateSkills();
    showNotification(`+${challenge.points} points! All ports discovered!`, 'success');
    addAchievement('Port Scanner', '🔍');

    const nextBtn = document.createElement('button');
    nextBtn.className = 'btn btn-primary';
    nextBtn.style.marginTop = '15px';
    nextBtn.textContent = 'Next Challenge →';
    nextBtn.onclick = () => nextChallenge();
    container.appendChild(nextBtn);
  }
}

