  gameState.currentChallenge++;

  const phaseChallenges = [
    mindsetChallenges,
    reconChallenges,
    exploitChallenges,
    rootChallenges
  ];

  if (gameState.currentChallenge >= phaseChallenges[gameState.currentPhase].length) {
    gameState.currentChallenge = 0;
    gameState.currentPhase++;

    if (gameState.currentPhase >= 4) {
      completeMission();
      return;
    }

    updatePhaseIndicator(gameState.currentPhase);
    showNotification(`Phase ${gameState.currentPhase + 1} started!`, 'info');
  }

  updateProgress();
  renderChallenge();
