    keys[e.key.toLowerCase()] = false;
    keys[e.code] = false;
});

function toggleFlashlight() {
    flashlightOn = !flashlightOn;
    document.getElementById('flashlightStatus').textContent = flashlightOn ? 'ON' : 'OFF';
}

function handleDoorInteraction() {
    const loc = locations[currentLocation];
    if (!loc) return;

    for (let door of loc.doors) {
        const dx = Math.abs(player.x - door.x);
        const dy = Math.abs(player.y - door.y);
        if (dx < 50 && dy < 30) {
            moveToLocation(door.target);
            return;
        }
    }
}

function moveToLocation(target) {
    currentLocation = target;
    const loc = locations[target];
    if (!loc) return;

    // Set player position based on door
    for (let door of loc.doors) {
        if (door.target === currentLocation || Object.values(locations).find(l => l.doors.includes(door))) {
            // Find the door that leads TO this location
        }
    }

    // Default positioning
    player.x = loc.width / 2;
    player.y = loc.height / 2;

    document.getElementById('location').textContent = loc.name;

    // Check for horror triggers
    if (target === GameState.RUKO_LOBBY && customersServed >= totalCustomers) {
        startHorrorSequence();
    }
}

function pickupItem() {
    const loc = locations[currentLocation];
    if (!loc) return;

    for (let item of loc.items) {
        if (item.collected) continue;
        const dx = Math.abs(player.x - (item.x + item.w/2));
        const dy = Math.abs(player.y - (item.y + item.h/2));
        if (dx < 40 && dy < 40) {
            item.collected = true;
            collectedItems.push(item);
            document.getElementById('itemCount').textContent = collectedItems.length;

            if (item.type === 'letter') {
                storyboardIndex = 2;
                showStoryboard();
            }
            if (item.type === 'scissors') {
                player.hasScissors = true;
            }
            break;
        }
    }
}

function cutHair() {
    const loc = locations[currentLocation];
    if (!loc) return;

    for (let customer of customers) {
        if (!customer.active) continue;
        const dx = Math.abs(player.x - customer.x);
        const dy = Math.abs(player.y - customer.y);
        if (dx < 60 && dy < 60) {
            if (player.hasScissors || customer.hairLength > 0) {
                customer.hairLength -= 20;
                if (customer.hairLength <= 0) {
                    customer.active = false;
                    customersServed++;
                    document.getElementById('customerCount').textContent = customersServed;

                    if (customersServed >= totalCustomers) {
                        setTimeout(() => {
                            storyboardIndex = 2;
                            showStoryboard();
                        }, 1000);
                    }
                }
            }
            break;
        }
    }
}

function showStoryboard() {
    if (storyboardIndex >= storyboards.length) {
        if (storyboards[storyboardIndex - 1].type === 'gameover') {
            showNews();
        }
        return;
    }

    const sb = storyboards[storyboardIndex];
    document.getElementById('storyTitle').textContent = sb.title;
    document.getElementById('storyText').textContent = sb.text;
    document.getElementById('storyboard').style.display = 'block';

    if (sb.type === 'chase') {
        currentState = GameState.CHASE_MODE;
    } else if (sb.type === 'gameover') {
        currentState = GameState.GAME_OVER;
    } else if (sb.type === 'horror_start') {
        currentState = GameState.HORROR_MODE;
        startHorrorEvents();
    } else {
        currentState = GameState.PLAYING;
    }
}

function nextStoryboard() {
    document.getElementById('storyboard').style.display = 'none';
    storyboardIndex++;

    if (storyboardIndex >= storyboards.length) {
        if (storyboards[storyboardIndex - 1].type === 'gameover') {
            showNews();
        } else {
            currentState = GameState.PLAYING;
        }
        return;
    }

    const sb = storyboards[storyboardIndex];
    document.getElementById('storyTitle').textContent = sb.title;
    document.getElementById('storyText').textContent = sb.text;
    document.getElementById('storyboard').style.display = 'block';

    if (sb.type === 'chase') {
        currentState = GameState.CHASE_MODE;
        startChase();
    } else if (sb.type === 'gameover') {
        currentState = GameState.GAME_OVER;
    } else if (sb.type === 'horror_start') {
        currentState = GameState.HORROR_MODE;
        startHorrorEvents();
    } else {
        currentState = GameState.PLAYING;
    }
}

function startHorrorEvents() {
    // Add horror letters
    horrorLetters = [
        {x: 100, y: 100, text: 'JANGAN MASUK...', rotation: 0},
        {x: 300, y: 200, text: 'LARI...', rotation: 0.3},
