// Drawing functions
function drawPixelCharacter(x, y, direction, frame, isPlayer, hairColor, hairLength) {
    ctx.save();

    if (isPlayer) {
        // Player Dimas - Citampi style pixel art
        const px = 4; // pixel size

        // Body
        ctx.fillStyle = '#2196F3'; // Blue shirt
        ctx.fillRect(x + 4*px, y + 8*px, 6*px, 8*px);

        // Head
        ctx.fillStyle = '#FFDAB9'; // Skin tone
        ctx.fillRect(x + 3*px, y, 8*px, 8*px);

        // Hair
        ctx.fillStyle = hairColor || '#2C1810';
        ctx.fillRect(x + 2*px, y - 2*px, 10*px, 4*px);
        ctx.fillRect(x + 2*px, y - 2*px, 2*px, 6*px);
        ctx.fillRect(x + 10*px, y - 2*px, 2*px, 6*px);

        // Eyes
        ctx.fillStyle = '#000';
        if (direction === 'down' || direction === 'left' || direction === 'right') {
            ctx.fillRect(x + 4*px, y + 3*px, 2*px, 2*px);
            ctx.fillRect(x + 7*px, y + 3*px, 2*px, 2*px);
        }

        // Mouth
        ctx.fillStyle = '#C62828';
        ctx.fillRect(x + 5*px, y + 6*px, 4*px, 1*px);

        // Legs
        ctx.fillStyle = '#1565C0';
        ctx.fillRect(x + 3*px, y + 16*px, 3*px, 6*px);
        ctx.fillRect(x + 7*px, y + 16*px, 3*px, 6*px);

        // Shoes
        ctx.fillStyle = '#333';
        ctx.fillRect(x + 2*px, y + 21*px, 4*px, 2*px);
        ctx.fillRect(x + 7*px, y + 21*px, 4*px, 2*px);

        // Arms
        ctx.fillStyle = '#FFDAB9';
        const armOffset = Math.sin(frame * 0.2) * 2;
        ctx.fillRect(x + px, y + 9*px + armOffset, 3*px, 6*px);
        ctx.fillRect(x + 11*px, y + 9*px - armOffset, 3*px, 6*px);

        // Scissors if has them
        if (player.hasScissors) {
            ctx.fillStyle = '#C0C0C0';
            ctx.fillRect(x + 12*px, y + 9*px - armOffset, 4*px, 2*px);
        }

    } else {
        // Customer - simpler pixel art
        const px = 4;

        // Body
        ctx.fillStyle = '#4CAF50';
        ctx.fillRect(x + 4*px, y + 8*px, 6*px, 8*px);

        // Head
        ctx.fillStyle = '#FFDAB9';
        ctx.fillRect(x + 3*px, y, 8*px, 8*px);

        // Hair (long based on hairLength)
        ctx.fillStyle = hairColor || '#8B4513';
        const hairHeight = Math.max(2, hairLength / 20);
        ctx.fillRect(x + 2*px, y - hairHeight*px, 10*px, (2 + hairHeight)*px);
        ctx.fillRect(x + 2*px, y - hairHeight*px, 2*px, (4 + hairHeight)*px);
        ctx.fillRect(x + 10*px, y - hairHeight*px, 2*px, (4 + hairHeight)*px);

        // Eyes
        ctx.fillStyle = '#000';
        ctx.fillRect(x + 4*px, y + 3*px, 2*px, 2*px);
        ctx.fillRect(x + 7*px, y + 3*px, 2*px, 2*px);

        // Mouth
        ctx.fillStyle = '#C62828';
        ctx.fillRect(x + 5*px, y + 6*px, 4*px, 1*px);

        // Legs
        ctx.fillStyle = '#333';
        ctx.fillRect(x + 3*px, y + 16*px, 3*px, 6*px);
        ctx.fillRect(x + 7*px, y + 16*px, 3*px, 6*px);

        // Shoes
        ctx.fillStyle = '#111';
        ctx.fillRect(x + 2*px, y + 21*px, 4*px, 2*px);
        ctx.fillRect(x + 7*px, y + 21*px, 4*px, 2*px);
    }

    ctx.restore();
}

function drawLocation(loc) {
    if (!loc) return;

    // Background
    if (alternateDimension) {
        ctx.fillStyle = '#1a0000';
    } else if (currentLocation === GameState.PARKING) {
        ctx.fillStyle = '#2d2d2d';
    } else if (currentLocation === GameState.WC || currentLocation === GameState.HOUSE_WC || currentLocation === GameState.RUKO_WC) {
        ctx.fillStyle = '#e0e0e0';
    } else {
        ctx.fillStyle = '#f5f5dc';
    }
    ctx.fillRect(0, 0, loc.width, loc.height);

    // Floor pattern
    if (!alternateDimension) {
        ctx.fillStyle = 'rgba(0,0,0,0.05)';
        for (let i = 0; i < loc.width; i += 40) {
            for (let j = 0; j < loc.height; j += 40) {
                if ((i + j) % 80 === 0) {
                    ctx.fillRect(i, j, 40, 40);
                }
            }
        }
    }

    // Walls
    ctx.fillStyle = alternateDimension ? '#3a0000' : '#8B4513';
    for (let wall of loc.walls) {
        ctx.fillRect(wall.x, wall.y, wall.w, wall.h);
    }

    // Doors
    ctx.fillStyle = '#8B6914';
    for (let door of loc.doors) {
        ctx.fillRect(door.x, door.y, door.w, door.h);
        ctx.fillStyle = '#FFD700';
        ctx.fillRect(door.x + door.w/2 - 2, door.y + door.h/2 - 2, 4, 4);
        ctx.fillStyle = '#8B6914';
    }

    // Furniture
    for (let furn of loc.furniture) {
        switch(furn.type) {
            case 'chair':
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#A0522D';
                ctx.fillRect(furn.x + 5, furn.y + 5, furn.w - 10, furn.h - 10);
                // Chair back
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(furn.x, furn.y - 10, furn.w, 10);
                break;
            case 'counter':
                ctx.fillStyle = '#654321';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#8B6914';
                ctx.fillRect(furn.x + 2, furn.y + 2, furn.w - 4, furn.h - 4);
                break;
            case 'mirror':
                ctx.fillStyle = '#C0C0C0';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#E8E8E8';
                ctx.fillRect(furn.x + 5, furn.y + 5, furn.w - 10, furn.h - 10);
                break;
            case 'bed':
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(furn.x + 5, furn.y + 5, furn.w - 10, furn.h - 10);
                // Pillow
                ctx.fillStyle = '#F0F0F0';
                ctx.fillRect(furn.x + 10, furn.y + 10, 30, 20);
                break;
            case 'wardrobe':
                ctx.fillStyle = '#4A2800';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#6B3A00';
                ctx.fillRect(furn.x + 5, furn.y + 5, furn.w - 10, furn.h - 10);
                break;
            case 'table':
                ctx.fillStyle = '#8B6914';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#A0782C';
                ctx.fillRect(furn.x + 3, furn.y + 3, furn.w - 6, furn.h - 6);
                break;
            case 'toilet':
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#E8E8E8';
                ctx.fillRect(furn.x + 5, furn.y + 5, furn.w - 10, furn.h - 10);
                break;
            case 'sink':
                ctx.fillStyle = '#C0C0C0';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                break;
            case 'stove':
                ctx.fillStyle = '#333';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#555';
                ctx.fillRect(furn.x + 5, furn.y + 5, furn.w - 10, furn.h - 10);
                break;
            case 'fridge':
                ctx.fillStyle = '#E8E8E8';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#D0D0D0';
                ctx.fillRect(furn.x + 5, furn.y + 5, furn.w - 10, furn.h - 10);
                break;
            case 'car':
                ctx.fillStyle = '#CC0000';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#FF6666';
                ctx.fillRect(furn.x + 10, furn.y + 5, furn.w - 20, furn.h - 10);
                // Wheels
                ctx.fillStyle = '#333';
                ctx.fillRect(furn.x + 10, furn.y + furn.h - 5, 20, 5);
                ctx.fillRect(furn.x + furn.w - 30, furn.y + furn.h - 5, 20, 5);
                break;
            case 'motor':
                ctx.fillStyle = '#0066CC';
                ctx.fillRect(furn.x + 20, furn.y + 10, 60, 40);
                ctx.fillStyle = '#333';
                ctx.fillRect(furn.x + 10, furn.y + 50, 20, 10);
                ctx.fillRect(furn.x + 70, furn.y + 50, 20, 10);
                break;
            case 'shelf':
                ctx.fillStyle = '#8B6914';
                ctx.fillRect(furn.x, furn.y, furn.w, furn.h);
                ctx.fillStyle = '#A0782C';
                for (let i = 0; i < 3; i++) {
                    ctx.fillRect(furn.x + 5, furn.y + 10 + i * 15, furn.w - 10, 3);
                }
                break;
        }
    }

    // Items on ground
    for (let item of loc.items) {
        if (item.collected) continue;

        switch(item.type) {
            case 'scissors':
                ctx.fillStyle = '#C0C0C0';
                ctx.fillRect(item.x, item.y, item.w, item.h);
                ctx.fillStyle = '#E0E0E0';
                ctx.fillRect(item.x + 2, item.y + 2, item.w - 4, item.h - 4);
                break;
            case 'comb':
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(item.x, item.y, item.w, item.h);
                break;
            case 'key':
                ctx.fillStyle = '#FFD700';
                ctx.fillRect(item.x, item.y, item.w, item.h);
                break;
            case 'letter':
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(item.x, item.y, item.w + 10, item.h + 5);
                ctx.fillStyle = '#000';
                ctx.fillRect(item.x + 3, item.y + 2, item.w + 4, 2);
                ctx.fillRect(item.x + 3, item.y + 6, item.w, 2);
                break;
            case 'knife':
                ctx.fillStyle = '#C0C0C0';
                ctx.fillRect(item.x, item.y, item.w, item.h);
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(item.x, item.y + item.h - 5, item.w, 5);
                break;
            case 'candle':
                ctx.fillStyle = '#FFFF00';
                ctx.fillRect(item.x, item.y, item.w, item.h);
                // Flame
                ctx.fillStyle = '#FF6600';
                ctx.fillRect(item.x + 6, item.y - 5, 6, 8);
                break;
            case 'photo':
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(item.x, item.y, item.w + 10, item.h + 10);
                ctx.fillStyle = '#888';
                ctx.fillRect(item.x + 3, item.y + 3, item.w + 4, item.h + 4);
                break;
        }
    }

    // Horror letters
    for (let letter of horrorLetters) {
        ctx.save();
        ctx.translate(letter.x + 20, letter.y + 10);
        ctx.rotate(letter.rotation);
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(-20, -10, 40, 20);
        ctx.fillStyle = '#FF0000';
        ctx.font = '8px Courier New';
        ctx.fillText(letter.text, -18, 0);
        ctx.restore();
    }

    // Horror entities
    for (let entity of horrorEntities) {
        if (!entity.active) continue;

        ctx.save();
        if (entity.type === 'shadow') {
            ctx.fillStyle = 'rgba(0,0,0,0.7)';
            ctx.beginPath();
            ctx.arc(entity.x + 20, entity.y + 30, 25, 0, Math.PI * 2);
            ctx.fill();
            // Eyes
            ctx.fillStyle = '#FF0000';
            ctx.fillRect(entity.x + 10, entity.y + 20, 5, 5);
            ctx.fillRect(entity.x + 25, entity.y + 20, 5, 5);
        } else if (entity.type === 'ghost') {
            ctx.fillStyle = 'rgba(255,255,255,0.3)';
            ctx.beginPath();
            ctx.arc(entity.x + 20, entity.y + 30, 30, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#000';
            ctx.fillRect(entity.x + 10, entity.y + 20, 8, 8);
            ctx.fillRect(entity.x + 22, entity.y + 20, 8, 8);
        }
        ctx.restore();
    }

    // Chase entity
    if (chaseEntity && chaseEntity.active) {
        ctx.save();
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(chaseEntity.x + 20, chaseEntity.y + 30, 35, 0, Math.PI * 2);
        ctx.fill();
        // Scary face
        ctx.fillStyle = '#FF0000';
        ctx.fillRect(chaseEntity.x + 8, chaseEntity.y + 15, 10, 10);
        ctx.fillRect(chaseEntity.x + 22, chaseEntity.y + 15, 10, 10);
        ctx.fillStyle = '#FFF';
        ctx.fillRect(chaseEntity.x + 10, chaseEntity.y + 17, 6, 6);
        ctx.fillRect(chaseEntity.x + 24, chaseEntity.y + 17, 6, 6);
        // Mouth
        ctx.fillStyle = '#FF0000';
        ctx.fillRect(chaseEntity.x + 10, chaseEntity.y + 35, 20, 8);
        ctx.restore();
    }

    // Customers
    for (let customer of customers) {
        if (!customer.active) continue;
        drawPixelCharacter(customer.x, customer.y, 'down', customer.frame, false, customer.color, customer.hairLength);

        // Name tag
        ctx.fillStyle = '#000';
        ctx.font = '10px Courier New';
        ctx.fillText(customer.name, customer.x, customer.y - 10);

        // Hair length indicator
        ctx.fillStyle = '#FFD700';
        ctx.fillRect(customer.x, customer.y - 5, customer.hairLength / 5, 3);
    }

    // Player
    drawPixelCharacter(player.x, player.y, player.direction, player.frame, true, '#2C1810', player.hairLength);

    // Player name
    ctx.fillStyle = '#00FF00';
    ctx.font = '12px Courier New';
    ctx.fillText('DIMAS', player.x - 10, player.y - 15);

    // Interaction prompt
    const loc = locations[currentLocation];
    if (loc) {
        for (let door of loc.doors) {
            const dx = Math.abs(player.x - door.x);
            const dy = Math.abs(player.y - door.y);
            if (dx < 50 && dy < 30) {
                ctx.fillStyle = 'rgba(0,0,0,0.7)';
                ctx.fillRect(player.x - 50, player.y - 40, 100, 20);
                ctx.fillStyle = '#FFF';
                ctx.font = '10px Courier New';
                ctx.fillText('E: ' + door.label, player.x - 45, player.y - 25);
            }
        }

        for (let item of loc.items) {
            if (item.collected) continue;
            const dx = Math.abs(player.x - (item.x + item.w/2));
            const dy = Math.abs(player.y - (item.y + item.h/2));
            if (dx < 40 && dy < 40) {
                ctx.fillStyle = 'rgba(0,0,0,0.7)';
                ctx.fillRect(player.x - 50, player.y - 40, 100, 20);
                ctx.fillStyle = '#FFD700';
                ctx.font = '10px Courier New';
                ctx.fillText('G: ' + item.label, player.x - 45, player.y - 25);
            }
        }

        for (let customer of customers) {
            if (!customer.active) continue;
            const dx = Math.abs(player.x - customer.x);
            const dy = Math.abs(player.y - customer.y);
            if (dx < 60 && dy < 60) {
                ctx.fillStyle = 'rgba(0,0,0,0.7)';
                ctx.fillRect(player.x - 50, player.y - 40, 100, 20);
                ctx.fillStyle = '#00FF00';
                ctx.font = '10px Courier New';
                ctx.fillText('H: Mangkas ' + customer.name, player.x - 55, player.y - 25);
            }
        }
    }
}

function drawFlashlight() {
    if (!flashlightOn) return;

    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';

    const gradient = ctx.createRadialGradient(
        player.x + 16, player.y + 24, 10,
        player.x + 16, player.y + 24, 150
    );
    gradient.addColorStop(0, 'rgba(255,255,255,1)');
    gradient.addColorStop(1, 'rgba(255,255,255,0)');

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(player.x + 16, player.y + 24, 150, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();

    // Light overlay
    ctx.save();
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = 'rgba(255,255,200,0.1)';
    ctx.beginPath();
    ctx.arc(player.x + 16, player.y + 24, 150, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
}

function drawRedOverlay() {
    if (redOverlay > 0) {
        ctx.save();
        ctx.fillStyle = `rgba(255,0,0,${redOverlay})`;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.restore();
    }
}

function drawMinimap() {
    minimapCtx.fillStyle = '#000';
    minimapCtx.fillRect(0, 0, 150, 150);

    // Draw all locations as small rectangles
    const locKeys = Object.keys(locations);
    const locNames = ['Barbershop', 'WC', 'Parkir', 'Kamar', 'Dapur', 'WC Rumah', 'WC Ruko', 'Lobby Ruko'];

    let idx = 0;
    for (let key of locKeys) {
        const loc = locations[key];
        const x = (idx % 4) * 38;
        const y = Math.floor(idx / 4) * 38;

        minimapCtx.fillStyle = key === currentLocation ? '#00FF00' : '#666';
        minimapCtx.fillRect(x, y, 35, 35);

        minimapCtx.fillStyle = '#FFF';
        minimapCtx.font = '6px Courier New';
        minimapCtx.fillText(locNames[idx] || key, x + 2, y + 10);

        idx++;
    }

    // Player position
    const loc = locations[currentLocation];
    if (loc) {
        const px = ((player.x / loc.width) * 35) + ((idx % 4) * 38);
        const py = ((player.y / loc.height) * 35) + (Math.floor(idx / 4) * 38);
        minimapCtx.fillStyle = '#FF0000';
        minimapCtx.fillRect(px - 2, py - 2, 4, 4);
    }
}

function updatePlayer() {
    if (currentState !== GameState.PLAYING && currentState !== GameState.HORROR_MODE) return;

    let dx = 0, dy = 0;
    player.moving = false;

    if (keys['w'] || keys['ArrowUp']) { dy = -player.speed; player.direction = 'up'; player.moving = true; }
    if (keys['s'] || keys['ArrowDown']) { dy = player.speed; player.direction = 'down'; player.moving = true; }
    if (keys['a'] || keys['ArrowLeft']) { dx = -player.speed; player.direction = 'left'; player.moving = true; }
    if (keys['d'] || keys['ArrowRight']) { dx = player.speed; player.direction = 'right'; player.moving = true; }

    if (player.moving) {
        player.frame++;

        const newX = player.x + dx;
        const newY = player.y + dy;
        const loc = locations[currentLocation];

        // Collision detection
        let canMove = true;

        for (let wall of loc.walls) {
            if (newX < wall.x + wall.w && newX + player.width > wall.x &&
                newY < wall.y + wall.h && newY + player.height > wall.y) {
                canMove = false;
                break;
            }
        }

        if (canMove) {
            player.x = Math.max(0, Math.min(loc.width - player.width, newX));
            player.y = Math.max(0, Math.min(loc.height - player.height, newY));
        }
    }

    // Update customer frames
    for (let customer of customers) {
        if (customer.active) {
            customer.frame++;
        }
    }
}

function updateHorror() {
    if (currentState !== GameState.HORROR_MODE) return;

    // Update horror entities
    for (let entity of horrorEntities) {
        if (!entity.active) continue;

        const dx = player.x - entity.x;
        const dy = player.y - entity.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > 0) {
            entity.x += (dx / dist) * entity.speed;
            entity.y += (dy / dist) * entity.speed;
        }

        // Rotate letters
        for (let letter of horrorLetters) {
            letter.rotation += 0.01;
        }
    }

    // Scare timer
    scareTimer++;
    if (scareTimer > 300) {
        scareTimer = 0;
        // Random scare
        if (Math.random() < 0.3) {
            redOverlay = 0.3;
            setTimeout(() => { redOverlay = 0.1; }, 500);
        }
    }
}

function updateChase() {
    if (currentState !== GameState.CHASE_MODE || !chaseEntity) return;

    // Update red overlay
    redOverlay = 0.3 + Math.sin(gameTime * 0.05) * 0.2;

    // Chase entity follows player
    const dx = player.x - chaseEntity.x;
    const dy = player.y - chaseEntity.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist > 0) {
        chaseEntity.x += (dx / dist) * chaseEntity.speed;
        chaseEntity.y += (dy / dist) * chaseEntity.speed;
    }

    // Check if caught
    if (dist < 40) {
        chaseEntity.active = false;
        currentState = GameState.GAME_OVER;
        storyboardIndex = 5;
        showStoryboard();
    }

    // Player speed boost when being chased
    player.speed = 4;
}

function update() {
    gameTime++;
    updatePlayer();
    updateHorror();
    updateChase();
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (currentState === GameState.MENU) {
        drawMenu();
        return;
    }

    const loc = locations[currentLocation];
    if (loc) {
        // Center the location on screen
        const offsetX = (canvas.width - loc.width) / 2;
        const offsetY = (canvas.height - loc.height) / 2;

        ctx.save();
        ctx.translate(offsetX, offsetY);

        drawLocation(loc);
        drawFlashlight();

        ctx.restore();
    }

    drawRedOverlay();
    drawMinimap();

    // Horror atmosphere effects
    if (currentState === GameState.HORROR_MODE || currentState === GameState.CHASE_MODE) {
        // Static noise
        ctx.save();
        for (let i = 0; i < 100; i++) {
            ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.1})`;
            ctx.fillRect(Math.random() * canvas.width, Math.random() * canvas.height, 2, 2);
        }
        ctx.restore();

        // Vignette
        const gradient = ctx.createRadialGradient(
            canvas.width/2, canvas.height/2, 100,
            canvas.width/2, canvas.height/2, 400
        );
        gradient.addColorStop(0, 'rgba(0,0,0,0)');
        gradient.addColorStop(1, 'rgba(0,0,0,0.5)');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
}

function drawMenu() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Title
    ctx.fillStyle = '#FF0000';
    ctx.font = '48px Courier New';
    ctx.textAlign = 'center';
    ctx.fillText('BARBER SHOP', canvas.width/2, 150);
    ctx.fillText('HORROR', canvas.width/2, 200);

    // Subtitle
    ctx.fillStyle = '#FFF';
    ctx.font = '20px Courier New';
    ctx.fillText('Sebuah cerita tentang Dimas', canvas.width/2, 260);

    // Character preview
    drawPixelCharacter(canvas.width/2 - 16, 300, 'down', 0, true, '#2C1810', 50);

    // Instructions
    ctx.fillStyle = '#AAA';
    ctx.font = '14px Courier New';
    ctx.fillText('WASD/Panah: Gerak', canvas.width/2, 420);
    ctx.fillText('E: Pindah Tempat', canvas.width/2, 440);
    ctx.fillText('F: Senter | G: Ambil Barang', canvas.width/2, 460);
    ctx.fillText('H: Mangkas | R: Lanjut Story', canvas.width/2, 480);

    // Start button
    ctx.fillStyle = '#FF0000';
    ctx.fillRect(canvas.width/2 - 100, 520, 200, 40);
    ctx.fillStyle = '#FFF';
    ctx.font = '18px Courier New';
    ctx.fillText('MULAI', canvas.width/2, 545);

    ctx.textAlign = 'left';

    // Check for start
    if (keys[' '] || keys['Enter']) {
        restartGame();
    }
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Initialize
createCustomers();
gameLoop();
</script>
