<script>
// ============ GAME CONFIG ============
const CONFIG = {
  WIDTH: 400,
  HEIGHT: 700,
  GRAVITY: 0.5,
  JUMP_FORCE: -8,
  BIRD_SIZE: 34,
  PIPE_WIDTH: 60,
  PIPE_GAP_BASE: 160,
  PIPE_GAP_MIN: 120,
  PIPE_SPEED_BASE: 2.5,
  PIPE_SPEED_MAX: 5,
  PIPE_SPAWN_BASE: 1800,
  PIPE_SPAWN_MIN: 1000,
  GROUND_HEIGHT: 80,
  COIN_SIZE: 20,
  DIFFICULTY_START: 3,
  DIFFICULTY_STEP: 0.10
};

// ============ AUDIO ENGINE ============
class AudioEngine {
  constructor() {
    this.ctx = null;
    this.initialized = false;
    this.musicPlaying = false;
    this.musicGain = null;
    this.sfxGain = null;
  }

  init() {
    if (this.initialized) return;
    try {
      this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = 0.15;
      this.musicGain.connect(this.ctx.destination);
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = 0.4;
      this.sfxGain.connect(this.ctx.destination);
      this.initialized = true;
    } catch(e) {
      console.log('Audio not available');
    }
  }

  playJump() {
    if (!this.initialized) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.connect(gain);
    gain.connect(this.sfxGain);
    osc.type = 'sine';
    osc.frequency.setValueAtTime(400, this.ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(600, this.ctx.currentTime + 0.1);
    gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.15);
    osc.start(this.ctx.currentTime);
    osc.stop(this.ctx.currentTime + 0.15);
  }

  playScore() {
    if (!this.initialized) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.connect(gain);
    gain.connect(this.sfxGain);
    osc.type = 'sine';
    osc.frequency.setValueAtTime(523, this.ctx.currentTime);
    osc.frequency.setValueAtTime(659, this.ctx.currentTime + 0.1);
    osc.frequency.setValueAtTime(784, this.ctx.currentTime + 0.2);
    gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);
    osc.start(this.ctx.currentTime);
    osc.stop(this.ctx.currentTime + 0.3);
  }

  playCollision() {
    if (!this.initialized) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.connect(gain);
    gain.connect(this.sfxGain);
    osc.type = 'square';
    osc.frequency.setValueAtTime(200, this.ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(50, this.ctx.currentTime + 0.3);
    gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);
    osc.start(this.ctx.currentTime);
    osc.stop(this.ctx.currentTime + 0.3);
  }

  playGameOver() {
    if (!this.initialized) return;
    const notes = [400, 350, 300, 250];
    notes.forEach((freq, i) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.connect(gain);
      gain.connect(this.sfxGain);
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, this.ctx.currentTime + i * 0.2);
      gain.gain.setValueAtTime(0.3, this.ctx.currentTime + i * 0.2);
      gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + i * 0.2 + 0.2);
      osc.start(this.ctx.currentTime + i * 0.2);
      osc.stop(this.ctx.currentTime + i * 0.2 + 0.2);
    });
  }

  playCoin() {
    if (!this.initialized) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.connect(gain);
    gain.connect(this.sfxGain);
    osc.type = 'sine';
    osc.frequency.setValueAtTime(880, this.ctx.currentTime);
    osc.frequency.setValueAtTime(1100, this.ctx.currentTime + 0.05);
    gain.gain.setValueAtTime(0.2, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.15);
    osc.start(this.ctx.currentTime);
    osc.stop(this.ctx.currentTime + 0.15);
  }

  startMusic() {
    if (!this.initialized || this.musicPlaying) return;
    this.musicPlaying = true;
    this.playMusicLoop();
  }

  playMusicLoop() {
    if (!this.musicPlaying || !this.initialized) return;
    const notes = [262, 294, 330, 349, 392, 349, 330, 294];
    notes.forEach((freq, i) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.connect(gain);
      gain.connect(this.musicGain);
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, this.ctx.currentTime + i * 0.25);
      gain.gain.setValueAtTime(0.1, this.ctx.currentTime + i * 0.25);
      gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + i * 0.25 + 0.2);
      osc.start(this.ctx.currentTime + i * 0.25);
      osc.stop(this.ctx.currentTime + i * 0.25 + 0.2);
    });
    setTimeout(() => {
      if (this.musicPlaying) this.playMusicLoop();
    }, notes.length * 250);
  }

  stopMusic() {
    this.musicPlaying = false;
  }
}

// ============ GAME CLASS ============
class FlappyGame {
  constructor() {
    this.canvas = document.getElementById('gameCanvas');
    this.ctx = this.canvas.getContext('2d');
    this.audio = new AudioEngine();

    this.canvas.width = CONFIG.WIDTH;
    this.canvas.height = CONFIG.HEIGHT;

    this.state = 'START'; // START, PLAYING, GAME_OVER
    this.score = 0;
    this.highScore = parseInt(localStorage.getItem('flappyHighScore')) || 0;
    this.coins = parseInt(localStorage.getItem('flappyCoins')) || 0;
    this.totalCoins = this.coins;

    this.bird = {
      x: 80,
      y: CONFIG.HEIGHT / 2,
      velocity: 0,
      rotation: 0,
      frame: 0,
      frameTimer: 0
    };

    this.pipes = [];
    this.coins = [];
    this.particles = [];
    this.clouds = [];
    this.groundOffset = 0;

    this.pipeSpawnTimer = 0;
    this.pipeSpawnInterval = CONFIG.PIPE_SPAWN_BASE;
    this.pipeSpeed = CONFIG.PIPE_SPEED_BASE;
    this.pipeGap = CONFIG.PIPE_GAP_BASE;

    this.difficulty = 1;
    this.lastPipeScored = -1;

    this.lastTime = 0;
    this.animFrame = null;

    this.setupEvents();
    this.updateUI();
    this.generateClouds();
    this.render();
  }

  setupEvents() {
    // Touch/Click handling
    const handleInput = (e) => {
      e.preventDefault();
      if (this.state === 'START') {
        this.audio.init();
        this.startGame();
      } else if (this.state === 'PLAYING') {
        this.jump();
      }
    };

    this.canvas.addEventListener('touchstart', handleInput, { passive: false });
    this.canvas.addEventListener('mousedown', handleInput);

    // Buttons
    document.getElementById('startBtn').addEventListener('click', (e) => {
      e.stopPropagation();
      this.audio.init();
      this.startGame();
    });

    document.getElementById('restartBtn').addEventListener('click', (e) => {
      e.stopPropagation();
      this.startGame();
    });

    document.getElementById('homeBtn').addEventListener('click', (e) => {
      e.stopPropagation();
      this.goHome();
    });

    document.getElementById('youtubeBtn').addEventListener('click', (e) => {
      e.stopPropagation();
      window.open('https://www.youtube.com/@YourChannel', '_blank');
    });

    // Keyboard
    document.addEventListener('keydown', (e) => {
      if (e.code === 'Space') {
        e.preventDefault();
        if (this.state === 'START') {
          this.audio.init();
          this.startGame();
        } else if (this.state === 'PLAYING') {
          this.jump();
        }
      }
    });

    // Handle resize
    window.addEventListener('resize', () => this.resizeCanvas());
  }

  resizeCanvas() {
    const container = document.getElementById('gameContainer');
    const aspect = CONFIG.WIDTH / CONFIG.HEIGHT;
    const containerAspect = container.clientWidth / container.clientHeight;

    if (containerAspect > aspect) {
      this.canvas.style.height = '100%';
      this.canvas.style.width = (container.clientHeight * aspect) + 'px';
    } else {
      this.canvas.style.width = '100%';
      this.canvas.style.height = (container.clientWidth / aspect) + 'px';
    }
  }

  generateClouds() {
    this.clouds = [];
    for (let i = 0; i < 5; i++) {
      this.clouds.push({
        x: Math.random() * CONFIG.WIDTH,
        y: Math.random() * (CONFIG.HEIGHT * 0.4),
        size: 30 + Math.random() * 40,
        speed: 0.2 + Math.random() * 0.3
      });
    }
  }

  startGame() {
    this.state = 'PLAYING';
    this.score = 0;
    this.bird.y = CONFIG.HEIGHT / 2;
    this.bird.velocity = 0;
    this.bird.rotation = 0;
    this.pipes = [];
    this.coins = [];
    this.particles = [];
    this.pipeSpawnTimer = 0;
    this.pipeSpeed = CONFIG.PIPE_SPEED_BASE;
    this.pipeGap = CONFIG.PIPE_GAP_BASE;
    this.difficulty = 1;
    this.lastPipeScored = -1;

    document.getElementById('startScreen').classList.remove('active');
    document.getElementById('gameOverScreen').classList.remove('active');
    document.getElementById('scoreDisplay').style.display = 'block';
    document.getElementById('coinDisplay').style.display = 'block';
    document.getElementById('youtubeBtn').style.display = 'none';
    this.updateScoreDisplay();

    this.audio.startMusic();
    this.lastTime = performance.now();
    if (this.animFrame) cancelAnimationFrame(this.animFrame);
    this.gameLoop(this.lastTime);
  }

  jump() {
    this.bird.velocity = CONFIG.JUMP_FORCE;
    this.audio.playJump();

    // Add jump particles
    for (let i = 0; i < 5; i++) {
      this.particles.push({
        x: this.bird.x,
        y: this.bird.y + CONFIG.BIRD_SIZE / 2,
        vx: (Math.random() - 0.5) * 3,
        vy: Math.random() * 2 + 1,
        life: 1,
        color: '#FFF',
        size: 3 + Math.random() * 3
      });
    }
  }

  spawnPipe() {
    const minGap = CONFIG.PIPE_GAP_MIN;
    const maxGapY = CONFIG.HEIGHT - CONFIG.GROUND_HEIGHT - minGap - 40;
    const minGapY = 40;
    const gapY = minGapY + Math.random() * (maxGapY - minGapY);

    this.pipes.push({
      x: CONFIG.WIDTH + 10,
      gapY: gapY,
      gapHeight: this.pipeGap,
      scored: false,
      width: CONFIG.PIPE_WIDTH
    });

    // Spawn coin in pipe gap
    if (Math.random() < 0.5) {
      this.coins.push({
        x: CONFIG.WIDTH + 10 + CONFIG.PIPE_WIDTH / 2,
        y: gapY + this.pipeGap / 2,
        size: CONFIG.COIN_SIZE,
        collected: false,
        rotation: 0
      });
    }
  }

  updateDifficulty() {
    if (this.score > CONFIG.DIFFICULTY_START) {
      this.difficulty = 1 + (this.score - CONFIG.DIFFICULTY_START) * CONFIG.DIFFICULTY_STEP;
      this.pipeSpeed = Math.min(CONFIG.PIPE_SPEED_MAX, CONFIG.PIPE_SPEED_BASE * this.difficulty);
      this.pipeGap = Math.max(CONFIG.PIPE_GAP_MIN, CONFIG.PIPE_GAP_BASE - (this.score - CONFIG.DIFFICULTY_START) * 3);
      this.pipeSpawnInterval = Math.max(CONFIG.PIPE_SPAWN_MIN, CONFIG.PIPE_SPAWN_BASE - (this.score - CONFIG.DIFFICULTY_START) * 50);
    }
  }

  update(dt) {
    if (this.state !== 'PLAYING') return;

    // Bird physics
    this.bird.velocity += CONFIG.GRAVITY;
    this.bird.y += this.bird.velocity;

    // Bird rotation
    if (this.bird.velocity < 0) {
      this.bird.rotation = Math.max(-30, this.bird.velocity * 3);
    } else {
      this.bird.rotation = Math.min(70, this.bird.velocity * 4);
    }

    // Bird animation frame
    this.bird.frameTimer += dt;
    if (this.bird.frameTimer > 100) {
      this.bird.frame = (this.bird.frame + 1) % 3;
      this.bird.frameTimer = 0;
    }

    // Ground collision
    if (this.bird.y + CONFIG.BIRD_SIZE / 2 >= CONFIG.HEIGHT - CONFIG.GROUND_HEIGHT) {
      this.bird.y = CONFIG.HEIGHT - CONFIG.GROUND_HEIGHT - CONFIG.BIRD_SIZE / 2;
      this.gameOver();
      return;
    }

    // Ceiling collision
    if (this.bird.y - CONFIG.BIRD_SIZE / 2 <= 0) {
      this.bird.y = CONFIG.BIRD_SIZE / 2;
      this.bird.velocity = 0;
    }

    // Pipe spawning
    this.pipeSpawnTimer += dt;
    if (this.pipeSpawnTimer >= this.pipeSpawnInterval) {
      this.spawnPipe();
      this.pipeSpawnTimer = 0;
    }

    // Update pipes
    for (let i = this.pipes.length - 1; i >= 0; i--) {
      const pipe = this.pipes[i];
      pipe.x -= this.pipeSpeed;

      // Score detection
      if (!pipe.scored && pipe.x + pipe.width < this.bird.x) {
        pipe.scored = true;
        this.score++;
        this.audio.playScore();
        this.updateDifficulty();
        this.updateScoreDisplay();

        // Score particles
        for (let j = 0; j < 8; j++) {
          this.particles.push({
            x: this.bird.x + 20,
            y: this.bird.y,
            vx: (Math.random() - 0.5) * 5,
            vy: (Math.random() - 0.5) * 5,
            life: 1,
            color: '#FFD700',
            size: 4 + Math.random() * 4
          });
        }
      }

      // Remove off-screen pipes
      if (pipe.x + pipe.width < -10) {
        this.pipes.splice(i, 1);
      }
    }

    // Update coins
    for (let i = this.coins.length - 1; i >= 0; i--) {
      const coin = this.coins[i];
      coin.x -= this.pipeSpeed;
      coin.rotation += 0.05;

      // Coin collection
      if (!coin.collected) {
        const dx = this.bird.x - coin.x;
        const dy = this.bird.y - coin.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < CONFIG.BIRD_SIZE / 2 + coin.size / 2) {
          coin.collected = true;
          this.totalCoins++;
          this.coins = this.totalCoins;
          localStorage.setItem('flappyCoins', this.coins);
          this.audio.playCoin();
          this.updateCoinDisplay();

          // Coin particles
          for (let j = 0; j < 6; j++) {
            this.particles.push({
              x: coin.x,
              y: coin.y,
              vx: (Math.random() - 0.5) * 4,
              vy: (Math.random() - 0.5) * 4,
              life: 1,
              color: '#FFD700',
              size: 3 + Math.random() * 3
            });
          }
        }
      }

      if (coin.x < -10 || coin.collected) {
        if (coin.x < -10) this.coins.splice(i, 1);
      }
    }

    // Update particles
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;
      if (p.life <= 0) {
        this.particles.splice(i, 1);
      }
    }

    // Update clouds
    this.clouds.forEach(cloud => {
      cloud.x -= cloud.speed;
      if (cloud.x + cloud.size < 0) {
        cloud.x = CONFIG.WIDTH + cloud.size;
        cloud.y = Math.random() * (CONFIG.HEIGHT * 0.4);
      }
    });

    // Ground scroll
    this.groundOffset = (this.groundOffset + this.pipeSpeed) % 40;

    // Collision detection with pipes
    for (const pipe of this.pipes) {
      const birdLeft = this.bird.x - CONFIG.BIRD_SIZE / 2 + 4;
      const birdRight = this.bird.x + CONFIG.BIRD_SIZE / 2 - 4;
      const birdTop = this.bird.y - CONFIG.BIRD_SIZE / 2 + 4;
      const birdBottom = this.bird.y + CONFIG.BIRD_SIZE / 2 - 4;

      const pipeLeft = pipe.x;
      const pipeRight = pipe.x + pipe.width;
      const gapTop = pipe.gapY;
      const gapBottom = pipe.gapY + pipe.gapHeight;

      if (birdRight > pipeLeft && birdLeft < pipeRight) {
        if (birdTop < gapTop || birdBottom > gapBottom) {
          this.gameOver();
          return;
        }
      }
    }
  }

  gameOver() {
    this.state = 'GAME_OVER';
    this.audio.stopMusic();
    this.audio.playCollision();
    setTimeout(() => this.audio.playGameOver(), 300);

    // Update high score
    let newRecord = false;
    if (this.score > this.highScore) {
      this.highScore = this.score;
      localStorage.setItem('flappyHighScore', this.highScore);
      newRecord = true;
    }

    // Show game over screen
    setTimeout(() => {
      document.getElementById('scoreDisplay').style.display = 'none';
      document.getElementById('coinDisplay').style.display = 'none';
      document.getElementById('finalScore').textContent = this.score;
      document.getElementById('finalHighScore').textContent = this.highScore;
      document.getElementById('newRecordLabel').style.display = newRecord ? 'block' : 'none';
      document.getElementById('gameOverScreen').classList.add('active');
      document.getElementById('youtubeBtn').style.display = 'flex';
    }, 500);
  }

  goHome() {
    this.state = 'START';
    this.audio.stopMusic();
    document.getElementById('gameOverScreen').classList.remove('active');
    document.getElementById('startScreen').classList.add('active');
    document.getElementById('youtubeBtn').style.display = 'flex';
    this.updateUI();
    this.render();
  }

  updateScoreDisplay() {
    document.getElementById('scoreDisplay').textContent = this.score;
  }

  updateCoinDisplay() {
    document.getElementById('coinDisplay').textContent = '🪙 ' + this.totalCoins;
  }

  updateUI() {
    document.getElementById('startHighScore').textContent = this.highScore;
    this.updateCoinDisplay();
  }

  // ============ RENDERING ============
  render() {
    const ctx = this.ctx;
    const W = CONFIG.WIDTH;
    const H = CONFIG.HEIGHT;

    // Sky gradient
    const skyGrad = ctx.createLinearGradient(0, 0, 0, H - CONFIG.GROUND_HEIGHT);
    skyGrad.addColorStop(0, '#4EC0CA');
    skyGrad.addColorStop(0.5, '#71D1DC');
    skyGrad.addColorStop(1, '#D4F0F7');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, W, H);

    // Clouds
    this.clouds.forEach(cloud => {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
      ctx.beginPath();
      ctx.arc(cloud.x, cloud.y, cloud.size * 0.5, 0, Math.PI * 2);
      ctx.arc(cloud.x + cloud.size * 0.3, cloud.y - cloud.size * 0.2, cloud.size * 0.4, 0, Math.PI * 2);
      ctx.arc(cloud.x + cloud.size * 0.6, cloud.y, cloud.size * 0.35, 0, Math.PI * 2);
      ctx.arc(cloud.x + cloud.size * 0.3, cloud.y + cloud.size * 0.1, cloud.size * 0.3, 0, Math.PI * 2);
      ctx.fill();
    });

    // Distant city silhouette
    ctx.fillStyle = '#8BC34A';
    for (let i = 0; i < W; i += 30) {
      const h = 20 + Math.sin(i * 0.1) * 15 + Math.cos(i * 0.05) * 10;
      ctx.fillRect(i, H - CONFIG.GROUND_HEIGHT - h, 25, h);
    }

    // Pipes
    this.pipes.forEach(pipe => {
      this.drawPipe(pipe);
    });

    // Coins
    this.coins.forEach(coin => {
      if (!coin.collected) {
        this.drawCoin(coin);
      }
    });

    // Bird
    this.drawBird();

    // Particles
    this.particles.forEach(p => {
      ctx.globalAlpha = p.life;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    });

    // Ground
    this.drawGround();
  }

  drawPipe(pipe) {
    const ctx = this.ctx;
    const W = pipe.width;
    const gapTop = pipe.gapY;
    const gapBottom = pipe.gapY + pipe.gapHeight;
    const groundY = CONFIG.HEIGHT - CONFIG.GROUND_HEIGHT;

    // Top pipe
    const topGrad = ctx.createLinearGradient(pipe.x, 0, pipe.x + W, 0);
    topGrad.addColorStop(0, '#5CBF2A');
    topGrad.addColorStop(0.3, '#73D942');
    topGrad.addColorStop(0.7, '#73D942');
    topGrad.addColorStop(1, '#4CA820');

    ctx.fillStyle = topGrad;
    ctx.fillRect(pipe.x, 0, W, gapTop);

    // Top pipe cap
    ctx.fillStyle = topGrad;
    ctx.fillRect(pipe.x - 4, gapTop - 24, W + 8, 24);
    ctx.strokeStyle = '#3D8B18';
    ctx.lineWidth = 2;
    ctx.strokeRect(pipe.x - 4, gapTop - 24, W + 8, 24);
    ctx.strokeRect(pipe.x, 0, W, gapTop - 24);

    // Top pipe highlight
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.fillRect(pipe.x + 6, 0, 8, gapTop - 24);

    // Bottom pipe
    ctx.fillStyle = topGrad;
    ctx.fillRect(pipe.x, gapBottom, W, groundY - gapBottom);

    // Bottom pipe cap
    ctx.fillRect(pipe.x - 4, gapBottom, W + 8, 24);
    ctx.strokeStyle = '#3D8B18';
    ctx.strokeRect(pipe.x - 4, gapBottom, W + 8, 24);
    ctx.strokeRect(pipe.x, gapBottom + 24, W, groundY - gapBottom - 24);

    // Bottom pipe highlight
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.fillRect(pipe.x + 6, gapBottom + 24, 8, groundY - gapBottom - 24);
  }

  drawBird() {
    const ctx = this.ctx;
    const x = this.bird.x;
    const y = this.bird.y;
    const size = CONFIG.BIRD_SIZE;

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(this.bird.rotation * Math.PI / 180);

    // Body
    const bodyGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, size / 2);
    bodyGrad.addColorStop(0, '#FFD700');
    bodyGrad.addColorStop(0.7, '#FFA500');
    bodyGrad.addColorStop(1, '#FF8C00');
    ctx.fillStyle = bodyGrad;
    ctx.beginPath();
    ctx.ellipse(0, 0, size / 2, size / 2.3, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#E67E00';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Wing
    const wingY = this.bird.frame === 0 ? 2 : this.bird.frame === 1 ? -2 : 4;
    ctx.fillStyle = '#FFE44D';
    ctx.beginPath();
    ctx.ellipse(-4, wingY, 10, 6, -0.3, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#E67E00';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Eye (white)
    ctx.fillStyle = '#FFF';
    ctx.beginPath();
    ctx.arc(8, -5, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Pupil
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(10, -5, 3.5, 0, Math.PI * 2);
    ctx.fill();

    // Eye highlight
    ctx.fillStyle = '#FFF';
    ctx.beginPath();
    ctx.arc(11, -6.5, 1.5, 0, Math.PI * 2);
    ctx.fill();

    // Beak
    ctx.fillStyle = '#FF6347';
    ctx.beginPath();
    ctx.moveTo(12, 0);
    ctx.lineTo(22, 2);
    ctx.lineTo(12, 5);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#CC4030';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Beak line
    ctx.strokeStyle = '#CC4030';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(12, 2.5);
    ctx.lineTo(20, 2.5);
    ctx.stroke();

    ctx.restore();
  }

  drawCoin(coin) {
    const ctx = this.ctx;
    const x = coin.x;
    const y = coin.y;
    const size = coin.size;

    ctx.save();
    ctx.translate(x, y);

    // Coin body
    const coinGrad = ctx.createRadialGradient(-2, -2, 0, 0, 0, size / 2);
    coinGrad.addColorStop(0, '#FFD700');
    coinGrad.addColorStop(0.5, '#FFA500');
    coinGrad.addColorStop(1, '#FF8C00');
    ctx.fillStyle = coinGrad;
    ctx.beginPath();
    ctx.arc(0, 0, size / 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#CC8800';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Inner circle
    ctx.strokeStyle = '#CC8800';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, size / 2 - 3, 0, Math.PI * 2);
    ctx.stroke();

    // Dollar sign
    ctx.fillStyle = '#CC8800';
    ctx.font = 'bold 12px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('$', 0, 1);

    ctx.restore();
  }

  drawGround() {
    const ctx = this.ctx;
    const H = CONFIG.HEIGHT;
    const groundY = H - CONFIG.GROUND_HEIGHT;

    // Ground base
    const groundGrad = ctx.createLinearGradient(0, groundY, 0, H);
    groundGrad.addColorStop(0, '#8B6914');
    groundGrad.addColorStop(0.1, '#DEB887');
    groundGrad.addColorStop(0.3, '#D2B48C');
    groundGrad.addColorStop(1, '#8B7355');
    ctx.fillStyle = groundGrad;
    ctx.fillRect(0, groundY, CONFIG.WIDTH, CONFIG.GROUND_HEIGHT);

    // Ground top grass
    ctx.fillStyle = '#5CBF2A';
    ctx.fillRect(0, groundY, CONFIG.WIDTH, 8);
    ctx.fillStyle = '#73D942';
    ctx.fillRect(0, groundY, CONFIG.WIDTH, 4);

    // Ground pattern
    ctx.strokeStyle = '#C4A882';
    ctx.lineWidth = 1;
    for (let i = -40 + (this.groundOffset % 40); i < CONFIG.WIDTH + 40; i += 40) {
      ctx.beginPath();
      ctx.moveTo(i, groundY + 12);
      ctx.lineTo(i + 20, groundY + 12);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(i + 20, groundY + 25);
      ctx.lineTo(i + 40, groundY + 25);
      ctx.stroke();
    }

    // Ground line
    ctx.strokeStyle = '#5CBF2A';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, groundY);
    ctx.lineTo(CONFIG.WIDTH, groundY);
    ctx.stroke();
  }

  gameLoop(timestamp) {
    if (this.state !== 'PLAYING') {
      if (this.state === 'START') {
        // Idle bird animation
        this.bird.y = CONFIG.HEIGHT / 2 + Math.sin(timestamp * 0.003) * 15;
        this.bird.frameTimer += 16;
        if (this.bird.frameTimer > 150) {
          this.bird.frame = (this.bird.frame + 1) % 3;
          this.bird.frameTimer = 0;
        }
        this.render();
      }
      this.animFrame = requestAnimationFrame((t) => this.gameLoop(t));
      return;
    }

    const dt = timestamp - this.lastTime;
    this.lastTime = timestamp;

    this.update(dt);
    this.render();

    this.animFrame = requestAnimationFrame((t) => this.gameLoop(t));
  }
}

// ============ INIT ============
window.addEventListener('load', () => {
  const game = new FlappyGame();
});
