  background: rgba(0,0,0,0.5); padding: 15px 30px; border-radius: 10px;
}
.jump-btn {
  padding: 20px 40px; font-size: 24px; font-weight: 900;
  color: #fff; background: rgba(255, 0, 0, 0.5);
