  margin-bottom: 30px;
}
.end-title.victory { color: #0f0; }
.end-title.defeat { color: #f00; }
.end-stats {
  background: rgba(255,255,255,0.1); padding: 30px; border-radius: 15px;
  border: 1px solid rgba(255,255,255,0.3);
}
.stat-row {
  display: flex; justify-content: space-between; width: 300px;
  padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.1);
  color: #fff; font-size: 16px;
}
.stat-value { color: #0ff; font-weight: 700; }
.rating-change {
  font-size: 24px; font-weight: 900; margin-top: 20px;
  color: #0f0;
}

/* Settings */
#settingsPanel {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: rgba(0,0,0,0.9);
  display: none; flex-direction: column; align-items: center; justify-content: center;
  z-index: 950;
}
#settingsPanel.active { display: flex; }
.settings-title { font-size: 40px; color: #fff; margin-bottom: 30px; }
.setting-row {
  display: flex; align-items: center; gap: 20px; margin: 10px 0;
