/* Notification */
.notification {
  position: absolute; top: 100px; left: 50%; transform: translateX(-50%);
  background: rgba(0,0,0,0.8); padding: 10px 20px; border-radius: 10px;
  color: #fff; font-size: 16px; font-weight: 700;
  border: 1px solid rgba(0,255,255,0.5);
