<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// ==================== GAME STATE ====================
const GameState = {
  loading: true,
  menu: false,
  modeSelect: false,
  plane: false,
  playing: false,
  ended: false,
  mode: 'solo',
  playerLevel: 1,
  playerRating: 0,
  playerName: 'Игрок',
  stats: {
    games: 0, wins: 0, kills: 0, damage: 0, time: 0, distance: 0
  }
};

// Player state
const Player = {
  health: 100, maxHealth: 100,
  armor: 0, maxArmor: 100,
  speed: 0.15, runSpeed: 0.25,
  position: new THREE.Vector3(0, 100, 0),
  velocity: new THREE.Vector3(0, 0, 0),
  rotation: 0,
  pitch: 0,
  isRunning: false,
  isCrouching: false,
  isProne: false,
  isJumping: false,
  isParachuting: false,
  weapons: [],
  currentWeapon: 0,
  grenades: 3,
  medkits: 2,
  alive: true,
  kills: 0,
  totalDamage: 0,
  distanceTraveled: 0,
  itemsCollected: 0,
  startTime: 0
};

// Zone state
const Zone = {
  currentRadius: 500,
  targetRadius: 500,
  center: new THREE.Vector3(0, 0, 0),
  phase: 0,
  maxPhases: 7,
  shrinkTime: 300, // 5 minutes in seconds
  timer: 300,
  damage: 5, // HP per second
  safe: true
};

// AI opponents
const AIEnemies = [];
const MAX_ENEMIES = 99;

// Map generation
const MAP_SIZE = 1000;
const buildings = [];
const trees = [];
const lootItems = [];
const projectiles = [];

// ==================== INITIALIZATION ====================
let scene, camera, renderer, clock;
let playerMesh, planeMesh;
let keys = {};
let mouse = { x: 0, y: 0 };
let isPointerLocked = false;

function init() {
  // Create scene
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x87CEEB);
  scene.fog = new THREE.Fog(0x87CEEB, 100, 800);

  // Create camera
  camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
  camera.position.set(0, 100, 0);

  // Create renderer
  renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  document.body.appendChild(renderer.domElement);

  // Create clock
  clock = new THREE.Clock();

  // Create lighting
  const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
  scene.add(ambientLight);

  const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
  directionalLight.position.set(100, 200, 100);
  directionalLight.castShadow = true;
  directionalLight.shadow.mapSize.width = 2048;
  directionalLight.shadow.mapSize.height = 2048;
  directionalLight.shadow.camera.near = 0.5;
  directionalLight.shadow.camera.far = 500;
  directionalLight.shadow.camera.left = -500;
  directionalLight.shadow.camera.right = 500;
  directionalLight.shadow.camera.top = 500;
  directionalLight.shadow.camera.bottom = -500;
  scene.add(directionalLight);

  // Generate map
  generateMap();

  // Setup event listeners
  setupEventListeners();

  // Start loading
  startLoading();
}

function startLoading() {
  const progressBar = document.getElementById('progressBar');
  const progressText = document.getElementById('progressText');
  const particles = document.getElementById('particles');

  // Create particles
  for (let i = 0; i < 50; i++) {
    const particle = document.createElement('div');
    particle.className = 'particle';
    particle.style.left = Math.random() * 100 + '%';
    particle.style.animationDelay = Math.random() * 3 + 's';
    particle.style.animationDuration = (2 + Math.random() * 3) + 's';
    particles.appendChild(particle);
  }

  let progress = 0;
  const loadingSteps = [
    'Загрузка текстур...',
    'Генерация карты...',
    'Загрузка моделей...',
    'Инициализация физики...',
    'Подготовка ИИ...',
    'Загрузка звуков...',
    'Почти готово...'
  ];

  const interval = setInterval(() => {
    progress += Math.random() * 15 + 5;
    if (progress > 100) progress = 100;

    progressBar.style.width = progress + '%';
    progressText.textContent = loadingSteps[Math.floor(progress / 15)] || 'Загрузка...';

    if (progress >= 100) {
      clearInterval(interval);
      setTimeout(() => {
        document.getElementById('loadingScreen').classList.add('hidden');
        showMainMenu();
      }, 500);
    }
  }, 300);
}

// ==================== MAP GENERATION ====================
function generateMap() {
  // Ground
  const groundGeometry = new THREE.PlaneGeometry(MAP_SIZE, MAP_SIZE, 100, 100);
  const groundMaterial = new THREE.MeshLambertMaterial({ color: 0x3a7d3a });

  // Add some height variation
  const vertices = groundGeometry.attributes.position.array;
  for (let i = 0; i < vertices.length; i += 3) {
    const x = vertices[i];
    const z = vertices[i + 1];
    // Simple noise for terrain
    vertices[i + 2] = Math.sin(x * 0.01) * Math.cos(z * 0.01) * 5 +
                       Math.sin(x * 0.03) * Math.cos(z * 0.03) * 2;
  }
  groundGeometry.computeVertexNormals();

  const ground = new THREE.Mesh(groundGeometry, groundMaterial);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  // Water
  const waterGeometry = new THREE.PlaneGeometry(MAP_SIZE, MAP_SIZE);
  const waterMaterial = new THREE.MeshLambertMaterial({ 
    color: 0x1a5276, transparent: true, opacity: 0.7 
  });
  const water = new THREE.Mesh(waterGeometry, waterMaterial);
  water.rotation.x = -Math.PI / 2;
  water.position.y = -1;
  scene.add(water);

  // Generate buildings (20% of map = 200 buildings)
  const buildingCount = 20;
  for (let i = 0; i < buildingCount; i++) {
    createBuilding(
      (Math.random() - 0.5) * MAP_SIZE * 0.8,
      (Math.random() - 0.5) * MAP_SIZE * 0.8
    );
  }

  // Generate trees (500-700)
  const treeCount = 600;
  for (let i = 0; i < treeCount; i++) {
    createTree(
      (Math.random() - 0.5) * MAP_SIZE * 0.9,
      (Math.random() - 0.5) * MAP_SIZE * 0.9
    );
  }

  // Generate mountains (10% of map)
  for (let i = 0; i < 10; i++) {
    createMountain(
      (Math.random() - 0.5) * MAP_SIZE * 0.6,
      (Math.random() - 0.5) * MAP_SIZE * 0.6
    );
  }

  // Generate loot
  generateLoot();
}

function createBuilding(x, z) {
  const width = 10 + Math.random() * 20;
  const height = 5 + Math.random() * 25;
  const depth = 10 + Math.random() * 20;

  const geometry = new THREE.BoxGeometry(width, height, depth);
  const material = new THREE.MeshLambertMaterial({
    color: new THREE.Color().setHSL(0, 0, 0.3 + Math.random() * 0.3)
  });
  const building = new THREE.Mesh(geometry, material);
  building.position.set(x, height / 2, z);
  building.castShadow = true;
  building.receiveShadow = true;
  scene.add(building);

  buildings.push({
    mesh: building,
    position: new THREE.Vector3(x, 0, z),
    width, height, depth,
    loot: []
  });

  // Add windows
  const windowGeometry = new THREE.PlaneGeometry(2, 3);
  const windowMaterial = new THREE.MeshLambertMaterial({ color: 0x87CEEB });

  for (let y = 3; y < height - 2; y += 5) {
    for (let wx = -width/2 + 3; wx < width/2 - 2; wx += 5) {
      const window = new THREE.Mesh(windowGeometry, windowMaterial);
      window.position.set(x + wx, y, z + depth/2 + 0.1);
      scene.add(window);

      const window2 = window.clone();
      window2.position.z = z - depth/2 - 0.1;
      window2.rotation.y = Math.PI;
      scene.add(window2);
    }
  }
}

function createTree(x, z) {
  const group = new THREE.Group();

  // Trunk
  const trunkGeometry = new THREE.CylinderGeometry(0.3, 0.5, 4, 8);
  const trunkMaterial = new THREE.MeshLambertMaterial({ color: 0x8B4513 });
  const trunk = new THREE.Mesh(trunkGeometry, trunkMaterial);
  trunk.position.y = 2;
  trunk.castShadow = true;
  group.add(trunk);

  // Leaves
  const leavesGeometry = new THREE.SphereGeometry(3, 8, 8);
  const leavesMaterial = new THREE.MeshLambertMaterial({ color: 0x228B22 });
  const leaves = new THREE.Mesh(leavesGeometry, leavesMaterial);
  leaves.position.y = 6;
  leaves.castShadow = true;
  group.add(leaves);

  group.position.set(x, 0, z);
  scene.add(group);

  trees.push({
    mesh: group,
    position: new THREE.Vector3(x, 0, z),
    radius: 1
  });
}

function createMountain(x, z) {
  const height = 20 + Math.random() * 30;
  const geometry = new THREE.ConeGeometry(15 + Math.random() * 10, height, 8);
  const material = new THREE.MeshLambertMaterial({ color: 0x808080 });
  const mountain = new THREE.Mesh(geometry, material);
  mountain.position.set(x, height / 2, z);
  mountain.castShadow = true;
  scene.add(mountain);
}

function generateLoot() {
  const weaponTypes = [
    { name: 'Пистолет', type: 'pistol', damage: 15, fireRate: 500, range: 100, ammo: 12, maxAmmo: 12, spread: 0.05, recoil: 0.02, rarity: 'common' },
    { name: 'ПП", type: 'smg', damage: 20, fireRate: 100, range: 80, ammo: 30, maxAmmo: 30, spread: 0.08, recoil: 0.03, rarity: 'common' },
    { name: 'Штурмовая', type: 'assault', damage: 30, fireRate: 150, range: 150, ammo: 30, maxAmmo: 30, spread: 0.04, recoil: 0.05, rarity: 'uncommon' },
    { name: 'Снайперская', type: 'sniper', damage: 80, fireRate: 1500, range: 300, ammo: 5, maxAmmo: 5, spread: 0.01, recoil: 0.1, rarity: 'rare' },
    { name: 'Дробовик', type: 'shotgun', damage: 40, fireRate: 800, range: 30, ammo: 8, maxAmmo: 8, spread: 0.15, recoil: 0.15, rarity: 'uncommon' },
    { name: 'Пулемет', type: 'lmg', damage: 25, fireRate: 80, range: 120, ammo: 100, maxAmmo: 100, spread: 0.1, recoil: 0.08, rarity: 'epic' },
    { name: 'Лук', type: 'bow', damage: 35, fireRate: 1000, range: 100, ammo: 1, maxAmmo: 1, spread: 0.02, recoil: 0.01, rarity: 'rare' }
  ];

  const armorTypes = [
    { name: 'Броня I', level: 1, armor: 30, rarity: 'common' },
    { name: 'Броня II', level: 2, armor: 60, rarity: 'uncommon' },
    { name: 'Броня III', level: 3, armor: 100, rarity: 'rare' }
  ];

  const medTypes = [
    { name: 'Аптечка', heal: 25, rarity: 'common' },
    { name: 'Большая аптечка', heal: 50, rarity: 'uncommon' },
    { name: 'Аптечка S', heal: 100, rarity: 'rare' }
  ];

  // Spawn loot in buildings
  buildings.forEach(building => {
    const lootCount = 3 + Math.floor(Math.random() * 5);
    for (let i = 0; i < lootCount; i++) {
      const roll = Math.random();
      let loot;

      if (roll < 0.4) {
        // Weapon
        const weaponType = weaponTypes[Math.floor(Math.random() * weaponTypes.length)];
        loot = {
          ...weaponType,
          category: 'weapon',
          id: Math.random()
        };
      } else if (roll < 0.6) {
        // Armor
        const armorType = armorTypes[Math.floor(Math.random() * armorTypes.length)];
        loot = {
          ...armorType,
          category: 'armor',
          id: Math.random()
        };
      } else if (roll < 0.8) {
        // Medkit
        const medType = medTypes[Math.floor(Math.random() * medTypes.length)];
        loot = {
          ...medType,
          category: 'medkit',
          id: Math.random()
        };
      } else {
        // Ammo
        loot = {
          name: 'Патроны',
          category: 'ammo',
          amount: 30,
          id: Math.random(),
          rarity: 'common'
        };
      }

      loot.position = new THREE.Vector3(
        building.position.x + (Math.random() - 0.5) * building.width,
        1,
        building.position.z + (Math.random() - 0.5) * building.depth
      );

      lootItems.push(loot);

      // Create visual indicator
      const lootGeometry = new THREE.BoxGeometry(0.5, 0.5, 0.5);
      let lootColor;
      switch (loot.rarity) {
        case 'common': lootColor = 0xaaaaaa; break;
        case 'uncommon': lootColor = 0x00ff00; break;
        case 'rare': lootColor = 0x0000ff; break;
        case 'epic': lootColor = 0xaa00ff; break;
        case 'legendary': lootColor = 0xff8800; break;
        default: lootColor = 0xaaaaaa;
      }
      const lootMaterial = new THREE.MeshLambertMaterial({ color: lootColor });
      const lootMesh = new THREE.Mesh(lootGeometry, lootMaterial);
      lootMesh.position.copy(loot.position);
      lootMesh.position.y = 0.5;
      scene.add(lootMesh);

      loot.mesh = lootMesh;
    }
  });
}

// ==================== EVENT LISTENERS ====================
function setupEventListeners() {
  document.addEventListener('keydown', (e) => {
    keys[e.code] = true;

    if (GameState.playing) {
      switch (e.code) {
        case 'KeyW': Player.velocity.z = -Player.speed; break;
        case 'KeyS': Player.velocity.z = Player.speed; break;
        case 'KeyA': Player.velocity.x = -Player.speed; break;
        case 'KeyD': Player.velocity.x = Player.speed; break;
        case 'Space': 
          if (!Player.isJumping && !Player.isParachuting) {
            Player.isJumping = true;
            Player.velocity.y = 0.3;
          }
          break;
        case 'ShiftLeft': Player.isRunning = true; break;
        case 'ControlLeft': Player.isCrouching = true; break;
        case 'KeyZ': Player.isProne = true; break;
        case 'KeyR': reloadWeapon(); break;
        case 'KeyG': throwGrenade(); break;
        case 'KeyF': interactWithLoot(); break;
        case 'Digit1': switchWeapon(0); break;
        case 'Digit2': switchWeapon(1); break;
        case 'Digit3': switchWeapon(2); break;
        case 'Digit4': switchWeapon(3); break;
        case 'Digit5': switchWeapon(4); break;
        case 'KeyM': toggleMinimap(); break;
      }
    }
  });

  document.addEventListener('keyup', (e) => {
    keys[e.code] = false;

    if (GameState.playing) {
      switch (e.code) {
        case 'KeyW': if (Player.velocity.z < 0) Player.velocity.z = 0; break;
        case 'KeyS': if (Player.velocity.z > 0) Player.velocity.z = 0; break;
        case 'KeyA': if (Player.velocity.x < 0) Player.velocity.x = 0; break;
        case 'KeyD': if (Player.velocity.x > 0) Player.velocity.x = 0; break;
        case 'ShiftLeft': Player.isRunning = false; break;
        case 'ControlLeft': Player.isCrouching = false; break;
        case 'KeyZ': Player.isProne = false; break;
      }
    }
  });

  document.addEventListener('mousedown', (e) => {
    if (GameState.playing && e.button === 0) {
      shoot();
    }
  });

  document.addEventListener('mousemove', (e) => {
    if (isPointerLocked && GameState.playing) {
      Player.rotation -= e.movementX * 0.002;
      Player.pitch -= e.movementY * 0.002;
      Player.pitch = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, Player.pitch));
    }
  });

  document.addEventListener('pointerlockchange', () => {
    isPointerLocked = document.pointerLockElement === renderer.domElement;
  });

  renderer.domElement.addEventListener('click', () => {
    if (GameState.playing) {
      renderer.domElement.requestPointerLock();
    }
  });

  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });
}

