// ==================== GAME START ====================
function startGame(mode) {
  GameState.mode = mode;
  hideAllScreens();

  // Show plane scene
  document.getElementById('planeScene').classList.add('active');
  GameState.plane = true;

  // Reset player
  Player.health = 100;
  Player.armor = 0;
  Player.position.set(
    (Math.random() - 0.5) * MAP_SIZE * 0.5,
    100,
    (Math.random() - 0.5) * MAP_SIZE * 0.5
  );
  Player.velocity.set(0, 0, 0);
  Player.alive = true;
  Player.kills = 0;
  Player.totalDamage = 0;
  Player.distanceTraveled = 0;
  Player.itemsCollected = 0;
  Player.weapons = [];
  Player.currentWeapon = 0;
  Player.grenades = 3;
  Player.medkits = 2;
  Player.isParachuting = false;
  Player.isJumping = false;

  // Reset zone
  Zone.currentRadius = 500;
  Zone.targetRadius = 500;
  Zone.phase = 0;
  Zone.timer = 300;
  Zone.damage = 5;

  // Clear old AI
  AIEnemies.forEach(ai => {
    if (ai.mesh) scene.remove(ai.mesh);
  });
  AIEnemies.length = 0;

  // Create AI enemies
  createAIE enemies();

  // Update HUD
  updateHUD();

  // Start game loop
  GameState.playing = true;
  GameState.startTime = Date.now();

  // Add initial weapon
  Player.weapons.push({
    name: 'Пистолет',
    type: 'pistol',
    damage: 15,
    fireRate: 500,
    range: 100,
    ammo: 12,
    maxAmmo: 12,
    spread: 0.05,
    recoil: 0.02,
    rarity: 'common',
    lastShot: 0
  });

  addChatMessage('Система', 'Добро пожаловать в REG2! Выживите!', 'system');
  addChatMessage('Система', 'Зона начнет сжиматься через 5 минут', 'system');
}

function createAIE enemies() {
  const count = GameState.mode === 'solo' ? 99 : GameState.mode === 'duo' ? 49 : 24;

  for (let i = 0; i < count; i++) {
    const ai = {
      id: i,
      name: 'AI_' + (i + 1),
      health: 100,
      position: new THREE.Vector3(
        (Math.random() - 0.5) * MAP_SIZE * 0.8,
        2,
        (Math.random() - 0.5) * MAP_SIZE * 0.8
      ),
      velocity: new THREE.Vector3(0, 0, 0),
      rotation: Math.random() * Math.PI * 2,
      state: 'patrol', // patrol, search, fight, flee, loot
      target: null,
      weapon: null,
      alive: true,
      speed: 0.05 + Math.random() * 0.05,
      reactionTime: 500 + Math.random() * 1000,
      lastShot: 0,
      patrolTarget: new THREE.Vector3(
        (Math.random() - 0.5) * MAP_SIZE * 0.5,
        0,
        (Math.random() - 0.5) * MAP_SIZE * 0.5
      ),
      difficulty: Math.random() < 0.3 ? 'easy' : Math.random() < 0.8 ? 'medium' : 'hard',
      team: GameState.mode === 'duo' ? Math.floor(i / 2) : GameState.mode === 'squad' ? Math.floor(i / 4) : i,
      mesh: null
    };

    // Create AI mesh
    const aiGeometry = new THREE.CapsuleGeometry(0.5, 1.5, 4, 8);
    const aiMaterial = new THREE.MeshLambertMaterial({ 
      color: new THREE.Color().setHSL(Math.random(), 0.7, 0.5) 
    });
    ai.mesh = new THREE.Mesh(aiGeometry, aiMaterial);
    ai.mesh.position.copy(ai.position);
    ai.mesh.castShadow = true;
    scene.add(ai.mesh);

    AIEnemies.push(ai);
  }
}

function jumpFromPlane() {
  if (!GameState.plane) return;

  GameState.plane = false;
  GameState.playing = true;

  document.getElementById('planeScene').classList.remove('active');
  document.getElementById('gameHUD').classList.add('active');

  // Set player position for landing
  Player.position.set(
    (Math.random() - 0.5) * MAP_SIZE * 0.5,
    100,
    (Math.random() - 0.5) * MAP_SIZE * 0.5
  );

  addChatMessage('Система', 'Прыжок выполнен! Выживайте!', 'system');
}

// ==================== GAME LOOP ====================
function gameLoop() {
  requestAnimationFrame(gameLoop);

  if (!GameState.playing) {
    renderer.render(scene, camera);
    return;
  }

  const delta = clock.getDelta();
  const time = clock.getElapsedTime();

  // Update player
  updatePlayer(delta);

  // Update AI
  updateAI(delta);

  // Update zone
  updateZone(delta);

  // Update projectiles
  updateProjectiles(delta);

  // Update loot
  updateLoot();

  // Update camera
  updateCamera();

  // Update HUD
  updateHUD();

  // Check win/lose conditions
  checkGameEnd();

  // Render
  renderer.render(scene, camera);
}

function updatePlayer(delta) {
  if (!Player.alive) return;

  // Apply gravity
  if (!Player.isParachuting) {
    Player.velocity.y -= 0.015;
  } else {
    Player.velocity.y = Math.min(Player.velocity.y, -0.05);
  }

  // Apply movement
  const speed = Player.isRunning ? Player.runSpeed : Player.speed;
  const moveX = Player.velocity.x * speed;
  const moveZ = Player.velocity.z * speed;

  // Rotate movement based on player rotation
  const cos = Math.cos(Player.rotation);
  const sin = Math.sin(Player.rotation);

  Player.position.x += moveX * cos - moveZ * sin;
  Player.position.z += moveX * sin + moveZ * cos;
  Player.position.y += Player.velocity.y;

  // Track distance
  Player.distanceTraveled += Math.sqrt(moveX * moveX + moveZ * moveZ);

  // Ground collision
  if (Player.position.y <= 2) {
    Player.position.y = 2;
    Player.velocity.y = 0;
    Player.isJumping = false;
    Player.isParachuting = false;
  }

  // Parachute activation
  if (Player.position.y < 200 && Player.velocity.y < 0 && !Player.isParachuting) {
    Player.isParachuting = true;
    addChatMessage('Система', 'Парашют активирован!', 'system');
  }

  // Map bounds
  Player.position.x = Math.max(-MAP_SIZE / 2, Math.min(MAP_SIZE / 2, Player.position.x));
  Player.position.z = Math.max(-MAP_SIZE / 2, Math.min(MAP_SIZE / 2, Player.position.z));

  // Building collision
  buildings.forEach(building => {
    const dx = Player.position.x - building.position.x;
    const dz = Player.position.z - building.position.z;

    if (Math.abs(dx) < building.width / 2 + 0.5 && Math.abs(dz) < building.depth / 2 + 0.5) {
      // Push player out
      if (Math.abs(dx) > Math.abs(dz)) {
        Player.position.x = building.position.x + (dx > 0 ? building.width / 2 + 0.5 : -building.width / 2 - 0.5);
      } else {
        Player.position.z = building.position.z + (dz > 0 ? building.depth / 2 + 0.5 : -building.depth / 2 - 0.5);
      }
    }
  });

  // Zone damage
  const distToCenter = Player.position.distanceTo(Zone.center);
  if (distToCenter > Zone.currentRadius) {
    Player.health -= Zone.damage * delta;
    document.getElementById('damageOverlay').classList.add('hit');
    document.getElementById('zoneWarning').style.display = 'block';

    if (Player.health <= 0) {
      Player.alive = false;
    }
  } else {
    document.getElementById('damageOverlay').classList.remove('hit');
    document.getElementById('zoneWarning').style.display = 'none';
  }

  // Health regeneration
  if (Player.health < Player.maxHealth && Player.health > 0) {
    Player.health = Math.min(Player.maxHealth, Player.health + 0.1 * delta);
  }
}

function updateAI(delta) {
  AIEnemies.forEach(ai => {
    if (!ai.alive) return;

    // Check if in zone
    const distToCenter = ai.position.distanceTo(Zone.center);
    if (distToCenter > Zone.currentRadius) {
      ai.health -= Zone.damage * delta;
      if (ai.health <= 0) {
        ai.alive = false;
        scene.remove(ai.mesh);
        addKillFeed('Зона', ai.name, 'zone');
        return;
      }
    }

    // State machine
    switch (ai.state) {
      case 'patrol':
        updateAIPatrol(ai, delta);
        break;
      case 'search':
        updateAISearch(ai, delta);
        break;
      case 'fight':
        updateAIFight(ai, delta);
        break;
      case 'loot':
        updateAILoot(ai, delta);
        break;
      case 'flee':
        updateAIFlee(ai, delta);
        break;
    }

    // Update mesh position
    if (ai.mesh) {
      ai.mesh.position.copy(ai.position);
      ai.mesh.position.y = 2;
      ai.mesh.rotation.y = ai.rotation;
    }

    // Check for player proximity
    const distToPlayer = ai.position.distanceTo(Player.position);
    if (distToPlayer < 50 && Player.alive) {
      ai.state = 'fight';
      ai.target = Player;
    }
  });
}

function updateAIPatrol(ai, delta) {
  // Move towards patrol target
  const dx = ai.patrolTarget.x - ai.position.x;
  const dz = ai.patrolTarget.z - ai.position.z;
  const dist = Math.sqrt(dx * dx + dz * dz);

  if (dist < 5) {
    // Pick new patrol target
    ai.patrolTarget.set(
      (Math.random() - 0.5) * MAP_SIZE * 0.5,
      0,
      (Math.random() - 0.5) * MAP_SIZE * 0.5
    );
  } else {
    ai.rotation = Math.atan2(dx, dz);
    ai.position.x += Math.sin(ai.rotation) * ai.speed;
    ai.position.z += Math.cos(ai.rotation) * ai.speed;
  }

  // Random chance to change state
  if (Math.random() < 0.001) {
    ai.state = 'search';
  }
}

function updateAISearch(ai, delta) {
  // Move towards nearest loot or building
  let nearestLoot = null;
  let nearestDist = Infinity;

  lootItems.forEach(loot => {
    if (!loot.mesh) return;
    const dist = ai.position.distanceTo(loot.position);
    if (dist < nearestDist) {
      nearestDist = dist;
      nearestLoot = loot;
    }
  });

  if (nearestLoot && nearestDist < 100) {
    const dx = nearestLoot.position.x - ai.position.x;
    const dz = nearestLoot.position.z - ai.position.z;
    ai.rotation = Math.atan2(dx, dz);
    ai.position.x += Math.sin(ai.rotation) * ai.speed;
    ai.position.z += Math.cos(ai.rotation) * ai.speed;

    if (nearestDist < 5) {
      ai.state = 'loot';
    }
  } else {
    ai.state = 'patrol';
  }
}

function updateAIFight(ai, delta) {
  if (!ai.target || !ai.target.alive) {
    ai.state = 'patrol';
    return;
  }

  const dist = ai.position.distanceTo(ai.target.position);

  if (dist > 50) {
    // Move towards target
    const dx = ai.target.position.x - ai.position.x;
    const dz = ai.target.position.z - ai.position.z;
    ai.rotation = Math.atan2(dx, dz);
    ai.position.x += Math.sin(ai.rotation) * ai.speed;
    ai.position.z += Math.cos(ai.rotation) * ai.speed;
  } else {
    // Shoot at target
    const now = Date.now();
    if (now - ai.lastShot > ai.reactionTime) {
      ai.lastShot = now;

      // Check if hit
      const accuracy = ai.difficulty === 'hard' ? 0.7 : ai.difficulty === 'medium' ? 0.5 : 0.3;
      if (Math.random() < accuracy) {
        const damage = ai.difficulty === 'hard' ? 20 : ai.difficulty === 'medium' ? 15 : 10;
        Player.health -= damage;
        addChatMessage(ai.name, 'нанес ' + damage + ' урона', 'kill');

        if (Player.health <= 0) {
          Player.alive = false;
        }
      }
    }
  }

  // Flee if low health
  if (ai.health < 30) {
    ai.state = 'flee';
  }
}

function updateAILoot(ai, delta) {
  // Simple loot animation
  ai.health = Math.min(100, ai.health + 10 * delta);

  if (Math.random() < 0.01) {
    ai.state = 'patrol';
  }
}

function updateAIFlee(ai, delta) {
  // Move away from player
  if (ai.target && ai.target.alive) {
    const dx = ai.position.x - ai.target.position.x;
    const dz = ai.position.z - ai.target.position.z;
    ai.rotation = Math.atan2(dx, dz);
    ai.position.x += Math.sin(ai.rotation) * ai.speed * 1.5;
    ai.position.z += Math.cos(ai.rotation) * ai.speed * 1.5;
  }

  if (ai.health > 50) {
    ai.state = 'patrol';
  }
}

function updateZone(delta) {
  Zone.timer -= delta;

  if (Zone.timer <= 0) {
    Zone.phase++;

    if (Zone.phase >= Zone.maxPhases) {
      // Final phase - small zone
      Zone.targetRadius = 50;
    } else {
      Zone.targetRadius = Math.max(50, Zone.currentRadius * 0.8);
    }

    Zone.timer = Zone.shrinkTime;
    Zone.damage += 2;

    addChatMessage('Система', 'Зона сжимается! Фаза ' + (Zone.phase + 1), 'system');
  }

  // Shrink zone
  if (Zone.currentRadius > Zone.targetRadius) {
    Zone.currentRadius -= delta * 2;
  }
}

function updateProjectiles(delta) {
  for (let i = projectiles.length - 1; i >= 0; i--) {
    const proj = projectiles[i];

    proj.position.add(proj.velocity.clone().multiplyScalar(delta));
    proj.life -= delta;

    if (proj.life <= 0) {
      scene.remove(proj.mesh);
      projectiles.splice(i, 1);
      continue;
    }

    // Check collision with AI
    if (proj.owner === 'player') {
      AIEnemies.forEach(ai => {
        if (!ai.alive) return;
        const dist = proj.position.distanceTo(ai.position);
        if (dist < 2) {
          ai.health -= proj.damage;
          scene.remove(proj.mesh);
          projectiles.splice(i, 1);

          if (ai.health <= 0) {
            ai.alive = false;
            scene.remove(ai.mesh);
            Player.kills++;
            Player.totalDamage += proj.damage;
            addKillFeed(Player.name, ai.name, 'player');
          }
        }
      });
    }
  }
}

function updateLoot() {
  // Check proximity to loot
  lootItems.forEach(loot => {
    if (!loot.mesh) return;

    const dist = Player.position.distanceTo(loot.position);
    if (dist < 3) {
      // Auto-pickup or prompt
      if (keys['KeyF']) {
        pickupLoot(loot);
      }
    }
  });
}

function pickupLoot(loot) {
  if (!loot.mesh) return;

  switch (loot.category) {
    case 'weapon':
      if (Player.weapons.length < 5) {
        Player.weapons.push({ ...loot });
        addChatMessage('Система', 'Подобрал: ' + loot.name, 'system');
        showLootPopup(loot.name, loot.rarity);
      }
      break;
    case 'armor':
      Player.armor = Math.min(Player.maxArmor, Player.armor + loot.armor);
      addChatMessage('Система', 'Подобрал: ' + loot.name, 'system');
      showLootPopup(loot.name, loot.rarity);
      break;
    case 'medkit':
      Player.health = Math.min(Player.maxHealth, Player.health + loot.heal);
      addChatMessage('Система', 'Использовал: ' + loot.name, 'system');
      showLootPopup(loot.name, loot.rarity);
      break;
    case 'ammo':
      addChatMessage('Система', 'Подобрал: ' + loot.amount + ' патронов', 'system');
      break;
  }

  // Remove loot
  scene.remove(loot.mesh);
  loot.mesh = null;
  Player.itemsCollected++;
}

function showLootPopup(name, rarity) {
  const popup = document.createElement('div');
  popup.className = 'loot-popup';
  popup.innerHTML = `<span class="rarity-${rarity}">${name}</span>`;
  document.getElementById('gameHUD').appendChild(popup);

  setTimeout(() => popup.remove(), 1500);
}

function updateCamera() {
  // Third-person camera
  const cameraDistance = 5;
  const cameraHeight = 3;

  const camX = Player.position.x - Math.sin(Player.rotation) * cameraDistance;
  const camZ = Player.position.z - Math.cos(Player.rotation) * cameraDistance;
  const camY = Player.position.y + cameraHeight;

  camera.position.set(camX, camY, camZ);
  camera.lookAt(Player.position.x, Player.position.y + 1, Player.position.z);
}

function updateHUD() {
  // Health
  const healthPercent = (Player.health / Player.maxHealth) * 100;
  document.getElementById('healthBar').style.width = healthPercent + '%';
  document.getElementById('healthText').textContent = Math.ceil(Player.health) + '/100 HP';

  // Armor
  const armorPercent = (Player.armor / Player.maxArmor) * 100;
  document.getElementById('armorBar').style.width = armorPercent + '%';
  document.getElementById('armorText').textContent = Math.ceil(Player.armor) + '/100 ARM';

  // Weapon
  if (Player.weapons.length > 0) {
    const weapon = Player.weapons[Player.currentWeapon];
    document.getElementById('weaponName').textContent = weapon.name;
    document.getElementById('ammoCount').textContent = weapon.ammo + '/' + weapon.maxAmmo;
  }

  // Player count
  const aliveCount = AIEnemies.filter(ai => ai.alive).length + (Player.alive ? 1 : 0);
  document.getElementById('playerCount').textContent = '👥 ' + aliveCount;

  // Zone timer
  const minutes = Math.floor(Zone.timer / 60);
  const seconds = Math.floor(Zone.timer % 60);
  document.getElementById('zoneTimer').textContent = 'Зона: ' + minutes + ':' + (seconds < 10 ? '0' : '') + seconds;

  if (Zone.timer < 60) {
    document.getElementById('zoneTimer').classList.add('danger');
  } else {
    document.getElementById('zoneTimer').classList.remove('danger');
  }

  // Minimap
  updateMinimap();
}

function updateMinimap() {
  const canvas = document.getElementById('minimapCanvas');
  const ctx = canvas.getContext('2d');

  ctx.clearRect(0, 0, 200, 200);

  // Background
  ctx.fillStyle = 'rgba(0, 50, 0, 0.8)';
  ctx.fillRect(0, 0, 200, 200);

  // Scale factor
  const scale = 200 / MAP_SIZE;

  // Draw zone
  ctx.strokeStyle = '#00f';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(100, 100, Zone.currentRadius * scale, 0, Math.PI * 2);
  ctx.stroke();

  // Draw target zone
  ctx.strokeStyle = '#0ff';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(100, 100, Zone.targetRadius * scale, 0, Math.PI * 2);
  ctx.stroke();

  // Draw buildings
  ctx.fillStyle = '#888';
  buildings.forEach(building => {
    const x = 100 + building.position.x * scale;
    const y = 100 + building.position.z * scale;
    ctx.fillRect(x - 2, y - 2, 4, 4);
  });

  // Draw AI enemies
  ctx.fillStyle = '#f00';
  AIEnemies.forEach(ai => {
    if (!ai.alive) return;
    const x = 100 + ai.position.x * scale;
    const y = 100 + ai.position.z * scale;
    ctx.beginPath();
    ctx.arc(x, y, 2, 0, Math.PI * 2);
    ctx.fill();
  });

  // Draw player
  ctx.fillStyle = '#0f0';
  const playerX = 100 + Player.position.x * scale;
  const playerY = 100 + Player.position.z * scale;
  ctx.beginPath();
  ctx.arc(playerX, playerY, 3, 0, Math.PI * 2);
  ctx.fill();

  // Player direction
  ctx.strokeStyle = '#0f0';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(playerX, playerY);
  ctx.lineTo(
    playerX + Math.sin(Player.rotation) * 10,
    playerY + Math.cos(Player.rotation) * 10
  );
  ctx.stroke();
}

// ==================== COMBAT ====================
function shoot() {
  if (!Player.alive || Player.weapons.length === 0) return;

  const weapon = Player.weapons[Player.currentWeapon];
  const now = Date.now();

  if (now - weapon.lastShot < weapon.fireRate) return;
  if (weapon.ammo <= 0) {
    reloadWeapon();
    return;
  }

  weapon.lastShot = now;
  weapon.ammo--;

  // Create projectile
  const projectileGeometry = new THREE.SphereGeometry(0.1, 8, 8);
  const projectileMaterial = new THREE.MeshBasicMaterial({ color: 0xffff00 });
  const projectile = new THREE.Mesh(projectileGeometry, projectileMaterial);

  const direction = new THREE.Vector3(
    Math.sin(Player.rotation) * Math.cos(Player.pitch),
    Math.sin(Player.pitch),
    Math.cos(Player.rotation) * Math.cos(Player.pitch)
  );

  projectile.position.copy(Player.position);
  projectile.position.y += 1;

  scene.add(projectile);

  projectiles.push({
    mesh: projectile,
    position: projectile.position.clone(),
    velocity: direction.multiplyScalar(2),
    damage: weapon.damage,
    owner: 'player',
    life: weapon.range / 2
  });

  // Recoil
  Player.pitch += weapon.recoil;

  // Sound effect (visual feedback)
  document.getElementById('damageOverlay').style.borderColor = 'rgba(255, 255, 0, 0.3)';
  setTimeout(() => {
    document.getElementById('damageOverlay').style.borderColor = 'rgba(255, 0, 0, 0)';
  }, 100);
}

function reloadWeapon() {
  if (Player.weapons.length === 0) return;

  const weapon = Player.weapons[Player.currentWeapon];
  if (weapon.ammo < weapon.maxAmmo) {
    weapon.ammo = weapon.maxAmmo;
    addChatMessage('Система', 'Перезарядка: ' + weapon.name, 'system');
  }
}

function throwGrenade() {
  if (Player.grenades <= 0) return;

  Player.grenades--;

  // Create grenade projectile
  const grenadeGeometry = new THREE.SphereGeometry(0.3, 8, 8);
  const grenadeMaterial = new THREE.MeshLambertMaterial({ color: 0x00ff00 });
  const grenade = new THREE.Mesh(grenadeGeometry, grenadeMaterial);

  grenade.position.copy(Player.position);
  grenade.position.y += 1;

  scene.add(grenade);

  const direction = new THREE.Vector3(
    Math.sin(Player.rotation),
    0.3,
    Math.cos(Player.rotation)
  );

  projectiles.push({
    mesh: grenade,
    position: grenade.position.clone(),
    velocity: direction.multiplyScalar(0.5),
    damage: 100,
    owner: 'player',
    life: 3,
    isGrenade: true
  });

  addChatMessage('Система', 'Граната брошена!', 'system');
}

function interactWithLoot() {
  // Already handled in updateLoot
}

function switchWeapon(index) {
  if (index < Player.weapons.length) {
    Player.currentWeapon = index;

    // Update slot UI
    for (let i = 1; i <= 5; i++) {
      document.getElementById('slot' + i).classList.remove('active');
    }
    document.getElementById('slot' + (index + 1)).classList.add('active');
  }
}

function toggleMinimap() {
  const minimap = document.querySelector('.minimap');
  minimap.style.display = minimap.style.display === 'none' ? 'block' : 'none';
}

// ==================== UI HELPERS ====================
function addChatMessage(sender, message, type) {
  const chat = document.getElementById('chat');
  const entry = document.createElement('div');
  entry.className = 'chat-message ' + type;
  entry.textContent = '[' + sender + '] ' + message;
  chat.appendChild(entry);
  chat.scrollTop = chat.scrollHeight;

  // Remove old messages
  while (chat.children.length > 20) {
    chat.removeChild(chat.firstChild);
  }
}

function addKillFeed(killer, victim, type) {
  const feed = document.getElementById('killFeed');
  const entry = document.createElement('div');
  entry.className = 'kill-entry';
  entry.textContent = killer + ' → ' + victim;
  feed.appendChild(entry);

  setTimeout(() => entry.remove(), 3000);

  // Keep only last 5
  while (feed.children.length > 5) {
    feed.removeChild(feed.firstChild);
  }
}

function checkGameEnd() {
  if (!Player.alive) {
    endGame(false);
    return;
  }

  const aliveEnemies = AIEnemies.filter(ai => ai.alive).length;
  if (aliveEnemies === 0) {
    endGame(true);
  }
}

function endGame(victory) {
  GameState.playing = false;
  GameState.ended = true;

  const endTime = Date.now();
  const playTime = (endTime - GameState.startTime) / 1000;
  const minutes = Math.floor(playTime / 60);
  const seconds = Math.floor(playTime % 60);

  const aliveEnemies = AIEnemies.filter(ai => ai.alive).length;
  const position = aliveEnemies + 1;

  // Calculate rating change
  let ratingChange = 0;
  if (victory) {
    ratingChange += 500;
    GameState.stats.wins++;
  }
  ratingChange += Player.kills * 10;
  ratingChange += Math.floor(playTime);
  if (Player.kills > 5) ratingChange += 20;

  GameState.playerRating += ratingChange;
  GameState.stats.games++;
  GameState.stats.kills += Player.kills;
  GameState.stats.damage += Player.totalDamage;
  GameState.stats.time += playTime / 60;

  // Level up check
  if (GameState.playerRating >= GameState.playerLevel * 100) {
    GameState.playerLevel++;
  }

  saveStats();

  // Show end screen
  document.getElementById('endScreen').classList.add('active');
  document.getElementById('endTitle').textContent = victory ? 'ПОБЕДА!' : 'ВЫБЫЛ';
  document.getElementById('endTitle').className = 'end-title ' + (victory ? 'victory' : 'defeat');
  document.getElementById('endKills').textContent = Player.kills;
  document.getElementById('endDamage').textContent = Math.floor(Player.totalDamage);
  document.getElementById('endTime').textContent = minutes + ':' + (seconds < 10 ? '0' : '') + seconds;
  document.getElementById('endDistance').textContent = Math.floor(Player.distanceTraveled) + 'м';
  document.getElementById('endItems').textContent = Player.itemsCollected;
  document.getElementById('endPosition').textContent = position + '/100';
  document.getElementById('ratingChange').textContent = (ratingChange >= 0 ? '+' : '') + ratingChange;
  document.getElementById('ratingChange').style.color = ratingChange >= 0 ? '#0f0' : '#f00';
}

// ==================== INIT ====================
loadStats();
init();
gameLoop();
</script>
